INSERT INTO public.stormevents_east VALUES (744738, 201805, 13, 1830, 201805, 13, 1832, 124104, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '13-MAY-18 18:30:00', 'EST-5', '13-MAY-18 18:32:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 2, 'SSE', 'JOHNSON', 2, 'SSE', 'JOHNSON', 39.5256, -83.3138, 39.5256, -83.3138, 'Scattered thunderstorms developed during the late afternoon and evening hours along a stationary boundary situated across southern Ohio.', 'A small tree was downed near the intersection of Clemens and White Roads.');
INSERT INTO public.stormevents_east VALUES (744740, 201805, 13, 2013, 201805, 13, 2015, 124104, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '13-MAY-18 20:13:00', 'EST-5', '13-MAY-18 20:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 2, 'WSW', 'MELVIN', 2, 'WSW', 'MELVIN', 39.4592, -83.7595, 39.4592, -83.7595, 'Scattered thunderstorms developed during the late afternoon and evening hours along a stationary boundary situated across southern Ohio.', 'A tree was downed, blocking the right hand lane of U.S. 22 near Stone Road.');
INSERT INTO public.stormevents_east VALUES (745280, 201805, 16, 0, 201805, 16, 100, 124187, 'KENTUCKY', 21, 2018, 'May', 'Flash Flood', 'ILN', '16-MAY-18 00:00:00', 'EST-5', '16-MAY-18 01:00:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'HEAD OF GRASSY', 2, 'NNE', 'HEAD OF GRASSY', 38.4, -83.26, 38.415, -83.2598, 'Slow moving thunderstorms produced localized flash flooding during the early morning hours and then again during the afternoon hours.', 'Parts of Dummit Branch Road and Upper Twin Branch Road were washed out near Head of Grassy.');
INSERT INTO public.stormevents_east VALUES (747008, 201805, 26, 1404, 201805, 26, 1406, 124505, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '26-MAY-18 14:04:00', 'EST-5', '26-MAY-18 14:06:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 0, 'N', 'SCIOTOVILLE', 0, 'N', 'SCIOTOVILLE', 38.7763, -82.8811, 38.7763, -82.8811, 'Isolated thunderstorms developed during the afternoon hours in an unstable air mass that was in place across the region.', 'A tree was downed across Elliot Hill Road.');
INSERT INTO public.stormevents_east VALUES (747012, 201805, 27, 100, 201805, 27, 200, 124506, 'OHIO', 39, 2018, 'May', 'Flash Flood', 'ILN', '27-MAY-18 01:00:00', 'EST-5', '27-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ROCKBRIDGE', 1, 'ENE', 'ROCKBRIDGE', 39.5759, -82.521, 39.5835, -82.5176, 'Slow moving thunderstorms produced locally heavy rainfall during the early morning hours.', 'Two high water rescues occurred in Rockbridge due to rapidly rising water.');
INSERT INTO public.stormevents_east VALUES (747014, 201805, 27, 130, 201805, 27, 230, 124506, 'OHIO', 39, 2018, 'May', 'Flash Flood', 'ILN', '27-MAY-18 01:30:00', 'EST-5', '27-MAY-18 02:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ROCKBRIDGE', 1, 'ESE', 'ROCKBRIDGE', 39.5774, -82.5213, 39.5748, -82.5198, 'Slow moving thunderstorms produced locally heavy rainfall during the early morning hours.', 'U.S. 33 was closed near Rockbridge due to high water running across the roadway. Also, a mini mart was flooded.');
INSERT INTO public.stormevents_east VALUES (751922, 201805, 31, 1551, 201805, 31, 1553, 124669, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'ILN', '31-MAY-18 15:51:00', 'EST-5', '31-MAY-18 15:53:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'TOLLESBORO', 1, 'NW', 'TOLLESBORO', 38.56, -83.58, 38.56, -83.58, 'A complex of thunderstorms pushed east across the Ohio Valley during the afternoon hours. Several of the thunderstorms produced damaging wind gusts.', 'Numerous trees and power lines were downed.');
INSERT INTO public.stormevents_east VALUES (747017, 201805, 27, 400, 201805, 27, 500, 124506, 'OHIO', 39, 2018, 'May', 'Flood', 'ILN', '27-MAY-18 04:00:00', 'EST-5', '27-MAY-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'ROCKBRIDGE', 1, 'ENE', 'ROCKBRIDGE', 39.5842, -82.5215, 39.5824, -82.5182, 'Slow moving thunderstorms produced locally heavy rainfall during the early morning hours.', 'A few roads remained closed in the Rockbridge area due to lingering high water.');
INSERT INTO public.stormevents_east VALUES (747015, 201805, 27, 230, 201805, 27, 330, 124506, 'OHIO', 39, 2018, 'May', 'Flood', 'ILN', '27-MAY-18 02:30:00', 'EST-5', '27-MAY-18 03:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'REVENGE', 2, 'W', 'REVENGE', 39.6, -82.69, 39.5968, -82.6798, 'Slow moving thunderstorms produced locally heavy rainfall during the early morning hours.', 'High water was reported in parts of southern Fairfield County.');
INSERT INTO public.stormevents_east VALUES (748748, 201805, 15, 1713, 201805, 15, 1713, 124790, 'RHODE ISLAND', 44, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 17:13:00', 'EST-5', '15-MAY-18 17:13:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 40, 'EG', NULL, NULL, 2, 'SSW', 'CANONCHET', 2, 'SSW', 'CANONCHET', 41.4761, -71.777, 41.4761, -71.777, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Rhode Island was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms moving east from Connecticut produced damaging wind gusts in Western Rhode Island.', 'At 5:13 PM EST, a large tree was blocking North Road in Hopkinton.');
INSERT INTO public.stormevents_east VALUES (748744, 201805, 15, 1710, 201805, 15, 1710, 124790, 'RHODE ISLAND', 44, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 17:10:00', 'EST-5', '15-MAY-18 17:10:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 40, 'EG', NULL, NULL, 1, 'ENE', 'ARKWRIGHT', 1, 'ENE', 'ARKWRIGHT', 41.7233, -71.5539, 41.7233, -71.5539, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Rhode Island was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms moving east from Connecticut produced damaging wind gusts in Western Rhode Island.', 'At 5:10 PM EST, a tree was reported down on a house on Pin Oak Court in Coventry.');
INSERT INTO public.stormevents_east VALUES (748767, 201805, 15, 1545, 201805, 15, 1545, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', 48, 'EG', NULL, NULL, 2, 'ENE', 'NORTH CANTON', 2, 'NW', 'SIMSBURY', 41.9118, -72.844, 41.9056, -72.8265, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 3:45 PM EST numerous trees were reported down on Old Farms Road near Tollgale Lane, Holcomb Street at Cardinal Road, and Barndoor Hills Road at Firetown Road.  A single tree was down across Richard Road.');
INSERT INTO public.stormevents_east VALUES (748774, 201805, 15, 1545, 201805, 15, 1545, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'W', 'UNION', 1, 'W', 'UNION', 41.9802, -72.177, 41.9802, -72.177, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 3:45 PM EST, a tree and wires were down on Buckley Highway in Union.');
INSERT INTO public.stormevents_east VALUES (748752, 201805, 15, 1540, 201805, 15, 1540, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 15:40:00', 'EST-5', '15-MAY-18 15:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 48, 'EG', NULL, NULL, 2, 'N', 'SOMERS', 2, 'N', 'SOMERS', 42.015, -72.448, 42.015, -72.448, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 3:40 PM EST trees and wires were reported down on Springfield Road at Turnpike Road in Somers.');
