INSERT INTO public.stormevents_east VALUES (748785, 201805, 15, 1623, 201805, 15, 1623, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 16:23:00', 'EST-5', '15-MAY-18 16:23:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 46, 'EG', NULL, NULL, 1, 'NNE', 'MARION', 1, 'NNE', 'MARION', 41.5827, -72.909, 41.5827, -72.909, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 4:23 PM EST a tree was down on a house on Marion Avenue in Southington. A tree was down on Wilbur Street and Milldale Avenue in Southington.  A large tree was down on South End Road in the Plantsville section of Southington.');
INSERT INTO public.stormevents_east VALUES (748789, 201805, 15, 1630, 201805, 15, 1630, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 16:30:00', 'EST-5', '15-MAY-18 16:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 40, 'EG', NULL, NULL, 1, 'SW', 'AMSTON', 1, 'SW', 'AMSTON', 41.6064, -72.3434, 41.6064, -72.3434, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 4:30 PM EST, a tree and wires were reported down on Old Colchester Road in Bolton near the Colchester town line.');
