INSERT INTO public.stormevents_east VALUES (755942, 201805, 28, 1300, 201805, 28, 1500, 126112, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'ILM', '28-MAY-18 13:00:00', 'EST-5', '28-MAY-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'WINNABOW', 2, 'W', 'WINNABOW', 34.15, -78.14, 34.1502, -78.1345, 'A trough extending from Tropical Storm Alberto produced heavy rain and flash flooding.', 'There was flowing water on Green Hill Road.');
INSERT INTO public.stormevents_east VALUES (755940, 201805, 28, 1100, 201805, 28, 1300, 126112, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'ILM', '28-MAY-18 11:00:00', 'EST-5', '28-MAY-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'IRONHILL', 0, 'ESE', 'IRONHILL', 34.13, -78.77, 34.1288, -78.7742, 'A trough extending from Tropical Storm Alberto produced heavy rain and flash flooding.', 'Water has submerged the entire intersection of Will Inmann and MM Ray Roads.');
INSERT INTO public.stormevents_east VALUES (755941, 201805, 28, 1100, 201805, 28, 1300, 126112, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'ILM', '28-MAY-18 11:00:00', 'EST-5', '28-MAY-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'WARD STATION', 2, 'E', 'WARD STATION', 34.2724, -78.7933, 34.2701, -78.7933, 'A trough extending from Tropical Storm Alberto produced heavy rain and flash flooding.', 'The intersection of Peacock Road and Hinson Road were submerged due to excessive rain.');
