INSERT INTO public.stormevents_east VALUES (726655, 201801, 4, 1213, 201801, 4, 1213, 121387, 'ATLANTIC NORTH', 88, 2018, 'January', 'Marine High Wind', 'PHI', '04-JAN-18 12:13:00', 'EST-5', '04-JAN-18 12:13:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 50, 'MG', NULL, NULL, 0, 'N', 'CAPE MAY PT', 0, 'N', 'CAPE MAY PT', 38.93, -74.97, 38.93, -74.97, 'Strong winds occurred offshore and in the Delaware Bay waters. Also, due to extended cold snap portions of Delaware Bay were frozen over impacting commerce and other services.', 'Weatherflow site.');
