INSERT INTO public.stormevents_east VALUES (750297, 201805, 16, 1650, 201805, 16, 1650, 125093, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '16-MAY-18 16:50:00', 'EST-5', '16-MAY-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'PALM COAST PARKWAY', 1, 'S', 'PALM COAST PARKWAY', 29.55, -81.21, 29.55, -81.21, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'A billboard sign was blown down near Interstate 95 and Old Kings Road. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (750298, 201805, 16, 1602, 201805, 16, 1602, 125094, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'JAX', '16-MAY-18 16:02:00', 'EST-5', '16-MAY-18 16:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 7, 'SW', 'MAYPORT NAS', 7, 'SW', 'MAYPORT NAS', 30.34, -81.51, 30.34, -81.51, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'The Craig Airfield ASOS measured a wind gust to 44 mph.');
INSERT INTO public.stormevents_east VALUES (750296, 201805, 16, 1630, 201805, 16, 1630, 125093, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '16-MAY-18 16:30:00', 'EST-5', '16-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'CODYS CORNER', 0, 'N', 'CODYS CORNER', 29.34, -81.31, 29.34, -81.31, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'Downburst winds blew down multiple trees and tore a section of a metal roof off with parts of the rafters attached from a pole barn in Codys Corner, near State Road 11 and County Road 304.');
INSERT INTO public.stormevents_east VALUES (750293, 201805, 15, 1320, 201805, 15, 1320, 125092, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '15-MAY-18 13:20:00', 'EST-5', '15-MAY-18 13:20:00', 0, 0, 0, 0, '0.10K', '0.00K', 'Public', 45, 'EG', NULL, NULL, 2, 'NW', 'ARREDONDA', 2, 'NW', 'ARREDONDA', 29.62, -82.45, 29.62, -82.45, 'A persistent upper level low over the NE Gulf of Mexico increased diurnal instability with enhanced a few storms that developed along the sea breezes as they drifted inland.', 'A tree was blown down on the 2200 Block of SW 41st Avenue. The cost of the damage was unknown but it was estimated for the event to be included in StormData.');
INSERT INTO public.stormevents_east VALUES (750294, 201805, 16, 1545, 201805, 16, 1545, 125093, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '16-MAY-18 15:45:00', 'EST-5', '16-MAY-18 15:45:00', 0, 0, 0, 0, '0.10K', '0.00K', 'Broadcast Media', 45, 'EG', NULL, NULL, 2, 'SSW', 'SAMPSON', 2, 'SSW', 'SAMPSON', 30, -81.41, 30, -81.41, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'A tree was blown down across International Golf Parkway about 1 mile west of U.S. Highway 1. The time of damage was based on radar. The cost of damage was unknown but it was estimated for the inclusion of the event in StormData.');
INSERT INTO public.stormevents_east VALUES (750295, 201805, 16, 1625, 201805, 16, 1625, 125093, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '16-MAY-18 16:25:00', 'EST-5', '16-MAY-18 16:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'WSW', 'RELAY WILDLIFE AREA', 2, 'WSW', 'RELAY WILDLIFE AREA', 29.31, -81.27, 29.31, -81.27, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'Multiple trees limbs were blown down with wind estimated between 50-60 mph.');
