INSERT INTO public.stormevents_east VALUES (750302, 201805, 16, 1617, 201805, 16, 1617, 125094, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'JAX', '16-MAY-18 16:17:00', 'EST-5', '16-MAY-18 16:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 39, 'MG', NULL, NULL, 0, 'N', 'MAYPORT NAS', 0, 'N', 'MAYPORT NAS', 30.4, -81.42, 30.4, -81.42, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', NULL);
INSERT INTO public.stormevents_east VALUES (750304, 201805, 16, 1700, 201805, 16, 1700, 125094, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'JAX', '16-MAY-18 17:00:00', 'EST-5', '16-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'JEKYLL ISLAND', 0, 'N', 'JEKYLL ISLAND', 31.07, -81.43, 31.07, -81.43, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'A WeatherFlow site on Jekyll Island measured the gust.');
INSERT INTO public.stormevents_east VALUES (754835, 201805, 31, 1740, 201805, 31, 1835, 125899, 'FLORIDA', 12, 2018, 'May', 'Heavy Rain', 'JAX', '31-MAY-18 17:40:00', 'EST-5', '31-MAY-18 18:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'N', 'WESCONNETT', 1, 'N', 'WESCONNETT', 30.26, -81.75, 30.26, -81.75, 'Tropical moisture combined with sea breeze forcing and diurnal heating produced localized heavy rainfall.', 'An observer measured 2.31 inches of rainfall in 55 minutes.');
INSERT INTO public.stormevents_east VALUES (754837, 201805, 30, 1215, 201805, 30, 1300, 125900, 'FLORIDA', 12, 2018, 'May', 'Heavy Rain', 'JAX', '30-MAY-18 12:15:00', 'EST-5', '30-MAY-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'E', 'PALM HARBOR', 1, 'E', 'PALM HARBOR', 29.58, -81.21, 29.58, -81.21, 'Tropical moisture combined with sea breeze forcing and diurnal heating produced localized heavy rainfall.', 'An observer measured 1.25 inches within 45 minutes.');
INSERT INTO public.stormevents_east VALUES (754853, 201805, 15, 1432, 201805, 15, 1432, 125092, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '15-MAY-18 14:32:00', 'EST-5', '15-MAY-18 14:32:00', 0, 0, 0, 0, '0.20K', '0.00K', 'State Official', 39, 'EG', NULL, NULL, 1, 'NNW', 'WEST END', 1, 'NNW', 'WEST END', 29.1909, -82.1554, 29.1909, -82.1554, 'A persistent upper level low over the NE Gulf of Mexico increased diurnal instability with enhanced a few storms that developed along the sea breezes as they drifted inland.', 'A tree branch fell on a home in Ocala. Extent of damage unknown, but estimated cost of damage so event could be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (750307, 201805, 17, 1240, 201805, 17, 1240, 125097, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'JAX', '17-MAY-18 12:40:00', 'EST-5', '17-MAY-18 12:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mariner', 35, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'An upper level short wave trough moving over the area enhanced afternoon sea breeze storms.', 'The gust was measured by the WeatherFlow site at Huguenot Park.');
INSERT INTO public.stormevents_east VALUES (750306, 201805, 16, 1700, 201805, 16, 1700, 125094, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'JAX', '16-MAY-18 17:00:00', 'EST-5', '16-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 43, 'EG', NULL, NULL, 9, 'SSW', 'CRESCENT BEACH', 9, 'SSW', 'CRESCENT BEACH', 29.65, -81.29, 29.65, -81.29, 'A persistent upper level low across the NE Gulf of Mexico began to lift NE with a lobe of strong mid level energy overspreading the area from west to east. This energy enhanced thunderstorms that developed along the west coast sea breeze and east coast sea breeze mergers in the afternoon.', 'A spotter reported a wind gust to 50 mph along U.S. Highway 1.');
INSERT INTO public.stormevents_east VALUES (754829, 201805, 21, 400, 201805, 21, 548, 125890, 'FLORIDA', 12, 2018, 'May', 'Heavy Rain', 'JAX', '21-MAY-18 04:00:00', 'EST-5', '21-MAY-18 05:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'NE', 'DALLAS', 1, 'NE', 'DALLAS', 28.98, -82.02, 28.98, -82.02, 'A boundary lifting northward over Florida under a mid level trough lingering across the eastern Gulf of Mexico resulted in waves of heavy rainfall, which produced daily rainfall amounts over 4 inches in southern Marion county.', 'An observer near Lake Weir measured 3.75 inches of rainfall between 5 am and 6:48 am. The 24-hr rainfall was 4.29 inches.');
INSERT INTO public.stormevents_east VALUES (754830, 201805, 22, 1245, 201805, 22, 1445, 125891, 'FLORIDA', 12, 2018, 'May', 'Heavy Rain', 'JAX', '22-MAY-18 12:45:00', 'EST-5', '22-MAY-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'S', 'LORETTO', 1, 'S', 'LORETTO', 30.15, -81.6, 30.15, -81.6, 'Low pressure tracking north over AL and northern GA streamed a plume of tropical moisture over the local area.  Waves of showers and thunderstorms produced locally heavy rainfall.', 'Over a two hour period, 4.5 inches was measured in Mandarin. Ditches were overflowed with water, some spreading onto roads.');
INSERT INTO public.stormevents_east VALUES (754833, 201805, 28, 1628, 201805, 28, 1628, 125894, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'JAX', '28-MAY-18 16:28:00', 'EST-5', '28-MAY-18 16:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 61, 'EG', NULL, NULL, 1, 'N', 'KEYSTONE HGTS', 1, 'N', 'KEYSTONE HGTS', 29.8, -82.03, 29.8, -82.03, 'A rain band formed across the area on the west side of TS Alberto. This band interacted with diurnal instability and upper level lift which combined to produce isolated severe storms as the band lifting NNE across the local area.', 'A former NWS employee estimated wind gusts of 70 mph near Lake Brooklyn.');
INSERT INTO public.stormevents_east VALUES (754832, 201805, 24, 1715, 201805, 24, 1715, 125892, 'GEORGIA', 13, 2018, 'May', 'Tornado', 'JAX', '24-MAY-18 17:15:00', 'EST-5', '24-MAY-18 17:15:00', 0, 0, 0, 0, NULL, '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 3, 'NNW', 'SCREVAN', 3, 'NNW', 'SCREVAN', 31.52, -82.05, 31.52, -82.05, 'East coast sea breeze storms moved inland an converged with high instability and inflow which cause a brief, weak EF0 landspout to form NW of Screven.', 'EM did a storm survey and confirmed EF0 tornado damage near Burch Farms and Dixie Road in Screven. Several videos of tornado via Wayne County EM Facebook page. A couple of homes had damage, no injuries reported.  The path length and width were unknown but estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (756206, 201805, 4, 1415, 201805, 4, 1415, 126143, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 14:15:00', 'EST-5', '04-MAY-18 14:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SSW', 'WESLEYVILLE', 2, 'SSW', 'WESLEYVILLE', 42.1075, -80.008, 42.1075, -80.008, 'A cold front marched across northwestern Pennsylvania during the afternoon of May 4th. A line of thunderstorms developed in advance of the front and caused some damage. A severe thunderstorm watch box was in effect during the time of the storms.', 'Thunderstorm winds downed a tree on the railroad tracks near the intersection of Norcross and Martin Roads.');
INSERT INTO public.stormevents_east VALUES (756682, 201805, 9, 1717, 201805, 9, 1717, 126222, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '09-MAY-18 17:17:00', 'EST-5', '09-MAY-18 17:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 0.88, NULL, NULL, NULL, 0, 'N', 'MAUMEE', 0, 'N', 'MAUMEE', 41.57, -83.65, 41.57, -83.65, 'A warm front moved north across the area causing a few thunderstorms to develop.  One of the storms produced hail in Lucas County.', 'Nickel sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (757183, 201805, 26, 1830, 201805, 26, 1830, 125545, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '26-MAY-18 18:30:00', 'EST-5', '26-MAY-18 18:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SSE', 'REEDSBURG', 1, 'SSE', 'REEDSBURG', 40.7929, -82.0941, 40.7929, -82.0941, 'Diurnal convection was being supported by the passage of an upper level shortwave on the evening of May 26th.  The environment was favorable for heavy rain with high moisture content in the airmass. Flooding occurred over portions of Holmes County Ohio as storms merged and stalled over the central part of the county while producing torrential rainfall rates.', 'Thunderstorm winds downed a tree.');
INSERT INTO public.stormevents_east VALUES (757184, 201805, 26, 1830, 201805, 26, 1830, 125545, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '26-MAY-18 18:30:00', 'EST-5', '26-MAY-18 18:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NW', 'SHREVE', 2, 'NW', 'SHREVE', 40.6942, -82.0434, 40.6942, -82.0434, 'Diurnal convection was being supported by the passage of an upper level shortwave on the evening of May 26th.  The environment was favorable for heavy rain with high moisture content in the airmass. Flooding occurred over portions of Holmes County Ohio as storms merged and stalled over the central part of the county while producing torrential rainfall rates.', 'Thunderstorm winds downed a tree.');
INSERT INTO public.stormevents_east VALUES (757186, 201805, 30, 1633, 201805, 30, 1633, 126315, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '30-MAY-18 16:33:00', 'EST-5', '30-MAY-18 16:33:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'UPPER SANDUSKY', 0, 'N', 'UPPER SANDUSKY', 40.83, -83.28, 40.83, -83.28, 'A warm front lift north across Ohio during the afternoon May 30th causing a broken line of showers and thunderstorms to develop.  A couple segments of the line became severe.', 'Thunderstorm winds downed a couple trees in the Upper Sandusky area.');
INSERT INTO public.stormevents_east VALUES (757187, 201805, 30, 1953, 201805, 30, 2005, 126315, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '30-MAY-18 19:53:00', 'EST-5', '30-MAY-18 20:05:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'S', 'MILLERSBURG', 1, 'WNW', 'CHARM', 40.5453, -81.9209, 40.5237, -81.8178, 'A warm front lift north across Ohio during the afternoon May 30th causing a broken line of showers and thunderstorms to develop.  A couple segments of the line became severe.', 'Thunderstorm winds downed several trees in the Millersburg area.');
INSERT INTO public.stormevents_east VALUES (757188, 201805, 30, 1744, 201805, 30, 1744, 126315, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '30-MAY-18 17:44:00', 'EST-5', '30-MAY-18 17:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'PT PLACE', 0, 'N', 'PT PLACE', 41.72, -83.48, 41.72, -83.48, 'A warm front lift north across Ohio during the afternoon May 30th causing a broken line of showers and thunderstorms to develop.  A couple segments of the line became severe.', 'Thunderstorm winds downed a tree and large tree limb.');
INSERT INTO public.stormevents_east VALUES (752926, 201805, 26, 1700, 201805, 26, 2000, 125545, 'OHIO', 39, 2018, 'May', 'Flash Flood', 'CLE', '26-MAY-18 17:00:00', 'EST-5', '26-MAY-18 20:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BERLIN', 0, 'NNE', 'FRYBURG', 40.57, -81.8, 40.6234, -81.8271, 'Diurnal convection was being supported by the passage of an upper level shortwave on the evening of May 26th.  The environment was favorable for heavy rain with high moisture content in the airmass. Flooding occurred over portions of Holmes County Ohio as storms merged and stalled over the central part of the county while producing torrential rainfall rates.', 'Heavy rainfall moved into Holmes County between 700 and 800 pm on the evening of the 26th. A line of thunderstorms over Wayne County moved south into Holmes County where there was a cell merger. This cause a brief period of storm back building and training over north central Holmes County. During this period the rainfall rates were estimated around 5 inches per hour. The storm motions were from north to south, paralleling the extent of the Killbuck Creek river basin starting in the headwaters. This confined the majority of the runoff to that single basin. The result was flash flooding in several areas across Holmes County. One home in Monroe and Prairie Township was flooded on County Road 320 from Paint Creek. Prairie Township Fire Department rescued people from a car in high water. One unofficial rainfall report of 3.00��� came from Berlin in eastern Holmes County. An official reading in Holmesville of 2.72��� was measured between 7 pm and 8 pm.');
INSERT INTO public.stormevents_east VALUES (757189, 201805, 30, 1746, 201805, 30, 1746, 126315, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '30-MAY-18 17:46:00', 'EST-5', '30-MAY-18 17:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 0, 'N', 'OREGON', 0, 'N', 'OREGON', 41.65, -83.43, 41.65, -83.43, 'A warm front lift north across Ohio during the afternoon May 30th causing a broken line of showers and thunderstorms to develop.  A couple segments of the line became severe.', 'Thunderstorm wind gusts were estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (730648, 201801, 12, 2257, 201801, 12, 2257, 122048, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'MHX', '12-JAN-18 22:57:00', 'EST-5', '12-JAN-18 22:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 1, 'NW', 'OCRACOKE FERRY TERMINAL', 1, 'NW', 'OCRACOKE FERRY TERMINAL', 35.1192, -76.0006, 35.1192, -76.0006, 'A strong cold front approached Eastern NC late on January 12th, 2018. A shortwave trough moved through the area prior to the cold front, with high-shear and limited instability, leading to several marine thunderstorm wind gusts across the coastal waters.', 'WeatherFlow sensor near the Ocracoke Ferry Terminal reported a 52 knot marine thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (727312, 201801, 12, 1315, 201801, 12, 1315, 121503, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'MLB', '12-JAN-18 13:15:00', 'EST-5', '12-JAN-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 2, 'SSE', 'PLAYALINDA BEACH', 2, 'SSE', 'PLAYALINDA BEACH', 28.53, -80.77, 28.53, -80.77, 'Scattered showers and a few thunderstorms developed within a moist and unstable environment well ahead of a cold front. A few of the showers produced strong wind gusts over the Indian River and adjacent Kennedy Space Center as they moved rapidly northeast at 40 knots.', 'USAF wind tower 1007 over the Indian River, along the NASA Causeway, measured a peak wind of 34 knots from the southwest as a heavy shower moved rapidly off the mainland.');
INSERT INTO public.stormevents_east VALUES (750186, 201806, 9, 1550, 201806, 9, 1555, 125077, 'FLORIDA', 12, 2018, 'June', 'Hail', 'TBW', '09-JUN-18 15:50:00', 'EST-5', '09-JUN-18 15:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 0.88, NULL, NULL, NULL, 0, 'N', 'ALVA', 0, 'N', 'ALVA', 26.72, -81.61, 26.72, -81.61, 'Deep moisture and strong surface heating led to scattered to numerous thunderstorms developing across the Florida Peninsula along sea breeze and outflow boundaries. One of these storms produced Nickel sized hail in southwest Florida.', NULL);
INSERT INTO public.stormevents_east VALUES (735694, 201802, 10, 2038, 201802, 10, 2330, 122805, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'MRX', '10-FEB-18 20:38:00', 'EST-5', '10-FEB-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 12, 'W', 'GATE CITY', 2, 'S', 'GATE CITY', 36.63, -82.7964, 36.6011, -82.58, 'At 500 MB, a strong western Atlantic high pressure ridge and a deep low pressure trough over the High Plains were denoted at the surface by a slow-moving cold front over the Mississippi and Ohio River valleys. This resulted in unseasonably warm and humid conditions across east Tennessee and southwest Virginia, and widespread heavy rains.', 'Several road closures around the county.');
INSERT INTO public.stormevents_east VALUES (735703, 201802, 10, 2200, 201802, 10, 2300, 122805, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'MRX', '10-FEB-18 22:00:00', 'EST-5', '10-FEB-18 23:00:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'EAST STONE GAP', 5, 'NE', 'EAST STONE GAP', 36.87, -82.7481, 36.9212, -82.666, 'At 500 MB, a strong western Atlantic high pressure ridge and a deep low pressure trough over the High Plains were denoted at the surface by a slow-moving cold front over the Mississippi and Ohio River valleys. This resulted in unseasonably warm and humid conditions across east Tennessee and southwest Virginia, and widespread heavy rains.', 'Water rescue in Powell Valley. Subject attempted to drive through high water and was pushed into the river. No injuries.');
INSERT INTO public.stormevents_east VALUES (735735, 201802, 11, 935, 201802, 11, 1100, 122806, 'TENNESSEE', 47, 2018, 'February', 'Flood', 'MRX', '11-FEB-18 09:35:00', 'EST-5', '11-FEB-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 5, 'NE', 'MAYNARDVILLE', 5, 'NW', 'MAYNARDVILLE', 36.3012, -83.7365, 36.3012, -83.8635, 'At 500 MB, a strong western Atlantic high pressure ridge and a deep low pressure trough over the High Plains were denoted at the surface by a slow-moving cold front over the Mississippi and Ohio River valleys. This resulted in unseasonably warm and humid conditions across east Tennessee and southwest Virginia, and widespread heavy rains.', 'Several road closures across the county. Some roads covered by debris flows.');
INSERT INTO public.stormevents_east VALUES (738669, 201804, 3, 2341, 201804, 3, 2341, 123204, 'KENTUCKY', 21, 2018, 'April', 'Thunderstorm Wind', 'JKL', '03-APR-18 23:41:00', 'EST-5', '03-APR-18 23:41:00', 0, 0, 0, 0, NULL, NULL, 'Utility Company', 51, 'EG', NULL, NULL, 1, 'WNW', 'WEST PRESTONSBURG', 1, 'WNW', 'WEST PRESTONSBURG', 37.68, -82.82, 37.68, -82.82, 'A strong early spring cold front led to a line of showers and thunderstorms developing across the Midwestern U.S. this afternoon and later pushing through eastern Kentucky during the late evening and overnight hours. Initially, a few embedded supercell thunderstorms produced large hail due to their rotation and stronger updrafts. Damaging wind gusts ended up being the primary threat across eastern Kentucky as these features became organized into line segments later into the night.||Numerous reports of downed trees and power lines were received across southeastern Kentucky where the greatest amount of instability was present. Homes in Leslie, Letcher, and Pike Counties suffered extensive damage from trees falling onto them, including one at Willow Tree Hollow near Marrowbone and Regina southeast of Pikeville that led to an injury to a person inside. More scattered wind damage was also reported up toward and north of Mountain Parkway as individual storm cells embedded within the larger line intensified.', 'A power pole was broken and knocked over by thunderstorm wind gusts northwest of Prestonsburg.');
INSERT INTO public.stormevents_east VALUES (737017, 201802, 11, 1132, 201802, 12, 1321, 122936, 'MARYLAND', 24, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 11:32:00', 'EST-5', '12-FEB-18 13:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'UPPER MARLBORO', 0, 'S', 'UPPER MARLBORO', 38.8145, -76.7514, 38.8134, -76.7509, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding in southern Maryland. Stream flooding persisted into February 12th.', 'The USGS stream gauge on the Western Branch Patuxent River at Upper Marlboro exceeded flood stage between 1132 AM on the 11th and 121 PM on the 12th.  While the gauge was above flood stage, Water Street in Upper Marlboro was flooded. For most of that timeframe it was also closed.');
INSERT INTO public.stormevents_east VALUES (737015, 201802, 11, 1456, 201802, 12, 1030, 122936, 'MARYLAND', 24, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 14:56:00', 'EST-5', '12-FEB-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'INDIAN HD MRYLND ARP', 1, 'SSW', 'INDIAN HD MRYLND ARP', 38.5975, -77.058, 38.5824, -77.0788, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding in southern Maryland. Stream flooding persisted into February 12th.', 'The USGS stream gauge on Mattawoman Creek near Pomonkey exceeded flood stage between 256 PM on the 11th and 1030 AM on the 12th. Several roads, including Maryland Route 227, were flooded and closed while the gauge was over flood stage.');
INSERT INTO public.stormevents_east VALUES (740052, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWSS', NULL, NULL, NULL, NULL, 2, 'E', 'ROSLYN HILLS', 2, 'E', 'ROSLYN HILLS', 37.58, -77.5335, 37.58, -77.5335, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 1.0 inch and 3.5 inches across the county. Roslyn Hills (2 E) reported 3.28 inches of rain. Tuckahoe (2 NW) reported 3.08 inches of rain. Short Pump (2 E) reported 1.78 inches of rain. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (741460, 201802, 10, 700, 201802, 11, 700, 123621, 'NORTH CAROLINA', 37, 2018, 'February', 'Heavy Rain', 'RNK', '10-FEB-18 07:00:00', 'EST-5', '11-FEB-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'W', 'TOAST', 1, 'W', 'TOAST', 36.499, -80.651, 36.499, -80.651, 'A broad upper level trough with a slow-moving frontal boundary extending from Texas to upstate New York brought an extended period of mainly light to moderate rainfall that began on the afternoon of the 10th and persisted well into the evening of the 11th. Storm total rainfall amounts ranged from 1.5 to 3 inches across parts of northwest North Carolina.', 'The COOP observer at Mt. Airy had a 24-hour total of 2.67 inches for the 24-hour period ending at 7 AM on the 11th. This was the 2nd highest daily rainfall total during the month of February at this location since records began in 1893.');
INSERT INTO public.stormevents_east VALUES (737006, 201802, 11, 621, 201802, 11, 1101, 122935, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 06:21:00', 'EST-5', '11-FEB-18 11:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'WOODBRIDGE', 0, 'WNW', 'WOODBRIDGE', 38.652, -77.2564, 38.6524, -77.2554, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding mainly in Central Virginia and the Virginia Piedmont region.', 'A portion of US Route 1 and Marys Way near Woodbridge was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (737009, 201802, 11, 630, 201802, 11, 1250, 122935, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 06:30:00', 'EST-5', '11-FEB-18 12:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'GLADSTONE', 0, 'SSE', 'GLADSTONE', 37.5514, -78.8773, 37.5475, -78.8687, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding mainly in Central Virginia and the Virginia Piedmont region.', 'Portions of Union School Road and Gladstone Road were reported flooded and impassible.');
INSERT INTO public.stormevents_east VALUES (737010, 201802, 11, 805, 201802, 11, 1000, 122935, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 08:05:00', 'EST-5', '11-FEB-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'SCOTTSVILLE', 1, 'WSW', 'SCOTTSVILLE', 37.7922, -78.5215, 37.7915, -78.5201, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding mainly in Central Virginia and the Virginia Piedmont region.', 'James River Road bridge flooded and closed.');
INSERT INTO public.stormevents_east VALUES (737011, 201802, 11, 956, 201802, 11, 1200, 122935, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 09:56:00', 'EST-5', '11-FEB-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'FALMOUTH', 1, 'ENE', 'FALMOUTH', 38.33, -77.45, 38.3288, -77.4504, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding mainly in Central Virginia and the Virginia Piedmont region.', 'Heavy rain caused flooding of Harrell Road near Falmouth. The road was closed.');
INSERT INTO public.stormevents_east VALUES (737013, 201802, 11, 1027, 201802, 12, 800, 122936, 'MARYLAND', 24, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 10:27:00', 'EST-5', '12-FEB-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'RUTLAND', 1, 'WNW', 'LUSBY XRDS', 38.9856, -76.6221, 38.9873, -76.6206, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding in southern Maryland. Stream flooding persisted into February 12th.', 'Rutland Road was flooded and closed near Route 450.');
INSERT INTO public.stormevents_east VALUES (737005, 201802, 11, 537, 201802, 11, 947, 122935, 'VIRGINIA', 51, 2018, 'February', 'Flood', 'LWX', '11-FEB-18 05:37:00', 'EST-5', '11-FEB-18 09:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'CAMPBELL', 0, 'WNW', 'CAMPBELL', 38.0339, -78.3065, 38.0323, -78.3051, 'Heavy precipitation developed along a stalled front during the overnight hours of February 10th into February 11th, causing flooding mainly in Central Virginia and the Virginia Piedmont region.', 'Heavy rain caused Route 600 to flood and be closed near Mechunk Creek.');
INSERT INTO public.stormevents_east VALUES (740572, 201802, 11, 1353, 201802, 11, 1353, 123489, 'ATLANTIC NORTH', 88, 2018, 'February', 'Marine Thunderstorm Wind', 'LWX', '11-FEB-18 13:53:00', 'EST-5', '11-FEB-18 13:53:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 40, 'MG', NULL, NULL, 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 38.29, -76.41, 38.29, -76.41, 'Gusty showers developed ahead of a strong cold front.', 'A wind gust of 40 knots was measured at KNHK.');
INSERT INTO public.stormevents_east VALUES (740573, 201802, 16, 1355, 201802, 16, 1355, 123490, 'ATLANTIC NORTH', 88, 2018, 'February', 'Marine Thunderstorm Wind', 'LWX', '16-FEB-18 13:55:00', 'EST-5', '16-FEB-18 13:55:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'HAMPSTEAD HILL ACADEMY (BLMHH)', 0, 'N', 'HAMPSTEAD HILL ACADEMY (BLMHH)', 39.29, -76.58, 39.29, -76.58, 'Gusty showers developed ahead of a cold front.', 'A wind gust in excess of 30 knots was reported at the Hampstead Hill Academy.');
INSERT INTO public.stormevents_east VALUES (740574, 201802, 16, 1355, 201802, 16, 1355, 123490, 'ATLANTIC NORTH', 88, 2018, 'February', 'Marine Thunderstorm Wind', 'LWX', '16-FEB-18 13:55:00', 'EST-5', '16-FEB-18 13:55:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 35, 'MG', NULL, NULL, 0, 'N', '(KMTN)MARTIN STATE AIRPORT', 0, 'N', '(KMTN)MARTIN STATE AIRPORT', 39.33, -76.42, 39.33, -76.42, 'Gusty showers developed ahead of a cold front.', 'A wind gust of 35 knots was reported at Martin State.');
