INSERT INTO public.stormevents_east VALUES (740577, 201802, 16, 1507, 201802, 16, 1507, 123490, 'ATLANTIC NORTH', 88, 2018, 'February', 'Marine Thunderstorm Wind', 'LWX', '16-FEB-18 15:07:00', 'EST-5', '16-FEB-18 15:07:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 34, 'EG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'Gusty showers developed ahead of a cold front.', 'A wind gust in excess of 30 knots was reported at Reagan National Airport.');
INSERT INTO public.stormevents_east VALUES (740041, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'CROZIER', 0, 'N', 'CROZIER', 37.63, -77.8, 37.63, -77.8, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 1.5 inches and 4.0 inches across the county. Tabscott reported 4.01 inches of rain. Crozier reported 2.29 inches of rain. Oilville (1 W) reported 2.09 inches of rain. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (740045, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'NNW', 'GOODALL', 1, 'NNW', 'GOODALL', 37.7934, -77.637, 37.7934, -77.637, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 1.5 inches and 4.0 inches across the county. Goodall (1 NNW) reported 4.07 inches of rain. Gilman (2 NNW) reported 2.62 inches of rain. Beaverdam (1 E) reported 2.27 inches of rain. Hanover County Municipal Airport reported 1.54 inches of rain. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (740060, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', NULL, NULL, NULL, NULL, 0, 'N', 'LOUISA', 0, 'N', 'LOUISA', 38.02, -78, 38.02, -78, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 2.0 inches and 4.2 inches across the county. Louisa reported 4.18 inches of rain. Zion Crossroads (1 NNE) reported 4.03 inches of rain. Mineral reported 3.76 inches of rain. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (740072, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWSS', NULL, NULL, NULL, NULL, 0, 'N', 'FARMVILLE', 0, 'N', 'FARMVILLE', 37.3, -78.57, 37.3, -78.57, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 1.0 inch and 2.5 inches across the county. Farmville reported 1.96 inches of rain. Elam (1 SW) reported 1.52 inches of rain. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (740326, 201804, 7, 1525, 201804, 7, 1525, 123458, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'TBW', '07-APR-18 15:25:00', 'EST-5', '07-APR-18 15:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'ESE', 'FANNING SPRINGS', 1, 'ESE', 'FANNING SPRINGS', 29.5737, -82.9069, 29.5737, -82.9069, 'A squall line developed ahead of a cold front and moved south through the Nature Coast and Central Florida during the afternoon and early evening of the 7th. Some of the stronger thunderstorms produced damaging wind gusts.', 'Numerous trees and power lines were reported to be knocked down on Northwest 80th Avenue.');
INSERT INTO public.stormevents_east VALUES (740341, 201804, 7, 1820, 201804, 7, 1820, 123458, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'TBW', '07-APR-18 18:20:00', 'EST-5', '07-APR-18 18:20:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Trained Spotter', 40, 'EG', NULL, NULL, 1, 'ENE', 'CHRISTINA', 1, 'ENE', 'CHRISTINA', 28.1044, -81.9404, 28.1044, -81.9404, 'A squall line developed ahead of a cold front and moved south through the Nature Coast and Central Florida during the afternoon and early evening of the 7th. Some of the stronger thunderstorms produced damaging wind gusts.', 'A 60 foot tree was uprooted by thunderstorm winds and fell across a road, landing on a carport. No other trees were knocked down in the area.');
INSERT INTO public.stormevents_east VALUES (742036, 201804, 10, 1000, 201804, 10, 1000, 123694, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '10-APR-18 10:00:00', 'EST-5', '10-APR-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 2, 'ENE', 'OLD TAMPA BAY', 2, 'ENE', 'OLD TAMPA BAY', 27.8578, -82.5527, 27.8578, -82.5527, 'A slow moving squall line pushed south through the eastern Gulf of Mexico on the 10th, producing thunderstorm wind gusts along the coast.', 'The PORTS site at Old Port Tampa (OPTF1) recorded a 41 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (742278, 201804, 15, 1242, 201804, 15, 1242, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '15-APR-18 12:42:00', 'EST-5', '15-APR-18 12:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 0, 'NNW', 'CEDAR KEY', 0, 'NNW', 'CEDAR KEY', 29.1338, -83.0309, 29.1338, -83.0309, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'The NOS NWLON station at Cedar Key (CKYF1) recorded a 41 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (734677, 201802, 27, 1340, 201802, 27, 1340, 122648, 'ATLANTIC SOUTH', 87, 2018, 'February', 'Waterspout', 'MFL', '27-FEB-18 13:40:00', 'EST-5', '27-FEB-18 13:40:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 10, 'E', 'PORT OF PALM BEACH', 10, 'E', 'PORT OF PALM BEACH', 26.76, -79.91, 26.76, -79.91, 'A weak frontal boundary lingering across South Florida lead to shower development over the local Atlantic during the morning and early afternoon hours. A suspected waterspout was spotted with a shower offshore West Palm Beach.', 'Video received via Twitter of funnel cloud associated with shower offshore West Palm Beach. Observer was unable to see clearly if funnel reached the water surface.');
INSERT INTO public.stormevents_east VALUES (752003, 201804, 15, 1455, 201804, 15, 1455, 125247, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'GSP', '15-APR-18 14:55:00', 'EST-5', '15-APR-18 14:55:00', 0, 0, 0, 0, '25.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'WOODLEAF', 1, 'E', 'WOODLEAF', 35.77, -80.59, 35.77, -80.59, 'Scattered to numerous afternoon thunderstorms developing ahead of a cold front moved into the North Carolina Piedmont from South Carolina during the early afternoon. Several of the storms produced severe weather in the form of large to very large hail and locally damaging winds.', 'County comms reported multiple trees blown down, with several on homes in the Woodleaf area.');
INSERT INTO public.stormevents_east VALUES (738698, 201803, 20, 1406, 201803, 20, 1406, 123208, 'FLORIDA', 12, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:06:00', 'EST-5', '20-MAR-18 14:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'W', 'MACCLENNY', 1, 'W', 'MACCLENNY', 30.28, -82.13, 30.28, -82.13, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Widespread 1 hail was reported near Macclenny.');
INSERT INTO public.stormevents_east VALUES (742448, 201804, 15, 1521, 201804, 15, 1521, 123764, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'TBW', '15-APR-18 15:21:00', 'EST-5', '15-APR-18 15:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 56, 'MG', NULL, NULL, 0, 'NW', 'GOLDEN BEACH', 0, 'NW', 'GOLDEN BEACH', 27.0725, -82.4528, 27.0725, -82.4528, 'A strong squall line moved into the west coast of Florida ahead of a fast moving cold front. Some of the stronger storms produced severe wind gusts, and one waterspout came onshore as a brief lived tornado.', 'The AWOS at Venice Municipal Airport (KVNC) recorded a 56 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (742449, 201804, 15, 1422, 201804, 15, 1426, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Waterspout', 'TBW', '15-APR-18 14:22:00', 'EST-5', '15-APR-18 14:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'WSW', 'MIDDLE TAMPA BAY', 3, 'NNE', 'MIDDLE TAMPA BAY', 27.7638, -82.5484, 27.8045, -82.5135, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'A citizen reported seeing a waterspout while driving on Interstate 275 in Pinellas County, looking back towards Tampa. Location was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (738699, 201803, 20, 1418, 201803, 20, 1418, 123208, 'FLORIDA', 12, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:18:00', 'EST-5', '20-MAR-18 14:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 1, 'W', 'BRYCEVILLE', 1, 'W', 'BRYCEVILLE', 30.38, -81.94, 30.38, -81.94, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Widespread hail up to ping-pong ball size was reported near Bryceville.');
INSERT INTO public.stormevents_east VALUES (738700, 201803, 20, 1422, 201803, 20, 1422, 123208, 'FLORIDA', 12, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:22:00', 'EST-5', '20-MAR-18 14:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1.5, NULL, NULL, NULL, 2, 'ESE', 'BOULOGNE', 2, 'ESE', 'BOULOGNE', 30.7319, -81.9479, 30.7319, -81.9479, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Ping-pong size hail was reported near Hilliard.');
INSERT INTO public.stormevents_east VALUES (738701, 201803, 20, 1425, 201803, 20, 1425, 123208, 'FLORIDA', 12, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:25:00', 'EST-5', '20-MAR-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 1, NULL, NULL, NULL, 3, 'SSE', 'SIMPSON YARD', 3, 'SSE', 'SIMPSON YARD', 30.31, -81.71, 30.31, -81.71, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', NULL);
INSERT INTO public.stormevents_east VALUES (786797, 201809, 6, 1200, 201809, 6, 1205, 131519, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Waterspout', 'MFL', '06-SEP-18 12:00:00', 'EST-5', '06-SEP-18 12:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 12, 'NNE', 'PORT EVERGLADES', 12, 'NNE', 'PORT EVERGLADES', 26.25, -80.04, 26.25, -80.04, 'A trough over the Bahamas helped increase deep level moisture across South Florida. Cool temperatures aloft and decent instabillity allowed for showers and thunderstorms to develop over South Florida Atlantic waters. One of these showers produced a waterspout offshore northern Broward County.', 'A member of the public called to report a funnel cloud approximately 6 miles southeast of Boca Raton. Location was estimated based on radar.');
INSERT INTO public.stormevents_east VALUES (787853, 201809, 8, 1534, 201809, 8, 1534, 131696, 'FLORIDA', 12, 2018, 'September', 'Funnel Cloud', 'MFL', '08-SEP-18 15:34:00', 'EST-5', '08-SEP-18 15:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'S', 'FLORIDA CITY', 2, 'S', 'FLORIDA CITY', 25.4152, -80.4814, 25.4152, -80.4814, 'An upper level low pressure area over Florida and moist southwest wind flow led to the development of showers and thunderstorms across much of South Florida during the afternoon hours.', 'A funnel cloud was spotted about halfway to the ground near US 1 about 2 miles south of Florida City.');
INSERT INTO public.stormevents_east VALUES (740030, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'N', 'FARMVILLE', 2, 'N', 'FARMVILLE', 37.329, -78.57, 37.329, -78.57, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 1.0 inch and 3.0 inches across the county. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (740034, 201802, 10, 2100, 201802, 11, 1600, 123410, 'VIRGINIA', 51, 2018, 'February', 'Heavy Rain', 'AKQ', '10-FEB-18 21:00:00', 'EST-5', '11-FEB-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'PALMYRA', 0, 'N', 'PALMYRA', 37.87, -78.28, 37.87, -78.28, 'Low pressure areas tracking northeast along a slow moving frontal boundary produced heavy rain and minor flooding across portions of central Virginia.', 'Rainfall totals generally ranged between 1.5 inches and 4.0 inches across the county. Palmyra River Gage reported 3.67 inches of rain. Antioch (2 SE) reported 3.10 inches of rain. Union Mills (1 S) reported 2.60 inches of rain. This heavy rain caused some minor street flooding.');
INSERT INTO public.stormevents_east VALUES (742279, 201804, 15, 1255, 201804, 15, 1255, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '15-APR-18 12:55:00', 'EST-5', '15-APR-18 12:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'EG', NULL, NULL, 6, 'WSW', 'CRYSTAL RIVER', 6, 'WSW', 'CRYSTAL RIVER', 28.8699, -82.6685, 28.8699, -82.6685, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'A home weather station in Crystal River (D4025) recorded a 39 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (742414, 201804, 15, 1418, 201804, 15, 1418, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '15-APR-18 14:18:00', 'EST-5', '15-APR-18 14:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 6, 'W', 'MIDDLE TAMPA BAY', 6, 'W', 'MIDDLE TAMPA BAY', 27.7606, -82.6269, 27.7606, -82.6269, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'The NOS station in Saint Petersburg (SAPF1) recorded a 43 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (742446, 201804, 15, 1412, 201804, 15, 1412, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '15-APR-18 14:12:00', 'EST-5', '15-APR-18 14:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'EG', NULL, NULL, 9, 'NNW', 'LOWER TAMPA BAY', 9, 'NNW', 'LOWER TAMPA BAY', 27.74, -82.7, 27.74, -82.7, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'The WeatherFlow station at Clam Bayou (XCBN) recorded a 44 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (742447, 201804, 15, 1406, 201804, 15, 1406, 123764, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'TBW', '15-APR-18 14:06:00', 'EST-5', '15-APR-18 14:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 51, 'EG', NULL, NULL, 1, 'NW', 'EDGEMONT KEY COMPS SITE', 1, 'NW', 'EDGEMONT KEY COMPS SITE', 27.61, -82.77, 27.61, -82.77, 'A strong squall line moved into the west coast of Florida ahead of a fast moving cold front. Some of the stronger storms produced severe wind gusts, and one waterspout came onshore as a brief lived tornado.', 'The WeatherFlow station at Egmont Key (XEGM) recorded a 51 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (738688, 201803, 19, 510, 201803, 19, 510, 123206, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'JAX', '19-MAR-18 05:10:00', 'EST-5', '19-MAR-18 05:10:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 4, 'NW', 'BELL', 4, 'NW', 'BELL', 29.8, -82.91, 29.8, -82.91, 'The first wave of pre-frontal thunderstorms moved across the Suwanee River Valley moved across the area as an MCS which produced wind damage across Gilchrist and Alachua counties.', 'Multiple barns were damaged and one was completely destroyed. The time of damage was based on radar. The cost of damage was unknown, but it was estimated so the event could be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (738689, 201803, 19, 530, 201803, 19, 530, 123206, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'JAX', '19-MAR-18 05:30:00', 'EST-5', '19-MAR-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'SSW', 'NEWBERRY', 3, 'SSW', 'NEWBERRY', 29.61, -82.65, 29.61, -82.65, 'The first wave of pre-frontal thunderstorms moved across the Suwanee River Valley moved across the area as an MCS which produced wind damage across Gilchrist and Alachua counties.', 'Numerous trees were blown down.');
INSERT INTO public.stormevents_east VALUES (738690, 201803, 19, 540, 201803, 19, 540, 123206, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'JAX', '19-MAR-18 05:40:00', 'EST-5', '19-MAR-18 05:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'ARCHER', 1, 'E', 'ARCHER', 29.53, -82.52, 29.53, -82.52, 'The first wave of pre-frontal thunderstorms moved across the Suwanee River Valley moved across the area as an MCS which produced wind damage across Gilchrist and Alachua counties.', 'Multiple trees were blown down in Archer and along Highway 441 between Archer and Newberry.');
INSERT INTO public.stormevents_east VALUES (786820, 201809, 19, 1400, 201809, 19, 1405, 131523, 'FLORIDA', 12, 2018, 'September', 'Funnel Cloud', 'MFL', '19-SEP-18 14:00:00', 'EST-5', '19-SEP-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 9, 'WNW', 'DAVIE', 9, 'WNW', 'DAVIE', 26.14, -80.36, 26.14, -80.36, 'A sea breeze weather pattern across South Florida, where showers and thunderstorms developed along sea breeze and boundary collisions. Thunderstorms developed across the western east coast metro in the afternoon where a boundary collision allowed a funnel cloud to form over western Broward County.', 'Multiple members of the broadcast media reported a funnel cloud near Markham Park area around 3PM EDT associated with an area of showers and thunderstorms.');
INSERT INTO public.stormevents_east VALUES (786882, 201809, 13, 705, 201809, 13, 705, 131541, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Waterspout', 'MFL', '13-SEP-18 07:05:00', 'EST-5', '13-SEP-18 07:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 4, 'NE', 'BOCA RATON', 4, 'NE', 'BOCA RATON', 26.3692, -80.0341, 26.3692, -80.0341, 'Light wind flow with diurnal showers over the local Florida waters. With the light wind flow it was a favorable environment for waterspouts. A shower offshore Palm Beach produced a waterspout.', 'A trained spotter called to report a waterspout offshore Palm Beach associated with a shower.');
INSERT INTO public.stormevents_east VALUES (738691, 201803, 19, 600, 201803, 19, 600, 123206, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'JAX', '19-MAR-18 06:00:00', 'EST-5', '19-MAR-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'ARREDONDA', 1, 'W', 'ARREDONDA', 29.5981, -82.4447, 29.5981, -82.4447, 'The first wave of pre-frontal thunderstorms moved across the Suwanee River Valley moved across the area as an MCS which produced wind damage across Gilchrist and Alachua counties.', 'Trees were blown down along Parker Road. About 19 power poles were snapped.');
INSERT INTO public.stormevents_east VALUES (738702, 201803, 20, 1425, 201803, 20, 1425, 123208, 'FLORIDA', 12, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:25:00', 'EST-5', '20-MAR-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 1, NULL, NULL, NULL, 2, 'SW', 'PLUMMER', 2, 'SW', 'PLUMMER', 30.41, -81.82, 30.41, -81.82, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Widespread quarter size hail was reported.');
INSERT INTO public.stormevents_east VALUES (738703, 201803, 20, 1430, 201803, 20, 1430, 123208, 'FLORIDA', 12, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:30:00', 'EST-5', '20-MAR-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 1.75, NULL, NULL, NULL, 3, 'NNW', 'GARDEN CITY', 3, 'NNW', 'GARDEN CITY', 30.47, -81.72, 30.47, -81.72, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Widespread golf ball size hail fell at the NWS Jacksonville office located at the Jacksonville International Airport.');
INSERT INTO public.stormevents_east VALUES (738692, 201803, 20, 1310, 201803, 20, 1310, 123207, 'GEORGIA', 13, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 13:10:00', 'EST-5', '20-MAR-18 13:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'NE', 'DIXIE UNION', 1, 'NE', 'DIXIE UNION', 31.34, -82.46, 31.34, -82.46, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Quarter size hail was observed in Dixie Union.');
INSERT INTO public.stormevents_east VALUES (738693, 201803, 20, 1332, 201803, 20, 1332, 123207, 'GEORGIA', 13, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 13:32:00', 'EST-5', '20-MAR-18 13:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 2, NULL, NULL, NULL, 1, 'E', 'BLACKSHEAR', 1, 'E', 'BLACKSHEAR', 31.3, -82.24, 31.3, -82.24, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Widespread egg sized hail was reported near Blackshear.');
INSERT INTO public.stormevents_east VALUES (738695, 201803, 20, 1400, 201803, 20, 1400, 123207, 'GEORGIA', 13, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:00:00', 'EST-5', '20-MAR-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 5, 'WSW', 'SILCO', 5, 'WSW', 'SILCO', 30.8386, -81.8981, 30.8386, -81.8981, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Quarter size hail was reported about 3 miles west of Browntown near Highway 40.');
INSERT INTO public.stormevents_east VALUES (738696, 201803, 20, 1400, 201803, 20, 1400, 123207, 'GEORGIA', 13, 2018, 'March', 'Hail', 'JAX', '20-MAR-18 14:00:00', 'EST-5', '20-MAR-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 1, 'WSW', 'MC KINNON', 1, 'WSW', 'MC KINNON', 31.42, -81.95, 31.42, -81.95, 'A strong short wave trough and pre-frontal trough over a moist and unstable environment triggered severe thunderstorm that produced large hail and gusty winds. Strong deep layer shear and most unstable CAPEs where near 2500 J/kg with steep mid level lapse rates (over 8C/km). The Storm Prediction Center highlighted an Enhanced Risk of Severe Storms across the local area.', 'Hail was reported in Manningtown.');
