INSERT INTO public.stormevents_east VALUES (752838, 201805, 15, 1347, 201805, 15, 1347, 125464, 'NEW YORK', 36, 2018, 'May', 'Hail', 'ALY', '15-MAY-18 13:47:00', 'EST-5', '15-MAY-18 13:47:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.75, NULL, NULL, NULL, 1, 'S', 'MANORTON', 1, 'S', 'MANORTON', 42.09, -73.8, 42.09, -73.8, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', NULL);
INSERT INTO public.stormevents_east VALUES (750489, 201804, 16, 144, 201804, 16, 144, 125140, 'MARYLAND', 24, 2018, 'April', 'Thunderstorm Wind', 'LWX', '16-APR-18 01:44:00', 'EST-5', '16-APR-18 01:44:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 57, 'MG', NULL, NULL, 2, 'SE', 'COBB IS', 2, 'SE', 'COBB IS', 38.243, -76.827, 38.243, -76.827, 'A strong cold front was able to mix down strong winds from aloft. There was enough instability for an isolated thunderstorm to produce damaging wind gusts in extreme southern Maryland.', 'A wind gust of 66 mph was reported at Cobb Point.');
