INSERT INTO public.stormevents_east VALUES (753695, 201804, 16, 341, 201804, 16, 538, 125669, 'DISTRICT OF COLUMBIA', 11, 2018, 'April', 'Flash Flood', 'LWX', '16-APR-18 03:41:00', 'EST-5', '16-APR-18 05:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'WALTER REED', 1, 'SW', 'WALTER REED', 38.9862, -77.0528, 38.9713, -77.045, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 1.5 to 2 inches fell in the District, causing flash flooding followed by flooding of Rock Creek which continued into early afternoon.', 'Water levels on Rock Creek rapidly rose above the 7 foot flood stage, causing flooding within Rock Creek Park in the District.');
INSERT INTO public.stormevents_east VALUES (753710, 201804, 16, 539, 201804, 16, 630, 125669, 'DISTRICT OF COLUMBIA', 11, 2018, 'April', 'Flood', 'LWX', '16-APR-18 05:39:00', 'EST-5', '16-APR-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'DALECARLIA RESERVOIR', 2, 'SSE', 'DALECARLIA RESERVOIR', 38.9249, -77.1075, 38.9246, -77.1071, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 1.5 to 2 inches fell in the District, causing flash flooding followed by flooding of Rock Creek which continued into early afternoon.', 'Minor street flooding was reported at the intersection of Canal Road and Arizona Avenue in Northwest DC.');
