INSERT INTO public.stormevents_east VALUES (753780, 201804, 16, 302, 201804, 16, 400, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flash Flood', 'LWX', '16-APR-18 03:02:00', 'EST-5', '16-APR-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'WSW', 'TREMONT', 38.8456, -77.2392, 38.8453, -77.2375, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'A swift water rescue occurred on Woodburn Road near Annandale at Accotink Creek. One person was successfully rescued from a vehicle.');
