INSERT INTO public.stormevents_east VALUES (750499, 201804, 16, 116, 201804, 16, 146, 125156, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'LWX', '16-APR-18 01:16:00', 'EST-5', '16-APR-18 01:46:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 44, 'MG', NULL, NULL, 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 38.34, -76.99, 38.34, -76.99, 'A strong cold front passed through, and showers were able to mix down gusty winds from aloft.', 'Wind gusts up to 44 knots were reported at Potomac Light.');
INSERT INTO public.stormevents_east VALUES (750501, 201804, 16, 116, 201804, 16, 146, 125156, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'LWX', '16-APR-18 01:16:00', 'EST-5', '16-APR-18 01:46:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 51, 'MG', NULL, NULL, 0, 'N', 'MONROE CREEK (MON)', 0, 'N', 'MONROE CREEK (MON)', 38.23, -76.95, 38.23, -76.95, 'A strong cold front passed through, and showers were able to mix down gusty winds from aloft.', 'Wind gusts up to 51 knots were reported at Monroe Creek.');
INSERT INTO public.stormevents_east VALUES (786345, 201809, 17, 1915, 201809, 17, 2025, 131419, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '17-SEP-18 19:15:00', 'EST-5', '17-SEP-18 20:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'SILVER CITY', 1, 'ENE', 'SILVER CITY', 34.9993, -79.2499, 35.0024, -79.2081, 'As remnants of Florence lifted north of the area, scattered thunderstorms developed during the afternoon due to strong differential heating within the pronounced mid-level dry slot, east of the center of the circulation. Two thunderstorms produced some scattered thunderstorm wind damage, along with some isolated flash flooding due to the  wet antecedent conditions.', 'Antecedent wet conditions from Florence combined with additional heavy rain from |the thunderstorms resulted in several flooded roads within the Raeford city limits.');
INSERT INTO public.stormevents_east VALUES (786346, 201809, 17, 1915, 201809, 17, 2025, 131419, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '17-SEP-18 19:15:00', 'EST-5', '17-SEP-18 20:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'KORNBOW', 5, 'WNW', 'BEAVER CREEK', 35.08, -78.95, 35.1223, -79.0851, 'As remnants of Florence lifted north of the area, scattered thunderstorms developed during the afternoon due to strong differential heating within the pronounced mid-level dry slot, east of the center of the circulation. Two thunderstorms produced some scattered thunderstorm wind damage, along with some isolated flash flooding due to the  wet antecedent conditions.', 'Antecedent wet conditions from Florence combined with additional heavy rain from |the thunderstorms resulted in numerous flooded roads across northwestern Fayetteville, Bonnie Doone, and Spring Lake.');
INSERT INTO public.stormevents_east VALUES (800236, 201809, 27, 1935, 201809, 27, 1935, 133721, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '27-SEP-18 19:35:00', 'EST-5', '27-SEP-18 19:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNE', 'KNIGHTDALE WNDLL ARP', 3, 'NNE', 'KNIGHTDALE WNDLL ARP', 35.8351, -78.4046, 35.8351, -78.4046, 'Isolated severe storms developed ahead of a cold front during the late afternoon in a moist and unstable air mass. A more organized comma head and trailing line of storms moved into the area mid to late evening. Some of the storms produced wind damage across portions of the area.', 'One tree was reported down blocking the entrance to Shanley Drive near Edgemont Road.');
INSERT INTO public.stormevents_east VALUES (800237, 201809, 27, 2115, 201809, 27, 2115, 133721, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '27-SEP-18 21:15:00', 'EST-5', '27-SEP-18 21:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'ALBEMARLE', 1, 'S', 'ALBEMARLE', 35.3487, -80.2183, 35.3487, -80.2183, 'Isolated severe storms developed ahead of a cold front during the late afternoon in a moist and unstable air mass. A more organized comma head and trailing line of storms moved into the area mid to late evening. Some of the storms produced wind damage across portions of the area.', 'One tree was reported down near the intersection of Forest and White Oak Avenues.');
INSERT INTO public.stormevents_east VALUES (752841, 201805, 15, 1351, 201805, 15, 1351, 125464, 'NEW YORK', 36, 2018, 'May', 'Hail', 'ALY', '15-MAY-18 13:51:00', 'EST-5', '15-MAY-18 13:51:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 2, NULL, NULL, NULL, 2, 'ESE', 'SNYDERVILLE', 2, 'ESE', 'SNYDERVILLE', 42.0683, -73.7243, 42.0683, -73.7243, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', 'Hail shattered windows of two vehicles on the Taconic State Parkway near the Gallatin Overlook.');
INSERT INTO public.stormevents_east VALUES (751656, 201805, 4, 2006, 201805, 4, 2006, 125334, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 20:06:00', 'EST-5', '04-MAY-18 20:06:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'E', 'GRAFTON', 1, 'E', 'GRAFTON', 43.17, -72.61, 43.17, -72.61, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across New York and New England. A line of thunderstorms developed along this front and pushed into southern Vermont in the evening, resulting in dozens of downed trees and wires. Over 2,500 customers lost power as a result of the storms.', 'Several trees were downed.');
INSERT INTO public.stormevents_east VALUES (752842, 201805, 15, 1357, 201805, 15, 1357, 125464, 'NEW YORK', 36, 2018, 'May', 'Hail', 'ALY', '15-MAY-18 13:57:00', 'EST-5', '15-MAY-18 13:57:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'NW', 'MT MERION PARK', 1, 'NW', 'MT MERION PARK', 42.04, -73.99, 42.04, -73.99, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', NULL);
INSERT INTO public.stormevents_east VALUES (756349, 201805, 15, 1519, 201805, 15, 1519, 125464, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '15-MAY-18 15:19:00', 'EST-5', '15-MAY-18 15:19:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', 50, 'EG', NULL, NULL, 0, 'ENE', 'CHELSEA', 0, 'ENE', 'CHELSEA', 41.5512, -73.9642, 41.5512, -73.9642, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', 'Trees were downed along Chelsea Road.');
INSERT INTO public.stormevents_east VALUES (752843, 201805, 15, 1405, 201805, 15, 1405, 125464, 'NEW YORK', 36, 2018, 'May', 'Hail', 'ALY', '15-MAY-18 14:05:00', 'EST-5', '15-MAY-18 14:05:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'E', 'COPAKE', 0, 'E', 'COPAKE', 42.1002, -73.5415, 42.1002, -73.5415, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', NULL);
INSERT INTO public.stormevents_east VALUES (751013, 201805, 10, 1553, 201805, 10, 1553, 125224, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '10-MAY-18 15:53:00', 'EST-5', '10-MAY-18 15:53:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'SCHOHARIE', 2, 'SW', 'SCHOHARIE', 42.6504, -74.3419, 42.6504, -74.3419, 'A broken line of thunderstorms tracked across eastern New York during the afternoon and evening of May 10th. One of these storms produced wind damage in Schoharie County.', 'A tree and large tree limbs were downed on Sunnyside Road.');
INSERT INTO public.stormevents_east VALUES (751651, 201805, 4, 1941, 201805, 4, 1941, 125334, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:41:00', 'EST-5', '04-MAY-18 19:41:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SE', 'DORSET', 1, 'SE', 'DORSET', 43.24, -73.08, 43.24, -73.08, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across New York and New England. A line of thunderstorms developed along this front and pushed into southern Vermont in the evening, resulting in dozens of downed trees and wires. Over 2,500 customers lost power as a result of the storms.', 'Several trees were downed.');
