INSERT INTO public.stormevents_east VALUES (733893, 201801, 12, 1426, 201801, 12, 1426, 122559, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'JAX', '12-JAN-18 14:26:00', 'EST-5', '12-JAN-18 14:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 0, 'N', 'SAUF1 CMAN', 0, 'N', 'SAUF1 CMAN', 29.85, -81.27, 29.85, -81.27, 'A pre-frontal line of showers and thunderstorms moved west to east across the area during the day with peak daytime heating mixing down strong wind gusts of 40-50 mph.', NULL);
INSERT INTO public.stormevents_east VALUES (733894, 201801, 12, 1436, 201801, 12, 1436, 122559, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'JAX', '12-JAN-18 14:36:00', 'EST-5', '12-JAN-18 14:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'MG', NULL, NULL, 14, 'SSE', 'SAUF1 CMAN', 14, 'SSE', 'SAUF1 CMAN', 29.66, -81.21, 29.66, -81.21, 'A pre-frontal line of showers and thunderstorms moved west to east across the area during the day with peak daytime heating mixing down strong wind gusts of 40-50 mph.', 'The automated weather station at Marineland measured the wind gust of 44 mph.');
INSERT INTO public.stormevents_east VALUES (735513, 201801, 12, 1205, 201801, 12, 1600, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 12:05:00', 'EST-5', '12-JAN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Ice Jam', NULL, 1, 'SE', 'CAMPBELL', 1, 'WNW', 'COOPERS PLAINS', 42.22, -77.19, 42.186, -77.1693, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam developed at the Interstate 86 bridge over the Cohocton River. Water was flooding low lying agricultural areas near the river.');
INSERT INTO public.stormevents_east VALUES (735514, 201801, 12, 1210, 201801, 12, 1900, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 12:10:00', 'EST-5', '12-JAN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Ice Jam', NULL, 1, 'E', 'WEST BROOKVILLE', 0, 'ENE', 'WEST BROOKVILLE', 41.5, -74.56, 41.5014, -74.5636, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam occurred on the Pine Kill at the State Route 209 bridge. The road was closed in this area for hours. Ice and floodwaters surrounded a couple homes near the creek. Residents were evacuated.');
INSERT INTO public.stormevents_east VALUES (735515, 201801, 12, 1422, 201801, 12, 1630, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 14:22:00', 'EST-5', '12-JAN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'FORESTPORT', 1, 'N', 'WOODGULL', 43.45, -75.22, 43.4446, -75.1968, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Water flooding streets and a basement on Newton Street.');
INSERT INTO public.stormevents_east VALUES (735516, 201801, 12, 1550, 201801, 12, 1900, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 15:50:00', 'EST-5', '12-JAN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Ice Jam', NULL, 1, 'NNE', 'ARKVILLE', 1, 'NNE', 'ARKVILLE', 42.17, -74.61, 42.1669, -74.6094, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam was causing minor, low land flooding along the East Branch Delaware river between Kelly Corners and Margaretville.');
INSERT INTO public.stormevents_east VALUES (735517, 201801, 12, 1645, 201801, 12, 2000, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 16:45:00', 'EST-5', '12-JAN-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 0, 'N', 'EAST BRANCH', 1, 'ESE', 'PEAKVILLE', 41.98, -75.12, 41.9734, -75.0822, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'The county emergency manager reported a large ice jam at the confluence of the Beaver Kill and East Branch Delaware near East Branch. Water was flooding agricultural areas near the river and ice was being pushed upstream on the Beaver Kill.');
INSERT INTO public.stormevents_east VALUES (735518, 201801, 13, 405, 201801, 13, 1851, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '13-JAN-18 04:05:00', 'EST-5', '13-JAN-18 18:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 0, 'N', 'SYLVAN BEACH', 1, 'WNW', 'TABERG', 43.2062, -75.7298, 43.3032, -75.6372, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Ice jam flooding was occurring  along the Fish Creek in the vicinity of Vienna, Sylvan Beach, New  London and Taberg. The ice jam was causing flooding of several  homes along Vienna Road, Haskins Road and also Cove Road.  Evacuations were taking place.');
INSERT INTO public.stormevents_east VALUES (727810, 201801, 12, 1830, 201801, 12, 1830, 121500, 'PENNSYLVANIA', 42, 2018, 'January', 'Thunderstorm Wind', 'CTP', '12-JAN-18 18:30:00', 'EST-5', '12-JAN-18 18:30:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 3, 'ESE', '(PSB)MID ST ARPT PHI', 3, 'ESE', '(PSB)MID ST ARPT PHI', 40.8698, -78.0281, 40.8698, -78.0281, 'A strong cold front push into near record warmth and humidity in central Pennsylvania during the evening of January 12, 2018. This front produced some gusty rain showers, although little if any lightning was observed. Sporadic wind damage was observed in the central mountains.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down power lines across a road near Beaver Mills in Rush Township.');
INSERT INTO public.stormevents_east VALUES (727818, 201801, 12, 1955, 201801, 12, 1955, 121500, 'PENNSYLVANIA', 42, 2018, 'January', 'Thunderstorm Wind', 'CTP', '12-JAN-18 19:55:00', 'EST-5', '12-JAN-18 19:55:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'NNW', 'MILLHEIM', 2, 'NNW', 'MILLHEIM', 40.907, -77.4776, 40.907, -77.4776, 'A strong cold front push into near record warmth and humidity in central Pennsylvania during the evening of January 12, 2018. This front produced some gusty rain showers, although little if any lightning was observed. Sporadic wind damage was observed in the central mountains.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree across the intersection of Toll House Road and Narrows Road near Millheim.');
INSERT INTO public.stormevents_east VALUES (727232, 201801, 12, 600, 201801, 12, 1200, 121489, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'RLX', '12-JAN-18 06:00:00', 'EST-5', '12-JAN-18 12:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'PLUM RUN', 1, 'NNE', 'EVERETT', 39.3716, -80.9888, 39.494, -81.0191, 'Strong moisture advection ahead of a southern stream low pressure system brought a prolonged period of moderate to heavy rainfall across the middle Ohio River Valley and Central Appalachians. The rainfall started during the evening of the 11th, and continued through most of the day on the 12th before changing to snow late in the day. Generally 1.5 to 2.5 inches of rain fell. Most of this rain immediately turned to runoff due to a combination of frozen and saturated soil. This caused some creeks and streams to flood.', 'Many creeks and streams across Tyler County flooded, resulting in numerous road closures. This included flooding along Elk Fork, which closed portions of County Route 11. County Routes 6 and 7 were closed due to high water on Rush Fork and Sugar Creek. Point Pleasant Creek flooded, closing portions of State Route 180. Other small tributaries of Middle Island Creek also flooded, closing portions of County Routes 13, 14 and 16, along with State Routes 18, and 24.');
INSERT INTO public.stormevents_east VALUES (729124, 201801, 23, 21, 201801, 23, 21, 121814, 'KENTUCKY', 21, 2018, 'January', 'Hail', 'RLX', '23-JAN-18 00:21:00', 'EST-5', '23-JAN-18 00:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 0.75, NULL, NULL, NULL, 0, 'N', 'FALLSBURG', 0, 'N', 'FALLSBURG', 38.17, -82.67, 38.17, -82.67, 'A strong cold front brought showers and thunderstorms to the middle Ohio River Valley late on the 22nd, into the 23rd. Most of the storms remained low topped, but did contain copious amounts of small hail -- enough to cover the ground in some spots. One storm became more organized, and produced some minor tree damage in Boyd County, and also just across the Ohio River in Lawrence County, Ohio.', 'The ground was covered with hail. Most of it was pea sized, but some stones as big as dimes were noted.');
INSERT INTO public.stormevents_east VALUES (753781, 201804, 16, 330, 201804, 16, 430, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 03:30:00', 'EST-5', '16-APR-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LINCOLNIA', 1, 'S', 'LINCOLNIA', 38.81, -77.15, 38.811, -77.1484, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'The HOV lanes of I-395 were flooded and closed near the intersection with the I-395 Express Lanes.');
INSERT INTO public.stormevents_east VALUES (727234, 201801, 13, 400, 201801, 13, 1100, 121489, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'RLX', '13-JAN-18 04:00:00', 'EST-5', '13-JAN-18 11:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'W', 'VALLEY BEND', 0, 'WNW', 'HUTTONSVILLE', 38.7666, -79.9554, 38.7228, -79.988, 'Strong moisture advection ahead of a southern stream low pressure system brought a prolonged period of moderate to heavy rainfall across the middle Ohio River Valley and Central Appalachians. The rainfall started during the evening of the 11th, and continued through most of the day on the 12th before changing to snow late in the day. Generally 1.5 to 2.5 inches of rain fell. Most of this rain immediately turned to runoff due to a combination of frozen and saturated soil. This caused some creeks and streams to flood.', 'The Tygart Valley River at Mill Creek came out of its banks, causing minor flooding on County Route 39. The river gauge at Mill Creek indicated the river spilled from its banks around 4 AM on the 13th, crested about half a foot above its bankfull level of 11 feet during the predawn hours, and returned to within its banks by late morning.');
INSERT INTO public.stormevents_east VALUES (727235, 201801, 13, 200, 201801, 13, 500, 121489, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'RLX', '13-JAN-18 02:00:00', 'EST-5', '13-JAN-18 05:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NNE', 'GALE', 1, 'NNE', 'GALE', 38.9172, -80.09, 38.9109, -80.0954, 'Strong moisture advection ahead of a southern stream low pressure system brought a prolonged period of moderate to heavy rainfall across the middle Ohio River Valley and Central Appalachians. The rainfall started during the evening of the 11th, and continued through most of the day on the 12th before changing to snow late in the day. Generally 1.5 to 2.5 inches of rain fell. Most of this rain immediately turned to runoff due to a combination of frozen and saturated soil. This caused some creeks and streams to flood.', 'The Middle Fork of the Tygart River flooded near Ellamore, closing a section of County Route 28. The river gauge at Ellamore showed the river rose just above its bankfull level of 13 feet during the predawn hours of the 13th.');
INSERT INTO public.stormevents_east VALUES (727236, 201801, 13, 830, 201801, 13, 1200, 121489, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'RLX', '13-JAN-18 08:30:00', 'EST-5', '13-JAN-18 12:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NNE', 'REVEL', 2, 'NE', 'LETTER GAP', 38.959, -80.8628, 38.9004, -80.8836, 'Strong moisture advection ahead of a southern stream low pressure system brought a prolonged period of moderate to heavy rainfall across the middle Ohio River Valley and Central Appalachians. The rainfall started during the evening of the 11th, and continued through most of the day on the 12th before changing to snow late in the day. Generally 1.5 to 2.5 inches of rain fell. Most of this rain immediately turned to runoff due to a combination of frozen and saturated soil. This caused some creeks and streams to flood.', 'The Little Kanawha River reached minor flood stage for several hours. The river gauge at Glenville indicated the river just surpassed the minor flood stage level of 23 feet, causing water to cover some streets right along the river in downtown Glenville.');
INSERT INTO public.stormevents_east VALUES (753782, 201804, 16, 516, 201804, 16, 630, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 05:16:00', 'EST-5', '16-APR-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'FORDWICK', 2, 'SW', 'FORDWICK', 38.0483, -79.3951, 38.0457, -79.3932, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'Wallace Mill Road impassible due to high water near Estaline Valley Road. Bashaw Road also closed nearby at Little River Road.');
INSERT INTO public.stormevents_east VALUES (753783, 201804, 16, 529, 201804, 16, 830, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 05:29:00', 'EST-5', '16-APR-18 08:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'SSW', 'WEST AUGUSTA', 4, 'ENE', 'DEERFIELD', 38.2307, -79.3458, 38.2273, -79.3446, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'Old Parkersburg Turnpike flooded and impassible near Bear Wallow Flat Road at the Calfpasture River.');
INSERT INTO public.stormevents_east VALUES (753784, 201804, 16, 606, 201804, 16, 700, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 06:06:00', 'EST-5', '16-APR-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'DOOMS', 3, 'S', 'DOOMS', 38.0742, -78.8597, 38.073, -78.8601, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'A Street flooded near Calf Mountain Road.');
INSERT INTO public.stormevents_east VALUES (753785, 201804, 16, 729, 201804, 16, 900, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 07:29:00', 'EST-5', '16-APR-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'CROWELLS CORNER', 1, 'W', 'KENMORE', 38.9549, -77.2922, 38.9517, -77.2844, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'Browns Mill Road flooded and closed between Beulah Road and Windstone Drive.');
INSERT INTO public.stormevents_east VALUES (753786, 201804, 16, 717, 201804, 16, 1315, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 07:17:00', 'EST-5', '16-APR-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BRISTOW', 1, 'N', 'BRISTOW', 38.7356, -77.5336, 38.7357, -77.5316, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'The stream gauge on Broad Run at Bristow exceeded the 9.5 foot flood stage, flooding Piper Lane at and near the railroad bridge.');
INSERT INTO public.stormevents_east VALUES (753790, 201804, 16, 619, 201804, 16, 730, 125672, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '16-APR-18 06:19:00', 'EST-5', '16-APR-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'OCCOQUAN', 1, 'SE', 'OCCOQUAN', 38.6707, -77.2539, 38.6699, -77.2536, 'Low pressure and its associated cold front passed through during the early morning hours of April 16th. Heavy rain of 2 to 4 inches fell in portions of the state, producing flooding throughout northern Virginia.', 'I-95 Express Lanes flooded and closed at Virginia Route 123.');
INSERT INTO public.stormevents_east VALUES (753792, 201804, 27, 558, 201804, 27, 800, 125687, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '27-APR-18 05:58:00', 'EST-5', '27-APR-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'TREMONT', 1, 'WSW', 'TREMONT', 38.8479, -77.2382, 38.8459, -77.2392, 'Early morning brief heavy rain up to one inch was enough to cause some minor flooding in Fairfax County, Virginia during the morning commute on April 27th.', 'Overflow from Accotink Creek flooded a portion of Woodburn Road. One vehicle became stuck in the floodwaters and the occupant required rescue.');
INSERT INTO public.stormevents_east VALUES (753793, 201804, 27, 621, 201804, 27, 800, 125687, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '27-APR-18 06:21:00', 'EST-5', '27-APR-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BURKE', 1, 'SSE', 'BURKE', 38.7883, -77.2661, 38.7877, -77.2655, 'Early morning brief heavy rain up to one inch was enough to cause some minor flooding in Fairfax County, Virginia during the morning commute on April 27th.', 'Flooding reported near the intersection of Burke Road and Heritage Square Drive, near Pohick Creek.');
INSERT INTO public.stormevents_east VALUES (753794, 201804, 27, 631, 201804, 27, 800, 125687, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'LWX', '27-APR-18 06:31:00', 'EST-5', '27-APR-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'KENMORE', 2, 'S', 'KENMORE', 38.9264, -77.2654, 38.9252, -77.2664, 'Early morning brief heavy rain up to one inch was enough to cause some minor flooding in Fairfax County, Virginia during the morning commute on April 27th.', 'Wolftrap Creek rose out of its banks, flooding Old Courthouse Road near Besley Road in Wolf Trap. One vehicle ran off the road in the high waters and the occupant had to await rescue.');
INSERT INTO public.stormevents_east VALUES (778068, 201808, 3, 1627, 201808, 3, 1627, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '03-AUG-18 16:27:00', 'EST-5', '03-AUG-18 16:27:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'ESE', 'BLANDFORD', 1, 'ESE', 'BLANDFORD', 42.1764, -72.9179, 42.1764, -72.9179, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:27 PM EST, thunderstorm winds brought a tree down in Blandford on state route 23 west of South Road.');
INSERT INTO public.stormevents_east VALUES (750505, 201804, 16, 135, 201804, 16, 145, 125156, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'LWX', '16-APR-18 01:35:00', 'EST-5', '16-APR-18 01:45:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 39, 'MG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'A strong cold front passed through, and showers were able to mix down gusty winds from aloft.', 'Wind gusts up to 39 knots were reported at Cuckold Creek.');
INSERT INTO public.stormevents_east VALUES (750506, 201804, 16, 139, 201804, 16, 144, 125156, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'LWX', '16-APR-18 01:39:00', 'EST-5', '16-APR-18 01:44:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 57, 'MG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'A strong cold front passed through, and showers were able to mix down gusty winds from aloft.', 'Wind gusts of 41 to 57 knots were reported at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (750507, 201804, 16, 142, 201804, 16, 142, 125156, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'LWX', '16-APR-18 01:42:00', 'EST-5', '16-APR-18 01:42:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'LEWISETTA MD (LWTV2)', 0, 'N', 'LEWISETTA MD (LWTV2)', 38, -76.47, 38, -76.47, 'A strong cold front passed through, and showers were able to mix down gusty winds from aloft.', 'Wind gusts of 35 knots were reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (800245, 201809, 10, 1518, 201809, 10, 1518, 133723, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '10-SEP-18 15:18:00', 'EST-5', '10-SEP-18 15:18:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NE', 'PINKSTON', 3, 'NE', 'PINKSTON', 35.0551, -80.0448, 35.0551, -80.0448, 'A weak wedge front extended through the Piedmont, with stratus lasting through the day in the northwest Piedmont. Convection formed along the wedge front, coincident with a weak surface low over the Upstate of South Carolina. This then congealed into a curved band of convection which tracked northeastward into southwestern and western central North Carolina. A few of these storms became severe and produced wind damage.', 'One tree was reported down on power lines near the intersection of Pleasant Grove Church Road and Dennis Road.');
INSERT INTO public.stormevents_east VALUES (786350, 201809, 17, 1810, 201809, 17, 1810, 131419, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '17-SEP-18 18:10:00', 'EST-5', '17-SEP-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'MANCHESTER', 1, 'S', 'MANCHESTER', 35.19, -78.98, 35.19, -78.98, 'As remnants of Florence lifted north of the area, scattered thunderstorms developed during the afternoon due to strong differential heating within the pronounced mid-level dry slot, east of the center of the circulation. Two thunderstorms produced some scattered thunderstorm wind damage, along with some isolated flash flooding due to the  wet antecedent conditions.', 'Numerous trees blown down in the Spring Lake area.');
INSERT INTO public.stormevents_east VALUES (800246, 201809, 10, 1519, 201809, 10, 1519, 133723, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '10-SEP-18 15:19:00', 'EST-5', '10-SEP-18 15:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 6, 'NE', 'PINKSTON', 6, 'NE', 'PINKSTON', 35.0713, -80.0006, 35.0713, -80.0006, 'A weak wedge front extended through the Piedmont, with stratus lasting through the day in the northwest Piedmont. Convection formed along the wedge front, coincident with a weak surface low over the Upstate of South Carolina. This then congealed into a curved band of convection which tracked northeastward into southwestern and western central North Carolina. A few of these storms became severe and produced wind damage.', 'One tree was reported down on Grassy Island Road.');
INSERT INTO public.stormevents_east VALUES (800247, 201809, 10, 1604, 201809, 10, 1604, 133723, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '10-SEP-18 16:04:00', 'EST-5', '10-SEP-18 16:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'S', 'CAPELSIE', 1, 'S', 'CAPELSIE', 35.3095, -79.8804, 35.3095, -79.8804, 'A weak wedge front extended through the Piedmont, with stratus lasting through the day in the northwest Piedmont. Convection formed along the wedge front, coincident with a weak surface low over the Upstate of South Carolina. This then congealed into a curved band of convection which tracked northeastward into southwestern and western central North Carolina. A few of these storms became severe and produced wind damage.', 'One tree was reported down in the 1800 block of Hicks Road.');
INSERT INTO public.stormevents_east VALUES (750509, 201804, 16, 127, 201804, 16, 142, 125156, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'LWX', '16-APR-18 01:27:00', 'EST-5', '16-APR-18 01:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BABAR POINT (BAB)', 0, 'N', 'BABAR POINT (BAB)', 38.31, -77.03, 38.31, -77.03, 'A strong cold front passed through, and showers were able to mix down gusty winds from aloft.', 'Wind gusts in excess of 30 knots were reported at Baber Point.');
INSERT INTO public.stormevents_east VALUES (800248, 201809, 10, 1622, 201809, 10, 1622, 133723, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '10-SEP-18 16:22:00', 'EST-5', '10-SEP-18 16:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ESE', 'BISCOE', 1, 'ESE', 'BISCOE', 35.365, -79.7789, 35.365, -79.7789, 'A weak wedge front extended through the Piedmont, with stratus lasting through the day in the northwest Piedmont. Convection formed along the wedge front, coincident with a weak surface low over the Upstate of South Carolina. This then congealed into a curved band of convection which tracked northeastward into southwestern and western central North Carolina. A few of these storms became severe and produced wind damage.', 'One tree was reported down on Pine Street.');
INSERT INTO public.stormevents_east VALUES (779817, 201808, 1, 1815, 201808, 1, 1815, 130230, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '01-AUG-18 18:15:00', 'EST-5', '01-AUG-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'SE', 'LORAY', 2, 'SE', 'LORAY', 35.799, -80.94, 35.799, -80.94, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. One storm produced brief severe weather in the Statesville area.', 'FD reported trees blown down On West Front St.');
INSERT INTO public.stormevents_east VALUES (786347, 201809, 17, 1515, 201809, 17, 1515, 131419, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '17-SEP-18 15:15:00', 'EST-5', '17-SEP-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'HELENA', 2, 'E', 'HELENA', 36.32, -78.94, 36.32, -78.94, 'As remnants of Florence lifted north of the area, scattered thunderstorms developed during the afternoon due to strong differential heating within the pronounced mid-level dry slot, east of the center of the circulation. Two thunderstorms produced some scattered thunderstorm wind damage, along with some isolated flash flooding due to the  wet antecedent conditions.', 'Two trees blown down in the area.');
INSERT INTO public.stormevents_east VALUES (786348, 201809, 17, 1530, 201809, 17, 1530, 131419, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '17-SEP-18 15:30:00', 'EST-5', '17-SEP-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'ROUGEMONT', 1, 'SE', 'ROUGEMONT', 36.21, -78.92, 36.21, -78.92, 'As remnants of Florence lifted north of the area, scattered thunderstorms developed during the afternoon due to strong differential heating within the pronounced mid-level dry slot, east of the center of the circulation. Two thunderstorms produced some scattered thunderstorm wind damage, along with some isolated flash flooding due to the  wet antecedent conditions.', 'Several trees blown down south of Rougemont.');
INSERT INTO public.stormevents_east VALUES (800233, 201809, 27, 1855, 201809, 27, 1855, 133721, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '27-SEP-18 18:55:00', 'EST-5', '27-SEP-18 18:55:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 3, 'ENE', 'CARALEIGH', 3, 'ENE', 'CARALEIGH', 35.77, -78.64, 35.77, -78.64, 'Isolated severe storms developed ahead of a cold front during the late afternoon in a moist and unstable air mass. A more organized comma head and trailing line of storms moved into the area mid to late evening. Some of the storms produced wind damage across portions of the area.', 'Trees were reported down on power lines near South Wilmington Street.');
INSERT INTO public.stormevents_east VALUES (800234, 201809, 27, 1927, 201809, 27, 1927, 133721, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '27-SEP-18 19:27:00', 'EST-5', '27-SEP-18 19:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ESE', 'SPRING HOPE', 1, 'ESE', 'SPRING HOPE', 35.9481, -78.1085, 35.9481, -78.1085, 'Isolated severe storms developed ahead of a cold front during the late afternoon in a moist and unstable air mass. A more organized comma head and trailing line of storms moved into the area mid to late evening. Some of the storms produced wind damage across portions of the area.', 'One tree was reported down on Alternate Highway 64.');
INSERT INTO public.stormevents_east VALUES (800235, 201809, 27, 1929, 201809, 27, 1929, 133721, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '27-SEP-18 19:29:00', 'EST-5', '27-SEP-18 19:29:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 2, 'WNW', 'SPRING HOPE', 2, 'WNW', 'SPRING HOPE', 35.96, -78.15, 35.96, -78.15, 'Isolated severe storms developed ahead of a cold front during the late afternoon in a moist and unstable air mass. A more organized comma head and trailing line of storms moved into the area mid to late evening. Some of the storms produced wind damage across portions of the area.', 'Power lines were reported down due to damaging winds near Coker Creek.');
INSERT INTO public.stormevents_east VALUES (735502, 201801, 12, 837, 201801, 12, 1130, 122750, 'NEW YORK', 36, 2018, 'January', 'Flash Flood', 'BGM', '12-JAN-18 08:37:00', 'EST-5', '12-JAN-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'W', 'LEE CENTER', 1, 'ESE', 'LEE CENTER', 43.2983, -75.5333, 43.296, -75.4991, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Flash flooding was reported along Stokes-Lee Center Road near Lee Center. Water was rushing down the hill, flooding roads and basements of nearby structures.');
INSERT INTO public.stormevents_east VALUES (735504, 201801, 12, 812, 201801, 12, 1700, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 08:12:00', 'EST-5', '12-JAN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 3, 'NE', 'TYRE', 13, 'NE', 'LEHIGH VLY JCT', 43.0119, -76.7626, 43.0665, -76.5728, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam along the Seneca River was causing minor, lowland flooding from Montezuma to Weedsport.');
INSERT INTO public.stormevents_east VALUES (735503, 201801, 12, 735, 201801, 12, 1500, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 07:35:00', 'EST-5', '12-JAN-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 1, 'E', 'YORKVILLE', 1, 'SSW', 'YORKVILLE', 43.1186, -75.2657, 43.1105, -75.284, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam was reported on the Sauquoit Creek near Whitesboro. Minor flooding of low lands along the creek  was reported. Water threatened nearby structures, but no significant inundation occurred.');
INSERT INTO public.stormevents_east VALUES (735505, 201801, 12, 904, 201801, 12, 1300, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 09:04:00', 'EST-5', '12-JAN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'SW', 'AVA', 0, 'N', 'AVA', 43.4173, -75.4828, 43.4232, -75.48, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Minor flooding was reported on Route 26 along the Ava Brook in Ava, NY. Water was covering yards and nearing the first floor of a residence.');
INSERT INTO public.stormevents_east VALUES (735506, 201801, 12, 934, 201801, 12, 1300, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 09:34:00', 'EST-5', '12-JAN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NW', 'CAMDEN', 1, 'NNE', 'CAMDEN', 43.3359, -75.7601, 43.344, -75.7456, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Flooding along the West Branch Fish Creek was crossing Route 69 and blocking traffic throughout downtown Camden.');
INSERT INTO public.stormevents_east VALUES (734123, 201801, 12, 1840, 201801, 12, 1842, 122594, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'CHS', '12-JAN-18 18:40:00', 'EST-5', '12-JAN-18 18:42:00', 0, 0, 0, 0, NULL, '0.00K', 'Buoy', 45, 'MG', NULL, NULL, 0, 'NE', 'EDISTO BUOY (41004)', 0, 'NE', 'EDISTO BUOY (41004)', 32.501, -79.099, 32.501, -79.099, 'A large band of showers with embedded thunderstorms developed ahead of a cold front and moved eastward across the Atlantic coastal waters. One of the embedded thunderstorms produce strong wind gusts.', 'Buoy 41004 measured a 45 knot wind gust with a passing thunderstorm.');
INSERT INTO public.stormevents_east VALUES (735507, 201801, 12, 941, 201801, 12, 1300, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 09:41:00', 'EST-5', '12-JAN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 2, 'SSW', 'BOONVILLE', 1, 'NE', 'BOONVILLE', 43.4561, -75.3414, 43.4865, -75.3202, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Flooding along Mill Creek and Merry Hill Road was approximately 8 inches deep across both lanes of the roadway.');
INSERT INTO public.stormevents_east VALUES (735508, 201801, 12, 1012, 201801, 12, 1030, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 10:12:00', 'EST-5', '12-JAN-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'WESTERNVILLE', 1, 'SW', 'WESTERNVILLE', 43.32, -75.38, 43.3078, -75.397, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Water was flowing along portions of Route 46 in Westernville.');
INSERT INTO public.stormevents_east VALUES (735510, 201801, 12, 1045, 201801, 12, 1400, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 10:45:00', 'EST-5', '12-JAN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 0, 'N', 'KANONA', 1, 'ESE', 'KANONA', 42.38, -77.37, 42.3748, -77.345, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam was leading to significant low land flooding between Cohocton and Bath on the Cohocton River. One residence was surrounded by flood waters.');
INSERT INTO public.stormevents_east VALUES (735511, 201801, 12, 1046, 201801, 12, 1300, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 10:46:00', 'EST-5', '12-JAN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Ice Jam', NULL, 2, 'SE', 'ONEIDA', 0, 'NE', 'ONEIDA', 43.0811, -75.637, 43.1032, -75.6647, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Minor, low land flooding was occurring along Oneida Creek due to an ice jam.  A vehicle was stuck, and filling with water.');
INSERT INTO public.stormevents_east VALUES (735512, 201801, 12, 1200, 201801, 12, 1500, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 12:00:00', 'EST-5', '12-JAN-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Ice Jam', NULL, 1, 'NE', 'DELHI', 1, 'SSW', 'DELHI', 42.2879, -74.9063, 42.2697, -74.9245, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam was reported on the West Branch Delaware River behind the county courthouse. Minor flooding of low lands along the river occurred, but no significant impacts.');
INSERT INTO public.stormevents_east VALUES (783345, 201808, 29, 955, 201808, 29, 955, 130928, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 09:55:00', 'EST-5', '29-AUG-18 09:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'Isolated gale-force wind gusts were observed in association with scattered thunderstorms offshore the upper Florida Keys, as a weak cyclonic perturbation moved west through the eastern Straits of Florida.', 'A wind gust of 34 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
INSERT INTO public.stormevents_east VALUES (765072, 201808, 13, 550, 201808, 13, 600, 127599, 'NEW JERSEY', 34, 2018, 'August', 'Funnel Cloud', 'PHI', '13-AUG-18 05:50:00', 'EST-5', '13-AUG-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 3, 'E', 'SHIP BOTTOM', 2, 'E', 'SHIP BOTTOM', 39.63, -74.13, 39.6332, -74.1358, 'Two separate reports of waterspouts just offshore during the flash flooding event.', 'Several pictures and videos shared on social media show a well defined waterspout over a couple miles offshore from Ship Bottom just before 7am EDT. Time and location estimated from weak rotation on radar. No damage or injuries were reported.');
INSERT INTO public.stormevents_east VALUES (767201, 201808, 17, 1711, 201808, 17, 1711, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:11:00', 'EST-5', '17-AUG-18 17:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'NE', 'WIND GAP', 1, 'NE', 'WIND GAP', 40.86, -75.29, 40.86, -75.29, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Power lines down on Broadway Street between the Monroe County line and Route 33 north. All lanes closed. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (768218, 201808, 8, 1858, 201808, 8, 1858, 128103, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 18:58:00', 'EST-5', '08-AUG-18 18:58:00', 0, 0, 0, 0, '0.20K', NULL, 'Public', 50, 'EG', NULL, NULL, 0, 'NNW', 'TAGGART', 0, 'NNW', 'TAGGART', 37.7216, -78.4305, 37.7216, -78.4305, 'A hot and humid air mass sparked scattered severe thunderstorms during the afternoon.  These storms blew down multiple trees and power lines in southwest Virginia.  Two homes suffered damage in the city of Danville due to a tree falling on each of them.', 'Thunderstorm winds blew down several large tree limbs five miles east-southeast of Centenary.');
INSERT INTO public.stormevents_east VALUES (769230, 201808, 13, 715, 201808, 13, 1130, 128247, 'DELAWARE', 10, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:15:00', 'EST-5', '13-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'BRANDYWINE SPGS', 1, 'W', 'SILVERBROOK', 39.7492, -75.6447, 39.751, -75.6271, 'Rainfall amounts of 1 to 2 inches fell in a short amount of time in northern Delaware on the morning of August 13.', 'Minor flooding occurred along the Red Clay Creek near Wooddale.');
INSERT INTO public.stormevents_east VALUES (780525, 201808, 9, 912, 201808, 9, 912, 130386, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '09-AUG-18 09:12:00', 'EST-5', '09-AUG-18 09:12:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'ROCK HARBOR', 1, 'S', 'ROCK HARBOR', 41.7906, -70.0023, 41.7906, -70.0023, 'A cold front moved across Massachusetts, bringing thunderstorms and downpours to Southeast Massachusetts and especially over Cape Cod.  Up to 4.5 inches of rain fell on Cape Cod during the morning and early afternoon.', 'At 9:12 AM EST, thunderstorm winds toppled numerous trees and wires on U.S. Route 6 between exit 12 and the Orleans rotary.');
INSERT INTO public.stormevents_east VALUES (780608, 201808, 11, 1803, 201808, 11, 2100, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '11-AUG-18 18:03:00', 'EST-5', '11-AUG-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'WEST BOYLSTON', 1, 'W', 'WEST BOYLSTON', 42.3745, -71.7908, 42.3718, -71.7973, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 6:03 PM EST, Crescent Street was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (781067, 201808, 9, 1504, 201808, 9, 1504, 130489, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'JAX', '09-AUG-18 15:04:00', 'EST-5', '09-AUG-18 15:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 39, 'MG', NULL, NULL, 4, 'W', 'BEVERLY BEACH', 4, 'W', 'BEVERLY BEACH', 29.61, -81.2, 29.61, -81.2, 'Increasing SW steering flow and moisture fueled scattered sea breeze storms. Boundary collisions near the east coast sea breeze front triggered stronger storm growth in the afternoon and early evening as activity moved offshore.', 'Gusts of 40-45 mph were reported across the eastern tier of the county.');
INSERT INTO public.stormevents_east VALUES (781565, 201808, 8, 1709, 201808, 8, 1709, 130568, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'OKX', '08-AUG-18 17:09:00', 'EST-5', '08-AUG-18 17:09:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 1, 'SE', 'BOTSFORD', 1, 'SE', 'BOTSFORD', 41.36, -73.26, 41.36, -73.26, 'A surface trough in a very warm and humid airmass triggered thunderstorms across the region.', 'A Tree down on wires on Swamp Road in Newtown, CT.');
INSERT INTO public.stormevents_east VALUES (781772, 201808, 8, 1743, 201808, 8, 1743, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 17:43:00', 'EST-5', '08-AUG-18 17:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'TERRELLS', 1, 'WSW', 'TERRELLS', 35.8141, -79.2533, 35.8141, -79.2533, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One down tree was blocking the intersection at NC Highway 87 and Chicken Bridge Road.');
INSERT INTO public.stormevents_east VALUES (781781, 201808, 7, 1640, 201808, 7, 1640, 130613, 'MASSACHUSETTS', 25, 2018, 'August', 'Lightning', 'ALY', '07-AUG-18 16:40:00', 'EST-5', '07-AUG-18 16:40:00', 0, 0, 0, 0, '1.00K', NULL, 'Amateur Radio', NULL, NULL, NULL, NULL, 1, 'NE', 'RICHMOND FURNACE', 1, 'NE', 'RICHMOND FURNACE', 42.38, -73.37, 42.38, -73.37, 'Scattered showers and thunderstorms developed within a humid, warm airmass across western Massachusetts. Some of these storms became severe, resulting in numerous trees and wires down.', 'Lightning caused a propane tank fire.');
INSERT INTO public.stormevents_east VALUES (781785, 201808, 7, 1715, 201808, 7, 1715, 130613, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'ALY', '07-AUG-18 17:15:00', 'EST-5', '07-AUG-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'E', 'MONTEREY', 1, 'E', 'MONTEREY', 42.18, -73.21, 42.18, -73.21, 'Scattered showers and thunderstorms developed within a humid, warm airmass across western Massachusetts. Some of these storms became severe, resulting in numerous trees and wires down.', 'A tree was downed onto a car along Main Road.');
INSERT INTO public.stormevents_east VALUES (782128, 201808, 18, 1512, 201808, 18, 1512, 130697, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '18-AUG-18 15:12:00', 'EST-5', '18-AUG-18 15:12:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'N', 'KINGS MTN', 4, 'N', 'KINGS MTN', 35.302, -81.36, 35.302, -81.36, 'Isolated to widely scattered thunderstorms developed across western North Carolina during the afternoon and evening. Several storms organized into a small cluster and produced brief damaging winds in Cleveland County.', 'County comms reported two trees blown down near the intersection of County Line Road And St Luke Church Rd.');
INSERT INTO public.stormevents_east VALUES (782134, 201808, 21, 1637, 201808, 21, 1637, 130705, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '21-AUG-18 16:37:00', 'EST-5', '21-AUG-18 16:37:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NE', 'TOXAWAY', 2, 'NE', 'TOXAWAY', 34.52, -82.602, 34.52, -82.602, 'A cluster of thunderstorms moved across Upstate South Carolina during the late afternoon and evening. Brief damaging winds were reported near Anderson.', 'County comms reported a tree blown down on power lines at the intersection of Snow Rd and Amber Dr and another tree down at Highways 252 and 76.');
INSERT INTO public.stormevents_east VALUES (782145, 201808, 12, 1834, 201808, 12, 1834, 130709, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'AKQ', '12-AUG-18 18:34:00', 'EST-5', '12-AUG-18 18:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'DELTAVILLE', 0, 'N', 'DELTAVILLE', 37.56, -76.29, 37.56, -76.29, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 36 knots was measured at Deltaville.');
INSERT INTO public.stormevents_east VALUES (769331, 201808, 25, 1620, 201808, 25, 1620, 128210, 'FLORIDA', 12, 2018, 'August', 'Lightning', 'TBW', '25-AUG-18 16:20:00', 'EST-5', '25-AUG-18 16:20:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 2, 'E', 'SEMINOLE', 2, 'E', 'SEMINOLE', 27.8335, -82.7401, 27.8335, -82.7401, 'Easterly flow allowed scattered to numerous thunderstorms to develop over the Florida Peninsula and push west into the eastern Gulf of Mexico during the afternoon and early evening. One of these storms caused damaging wind gusts. Lightning strikes from other storms caused multiple structure fires.', 'A fire at a home was suspected to have been caused by a lightning strike. The time of the lightning strike was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (776990, 201807, 23, 2000, 201807, 23, 2100, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flood', 'CTP', '23-JUL-18 20:00:00', 'EST-5', '23-JUL-18 21:00:00', 0, 0, 1, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 3, 'SE', 'DEODATE', 3, 'SSE', 'DEODATE', 40.1944, -76.5847, 40.1876, -76.585, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'At 9pm, A 19 year old female attempted to swim across Conewago Creek with her 22 year old relative.  She was unable to cross the creek due to the fast current and was swept away.   She was found downstream several days later deceased.');
INSERT INTO public.stormevents_east VALUES (776992, 201807, 23, 500, 201807, 27, 500, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flood', 'CTP', '23-JUL-18 05:00:00', 'EST-5', '27-JUL-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'SYNER', 3, 'NW', 'SYNER', 40.3417, -76.6283, 40.3726, -76.624, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Widespread flooding along Swatara Creek.');
INSERT INTO public.stormevents_east VALUES (737400, 201801, 12, 2032, 201801, 12, 2034, 122972, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'ILM', '12-JAN-18 20:32:00', 'EST-5', '12-JAN-18 20:34:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 2, 'NW', 'SHEEPSHEAD ROCK', 2, 'NW', 'SHEEPSHEAD ROCK', 33.96, -77.94, 33.96, -77.94, 'A trough ahead of a strong cold front produced strong winds along and off the coast of North Carolina.', 'A 44 mph gust was recorded at Federal Point.');
INSERT INTO public.stormevents_east VALUES (727844, 201801, 22, 2323, 201801, 22, 2325, 121610, 'OHIO', 39, 2018, 'January', 'Thunderstorm Wind', 'ILN', '22-JAN-18 23:23:00', 'EST-5', '22-JAN-18 23:25:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'FLEATOWN', 0, 'N', 'FLEATOWN', 40, -82.67, 40, -82.67, 'Showers and thunderstorms developed ahead of an approaching cold front. The storms moved east across the area through the evening hours, producing damaging winds and large hail.', 'Several trees were downed.');
INSERT INTO public.stormevents_east VALUES (727902, 201801, 22, 2343, 201801, 22, 2345, 121610, 'OHIO', 39, 2018, 'January', 'Thunderstorm Wind', 'ILN', '22-JAN-18 23:43:00', 'EST-5', '22-JAN-18 23:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 0, 'N', 'ST LOUISVILLE', 0, 'N', 'ST LOUISVILLE', 40.17, -82.42, 40.17, -82.42, 'Showers and thunderstorms developed ahead of an approaching cold front. The storms moved east across the area through the evening hours, producing damaging winds and large hail.', 'A couple of trees were downed across northeast Licking County.');
INSERT INTO public.stormevents_east VALUES (727959, 201801, 22, 2335, 201801, 22, 2337, 121610, 'OHIO', 39, 2018, 'January', 'Thunderstorm Wind', 'ILN', '22-JAN-18 23:35:00', 'EST-5', '22-JAN-18 23:37:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'SSW', 'UTICA', 2, 'SSW', 'UTICA', 40.2, -82.47, 40.2, -82.47, 'Showers and thunderstorms developed ahead of an approaching cold front. The storms moved east across the area through the evening hours, producing damaging winds and large hail.', 'A roof was torn off of a barn and there was damage to some playground equipment. A tree was also uprooted.');
INSERT INTO public.stormevents_east VALUES (727845, 201801, 22, 2325, 201801, 22, 2326, 121610, 'OHIO', 39, 2018, 'January', 'Thunderstorm Wind', 'ILN', '22-JAN-18 23:25:00', 'EST-5', '22-JAN-18 23:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 50, 'MG', NULL, NULL, 1, 'NW', 'LNCSTER FRFLD CO ARP', 1, 'NW', 'LNCSTER FRFLD CO ARP', 39.76, -82.66, 39.76, -82.66, 'Showers and thunderstorms developed ahead of an approaching cold front. The storms moved east across the area through the evening hours, producing damaging winds and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (737372, 201801, 13, 47, 201801, 13, 746, 122966, 'NEW HAMPSHIRE', 33, 2018, 'January', 'Flood', 'GYX', '13-JAN-18 00:47:00', 'EST-5', '13-JAN-18 07:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'WOODSTOCK', 1, 'NE', 'WOODSTOCK', 43.9866, -71.6809, 43.9919, -71.6594, 'Unusually warm weather combined with 1 to 3 inches of rainfall to produce ice jams on numerous rivers across New Hampshire.', 'Snow melt and heavy rain combined to produce ice jams and flooding on the Pemigewasset River at Woodstock (flood stage 9.0 ft), which crested at 9.8 ft.');
INSERT INTO public.stormevents_east VALUES (737969, 201801, 12, 306, 201801, 12, 1600, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 03:06:00', 'EST-5', '12-JAN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NW', 'STRABANE', 1, 'N', 'CANONSBURG', 40.26, -80.19, 40.2587, -80.2022, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Local law enforcement reported roads closed due to flooding including the 400 block of Western Ave from Chartiers Creek. In addition, local media reported that Linden Creek Road and Washington Road were closed due to Linden Creek being out of its banks.');
INSERT INTO public.stormevents_east VALUES (737970, 201801, 12, 306, 201801, 12, 1400, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 03:06:00', 'EST-5', '12-JAN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'NE', 'VENICE', 1, 'WNW', 'BISHOP', 40.324, -80.2242, 40.3246, -80.2102, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Local law enforcement reported roads closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (733199, 201801, 12, 300, 201801, 13, 2300, 121771, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BTV', '12-JAN-18 03:00:00', 'EST-5', '13-JAN-18 23:00:00', 0, 0, 0, 0, '150.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 1, 'W', 'FT COVINGTON', 1, 'WNW', 'FT COVINGTON', 44.9815, -74.4943, 44.9884, -74.4897, 'A very deep upper level trough from Central Canada to the Gulf of Mexico allowed for a warm, moist flow with temperatures in the 50s and 60s through midday on January 12th. By late afternoon, an arctic front moved into the St. Lawrence Valley, with temperatures plummeting into the 20s by evening and single digits by Saturday morning (1/13). In addition low pressure traveled along the front as it moved across Vermont delivering an inch or more of precipitation in the form of rain, freezing rain, sleet and snow. ||Several impacts occurred with this event. First, temperatures 25 to 30 degrees above normal caused significant snow melt across the region and then an half inch or more of rainfall in January 12th both lead to some ice jams and localized flooding, especially along the Little Salmon in Fort Covington where dozens of residents were flooded and evacuated as well as the AuSable River in Essex county.||Second, rapidly falling temperatures accounted for rain changing to freezing rain, sleet then snow. Snow was more prevalent in the St. Lawrence Valley and northern Adirondacks with significant sleet in the Champlain Valley. Sharply falling temperatures allowed for a flash freeze of area roads making for extremely hazardous travel.||Third, the combination of earlier thawing and sub-zero temperatures allowed for freeze-up jams to develop with some major flooding in the Underwood trailer park along the Saranac River in Plattsburgh.', 'A large ice jam formed on the Salmon River in Fort Covington, NY and extended for several miles from the Route 37 bridge crossing north to near the international border. Up to 17 homes and 37 people were evacuated. Some damage to residences was reported.');
INSERT INTO public.stormevents_east VALUES (735805, 201801, 13, 900, 201801, 20, 1100, 122813, 'CONNECTICUT', 9, 2018, 'January', 'Flood', 'ALY', '13-JAN-18 09:00:00', 'EST-5', '20-JAN-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Ice Jam', NULL, 1, 'NNW', 'BULLS BRIDGE', 1, 'W', 'KENT FURNACE', 41.6838, -73.5118, 41.7309, -73.485, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western New England on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to three inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and a few residences had to be evacuated. After the strong cold front passed, many ice jams and their associated flooding froze back in place, resulting in road closures continuing for several days in some areas.', 'Two ice jams on the Housatonic River spanning a mile caused flooding in Kent beginning on the morning of January 13th. The flood waters first went over Skiff Mountain Road and into the Kent School campus. The waters surrounded parked cars and an indoor ice rink on the campus. Students were sent home as flood waters rendered the campus inaccessible. Waters continued to rise during the afternoon, surrounding houses and necessitating technical rescues of residents on Johnson Road and South Main Street. A total of 12 people in four homes were evacuated. US Route 7, the main north-south route through Kent, was closed between Bulls Bridge Road and Route 341. Schaghticoke Road and River Road were also closed due to flooding. Frigid temperatures resulted in the jam and associated flooding freezing in place, extending the road closures for around a week. A state of emergency was declared for the Town of Kent.');
INSERT INTO public.stormevents_east VALUES (735812, 201801, 13, 1100, 201801, 14, 1100, 122813, 'CONNECTICUT', 9, 2018, 'January', 'Flood', 'ALY', '13-JAN-18 11:00:00', 'EST-5', '14-JAN-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Local Official', NULL, NULL, 'Ice Jam', NULL, 1, 'SW', 'CLAYTON', 1, 'SW', 'CLAYTON', 42.0368, -73.2977, 42.0401, -73.2926, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western New England on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to three inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and a few residences had to be evacuated. After the strong cold front passed, many ice jams and their associated flooding froze back in place, resulting in road closures continuing for several days in some areas.', 'Sodom Road was closed between Allyndale Road and Old Turnpike Road due to encroaching water and ice.');
INSERT INTO public.stormevents_east VALUES (749423, 201806, 8, 1748, 201806, 8, 1748, 124949, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MLB', '08-JUN-18 17:48:00', 'EST-5', '08-JUN-18 17:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 54, 'MG', NULL, NULL, 1, 'NW', '(COF)PATRICK AFB', 1, 'NW', '(COF)PATRICK AFB', 28.24, -80.61, 28.24, -80.61, 'The combination of a cutoff upper-level low over the Florida panhandle and northeast Gulf of Mexico, and the Atlantic ridge axis over the Florida Straits and the northern Bahamas generated deep southwest flow across central Florida. Despite early day showers and storms, clouds cleared during the afternoon allowing daytime heating to occur. Both the east coast and west coast sea breezes developed, with the west coast being more progressive due to southwest winds. As the two collided over eastern Orange and Osceola counties, numerous thunderstorms formed along a line from Orlando south to Lake Okeechobee. As the line of storms pushed east into Brevard County, several reports of severe wind gusts were received from the Cape south across the intracoastal waters of central Brevard County.', 'The AWOS at Patrick Air Force Base, KCOF, measured a peak wind gust of 62 mph or 54 knots from the west.');
INSERT INTO public.stormevents_east VALUES (737399, 201801, 12, 2040, 201801, 12, 2042, 122972, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'ILM', '12-JAN-18 20:40:00', 'EST-5', '12-JAN-18 20:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 54, 'MG', NULL, NULL, 34, 'SSW', 'WR4', 34, 'SSW', 'WR4', 33.44, -77.74, 33.44, -77.74, 'A trough ahead of a strong cold front produced strong winds along and off the coast of North Carolina.', 'A 62 mph gust was recorded at the Frying Pan Shoals buoy.');
INSERT INTO public.stormevents_east VALUES (737841, 201801, 23, 1338, 201801, 23, 1338, 123067, 'NEW YORK', 36, 2018, 'January', 'Thunderstorm Wind', 'BUF', '23-JAN-18 13:38:00', 'EST-5', '23-JAN-18 13:38:00', 2, 0, 0, 0, '40.00K', '0.00K', 'Emergency Manager', 43, 'EG', NULL, NULL, 2, 'NE', 'PRE EMPTION', 2, 'NE', 'PRE EMPTION', 42.8988, -76.9773, 42.8988, -76.9773, 'A cold front crossed the region during the early afternoon hours. A rather ill-defined line of convection developed along this front. In Geneva, a building under construction collapse with six people inside. Two were injured. The building which was 60��� by 150��� was framed in with a completed roof. Witnesses said the wind lifted and shifted the building, which then fell to the ground and collapsed.', 'A 62 year-old male and a 35 year-old-male had to be rescued from the collapsed structure.');
INSERT INTO public.stormevents_east VALUES (737974, 201801, 12, 439, 201801, 12, 1430, 122450, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 04:39:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'CAMERON', 0, 'SSE', 'CAMERON', 39.83, -80.57, 39.8245, -80.5675, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported a couple of houses flooded in Cameron. Several other roads are flooded throughout the county.');
INSERT INTO public.stormevents_east VALUES (737971, 201801, 12, 429, 201801, 12, 1430, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 04:29:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'N', 'MC DONALD', 1, 'NE', 'MC DONALD', 40.3787, -80.2309, 40.3789, -80.2202, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Local law enforcement reported Millers Run road and Reed Street closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (737973, 201801, 12, 729, 201801, 12, 1430, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 07:29:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'E', 'COAL BLUFF', 1, 'ESE', 'COAL BLUFF', 40.25, -79.96, 40.2438, -79.9506, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'State official reported that a person was rescued on Finleyville Elrama Road in Union Township.');
INSERT INTO public.stormevents_east VALUES (735816, 201801, 12, 1650, 201801, 12, 1905, 122818, 'VERMONT', 50, 2018, 'January', 'Flash Flood', 'ALY', '12-JAN-18 16:50:00', 'EST-5', '12-JAN-18 19:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Ice Jam', NULL, 2, 'ESE', 'BROOKLINE', 2, 'ESE', 'BROOKLINE', 43.0176, -72.5562, 43.0162, -72.5581, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western New England on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to two inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and a trailer park experienced flooding.', 'Water was reported over Brook Road.');
INSERT INTO public.stormevents_east VALUES (735818, 201801, 12, 1630, 201801, 12, 1905, 122818, 'VERMONT', 50, 2018, 'January', 'Flash Flood', 'ALY', '12-JAN-18 16:30:00', 'EST-5', '12-JAN-18 19:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 1, 'W', 'EAST JAMAICA', 1, 'WNW', 'EAST JAMAICA', 43.0836, -72.756, 43.0843, -72.7542, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western New England on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to two inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and a trailer park experienced flooding.', 'The West River overflowed its banks, flooding River Road and a trailer park in the town of Jamaica.');
INSERT INTO public.stormevents_east VALUES (735821, 201801, 12, 1650, 201801, 12, 1905, 122818, 'VERMONT', 50, 2018, 'January', 'Flash Flood', 'ALY', '12-JAN-18 16:50:00', 'EST-5', '12-JAN-18 19:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Ice Jam', NULL, 3, 'W', 'JAMAICA', 3, 'W', 'JAMAICA', 43.1015, -72.8479, 43.0965, -72.8475, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western New England on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to two inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and a trailer park experienced flooding.', 'Water was over Pikes Falls Road in Jamaica.');
INSERT INTO public.stormevents_east VALUES (735829, 201801, 12, 1300, 201801, 12, 1855, 122820, 'MASSACHUSETTS', 25, 2018, 'January', 'Flash Flood', 'ALY', '12-JAN-18 13:00:00', 'EST-5', '12-JAN-18 18:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'ESE', 'DRURY', 1, 'SE', 'DRURY', 42.6428, -72.9832, 42.6345, -72.9853, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western Massachusetts on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to three inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and some residences experienced basement flooding.', 'Two mudslides resulted in the closure of the eastbound lanes of Route 2.');
INSERT INTO public.stormevents_east VALUES (735790, 201801, 13, 300, 201801, 24, 1800, 122794, 'NEW YORK', 36, 2018, 'January', 'Flood', 'ALY', '13-JAN-18 03:00:00', 'EST-5', '24-JAN-18 18:00:00', 0, 0, 0, 0, '1.00M', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 2, 'WNW', 'WARRENSBURG', 1, 'NE', 'THE GLEN', 43.4903, -73.7858, 43.5913, -73.8516, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into New York on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to three inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and a water rescue had to be performed near the Hoosic River in Rensselaer County. After the strong cold front passed, many ice jams and their associated flooding froze back in place, resulting in road closures continuing for several days in some areas.', 'Flooding occurred along the Hudson River between Warrensburg and The Glen due to an ice jam. People were stranded in houses on Glen Creek Road and one family was evacuated. The water eroded a portion of River Road in the town of Thurman and flooded the Glen Hudson campsite, prompting an evacuation of the owners. The water and ice also spread onto Cronin''s Golf Course. To the south, water and ice flowed over the Route 418 bridge, resulting in an extended closure for the better part of 12 days. Stony Creek Road was also flooded near Cameron Road.');
INSERT INTO public.stormevents_east VALUES (737975, 201801, 12, 519, 201801, 12, 1430, 122450, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 05:19:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'ENE', 'WHEELING', 1, 'NW', 'BETHLEHEM', 40.08, -80.7, 40.064, -80.6954, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported roads closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (737977, 201801, 12, 637, 201801, 12, 1430, 122450, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 06:37:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'W', 'WEIRTON ARPT', 0, 'ENE', 'WEIRTON', 40.4, -80.55, 40.4023, -80.5713, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Trained spotter reported that Kings Creek was out of its banks and flooding the intersection of Kings Creek Road and Martina Drive. Also flooding is occuring on Willow Road and Union Chapel.');
INSERT INTO public.stormevents_east VALUES (735832, 201801, 12, 1230, 201801, 12, 1335, 122820, 'MASSACHUSETTS', 25, 2018, 'January', 'Flash Flood', 'ALY', '12-JAN-18 12:30:00', 'EST-5', '12-JAN-18 13:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Ice Jam', NULL, 1, 'S', 'CHESHIRE', 1, 'SSE', 'CHESHIRE', 42.5606, -73.1693, 42.56, -73.1664, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western Massachusetts on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to three inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and some residences experienced basement flooding.', 'An ice jam broke loose along Kitchen Brook, which overflowed its banks and covered a section of Route 8 with large chunks of ice. Flood waters flowed into a nearby parking lot, covering it in around a foot of water. Route 8 remained closed for around an hour.');
INSERT INTO public.stormevents_east VALUES (735833, 201801, 12, 1230, 201801, 12, 1855, 122820, 'MASSACHUSETTS', 25, 2018, 'January', 'Flash Flood', 'ALY', '12-JAN-18 12:30:00', 'EST-5', '12-JAN-18 18:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Ice Jam', NULL, 1, 'NNW', 'RENFREW', 1, 'NNW', 'RENFREW', 42.64, -73.1077, 42.6392, -73.1076, 'After a frigid end of December and beginning of January, an unseasonably warm airmass was pumped into western Massachusetts on January 12th on southerly winds. The temperatures reached the 50s and 60s during the day. Showers also developed in the warm airmass ahead of a cold front and were heavy at times, with some locations receiving one to three inches of rainfall. The combination of warm temperatures and heavy rainfall caused river ice to dislodge and resulted in ice jams in spots. Flooding occurred due to a combination of ice jam movement and heavy rainfall. Several roads were closed or damaged and some residences experienced basement flooding.', 'One lane of Lime Street was closed due to flooding along the Southwick Brook.');
INSERT INTO public.stormevents_east VALUES (736205, 201801, 12, 1657, 201801, 12, 1657, 122863, 'VIRGINIA', 51, 2018, 'January', 'Thunderstorm Wind', 'LWX', '12-JAN-18 16:57:00', 'EST-5', '12-JAN-18 16:57:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'SSE', 'RUCKERSVILLE', 2, 'SSE', 'RUCKERSVILLE', 38.2, -78.36, 38.2, -78.36, 'A strong cold front passed through on the 12th. Despite limited instability, there was enough forcing for showers to develop along the cold front. These showers were able to mix down some of the very strong winds from aloft.', 'A medium sized oak tree was uprooted.');
INSERT INTO public.stormevents_east VALUES (737978, 201801, 12, 725, 201801, 12, 1430, 122450, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 07:25:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 2, 'NNW', 'BETHANY', 1, 'NNE', 'BETHANY', 40.2196, -80.5669, 40.212, -80.5408, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported that Buffalo Creek was flooding portions of Bethany.');
INSERT INTO public.stormevents_east VALUES (737979, 201801, 12, 315, 201801, 12, 1400, 122447, 'OHIO', 39, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 03:15:00', 'EST-5', '12-JAN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'W', 'CAMERON', 1, 'SSE', 'CAMERON', 39.77, -80.94, 39.7547, -80.926, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported that both lanes of State Route 78 were flooded.');
INSERT INTO public.stormevents_east VALUES (737367, 201801, 12, 2145, 201801, 12, 2236, 122966, 'NEW HAMPSHIRE', 33, 2018, 'January', 'Flood', 'GYX', '12-JAN-18 21:45:00', 'EST-5', '12-JAN-18 22:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'WNW', 'PETERBOROUGH', 1, 'S', 'NOONE', 42.874, -71.9393, 42.8557, -71.9509, 'Unusually warm weather combined with 1 to 3 inches of rainfall to produce ice jams on numerous rivers across New Hampshire.', 'Snow melt and heavy rain produced brief minor flooding on the Contoocook River (flood stage 5.5 ft), which crested at 5.88 ft.');
INSERT INTO public.stormevents_east VALUES (736884, 201801, 12, 800, 201801, 12, 1900, 121827, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'CTP', '12-JAN-18 08:00:00', 'EST-5', '12-JAN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Ice Jam', NULL, 1, 'SE', 'DEGOLIA', 1, 'NNE', 'HOWARD', 41.91, -78.66, 41.894, -78.6195, 'A strong cold front crossed central Pennsylvania during the evening of January 12, 2018. The front was preceded by near-record warmth, and accompanied by showers and gusty thunderstorms. Temperatures dropped quickly behind the front, with precipitation changing over to a wintry mix and eventually snow.  Several ice jams were reported over northern Pennsylvania.', 'Ice jam reported on Minard Run Road.  One house and one vehicle was flooded.');
INSERT INTO public.stormevents_east VALUES (736260, 201801, 13, 1145, 201801, 18, 1406, 122874, 'MAINE', 23, 2018, 'January', 'Flood', 'GYX', '13-JAN-18 11:45:00', 'EST-5', '18-JAN-18 14:06:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Official NWS Observations', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'E', '(AUG)AUGUSTA STATE A', 1, 'W', 'HALLOWELL', 44.3177, -69.7826, 44.278, -69.8005, 'Unusually warm temperatures combined with 1 to 3 inches of rain causing ice jams to form on the Kennebec River. Several cars were damaged in a parking lot in Hallowell.', 'Very warm temperatures combined with 1 to 3 inches of rain to produce ice jams and flooding on the Kennebec River in Augusta (flood stage 12.0 ft), which crested at 19.58 ft. Several cars were damaged in Hallowell.');
INSERT INTO public.stormevents_east VALUES (736263, 201801, 13, 2012, 201801, 14, 200, 122874, 'MAINE', 23, 2018, 'January', 'Flood', 'GYX', '13-JAN-18 20:12:00', 'EST-5', '14-JAN-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'NORTH SIDNEY', 1, 'S', 'NORTH SIDNEY', 44.47, -69.68, 44.462, -69.6801, 'Unusually warm temperatures combined with 1 to 3 inches of rain causing ice jams to form on the Kennebec River. Several cars were damaged in a parking lot in Hallowell.', 'Very warm temperatures combined with 1 to 3 inches of rain to produce ice jams on the Kennebec River at North Sidney (flood Stage 17.0 ft), which crested at 17.38 ft.');
INSERT INTO public.stormevents_east VALUES (737365, 201801, 12, 1935, 201801, 12, 2035, 122966, 'NEW HAMPSHIRE', 33, 2018, 'January', 'Flood', 'GYX', '12-JAN-18 19:35:00', 'EST-5', '12-JAN-18 20:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'MILFORD', 1, 'W', 'MILFORD', 42.83, -71.63, 42.8321, -71.645, 'Unusually warm weather combined with 1 to 3 inches of rainfall to produce ice jams on numerous rivers across New Hampshire.', 'Snow melt and heavy rain produced ice jams and brief minor flooding on the Souhegan River (flood stage 9.0 ft), which crested at 9.38 ft.');
INSERT INTO public.stormevents_east VALUES (737384, 201801, 12, 2354, 201801, 14, 221, 122966, 'NEW HAMPSHIRE', 33, 2018, 'January', 'Flood', 'GYX', '12-JAN-18 23:54:00', 'EST-5', '14-JAN-18 02:21:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NNE', 'PLYMOUTH', 1, 'S', 'RIVERSIDE ARPT', 43.7674, -71.6925, 43.7372, -71.6811, 'Unusually warm weather combined with 1 to 3 inches of rainfall to produce ice jams on numerous rivers across New Hampshire.', 'Snow melt and heavy rain produced ice jams and flooding on the Pemigewasset River at Plymouth (flood stage 13.0 ft), which crested at 17.19 ft. Several buildings on Route 175A were flooded.');
INSERT INTO public.stormevents_east VALUES (737981, 201801, 12, 320, 201801, 12, 1429, 122447, 'OHIO', 39, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 03:20:00', 'EST-5', '12-JAN-18 14:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'N', 'BARNESVILLE', 0, 'NNW', 'MENDRYSBURG', 40.0209, -81.1796, 40.0529, -81.1712, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported both lanes of State Route 800 flooded between mile markers 2 and 3.');
INSERT INTO public.stormevents_east VALUES (737982, 201801, 12, 323, 201801, 12, 1430, 122447, 'OHIO', 39, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 03:23:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'W', 'SOMERTON', 0, 'SSW', 'SOMERTON', 39.9, -81.14, 39.8998, -81.1302, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manger reported that Skinner-Grimes Road and Johnson Ridge Road were flooded.');
INSERT INTO public.stormevents_east VALUES (737370, 201801, 13, 100, 201801, 15, 0, 122966, 'NEW HAMPSHIRE', 33, 2018, 'January', 'Flood', 'GYX', '13-JAN-18 01:00:00', 'EST-5', '15-JAN-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'W', 'NORTH STRATFORD', 0, 'SW', 'NORTH STRATFORD', 44.7512, -71.6305, 44.7465, -71.6258, 'Unusually warm weather combined with 1 to 3 inches of rainfall to produce ice jams on numerous rivers across New Hampshire.', 'Snow melt and heavy rain produced ice jams and minor flooding on the Connecticut River at North Stratford (flood stage 13.0 ft), which crested at 14.84 ft.');
INSERT INTO public.stormevents_east VALUES (737368, 201801, 13, 841, 201801, 15, 107, 122966, 'NEW HAMPSHIRE', 33, 2018, 'January', 'Flood', 'GYX', '13-JAN-18 08:41:00', 'EST-5', '15-JAN-18 01:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'NORTH CHICHESTER', 1, 'S', 'KELLEYS CORNER', 43.25, -71.38, 43.2675, -71.3708, 'Unusually warm weather combined with 1 to 3 inches of rainfall to produce ice jams on numerous rivers across New Hampshire.', 'Snow melt and heavy rain combined to produce ice jams and minor flooding on the Suncook River (flood stage 7.0 ft), which crested at 8.46 ft.');
INSERT INTO public.stormevents_east VALUES (737614, 201801, 12, 616, 201801, 12, 1500, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 06:16:00', 'EST-5', '12-JAN-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'SSW', 'CRAIGSVILLE', 2, 'W', 'CRAIGSVILLE', 40.8396, -79.6539, 40.8455, -79.6912, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'State official reported that Yellow Dog Road was closed due to flooding. In addition, a water rescue was reported on Nichola Road with male trapped on roof of vehicle.');
INSERT INTO public.stormevents_east VALUES (737984, 201801, 12, 521, 201801, 12, 1430, 122447, 'OHIO', 39, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 05:21:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'S', 'CAPTINA IS', 1, 'SE', 'POWHATAN PT', 39.8652, -80.7976, 39.8586, -80.8047, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported that there was a water rescue as a car drove into a flooded roadway from Captina Creek.');
INSERT INTO public.stormevents_east VALUES (736581, 201801, 12, 1700, 201801, 12, 2130, 122905, 'NEW YORK', 36, 2018, 'January', 'Flood', 'OKX', '12-JAN-18 17:00:00', 'EST-5', '12-JAN-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 2, 'NNW', 'TALLMAN', 2, 'NNW', 'TALLMAN', 41.1418, -74.1162, 41.1406, -74.1153, 'Rain associated with an approaching cold front combined with near record high temperatures and continued snow melt to result in river flooding along the Mahwah River near Suffern, New York. After an average of 5-9 inches of snow the week before, rainfall totals across the region ranged from 1-3 inches.', 'The Mahwah River near Suffern New York exceeded its flood stage of 4.0 feet at 5:00pm EST on January 12th, crested at a height of 4.42 feet at 7:00pm EST, and fell back below flood stage at 9:30pm EST.');
INSERT INTO public.stormevents_east VALUES (737625, 201801, 23, 1335, 201801, 23, 1335, 123029, 'ATLANTIC NORTH', 88, 2018, 'January', 'Marine Thunderstorm Wind', 'OKX', '23-JAN-18 13:35:00', 'EST-5', '23-JAN-18 13:35:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 39, 'MG', NULL, NULL, 0, 'N', 'GREAT GULL ISLAND WXFLOW', 0, 'N', 'GREAT GULL ISLAND WXFLOW', 41.2, -72.12, 41.2, -72.12, 'A passing cold front triggered isolated strong thunderstorms over far eastern portions of eastern Long Island Sound.', 'A gust of 39 knots was measured at the Great Gull Island mesonet location.');
INSERT INTO public.stormevents_east VALUES (737626, 201801, 23, 1340, 201801, 23, 1340, 123029, 'ATLANTIC NORTH', 88, 2018, 'January', 'Marine Thunderstorm Wind', 'OKX', '23-JAN-18 13:40:00', 'EST-5', '23-JAN-18 13:40:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'STATION LDLC3', 0, 'N', 'STATION LDLC3', 41.31, -72.08, 41.31, -72.08, 'A passing cold front triggered isolated strong thunderstorms over far eastern portions of eastern Long Island Sound.', 'A gust of 39 knots was measured at Ledge Light.');
INSERT INTO public.stormevents_east VALUES (735330, 201801, 13, 800, 201801, 13, 1030, 122742, 'MAINE', 23, 2018, 'January', 'Flood', 'CAR', '13-JAN-18 08:00:00', 'EST-5', '13-JAN-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 2, 'WSW', 'WALTHAM', 15, 'NNE', 'TUNK LAKE', 44.7108, -68.3636, 44.7393, -67.953, 'A warm front lifted across the region through the overnight hours of the 11th into the 12th bringing unusually warm air. A slow moving Arctic cold front then settled across the region through the night of the 12th into the 13th while low pressure tracked along the front. Precipitation began in the form of rain in advance of the Arctic front. The rain transitioned to snow...sleet and freezing rain across northern areas through the evening of the 12th into the early morning hours of the 13th. Storm total sleet accumulations across northern Aroostook county ranged from 1 to 2 inches along with between a tenth and two tenths of an inch of freezing rain. Snow accumulations of 4 to 6 inches occurred across northwest Aroostook county...with 1 to 3 inches across northeast areas. Warning criteria sleet accumulations occurred during the morning of the 13th.|Record high temperatures and record daily rainfall occurred across portions of Downeast Maine in the warm sector of the storm. Storm total rainfall across Downeast Maine ranged from 2.00 to 3.00 inches...with local totals up to around 4.00 inches...from the 12th into the 13th. The warm temperatures and rain also contributed to rapidly melting snow. Several roads were flooded and damaged. In Washington county...Route 191 in East Machias was damaged. In Hancock county flooding and road damage was reported on Norway Drive in Bar Harbor...Molasses Pond Road in Eastbrook and Torrey Brook Road on Deer Isle.', 'Flooding was reported on Molasses Pond Road near Eastbrook. Water was also reported over Norway Drive in Bar Harbor with damage to the road. Flooding and road damage was also reported on Torrey Brook Lane on Deer Isle.');
INSERT INTO public.stormevents_east VALUES (735331, 201801, 13, 800, 201801, 13, 1030, 122742, 'MAINE', 23, 2018, 'January', 'Flood', 'CAR', '13-JAN-18 08:00:00', 'EST-5', '13-JAN-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 5, 'SW', 'AYERS', 3, 'SSW', 'WHITING', 44.9424, -67.3093, 44.7413, -67.2008, 'A warm front lifted across the region through the overnight hours of the 11th into the 12th bringing unusually warm air. A slow moving Arctic cold front then settled across the region through the night of the 12th into the 13th while low pressure tracked along the front. Precipitation began in the form of rain in advance of the Arctic front. The rain transitioned to snow...sleet and freezing rain across northern areas through the evening of the 12th into the early morning hours of the 13th. Storm total sleet accumulations across northern Aroostook county ranged from 1 to 2 inches along with between a tenth and two tenths of an inch of freezing rain. Snow accumulations of 4 to 6 inches occurred across northwest Aroostook county...with 1 to 3 inches across northeast areas. Warning criteria sleet accumulations occurred during the morning of the 13th.|Record high temperatures and record daily rainfall occurred across portions of Downeast Maine in the warm sector of the storm. Storm total rainfall across Downeast Maine ranged from 2.00 to 3.00 inches...with local totals up to around 4.00 inches...from the 12th into the 13th. The warm temperatures and rain also contributed to rapidly melting snow. Several roads were flooded and damaged. In Washington county...Route 191 in East Machias was damaged. In Hancock county flooding and road damage was reported on Norway Drive in Bar Harbor...Molasses Pond Road in Eastbrook and Torrey Brook Road on Deer Isle.', 'Flooding was reported along portions of Routes 191 and 192. Portions of Routes 191 and 192 were closed to traffic for a time. Route 191 also received flood damage in the vicinity of East Machias.');
INSERT INTO public.stormevents_east VALUES (736207, 201801, 23, 1320, 201801, 23, 1320, 122864, 'ATLANTIC NORTH', 88, 2018, 'January', 'Marine Thunderstorm Wind', 'LWX', '23-JAN-18 13:20:00', 'EST-5', '23-JAN-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'GOOSES REEF BUOY (44062)', 0, 'N', 'GOOSES REEF BUOY (44062)', 38.56, -76.41, 38.56, -76.41, 'A strong cold front passed through on the 12th. Despite limited instability, there was enough forcing for showers to develop along the cold front. These showers were able to mix down some of the gusty winds from aloft.', 'A wind gusts in excess of 30 knots was reported at Gooses Reef.');
INSERT INTO public.stormevents_east VALUES (727231, 201801, 12, 445, 201801, 12, 900, 121489, 'WEST VIRGINIA', 54, 2018, 'January', 'Flood', 'RLX', '12-JAN-18 04:45:00', 'EST-5', '12-JAN-18 09:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'SW', 'FINCH', 0, 'WNW', 'PIKE', 39.3129, -81.0936, 39.2823, -81.0867, 'Strong moisture advection ahead of a southern stream low pressure system brought a prolonged period of moderate to heavy rainfall across the middle Ohio River Valley and Central Appalachians. The rainfall started during the evening of the 11th, and continued through most of the day on the 12th before changing to snow late in the day. Generally 1.5 to 2.5 inches of rain fell. Most of this rain immediately turned to runoff due to a combination of frozen and saturated soil. This caused some creeks and streams to flood.', 'Bond Creek rose out of its banks, flooding sections of County Routes 1, 6, 6/3, and 6/5.');
INSERT INTO public.stormevents_east VALUES (731519, 201801, 12, 1947, 201801, 12, 1947, 122197, 'VIRGINIA', 51, 2018, 'January', 'Thunderstorm Wind', 'RNK', '12-JAN-18 19:47:00', 'EST-5', '12-JAN-18 19:47:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'W', 'BLAIRS', 3, 'W', 'BLAIRS', 36.6752, -79.4313, 36.6752, -79.4313, 'An aggressive cold front crossed the region bringing a soaking rain on top of already antecedent wet conditions from the previous day. Gusty winds associated with an isolated thunderstorm brought down a few trees in Pittsylvania County.', 'Thunderstorm winds knocked over a couple of trees at Tuscarora Country Club.');
INSERT INTO public.stormevents_east VALUES (772386, 201807, 25, 10, 201807, 25, 11, 127275, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '25-JUL-18 00:10:00', 'EST-5', '25-JUL-18 00:11:00', 0, 0, 0, 0, '40.00K', '0.00K', 'NWS Storm Survey', 61, 'EG', NULL, NULL, 2, 'ESE', 'MORELAND', 2, 'SE', 'MORELAND', 41.1686, -76.6371, 41.157, -76.6384, 'A severe thunderstorm developed in a very moist airmass and produced a microburst in Lycoming County that was determined by a NWS survey team to have produced winds estimated at 70 to 80 mph east of Muncy during the early morning hours of July 25, 2018.', 'A severe thunderstorm produced a downburst with winds estimated near 70 mph, knocking down many trees and damaging two barn roofs along its path.');
INSERT INTO public.stormevents_east VALUES (773240, 201807, 23, 332, 201807, 23, 630, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '23-JUL-18 03:32:00', 'EST-5', '23-JUL-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'PINE GLEN', 1, 'NNE', 'ROCK', 40.55, -76.39, 40.5476, -76.2904, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Numerous flood roads and water rescues were reported.  One rescue was noted at Bethel Township and Mt Zion Road and US 22.');
INSERT INTO public.stormevents_east VALUES (773249, 201807, 23, 2104, 201807, 24, 200, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '23-JUL-18 21:04:00', 'EST-5', '24-JUL-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'ELIZABETHVILLE', 7, 'N', 'PILLOW', 40.55, -76.81, 40.726, -76.7909, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Water rescues occurred on Route 209 from Green Street in Washington Township through Cedar Street in Elizabethville as a result of several vehicles driving into floodwaters. Furthermore, Route 225 was closed from Winter Avenue to Bechtel Road as a result of floodwaters. Route 443 was also closed from Mumma Road in West Hanover to Appleby Road in East Hanover as a result of flooding rains. In Middletown by Chestnut Alley to Locust Avenue, and Bradford Avenue to Wayne Avenue, local residents were evacuated as a result of rising waters across Lower Swatara Township.');
INSERT INTO public.stormevents_east VALUES (773814, 201807, 24, 2120, 201807, 25, 1215, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '24-JUL-18 21:20:00', 'EST-5', '25-JUL-18 12:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'JEFFERSON', 1, 'N', 'LOGANVILLE', 39.83, -76.83, 39.8582, -76.7011, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Flooding occurred on Green Valley Road, near Meyers Road. Flooding also occurred onto Indian Rock Dam Road as a result of high waters from Codorus Creek. Codorus Creek also flooded onto Trinity Road.');
INSERT INTO public.stormevents_east VALUES (735537, 201801, 23, 925, 201801, 23, 1200, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '23-JAN-18 09:25:00', 'EST-5', '23-JAN-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NE', 'DALTON', 1, 'NE', 'DALTON', 41.54, -75.74, 41.5401, -75.7309, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Minor flooding was reported around Dalton, mainly on Brookside Road.');
INSERT INTO public.stormevents_east VALUES (737606, 201801, 12, 503, 201801, 12, 900, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 05:03:00', 'EST-5', '12-JAN-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'S', 'ARNOLA', 0, 'NNW', 'NEW KENSINGTON', 40.57, -79.75, 40.5714, -79.7704, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Local law enforcement and 911 reported that Stevenson Blvd, Milligantown Road were flooded. In addition, there was residential flooding reported at Wells Ave.');
INSERT INTO public.stormevents_east VALUES (737885, 201801, 12, 634, 201801, 12, 934, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 06:34:00', 'EST-5', '12-JAN-18 09:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'N', 'IRON BRIDGE', 0, 'NW', 'IRON BRIDGE', 40.73, -79.68, 40.7323, -79.684, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'State official reported that Iron Bridge Road was flooded in South Buffalo Township.');
INSERT INTO public.stormevents_east VALUES (735509, 201801, 12, 1030, 201801, 12, 1600, 122750, 'NEW YORK', 36, 2018, 'January', 'Flood', 'BGM', '12-JAN-18 10:30:00', 'EST-5', '12-JAN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Ice Jam', NULL, 1, 'S', 'YORKVILLE', 0, 'E', 'WHITESBORO', 43.1124, -75.2784, 43.1212, -75.2914, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam along the Sauquoit Creek had backed up 4 feet of water into the neighborhood along Sauquoit Street. Water surrounded a dozen residences. Water rescues were underway for individuals stranded on a porch.');
INSERT INTO public.stormevents_east VALUES (735520, 201801, 23, 732, 201801, 23, 1230, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '23-JAN-18 07:32:00', 'EST-5', '23-JAN-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 1, 'NNE', 'DURYEA', 1, 'ENE', 'DURYEA', 41.3571, -75.7447, 41.3566, -75.7353, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An ice jam occurred on Mill Creek which caused flooding along York Ave.');
INSERT INTO public.stormevents_east VALUES (735536, 201801, 23, 925, 201801, 23, 1245, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '23-JAN-18 09:25:00', 'EST-5', '23-JAN-18 12:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NW', 'DUNMORE', 2, 'SW', 'WEST SCRANTON', 41.4405, -75.6657, 41.4029, -75.6993, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Areas of minor street flooding reported around the City of Scranton. Law enforcement closing some roads.');
INSERT INTO public.stormevents_east VALUES (737749, 201801, 12, 0, 201801, 12, 800, 123048, 'NORTH CAROLINA', 37, 2018, 'January', 'Flood', 'RNK', '12-JAN-18 00:00:00', 'EST-5', '12-JAN-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'ROMINGER', 2, 'NNW', 'ROMINGER', 36.2513, -81.8486, 36.2526, -81.8402, 'On January 11-12 an amplified upper trough over the south central states along with a slow-moving frontal boundary brought heavy rainfall of 4 to 5 inches in about 36 hours  across much of Watauga County. The highst gauge report was 5.20 inches at Sandy Flats IFLOWS (SDRN7). The Boone COOP had (records back to 1980) recorded 3.00 for the 24-hour period ending 12z (7AM) on January 12th which was the 3rd highest one-day January rainfall at this site. Including the previous Boone COOP with records back to 1929, it ranked as the 4th highest daily January rainfall at Boone.  The county was in a Moderate Drought category on the U.S. Drought Monitor preceding this event, which may have lessened the severity of flooding that occurred.', 'The Watauga River at Sugar Grove (SGWN7) USGS gauge crested at 7.04 feet (Minor flood stage - 6 ft.) early on the 12th. Several low-water bridges and roads near the river were flooded and closed.');
INSERT INTO public.stormevents_east VALUES (773816, 201807, 25, 35, 201807, 25, 530, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '25-JUL-18 00:35:00', 'EST-5', '25-JUL-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'ROARING CREEK', 2, 'SSW', 'RUPERT', 40.91, -76.43, 40.961, -76.4858, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Water rescues occurred in Locust Township. Residents in Locust Township were unable to leave their homes due to floodwaters.');
INSERT INTO public.stormevents_east VALUES (736020, 201801, 23, 2100, 201801, 26, 1130, 122847, 'CONNECTICUT', 9, 2018, 'January', 'Flood', 'ALY', '23-JAN-18 21:00:00', 'EST-5', '26-JAN-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 0, 'WNW', 'KENT', 1, 'WNW', 'BULLS BRIDGE', 41.7224, -73.4869, 41.6788, -73.5178, 'An approaching warm front brought temperatures into the 50s on the 23rd along with a batch of showers. Additional showers occurred in the evening along a cold front, bringing rainfall totals to a half inch to an inch across Litchfield County. The mild temperatures and rainfall caused the Housatonic River to rise in the vicinity of a long-lived ice jam near Kent, resulting in flooding, road closures, and evacuations of houses along the river.', 'Flooding occurred in the vicinity of an ice jam on the Housatonic River as mild temperatures and rainfall caused the river to rise. Water was over Route 7 in spots, resulting in its closure between Route 341 and Bulls Bridge Road. Several homes were evacuated. Water was also over Schaghticoke Road.');
INSERT INTO public.stormevents_east VALUES (736021, 201801, 28, 45, 201801, 30, 945, 122848, 'NEW YORK', 36, 2018, 'January', 'Flood', 'ALY', '28-JAN-18 00:45:00', 'EST-5', '30-JAN-18 09:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 3, 'NE', 'ATHOL', 3, 'ENE', 'ATHOL', 43.5264, -73.8248, 43.5078, -73.8176, 'Minor flooding occurred in the vicinity of a long-lived ice jam along the Hudson River between The Glen and Warrensburg from the 28th through the 30th.', 'River Road near Snake Rock in the Town of Thurman was closed due to ice jam flooding. There was four inches of water flowing across the road.');
INSERT INTO public.stormevents_east VALUES (737886, 201801, 12, 1330, 201801, 12, 1730, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 13:30:00', 'EST-5', '12-JAN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 1, 'SE', 'HILLVILLE', 3, 'E', 'HILLVILLE', 41.02, -79.61, 41.0276, -79.5674, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency manager reported flooding along the Allegheny River as a result of ice jam flooding. Trained spotter also noted that homes in the Seybertown area were being flooded.');
INSERT INTO public.stormevents_east VALUES (737887, 201801, 12, 732, 201801, 12, 1430, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 07:32:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'MILL CREEK', 1, 'N', 'WILLIAMSBURG', 41.2182, -79.3175, 41.1917, -79.4027, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'State official reported many flooded roadways across the county.');
INSERT INTO public.stormevents_east VALUES (735538, 201801, 23, 1049, 201801, 23, 1600, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '23-JAN-18 10:49:00', 'EST-5', '23-JAN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'HARDING', 2, 'W', 'DURYEA', 41.3572, -75.7972, 41.355, -75.784, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Minor flooding was reported along Coxton Road from a combination of locally heavy rainfall and backwater from an ice jam on the Susquehanna River.');
INSERT INTO public.stormevents_east VALUES (735539, 201801, 23, 1335, 201801, 24, 700, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '23-JAN-18 13:35:00', 'EST-5', '24-JAN-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 1, 'W', 'NICHOLSON', 1, 'W', 'EASTLEMON', 41.63, -75.79, 41.5776, -75.9071, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'A large ice jam along Tunkhannock Creek was causing significant flooding to nearby roads and residences. Water was backing upstream on Martins Creek near the Route 92 bridge affecting a lumber yard. Six homes were evacuated by swift water rescue teams. One-hundred people were evacuated from a winterized campground that housed migrant oil and gas workers.');
INSERT INTO public.stormevents_east VALUES (735542, 201801, 24, 500, 201801, 25, 400, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '24-JAN-18 05:00:00', 'EST-5', '25-JAN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 0, 'E', 'FORTY FT', 1, 'NNE', 'WEST PITTSTON', 41.3, -75.8707, 41.3434, -75.812, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'An approximately 20 mile long ice jam on the Susquehanna River was creating flooding in Pittston, Exeter Township and West Pittston. Vehicle size chunks of ice were jammed up against bridges, and along islands within the river. Water behind the main ice dam flooded roads and a few homes in West Pittston to the equivalent of a 35 foot natural flow. The ice jam was in place causing flooding for nearly 24 hours, and released during the early hours of January 25, 2018.');
INSERT INTO public.stormevents_east VALUES (776989, 201807, 22, 2000, 201807, 23, 0, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flood', 'CTP', '22-JUL-18 20:00:00', 'EST-5', '23-JUL-18 00:00:00', 0, 0, 1, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'HEIDLERSBURG', 1, 'S', 'GUERNSEY', 39.9408, -77.1728, 39.9396, -77.2214, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'On Wednesday, July 25th, An 18 year old boy was found deceased along Conewago Creek by Stone Jug Road and Benders Church Road in Butler Township.  His family reported him missing on July 23rd, and it is believed he was last seen on Sunday evening.');
INSERT INTO public.stormevents_east VALUES (729826, 201802, 7, 1040, 201802, 7, 1800, 121924, 'OHIO', 39, 2018, 'February', 'Flood', 'RLX', '07-FEB-18 10:40:00', 'EST-5', '07-FEB-18 18:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'CARBONDALE', 1, 'E', 'CARBONDALE', 39.38, -82.27, 39.3773, -82.2588, 'A low pressure system moved through the southern Ohio River Valley on the 6th, crossing the middle Ohio River Valley on the 7th. This system tapped into moisture from the Gulf of Mexico and brought a prolonged period of moderate to heavy rainfall. Many rain gauges across southeastern Ohio reported 24 hour rainfall amounts of 1.0 to 1.3 inches, resulting in minor flooding.', 'State Route 56 was closed near mile marker one due to flooding along Hewett Fork and Trace Run.');
INSERT INTO public.stormevents_east VALUES (732225, 201802, 16, 1630, 201802, 16, 2200, 122282, 'WEST VIRGINIA', 54, 2018, 'February', 'Flood', 'RLX', '16-FEB-18 16:30:00', 'EST-5', '16-FEB-18 22:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'GARRETTS BEND', 2, 'NE', 'SOD', 38.3091, -81.9096, 38.2442, -81.8276, 'A wave of low pressure and surface front crossed West Virginia, producing heavy rainfall on the 16th. Generally 1 to 2 inches of rain fell on already saturated soil. This resulted in creek and stream flooding on the 16th and into the 17th. As the rain drained through the river system, smaller main stem rivers flooded. This eventually led to flooding along the the Ohio River.', 'Tenmile Creek Flooded, causing the closure of Tenmile Creek Road.  Upper Mud River Road was closed by flooding along Big Laurel Creek. Flooding along Straight Fork and Valley Fork closed a section of Route 3 in Griffithsville. Also, Garretts Bend Road was closed near Elizabeth Church due to flooding along Trace Fork and Hayzlett Fork.');
INSERT INTO public.stormevents_east VALUES (750937, 201804, 27, 1748, 201804, 27, 1748, 125212, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'CLE', '27-APR-18 17:48:00', 'EST-5', '27-APR-18 17:48:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'E', 'MC KINLEY HGTS', 1, 'E', 'MC KINLEY HGTS', 41.1814, -80.6887, 41.1814, -80.6887, 'An area of low pressure moved northeast across Ohio during the afternoon of April 27th.  An area of showers with embedded thunderstorms developed along a cold front trailing the low.  A few of the thunderstorms produced damaging wind gusts.  Most of the damage occurred in Trumbull and Mahoning Counties during the early evening.', 'Thunderstorm winds downed a tree on southbound State Route 11 in Liberty Township.');
INSERT INTO public.stormevents_east VALUES (783410, 201811, 1, 2200, 201811, 1, 2300, 130951, 'OHIO', 39, 2018, 'November', 'Flood', 'ILN', '01-NOV-18 22:00:00', 'EST-5', '01-NOV-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LAKEVIEW VAN HORN AR', 1, 'NNW', 'LAKEVIEW VAN HORN AR', 40.5158, -83.9272, 40.5066, -83.924, 'Widespread rain fell across the region as a low pressure system lifted northeast across the Ohio Valley.', 'High water forced the evacuation of 4 households between U.S. Route 33 and State Route 366.');
INSERT INTO public.stormevents_east VALUES (737888, 201801, 12, 530, 201801, 12, 1430, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 05:30:00', 'EST-5', '12-JAN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'HUNTERS CAVE', 1, 'WSW', 'SWART', 39.8982, -80.3034, 39.9419, -80.2721, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'A trained spotter reported that Ten Mile Creek was out of its banks with several roadways flooded around Sycamore. In addition, a male was stuck in in his vehicle due to flooding on the west side of Rogersville. State Route 21 was flooded in several locations.');
INSERT INTO public.stormevents_east VALUES (737889, 201801, 12, 257, 201801, 12, 1630, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 02:57:00', 'EST-5', '12-JAN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NW', 'CLIFTON', 1, 'SSW', 'BOYCE', 40.34, -80.11, 40.3124, -80.1042, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'State officials and local law enforcement reported several roads closed across much of southwestern Allegheny county. This included Route 51 in Brentwood and Baldwin, Baldwin Road in West Homestead, and Lebanon Church Road in West Mifflin. In addition, Chartiers Creek was out of it''s banks flooding South Fayette Road in Bridgeville and Boyce and Mayview Roads in Upper Saint Clair. Evacuations were taking place at the 100 block of Blythe Road in Bridgeville.');
INSERT INTO public.stormevents_east VALUES (737401, 201801, 23, 742, 201801, 23, 744, 122973, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'ILM', '23-JAN-18 07:42:00', 'EST-5', '23-JAN-18 07:44:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 41, 'MG', NULL, NULL, 2, 'NW', 'SHEEPSHEAD ROCK', 2, 'NW', 'SHEEPSHEAD ROCK', 33.96, -77.94, 33.96, -77.94, 'A large low pressure system with associated cold front produced strong winds along and off the coast of North Carolina.', 'A 47 mph gust was recorded at Federal Point.');
INSERT INTO public.stormevents_east VALUES (737402, 201801, 23, 830, 201801, 23, 832, 122973, 'ATLANTIC SOUTH', 87, 2018, 'January', 'Marine Thunderstorm Wind', 'ILM', '23-JAN-18 08:30:00', 'EST-5', '23-JAN-18 08:32:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 34, 'SSW', 'WR4', 34, 'SSW', 'WR4', 33.44, -77.74, 33.44, -77.74, 'A large low pressure system with associated cold front produced strong winds along and off the coast of North Carolina.', 'A 40 mph gust was recorded at the Frying Pan Shoals buoy.');
INSERT INTO public.stormevents_east VALUES (736204, 201801, 11, 2230, 201801, 12, 1900, 122862, 'NORTH CAROLINA', 37, 2018, 'January', 'Flood', 'GSP', '11-JAN-18 22:30:00', 'EST-5', '12-JAN-18 19:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'CALHOUN', 1, 'W', 'GRANGE', 35.243, -82.636, 35.232, -82.643, 'A strong and moist southeasterly upslope flow developed across the western Carolinas in advance of a strong cold front during the 11th and persisted until the front passed through the area on the 12th. Numerous rain showers developing and moving over the North Carolina Blue Ridge resulted in storm total rainfall amounts of 3 to 5 inches across portions of Transylvania County, resulting in minor flooding.', 'A stream gauge on the Little River in eastern Transylvania County exceeded its established flood stage and remained in minor flood conditions for almost 24 hours. The main impact was to lowlands along the stream and to Cascade Lake Rd, which was covered by flood water in spots. Total rainfall of 4 to 5 inches fell over the basin in around 24 hours. Minor river flooding also developed along the French Broad River near Blantyre and persisted for a couple of days.');
INSERT INTO public.stormevents_east VALUES (750938, 201804, 27, 1753, 201804, 27, 1803, 125212, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'CLE', '27-APR-18 17:53:00', 'EST-5', '27-APR-18 18:03:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 6, 'N', 'CORTLAND', 2, 'SE', 'KINSMAN', 41.4168, -80.73, 41.4333, -80.5769, 'An area of low pressure moved northeast across Ohio during the afternoon of April 27th.  An area of showers with embedded thunderstorms developed along a cold front trailing the low.  A few of the thunderstorms produced damaging wind gusts.  Most of the damage occurred in Trumbull and Mahoning Counties during the early evening.', 'Thunderstorm winds gusts downed many trees and large limbs from north of Cortland east into the Kinsman area.');
INSERT INTO public.stormevents_east VALUES (750941, 201804, 27, 1712, 201804, 27, 1717, 125212, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'CLE', '27-APR-18 17:12:00', 'EST-5', '27-APR-18 17:17:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'MANTUA', 0, 'N', 'GARRETTSVILLE', 41.28, -81.22, 41.28, -81.1, 'An area of low pressure moved northeast across Ohio during the afternoon of April 27th.  An area of showers with embedded thunderstorms developed along a cold front trailing the low.  A few of the thunderstorms produced damaging wind gusts.  Most of the damage occurred in Trumbull and Mahoning Counties during the early evening.', 'Thunderstorm wind gusts downed trees from Mantua east to Garrettsville.');
INSERT INTO public.stormevents_east VALUES (729125, 201801, 22, 2353, 201801, 22, 2353, 121814, 'KENTUCKY', 21, 2018, 'January', 'Thunderstorm Wind', 'RLX', '22-JAN-18 23:53:00', 'EST-5', '22-JAN-18 23:53:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 40, 'EG', NULL, NULL, 2, 'S', 'ASHLAND', 2, 'S', 'ASHLAND', 38.44, -82.63, 38.44, -82.63, 'A strong cold front brought showers and thunderstorms to the middle Ohio River Valley late on the 22nd, into the 23rd. Most of the storms remained low topped, but did contain copious amounts of small hail -- enough to cover the ground in some spots. One storm became more organized, and produced some minor tree damage in Boyd County, and also just across the Ohio River in Lawrence County, Ohio.', 'A large tree limb fell down across Valley View Drive.');
INSERT INTO public.stormevents_east VALUES (737890, 201801, 12, 122, 201801, 12, 1630, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 01:22:00', 'EST-5', '12-JAN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'NNW', 'OAKDALE', 0, 'E', 'OAKDALE', 40.4183, -80.1931, 40.3988, -80.1722, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'Emergency management and local law enforcement reported several roads closed around Oakdale.');
INSERT INTO public.stormevents_east VALUES (737891, 201801, 12, 310, 201801, 12, 1410, 122408, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'PBZ', '12-JAN-18 03:10:00', 'EST-5', '12-JAN-18 14:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'NE', 'ELFINWILD', 1, 'E', 'ELFINWILD', 40.5543, -79.9626, 40.5521, -79.9479, 'Low pressure tracking up the Appalachians combined with a strong arctic cold front to produce a significant rain and snow producing storm for the region. Ahead of the front, a strong southwesterly moisture feed and mid-level short wave brought heavy rainfall to the area, with 2 to 3 inch storm total rainfall reports common. This rain created strong rises on area rivers and streams, with several gauging points reaching flood stage. Also, the strong river rises broke up ice on these waterways, creating significant ice jam concerns.||The strong arctic cold front passed through during the afternoon and evening of the 12th, bringing a flash freeze to area roads that were wet and water-covered from the rain. A mix of sleet and freezing rain developed during the evening with minor ice accretion reported. Precipitation then changed to all snow and continued into the morning of the 13th before tapering to snow showers. A swath of 6-8 inches of snow fell from southeast Ohio, across the northern WV panhandle into portions of southwest Pennsylvania, with lesser totals in the Laurel Highlands and southeastern ridges.', 'The public reported several roads closed due to flooding including Route 8 southbound.');
INSERT INTO public.stormevents_east VALUES (736578, 201801, 12, 1515, 201801, 12, 1715, 122903, 'NEW JERSEY', 34, 2018, 'January', 'Flood', 'OKX', '12-JAN-18 15:15:00', 'EST-5', '12-JAN-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 0, 'ESE', 'RIDGEWOOD', 0, 'ESE', 'RIDGEWOOD', 40.9973, -74.1119, 40.998, -74.1116, 'Rain associated with an approaching cold front combined with near record high temperatures and continued snow melt to result in river flooding along the Hohokus Brook in Ho-Ho-Kus, New Jersey. After an average of 5-9 inches of snow the week before, rainfall totals across the region ranged from 1-2.5 inches.', 'The Hohokus Brook at Ho-Ho-Kus rose above its flood stage of 3.0 feet at 3:15pm EST January 12th, crested at a height of 3.33 ft at 4:00pm EST, and fell back below flood stage by 5:15pm EST.');
INSERT INTO public.stormevents_east VALUES (727940, 201801, 12, 2316, 201801, 12, 2316, 121628, 'NORTH CAROLINA', 37, 2018, 'January', 'Thunderstorm Wind', 'MHX', '12-JAN-18 23:16:00', 'EST-5', '12-JAN-18 23:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 2, 'SE', 'BUXTON', 2, 'SE', 'BUXTON', 35.25, -75.53, 35.25, -75.53, 'A strong cold front approached Eastern NC late on January 12th, 2018. A shortwave trough moved through the area prior to the cold front, with high-shear and limited instability, leading to several strong thunderstorm wind gusts across the Outer Banks.', 'WeatherFlow Inc. station at Buxton reported a 60 mph wind gust.');
INSERT INTO public.stormevents_east VALUES (735525, 201801, 23, 757, 201801, 23, 1100, 122751, 'PENNSYLVANIA', 42, 2018, 'January', 'Flood', 'BGM', '23-JAN-18 07:57:00', 'EST-5', '23-JAN-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 1, 'SSE', 'EDWARDSVILLE', 0, 'S', 'KINGSTON', 41.2623, -75.914, 41.2642, -75.9004, 'A mid-January thaw occurred for several days, allowing much of the snow pack to melt into river runoff. This combined with a moderate rainfall of 1 to 2 inches across the region was enough to loosen the river ice cover throughout central New York and northeast Pennsylvania. Moving ice congested and jammed along bridges and narrows on our main stem rivers and tributaries which resulted in numerous areas of minor to moderate flood impacts.', 'Minor flooding was reported along Toby''s Creek.');
INSERT INTO public.stormevents_east VALUES (734444, 201801, 12, 2105, 201801, 12, 2105, 122622, 'VIRGINIA', 51, 2018, 'January', 'Thunderstorm Wind', 'AKQ', '12-JAN-18 21:05:00', 'EST-5', '12-JAN-18 21:05:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'BOYDTON', 1, 'E', 'BOYDTON', 36.67, -78.39, 36.67, -78.39, 'Scattered severe thunderstorms in advance of low pressure and a cold front produced damaging winds and one tornado across portions of central and south central Virginia.', 'Trees and power lines were downed in Boydton.');
INSERT INTO public.stormevents_east VALUES (734446, 201801, 12, 2122, 201801, 12, 2122, 122622, 'VIRGINIA', 51, 2018, 'January', 'Thunderstorm Wind', 'AKQ', '12-JAN-18 21:22:00', 'EST-5', '12-JAN-18 21:22:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'LUNENBURG', 1, 'N', 'LUNENBURG', 36.96, -78.27, 36.96, -78.27, 'Scattered severe thunderstorms in advance of low pressure and a cold front produced damaging winds and one tornado across portions of central and south central Virginia.', 'Trees and power lines were downed in Lunenburg.');
INSERT INTO public.stormevents_east VALUES (734451, 201801, 12, 2141, 201801, 12, 2141, 122622, 'VIRGINIA', 51, 2018, 'January', 'Thunderstorm Wind', 'AKQ', '12-JAN-18 21:41:00', 'EST-5', '12-JAN-18 21:41:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'CREWE', 0, 'N', 'CREWE', 37.17, -78.12, 37.17, -78.12, 'Scattered severe thunderstorms in advance of low pressure and a cold front produced damaging winds and one tornado across portions of central and south central Virginia.', 'Trees were downed near Crewe.');
