INSERT INTO public.stormevents_east VALUES (734455, 201801, 12, 2156, 201801, 12, 2156, 122622, 'VIRGINIA', 51, 2018, 'January', 'Thunderstorm Wind', 'AKQ', '12-JAN-18 21:56:00', 'EST-5', '12-JAN-18 21:56:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'ESE', 'MORVEN', 1, 'ESE', 'MORVEN', 37.41, -78.05, 37.41, -78.05, 'Scattered severe thunderstorms in advance of low pressure and a cold front produced damaging winds and one tornado across portions of central and south central Virginia.', 'Trees were downed along Haw Branch Lane.');
