INSERT INTO public.stormevents_east VALUES (740609, 201803, 20, 206, 201803, 20, 208, 122763, 'GEORGIA', 13, 2018, 'March', 'Thunderstorm Wind', 'CAE', '20-MAR-18 02:06:00', 'EST-5', '20-MAR-18 02:08:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'E', 'ALEXANDER', 1, 'E', 'ALEXANDER', 33.02, -81.87, 33.02, -81.87, 'A band of severe thunderstorms moved southeast over the Central Savannah River Area of GA along a warm front, producing wind damage and some hail.', 'Burke Co dispatch reported downed power lines on Hwy 24 near Alexander Munnerlyn Rd.');
INSERT INTO public.stormevents_east VALUES (737907, 201803, 19, 1455, 201803, 19, 1455, 122888, 'GEORGIA', 13, 2018, 'March', 'Hail', 'TAE', '19-MAR-18 14:55:00', 'EST-5', '19-MAR-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1, NULL, NULL, NULL, 2, 'ENE', 'AUTREYVILLE', 2, 'ENE', 'AUTREYVILLE', 31.0714, -83.7266, 31.0714, -83.7266, 'A typical early spring cold front brought a round of showers and thunderstorms to the area with some large hail and marginally severe winds.', 'A picture of quarter size hail was posted on social media from Tallokas Road in Colquitt county.');
INSERT INTO public.stormevents_east VALUES (735905, 201803, 20, 1506, 201803, 20, 1506, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 15:06:00', 'EST-5', '20-MAR-18 15:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 1.5, NULL, NULL, NULL, 2, 'W', 'SHARPES', 2, 'W', 'SHARPES', 28.43, -80.81, 28.43, -80.81, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A US Air Force meteorologist reported ping pong ball sized hail along Tangelo Avenue about 1/4 mile east of Interstate 95 in Canaveral Groves.');
INSERT INTO public.stormevents_east VALUES (735904, 201803, 20, 1710, 201803, 20, 1710, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 17:10:00', 'EST-5', '20-MAR-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Storm Chaser', 1, NULL, NULL, NULL, 5, 'ENE', 'FT DRUM', 5, 'ENE', 'FT DRUM', 27.54, -80.74, 27.54, -80.74, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A storm chaser near Fort Drum reported quarter sized hail.');
INSERT INTO public.stormevents_east VALUES (735906, 201803, 20, 1359, 201803, 20, 1359, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 13:59:00', 'EST-5', '20-MAR-18 13:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1.75, NULL, NULL, NULL, 2, 'SSE', 'OVIEDO', 2, 'SSE', 'OVIEDO', 28.65, -81.19, 28.65, -81.19, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'Per various social media photos and reports; various members of the public reported hail ranging from ping pong to golf ball size fell in an area from Oviedo to Chuluota to just north of the University of Central Florida campus.');
INSERT INTO public.stormevents_east VALUES (735908, 201803, 20, 1502, 201803, 20, 1502, 122832, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'MLB', '20-MAR-18 15:02:00', 'EST-5', '20-MAR-18 15:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 56, 'MG', NULL, NULL, 3, 'E', 'FRONTENAC', 3, 'E', 'FRONTENAC', 28.47, -80.72, 28.47, -80.72, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A trained spotter measured a peak wind gust of 65 mph from a weather station in North Merritt Island.');
INSERT INTO public.stormevents_east VALUES (738826, 201803, 20, 1414, 201803, 20, 1414, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 14:14:00', 'EST-5', '20-MAR-18 14:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 3, 'WNW', 'PINE CASTLE', 3, 'WNW', 'PINE CASTLE', 28.48, -81.42, 28.48, -81.42, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A trained spotter reported quarter sized hail at the 4300 block of John Young Parkway.');
