INSERT INTO public.stormevents_east VALUES (780618, 201807, 22, 1140, 201807, 22, 1140, 130346, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '22-JUL-18 11:40:00', 'EST-5', '22-JUL-18 11:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'PENIEL', 2, 'SE', 'PENIEL', 29.6028, -81.6762, 29.6028, -81.6762, 'A low level boundary was draped across north-central FL roughly from Suwanee to Marion counties with high moisture content and an unstable airmass pumping over the boundary from the Gulf of Mexico under WSW flow.', 'A tree was blown down and blocking the road at 4044 Browns Landing Road.');
