INSERT INTO public.stormevents_east VALUES (772169, 201807, 17, 1531, 201807, 17, 1531, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 15:31:00', 'EST-5', '17-JUL-18 15:31:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'EG', NULL, NULL, 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 38.29, -76.41, 38.29, -76.41, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust in excess of 30 knots was reported at Patuxent River (KNHK).');
