INSERT INTO public.stormevents_east VALUES (772171, 201807, 17, 1548, 201807, 17, 1554, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 15:48:00', 'EST-5', '17-JUL-18 15:54:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 3, 'S', 'MID BAY BUOY', 3, 'S', 'MID BAY BUOY', 38.432, -76.387, 38.432, -76.387, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'Wind gusts up to 37 knots were reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (772172, 201807, 22, 1500, 201807, 22, 1500, 128754, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '22-JUL-18 15:00:00', 'EST-5', '22-JUL-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A cutoff low from the jet stream developed just to our west on the 22nd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts in excess of 30 knots were reported at Thomas Point Lighthouse.');
