INSERT INTO public.stormevents_east VALUES (768136, 201807, 17, 1442, 201807, 17, 1442, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 14:42:00', 'EST-5', '17-JUL-18 14:42:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SSW', 'TEMPLE HILLS', 1, 'SSW', 'TEMPLE HILLS', 38.808, -76.959, 38.808, -76.959, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'A tree six inches in diameter was down blocking a lane of traffic on Brinkley Road.');
INSERT INTO public.stormevents_east VALUES (756491, 201805, 6, 745, 201805, 6, 745, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 07:45:00', 'EST-5', '06-MAY-18 07:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'W', 'WILES CORNER', 1, 'W', 'WILES CORNER', 36.78, -76.59, 36.78, -76.59, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.13 inches was reported at (1 E) Kings Fork.');
INSERT INTO public.stormevents_east VALUES (768142, 201807, 17, 1900, 201807, 17, 1900, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 19:00:00', 'EST-5', '17-JUL-18 19:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'FOUNTAIN HEAD', 1, 'SE', 'FOUNTAIN HEAD', 39.6651, -77.7216, 39.6651, -77.7216, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'A downed tree on wires was located near the 1000 Block of Columbia Road.');
INSERT INTO public.stormevents_east VALUES (756494, 201805, 6, 859, 201805, 6, 859, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 08:59:00', 'EST-5', '06-MAY-18 08:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 2, 'WSW', 'NORFOLK', 2, 'WSW', 'NORFOLK', 36.86, -76.3, 36.86, -76.3, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.88 inches was reported at Ghent.');
INSERT INTO public.stormevents_east VALUES (756444, 201805, 6, 2102, 201805, 6, 2102, 126190, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '06-MAY-18 21:02:00', 'EST-5', '06-MAY-18 21:02:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 3, 'SSE', 'MAGRUDER', 3, 'SSE', 'MAGRUDER', 37.28, -76.66, 37.28, -76.66, 'Scattered severe thunderstorms well in advance of a frontal boundary produced damaging winds across portions of south central and southeast Virginia.', 'Trees were downed near Queens Lake.');
INSERT INTO public.stormevents_east VALUES (756497, 201805, 6, 901, 201805, 6, 901, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 09:01:00', 'EST-5', '06-MAY-18 09:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'WSW', 'NORFOLK', 1, 'WSW', 'NORFOLK', 36.86, -76.29, 36.86, -76.29, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.68 inches was reported at Downtown Norfolk.');
INSERT INTO public.stormevents_east VALUES (758162, 201805, 10, 1812, 201805, 10, 1812, 126405, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 18:12:00', 'EST-5', '10-MAY-18 18:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 44, 'MG', NULL, NULL, 0, 'N', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 0, 'N', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.96, -76.43, 36.96, -76.43, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the James River.', 'Wind gust of 44 knots was measured at Dominion Terminal Associates.');
