INSERT INTO public.stormevents_east VALUES (759435, 201805, 12, 2100, 201805, 12, 2100, 126516, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '12-MAY-18 21:00:00', 'EST-5', '12-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 44, 'MG', NULL, NULL, 0, 'N', 'OCEAN CITY INLET STATION (OCIM2)', 0, 'N', 'OCEAN CITY INLET STATION (OCIM2)', 38.33, -75.03, 38.33, -75.03, 'Scattered thunderstorms along a frontal boundary produced gusty winds across portions of the Maryland Coastal Waters.', 'Wind gust of 44 knots was measured at Ocean City Inlet (OCIM2).');
INSERT INTO public.stormevents_east VALUES (735077, 201803, 17, 1900, 201803, 17, 1900, 122703, 'VIRGINIA', 51, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 19:00:00', 'EST-5', '17-MAR-18 19:00:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 1, NULL, NULL, NULL, 0, 'N', 'BONDTOWN', 0, 'N', 'BONDTOWN', 36.95, -82.47, 36.95, -82.47, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported at Coeburn.');
INSERT INTO public.stormevents_east VALUES (759444, 201805, 14, 344, 201805, 14, 344, 126702, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '14-MAY-18 03:44:00', 'EST-5', '14-MAY-18 03:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 3, 'SW', 'MANOKIN', 3, 'SW', 'MANOKIN', 38.37, -75.66, 38.37, -75.66, 'Scattered thunderstorms along a frontal boundary produced heavy rain across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 2.12 inches was measured at Mesonet Station C1767, (2 NW Shad Point).');
INSERT INTO public.stormevents_east VALUES (759445, 201805, 14, 353, 201805, 14, 353, 126702, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '14-MAY-18 03:53:00', 'EST-5', '14-MAY-18 03:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 1, 'S', '(W30)OCEAN CITY MUNI', 1, 'S', '(W30)OCEAN CITY MUNI', 38.31, -75.12, 38.31, -75.12, 'Scattered thunderstorms along a frontal boundary produced heavy rain across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 1.75 inches was measured at OXB.');
INSERT INTO public.stormevents_east VALUES (760324, 201805, 14, 1940, 201805, 14, 1940, 126827, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 19:40:00', 'EST-5', '14-MAY-18 19:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'COLEMAN BRIDGE', 0, 'N', 'COLEMAN BRIDGE', 37.24, -76.51, 37.24, -76.51, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the York River.', 'Wind gust of 35 knots was measured at Mesonet Station VA049 (1 N Yorktown).');
