INSERT INTO public.stormevents_east VALUES (768148, 201807, 17, 1935, 201807, 17, 1935, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 19:35:00', 'EST-5', '17-JUL-18 19:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'BRADDOCK HGTS', 2, 'SSW', 'BRADDOCK HGTS', 39.4002, -77.512, 39.4002, -77.512, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'There were downed trees near the 4000 Block of Cherry Lane.');
INSERT INTO public.stormevents_east VALUES (768149, 201807, 17, 1937, 201807, 17, 1937, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 19:37:00', 'EST-5', '17-JUL-18 19:37:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'FEAGAVILLE', 1, 'NW', 'FEAGAVILLE', 39.3892, -77.4887, 39.3892, -77.4887, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'There were downed trees near the crossroad of Mount Phillip Road and Mount Zion Road.');
INSERT INTO public.stormevents_east VALUES (768150, 201807, 17, 1951, 201807, 17, 1951, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 19:51:00', 'EST-5', '17-JUL-18 19:51:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 0, 'N', 'URBANA', 0, 'N', 'URBANA', 39.33, -77.35, 39.33, -77.35, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'Multiple trees and branches were down in roadways in the Urbana Area.');
INSERT INTO public.stormevents_east VALUES (772175, 201807, 22, 1630, 201807, 22, 1630, 128754, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '22-JUL-18 16:30:00', 'EST-5', '22-JUL-18 16:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'PINEY POINT (PPTM2)', 0, 'N', 'PINEY POINT (PPTM2)', 38.13, -76.53, 38.13, -76.53, 'A cutoff low from the jet stream developed just to our west on the 22nd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts in excess of 30 knots were reported at Piney Point.');
