INSERT INTO public.stormevents_east VALUES (772177, 201807, 22, 1648, 201807, 22, 1648, 128754, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '22-JUL-18 16:48:00', 'EST-5', '22-JUL-18 16:48:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'LOWER HOOPERS ISLAND (HPR)', 0, 'N', 'LOWER HOOPERS ISLAND (HPR)', 38.26, -76.18, 38.26, -76.18, 'A cutoff low from the jet stream developed just to our west on the 22nd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts in excess of 30 knots were reported at Lower Hooper Island.');
INSERT INTO public.stormevents_east VALUES (772178, 201807, 22, 1648, 201807, 22, 1648, 128754, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '22-JUL-18 16:48:00', 'EST-5', '22-JUL-18 16:48:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BISHOPS HEAD (BISM2)', 0, 'N', 'BISHOPS HEAD (BISM2)', 38.22, -76.04, 38.22, -76.04, 'A cutoff low from the jet stream developed just to our west on the 22nd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts in excess of 30 knots were reported at Bishops Head.');
INSERT INTO public.stormevents_east VALUES (772180, 201807, 23, 532, 201807, 23, 532, 128755, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '23-JUL-18 05:32:00', 'EST-5', '23-JUL-18 05:32:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 35, 'MG', NULL, NULL, 0, 'ENE', 'QUANTICO (KNYG)', 0, 'ENE', 'QUANTICO (KNYG)', 38.51, -77.3, 38.51, -77.3, 'A cutoff low from the jet stream remained just to our west on the 23rd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust of 35 knots was reported at Quantico.');
INSERT INTO public.stormevents_east VALUES (772182, 201807, 23, 1300, 201807, 23, 1300, 128755, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '23-JUL-18 13:00:00', 'EST-5', '23-JUL-18 13:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A cutoff low from the jet stream remained just to our west on the 23rd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust in excess of 30 knots was reported at Thomas Point Lighthouse.');
INSERT INTO public.stormevents_east VALUES (772179, 201807, 22, 1958, 201807, 22, 1958, 128754, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '22-JUL-18 19:58:00', 'EST-5', '22-JUL-18 19:58:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 3, 'ESE', 'LEESYLVANIA STATE PARK (LSLVN)', 3, 'ESE', 'LEESYLVANIA STATE PARK (LSLVN)', 38.644, -77.199, 38.644, -77.199, 'A cutoff low from the jet stream developed just to our west on the 22nd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust of 37 knots was reported at Occoquon Creek.');
INSERT INTO public.stormevents_east VALUES (742661, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'BUTLER', 2, 'W', 'HERMAN', 40.83, -79.85, 40.8281, -79.8331, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Herman Road flooded between Stutz road and Simon drive.');
INSERT INTO public.stormevents_east VALUES (742664, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'EIDENAU', 1, 'ENE', 'MIDDLE LANCASTER', 40.8205, -80.1102, 40.857, -80.103, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Yellow Creek Road closed due to flooding along Yellow  Creek between Little Creek road and East Lancaster road.');
INSERT INTO public.stormevents_east VALUES (779977, 201808, 13, 1330, 201808, 13, 1330, 130273, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PBZ', '13-AUG-18 13:30:00', 'EST-5', '13-AUG-18 13:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'WSW', 'CRUCIBLE', 1, 'WSW', 'CRUCIBLE', 39.948, -79.9896, 39.948, -79.9896, 'A lingering upper level low pressure system drifting across Pennsylvania promoted low convective temperatures, allowing numerous showers and thunderstorms to develop, which concentrated near disturbances around the upper low.  Decent instability and strong low-level lapse rates promoted damaging wind gusts and hail.  Moisture overall was not excessive for August, but thanks to weak flow near the upper low, storm motion was generally 10 knots or less.  This promoted a few instances of flash flooding as well.', 'Broadcast media reported that several trees were uprooted near Rices Landing.');
INSERT INTO public.stormevents_east VALUES (780015, 201808, 18, 1617, 201808, 18, 1900, 130287, 'PENNSYLVANIA', 42, 2018, 'August', 'Flood', 'PBZ', '18-AUG-18 16:17:00', 'EST-5', '18-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'HOPWOOD', 1, 'ENE', 'HOPWOOD', 39.8781, -79.7021, 39.8801, -79.698, 'Showers and thunderstorms along a slow-moving frontal boundary created some minor flooding issues in Fayette County.', 'A trained spotter reported that Nell Street in Hopwood was flooded.');
INSERT INTO public.stormevents_east VALUES (768151, 201807, 17, 1954, 201807, 17, 1954, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 19:54:00', 'EST-5', '17-JUL-18 19:54:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NW', 'MONROVIA', 0, 'NW', 'MONROVIA', 39.3712, -77.2714, 39.3712, -77.2714, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'A downed tree fell into a house in Monrovia.');
INSERT INTO public.stormevents_east VALUES (768153, 201807, 22, 1310, 201807, 22, 1310, 128095, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '22-JUL-18 13:10:00', 'EST-5', '22-JUL-18 13:10:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'CHANEY', 1, 'SSE', 'CHANEY', 38.7382, -76.6267, 38.7382, -76.6267, 'A cutoff low from the jet stream developed just to our west on the 22nd. A couple thunderstorms became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A tree fell on power lines along MD-260 west of Chesapeake Beach Road.');
INSERT INTO public.stormevents_east VALUES (768621, 201807, 27, 2037, 201807, 27, 2037, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 20:37:00', 'EST-5', '27-JUL-18 20:37:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SSW', 'OVERLEA', 1, 'SSW', 'OVERLEA', 39.3563, -76.5344, 39.3563, -76.5344, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'Numerous trees were down on Rosemont Avenue.');
INSERT INTO public.stormevents_east VALUES (768622, 201807, 27, 1230, 201807, 27, 1230, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 12:30:00', 'EST-5', '27-JUL-18 12:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'NE', 'FLATRUN', 1, 'NE', 'FLATRUN', 38.3764, -77.7622, 38.3764, -77.7622, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'Numerous trees were snapped in a subdivision off of Route 3.');
INSERT INTO public.stormevents_east VALUES (768623, 201807, 27, 1356, 201807, 27, 1356, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 13:56:00', 'EST-5', '27-JUL-18 13:56:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'BULL RUN', 2, 'ENE', 'BULL RUN', 38.843, -77.4544, 38.843, -77.4544, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down on the 6000 block of Oday Drive. Multiple trees were down in the Sully Station neighborhood off of VA-28 Sully Road near Westfields Boulevard.');
INSERT INTO public.stormevents_east VALUES (768624, 201807, 27, 1602, 201807, 27, 1602, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 16:02:00', 'EST-5', '27-JUL-18 16:02:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNE', 'WARRENTON', 2, 'NNE', 'WARRENTON', 38.7403, -77.7634, 38.7403, -77.7634, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down on the 6000 block of Airlie Road.');
INSERT INTO public.stormevents_east VALUES (768629, 201807, 27, 1800, 201807, 27, 1800, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 18:00:00', 'EST-5', '27-JUL-18 18:00:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 60, 'EG', NULL, NULL, 1, 'S', 'UNIONVILLE', 1, 'S', 'UNIONVILLE', 38.2597, -77.9686, 38.2597, -77.9686, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'Twenty to thirty trees were down and a barn was heavily damaged in Unionville.');
INSERT INTO public.stormevents_east VALUES (768630, 201807, 27, 1821, 201807, 27, 1821, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 18:21:00', 'EST-5', '27-JUL-18 18:21:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'W', 'WILDERNESS CORNER', 0, 'W', 'WILDERNESS CORNER', 38.321, -77.709, 38.321, -77.709, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down near Route 3 and Brock Road.');
INSERT INTO public.stormevents_east VALUES (768631, 201807, 27, 1423, 201807, 27, 1423, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 14:23:00', 'EST-5', '27-JUL-18 14:23:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'MORGANTOWN', 1, 'E', 'MORGANTOWN', 38.348, -76.953, 38.348, -76.953, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A large tree was down at the intersection of Morgantown Road and Waverly Point Road.');
INSERT INTO public.stormevents_east VALUES (733320, 201802, 10, 1709, 201802, 11, 1015, 121976, 'KENTUCKY', 21, 2018, 'February', 'Flood', 'JKL', '10-FEB-18 17:09:00', 'EST-5', '11-FEB-18 10:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'WOOTON', 2, 'W', 'WOOTON', 37.18, -83.3, 37.1777, -83.3274, 'A prolonged period of light to moderate rain led to flooding across portions of eastern Kentucky, particularly southeastern Kentucky, beginning during the overnight hours of Friday, February 9 into Saturday, February 10, 2018. This occurred along and ahead of a slow moving frontal boundary as generally between 1.5 and 4.5 inches of rain fell across eastern Kentucky. The hardest hit area was Harlan County, where flooding occurred across much of the county as up to 5.5 inches of rain fell. A state of emergency was declared as the Cumberland River at Baxter reached major flood stage, prompting the closure of all of the city of Harlan''s floodgates. The floodgate for the city of Pikeville was also closed as the Levisa Fork of the Big Sandy River breached 38 feet. Additional emergency declarations were made in Bell, Clay, Floyd, Knott, Knox, Leslie, Letcher, and Perry Counties, as well as for the city of Pineville, as numerous tributaries and the main stems of the Kentucky, Cumberland, and Levisa Fork of the Big Sandy Rivers exceeded bankfull.||Nearly 2,200 power outages were blamed on the widespread flooding, while thousands of boil water advisories were issued as shelters were opened to provide water. Several bridges were also inspected by engineers for structural integrity as the flood waters receded. A number of water rescues took place during the weekend and into Monday morning, including nearly half a dozen in and around Hazard. Hundreds of people were forced from their homes as river flooding along portions of the Kentucky and Cumberland Rivers continued well into the following week. In addition, the saturated ground led to several landslides and mudslides, including one along Kentucky Highway 74 near Middlesboro.||Maximum storm total rainfall amounts from various eastern Kentucky rain gauges (by county) were as follows: ||February 10-11, 2018 Maximum Rainfall Totals (3 inches +)||...Bell County Gauges...|Middlesboro AWOS           4.54 inches|Yellow Creek RAWS          3.45 inches|Meldrum Stream Gauge     5.00 inches|Pineville River Gauge         4.32 inches|Arjay IFLOWS                  4.25 inches ||...Harlan County Gauges...|Harlan 3S                        4.71 inches|Harlan 3N Coop                4.60 inches|Harlan 24E Mesonet          5.59 inches|Cumberland River Gauge    4.27 inches|Lloyal River Gauge            4.92 inches|Cranks Creek Lake Gauge   4.82 inches|Big Black IFLOWS             4.14 inches  |Evarts IFLOWS                3.76 inches    |Cumberland IFLOWS         4.08 inches    ||...Knott County Gauges...|Hindman 5N                    4.11 inches||...Knox County Gauges...|Barbourville Water Coop    3.66 inches|Barbourville 3E Mesonet    4.11 inches|Barbourville River Gauge    3.72 inches|Artemus IFLOWS              3.92 inches  |Dewitt IFLOWS                4.48 inches  |Helton Branch IFLOWS       3.55 inches    |Johnson Hollow IFLOWS     3.03 inches   |Pidgeon Fork IFLOWS        3.88 inches    ||...Leslie County Gauges...|Hyden River Gauge            3.77 inches||...Letcher County Gauges...|Whitesburg 2NW               3.43 inches|Whitesburg 2SE Coop         3.81 inches|Skyline Coop                    3.52 inches|Whitesburg 2NW Mesonet   3.43 inches|Whitesburg River Gauge      3.65 inches||...McCreary County Gauges...|Whitley City 3N                3.48 inches|Stearns Coop                   3.76 inches   |Whitley City 3N Mesonet    3.47 inches|Stearns River Gauge          4.00 inches||...Perry County Gauges...|Hazard Water Plant Coop   3.65 inches|Viper 0.5N COCORAHS       3.43 inches|Hazard River Gauge           3.44 inches||...Pike County Gauges...|Pikeville 13S Mesonet        3.44 inches|Fishtrap Lake Gauge         3.01 inches|Virgie Gauge                    3.20 inches|Elkhorn City River Gauge    3.54 inches|Myra IFLOWS                   3.38 inches    |Virgie IFLOWS                  3.34 inches   |Beefhide IFLOWS              3.59 inches.', 'Highway 699 was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (743764, 201803, 31, 1400, 201803, 31, 1403, 123927, 'FLORIDA', 12, 2018, 'March', 'Tornado', 'MFL', '31-MAR-18 14:00:00', 'EST-5', '31-MAR-18 14:03:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 3, 'SE', 'PAHOKEE', 4, 'SE', 'PAHOKEE', 26.7893, -80.6356, 26.7842, -80.6299, 'A frontal boundary moved into the region which allowed scattered showers and isolated thunderstorms to develop. In the moist and unstable air mass a thunderstorm developed and produced a tornado along outflow and boundary interactions.', 'A trained spotter reported a tornado approximately 3 miles southeast of Pahokee. The tornado was rain-wrapped and nearly stationary. The tornado remained over an open field with no damage reported.');
INSERT INTO public.stormevents_east VALUES (735089, 201803, 17, 1845, 201803, 17, 1845, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 18:45:00', 'EST-5', '17-MAR-18 18:45:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'NE', 'SNEEDVILLE', 1, 'NE', 'SNEEDVILLE', 36.54, -83.21, 36.54, -83.21, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported at Sneedville.');
INSERT INTO public.stormevents_east VALUES (794844, 201811, 24, 1420, 201811, 24, 1420, 132837, 'NORTH CAROLINA', 37, 2018, 'November', 'Thunderstorm Wind', 'MHX', '24-NOV-18 14:20:00', 'EST-5', '24-NOV-18 14:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 3, 'NNW', 'BROAD CREEK', 3, 'NNW', 'BROAD CREEK', 34.76, -76.93, 34.76, -76.93, 'A supercell thunderstorm came ashore in Carteret County and produced several tornadoes, as well as severe thunderstorm wind gusts.', 'Trees down on power lines on Nine Mile Road.  The time was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (742667, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'WINDWARD HGTS', 2, 'N', 'WINDWARD HGTS', 40.92, -79.88, 40.9255, -79.8757, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Oneida Valley road closed between Summit and Oakland Townships owing to flooding likely from Connoquenessing creek.');
INSERT INTO public.stormevents_east VALUES (742668, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'WEHRUM', 1, 'W', 'WEHRUM', 40.4586, -78.9669, 40.4784, -78.9518, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Wehrum Road closed between Mack Road and Plowman Road owing to flooding along Blacklick Creek.');
INSERT INTO public.stormevents_east VALUES (742670, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'DIAMONDVILLE', 1, 'W', 'PINE FLATS', 40.6747, -78.9463, 40.6715, -78.944, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Wandin Road between Two Lick Road and Hill Road closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (780344, 201807, 21, 1320, 201807, 21, 1320, 130344, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'JAX', '21-JUL-18 13:20:00', 'EST-5', '21-JUL-18 13:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (780345, 201807, 21, 1320, 201807, 21, 1320, 130344, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'JAX', '21-JUL-18 13:20:00', 'EST-5', '21-JUL-18 13:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 4, 'W', 'MAYPORT NAS', 4, 'W', 'MAYPORT NAS', 30.39, -81.48, 30.39, -81.48, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', 'A WeatherFlow sensor on Buck Island measured a gust to 45 mph.');
INSERT INTO public.stormevents_east VALUES (780346, 201807, 21, 1325, 201807, 21, 1325, 130344, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'JAX', '21-JUL-18 13:25:00', 'EST-5', '21-JUL-18 13:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 27, 'S', 'FERNANDINA NOS', 27, 'S', 'FERNANDINA NOS', 30.29, -81.39, 30.29, -81.39, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (771967, 201807, 7, 1430, 201807, 7, 1430, 128714, 'FLORIDA', 12, 2018, 'July', 'Flood', 'JAX', '07-JUL-18 14:30:00', 'EST-5', '07-JUL-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'JACKSONVILLE', 3, 'S', 'JACKSONVILLE', 30.3123, -81.6636, 30.3123, -81.6617, 'A TUTT was retrograding over Apalachee Bay with a moist and unstable airmass over the local area. Slow storm motion under an upper level trough axis created very weak storm motion, which promoted heavy rainfall.', 'Children''s Way was flooded to Palm Avenue. Hoods of cars were under water. The cost of damage was unknown, but it was estimated for the event to be included in storm Data.');
INSERT INTO public.stormevents_east VALUES (771969, 201807, 7, 1208, 201807, 7, 1208, 128714, 'FLORIDA', 12, 2018, 'July', 'Funnel Cloud', 'JAX', '07-JUL-18 12:08:00', 'EST-5', '07-JUL-18 12:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'E', 'PALATKA KAY ARKIN AR', 1, 'E', 'PALATKA KAY ARKIN AR', 29.65, -81.66, 29.65, -81.66, 'A TUTT was retrograding over Apalachee Bay with a moist and unstable airmass over the local area. Slow storm motion under an upper level trough axis created very weak storm motion, which promoted heavy rainfall.', 'A funnel cloud was reported over Palatka. Radar imagery indicated a weak shower.');
INSERT INTO public.stormevents_east VALUES (771970, 201807, 8, 815, 201807, 8, 815, 128716, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'JAX', '08-JUL-18 08:15:00', 'EST-5', '08-JUL-18 08:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'ESE', 'CUMBERLAND STAFFORD', 2, 'ESE', 'CUMBERLAND STAFFORD', 31.06, -81.4, 31.06, -81.4, 'A waterspout was reported offshore of Jekyll Island.', 'A waterspout was reported offshore of Jekyll Island.');
INSERT INTO public.stormevents_east VALUES (771972, 201807, 14, 1500, 201807, 14, 1500, 128717, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'JAX', '14-JUL-18 15:00:00', 'EST-5', '14-JUL-18 15:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 3, 'SE', 'CENTER PARK', 3, 'SE', 'CENTER PARK', 30.25, -81.47, 30.25, -81.47, 'A diffuse surface front settled south across SE Georgia with a weak meso low pressure system along the boundary. Very high moisture content fueled widespread rainfall and wet downburst potential due to heavy rainfall loading.', 'A lightning caused brush fire grew to 35 acres near JTB and Hodges. At the time of the report, the fire was 40% contained. The cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (768626, 201807, 27, 1604, 201807, 27, 1604, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 16:04:00', 'EST-5', '27-JUL-18 16:04:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'NEW BALTIMORE', 1, 'WSW', 'NEW BALTIMORE', 38.767, -77.729, 38.767, -77.729, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was blocking the 5300 Block of Old Alexandria Turnpike.');
INSERT INTO public.stormevents_east VALUES (768628, 201807, 27, 1748, 201807, 27, 1748, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 17:48:00', 'EST-5', '27-JUL-18 17:48:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'NASONS', 2, 'WNW', 'NASONS', 38.279, -78.0666, 38.279, -78.0666, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down near the intersection of VA-615 Rapidan Road and VA-700 Trimmers Road.');
INSERT INTO public.stormevents_east VALUES (768636, 201807, 27, 2347, 201807, 27, 2347, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 23:47:00', 'EST-5', '27-JUL-18 23:47:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', '(CHO)CHARLOTTESVILLE', 1, 'ENE', '(CHO)CHARLOTTESVILLE', 38.1567, -78.4333, 38.1567, -78.4333, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down across Dickerson Road.');
INSERT INTO public.stormevents_east VALUES (768637, 201807, 27, 2348, 201807, 27, 2348, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 23:48:00', 'EST-5', '27-JUL-18 23:48:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NW', 'PROFFIT', 0, 'NW', 'PROFFIT', 38.124, -78.434, 38.124, -78.434, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'There were several reports of downed trees and branches between Hollymead and Airport Acres.');
INSERT INTO public.stormevents_east VALUES (768638, 201807, 27, 1531, 201807, 27, 1531, 128157, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 15:31:00', 'EST-5', '27-JUL-18 15:31:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'CHARLES TOWN', 1, 'ESE', 'CHARLES TOWN', 39.2932, -77.8337, 39.2932, -77.8337, 'A cold front caused a severe thunderstorm in the eastern Panhandle of West Virginia.', 'A tree was down at Keys Ferry Road near Route 340.');
INSERT INTO public.stormevents_east VALUES (769513, 201807, 3, 1921, 201807, 3, 2100, 128265, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '03-JUL-18 19:21:00', 'EST-5', '03-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'PYLESVILLE', 1, 'SSW', 'PYLESVILLE', 39.6889, -76.3736, 39.6887, -76.3734, 'Isolated heavy rain developed in Harford County Maryland during the evening of July 3rd. Up to two inches was observed, which caused isolated flooding.', 'Flooding reported in the 900 block of Old Pylesville Road in Pylesville forced the closure of the road.');
INSERT INTO public.stormevents_east VALUES (769515, 201807, 3, 2144, 201807, 3, 2330, 128265, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '03-JUL-18 21:44:00', 'EST-5', '03-JUL-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'STREET', 2, 'WNW', 'STREET', 39.6867, -76.4106, 39.683, -76.4106, 'Isolated heavy rain developed in Harford County Maryland during the evening of July 3rd. Up to two inches was observed, which caused isolated flooding.', 'High water over the roadway in the 4900 block of Rocks Road (Maryland Route 24) forced the closure of the road.');
INSERT INTO public.stormevents_east VALUES (744459, 201803, 20, 1415, 201803, 20, 1418, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:15:00', 'EST-5', '20-MAR-18 14:18:00', 0, 0, 0, 0, NULL, '0.00K', '911 Call Center', 1, NULL, NULL, NULL, 1, 'E', 'MONCKS CORNER', 1, 'E', 'MONCKS CORNER', 33.2, -80.01, 33.2, -80.01, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'Berkeley County dispatch reported quarter sized hail in Moncks Corner.');
INSERT INTO public.stormevents_east VALUES (735093, 201803, 17, 1901, 201803, 17, 1901, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 19:01:00', 'EST-5', '17-MAR-18 19:01:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'NNW', 'STRIGGERSVILLE', 1, 'NNW', 'STRIGGERSVILLE', 36.45, -82.99, 36.45, -82.99, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported three miles north northeast of Rogersville at 119 Devils Nose Road.');
INSERT INTO public.stormevents_east VALUES (735095, 201803, 17, 1924, 201803, 17, 1924, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 19:24:00', 'EST-5', '17-MAR-18 19:24:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'SE', 'ROCK SPGS', 1, 'SE', 'ROCK SPGS', 36.46, -82.54, 36.46, -82.54, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported at the I-26 welcome center.');
INSERT INTO public.stormevents_east VALUES (735096, 201803, 17, 1925, 201803, 17, 1925, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 19:25:00', 'EST-5', '17-MAR-18 19:25:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1.25, NULL, NULL, NULL, 1, 'W', 'MOORESBURG', 1, 'W', 'MOORESBURG', 36.35, -83.23, 36.35, -83.23, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Half dollar size hail was reported near Mooresburg.');
INSERT INTO public.stormevents_east VALUES (735092, 201803, 17, 1900, 201803, 17, 1900, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 19:00:00', 'EST-5', '17-MAR-18 19:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NW', 'ALUMWELL', 1, 'NW', 'ALUMWELL', 36.49, -83.01, 36.49, -83.01, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported six miles south southeast of Kyles Ford.');
INSERT INTO public.stormevents_east VALUES (759437, 201805, 12, 2105, 201805, 12, 2105, 126516, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '12-MAY-18 21:05:00', 'EST-5', '12-MAY-18 21:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 1, 'NE', '(OXB)OCEAN CITY AIRPORT', 1, 'NE', '(OXB)OCEAN CITY AIRPORT', 38.33, -75.08, 38.33, -75.08, 'Scattered thunderstorms along a frontal boundary produced gusty winds across portions of the Maryland Coastal Waters.', 'Wind gust of 41 knots was measured at Mesonet Station XOCN, Ocean City.');
INSERT INTO public.stormevents_east VALUES (759442, 201805, 14, 319, 201805, 14, 319, 126702, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '14-MAY-18 03:19:00', 'EST-5', '14-MAY-18 03:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 3, 'ESE', 'PARSONBURG', 3, 'ESE', 'PARSONBURG', 38.36, -75.43, 38.36, -75.43, 'Scattered thunderstorms along a frontal boundary produced heavy rain across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 1.72 inches was measured at Mesonet Station PWLM2 (2 SSW Pittsville).');
INSERT INTO public.stormevents_east VALUES (759443, 201805, 14, 341, 201805, 14, 341, 126702, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '14-MAY-18 03:41:00', 'EST-5', '14-MAY-18 03:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'SSW', 'HEBRON', 1, 'SSW', 'HEBRON', 38.4, -75.69, 38.4, -75.69, 'Scattered thunderstorms along a frontal boundary produced heavy rain across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 2.23 inches was measured at Mesonet Station AU888, (1 SSW Hebron).');
INSERT INTO public.stormevents_east VALUES (742585, 201802, 16, 202, 201802, 16, 1700, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 02:02:00', 'EST-5', '16-FEB-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'GABBY HGTS', 0, 'SW', 'TYLERDALE JCT', 40.1577, -80.274, 40.1659, -80.2743, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Local law enforcement reported that State Route 40 was closed at Franklin Farm Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (742586, 201802, 15, 2221, 201802, 15, 2221, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 22:21:00', 'EST-5', '15-FEB-18 22:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'COLDBROOK', 0, 'NNE', 'CONNELLSVILLE', 40.0278, -79.591, 40.022, -79.5787, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Emergency manager reported that the Dutch Bottom Area has been flooded.');
INSERT INTO public.stormevents_east VALUES (742604, 201802, 15, 1928, 201802, 15, 1928, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 19:28:00', 'EST-5', '15-FEB-18 19:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'BLAINE HILL', 1, 'ESE', 'ELIZABETH', 40.2547, -79.8476, 40.2603, -79.8602, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Emergency manager reported that Scenery Drive at Happy Hollow was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (742607, 201802, 15, 1930, 201802, 16, 1000, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 19:30:00', 'EST-5', '16-FEB-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'BRENTWOOD', 2, 'NNW', 'BRENTWOOD', 40.391, -79.9791, 40.3941, -79.9837, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Emergency manager reported that Becks Run Road at Brownsville Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (769536, 201807, 4, 1610, 201807, 4, 1800, 128267, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '04-JUL-18 16:10:00', 'EST-5', '04-JUL-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'WINCHESTER ARPT', 1, 'NW', 'WINCHESTER ARPT', 39.1641, -78.1676, 39.1622, -78.1643, 'Scattered showers and thunderstorms developed on the afternoon of July 4th across western Virginia. One to three inches of rain caused isolated flooding in Shenandoah and Frederick Counties.', 'Abrams Creek was reported to be out of its banks near Winchester, with several inches of water flowing across the driveways of businesses.');
INSERT INTO public.stormevents_east VALUES (769552, 201807, 4, 1645, 201807, 4, 1845, 128267, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '04-JUL-18 16:45:00', 'EST-5', '04-JUL-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'COLUMBIA FURNACE', 1, 'NW', 'COLUMBIA FURNACE', 38.8772, -78.6262, 38.8764, -78.6256, 'Scattered showers and thunderstorms developed on the afternoon of July 4th across western Virginia. One to three inches of rain caused isolated flooding in Shenandoah and Frederick Counties.', 'Flooding was reported in Columbia Furnace near the intersection of Wolf Gap Road and Back Road. The road was impassable.');
INSERT INTO public.stormevents_east VALUES (769554, 201807, 4, 1848, 201807, 4, 2100, 128267, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '04-JUL-18 18:48:00', 'EST-5', '04-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'EDINBURG', 0, 'E', 'EDINBURG', 38.8203, -78.5632, 38.8202, -78.5629, 'Scattered showers and thunderstorms developed on the afternoon of July 4th across western Virginia. One to three inches of rain caused isolated flooding in Shenandoah and Frederick Counties.', 'Palmyra Road closed at Stony Creek in Edinburg.');
INSERT INTO public.stormevents_east VALUES (769558, 201807, 4, 1848, 201807, 4, 2100, 128267, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '04-JUL-18 18:48:00', 'EST-5', '04-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'READUS', 1, 'ENE', 'LANTZ MILLS', 38.8417, -78.5811, 38.8385, -78.5822, 'Scattered showers and thunderstorms developed on the afternoon of July 4th across western Virginia. One to three inches of rain caused isolated flooding in Shenandoah and Frederick Counties.', 'Barbershop Road flooded and closed near Edinburg.');
INSERT INTO public.stormevents_east VALUES (769561, 201807, 4, 1848, 201807, 4, 2100, 128267, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '04-JUL-18 18:48:00', 'EST-5', '04-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'CALVARY', 0, 'S', 'CALVARY', 38.8671, -78.5553, 38.8643, -78.5504, 'Scattered showers and thunderstorms developed on the afternoon of July 4th across western Virginia. One to three inches of rain caused isolated flooding in Shenandoah and Frederick Counties.', 'Route 605 flooded and closed near Narrow Passage Creek.');
INSERT INTO public.stormevents_east VALUES (769564, 201807, 4, 1848, 201807, 4, 2100, 128267, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '04-JUL-18 18:48:00', 'EST-5', '04-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MAURERTOWN', 1, 'N', 'MAURERTOWN', 38.9389, -78.4516, 38.9391, -78.4509, 'Scattered showers and thunderstorms developed on the afternoon of July 4th across western Virginia. One to three inches of rain caused isolated flooding in Shenandoah and Frederick Counties.', 'Toll House Road flooded and closed near Toms Brook.');
INSERT INTO public.stormevents_east VALUES (769570, 201807, 11, 1813, 201807, 11, 2000, 128269, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '11-JUL-18 18:13:00', 'EST-5', '11-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'WAYNESBORO ARPT', 2, 'ESE', 'WAYNESBORO ARPT', 38.0705, -78.9027, 38.0704, -78.9026, 'An isolated thunderstorm produced over an inch of rain in the City of Waynesboro during the evening of July 11th, causing localized flooding.', 'Flooding on W 12th Street near Linden Avenue forced a road closure.');
INSERT INTO public.stormevents_east VALUES (772156, 201807, 3, 1931, 201807, 3, 1951, 128751, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '03-JUL-18 19:31:00', 'EST-5', '03-JUL-18 19:51:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 0, 'N', 'GROVE POINT (GVP)', 0, 'N', 'GROVE POINT (GVP)', 39.4, -76.04, 39.4, -76.04, 'An isolated thunderstorm produced gusty winds due to an unstable atmosphere.', 'Wind gusts up to 38 knots were reported at Grove Point.');
INSERT INTO public.stormevents_east VALUES (744917, 201803, 17, 2030, 201803, 17, 2030, 124130, 'GEORGIA', 13, 2018, 'March', 'Hail', 'GSP', '17-MAR-18 20:30:00', 'EST-5', '17-MAR-18 20:30:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 1, 'W', 'MOUNTAIN CITY', 1, 'W', 'MOUNTAIN CITY', 34.92, -83.39, 34.92, -83.39, 'Scattered thunderstorms developed within an unseasonably warm and moist environment ahead of a cold front across the Tennessee Valley during the afternoon and moved southeast into northeast Georgia during the evening. A few of the storms produced large hail and marginally severe wind gusts.', 'Public reported (via Social Media) mostly pea-to-dime size hail, with a few as large as quarters in the Mountain City area.');
INSERT INTO public.stormevents_east VALUES (744918, 201803, 17, 2121, 201803, 17, 2121, 124130, 'GEORGIA', 13, 2018, 'March', 'Hail', 'GSP', '17-MAR-18 21:21:00', 'EST-5', '17-MAR-18 21:21:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 1, 'ENE', 'FAIRVIEW', 1, 'ENE', 'FAIRVIEW', 34.536, -83.153, 34.536, -83.153, 'Scattered thunderstorms developed within an unseasonably warm and moist environment ahead of a cold front across the Tennessee Valley during the afternoon and moved southeast into northeast Georgia during the evening. A few of the storms produced large hail and marginally severe wind gusts.', 'Public reported (via Social Media) mostly dime-to-nickel sized hail with a few quarter sized stones northeast of Avalon.');
INSERT INTO public.stormevents_east VALUES (744919, 201803, 17, 2053, 201803, 17, 2053, 124130, 'GEORGIA', 13, 2018, 'March', 'Thunderstorm Wind', 'GSP', '17-MAR-18 20:53:00', 'EST-5', '17-MAR-18 20:53:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'HILLS', 1, 'NW', 'TURNERVILLE', 34.626, -83.49, 34.692, -83.438, 'Scattered thunderstorms developed within an unseasonably warm and moist environment ahead of a cold front across the Tennessee Valley during the afternoon and moved southeast into northeast Georgia during the evening. A few of the storms produced large hail and marginally severe wind gusts.', 'County comms reported a tree blown down with power outages at the intersection of Old Highway 441 at Abbington way and at Old 441 and Thacker Rd. Another tree was down at the Orchard Rd and Orchard Dr.');
INSERT INTO public.stormevents_east VALUES (744920, 201803, 17, 2112, 201803, 17, 2112, 124131, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'GSP', '17-MAR-18 21:12:00', 'EST-5', '17-MAR-18 21:12:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.75, NULL, NULL, NULL, 0, 'N', 'MADISON', 0, 'N', 'MADISON', 34.65, -83.2, 34.65, -83.2, 'Scattered thunderstorms developed within an unseasonably warm and moist environment ahead of a cold front across the Tennessee Valley during the afternoon and moved southeast across north Georgia and into Upstate South Carolina during the evening. One storm produced marginally damaging winds in Oconee County.', 'Public reported (via Social Media) 3/4 inch diameter hail west of Westminster.');
INSERT INTO public.stormevents_east VALUES (744921, 201803, 17, 2054, 201803, 17, 2054, 124131, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'GSP', '17-MAR-18 20:54:00', 'EST-5', '17-MAR-18 20:54:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'TAMASSEE', 2, 'SSE', 'TAMASSEE', 34.84, -83.02, 34.84, -83.02, 'Scattered thunderstorms developed within an unseasonably warm and moist environment ahead of a cold front across the Tennessee Valley during the afternoon and moved southeast across north Georgia and into Upstate South Carolina during the evening. One storm produced marginally damaging winds in Oconee County.', 'County comms reported a tree blown down on a power line along Bethel Church Rd. Public reported (via Social Media) at least one additional tree down along with power lines in the Salem area.');
INSERT INTO public.stormevents_east VALUES (735099, 201803, 17, 2030, 201803, 17, 2030, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 20:30:00', 'EST-5', '17-MAR-18 20:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'ENE', 'PIGEON FORGE', 1, 'ENE', 'PIGEON FORGE', 35.79, -83.53, 35.79, -83.53, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported two miles east of Pigeon Forge.');
INSERT INTO public.stormevents_east VALUES (735100, 201803, 17, 2035, 201803, 17, 2035, 122704, 'TENNESSEE', 47, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 20:35:00', 'EST-5', '17-MAR-18 20:35:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NE', 'CHURCH HILL', 1, 'NE', 'CHURCH HILL', 36.53, -82.71, 36.53, -82.71, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Several trees and power lines were reported down between Church Hill and Surgoinsville.');
INSERT INTO public.stormevents_east VALUES (735101, 201803, 17, 2100, 201803, 17, 2100, 122704, 'TENNESSEE', 47, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 21:00:00', 'EST-5', '17-MAR-18 21:00:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'RUSSELLVILLE', 2, 'NE', 'RUSSELLVILLE', 36.27, -83.18, 36.27, -83.18, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'A few trees were reported down between Russellville and Whitesburg.');
INSERT INTO public.stormevents_east VALUES (735097, 201803, 17, 2003, 201803, 17, 2003, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 20:03:00', 'EST-5', '17-MAR-18 20:03:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'E', 'LIMESTONE COVE', 1, 'E', 'LIMESTONE COVE', 36.18, -82.26, 36.18, -82.26, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Quarter size hail was reported at Limestone Cove.');
INSERT INTO public.stormevents_east VALUES (735098, 201803, 17, 2005, 201803, 17, 2005, 122704, 'TENNESSEE', 47, 2018, 'March', 'Hail', 'MRX', '17-MAR-18 20:05:00', 'EST-5', '17-MAR-18 20:05:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1.25, NULL, NULL, NULL, 0, 'N', 'BAILEYTON', 0, 'N', 'BAILEYTON', 36.33, -82.83, 36.33, -82.83, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Half dollar size hail fell and a few trees were reported down near Baileyton.');
INSERT INTO public.stormevents_east VALUES (769768, 201808, 17, 1552, 201808, 17, 1552, 127767, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'CTP', '17-AUG-18 15:52:00', 'EST-5', '17-AUG-18 15:52:00', 0, 0, 0, 0, '8.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'SW', 'BONNEAUVILLE', 1, 'SW', 'BONNEAUVILLE', 39.8129, -77.1386, 39.8129, -77.1386, 'Scattered storms developed across central Pennsylvania during the late afternoon and evening hours of August 17, 2018 in a moderate CAPE, moderate shear environment. A few of the storms produced wind damage across south-central Pennsylvania.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down several trees, lines and poles in Bonneauville.');
INSERT INTO public.stormevents_east VALUES (786465, 201809, 21, 1354, 201809, 21, 1354, 131446, 'LAKE HURON', 90, 2018, 'September', 'Marine Thunderstorm Wind', 'DTX', '21-SEP-18 13:54:00', 'EST-5', '21-SEP-18 13:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 41, 'MG', NULL, NULL, 0, 'N', 'FORT GRATIOT WLON STATION (FTGM4)', 0, 'N', 'FORT GRATIOT WLON STATION (FTGM4)', 43.01, -82.42, 43.01, -82.42, 'A thunderstorm near Fort Gratiot produced 41 knot wind gust.', NULL);
INSERT INTO public.stormevents_east VALUES (779989, 201808, 13, 1443, 201808, 13, 1443, 130279, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'PBZ', '13-AUG-18 14:43:00', 'EST-5', '13-AUG-18 14:43:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'NW', 'TORONTO', 1, 'NW', 'TORONTO', 40.46, -80.61, 40.46, -80.61, 'A lingering upper level low pressure system drifting across Pennsylvania promoted low convective temperatures, allowing numerous showers and thunderstorms to develop, which concentrated near disturbances around the upper low.  Decent instability and strong low-level lapse rates promoted damaging wind gusts and hail.', 'The broadcast media reported that several trees were uprooted and that part of a roof was blown off of a house in Toronto.');
INSERT INTO public.stormevents_east VALUES (782185, 201808, 21, 2159, 201808, 22, 30, 127889, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '21-AUG-18 21:59:00', 'EST-5', '22-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BOWMANSVILLE', 1, 'NW', 'FIVEPOINTVILLE', 40.2147, -76.0279, 40.1903, -76.0641, 'A warm front was draped from northwest to southeast across central Pennsylvania on August 21, 2018, with scattered convection developing in the warmer air south and west of the front during the afternoon and evening hours. The storms organized into multiple lines with some exhibited bowing structure. Rotation was observed in some cells within the lines as well.  Late in the evening the storms produced flash flooding in Lancaster County.', 'A vehicle was swept into Muddy Creek north of Bowmansville.');
INSERT INTO public.stormevents_east VALUES (782186, 201808, 21, 2225, 201808, 22, 30, 127889, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '21-AUG-18 22:25:00', 'EST-5', '22-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NEW HOLLAND', 3, 'NNE', 'CHURCHTOWN', 40.1, -76.09, 40.1728, -75.9559, 'A warm front was draped from northwest to southeast across central Pennsylvania on August 21, 2018, with scattered convection developing in the warmer air south and west of the front during the afternoon and evening hours. The storms organized into multiple lines with some exhibited bowing structure. Rotation was observed in some cells within the lines as well.  Late in the evening the storms produced flash flooding in Lancaster County.', 'Several road closures from flash flooding reported across eastern Lancaster County, including New Holland, Bowmansville and Adamstown.');
INSERT INTO public.stormevents_east VALUES (786467, 201809, 3, 1810, 201809, 3, 1810, 131447, 'MICHIGAN', 26, 2018, 'September', 'Thunderstorm Wind', 'DTX', '03-SEP-18 18:10:00', 'EST-5', '03-SEP-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 54, 'EG', NULL, NULL, 2, 'NNW', 'WASHINGTON', 2, 'NNW', 'WASHINGTON', 42.75, -83.04, 42.75, -83.04, 'Thunderstorms brought trees and power lines in Macomb county.', 'Numerous trees and power lines were reported down around Washington Township.');
INSERT INTO public.stormevents_east VALUES (786470, 201809, 5, 1645, 201809, 5, 1645, 131450, 'LAKE HURON', 90, 2018, 'September', 'Marine Thunderstorm Wind', 'DTX', '05-SEP-18 16:45:00', 'EST-5', '05-SEP-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 39, 'MG', NULL, NULL, 0, 'N', 'GRAVELLY SHOALS LIGHT', 0, 'N', 'GRAVELLY SHOALS LIGHT', 44.02, -83.54, 44.02, -83.54, 'Thunderstorms moving through Saginaw Bay and southern Lake Huron produced wind gusts near 40 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (786709, 201809, 5, 2048, 201809, 5, 2048, 131450, 'LAKE HURON', 90, 2018, 'September', 'Marine Thunderstorm Wind', 'DTX', '05-SEP-18 20:48:00', 'EST-5', '05-SEP-18 20:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 34, 'MG', NULL, NULL, 2, 'NNW', 'PORT HURON', 2, 'NNW', 'PORT HURON', 43.01, -82.43, 43.01, -82.43, 'Thunderstorms moving through Saginaw Bay and southern Lake Huron produced wind gusts near 40 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (742609, 201802, 16, 719, 201802, 16, 1000, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:19:00', 'EST-5', '16-FEB-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'GLENDALE', 0, 'NNE', 'WOODVILLE', 40.3954, -80.094, 40.3861, -80.0952, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Trained spotter reported that Chartiers creek was out of its banks flooding nearby roads.');
INSERT INTO public.stormevents_east VALUES (786463, 201809, 25, 1947, 201809, 25, 1947, 129599, 'MICHIGAN', 26, 2018, 'September', 'Thunderstorm Wind', 'DTX', '25-SEP-18 19:47:00', 'EST-5', '25-SEP-18 19:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', 52, 'EG', NULL, NULL, 3, 'SE', 'SOUTH ROCKWOOD', 3, 'SE', 'SOUTH ROCKWOOD', 42.04, -83.22, 42.04, -83.22, 'A robust upper level trough approached the western Great Lakes on September 25, while low pressure developed over northern Lower Michigan along a cold front draped over the region. Ahead of this cold front, southwest winds brought warm and moist air (dew points exceeding 70 degrees in a few areas) to Southeast Michigan during the daytime and evening hours. This moist air mass paired with ample wind shear was sufficient to generate three tornadoes, impacting northern Monroe and southern Wayne counties.', 'A tree was blown down, along with a few large limbs.');
INSERT INTO public.stormevents_east VALUES (780616, 201807, 22, 1110, 201807, 22, 1110, 130346, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '22-JUL-18 11:10:00', 'EST-5', '22-JUL-18 11:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Drought Monitor', 50, 'EG', NULL, NULL, 1, 'ESE', 'PALATKA KAY ARKIN AR', 1, 'ESE', 'PALATKA KAY ARKIN AR', 29.6415, -81.6622, 29.6415, -81.6622, 'A low level boundary was draped across north-central FL roughly from Suwanee to Marion counties with high moisture content and an unstable airmass pumping over the boundary from the Gulf of Mexico under WSW flow.', 'Trees were blown down and blocking the road at South Palm Avenue and Crill Avenue.');
INSERT INTO public.stormevents_east VALUES (780617, 201807, 22, 1115, 201807, 22, 1115, 130346, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '22-JUL-18 11:15:00', 'EST-5', '22-JUL-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'LUNDY', 1, 'WSW', 'LUNDY', 29.6254, -81.6528, 29.6254, -81.6528, 'A low level boundary was draped across north-central FL roughly from Suwanee to Marion counties with high moisture content and an unstable airmass pumping over the boundary from the Gulf of Mexico under WSW flow.', 'Power lines were blown down at 109 Ashley Drive.');
INSERT INTO public.stormevents_east VALUES (774325, 201807, 21, 1030, 201807, 21, 1030, 129220, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'JAX', '21-JUL-18 10:30:00', 'EST-5', '21-JUL-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', '(AMG)BACON CO ARPT A', 1, 'N', '(AMG)BACON CO ARPT A', 31.54, -82.52, 31.54, -82.52, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', 'About 6 trees were blown down and power lines were blown down near the 4th Street exit of Highway 32 West. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (774326, 201807, 21, 1030, 201807, 21, 1030, 129220, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'JAX', '21-JUL-18 10:30:00', 'EST-5', '21-JUL-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'CHATTERTON', 1, 'WSW', 'CHATTERTON', 31.51, -82.75, 31.51, -82.75, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', 'A tree was blown down near General Coffee State Park along Highway 32.');
INSERT INTO public.stormevents_east VALUES (744477, 201803, 20, 1400, 201803, 20, 1415, 124051, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'CHS', '20-MAR-18 14:00:00', 'EST-5', '20-MAR-18 14:15:00', 0, 0, 0, 0, NULL, '0.00K', 'Official NWS Observations', 39, 'MG', NULL, NULL, 5, 'SW', 'SAPELO ISLAND', 5, 'SW', 'SAPELO ISLAND', 31.4178, -81.2954, 31.4178, -81.2954, 'Inland thunderstorms that developed in the vicinity of a warm front inland moved to the coast and out over the adjacent coastal waters in the early morning hours. Then later in the day, additional thunderstorms impacted the coast and the coastal waters during the afternoon. Some of these thunderstorms became strong enough to produce strong wind gusts and large hail.', 'The Sapelo Island NERRS site measured a 39 knot wind gust. The peak gust for the event was 48 knots which occurred at 2:15 pm EST.');
INSERT INTO public.stormevents_east VALUES (756499, 201805, 6, 903, 201805, 6, 903, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 09:03:00', 'EST-5', '06-MAY-18 09:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'N', 'CRADOCK', 1, 'N', 'CRADOCK', 36.8, -76.33, 36.8, -76.33, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.38 inches was reported at Cradock.');
INSERT INTO public.stormevents_east VALUES (756500, 201805, 6, 905, 201805, 6, 905, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 09:05:00', 'EST-5', '06-MAY-18 09:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 2, 'SE', 'CRITTENDEN', 2, 'SE', 'CRITTENDEN', 36.88, -76.48, 36.88, -76.48, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.09 inches was reported at (2 ESE) Hobson.');
INSERT INTO public.stormevents_east VALUES (756501, 201805, 6, 915, 201805, 6, 915, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 09:15:00', 'EST-5', '06-MAY-18 09:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 4, 'ENE', 'NORFOLK', 4, 'ENE', 'NORFOLK', 36.89, -76.21, 36.89, -76.21, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.05 inches was reported at Mesonet Station E4350 (Norfolk International Airport).');
INSERT INTO public.stormevents_east VALUES (756503, 201805, 6, 1030, 201805, 6, 1030, 126203, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '06-MAY-18 10:30:00', 'EST-5', '06-MAY-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 4, 'ENE', 'NORFOLK', 4, 'ENE', 'NORFOLK', 36.9, -76.2, 36.9, -76.2, 'Low pressure moving along a frontal boundary across North Carolina produced heavy rain across portions of southeast Virginia.', 'Rainfall total of 2.43 inches was reported by Co-op Observer who lives close to ORF.');
INSERT INTO public.stormevents_east VALUES (758152, 201805, 10, 1704, 201805, 10, 1704, 126404, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 17:04:00', 'EST-5', '10-MAY-18 17:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 0, 'N', 'DELTAVILLE', 0, 'N', 'DELTAVILLE', 37.56, -76.29, 37.56, -76.29, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 38 knots was measured at Deltaville.');
INSERT INTO public.stormevents_east VALUES (758153, 201805, 10, 1710, 201805, 10, 1710, 126404, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 17:10:00', 'EST-5', '10-MAY-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 44, 'MG', NULL, NULL, 0, 'N', 'STINGRAY POINT CBIBS (44058)', 0, 'N', 'STINGRAY POINT CBIBS (44058)', 37.57, -76.27, 37.57, -76.27, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 44 knots was measured at Stingray Point.');
INSERT INTO public.stormevents_east VALUES (758154, 201805, 10, 1715, 201805, 10, 1715, 126404, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 17:15:00', 'EST-5', '10-MAY-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'NEW POINT COMFORT', 0, 'N', 'NEW POINT COMFORT', 37.33, -76.26, 37.33, -76.26, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 35 knots was measured at New Point Comfort.');
INSERT INTO public.stormevents_east VALUES (758155, 201805, 10, 1724, 201805, 10, 1724, 126404, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 17:24:00', 'EST-5', '10-MAY-18 17:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 41, 'MG', NULL, NULL, 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 37.54, -76.02, 37.54, -76.02, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 41 knots was measured at Rappahannock Light.');
INSERT INTO public.stormevents_east VALUES (756436, 201805, 6, 1920, 201805, 6, 1920, 126190, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '06-MAY-18 19:20:00', 'EST-5', '06-MAY-18 19:20:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'W', 'OGLURN', 1, 'W', 'OGLURN', 36.8, -78.25, 36.8, -78.25, 'Scattered severe thunderstorms well in advance of a frontal boundary produced damaging winds across portions of south central and southeast Virginia.', 'Trees were downed across Route 743.');
INSERT INTO public.stormevents_east VALUES (760325, 201805, 14, 1948, 201805, 14, 1948, 126827, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 19:48:00', 'EST-5', '14-MAY-18 19:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 44, 'MG', NULL, NULL, 0, 'N', 'YORKTOWN USCG STATION WLON (YKTV2)', 0, 'N', 'YORKTOWN USCG STATION WLON (YKTV2)', 37.23, -76.48, 37.23, -76.48, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the York River.', 'Wind gust of 44 knots was measured at Yorktown USCG Station.');
INSERT INTO public.stormevents_east VALUES (760415, 201805, 14, 2036, 201805, 14, 2036, 126826, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:36:00', 'EST-5', '14-MAY-18 20:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 37, 'MG', NULL, NULL, 0, 'N', 'CAPE HENRY', 0, 'N', 'CAPE HENRY', 36.92, -76, 36.92, -76, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 37 knots was measured at Cape Henry.');
INSERT INTO public.stormevents_east VALUES (760416, 201805, 14, 2041, 201805, 14, 2041, 126826, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:41:00', 'EST-5', '14-MAY-18 20:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'RUDEE INLET', 0, 'N', 'RUDEE INLET', 36.83, -75.97, 36.83, -75.97, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 36 knots was measured at Rudee Inlet.');
INSERT INTO public.stormevents_east VALUES (760417, 201805, 14, 2042, 201805, 14, 2042, 126826, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:42:00', 'EST-5', '14-MAY-18 20:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 38, 'MG', NULL, NULL, 0, 'N', 'CAPE HENRY', 0, 'N', 'CAPE HENRY', 36.92, -76, 36.92, -76, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 38 knots was measured at Cape Henry.');
INSERT INTO public.stormevents_east VALUES (760418, 201805, 14, 2045, 201805, 14, 2045, 126826, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:45:00', 'EST-5', '14-MAY-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 0, 'N', 'SANDBRIDGE', 0, 'N', 'SANDBRIDGE', 36.7, -75.92, 36.7, -75.92, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 40 knots was measured at Sandbridge.');
INSERT INTO public.stormevents_east VALUES (772190, 201807, 24, 950, 201807, 24, 950, 128756, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '24-JUL-18 09:50:00', 'EST-5', '24-JUL-18 09:50:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 1, 'SE', 'GREENBERRY POINT (GBY)', 1, 'SE', 'GREENBERRY POINT (GBY)', 38.96, -76.45, 38.96, -76.45, 'A cutoff low from the jet stream remained just to our west on the 24th. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust of 35 knots was reported at Greenberry Point.');
INSERT INTO public.stormevents_east VALUES (735103, 201803, 17, 2015, 201803, 17, 2015, 122704, 'TENNESSEE', 47, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 20:15:00', 'EST-5', '17-MAR-18 20:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 1, 'E', 'CARNEGIE', 1, 'E', 'CARNEGIE', 36.32, -82.32, 36.32, -82.32, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Wind gust was estimated at 60 mph  three miles east southeast of Johnson City at King Springs and Dave Buck Roads.');
INSERT INTO public.stormevents_east VALUES (735102, 201803, 17, 2110, 201803, 17, 2110, 122704, 'TENNESSEE', 47, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 21:10:00', 'EST-5', '17-MAR-18 21:10:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SW', 'GRAY', 1, 'SW', 'GRAY', 36.41, -82.48, 36.41, -82.48, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'A few trees were reported down near Gray.');
INSERT INTO public.stormevents_east VALUES (735105, 201803, 17, 1930, 201803, 17, 1930, 122706, 'NORTH CAROLINA', 37, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 19:30:00', 'EST-5', '17-MAR-18 19:30:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 65, 'EG', NULL, NULL, 1, 'S', 'PEACHTREE', 1, 'S', 'PEACHTREE', 35.09, -83.95, 35.09, -83.95, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'A tree fell on a house and a car and a roof was blown off a shed. Additionally, a fence was blown down on the property.');
INSERT INTO public.stormevents_east VALUES (735107, 201803, 17, 2009, 201803, 17, 2009, 122706, 'NORTH CAROLINA', 37, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 20:09:00', 'EST-5', '17-MAR-18 20:09:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 65, 'EG', NULL, NULL, 1, 'ESE', 'FIRES CREEK', 1, 'ESE', 'FIRES CREEK', 35.07, -83.86, 35.07, -83.86, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Numerous large trees were downed and quarter size hail was reported three miles north of highway 64 on Fires Creek Road.');
INSERT INTO public.stormevents_east VALUES (780189, 201808, 17, 1720, 201808, 17, 2000, 130317, 'OHIO', 39, 2018, 'August', 'Flood', 'PBZ', '17-AUG-18 17:20:00', 'EST-5', '17-AUG-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BRIDGEPORT', 0, 'NW', 'BRIDGEPORT', 40.0716, -80.7592, 40.0721, -80.7521, 'A crossing shortwave worked with mostly elevated instability to generate a line of showers  and thunderstorms across Ohio.  The line produced training thunderstorms across Belmont County, which led to some minor flooding.', 'County 911 officials reported that State Route 40 near Bridgeport was flooded.');
INSERT INTO public.stormevents_east VALUES (737421, 201803, 20, 1630, 201803, 20, 1630, 122977, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'TBW', '20-MAR-18 16:30:00', 'EST-5', '20-MAR-18 16:30:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'SEBRING', 1, 'SW', 'SEBRING', 27.49, -81.45, 27.49, -81.45, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'The Highlands County 911 call center reported widespread wind damage throughout the county, with numerous trees and power lines down.');
INSERT INTO public.stormevents_east VALUES (737433, 201803, 20, 1635, 201803, 20, 1635, 122977, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'TBW', '20-MAR-18 16:35:00', 'EST-5', '20-MAR-18 16:35:00', 0, 0, 0, 0, '50.00K', '0.00K', 'AWOS', 54, 'MG', NULL, NULL, 0, 'NNW', 'SEBRING AIR TERMINAL', 0, 'NNW', 'SEBRING AIR TERMINAL', 27.4552, -81.3415, 27.4552, -81.3415, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'The AWOS at Sebring Regional Airport reported a 62 MPH thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (776355, 201809, 25, 1923, 201809, 25, 1932, 129599, 'MICHIGAN', 26, 2018, 'September', 'Tornado', 'DTX', '25-SEP-18 19:23:00', 'EST-5', '25-SEP-18 19:32:00', 0, 0, 0, 0, '0.50M', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'N', 'MONROE CUSTER ARPT', 1, 'SSW', 'GRAFTON', 41.9562, -83.4321, 42.0099, -83.3892, 'A robust upper level trough approached the western Great Lakes on September 25, while low pressure developed over northern Lower Michigan along a cold front draped over the region. Ahead of this cold front, southwest winds brought warm and moist air (dew points exceeding 70 degrees in a few areas) to Southeast Michigan during the daytime and evening hours. This moist air mass paired with ample wind shear was sufficient to generate three tornadoes, impacting northern Monroe and southern Wayne counties.', 'The path began as weak EF0 damage, mainly to trees, until near Reinhardt and Heiss roads where it became a solid EF0. The tornado reached EF1 strength near Toben and South Stony Creek roads where roofing material was removed leaving exposed trusses and windows that were blown out of homes in the area. Garage doors were also blown in and many trees were damaged and uprooted. EF0 damage to siding and tree limbs was noted before the tornado dissipated near North Stoney Creek road and the railroad|tracks.');
INSERT INTO public.stormevents_east VALUES (776363, 201809, 25, 1955, 201809, 25, 2002, 129599, 'MICHIGAN', 26, 2018, 'September', 'Tornado', 'DTX', '25-SEP-18 19:55:00', 'EST-5', '25-SEP-18 20:02:00', 0, 0, 0, 0, '0.50M', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'NE', 'GIBRALTAR', 1, 'NNE', 'GROSSE ILE NAS', 42.0914, -83.2059, 42.1079, -83.1462, 'A robust upper level trough approached the western Great Lakes on September 25, while low pressure developed over northern Lower Michigan along a cold front draped over the region. Ahead of this cold front, southwest winds brought warm and moist air (dew points exceeding 70 degrees in a few areas) to Southeast Michigan during the daytime and evening hours. This moist air mass paired with ample wind shear was sufficient to generate three tornadoes, impacting northern Monroe and southern Wayne counties.', 'An EF1 tornado began just to the west of W Jefferson Ave and south of Gibraltar Road.  The tornado remained at EF1 strength up to the Navarre Street and Young Drive area, before weakening to EF0 strength for the remainder of the path.  The tornado then crossed the Detroit River before dissipating at the north end of Elba Island in Grosse Ile Township.  Damage included multiple large limbs and trees downed, a roof partially blown off and power lines downed.');
INSERT INTO public.stormevents_east VALUES (780186, 201808, 17, 1700, 201808, 17, 2000, 130317, 'OHIO', 39, 2018, 'August', 'Flood', 'PBZ', '17-AUG-18 17:00:00', 'EST-5', '17-AUG-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'ST CLAIRSVILLE', 0, 'W', 'ST CLAIRSVILLE', 40.0808, -80.9011, 40.0799, -80.9011, 'A crossing shortwave worked with mostly elevated instability to generate a line of showers  and thunderstorms across Ohio.  The line produced training thunderstorms across Belmont County, which led to some minor flooding.', 'County 911 officials reported several flooded basements in St. Clairsville.');
INSERT INTO public.stormevents_east VALUES (780188, 201808, 17, 1700, 201808, 17, 2000, 130317, 'OHIO', 39, 2018, 'August', 'Flood', 'PBZ', '17-AUG-18 17:00:00', 'EST-5', '17-AUG-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'MARTINS FERRY', 0, 'WNW', 'MARTINS FERRY', 40.0992, -80.7227, 40.1003, -80.721, 'A crossing shortwave worked with mostly elevated instability to generate a line of showers  and thunderstorms across Ohio.  The line produced training thunderstorms across Belmont County, which led to some minor flooding.', 'County 911 officials reported flooded docks at the United Dairy Plant.');
INSERT INTO public.stormevents_east VALUES (742671, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'CUMMINGS', 1, 'SSW', 'CUMMINGS', 40.6975, -79.1792, 40.6928, -79.1726, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported that State Route 954 was closed between Route 110 and Chambersville Road owing to flooding from Crooked Creek.');
INSERT INTO public.stormevents_east VALUES (781176, 201808, 12, 1750, 201808, 12, 1945, 130505, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '12-AUG-18 17:50:00', 'EST-5', '12-AUG-18 19:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'MT CARBON', 1, 'NNW', 'KASKA', 40.6779, -76.1336, 40.7448, -76.1302, 'A wet and unsettled weather pattern brought flash flooding to portions of central Pennsylvania from the 12th through the 14th.', 'Widespread flash flooding reported across the area.  Near Mechanicsville Market Street at 3rd Street was impassable.  In Tremont, Clay Street at North Street and Spring Street at the Pine Street Bridge was impassable.  Pottsville reported widespread flooding throughout the town with numerous roadways closed and homes flooded.');
INSERT INTO public.stormevents_east VALUES (781194, 201808, 13, 655, 201808, 13, 930, 130505, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '13-AUG-18 06:55:00', 'EST-5', '13-AUG-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'DINERS HILL', 1, 'NE', 'NEW STREET', 40.716, -76.1543, 40.7083, -76.2143, 'A wet and unsettled weather pattern brought flash flooding to portions of central Pennsylvania from the 12th through the 14th.', 'Widespread flash flooding.  Many evacuations reported in Port Carbon.  In Marlin, Route 209 was flooded from Marlin to Branchdale.');
INSERT INTO public.stormevents_east VALUES (774327, 201807, 21, 1030, 201807, 21, 1030, 129220, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'JAX', '21-JUL-18 10:30:00', 'EST-5', '21-JUL-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'DOUGLAS', 1, 'N', 'DOUGLAS', 31.51, -82.85, 31.51, -82.85, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', 'Several trees were blown down within the city limits of Douglas. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (735913, 201803, 20, 1445, 201803, 20, 1445, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 14:45:00', 'EST-5', '20-MAR-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 48, 'MG', NULL, NULL, 6, 'NNE', 'PLAYALINDA BEACH', 6, 'NNE', 'PLAYALINDA BEACH', 28.64, -80.75, 28.64, -80.75, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A US Air Force wind tower 0714 measured a peak wind gust of 48 knot from the northwest.');
INSERT INTO public.stormevents_east VALUES (735920, 201803, 20, 1455, 201803, 20, 1455, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 14:55:00', 'EST-5', '20-MAR-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 49, 'MG', NULL, NULL, 6, 'NNE', 'CAPE CANAVERAL', 6, 'NNE', 'CAPE CANAVERAL', 28.46, -80.57, 28.46, -80.57, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A US Air Force wind tower measured a peak wind gust of 49 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (774328, 201807, 21, 1109, 201807, 21, 1109, 129220, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'JAX', '21-JUL-18 11:09:00', 'EST-5', '21-JUL-18 11:09:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 3, 'NNE', 'SCREVAN', 3, 'NNE', 'SCREVAN', 31.52, -81.99, 31.52, -81.99, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', 'A tree was blown down onto a power line near the intersection of GA State Road 38 and Alberta Road. The cost of damage was unknown but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (768632, 201807, 27, 1424, 201807, 27, 1424, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 14:24:00', 'EST-5', '27-JUL-18 14:24:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'LA PLATA', 1, 'ENE', 'LA PLATA', 38.5341, -76.9705, 38.5341, -76.9705, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A large tree was down across Tip Hill Court.');
INSERT INTO public.stormevents_east VALUES (768633, 201807, 27, 1650, 201807, 27, 1650, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 16:50:00', 'EST-5', '27-JUL-18 16:50:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'FALLSTON ARPT', 1, 'NNW', 'FALLSTON ARPT', 39.5097, -76.4258, 39.5097, -76.4258, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down on the 2700 Block of Laurel Brook Road.');
INSERT INTO public.stormevents_east VALUES (768634, 201807, 27, 1630, 201807, 27, 1630, 128153, 'MARYLAND', 24, 2018, 'July', 'Hail', 'LWX', '27-JUL-18 16:30:00', 'EST-5', '27-JUL-18 16:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.25, NULL, NULL, NULL, 1, 'ENE', 'CAMDEN', 1, 'ENE', 'CAMDEN', 39.2839, -76.6219, 39.2839, -76.6219, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'Half dollar sized hail was reported at Oriole Park.');
INSERT INTO public.stormevents_east VALUES (768635, 201807, 27, 2331, 201807, 27, 2331, 128156, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 23:31:00', 'EST-5', '27-JUL-18 23:31:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'EARLYSVILLE', 1, 'S', 'EARLYSVILLE', 38.1575, -78.4827, 38.1575, -78.4827, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was blocking Earlysville Road.');
INSERT INTO public.stormevents_east VALUES (768614, 201807, 27, 1701, 201807, 27, 1701, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 17:01:00', 'EST-5', '27-JUL-18 17:01:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NNE', 'SEWELL', 1, 'NNE', 'SEWELL', 39.4791, -76.2463, 39.4791, -76.2463, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down near the intersection of Belcamp Road and Sanford Court.');
INSERT INTO public.stormevents_east VALUES (768616, 201807, 27, 1704, 201807, 27, 1704, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 17:04:00', 'EST-5', '27-JUL-18 17:04:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'SE', 'STEPNEY', 0, 'SE', 'STEPNEY', 39.4784, -76.1986, 39.4784, -76.1986, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down near the intersection of MD-159 Perryman Road and Cranberry Road.');
INSERT INTO public.stormevents_east VALUES (747569, 201803, 17, 2148, 201803, 17, 2148, 124583, 'NORTH CAROLINA', 37, 2018, 'March', 'Hail', 'RNK', '17-MAR-18 21:48:00', 'EST-5', '17-MAR-18 21:48:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'E', 'REIDSVILLE ARPT', 1, 'E', 'REIDSVILLE ARPT', 36.33, -79.62, 36.33, -79.62, 'As high pressure started to depart the area, moisture levels started to rise across the area and a warm front was approaching from the south. A storm developed head of this front over Rockingham County and progressed into Caswell County. Along its course it produced 30 to 50 mph wind gusts and hail ranging from pea to quarter size.', NULL);
INSERT INTO public.stormevents_east VALUES (735108, 201803, 17, 2015, 201803, 17, 2015, 122706, 'NORTH CAROLINA', 37, 2018, 'March', 'Thunderstorm Wind', 'MRX', '17-MAR-18 20:15:00', 'EST-5', '17-MAR-18 20:15:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'HAYESVILLE', 1, 'E', 'HAYESVILLE', 35.05, -83.82, 35.05, -83.82, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'Several trees and power lines were reported down at Hayesville.');
INSERT INTO public.stormevents_east VALUES (737612, 201803, 17, 1917, 201803, 17, 1918, 122706, 'NORTH CAROLINA', 37, 2018, 'March', 'Tornado', 'MRX', '17-MAR-18 19:17:00', 'EST-5', '17-MAR-18 19:18:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ESE', 'PEACHTREE', 2, 'NNE', 'MISSION', 35.0946, -83.9271, 35.0934, -83.9161, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'This tornado started near Upper Peachtree Road and Lizzie Elliot Road. It damaged a business nearby this intersection and tracked into the field behind it. There was debris scattered about the field and an overturned trailer near the creek. The tornado crossed and dissipated just past Lunsford Road and Pipes Branch. There was extensive tree and structural damage to homes and barns along Lunsford Road.');
INSERT INTO public.stormevents_east VALUES (737456, 201803, 20, 1409, 201803, 20, 1414, 122977, 'FLORIDA', 12, 2018, 'March', 'Hail', 'TBW', '20-MAR-18 14:09:00', 'EST-5', '20-MAR-18 14:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'SAINT PETERSBURG', 0, 'N', 'SAINT PETERSBURG', 27.77, -82.64, 27.77, -82.64, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'A trained spotter reported penny size hail in St. Petersburg.');
INSERT INTO public.stormevents_east VALUES (737476, 201803, 20, 1615, 201803, 20, 1615, 122977, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'TBW', '20-MAR-18 16:15:00', 'EST-5', '20-MAR-18 16:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 40, 'EG', NULL, NULL, 1, 'WNW', 'SEBRING', 1, 'WNW', 'SEBRING', 27.5071, -81.4547, 27.5071, -81.4547, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'The Highlands County emergency manager reported a downed tree on Lakeview Drive in Sebring.');
INSERT INTO public.stormevents_east VALUES (737480, 201803, 20, 1400, 201803, 20, 1400, 122977, 'FLORIDA', 12, 2018, 'March', 'Lightning', 'TBW', '20-MAR-18 14:00:00', 'EST-5', '20-MAR-18 14:00:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'ENE', 'GULFPORT', 2, 'ENE', 'GULFPORT', 27.7624, -82.6864, 27.7624, -82.6864, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'Broadcast media reported that a travel trailer was destroyed in St. Petersburg in a fire that was sparked by a lightning strike. One dog was killed in the fire.');
INSERT INTO public.stormevents_east VALUES (737425, 201803, 20, 1615, 201803, 20, 1615, 122977, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'TBW', '20-MAR-18 16:15:00', 'EST-5', '20-MAR-18 16:15:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 40, 'EG', NULL, NULL, 0, 'NW', 'WILD IS', 0, 'NW', 'WILD IS', 27.373, -81.2039, 27.373, -81.2039, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'Highlands County emergency management reported a produce truck was overturned by thunderstorm wind gusts on SR 621 and Charlie Dr.');
INSERT INTO public.stormevents_east VALUES (737454, 201803, 20, 1225, 201803, 20, 1230, 122977, 'FLORIDA', 12, 2018, 'March', 'Hail', 'TBW', '20-MAR-18 12:25:00', 'EST-5', '20-MAR-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', 1.25, NULL, NULL, NULL, 0, 'N', 'CHIEFLAND', 0, 'N', 'CHIEFLAND', 29.48, -82.86, 29.48, -82.86, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'Levy County Public Works reported half dollar size hail in Chiefland.');
INSERT INTO public.stormevents_east VALUES (737455, 201803, 20, 1338, 201803, 20, 1343, 122977, 'FLORIDA', 12, 2018, 'March', 'Hail', 'TBW', '20-MAR-18 13:38:00', 'EST-5', '20-MAR-18 13:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 0.88, NULL, NULL, NULL, 6, 'WNW', 'BUSHNELL', 6, 'WNW', 'BUSHNELL', 28.69, -82.2, 28.69, -82.2, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'Sumter County Sheriff''s Office reported nickel size hail in Wahoo.');
INSERT INTO public.stormevents_east VALUES (779964, 201808, 13, 1254, 201808, 13, 1430, 130273, 'PENNSYLVANIA', 42, 2018, 'August', 'Flood', 'PBZ', '13-AUG-18 12:54:00', 'EST-5', '13-AUG-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'STONEVILLA', 1, 'ENE', 'STONEVILLA', 40.3, -79.51, 40.3026, -79.5102, 'A lingering upper level low pressure system drifting across Pennsylvania promoted low convective temperatures, allowing numerous showers and thunderstorms to develop, which concentrated near disturbances around the upper low.  Decent instability and strong low-level lapse rates promoted damaging wind gusts and hail.  Moisture overall was not excessive for August, but thanks to weak flow near the upper low, storm motion was generally 10 knots or less.  This promoted a few instances of flash flooding as well.', 'County 911 officials reported that water was covering the road near Route 30, and that lane restrictions have been made.');
INSERT INTO public.stormevents_east VALUES (742672, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'CHERRY TREE', 0, 'SE', 'CHERRY TREE', 40.72, -78.81, 40.7277, -78.8278, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Route 580 closed between Mahoning Road and Route 219 due to flooding along Cushion Creek.');
INSERT INTO public.stormevents_east VALUES (742673, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'PURCHASE LINE', 1, 'N', 'PURCHASE LINE', 40.74, -78.93, 40.7386, -78.9195, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported Sebring Road closed around Rice Road and Purchase Line Road.');
INSERT INTO public.stormevents_east VALUES (742674, 201802, 16, 700, 201802, 16, 700, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'TRADE CITY', 2, 'WNW', 'SAVAN', 40.8641, -79.0848, 40.8289, -79.0292, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of highways reported West Creek Road was closed between Route 110 and Route 210 owing to flooding along Little Mahoning Creek.');
INSERT INTO public.stormevents_east VALUES (780583, 201807, 25, 1344, 201807, 25, 1344, 130398, 'FLORIDA', 12, 2018, 'July', 'Tornado', 'JAX', '25-JUL-18 13:44:00', 'EST-5', '25-JUL-18 13:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'E', 'BEVERLY BEACH', 1, 'E', 'BEVERLY BEACH', 29.5, -81.14, 29.5, -81.14, 'A brief tornado touchdown occurred near Flagler Beach, before it moved offshore as a waterspout and dissipated. The airmass was moist, moderately unstable with lingering outflow boundaries and sea breezes in place to support convective growth and low level spin.', 'A brief tornado touchdown was reported near A1A and North 19th Street.  The tornado moved quickly over water where it became a brief waterspout before dissipating. Damage was not reported.');
INSERT INTO public.stormevents_east VALUES (780585, 201807, 27, 1640, 201807, 27, 1940, 130400, 'FLORIDA', 12, 2018, 'July', 'Heavy Rain', 'JAX', '27-JUL-18 16:40:00', 'EST-5', '27-JUL-18 19:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 2, 'E', 'FERNANDINA BEACH ARP', 2, 'E', 'FERNANDINA BEACH ARP', 30.62, -81.44, 30.62, -81.44, 'Slightly drier air aloft created less sea breeze storm coverage  compared to recent days, however it did favor stronger wind gusts in storms.', 'A total of 3.62 was measured since 5 pm.');
INSERT INTO public.stormevents_east VALUES (780586, 201807, 27, 1600, 201807, 27, 2015, 130400, 'FLORIDA', 12, 2018, 'July', 'Heavy Rain', 'JAX', '27-JUL-18 16:00:00', 'EST-5', '27-JUL-18 20:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'W', 'MACCLENNY', 1, 'W', 'MACCLENNY', 30.28, -82.14, 30.28, -82.14, 'Slightly drier air aloft created less sea breeze storm coverage  compared to recent days, however it did favor stronger wind gusts in storms.', 'Since 5 pm, 5.24 of rainfall was measured.');
INSERT INTO public.stormevents_east VALUES (780588, 201807, 27, 1908, 201807, 27, 1908, 130400, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '27-JUL-18 19:08:00', 'EST-5', '27-JUL-18 19:08:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'SE', 'GROSS WELCOME STN', 1, 'SE', 'GROSS WELCOME STN', 30.69, -81.66, 30.69, -81.66, 'Slightly drier air aloft created less sea breeze storm coverage  compared to recent days, however it did favor stronger wind gusts in storms.', 'Power lines were blown down at County Road 108 near US. Highway 17 in Yulee. Cost of damage was unknown but estimated for the event to be in Storm Data.');
INSERT INTO public.stormevents_east VALUES (780591, 201807, 27, 1925, 201807, 27, 1925, 130400, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '27-JUL-18 19:25:00', 'EST-5', '27-JUL-18 19:25:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'S', 'FERNANDINA BEACH', 1, 'S', 'FERNANDINA BEACH', 30.66, -81.45, 30.66, -81.45, 'Slightly drier air aloft created less sea breeze storm coverage  compared to recent days, however it did favor stronger wind gusts in storms.', 'Power lines were blown down at the intersection of South 14th Street and Hickory Street. The time of damage was based on radar. The cost of damage was unknown, but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (780599, 201807, 27, 1927, 201807, 27, 1927, 130400, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '27-JUL-18 19:27:00', 'EST-5', '27-JUL-18 19:27:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'ESE', 'FERNANDINA BEACH', 1, 'ESE', 'FERNANDINA BEACH', 30.66, -81.43, 30.66, -81.43, 'Slightly drier air aloft created less sea breeze storm coverage  compared to recent days, however it did favor stronger wind gusts in storms.', 'Power lines were blown down at the intersection south Fletcher Avenue and Jasmine St in Fernandina Beach. The time of damage was based on radar. The cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (780601, 201807, 28, 1357, 201807, 28, 1357, 130403, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'JAX', '28-JUL-18 13:57:00', 'EST-5', '28-JUL-18 13:57:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'E', 'PINE LAKES', 1, 'E', 'PINE LAKES', 29.53, -81.22, 29.53, -81.22, 'Sea breeze storms formed over a moist and unstable airmass.', 'Wires and a transformer were damaged from a lightning strike. The cost of damage was unknown, but it was estimated for inclusion in Storm Data.');
INSERT INTO public.stormevents_east VALUES (735922, 201803, 20, 1455, 201803, 20, 1455, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 14:55:00', 'EST-5', '20-MAR-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 50, 'MG', NULL, NULL, 11, 'N', 'CAPE CANAVERAL', 11, 'N', 'CAPE CANAVERAL', 28.54, -80.57, 28.54, -80.57, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A US Air Force wind tower measured a peak gust of 50 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (735925, 201803, 20, 1456, 201803, 20, 1456, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 14:56:00', 'EST-5', '20-MAR-18 14:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 63, 'MG', NULL, NULL, 7, 'N', 'CAPE CANAVERAL', 7, 'N', 'CAPE CANAVERAL', 28.477, -80.594, 28.477, -80.594, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'The AWOS at the Cape Canaveral Air Force Station Skid Strip (KXMR) measured a peak wind gust of 63 knots from the west.');
INSERT INTO public.stormevents_east VALUES (735926, 201803, 20, 1500, 201803, 20, 1500, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 15:00:00', 'EST-5', '20-MAR-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 62, 'MG', NULL, NULL, 6, 'N', 'CAPE CANAVERAL', 6, 'N', 'CAPE CANAVERAL', 28.46, -80.59, 28.46, -80.59, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'US Air Force wind tower 0403 measured a peak wind gust of 62 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (735927, 201803, 20, 1510, 201803, 20, 1510, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 15:10:00', 'EST-5', '20-MAR-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 55, 'MG', NULL, NULL, 4, 'NNE', 'CAPE CANAVERAL', 4, 'NNE', 'CAPE CANAVERAL', 28.4338, -80.5734, 28.4338, -80.5734, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'US Air Force wind tower 0001 measured a peak wind gust of 55 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (735931, 201803, 20, 1553, 201803, 20, 1553, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 15:53:00', 'EST-5', '20-MAR-18 15:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 36, 'MG', NULL, NULL, 2, 'NNW', 'MELBOURNE', 2, 'NNW', 'MELBOURNE', 28.101, -80.612, 28.101, -80.612, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'The ASOS at the Melbourne International Airport measured a peak wind gust of 36 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (754874, 201806, 25, 55, 201806, 25, 55, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '25-JUN-18 00:55:00', 'EST-5', '25-JUN-18 00:55:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 43, 'EG', NULL, NULL, 1, 'SW', 'WEST MEDFORD', 1, 'SW', 'WEST MEDFORD', 42.4206, -71.1464, 42.4206, -71.1464, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 12:55 AM EST, a tree and wires were down on Webcowett Road in Arlington, near the Medford town line.');
INSERT INTO public.stormevents_east VALUES (745324, 201803, 1, 1748, 201803, 1, 1749, 124195, 'NORTH CAROLINA', 37, 2018, 'March', 'Thunderstorm Wind', 'ILM', '01-MAR-18 17:48:00', 'EST-5', '01-MAR-18 17:49:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'BEAVER DAM', 3, 'SE', 'BEAVER DAM', 34.2062, -78.7618, 34.2062, -78.7618, 'Showers and thunderstorms associated with an approaching cold front moved through the area during the late afternoon and early evening. Shear values were high. A low level jet of 50 kt helped to enhance the damaging wind risk at the surface despite marginal instability and weak lapse rates.', 'A tree was reported down near the school on James B White Hwy. The time was estimated based on radar data.');
INSERT INTO public.stormevents_east VALUES (772159, 201807, 17, 1418, 201807, 17, 1418, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:18:00', 'EST-5', '17-JUL-18 14:18:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 3, 'ESE', 'LEESYLVANIA STATE PARK (LSLVN)', 3, 'ESE', 'LEESYLVANIA STATE PARK (LSLVN)', 38.644, -77.199, 38.644, -77.199, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust of 35 knots was reported at Occoquon Creek.');
INSERT INTO public.stormevents_east VALUES (737624, 201803, 17, 1932, 201803, 17, 1939, 122706, 'NORTH CAROLINA', 37, 2018, 'March', 'Tornado', 'MRX', '17-MAR-18 19:32:00', 'EST-5', '17-MAR-18 19:39:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ESE', 'FIRES CREEK', 2, 'NNW', 'HAYESVILLE', 35.0759, -83.8679, 35.0699, -83.8423, 'Thunderstorms developed ahead of an upper level system and surface cold front during the evening hours. Several of these storms produced large hail and wind damage. Funnel clouds were reported as a discrete supercell thunderstorm developed over Southeast Tennessee and moved into Southwest North Carolina. As this supercell moved into Monroe County, Tennessee, a weak tornado developed downing several trees and producing minor structural damage.', 'The tornado started approximately near Fires Creek Road and Barlow Fields Drive. This was a non-continuous track more than likely due to the terrain. There was extensive softwood tree damage noted with most trees uprooted. Many trees were snapped in the upper third of their trunks as well. Trees also fell on homes and vehicles along the track. The rear flank downdraft winds were impressive particularly along Lance Cove Road and Sweetwater Bend, just south of the Hiawassee River. The tornado weakened and ended near Poplar Cove just south of the Hiawassee River.');
INSERT INTO public.stormevents_east VALUES (737419, 201803, 20, 1545, 201803, 20, 1545, 122977, 'FLORIDA', 12, 2018, 'March', 'Thunderstorm Wind', 'TBW', '20-MAR-18 15:45:00', 'EST-5', '20-MAR-18 15:45:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', 52, 'EG', NULL, NULL, 3, 'ENE', 'ONA', 3, 'ENE', 'ONA', 27.5, -81.87, 27.5, -81.87, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'Hardee County Emergency Management forwarded pictures of numerous large tree branches snapped and fences knocked down near Wauchula. A trampoline was also blown by the wind into a pickup truck, knocking out a side window.');
INSERT INTO public.stormevents_east VALUES (737424, 201803, 20, 1545, 201803, 20, 1550, 122977, 'FLORIDA', 12, 2018, 'March', 'Hail', 'TBW', '20-MAR-18 15:45:00', 'EST-5', '20-MAR-18 15:50:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Emergency Manager', 1, NULL, NULL, NULL, 2, 'W', 'ZOLFO SPRINGS', 2, 'W', 'ZOLFO SPRINGS', 27.4911, -81.8309, 27.4911, -81.8309, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida Peninsula on the 20th, producing numerous thunderstorms. Some of these storms produced damaging wind gusts and hail across the Nature Coast and West Central Florida.', 'Hardee County Emergency Management forwarded pictures of a window on a home that was broken by wind driven hail near Zolfo Springs.');
INSERT INTO public.stormevents_east VALUES (737412, 201803, 20, 1514, 201803, 20, 1514, 122974, 'GULF OF MEXICO', 85, 2018, 'March', 'Marine Thunderstorm Wind', 'TBW', '20-MAR-18 15:14:00', 'EST-5', '20-MAR-18 15:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 46, 'EG', NULL, NULL, 1, 'S', 'LOWER TAMPA BAY', 1, 'S', 'LOWER TAMPA BAY', 27.6, -82.65, 27.6, -82.65, 'A prefrontal trough developed ahead of a cold front moving southeast through the eastern Gulf of Mexico and Florida peninsula on the 20th, producing numerous thunderstorms. Some of these storms caused marine wind gusts and hail as they came onshore.', 'The WeatherFlow station near the Skyway bridge recorded a thunderstorm wind gust of 46 knots.');
INSERT INTO public.stormevents_east VALUES (772160, 201807, 17, 1431, 201807, 17, 1433, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:31:00', 'EST-5', '17-JUL-18 14:33:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 36, 'MG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'Wind gusts of 35 to 36 knots were reported at Reagan National.');
INSERT INTO public.stormevents_east VALUES (781330, 201808, 3, 929, 201808, 3, 1315, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 09:29:00', 'EST-5', '03-AUG-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'ESTELLA', 2, 'SSE', 'MILLVIEW', 41.521, -76.6172, 41.4723, -76.5712, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'Numerous reports of water and debris across roadways, including Julia Street, Worlds End Road in Forks Township and Route 220 in Dushore.');
INSERT INTO public.stormevents_east VALUES (735935, 201803, 20, 1510, 201803, 20, 1510, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MLB', '20-MAR-18 15:10:00', 'EST-5', '20-MAR-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 64, 'MG', NULL, NULL, 4, 'WNW', 'CAPE CANAVERAL', 4, 'WNW', 'CAPE CANAVERAL', 28.4048, -80.6519, 28.4048, -80.6519, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'US Air Force wind tower 0300 measured a peak wind gust of 64 knots.');
INSERT INTO public.stormevents_east VALUES (772161, 201807, 17, 1439, 201807, 17, 1439, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:39:00', 'EST-5', '17-JUL-18 14:39:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'NATIONALS PARK (WSHNP)', 0, 'N', 'NATIONALS PARK (WSHNP)', 38.87, -77.01, 38.87, -77.01, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust in excess of 30 knots was reported at Nationals Park.');
INSERT INTO public.stormevents_east VALUES (735996, 201803, 20, 1454, 201803, 20, 1454, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Hail', 'MLB', '20-MAR-18 14:54:00', 'EST-5', '20-MAR-18 14:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 2, 'WNW', 'PLAYALINDA BEACH', 2, 'WNW', 'PLAYALINDA BEACH', 28.5598, -80.8035, 28.5598, -80.8035, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A trained spotter reported quarter size hail as a severe thunderstorm moved over the intracoastal waters in Titusville.');
INSERT INTO public.stormevents_east VALUES (735997, 201803, 20, 1514, 201803, 20, 1514, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Hail', 'MLB', '20-MAR-18 15:14:00', 'EST-5', '20-MAR-18 15:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1.25, NULL, NULL, NULL, 6, 'N', 'MERRITT ISLAND', 6, 'N', 'MERRITT ISLAND', 28.4299, -80.723, 28.4299, -80.723, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A trained spotter reported half dollar sized hail in North Merritt Island as a severe thunderstorm moved over the intracoastal waters.');
INSERT INTO public.stormevents_east VALUES (735998, 201803, 20, 1650, 201803, 20, 1650, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Hail', 'MLB', '20-MAR-18 16:50:00', 'EST-5', '20-MAR-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 1, 'NE', 'DAYTONA BEACH', 1, 'NE', 'DAYTONA BEACH', 29.2335, -81.0181, 29.2335, -81.0181, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A member of the public reported ping pong ball sized hail at the intersection of Halifax Avenue and Seabreeze Boulevard as a severe thunderstorm moved across the intracoastal waters and barrier islands in Daytona Beach.');
INSERT INTO public.stormevents_east VALUES (771979, 201807, 14, 1403, 201807, 14, 1403, 128717, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '14-JUL-18 14:03:00', 'EST-5', '14-JUL-18 14:03:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 40, 'EG', NULL, NULL, 0, 'N', 'ORANGE PARK', 0, 'N', 'ORANGE PARK', 30.17, -81.7, 30.17, -81.7, 'A diffuse surface front settled south across SE Georgia with a weak meso low pressure system along the boundary. Very high moisture content fueled widespread rainfall and wet downburst potential due to heavy rainfall loading.', 'Trees were blown down in Heritage Hills. The time of damage was based on radar.  The cost of damage was unknown, but it was estimated for the inclusion Storm Data.');
INSERT INTO public.stormevents_east VALUES (771983, 201807, 13, 2300, 201807, 13, 2300, 128718, 'GEORGIA', 13, 2018, 'July', 'Heavy Rain', 'JAX', '13-JUL-18 23:00:00', 'EST-5', '13-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'NE', 'PYLES MARSH', 2, 'NE', 'PYLES MARSH', 31.15, -81.48, 31.15, -81.48, 'A diffuse surface front settled south across SE Georgia with a weak meso low pressure system along the boundary. Very high moisture content fueled widespread rainfall and wet downburst potential due to heavy rainfall loading.', 'A weather station along Bartow Street in Brunswick, just west of Coffin Park, measured 3.71 inches since midnight.');
INSERT INTO public.stormevents_east VALUES (773644, 201807, 17, 1230, 201807, 17, 1230, 129058, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '17-JUL-18 12:30:00', 'EST-5', '17-JUL-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'JACKSONVILLE', 2, 'SE', 'JACKSONVILLE', 30.33, -81.65, 30.33, -81.65, 'Stronger SW steering flow with a weak surface trough axis across SE GA provided amble moisture and forcing over an unstable airmass that triggered a few strong storms as the sea breezes edged inland.', 'PA power line was blown down near Liberty and Adams Streets. The time of damage was based on radar imagery.');
INSERT INTO public.stormevents_east VALUES (772158, 201807, 17, 1404, 201807, 17, 1404, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:04:00', 'EST-5', '17-JUL-18 14:04:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'EG', NULL, NULL, 0, 'N', 'QUANTICO (KNYG)', 0, 'N', 'QUANTICO (KNYG)', 38.51, -77.3, 38.51, -77.3, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust in excess of 30 knots was reported at Quantico.');
INSERT INTO public.stormevents_east VALUES (772162, 201807, 17, 1439, 201807, 17, 1439, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:39:00', 'EST-5', '17-JUL-18 14:39:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'LYLES-CROUCH ACADEMY (AXDRA)', 0, 'N', 'LYLES-CROUCH ACADEMY (AXDRA)', 38.8, -77.05, 38.8, -77.05, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust of 35 knots was reported at Lyles Crouch Academy.');
INSERT INTO public.stormevents_east VALUES (747200, 201803, 1, 1648, 201803, 1, 1649, 124197, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'ILM', '01-MAR-18 16:48:00', 'EST-5', '01-MAR-18 16:49:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'NNW', 'OLANTA', 1, 'NNW', 'OLANTA', 33.9382, -79.9332, 33.9382, -79.9332, 'Showers and thunderstorms associated with an approaching cold front moved through the area during the late afternoon and early evening. Shear values were high. A low level jet of 50 kt helped to enhance the damaging wind risk at the surface despite marginal instability and weak lapse rates.', 'A tree was reported down on U.S. 301 near Olanta Elementary School. The time was estimated based on radar data.');
INSERT INTO public.stormevents_east VALUES (748504, 201803, 1, 1000, 201803, 1, 1200, 124772, 'TENNESSEE', 47, 2018, 'March', 'Flood', 'MRX', '01-MAR-18 10:00:00', 'EST-5', '01-MAR-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'BLOCKHOUSE', 1, 'E', 'BLOCKHOUSE', 35.7111, -83.8971, 35.7, -83.9122, 'The region was between two surface fronts, one over the southeastern states and the other over the Ohio Valley. These contributed to additional widespread rainfall on the heels of previous high rainfall days.', 'Butterfly Gap Road and Butterfly Gap Loop were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (748503, 201803, 1, 949, 201803, 1, 1115, 124772, 'TENNESSEE', 47, 2018, 'March', 'Flood', 'MRX', '01-MAR-18 09:49:00', 'EST-5', '01-MAR-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Park/Forest Service', NULL, NULL, 'Heavy Rain', NULL, 4, 'ESE', 'CADES COVE', 3, 'E', 'CADES COVE', 35.5979, -83.7642, 35.62, -83.7766, 'The region was between two surface fronts, one over the southeastern states and the other over the Ohio Valley. These contributed to additional widespread rainfall on the heels of previous high rainfall days.', 'Cades Cove Loop Road closed due to high water.');
INSERT INTO public.stormevents_east VALUES (792156, 201811, 3, 553, 201811, 3, 553, 132396, 'RHODE ISLAND', 44, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 05:53:00', 'EST-5', '03-NOV-18 05:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'NATICK', 0, 'N', 'NATICK', 41.7254, -71.4856, 41.7264, -71.4811, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England. Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires. A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak. As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'Cars stuck in flood waters on Interstate 295 exit ramp Exit 1B in Warwick.');
INSERT INTO public.stormevents_east VALUES (792159, 201811, 3, 546, 201811, 3, 546, 132396, 'RHODE ISLAND', 44, 2018, 'November', 'Thunderstorm Wind', 'BOX', '03-NOV-18 05:46:00', 'EST-5', '03-NOV-18 05:46:00', 0, 0, 0, 0, '0.70K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'GREENWOOD', 1, 'S', 'GREENWOOD', 41.7116, -71.449, 41.7116, -71.449, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England. Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires. A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak. As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'A pole and wires were down on Jefferson Blvd. near Main Ave.');
INSERT INTO public.stormevents_east VALUES (792301, 201811, 3, 614, 201811, 3, 714, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 06:14:00', 'EST-5', '03-NOV-18 07:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'MIDDLETON', 0, 'SE', 'MIDDLETON', 42.5954, -71.0144, 42.5946, -71.0149, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'In Middleton, there was significant flooding on a portion of Maple Street.');
INSERT INTO public.stormevents_east VALUES (768155, 201807, 22, 1340, 201807, 22, 1340, 128095, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '22-JUL-18 13:40:00', 'EST-5', '22-JUL-18 13:40:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'E', 'STOAKLEY', 2, 'E', 'STOAKLEY', 38.5728, -76.5686, 38.5728, -76.5686, 'A cutoff low from the jet stream developed just to our west on the 22nd. A couple thunderstorms became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A tree was down on wires blocking Clay Hammond Road near Lottie Fowler Road.');
INSERT INTO public.stormevents_east VALUES (792300, 201811, 3, 545, 201811, 3, 645, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 05:45:00', 'EST-5', '03-NOV-18 06:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'EDGEMERE', 0, 'NNW', 'EDGEMERE', 42.2557, -71.734, 42.2556, -71.7338, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'Street flooding in Shrewsbury at Fairview Street and Quinsigamond Ave.');
INSERT INTO public.stormevents_east VALUES (786462, 201809, 25, 1946, 201809, 25, 1946, 129599, 'MICHIGAN', 26, 2018, 'September', 'Thunderstorm Wind', 'DTX', '25-SEP-18 19:46:00', 'EST-5', '25-SEP-18 19:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', 52, 'EG', NULL, NULL, 2, 'SSE', 'SOUTH ROCKWOOD', 2, 'SSE', 'SOUTH ROCKWOOD', 42.04, -83.23, 42.04, -83.23, 'A robust upper level trough approached the western Great Lakes on September 25, while low pressure developed over northern Lower Michigan along a cold front draped over the region. Ahead of this cold front, southwest winds brought warm and moist air (dew points exceeding 70 degrees in a few areas) to Southeast Michigan during the daytime and evening hours. This moist air mass paired with ample wind shear was sufficient to generate three tornadoes, impacting northern Monroe and southern Wayne counties.', 'A tree was blown down.');
INSERT INTO public.stormevents_east VALUES (781339, 201808, 3, 2005, 201808, 3, 2200, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 20:05:00', 'EST-5', '03-AUG-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'YORKSHIRE', 1, 'S', 'SPRY', 40.0103, -76.6667, 39.9102, -76.6805, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'Flash flooding resulted in a water rescue on Camp Betty Washington Road in York Township.  Flooding was also reported between Camp Betty Washington Road and Chapel Church Road.   A portion of Springwood Road was washed out.  A water rescue also occurred on Frysville Road near the Prince mobile home park.');
INSERT INTO public.stormevents_east VALUES (768156, 201807, 22, 1834, 201807, 22, 1834, 128096, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '22-JUL-18 18:34:00', 'EST-5', '22-JUL-18 18:34:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNE', 'BOYD TAVERN', 1, 'NNE', 'BOYD TAVERN', 37.9925, -78.3448, 37.9925, -78.3448, 'A cutoff low from the jet stream developed just to our west on the 22nd. A couple thunderstorms became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A tree was down near the intersection of US-250 Richmond Road and VA-794 Three Chopt Road.');
INSERT INTO public.stormevents_east VALUES (742610, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CRAIGSVILLE', 0, 'SSW', 'CRAIGSVILLE', 40.842, -79.6416, 40.8435, -79.653, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of Highways reported that Yellow Dog Road was closed between Craigsville Road and Airport Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (742614, 201802, 16, 700, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '16-FEB-18 07:00:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'CRAIGSVILLE', 1, 'NW', 'CRAIGSVILLE', 40.8698, -79.6714, 40.8644, -79.6676, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Department of Highways reported that Nichola Road was flooded between Hindman Hill Road and Valley View Road from Buffalo Creek.');
INSERT INTO public.stormevents_east VALUES (736001, 201803, 20, 1651, 201803, 20, 1651, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Hail', 'MLB', '20-MAR-18 16:51:00', 'EST-5', '20-MAR-18 16:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 2, NULL, NULL, NULL, 2, 'NNW', 'DAYTONA BEACH', 2, 'NNW', 'DAYTONA BEACH', 29.24, -81.04, 29.24, -81.04, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A trained spotter in Holly Hill reported two inch hail as a severe thunderstorm moved over the intracoastal waterway.');
INSERT INTO public.stormevents_east VALUES (736002, 201803, 20, 1623, 201803, 20, 1623, 122839, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Hail', 'MLB', '20-MAR-18 16:23:00', 'EST-5', '20-MAR-18 16:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 5, 'NNW', 'DAYTONA BEACH', 5, 'NNW', 'DAYTONA BEACH', 29.28, -81.06, 29.28, -81.06, 'A mid-level weather disturbance moved across north Florida with an associated strong cold front. These features sparked several rounds of strong to severe storms that moved over the intracoastal and near-shore waters of Volusia and Brevard Counties. These storms produced hail ranging from 1.25 to 2 inches in Volusia County. In Brevard County, |near-hurricane-force wind gusts and hail up to 1.25 inches occurred.', 'A trained spotter in Ormond Beach reported quarter size hail as a severe thunderstorm moved over the intracoastal waterway.');
INSERT INTO public.stormevents_east VALUES (735888, 201803, 20, 1357, 201803, 20, 1357, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 13:57:00', 'EST-5', '20-MAR-18 13:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1.5, NULL, NULL, NULL, 1, 'WSW', 'JONES LNDG', 1, 'WSW', 'JONES LNDG', 28.62, -81.2, 28.62, -81.2, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A trained spotter reported ping pong ball sized hail in Oviedo.');
INSERT INTO public.stormevents_east VALUES (735891, 201803, 20, 1430, 201803, 20, 1430, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 14:30:00', 'EST-5', '20-MAR-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 1, NULL, NULL, NULL, 6, 'WSW', 'BITHLO', 6, 'WSW', 'BITHLO', 28.52, -81.19, 28.52, -81.19, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A ham radio operator reported quarter sized hail near Alafaya Trail and Stoney Brook East in Avalon Park.');
INSERT INTO public.stormevents_east VALUES (735892, 201803, 20, 1454, 201803, 20, 1454, 122832, 'FLORIDA', 12, 2018, 'March', 'Hail', 'MLB', '20-MAR-18 14:54:00', 'EST-5', '20-MAR-18 14:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 3, 'WNW', 'PLAYALINDA BEACH', 3, 'WNW', 'PLAYALINDA BEACH', 28.56, -80.82, 28.56, -80.82, 'A deepening mid-level trough and associated strong cold front moved across north/central Florida. Conditions ahead and along the cold front were favorable for severe thunderstorms as an 80-90 knot jet maxima produced sufficient upper level divergence. These conditions produced an enhanced risk of severe weather, sparking several rounds of severe thunderstorms, which affected Volusia, Seminole, Orange, Brevard and Okeechobee Counties.', 'A trained spotter reported quarter sized hail in Titusville.');
INSERT INTO public.stormevents_east VALUES (768154, 201807, 22, 1320, 201807, 22, 1320, 128095, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '22-JUL-18 13:20:00', 'EST-5', '22-JUL-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'E', 'HALL', 1, 'E', 'HALL', 38.8988, -76.7197, 38.8988, -76.7197, 'A cutoff low from the jet stream developed just to our west on the 22nd. A couple thunderstorms became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A tree fell on power lines blocking the westbound ramp from MD-214 to US-301 Crain Highway.');
INSERT INTO public.stormevents_east VALUES (768157, 201807, 22, 1847, 201807, 22, 1847, 128096, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '22-JUL-18 18:47:00', 'EST-5', '22-JUL-18 18:47:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'EASTHAM', 1, 'NE', 'EASTHAM', 38.0847, -78.402, 38.0847, -78.402, 'A cutoff low from the jet stream developed just to our west on the 22nd. A couple thunderstorms became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A tree was down near the intersection of VA-649 Proffit Road and VA-20 Stony Point Road.');
INSERT INTO public.stormevents_east VALUES (768158, 201807, 23, 201, 201807, 23, 201, 128097, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '23-JUL-18 02:01:00', 'EST-5', '23-JUL-18 02:01:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 3, 'WNW', 'MT HOPE', 3, 'WNW', 'MT HOPE', 39.4, -76.76, 39.4, -76.76, 'A cutoff low from the jet stream remained just to our west on the 23rd. An isolated  thunderstorm became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Multiple downed trees were near Greenspring Valley Road and Championship Court.');
INSERT INTO public.stormevents_east VALUES (768159, 201807, 23, 705, 201807, 23, 705, 128099, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '23-JUL-18 07:05:00', 'EST-5', '23-JUL-18 07:05:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'S', 'VIENNA', 2, 'S', 'VIENNA', 38.8778, -77.2654, 38.8778, -77.2654, 'A cutoff low from the jet stream remained just to our west on the 23rd. An isolated thunderstorm became severe due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A tree was down blocking the right side of the I-66 westbound ramp toward the Vienna Metro.');
INSERT INTO public.stormevents_east VALUES (768576, 201807, 27, 1420, 201807, 27, 1420, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 14:20:00', 'EST-5', '27-JUL-18 14:20:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'WSW', 'COVE PT', 1, 'WSW', 'COVE PT', 38.3767, -76.4144, 38.3767, -76.4144, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'Multiple trees were down on the Pioneer Trail. Numerous trees were uprooted near Cove Point as well.');
INSERT INTO public.stormevents_east VALUES (772163, 201807, 17, 1443, 201807, 17, 1443, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:43:00', 'EST-5', '17-JUL-18 14:43:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 2, 'E', 'BABAR POINT (BAB)', 2, 'E', 'BABAR POINT (BAB)', 38.3089, -77.0019, 38.3089, -77.0019, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust of 35 knots was reported at Pylons DAH.');
INSERT INTO public.stormevents_east VALUES (772164, 201807, 17, 1446, 201807, 17, 1446, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 14:46:00', 'EST-5', '17-JUL-18 14:46:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 38.34, -76.99, 38.34, -76.99, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust of 34 knots was reported at Potomac Light.');
INSERT INTO public.stormevents_east VALUES (772165, 201807, 17, 1500, 201807, 17, 1500, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 15:00:00', 'EST-5', '17-JUL-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust of 37 knots was reported at Thomas Point Lighthouse.');
INSERT INTO public.stormevents_east VALUES (772167, 201807, 17, 1509, 201807, 17, 1519, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 15:09:00', 'EST-5', '17-JUL-18 15:19:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'Wind gusts of 38 to 41 knots were reported at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (772168, 201807, 17, 1524, 201807, 17, 1536, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 15:24:00', 'EST-5', '17-JUL-18 15:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'SOLOMONS ISLAND (SLIM2)', 0, 'N', 'SOLOMONS ISLAND (SLIM2)', 38.32, -76.45, 38.32, -76.45, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'Wind gusts up to 36 knots were reported at Solomons Island.');
INSERT INTO public.stormevents_east VALUES (740603, 201803, 20, 203, 201803, 20, 205, 122763, 'GEORGIA', 13, 2018, 'March', 'Hail', 'CAE', '20-MAR-18 02:03:00', 'EST-5', '20-MAR-18 02:05:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 0, 'N', 'ALEXANDER', 0, 'N', 'ALEXANDER', 33.02, -81.88, 33.02, -81.88, 'A band of severe thunderstorms moved southeast over the Central Savannah River Area of GA along a warm front, producing wind damage and some hail.', 'Utility worker reported quarter size hail in the Alexander community.');
INSERT INTO public.stormevents_east VALUES (740604, 201803, 20, 205, 201803, 20, 208, 122763, 'GEORGIA', 13, 2018, 'March', 'Hail', 'CAE', '20-MAR-18 02:05:00', 'EST-5', '20-MAR-18 02:08:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Fire Department/Rescue', 0.88, NULL, NULL, NULL, 1, 'E', 'ALEXANDER', 1, 'E', 'ALEXANDER', 33.02, -81.87, 33.02, -81.87, 'A band of severe thunderstorms moved southeast over the Central Savannah River Area of GA along a warm front, producing wind damage and some hail.', 'Fire Dept reported nickel size hail and damage to a gutter spout at Burke Co Fire Station 10 in Alexander.');
INSERT INTO public.stormevents_east VALUES (758161, 201805, 10, 1811, 201805, 10, 1811, 126405, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 18:11:00', 'EST-5', '10-MAY-18 18:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 47, 'MG', NULL, NULL, 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.95, -76.39, 36.95, -76.39, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the James River.', 'Wind gust of 47 knots was measured at Middle Ground Lighthouse.');
INSERT INTO public.stormevents_east VALUES (759905, 201805, 14, 2012, 201805, 14, 2012, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 20:12:00', 'EST-5', '14-MAY-18 20:12:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'WILLIAMSBURG', 2, 'ENE', 'WILLIAMSBURG', 37.28, -76.69, 37.28, -76.69, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Tree was downed at the 500 Block of Capital Landing Road.');
INSERT INTO public.stormevents_east VALUES (747571, 201803, 17, 2154, 201803, 17, 2154, 124583, 'NORTH CAROLINA', 37, 2018, 'March', 'Hail', 'RNK', '17-MAR-18 21:54:00', 'EST-5', '17-MAR-18 21:54:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'SE', 'ASHLAND', 1, 'SE', 'ASHLAND', 36.31, -79.51, 36.31, -79.51, 'As high pressure started to depart the area, moisture levels started to rise across the area and a warm front was approaching from the south. A storm developed head of this front over Rockingham County and progressed into Caswell County. Along its course it produced 30 to 50 mph wind gusts and hail ranging from pea to quarter size.', 'Hail occurred in the 2400 block of Camp Springs Road.');
INSERT INTO public.stormevents_east VALUES (743767, 201803, 20, 1830, 201803, 20, 1830, 123930, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'MFL', '20-MAR-18 18:30:00', 'EST-5', '20-MAR-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 7, 'NW', 'KREAMER ISLAND', 7, 'NW', 'KREAMER ISLAND', 26.85, -80.79, 26.85, -80.79, 'A moist and unstable air mass with south southwesterly wind flow across South Florida ahead of a cold front. A line of thunderstorms ahead of an approaching cold front produced gusty winds over Lake Okeechobee and the Atlantic Waters.', 'A marine thunderstorm wind gust of 49 mph / 43 knots was recorded by the SFWMD mesonet site L006 located over the center of Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (779982, 201808, 13, 1633, 201808, 13, 1800, 130278, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'PBZ', '13-AUG-18 16:33:00', 'EST-5', '13-AUG-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'MONTANA', 0, 'ESE', 'MONTANA', 39.5303, -80.1175, 39.5293, -80.1173, 'A lingering upper level low pressure system drifting across Pennsylvania promoted low convective temperatures, allowing numerous showers and thunderstorms to develop, which concentrated near disturbances around the upper low.  Decent instability and strong low-level lapse rates promoted damaging wind gusts.  Moisture overall was not excessive for August, but thanks to weak flow near the upper low, storm motion was generally 10 knots or less.  This promoted a few instances of flash flooding as well.', 'County 911 officials reported flooding along 1st Street where Pharaoh Run enters into the Monongahela River.');
INSERT INTO public.stormevents_east VALUES (779983, 201808, 13, 1450, 201808, 13, 1450, 130278, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'PBZ', '13-AUG-18 14:50:00', 'EST-5', '13-AUG-18 14:50:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'W', 'COLLIERS', 1, 'W', 'COLLIERS', 40.37, -80.54, 40.37, -80.54, 'A lingering upper level low pressure system drifting across Pennsylvania promoted low convective temperatures, allowing numerous showers and thunderstorms to develop, which concentrated near disturbances around the upper low.  Decent instability and strong low-level lapse rates promoted damaging wind gusts.  Moisture overall was not excessive for August, but thanks to weak flow near the upper low, storm motion was generally 10 knots or less.  This promoted a few instances of flash flooding as well.', 'A trained spotter reported that trees were uprooted near Colliers.');
INSERT INTO public.stormevents_east VALUES (779984, 201808, 13, 1458, 201808, 13, 1458, 130278, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'PBZ', '13-AUG-18 14:58:00', 'EST-5', '13-AUG-18 14:58:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SE', 'HALLECK', 1, 'SE', 'HALLECK', 39.46, -79.94, 39.46, -79.94, 'A lingering upper level low pressure system drifting across Pennsylvania promoted low convective temperatures, allowing numerous showers and thunderstorms to develop, which concentrated near disturbances around the upper low.  Decent instability and strong low-level lapse rates promoted damaging wind gusts.  Moisture overall was not excessive for August, but thanks to weak flow near the upper low, storm motion was generally 10 knots or less.  This promoted a few instances of flash flooding as well.', 'The county Department of Highways reported that trees were blown down along Rogers Road.');
INSERT INTO public.stormevents_east VALUES (792303, 201811, 3, 627, 201811, 3, 727, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 06:27:00', 'EST-5', '03-NOV-18 07:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'FRAMINGHAM', 2, 'WNW', 'FRAMINGHAM', 42.2954, -71.4561, 42.2951, -71.4555, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'In Framingham, Route 9 was closed at Oakcrest Drive due to flooding.');
INSERT INTO public.stormevents_east VALUES (792304, 201811, 3, 648, 201811, 3, 748, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 06:48:00', 'EST-5', '03-NOV-18 07:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'DORCHESTER CENTER', 1, 'ENE', 'DORCHESTER CENTER', 42.2896, -71.0462, 42.2896, -71.0459, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'In Dorchester, Morrissey Boulevard at Tolman Street was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (792306, 201811, 3, 655, 201811, 3, 755, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 06:55:00', 'EST-5', '03-NOV-18 07:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'FRANKLIN', 1, 'S', 'FRANKLIN', 42.0655, -71.4037, 42.0656, -71.4032, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'In Franklin, the I-495 exit southbound ramp to King Street was completely flooded and was reaching up to car doors.');
INSERT INTO public.stormevents_east VALUES (792311, 201811, 3, 717, 201811, 3, 817, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 07:17:00', 'EST-5', '03-NOV-18 08:17:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'SOUTH WEYMOUTH NAS', 1, 'NW', 'SOUTH WEYMOUTH NAS', 42.1772, -70.9581, 42.1769, -70.958, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'In South Weymouth, Columbian Street was closed at Nevin Street due to flooding. A car was stuck in the flood waters.');
INSERT INTO public.stormevents_east VALUES (792309, 201811, 3, 710, 201811, 3, 810, 132394, 'MASSACHUSETTS', 25, 2018, 'November', 'Flood', 'BOX', '03-NOV-18 07:10:00', 'EST-5', '03-NOV-18 08:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'KINGSTON', 1, 'N', 'KINGSTON', 41.9973, -70.7344, 41.9973, -70.7343, 'Low pressure over New York City early in the morning on November 3rd rapidly intensified as it moved northeastward across New England.  Heavy rain occurred in the early morning hours, with generally 1.50 to 2.50 inches in eastern sections of southern New England and up to 3.66 inches in the slopes of the Berkshires.  A few severe thunderstorms moved from Rhode Island into eastern Massachusetts around daybreak.  As the strong low passed to our north, strong to damaging westerly winds developed during the afternoon.', 'In Kingston, a car was stuck in two feet of water on Marion Drive near the railroad tracks.');
INSERT INTO public.stormevents_east VALUES (757505, 201805, 10, 1730, 201805, 10, 1730, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 17:30:00', 'EST-5', '10-MAY-18 17:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'WSW', 'CLAREMONT', 1, 'WSW', 'CLAREMONT', 37.22, -76.97, 37.22, -76.97, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed on Spring Grove Avenue.');
INSERT INTO public.stormevents_east VALUES (779387, 201808, 10, 1635, 201808, 10, 1830, 130142, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PBZ', '10-AUG-18 16:35:00', 'EST-5', '10-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ATLASBURG', 1, 'NNW', 'ATLASBURG', 40.3404, -80.3846, 40.3394, -80.3855, 'Showers and thunderstorms formed along a nearly stationary boundary that crept southeastward from the Great Lakes.  Precipitable water values of around 1.6 inches and weak steering flow along the boundary led to a few areas of training thunderstorms.  Rainfall amounts of 1.5 to 3.0 inches on already saturated ground led to several areas of flash flooding in Washington, Allegheny, and Westmoreland Counties.  The worst flooding was near Herminie, where up to 14 homes were impacted and a mobile home was shifted off of its foundation.', 'The post office at 1620 Smith Township State Road was flooded according to the county emergency manager.');
INSERT INTO public.stormevents_east VALUES (778193, 201808, 5, 1507, 201808, 5, 1507, 129906, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PBZ', '05-AUG-18 15:07:00', 'EST-5', '05-AUG-18 15:07:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'SHEARERSBURG', 2, 'WNW', 'SHEARERSBURG', 40.6341, -79.6824, 40.6341, -79.6824, 'Isolated thunderstorms managed to form in a hot and humid pattern.  Weak steering flow led to some localized flash flooding in Allegheny County, and steep lapse rates/high instability combined with dry air aloft to produce hail and wind damage in a few instances.', 'County 911 officials reported that trees were blown down along Garvers Ferry Road.');
INSERT INTO public.stormevents_east VALUES (742617, 201802, 15, 2131, 201802, 16, 1000, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 21:31:00', 'EST-5', '16-FEB-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'INDUSTRY', 1, 'ENE', 'INDUSTRY', 40.6462, -80.416, 40.6538, -80.4057, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Local law enforcement reported that PA Route 68 is closed in Industry due to flooding.');
INSERT INTO public.stormevents_east VALUES (742618, 201802, 15, 2336, 201802, 16, 1400, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 23:36:00', 'EST-5', '16-FEB-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 13, 'SSW', 'LEESBURG', 13, 'SSW', 'LEESBURG', 40.9651, -80.3351, 40.9625, -80.3246, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Emergency manager reported that Pennsylvania Ave and Quarry Road are flooded. Savannah Gardner Road flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (742621, 201802, 15, 1729, 201802, 15, 2230, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 17:29:00', 'EST-5', '15-FEB-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'PRICEDALE', 0, 'SSW', 'PRICEDALE', 40.13, -79.85, 40.1268, -79.8509, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Trained spotter reported that the 600 block of Fayette Street is flooding.');
INSERT INTO public.stormevents_east VALUES (744916, 201803, 17, 2020, 201803, 17, 2020, 124129, 'NORTH CAROLINA', 37, 2018, 'March', 'Thunderstorm Wind', 'GSP', '17-MAR-18 20:20:00', 'EST-5', '17-MAR-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SENIA', 1, 'E', 'SENIA', 36.08, -82.01, 36.08, -82.01, 'Scattered thunderstorms developed within an unseasonably warm and moist environment ahead of a cold front across the Tennessee Valley during the afternoon and moved into western North Carolina during the evening. One storm produced brief damaging winds across Avery County.', 'County comms reported trees blown down off Highway 19E near the Frank community.');
INSERT INTO public.stormevents_east VALUES (761394, 201805, 19, 1900, 201805, 23, 1745, 127034, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '19-MAY-18 19:00:00', 'EST-5', '23-MAY-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ELLERSON', 2, 'ESE', 'MECHANICSVILLE', 37.6188, -77.4155, 37.5823, -77.3334, 'Flooding occurred along the Chickahominy River in central Virginia.', 'Flooding occurred along the Chickahominy River over a couple of days, with roads and low lying areas near the river impacted the most.');
INSERT INTO public.stormevents_east VALUES (761400, 201805, 19, 1900, 201805, 23, 1745, 127034, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '19-MAY-18 19:00:00', 'EST-5', '23-MAY-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'CHAMBERLAYNE FARMS', 2, 'ESE', 'CHAMBERLAYNE FARMS', 37.6015, -77.4005, 37.6075, -77.4022, 'Flooding occurred along the Chickahominy River in central Virginia.', 'Flooding occurred along the Chickahominy River over a couple of days, with roads and low lying areas near the river impacted the most.');
INSERT INTO public.stormevents_east VALUES (744454, 201803, 20, 1402, 201803, 20, 1405, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:02:00', 'EST-5', '20-MAR-18 14:05:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'NW', 'LADSON', 1, 'NW', 'LADSON', 32.99, -80.11, 32.99, -80.11, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A trained spotter reported dime sized hail at the intersection of Ladson Road and Miles Jamison Road. The spotter also reported 30-40 mph winds.');
INSERT INTO public.stormevents_east VALUES (744455, 201803, 20, 1405, 201803, 20, 1408, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:05:00', 'EST-5', '20-MAR-18 14:08:00', 0, 0, 0, 0, NULL, '0.00K', 'CoCoRaHS', 1.75, NULL, NULL, NULL, 1, 'ESE', 'SCOTT', 1, 'ESE', 'SCOTT', 32.34, -80.6, 32.34, -80.6, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A CoCoRaHS volunteer reported hail ranging from the size of quarters to golf balls.');
INSERT INTO public.stormevents_east VALUES (744456, 201803, 20, 1410, 201803, 20, 1413, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:10:00', 'EST-5', '20-MAR-18 14:13:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 1.75, NULL, NULL, NULL, 1, 'SE', 'SCOTT', 1, 'SE', 'SCOTT', 32.34, -80.61, 32.34, -80.61, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A trained spotter reported golf ball sized hail on Saint Helena Island near Cuffee Road.');
INSERT INTO public.stormevents_east VALUES (744457, 201803, 20, 1412, 201803, 20, 1415, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:12:00', 'EST-5', '20-MAR-18 14:15:00', 0, 0, 0, 0, NULL, '0.00K', 'NWS Employee', 1.75, NULL, NULL, NULL, 6, 'SE', 'SUMMERVILLE', 6, 'SE', 'SUMMERVILLE', 32.9464, -80.1138, 32.9464, -80.1138, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'An off duty NWS employee measured hail up to the sized of golf balls.');
INSERT INTO public.stormevents_east VALUES (744461, 201803, 20, 1421, 201803, 20, 1426, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:21:00', 'EST-5', '20-MAR-18 14:26:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 5, 'ENE', 'FROGMORE', 5, 'ENE', 'FROGMORE', 32.43, -80.49, 32.43, -80.49, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A trained spotter reported penny sized hail at Racoon Ridge Road on Saint Helena Island. The hail lasted about 5 minutes.');
INSERT INTO public.stormevents_east VALUES (744462, 201803, 20, 1434, 201803, 20, 1437, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:34:00', 'EST-5', '20-MAR-18 14:37:00', 0, 0, 0, 0, NULL, '0.00K', 'Public', 1, NULL, NULL, NULL, 2, 'SSW', 'ALVIN', 2, 'SSW', 'ALVIN', 33.32, -79.83, 33.32, -79.83, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A report of quarter sized hail was received via the mPING program.');
INSERT INTO public.stormevents_east VALUES (744463, 201803, 20, 1439, 201803, 20, 1442, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:39:00', 'EST-5', '20-MAR-18 14:42:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 1.75, NULL, NULL, NULL, 1, 'ENE', 'EDISTO IS ARPT', 1, 'ENE', 'EDISTO IS ARPT', 32.54, -80.3, 32.54, -80.3, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A trained spotter reported golf ball sized hail near Edisto Island.');
INSERT INTO public.stormevents_east VALUES (744478, 201803, 20, 1421, 201803, 20, 1424, 124051, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Hail', 'CHS', '20-MAR-18 14:21:00', 'EST-5', '20-MAR-18 14:24:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 5, 'NNW', 'HUNTING ISLAND', 5, 'NNW', 'HUNTING ISLAND', 32.4349, -80.4735, 32.4349, -80.4735, 'Inland thunderstorms that developed in the vicinity of a warm front inland moved to the coast and out over the adjacent coastal waters in the early morning hours. Then later in the day, additional thunderstorms impacted the coast and the coastal waters during the afternoon. Some of these thunderstorms became strong enough to produce strong wind gusts and large hail.', 'A trained spotter reported penny sized hail at Racoon Ridge Road on Saint Helena Island. The hail lasted about 5 minutes.');
INSERT INTO public.stormevents_east VALUES (744479, 201803, 20, 1445, 201803, 20, 1447, 124051, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'CHS', '20-MAR-18 14:45:00', 'EST-5', '20-MAR-18 14:47:00', 0, 0, 0, 0, NULL, '0.00K', 'Official NWS Observations', 41, 'MG', NULL, NULL, 5, 'SW', 'SAPELO ISLAND', 5, 'SW', 'SAPELO ISLAND', 31.4178, -81.2954, 31.4178, -81.2954, 'Inland thunderstorms that developed in the vicinity of a warm front inland moved to the coast and out over the adjacent coastal waters in the early morning hours. Then later in the day, additional thunderstorms impacted the coast and the coastal waters during the afternoon. Some of these thunderstorms became strong enough to produce strong wind gusts and large hail.', 'The Sapelo Island NERRS site measured a 41 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (744481, 201803, 20, 1520, 201803, 20, 1530, 124051, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'CHS', '20-MAR-18 15:20:00', 'EST-5', '20-MAR-18 15:30:00', 0, 0, 0, 0, NULL, '0.00K', 'Buoy', 35, 'MG', NULL, NULL, 0, 'NE', 'EDISTO BUOY (41004)', 0, 'NE', 'EDISTO BUOY (41004)', 32.501, -79.099, 32.501, -79.099, 'Inland thunderstorms that developed in the vicinity of a warm front inland moved to the coast and out over the adjacent coastal waters in the early morning hours. Then later in the day, additional thunderstorms impacted the coast and the coastal waters during the afternoon. Some of these thunderstorms became strong enough to produce strong wind gusts and large hail.', 'Buoy 41004 measured a 35 knot wind gust. The peak wind gust of 39 knots occurred 10 minutes later.');
INSERT INTO public.stormevents_east VALUES (744615, 201803, 1, 1912, 201803, 1, 1914, 124072, 'ATLANTIC SOUTH', 87, 2018, 'March', 'Marine Thunderstorm Wind', 'CHS', '01-MAR-18 19:12:00', 'EST-5', '01-MAR-18 19:14:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 2, 'SSW', 'TYBEE ISLAND', 2, 'SSW', 'TYBEE ISLAND', 31.9869, -80.8519, 31.9869, -80.8519, 'A narrow band of showers and embedded thunderstorms developed ahead of a cold front and moved across the southeast Georgia and southeast South Carolina coast in the evening hours. This line of showers and thunderstorms produced strong wind gusts.', 'The Weatherflow site on the south end of Tybee Island measured a 34 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (744619, 201803, 20, 1408, 201803, 20, 1409, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'CHS', '20-MAR-18 14:08:00', 'EST-5', '20-MAR-18 14:09:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 40, 'EG', NULL, NULL, 3, 'ENE', 'ISLANDTON', 3, 'ENE', 'ISLANDTON', 32.9216, -80.8877, 32.9216, -80.8877, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'Colleton County Emergency Management reported a tree down in the 2000 block of Adnah Church Road.');
INSERT INTO public.stormevents_east VALUES (760435, 201805, 14, 2010, 201805, 14, 2010, 126825, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:10:00', 'EST-5', '14-MAY-18 20:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 0, 'N', 'THIMBLE SHOALS', 0, 'N', 'THIMBLE SHOALS', 37.05, -76.26, 37.05, -76.26, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 43 knots was measured at Thimble Shoals.');
INSERT INTO public.stormevents_east VALUES (760438, 201805, 14, 2012, 201805, 14, 2012, 126825, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:12:00', 'EST-5', '14-MAY-18 20:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 37.54, -76.02, 37.54, -76.02, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 36 knots was measured at Rappahannock Light.');
INSERT INTO public.stormevents_east VALUES (732932, 201803, 1, 1708, 201803, 1, 1710, 122414, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'CAE', '01-MAR-18 17:08:00', 'EST-5', '01-MAR-18 17:10:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 55, 'EG', NULL, NULL, 7, 'S', 'ST PAUL', 7, 'S', 'ST PAUL', 33.48, -80.39, 33.48, -80.39, 'Weak instability coupled with strong shear and a strong low level jet allowed scattered heavy showers to develop along and ahead of a cold front, some of which produced severe damaging wind gusts.', 'SC DOT reported trees down on Francis Marion Blvd at Benton Rd.');
INSERT INTO public.stormevents_east VALUES (732933, 201803, 1, 1713, 201803, 1, 1715, 122414, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'CAE', '01-MAR-18 17:13:00', 'EST-5', '01-MAR-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 55, 'EG', NULL, NULL, 1, 'WSW', 'BLOOMVILLE', 1, 'WSW', 'BLOOMVILLE', 33.62, -80.19, 33.62, -80.19, 'Weak instability coupled with strong shear and a strong low level jet allowed scattered heavy showers to develop along and ahead of a cold front, some of which produced severe damaging wind gusts.', 'SC DOT reported a tree on the roadway on Raccoon Rd.');
INSERT INTO public.stormevents_east VALUES (744470, 201803, 20, 1410, 201803, 20, 1413, 124050, 'GEORGIA', 13, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 14:10:00', 'EST-5', '20-MAR-18 14:13:00', 0, 0, 0, 0, NULL, '0.00K', 'Public', 0.75, NULL, NULL, NULL, 2, 'NNW', 'TOWNSEND', 2, 'NNW', 'TOWNSEND', 31.56, -81.55, 31.56, -81.55, 'A large area of thunderstorms develop upstream of the southeast Georgia region and moved through during the early morning hours in the vicinity of a warm front. A few of these thunderstorms became strong enough to produce damaging wind gusts across interior portions of southeast Georgia. Then in the afternoon, additional thunderstorms developed ahead of a strong cold front, mainly impacting coastal areas of southeast Georgia.', 'Penny sized hail was reported at the Townsend Bombing Range.');
INSERT INTO public.stormevents_east VALUES (772191, 201807, 24, 954, 201807, 24, 954, 128756, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '24-JUL-18 09:54:00', 'EST-5', '24-JUL-18 09:54:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 3, 'S', 'MID BAY BUOY', 3, 'S', 'MID BAY BUOY', 38.432, -76.387, 38.432, -76.387, 'A cutoff low from the jet stream remained just to our west on the 24th. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts in excess of 30 knots were reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (772192, 201807, 24, 1000, 201807, 24, 1000, 128756, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '24-JUL-18 10:00:00', 'EST-5', '24-JUL-18 10:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A cutoff low from the jet stream remained just to our west on the 24th. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust of 34 knots was reported at Thomas Point Lighthouse.');
INSERT INTO public.stormevents_east VALUES (772195, 201807, 27, 1246, 201807, 27, 1321, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 12:46:00', 'EST-5', '27-JUL-18 13:21:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'MONROE CREEK (MON)', 0, 'N', 'MONROE CREEK (MON)', 38.23, -76.95, 38.23, -76.95, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts up to 36 knots were reported at Monroe Creek.');
INSERT INTO public.stormevents_east VALUES (744464, 201803, 20, 1502, 201803, 20, 1505, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 15:02:00', 'EST-5', '20-MAR-18 15:05:00', 0, 0, 0, 0, NULL, '0.00K', 'Public', 0.75, NULL, NULL, NULL, 1, 'W', 'CHARLESTON', 1, 'W', 'CHARLESTON', 32.78, -79.94, 32.78, -79.94, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'Penny sized hail was reported on King Street between George and Calhoun Streets.');
INSERT INTO public.stormevents_east VALUES (744465, 201803, 20, 1640, 201803, 20, 1643, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 16:40:00', 'EST-5', '20-MAR-18 16:43:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 2, 'NW', 'JEDBURG', 2, 'NW', 'JEDBURG', 33.07, -80.26, 33.07, -80.26, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A trained spotter reported hail ranging from pea to dime sized near Jedburg.');
INSERT INTO public.stormevents_east VALUES (744466, 201803, 20, 1655, 201803, 20, 1658, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 16:55:00', 'EST-5', '20-MAR-18 16:58:00', 0, 0, 0, 0, NULL, '0.00K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 4, 'WNW', 'MONCKS CORNER ARPT', 4, 'WNW', 'MONCKS CORNER ARPT', 33.2, -80.09, 33.2, -80.09, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'A trained spotter located near Pinopolis reported penny to nickel sized hail.');
INSERT INTO public.stormevents_east VALUES (744467, 201803, 20, 1658, 201803, 20, 1701, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Hail', 'CHS', '20-MAR-18 16:58:00', 'EST-5', '20-MAR-18 17:01:00', 0, 0, 0, 0, NULL, '0.00K', '911 Call Center', 1, NULL, NULL, NULL, 1, 'ESE', 'MONCKS CORNER', 1, 'ESE', 'MONCKS CORNER', 33.19, -80, 33.19, -80, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'Berkeley County dispatch reported quarter sized hail at their office.');
INSERT INTO public.stormevents_east VALUES (744468, 201803, 20, 1425, 201803, 20, 1426, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'CHS', '20-MAR-18 14:25:00', 'EST-5', '20-MAR-18 14:26:00', 0, 0, 0, 0, NULL, '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 6, 'E', 'CANADYS', 6, 'E', 'CANADYS', 33.05, -80.51, 33.05, -80.51, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'South Carolina Highway Patrol reported 2 trees down near the intersection of Highway 61 and Arrowhead lane.');
INSERT INTO public.stormevents_east VALUES (744469, 201803, 20, 1640, 201803, 20, 1641, 124049, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'CHS', '20-MAR-18 16:40:00', 'EST-5', '20-MAR-18 16:41:00', 0, 0, 0, 0, NULL, '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'JEDBURG', 1, 'W', 'JEDBURG', 33.05, -80.25, 33.05, -80.25, 'Clusters of thunderstorms developed across portions of southeast South Carolina in the afternoon hours ahead of a strong cold front. Several of these thunderstorms became strong enough to produce damaging wind gusts and large hail.', 'South Carolina Highway Patrol reported a tree down on Orangeburg Road in front of the Blackberry Creek subdivision.');
