INSERT INTO public.stormevents_east VALUES (732934, 201803, 1, 1622, 201803, 1, 1625, 122414, 'SOUTH CAROLINA', 45, 2018, 'March', 'Thunderstorm Wind', 'CAE', '01-MAR-18 16:22:00', 'EST-5', '01-MAR-18 16:25:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'ENE', 'BRENT', 1, 'ENE', 'BRENT', 34.03, -80.33, 34.03, -80.33, 'Weak instability coupled with strong shear and a strong low level jet allowed scattered heavy showers to develop along and ahead of a cold front, some of which produced severe damaging wind gusts.', 'Military meteorologist/trained spotter estimated wind gusts at 60 MPH. Power outage in the area occurred at 1625 EST shortly after the peak winds.');
