INSERT INTO public.stormevents_east VALUES (743094, 201804, 3, 1953, 201804, 3, 1953, 123840, 'WEST VIRGINIA', 54, 2018, 'April', 'Thunderstorm Wind', 'RLX', '03-APR-18 19:53:00', 'EST-5', '03-APR-18 19:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 55, 'MG', NULL, NULL, 0, 'N', 'FLATROCK', 0, 'N', 'FLATROCK', 38.85, -82.02, 38.85, -82.02, 'A warm front lifted across the middle Ohio River Valley and central Appalachians on the morning of the 3rd. This brought a round of showers and thunderstorms. Showers lingered along the US 50 corridor through much of the day with the warm front in the vicinity. A strong cold front then pushed through in the evening with strong to severe thunderstorms. Periods of heavy rain, first with the warm front, and then again with the cold front led to flooding.', NULL);
INSERT INTO public.stormevents_east VALUES (738602, 201804, 4, 139, 201804, 4, 139, 123185, 'TENNESSEE', 47, 2018, 'April', 'Thunderstorm Wind', 'MRX', '04-APR-18 01:39:00', 'EST-5', '04-APR-18 01:39:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 3, 'W', 'PETTYJOHNS MILL', 3, 'W', 'PETTYJOHNS MILL', 36.53, -82.5, 36.53, -82.5, 'A strong low pressure system moved northeast out of the Midwest into the Eastern Great Lakes while pulling colder air southeast across the Southern Appalachian region. Severe convection developed ahead of the front generating wind gusts strong enough to down trees and produce some limited structural damage to homes. The damage reports were mainly over the higher Cumberland Plateau terrain.', 'A tree fell onto a home off Mountain View Avenue.');
INSERT INTO public.stormevents_east VALUES (738603, 201804, 4, 110, 201804, 4, 110, 123186, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'MRX', '04-APR-18 01:10:00', 'EST-5', '04-APR-18 01:10:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'WNW', 'JONESVILLE', 1, 'WNW', 'JONESVILLE', 36.69, -83.12, 36.69, -83.12, 'A strong low pressure system moved northeast out of the Midwest into the Eastern Great Lakes while pulling colder air southeast across the Southern Appalachian region. Severe convection developed ahead of the front generating wind gusts strong enough to down trees and produce some limited structural damage to homes. The damage reports were mainly over the higher Cumberland Plateau terrain.', 'Several trees and power lines were reported down.');
INSERT INTO public.stormevents_east VALUES (738604, 201804, 4, 140, 201804, 4, 140, 123186, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'MRX', '04-APR-18 01:40:00', 'EST-5', '04-APR-18 01:40:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'ABINGDON', 1, 'E', 'ABINGDON', 36.71, -81.97, 36.71, -81.97, 'A strong low pressure system moved northeast out of the Midwest into the Eastern Great Lakes while pulling colder air southeast across the Southern Appalachian region. Severe convection developed ahead of the front generating wind gusts strong enough to down trees and produce some limited structural damage to homes. The damage reports were mainly over the higher Cumberland Plateau terrain.', 'Numerous trees were reported down, especially across the northern part of the county.');
INSERT INTO public.stormevents_east VALUES (742859, 201804, 3, 1643, 201804, 3, 1648, 123573, 'OHIO', 39, 2018, 'April', 'Hail', 'ILN', '03-APR-18 16:43:00', 'EST-5', '03-APR-18 16:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.25, NULL, NULL, NULL, 0, 'ENE', 'GROVE CITY', 0, 'ENE', 'GROVE CITY', 39.8812, -83.0765, 39.8812, -83.0765, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', NULL);
