INSERT INTO public.stormevents_east VALUES (749797, 201804, 15, 1200, 201804, 15, 1200, 124999, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'JAX', '15-APR-18 12:00:00', 'EST-5', '15-APR-18 12:00:00', 0, 0, 0, 0, '0.20K', '0.00K', 'Law Enforcement', 45, 'EG', NULL, NULL, 1, 'W', 'JESUP', 1, 'W', 'JESUP', 31.6, -81.89, 31.6, -81.89, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'A tree was blown down along South Macon Street. The time of damage was based on radar.  The cost of damage was unknown but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (749798, 201804, 15, 1400, 201804, 15, 1400, 124999, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'JAX', '15-APR-18 14:00:00', 'EST-5', '15-APR-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'HARRIETS BLUFF', 1, 'W', 'HARRIETS BLUFF', 30.87, -81.59, 30.87, -81.59, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'A tree was blown down in a backyard in Harrietts Bluff.');
INSERT INTO public.stormevents_east VALUES (749943, 201804, 15, 1430, 201804, 15, 1430, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:30:00', 'EST-5', '15-APR-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', 36, 'MG', NULL, NULL, 6, 'W', 'MAYPORT NAS', 6, 'W', 'MAYPORT NAS', 30.39, -81.52, 30.39, -81.52, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The NOS station at Blount Island Command measured a wind gust of 42 mph.');
INSERT INTO public.stormevents_east VALUES (749944, 201804, 15, 1440, 201804, 15, 1440, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:40:00', 'EST-5', '15-APR-18 14:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 4, 'W', 'MAYPORT NAS', 4, 'W', 'MAYPORT NAS', 30.39, -81.48, 30.39, -81.48, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The WeatherFlow sensor at Buck Island measured a thunderstorm squall line gust of 40 mph.');
INSERT INTO public.stormevents_east VALUES (742209, 201804, 15, 1453, 201804, 15, 1653, 123710, 'OHIO', 39, 2018, 'April', 'Flood', 'ILN', '15-APR-18 14:53:00', 'EST-5', '15-APR-18 16:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CHILLICOTHE', 0, 'SSE', 'CHILLICOTHE', 39.34, -82.99, 39.3244, -82.977, 'Showers and thunderstorms which produced heavy rain, developed ahead of potent surface low.', 'Minor flooding was reported with water over some area roadways.');
INSERT INTO public.stormevents_east VALUES (744440, 201804, 15, 1147, 201804, 15, 1147, 124046, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 11:47:00', 'EST-5', '15-APR-18 11:47:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'SW', 'PEACH ORCHARD', 1, 'SW', 'PEACH ORCHARD', 33.42, -82.03, 33.42, -82.03, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Power lines down on Anne St.');
INSERT INTO public.stormevents_east VALUES (744441, 201804, 15, 1149, 201804, 15, 1149, 124046, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 11:49:00', 'EST-5', '15-APR-18 11:49:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'S', 'SOUTH NELLIEVILLE', 1, 'S', 'SOUTH NELLIEVILLE', 33.45, -82, 33.45, -82, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trees down on power lines on Hollis Rd.');
INSERT INTO public.stormevents_east VALUES (744442, 201804, 15, 1212, 201804, 15, 1212, 124046, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 12:12:00', 'EST-5', '15-APR-18 12:12:00', 0, 0, 0, 0, '0.10K', '0.10K', 'ASOS', 45, 'MG', NULL, NULL, 0, 'ESE', '(AGS)BUSH FLD AUGUST', 0, 'ESE', '(AGS)BUSH FLD AUGUST', 33.3683, -81.9648, 33.3683, -81.9648, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'ASOS unit at Augusta GA Bush Field airport measured a peak wind gust of 52 mph.');
INSERT INTO public.stormevents_east VALUES (743109, 201804, 3, 2248, 201804, 3, 2248, 123841, 'KENTUCKY', 21, 2018, 'April', 'Thunderstorm Wind', 'RLX', '03-APR-18 22:48:00', 'EST-5', '03-APR-18 22:48:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'NE', 'MARTHA', 1, 'NE', 'MARTHA', 38.01, -82.91, 38.01, -82.91, 'A strong cold front pushed through on the evening of the 3rd, driving a line of strong to severe thunderstorms through northeastern Kentucky.', 'Multiple large tree limbs were blown down along Highway 32.');
INSERT INTO public.stormevents_east VALUES (743246, 201804, 15, 2245, 201804, 16, 1100, 123859, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '15-APR-18 22:45:00', 'EST-5', '16-APR-18 11:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'CARBONDALE', 1, 'N', 'EAST CLAYTON', 39.4094, -82.2599, 39.466, -82.2504, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. One to two inches of rain fell across most of southeast Ohio, resulting in flooding.', 'Flooding along Minkers Run caused high water on Kimberly Road.');
INSERT INTO public.stormevents_east VALUES (743247, 201804, 15, 2335, 201804, 16, 1200, 123859, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '15-APR-18 23:35:00', 'EST-5', '16-APR-18 12:00:00', 0, 0, 0, 0, '20.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'ZIONTOWN', 3, 'NW', 'GLENFORD', 39.854, -82.364, 39.9117, -82.3504, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. One to two inches of rain fell across most of southeast Ohio, resulting in flooding.', 'Near the intersection of Mount Perry Road and Coopermill Road, flooding along Painter Run caused the road to collapse. Flooding along Jonathan Creek cause high water on State Route 204 near Glass Rock Road.');
INSERT INTO public.stormevents_east VALUES (743256, 201804, 16, 553, 201804, 16, 1448, 123859, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '16-APR-18 05:53:00', 'EST-5', '16-APR-18 14:48:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'BECKETT', 2, 'W', 'WATERFORD', 39.5797, -81.6971, 39.5298, -81.6692, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. One to two inches of rain fell across most of southeast Ohio, resulting in flooding.', 'Low areas along the Muskingum River near Beverly flooded as the Muskingum River crested half a foot above flood stage. The river rose above its 29 foot flood stage just before sunrise on the 16th. It crested during the mid afternoon at 29.5 feet and then returned to within its banks early that evening.');
INSERT INTO public.stormevents_east VALUES (743258, 201804, 17, 1615, 201804, 19, 942, 123859, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '17-APR-18 16:15:00', 'EST-5', '19-APR-18 09:42:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 21, 'SSW', 'PRATTS FORK', 21, 'SSW', 'PRATTS FORK', 38.8974, -82.1413, 38.9032, -82.1617, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. One to two inches of rain fell across most of southeast Ohio, resulting in flooding.', 'For the second time in the month of April, the Ohio River flooded causing water to spill onto Addison Pike near Addison. The Point Pleasant, WV river gage showed the river rose above its 40 foot flood stage late afternoon of the 17th. It crested at just over 42 feet around noon on the 16th and then returned to below flood stage mid morning on the 19th.');
INSERT INTO public.stormevents_east VALUES (743261, 201804, 15, 2017, 201804, 16, 830, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Flood', 'RLX', '15-APR-18 20:17:00', 'EST-5', '16-APR-18 08:30:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'PANTHER', 1, 'NNE', 'LITWAR', 37.4493, -81.937, 37.4862, -81.8251, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'Rocket Boys Drive and Frog Level Road were closed in the Coalwood area due to flooding on Clear Fork and Snakeroot Branch. John''s Branch Road was closed near War due to high water on John''s Branch.||The Dry Fork at Bradshaw also rose out of its banks early on the 16th, causing minor flooding in some homes along the river. The gage showed the river crested half a foot above its flood stage of 10 feet a couple hours before sunrise on the 16th. It was back within its banks just after sunrise.');
INSERT INTO public.stormevents_east VALUES (749711, 201804, 16, 1013, 201804, 16, 1045, 125008, 'NEW YORK', 36, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 10:13:00', 'EST-5', '16-APR-18 10:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'CENTRAL PARK', 2, 'NW', 'CENTRAL PARK', 40.7958, -73.976, 40.7962, -73.9771, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 1.5 to 3.5 inches across much of New York City and the Lower Hudson Valley, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'The southbound lanes of the Henry Hudson Parkway were closed at West 96th Street in Bloomingdale due to flooding.');
INSERT INTO public.stormevents_east VALUES (749712, 201804, 16, 1027, 201804, 16, 1045, 125008, 'NEW YORK', 36, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 10:27:00', 'EST-5', '16-APR-18 10:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'WOODSIDE', 1, 'NE', 'WOODSIDE', 40.7668, -73.9029, 40.7673, -73.9039, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 1.5 to 3.5 inches across much of New York City and the Lower Hudson Valley, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'The Grand Central Parkway was closed in both directions at 48th Street in Astoria due to flooding.');
INSERT INTO public.stormevents_east VALUES (749766, 201804, 16, 1200, 201804, 16, 1234, 125020, 'CONNECTICUT', 9, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 12:00:00', 'EST-5', '16-APR-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'MONTOWESE', 2, 'S', 'MONTOWESE', 41.3166, -72.8765, 41.3168, -72.877, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 2.0 to 4.0 inches across southern Connecticut, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'Quinnipiac Avenue was closed due to flooding near Foxon Street and Hemingway Creek in New Haven.');
INSERT INTO public.stormevents_east VALUES (749767, 201804, 16, 1115, 201804, 16, 1234, 125020, 'CONNECTICUT', 9, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 11:15:00', 'EST-5', '16-APR-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'STRATFORD', 1, 'SSW', 'STRATFORD', 41.1833, -73.1546, 41.1837, -73.1549, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 2.0 to 4.0 inches across southern Connecticut, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'The intersection of Bruce Avenue and Stratford Avenue was closed due to flooding in Stratford.');
INSERT INTO public.stormevents_east VALUES (749768, 201804, 16, 1115, 201804, 16, 1234, 125020, 'CONNECTICUT', 9, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 11:15:00', 'EST-5', '16-APR-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', '(BDR)BRIDGEPORT MEM', 1, 'WNW', '(BDR)BRIDGEPORT MEM', 41.1738, -73.1552, 41.1742, -73.1556, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 2.0 to 4.0 inches across southern Connecticut, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'The entrance ramp to I-95 from Surf Avenue in Bridgeport was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (744424, 201804, 15, 1452, 201804, 15, 1500, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 14:52:00', 'EST-5', '15-APR-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 3, 'SW', 'QUINTS XRDS', 3, 'SW', 'QUINTS XRDS', 33.95, -80.39, 33.95, -80.39, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'County dispatch reported trees and power lines down in multiple locations including Wedgefield Rd and Oakland Ave, Wedgefield Rd and Sandalwood Lane, Alice Dr and Wesmark, Catchall Rd, and Colony Rd at US Hwy 15. An awning of a gas station on Alice Dr was heavily damaged. Time estimated.');
INSERT INTO public.stormevents_east VALUES (742195, 201804, 3, 1637, 201804, 3, 1647, 123573, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'ILN', '03-APR-18 16:37:00', 'EST-5', '03-APR-18 16:47:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SE', 'GROVE CITY', 1, 'SE', 'GROVE CITY', 39.87, -83.07, 39.87, -83.07, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'Multiple utility poles were knocked down.');
INSERT INTO public.stormevents_east VALUES (742171, 201804, 3, 1647, 201804, 3, 1652, 123573, 'OHIO', 39, 2018, 'April', 'Hail', 'ILN', '03-APR-18 16:47:00', 'EST-5', '03-APR-18 16:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 1, NULL, NULL, NULL, 0, 'N', 'GROVEPORT', 0, 'N', 'GROVEPORT', 39.85, -82.88, 39.85, -82.88, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', NULL);
INSERT INTO public.stormevents_east VALUES (743062, 201804, 3, 1030, 201804, 3, 1330, 123684, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '03-APR-18 10:30:00', 'EST-5', '03-APR-18 13:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'HARRISBURG', 3, 'WSW', 'VINTON', 38.9133, -82.3927, 38.958, -82.3772, 'A warm front lifted across the middle Ohio River Valley on the morning of the 3rd. This brought a round of showers and thunderstorms. Showers lingered across central and eastern Ohio through much of the day with the warm front in the vicinity. A strong cold front then pushed through in the evening with strong to severe thunderstorms. Periods of heavy rain, first with the warm front, and then again with the cold front led to flooding.', 'State Route 325 was closed around Vinton due to flooding along Deer Creek.');
INSERT INTO public.stormevents_east VALUES (742415, 201804, 15, 1530, 201804, 15, 1530, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '15-APR-18 15:30:00', 'EST-5', '15-APR-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 43, 'MG', NULL, NULL, 27, 'WSW', 'SARASOTA BEACH', 27, 'WSW', 'SARASOTA BEACH', 27.173, -82.924, 27.173, -82.924, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'The COMPS buoy C10 off of Longboat Key (42013) recorded a 43 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (744425, 201804, 15, 1318, 201804, 15, 1318, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:18:00', 'EST-5', '15-APR-18 13:18:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'WNW', 'ST ANDREWS', 3, 'WNW', 'ST ANDREWS', 34.04, -81.13, 34.04, -81.13, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trees down in roadway at Ashland Rd and Marydale Lane.');
INSERT INTO public.stormevents_east VALUES (744422, 201804, 15, 1318, 201804, 15, 1318, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:18:00', 'EST-5', '15-APR-18 13:18:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 2, 'SSW', 'MONTGOMERY', 2, 'SSW', 'MONTGOMERY', 34.1, -81.15, 34.1, -81.15, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Tree fell on a house in the Riverwalk neighborhood near Irmo. Photos of damage received via social media. Time estimated.');
INSERT INTO public.stormevents_east VALUES (744426, 201804, 15, 1456, 201804, 15, 1456, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 14:56:00', 'EST-5', '15-APR-18 14:56:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 0, 'N', 'PAGELAND', 0, 'N', 'PAGELAND', 34.77, -80.38, 34.77, -80.38, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trees down in Pageland.');
INSERT INTO public.stormevents_east VALUES (744427, 201804, 15, 1528, 201804, 15, 1530, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 15:28:00', 'EST-5', '15-APR-18 15:30:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 1, 'W', 'CHESTERFIELD', 1, 'W', 'CHESTERFIELD', 34.73, -80.09, 34.73, -80.09, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trees down in downtown Chesterfield.');
INSERT INTO public.stormevents_east VALUES (744428, 201804, 15, 1336, 201804, 15, 1336, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:36:00', 'EST-5', '15-APR-18 13:36:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 60, 'EG', NULL, NULL, 5, 'SSW', 'SIMPSON', 5, 'SSW', 'SIMPSON', 34.23, -81.07, 34.23, -81.07, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trained spotter reported multiple trees down along US Hwy 321 just north of the  Fairfield/Richland Co line. Time estimated.');
INSERT INTO public.stormevents_east VALUES (744429, 201804, 15, 1326, 201804, 15, 1326, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:26:00', 'EST-5', '15-APR-18 13:26:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'NW', 'FAIRWOLD', 2, 'NW', 'FAIRWOLD', 34.09, -81.03, 34.09, -81.03, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Power lines down on Fairfield Rd and on Lincolnshire Blvd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (742178, 201804, 3, 1545, 201804, 3, 1550, 123573, 'OHIO', 39, 2018, 'April', 'Tornado', 'ILN', '03-APR-18 15:45:00', 'EST-5', '03-APR-18 15:50:00', 0, 0, 0, 0, '500.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SSE', 'BRYON', 3, 'E', 'YELLOW SPGS', 39.7473, -83.971, 39.7939, -83.8229, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'The tornado first touched down in the 1000 block of Ludlow Road in Beavercreek Township. One barn on the property had roof damage, while the other barn had wall damage. In addition, a silo collapsed. Numerous hardwood and softwood trees were damaged and there was roof and chimney damage to the home. This damage was consistent with low end EF1/high end EF0 damage, with wind estimated at 85 to 90 mph.||Several properties further east along Ludlow Road sustained damage. The most significant being in the 800 block, where a home sustained more than 30 percent of its roof torn off, multiple broken windows, and structural damage to both the exterior and interior walls of the home. Damage to the home was consistent with wind speeds of 90 to 95 mph, EF1 category. Additional significant barn and tree damage occurred on the property.||Further east on Ludlow Road, in the 700 to 500 block, several homes sustained roof damage, with significant damage to barns. Such damage was consistent with high end EF0 damage of 75 to 80 mph.||The tornado continued eastward in the 2400 North Block of U.S. 68. A home received minor siding and roof damage as well as a collapsed chimney, with a fence also destroyed. A large camper was rolled over and the roof was lifted off a brick outbuilding. Damage to this property was consistent with EF1 strength of near 90 mph.||Further east along Clifton Road, structural damage occurred to barns along with roof and porch damage to homes in the 700 and 800 block of Clifton Road. Damage in this area was consistent with EF0 damage of about 75 mph.||Damage became more significant further northeast along Clifton Road, where substantial damage occurred to several barns, along with snapped softwood and hardwood trees. In addition, significant roof and siding damage was present on the residences of two homes in the 2400 block of Clifton Road. Damage here was consistent with low end EF1 between 86 and 90 mph. A sheep farm in this area did experience the loss of five sheep.||The northern most extent of confirmed tornado damage was along State Route 72 and Clifton Road. While there was widespread tree and roof damage along Wilberforce-Clifton Road and State Route 72 south of Clifton, this damage was all in the same direction to the north-northeast, without substantial evidence of back-splatter as associated with rotation. While the wind damage was significant in this area, estimated to be as high as 80 mph, this damage was more consistent with straight line wind damage.');
INSERT INTO public.stormevents_east VALUES (742181, 201804, 3, 1614, 201804, 3, 1615, 123573, 'OHIO', 39, 2018, 'April', 'Tornado', 'ILN', '03-APR-18 16:14:00', 'EST-5', '03-APR-18 16:15:00', 0, 0, 0, 0, '60.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'NNW', 'NEWPORT', 2, 'NNW', 'NEWPORT', 39.8588, -83.4949, 39.8603, -83.4924, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'The tornado appears to have touched down at a farm on Roberts Mill Road, where several barns sustained heavy damage. These barns had complete roof removal and the collapse of exterior walls. Barn roofing and wall material was thrown west- northwest across Roberts Mill Road into the tops of trees of adjacent properties, and strewn across fields on the west side of Roberts Mill Road. The damage is consistent with wind speeds around 85 mph.||Other barn damage observed on State Route 38 south of Newport, Old Xenia Road SW south of London, and on State Route 56 southeast of London, was all determined to be nontornadic with no conclusive components of typical tornado damage.');
INSERT INTO public.stormevents_east VALUES (742874, 201804, 3, 1638, 201804, 3, 1648, 123573, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'ILN', '03-APR-18 16:38:00', 'EST-5', '03-APR-18 16:48:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 3, 'WNW', 'HANFORD', 3, 'WNW', 'HANFORD', 39.9643, -82.9748, 39.9643, -82.9748, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'A significant part of a building''s roof was blown off, with slate tiles embedded in the ground 6 inches. Also, a couple of other homes had chimneys collapse.');
INSERT INTO public.stormevents_east VALUES (749290, 201804, 15, 1825, 201804, 15, 1826, 124543, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'ILM', '15-APR-18 18:25:00', 'EST-5', '15-APR-18 18:26:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'SE', 'SATTERS DEPOT', 1, 'SE', 'SATTERS DEPOT', 33.5885, -79.8389, 33.5885, -79.8389, 'An anomalously deep upper trough became negatively tilted as it moved through the eastern Carolinas. A squall line raced northeast ahead of a cold front and was enhanced by ample instability and strong shear.', 'A tree was reported down along U.S. 521 between Highway 377 and N Columbia Rd.');
INSERT INTO public.stormevents_east VALUES (749292, 201804, 15, 1857, 201804, 15, 1858, 124543, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'ILM', '15-APR-18 18:57:00', 'EST-5', '15-APR-18 18:58:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'SE', 'RED HILL', 1, 'SE', 'RED HILL', 33.5589, -79.4148, 33.5589, -79.4148, 'An anomalously deep upper trough became negatively tilted as it moved through the eastern Carolinas. A squall line raced northeast ahead of a cold front and was enhanced by ample instability and strong shear.', 'A tree was reported down along Browns Ferry Rd. about a mile west of Browns Ferry Bridge.');
INSERT INTO public.stormevents_east VALUES (749293, 201804, 15, 1903, 201804, 15, 1904, 124543, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'ILM', '15-APR-18 19:03:00', 'EST-5', '15-APR-18 19:04:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 2, 'ENE', 'GRESHAM', 2, 'ENE', 'GRESHAM', 33.9268, -79.3898, 33.9268, -79.3898, 'An anomalously deep upper trough became negatively tilted as it moved through the eastern Carolinas. A squall line raced northeast ahead of a cold front and was enhanced by ample instability and strong shear.', 'A tree was reported down along Highway 41.');
INSERT INTO public.stormevents_east VALUES (749294, 201804, 15, 1903, 201804, 15, 1904, 124543, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'ILM', '15-APR-18 19:03:00', 'EST-5', '15-APR-18 19:04:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'NW', 'MILL BRANCH', 0, 'NW', 'MILL BRANCH', 34.0727, -79.5539, 34.0727, -79.5539, 'An anomalously deep upper trough became negatively tilted as it moved through the eastern Carolinas. A squall line raced northeast ahead of a cold front and was enhanced by ample instability and strong shear.', 'A tree was reported down along Willow Grove Rd.');
INSERT INTO public.stormevents_east VALUES (749295, 201804, 15, 1930, 201804, 15, 1931, 124543, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'ILM', '15-APR-18 19:30:00', 'EST-5', '15-APR-18 19:31:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'E', 'NICHOLS', 0, 'E', 'NICHOLS', 34.2305, -79.1443, 34.2305, -79.1443, 'An anomalously deep upper trough became negatively tilted as it moved through the eastern Carolinas. A squall line raced northeast ahead of a cold front and was enhanced by ample instability and strong shear.', 'A tree was reported down along Highway 9 near Sunny Mart.');
INSERT INTO public.stormevents_east VALUES (748094, 201804, 15, 1405, 201804, 15, 1405, 124686, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'MLB', '15-APR-18 14:05:00', 'EST-5', '15-APR-18 14:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', 48, 'EG', NULL, NULL, 2, 'SSE', 'PINE HILLS', 2, 'SSE', 'PINE HILLS', 28.52, -81.42, 28.52, -81.42, 'The Storm Prediction Center had designated a slight change of severe weather for all of east central Florida. A high amplitude shortwave over the Mississippi River Valley quickly moved south across the Florida peninsula during the afternoon and evening hours. A cold front associated with the intensifying trough was also observed crossing the Florida peninsula. Ahead of the cold front moderate thermodynamic instability with 700mb temperatures between -7 to -8 degrees Celsius, and 500mb between -9 to -10 degrees Celsius, resulting in lapse rates of 6-6.5 C/km. 90 knot winds atop a het streak over the north central Gulf of Mexico created resulting flow from the southwest. Numerous showers and thunderstorms developed along the cold front, eventually forming a line that crossed across all of east central Florida. Several thunderstorms became severe and produced wind damage in Orange and Volusia counties, as well as severe winds in Brevard and Indian River counties.', 'Pictures relayed by local broadcast media shows a large tree that fell on a car and caused power outages in the area. Winds were estimated at 50-55 mph with the strong storm.');
INSERT INTO public.stormevents_east VALUES (748088, 201804, 15, 1551, 201804, 15, 1551, 124686, 'FLORIDA', 12, 2018, 'April', 'Hail', 'MLB', '15-APR-18 15:51:00', 'EST-5', '15-APR-18 15:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 2, 'W', '(VRB)VERO BEACH MUNI', 2, 'W', '(VRB)VERO BEACH MUNI', 27.6461, -80.4466, 27.6461, -80.4466, 'The Storm Prediction Center had designated a slight change of severe weather for all of east central Florida. A high amplitude shortwave over the Mississippi River Valley quickly moved south across the Florida peninsula during the afternoon and evening hours. A cold front associated with the intensifying trough was also observed crossing the Florida peninsula. Ahead of the cold front moderate thermodynamic instability with 700mb temperatures between -7 to -8 degrees Celsius, and 500mb between -9 to -10 degrees Celsius, resulting in lapse rates of 6-6.5 C/km. 90 knot winds atop a het streak over the north central Gulf of Mexico created resulting flow from the southwest. Numerous showers and thunderstorms developed along the cold front, eventually forming a line that crossed across all of east central Florida. Several thunderstorms became severe and produced wind damage in Orange and Volusia counties, as well as severe winds in Brevard and Indian River counties.', 'A trained spotter reported penny sized hail in Vero Beach near the intersection of 26th Street and 58th Avenue.');
INSERT INTO public.stormevents_east VALUES (752833, 201804, 15, 1801, 201804, 15, 1805, 124836, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'CHS', '15-APR-18 18:01:00', 'EST-5', '15-APR-18 18:05:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'A strong cold front pushed into an area of high instability, helping produce a squall line of strong to severe thunderstorms over the coastal waters.', 'The Weatherflow site at Fort Sumter measured a 38 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (752834, 201804, 15, 1806, 201804, 15, 1807, 124836, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'CHS', '15-APR-18 18:06:00', 'EST-5', '15-APR-18 18:07:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 44, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'A strong cold front pushed into an area of high instability, helping produce a squall line of strong to severe thunderstorms over the coastal waters.', 'The Weatherflow site at Fort Sumter measured a peak wind gust of 44 knots.');
INSERT INTO public.stormevents_east VALUES (748073, 201804, 15, 1710, 201804, 15, 1710, 124679, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MLB', '15-APR-18 17:10:00', 'EST-5', '15-APR-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 39, 'MG', NULL, NULL, 0, 'N', 'BUOY 41009', 0, 'N', 'BUOY 41009', 28.52, -80.17, 28.52, -80.17, 'The Storm Prediction Center had designated a slight change of severe weather for all of east central Florida. A high amplitude shortwave over the Mississippi River Valley quickly moved south across the Florida peninsula during the afternoon and evening hours. A cold front associated with the intensifying trough was also observed crossing the Florida peninsula. Ahead of the cold front moderate thermodynamic instability with 700mb temperatures between -7 to -8 degrees Celsius, and 500mb between -9 to -10 degrees Celsius, resulting in lapse rates of 6-6.5 C/km. 90 knot winds atop a het streak over the north central Gulf of Mexico created resulting flow from the southwest. Numerous showers and thunderstorms developed along the cold front, eventually forming a line that crossed across all of east central Florida. A few storms produced strong winds along most of the coast, with two severe thunderstorms producing winds in excess of 50 knots in Brevard and Indian River counties.', 'Buoy 41009 measured a peak wind gust of 39 knots from the south.');
INSERT INTO public.stormevents_east VALUES (748075, 201804, 15, 1840, 201804, 15, 1840, 124679, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MLB', '15-APR-18 18:40:00', 'EST-5', '15-APR-18 18:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 3, 'ENE', 'STUART', 3, 'ENE', 'STUART', 27.2243, -80.2023, 27.2243, -80.2023, 'The Storm Prediction Center had designated a slight change of severe weather for all of east central Florida. A high amplitude shortwave over the Mississippi River Valley quickly moved south across the Florida peninsula during the afternoon and evening hours. A cold front associated with the intensifying trough was also observed crossing the Florida peninsula. Ahead of the cold front moderate thermodynamic instability with 700mb temperatures between -7 to -8 degrees Celsius, and 500mb between -9 to -10 degrees Celsius, resulting in lapse rates of 6-6.5 C/km. 90 knot winds atop a het streak over the north central Gulf of Mexico created resulting flow from the southwest. Numerous showers and thunderstorms developed along the cold front, eventually forming a line that crossed across all of east central Florida. A few storms produced strong winds along most of the coast, with two severe thunderstorms producing winds in excess of 50 knots in Brevard and Indian River counties.', 'Weatherflow site XJEN on the Indian River in Jensen Beach measured a peak wind gust of 36 knots from the south.');
INSERT INTO public.stormevents_east VALUES (749945, 201804, 15, 1447, 201804, 15, 1447, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:47:00', 'EST-5', '15-APR-18 14:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 36, 'EG', NULL, NULL, 8, 'SW', 'MAYPORT NAS', 8, 'SW', 'MAYPORT NAS', 30.33, -81.52, 30.33, -81.52, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'Craig airfield ASOS measured a wind gust of 41 mph.');
INSERT INTO public.stormevents_east VALUES (749947, 201804, 15, 1447, 201804, 15, 1447, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:47:00', 'EST-5', '15-APR-18 14:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 42, 'MG', NULL, NULL, 1, 'S', 'MAYPORT NAS', 1, 'S', 'MAYPORT NAS', 30.39, -81.42, 30.39, -81.42, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'A wind gust of 48 mph was measured at Mayport Naval Air Station.');
INSERT INTO public.stormevents_east VALUES (749948, 201804, 15, 1448, 201804, 15, 1448, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:48:00', 'EST-5', '15-APR-18 14:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 35, 'MG', NULL, NULL, 1, 'SW', 'ST AUGUSTINE ARPT', 1, 'SW', 'ST AUGUSTINE ARPT', 29.96, -81.34, 29.96, -81.34, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The SGJ weather sensor at NE FL Regional Airfield measured a wind gust of 40 mph.');
INSERT INTO public.stormevents_east VALUES (749949, 201804, 15, 1450, 201804, 15, 1450, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:50:00', 'EST-5', '15-APR-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 1, 'N', 'JACKSONVILLE BEACH', 1, 'N', 'JACKSONVILLE BEACH', 30.29, -81.38, 30.29, -81.38, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The WeatherFlow sensor at the Jacksonville Beach Pier measured a peak wind gust of 43 mph.');
INSERT INTO public.stormevents_east VALUES (749950, 201804, 15, 1450, 201804, 15, 1450, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:50:00', 'EST-5', '15-APR-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 41, 'MG', NULL, NULL, 11, 'SSW', 'BEVERLY BEACH', 11, 'SSW', 'BEVERLY BEACH', 29.47, -81.21, 29.47, -81.21, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'A wind gust of 47 mph was measured at the Flagler County Airport.');
INSERT INTO public.stormevents_east VALUES (749952, 201804, 15, 1451, 201804, 15, 1451, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:51:00', 'EST-5', '15-APR-18 14:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 18, 'S', 'FERNANDINA NOS', 18, 'S', 'FERNANDINA NOS', 30.41, -81.41, 30.41, -81.41, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The WeatherFlow sensor at Huguenot Park measured a wind gust of 45 mph.');
INSERT INTO public.stormevents_east VALUES (749954, 201804, 15, 1454, 201804, 15, 1454, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:54:00', 'EST-5', '15-APR-18 14:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 3, 'S', 'ST AUGUSTINE ARPT', 3, 'S', 'ST AUGUSTINE ARPT', 29.92, -81.33, 29.92, -81.33, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The WeatherFlow sensor at San Sebastian River measured a gust of 44 mph.');
INSERT INTO public.stormevents_east VALUES (749955, 201804, 15, 1452, 201804, 15, 1452, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:52:00', 'EST-5', '15-APR-18 14:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 38, 'MG', NULL, NULL, 0, 'N', 'SAUF1 CMAN', 0, 'N', 'SAUF1 CMAN', 29.85, -81.27, 29.85, -81.27, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', NULL);
INSERT INTO public.stormevents_east VALUES (749956, 201804, 15, 1455, 201804, 15, 1455, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:55:00', 'EST-5', '15-APR-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 37, 'MG', NULL, NULL, 4, 'N', 'ST AUGUSTINE ARPT', 4, 'N', 'ST AUGUSTINE ARPT', 30.03, -81.32, 30.03, -81.32, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'A private weather station at Vilano Beach measured a gust of 43 mph.');
INSERT INTO public.stormevents_east VALUES (742210, 201804, 15, 1528, 201804, 15, 1728, 123710, 'OHIO', 39, 2018, 'April', 'Flood', 'ILN', '15-APR-18 15:28:00', 'EST-5', '15-APR-18 17:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'LOGAN', 1, 'ENE', 'LOGAN', 39.54, -82.4, 39.5354, -82.3971, 'Showers and thunderstorms which produced heavy rain, developed ahead of potent surface low.', 'High water was reported on some area roadways.');
INSERT INTO public.stormevents_east VALUES (743268, 201804, 15, 241, 201804, 16, 241, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Heavy Rain', 'RLX', '15-APR-18 02:41:00', 'EST-5', '16-APR-18 02:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'E', 'BARTOW', 1, 'E', 'BARTOW', 38.53, -79.77, 38.53, -79.77, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'The cooperative observer at Bartow measured 2.5 inches of rain in 24 hours.');
INSERT INTO public.stormevents_east VALUES (743278, 201804, 16, 528, 201804, 16, 1000, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Flood', 'RLX', '16-APR-18 05:28:00', 'EST-5', '16-APR-18 10:00:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'RICHWOOD', 1, 'E', 'HOOKERSVILLE', 38.2453, -80.4757, 38.38, -80.7645, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'Route 39 in the Bear Run community was covered in 3 feet of water from the Cherry River. Water also flowed over the 41/55 split in Persinger, along Persinger Creek.');
INSERT INTO public.stormevents_east VALUES (743288, 201804, 16, 23, 201804, 17, 1706, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Flood', 'RLX', '16-APR-18 00:23:00', 'EST-5', '17-APR-18 17:06:00', 0, 0, 0, 0, '6.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'OVERFIELD', 1, 'E', 'ADALAND', 39.1506, -80.1939, 39.2004, -80.0679, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'The Tygart Valley River and many of its smaller tributaries flooded, closing multiple roads. This included Route 38 near Moatsville where Brush Fork and Teter Creek came out of their banks. Route 57 was closed in several places near Elk City, as Elk Creek flooded. Maple Avenue and other roads in Philippi were flooded by the Tygart Valley River.||In Philippi, the river crested about a foot and a half above its 19 foot flood stage during the early afternoon of the 16th. This was after rising above flood stage mid morning. The river returned to its banks by mid morning on the 17th.||A bit upstream, in Belington, the river crested at 16.9, just below moderate flood stage of 17. This occurred during the predawn hours on the 17th. It took until late afternoon for the flood waters to recede.||The Middle Fork of the Tygart Valley River flooded near Audra State Park, about 0.3 feet above its moderate level of 11 feet. The river first rose out of its banks around sunrise on the 16th, crested mid morning, and was back in its banks by mid afternoon.');
INSERT INTO public.stormevents_east VALUES (743292, 201804, 17, 1615, 201804, 19, 942, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Flood', 'RLX', '17-APR-18 16:15:00', 'EST-5', '19-APR-18 09:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNW', 'POINT PLEASANT', 2, 'NNE', 'POINT PLEASANT', 38.8839, -82.1431, 38.8805, -82.1053, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'For the second time in the month of April, the Ohio River flooded near Point Pleasant, with water collecting in low lying areas. The river rose above flood stage, 40 feet, during the late afternoon of the 17th. It crested just over 42 feet on the afternoon of the 18th, and returned to its banks mid morning on the 19th.');
INSERT INTO public.stormevents_east VALUES (754429, 201806, 10, 1400, 201806, 10, 1400, 125805, 'VIRGINIA', 51, 2018, 'June', 'Hail', 'RNK', '10-JUN-18 14:00:00', 'EST-5', '10-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 6, 'ENE', 'BURNT CHIMNEY', 6, 'ENE', 'BURNT CHIMNEY', 37.1196, -79.7317, 37.1196, -79.7317, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (749769, 201804, 16, 1105, 201804, 16, 1234, 125020, 'CONNECTICUT', 9, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 11:05:00', 'EST-5', '16-APR-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'SPRING GLEN', 2, 'SSE', 'SPRING GLEN', 41.323, -72.8874, 41.3223, -72.8863, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 2.0 to 4.0 inches across southern Connecticut, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'Middletown Avenue was closed due to flooding in the vicinity of I-91 and Foxon Boulevard in New Haven.');
INSERT INTO public.stormevents_east VALUES (749770, 201804, 16, 933, 201804, 16, 1234, 125020, 'CONNECTICUT', 9, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 09:33:00', 'EST-5', '16-APR-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'STAMFORD', 0, 'NE', 'STAMFORD', 41.0518, -73.5309, 41.0507, -73.5287, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 2.0 to 4.0 inches across southern Connecticut, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'Elm Street was closed between Cherry Street and South State Street in Stamford due to flooding.');
INSERT INTO public.stormevents_east VALUES (749771, 201804, 16, 1115, 201804, 16, 1234, 125020, 'CONNECTICUT', 9, 2018, 'April', 'Flash Flood', 'OKX', '16-APR-18 11:15:00', 'EST-5', '16-APR-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'STRATFORD', 1, 'ESE', 'STRATFORD', 41.193, -73.1339, 41.1934, -73.1341, 'Heavy rainfall developed across the area on the morning of April 16th ahead of a slow moving warm front. This rain developed in an environment with precipitable water values greater than 1.25 inches, well above normal for mid April. Rainfall totals generally ranged from 2.0 to 4.0 inches across southern Connecticut, with the majority of the rain falling in a 3-4 hour period. This resulted in flash flooding across the region.', 'The intersection of King Street and Broadbridge Avenue in Stratford was impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (779371, 201808, 10, 1525, 201808, 10, 1715, 130142, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PBZ', '10-AUG-18 15:25:00', 'EST-5', '10-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'HUTCHINSON', 1, 'W', 'YUKON', 40.2227, -79.7064, 40.22, -79.7054, 'Showers and thunderstorms formed along a nearly stationary boundary that crept southeastward from the Great Lakes.  Precipitable water values of around 1.6 inches and weak steering flow along the boundary led to a few areas of training thunderstorms.  Rainfall amounts of 1.5 to 3.0 inches on already saturated ground led to several areas of flash flooding in Washington, Allegheny, and Westmoreland Counties.  The worst flooding was near Herminie, where up to 14 homes were impacted and a mobile home was shifted off of its foundation.', 'The county emergency manager reported that a vehicle was stuck in flood waters at the intersection of Derr Road and Pierce Road in Sewickley Township.');
INSERT INTO public.stormevents_east VALUES (779377, 201808, 10, 1529, 201808, 10, 1715, 130142, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PBZ', '10-AUG-18 15:29:00', 'EST-5', '10-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'WYANO', 1, 'ENE', 'HERMINIE', 40.2151, -79.7026, 40.2756, -79.7002, 'Showers and thunderstorms formed along a nearly stationary boundary that crept southeastward from the Great Lakes.  Precipitable water values of around 1.6 inches and weak steering flow along the boundary led to a few areas of training thunderstorms.  Rainfall amounts of 1.5 to 3.0 inches on already saturated ground led to several areas of flash flooding in Washington, Allegheny, and Westmoreland Counties.  The worst flooding was near Herminie, where up to 14 homes were impacted and a mobile home was shifted off of its foundation.', 'The county emergency manager reported that 14 homes were flooded with 2 feet of water, with one mobile home knocked off of its foundation.  Route 136 and Hutchinson Road were washed out, with numerous other roads flooded in the area.');
INSERT INTO public.stormevents_east VALUES (779373, 201808, 10, 1529, 201808, 10, 1715, 130142, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PBZ', '10-AUG-18 15:29:00', 'EST-5', '10-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'COWANSBURG', 1, 'NW', 'HUTCHINSON', 40.24, -79.74, 40.2386, -79.7407, 'Showers and thunderstorms formed along a nearly stationary boundary that crept southeastward from the Great Lakes.  Precipitable water values of around 1.6 inches and weak steering flow along the boundary led to a few areas of training thunderstorms.  Rainfall amounts of 1.5 to 3.0 inches on already saturated ground led to several areas of flash flooding in Washington, Allegheny, and Westmoreland Counties.  The worst flooding was near Herminie, where up to 14 homes were impacted and a mobile home was shifted off of its foundation.', 'The county emergency manager reported that the intersection of Apples Mill Road and Hildenbrand Road in Sewickley Township was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (742416, 201804, 15, 1542, 201804, 15, 1542, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'TBW', '15-APR-18 15:42:00', 'EST-5', '15-APR-18 15:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'EG', NULL, NULL, 2, 'SSE', 'BOCA GRANDE', 2, 'SSE', 'BOCA GRANDE', 26.72, -82.26, 26.72, -82.26, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'The WeatherFlow station on Boca Grande (XBCG) recorded a 36 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (743054, 201804, 3, 1025, 201804, 3, 1830, 123684, 'OHIO', 39, 2018, 'April', 'Flash Flood', 'RLX', '03-APR-18 10:25:00', 'EST-5', '03-APR-18 18:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'ROSEVILLE', 2, 'NW', 'ROSEVILLE', 39.8157, -82.0735, 39.8164, -82.1028, 'A warm front lifted across the middle Ohio River Valley on the morning of the 3rd. This brought a round of showers and thunderstorms. Showers lingered across central and eastern Ohio through much of the day with the warm front in the vicinity. A strong cold front then pushed through in the evening with strong to severe thunderstorms. Periods of heavy rain, first with the warm front, and then again with the cold front led to flooding.', 'Following heavy rain, several roads were covered with water in the Roseville Area.');
INSERT INTO public.stormevents_east VALUES (743236, 201804, 3, 915, 201804, 5, 1230, 123684, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '03-APR-18 09:15:00', 'EST-5', '05-APR-18 12:30:00', 0, 0, 0, 0, '4.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MACKSBURG', 1, 'NE', 'MACKSBURG', 39.6427, -81.4702, 39.6426, -81.4548, 'A warm front lifted across the middle Ohio River Valley on the morning of the 3rd. This brought a round of showers and thunderstorms. Showers lingered across central and eastern Ohio through much of the day with the warm front in the vicinity. A strong cold front then pushed through in the evening with strong to severe thunderstorms. Periods of heavy rain, first with the warm front, and then again with the cold front led to flooding.', 'Flooding along Duck Creek and the Little Muskingum River closed several roads, including Broad Street in Macksburg, and State Routes 26, 145 and 821 along Duck Creek. State Route 26, near the intersection with 260, and Bloomfield Church Road also flooded along the Little Muskingum River. ||The West Fork of Duck Creek at Macksburg rose above its bankfull level of 13 feet on the morning of the 3rd. It crested just above moderate stage, or 15 feet, around sunrise on the 4th and returned to its banks just after midnight on the 5th.||At Whipple on Duck Creek, the gage indicated the creek rose out of its banks early afternoon on the 3rd. It crested half a foot above its 16 foot moderate flood stage mid morning on the 4th and was back in its banks around sunrise on the 5th.||The Little Muskingum River at Bloomfield rose above its 16 foot bankfull level early afternoon on the 3rd. It crested just under 23.5 feet, about half a foot over moderate stage, near sunrise on the 4th and returned to its banks late that evening.');
INSERT INTO public.stormevents_east VALUES (743074, 201804, 3, 1530, 201804, 5, 15, 123684, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '03-APR-18 15:30:00', 'EST-5', '05-APR-18 00:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'HAYWARD', 0, 'SW', 'HAYWARD', 39.5787, -81.6535, 39.5671, -81.6745, 'A warm front lifted across the middle Ohio River Valley on the morning of the 3rd. This brought a round of showers and thunderstorms. Showers lingered across central and eastern Ohio through much of the day with the warm front in the vicinity. A strong cold front then pushed through in the evening with strong to severe thunderstorms. Periods of heavy rain, first with the warm front, and then again with the cold front led to flooding.', 'The Muskingum River in Beverly flooded, causing minor flooding of low areas, farmland and several camps. The river rose above its 29 foot flood stage during the afternoon of the 3rd. It crested at just over 32 feet mid morning on the 4th, and returned to within its banks just after midnight on the 5th.');
INSERT INTO public.stormevents_east VALUES (743243, 201804, 15, 1900, 201804, 15, 2300, 123859, 'OHIO', 39, 2018, 'April', 'Flood', 'RLX', '15-APR-18 19:00:00', 'EST-5', '15-APR-18 23:00:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'WNW', 'RATCLIFFBURG', 1, 'N', 'ALLENSVILLE', 39.2853, -82.7431, 39.2867, -82.6225, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. One to two inches of rain fell across most of southeast Ohio, resulting in flooding.', 'Clark Road near Ray along with Thompson Road near Ratcliffburg were closed due to flooding along the Middle Fork of Salt Creek.');
INSERT INTO public.stormevents_east VALUES (760744, 201805, 17, 1200, 201805, 19, 2130, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '19-MAY-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 0, 'N', 'ASHLAND', 0, 'N', 'ASHLAND', 37.75, -77.48, 37.75, -77.48, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 5.18 inches at Mesonet Station AS799 (Ashland).');
INSERT INTO public.stormevents_east VALUES (743281, 201804, 16, 110, 201804, 16, 500, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Flood', 'RLX', '16-APR-18 01:10:00', 'EST-5', '16-APR-18 05:00:00', 0, 0, 0, 0, '6.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'COPLEY', 3, 'NNW', 'BERLIN', 38.9941, -80.6414, 39.082, -80.3719, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'In Jane Lew, Hackers Creek flooded parts of the city ball park and Parkway Drive. Vadis Road also flooded along Walnut Fork near Vadis. Interstate 79 was also closed near mile maker 105 due to high water on Hackers Creek and Jesse Run.');
INSERT INTO public.stormevents_east VALUES (744430, 201804, 15, 1326, 201804, 15, 1326, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:26:00', 'EST-5', '15-APR-18 13:26:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 4, 'NW', 'SPRING HILL', 4, 'NW', 'SPRING HILL', 34.22, -81.32, 34.22, -81.32, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'SC Highway Patrol reported trees down on Broad River Rd and Mike Stuck Rd.');
INSERT INTO public.stormevents_east VALUES (744431, 201804, 15, 1336, 201804, 15, 1336, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:36:00', 'EST-5', '15-APR-18 13:36:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'ESE', 'BONEY', 2, 'ESE', 'BONEY', 34.24, -80.93, 34.24, -80.93, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Power lines down on Clamp Rd near Twentyfive Mile Creek. Time estimated.');
INSERT INTO public.stormevents_east VALUES (744432, 201804, 15, 1214, 201804, 15, 1214, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 12:14:00', 'EST-5', '15-APR-18 12:14:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 1, 'ESE', 'SUPREME', 1, 'ESE', 'SUPREME', 33.81, -81.91, 33.81, -81.91, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'SC Highway Patrol reported trees down at Crest Rd near the town of Edgefield.');
INSERT INTO public.stormevents_east VALUES (744433, 201804, 15, 1201, 201804, 15, 1201, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 12:01:00', 'EST-5', '15-APR-18 12:01:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 6, 'E', 'MORGANA', 6, 'E', 'MORGANA', 33.57, -81.97, 33.57, -81.97, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'SC Highway Patrol reported trees down at Country Club Hills and Gregory Lake Rd.');
INSERT INTO public.stormevents_east VALUES (744435, 201804, 15, 1333, 201804, 15, 1333, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:33:00', 'EST-5', '15-APR-18 13:33:00', 0, 0, 0, 0, NULL, NULL, 'Public', 55, 'EG', NULL, NULL, 8, 'WSW', 'HAMMOND XRDS', 8, 'WSW', 'HAMMOND XRDS', 33.69, -80.99, 33.69, -80.99, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'SCHP reported trees down on Interstate 26.');
INSERT INTO public.stormevents_east VALUES (744436, 201804, 15, 1229, 201804, 15, 1229, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 12:29:00', 'EST-5', '15-APR-18 12:29:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'NE', 'STIEFELTOWN', 2, 'NE', 'STIEFELTOWN', 33.57, -81.77, 33.57, -81.77, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Tree down Gregg Hwy and University Ln.');
INSERT INTO public.stormevents_east VALUES (744437, 201804, 15, 1255, 201804, 15, 1255, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 12:55:00', 'EST-5', '15-APR-18 12:55:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 0, 'N', 'NEW HOLLAND XRDS', 0, 'N', 'NEW HOLLAND XRDS', 33.7, -81.48, 33.7, -81.48, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Multiple trees down on Kirkland Rd in New Holland.');
INSERT INTO public.stormevents_east VALUES (744438, 201804, 15, 1238, 201804, 15, 1238, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 12:38:00', 'EST-5', '15-APR-18 12:38:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'SW', 'WILLISTON', 3, 'SW', 'WILLISTON', 33.37, -81.45, 33.37, -81.45, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trees down in roadway Fellowship Rd at Moonlight Rd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (754426, 201806, 10, 1342, 201806, 10, 1342, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 13:42:00', 'EST-5', '10-JUN-18 13:42:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 6, 'NE', 'BURNT CHIMNEY', 6, 'NE', 'BURNT CHIMNEY', 37.1508, -79.7353, 37.1508, -79.7353, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'A large tree was blown down by thunderstorm winds along Middle Valley Road.');
INSERT INTO public.stormevents_east VALUES (742188, 201804, 3, 1637, 201804, 3, 1641, 123573, 'OHIO', 39, 2018, 'April', 'Tornado', 'ILN', '03-APR-18 16:37:00', 'EST-5', '03-APR-18 16:41:00', 0, 0, 0, 0, '120.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'S', 'GROVE CITY', 2, 'E', 'GROVE CITY', 39.8588, -83.0829, 39.8753, -83.0382, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'The tornado initially touched down just south of Orders Road and moved northeast, crossing Hoover Road and I-71, and eventually White Road before lifting just north of White Road and just south of Stringtown Road.||The most significant damage along this path occurred on the west side of I-71, first near Orders Road where 4 large utility poles were snapped at the base and lying across Orders Road. Structural damage was found to multiple townhouses and other structures on the west side of Hoover Road, where a newly built detached garage was completely destroyed, and several townhouses had partial uplift and removal of roofing and damage to exterior walls. Many townhouses had garage doors pushed in, with portions of roofs removed. Debris spatter was indicated on all 4 sides of several structures. Four more large electrical transmission poles were snapped on the west side of Hoover Road. Eyewitness photos and videos confirm a tornado on the ground in this area. The most significant damage in this area was consistent with wind speeds around 105 mph and represents the strongest of the winds associated with this tornado.||As the tornado crossed I-71, it began to weaken and lift as damage became lighter and more intermittent, consisting of tree and minor structural damage to roofing materials. Still, many homes immediately east of I-71 suffered at least minor damage and/or tree damage before the tornado lifted.');
INSERT INTO public.stormevents_east VALUES (745887, 201804, 24, 1325, 201804, 24, 1325, 124328, 'FLORIDA', 12, 2018, 'April', 'Hail', 'MLB', '24-APR-18 13:25:00', 'EST-5', '24-APR-18 13:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'W', 'HOBE SOUND', 1, 'W', 'HOBE SOUND', 27.07, -80.14, 27.07, -80.14, 'A mid level closed low at 500 mb across western Tennessee with a surface low pressure across northern Georgia caused the predominant southwest/west-southwest winds to veer to the west across east central Florida. A drier, cooler air mass moved in across the northern half of east central Florida through the afternoon hours, which led to greater instability across the Treasure Coast. Deep moisture moved eastward across southern Osceola and Okeechobee counties and the Treasure Coast resulting in the development of strong to severe thunderstorms from Okeechobee to St. Lucie to Maritn counties. One severe thunderstorm produced hail and strong winds in Hobe Sound, while a second severe thunderstorm produced golf ball sized hail in Tequesta.', 'A trained spotter reported quarter-sized hail in Hobe Sound.');
INSERT INTO public.stormevents_east VALUES (745884, 201804, 24, 1319, 201804, 24, 1319, 124327, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MLB', '24-APR-18 13:19:00', 'EST-5', '24-APR-18 13:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'MG', NULL, NULL, 7, 'NNW', 'TEQUESTA', 7, 'NNW', 'TEQUESTA', 27.06, -80.13, 27.06, -80.13, 'A mid level closed low at 500 mb across western Tennessee with a surface low pressure across northern Georgia caused the predominant southwest/west-southwest winds to veer to the west across east central Florida. A drier, cooler air mass moved in across the northern half of east central Florida through the afternoon hours, which led to greater instability across the Treasure Coast. Deep moisture moved eastward across southern Osceola and Okeechobee counties and the Treasure Coast resulting in the development of strong to severe thunderstorms from Okeechobee to St. Lucie to Maritn counties. Two severe thunderstorms produced hail and strong winds along the Martin County coast as they moved offshore.', 'Weatherbug site MCRF1 measured a peak wind gust of 44 knots.');
INSERT INTO public.stormevents_east VALUES (754438, 201806, 11, 1625, 201806, 11, 1630, 125807, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '11-JUN-18 16:25:00', 'EST-5', '11-JUN-18 16:30:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Public', 55, 'EG', NULL, NULL, 3, 'N', 'HUNTSVILLE', 2, 'W', 'ENON', 36.1196, -80.5147, 36.1433, -80.5132, 'Strong daytime heating helped destabilize the atmosphere, allowing a lone thunderstorm to intensify to severe levels during the afternoon and produce locally-damaging winds.', 'Several trees and large limbs were blown down by thunderstorm winds along Baltimore Road, while another tree was blown down along Cornelius Road.');
INSERT INTO public.stormevents_east VALUES (754424, 201806, 10, 1425, 201806, 10, 1425, 125805, 'VIRGINIA', 51, 2018, 'June', 'Hail', 'RNK', '10-JUN-18 14:25:00', 'EST-5', '10-JUN-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 1, 'NNW', 'SARDIS', 1, 'NNW', 'SARDIS', 37.6497, -79.1276, 37.6497, -79.1276, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (754425, 201806, 10, 1342, 201806, 10, 1342, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 13:42:00', 'EST-5', '10-JUN-18 13:42:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'ENE', 'BURNT CHIMNEY', 5, 'ENE', 'BURNT CHIMNEY', 37.1199, -79.7404, 37.1199, -79.7404, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'A large tree was blown down by thunderstorm winds along Lost Mountain Road.');
INSERT INTO public.stormevents_east VALUES (754427, 201806, 10, 1350, 201806, 10, 1350, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 13:50:00', 'EST-5', '10-JUN-18 13:50:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 5, 'ESE', 'BURNT CHIMNEY', 5, 'ESE', 'BURNT CHIMNEY', 37.0866, -79.7474, 37.0866, -79.7474, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'Multiple trees were blown down by thunderstorm winds along Brooks Mill Road.');
INSERT INTO public.stormevents_east VALUES (754428, 201806, 10, 1406, 201806, 10, 1406, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 14:06:00', 'EST-5', '10-JUN-18 14:06:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'N', 'UNION HALL', 5, 'N', 'UNION HALL', 37.0659, -79.7148, 37.0659, -79.7148, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'A large tree was blown down by thunderstorm winds along Big Oak Lane.');
INSERT INTO public.stormevents_east VALUES (754430, 201806, 10, 1438, 201806, 10, 1443, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 14:38:00', 'EST-5', '10-JUN-18 14:43:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'E', 'SANDLEDGE', 1, 'N', 'SARDIS', 37.6739, -79.1188, 37.6407, -79.1183, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'A large tree was blown down by thunderstorm winds along Lowesville Road while another tree was blown down at Stonehouse Lake.');
INSERT INTO public.stormevents_east VALUES (769337, 201806, 25, 1833, 201806, 25, 1843, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 18:33:00', 'EST-5', '25-JUN-18 18:43:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'ENE', 'WAXHAW', 1, 'NW', 'MINERAL SPG', 34.921, -80.744, 34.938, -80.679, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms reported multiple trees blown down between Waxhaw and Mineral Springs.');
INSERT INTO public.stormevents_east VALUES (756161, 201806, 2, 1500, 201806, 2, 1501, 126045, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '02-JUN-18 15:00:00', 'EST-5', '02-JUN-18 15:01:00', 0, 0, 0, 0, NULL, NULL, 'Official NWS Observations', 38, 'MG', NULL, NULL, 6, 'N', 'ALTAMAHA SOUND', 6, 'N', 'ALTAMAHA SOUND', 31.41, -81.31, 31.41, -81.31, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across the coastal waters.', 'The Sapelo Island NERRS sensor recorded a 38 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (770292, 201806, 2, 1709, 201806, 2, 1710, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 17:09:00', 'EST-5', '02-JUN-18 17:10:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 4, 'ENE', 'COTTAGEVILLE', 4, 'ENE', 'COTTAGEVILLE', 32.96, -80.42, 32.96, -80.42, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'A report via social media indicated multiple trees down near the 2300 block of McDanieltown Road.');
INSERT INTO public.stormevents_east VALUES (771014, 201806, 27, 1603, 201806, 27, 1604, 126067, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '27-JUN-18 16:03:00', 'EST-5', '27-JUN-18 16:04:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'SSE', 'BELFAST', 2, 'SSE', 'BELFAST', 31.9, -81.27, 31.9, -81.27, 'A moderately unstable atmosphere in combination with a stationary front over the area and an inland moving sea breeze provided an environment capable of producing thunderstorms with damaging wind gusts.', 'The media reported vinyl ceiling material blown off a porch roof along Georgia Highway 144 near Charlies Road.');
INSERT INTO public.stormevents_east VALUES (771019, 201806, 27, 1546, 201806, 27, 1547, 126069, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '27-JUN-18 15:46:00', 'EST-5', '27-JUN-18 15:47:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'SW', 'COLLINS CRK SETTLEME', 1, 'SW', 'COLLINS CRK SETTLEME', 33.14, -79.43, 33.14, -79.43, 'A moderately unstable atmosphere in combination with a stationary front over the area and an inland moving sea breeze provided an environment capable of producing thunderstorms with damaging wind gusts.', 'The McClellanville Fire Department reported a tree down on a power line along South Santee Road north of McClellanville.');
INSERT INTO public.stormevents_east VALUES (771023, 201806, 27, 1815, 201806, 27, 1816, 126070, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '27-JUN-18 18:15:00', 'EST-5', '27-JUN-18 18:16:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 39, 'MG', NULL, NULL, 1, 'S', 'ISLE OF PALMS', 1, 'S', 'ISLE OF PALMS', 32.78, -79.79, 32.78, -79.79, 'A moderately unstable atmosphere in combination with a stationary front over the area and a sea breeze provided an environment capable of producing thunderstorms with damaging wind gusts.', 'The Weatherflow sensor at Isle of Palms recorded a wind gust of 39 knots.');
INSERT INTO public.stormevents_east VALUES (771027, 201806, 28, 1355, 201806, 28, 1358, 126071, 'GEORGIA', 13, 2018, 'June', 'Hail', 'CHS', '28-JUN-18 13:55:00', 'EST-5', '28-JUN-18 13:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.88, NULL, NULL, NULL, 1, 'W', 'STILSON', 1, 'W', 'STILSON', 32.33, -81.56, 32.33, -81.56, 'A weak surface trough of low pressure and a mid-level shortwave passing over a warm and moist atmosphere led to thunderstorms capable of producing hail.', 'The public reported nickel size hail and gusty winds for a few minutes.');
INSERT INTO public.stormevents_east VALUES (770862, 201806, 12, 1010, 201806, 12, 1015, 128452, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'CHS', '12-JUN-18 10:10:00', 'EST-5', '12-JUN-18 10:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 3, 'E', 'ISLE OF PALMS', 3, 'E', 'ISLE OF PALMS', 32.7888, -79.7325, 32.7888, -79.7325, 'A stationary front over the area along with deep moisture and weak wind fields led to showers and thunderstorms capable of producing waterspouts along the Southeast Coast.', 'The public relayed a picture of a waterspout off the coast of Isle of Palms.');
INSERT INTO public.stormevents_east VALUES (755834, 201806, 2, 1505, 201806, 2, 1506, 126044, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 15:05:00', 'EST-5', '02-JUN-18 15:06:00', 0, 0, 0, 0, '5.00K', NULL, 'Emergency Manager', 40, 'EG', NULL, NULL, 1, 'SW', 'CENTRAL JCT', 1, 'SW', 'CENTRAL JCT', 32.07, -81.13, 32.07, -81.13, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Chatham County Emergency Management reported a large Georgia Department of Transportation sign down on Interstate 16 near the Interstate 516 interchange.');
INSERT INTO public.stormevents_east VALUES (759903, 201805, 14, 2002, 201805, 14, 2002, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 20:02:00', 'EST-5', '14-MAY-18 20:02:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'TABB', 1, 'NW', 'TABB', 37.14, -76.44, 37.14, -76.44, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (759906, 201805, 14, 1841, 201805, 14, 1841, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 18:41:00', 'EST-5', '14-MAY-18 18:41:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'E', 'MACON', 1, 'E', 'MACON', 37.52, -77.96, 37.52, -77.96, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Wind gust of 52 knots (60 mph) was reported.');
INSERT INTO public.stormevents_east VALUES (759908, 201805, 14, 1900, 201805, 14, 1900, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 19:00:00', 'EST-5', '14-MAY-18 19:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Mesonet', 56, 'MG', NULL, NULL, 5, 'S', 'VARINA GROVE', 5, 'S', 'VARINA GROVE', 37.38, -77.35, 37.38, -77.35, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Wind gust of 56 knots (64 mph) was measured at Mesonet Station VA036 (1 WNW Meadowville).');
INSERT INTO public.stormevents_east VALUES (760329, 201805, 14, 2011, 201805, 14, 2011, 126830, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:11:00', 'EST-5', '14-MAY-18 20:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 3, 'NW', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 3, 'NW', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 37.01, -76.35, 37.01, -76.35, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the James River.', 'Wind gust of 39 knots was measured at Hampton Flats.');
INSERT INTO public.stormevents_east VALUES (760331, 201805, 14, 2011, 201805, 14, 2011, 126830, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:11:00', 'EST-5', '14-MAY-18 20:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 46, 'MG', NULL, NULL, 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.95, -76.39, 36.95, -76.39, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the James River.', 'Wind gust of 46 knots was measured at Middle Ground Lighthouse.');
INSERT INTO public.stormevents_east VALUES (760339, 201805, 14, 2012, 201805, 14, 2012, 126830, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:12:00', 'EST-5', '14-MAY-18 20:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 0, 'N', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 0, 'N', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 36.98, -76.32, 36.98, -76.32, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the James River.', 'Wind gust of 38 knots was measured at Willoughby Degaussing Station.');
INSERT INTO public.stormevents_east VALUES (760348, 201805, 14, 2012, 201805, 14, 2012, 126830, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 20:12:00', 'EST-5', '14-MAY-18 20:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 38, 'MG', NULL, NULL, 0, 'N', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 0, 'N', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.96, -76.43, 36.96, -76.43, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the James River.', 'Wind gust of 38 knots was measured at Dominion Terminal Associates.');
INSERT INTO public.stormevents_east VALUES (760686, 201805, 17, 1200, 201805, 19, 2140, 126867, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '19-MAY-18 21:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'SSW', 'HEBRON', 1, 'SSW', 'HEBRON', 38.4, -75.69, 38.4, -75.69, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of the Lower Maryland Eastern Shore.', 'Three day rainfall total was 7.23 inches at Mesonet Station AU888 (1 SSW Hebron).');
INSERT INTO public.stormevents_east VALUES (771164, 201806, 27, 1905, 201806, 27, 1905, 128535, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '27-JUN-18 19:05:00', 'EST-5', '27-JUN-18 19:05:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SW', 'NORVELT', 1, 'SW', 'NORVELT', 40.21, -79.51, 40.21, -79.51, 'In the wake of morning rain, cloud breaks developed from Virginia into south central Pennsylvania during the afternoon.  CAPE values climbed to near 1000 J/kg, despite poor mid-level lapse rates.  Disturbances rotating around the southeastern periphery of a Great Lakes/upper Ohio Valley trough helped to increase low level flow and shear.  This proved sufficient to allow afternoon storms to rotate. ||Westmoreland County bore the brunt of the damage, with two short-track EF0 tornadoes confirmed. One in the Hempfield Township/Mount Pleasant area mainly caused tree damage, although damage was done to a barn and outbuildings along Brinker Road.  The second tornado in Unity Township, near Arnold Palmer Regional Airport, mainly caused tree damage as well, along with damage to a barn roof and other minimal home damage. Straight-line wind damage was apparent in other areas in the county.', 'County law enforcement reported multiple trees down near Reservoir Road just west of Norvelt.');
INSERT INTO public.stormevents_east VALUES (771165, 201806, 27, 1905, 201806, 27, 1905, 128535, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '27-JUN-18 19:05:00', 'EST-5', '27-JUN-18 19:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'ARMBRUST', 1, 'S', 'ARMBRUST', 40.21, -79.55, 40.21, -79.55, 'In the wake of morning rain, cloud breaks developed from Virginia into south central Pennsylvania during the afternoon.  CAPE values climbed to near 1000 J/kg, despite poor mid-level lapse rates.  Disturbances rotating around the southeastern periphery of a Great Lakes/upper Ohio Valley trough helped to increase low level flow and shear.  This proved sufficient to allow afternoon storms to rotate. ||Westmoreland County bore the brunt of the damage, with two short-track EF0 tornadoes confirmed. One in the Hempfield Township/Mount Pleasant area mainly caused tree damage, although damage was done to a barn and outbuildings along Brinker Road.  The second tornado in Unity Township, near Arnold Palmer Regional Airport, mainly caused tree damage as well, along with damage to a barn roof and other minimal home damage. Straight-line wind damage was apparent in other areas in the county.', 'The county emergency manager reported that trees and wires were blown down along Route 819 in Mount Pleasant Township.');
INSERT INTO public.stormevents_east VALUES (771166, 201806, 27, 1920, 201806, 27, 1920, 128535, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '27-JUN-18 19:20:00', 'EST-5', '27-JUN-18 19:20:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WNW', 'BAGGALEY', 1, 'WNW', 'BAGGALEY', 40.2746, -79.3898, 40.2746, -79.3898, 'In the wake of morning rain, cloud breaks developed from Virginia into south central Pennsylvania during the afternoon.  CAPE values climbed to near 1000 J/kg, despite poor mid-level lapse rates.  Disturbances rotating around the southeastern periphery of a Great Lakes/upper Ohio Valley trough helped to increase low level flow and shear.  This proved sufficient to allow afternoon storms to rotate. ||Westmoreland County bore the brunt of the damage, with two short-track EF0 tornadoes confirmed. One in the Hempfield Township/Mount Pleasant area mainly caused tree damage, although damage was done to a barn and outbuildings along Brinker Road.  The second tornado in Unity Township, near Arnold Palmer Regional Airport, mainly caused tree damage as well, along with damage to a barn roof and other minimal home damage. Straight-line wind damage was apparent in other areas in the county.', 'The county emergency manager reported that trees and power lines were down along Gravel Hill Road.');
INSERT INTO public.stormevents_east VALUES (784180, 201809, 12, 1345, 201809, 12, 1430, 131087, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 13:45:00', 'EST-5', '12-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'NEW LONDON', 0, 'NE', 'NEW LONDON', 41.352, -72.0973, 41.3518, -72.0976, 'Showers and thunderstorms developed along a stationary front draped across southern Connecticut during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over southeast Connecticut. A cooperative observer in Norwich reported 4.62 inches of rain with these storms, the bulk of which fell over a period of 2-3 hours.', 'Water was inside the Octane Cafe at the corner of Tilley Street and Bank Street in New London.');
INSERT INTO public.stormevents_east VALUES (754913, 201806, 23, 1450, 201806, 23, 1450, 125920, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MRX', '23-JUN-18 14:50:00', 'EST-5', '23-JUN-18 14:50:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'HAYESVILLE', 1, 'E', 'HAYESVILLE', 35.05, -83.82, 35.05, -83.82, 'A rather small thunderstorm complex which originated across Arkansas earlier in the day made steady progress across the Tennessee Valley of Alabama and into Southeast Tennessee and Southwest North Carolina producing damaging winds along its path.', 'Several trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (784184, 201809, 12, 1430, 201809, 12, 1448, 131090, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 14:30:00', 'EST-5', '12-SEP-18 14:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'STONY BROOK', 1, 'SE', 'STONY BROOK', 40.9022, -73.1144, 40.9026, -73.1138, 'Showers and thunderstorms developed along a stationary front located just north of Long Island during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over parts of northern Suffolk County. A CoCoRaHS observer in Port Jefferson Station recorded 2.98 inches of rain over a period of about three and a half hours in this event.', 'Flooding in two homes on Martingale Court in Stony Brook resulted in electrical issues.');
INSERT INTO public.stormevents_east VALUES (784185, 201809, 12, 1430, 201809, 12, 1448, 131090, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 14:30:00', 'EST-5', '12-SEP-18 14:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'STONY BROOK', 1, 'SE', 'STONY BROOK', 40.906, -73.1111, 40.9065, -73.1111, 'Showers and thunderstorms developed along a stationary front located just north of Long Island during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over parts of northern Suffolk County. A CoCoRaHS observer in Port Jefferson Station recorded 2.98 inches of rain over a period of about three and a half hours in this event.', 'A car was submerged in water with the driver inside the vehicle on Edmund D. Pellegrino Road in South Setauket.');
INSERT INTO public.stormevents_east VALUES (784212, 201809, 25, 1103, 201809, 25, 1430, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 11:03:00', 'EST-5', '25-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'COMMUNIPAW', 1, 'W', 'COMMUNIPAW', 40.6832, -74.0959, 40.6806, -74.0935, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'Car stuck in flood waters on Route 440 southbound near Port Jersey Boulevard in Bayonne.');
INSERT INTO public.stormevents_east VALUES (784744, 201809, 25, 1530, 201809, 25, 1900, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 15:30:00', 'EST-5', '25-SEP-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'RIDGEWOOD', 0, 'ESE', 'RIDGEWOOD', 40.9983, -74.1141, 40.9975, -74.1139, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'The Hohokus Brook at Ho-Ho-Kus rose above its minor flood stage of 3.0 feet at 4:30pm EDT, crested at a height of 3.30 feet at 5:15pm EDT, then fell back below flood stage at 8:00pm EDT.');
INSERT INTO public.stormevents_east VALUES (784743, 201809, 25, 1400, 201809, 26, 415, 131100, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 14:00:00', 'EST-5', '26-SEP-18 04:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'FORDHAM', 1, 'SSE', 'FORDHAM', 40.8626, -73.8748, 40.8626, -73.8742, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 1-4 inches across New York City and Westchester County, and 2-5 inches across portions of northern Suffolk County. The ASOS at Central Park recorded 2.08 inches of rain while the ASOS at the White Plains Airport recorded 4.43 inches of rain during the event. Farther east, 4.27 inches of rain was reported by a CoCoRaHS observer in Port Jefferson Station, while a member of the public reported 4.53 inches of rain in Setauket.', 'The Bronx River at the New York Botanical Garden exceeded its flood stage of 3.0 feet at 2:00pm EDT. The river then proceeded to rise above its moderate flood stage of 3.5 feet at 3:15pm EDT and above its major flood stage of 4.0 feet at 5:45pm, cresting at a height of 4.16 feet at 8:30pm EDT. The river fell back below flood stage at 4:15am EDT on September 26th.');
INSERT INTO public.stormevents_east VALUES (786257, 201809, 17, 1610, 201809, 17, 1610, 131404, 'NEW JERSEY', 34, 2018, 'September', 'Thunderstorm Wind', 'OKX', '17-SEP-18 16:10:00', 'EST-5', '17-SEP-18 16:10:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'S', 'SUMMIT', 1, 'S', 'SUMMIT', 40.71, -74.37, 40.71, -74.37, 'A surface trough triggered showers and a severe thunderstorm across Northeast New Jersey.', 'Multiple large trees down on Meadowbrook Court.');
INSERT INTO public.stormevents_east VALUES (786331, 201809, 18, 1345, 201809, 18, 1415, 131414, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '18-SEP-18 13:45:00', 'EST-5', '18-SEP-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'HARRISON', 0, 'NE', 'HARRISON', 40.7534, -74.1626, 40.754, -74.1625, 'A tropical airmass associated with the remnants of Hurricane Florence combined with an approaching cold front to produce waves of showers and thunderstorms that resulted isolated flash flooding in northeast New Jersey. The precipitable water value on the 8am sounding from Upton, New York was 2.10, which represents a daily maximum value based on the Storm Prediction Center''s sounding climatology.', 'The intersection of Passaic Avenue and Johnston Avenue in Kearny was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (787935, 201809, 3, 2139, 201809, 3, 2139, 131711, 'GULF OF MEXICO', 85, 2018, 'September', 'Marine Thunderstorm Wind', 'KEY', '03-SEP-18 21:39:00', 'EST-5', '03-SEP-18 21:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 39, 'MG', NULL, NULL, 2, 'SE', 'BIG COPPITT KEY', 2, 'SE', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'Isolated gale-force wind gusts occurred within rain bands across the Lower Florida Keys, indirectly-associated with Tropical Storm Gordon, located well north of the Florida Keys.', 'A wind gust of 39 knots was measured at the Naval Air Station Key West Boca Chica Field.');
INSERT INTO public.stormevents_east VALUES (787936, 201809, 3, 2152, 201809, 3, 2152, 131711, 'GULF OF MEXICO', 85, 2018, 'September', 'Marine Thunderstorm Wind', 'KEY', '03-SEP-18 21:52:00', 'EST-5', '03-SEP-18 21:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 2, 'SE', 'BIG COPPITT KEY', 2, 'SE', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'Isolated gale-force wind gusts occurred within rain bands across the Lower Florida Keys, indirectly-associated with Tropical Storm Gordon, located well north of the Florida Keys.', 'A wind gust of 38 knots was measured at the Naval Air Station Key West Boca Chica Field.');
INSERT INTO public.stormevents_east VALUES (754436, 201806, 10, 1235, 201806, 10, 1235, 125806, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 12:35:00', 'EST-5', '10-JUN-18 12:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SSE', 'LOW GAP', 2, 'SSE', 'LOW GAP', 36.5072, -80.857, 36.5072, -80.857, 'Strong daytime heating helped destabilize the atmosphere, allowing a thunderstorm to  briefly intensify to severe levels during the afternoon and produce locally-damaging winds.', 'At least two trees were blown down by thunderstorm winds at the Low Gap Recycling Center.');
INSERT INTO public.stormevents_east VALUES (755248, 201806, 11, 2351, 201806, 12, 100, 125983, 'KENTUCKY', 21, 2018, 'June', 'Flash Flood', 'RLX', '11-JUN-18 23:51:00', 'EST-5', '12-JUN-18 01:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'PACTOLUS', 1, 'SSE', 'GRAYSON', 38.3614, -82.9375, 38.3206, -82.9456, 'As a cold front sunk through the middle Ohio River Valley, showers and thunderstorms moved through northeastern Kentucky late on the 11th into early on the 12th. With abundant moisture in the atmosphere these showers and storms produced heavy rainfall.', 'High water closed a portion of Rupert Lane near the Grayson city limits.');
INSERT INTO public.stormevents_east VALUES (768818, 201806, 20, 2055, 201806, 20, 2055, 128186, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '20-JUN-18 20:55:00', 'EST-5', '20-JUN-18 20:55:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'GIBSONVILLE', 1, 'SE', 'GIBSONVILLE', 36.11, -79.54, 36.11, -79.54, 'Isolated pulse severe storms developed near the Piedmont trough at mid-afternoon. These storms formed into clusters as they moved east-southeast. The strongest and isolated severe storms affected Moore, Lee, Harnett, Johnston, Wilson, Franklin, Nash, and Edgecombe Counties. There were frequent CG strikes that affected Harnett, Johnston, and eastern Wake Counties as well, with some house fires reported.', 'Multiple trees were reported down in Gibsonville, with some falling on homes.');
INSERT INTO public.stormevents_east VALUES (768865, 201806, 22, 2006, 201806, 22, 2006, 128191, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 20:06:00', 'EST-5', '22-JUN-18 20:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 3, 'NW', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 3, 'NW', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 37.01, -76.35, 37.01, -76.35, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the James River.', 'Wind gust of 36 knots was measured at Hampton Flats.');
INSERT INTO public.stormevents_east VALUES (768998, 201806, 25, 1714, 201806, 25, 1714, 128213, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 17:14:00', 'EST-5', '25-JUN-18 17:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 3, 'NNW', 'CAMPBELL', 1, 'W', 'BLAIR MILLS', 34.559, -82.555, 34.551, -82.525, 'Scattered thunderstorms developed over the Upstate during the afternoon. Some of these storms produced severe weather in the form of damaging winds and large hail. Meanwhile, clusters of storms moved out of the North Carolina mountains and across the Upstate during the late afternoon and evening, producing areas of wind damage.', 'Highway patrol reported a tree blown down at Griffin Rd and Highway 29 and another tree down on Dorchester Rd.');
INSERT INTO public.stormevents_east VALUES (768905, 201806, 18, 1654, 201806, 18, 1654, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:54:00', 'EST-5', '18-JUN-18 16:54:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NNW', 'HURLEYVILLE', 1, 'NNW', 'HURLEYVILLE', 41.75, -74.69, 41.75, -74.69, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines at Mitteer Road.');
INSERT INTO public.stormevents_east VALUES (768914, 201806, 18, 1448, 201806, 18, 1448, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 14:48:00', 'EST-5', '18-JUN-18 14:48:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'ROME', 1, 'NW', 'ROME', 41.86, -76.34, 41.86, -76.34, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees which blocked some roadways.');
INSERT INTO public.stormevents_east VALUES (768920, 201806, 24, 1647, 201806, 24, 1647, 128203, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '24-JUN-18 16:47:00', 'EST-5', '24-JUN-18 16:47:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SW', 'HUNTSVILLE', 1, 'SW', 'HUNTSVILLE', 41.29, -75.99, 41.29, -75.99, 'An area of low pressure moved across Pennsylvania on the 24th triggered a couple severe thunderstorms in northeast Pennsylvania.', 'Thunderstorm winds knocked down numerous trees.');
INSERT INTO public.stormevents_east VALUES (766214, 201806, 18, 1500, 201806, 18, 1500, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:00:00', 'EST-5', '18-JUN-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'E', 'SCHUYLERVILLE', 1, 'E', 'SCHUYLERVILLE', 43.1, -73.58, 43.1, -73.58, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'One tree was downed along Route 29.');
INSERT INTO public.stormevents_east VALUES (766216, 201806, 18, 1504, 201806, 18, 1504, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:04:00', 'EST-5', '18-JUN-18 15:04:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'GRAFTON', 2, 'WSW', 'GRAFTON', 42.76, -73.49, 42.76, -73.49, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (766217, 201806, 18, 1504, 201806, 18, 1504, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:04:00', 'EST-5', '18-JUN-18 15:04:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 4, 'NNE', 'SARATOGA LAKE', 4, 'NNE', 'SARATOGA LAKE', 43.1, -73.71, 43.1, -73.71, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Trees were snapped and uprooted along Route 50.');
INSERT INTO public.stormevents_east VALUES (766218, 201806, 18, 1505, 201806, 18, 1505, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:05:00', 'EST-5', '18-JUN-18 15:05:00', 0, 0, 0, 0, NULL, NULL, 'COOP Observer', 50, 'EG', NULL, NULL, 1, 'SE', 'GREENWICH', 1, 'SE', 'GREENWICH', 43.09, -73.5, 43.09, -73.5, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Widespread trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (760745, 201805, 17, 1200, 201805, 19, 2130, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '19-MAY-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 5, 'NE', 'NORGE', 5, 'NE', 'NORGE', 37.41, -76.71, 37.41, -76.71, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 4.01 inches at Mesonet Station YRSV2 (York River State Park).');
INSERT INTO public.stormevents_east VALUES (766506, 201806, 18, 1818, 201806, 18, 1818, 127822, 'CONNECTICUT', 9, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 18:18:00', 'EST-5', '18-JUN-18 18:18:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SHARON', 1, 'E', 'SHARON', 41.88, -73.47, 41.88, -73.47, 'A hot and humid air mass was in place across the region.  This provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down.', 'A tree was knocked down across a roadway.');
INSERT INTO public.stormevents_east VALUES (768408, 201806, 22, 405, 201806, 22, 530, 128138, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '22-JUN-18 04:05:00', 'EST-5', '22-JUN-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'MONTROSE', 1, 'ESE', 'MONTROSE', 37.51, -77.36, 37.5099, -77.3567, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Dump truck was submerged in high water along Charles City Road near Glen Alden Drive near the Richmond Airport.');
INSERT INTO public.stormevents_east VALUES (765382, 201806, 8, 1945, 201806, 8, 2100, 127635, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PBZ', '08-JUN-18 19:45:00', 'EST-5', '08-JUN-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'CLAIRTON', 1, 'E', 'CLAIRTON', 40.2995, -79.8772, 40.3002, -79.8753, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  The storms produced scattered reports of flooding in portions of southwest Pennsylvania.', 'Flooding was reported on North State Street near Ostermayer Avenue by county 911 officials.');
INSERT INTO public.stormevents_east VALUES (765383, 201806, 8, 1949, 201806, 8, 2100, 127635, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PBZ', '08-JUN-18 19:49:00', 'EST-5', '08-JUN-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'VERSAILLES', 1, 'ESE', 'VERSAILLES', 40.3096, -79.8272, 40.3091, -79.8269, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  The storms produced scattered reports of flooding in portions of southwest Pennsylvania.', 'County 911 officials reported roadway flooding at 1441 Boston Hollow Road.');
INSERT INTO public.stormevents_east VALUES (760749, 201805, 17, 1200, 201805, 19, 2131, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '19-MAY-18 21:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 3, 'ENE', 'ROGERS CORNER', 3, 'ENE', 'ROGERS CORNER', 36.73, -78.36, 36.73, -78.36, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 9.18 inches at Mesonet Station AP329 (3 E Rogers Corner).');
INSERT INTO public.stormevents_east VALUES (768725, 201806, 17, 1254, 201806, 17, 1254, 128178, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '17-JUN-18 12:54:00', 'EST-5', '17-JUN-18 12:54:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WSW', 'TYNDALL', 1, 'WSW', 'TYNDALL', 40.2166, -81.9011, 40.2166, -81.9011, 'Hot and humid conditions were prevalent under an upper level ridge. A few thunderstorms formed during the afternoon hours of both June 16th and June 17th.   Sufficient instability and dry air aloft allowed for isolated downbursts, creating a few instances of wind damage.', 'A trained spotter reported that trees were blown down on Township Road 285.');
INSERT INTO public.stormevents_east VALUES (768727, 201806, 17, 1406, 201806, 17, 1406, 128178, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '17-JUN-18 14:06:00', 'EST-5', '17-JUN-18 14:06:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'WNW', 'OAKLAND', 1, 'WNW', 'OAKLAND', 39.9381, -82.0002, 39.9381, -82.0002, 'Hot and humid conditions were prevalent under an upper level ridge. A few thunderstorms formed during the afternoon hours of both June 16th and June 17th.   Sufficient instability and dry air aloft allowed for isolated downbursts, creating a few instances of wind damage.', 'Local law enforcement reported several trees were blown down on the eastern side of Zanesville.');
INSERT INTO public.stormevents_east VALUES (768729, 201806, 17, 1520, 201806, 17, 1520, 128178, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '17-JUN-18 15:20:00', 'EST-5', '17-JUN-18 15:20:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'WNW', 'SHARON', 1, 'WNW', 'SHARON', 39.74, -81.59, 39.74, -81.59, 'Hot and humid conditions were prevalent under an upper level ridge. A few thunderstorms formed during the afternoon hours of both June 16th and June 17th.   Sufficient instability and dry air aloft allowed for isolated downbursts, creating a few instances of wind damage.', 'A single tree was reported by local law enforcement to be blown down along State Route 78.');
INSERT INTO public.stormevents_east VALUES (768724, 201806, 16, 1941, 201806, 16, 1941, 128178, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '16-JUN-18 19:41:00', 'EST-5', '16-JUN-18 19:41:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'WNW', 'IRONSPOT', 2, 'WNW', 'IRONSPOT', 39.83, -82.1, 39.83, -82.1, 'Hot and humid conditions were prevalent under an upper level ridge. A few thunderstorms formed during the afternoon hours of both June 16th and June 17th.   Sufficient instability and dry air aloft allowed for isolated downbursts, creating a few instances of wind damage.', 'Several trees were reported by local law enforcement to be blown down near County Route 88 between Roseville and Fultonham.');
INSERT INTO public.stormevents_east VALUES (768726, 201806, 17, 1400, 201806, 17, 1400, 128178, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '17-JUN-18 14:00:00', 'EST-5', '17-JUN-18 14:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NE', 'ZANESVILLE PARR ARPT', 1, 'NE', 'ZANESVILLE PARR ARPT', 40.0089, -82.0058, 40.0089, -82.0058, 'Hot and humid conditions were prevalent under an upper level ridge. A few thunderstorms formed during the afternoon hours of both June 16th and June 17th.   Sufficient instability and dry air aloft allowed for isolated downbursts, creating a few instances of wind damage.', 'Several trees were reported by local law enforcement to be blown down near the intersection of Dresden Road and Fairview Road.');
INSERT INTO public.stormevents_east VALUES (768710, 201806, 24, 1448, 201806, 24, 1448, 128175, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 14:48:00', 'EST-5', '24-JUN-18 14:48:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'WAYAH DEPOT', 2, 'E', 'WAYAH DEPOT', 35.17, -83.49, 35.17, -83.49, 'For the second day in a row, thunderstorm clusters produced isolated wind damage across the North Carolina mountains after moving into the area from East Tennessee.', 'County comms reported two trees blown down.');
INSERT INTO public.stormevents_east VALUES (768711, 201806, 24, 1501, 201806, 24, 1501, 128175, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 15:01:00', 'EST-5', '24-JUN-18 15:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NE', 'NORTON', 2, 'NE', 'NORTON', 35.04, -83.36, 35.04, -83.36, 'For the second day in a row, thunderstorm clusters produced isolated wind damage across the North Carolina mountains after moving into the area from East Tennessee.', 'Law enforcement reported a few trees and power lines blown down near Otto.');
INSERT INTO public.stormevents_east VALUES (754435, 201806, 10, 1425, 201806, 10, 1427, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 14:25:00', 'EST-5', '10-JUN-18 14:27:00', 0, 0, 0, 0, '45.00K', '0.00K', 'Public', 60, 'EG', NULL, NULL, 2, 'ESE', 'SANDLEDGE', 2, 'N', 'SARDIS', 37.6584, -79.1206, 37.6563, -79.1174, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'Considerable damage occurred to a residential farm property due to thunderstorm winds.   A large barn was completely destroyed, with debris scattered a significant distance away.  Numerous trees in the nearby area were damaged or blown down by the thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (754431, 201806, 10, 1600, 201806, 10, 1600, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 16:00:00', 'EST-5', '10-JUN-18 16:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'GALAX CITY', 1, 'ESE', 'GALAX CITY', 36.6605, -80.901, 36.6605, -80.901, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'One large tree was blown down by thunderstorm winds along Tower Road while another tree was blown down along Hebron Road.');
INSERT INTO public.stormevents_east VALUES (754432, 201806, 10, 1930, 201806, 10, 1930, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 19:30:00', 'EST-5', '10-JUN-18 19:30:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'SOUTH BOSTON', 1, 'NE', 'SOUTH BOSTON', 36.7129, -78.8875, 36.7129, -78.8875, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'A large tree was blown down by thunderstorm winds along Hamilton Boulevard.');
INSERT INTO public.stormevents_east VALUES (754433, 201806, 10, 1942, 201806, 10, 1942, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 19:42:00', 'EST-5', '10-JUN-18 19:42:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SSE', 'BARKSDALE', 3, 'SSE', 'BARKSDALE', 36.5841, -79.1424, 36.5841, -79.1424, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'Three trees were blown down by thunderstorm winds along Highway 58.');
INSERT INTO public.stormevents_east VALUES (754434, 201806, 10, 1634, 201806, 10, 1634, 125805, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '10-JUN-18 16:34:00', 'EST-5', '10-JUN-18 16:34:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 2, 'E', 'WILLIS STORE', 2, 'E', 'WILLIS STORE', 37.0724, -80.2155, 37.0724, -80.2155, 'The passage of an upper level disturbance, as well as strong heating ahead of a cold front situated north of the region, supported the development of multiple severe thunderstorms, producing mainly wind damage.', 'Several trees were blown down by thunderstorm winds along Shawsville Pike.');
INSERT INTO public.stormevents_east VALUES (752638, 201806, 9, 1654, 201806, 9, 1654, 125497, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '09-JUN-18 16:54:00', 'EST-5', '09-JUN-18 16:54:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'AMHERST', 1, 'NNW', 'AMHERST', 37.5945, -79.0603, 37.5945, -79.0603, 'A few severe thunderstorms developed across the Piedmont and foothills of central Virginia, ahead of a weak cold front drifting southward from the Ohio River region.  While instability appeared marginal across the region, a weak upper level disturbance aloft provided additional support for these storms to briefly intensify to severe levels.  Precipitable water values ahead of the front were observed around 1.5 inches which contributed to heavy downpours with locally observed amounts of 2 to 3 inches in a few hours time.', 'A few trees were blown down by severe thunderstorm winds across the community of Amherst.');
INSERT INTO public.stormevents_east VALUES (769848, 201806, 26, 1325, 201806, 26, 1325, 128331, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 13:25:00', 'EST-5', '26-JUN-18 13:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'MILLS RIVER', 1, 'SE', 'MILLS RIVER', 35.39, -82.57, 35.39, -82.57, 'Scattered to numerous thunderstorms developed over the high terrain of western North Carolina during the afternoon, then moved steadily southeast across the valleys and the foothills. A few of these storms produced locally damaging winds. This was followed by a decaying line of strong to severe storms that moved into the mountains from East Tennessee during the evening, which was responsible for wind damage that was more widespread, mainly for the counties along the state line.', 'County comms reported multiple trees blown down in the Mills River area.');
INSERT INTO public.stormevents_east VALUES (769849, 201806, 26, 1343, 201806, 26, 1343, 128331, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 13:43:00', 'EST-5', '26-JUN-18 13:43:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'FLETCHER', 1, 'E', 'FLETCHER', 35.43, -82.5, 35.43, -82.5, 'Scattered to numerous thunderstorms developed over the high terrain of western North Carolina during the afternoon, then moved steadily southeast across the valleys and the foothills. A few of these storms produced locally damaging winds. This was followed by a decaying line of strong to severe storms that moved into the mountains from East Tennessee during the evening, which was responsible for wind damage that was more widespread, mainly for the counties along the state line.', 'County comms reported multiple trees blown down in the Fletcher area.');
INSERT INTO public.stormevents_east VALUES (767666, 201807, 21, 1245, 201807, 21, 1245, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 12:45:00', 'EST-5', '21-JUL-18 12:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'WAUKEENAH', 1, 'W', 'WAUKEENAH', 30.41, -83.96, 30.41, -83.96, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'A tree was blown down in the southbound lane near W Capps Highway and St Augustine Road.');
INSERT INTO public.stormevents_east VALUES (767668, 201807, 21, 1255, 201807, 21, 1255, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 12:55:00', 'EST-5', '21-JUL-18 12:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'GREENVILLE', 0, 'N', 'GREENVILLE', 30.47, -83.63, 30.47, -83.63, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees were blown down in Greenville.');
INSERT INTO public.stormevents_east VALUES (767669, 201807, 21, 1300, 201807, 21, 1300, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 13:00:00', 'EST-5', '21-JUL-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'MADISON', 0, 'N', 'MADISON', 30.46, -83.41, 30.46, -83.41, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees were blown down in Madison.');
INSERT INTO public.stormevents_east VALUES (768074, 201806, 10, 1307, 201806, 10, 1407, 127985, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 13:07:00', 'EST-5', '10-JUN-18 14:07:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'GAVERS', 1, 'NW', 'GAVERS', 40.71, -80.81, 40.7099, -80.8099, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event. Flooding reports were received from Columbiana, Jefferson, and Harrison Counties in Ohio.  Tree damage from severe thunderstorm wind also occurred in Columbiana County.', 'The county 911 Call Center reported road closed due to high water.');
INSERT INTO public.stormevents_east VALUES (768075, 201806, 10, 1900, 201806, 10, 2100, 127985, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 19:00:00', 'EST-5', '10-JUN-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CADIZ', 1, 'ESE', 'CADIZ', 40.27, -81, 40.2663, -80.9895, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event. Flooding reports were received from Columbiana, Jefferson, and Harrison Counties in Ohio.  Tree damage from severe thunderstorm wind also occurred in Columbiana County.', 'Local police department reported flooded roadways along Route 250.');
INSERT INTO public.stormevents_east VALUES (768076, 201806, 10, 1915, 201806, 10, 2015, 127985, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 19:15:00', 'EST-5', '10-JUN-18 20:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'ADENA', 0, 'SE', 'ADENA', 40.22, -80.88, 40.2193, -80.879, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event. Flooding reports were received from Columbiana, Jefferson, and Harrison Counties in Ohio.  Tree damage from severe thunderstorm wind also occurred in Columbiana County.', 'Citizens of Adena reported flooding near the bridge in Adena, OH. Multiple homes had flooded yards as well.');
INSERT INTO public.stormevents_east VALUES (768745, 201806, 10, 1610, 201806, 10, 1900, 127985, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 16:10:00', 'EST-5', '10-JUN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'SALINEVILLE', 1, 'NW', 'SALINEVILLE', 40.62, -80.84, 40.6245, -80.8383, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event. Flooding reports were received from Columbiana, Jefferson, and Harrison Counties in Ohio.  Tree damage from severe thunderstorm wind also occurred in Columbiana County.', 'Roadway flooding was reported in Salineville.');
