INSERT INTO public.stormevents_east VALUES (759884, 201805, 14, 1844, 201805, 14, 1844, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 18:44:00', 'EST-5', '14-MAY-18 18:44:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'SE', 'BEVERLY HILLS', 1, 'SE', 'BEVERLY HILLS', 37.59, -77.56, 37.59, -77.56, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'An estimated wind gust of 60 mph knocked down a large tree near Tuckahoe.');
