INSERT INTO public.stormevents_east VALUES (759892, 201805, 14, 1848, 201805, 14, 1848, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 18:48:00', 'EST-5', '14-MAY-18 18:48:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 44, 'WSW', 'WELLFORD', 44, 'WSW', 'WELLFORD', 37.55, -77.46, 37.55, -77.46, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Twitter reported a photo of a tree down on Grove Avenue. The tree was laying on top of two vehicles.');
INSERT INTO public.stormevents_east VALUES (791266, 201811, 6, 1200, 201811, 6, 1200, 132244, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '06-NOV-18 12:00:00', 'EST-5', '06-NOV-18 12:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 40, 'MG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'Mild and moist air with limited instability moved across the region ahead of an eastward moving cold front. This combined with high amounts of wind shear to create a squall line that moved across the waters, producing gusty winds.', 'A wind gust of 40 knots was measured at Thomas Point.');
INSERT INTO public.stormevents_east VALUES (791267, 201811, 24, 1700, 201811, 24, 1700, 132245, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '24-NOV-18 17:00:00', 'EST-5', '24-NOV-18 17:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'A low pressure system moved up the east coast of the United States on November 24th with the warm sector of the system moving across the waters during the late day hours. This generated a limited amount of instability which combined with high levels of wind shear to produce gusty showers.', 'A wind gust of up to 34 knots was observed at Cuckold Creek.');
INSERT INTO public.stormevents_east VALUES (791268, 201811, 24, 1704, 201811, 24, 1729, 132245, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '24-NOV-18 17:04:00', 'EST-5', '24-NOV-18 17:29:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 43, 'MG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'A low pressure system moved up the east coast of the United States on November 24th with the warm sector of the system moving across the waters during the late day hours. This generated a limited amount of instability which combined with high levels of wind shear to produce gusty showers.', 'A wind gust of 43 knots was measured at Cobb Point.');
