INSERT INTO public.stormevents_east VALUES (768417, 201806, 22, 600, 201806, 22, 600, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 06:00:00', 'EST-5', '22-JUN-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'N', 'VARINA GROVE', 1, 'N', 'VARINA GROVE', 37.46, -77.35, 37.46, -77.35, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 4.35 inches was reported at Station VA-HR-13 (Varina).');
INSERT INTO public.stormevents_east VALUES (768420, 201806, 22, 600, 201806, 22, 600, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 06:00:00', 'EST-5', '22-JUN-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'W', 'HUNTERDALE', 1, 'W', 'HUNTERDALE', 36.7, -76.98, 36.7, -76.98, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 3.41 inches was reported at Station VA-ST-16 (Hunterdale).');
INSERT INTO public.stormevents_east VALUES (768425, 201806, 22, 654, 201806, 22, 654, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 06:54:00', 'EST-5', '22-JUN-18 06:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 1, 'S', 'SANDSTON', 1, 'S', 'SANDSTON', 37.51, -77.32, 37.51, -77.32, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 7.43 inches was reported at RIC.');
INSERT INTO public.stormevents_east VALUES (768428, 201806, 22, 655, 201806, 22, 655, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 06:55:00', 'EST-5', '22-JUN-18 06:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', NULL, NULL, NULL, NULL, 2, 'ESE', 'LOUISA', 2, 'ESE', 'LOUISA', 38.01, -77.97, 38.01, -77.97, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 3.97 inches was reported at LKU.');
INSERT INTO public.stormevents_east VALUES (768956, 201806, 24, 1616, 201806, 24, 1616, 128175, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 16:16:00', 'EST-5', '24-JUN-18 16:16:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', '(HSS)HOT SPGS', 1, 'ENE', '(HSS)HOT SPGS', 35.89, -82.83, 35.89, -82.83, 'For the second day in a row, thunderstorm clusters produced isolated wind damage across the North Carolina mountains after moving into the area from East Tennessee.', 'County comms reported multiple power lines blown down in the Hot Springs area.');
INSERT INTO public.stormevents_east VALUES (768957, 201806, 24, 1700, 201806, 24, 1700, 128175, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 17:00:00', 'EST-5', '24-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'N', 'OTEEN', 1, 'N', 'OTEEN', 35.59, -82.5, 35.59, -82.5, 'For the second day in a row, thunderstorm clusters produced isolated wind damage across the North Carolina mountains after moving into the area from East Tennessee.', 'NWS volunteer student relayed report of multiple trees blown down along the Swannanoa River in East Asheville.');
INSERT INTO public.stormevents_east VALUES (751087, 201806, 1, 1518, 201806, 1, 1525, 125233, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '01-JUN-18 15:18:00', 'EST-5', '01-JUN-18 15:25:00', 0, 0, 0, 0, '8.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'PINE RIDGE', 2, 'NE', 'PINE RIDGE', 36.5029, -80.6971, 36.5245, -80.6902, 'Instability associated with a passing upper level disturbance combined with strong surface heating to trigger spotty showers and thunderstorms.  A few of the storms reached severe intensity for brief periods of time across the foothills of the Blue Ridge into the Piedmont of northern North Carolina.', 'Several trees were blown down by severe thunderstorms winds, including along W. Pine Street, Laila Lane and on Sparger Road.');
INSERT INTO public.stormevents_east VALUES (751083, 201806, 1, 1500, 201806, 1, 1500, 125233, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '01-JUN-18 15:00:00', 'EST-5', '01-JUN-18 15:00:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 2, 'WNW', 'ELKIN', 2, 'WNW', 'ELKIN', 36.26, -80.88, 36.2591, -80.8797, 'Instability associated with a passing upper level disturbance combined with strong surface heating to trigger spotty showers and thunderstorms.  A few of the storms reached severe intensity for brief periods of time across the foothills of the Blue Ridge into the Piedmont of northern North Carolina.', 'Multiple trees were blown down by severe thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (751084, 201806, 1, 1550, 201806, 1, 1550, 125233, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '01-JUN-18 15:50:00', 'EST-5', '01-JUN-18 15:50:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'E', 'JONESVILLE', 0, 'WSW', 'ARLINGTON', 36.23, -80.84, 36.2287, -80.8361, 'Instability associated with a passing upper level disturbance combined with strong surface heating to trigger spotty showers and thunderstorms.  A few of the storms reached severe intensity for brief periods of time across the foothills of the Blue Ridge into the Piedmont of northern North Carolina.', 'Multiple trees were blown down by severe thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (752641, 201806, 9, 1730, 201806, 9, 1730, 125497, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '09-JUN-18 17:30:00', 'EST-5', '09-JUN-18 17:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SSE', 'MONROE', 1, 'SSE', 'MONROE', 37.4888, -79.1225, 37.4888, -79.1225, 'A few severe thunderstorms developed across the Piedmont and foothills of central Virginia, ahead of a weak cold front drifting southward from the Ohio River region.  While instability appeared marginal across the region, a weak upper level disturbance aloft provided additional support for these storms to briefly intensify to severe levels.  Precipitable water values ahead of the front were observed around 1.5 inches which contributed to heavy downpours with locally observed amounts of 2 to 3 inches in a few hours time.', 'Several large limbs were blown down out of trees by severe thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (752643, 201806, 9, 1748, 201806, 9, 1748, 125497, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '09-JUN-18 17:48:00', 'EST-5', '09-JUN-18 17:48:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'BUNCHER', 1, 'NW', 'BUNCHER', 37.4611, -79.1963, 37.4611, -79.1963, 'A few severe thunderstorms developed across the Piedmont and foothills of central Virginia, ahead of a weak cold front drifting southward from the Ohio River region.  While instability appeared marginal across the region, a weak upper level disturbance aloft provided additional support for these storms to briefly intensify to severe levels.  Precipitable water values ahead of the front were observed around 1.5 inches which contributed to heavy downpours with locally observed amounts of 2 to 3 inches in a few hours time.', 'A tree was blown down along John Scott Drive by severe thunderstorm winds.');
