INSERT INTO public.stormevents_east VALUES (760995, 201805, 18, 1100, 201805, 19, 1600, 126956, 'MARYLAND', 24, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 11:00:00', 'EST-5', '19-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'HURLOCK', 1, 'SSE', 'EAST NEW MARKET', 38.63, -75.87, 38.5795, -75.892, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of the Lower Maryland Eastern Shore.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (761080, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'HIGHLAND SPGS', 1, 'N', 'WINDSOR PLACE', 37.55, -77.33, 37.5481, -77.3805, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county. Also, a pool and tennis court were flooded at Patterson Avenue and Lauderdale Drive just northwest of Tuckahoe.');
INSERT INTO public.stormevents_east VALUES (761071, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'GOOCHLAND', 1, 'SW', 'GOOCHLAND', 37.68, -77.88, 37.663, -77.8968, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county. Also, Riddles Bridge Road in Goochland was washed out.');
INSERT INTO public.stormevents_east VALUES (760998, 201805, 19, 1615, 201805, 22, 1615, 126957, 'MARYLAND', 24, 2018, 'May', 'Flood', 'AKQ', '19-MAY-18 16:15:00', 'EST-5', '22-MAY-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'SNOW HILL', 2, 'N', 'SNOW HILL', 38.18, -75.4, 38.2095, -75.3935, 'Flooding occurred along the Pocomoke River and Nassawango Creek in southwest Worcester county.', 'Flooding occurred along the Pocomoke River and Nassawango Creek in southwest Worcester county. The Route 12 bridge near Snow Hill was closed due to flooding, along with several roads.');
INSERT INTO public.stormevents_east VALUES (761357, 201805, 19, 1600, 201805, 25, 400, 127031, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '19-MAY-18 16:00:00', 'EST-5', '25-MAY-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'AYLETT', 1, 'SW', 'AYLETT', 37.7863, -77.1038, 37.7692, -77.111, 'Flooding occurred along the Mattaponi River in East Central Virginia.', 'Flooding occurred along the Mattaponi River over several days, with roads and low lying areas near the river impacted the most.');
INSERT INTO public.stormevents_east VALUES (761362, 201805, 19, 1655, 201805, 21, 1645, 127032, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '19-MAY-18 16:55:00', 'EST-5', '21-MAY-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'RUTHER GLEN', 2, 'NW', 'BURRUSS CORNER', 37.8977, -77.4777, 37.8998, -77.441, 'Flooding occurred along the North Anna River, South Anna River, and Pamunkey River in central Virginia.', 'Flooding occurred along the North Anna River over a couple of days, with roads and low lying areas near the river impacted the most.');
INSERT INTO public.stormevents_east VALUES (770910, 201806, 20, 1435, 201806, 20, 1800, 128458, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '20-JUN-18 14:35:00', 'EST-5', '20-JUN-18 18:00:00', 0, 0, 0, 0, '5.00K', '0.50K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'LOYALHANNA', 1, 'WSW', 'LOYALHANNA', 40.3205, -79.3796, 40.3171, -79.3935, 'Heavy rain with little, if any, lightning moved along a stationary front in a tropical environment.  Moisture was plentiful, with precipitable water values of over 2 inches.  Rainfall totals reached levels that were 350% of flash flood guidance, with 1-hour rainfall totals approaching levels that were 350% above guidance and had a 0.5% annual occurrence probability.  Allegheny County activated their EOC due to the flooding and severe weather. Numerous flooding incidents were reported, and approximately 66 water rescues were needed throughout the county. Flooding damaged a number of basement foundations. Bethel Park partially activated their EOC for massive flooding.  Here, water rescues occurred in the area of the Trolley Stop Inn, with 27 persons requiring rescue. Water rescues were conducted from Scott Township to Bridgeville Borough. One female was killed in Bridgeville Borough. She left her trapped car and was swept away by flood waters. Bethel Park submitted a municipal disaster declaration. ||In Westmoreland County, flash floods and heavy rains occurred throughout the Ligonier Borough, Ligonier Township, Cook Township areas of the of the Loyalhanna and Mill Creek watershed in Westmoreland County causing localized flooding, road closures, wires down, and requiring multiple water rescues to be conducted of individuals in vehicles in flooded roadways. The Ligonier Valley area in eastern Westmoreland County was especially hard hit by flooded roadways that necessitated water rescues. The Westmoreland County EOC was activated for the flooding.  The Johnstown, Cambria County Fire Department Swift Water Rescue Team was dispatched to assist in Ligonier Township.  Several areas in the county experienced heavy basement flooding and Cook Township had first floor flooding of a residence on Green Hollow Lane that required three occupants to be rescued from a rooftop. Four adults, two children, and one dog were evacuated from two other residences. Residential flooding occurred in the area of Snowman Lane and Blouch Lane that required a water rescue of one resident.', 'The 911 Call Center reported a number of roads in the city of Latrobe have been flooded.');
