INSERT INTO public.stormevents_east VALUES (768464, 201806, 22, 819, 201806, 22, 819, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 08:19:00', 'EST-5', '22-JUN-18 08:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'NE', 'BON AIR', 1, 'NE', 'BON AIR', 37.53, -77.56, 37.53, -77.56, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 3.92 inches was reported at Mesonet Station RCRMR (Bon Air).');
