INSERT INTO public.stormevents_east VALUES (768472, 201806, 22, 820, 201806, 22, 820, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 08:20:00', 'EST-5', '22-JUN-18 08:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 0, 'N', 'MINERAL', 0, 'N', 'MINERAL', 38.02, -77.92, 38.02, -77.92, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 6.96 inches was reported at Mesonet Station MINRL (Mineral).');
INSERT INTO public.stormevents_east VALUES (751086, 201806, 1, 1615, 201806, 1, 1615, 125233, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '01-JUN-18 16:15:00', 'EST-5', '01-JUN-18 16:15:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'WINDSORS XRDS', 1, 'E', 'WINDSORS XRDS', 36.07, -80.81, 36.07, -80.81, 'Instability associated with a passing upper level disturbance combined with strong surface heating to trigger spotty showers and thunderstorms.  A few of the storms reached severe intensity for brief periods of time across the foothills of the Blue Ridge into the Piedmont of northern North Carolina.', 'Multiple trees were blown down by severe thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (751085, 201806, 1, 1622, 201806, 1, 1645, 125233, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '01-JUN-18 16:22:00', 'EST-5', '01-JUN-18 16:45:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'SSE', 'ARLINGTON', 2, 'WNW', 'HUNTSVILLE', 36.2186, -80.8227, 36.0948, -80.5591, 'Instability associated with a passing upper level disturbance combined with strong surface heating to trigger spotty showers and thunderstorms.  A few of the storms reached severe intensity for brief periods of time across the foothills of the Blue Ridge into the Piedmont of northern North Carolina.', 'Numerous trees were blown down across Yadkin County by severe thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (751089, 201806, 1, 1532, 201806, 1, 1533, 125234, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '01-JUN-18 15:32:00', 'EST-5', '01-JUN-18 15:33:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 3, 'E', 'FINCASTLE', 3, 'E', 'FINCASTLE', 37.5041, -79.8346, 37.5052, -79.8331, 'Instability associated with a passing upper level disturbance combined with strong surface heating to trigger spotty showers and thunderstorms. A few of the storms reached severe intensity for brief periods of time across the Piedmont of central Virginia.', 'A large tree was blown onto home by severe thunderstorm winds near the intersection of Springwood and Wheatland Road, while another tree was blown down further along Springwood Road.');
INSERT INTO public.stormevents_east VALUES (751090, 201806, 3, 1735, 201806, 3, 1735, 125235, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '03-JUN-18 17:35:00', 'EST-5', '03-JUN-18 17:35:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SSW', 'WOODLAWN', 1, 'SSW', 'WOODLAWN', 36.7055, -80.8252, 36.7055, -80.8252, 'Strong daytime heating triggered a few thunderstorms across southwest Virginia, with one of these storms reaching severe intensity for a brief period of time.', 'Multiple trees were blown down by severe thunderstorm winds along Taylor Lane.');
INSERT INTO public.stormevents_east VALUES (758217, 201806, 25, 1712, 201806, 25, 1712, 126500, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '25-JUN-18 17:12:00', 'EST-5', '25-JUN-18 17:12:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'FRANCISCO', 1, 'WNW', 'FRANCISCO', 36.5085, -80.386, 36.5085, -80.386, 'An upper level disturbance moving along an approaching weak cold front triggered a few severe thunderstorms across the foothills of the Blue Ridge in northern North Carolina.', 'A tree was blown down by thunderstorm winds along George Farm Road.');
INSERT INTO public.stormevents_east VALUES (758220, 201806, 25, 1715, 201806, 25, 1719, 126500, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '25-JUN-18 17:15:00', 'EST-5', '25-JUN-18 17:19:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'MOORES SPGS', 1, 'N', 'VADE MECUM', 36.4447, -80.3653, 36.4282, -80.3209, 'An upper level disturbance moving along an approaching weak cold front triggered a few severe thunderstorms across the foothills of the Blue Ridge in northern North Carolina.', 'A tree was blown down by thunderstorm winds along Highway 66 near Brown Mountain Church Road, while another tree was blown down along Keaton Road.');
INSERT INTO public.stormevents_east VALUES (758214, 201806, 25, 1618, 201806, 25, 1618, 126500, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '25-JUN-18 16:18:00', 'EST-5', '25-JUN-18 16:18:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NE', 'PURLEAR', 1, 'NE', 'PURLEAR', 36.1931, -81.2634, 36.1931, -81.2634, 'An upper level disturbance moving along an approaching weak cold front triggered a few severe thunderstorms across the foothills of the Blue Ridge in northern North Carolina.', 'Two trees were blown down by thunderstorm winds along Arbor Grove Church Road.');
INSERT INTO public.stormevents_east VALUES (752646, 201806, 9, 1814, 201806, 9, 1814, 125497, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '09-JUN-18 18:14:00', 'EST-5', '09-JUN-18 18:14:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'LYH IVY HILL ARPT', 2, 'SSE', 'LYH IVY HILL ARPT', 37.3673, -79.2024, 37.3673, -79.2024, 'A few severe thunderstorms developed across the Piedmont and foothills of central Virginia, ahead of a weak cold front drifting southward from the Ohio River region.  While instability appeared marginal across the region, a weak upper level disturbance aloft provided additional support for these storms to briefly intensify to severe levels.  Precipitable water values ahead of the front were observed around 1.5 inches which contributed to heavy downpours with locally observed amounts of 2 to 3 inches in a few hours time.', 'A tree was blown down by thunderstorm winds along the entrance ramp to Highway 501 from Fort Avenue.');
INSERT INTO public.stormevents_east VALUES (769858, 201806, 26, 1706, 201806, 26, 1736, 128331, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 17:06:00', 'EST-5', '26-JUN-18 17:36:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 6, 'WSW', 'MT STERLING', 5, 'ESE', 'COVE', 35.712, -83.191, 35.637, -82.877, 'Scattered to numerous thunderstorms developed over the high terrain of western North Carolina during the afternoon, then moved steadily southeast across the valleys and the foothills. A few of these storms produced locally damaging winds. This was followed by a decaying line of strong to severe storms that moved into the mountains from East Tennessee during the evening, which was responsible for wind damage that was more widespread, mainly for the counties along the state line.', 'County comms reported numerous trees blown down in the northern part of Haywood county.');
INSERT INTO public.stormevents_east VALUES (769860, 201806, 26, 1756, 201806, 26, 1804, 128331, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 17:56:00', 'EST-5', '26-JUN-18 18:04:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'LEICESTER', 0, 'WSW', 'HOMINY', 35.65, -82.688, 35.548, -82.688, 'Scattered to numerous thunderstorms developed over the high terrain of western North Carolina during the afternoon, then moved steadily southeast across the valleys and the foothills. A few of these storms produced locally damaging winds. This was followed by a decaying line of strong to severe storms that moved into the mountains from East Tennessee during the evening, which was responsible for wind damage that was more widespread, mainly for the counties along the state line.', 'County comms reported numerous trees blown down along Leicester Highway near Leicester and numerous trees and power lines down in the Candler area. One tree fell on a home in Candler.');
INSERT INTO public.stormevents_east VALUES (769861, 201806, 27, 1410, 201806, 27, 1410, 128335, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 14:10:00', 'EST-5', '27-JUN-18 14:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ENE', 'SUNNY VIEW', 3, 'ENE', 'SUNNY VIEW', 35.39, -82.13, 35.39, -82.13, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast. Some of the storms produced damaging wind gusts across the southern foothills.', 'County comms reported multiple trees down near the Rutherford County line including on Polk County Line Rd and Rock Springs Rd.');
INSERT INTO public.stormevents_east VALUES (769862, 201806, 27, 1415, 201806, 27, 1415, 128335, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 14:15:00', 'EST-5', '27-JUN-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'COLUMBUS', 2, 'ENE', 'COLUMBUS', 35.26, -82.16, 35.26, -82.16, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast. Some of the storms produced damaging wind gusts across the southern foothills.', 'County comms and the public reported numerous trees blown down in the area around Fox Mountain Rd, Smith Dairy Rd, and Huntview Ln.');
INSERT INTO public.stormevents_east VALUES (769863, 201806, 27, 1444, 201806, 27, 1458, 128335, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 14:44:00', 'EST-5', '27-JUN-18 14:58:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'WSW', 'BOILING SPGS', 5, 'S', 'BOILING SPGS', 35.218, -81.751, 35.18, -81.679, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast. Some of the storms produced damaging wind gusts across the southern foothills.', 'County comms reported multiple trees blown down south of Boiling Springs.');
INSERT INTO public.stormevents_east VALUES (770627, 201806, 27, 1430, 201806, 27, 1430, 128335, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 14:30:00', 'EST-5', '27-JUN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'ENE', 'HARRIS SPICERS ARPT', 1, 'ENE', 'HARRIS SPICERS ARPT', 35.23, -81.85, 35.23, -81.85, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast. Some of the storms produced damaging wind gusts across the southern foothills.', 'Public reported trees uprooted on Hogan Rd near Highway 221.');
INSERT INTO public.stormevents_east VALUES (768497, 201808, 12, 1320, 201808, 12, 1320, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:20:00', 'EST-5', '12-AUG-18 13:20:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'POAGES MILL', 1, 'NE', 'POAGES MILL', 37.2076, -80.0419, 37.2076, -80.0419, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down two trees along Ran Lynn Drive and were blocking the road.');
INSERT INTO public.stormevents_east VALUES (765528, 201806, 1, 1633, 201806, 1, 1705, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 16:33:00', 'EST-5', '01-JUN-18 17:05:00', 0, 0, 0, 0, '15.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'WNW', 'BESSEMER CITY', 1, 'N', 'BELMONT SOUTH', 35.285, -81.304, 35.242, -81.029, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'County comms reported numerous trees blown down across the county. One tree fell on a house on East Georgia Ave in Bessemer City. Public reported a large tree limb fell on a vehicle in Gastonia.');
INSERT INTO public.stormevents_east VALUES (765540, 201806, 1, 1652, 201806, 1, 1706, 127663, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 16:52:00', 'EST-5', '01-JUN-18 17:06:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 5, 'SE', 'TOWNVILLE', 2, 'N', 'TOXAWAY', 34.532, -82.831, 34.53, -82.614, 'Scattered to numerous thunderstorms and storm clusters moved into the Upstate from north Georgia during the late afternoon and evening. Multiple storm clusters produced severe weather in the form of damaging wind gusts.', 'Ham Radio operator and the public reported multiple trees blown down on I-85 between mile markers 11 and 12, and multiple trees down along Quail Ridge Rd, with falling trees causing minor structural and vehicle damage. Public reported three large trees blown down on North St in Anderson, with one tree damaging a home.');
INSERT INTO public.stormevents_east VALUES (767294, 201806, 10, 2016, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 20:16:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'BOWEST JCT', 1, 'NE', 'BOWEST JCT', 39.9947, -79.5911, 39.9891, -79.5897, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Baldridge Avenue in South Connellsville was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (768910, 201806, 13, 2102, 201806, 13, 2110, 128200, 'PENNSYLVANIA', 42, 2018, 'June', 'Tornado', 'BGM', '13-JUN-18 21:02:00', 'EST-5', '13-JUN-18 21:10:00', 6, 0, 0, 0, '5.00M', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'WSW', 'BOULEVARD MANOR', 1, 'ESE', 'LEE PARK', 41.2436, -75.8467, 41.2245, -75.7969, 'A strong area of low pressure moved from northern Ontario to the Saint Lawrence Valley from the day of the 13th into the evening. This low pressure system pushed a cold front into northeast Pennsylvania during the evening of the 13th. This front triggered severe thunderstorms which spawned two EF2 tornadoes, one in Bradford County and the other Wilkes-Barre, Pennsylvania. The E2 tornados knocked down numerous trees, destroyed several homes and damaged up to 24 businesses. There were no deaths and 6 minor injuries.', 'A severe thunderstorm moved across Luzerne County between 930 and|1030 pm on Wednesday June 13 2018, producing an EF2 tornado in |Wilkes-Barre Township around 1000 pm. The tornado touched down |at Mundy Street and Highland Park Boulevard near the Wyoming |Valley Mall, then traveled across Interstate 81 and up into the woods|on Wilkes-Barre Mountain. Tornado damage continued on a broken |path through the State Game Lands before dissipating near |Llewelyn Corners and Interstate 476. Numerous roofs were destroyed and |windows blown out throughout the shopping center. Some structures |were sheared off near their foundation. Power poles were snapped |with numerous lines down. Several signs were destroyed, and |debris was scattered throughout the region. One piece of sign was |found approximately 7 miles from the mall area. A total of 23 business were damaged, with some suffering major damage. Maximum estimated winds were at 130 mph.');
INSERT INTO public.stormevents_east VALUES (768904, 201806, 18, 1654, 201806, 18, 1654, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:54:00', 'EST-5', '18-JUN-18 16:54:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'HARRIS', 0, 'N', 'HARRIS', 41.72, -74.73, 41.72, -74.73, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees near Route 17 and Bushville Road.');
INSERT INTO public.stormevents_east VALUES (768084, 201806, 13, 2004, 201806, 13, 2104, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '13-JUN-18 20:04:00', 'EST-5', '13-JUN-18 21:04:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'FURNACE RUN', 0, 'SSE', 'FURNACE RUN', 40.8482, -79.5528, 40.8452, -79.5487, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'A state official washed out Montgomery and Tarrtown Road near East Franklin Township.');
INSERT INTO public.stormevents_east VALUES (757707, 201807, 1, 2200, 201807, 1, 2202, 125774, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'ILN', '01-JUL-18 22:00:00', 'EST-5', '01-JUL-18 22:02:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'S', 'HOMEDALE', 1, 'S', 'HOMEDALE', 40.0532, -83.0226, 40.0532, -83.0226, 'Scattered thunderstorms developed during the afternoon hours in a hot and humid air mass that was in place across the Ohio Valley.', 'A few trees were downed and a fence was damaged.');
INSERT INTO public.stormevents_east VALUES (757713, 201807, 3, 2230, 201807, 3, 2232, 125856, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'ILN', '03-JUL-18 22:30:00', 'EST-5', '03-JUL-18 22:32:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 45, 'EG', NULL, NULL, 1, 'WNW', 'COLUMBUS', 1, 'WNW', 'COLUMBUS', 40.0352, -83.0226, 40.0352, -83.0226, 'Scattered thunderstorms developed during the afternoon hours in a hot and humid air mass that was in place across the Ohio Valley.', 'A tree was downed onto some power lines.');
INSERT INTO public.stormevents_east VALUES (760769, 201805, 17, 1200, 201805, 20, 700, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '20-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'W', 'SAMPSONS WHARF', 1, 'W', 'SAMPSONS WHARF', 37.87, -76.42, 37.87, -76.42, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 5.39 inches at (2 E) Howland.');
INSERT INTO public.stormevents_east VALUES (760770, 201805, 17, 1200, 201805, 20, 830, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '20-MAY-18 08:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'S', 'YELLOW TAVERN', 1, 'S', 'YELLOW TAVERN', 37.62, -77.47, 37.62, -77.47, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 6.72 inches at Lakeside.');
