INSERT INTO public.stormevents_east VALUES (760776, 201805, 17, 1200, 201805, 20, 840, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '20-MAY-18 08:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'E', 'EAST HIGHLAND PARK', 1, 'E', 'EAST HIGHLAND PARK', 37.57, -77.38, 37.57, -77.38, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 8.64 inches at Mesonet Station RCHRV (East Highland Park).');
