INSERT INTO public.stormevents_east VALUES (761118, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'PRINCE GEORGE', 2, 'S', 'POE', 37.22, -77.28, 37.1516, -77.3277, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (761119, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'NEWLAND', 3, 'NNW', 'FARMERS FORK', 38.05, -76.87, 38.0635, -76.8237, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (761120, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'RICHMOND', 2, 'ESE', 'RICHMOND', 37.55, -77.45, 37.5442, -77.4183, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (771010, 201806, 20, 1517, 201806, 20, 1630, 128458, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '20-JUN-18 15:17:00', 'EST-5', '20-JUN-18 16:30:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'INGRAM', 2, 'SSE', 'GAYLY', 40.43, -80.11, 40.4285, -80.1202, 'Heavy rain with little, if any, lightning moved along a stationary front in a tropical environment.  Moisture was plentiful, with precipitable water values of over 2 inches.  Rainfall totals reached levels that were 350% of flash flood guidance, with 1-hour rainfall totals approaching levels that were 350% above guidance and had a 0.5% annual occurrence probability.  Allegheny County activated their EOC due to the flooding and severe weather. Numerous flooding incidents were reported, and approximately 66 water rescues were needed throughout the county. Flooding damaged a number of basement foundations. Bethel Park partially activated their EOC for massive flooding.  Here, water rescues occurred in the area of the Trolley Stop Inn, with 27 persons requiring rescue. Water rescues were conducted from Scott Township to Bridgeville Borough. One female was killed in Bridgeville Borough. She left her trapped car and was swept away by flood waters. Bethel Park submitted a municipal disaster declaration. ||In Westmoreland County, flash floods and heavy rains occurred throughout the Ligonier Borough, Ligonier Township, Cook Township areas of the of the Loyalhanna and Mill Creek watershed in Westmoreland County causing localized flooding, road closures, wires down, and requiring multiple water rescues to be conducted of individuals in vehicles in flooded roadways. The Ligonier Valley area in eastern Westmoreland County was especially hard hit by flooded roadways that necessitated water rescues. The Westmoreland County EOC was activated for the flooding.  The Johnstown, Cambria County Fire Department Swift Water Rescue Team was dispatched to assist in Ligonier Township.  Several areas in the county experienced heavy basement flooding and Cook Township had first floor flooding of a residence on Green Hollow Lane that required three occupants to be rescued from a rooftop. Four adults, two children, and one dog were evacuated from two other residences. Residential flooding occurred in the area of Snowman Lane and Blouch Lane that required a water rescue of one resident.', 'The 911 Call Center reported that Campbells Run is overflowing its banks and flooding nearby roadways (including Campbells Run Road).');
INSERT INTO public.stormevents_east VALUES (770963, 201806, 20, 2015, 201806, 21, 130, 128458, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '20-JUN-18 20:15:00', 'EST-5', '21-JUN-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'CLIFTON', 1, 'ENE', 'CLIFTON', 40.34, -80.08, 40.3342, -80.0773, 'Heavy rain with little, if any, lightning moved along a stationary front in a tropical environment.  Moisture was plentiful, with precipitable water values of over 2 inches.  Rainfall totals reached levels that were 350% of flash flood guidance, with 1-hour rainfall totals approaching levels that were 350% above guidance and had a 0.5% annual occurrence probability.  Allegheny County activated their EOC due to the flooding and severe weather. Numerous flooding incidents were reported, and approximately 66 water rescues were needed throughout the county. Flooding damaged a number of basement foundations. Bethel Park partially activated their EOC for massive flooding.  Here, water rescues occurred in the area of the Trolley Stop Inn, with 27 persons requiring rescue. Water rescues were conducted from Scott Township to Bridgeville Borough. One female was killed in Bridgeville Borough. She left her trapped car and was swept away by flood waters. Bethel Park submitted a municipal disaster declaration. ||In Westmoreland County, flash floods and heavy rains occurred throughout the Ligonier Borough, Ligonier Township, Cook Township areas of the of the Loyalhanna and Mill Creek watershed in Westmoreland County causing localized flooding, road closures, wires down, and requiring multiple water rescues to be conducted of individuals in vehicles in flooded roadways. The Ligonier Valley area in eastern Westmoreland County was especially hard hit by flooded roadways that necessitated water rescues. The Westmoreland County EOC was activated for the flooding.  The Johnstown, Cambria County Fire Department Swift Water Rescue Team was dispatched to assist in Ligonier Township.  Several areas in the county experienced heavy basement flooding and Cook Township had first floor flooding of a residence on Green Hollow Lane that required three occupants to be rescued from a rooftop. Four adults, two children, and one dog were evacuated from two other residences. Residential flooding occurred in the area of Snowman Lane and Blouch Lane that required a water rescue of one resident.', 'The 911 Call Center reported that a female became trapped in her car on McLaughlin Run Road. She got out of her vehicle and attempted to walk home, however she was swept away by the flood waters of McLaughlin Run and carried about 2 miles downstream. Her body was found the next morning. A number of small bridges were destroyed along McLaughlin Run Road and near McMillian Road. Parked cars were sweep downstream along McLaughlin Run and were destroyed. An Outback Steakhouse had severe water damage. A state of emergency was declared in Upper St. Clair; Allegheny County officials had at least 66 swift water rescues (CBS Pittsburgh).');
