INSERT INTO public.stormevents_east VALUES (784174, 201809, 12, 1400, 201809, 12, 1430, 131087, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 14:00:00', 'EST-5', '12-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'CRESCENT BEACH', 0, 'ENE', 'CRESCENT BEACH', 41.3233, -72.1922, 41.3238, -72.1923, 'Showers and thunderstorms developed along a stationary front draped across southern Connecticut during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over southeast Connecticut. A cooperative observer in Norwich reported 4.62 inches of rain with these storms, the bulk of which fell over a period of 2-3 hours.', 'Main Street was closed at Pennsylvania Avenue in Niantic due to flooding.');
INSERT INTO public.stormevents_east VALUES (784176, 201809, 12, 1400, 201809, 12, 1430, 131087, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 14:00:00', 'EST-5', '12-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'POQUONOCK BRIDGE', 1, 'NNW', 'POQUONOCK BRIDGE', 41.3464, -72.0387, 41.3473, -72.0387, 'Showers and thunderstorms developed along a stationary front draped across southern Connecticut during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over southeast Connecticut. A cooperative observer in Norwich reported 4.62 inches of rain with these storms, the bulk of which fell over a period of 2-3 hours.', 'The intersection of Route 1 and Route 12 as well as the intersection of Route 1 and South Road were closed due to flooding in Groton.');
INSERT INTO public.stormevents_east VALUES (784178, 201809, 12, 1400, 201809, 12, 1430, 131087, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 14:00:00', 'EST-5', '12-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'HAPPYLAND', 1, 'SSE', 'HAPPYLAND', 41.4647, -72.0628, 41.4636, -72.0646, 'Showers and thunderstorms developed along a stationary front draped across southern Connecticut during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over southeast Connecticut. A cooperative observer in Norwich reported 4.62 inches of rain with these storms, the bulk of which fell over a period of 2-3 hours.', 'Tanager Lane closed due to flooding in Happyland.');
INSERT INTO public.stormevents_east VALUES (784213, 201809, 25, 1103, 201809, 25, 1430, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 11:03:00', 'EST-5', '25-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'GRANTON JCT', 1, 'N', 'UNION CITY', 40.7849, -74.0468, 40.7849, -74.0489, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'New Jersey Route 3 flooded westbound in the area of the eastern spur of the New Jersey Turnpike in Secaucus.');
INSERT INTO public.stormevents_east VALUES (784215, 201809, 25, 1110, 201809, 25, 1430, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 11:10:00', 'EST-5', '25-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'JERSEY CITY ARPT', 1, 'W', 'JERSEY CITY ARPT', 40.7211, -74.1128, 40.7212, -74.1135, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'Portions of Central Avenue in Kearny were impassable due to 3-4 feet of standing water.');
INSERT INTO public.stormevents_east VALUES (784214, 201809, 25, 1105, 201809, 25, 1430, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 11:05:00', 'EST-5', '25-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'JERSEY CITY ARPT', 0, 'NNE', 'JERSEY CITY ARPT', 40.7267, -74.0946, 40.7252, -74.0956, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'All lanes closed in both directions due to flooding on the US Route 1 & 9 truck route approaching NJ 440 in West Bergen.');
INSERT INTO public.stormevents_east VALUES (784217, 201809, 25, 1111, 201809, 25, 1430, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 11:11:00', 'EST-5', '25-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'COMMUNIPAW', 1, 'WSW', 'GREENVILLE', 40.6886, -74.1021, 40.6906, -74.0999, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'A ramp was closed due to flooding on the New Jersey Turnpike-Hudson County Extension outside interchange 14A (NJ 440A/Bayonne Bridge) in Bayonne.');
INSERT INTO public.stormevents_east VALUES (784225, 201809, 25, 1630, 201809, 25, 1745, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 16:30:00', 'EST-5', '25-SEP-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'TEANECK', 0, 'NW', 'TEANECK', 40.8802, -74.0462, 40.8817, -74.0524, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'Numerous roads closed due to flooding in Hackensack including Essex Street, State Street, Railroad Avenue, Sussex Street, and South Newman Street. Boats were deployed for possible rescues on Essex and State Streets.');
INSERT INTO public.stormevents_east VALUES (784226, 201809, 25, 1700, 201809, 25, 1745, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:00:00', 'EST-5', '25-SEP-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'MAYWOOD', 1, 'NE', 'MAYWOOD', 40.9105, -74.0309, 40.9102, -74.0337, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'Flooding was occurring along Commerce Way in Hackensack. Emergency management was employing mitigation methods.');
INSERT INTO public.stormevents_east VALUES (784227, 201809, 25, 1715, 201809, 25, 1745, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:15:00', 'EST-5', '25-SEP-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'TEANECK', 1, 'NNE', 'MAYWOOD', 40.8834, -74.0636, 40.9095, -74.0463, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'The Hackensack Fire Department rescued over 18 people from cars stranded in flood waters across the city. Many roads remain closed and impassable.');
INSERT INTO public.stormevents_east VALUES (768207, 201806, 20, 1635, 201806, 20, 1635, 128104, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '20-JUN-18 16:35:00', 'EST-5', '20-JUN-18 16:35:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'DAWN', 0, 'N', 'DAWN', 37.83, -77.37, 37.83, -77.37, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Tree was downed on Dawn Boulevard.');
INSERT INTO public.stormevents_east VALUES (770898, 201806, 24, 2249, 201806, 24, 2250, 126061, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '24-JUN-18 22:49:00', 'EST-5', '24-JUN-18 22:50:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 35, 'MG', NULL, NULL, 1, 'E', 'FOLLY BEACH C-MAN (FBIS1)', 1, 'E', 'FOLLY BEACH C-MAN (FBIS1)', 32.68, -79.88, 32.68, -79.88, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted toward the coast, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over coastal waters.', 'The C-MAN station at the northern end of Folly Beach recorded a 35 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (770988, 201806, 25, 2022, 201806, 25, 2023, 126063, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '25-JUN-18 20:22:00', 'EST-5', '25-JUN-18 20:23:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'SYCAMORE', 1, 'N', 'SYCAMORE', 33.04, -81.22, 33.04, -81.22, 'A warm and moist atmosphere in combination with a sea breeze circulation shifting inland  and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'The Allendale 911 Call Center reported a tree down on Highway 321 near the intersection with Main Street in Sycamore.');
INSERT INTO public.stormevents_east VALUES (771047, 201806, 20, 2030, 201806, 20, 2130, 128458, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '20-JUN-18 20:30:00', 'EST-5', '20-JUN-18 21:30:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'WHITEHALL', 1, 'SE', 'WHITEHALL', 40.3466, -79.9626, 40.3426, -79.9629, 'Heavy rain with little, if any, lightning moved along a stationary front in a tropical environment.  Moisture was plentiful, with precipitable water values of over 2 inches.  Rainfall totals reached levels that were 350% of flash flood guidance, with 1-hour rainfall totals approaching levels that were 350% above guidance and had a 0.5% annual occurrence probability.  Allegheny County activated their EOC due to the flooding and severe weather. Numerous flooding incidents were reported, and approximately 66 water rescues were needed throughout the county. Flooding damaged a number of basement foundations. Bethel Park partially activated their EOC for massive flooding.  Here, water rescues occurred in the area of the Trolley Stop Inn, with 27 persons requiring rescue. Water rescues were conducted from Scott Township to Bridgeville Borough. One female was killed in Bridgeville Borough. She left her trapped car and was swept away by flood waters. Bethel Park submitted a municipal disaster declaration. ||In Westmoreland County, flash floods and heavy rains occurred throughout the Ligonier Borough, Ligonier Township, Cook Township areas of the of the Loyalhanna and Mill Creek watershed in Westmoreland County causing localized flooding, road closures, wires down, and requiring multiple water rescues to be conducted of individuals in vehicles in flooded roadways. The Ligonier Valley area in eastern Westmoreland County was especially hard hit by flooded roadways that necessitated water rescues. The Westmoreland County EOC was activated for the flooding.  The Johnstown, Cambria County Fire Department Swift Water Rescue Team was dispatched to assist in Ligonier Township.  Several areas in the county experienced heavy basement flooding and Cook Township had first floor flooding of a residence on Green Hollow Lane that required three occupants to be rescued from a rooftop. Four adults, two children, and one dog were evacuated from two other residences. Residential flooding occurred in the area of Snowman Lane and Blouch Lane that required a water rescue of one resident.', 'The 911 Call Center reported 2400 Block of Lebanon Church Road had a vehicle stuck in flood waters.');
INSERT INTO public.stormevents_east VALUES (770473, 201806, 27, 1512, 201806, 27, 1530, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 15:12:00', 'EST-5', '27-JUN-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NNE', 'RENFREW', 2, 'W', 'GREENVILLE-SPARTANBU', 35.001, -82.441, 34.898, -82.26, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'Highway patrol and the public reported several trees blown down from Tigerville to Taylors to the Greer area. A couple of trees were also down in the Blue Ridge area.');
INSERT INTO public.stormevents_east VALUES (770825, 201806, 15, 1910, 201806, 15, 1911, 126055, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '15-JUN-18 19:10:00', 'EST-5', '15-JUN-18 19:11:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'SW', 'SLANDSVILLE', 3, 'SW', 'SLANDSVILLE', 32.95, -80.26, 32.95, -80.26, 'A highly unstable atmosphere developed across the region ahead of a backdoor cold front approaching from the north during the afternoon.', 'The South Carolina Highway Patrol reported a tree down at the intersection of Summers Drive and Highway 61.');
INSERT INTO public.stormevents_east VALUES (768208, 201806, 20, 1635, 201806, 20, 1635, 128104, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '20-JUN-18 16:35:00', 'EST-5', '20-JUN-18 16:35:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNW', 'DAWN', 2, 'NNW', 'DAWN', 37.86, -77.38, 37.86, -77.38, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Tree was downed on a power line on Concord Road.');
INSERT INTO public.stormevents_east VALUES (768209, 201806, 20, 1855, 201806, 20, 1855, 128104, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '20-JUN-18 18:55:00', 'EST-5', '20-JUN-18 18:55:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SW', 'CHASE CITY MUNI', 3, 'SW', 'CHASE CITY MUNI', 36.75, -78.53, 36.75, -78.53, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Tree was downed and blocking the road on Highway 49.');
INSERT INTO public.stormevents_east VALUES (766227, 201806, 18, 1515, 201806, 18, 1515, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:15:00', 'EST-5', '18-JUN-18 15:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NW', 'HILLS TERRACE', 1, 'NW', 'HILLS TERRACE', 41.68, -73.92, 41.68, -73.92, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Tree limbs were downed. A very large branch that broke off fell onto power lines.');
INSERT INTO public.stormevents_east VALUES (766228, 201806, 18, 1515, 201806, 18, 1515, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:15:00', 'EST-5', '18-JUN-18 15:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'S', 'SPACKENKILL', 1, 'S', 'SPACKENKILL', 41.69, -73.92, 41.69, -73.92, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Uprooted trees and large branches were downed.');
INSERT INTO public.stormevents_east VALUES (766229, 201806, 18, 1516, 201806, 18, 1516, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:16:00', 'EST-5', '18-JUN-18 15:16:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NW', 'SPRAGUETOWN', 1, 'NW', 'SPRAGUETOWN', 43.14, -73.49, 43.14, -73.49, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Multiple wires, poles and trees were downed on County Route 113 and County Route 70 in the town of Greenwich.');
INSERT INTO public.stormevents_east VALUES (766230, 201806, 18, 1516, 201806, 18, 1516, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:16:00', 'EST-5', '18-JUN-18 15:16:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'WEST HEBRON', 0, 'N', 'WEST HEBRON', 43.23, -73.38, 43.23, -73.38, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'A tree was downed onto a residence on Patterson Hill Road.');
INSERT INTO public.stormevents_east VALUES (768474, 201806, 22, 825, 201806, 22, 825, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 08:25:00', 'EST-5', '22-JUN-18 08:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'N', 'VARINA GROVE', 1, 'N', 'VARINA GROVE', 37.46, -77.35, 37.46, -77.35, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Rainfall total of 3.52 inches was reported at Mesonet Station E5195 (Varina).');
INSERT INTO public.stormevents_east VALUES (768486, 201806, 22, 137, 201806, 22, 137, 128138, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '22-JUN-18 01:37:00', 'EST-5', '22-JUN-18 01:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'SE', 'RICHMOND', 2, 'SE', 'RICHMOND', 37.53, -77.43, 37.53, -77.43, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Minor flooding of roadways was reported at the corner of 18th and Cary Street in Shockoe Bottom.');
INSERT INTO public.stormevents_east VALUES (768496, 201806, 22, 620, 201806, 22, 1100, 128138, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '22-JUN-18 06:20:00', 'EST-5', '22-JUN-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'SANDSTON', 1, 'ESE', 'MANBUR', 37.52, -77.32, 37.5272, -77.3216, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'High water was reported over Berry Street in Sandston. Other roads were flooded and closed in the area.');
INSERT INTO public.stormevents_east VALUES (768501, 201806, 22, 652, 201806, 22, 1100, 128138, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '22-JUN-18 06:52:00', 'EST-5', '22-JUN-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'VARINA GROVE', 2, 'N', 'VARINA GROVE', 37.48, -77.36, 37.4802, -77.3551, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Two cars were stuck in flood waters on Darbytown Road and South Laburnum Avenue. The police had part of the road blocked off. Other roads were flooded and closed in the area.');
INSERT INTO public.stormevents_east VALUES (768505, 201806, 22, 645, 201806, 22, 900, 128138, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '22-JUN-18 06:45:00', 'EST-5', '22-JUN-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'LOUISA', 1, 'ENE', 'MINERAL', 38.03, -78, 38.0296, -77.898, 'Scattered thunderstorms along a frontal boundary produced heavy rain which caused flash flooding and flooding across portions of central Virginia.', 'Numerous road closures and water rescues were reported between Mineral and Louisa.');
INSERT INTO public.stormevents_east VALUES (768749, 201806, 22, 1657, 201806, 22, 1657, 128180, 'VIRGINIA', 51, 2018, 'June', 'Hail', 'AKQ', '22-JUN-18 16:57:00', 'EST-5', '22-JUN-18 16:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 2, 'WNW', 'GASBURG', 2, 'WNW', 'GASBURG', 36.58, -77.91, 36.58, -77.91, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Quarter size hail was reported.');
