INSERT INTO public.stormevents_east VALUES (768779, 201806, 22, 1805, 201806, 22, 1805, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 18:05:00', 'EST-5', '22-JUN-18 18:05:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SSE', 'SUSSEX', 1, 'SSE', 'SUSSEX', 36.9, -77.27, 36.9, -77.27, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Trees were snapped on Hines Lane. Acrylic greenhouse was damaged.');
INSERT INTO public.stormevents_east VALUES (758221, 201806, 25, 1724, 201806, 25, 1724, 126500, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RNK', '25-JUN-18 17:24:00', 'EST-5', '25-JUN-18 17:24:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'CAPELLA', 1, 'NNW', 'CAPELLA', 36.3771, -80.3222, 36.3771, -80.3222, 'An upper level disturbance moving along an approaching weak cold front triggered a few severe thunderstorms across the foothills of the Blue Ridge in northern North Carolina.', 'A tree was blown down by thunderstorm winds along Capella Road near the Closer Walk Baptist Church.');
