INSERT INTO public.stormevents_east VALUES (754759, 201806, 24, 1526, 201806, 24, 1526, 125872, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '24-JUN-18 15:26:00', 'EST-5', '24-JUN-18 15:26:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'WINGINA', 2, 'SSE', 'WINGINA', 37.6056, -78.6995, 37.6056, -78.6995, 'An upper level disturbance passed across the mid-Atlantic during late afternoon, triggering scattered thunderstorms. A couple of storms intensified to severe levels across central Virginia.', 'A tree was blown down by thunderstorm winds along Meadow Creek Road.');
INSERT INTO public.stormevents_east VALUES (754760, 201806, 24, 1531, 201806, 24, 1536, 125872, 'VIRGINIA', 51, 2018, 'June', 'Hail', 'RNK', '24-JUN-18 15:31:00', 'EST-5', '24-JUN-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 3, 'SSW', 'MT VINCO', 3, 'SSW', 'MT VINCO', 37.5681, -78.6256, 37.5681, -78.6256, 'An upper level disturbance passed across the mid-Atlantic during late afternoon, triggering scattered thunderstorms. A couple of storms intensified to severe levels across central Virginia.', NULL);
INSERT INTO public.stormevents_east VALUES (769866, 201806, 27, 1507, 201806, 27, 1507, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 15:07:00', 'EST-5', '27-JUN-18 15:07:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 4, 'SSW', 'PUMPKINTOWN', 2, 'N', 'EASLEY', 34.945, -82.67, 34.857, -82.598, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'Trained spotter reported a tree down blocking the road at Connelly Road and Highway 8. Public reported (via Social Media) a tree down on a house on Noble Rd.');
INSERT INTO public.stormevents_east VALUES (769867, 201806, 27, 1536, 201806, 27, 1610, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 15:36:00', 'EST-5', '27-JUN-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'PELHAM', 1, 'NNE', 'CROSS ANCHOR', 34.844, -82.195, 34.667, -81.843, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'County comms reported many trees blown down across the western part of the county.');
INSERT INTO public.stormevents_east VALUES (769868, 201806, 27, 1612, 201806, 27, 1630, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 16:12:00', 'EST-5', '27-JUN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'WEST SPGS', 3, 'SW', 'LOCKHART', 34.748, -81.795, 34.749, -81.487, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'County comms reported multiple trees and power lines blown down throughout Union County.');
INSERT INTO public.stormevents_east VALUES (770458, 201806, 27, 1555, 201806, 27, 1643, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 15:55:00', 'EST-5', '27-JUN-18 16:43:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'WSW', 'SHARON', 2, 'E', 'SMITH', 34.948, -81.342, 34.828, -81.071, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'County comms reported numerous trees blown down in the southern and western part of York County, especially in the McConnells area. Public also reported damage to some outbuildings along Steele Village Rd south of Rock Hill.');
INSERT INTO public.stormevents_east VALUES (770467, 201806, 27, 1640, 201806, 27, 1714, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 16:40:00', 'EST-5', '27-JUN-18 17:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'NE', 'LEWIS', 1, 'E', 'FT LAWN', 34.816, -81.115, 34.698, -80.88, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'County comms reported numerous trees blown down in eastern portions of Chester County.');
INSERT INTO public.stormevents_east VALUES (770468, 201806, 27, 1641, 201806, 27, 1725, 128336, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '27-JUN-18 16:41:00', 'EST-5', '27-JUN-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 2, 'NNW', 'LEEDS', 1, 'NE', 'BECKHAMVILLE', 34.66, -81.399, 34.588, -80.908, 'Scattered clusters of thunderstorms developed during the afternoon across the mountains and foothills of North Carolina and moved southeast into Upstate South Carolina. Some of the storms produced damaging wind gusts.', 'County comms reported numerous trees blown down throughout the county.');
INSERT INTO public.stormevents_east VALUES (770481, 201806, 29, 1810, 201806, 29, 1810, 128425, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '29-JUN-18 18:10:00', 'EST-5', '29-JUN-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'JOANNA', 1, 'SW', 'JOANNA', 34.41, -81.81, 34.41, -81.81, 'Scattered afternoon and evening thunderstorms developed along a slow-moving backdoor cold front across the South Carolina Piedmont. One of the storms produced brief damaging winds across Laurens County.', 'County comms reported multiple trees blown down in the Joanna area.');
INSERT INTO public.stormevents_east VALUES (767295, 201806, 10, 1729, 201806, 10, 1729, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '10-JUN-18 17:29:00', 'EST-5', '10-JUN-18 17:29:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'VANDERBILT', 1, 'E', 'VANDERBILT', 40.03, -79.66, 40.03, -79.66, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Trees were reported to be blown down just south of Vanderbilt.');
INSERT INTO public.stormevents_east VALUES (767298, 201806, 10, 1815, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:15:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'GROTZTOWN', 0, 'W', 'GROTZTOWN', 40.23, -79.7856, 40.2293, -79.7853, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported at 258 Sutersville Road in Grotztown.');
INSERT INTO public.stormevents_east VALUES (767296, 201806, 10, 1733, 201806, 10, 1733, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '10-JUN-18 17:33:00', 'EST-5', '10-JUN-18 17:33:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'LEISENRING', 1, 'E', 'LEISENRING', 40, -79.64, 40, -79.64, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Power lines were blown down on Highland Street in Leisenring.');
INSERT INTO public.stormevents_east VALUES (767300, 201806, 10, 1839, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:39:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'COLLINSBURG', 0, 'NW', 'COLLINSBURG', 40.2328, -79.805, 40.2337, -79.8041, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Residential flooding was reported on 1st Avenue in Sutersville.');
INSERT INTO public.stormevents_east VALUES (768088, 201806, 13, 1720, 201806, 13, 1720, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 17:20:00', 'EST-5', '13-JUN-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'E', 'WEST KITTANNING', 1, 'E', 'WEST KITTANNING', 40.82, -79.52, 40.82, -79.52, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'County Emergency Manager reported multiple trees down in downtown Kittanning.');
INSERT INTO public.stormevents_east VALUES (768087, 201806, 13, 1945, 201806, 13, 2045, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '13-JUN-18 19:45:00', 'EST-5', '13-JUN-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'RURAL VLY', 1, 'W', 'RURAL VLY', 40.8007, -79.3091, 40.8004, -79.3101, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'An emergency manager reported that roadway in Rural Valley was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (768090, 201806, 13, 1721, 201806, 13, 1721, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 17:21:00', 'EST-5', '13-JUN-18 17:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'KITTANNING', 1, 'SE', 'KITTANNING', 40.81, -79.49, 40.81, -79.49, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'The county Emergency Manager reported trees on power lines near Indian Hills Road.');
INSERT INTO public.stormevents_east VALUES (768092, 201806, 13, 1720, 201806, 13, 1721, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Funnel Cloud', 'PBZ', '13-JUN-18 17:20:00', 'EST-5', '13-JUN-18 17:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'NE', 'WEST KITTANNING', 1, 'NE', 'WEST KITTANNING', 40.83, -79.52, 40.83, -79.52, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'A citizen reported a funnel cloud near East Franklin Shopping Center.');
INSERT INTO public.stormevents_east VALUES (771690, 201807, 5, 1434, 201807, 5, 1434, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 14:34:00', 'EST-5', '05-JUL-18 14:34:00', 0, 0, 0, 0, '1.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 2, 'SE', 'FAIRVIEW', 2, 'SE', 'FAIRVIEW', 41.4509, -81.8167, 41.4509, -81.8167, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm winds downed a tree.');
INSERT INTO public.stormevents_east VALUES (771691, 201807, 5, 1442, 201807, 5, 1442, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 14:42:00', 'EST-5', '05-JUL-18 14:42:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'WSW', 'CLEVELAND', 1, 'WSW', 'CLEVELAND', 41.4605, -81.7709, 41.4605, -81.7709, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm winds downed a tree on West 119th Street.  The tree landed on a car causing some damage.');
INSERT INTO public.stormevents_east VALUES (771692, 201807, 5, 1725, 201807, 5, 1725, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 17:25:00', 'EST-5', '05-JUL-18 17:25:00', 0, 0, 0, 0, '12.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 0, 'N', 'LEAVITTSBURG', 0, 'N', 'LEAVITTSBURG', 41.25, -80.88, 41.25, -80.88, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm wind gusts estimated to be at least 60 mph downed several trees in the Leavittsburg area.');
INSERT INTO public.stormevents_east VALUES (772604, 201807, 5, 1420, 201807, 5, 1420, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 14:20:00', 'EST-5', '05-JUL-18 14:20:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NE', 'SHELBY', 2, 'NE', 'SHELBY', 40.9067, -82.618, 40.9067, -82.618, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm winds downed some trees and large limbs along Miller Road northeast of Shelby.  A power line was also down in the area.');
INSERT INTO public.stormevents_east VALUES (772605, 201807, 5, 1710, 201807, 5, 1710, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 17:10:00', 'EST-5', '05-JUL-18 17:10:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'EDINBURG', 0, 'N', 'EDINBURG', 41.1, -81.15, 41.1, -81.15, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm winds downed several trees and at least one utility pole in Edinburg Township.');
INSERT INTO public.stormevents_east VALUES (772606, 201807, 5, 1645, 201807, 5, 1645, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 16:45:00', 'EST-5', '05-JUL-18 16:45:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'RANDOLPH', 0, 'N', 'RANDOLPH', 41.03, -81.25, 41.03, -81.25, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm winds downed a tree in Randolph Township.');
INSERT INTO public.stormevents_east VALUES (772607, 201807, 5, 1357, 201807, 5, 1405, 128613, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '05-JUL-18 13:57:00', 'EST-5', '05-JUL-18 14:05:00', 0, 0, 0, 0, '35.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'BUCYRUS', 0, 'N', 'BUCYRUS', 40.8, -82.98, 40.8, -82.98, 'A cold front moved across northern Ohio during the afternoon of July 5th.  Scattered showers and thunderstorms developed in advance of the front.  A couple of the thunderstorms became severe and caused some damage.', 'Thunderstorm winds downed several trees and a couple utility poles in the Bucyrus area.  Scattered power outages were also reported.');
INSERT INTO public.stormevents_east VALUES (772610, 201807, 16, 1747, 201807, 16, 1747, 128829, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CLE', '16-JUL-18 17:47:00', 'EST-5', '16-JUL-18 17:47:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'MEADVILLE', 0, 'N', 'MEADVILLE', 41.63, -80.15, 41.63, -80.15, 'A cold front moved across the Upper Ohio Valley on July 16th.  Scattered thunderstorms developed in advance of the front.  Some damage was reported in Crawford County.', 'Thunderstorm winds downed several trees in the Meadville area.');
INSERT INTO public.stormevents_east VALUES (773133, 201807, 26, 1650, 201807, 26, 1650, 128935, 'OHIO', 39, 2018, 'July', 'Hail', 'CLE', '26-JUL-18 16:50:00', 'EST-5', '26-JUL-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'PAINESVILLE', 0, 'N', 'PAINESVILLE', 41.73, -81.25, 41.73, -81.25, 'A cold front swept east across the Upper Ohio Valley on July 26th causing a lines of thunderstorms to develop.  A lot of storm damage was reported along the central lakeshore counties of Lake Erie.  Sandusky in Erie County sustained the worst of the damage.', 'Penny sized hail was observed.');
INSERT INTO public.stormevents_east VALUES (773134, 201807, 26, 1714, 201807, 26, 1714, 128935, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '26-JUL-18 17:14:00', 'EST-5', '26-JUL-18 17:14:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Social Media', 60, 'EG', NULL, NULL, 4, 'SW', 'KIRTLAND', 4, 'SW', 'KIRTLAND', 41.5891, -81.4248, 41.5891, -81.4248, 'A cold front swept east across the Upper Ohio Valley on July 26th causing a lines of thunderstorms to develop.  A lot of storm damage was reported along the central lakeshore counties of Lake Erie.  Sandusky in Erie County sustained the worst of the damage.', 'Thunderstorm wind gusts were estimated to be 60 mph.  A few trees were reported down.');
INSERT INTO public.stormevents_east VALUES (773135, 201807, 26, 1636, 201807, 26, 1636, 128935, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '26-JUL-18 16:36:00', 'EST-5', '26-JUL-18 16:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 54, 'MG', NULL, NULL, 0, 'N', 'PAINESVILLE', 0, 'N', 'PAINESVILLE', 41.73, -81.25, 41.73, -81.25, 'A cold front swept east across the Upper Ohio Valley on July 26th causing a lines of thunderstorms to develop.  A lot of storm damage was reported along the central lakeshore counties of Lake Erie.  Sandusky in Erie County sustained the worst of the damage.', 'A 62 mph wind gust was measured by an automated sensor at the Fairport Harbor Lighthouse.');
INSERT INTO public.stormevents_east VALUES (773129, 201807, 23, 1935, 201807, 23, 1940, 128934, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '23-JUL-18 19:35:00', 'EST-5', '23-JUL-18 19:40:00', 0, 0, 0, 0, '40.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'STRONGSVILLE', 0, 'N', 'STRONGSVILLE', 41.32, -81.83, 41.32, -81.83, 'A trough of low pressure moved across Ohio on July 24rd causing a broken line of showers and thunderstorms to develop.  There were a couple reports of damage from the stronger thunderstorms.', 'Thunderstorm winds downed a couple trees and some power lines in Strongsville.  A house along Deerfield Drive was damaged by a fallen tree.  At least 3000 electric customers in Strongsville lost power during this event.');
INSERT INTO public.stormevents_east VALUES (773132, 201807, 26, 1645, 201807, 26, 1645, 128935, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'CLE', '26-JUL-18 16:45:00', 'EST-5', '26-JUL-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'PAINESVILLE', 0, 'N', 'PAINESVILLE', 41.73, -81.25, 41.73, -81.25, 'A cold front swept east across the Upper Ohio Valley on July 26th causing a lines of thunderstorms to develop.  A lot of storm damage was reported along the central lakeshore counties of Lake Erie.  Sandusky in Erie County sustained the worst of the damage.', 'Thunderstorm winds downed a tree along Hine Avenue in Painesville.');
