INSERT INTO public.stormevents_east VALUES (760778, 201805, 17, 1200, 201805, 20, 845, 126866, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'AKQ', '17-MAY-18 12:00:00', 'EST-5', '20-MAY-18 08:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 2, 'NE', 'PORT RICHMOND', 2, 'NE', 'PORT RICHMOND', 37.57, -76.8, 37.57, -76.8, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain across much of central, south central, and eastern Virginia.', 'Three day rainfall total was 8.81 inches at Mesonet Station D1998 (West Point).');
