INSERT INTO public.stormevents_east VALUES (761045, 201805, 18, 2130, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 21:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'FARMVILLE', 2, 'S', 'KIMBERLEY HILLS', 37.3, -78.57, 37.3048, -78.4059, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
