INSERT INTO public.stormevents_east VALUES (760983, 201805, 18, 700, 201805, 18, 730, 126923, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'AKQ', '18-MAY-18 07:00:00', 'EST-5', '18-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'ELMONT', 2, 'ESE', 'FARRINGTON', 37.72, -77.5549, 37.7183, -77.5527, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused flash flooding across portions of central and south central Virginia.', 'Portion of Greenwood Road was washed out.');
INSERT INTO public.stormevents_east VALUES (760984, 201805, 18, 630, 201805, 18, 730, 126923, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'AKQ', '18-MAY-18 06:30:00', 'EST-5', '18-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'WEST END MANOR', 2, 'N', 'WEST END MANOR', 37.6784, -77.5381, 37.6784, -77.5371, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused flash flooding across portions of central and south central Virginia.', 'A low lying segment of Old Springfield Road was flooded.');
INSERT INTO public.stormevents_east VALUES (760987, 201805, 18, 700, 201805, 18, 730, 126923, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'AKQ', '18-MAY-18 07:00:00', 'EST-5', '18-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'QUIOCCASIN', 2, 'NW', 'QUIOCCASIN', 37.62, -77.6, 37.6198, -77.5967, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused flash flooding across portions of central and south central Virginia.', 'Flooding was reported in the Raintree area.');
INSERT INTO public.stormevents_east VALUES (760994, 201805, 18, 1100, 201805, 19, 1600, 126956, 'MARYLAND', 24, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 11:00:00', 'EST-5', '19-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'DELMAR', 3, 'N', 'PITTSVILLE', 38.45, -75.57, 38.4365, -75.4128, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of the Lower Maryland Eastern Shore.', 'Sinkhole was reported near the intersection of Nelson Church Road and East Line Road in Delmar. Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (760996, 201805, 18, 1100, 201805, 19, 1600, 126956, 'MARYLAND', 24, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 11:00:00', 'EST-5', '19-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'PRINCESS ANNE', 2, 'NW', 'WESTOVER', 38.2, -75.7, 38.1429, -75.7196, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of the Lower Maryland Eastern Shore.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (771050, 201806, 20, 1900, 201806, 21, 0, 128458, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '20-JUN-18 19:00:00', 'EST-5', '21-JUN-18 00:00:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ROOK', 1, 'NE', 'WOODVILLE', 40.4, -80.08, 40.389, -80.0845, 'Heavy rain with little, if any, lightning moved along a stationary front in a tropical environment.  Moisture was plentiful, with precipitable water values of over 2 inches.  Rainfall totals reached levels that were 350% of flash flood guidance, with 1-hour rainfall totals approaching levels that were 350% above guidance and had a 0.5% annual occurrence probability.  Allegheny County activated their EOC due to the flooding and severe weather. Numerous flooding incidents were reported, and approximately 66 water rescues were needed throughout the county. Flooding damaged a number of basement foundations. Bethel Park partially activated their EOC for massive flooding.  Here, water rescues occurred in the area of the Trolley Stop Inn, with 27 persons requiring rescue. Water rescues were conducted from Scott Township to Bridgeville Borough. One female was killed in Bridgeville Borough. She left her trapped car and was swept away by flood waters. Bethel Park submitted a municipal disaster declaration. ||In Westmoreland County, flash floods and heavy rains occurred throughout the Ligonier Borough, Ligonier Township, Cook Township areas of the of the Loyalhanna and Mill Creek watershed in Westmoreland County causing localized flooding, road closures, wires down, and requiring multiple water rescues to be conducted of individuals in vehicles in flooded roadways. The Ligonier Valley area in eastern Westmoreland County was especially hard hit by flooded roadways that necessitated water rescues. The Westmoreland County EOC was activated for the flooding.  The Johnstown, Cambria County Fire Department Swift Water Rescue Team was dispatched to assist in Ligonier Township.  Several areas in the county experienced heavy basement flooding and Cook Township had first floor flooding of a residence on Green Hollow Lane that required three occupants to be rescued from a rooftop. Four adults, two children, and one dog were evacuated from two other residences. Residential flooding occurred in the area of Snowman Lane and Blouch Lane that required a water rescue of one resident.', 'The 911 call center reported that the 1000 block of Washington Avenue has six vehicles stuck in rising flood waters. The Department of Transportation reports that US22 in both directions at exit East I-376/US22 is flooding.');
INSERT INTO public.stormevents_east VALUES (771026, 201806, 20, 1812, 201806, 20, 1812, 128520, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '20-JUN-18 18:12:00', 'EST-5', '20-JUN-18 18:12:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', 65, 'EG', NULL, NULL, 1, 'W', 'COLERAIN', 1, 'W', 'COLERAIN', 40.12, -80.81, 40.12, -80.81, 'Thunderstorms were able to form along a stationary front in a tropical environment.  Moisture was plentiful, with precipitable water values of over 2 inches.  One storm in Belmont County was able to generate severe winds, ripping a roof off of a barn along Highway 250.', 'An emergency manager reported that a roof was ripped off a barn along Hwy 250.');
INSERT INTO public.stormevents_east VALUES (771298, 201806, 11, 1112, 201806, 11, 1112, 128576, 'GULF OF MEXICO', 85, 2018, 'June', 'Marine Thunderstorm Wind', 'KEY', '11-JUN-18 11:12:00', 'EST-5', '11-JUN-18 11:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'SE', 'BIG COPPITT KEY', 2, 'SE', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'Gale-force wind gusts occurred in association with thunderstorms developing over the Lower Florida Keys.', 'A wind gust of 34 knots was measured at the Naval Air Station Key West Boca Chica Field.');
INSERT INTO public.stormevents_east VALUES (787860, 201809, 16, 713, 201809, 16, 1730, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 07:13:00', 'EST-5', '16-SEP-18 17:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'HAHN', 3, 'N', 'WILGROVE', 35.347, -80.699, 35.26, -80.681, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'EM and stream gauges indicated flash flooding developed during the morning of the 16th and steadily worsened through the morning and afternoon, especially across eastern and southern sections of Mecklenburg County where 6 to 10 inches fell throughout the 16th. The main streams impacted where Mallard Creek in the eastern part of the county and McAlpine and McMullen Creek and their tributaries in South Charlotte. Multiple stream gauges on these streams exceeded their established flood stages. A couple of dozen roads were closed due to urban and small stream flooding during the afternoon, especially across the south side of the city, where several water rescues were necessary and some people were briefly trapped in their homes.');
INSERT INTO public.stormevents_east VALUES (787901, 201809, 16, 1445, 201809, 16, 1700, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 14:45:00', 'EST-5', '16-SEP-18 17:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'MONTREAT', 2, 'S', 'MONTREAT', 35.628, -82.321, 35.626, -82.318, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'Law enforcement reported evacuation of a mobile home park after a tributary of Flat Creek flooded the area around Portman Villa Rd and David Dr in Black Mountain. Four to six inches of rain fell across the area throughout the 16th.');
INSERT INTO public.stormevents_east VALUES (787916, 201809, 16, 2230, 201809, 17, 400, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '16-SEP-18 22:30:00', 'EST-5', '17-SEP-18 04:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'EDGEMONT', 2, 'S', 'MORTIMER', 35.991, -81.771, 35.957, -81.768, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'A stream gauge on Wilson Creek in the Edgemont community rose above its established flood stage late on the 29th and remained in flood through much of the overnight. The main impacts were dangerously high flows on the stream, but multiple campgrounds were flooded along the river while portions of Brown Mountain Beach Rd were also flooded.');
INSERT INTO public.stormevents_east VALUES (787914, 201809, 16, 2000, 201809, 17, 600, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '16-SEP-18 20:00:00', 'EST-5', '17-SEP-18 06:00:00', 0, 0, 1, 0, '5.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'OLIVE BRANCH', 1, 'SSW', 'BRIEF', 35.146, -80.324, 35.169, -80.555, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'Although heavy rain ended across Union County during the evening, EM reported high water conditions continued through the overnight, as waters were slow to recede in light of the 7 to 13 inches that fell across the county in about 24 hours. During the morning of the 17th, an 88 year-old man drowned when he drove his vehicle through a swollen tributary on Landsford Dr.');
INSERT INTO public.stormevents_east VALUES (764719, 201806, 28, 1747, 201806, 28, 1819, 127563, 'NEW YORK', 36, 2018, 'June', 'Flash Flood', 'OKX', '28-JUN-18 17:47:00', 'EST-5', '28-JUN-18 18:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SPRINGFIELD GARDENS', 1, 'SW', 'SPRINGFIELD GARDENS', 40.6657, -73.7871, 40.6656, -73.789, 'Convection developed out ahead of an approaching cold front in a high precipitable water environment (around 2 inches based on the 12Z 6/28 OKX sounding), leading to isolated flash flooding across parts of Queens and Brooklyn. Close to one inch of rain fell in a short period of time over these areas.', 'South Conduit Avenue was closed due to flooding under the JFK Expressway near JFK Airport.');
INSERT INTO public.stormevents_east VALUES (784179, 201809, 12, 1439, 201809, 12, 1509, 131087, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 14:39:00', 'EST-5', '12-SEP-18 15:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'WEST HAVEN', 0, 'NNE', 'WEST HAVEN', 41.2839, -72.9676, 41.2841, -72.9673, 'Showers and thunderstorms developed along a stationary front draped across southern Connecticut during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over southeast Connecticut. A cooperative observer in Norwich reported 4.62 inches of rain with these storms, the bulk of which fell over a period of 2-3 hours.', 'Glade Street was closed due to flooding between Terrace Avenue and Coleman Street in West Haven. One car was stranded.');
INSERT INTO public.stormevents_east VALUES (787937, 201809, 6, 1615, 201809, 6, 1622, 131712, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'KEY', '06-SEP-18 16:15:00', 'EST-5', '06-SEP-18 16:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 3, 'W', 'BIG COPPITT KEY', 3, 'W', 'BIG COPPITT KEY', 24.5998, -81.7425, 24.5998, -81.7425, 'Scattered showers and thunderstorms moving southwest along the Lower Florida Keys were associated with one waterspout near Key West.', 'A waterspout was observed about two miles northeast of Key West.');
INSERT INTO public.stormevents_east VALUES (787938, 201809, 7, 1712, 201809, 7, 1717, 131713, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'KEY', '07-SEP-18 17:12:00', 'EST-5', '07-SEP-18 17:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 3, 'SW', 'SUMMERLAND KEY', 3, 'SW', 'SUMMERLAND KEY', 24.6312, -81.4816, 24.6312, -81.4816, 'An isolated waterspout was observed in association with widely-separated showers near Cudjoe Key.', 'A waterspout was observed about one mile south of Cudjoe Key.');
INSERT INTO public.stormevents_east VALUES (787940, 201809, 12, 1200, 201809, 12, 1210, 131715, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'KEY', '12-SEP-18 12:00:00', 'EST-5', '12-SEP-18 12:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 4, 'ESE', 'SNIPE POINT', 4, 'ESE', 'SNIPE POINT', 24.67, -81.63, 24.67, -81.63, 'An isolated waterspout was observed northeast of Big Coppitt Key in association with a cloud line and showers extending along the Gulf side of the Lower Florida Keys.', 'A waterspout was observed north of the Saddlebunch Keys, with a full funnel cloud extending from cloud base to the water surface and a spray ring.');
INSERT INTO public.stormevents_east VALUES (787941, 201809, 15, 1125, 201809, 15, 1128, 131716, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'KEY', '15-SEP-18 11:25:00', 'EST-5', '15-SEP-18 11:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 3, 'NW', 'SUMMERLAND KEY', 3, 'NW', 'SUMMERLAND KEY', 24.69, -81.48, 24.69, -81.48, 'An isolated waterspout was observed over Kemp Channel.  Very light lower tropospheric wind flow was noted.', 'A waterspout was observed over Kemp Channel.  The condensation funnel cloud did not extend very far from cloud base.');
INSERT INTO public.stormevents_east VALUES (787942, 201809, 19, 707, 201809, 19, 707, 131717, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'KEY', '19-SEP-18 07:07:00', 'EST-5', '19-SEP-18 07:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'E', 'SOMBRERO KEY LIGHT', 2, 'E', 'SOMBRERO KEY LIGHT', 24.63, -81.08, 24.63, -81.08, 'An isolated waterspout was observed in association with a rain shower south of Marathon.', 'A waterspout was observed with medium condensation funnel width about 6 miles south of Marathon and Vaca Cut.  The condensation funnel cloud extended about halfway from cloud base to the water surface.  The report was relayed via social media.');
INSERT INTO public.stormevents_east VALUES (749872, 201804, 16, 125, 201804, 16, 125, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '16-APR-18 01:25:00', 'EST-5', '16-APR-18 01:25:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'QUINTON ARPT', 1, 'S', 'QUINTON ARPT', 37.48, -77.13, 37.48, -77.13, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Large tree was downed along Route 60.');
INSERT INTO public.stormevents_east VALUES (749873, 201804, 16, 135, 201804, 16, 135, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '16-APR-18 01:35:00', 'EST-5', '16-APR-18 01:35:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'BARHAMSVILLE', 2, 'W', 'BARHAMSVILLE', 37.45, -76.89, 37.45, -76.89, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed along Homestead Road.');
INSERT INTO public.stormevents_east VALUES (749874, 201804, 16, 147, 201804, 16, 147, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '16-APR-18 01:47:00', 'EST-5', '16-APR-18 01:47:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'CROUCH', 1, 'SSW', 'CROUCH', 37.73, -76.88, 37.73, -76.88, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed near King and Queen Courthouse.');
INSERT INTO public.stormevents_east VALUES (749875, 201804, 16, 150, 201804, 16, 150, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '16-APR-18 01:50:00', 'EST-5', '16-APR-18 01:50:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ENE', 'CARRSVILLE', 1, 'ENE', 'CARRSVILLE', 36.73, -76.8, 36.73, -76.8, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed near Carrsville.');
INSERT INTO public.stormevents_east VALUES (749876, 201804, 16, 155, 201804, 16, 155, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '16-APR-18 01:55:00', 'EST-5', '16-APR-18 01:55:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'FIVE FORKS', 2, 'ENE', 'FIVE FORKS', 37.26, -76.74, 37.26, -76.74, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed along Kings Way.');
INSERT INTO public.stormevents_east VALUES (749877, 201804, 16, 347, 201804, 16, 347, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '16-APR-18 03:47:00', 'EST-5', '16-APR-18 03:47:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SSE', 'BAYVIEW', 1, 'SSE', 'BAYVIEW', 37.26, -75.96, 37.26, -75.96, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees and power lines were downed.');
INSERT INTO public.stormevents_east VALUES (758144, 201806, 22, 1430, 201806, 22, 1430, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 14:30:00', 'EST-5', '22-JUN-18 14:30:00', 0, 0, 0, 0, '0.25K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'SALEM (C)', 1, 'S', 'SALEM (C)', 37.28, -80.0495, 37.28, -80.0495, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'A large limbed was snapped off of a tree along Tennessee Street by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (766696, 201806, 3, 1204, 201806, 3, 1810, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 12:04:00', 'EST-5', '03-JUN-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'PEARRE', 2, 'NW', 'PEARRE', 39.6533, -78.343, 39.6497, -78.3409, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'The USGS stream gage on Sideling Hill Creek near Bellegrove exceeded the 7.5 foot flood stage during the indicated times, causing flooding of lowlands near the creek. The peak level of 8.02 feet was observed at 4:00pm EST on June 3rd.');
INSERT INTO public.stormevents_east VALUES (766822, 201806, 3, 1917, 201806, 3, 2024, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 19:17:00', 'EST-5', '03-JUN-18 20:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'ELLICOTT CITY', 0, 'ESE', 'ELLICOTT CITY', 39.2678, -76.7944, 39.2677, -76.7944, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'The stream gage on the Patapsco River at Ellicott City briefly exceeded the 122.50 foot flood elevation during the indicated period. The peak elevation of 122.60 feet was observed at 7:30pm EST on June 3rd. Water briefly reached the top of the inlet where the Patapsco and Tiber meet, but no inundation was reported.');
INSERT INTO public.stormevents_east VALUES (780292, 201810, 2, 1930, 201810, 2, 2130, 130331, 'NEW JERSEY', 34, 2018, 'October', 'Flash Flood', 'PHI', '02-OCT-18 19:30:00', 'EST-5', '02-OCT-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'HALSEY', 0, 'NNE', 'NEWTON', 41.0913, -74.7386, 41.0564, -74.7667, 'Thunderstorms brought locally heavy rain to northern New Jersey on the evening of October 2.', 'Sections of US Route 206 and NJ Route 94 were closed in Newton and in Hampton Township due to flooding.');
INSERT INTO public.stormevents_east VALUES (780293, 201810, 2, 2000, 201810, 2, 2200, 130331, 'NEW JERSEY', 34, 2018, 'October', 'Flash Flood', 'PHI', '02-OCT-18 20:00:00', 'EST-5', '02-OCT-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'BUDD LAKE', 2, 'SSW', 'NETCONG', 40.8951, -74.7152, 40.898, -74.709, 'Thunderstorms brought locally heavy rain to northern New Jersey on the evening of October 2.', 'Sections of US Route 46 in Netcong were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (766232, 201806, 18, 1520, 201806, 18, 1520, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:20:00', 'EST-5', '18-JUN-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SE', 'NORTHUMBERLAND', 1, 'SE', 'NORTHUMBERLAND', 43.12, -73.59, 43.12, -73.59, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Route 4 at Starks Knob Road in the town of Northumberland was closed in both directions due to downed trees.');
INSERT INTO public.stormevents_east VALUES (766233, 201806, 18, 1520, 201806, 18, 1520, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:20:00', 'EST-5', '18-JUN-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'CHAMBERLAIN MILLS', 1, 'W', 'CHAMBERLAIN MILLS', 43.25, -73.33, 43.25, -73.33, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Tree was downed onto wires along Chamberlin Mills Road.');
INSERT INTO public.stormevents_east VALUES (766234, 201806, 18, 1538, 201806, 18, 1538, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:38:00', 'EST-5', '18-JUN-18 15:38:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'WNW', 'SPRAGUETOWN', 2, 'WNW', 'SPRAGUETOWN', 43.14, -73.51, 43.14, -73.51, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Route 40 at Cottrell Road in the town of Greenwich was closed in both directions due to a downed tree.');
INSERT INTO public.stormevents_east VALUES (766235, 201806, 18, 1800, 201806, 18, 1800, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 18:00:00', 'EST-5', '18-JUN-18 18:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'MATTEAWAN', 0, 'N', 'MATTEAWAN', 41.5, -73.97, 41.5, -73.97, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (768780, 201806, 22, 1812, 201806, 22, 1812, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 18:12:00', 'EST-5', '22-JUN-18 18:12:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'YALE', 1, 'NW', 'YALE', 36.86, -77.29, 36.86, -77.29, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Several trees were downed near Yale.');
INSERT INTO public.stormevents_east VALUES (768781, 201806, 22, 1830, 201806, 22, 1830, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 18:30:00', 'EST-5', '22-JUN-18 18:30:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'SEBRELL', 1, 'N', 'SEBRELL', 36.8, -77.13, 36.8, -77.13, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Trees were downed north of Capron near the Sussex county line.');
