INSERT INTO public.stormevents_east VALUES (760997, 201805, 18, 1100, 201805, 19, 1600, 126956, 'MARYLAND', 24, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 11:00:00', 'EST-5', '19-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'OCEAN CITY', 2, 'S', 'BOXIRON', 38.33, -75.08, 38.0919, -75.3448, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of the Lower Maryland Eastern Shore.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (764734, 201806, 28, 1600, 201806, 28, 1641, 127565, 'CONNECTICUT', 9, 2018, 'June', 'Flash Flood', 'OKX', '28-JUN-18 16:00:00', 'EST-5', '28-JUN-18 16:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'DARIEN', 0, 'ESE', 'NORTON HGTS', 41.0777, -73.4704, 41.0698, -73.4993, 'Convection developed out ahead of an approaching cold front in a high precipitable water environment (around 2 inches based on the 12Z 6/28 OKX sounding), leading to isolated flash flooding across parts of coastal Fairfield County, CT. Rainfall amounts from CoCoRaHS gauges in the area ranged from 1-1.5 inches, the majority of which fell in a short period of time.', 'Numerous roads closed due to flooding in Darien including Heights Road, Post Road at Tokeneke Road, Post Road at Thorndal Circle, and Hoyt Street at Briar Brae Road.');
INSERT INTO public.stormevents_east VALUES (764736, 201806, 28, 1611, 201806, 28, 1641, 127565, 'CONNECTICUT', 9, 2018, 'June', 'Flash Flood', 'OKX', '28-JUN-18 16:11:00', 'EST-5', '28-JUN-18 16:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'EAST NORWALK', 1, 'NNW', 'EAST NORWALK', 41.1102, -73.4036, 41.1086, -73.403, 'Convection developed out ahead of an approaching cold front in a high precipitable water environment (around 2 inches based on the 12Z 6/28 OKX sounding), leading to isolated flash flooding across parts of coastal Fairfield County, CT. Rainfall amounts from CoCoRaHS gauges in the area ranged from 1-1.5 inches, the majority of which fell in a short period of time.', 'I-95 was impassable due to flash flooding at Exit 16 in Norwalk.');
INSERT INTO public.stormevents_east VALUES (787824, 201809, 16, 930, 201809, 16, 1900, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 09:30:00', 'EST-5', '16-SEP-18 19:00:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'ESKOTA', 1, 'W', 'CONCORD', 35.764, -82.323, 35.879, -82.329, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'County comms and stream gauges reported flash flooding developed along the South Toe River and Cane River basins after 5 to 10 inches of rain fell in the headwaters in less than 24 hours. Numerous roads were closed throughout the area, including a portion of Highway 197 which was covered with water from the Cane River. The bridge over Still Fork Creek on South Toe River Rd was closed, cutting off the community of Alpine Village. Also, a stream gauge on the Cane River near Pensacola exceeded its established flood stage by a couple of feet, and remained in flood for several hours, while a gauge on the South Toe River near Celo briefly exceeded its established flood stage.');
INSERT INTO public.stormevents_east VALUES (787854, 201809, 16, 2000, 201809, 16, 2230, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 20:00:00', 'EST-5', '16-SEP-18 22:30:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'COOLEEMEE', 1, 'ENE', 'COOLEEMEE', 35.823, -80.562, 35.822, -80.559, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'County comms reported a tributary of the Yadkin River overflowed its banks in the Cooleemee area, flooding a portion of Gladstone Rd, which had to be closed.');
INSERT INTO public.stormevents_east VALUES (787827, 201809, 16, 1640, 201809, 16, 2230, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 16:40:00', 'EST-5', '16-SEP-18 22:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ASHFORD', 1, 'SW', 'ASHFORD', 35.89, -81.934, 35.868, -81.94, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'A stream gauge on the North Fork Catawba River near Ashford exceeded its established flood stage after 4 to 6 inches fell in the headwaters, mainly over a 12 hour period. Water from the river and its tributaries flooded a couple of roads off Highway 221.');
INSERT INTO public.stormevents_east VALUES (759129, 201806, 15, 1504, 201806, 15, 1506, 126627, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'ILM', '15-JUN-18 15:04:00', 'EST-5', '15-JUN-18 15:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 2, 'NW', 'MURRELLS INLET SEA NAVIGATIONAL BUOY', 2, 'NW', 'MURRELLS INLET SEA NAVIGATIONAL BUOY', 33.53, -79.03, 33.53, -79.03, 'A cold front produced strong storms along the coast of northeast South Carolina.', 'A 43 mph gusts was recorded at a Weatherflow site.');
INSERT INTO public.stormevents_east VALUES (780294, 201810, 8, 1550, 201810, 8, 1800, 130332, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '08-OCT-18 15:50:00', 'EST-5', '08-OCT-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'CARMICHAEL', 3, 'NE', 'CARMICHAEL', 38.9496, -76.0877, 38.9569, -76.0928, 'Locally heavy rain resulted in isolated flash flooding in northeastern Maryland on the afternoon of October 8.', 'Roadways and parking lots were under water in the area of Chesapeake College.');
INSERT INTO public.stormevents_east VALUES (780295, 201810, 12, 110, 201810, 12, 210, 130333, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 01:10:00', 'EST-5', '12-OCT-18 02:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'WOODLAND', 1, 'NE', 'CORDOVA', 38.8377, -76.0357, 38.8909, -75.9903, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Sections of Maryland Routes 303 and 309 were closed in and around Cordova due to flooding.');
INSERT INTO public.stormevents_east VALUES (780296, 201810, 12, 120, 201810, 12, 220, 130333, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 01:20:00', 'EST-5', '12-OCT-18 02:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'EASTON', 1, 'WNW', 'EASTON', 38.7691, -76.088, 38.7734, -76.0887, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Maryland Route 322 in Easton was closed due to flooding in the vicinity of Port Street.');
INSERT INTO public.stormevents_east VALUES (780297, 201810, 12, 35, 201810, 12, 135, 130333, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 00:35:00', 'EST-5', '12-OCT-18 01:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'ROMANCOKE', 2, 'SSW', 'MATTAPEX', 38.8781, -76.3353, 38.8778, -76.3603, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Sections of Maryland Route 8 in Romancoke were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (780298, 201810, 12, 35, 201810, 12, 135, 130333, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 00:35:00', 'EST-5', '12-OCT-18 01:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'ROCK HALL', 1, 'N', 'ROCK HALL', 39.1425, -76.2237, 39.1409, -76.2299, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Maryland Route 20 was closed near Rock Hall in the vicinity of Crosby Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (780299, 201810, 12, 140, 201810, 12, 230, 130333, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 01:40:00', 'EST-5', '12-OCT-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'QUEEN ANNE', 0, 'ESE', 'QUEEN ANNE', 38.9192, -75.9631, 38.9178, -75.9642, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'A section of Maryland Route 404 to the south of Queen Anne along Norwich Creek was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (766236, 201806, 18, 1800, 201806, 18, 1800, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 18:00:00', 'EST-5', '18-JUN-18 18:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'BRINCKERHOFF', 1, 'SSW', 'BRINCKERHOFF', 41.53, -73.89, 41.53, -73.89, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (766237, 201806, 18, 1800, 201806, 18, 1800, 127773, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 18:00:00', 'EST-5', '18-JUN-18 18:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'WAPPINGERS FALLS', 0, 'N', 'WAPPINGERS FALLS', 41.6, -73.92, 41.6, -73.92, 'A hot and humid airmass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s.  This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This hot and humid air mass also provided an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 10,000 customers without power. A vacant historic building in Poughkeepsie, New York partially collapsed onto an occupied building, trapping and injuring one woman.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (766465, 201806, 18, 1520, 201806, 18, 1550, 127813, 'VERMONT', 50, 2018, 'June', 'Heavy Rain', 'ALY', '18-JUN-18 15:20:00', 'EST-5', '18-JUN-18 15:50:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'E', 'MANCHESTER CENTER', 1, 'E', 'MANCHESTER CENTER', 43.18, -73.04, 43.18, -73.04, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'A trained spotter reported 1.4 inches of rain.');
INSERT INTO public.stormevents_east VALUES (768693, 201806, 22, 1850, 201806, 22, 1850, 128169, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '22-JUN-18 18:50:00', 'EST-5', '22-JUN-18 18:50:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 40, 'EG', NULL, NULL, 0, 'N', 'BELTON', 0, 'N', 'BELTON', 34.52, -82.5, 34.52, -82.5, 'A cluster of thunderstorms moved into Upstate South Carolina from northeast Georgia during the evening. Cells within the cluster produced occasional, brief damaging wind gusts across the Piedmont.', 'Public reported a large tree was blown down on a vehicle in the Belton area.');
INSERT INTO public.stormevents_east VALUES (749860, 201804, 15, 1831, 201804, 15, 1831, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 18:31:00', 'EST-5', '15-APR-18 18:31:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'FARMVILLE', 1, 'NE', 'FARMVILLE', 37.31, -78.56, 37.31, -78.56, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed near Prospect.');
INSERT INTO public.stormevents_east VALUES (749861, 201804, 15, 1930, 201804, 15, 1930, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 19:30:00', 'EST-5', '15-APR-18 19:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 6, 'NE', 'CUMBERLAND', 6, 'NE', 'CUMBERLAND', 37.55, -78.18, 37.55, -78.18, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Large tree was downed on Miller Lane.');
INSERT INTO public.stormevents_east VALUES (749862, 201804, 15, 1941, 201804, 15, 1941, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 19:41:00', 'EST-5', '15-APR-18 19:41:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'CLARKSVILLE MARKS AR', 1, 'WNW', 'CLARKSVILLE MARKS AR', 36.61, -78.59, 36.61, -78.59, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed along Highway 49.');
INSERT INTO public.stormevents_east VALUES (768806, 201806, 22, 1945, 201806, 22, 1945, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 19:45:00', 'EST-5', '22-JUN-18 19:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'SE', 'BARTLETT', 1, 'SE', 'BARTLETT', 36.92, -76.52, 36.92, -76.52, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Trees were snapped in neighborhood near Owen Farm Road and Cedar Grove.');
INSERT INTO public.stormevents_east VALUES (768807, 201806, 22, 1945, 201806, 22, 1945, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 19:45:00', 'EST-5', '22-JUN-18 19:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'BARTLETT', 0, 'N', 'BARTLETT', 36.93, -76.53, 36.93, -76.53, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Numerous trees were downed in Carrollton.');
INSERT INTO public.stormevents_east VALUES (768809, 201806, 22, 2034, 201806, 22, 2034, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 20:34:00', 'EST-5', '22-JUN-18 20:34:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'SNEADS CORNER', 1, 'NW', 'SNEADS CORNER', 36.91, -78.18, 36.91, -78.18, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Trees were downed near Laurel Brand Road and Sneads Store Road.');
INSERT INTO public.stormevents_east VALUES (768810, 201806, 22, 1935, 201806, 22, 1935, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 19:35:00', 'EST-5', '22-JUN-18 19:35:00', 0, 0, 0, 0, '35.00K', '0.00K', 'NWS Employee', 63, 'EG', NULL, NULL, 1, 'N', 'WILLS CORNER', 1, 'N', 'WILLS CORNER', 36.8945, -76.58, 36.8945, -76.58, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'About one half mile wide swath of thunderstorms produced wind damage with wind speeds estimated between 70 and 75 mph. There was damage to a barn and outbuildings, and small to medium sized trailers were overturned. Also, large number of trees were snapped or broken.');
INSERT INTO public.stormevents_east VALUES (768845, 201806, 22, 1630, 201806, 22, 1630, 128180, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '22-JUN-18 16:30:00', 'EST-5', '22-JUN-18 16:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'BRIERY', 0, 'N', 'BRIERY', 37.1, -78.47, 37.1, -78.47, 'Scattered severe thunderstorms along a warm frontal boundary produced damaging winds, large hail, and lightning damage across portions of south central and southeast Virginia.', 'Numerous trees were downed on a farm that straddles the Charlotte/Prince Edward county line.');
INSERT INTO public.stormevents_east VALUES (768848, 201806, 22, 2020, 201806, 22, 2020, 128188, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 20:20:00', 'EST-5', '22-JUN-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 0, 'N', 'THIMBLE SHOALS', 0, 'N', 'THIMBLE SHOALS', 37.05, -76.26, 37.05, -76.26, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 40 knots was measured at Thimble Shoals.');
INSERT INTO public.stormevents_east VALUES (768853, 201806, 22, 2025, 201806, 22, 2025, 128188, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 20:25:00', 'EST-5', '22-JUN-18 20:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 56, 'MG', NULL, NULL, 0, 'N', 'CHESAPEAKE BAY BRIDGE TUNNEL 3RD ISLAND', 0, 'N', 'CHESAPEAKE BAY BRIDGE TUNNEL 3RD ISLAND', 37.04, -76.08, 37.04, -76.08, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 56 knots was measured at the Chesapeake Bay Bridge Tunnel 3rd Island.');
INSERT INTO public.stormevents_east VALUES (768854, 201806, 22, 2030, 201806, 22, 2030, 128188, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 20:30:00', 'EST-5', '22-JUN-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 45, 'MG', NULL, NULL, 2, 'NNE', 'CHESAPEAKE BAY BRIDGE TUNNEL STATION (CBBV2)', 2, 'NNE', 'CHESAPEAKE BAY BRIDGE TUNNEL STATION (CBBV2)', 37, -76.09, 37, -76.09, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 45 knots was measured at First Landing.');
INSERT INTO public.stormevents_east VALUES (766180, 201806, 22, 1920, 201806, 22, 1920, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 19:20:00', 'EST-5', '22-JUN-18 19:20:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'RABAT', 1, 'N', 'RABAT', 36.9861, -78.9316, 36.9861, -78.9316, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'One power line was blown down by thunderstorm winds along Clarkton Road.');
INSERT INTO public.stormevents_east VALUES (766182, 201806, 22, 1452, 201806, 22, 1452, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 14:52:00', 'EST-5', '22-JUN-18 14:52:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNE', 'FOREST', 3, 'NNE', 'FOREST', 37.408, -79.2638, 37.408, -79.2638, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'One tree was blown down by thunderstorm winds near the intersection of Shadwell Drive and Hawkins Mill Road.');
INSERT INTO public.stormevents_east VALUES (766183, 201806, 22, 1416, 201806, 22, 1422, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 14:16:00', 'EST-5', '22-JUN-18 14:22:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'WSW', 'SALEM (C)', 2, 'W', 'SALEM (C)', 37.2831, -80.1117, 37.3031, -80.0896, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'One tree was blown down by thunderstorm winds along Butt Hollow Road, while another was blown down along Shirley Road.');
INSERT INTO public.stormevents_east VALUES (766185, 201806, 22, 1519, 201806, 22, 1519, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 15:19:00', 'EST-5', '22-JUN-18 15:19:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'POSM', 2, 'ENE', 'POSM', 37.3896, -79.0454, 37.3896, -79.0454, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'One tree was blown down by thunderstorm winds near the intersection of Cabin Field Road and Stage Road.');
INSERT INTO public.stormevents_east VALUES (758145, 201806, 22, 1446, 201806, 22, 1446, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 14:46:00', 'EST-5', '22-JUN-18 14:46:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'TIMBERLAKE', 1, 'W', 'TIMBERLAKE', 37.331, -79.2718, 37.331, -79.2718, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'A tree was blown down onto a house by thunderstorm winds along Independence Circle.');
INSERT INTO public.stormevents_east VALUES (766186, 201806, 22, 1615, 201806, 22, 1619, 126485, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 16:15:00', 'EST-5', '22-JUN-18 16:19:00', 0, 0, 0, 0, '15.00K', '0.00K', '911 Call Center', 60, 'EG', NULL, NULL, 1, 'SW', 'KEYSVILLE', 3, 'NNE', 'KEYSVILLE', 37.0376, -78.4941, 37.0852, -78.4598, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop.', 'Reports were received from multiple sources of dozens of trees being blown down by thunderstorm winds in the community of Keysville, including several trees down along Watts Lane, and at least one tree having been blown down along Highway 15.');
INSERT INTO public.stormevents_east VALUES (768876, 201806, 1, 1315, 201806, 1, 1315, 128198, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '01-JUN-18 13:15:00', 'EST-5', '01-JUN-18 13:15:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'N', 'FAWN RIDGE', 1, 'N', 'FAWN RIDGE', 43.16, -76.33, 43.16, -76.33, 'A cold front moved into central New York the evening of the 1st triggering thunderstorms a few of which became severe with damaging winds.', 'Thunderstorm winds knocked down numerous trees and power lines.');
INSERT INTO public.stormevents_east VALUES (754315, 201807, 1, 1613, 201807, 1, 1615, 125774, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'ILN', '01-JUL-18 16:13:00', 'EST-5', '01-JUL-18 16:15:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SW', 'SCIOTOVILLE', 1, 'SW', 'SCIOTOVILLE', 38.76, -82.89, 38.76, -82.89, 'Scattered thunderstorms developed during the afternoon hours in a hot and humid air mass that was in place across the Ohio Valley.', 'Numerous large tree limbs were downed.');
INSERT INTO public.stormevents_east VALUES (767598, 201806, 10, 1620, 201806, 10, 2300, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 16:20:00', 'EST-5', '10-JUN-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'VANDERBILT', 0, 'WSW', 'LEISENRING', 40.0219, -79.6609, 39.9986, -79.6591, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported on multiple roads in Dunbar Township.');
INSERT INTO public.stormevents_east VALUES (767600, 201806, 10, 1952, 201806, 10, 2230, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 19:52:00', 'EST-5', '10-JUN-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'FIVE PTS', 0, 'N', 'FIVE PTS', 40.4, -79.52, 40.405, -79.5197, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported at the intersection of Route 819 and Trees Mills Road.');
INSERT INTO public.stormevents_east VALUES (767602, 201806, 10, 1729, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 17:29:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'THOMAS', 1, 'E', 'WYLANDVILLE', 40.2311, -80.0771, 40.2022, -80.0952, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Several roads were reported to be flooded in Nottingham Township.');
INSERT INTO public.stormevents_east VALUES (767603, 201806, 10, 1729, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 17:29:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'GASTONVILLE', 1, 'WSW', 'ELRAMA', 40.2715, -79.9875, 40.2469, -79.9396, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Several roads were reported to be flooded in Union Township.');
INSERT INTO public.stormevents_east VALUES (768755, 201806, 13, 1715, 201806, 13, 1715, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 17:15:00', 'EST-5', '13-JUN-18 17:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NE', 'WEST KITTANNING', 1, 'NE', 'WEST KITTANNING', 40.83, -79.52, 40.83, -79.52, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'Trees and wires were reported blown down just north of Kittanning.');
INSERT INTO public.stormevents_east VALUES (768756, 201806, 13, 1715, 201806, 13, 1715, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 17:15:00', 'EST-5', '13-JUN-18 17:15:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NW', 'TARRTOWN', 1, 'NW', 'TARRTOWN', 40.8578, -79.5287, 40.8578, -79.5287, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'A tree was reported to be blown down on Tarrtown Road, blocking the roadway.');
INSERT INTO public.stormevents_east VALUES (768757, 201806, 13, 1820, 201806, 13, 1820, 128075, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 18:20:00', 'EST-5', '13-JUN-18 18:20:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SSE', 'KITTANNING', 1, 'SSE', 'KITTANNING', 40.8091, -79.4935, 40.8091, -79.4935, 'Warm and humid conditions were in place across western Pennsylvania on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe.  Most severe reports were received from Armstrong County, with several reports of tree damage.  Flash flooding occurred here during the evening as well, as multiple storms dropped sufficient rainfall to cause roadway flooding and damage. The severe weather threat ended with a passage of a cold front during the evening.', 'A tree was reported to be blown onto power lines along Indian Hills Road.');
INSERT INTO public.stormevents_east VALUES (768741, 201806, 13, 1733, 201806, 13, 1733, 128179, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 17:33:00', 'EST-5', '13-JUN-18 17:33:00', 0, 0, 0, 0, '0.50K', '0.00K', 'COOP Observer', 50, 'EG', NULL, NULL, 1, 'NW', 'SMYRNA', 1, 'NW', 'SMYRNA', 40.1793, -81.2432, 40.1793, -81.2432, 'Warm and humid conditions were in place across eastern Ohio on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe. Harrison County was hit with a severe storms that caused some tree damage. The severe weather threat ended with a passage of a cold front during the evening.', 'A cooperative observer reported that a few trees were blown down along US Route 22 near Ohio Route 800.');
INSERT INTO public.stormevents_east VALUES (750490, 201804, 2, 658, 201804, 2, 658, 125141, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Waterspout', 'MFL', '02-APR-18 06:58:00', 'EST-5', '02-APR-18 06:58:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 10, 'NNE', 'BOCA RATON', 10, 'NNE', 'BOCA RATON', 26.46, -80.01, 26.46, -80.01, 'A weak boundary over the local Atlantic waters lead to the development of showers and storms during the morning hours. A showers off the coast of Palm Beach County produced a waterspout early in the day.', 'A waterspout was reported by a member of the public offshore Delray Beach associated with a shower.');
INSERT INTO public.stormevents_east VALUES (750492, 201804, 4, 735, 201804, 4, 735, 125143, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Waterspout', 'MFL', '04-APR-18 07:35:00', 'EST-5', '04-APR-18 07:35:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 6, 'SE', 'PORT OF PALM BEACH', 6, 'SE', 'PORT OF PALM BEACH', 26.7, -80, 26.7, -80, 'Morning showers and storms over the local Atlantic waters produced a waterspout off the coast of Palm Beach County.', 'A waterspout was reported offshore Palm Beach by a member of the public via social media. The water spout was associated with a shower that had moved offshore. Time estimated via radar.');
INSERT INTO public.stormevents_east VALUES (750493, 201804, 4, 1220, 201804, 4, 1220, 125144, 'FLORIDA', 12, 2018, 'April', 'Funnel Cloud', 'MFL', '04-APR-18 12:20:00', 'EST-5', '04-APR-18 12:20:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 1, 'S', 'MIAMI NEW TAMIAMI AR', 1, 'S', 'MIAMI NEW TAMIAMI AR', 25.64, -80.43, 25.64, -80.43, 'Showers and storms that developed along the seabreezes during the late morning hours across South Florida brought numerous boundary collisions into the early afternoon. One of these collisions lead to the development of a funnel cloud over southwestern Miami-Dade County.', 'A report of a funnel cloud was relayed to an off duty NWS meteorologist at 120 PM EDT. Photo shows it extending at least halfway to the ground.');
INSERT INTO public.stormevents_east VALUES (760783, 201805, 18, 642, 201805, 18, 730, 126923, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'AKQ', '18-MAY-18 06:42:00', 'EST-5', '18-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'LAUREL', 1, 'ESE', 'WEST END MANOR', 37.63, -77.51, 37.6446, -77.5161, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused flash flooding across portions of central and south central Virginia.', 'Numerous road closures were reported in and around the Laurel area.');
INSERT INTO public.stormevents_east VALUES (760784, 201805, 18, 1530, 201805, 18, 1800, 126923, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'AKQ', '18-MAY-18 15:30:00', 'EST-5', '18-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 44, 'WSW', 'WELLFORD', 44, 'WSW', 'WELLFORD', 37.58, -77.49, 37.5795, -77.4862, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused flash flooding across portions of central and south central Virginia.', 'Flash flooding was reported at the 4800 Block of West Broad Street.');
INSERT INTO public.stormevents_east VALUES (786157, 201809, 27, 1937, 201809, 27, 1937, 131385, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 19:37:00', 'EST-5', '27-SEP-18 19:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'WNW', 'STARTOWN', 2, 'WNW', 'STARTOWN', 35.661, -81.296, 35.661, -81.296, 'A cluster of thunderstorms producing pockets of damaging wind gusts moved into the North Carolina Piedmont from Upstate South Carolina during the evening. Several areas of wind damage were reported along the I-77 corridor.', 'FD reported two trees blown down on Robinson Rd.');
INSERT INTO public.stormevents_east VALUES (786147, 201809, 27, 1959, 201809, 27, 2009, 131385, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 19:59:00', 'EST-5', '27-SEP-18 20:09:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'DIXIE', 1, 'NNW', 'CHARLOTTE', 35.197, -80.972, 35.246, -80.862, 'A cluster of thunderstorms producing pockets of damaging wind gusts moved into the North Carolina Piedmont from Upstate South Carolina during the evening. Several areas of wind damage were reported along the I-77 corridor.', 'County comms reported multiple trees blown down across the west side of Charlotte.');
INSERT INTO public.stormevents_east VALUES (786148, 201809, 27, 2028, 201809, 27, 2028, 131385, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 20:28:00', 'EST-5', '27-SEP-18 20:28:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'HARRISBURG', 0, 'N', 'HARRISBURG', 35.32, -80.67, 35.32, -80.67, 'A cluster of thunderstorms producing pockets of damaging wind gusts moved into the North Carolina Piedmont from Upstate South Carolina during the evening. Several areas of wind damage were reported along the I-77 corridor.', 'County comms reported a couple of trees blown down in the  Harrisburg area.');
INSERT INTO public.stormevents_east VALUES (786149, 201809, 27, 2029, 201809, 27, 2029, 131385, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 20:29:00', 'EST-5', '27-SEP-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'STATESVILLE', 1, 'ENE', 'STATESVILLE', 35.785, -80.879, 35.785, -80.879, 'A cluster of thunderstorms producing pockets of damaging wind gusts moved into the North Carolina Piedmont from Upstate South Carolina during the evening. Several areas of wind damage were reported along the I-77 corridor.', 'FD reported trees blown down on Davis St.');
INSERT INTO public.stormevents_east VALUES (786155, 201809, 27, 2054, 201809, 27, 2054, 131385, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 20:54:00', 'EST-5', '27-SEP-18 20:54:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'ROCKWELL', 1, 'E', 'ROCKWELL', 35.55, -80.41, 35.55, -80.41, 'A cluster of thunderstorms producing pockets of damaging wind gusts moved into the North Carolina Piedmont from Upstate South Carolina during the evening. Several areas of wind damage were reported along the I-77 corridor.', 'County comms reported a couple of trees and power lines blown down in the Rockwell area.');
INSERT INTO public.stormevents_east VALUES (786156, 201809, 27, 2016, 201809, 27, 2016, 131385, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 20:16:00', 'EST-5', '27-SEP-18 20:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'SW', 'OLIVERS XRDS', 2, 'SW', 'OLIVERS XRDS', 35.562, -81.158, 35.562, -81.158, 'A cluster of thunderstorms producing pockets of damaging wind gusts moved into the North Carolina Piedmont from Upstate South Carolina during the evening. Several areas of wind damage were reported along the I-77 corridor.', 'Ham radio operator reported multiple trees blown down near Maiden.');
INSERT INTO public.stormevents_east VALUES (787798, 201809, 30, 345, 201809, 30, 1130, 131596, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '30-SEP-18 03:45:00', 'EST-5', '30-SEP-18 11:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'OLD FT', 5, 'W', 'DAVISTOWN', 35.618, -82.232, 35.568, -82.25, 'Heavy rain showers and isolated thunderstorms developed near the Blue Ridge escarpment within a moist southeast upslope flow throughout the 29th. Localized heavy rainfall developed during the evening and into the early morning hours of the 30th, culminating in localized flash flooding across the mountains during the early morning hours.', 'Although heavy rain ended across the area during the early morning hours, EM reported flooding continued along the upper Catawba and Crooked Creek basins into late morning and early afternoon. Several roads reportedly remained flooded along the Catawba in the Old Fort area, while a culvert was washed out and several private bridges washed out along Crooked Creek.');
INSERT INTO public.stormevents_east VALUES (787796, 201809, 30, 200, 201809, 30, 345, 131596, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '30-SEP-18 02:00:00', 'EST-5', '30-SEP-18 03:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'OLD FT', 1, 'SW', 'OLD FT', 35.618, -82.232, 35.62, -82.189, 'Heavy rain showers and isolated thunderstorms developed near the Blue Ridge escarpment within a moist southeast upslope flow throughout the 29th. Localized heavy rainfall developed during the evening and into the early morning hours of the 30th, culminating in localized flash flooding across the mountains during the early morning hours.', 'EM reported flash flooding along developed along the headwaters of the Catawba River and some of its tributaries after 4 to 8 inches of rain fell on the basin during the 29th and early on the 30th, with the bulk of that falling during the evening. A mobile home was damaged by flood water from a tributary on Catawba River Rd. A private bridge over the Catawba on Denny Bean Rd was also damaged.');
INSERT INTO public.stormevents_east VALUES (787904, 201809, 16, 1900, 201809, 16, 2100, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 19:00:00', 'EST-5', '16-SEP-18 21:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'PLEASANT GROVE BRKE', 4, 'NE', 'PLEASANT GROVE BRKE', 35.667, -81.571, 35.669, -81.557, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'Spotter reported a water rescue became necessary along River Rd in eastern Burke County after Henry Fork overflowed its banks and flooded a portion of the road.');
INSERT INTO public.stormevents_east VALUES (787911, 201809, 16, 2330, 201809, 17, 330, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '16-SEP-18 23:30:00', 'EST-5', '17-SEP-18 03:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'ROCKWELL', 1, 'WSW', 'LIBERTY', 35.56, -80.43, 35.576, -80.362, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'Although heavy rain ended across Rowan County during the evening of the 16th, high water conditions persisted through the overnight, with multiple roads remaining closed.');
INSERT INTO public.stormevents_east VALUES (787912, 201809, 16, 1730, 201809, 16, 2300, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '16-SEP-18 17:30:00', 'EST-5', '16-SEP-18 23:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'HAHN', 3, 'N', 'WILGROVE', 35.347, -80.699, 35.26, -80.681, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'Although heavy rain ended across Charlotte and vicinity during early evening, flooding continued along some streams and poorly drained areas through the evening.');
INSERT INTO public.stormevents_east VALUES (771791, 201806, 13, 945, 201806, 13, 945, 128673, 'LAKE HURON', 90, 2018, 'June', 'Marine Thunderstorm Wind', 'APX', '13-JUN-18 09:45:00', 'EST-5', '13-JUN-18 09:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 38, 'MG', NULL, NULL, 1, 'SE', 'STURGEON POINT', 1, 'SE', 'STURGEON POINT', 44.7038, -83.2676, 44.7038, -83.2676, 'A small cluster of thunderstorms moved off of Alcona County, producing gusty winds.', NULL);
INSERT INTO public.stormevents_east VALUES (763086, 201806, 25, 1857, 201806, 25, 1859, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:57:00', 'EST-5', '25-JUN-18 18:59:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 2, 'NNW', 'SPRING HILL', 2, 'NNW', 'SPRING HILL', 34.21, -81.3, 34.21, -81.3, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Trees and power lines downed along Wash Lever Rd.');
INSERT INTO public.stormevents_east VALUES (749201, 201806, 5, 1520, 201806, 5, 1520, 124889, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '05-JUN-18 15:20:00', 'EST-5', '05-JUN-18 15:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 36, 'MG', NULL, NULL, 4, 'WNW', 'CAPE CANAVERAL', 4, 'WNW', 'CAPE CANAVERAL', 28.4048, -80.6519, 28.4048, -80.6519, 'Persistent westerly flow was observed across central Florida. Deep moisture was in place across the area, with cool temperatures aloft and daytime heating conditions became favorable for the development of scattered showers and thunderstorms in the afternoon. Dry mid-level air was observed in the upper air sounding, allowing storms to produce strong to severe wind gusts. Scattered showers and storms were ongoing across east central Florida during the afternoon. As the storms approached Brevard County they intensified, and produced several strong wind reports along the intracoastal waters.', 'US Air Force wind tower 0300 measured a peak wind gust of 36 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (780300, 201810, 12, 130, 201810, 12, 230, 130333, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 01:30:00', 'EST-5', '12-OCT-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CHURCH HILL', 2, 'N', 'CHURCH HILL', 39.1386, -75.9948, 39.1549, -75.9837, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Sections of Main Street and Walnut Street in Church Hill were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (749316, 201806, 7, 1530, 201806, 7, 1530, 124928, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '07-JUN-18 15:30:00', 'EST-5', '07-JUN-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 55, 'MG', NULL, NULL, 2, 'SSE', 'PLAYALINDA BEACH', 2, 'SSE', 'PLAYALINDA BEACH', 28.53, -80.77, 28.53, -80.77, 'A well-defined, positively tilted trough aloft became a closed mid-level low pressure over north central Florida. This resulted in modest force for ascent across north central Florida, and also maintained a weak surface trough across north-central Florida, which helped to decrease the strong west/southwest flow, allowing the east coast sea breeze to develop in the afternoon. Moisture was plentiful across the area with Precipitable Water values around 1.50 - 1.70 inches. With diurnal heating, numerous showers and thunderstorms were able to develop along and a head of the east coast sea breeze. Once the initial round of storms got going, numerous outflow boundaries helped to create additional storms across the area. A severe thunderstorm developed in Brevard County where it produced a 55 knot gust along the intracoastal waters. Several other thunderstorms developed throughout the afternoon and evening, and some of those storms produced strong winds along the Brevard and Indian River coasts.', 'US Air Force wind tower 1007 measured a peak wind gust of 55 knots.');
INSERT INTO public.stormevents_east VALUES (749659, 201806, 9, 1638, 201806, 9, 1648, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:38:00', 'EST-5', '09-JUN-18 16:48:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'BOWLUSVILLE', 2, 'SE', 'BOWLUSVILLE', 40.0044, -83.7719, 40.0044, -83.7719, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A large tree limb was knocked down along Victorian Way.');
INSERT INTO public.stormevents_east VALUES (781307, 201808, 7, 1900, 201808, 7, 2100, 130514, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '07-AUG-18 19:00:00', 'EST-5', '07-AUG-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'ESE', 'HUGOS CORNERS', 1, 'ESE', 'MILLVIEW', 41.55, -76.55, 41.4944, -76.5578, 'Slow moving thunderstorms produced flash flooding in Sullivan County.', 'Four roads were washed out and a bridge was structurally damaged in Forks Township.  Flash flooding also reported in Dushore where water rescues took place.');
INSERT INTO public.stormevents_east VALUES (780301, 201810, 12, 330, 201810, 12, 530, 130334, 'NEW JERSEY', 34, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 03:30:00', 'EST-5', '12-OCT-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'COLLINGWOOD PARK', 1, 'N', 'MONMOUTH CO ARPT', 40.2165, -74.1317, 40.1979, -74.1233, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'NJ Route 34 was closed in Wall Township to the north of Belmar Boulevard due to flooding.');
INSERT INTO public.stormevents_east VALUES (778370, 201810, 2, 2115, 201810, 2, 2115, 129936, 'PENNSYLVANIA', 42, 2018, 'October', 'Hail', 'PHI', '02-OCT-18 21:15:00', 'EST-5', '02-OCT-18 21:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 0.8, NULL, NULL, NULL, 0, 'N', 'HATFIELD', 0, 'N', 'HATFIELD', 40.28, -75.3, 40.28, -75.3, 'Supercellular severe thunderstorms caused 2 tornadoes, wind damage, and hail across the region all part of a record breaking tornado outbreak across Pennsylvania.', 'Hail 2 cm in diameter reported in Hatfield. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (778374, 201810, 2, 1737, 201810, 2, 1738, 129936, 'PENNSYLVANIA', 42, 2018, 'October', 'Tornado', 'PHI', '02-OCT-18 17:37:00', 'EST-5', '02-OCT-18 17:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SE', 'LAKE HARMONY', 2, 'NE', 'ALBRIGHTSVILLE', 41.0484, -75.6049, 41.042, -75.5876, 'Supercellular severe thunderstorms caused 2 tornadoes, wind damage, and hail across the region all part of a record breaking tornado outbreak across Pennsylvania.', 'Tornado caused tree damage along an unbroken path from the Big Boulder Ski Area along a communications tower access road near Big Boulder Lake. Numerous trees were uprooted and snapped. Estimated maximum wind speed was 100 to 110 mph. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (778377, 201810, 2, 1801, 201810, 2, 1802, 129936, 'PENNSYLVANIA', 42, 2018, 'October', 'Tornado', 'PHI', '02-OCT-18 18:01:00', 'EST-5', '02-OCT-18 18:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NNW', 'MC MICHAELS', 1, 'NE', 'MC MICHAELS', 41.0158, -75.4114, 41.0108, -75.3855, 'Supercellular severe thunderstorms caused 2 tornadoes, wind damage, and hail across the region all part of a record breaking tornado outbreak across Pennsylvania.', 'The path of this tornado started with tree damage along Jackson Road. Many trees were uprooted and some were snapped. Additional tree damage was observed along Sportsmans Trail and Skyhawk Trail. The damage path continued through a corn field near the intersection of Mountain Road and Jackson Road. A large limb of approximately 18 inches in diameter was snapped off a tree and caused roof damage and downed power lines to a residence. Estimated maximum wind speed was 90 to 100 mph. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (778378, 201810, 2, 1730, 201810, 2, 1730, 129936, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'PHI', '02-OCT-18 17:30:00', 'EST-5', '02-OCT-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'LAKE HARMONY', 2, 'WSW', 'LAKE HARMONY', 41.06, -75.67, 41.06, -75.67, 'Supercellular severe thunderstorms caused 2 tornadoes, wind damage, and hail across the region all part of a record breaking tornado outbreak across Pennsylvania.', 'A couple of trees reported down in Kidder Township. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (778390, 201810, 2, 2022, 201810, 2, 2022, 129936, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'PHI', '02-OCT-18 20:22:00', 'EST-5', '02-OCT-18 20:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SSE', 'DELEWARE WATER GAP', 1, 'SSE', 'DELEWARE WATER GAP', 40.9678, -75.1216, 40.9678, -75.1216, 'Supercellular severe thunderstorms caused 2 tornadoes, wind damage, and hail across the region all part of a record breaking tornado outbreak across Pennsylvania.', 'Tree down at Point of Gap Overlook on Route 611.');
INSERT INTO public.stormevents_east VALUES (780302, 201810, 12, 130, 201810, 12, 230, 130334, 'NEW JERSEY', 34, 2018, 'October', 'Flash Flood', 'PHI', '12-OCT-18 01:30:00', 'EST-5', '12-OCT-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'WOODSTOWN', 1, 'W', 'WOODSTOWN', 39.6432, -75.3332, 39.6517, -75.3479, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Minor flooding occurred along the Salem River at Woodstown.');
INSERT INTO public.stormevents_east VALUES (780303, 201810, 11, 2340, 201810, 12, 245, 130334, 'NEW JERSEY', 34, 2018, 'October', 'Flash Flood', 'PHI', '11-OCT-18 23:40:00', 'EST-5', '12-OCT-18 02:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'GLASSBORO', 1, 'SSW', 'HURFFVILLE', 39.7262, -75.1104, 39.7406, -75.1244, 'Rainfall totals of 3 to 5 inches fell in parts of northeastern Maryland, Delaware, and southern and central New Jersey on the night of October 11.  There were a few reports of rainfall amounts in excess of 5 inches.', 'Minor flooding occurred along the Mantua Creek at Pitman.');
INSERT INTO public.stormevents_east VALUES (766467, 201806, 18, 1515, 201806, 18, 1515, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:15:00', 'EST-5', '18-JUN-18 15:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'E', 'MANCHESTER CENTER', 1, 'E', 'MANCHESTER CENTER', 43.18, -73.04, 43.18, -73.04, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'A tree, one foot in diameter, was downed by thunderstorm winds at 1244 Beech Street.');
INSERT INTO public.stormevents_east VALUES (766468, 201806, 18, 1518, 201806, 18, 1518, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:18:00', 'EST-5', '18-JUN-18 15:18:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'SHAFTSBURY', 1, 'E', 'SHAFTSBURY', 43, -73.19, 43, -73.19, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (766469, 201806, 18, 1530, 201806, 18, 1530, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:30:00', 'EST-5', '18-JUN-18 15:30:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'WSW', 'SUNDERLAND', 2, 'WSW', 'SUNDERLAND', 43.11, -73.13, 43.11, -73.13, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Vermont Route 7A was closed between Dunham Road and Hill Farm Road due to trees and powerlines down.');
INSERT INTO public.stormevents_east VALUES (766471, 201806, 18, 1541, 201806, 18, 1541, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:41:00', 'EST-5', '18-JUN-18 15:41:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'E', 'WILMINGTON', 1, 'E', 'WILMINGTON', 42.87, -72.86, 42.87, -72.86, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Many reports of downed trees in the Wilmington area, including on Stowe Hill Road.');
INSERT INTO public.stormevents_east VALUES (768694, 201806, 22, 1932, 201806, 22, 1932, 128169, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '22-JUN-18 19:32:00', 'EST-5', '22-JUN-18 19:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'GOODWINS XRDS', 2, 'SW', 'TYLERSVILLE', 34.533, -81.939, 34.567, -81.942, 'A cluster of thunderstorms moved into Upstate South Carolina from northeast Georgia during the evening. Cells within the cluster produced occasional, brief damaging wind gusts across the Piedmont.', 'Public reported a tree blown down on I-385 at mile marker 4 and another tree down at Highways 308 and 49.');
INSERT INTO public.stormevents_east VALUES (768695, 201806, 22, 1935, 201806, 22, 1939, 128169, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '22-JUN-18 19:35:00', 'EST-5', '22-JUN-18 19:39:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'FAIR FOREST', 1, 'NNW', 'ARKWRIGHT', 34.981, -82.043, 34.933, -81.925, 'A cluster of thunderstorms moved into Upstate South Carolina from northeast Georgia during the evening. Cells within the cluster produced occasional, brief damaging wind gusts across the Piedmont.', 'Public reported a few trees blown down on Halibut Ln in Lyman. County comms reported numerous trees blown down in Spartanburg, especially on the south side of the city.');
INSERT INTO public.stormevents_east VALUES (768696, 201806, 22, 1953, 201806, 22, 1959, 128169, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '22-JUN-18 19:53:00', 'EST-5', '22-JUN-18 19:59:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'NINETY SIX', 1, 'ENE', 'CAMBRIDGE', 34.171, -82.024, 34.084, -81.948, 'A cluster of thunderstorms moved into Upstate South Carolina from northeast Georgia during the evening. Cells within the cluster produced occasional, brief damaging wind gusts across the Piedmont.', 'County comms reported multiple power lines blown down in Ninety Six, including on Cambridge St. Two trees were also blown down on Pheasant Road near the Saluda County line.');
INSERT INTO public.stormevents_east VALUES (768697, 201806, 22, 2003, 201806, 22, 2014, 128169, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '22-JUN-18 20:03:00', 'EST-5', '22-JUN-18 20:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'UNION', 1, 'WNW', 'LOCKHART', 34.715, -81.607, 34.784, -81.465, 'A cluster of thunderstorms moved into Upstate South Carolina from northeast Georgia during the evening. Cells within the cluster produced occasional, brief damaging wind gusts across the Piedmont.', 'County comms reported multiple trees blown down across the eastern part of Union County.');
INSERT INTO public.stormevents_east VALUES (749863, 201804, 15, 1942, 201804, 15, 1942, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 19:42:00', 'EST-5', '15-APR-18 19:42:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 5, 'SSW', 'RODEPHIL', 5, 'SSW', 'RODEPHIL', 37.31, -78.22, 37.31, -78.22, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed along Slayer Creek Road.');
INSERT INTO public.stormevents_east VALUES (749866, 201804, 15, 2056, 201804, 15, 2056, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 20:56:00', 'EST-5', '15-APR-18 20:56:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ESE', 'KENBRIDGE', 2, 'ESE', 'KENBRIDGE', 36.96, -78.12, 36.96, -78.12, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed along East Third Street in Kenbridge.');
INSERT INTO public.stormevents_east VALUES (749868, 201804, 15, 2113, 201804, 15, 2113, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 21:13:00', 'EST-5', '15-APR-18 21:13:00', 0, 0, 0, 0, '3.00K', '0.00K', 'NWS Storm Survey', 50, 'EG', NULL, NULL, 3, 'NE', 'NOTTOWAY', 3, 'NE', 'NOTTOWAY', 37.16, -78.03, 37.16, -78.03, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed on Piney Green Road. This was consistent with straight line winds.');
INSERT INTO public.stormevents_east VALUES (768855, 201806, 22, 2350, 201806, 22, 2350, 128188, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 23:50:00', 'EST-5', '22-JUN-18 23:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 52, 'MG', NULL, NULL, 2, 'NNE', 'CHESAPEAKE BAY BRIDGE TUNNEL STATION (CBBV2)', 2, 'NNE', 'CHESAPEAKE BAY BRIDGE TUNNEL STATION (CBBV2)', 37, -76.09, 37, -76.09, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 52 knots was measured at First Landing.');
INSERT INTO public.stormevents_east VALUES (753756, 201804, 16, 424, 201804, 16, 424, 125632, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 04:24:00', 'EST-5', '16-APR-18 04:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 43, 'MG', NULL, NULL, 0, 'N', 'WACHAPREAGUE STATION (WAHV2)', 0, 'N', 'WACHAPREAGUE STATION (WAHV2)', 37.61, -75.62, 37.61, -75.62, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 43 knots was measured at Wachapreague.');
INSERT INTO public.stormevents_east VALUES (753758, 201804, 16, 425, 201804, 16, 425, 125632, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 04:25:00', 'EST-5', '16-APR-18 04:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'MG', NULL, NULL, 4, 'W', 'WACHAPREAGUE STATION (WAHV2)', 4, 'W', 'WACHAPREAGUE STATION (WAHV2)', 37.6, -75.69, 37.6, -75.69, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 44 knots was measured at Mesonet Station XWAC, Wachapreague.');
INSERT INTO public.stormevents_east VALUES (757478, 201805, 10, 1343, 201805, 10, 1343, 126346, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'AKQ', '10-MAY-18 13:43:00', 'EST-5', '10-MAY-18 13:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 2, 'W', 'WILDWOOD', 2, 'W', 'WILDWOOD', 37.98, -78.25, 37.98, -78.25, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Quarter size hail was reported.');
