INSERT INTO public.stormevents_east VALUES (768877, 201806, 1, 1518, 201806, 1, 1518, 128198, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '01-JUN-18 15:18:00', 'EST-5', '01-JUN-18 15:18:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'THURSTON', 1, 'NW', 'THURSTON', 42.23, -77.29, 42.23, -77.29, 'A cold front moved into central New York the evening of the 1st triggering thunderstorms a few of which became severe with damaging winds.', 'Thunderstorm winds knocked down trees and power lines which blocked the roadway at Route 12 near Griffin Road.');
INSERT INTO public.stormevents_east VALUES (766189, 201806, 22, 1751, 201806, 22, 1751, 127774, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 17:51:00', 'EST-5', '22-JUN-18 17:51:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'LEWISBURG', 1, 'ESE', 'LEWISBURG', 37.7976, -80.4386, 37.7976, -80.4386, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft by a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop along and south of Interstate 64.', 'One tree was blown down by thunderstorm winds near the intersection of East Washington Street and Holt Lane.');
INSERT INTO public.stormevents_east VALUES (766191, 201806, 22, 1746, 201806, 22, 1746, 127774, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 17:46:00', 'EST-5', '22-JUN-18 17:46:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'RONCEVERTE', 1, 'SE', 'RONCEVERTE', 37.7519, -80.4704, 37.7409, -80.4577, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft by a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop along and south of Interstate 64.', 'One tree was blown down by thunderstorm winds along Morgan Drive, while another was blown down along Shirley Road.');
INSERT INTO public.stormevents_east VALUES (766188, 201806, 22, 1659, 201806, 22, 1659, 127774, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RNK', '22-JUN-18 16:59:00', 'EST-5', '22-JUN-18 16:59:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'PIPESTEM', 1, 'N', 'PIPESTEM', 37.5479, -80.9731, 37.5479, -80.9731, 'Strong surface heating and low level convergence south of an approaching cold front was supported aloft by a passing upper level disturbance.  This resulted in a favorable environment for multiple severe thunderstorms to develop along and south of Interstate 64.', 'Multiple trees were blown down by thunderstorm winds along Fairway Drive.');
INSERT INTO public.stormevents_east VALUES (768878, 201806, 13, 1820, 201806, 13, 1820, 128199, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '13-JUN-18 18:20:00', 'EST-5', '13-JUN-18 18:20:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'N', 'LANSINGVILLE', 0, 'N', 'LANSINGVILLE', 42.6, -76.55, 42.6, -76.55, 'A strong area of low pressure moved  from northern Ontario to the Saint Lawrence Valley from the day of the 13th into the evening. This low pressure system pushed a cold front into central New York which triggered severe thunderstorms which produced damaging winds.', 'Thunderstorm winds knocked down trees and wires. A few electric poles were sheared off into a field.');
INSERT INTO public.stormevents_east VALUES (768879, 201806, 13, 1830, 201806, 13, 1830, 128199, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '13-JUN-18 18:30:00', 'EST-5', '13-JUN-18 18:30:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'HECTOR', 0, 'N', 'HECTOR', 42.5, -76.87, 42.5, -76.87, 'A strong area of low pressure moved  from northern Ontario to the Saint Lawrence Valley from the day of the 13th into the evening. This low pressure system pushed a cold front into central New York which triggered severe thunderstorms which produced damaging winds.', 'Thunderstorm winds knocked down trees and power lines.');
INSERT INTO public.stormevents_east VALUES (768880, 201806, 13, 1853, 201806, 13, 1853, 128199, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '13-JUN-18 18:53:00', 'EST-5', '13-JUN-18 18:53:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'NNE', 'PERUVILLE', 2, 'NNE', 'PERUVILLE', 42.58, -76.35, 42.58, -76.35, 'A strong area of low pressure moved  from northern Ontario to the Saint Lawrence Valley from the day of the 13th into the evening. This low pressure system pushed a cold front into central New York which triggered severe thunderstorms which produced damaging winds.', 'Thunderstorm winds knocked down large tree branches and power poles.');
INSERT INTO public.stormevents_east VALUES (760154, 201806, 1, 1834, 201806, 1, 1839, 126275, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '01-JUN-18 18:34:00', 'EST-5', '01-JUN-18 18:39:00', 0, 0, 0, 0, NULL, NULL, 'Public', 70, 'EG', NULL, NULL, 0, 'N', 'GASTON LEX CO ARPT', 0, 'N', 'GASTON LEX CO ARPT', 33.78, -81.1, 33.78, -81.1, 'An upper level shortwave, combined with instability enhanced by daytime heating, produced a band of scattered severe thunderstorms which moved east across the region during the late afternoon and evening.', 'Video, relayed via social media, taken from US Hwy 321 near Athens School Rd showed a flipped irrigation system, broken power pole, and a tractor trailer flipped on to its side. Time estimated.');
INSERT INTO public.stormevents_east VALUES (760207, 201806, 11, 2036, 201806, 11, 2100, 126818, 'SOUTH CAROLINA', 45, 2018, 'June', 'Flash Flood', 'CAE', '11-JUN-18 20:36:00', 'EST-5', '11-JUN-18 21:00:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'GREEN HILL', 1, 'NNW', 'CAYCE', 33.9862, -81.0582, 33.9836, -81.0582, 'Strong daytime heating, and surface boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Law enforcement closed Knox Abbott Dr near State St due to rapidly moving water over the roadway. Video of the officers blocking the roadway was sent by a trained spotter via social media.');
INSERT INTO public.stormevents_east VALUES (760236, 201806, 11, 1600, 201806, 11, 1605, 126819, 'GEORGIA', 13, 2018, 'June', 'Hail', 'CAE', '11-JUN-18 16:00:00', 'EST-5', '11-JUN-18 16:05:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.75, NULL, NULL, NULL, 4, 'ENE', 'WRIGHTSBORO', 4, 'ENE', 'WRIGHTSBORO', 33.5229, -82.4346, 33.5229, -82.4346, 'Strong daytime heating, and surface boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Report of golf ball size hail, and strong winds, near the intersection of Cobbham Rd and Stagecoach Rd NE.');
INSERT INTO public.stormevents_east VALUES (760530, 201806, 15, 1648, 201806, 15, 1710, 126863, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '15-JUN-18 16:48:00', 'EST-5', '15-JUN-18 17:10:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 52, 'EG', NULL, NULL, 0, 'NW', 'BLACKVILLE', 0, 'NW', 'BLACKVILLE', 33.3536, -81.2758, 33.3536, -81.2758, 'Instability caused by daytime heating, combined with surface convergence along a surface trough and outflow boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Barnwell County Dispatch reported trees down on Dexter Street.');
INSERT INTO public.stormevents_east VALUES (767604, 201806, 10, 1829, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:29:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'GINGER HILL', 1, 'NNW', 'GINGER HILL', 40.21, -80.01, 40.2104, -80.0038, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'A water rescue took place at the intersection of Mingo Creek Road and Little Mingo Road.');
INSERT INTO public.stormevents_east VALUES (767606, 201806, 10, 1839, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:39:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'FINLEYVILLE', 0, 'SE', 'FINLEYVILLE', 40.2499, -80.0171, 40.2485, -80.0175, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'A vehicle was reported to be stuck in flood waters at Airport Road and Rankintown Road.');
INSERT INTO public.stormevents_east VALUES (767605, 201806, 10, 1830, 201806, 10, 2045, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:30:00', 'EST-5', '10-JUN-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'LINCOLN HILL', 1, 'SSE', 'LINCOLN HILL', 40.1651, -80.2756, 40.1627, -80.275, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'A motorist was reported to be trapped by flood waters at the intersection of West Chestnut Street and Franklin Farms Road.');
INSERT INTO public.stormevents_east VALUES (767607, 201806, 10, 1848, 201806, 10, 2045, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:48:00', 'EST-5', '10-JUN-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'WASHINGTON', 1, 'S', 'WASHINGTON', 40.1659, -80.2457, 40.1631, -80.2465, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'State Route 18 was closed at South Main Street by flooding.');
INSERT INTO public.stormevents_east VALUES (770818, 201806, 13, 1736, 201806, 13, 1736, 128179, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '13-JUN-18 17:36:00', 'EST-5', '13-JUN-18 17:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', 50, 'EG', NULL, NULL, 1, 'NW', 'PIEDMONT', 1, 'NW', 'PIEDMONT', 40.1894, -81.2107, 40.1894, -81.2107, 'Warm and humid conditions were in place across eastern Ohio on June 13th behind a warm front.  After morning showers departed, instability was able to build during the afternoon hours.  A strong shortwave was able to generate high levels of deep layer shear, which allowed for the development of thunderstorms during the afternoon and early evening, a few of which became severe. Harrison County was hit with a severe storms that caused some tree damage. The severe weather threat ended with a passage of a cold front during the evening.', 'A cooperative observer reported that large limbs were snapped near Piedmont.');
INSERT INTO public.stormevents_east VALUES (759872, 201805, 14, 1924, 201805, 14, 1924, 126703, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'AKQ', '14-MAY-18 19:24:00', 'EST-5', '14-MAY-18 19:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'W', 'PRINCE GEORGE', 1, 'W', 'PRINCE GEORGE', 37.22, -77.29, 37.22, -77.29, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Quarter size hail was reported.');
INSERT INTO public.stormevents_east VALUES (759873, 201805, 14, 1927, 201805, 14, 1927, 126703, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'AKQ', '14-MAY-18 19:27:00', 'EST-5', '14-MAY-18 19:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 2, 'NNW', 'PRINCE GEORGE', 2, 'NNW', 'PRINCE GEORGE', 37.25, -77.29, 37.25, -77.29, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Quarter size hail was reported.');
INSERT INTO public.stormevents_east VALUES (759874, 201805, 14, 1750, 201805, 14, 1750, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 17:50:00', 'EST-5', '14-MAY-18 17:50:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SE', 'MINERAL', 1, 'SE', 'MINERAL', 38.01, -77.91, 38.01, -77.91, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Several large oak trees were downed.');
INSERT INTO public.stormevents_east VALUES (759875, 201805, 14, 1819, 201805, 14, 1819, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 18:19:00', 'EST-5', '14-MAY-18 18:19:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ENE', 'SANDY HOOK', 1, 'ENE', 'SANDY HOOK', 37.76, -77.9, 37.76, -77.9, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Numerous trees were downed.');
INSERT INTO public.stormevents_east VALUES (759901, 201805, 14, 1947, 201805, 14, 1947, 126703, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '14-MAY-18 19:47:00', 'EST-5', '14-MAY-18 19:47:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'PRINCE GEORGE', 2, 'SSE', 'PRINCE GEORGE', 37.19, -77.26, 37.19, -77.26, 'Scattered severe thunderstorms associated with a trough of low pressure produced damaging winds and large hail across portions of central and eastern Virginia.', 'Tree was downed on a roadway.');
INSERT INTO public.stormevents_east VALUES (755799, 201806, 2, 1550, 201806, 2, 1555, 126044, 'GEORGIA', 13, 2018, 'June', 'Hail', 'CHS', '02-JUN-18 15:50:00', 'EST-5', '02-JUN-18 15:55:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.88, NULL, NULL, NULL, 3, 'NNE', 'WILMINGTON IS', 3, 'NNE', 'WILMINGTON IS', 32.01, -80.98, 32.01, -80.98, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'A report via social media indicated dime to nickel size hail falling for 3-5 minutes.');
INSERT INTO public.stormevents_east VALUES (750523, 201804, 10, 1415, 201804, 10, 1415, 125147, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'MFL', '10-APR-18 14:15:00', 'EST-5', '10-APR-18 14:15:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 50, 'MG', NULL, NULL, 3, 'N', 'LOXAHATCHEE', 3, 'N', 'LOXAHATCHEE', 26.7285, -80.3483, 26.7285, -80.3483, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms across Palm Beach and Broward Counties during the early to mid afternoon hours. Strong winds, two brief tornadoes, and small hail were reported with this activity.', 'A thunderstorm wind gust of 58 mph / 50 knots was recorded by mesonet weather station KFLOXAH26 in Loxahatchee Groves. The owner of the personal weather station also noted some small tree branches broken.');
INSERT INTO public.stormevents_east VALUES (750534, 201804, 10, 1525, 201804, 10, 1536, 125147, 'FLORIDA', 12, 2018, 'April', 'Tornado', 'MFL', '10-APR-18 15:25:00', 'EST-5', '10-APR-18 15:36:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NW', '(FLL)FT LAUDRDL INTL', 2, 'E', '(FLL)FT LAUDRDL INTL', 26.08, -80.16, 26.065, -80.111, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms across Palm Beach and Broward Counties during the early to mid afternoon hours. Strong winds, two brief tornadoes, and small hail were reported with this activity.', 'Survey summary: Multiple eyewitness videos show a tornado touched down along the northwestern side of Fort Lauderdale-Hollywood International Airport near I-595, leading to damage to cargo and storage containers in the FedEx facility on the north side of the  airfield. The tornado then moved east-southeast along the airport''s northern taxiway, causing damage to a jet bridge on the north side of the terminal. The damage path becomes diffuse as it likely crossed Perimeter Road and US 1 along the immediate east side of the airport. The tornado then moved into the extreme |southern end of Port Everglades, where multiple cargo containers were flipped and damaged, along with eyewitness reports of port-a-johns being tossed about. The tornado then likely crossed the intracoastal waterway, and moved across the barrier island within Dr. Von D. Mizell-Eula Johnson State Port before moving offshore into the Atlantic Ocean.');
INSERT INTO public.stormevents_east VALUES (750496, 201804, 10, 1429, 201804, 10, 1429, 125146, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '10-APR-18 14:29:00', 'EST-5', '10-APR-18 14:29:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 3, 'SSE', 'JUPITER INLET', 3, 'SSE', 'JUPITER INLET', 26.8933, -80.0563, 26.8933, -80.0563, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms, initially producing strong wind gusts over Lake Okeechobee, then moving offshore into the local Atlantic waters were a brief waterspout was also reported.', 'A marine thunderstorm wind gust of 43 mph / 37 knots was recorded by Wxflow mesonet site XJUP at Juno Beach Pier.');
INSERT INTO public.stormevents_east VALUES (764720, 201806, 28, 1749, 201806, 28, 1819, 127563, 'NEW YORK', 36, 2018, 'June', 'Flash Flood', 'OKX', '28-JUN-18 17:49:00', 'EST-5', '28-JUN-18 18:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'LONG IS CITY', 0, 'NNW', 'LONG IS CITY', 40.7365, -73.9313, 40.7365, -73.9321, 'Convection developed out ahead of an approaching cold front in a high precipitable water environment (around 2 inches based on the 12Z 6/28 OKX sounding), leading to isolated flash flooding across parts of Queens and Brooklyn. Close to one inch of rain fell in a short period of time over these areas.', 'Greenpoint Avenue was closed due to flooding at Borden Avenue in Sunnyside.');
INSERT INTO public.stormevents_east VALUES (781329, 201808, 3, 845, 201808, 3, 1100, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 08:45:00', 'EST-5', '03-AUG-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'NEWBURG', 2, 'W', 'CANAN', 40.5245, -78.443, 40.4737, -78.4688, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'Flash flooding with water flowing into houses and across roads between 13th and 15th Streets in Altoona.');
INSERT INTO public.stormevents_east VALUES (786212, 201809, 23, 2145, 201809, 23, 2330, 131394, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '23-SEP-18 21:45:00', 'EST-5', '23-SEP-18 23:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'JOY', 2, 'S', 'JOY', 35.873, -81.79, 35.849, -81.785, 'Heavy rain showers developed throughout the evening and overnight hours near the eastern Blue Ridge escarpment in response to a moist southeast flow. A small area of excessive rainfall produced some flash flooding across northern Burke County.', 'Public reported flash flooding of creeks in northwest Burke County after 2 to 4 inches of rain fell in just a few hours. Steels Creek overflowed its banks and sent water over the entrance road to a campground off Highway 181. Simpson Creek and Rose Creek washed out a bridge in another campground off Rose Creek Rd.');
INSERT INTO public.stormevents_east VALUES (787160, 201809, 30, 120, 201809, 30, 330, 131596, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '30-SEP-18 01:20:00', 'EST-5', '30-SEP-18 03:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'CHIMNEY ROCK', 2, 'NW', 'CHIMNEY ROCK', 35.446, -82.277, 35.449, -82.276, 'Heavy rain showers and isolated thunderstorms developed near the Blue Ridge escarpment within a moist southeast upslope flow throughout the 29th. Localized heavy rainfall developed during the evening and into the early morning hours of the 30th, culminating in localized flash flooding across the mountains during the early morning hours.', 'A stream gauge on the Rocky Broad River at Bat Cave exceeded its established flood stage after 4 to 8 inches of rain fell on the 29th into the early part of the 30th, with the bulk of that falling in just a few hours late on the 29th. Pedestrian bridges and side roads were flooded along the river from the Henderson County line to Chimney Rock Village. Also, public reported a bridge washed out over Buffalo Creek near where it flows into Lake Lure.');
INSERT INTO public.stormevents_east VALUES (787162, 201809, 30, 120, 201809, 30, 330, 131596, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '30-SEP-18 01:20:00', 'EST-5', '30-SEP-18 03:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BAT CAVE', 0, 'E', 'BAT CAVE', 35.454, -82.291, 35.45, -82.276, 'Heavy rain showers and isolated thunderstorms developed near the Blue Ridge escarpment within a moist southeast upslope flow throughout the 29th. Localized heavy rainfall developed during the evening and into the early morning hours of the 30th, culminating in localized flash flooding across the mountains during the early morning hours.', 'A stream gauge on the Rocky Broad River at Bat Cave exceeded its established flood stage after 4 to 8 inches of rain fell during the 29th and early part of the 30th, with the bulk of that falling during the evening. A few roads were flooded along the river in the Bat Cave community.');
INSERT INTO public.stormevents_east VALUES (787165, 201809, 30, 200, 201809, 30, 330, 131596, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '30-SEP-18 02:00:00', 'EST-5', '30-SEP-18 03:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'CoCoRaHS', NULL, NULL, 'Heavy Rain', NULL, 4, 'ESE', 'BLUE RIDGE', 5, 'ESE', 'BLUE RIDGE', 35.562, -82.262, 35.549, -82.246, 'Heavy rain showers and isolated thunderstorms developed near the Blue Ridge escarpment within a moist southeast upslope flow throughout the 29th. Localized heavy rainfall developed during the evening and into the early morning hours of the 30th, culminating in localized flash flooding across the mountains during the early morning hours.', 'Cocorahs observer reported flash flooding developed along tributaries of the rocky Broad River in buncombe county after 4 to 8 inches fell in the basin throughout the 29th and the early part of the 30th, with the bulk of that falling during the evening. Affected Streams included grice branch and duck branch, which was responsible for a washed out bridge.');
INSERT INTO public.stormevents_east VALUES (795253, 201812, 21, 1648, 201812, 21, 1648, 132914, 'MARYLAND', 24, 2018, 'December', 'Hail', 'LWX', '21-DEC-18 16:48:00', 'EST-5', '21-DEC-18 16:48:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'N', 'EASTVIEW', 0, 'N', 'EASTVIEW', 39.52, -76.95, 39.52, -76.95, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the|atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'Quarter size hail was reported on the southeast side of Westminster.');
INSERT INTO public.stormevents_east VALUES (770120, 201806, 18, 1829, 201806, 18, 1829, 128365, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '18-JUN-18 18:29:00', 'EST-5', '18-JUN-18 18:29:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Newspaper', 50, 'EG', NULL, NULL, 1, 'E', 'BREWSTER', 1, 'E', 'BREWSTER', 41.4, -73.61, 41.4, -73.61, 'A prefrontal trough ahead of a cold front approaching from the west brought severe weather to Southeastern New York.', 'A tree and wires down on Peaceable Hill Road.');
INSERT INTO public.stormevents_east VALUES (770132, 201806, 18, 1845, 201806, 18, 1845, 128365, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '18-JUN-18 18:45:00', 'EST-5', '18-JUN-18 18:45:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Public', 61, 'EG', NULL, NULL, 1, 'E', 'JEFFERSON VLY', 1, 'E', 'JEFFERSON VLY', 41.33, -73.79, 41.33, -73.79, 'A prefrontal trough ahead of a cold front approaching from the west brought severe weather to Southeastern New York.', 'A 25 foot tree split at top of tree along with numerous large branches down on Adrea Road.');
INSERT INTO public.stormevents_east VALUES (770186, 201806, 24, 1902, 201806, 24, 1902, 128378, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '24-JUN-18 19:02:00', 'EST-5', '24-JUN-18 19:02:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'ESE', 'PLEASANTVILLE', 1, 'ESE', 'PLEASANTVILLE', 41.14, -73.78, 41.14, -73.78, 'A cold front from the northwest approached the region bringing strong to severe thunderstorms across Southeast New York.', 'A tree down on wires on Old Sleepy Hollow Road.');
INSERT INTO public.stormevents_east VALUES (781328, 201808, 3, 330, 201808, 3, 546, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 03:30:00', 'EST-5', '03-AUG-18 05:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'WOODYCREST', 1, 'NW', 'COLEVILLE', 40.798, -77.921, 40.9089, -77.7891, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'Early morning heavy rainfall brought flash flooding to the State College area.  Numerous roads were closed, including Fox Hollow Road, West Pine Grove Road and portions of East College Avenue.');
INSERT INTO public.stormevents_east VALUES (759414, 201805, 12, 2358, 201805, 12, 2358, 126515, 'MARYLAND', 24, 2018, 'May', 'Hail', 'AKQ', '12-MAY-18 23:58:00', 'EST-5', '12-MAY-18 23:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1.5, NULL, NULL, NULL, 1, 'W', 'WESTOVER', 1, 'W', 'WESTOVER', 38.12, -75.71, 38.12, -75.71, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds and large hail across portions of the Lower Maryland Eastern Shore.', 'Ping pong ball size hail was reported.');
INSERT INTO public.stormevents_east VALUES (750181, 201806, 6, 1131, 201806, 6, 1131, 125073, 'GULF OF MEXICO', 85, 2018, 'June', 'Marine Thunderstorm Wind', 'TBW', '06-JUN-18 11:31:00', 'EST-5', '06-JUN-18 11:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 6, 'W', 'MIDDLE TAMPA BAY', 6, 'W', 'MIDDLE TAMPA BAY', 27.7685, -82.6257, 27.7685, -82.6257, 'Deep moisture along a stalled cold front across the northern Gulf of Mexico led to scattered thunderstorms moving east into the Florida Peninsula during the morning and afternoon hours. A couple of these storms produced gusty winds along the coast.', 'The ASOS at Albert Whitted Airport (KSPG) measured a 24 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (750716, 201806, 10, 2347, 201806, 11, 100, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PHI', '10-JUN-18 23:47:00', 'EST-5', '11-JUN-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'CHESTERBROOK', 1, 'ENE', 'CHESTERBROOK', 40.07, -75.43, 40.0742, -75.4357, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on U.S. Highway 202 between Valley Forge Road and State Highway 29.');
INSERT INTO public.stormevents_east VALUES (751363, 201806, 9, 1530, 201806, 9, 1730, 125267, 'DELAWARE', 10, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 15:30:00', 'EST-5', '09-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'BETHEL', 1, 'NE', 'LAUREL', 38.574, -75.6221, 38.5647, -75.5559, 'Heavy rain fell in southern Delaware on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'Several roads were flooded from Bethel to Laurel.');
INSERT INTO public.stormevents_east VALUES (781331, 201808, 3, 1009, 201808, 3, 1315, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 10:09:00', 'EST-5', '03-AUG-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'BARBOURS', 4, 'ESE', 'BARBOURS', 41.4, -76.78, 41.3803, -76.7287, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'Flash flooding closed Lower Barbours Road along The Loyalsock Cree.   Many roads were closed across the area.');
INSERT INTO public.stormevents_east VALUES (781332, 201808, 3, 1001, 201808, 3, 1145, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 10:01:00', 'EST-5', '03-AUG-18 11:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'JULIAN', 1, 'WNW', 'BELLEFONTE ARPT', 40.84, -77.92, 40.8835, -77.8392, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'Widespread flash flooding across the area.  Some roads impacted included Fox Hollow Road, Buffalo Run Road, Rock Road, the Benner Pike near the Sheetz, and East College Avenue by the YBC.');
INSERT INTO public.stormevents_east VALUES (781346, 201808, 3, 2142, 201808, 3, 2200, 130516, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '03-AUG-18 21:42:00', 'EST-5', '03-AUG-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'REINHOLDS', 1, 'SW', 'REINHOLDS', 40.2718, -76.1294, 40.2641, -76.1283, 'A moist weather pattern brought waves of heavy rain to the area.  Flash flooding was reported with the rainfall.', 'A water rescue occurred on Creamery Road at the railroad tracks in West Cocalico Township.');
INSERT INTO public.stormevents_east VALUES (782189, 201808, 31, 1330, 201808, 31, 2200, 128680, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'CTP', '31-AUG-18 13:30:00', 'EST-5', '31-AUG-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'FLORIN', 2, 'NW', 'KLINESVILLE', 40.1228, -76.5334, 40.0713, -76.5262, 'A weak frontal boundary and copious moisture in place was the trigger for significant flash flooding across Lebanon, Lancaster and York Counties on Friday August 31st.', 'A nearly stationary thunderstorm brought over 10 inches of rain in several hours between Manheim Borough and Mount Joy Borough.  This prompted severe flash flooding in this area, with numerous water rescues and one home that was evacuated.  PA Route 283 was closed in both directions at PA 772.');
INSERT INTO public.stormevents_east VALUES (793693, 201811, 7, 1815, 201811, 7, 1825, 132630, 'GEORGIA', 13, 2018, 'November', 'Thunderstorm Wind', 'FFC', '07-NOV-18 18:15:00', 'EST-5', '07-NOV-18 18:25:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 3, 'S', 'IVEY', 3, 'S', 'IVEY', 32.88, -83.28, 32.88, -83.28, 'Thunderstorms along a slowly moving cold front produced isolated reports of damaging thunderstorm winds across central Georgia during the late afternoon and early evening.', 'The Wilkinson County Emergency Manager reported a tree blown down on Gordon McIntyre Road.');
INSERT INTO public.stormevents_east VALUES (793695, 201811, 7, 1820, 201811, 7, 1825, 132630, 'GEORGIA', 13, 2018, 'November', 'Thunderstorm Wind', 'FFC', '07-NOV-18 18:20:00', 'EST-5', '07-NOV-18 18:25:00', 0, 0, 0, 0, '10.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 2, 'W', 'SINCLAIR LAKE', 2, 'W', 'SINCLAIR LAKE', 33.1796, -83.2927, 33.1796, -83.2927, 'Thunderstorms along a slowly moving cold front produced isolated reports of damaging thunderstorm winds across central Georgia during the late afternoon and early evening.', 'The Baldwin County Emergency Manager reported a tree blown down on Admiralty Way. The tree struck and damaged 2 cars, no injuries were reported.');
INSERT INTO public.stormevents_east VALUES (793697, 201811, 7, 1845, 201811, 7, 1855, 132630, 'GEORGIA', 13, 2018, 'November', 'Thunderstorm Wind', 'FFC', '07-NOV-18 18:45:00', 'EST-5', '07-NOV-18 18:55:00', 0, 0, 0, 0, '2.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 8, 'NW', 'SPANN', 8, 'NW', 'SPANN', 32.74, -82.86, 32.74, -82.86, 'Thunderstorms along a slowly moving cold front produced isolated reports of damaging thunderstorm winds across central Georgia during the late afternoon and early evening.', 'The Johnson County Emergency Manager reported trees blown down along Calvary Church Road.');
INSERT INTO public.stormevents_east VALUES (766472, 201806, 18, 1549, 201806, 18, 1549, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:49:00', 'EST-5', '18-JUN-18 15:49:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'HARMONYVILLE', 1, 'N', 'HARMONYVILLE', 43.04, -72.67, 43.04, -72.67, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (766474, 201806, 18, 1557, 201806, 18, 1557, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:57:00', 'EST-5', '18-JUN-18 15:57:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'PUTNEY STATION', 0, 'N', 'PUTNEY STATION', 42.97, -72.52, 42.97, -72.52, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (766473, 201806, 18, 1553, 201806, 18, 1553, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 15:53:00', 'EST-5', '18-JUN-18 15:53:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'LONDONDERRY', 1, 'W', 'LONDONDERRY', 43.23, -72.81, 43.23, -72.81, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (767532, 201806, 25, 1535, 201806, 25, 1535, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'RAH', '25-JUN-18 15:35:00', 'EST-5', '25-JUN-18 15:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'W', 'LAKEDALE', 1, 'W', 'LAKEDALE', 35.03, -78.94, 35.03, -78.94, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', NULL);
INSERT INTO public.stormevents_east VALUES (767533, 201806, 25, 1625, 201806, 25, 1625, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'RAH', '25-JUN-18 16:25:00', 'EST-5', '25-JUN-18 16:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 1, 'W', 'SCOTCH GROVE', 1, 'W', 'SCOTCH GROVE', 34.85, -79.44, 34.85, -79.44, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', NULL);
INSERT INTO public.stormevents_east VALUES (767534, 201806, 25, 1630, 201806, 25, 1630, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'RAH', '25-JUN-18 16:30:00', 'EST-5', '25-JUN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 4, 'ENE', 'SANATORIUM', 4, 'ENE', 'SANATORIUM', 35.1, -79.26, 35.1, -79.26, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'Hail up to ping pong size was reported.');
INSERT INTO public.stormevents_east VALUES (749869, 201804, 15, 2115, 201804, 15, 2115, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 21:15:00', 'EST-5', '15-APR-18 21:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'NWS Storm Survey', 50, 'EG', NULL, NULL, 4, 'NE', 'NOTTOWAY', 4, 'NE', 'NOTTOWAY', 37.17, -78.02, 37.17, -78.02, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Roof was removed from an old and rotted wooden shed. This damage was consistent with straight line winds.');
INSERT INTO public.stormevents_east VALUES (757484, 201805, 10, 1600, 201805, 10, 1600, 126346, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'AKQ', '10-MAY-18 16:00:00', 'EST-5', '10-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 3, 'WSW', 'BEACH', 3, 'WSW', 'BEACH', 37.33, -77.64, 37.33, -77.64, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Quarter size hail was reported.');
INSERT INTO public.stormevents_east VALUES (757504, 201805, 10, 1725, 201805, 10, 1725, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 17:25:00', 'EST-5', '10-MAY-18 17:25:00', 0, 0, 0, 0, '2.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'N', 'WAKEFIELD', 1, 'N', 'WAKEFIELD', 36.98, -76.98, 36.98, -76.98, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Large maple tree was downed. One pine tree was downed, and two were snapped.');
INSERT INTO public.stormevents_east VALUES (757506, 201805, 10, 1745, 201805, 10, 1745, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 17:45:00', 'EST-5', '10-MAY-18 17:45:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NNW', 'BACONS CASTLE', 2, 'NNW', 'BACONS CASTLE', 37.13, -76.75, 37.13, -76.75, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed on Chippokes Farm Road.');
INSERT INTO public.stormevents_east VALUES (759417, 201805, 13, 340, 201805, 13, 340, 126515, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '13-MAY-18 03:40:00', 'EST-5', '13-MAY-18 03:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 9, 'ESE', 'BOXIRON', 9, 'ESE', 'BOXIRON', 38.08, -75.2, 38.08, -75.2, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds and large hail across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 3.25 inches was measured at Mesonet Station ASTM2, ASSATEAGUE RAWS.  Rainfall total of 1.69 inches was measured in one hour.');
INSERT INTO public.stormevents_east VALUES (759418, 201805, 12, 2025, 201805, 12, 2025, 126515, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '12-MAY-18 20:25:00', 'EST-5', '12-MAY-18 20:25:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'N', 'HURLOCK', 1, 'N', 'HURLOCK', 38.64, -75.87, 38.64, -75.87, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds and large hail across portions of the Lower Maryland Eastern Shore.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (768882, 201806, 13, 1934, 201806, 13, 1934, 128199, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '13-JUN-18 19:34:00', 'EST-5', '13-JUN-18 19:34:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'GREENE', 0, 'N', 'GREENE', 42.33, -75.77, 42.33, -75.77, 'A strong area of low pressure moved  from northern Ontario to the Saint Lawrence Valley from the day of the 13th into the evening. This low pressure system pushed a cold front into central New York which triggered severe thunderstorms which produced damaging winds.', 'Thunderstorm winds knocked down trees and power lines on County Route 3A.');
