INSERT INTO public.stormevents_east VALUES (754758, 201806, 21, 1859, 201806, 21, 1859, 125871, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RNK', '21-JUN-18 18:59:00', 'EST-5', '21-JUN-18 18:59:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SW', 'WAITEVILLE', 1, 'SW', 'WAITEVILLE', 37.4704, -80.4433, 37.4704, -80.4433, 'A lone severe thunderstorm brought localized wind damage to Monroe County.', 'Two large limbs of a tree were blown down by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (760534, 201806, 15, 1943, 201806, 15, 1943, 126863, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '15-JUN-18 19:43:00', 'EST-5', '15-JUN-18 19:43:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 56, 'EG', NULL, NULL, 4, 'SSW', 'MC BRIDE CORNERS', 4, 'SSW', 'MC BRIDE CORNERS', 33.85, -80.17, 33.85, -80.17, 'Instability caused by daytime heating, combined with surface convergence along a surface trough and outflow boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Sumter County Sheriff reported numerous trees down on the following roadways: E Brewington Road, Foxworth Mill Road, Asbury Lane and Queen Chapels Road.');
