INSERT INTO public.stormevents_east VALUES (760548, 201806, 15, 2041, 201806, 15, 2041, 126863, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '15-JUN-18 20:41:00', 'EST-5', '15-JUN-18 20:41:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 52, 'MG', NULL, NULL, 0, 'SE', '(SSC)SHAW AFB SUMTER', 0, 'SE', '(SSC)SHAW AFB SUMTER', 33.9657, -80.4757, 33.9657, -80.4757, 'Instability caused by daytime heating, combined with surface convergence along a surface trough and outflow boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Shaw AFB ASOS recorded 52-knot (60 mph) wind gust.');
INSERT INTO public.stormevents_east VALUES (760549, 201806, 15, 2055, 201806, 15, 2055, 126863, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'CAE', '15-JUN-18 20:55:00', 'EST-5', '15-JUN-18 20:55:00', 0, 0, 0, 0, '0.00K', '0.10K', 'Social Media', 0.25, NULL, NULL, NULL, 1, 'SSE', 'PINCKNEY XRDS', 1, 'SSE', 'PINCKNEY XRDS', 33.9704, -80.4934, 33.9704, -80.4934, 'Instability caused by daytime heating, combined with surface convergence along a surface trough and outflow boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Social media report of pea-size hail lasting about 90 seconds near Shaw AFB.');
