INSERT INTO public.stormevents_east VALUES (755810, 201806, 2, 1448, 201806, 2, 1449, 126044, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 14:48:00', 'EST-5', '02-JUN-18 14:49:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'SYLVANIA', 1, 'W', 'SYLVANIA', 32.75, -81.65, 32.75, -81.65, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Screven County 911 Call Center reported a tree down on Forest Road in Sylvania.');
