INSERT INTO public.stormevents_east VALUES (772046, 201807, 28, 1412, 201807, 28, 1412, 128670, 'VERMONT', 50, 2018, 'July', 'Thunderstorm Wind', 'ALY', '28-JUL-18 14:12:00', 'EST-5', '28-JUL-18 14:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NW', 'WESTMINSTER STATION', 1, 'NW', 'WESTMINSTER STATION', 43.0887, -72.458, 43.0887, -72.458, 'Scattered thunderstorms developed during the afternoon of July 28th ahead of a weak frontal boundary. One of these storms produced fairly extensive damage across the town of Westminster, downing numerous trees, some onto houses and cars. The storm cleanup was estimated to cost $80,000, and portions of the town lost power which was not restored until the next day.', 'Trees were downed near Interstate 91 south of exit 5.');
INSERT INTO public.stormevents_east VALUES (767539, 201806, 25, 1442, 201806, 25, 1442, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 14:42:00', 'EST-5', '25-JUN-18 14:42:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NE', 'ARABIA', 2, 'NE', 'ARABIA', 34.9683, -79.1012, 34.9683, -79.1012, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'A tree was reported down on a power line in the 3100 block of Pittman Grove Church Road.');
