INSERT INTO public.stormevents_east VALUES (767541, 201806, 25, 1535, 201806, 25, 1535, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 15:35:00', 'EST-5', '25-JUN-18 15:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'KORNBOW', 1, 'S', 'KORNBOW', 35.0626, -78.92, 35.0626, -78.92, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down on Morganton Road.');
INSERT INTO public.stormevents_east VALUES (767542, 201806, 25, 1755, 201806, 25, 1755, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 17:55:00', 'EST-5', '25-JUN-18 17:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'LEWISVILLE', 1, 'WNW', 'LEWISVILLE', 36.104, -80.441, 36.104, -80.441, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down on Conrad Road near Shallowford Road.');
INSERT INTO public.stormevents_east VALUES (767543, 201806, 25, 1804, 201806, 25, 1804, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 18:04:00', 'EST-5', '25-JUN-18 18:04:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'CLEMMONS', 1, 'W', 'CLEMMONS', 36.0192, -80.3965, 36.0192, -80.3965, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One large tree was reported down on Meeting House Lane, near Clemmons Road.');
INSERT INTO public.stormevents_east VALUES (757488, 201805, 10, 1445, 201805, 10, 1445, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 14:45:00', 'EST-5', '10-MAY-18 14:45:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'CARTERSVILLE', 1, 'SW', 'CARTERSVILLE', 37.66, -78.11, 37.66, -78.11, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Trees were downed near Cartersville.');
