INSERT INTO public.stormevents_east VALUES (760507, 201806, 20, 1431, 201806, 20, 1436, 126871, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '20-JUN-18 14:31:00', 'EST-5', '20-JUN-18 14:36:00', 0, 0, 0, 0, NULL, NULL, 'Public', 70, 'EG', NULL, NULL, 1, 'NE', 'SOUTH CONGAREE', 1, 'NE', 'SOUTH CONGAREE', 33.9104, -81.1044, 33.9104, -81.1044, 'Strong daytime heating and a surface trough led to scattered thunderstorms during the afternoon and evening, an isolated storm over the Central Midlands was severe.', 'Reports received, via social media, of numerous trees downed, split in half, or uprooted, including some trees down on power lines, in Pine Ridge and vicinity, including Arborgate subdivision.');
INSERT INTO public.stormevents_east VALUES (767788, 201806, 18, 1652, 201806, 18, 1656, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 16:52:00', 'EST-5', '18-JUN-18 16:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'N', 'SOUTH GORHAM', 1, 'N', 'SOUTH GORHAM', 43.64, -70.42, 43.64, -70.42, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed trees in South Gorham.');
INSERT INTO public.stormevents_east VALUES (767793, 201806, 18, 1750, 201806, 18, 1755, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:50:00', 'EST-5', '18-JUN-18 17:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'E', 'BERWICK', 1, 'E', 'BERWICK', 43.27, -70.86, 43.27, -70.86, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires in Berwick.');
INSERT INTO public.stormevents_east VALUES (767797, 201806, 18, 1757, 201806, 18, 1801, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:57:00', 'EST-5', '18-JUN-18 18:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'WELLS', 0, 'N', 'WELLS', 43.32, -70.58, 43.32, -70.58, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed large branches resulting in power outages in Wells.');
INSERT INTO public.stormevents_east VALUES (767802, 201806, 30, 2116, 201806, 30, 2120, 128015, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Hail', 'GYX', '30-JUN-18 21:16:00', 'EST-5', '30-JUN-18 21:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 0.88, NULL, NULL, NULL, 0, 'W', '(BML)BERLIN MUNI ARP', 0, 'W', '(BML)BERLIN MUNI ARP', 44.57, -71.19, 44.57, -71.19, 'Isolated convection formed ahead of a warm front lifting northeast through the region during the  afternoon of June 30th. An isolated cell in Coos County produced 1.00 inch hail.', 'A thunderstorm produced 0.88 inch Hail near Berlin.');
INSERT INTO public.stormevents_east VALUES (767804, 201806, 30, 2138, 201806, 30, 2142, 128015, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Hail', 'GYX', '30-JUN-18 21:38:00', 'EST-5', '30-JUN-18 21:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1, NULL, NULL, NULL, 1, 'W', 'BERLIN', 1, 'W', 'BERLIN', 44.47, -71.19, 44.47, -71.19, 'Isolated convection formed ahead of a warm front lifting northeast through the region during the  afternoon of June 30th. An isolated cell in Coos County produced 1.00 inch hail.', 'A severe thunderstorm produced 1 inch hail in Berlin.');
INSERT INTO public.stormevents_east VALUES (769363, 201806, 11, 1735, 201806, 11, 1735, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Lightning', 'RAH', '11-JUN-18 17:35:00', 'EST-5', '11-JUN-18 17:35:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 2, 'NNE', 'INGOLD', 2, 'NNE', 'INGOLD', 34.8539, -78.3375, 34.8539, -78.3375, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'A lightning strike caught a house on fire along Tatum Lane, near Garland. Damages were estimated.');
INSERT INTO public.stormevents_east VALUES (769399, 201806, 23, 1511, 201806, 23, 1511, 128284, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '23-JUN-18 15:11:00', 'EST-5', '23-JUN-18 15:11:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 0, 'N', 'CHINCOTEAGUE', 0, 'N', 'CHINCOTEAGUE', 37.93, -75.38, 37.93, -75.38, 'Scattered severe thunderstorms in advance of a frontal boundary produced damaging winds and large hail across portions of eastern Virginia.', 'Wind gust of 52 knots (60 mph) was measured at Mesonet Station E9295 (1 WSW Chincoteague).');
INSERT INTO public.stormevents_east VALUES (769551, 201806, 24, 1540, 201806, 24, 1540, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 15:40:00', 'EST-5', '24-JUN-18 15:40:00', 0, 0, 0, 0, '3.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 1, 'ENE', 'ANTIOCH FORK', 1, 'ENE', 'ANTIOCH FORK', 38.03, -77.31, 38.03, -77.31, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Numerous trees were downed county wide.');
