INSERT INTO public.stormevents_east VALUES (769589, 201806, 24, 1655, 201806, 24, 1655, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 16:55:00', 'EST-5', '24-JUN-18 16:55:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'LIVELY', 0, 'N', 'LIVELY', 37.78, -76.52, 37.78, -76.52, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees were downed and blocking Route 3 (Kings Highway) and Ball Road.');
INSERT INTO public.stormevents_east VALUES (769595, 201806, 24, 1658, 201806, 24, 1658, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 16:58:00', 'EST-5', '24-JUN-18 16:58:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 47, 'SW', 'WELLFORD', 47, 'SW', 'WELLFORD', 37.46, -77.45, 37.46, -77.45, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Trees and power lines were downed on Cronin Road in Richmond.');
INSERT INTO public.stormevents_east VALUES (769996, 201806, 2, 1744, 201806, 2, 1745, 126045, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '02-JUN-18 17:44:00', 'EST-5', '02-JUN-18 17:45:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 1, 'WSW', 'FOLLY BEACH', 1, 'WSW', 'FOLLY BEACH', 32.65, -79.94, 32.65, -79.94, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across the coastal waters.', 'The Folly Beach Weatherflow sensor recorded a wind gust of 36 knots.');
INSERT INTO public.stormevents_east VALUES (767637, 201806, 10, 1741, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 17:41:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'BOSTON', 1, 'E', 'MC KEESPORT', 40.33, -79.81, 40.3316, -79.8174, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported at the intersection of Long Run Road and Cool Springs Road.');
INSERT INTO public.stormevents_east VALUES (767639, 201806, 10, 1838, 201806, 10, 2045, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 18:38:00', 'EST-5', '10-JUN-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'BRENTWOOD', 2, 'NNW', 'BRENTWOOD', 40.3913, -79.9824, 40.3907, -79.9809, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Becks Run Road was closed by flooding between Brownsville Road and Raven Street.');
INSERT INTO public.stormevents_east VALUES (767638, 201806, 10, 1743, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 17:43:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ELIZABETH', 1, 'W', 'ELIZABETH', 40.27, -79.9, 40.2697, -79.9009, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported at the intersection of 6th Street and Burnett Street.');
INSERT INTO public.stormevents_east VALUES (767645, 201806, 10, 1909, 201806, 10, 2045, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 19:09:00', 'EST-5', '10-JUN-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'CHALEANT', 0, 'ENE', 'CHALEANT', 40.4249, -79.8154, 40.4216, -79.8113, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported at the intersection of Thompson Run Road and Larimer Avenue.');
INSERT INTO public.stormevents_east VALUES (767745, 201806, 18, 1438, 201806, 18, 1443, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 14:38:00', 'EST-5', '18-JUN-18 14:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'WOODSTOCK', 1, 'W', 'WOODSTOCK', 43.98, -71.69, 43.98, -71.69, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires on Route 112 in Woodstock.');
INSERT INTO public.stormevents_east VALUES (767748, 201806, 18, 1503, 201806, 18, 1508, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 15:03:00', 'EST-5', '18-JUN-18 15:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SW', 'BATH', 2, 'SW', 'BATH', 44.15, -72, 44.15, -72, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires in Bath.');
INSERT INTO public.stormevents_east VALUES (767751, 201806, 18, 1605, 201806, 18, 1609, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 16:05:00', 'EST-5', '18-JUN-18 16:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SE', 'WESTMORELAND', 1, 'SE', 'WESTMORELAND', 42.96, -72.44, 42.96, -72.44, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed multiple trees in Westmoreland.');
