INSERT INTO public.stormevents_east VALUES (755848, 201806, 2, 1600, 201806, 2, 1601, 126044, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 16:00:00', 'EST-5', '02-JUN-18 16:01:00', 0, 0, 0, 0, NULL, NULL, 'Official NWS Observations', 53, 'MG', NULL, NULL, 3, 'NE', 'FT SCREVEN', 3, 'NE', 'FT SCREVEN', 32.03, -80.9, 32.03, -80.9, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Fort Pulaski NOS tide gauge measured a 61 mph wind gust.');
