INSERT INTO public.stormevents_east VALUES (761085, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'KING WILLIAM', 0, 'N', 'RUMFORD', 37.68, -77.02, 37.7251, -77.0812, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
