INSERT INTO public.stormevents_east VALUES (791248, 201811, 2, 2124, 201811, 2, 2124, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:24:00', 'EST-5', '02-NOV-18 21:24:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Tolchester.');
INSERT INTO public.stormevents_east VALUES (791250, 201811, 2, 2118, 201811, 2, 2124, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:18:00', 'EST-5', '02-NOV-18 21:24:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 1, 'WSW', 'POTOMAC LIGHT 33 (LT3)', 1, 'WSW', 'POTOMAC LIGHT 33 (LT3)', 38.3333, -77.0115, 38.3333, -77.0115, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Dahlgren.');
INSERT INTO public.stormevents_east VALUES (791251, 201811, 2, 2118, 201811, 2, 2123, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:18:00', 'EST-5', '02-NOV-18 21:23:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 1, 'NW', 'POTOMAC LIGHT 33 (LT3)', 1, 'NW', 'POTOMAC LIGHT 33 (LT3)', 38.3514, -77.0109, 38.3514, -77.0109, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Pylons.');
INSERT INTO public.stormevents_east VALUES (791252, 201811, 2, 2126, 201811, 2, 2131, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:26:00', 'EST-5', '02-NOV-18 21:31:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 38.34, -76.99, 38.34, -76.99, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 38 knots was measured at Potomac Light.');
INSERT INTO public.stormevents_east VALUES (750503, 201804, 10, 1555, 201804, 10, 1555, 125146, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '10-APR-18 15:55:00', 'EST-5', '10-APR-18 15:55:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 39, 'MG', NULL, NULL, 3, 'SSE', 'PORT EVERGLADES', 3, 'SSE', 'PORT EVERGLADES', 26.0583, -80.1108, 26.0583, -80.1108, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms, initially producing strong wind gusts over Lake Okeechobee, then moving offshore into the local Atlantic waters were a brief waterspout was also reported.', 'A marine thunderstorm wind gust of 45 mph / 39 knots was recorded by the WxFlow mesonet site XDAN at Dania Beach Pier. An additional wind gust to 40 mph/ 35 knots was recorded at 505pm EDT.');
INSERT INTO public.stormevents_east VALUES (750511, 201804, 10, 1606, 201804, 10, 1606, 125146, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '10-APR-18 16:06:00', 'EST-5', '10-APR-18 16:06:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 50, 'MG', NULL, NULL, 7, 'S', 'HALLANDALE BEACH', 7, 'S', 'HALLANDALE BEACH', 25.9012, -80.1235, 25.9012, -80.1235, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms, initially producing strong wind gusts over Lake Okeechobee, then moving offshore into the local Atlantic waters were a brief waterspout was also reported.', 'A marine thunderstorm wind gust of 57 mph / 50 knots was recorded by a WeatherBug mesonet site MDFR4 located at Miami Dade Fire Rescue Fire Station 21.');
INSERT INTO public.stormevents_east VALUES (750515, 201804, 10, 1614, 201804, 10, 1614, 125146, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Waterspout', 'MFL', '10-APR-18 16:14:00', 'EST-5', '10-APR-18 16:14:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 4, 'N', 'MIAMI BEACH', 4, 'N', 'MIAMI BEACH', 25.861, -80.1112, 25.861, -80.1112, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms, initially producing strong wind gusts over Lake Okeechobee, then moving offshore into the local Atlantic waters were a brief waterspout was also reported.', 'A trained weather spotter reported a waterspout just off of Miami Beach east of 76th Street and Collins Avenue.');
INSERT INTO public.stormevents_east VALUES (750537, 201804, 15, 1735, 201804, 15, 1735, 125149, 'GULF OF MEXICO', 85, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 17:35:00', 'EST-5', '15-APR-18 17:35:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 40, 'MG', NULL, NULL, 25, 'SSE', 'WIGGINS PASS', 25, 'SSE', 'WIGGINS PASS', 25.92, -81.73, 25.92, -81.73, 'A band of strong showers and storms moved eastward across the Gulf and into the Southwest Florida coast during the early evening hours of April 15. A strong wind gust was recorded as these storms arrived along the Collier County coast.', 'A WeatherBug mesonet site at the Charter Club of Marco Beach reported a wind gust of 40 knots / 46 mph.');
INSERT INTO public.stormevents_east VALUES (750543, 201804, 15, 1815, 201804, 15, 1815, 125150, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 18:15:00', 'EST-5', '15-APR-18 18:15:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 9, 'WSW', 'PORT MAYACA', 9, 'WSW', 'PORT MAYACA', 26.96, -80.94, 26.96, -80.94, 'A band of strong showers and storms moved eastward across South Florida during the evening hours of April 15. These storms produced several strong wind gusts across Lake Okeechobee before moving out into the local Atlantic waters, producing additional strong gusts as they moved offshore.', 'A 35 knot / 40 mph wind gust  was recorded by the SFWMD mesonet site L005 Located over the western portion of Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (786124, 201809, 27, 1720, 201809, 27, 1720, 131379, 'GEORGIA', 13, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 17:20:00', 'EST-5', '27-SEP-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'SANDY CROSS', 2, 'E', 'CANON FRANKLIN CO AR', 34.248, -83.193, 34.327, -83.1, 'A cluster of thunderstorms moved into northeast Georgia from the southwest during the late afternoon and evening. Several areas of low-end wind damage were reported across the Piedmont.', 'County comms reported a couple of trees blown down.');
INSERT INTO public.stormevents_east VALUES (785386, 201809, 1, 2025, 201809, 1, 2025, 131269, 'NORTH CAROLINA', 37, 2018, 'September', 'Hail', 'GSP', '01-SEP-18 20:25:00', 'EST-5', '01-SEP-18 20:25:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 2, 'W', 'GLEN ALPINE', 2, 'W', 'GLEN ALPINE', 35.73, -81.827, 35.73, -81.827, 'Isolated thunderstorms developed over the North Carolina Piedmont and foothills during the evening. A couple of the storms produced brief severe weather.', 'Media reported up to quarter size hail covering the ground in the area around Powerhouse Rd, RR White Dr, and Conley Bumgarner Rd.');
INSERT INTO public.stormevents_east VALUES (785959, 201809, 2, 1605, 201809, 2, 1610, 131356, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '02-SEP-18 16:05:00', 'EST-5', '02-SEP-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'MORGANTON', 3, 'N', 'ENOLA', 35.725, -81.693, 35.707, -81.65, 'Isolated thunderstorms developed across the foothills and western Piedmont during the afternoon and evening. A couple of the storms produced brief damaging winds.', 'County comms reported multiple trees blown down across the south side of Morganton. One tree fell on a house and took down a power line on Mt Home Church Ave.');
INSERT INTO public.stormevents_east VALUES (785960, 201809, 2, 1815, 201809, 2, 1815, 131356, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '02-SEP-18 18:15:00', 'EST-5', '02-SEP-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'NEWTON', 2, 'SW', 'NEWTON', 35.664, -81.244, 35.664, -81.244, 'Isolated thunderstorms developed across the foothills and western Piedmont during the afternoon and evening. A couple of the storms produced brief damaging winds.', 'County comms reported a few trees blown down near the intersection of Shannonbrook Dr and Radio Station Rd.');
INSERT INTO public.stormevents_east VALUES (785961, 201809, 2, 1602, 201809, 2, 1602, 131358, 'SOUTH CAROLINA', 45, 2018, 'September', 'Thunderstorm Wind', 'GSP', '02-SEP-18 16:02:00', 'EST-5', '02-SEP-18 16:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'NW', 'LIMA', 2, 'NW', 'LIMA', 35.1, -82.45, 35.1, -82.45, 'Isolated thunderstorms developed over portions of Upstate South Carolina during the late afternoon and evening. One of the storms produced brief damaging winds in northern Greenville County.', 'FD reported two trees and a power line blown down near the intersection of Highway 25 and Old Highway 25.');
INSERT INTO public.stormevents_east VALUES (786122, 201809, 27, 1713, 201809, 27, 1727, 131379, 'GEORGIA', 13, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 17:13:00', 'EST-5', '27-SEP-18 17:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'GOSS', 2, 'E', 'RUCKERSVILLE', 34.131, -82.951, 34.168, -82.739, 'A cluster of thunderstorms moved into northeast Georgia from the southwest during the late afternoon and evening. Several areas of low-end wind damage were reported across the Piedmont.', 'County comms reported multiple trees blown down across Elbert County.');
INSERT INTO public.stormevents_east VALUES (786123, 201809, 27, 1714, 201809, 27, 1735, 131379, 'GEORGIA', 13, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 17:14:00', 'EST-5', '27-SEP-18 17:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'VANNA', 1, 'SSW', 'HARTWELL RESV', 34.236, -83.085, 34.382, -82.862, 'A cluster of thunderstorms moved into northeast Georgia from the southwest during the late afternoon and evening. Several areas of low-end wind damage were reported across the Piedmont.', 'County comms reported a few trees blown down across Hart County.');
INSERT INTO public.stormevents_east VALUES (786125, 201809, 27, 1740, 201809, 27, 1740, 131380, 'SOUTH CAROLINA', 45, 2018, 'September', 'Thunderstorm Wind', 'GSP', '27-SEP-18 17:40:00', 'EST-5', '27-SEP-18 17:40:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 55, 'EG', NULL, NULL, 7, 'WSW', '(AND)ANDERSON CO ARP', 7, 'WSW', '(AND)ANDERSON CO ARP', 34.448, -82.82, 34.448, -82.82, 'An intensifying cluster of thunderstorms moved into Upstate South Carolina from northeast Georgia during the evening and produced areas of damaging winds along and near the I-85 corridor.', 'Public reported a couple of dozen trees snapped or uprooted off Providence Church Rd. One tree fell on a house on Providence Church Rd.');
INSERT INTO public.stormevents_east VALUES (768944, 201807, 10, 1448, 201807, 10, 1448, 128211, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '10-JUL-18 14:48:00', 'EST-5', '10-JUL-18 14:48:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'BOLTON', 1, 'E', 'BOLTON', 43.53, -73.67, 43.53, -73.67, 'A couple of clusters of thunderstorms formed during the afternoon hours ahead of a cold front. Two of these storms became severe resulting in downed trees, one in the Lake George region and one in the Capital District.', 'A tree was downed near Bolton Landing.');
INSERT INTO public.stormevents_east VALUES (768946, 201807, 10, 1449, 201807, 10, 1449, 128211, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '10-JUL-18 14:49:00', 'EST-5', '10-JUL-18 14:49:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SE', 'PILOT KNOB', 0, 'SE', 'PILOT KNOB', 43.5186, -73.6277, 43.5186, -73.6277, 'A couple of clusters of thunderstorms formed during the afternoon hours ahead of a cold front. Two of these storms became severe resulting in downed trees, one in the Lake George region and one in the Capital District.', 'Trees and wires were downed near Pilot Knob.');
INSERT INTO public.stormevents_east VALUES (768951, 201807, 10, 1544, 201807, 10, 1544, 128211, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '10-JUL-18 15:44:00', 'EST-5', '10-JUL-18 15:44:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'NORTH BETHLEHEM', 1, 'NNW', 'NORTH BETHLEHEM', 42.6808, -73.8578, 42.6808, -73.8578, 'A couple of clusters of thunderstorms formed during the afternoon hours ahead of a cold front. Two of these storms became severe resulting in downed trees, one in the Lake George region and one in the Capital District.', 'A tree was downed on Zorn Road in Guilderland.');
INSERT INTO public.stormevents_east VALUES (768954, 201807, 10, 1549, 201807, 10, 1549, 128211, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '10-JUL-18 15:49:00', 'EST-5', '10-JUL-18 15:49:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'E', 'KARLSFELD', 1, 'E', 'KARLSFELD', 42.6512, -73.8291, 42.6512, -73.8291, 'A couple of clusters of thunderstorms formed during the afternoon hours ahead of a cold front. Two of these storms became severe resulting in downed trees, one in the Lake George region and one in the Capital District.', 'Multiple trees were downed at the intersection of New Scotland and Hartman Roads. One large tree crushed a wooden fence.');
INSERT INTO public.stormevents_east VALUES (768955, 201807, 10, 1553, 201807, 10, 1553, 128211, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '10-JUL-18 15:53:00', 'EST-5', '10-JUL-18 15:53:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WNW', 'ALBANY', 1, 'WNW', 'ALBANY', 42.6562, -73.7942, 42.6562, -73.7942, 'A couple of clusters of thunderstorms formed during the afternoon hours ahead of a cold front. Two of these storms became severe resulting in downed trees, one in the Lake George region and one in the Capital District.', 'Trees were downed on Fairview Avenue.');
INSERT INTO public.stormevents_east VALUES (769025, 201807, 14, 1755, 201807, 14, 1755, 128215, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '14-JUL-18 17:55:00', 'EST-5', '14-JUL-18 17:55:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'LIVINGSTONVILLE', 1, 'N', 'LIVINGSTONVILLE', 42.49, -74.27, 42.49, -74.27, 'Thunderstorms developed ahead of a weak disturbance during the evening of July 14th. A couple of these storms became severe with a few reports of downed trees and wires.', 'A tree and powerlines were downed.');
INSERT INTO public.stormevents_east VALUES (769026, 201807, 14, 1850, 201807, 14, 1850, 128215, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '14-JUL-18 18:50:00', 'EST-5', '14-JUL-18 18:50:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'NW', 'SAWKILL', 2, 'NW', 'SAWKILL', 42, -74.05, 42, -74.05, 'Thunderstorms developed ahead of a weak disturbance during the evening of July 14th. A couple of these storms became severe with a few reports of downed trees and wires.', 'A tree was downed onto wires.');
INSERT INTO public.stormevents_east VALUES (769666, 201806, 24, 1930, 201806, 24, 1930, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 19:30:00', 'EST-5', '24-JUN-18 19:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NW', 'SIGMA', 1, 'NW', 'SIGMA', 36.74, -75.99, 36.74, -75.99, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Several trees were downed in the Lagomar neighborhood.');
INSERT INTO public.stormevents_east VALUES (760030, 201807, 23, 332, 201807, 23, 332, 126777, 'GULF OF MEXICO', 85, 2018, 'July', 'Marine Thunderstorm Wind', 'TBW', '23-JUL-18 03:32:00', 'EST-5', '23-JUL-18 03:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'EG', NULL, NULL, 2, 'SSE', 'CLEARWATER BEACH', 2, 'SSE', 'CLEARWATER BEACH', 27.95, -82.81, 27.95, -82.81, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing marine wind gusts along the coast.', 'A home weather station in Belleair (E6508) recorded a 37 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (760031, 201807, 23, 338, 201807, 23, 338, 126777, 'GULF OF MEXICO', 85, 2018, 'July', 'Marine Thunderstorm Wind', 'TBW', '23-JUL-18 03:38:00', 'EST-5', '23-JUL-18 03:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'EG', NULL, NULL, 10, 'NNE', 'ST PETERSBURG BEACH', 10, 'NNE', 'ST PETERSBURG BEACH', 27.85, -82.67, 27.85, -82.67, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing marine wind gusts along the coast.', 'A home weather station in Pinellas Park (E5225) recorded a 35 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (760034, 201807, 23, 348, 201807, 23, 348, 126777, 'GULF OF MEXICO', 85, 2018, 'July', 'Marine Thunderstorm Wind', 'TBW', '23-JUL-18 03:48:00', 'EST-5', '23-JUL-18 03:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 2, 'ENE', 'OLD TAMPA BAY', 2, 'ENE', 'OLD TAMPA BAY', 27.8578, -82.5527, 27.8578, -82.5527, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing marine wind gusts along the coast.', 'The PORTS site at Old Port Tampa (OPTF1) recorded a 43 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (760036, 201807, 23, 349, 201807, 23, 349, 126777, 'GULF OF MEXICO', 85, 2018, 'July', 'Marine Thunderstorm Wind', 'TBW', '23-JUL-18 03:49:00', 'EST-5', '23-JUL-18 03:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 6, 'W', 'MIDDLE TAMPA BAY', 6, 'W', 'MIDDLE TAMPA BAY', 27.7685, -82.6257, 27.7685, -82.6257, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing marine wind gusts along the coast.', 'The ASOS at Albert Whitted Airport in St. Petersburg (KSPG) recorded a 34 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (760049, 201807, 23, 310, 201807, 23, 310, 126794, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TBW', '23-JUL-18 03:10:00', 'EST-5', '23-JUL-18 03:10:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 2, 'E', 'ELFERS', 2, 'E', 'ELFERS', 28.22, -82.69, 28.22, -82.69, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico and onshore during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing damaging wind gusts across west central Florida.', 'Power lines were reported down on the road near State Road 54 and Rowan Road.');
INSERT INTO public.stormevents_east VALUES (760050, 201807, 23, 311, 201807, 23, 311, 126794, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TBW', '23-JUL-18 03:11:00', 'EST-5', '23-JUL-18 03:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 53, 'EG', NULL, NULL, 1, 'N', 'CRYSTAL BEACH', 1, 'N', 'CRYSTAL BEACH', 28.1, -82.78, 28.1, -82.78, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico and onshore during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing damaging wind gusts across west central Florida.', 'A home weather station recorded a 53 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (760053, 201807, 23, 315, 201807, 23, 315, 126794, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TBW', '23-JUL-18 03:15:00', 'EST-5', '23-JUL-18 03:15:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 3, 'WSW', 'COSME', 3, 'WSW', 'COSME', 28.1, -82.62, 28.1, -82.62, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico and onshore during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing damaging wind gusts across west central Florida.', 'Broadcast media reported power lines blocking the road near Patterson Road and Glass Lake Drive.');
INSERT INTO public.stormevents_east VALUES (756112, 201807, 4, 1810, 201807, 4, 1811, 126131, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'JKL', '04-JUL-18 18:10:00', 'EST-5', '04-JUL-18 18:11:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', 74, 'EG', NULL, NULL, 1, 'SW', 'THELMA', 1, 'SW', 'THELMA', 37.8125, -82.7803, 37.8136, -82.7775, 'A cluster of strong to severe thunderstorms moved west/southwest from West Virginia into portions of northeast and east Kentucky this evening. Due to the high amount of moisture and subsequent instability in place, the downdraft portion of one of these storms produced winds of up to 85 mph as it collapsed over Paintsville. This resulted in substantial damage in Paintsville, including half of a roof being removed from an office building along with the steeple of a church being blown off. A couple of residential buildings were also damaged from falling trees.', 'An NWS Storm Survey confirmed microburst winds of between 75-85 mph felled several trees east of Paintsville, including one which fell on a residential building.');
INSERT INTO public.stormevents_east VALUES (756114, 201807, 4, 1944, 201807, 4, 1944, 126131, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'JKL', '04-JUL-18 19:44:00', 'EST-5', '04-JUL-18 19:44:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 52, 'EG', NULL, NULL, 0, 'S', 'SEITZ', 0, 'S', 'SEITZ', 37.6946, -83.1699, 37.6946, -83.1699, 'A cluster of strong to severe thunderstorms moved west/southwest from West Virginia into portions of northeast and east Kentucky this evening. Due to the high amount of moisture and subsequent instability in place, the downdraft portion of one of these storms produced winds of up to 85 mph as it collapsed over Paintsville. This resulted in substantial damage in Paintsville, including half of a roof being removed from an office building along with the steeple of a church being blown off. A couple of residential buildings were also damaged from falling trees.', 'An NWS Employee observed several trees downed along Kentucky Highway 378 in and around Seitz.');
INSERT INTO public.stormevents_east VALUES (758202, 201807, 3, 1725, 201807, 3, 1725, 126496, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '03-JUL-18 17:25:00', 'EST-5', '03-JUL-18 17:25:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'REGER', 1, 'NE', 'REGER', 38.9866, -80.1683, 38.9866, -80.1683, 'In a very hot and humid airmass, some showers and storms developed during the late afternoon of the 3rd. Most of these were not very strong, however one did produce a downburst causing some tree damage.', 'Several trees were blown down along Kesling Mill Road.');
INSERT INTO public.stormevents_east VALUES (760498, 201807, 23, 1815, 201807, 23, 1815, 126869, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '23-JUL-18 18:15:00', 'EST-5', '23-JUL-18 18:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'WSW', 'BOAZ', 1, 'WSW', 'BOAZ', 39.3626, -81.4977, 39.3626, -81.4977, 'A stacked low pressure system brought showers and thunderstorms on the 23rd. Just enough afternoon sunshine developed in the middle Ohio River Valley for one storm to become severe.', 'Multiple trees were blown down near Boaz.');
INSERT INTO public.stormevents_east VALUES (760508, 201807, 27, 1027, 201807, 27, 1230, 126873, 'WEST VIRGINIA', 54, 2018, 'July', 'Flash Flood', 'RLX', '27-JUL-18 10:27:00', 'EST-5', '27-JUL-18 12:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'TRIPLET', 1, 'SSE', 'TRIPLET', 38.81, -81.2924, 38.8146, -81.2949, 'Showers and thunderstorms formed on the 27th as a cold front moved through. Some storms were stronger, producing isolated tree damage. Some areas also experienced repetitive storms, causing high water in spots.', 'Little Spring Creek flooded, closing the intersection of Triplett Road and Egypt Ridge Road.');
INSERT INTO public.stormevents_east VALUES (760510, 201807, 27, 1120, 201807, 27, 1230, 126873, 'WEST VIRGINIA', 54, 2018, 'July', 'Flash Flood', 'RLX', '27-JUL-18 11:20:00', 'EST-5', '27-JUL-18 12:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'HUR', 2, 'SE', 'HUR', 38.8485, -81.1709, 38.8478, -81.1487, 'Showers and thunderstorms formed on the 27th as a cold front moved through. Some storms were stronger, producing isolated tree damage. Some areas also experienced repetitive storms, causing high water in spots.', 'Coon Fork Run flooded, causing water to flow across Coon Fork Road.');
INSERT INTO public.stormevents_east VALUES (760514, 201807, 27, 1640, 201807, 27, 1740, 126873, 'WEST VIRGINIA', 54, 2018, 'July', 'Flash Flood', 'RLX', '27-JUL-18 16:40:00', 'EST-5', '27-JUL-18 17:40:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'MARMET', 1, 'SW', 'CHESAPEAKE', 38.2365, -81.574, 38.2137, -81.5417, 'Showers and thunderstorms formed on the 27th as a cold front moved through. Some storms were stronger, producing isolated tree damage. Some areas also experienced repetitive storms, causing high water in spots.', 'Lens Creek flooded, closing a portion of Route 60 between Marmet and Chesapeake with water 6 to 15 inches deep. Nearby, at the Bee Mountain RAWS site, the rain gauge had measured 2.17 inches in the previous 4 hours.');
INSERT INTO public.stormevents_east VALUES (760516, 201807, 27, 1326, 201807, 27, 1326, 126873, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '27-JUL-18 13:26:00', 'EST-5', '27-JUL-18 13:26:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SW', 'GALLAGHER', 0, 'SW', 'GALLAGHER', 38.1669, -81.4039, 38.1669, -81.4039, 'Showers and thunderstorms formed on the 27th as a cold front moved through. Some storms were stronger, producing isolated tree damage. Some areas also experienced repetitive storms, causing high water in spots.', 'A couple trees were blown down in the Gallagher and Standard area, including along Paint Creek Road.');
INSERT INTO public.stormevents_east VALUES (765241, 201807, 31, 1242, 201807, 31, 1242, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 12:42:00', 'EST-5', '31-JUL-18 12:42:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'LAVALETTE', 1, 'E', 'LAVALETTE', 38.32, -82.44, 38.32, -82.44, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'Multiple trees were blown down around the town of Lavalette.');
INSERT INTO public.stormevents_east VALUES (765253, 201807, 31, 1320, 201807, 31, 1320, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 13:20:00', 'EST-5', '31-JUL-18 13:20:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 70, 'EG', NULL, NULL, 1, 'SW', 'HURRICANE', 1, 'SW', 'HURRICANE', 38.42, -82.04, 38.42, -82.04, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'A tree was blown down across Lower Coach Road.');
INSERT INTO public.stormevents_east VALUES (767545, 201806, 25, 1810, 201806, 25, 1810, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 18:10:00', 'EST-5', '25-JUN-18 18:10:00', 0, 0, 0, 0, '25.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'LEXINGTON', 1, 'SE', 'LEXINGTON', 35.81, -80.26, 35.81, -80.26, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'Trees were reported down into multiple residences across the county.');
INSERT INTO public.stormevents_east VALUES (768376, 201806, 25, 1815, 201806, 25, 1815, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 18:15:00', 'EST-5', '25-JUN-18 18:15:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'LEXINGTON', 1, 'ENE', 'LEXINGTON', 35.83, -80.25, 35.83, -80.25, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down on a house in Lexington.');
INSERT INTO public.stormevents_east VALUES (768379, 201806, 25, 1834, 201806, 25, 1834, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 18:34:00', 'EST-5', '25-JUN-18 18:34:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'DENTON', 1, 'E', 'DENTON', 35.63, -80.11, 35.63, -80.11, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down on a house in Denton.');
INSERT INTO public.stormevents_east VALUES (768380, 201806, 25, 1840, 201806, 25, 1840, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 18:40:00', 'EST-5', '25-JUN-18 18:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'ESE', 'ALBEMARLE', 2, 'ESE', 'ALBEMARLE', 35.36, -80.19, 35.36, -80.19, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'Several trees were reported across the county, including in the city of Albemarle.');
INSERT INTO public.stormevents_east VALUES (768381, 201806, 25, 1901, 201806, 25, 1901, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 19:01:00', 'EST-5', '25-JUN-18 19:01:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ESE', 'BURNSVILLE', 2, 'ESE', 'BURNSVILLE', 35.1105, -80.2201, 35.1105, -80.2201, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down across Race Track Road.');
INSERT INTO public.stormevents_east VALUES (757493, 201805, 10, 1510, 201805, 10, 1510, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:10:00', 'EST-5', '10-MAY-18 15:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SE', 'JEFFERSON', 1, 'SE', 'JEFFERSON', 37.61, -77.91, 37.61, -77.91, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed at Maidens Road and Huguenot Trail.');
INSERT INTO public.stormevents_east VALUES (768382, 201806, 25, 1901, 201806, 25, 1901, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 19:01:00', 'EST-5', '25-JUN-18 19:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SSW', 'ASHEBORO', 2, 'SSW', 'ASHEBORO', 35.6731, -79.8412, 35.6731, -79.8412, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down at the intersection of Mack Road and McDowell Road.');
INSERT INTO public.stormevents_east VALUES (767988, 201806, 2, 1725, 201806, 2, 1725, 128048, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '02-JUN-18 17:25:00', 'EST-5', '02-JUN-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'WSW', 'MAJOLICA', 1, 'NW', 'ROWAN CO ARPT', 35.718, -80.557, 35.663, -80.541, 'Isolated thunderstorms developed over the foothills of North Carolina during the afternoon and moved east and southeast into the Piedmont. One of the storms produced brief damaging wind gusts and large hail.', 'Spotter reported trees blown down and blocking a driveway on Goodson Road and another tree down on Wheaton Ct. Media also reported a tree down on Highway 70.');
INSERT INTO public.stormevents_east VALUES (757492, 201805, 10, 1510, 201805, 10, 1510, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:10:00', 'EST-5', '10-MAY-18 15:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SE', 'CARDWELL', 1, 'SE', 'CARDWELL', 37.67, -77.77, 37.67, -77.77, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed on Genito Road.');
INSERT INTO public.stormevents_east VALUES (757494, 201805, 10, 1522, 201805, 10, 1522, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:22:00', 'EST-5', '10-MAY-18 15:22:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'DAWN', 1, 'N', 'DAWN', 37.85, -77.37, 37.85, -77.37, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Numerous trees were downed along Gegory Road, Frogg Level Road, and Route 30.');
INSERT INTO public.stormevents_east VALUES (757495, 201805, 10, 1525, 201805, 10, 1525, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:25:00', 'EST-5', '10-MAY-18 15:25:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NE', 'DAWN', 1, 'NE', 'DAWN', 37.84, -77.36, 37.84, -77.36, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Multiple trees were downed.');
INSERT INTO public.stormevents_east VALUES (757496, 201805, 10, 1525, 201805, 10, 1525, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:25:00', 'EST-5', '10-MAY-18 15:25:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'ESE', 'MANAKIN', 3, 'ESE', 'MANAKIN', 37.58, -77.66, 37.58, -77.66, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed on Pagebrook Drive.');
INSERT INTO public.stormevents_east VALUES (757497, 201805, 10, 1540, 201805, 10, 1540, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:40:00', 'EST-5', '10-MAY-18 15:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'YELLOW TAVERN', 1, 'N', 'YELLOW TAVERN', 37.65, -77.47, 37.65, -77.47, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed on a vehicle.');
INSERT INTO public.stormevents_east VALUES (757498, 201805, 10, 1547, 201805, 10, 1547, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:47:00', 'EST-5', '10-MAY-18 15:47:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'OWENTON', 1, 'W', 'OWENTON', 37.88, -77.1, 37.88, -77.1, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Trees were downed along Newtown Road and along Owens Mill Road.');
INSERT INTO public.stormevents_east VALUES (757499, 201805, 10, 1552, 201805, 10, 1552, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 15:52:00', 'EST-5', '10-MAY-18 15:52:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'N', 'OLD CHURCH', 3, 'N', 'OLD CHURCH', 37.67, -77.21, 37.67, -77.21, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Trees were downed along Highway 360.');
INSERT INTO public.stormevents_east VALUES (768901, 201806, 18, 1649, 201806, 18, 1649, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:49:00', 'EST-5', '18-JUN-18 16:49:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SW', 'SWAN LAKE', 1, 'SW', 'SWAN LAKE', 41.74, -74.8, 41.74, -74.8, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees on Cohen Road.');
INSERT INTO public.stormevents_east VALUES (768902, 201806, 18, 1649, 201806, 18, 1649, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:49:00', 'EST-5', '18-JUN-18 16:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'SWAN LAKE', 0, 'N', 'SWAN LAKE', 41.75, -74.78, 41.75, -74.78, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines.');
INSERT INTO public.stormevents_east VALUES (751918, 201806, 21, 2250, 201806, 22, 230, 125365, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'ILN', '21-JUN-18 22:50:00', 'EST-5', '22-JUN-18 02:30:00', 0, 0, 0, 0, '500.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'HAYDENVILLE', 3, 'W', 'GREENDALE', 39.5049, -82.3441, 39.5283, -82.3374, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general, with locally higher amounts.', 'A water rescue occurred in a subdivision on Hock Hocking Road. One home was reported off its foundation from the flash flooding. Around 100 houses were damaged by flooding around Logan. First responders worked for nearly twelve hours to rescue dozens of people trapped in their homes and cars.');
INSERT INTO public.stormevents_east VALUES (769611, 201806, 24, 1700, 201806, 24, 1700, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 17:00:00', 'EST-5', '24-JUN-18 17:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 1, 'N', 'AMPT HILL', 1, 'N', 'AMPT HILL', 37.46, -77.45, 37.46, -77.45, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Tree was downed and blocking the road at Pate Avenue and Castlewood Road.');
INSERT INTO public.stormevents_east VALUES (769618, 201806, 24, 1705, 201806, 24, 1705, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 17:05:00', 'EST-5', '24-JUN-18 17:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 1, 'SE', 'CHESTER', 1, 'SE', 'CHESTER', 37.34, -77.44, 37.34, -77.44, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Tree was downed and blocking a road at Foreign Creek Place near Harrowgate Road.');
INSERT INTO public.stormevents_east VALUES (769631, 201806, 24, 1720, 201806, 24, 1720, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 17:20:00', 'EST-5', '24-JUN-18 17:20:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'N', 'REAMS', 1, 'N', 'REAMS', 37.11, -77.42, 37.11, -77.42, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Tree was downed along Halifax Road. Power outage was also reported in the area.');
INSERT INTO public.stormevents_east VALUES (769651, 201806, 24, 1740, 201806, 24, 1740, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 17:40:00', 'EST-5', '24-JUN-18 17:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'ESE', 'MC KENNEY', 2, 'ESE', 'MC KENNEY', 36.97, -77.7, 36.97, -77.7, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Numerous trees were downed along Old Hickory Road near Highway 40, just north of the Dinwiddie/Brunswick county line.');
INSERT INTO public.stormevents_east VALUES (769653, 201806, 24, 1805, 201806, 24, 1805, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 18:05:00', 'EST-5', '24-JUN-18 18:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'W', 'MOON', 1, 'W', 'MOON', 37.42, -76.33, 37.42, -76.33, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Power lines were downed along Highway 14, just outside of the town of Mathews.');
INSERT INTO public.stormevents_east VALUES (769656, 201806, 24, 1840, 201806, 24, 1840, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 18:40:00', 'EST-5', '24-JUN-18 18:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 1, 'E', 'SMITHFIELD', 1, 'E', 'SMITHFIELD', 36.98, -76.61, 36.98, -76.61, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'Several trees and power lines were downed at the intersection of South Church Street and Benns Church Boulevard.');
INSERT INTO public.stormevents_east VALUES (769679, 201806, 24, 1935, 201806, 24, 1935, 128289, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 19:35:00', 'EST-5', '24-JUN-18 19:35:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'ESE', 'SIGMA', 2, 'ESE', 'SIGMA', 36.72, -75.94, 36.72, -75.94, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of central and eastern Virginia.', 'A few trees were downed near Sandbridge Beach.');
INSERT INTO public.stormevents_east VALUES (785366, 201809, 1, 1945, 201809, 1, 1945, 131265, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'AKQ', '01-SEP-18 19:45:00', 'EST-5', '01-SEP-18 19:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, NULL, NULL, 1, 'SSW', 'DUMBARTON', 1, 'SSW', 'DUMBARTON', 37.6, -77.51, 37.6, -77.51, 'Scattered thunderstorms associated with a weak frontal boundary produced heavy rain across portions of central Virginia.', 'Vehicle was stuck in high water on Indigo Street near Staples Mill Road exit off of Interstate 64. Rainfall total was estimated at 2.00 inches.');
INSERT INTO public.stormevents_east VALUES (767649, 201806, 10, 1910, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 19:10:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'DRAVOSBURG', 0, 'NE', 'DRAVOSBURG', 40.3524, -79.8982, 40.3514, -79.8978, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'Flooding was reported at Sandy Lake along Marc Arthur Drive.');
INSERT INTO public.stormevents_east VALUES (767652, 201806, 10, 1936, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 19:36:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'LINCOLN', 1, 'NNE', 'LINCOLN', 40.3305, -79.8622, 40.3296, -79.8656, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'A creek was reported to be flooding Glenn Avenue in Port Vue.');
INSERT INTO public.stormevents_east VALUES (768067, 201806, 10, 1602, 201806, 10, 1602, 127985, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '10-JUN-18 16:02:00', 'EST-5', '10-JUN-18 16:02:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'W', 'MILLPORT', 1, 'W', 'MILLPORT', 40.7, -80.89, 40.7, -80.89, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event. Flooding reports were received from Columbiana, Jefferson, and Harrison Counties in Ohio.  Tree damage from severe thunderstorm wind also occurred in Columbiana County.', 'Multiple trees reported down by the Department of Transportation.');
INSERT INTO public.stormevents_east VALUES (767653, 201806, 10, 2012, 201806, 10, 2227, 127920, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PBZ', '10-JUN-18 20:12:00', 'EST-5', '10-JUN-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'MC KEESPORT', 1, 'ESE', 'MC KEESPORT', 40.3306, -79.8175, 40.3272, -79.8198, 'A wavy and nearly stationary frontal boundary was in place near the Mason-Dixon Line.  Morning clouds hindered destabilization somewhat, but afternoon clearing and the arrival of a mesoscale low allowed storms to blossom during the afternoon and evening.  Although a few wind damage reports were received, flash flooding was the main focus of this event.  Hardest hit were Allegheny, Washington, and Westmoreland Counties in Pennsylvania.  Here, numerous reports of roadway flooding were received, along with a few instances of creek overflows and residential basement flooding.', 'The intersection of Long Run Road and Rippel Road was reported to be flooded.');
INSERT INTO public.stormevents_east VALUES (767767, 201806, 18, 1703, 201806, 18, 1707, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:03:00', 'EST-5', '18-JUN-18 17:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SE', 'BOSCAWEN', 1, 'SE', 'BOSCAWEN', 43.31, -71.62, 43.31, -71.62, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires in Boscawen.');
INSERT INTO public.stormevents_east VALUES (767769, 201806, 18, 1710, 201806, 18, 1715, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:10:00', 'EST-5', '18-JUN-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'ALLENSTOWN', 1, 'SW', 'ALLENSTOWN', 43.16, -71.41, 43.16, -71.41, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires in Allenstown.');
INSERT INTO public.stormevents_east VALUES (767770, 201806, 18, 1712, 201806, 18, 1717, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:12:00', 'EST-5', '18-JUN-18 17:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'N', 'LOUDON', 1, 'N', 'LOUDON', 43.29, -71.47, 43.29, -71.47, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires in Loudon.');
INSERT INTO public.stormevents_east VALUES (767773, 201806, 18, 1725, 201806, 18, 1730, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:25:00', 'EST-5', '18-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'N', 'WESTVILLE', 1, 'N', 'WESTVILLE', 42.84, -71.1, 42.84, -71.1, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed a large tree in Westville.');
INSERT INTO public.stormevents_east VALUES (769470, 201806, 18, 1432, 201806, 18, 1433, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Tornado', 'GYX', '18-JUN-18 14:32:00', 'EST-5', '18-JUN-18 14:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 3, 'NW', 'LINCOLN', 3, 'NW', 'LINCOLN', 44.08, -71.72, 44.08, -71.72, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A hiker on Mt. Pemigewasset filmed a small tornado that touched down briefly in a remote wooded area about 3 miles northwest of the Town of Lincoln in Grafton County.  The video showed the small tornado in contact with the ground on the side of a nearby wooded hillside. Rapid rotation was noted in the cloud base.');
INSERT INTO public.stormevents_east VALUES (770000, 201806, 2, 1750, 201806, 2, 1751, 126045, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '02-JUN-18 17:50:00', 'EST-5', '02-JUN-18 17:51:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 1, 'S', 'ISLE OF PALMS', 1, 'S', 'ISLE OF PALMS', 32.78, -79.79, 32.78, -79.79, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across the coastal waters.', 'The Isle Of Palms Weatherflow sensor recorded a wind gust of 38 knots.');
INSERT INTO public.stormevents_east VALUES (770008, 201806, 2, 1756, 201806, 2, 1757, 126045, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '02-JUN-18 17:56:00', 'EST-5', '02-JUN-18 17:57:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'FORT SUMTER', 0, 'N', 'FORT SUMTER', 32.75, -79.87, 32.75, -79.87, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across the coastal waters.', 'The Fort Sumter Weatherflow sensor recorded a wind gust of 36 knots.');
INSERT INTO public.stormevents_east VALUES (770275, 201806, 2, 1802, 201806, 2, 1803, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'CHS', '02-JUN-18 18:02:00', 'EST-5', '02-JUN-18 18:03:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 2, 'SW', 'OAKLEY', 2, 'SW', 'OAKLEY', 33.1, -80.04, 33.1, -80.04, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'A trained spotter reported penny size hail.');
INSERT INTO public.stormevents_east VALUES (770284, 201806, 2, 1602, 201806, 2, 1603, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 16:02:00', 'EST-5', '02-JUN-18 16:03:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'SWITZERLAND', 1, 'W', 'SWITZERLAND', 32.43, -81.01, 32.43, -81.01, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Jasper County 911 Call Center reported a tree down on I-95 southbound near mile marker 15.');
INSERT INTO public.stormevents_east VALUES (770286, 201806, 2, 1627, 201806, 2, 1628, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 16:27:00', 'EST-5', '02-JUN-18 16:28:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SSW', 'GRAHAMVILLE', 2, 'SSW', 'GRAHAMVILLE', 32.45, -80.98, 32.45, -80.98, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The South Carolina Highway Patrol reported a tree down on Bees Creek Road near Scarlett Ibis Drive.');
INSERT INTO public.stormevents_east VALUES (770287, 201806, 2, 1645, 201806, 2, 1646, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 16:45:00', 'EST-5', '02-JUN-18 16:46:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 5, 'E', 'CANADYS', 5, 'E', 'CANADYS', 33.06, -80.53, 33.06, -80.53, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Colleton County 911 Call Center reported two trees down along with power lines and hail of unknown size along Sidney''s Road.');
INSERT INTO public.stormevents_east VALUES (770305, 201806, 2, 1722, 201806, 2, 1723, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 17:22:00', 'EST-5', '02-JUN-18 17:23:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'WNW', 'WALTERBORO', 1, 'WNW', 'WALTERBORO', 32.91, -80.67, 32.91, -80.67, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Colleton County 911 Call Center reported trees and a power pole down near the intersection of north Jefferies Boulevard and Ivanhoe Road.');
INSERT INTO public.stormevents_east VALUES (770331, 201806, 2, 1741, 201806, 2, 1742, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 17:41:00', 'EST-5', '02-JUN-18 17:42:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'S', 'ASHLEY HALL', 1, 'S', 'ASHLEY HALL', 32.81, -80.02, 32.81, -80.02, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The media reported one tree down on Brockington Avenue and two power lines down on Ashley River Road.');
INSERT INTO public.stormevents_east VALUES (770851, 201806, 27, 2245, 201806, 28, 345, 128450, 'WEST VIRGINIA', 54, 2018, 'June', 'Flash Flood', 'PBZ', '27-JUN-18 22:45:00', 'EST-5', '28-JUN-18 03:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 7, 'WNW', 'ST GEORGE', 6, 'W', 'ST GEORGE', 39.19, -79.82, 39.1859, -79.8178, 'In the wake of morning rain, cloud breaks developed from Virginia into south central Pennsylvania during the afternoon.  CAPE values climbed to near 1000 J/kg, despite poor mid-level lapse rates.  Disturbances rotating around the southeastern periphery of a Great Lakes/upper Ohio Valley trough helped to increase low level flow and shear.  This proved sufficient to allow afternoon storms to rotate.||One storm produced a weak EF0 tornado in Monongalia county off Kingwood Road.  There were several trees uprooted and snapped. Five homes lost parts of their roof.||Multiple rounds of thunderstorms also produced flash flooding in Tucker County during the evening hours, mainly in the vicinity of Route 38 to the northwest of Parsons.', 'County officials reported that several people, waiting for rescue, climbed onto the roofs of their houses due to flood water.');
INSERT INTO public.stormevents_east VALUES (767785, 201806, 18, 1540, 201806, 18, 1544, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 15:40:00', 'EST-5', '18-JUN-18 15:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'WEST BALDWIN', 0, 'N', 'WEST BALDWIN', 43.83, -70.78, 43.83, -70.78, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed large limbs in West Baldwin.');
INSERT INTO public.stormevents_east VALUES (767786, 201806, 18, 1533, 201806, 18, 1537, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 15:33:00', 'EST-5', '18-JUN-18 15:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'ENE', 'PORTERFIELD', 2, 'ENE', 'PORTERFIELD', 43.88, -70.88, 43.88, -70.88, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed  a tree on Notch Road in Hiram.');
INSERT INTO public.stormevents_east VALUES (767787, 201806, 18, 1633, 201806, 18, 1638, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 16:33:00', 'EST-5', '18-JUN-18 16:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'E', 'LIMINGTON', 1, 'E', 'LIMINGTON', 43.73, -70.71, 43.73, -70.71, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed trees on North Road in Limington.');
INSERT INTO public.stormevents_east VALUES (767791, 201806, 18, 1700, 201806, 18, 1704, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:00:00', 'EST-5', '18-JUN-18 17:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'E', 'BUXTON', 1, 'E', 'BUXTON', 43.6323, -70.5017, 43.6323, -70.5017, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm downed trees on Route 202 in Buxton.');
INSERT INTO public.stormevents_east VALUES (760977, 201805, 18, 700, 201805, 18, 730, 126923, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'AKQ', '18-MAY-18 07:00:00', 'EST-5', '18-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'DUMBARTON', 0, 'ESE', 'MONUMENT HGTS', 37.5911, -77.5, 37.5788, -77.4971, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused flash flooding across portions of central and south central Virginia.', 'Right and center lanes were closed on Interstate 195 North near Broad Street due to standing water.');
INSERT INTO public.stormevents_east VALUES (797077, 201811, 12, 1902, 201811, 12, 2200, 132871, 'GEORGIA', 13, 2018, 'November', 'Flash Flood', 'FFC', '12-NOV-18 19:02:00', 'EST-5', '12-NOV-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'HOLLINGSWORTH', 1, 'SSE', 'HOLLINGSWORTH', 34.43, -83.5052, 34.4166, -83.4942, 'A series of weak surface low systems traversed the area, producing periods of heavy rain over north Georgia late on November 11th through November 12th. Rainfall amounts of 2 to 5 inches occurred, combining with the already saturated soils to produce isolated flash flooding in portions of the north Atlanta metropolitan area.', 'Emergency Manager reported Moss Mill Road near Highway 441 and Old Highway 441 was inundated with water due to Little Nails Creek overflowing its banks. Radar estimates indicate that 2.5 to 3 inches of rainfall occurred over the area.');
INSERT INTO public.stormevents_east VALUES (791255, 201811, 2, 2109, 201811, 2, 2109, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:09:00', 'EST-5', '02-NOV-18 21:09:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'GREENBERRY POINT (GBY)', 0, 'N', 'GREENBERRY POINT (GBY)', 38.97, -76.46, 38.97, -76.46, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Greenbury Point.');
INSERT INTO public.stormevents_east VALUES (791256, 201811, 2, 2136, 201811, 2, 2136, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:36:00', 'EST-5', '02-NOV-18 21:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 41 knots was measured at Tolly Point.');
INSERT INTO public.stormevents_east VALUES (791257, 201811, 2, 2146, 201811, 2, 2151, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:46:00', 'EST-5', '02-NOV-18 21:51:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 42, 'MG', NULL, NULL, 0, 'N', 'HERRING BAY (HRB)', 0, 'N', 'HERRING BAY (HRB)', 38.73, -76.54, 38.73, -76.54, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 42 knots was measured at Herring Bay.');
INSERT INTO public.stormevents_east VALUES (791258, 201811, 2, 2212, 201811, 2, 2212, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 22:12:00', 'EST-5', '02-NOV-18 22:12:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'MID BAY BUOY', 0, 'N', 'MID BAY BUOY', 38.47, -76.38, 38.47, -76.38, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Cove Point.');
INSERT INTO public.stormevents_east VALUES (750549, 201804, 15, 1931, 201804, 15, 1931, 125150, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 19:31:00', 'EST-5', '15-APR-18 19:31:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 44, 'MG', NULL, NULL, 2, 'SSE', 'JUPITER INLET', 2, 'SSE', 'JUPITER INLET', 26.91, -80.07, 26.91, -80.07, 'A band of strong showers and storms moved eastward across South Florida during the evening hours of April 15. These storms produced several strong wind gusts across Lake Okeechobee before moving out into the local Atlantic waters, producing additional strong gusts as they moved offshore.', 'WxFlow mesonet site XOAK near Jupiter reported a 35 kt / 40 mph wind gust.');
INSERT INTO public.stormevents_east VALUES (750552, 201804, 15, 2012, 201804, 15, 2012, 125150, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 20:12:00', 'EST-5', '15-APR-18 20:12:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 3, 'SW', 'GOVERNMENT CUT', 3, 'SW', 'GOVERNMENT CUT', 25.73, -80.16, 25.73, -80.16, 'A band of strong showers and storms moved eastward across South Florida during the evening hours of April 15. These storms produced several strong wind gusts across Lake Okeechobee before moving out into the local Atlantic waters, producing additional strong gusts as they moved offshore.', 'NOAA/NOS station at Virginia Key reported a 43 mph / 37 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (750553, 201804, 15, 2012, 201804, 15, 2012, 125150, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 20:12:00', 'EST-5', '15-APR-18 20:12:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 1, 'ESE', 'GOVERNMENT CUT', 1, 'ESE', 'GOVERNMENT CUT', 25.76, -80.11, 25.76, -80.11, 'A band of strong showers and storms moved eastward across South Florida during the evening hours of April 15. These storms produced several strong wind gusts across Lake Okeechobee before moving out into the local Atlantic waters, producing additional strong gusts as they moved offshore.', 'A 37 kt / 43 mph wind gust was recorded by the WxFlow mesonet site XGVT at Government Cut. This site is elevated at 63 feet.');
INSERT INTO public.stormevents_east VALUES (750550, 201804, 15, 2008, 201804, 15, 2008, 125150, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 20:08:00', 'EST-5', '15-APR-18 20:08:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 44, 'MG', NULL, NULL, 11, 'NE', 'ELLIOT KEY', 11, 'NE', 'ELLIOT KEY', 25.58, -80.1, 25.58, -80.1, 'A band of strong showers and storms moved eastward across South Florida during the evening hours of April 15. These storms produced several strong wind gusts across Lake Okeechobee before moving out into the local Atlantic waters, producing additional strong gusts as they moved offshore.', 'C-MAN station at Fowey Rocks (FWYF1) reported a 44 kt / 51 mph wind gust at a height of 144 feet.');
INSERT INTO public.stormevents_east VALUES (750554, 201804, 15, 2029, 201804, 15, 2029, 125150, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '15-APR-18 20:29:00', 'EST-5', '15-APR-18 20:29:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 3, 'N', 'BOCA RATON', 3, 'N', 'BOCA RATON', 26.3714, -80.0853, 26.3714, -80.0853, 'A band of strong showers and storms moved eastward across South Florida during the evening hours of April 15. These storms produced several strong wind gusts across Lake Okeechobee before moving out into the local Atlantic waters, producing additional strong gusts as they moved offshore.', 'WxFlow mesonet site XBOC in Boca Raton reported a 34 knot / 39 mph wind gust.');
INSERT INTO public.stormevents_east VALUES (750556, 201804, 22, 550, 201804, 22, 550, 125151, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Waterspout', 'MFL', '22-APR-18 05:50:00', 'EST-5', '22-APR-18 05:50:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 4, 'E', 'PORT EVERGLADES', 4, 'E', 'PORT EVERGLADES', 26.09, -80.07, 26.09, -80.07, 'A stalled frontal boundary near Lake Okeechobee aided the development of morning showers and storms over the local Atlantic waters. Two waterspouts were reported offshore Broward County with this activity.', 'Trained spotter near Fort Lauderdale International Airport reported two funnel clouds several miles offshore.');
INSERT INTO public.stormevents_east VALUES (785383, 201809, 1, 2011, 201809, 1, 2011, 131269, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '01-SEP-18 20:11:00', 'EST-5', '01-SEP-18 20:11:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 40, 'EG', NULL, NULL, 1, 'SSW', 'BOOGERTOWN', 1, 'SSW', 'BOOGERTOWN', 35.2, -81.18, 35.2, -81.18, 'Isolated thunderstorms developed over the North Carolina Piedmont and foothills during the evening. A couple of the storms produced brief severe weather.', 'Ham radio operator reported a tree blown down on a house at Forbes Rd. and Little Mountain Rd.');
INSERT INTO public.stormevents_east VALUES (785385, 201809, 1, 2023, 201809, 1, 2023, 131269, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '01-SEP-18 20:23:00', 'EST-5', '01-SEP-18 20:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'W', 'GLEN ALPINE', 2, 'W', 'GLEN ALPINE', 35.73, -81.83, 35.73, -81.83, 'Isolated thunderstorms developed over the North Carolina Piedmont and foothills during the evening. A couple of the storms produced brief severe weather.', 'Media reported multiple trees blown down on Powerhouse Rd.');
INSERT INTO public.stormevents_east VALUES (744089, 201804, 23, 1734, 201804, 23, 1739, 123974, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'FFC', '23-APR-18 17:34:00', 'EST-5', '23-APR-18 17:39:00', 0, 0, 0, 0, '5.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 4, 'N', 'SPRING HILL', 4, 'N', 'SPRING HILL', 32.0677, -82.7295, 32.0677, -82.7295, 'A strong cold front associated with a deep upper-level low swept across the region. Moderate instability and strong mid-level winds combined to produce scattered severe thunderstorms across portions of central and east Georgia.', 'The Wheeler County Emergency Manager reported several trees blown down around the intersection of Scotland Road and Springhill Road.');
INSERT INTO public.stormevents_east VALUES (750500, 201804, 10, 1535, 201804, 10, 1537, 125146, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Waterspout', 'MFL', '10-APR-18 15:35:00', 'EST-5', '10-APR-18 15:37:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 3, 'ESE', 'PORT EVERGLADES', 3, 'ESE', 'PORT EVERGLADES', 26.09, -80.09, 26.09, -80.09, 'Increasing moist south-southwesterly flow ahead of an approaching cold front lead to scattered shower and storm development along the east coast of South Florida during the afternoon hours. Interaction with the east coast seabreeze brought several strong to severe storms, initially producing strong wind gusts over Lake Okeechobee, then moving offshore into the local Atlantic waters were a brief waterspout was also reported.', 'Multiple reports of several waterspouts that occurred offshore Fort Lauderdale Beach and Port Everglades. Many videos and photos relayed via social media and local broadcast media outlets.');
INSERT INTO public.stormevents_east VALUES (764848, 201806, 3, 1600, 201806, 3, 1800, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:00:00', 'EST-5', '03-JUN-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'REMINGTON', 0, 'NNW', 'REMINGTON', 38.5283, -77.8073, 38.5364, -77.8032, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Flooding along Tin Pot Run caused multiple road closures near Remington.');
INSERT INTO public.stormevents_east VALUES (764879, 201806, 21, 1538, 201806, 21, 1730, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '21-JUN-18 15:38:00', 'EST-5', '21-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'SNYDER', 1, 'NNW', 'SNYDER', 38.169, -79.1373, 38.1685, -79.1358, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Morris Mill Road closed in the 3000 block due to flooding.');
INSERT INTO public.stormevents_east VALUES (760057, 201807, 23, 330, 201807, 23, 330, 126794, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TBW', '23-JUL-18 03:30:00', 'EST-5', '23-JUL-18 03:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'W', 'NOWATNEY', 1, 'W', 'NOWATNEY', 28.08, -82.46, 28.08, -82.46, 'A strong outflow boundary moved south from the Florida Panhandle through the eastern Gulf of Mexico and onshore during the overnight and early morning hours of the 23rd. Numerous thunderstorms developed along the outflow, producing damaging wind gusts across west central Florida.', 'Power lines were reported down on Palm Drive.');
INSERT INTO public.stormevents_east VALUES (760074, 201807, 24, 2035, 201807, 24, 2035, 126796, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'TBW', '24-JUL-18 20:35:00', 'EST-5', '24-JUL-18 20:35:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'NE', 'INDIAN ROCKS BEACH', 1, 'NE', 'INDIAN ROCKS BEACH', 27.907, -82.84, 27.907, -82.84, 'Scattered thunderstorms moved onshore from the eastern Gulf of Mexico. A lightning strike from one of these storms damaged a home in Indian Rocks Beach.', 'A lightning strike was reported to a home in the Indian Rocks Beach area, damaging a DVD player and leaving a mark on the floor. The fire department did not find any additional damage or fires.');
INSERT INTO public.stormevents_east VALUES (756116, 201807, 4, 1946, 201807, 4, 1946, 126131, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'JKL', '04-JUL-18 19:46:00', 'EST-5', '04-JUL-18 19:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'NNE', '(JKL)CARROLL ARPT JA', 1, 'NNE', '(JKL)CARROLL ARPT JA', 37.588, -83.3162, 37.588, -83.3162, 'A cluster of strong to severe thunderstorms moved west/southwest from West Virginia into portions of northeast and east Kentucky this evening. Due to the high amount of moisture and subsequent instability in place, the downdraft portion of one of these storms produced winds of up to 85 mph as it collapsed over Paintsville. This resulted in substantial damage in Paintsville, including half of a roof being removed from an office building along with the steeple of a church being blown off. A couple of residential buildings were also damaged from falling trees.', 'NWS Employees observed a large tree blown down on Kentucky Highway 2436 near the Jackson NWS office.');
INSERT INTO public.stormevents_east VALUES (765073, 201807, 10, 1500, 201807, 10, 1500, 127600, 'VERMONT', 50, 2018, 'July', 'Thunderstorm Wind', 'BTV', '10-JUL-18 15:00:00', 'EST-5', '10-JUL-18 15:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'CASTLETON', 0, 'N', 'CASTLETON', 43.62, -73.18, 43.62, -73.18, 'A weak cold front moved across a moderately unstable air mass across southern Vermont that produced scattered thunderstorms during the afternoon of July 10th. One isolated supercell developed and moved across Rutland county, producing wind damage in severe thunderstorm in Castleton and Wallingfordwith numerous tree damage.', 'Power lines and numerous tree limbs down across Castleton due to thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (765254, 201807, 31, 1325, 201807, 31, 1325, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 13:25:00', 'EST-5', '31-JUL-18 13:25:00', 0, 0, 0, 0, '35.00K', '0.00K', 'State Official', 56, 'EG', NULL, NULL, 1, 'NE', 'HURRICANE', 1, 'NE', 'HURRICANE', 38.44, -82.02, 38.44, -82.02, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'Numerous trees and power lines were blown down in Hurricane. One tree fell on a house along Renard Run and another tree fell on a truck.');
INSERT INTO public.stormevents_east VALUES (765255, 201807, 31, 1450, 201807, 31, 1450, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 14:50:00', 'EST-5', '31-JUL-18 14:50:00', 0, 0, 0, 0, '6.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'SYCAMORE', 1, 'NW', 'SYCAMORE', 38.84, -81.11, 38.84, -81.11, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'Numerous trees along with power lines were blown down in the Mt. Zion area.');
INSERT INTO public.stormevents_east VALUES (765258, 201807, 31, 1500, 201807, 31, 1500, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 15:00:00', 'EST-5', '31-JUL-18 15:00:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'W', 'ELMIRA', 1, 'W', 'ELMIRA', 38.6499, -80.9904, 38.6499, -80.9904, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'A tree fell across Servia Road in Elmira.');
INSERT INTO public.stormevents_east VALUES (765260, 201807, 31, 1510, 201807, 31, 1510, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 15:10:00', 'EST-5', '31-JUL-18 15:10:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 2, 'SW', 'LEGG', 2, 'SW', 'LEGG', 38.46, -81.63, 38.46, -81.63, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'A tree fell down at the intersection of Newquay Drive and Walker Drive blocking one lane of traffic.');
INSERT INTO public.stormevents_east VALUES (765269, 201807, 31, 1314, 201807, 31, 1314, 127617, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '31-JUL-18 13:14:00', 'EST-5', '31-JUL-18 13:14:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Broadcast Media', 70, 'EG', NULL, NULL, 1, 'WSW', 'CULLODEN', 1, 'WSW', 'CULLODEN', 38.4168, -82.0671, 38.4168, -82.0671, 'An area of low pressure moved out of the Mississippi Valley on the 31st crossing through West Virginia that afternoon with strong to severe thunderstorms.', 'Thunderstorm winds removed parts of the roof and siding of Fairview Primitive Baptist Church in Culloden. Following the wind damage, heavy rain leaked into the building causing water damage. There were also many trees and power lines down in the area.');
INSERT INTO public.stormevents_east VALUES (762146, 201807, 3, 1725, 201807, 3, 1725, 127178, 'GULF OF MEXICO', 85, 2018, 'July', 'Waterspout', 'TAE', '03-JUL-18 17:25:00', 'EST-5', '03-JUL-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 4, 'SSW', 'KEATON BEACH', 4, 'SSW', 'KEATON BEACH', 29.7699, -83.6044, 29.7699, -83.6044, 'Several strong to severe storms developed across the coastal waters in the July 2-5 time period with wind gusts in excess of 34 knots and waterspouts.', 'A picture of a waterspout offshore of Hagen''s Cove was posted to social media.');
INSERT INTO public.stormevents_east VALUES (762147, 201807, 3, 1754, 201807, 3, 1754, 127178, 'GULF OF MEXICO', 85, 2018, 'July', 'Waterspout', 'TAE', '03-JUL-18 17:54:00', 'EST-5', '03-JUL-18 17:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 6, 'WSW', 'ADAMS BEACH', 6, 'WSW', 'ADAMS BEACH', 29.8468, -83.7225, 29.8468, -83.7225, 'Several strong to severe storms developed across the coastal waters in the July 2-5 time period with wind gusts in excess of 34 knots and waterspouts.', 'The Perry airport control tower tweeted a picture of a waterspout off of the Taylor county coast.');
INSERT INTO public.stormevents_east VALUES (767670, 201807, 21, 1305, 201807, 21, 1305, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 13:05:00', 'EST-5', '21-JUL-18 13:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'LEE', 0, 'N', 'LEE', 30.41, -83.3, 30.41, -83.3, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees were blown down in Lee.');
INSERT INTO public.stormevents_east VALUES (767671, 201807, 21, 1320, 201807, 21, 1320, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 13:20:00', 'EST-5', '21-JUL-18 13:20:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 2, 'SE', 'SECOTAN', 2, 'SE', 'SECOTAN', 30.15, -83.61, 30.15, -83.61, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Fallen trees and limbs resulted in a power outage on McDaniel Road.');
