INSERT INTO public.stormevents_east VALUES (768384, 201806, 25, 1908, 201806, 25, 1908, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 19:08:00', 'EST-5', '25-JUN-18 19:08:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'TROY', 1, 'S', 'TROY', 35.3521, -79.9004, 35.3521, -79.9004, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down on Reynolds Street, near Hickory Street.');
