INSERT INTO public.stormevents_east VALUES (768392, 201806, 25, 1930, 201806, 25, 1930, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 19:30:00', 'EST-5', '25-JUN-18 19:30:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'LEAMAN', 1, 'W', 'LEAMAN', 35.5, -79.5924, 35.5, -79.5924, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down on power lines along Odell Road.');
INSERT INTO public.stormevents_east VALUES (767997, 201806, 3, 1732, 201806, 3, 1732, 128054, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '03-JUN-18 17:32:00', 'EST-5', '03-JUN-18 17:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 4, 'W', 'ENOLA', 4, 'W', 'ENOLA', 35.672, -81.724, 35.672, -81.724, 'Scattered thunderstorms developed across the southern Appalachians throughout the afternoon and moved southeast. Several storms produced brief severe weather in the form of large hail and damaging winds across the North Carolina mountains and foothills.', 'Media reported trees blown down on Jenkins Rd.');
INSERT INTO public.stormevents_east VALUES (768044, 201806, 10, 2118, 201806, 10, 2118, 128064, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '10-JUN-18 21:18:00', 'EST-5', '10-JUN-18 21:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 0, 'N', 'ONANCOCK', 0, 'N', 'ONANCOCK', 37.65, -75.9, 37.65, -75.9, 'Scattered thunderstorms along a frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 41 knots was measured at Onancock.');
INSERT INTO public.stormevents_east VALUES (768066, 201806, 19, 1634, 201806, 19, 1634, 128069, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '19-JUN-18 16:34:00', 'EST-5', '19-JUN-18 16:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 0, 'N', 'DELTAVILLE', 0, 'N', 'DELTAVILLE', 37.56, -76.29, 37.56, -76.29, 'Scattered thunderstorms in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 40 knots was measured at Deltaville.');
INSERT INTO public.stormevents_east VALUES (749870, 201804, 15, 2145, 201804, 15, 2145, 125027, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'AKQ', '15-APR-18 21:45:00', 'EST-5', '15-APR-18 21:45:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'AMELIA', 1, 'N', 'AMELIA', 37.34, -77.98, 37.34, -77.98, 'Scattered severe thunderstorms in advance of low pressure and its associated cold front produced damaging winds across portions of central and eastern Virginia.', 'Large tree was downed.');
INSERT INTO public.stormevents_east VALUES (757500, 201805, 10, 1635, 201805, 10, 1635, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 16:35:00', 'EST-5', '10-MAY-18 16:35:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SW', 'JEFFRESS', 2, 'SW', 'JEFFRESS', 36.63, -78.55, 36.63, -78.55, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Multiple trees were downed.');
INSERT INTO public.stormevents_east VALUES (757501, 201805, 10, 1705, 201805, 10, 1705, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 17:05:00', 'EST-5', '10-MAY-18 17:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'N', 'CARSON', 1, 'N', 'CARSON', 37.04, -77.4, 37.04, -77.4, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Power lines and power poles were downed on Haligan Park Road in Carson.');
INSERT INTO public.stormevents_east VALUES (757502, 201805, 10, 1705, 201805, 10, 1705, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 17:05:00', 'EST-5', '10-MAY-18 17:05:00', 0, 0, 0, 0, '5.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 2, 'SSE', 'REAMS', 2, 'SSE', 'REAMS', 37.07, -77.41, 37.07, -77.41, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Two trees were downed. One tree was downed on a house.');
INSERT INTO public.stormevents_east VALUES (757503, 201805, 10, 1725, 201805, 10, 1725, 126346, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '10-MAY-18 17:25:00', 'EST-5', '10-MAY-18 17:25:00', 0, 0, 0, 0, '3.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'W', 'WAKEFIELD', 1, 'W', 'WAKEFIELD', 36.97, -76.99, 36.97, -76.99, 'Scattered severe thunderstorms well in advance of a cold front produced damaging winds and large hail across portions of central and south central Virginia.', 'Tree was downed with a vehicle accident in Wakefield. Also, tin roofing was torn off an outbuilding.');
INSERT INTO public.stormevents_east VALUES (753446, 201804, 16, 115, 201804, 16, 115, 125033, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 01:15:00', 'EST-5', '16-APR-18 01:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 0, 'N', 'THIMBLE SHOALS', 0, 'N', 'THIMBLE SHOALS', 37.05, -76.26, 37.05, -76.26, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 38 knots was measured at Thimble Shoals.');
INSERT INTO public.stormevents_east VALUES (753449, 201804, 16, 132, 201804, 16, 132, 125033, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 01:32:00', 'EST-5', '16-APR-18 01:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 5, 'NW', 'THIMBLE SHOALS', 5, 'NW', 'THIMBLE SHOALS', 37.11, -76.32, 37.11, -76.32, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 39 knots was measured at Poquoson.');
INSERT INTO public.stormevents_east VALUES (768903, 201806, 18, 1649, 201806, 18, 1649, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:49:00', 'EST-5', '18-JUN-18 16:49:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'LOOMIS', 1, 'SE', 'LOOMIS', 41.79, -74.78, 41.79, -74.78, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines on Cherry Lane.');
INSERT INTO public.stormevents_east VALUES (768906, 201806, 18, 1654, 201806, 18, 1654, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:54:00', 'EST-5', '18-JUN-18 16:54:00', 0, 0, 0, 0, '20.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NNW', 'HASBROUCK', 1, 'NNW', 'HASBROUCK', 41.8, -74.63, 41.8, -74.63, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees on several roadways.');
INSERT INTO public.stormevents_east VALUES (768907, 201806, 18, 1834, 201806, 18, 1834, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 18:34:00', 'EST-5', '18-JUN-18 18:34:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'WATKINS GLEN', 0, 'N', 'WATKINS GLEN', 42.38, -76.87, 42.38, -76.87, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines on County Route 28.');
INSERT INTO public.stormevents_east VALUES (768908, 201806, 18, 1910, 201806, 18, 1910, 128201, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 19:10:00', 'EST-5', '18-JUN-18 19:10:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'CATATONK', 2, 'NE', 'CATATONK', 42.17, -76.3, 42.17, -76.3, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms as it moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines partially blocking Dominic Road.');
INSERT INTO public.stormevents_east VALUES (768911, 201806, 18, 1440, 201806, 18, 1440, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 14:40:00', 'EST-5', '18-JUN-18 14:40:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'ULSTER', 0, 'N', 'ULSTER', 41.85, -76.5, 41.85, -76.5, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees.');
INSERT INTO public.stormevents_east VALUES (769304, 201806, 25, 1522, 201806, 25, 1553, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:22:00', 'EST-5', '25-JUN-18 15:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 3, 'N', 'PLEASANT GARDENS', 5, 'S', 'FERO', 35.717, -82.073, 35.551, -81.965, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Media reported trees blown down at lake Tahoma Rd and Toms Creek Rd, on Sugar Hill rd, on Ashworth Rd, and on Luck Strike Rd.');
INSERT INTO public.stormevents_east VALUES (785368, 201809, 9, 755, 201809, 9, 1015, 131266, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'AKQ', '09-SEP-18 07:55:00', 'EST-5', '09-SEP-18 10:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 3, 'WNW', 'HAMPTON', 3, 'NW', 'HAMPTON', 37.04, -76.39, 37.041, -76.3869, 'Scattered showers and thunderstorms along a stationary boundary produced heavy rain which caused flooding across portions of southeast Virginia.', 'Road was closed due to flooding at Coliseum Drive and Merchant Lane. Radar estimates indicated that two to four inches of rain had fallen in the area.');
INSERT INTO public.stormevents_east VALUES (785384, 201809, 10, 115, 201809, 10, 1915, 131270, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'AKQ', '10-SEP-18 01:15:00', 'EST-5', '10-SEP-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'BELLE HAVEN', 2, 'E', 'NASSAWADOX', 37.54, -75.82, 37.474, -75.8401, 'Scattered showers and thunderstorms along a stationary boundary produced heavy rain which caused lingering flooding across portions of the Virginia Eastern Shore.', 'Several roads were closed in and around the town of Exmore due to high water, including a section of Route 13 which runs through town.');
INSERT INTO public.stormevents_east VALUES (785389, 201809, 9, 2200, 201809, 10, 45, 131271, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'AKQ', '09-SEP-18 22:00:00', 'EST-5', '10-SEP-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'REHOBOTH CHURCH', 2, 'ENE', 'REHOBOTH CHURCH', 37.7532, -76.4126, 37.7608, -76.3392, 'Scattered showers and thunderstorms along a stationary boundary produced heavy rain which caused flash flooding across portions of the Virginia Northern Neck.', 'Several roads were flooded over portions of eastern Lancaster county, especially around the town of Kilmarnock. Radar estimates indicated that up to three inches of rain had fallen in the area.');
INSERT INTO public.stormevents_east VALUES (785922, 201809, 11, 1935, 201809, 11, 2200, 131350, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'AKQ', '11-SEP-18 19:35:00', 'EST-5', '11-SEP-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSE', 'STUDLEY', 2, 'SSW', 'STUDLEY', 37.63, -77.28, 37.6357, -77.3099, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Several roads were flooded throughout the Mechanicsville area.');
INSERT INTO public.stormevents_east VALUES (785926, 201809, 11, 1954, 201809, 11, 2200, 131350, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'AKQ', '11-SEP-18 19:54:00', 'EST-5', '11-SEP-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'YELLOW TAVERN', 2, 'N', 'YELLOW TAVERN', 37.64, -77.47, 37.6529, -77.4721, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Several roads were flooded south of Glen Allen.');
INSERT INTO public.stormevents_east VALUES (785945, 201809, 9, 915, 201809, 9, 915, 131353, 'ATLANTIC NORTH', 88, 2018, 'September', 'Waterspout', 'AKQ', '09-SEP-18 09:15:00', 'EST-5', '09-SEP-18 09:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 5, 'NW', '(KORF)NORFOLK INTERNATIONAL AIRPORT', 5, 'NW', '(KORF)NORFOLK INTERNATIONAL AIRPORT', 36.96, -76.26, 36.96, -76.26, 'Scattered showers along a frontal boundary produced a waterspout across portions of the Chesapeake Bay.', 'Waterspout caused some damage near Willoughby Spit.');
INSERT INTO public.stormevents_east VALUES (785958, 201809, 9, 1030, 201809, 9, 1030, 131355, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'AKQ', '09-SEP-18 10:30:00', 'EST-5', '09-SEP-18 10:30:00', 1, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ESE', 'OCEAN VIEW', 1, 'ESE', 'OCEAN VIEW', 36.94, -76.23, 36.94, -76.23, 'Isolated severe thunderstorm along a frontal boundary produced damaging winds across portions of southeast Virginia.', 'Several trees were downed at the Ocean View Golf Course. One minor injury to a golfer was reported.');
INSERT INTO public.stormevents_east VALUES (785977, 201809, 14, 1710, 201809, 14, 1710, 131360, 'VIRGINIA', 51, 2018, 'September', 'Funnel Cloud', 'AKQ', '14-SEP-18 17:10:00', 'EST-5', '14-SEP-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 2, 'S', 'COCHRAN', 2, 'S', 'COCHRAN', 36.8, -77.9, 36.8, -77.9, 'Isolated thunderstorm near a stationary boundary produced a funnel cloud across portions of south central Virginia.', 'Funnel cloud was sighted near the intersection of Christanna Highway and Woodley Lane.');
INSERT INTO public.stormevents_east VALUES (769548, 201806, 18, 1403, 201806, 18, 1415, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Tornado', 'GYX', '18-JUN-18 14:03:00', 'EST-5', '18-JUN-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SW', 'BATH', 4, 'ESE', 'BENTON', 44.15, -72, 44.1, -71.83, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'An EF-0 tornado touched down near Bath in Grafton County and continued east-southeast for about 9.5 miles.  The tornado downed trees along the Ammonoosuc River near the Bath/Haverhill line.  The path of snapped, uprooted, and other downed trees continued to the east southeast, crossing Goose Lane Road and then paralleling State Route 112. The tornado passed very close to the Swiftwater Covered Bridge before continuing east southeast.  Tree damage was also noted northeast of the intersection of State Routes 112 and 116 in the Town of Easton, NH||Given the lack of structural damage and the nature of the tree damage, a rating of EF0 was assigned to this tornado.');
INSERT INTO public.stormevents_east VALUES (761022, 201805, 18, 730, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 07:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BOWLING GREEN', 2, 'NE', 'PENOLA', 38.05, -77.35, 37.9658, -77.3431, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (770336, 201806, 2, 1741, 201806, 2, 1742, 126046, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '02-JUN-18 17:41:00', 'EST-5', '02-JUN-18 17:42:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNW', 'ASHLEY JCT', 2, 'NNW', 'ASHLEY JCT', 32.9, -79.99, 32.9, -79.99, 'A warm and moist airmass in combination with a passing low pressure trough and embedded mid-level shortwave created and environment favorable for strong to severe thunderstorms across Southeast Georgia.', 'The Charleston County 911 Call Center reported traffic lights blown down on North Rhett Avenue near the Mark Clark Expressway.');
INSERT INTO public.stormevents_east VALUES (770814, 201806, 14, 1234, 201806, 14, 1235, 126053, 'GEORGIA', 13, 2018, 'June', 'Lightning', 'CHS', '14-JUN-18 12:34:00', 'EST-5', '14-JUN-18 12:35:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'ESE', 'RINCON', 1, 'ESE', 'RINCON', 32.29, -81.21, 32.29, -81.21, 'A warm and moist airmass along with a weak trough of low pressure and associated surface boundary led to an environment capable of producing strong to severe thunderstorms across Southeast Georgia.', 'An emergency manager reported minor electrical damage due to a lightning strike at a residence on the 200 block of St. Andrews Road.');
INSERT INTO public.stormevents_east VALUES (770817, 201806, 14, 1518, 201806, 14, 1519, 126053, 'GEORGIA', 13, 2018, 'June', 'Lightning', 'CHS', '14-JUN-18 15:18:00', 'EST-5', '14-JUN-18 15:19:00', 0, 0, 0, 0, '2.50K', NULL, 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'E', 'SPRINGFIELD', 1, 'E', 'SPRINGFIELD', 32.37, -81.31, 32.37, -81.31, 'A warm and moist airmass along with a weak trough of low pressure and associated surface boundary led to an environment capable of producing strong to severe thunderstorms across Southeast Georgia.', 'An emergency manager reported a lightning strike to a transformer, starting a fire and power lines down in the roadway near the 400 block of Ash Street.');
INSERT INTO public.stormevents_east VALUES (770819, 201806, 14, 1524, 201806, 14, 1525, 126053, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '14-JUN-18 15:24:00', 'EST-5', '14-JUN-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 3, 'ENE', 'MARLOW', 3, 'ENE', 'MARLOW', 32.28, -81.33, 32.28, -81.33, 'A warm and moist airmass along with a weak trough of low pressure and associated surface boundary led to an environment capable of producing strong to severe thunderstorms across Southeast Georgia.', 'An emergency manager reported trees and power lines down at the intersection of Standard Lane and Tusculum Road and at the 200 block of Church Road.');
INSERT INTO public.stormevents_east VALUES (770820, 201806, 14, 1534, 201806, 14, 1535, 126054, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '14-JUN-18 15:34:00', 'EST-5', '14-JUN-18 15:35:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'ESE', 'CANADYS', 2, 'ESE', 'CANADYS', 33.04, -80.59, 33.04, -80.59, 'A warm and moist airmass along with a weak trough of low pressure and associated surface boundary led to an environment capable of producing strong to severe thunderstorms across Southeast South Carolina.', 'The South Carolina Highway Patrol reported a tree down at Augusta Highway and Round O Road.');
INSERT INTO public.stormevents_east VALUES (770821, 201806, 14, 1620, 201806, 14, 1621, 126054, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '14-JUN-18 16:20:00', 'EST-5', '14-JUN-18 16:21:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'JACKSONBORO', 0, 'N', 'JACKSONBORO', 32.77, -80.45, 32.77, -80.45, 'A warm and moist airmass along with a weak trough of low pressure and associated surface boundary led to an environment capable of producing strong to severe thunderstorms across Southeast South Carolina.', 'The South Carolina Highway Patrol reported a tree down.');
INSERT INTO public.stormevents_east VALUES (770824, 201806, 15, 1700, 201806, 15, 1701, 126055, 'SOUTH CAROLINA', 45, 2018, 'June', 'Lightning', 'CHS', '15-JUN-18 17:00:00', 'EST-5', '15-JUN-18 17:01:00', 0, 0, 0, 0, '5.00K', NULL, 'Public', NULL, NULL, NULL, NULL, 2, 'NW', 'REMLEYS', 2, 'NW', 'REMLEYS', 32.89, -79.92, 32.89, -79.92, 'A highly unstable atmosphere developed across the region ahead of a backdoor cold front approaching from the north during the afternoon.', 'The public reported major electrical damage due to a lightning strike to at least one home in Beresford Creek Subdivision on Peach Blossom Drive.');
INSERT INTO public.stormevents_east VALUES (770338, 201806, 8, 1258, 201806, 8, 1400, 126052, 'SOUTH CAROLINA', 45, 2018, 'June', 'Heavy Rain', 'CHS', '08-JUN-18 12:58:00', 'EST-5', '08-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 0, 'N', 'CHARLESTON', 0, 'N', 'CHARLESTON', 32.78, -79.93, 32.78, -79.93, 'A weak low positioned over the northeast Gulf of Mexico helped draw deep moisture over Southeast South Carolina during the afternoon.', 'The media reported a building between John and Hutson Streets having a partial roof collapse following heavy rainfall at 1:15 PM. John and Hutson Streets were closed. Rainfall accumulation of 2.60 inches had fallen between 11 AM and 1:20 PM, setting a new daily record. Additionally, the Charleston Fire Department had to assist a stranded motorist near the intersection of Morris Street and Marbel Lane.');
INSERT INTO public.stormevents_east VALUES (770868, 201806, 24, 2102, 201806, 24, 2103, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 21:02:00', 'EST-5', '24-JUN-18 21:03:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'PINEVILLE', 2, 'E', 'PINEVILLE', 33.43, -79.99, 33.43, -79.99, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The Berkeley County 911 Call Center reported a tree down along Highway 45 near Pineville.');
INSERT INTO public.stormevents_east VALUES (770870, 201806, 24, 2119, 201806, 24, 2120, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 21:19:00', 'EST-5', '24-JUN-18 21:20:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'MONCKS CORNER', 1, 'E', 'MONCKS CORNER', 33.2, -80.01, 33.2, -80.01, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'Law enforcement reported a tree down on Highway 17A near Church Street.');
INSERT INTO public.stormevents_east VALUES (770852, 201806, 27, 2300, 201806, 28, 345, 128450, 'WEST VIRGINIA', 54, 2018, 'June', 'Flash Flood', 'PBZ', '27-JUN-18 23:00:00', 'EST-5', '28-JUN-18 03:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 7, 'W', 'ST GEORGE', 7, 'WNW', 'ST GEORGE', 39.1739, -79.8284, 39.1961, -79.8222, 'In the wake of morning rain, cloud breaks developed from Virginia into south central Pennsylvania during the afternoon.  CAPE values climbed to near 1000 J/kg, despite poor mid-level lapse rates.  Disturbances rotating around the southeastern periphery of a Great Lakes/upper Ohio Valley trough helped to increase low level flow and shear.  This proved sufficient to allow afternoon storms to rotate.||One storm produced a weak EF0 tornado in Monongalia county off Kingwood Road.  There were several trees uprooted and snapped. Five homes lost parts of their roof.||Multiple rounds of thunderstorms also produced flash flooding in Tucker County during the evening hours, mainly in the vicinity of Route 38 to the northwest of Parsons.', 'County officials reported that several roads in Tucker County were closed. This included a portion of Route 38, which was washed out.');
INSERT INTO public.stormevents_east VALUES (770853, 201806, 27, 1642, 201806, 27, 1643, 128450, 'WEST VIRGINIA', 54, 2018, 'June', 'Tornado', 'PBZ', '27-JUN-18 16:42:00', 'EST-5', '27-JUN-18 16:43:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'S', 'BURNS CHAPEL', 2, 'SSE', 'BURNS CHAPEL', 39.543, -79.875, 39.541, -79.872, 'In the wake of morning rain, cloud breaks developed from Virginia into south central Pennsylvania during the afternoon.  CAPE values climbed to near 1000 J/kg, despite poor mid-level lapse rates.  Disturbances rotating around the southeastern periphery of a Great Lakes/upper Ohio Valley trough helped to increase low level flow and shear.  This proved sufficient to allow afternoon storms to rotate.||One storm produced a weak EF0 tornado in Monongalia county off Kingwood Road.  There were several trees uprooted and snapped. Five homes lost parts of their roof.||Multiple rounds of thunderstorms also produced flash flooding in Tucker County during the evening hours, mainly in the vicinity of Route 38 to the northwest of Parsons.', 'A weak tornado touched down southeast of Morgantown in the 2800|block of Kingwood Pike. There was roof damage to four structures.|One house lost over half its roof, while the others had less than|20 percent of their roofs affected. A support beam to a covered |porch was blown out at a residence. Meanwhile a utility pole was |ripped loose and landed on the side of a house. There were around|10 trees that were either uprooted or snapped.   The estimated maximum wind speed was 65-70 MPH.');
INSERT INTO public.stormevents_east VALUES (767740, 201806, 18, 1355, 201806, 18, 1359, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 13:55:00', 'EST-5', '18-JUN-18 13:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'WOODSVILLE', 1, 'E', 'WOODSVILLE', 44.15, -72.04, 44.15, -72.04, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees and wires in Woodsville.');
INSERT INTO public.stormevents_east VALUES (767746, 201806, 18, 1455, 201806, 18, 1459, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 14:55:00', 'EST-5', '18-JUN-18 14:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', 50, 'EG', NULL, NULL, 2, 'SE', 'LOST RIVER', 2, 'SE', 'LOST RIVER', 44.01, -71.74, 44.01, -71.74, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed multiple trees on Route 118 near Lost River.');
INSERT INTO public.stormevents_east VALUES (761019, 201805, 18, 830, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 08:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'AMELIA', 1, 'N', 'AMELIA', 37.33, -77.98, 37.3447, -77.9775, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (761020, 201805, 18, 830, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 08:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BRUNSWICK', 1, 'S', 'FITZHUGH', 36.65, -77.87, 36.6561, -77.7711, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (761028, 201805, 18, 1530, 201805, 19, 1630, 126966, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '18-MAY-18 15:30:00', 'EST-5', '19-MAY-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CHARLES CITY', 1, 'N', 'CHARLES CITY', 37.33, -77.07, 37.3477, -77.0672, 'Showers and thunderstorms associated with areas of low pressure along a frontal boundary produced heavy rain which caused lingering flooding across portions of central, south central, and eastern Virginia.', 'Numerous roads remained closed due to ongoing flooding from heavy rainfall across portions of the county.');
INSERT INTO public.stormevents_east VALUES (791259, 201811, 2, 2213, 201811, 2, 2213, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 22:13:00', 'EST-5', '02-NOV-18 22:13:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 9, 'NNE', 'GOOSES REEF BUOY (44062)', 9, 'NNE', 'GOOSES REEF BUOY (44062)', 38.6728, -76.337, 38.6728, -76.337, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 38 knots was measured at Blackwalnut Harbor.');
INSERT INTO public.stormevents_east VALUES (791264, 201811, 6, 1142, 201811, 6, 1142, 132244, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '06-NOV-18 11:42:00', 'EST-5', '06-NOV-18 11:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BABAR POINT (BAB)', 0, 'N', 'BABAR POINT (BAB)', 38.31, -77.03, 38.31, -77.03, 'Mild and moist air with limited instability moved across the region ahead of an eastward moving cold front. This combined with high amounts of wind shear to create a squall line that moved across the waters, producing gusty winds.', 'A wind gust of up to 34 knots was observed at Babar Point.');
INSERT INTO public.stormevents_east VALUES (791265, 201811, 6, 1142, 201811, 6, 1142, 132244, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '06-NOV-18 11:42:00', 'EST-5', '06-NOV-18 11:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'KENT ISLAND (KNT)', 0, 'N', 'KENT ISLAND (KNT)', 38.92, -76.36, 38.92, -76.36, 'Mild and moist air with limited instability moved across the region ahead of an eastward moving cold front. This combined with high amounts of wind shear to create a squall line that moved across the waters, producing gusty winds.', 'A wind gust of up to 34 knots was observed at Kent Island.');
INSERT INTO public.stormevents_east VALUES (750564, 201804, 24, 1442, 201804, 24, 1442, 125154, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '24-APR-18 14:42:00', 'EST-5', '24-APR-18 14:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 10, 'SSE', 'PORT OF PALM BEACH', 10, 'SSE', 'PORT OF PALM BEACH', 26.6128, -80.0362, 26.6128, -80.0362, 'A lingering stalled frontal boundary near Lake Okeechobee aided in the development of another day of scattered afternoon showers and storms across the region. Several reports of strong wind gusts were received as these storms moved off the Palm Beach County coast, in addition to the development of a waterspout.', 'A marine thunderstorm wind gust of 40 mph / 35 knots was recorded by the C-Man station LKWF1 at Lake Worth Pier.');
INSERT INTO public.stormevents_east VALUES (750561, 201804, 24, 1409, 201804, 24, 1409, 125154, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '24-APR-18 14:09:00', 'EST-5', '24-APR-18 14:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 3, 'SSE', 'JUPITER INLET', 3, 'SSE', 'JUPITER INLET', 26.8932, -80.0562, 26.8932, -80.0562, 'A lingering stalled frontal boundary near Lake Okeechobee aided in the development of another day of scattered afternoon showers and storms across the region. Several reports of strong wind gusts were received as these storms moved off the Palm Beach County coast, in addition to the development of a waterspout.', 'A marine thunderstorm wind gust of 41 mph / 36 knots was recorded by the WxFlow mesonet site XJUP at Juno Beach Pier.');
INSERT INTO public.stormevents_east VALUES (750563, 201804, 24, 1436, 201804, 24, 1436, 125154, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MFL', '24-APR-18 14:36:00', 'EST-5', '24-APR-18 14:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 46, 'MG', NULL, NULL, 1, 'SSE', 'JUPITER INLET', 1, 'SSE', 'JUPITER INLET', 26.9116, -80.0734, 26.9116, -80.0734, 'A lingering stalled frontal boundary near Lake Okeechobee aided in the development of another day of scattered afternoon showers and storms across the region. Several reports of strong wind gusts were received as these storms moved off the Palm Beach County coast, in addition to the development of a waterspout.', 'A marine thunderstorm wind gust of 53 mph / 46 knots was recorded by WxFlow mesonet site XOAK near Jupiter. A subsequent gust of 53mph/46 knots was recorded at 341 pm EDT.');
INSERT INTO public.stormevents_east VALUES (750565, 201804, 24, 1425, 201804, 24, 1425, 125154, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Waterspout', 'MFL', '24-APR-18 14:25:00', 'EST-5', '24-APR-18 14:25:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 3, 'ENE', 'PORT OF PALM BEACH', 3, 'ENE', 'PORT OF PALM BEACH', 26.77, -80.02, 26.77, -80.02, 'A lingering stalled frontal boundary near Lake Okeechobee aided in the development of another day of scattered afternoon showers and storms across the region. Several reports of strong wind gusts were received as these storms moved off the Palm Beach County coast, in addition to the development of a waterspout.', 'A video of a water spout offshore of Palm Beach Shores at 325 pm EDT. The video was reported via Twitter.');
INSERT INTO public.stormevents_east VALUES (750560, 201804, 24, 1446, 201804, 24, 1446, 125153, 'FLORIDA', 12, 2018, 'April', 'Hail', 'MFL', '24-APR-18 14:46:00', 'EST-5', '24-APR-18 14:46:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'S', 'SEMINOLE MANOR', 1, 'S', 'SEMINOLE MANOR', 26.5848, -80.0683, 26.5848, -80.0683, 'A lingering stalled frontal boundary near Lake Okeechobee aided in the development of another day of scattered afternoon showers and storms across the region. Stronger storms that developed with boundary interactions across Palm Beach County produced small hail.', 'A trained weather spotter reported dime sized hail at the intersection of I-95 and Ocean Ave in Lantana. Additional reports of pea sized hail were received in the vicinity.');
INSERT INTO public.stormevents_east VALUES (765388, 201806, 8, 1955, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 19:55:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 5, 'ESE', 'NEW CUMBERLAND', 5, 'ESE', 'NEW CUMBERLAND', 40.5305, -81.2095, 40.5281, -81.2089, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'A private lake in the vicinity of State Route 39 was reported to have overtopped.');
INSERT INTO public.stormevents_east VALUES (765436, 201806, 13, 1542, 201806, 13, 1542, 127651, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'BUF', '13-JUN-18 15:42:00', 'EST-5', '13-JUN-18 15:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 50, 'MG', NULL, NULL, 1, 'WSW', 'BUFFALO HARBOR', 1, 'WSW', 'BUFFALO HARBOR', 42.8727, -78.9066, 42.8727, -78.9066, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', NULL);
INSERT INTO public.stormevents_east VALUES (765562, 201806, 2, 1312, 201806, 2, 1312, 125384, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '02-JUN-18 13:12:00', 'EST-5', '02-JUN-18 13:12:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'S', 'CENTER HILL', 4, 'S', 'CENTER HILL', 31.08, -83.9, 31.08, -83.9, 'Scattered to numerous showers and thunderstorms occurred across the area during the June 2-4 period.  As is typical with summer storms in this part of the country, some of the storms were severe with impacts to trees and power lines.  One storm was particularly severe in southern Lanier county with overturned farm equipment reported.', 'Straight line winds uprooted four oak trees on a property in southwestern Colquitt county.  One tree landed on a house.  Damage cost was estimated.');
INSERT INTO public.stormevents_east VALUES (765579, 201806, 3, 2310, 201806, 3, 2310, 125384, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '03-JUN-18 23:10:00', 'EST-5', '03-JUN-18 23:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SW', 'ALAPAHA', 3, 'SW', 'ALAPAHA', 31.3493, -83.256, 31.3493, -83.256, 'Scattered to numerous showers and thunderstorms occurred across the area during the June 2-4 period.  As is typical with summer storms in this part of the country, some of the storms were severe with impacts to trees and power lines.  One storm was particularly severe in southern Lanier county with overturned farm equipment reported.', 'Several trees were blown down.');
INSERT INTO public.stormevents_east VALUES (784219, 201809, 25, 1127, 201809, 25, 1430, 131099, 'NEW JERSEY', 34, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 11:27:00', 'EST-5', '25-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BRILLS JCT', 1, 'SSW', 'BRILLS JCT', 40.7146, -74.1526, 40.7159, -74.157, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain across northeast New Jersey by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 3-5 inches, with one CoCoRaHS observer reporting 5.56 inches of rain in Palisades Park.', 'The local lanes of US Routes 1 & 9 were flooded northbound approaching Delancy Street in Newark.');
INSERT INTO public.stormevents_east VALUES (774370, 201807, 10, 1225, 201807, 10, 1225, 129227, 'MAINE', 23, 2018, 'July', 'Hail', 'CAR', '10-JUL-18 12:25:00', 'EST-5', '10-JUL-18 12:25:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 0, 'N', 'DAIGLE', 0, 'N', 'DAIGLE', 47.18, -68.47, 47.18, -68.47, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'The hail ranged from nickel to quarter size.');
INSERT INTO public.stormevents_east VALUES (774371, 201807, 10, 1237, 201807, 10, 1237, 129227, 'MAINE', 23, 2018, 'July', 'Hail', 'CAR', '10-JUL-18 12:37:00', 'EST-5', '10-JUL-18 12:37:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 1, NULL, NULL, NULL, 2, 'ENE', 'SHIRLEY MILLS', 2, 'ENE', 'SHIRLEY MILLS', 45.38, -69.6, 45.38, -69.6, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (774375, 201807, 10, 1440, 201807, 10, 1440, 129227, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '10-JUL-18 14:40:00', 'EST-5', '10-JUL-18 14:40:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'GREENBUSH', 0, 'N', 'GREENBUSH', 45.08, -68.67, 45.08, -68.67, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Trees were toppled on to power lines by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (774378, 201807, 10, 1510, 201807, 10, 1510, 129227, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '10-JUL-18 15:10:00', 'EST-5', '10-JUL-18 15:10:00', 0, 0, 0, 0, NULL, NULL, 'Public', 56, 'EG', NULL, NULL, 14, 'NE', 'MYRA', 14, 'NE', 'MYRA', 45.13, -68.2, 45.13, -68.2, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Numerous trees were toppled and snapped along the shore of Nicatous Lake by wind gusts estimated at 65 mph. Docks were also flipped and pushed on to the shore. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (774379, 201807, 10, 1505, 201807, 10, 1505, 129227, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '10-JUL-18 15:05:00', 'EST-5', '10-JUL-18 15:05:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'OLD TOWN', 0, 'N', 'OLD TOWN', 44.93, -68.63, 44.93, -68.63, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Trees were toppled by wind gusts estimated at 60 mph.');
