INSERT INTO public.stormevents_east VALUES (774387, 201807, 28, 1355, 201807, 28, 1355, 129228, 'MAINE', 23, 2018, 'July', 'Hail', 'CAR', '28-JUL-18 13:55:00', 'EST-5', '28-JUL-18 13:55:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.25, NULL, NULL, NULL, 0, 'N', 'HAMLIN', 0, 'N', 'HAMLIN', 47.07, -67.8, 47.07, -67.8, 'A cold front crossed the region through the afternoon and evening of the 28th. Thunderstorms developed in advance of the front. Some of the thunderstorms became severe producing damaging winds and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (774388, 201807, 28, 1725, 201807, 28, 1725, 129228, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '28-JUL-18 17:25:00', 'EST-5', '28-JUL-18 17:25:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 2, 'E', 'CONNOR', 2, 'E', 'CONNOR', 46.95, -67.93, 46.95, -67.93, 'A cold front crossed the region through the afternoon and evening of the 28th. Thunderstorms developed in advance of the front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Several trees were toppled at the Limestone Country Club by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (767282, 201806, 3, 515, 201806, 3, 800, 127917, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '03-JUN-18 05:15:00', 'EST-5', '03-JUN-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'OZEANA', 2, 'NNW', 'OZEANA', 37.84, -76.8, 37.8643, -76.7893, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of central and eastern Virginia.', 'Car was stuck in water at Peach Tree Lane. Several roads were flooded.');
INSERT INTO public.stormevents_east VALUES (767674, 201807, 21, 1430, 201807, 21, 1430, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 14:30:00', 'EST-5', '21-JUL-18 14:30:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'HINES', 0, 'N', 'HINES', 29.73, -83.23, 29.73, -83.23, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees and power lines were blown down.');
