INSERT INTO public.stormevents_east VALUES (767284, 201806, 3, 1259, 201806, 3, 1259, 127917, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '03-JUN-18 12:59:00', 'EST-5', '03-JUN-18 12:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'N', 'HARMONY VLG', 1, 'N', 'HARMONY VLG', 37.59, -76.48, 37.59, -76.48, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of central and eastern Virginia.', 'Rainfall total of 3.35 inches was reported.');
