INSERT INTO public.stormevents_east VALUES (767754, 201807, 22, 1505, 201807, 22, 1505, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 15:05:00', 'EST-5', '22-JUL-18 15:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NNW', 'MIDWAY', 2, 'NNW', 'MIDWAY', 30.04, -83.08, 30.04, -83.08, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'A tree was blown down onto power lines near SE Walter Henderson Road.');
INSERT INTO public.stormevents_east VALUES (767756, 201807, 22, 1510, 201807, 22, 1510, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 15:10:00', 'EST-5', '22-JUL-18 15:10:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'GRADY', 1, 'WSW', 'GRADY', 29.94, -82.95, 29.94, -82.95, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'A tree was blown down onto power lines along Highway 349.');
INSERT INTO public.stormevents_east VALUES (767798, 201807, 21, 1030, 201807, 21, 1030, 127753, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 10:30:00', 'EST-5', '21-JUL-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 5, 'SW', 'DOLES', 5, 'SW', 'DOLES', 31.6577, -83.9498, 31.6577, -83.9498, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees were blown down on Camp Osborn Road.');
INSERT INTO public.stormevents_east VALUES (767286, 201806, 3, 930, 201806, 3, 1030, 127917, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '03-JUN-18 09:30:00', 'EST-5', '03-JUN-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'HAGUE', 0, 'N', 'HAGUE', 38.07, -76.65, 38.0735, -76.6498, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of central and eastern Virginia.', 'Mudslide was reported in the eastern portion of the county. Several roads were flooded.');
INSERT INTO public.stormevents_east VALUES (767192, 201806, 3, 2200, 201806, 5, 54, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 22:00:00', 'EST-5', '05-JUN-18 00:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'FREDERICKSBURG', 2, 'N', 'FREDERICKSBURG', 38.3171, -77.483, 38.3214, -77.4745, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The tide gage on the Rappahannock River at Fredericksburg City Dock exceeded the 13 foot flood stage during the indicated period. City Dock in Fredericksburg flooded, with over six feet of water over the dock at peak. Old Mill Park was also flooded. Basement flooding from overland flow was reported near the City Dock.');
INSERT INTO public.stormevents_east VALUES (767279, 201806, 3, 215, 201806, 3, 415, 127917, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '03-JUN-18 02:15:00', 'EST-5', '03-JUN-18 04:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'PROVIDENCE FORGE', 1, 'S', 'PROVIDENCE FORGE', 37.44, -77.03, 37.4375, -77.0311, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of central and eastern Virginia.', 'Several roads were closed due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (768393, 201806, 25, 1940, 201806, 25, 1940, 127592, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '25-JUN-18 19:40:00', 'EST-5', '25-JUN-18 19:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'N', 'ROBBINS', 2, 'N', 'ROBBINS', 35.4547, -79.6041, 35.4547, -79.6041, 'Strong to severe convection initially developed in a region of weak to moderately instability in the vicinity of surface boundary near the North Carolina, South Carolina border. Subsequently a line of severe thunderstorms developed in Tennessee in association with a southeast advancing mesoscale convective vortex that moved across the mountains and then across central North Carolina.', 'One tree was reported down in the road at Highway 705 and Leaman Road.');
