INSERT INTO public.stormevents_east VALUES (768912, 201806, 18, 1443, 201806, 18, 1443, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 14:43:00', 'EST-5', '18-JUN-18 14:43:00', 0, 0, 0, 0, '20.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'SHESHEQUIN', 0, 'N', 'SHESHEQUIN', 41.85, -76.48, 41.85, -76.48, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees blocking roadways in Ulster.');
INSERT INTO public.stormevents_east VALUES (768913, 201806, 18, 1447, 201806, 18, 1447, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 14:47:00', 'EST-5', '18-JUN-18 14:47:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'NORTH TOWANDA', 1, 'S', 'NORTH TOWANDA', 41.77, -76.45, 41.77, -76.45, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees.');
INSERT INTO public.stormevents_east VALUES (768915, 201806, 18, 1528, 201806, 18, 1528, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 15:28:00', 'EST-5', '18-JUN-18 15:28:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'MONTROSE', 0, 'N', 'MONTROSE', 41.83, -75.88, 41.83, -75.88, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines.  One person had part of tree come down on them with no injuries.');
INSERT INTO public.stormevents_east VALUES (768916, 201806, 18, 1550, 201806, 18, 1550, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 15:50:00', 'EST-5', '18-JUN-18 15:50:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'SUSQUEHANNA', 0, 'N', 'SUSQUEHANNA', 41.93, -75.6, 41.93, -75.6, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees.');
INSERT INTO public.stormevents_east VALUES (768917, 201806, 18, 1610, 201806, 18, 1610, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:10:00', 'EST-5', '18-JUN-18 16:10:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'STARLIGHT', 0, 'N', 'STARLIGHT', 41.9, -75.33, 41.9, -75.33, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees.');
INSERT INTO public.stormevents_east VALUES (786180, 201809, 17, 2221, 201809, 18, 45, 131390, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'AKQ', '17-SEP-18 22:21:00', 'EST-5', '18-SEP-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 4, 'N', 'CUNNINGHAM', 3, 'N', 'CUNNINGHAM', 37.92, -78.34, 37.9137, -78.3391, 'Scattered showers and thunderstorms associated with tropical cyclone Florence produced heavy rain which caused flash flooding across portions of central Virginia.', 'Woodlawn Drive was impassable due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (770826, 201806, 15, 1911, 201806, 15, 1912, 126055, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '15-JUN-18 19:11:00', 'EST-5', '15-JUN-18 19:12:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 6, 'S', 'GIVHANS', 6, 'S', 'GIVHANS', 32.94, -80.33, 32.94, -80.33, 'A highly unstable atmosphere developed across the region ahead of a backdoor cold front approaching from the north during the afternoon.', 'The South Carolina Highway Patrol reported a tree down at the intersection of Alternate Highway 17 and Clubhouse Road.');
INSERT INTO public.stormevents_east VALUES (770828, 201806, 15, 1928, 201806, 15, 1929, 126055, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '15-JUN-18 19:28:00', 'EST-5', '15-JUN-18 19:29:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'N', 'COTTAGEVILLE', 1, 'N', 'COTTAGEVILLE', 32.94, -80.48, 32.94, -80.48, 'A highly unstable atmosphere developed across the region ahead of a backdoor cold front approaching from the north during the afternoon.', 'The South Carolina Highway Patrol reported a tree down at the 1000 Block of Griffith Acres Drive.');
INSERT INTO public.stormevents_east VALUES (770830, 201806, 16, 1458, 201806, 16, 1459, 126056, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '16-JUN-18 14:58:00', 'EST-5', '16-JUN-18 14:59:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'BOYD', 1, 'NW', 'BOYD', 32.69, -81.53, 32.69, -81.53, 'A weak cold front approaching from the north encountered a warm and moist airmass, helping produce strong to severe thunderstorms across Southeast Georgia.', 'The Screven County 911 Call Center reported a tree down on Poor Robin Road.');
INSERT INTO public.stormevents_east VALUES (770833, 201806, 16, 1538, 201806, 16, 1539, 126056, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CHS', '16-JUN-18 15:38:00', 'EST-5', '16-JUN-18 15:39:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NW', 'BASCOM', 3, 'NW', 'BASCOM', 32.86, -81.7, 32.86, -81.7, 'A weak cold front approaching from the north encountered a warm and moist airmass, helping produce strong to severe thunderstorms across Southeast Georgia.', 'The Screven County 911 Call Center reported a tree down on Hiltonia-Perkins Road.');
INSERT INTO public.stormevents_east VALUES (770845, 201806, 20, 1724, 201806, 20, 1725, 126057, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '20-JUN-18 17:24:00', 'EST-5', '20-JUN-18 17:25:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 60, 'EG', NULL, NULL, 1, 'N', 'HAMPTON', 1, 'N', 'HAMPTON', 32.88, -81.12, 32.88, -81.12, 'A trough of low pressure encountered an unstable airmass over Southeast South Carolina, which led to severe thunderstorms during late afternoon hours.', 'A report relayed via social media indicated the awning covering a walkway into the Ben Hazel Primary School sustaining minor damage.');
INSERT INTO public.stormevents_east VALUES (770847, 201806, 20, 1732, 201806, 20, 1735, 126057, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '20-JUN-18 17:32:00', 'EST-5', '20-JUN-18 17:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 70, 'EG', NULL, NULL, 1, 'NW', 'HAMPTON', 1, 'NW', 'HAMPTON', 32.88, -81.13, 32.88, -81.13, 'A trough of low pressure encountered an unstable airmass over Southeast South Carolina, which led to severe thunderstorms during late afternoon hours.', 'The Hampton County 911 Call Center reported a roof collapse of the Babcock Furniture Store in Hampton. Five people were pulled out from the building, but were not injured. An adjacent building also had a roof lifted up and the windows blown out. A nearby Food Lion also had some ceiling tiles blown out of the building. Several trees were also knocked down in and around town.');
INSERT INTO public.stormevents_east VALUES (770848, 201806, 20, 1735, 201806, 20, 1736, 126057, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '20-JUN-18 17:35:00', 'EST-5', '20-JUN-18 17:36:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'VARNVILLE', 1, 'W', 'VARNVILLE', 32.85, -81.09, 32.85, -81.09, 'A trough of low pressure encountered an unstable airmass over Southeast South Carolina, which led to severe thunderstorms during late afternoon hours.', 'The South Carolina Highway Patrol reported a tree down at Taylor Street off Carolina Avenue.');
INSERT INTO public.stormevents_east VALUES (770849, 201806, 20, 1738, 201806, 20, 1739, 126057, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '20-JUN-18 17:38:00', 'EST-5', '20-JUN-18 17:39:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'SSW', 'HAMPTON', 4, 'SSW', 'HAMPTON', 32.82, -81.15, 32.82, -81.15, 'A trough of low pressure encountered an unstable airmass over Southeast South Carolina, which led to severe thunderstorms during late afternoon hours.', 'The South Carolina Highway Patrol reported a tree down at Lake Warren Road and Savannah Highway.');
INSERT INTO public.stormevents_east VALUES (770871, 201806, 24, 2123, 201806, 24, 2124, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 21:23:00', 'EST-5', '24-JUN-18 21:24:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 4, 'ESE', 'BONNEAU', 4, 'ESE', 'BONNEAU', 33.28, -79.89, 33.28, -79.89, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'A trained spotter reported trees down on a property along the 1000 block of High Hope Drive.');
INSERT INTO public.stormevents_east VALUES (770872, 201806, 24, 2234, 201806, 24, 2235, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 22:34:00', 'EST-5', '24-JUN-18 22:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'JENNYS', 1, 'NE', 'JENNYS', 33.04, -81.11, 33.04, -81.11, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The Allendale 911 Call Center reported a tree down near the intersection of Conferderate Highway and Jenny''s Road.');
INSERT INTO public.stormevents_east VALUES (770873, 201806, 24, 2249, 201806, 24, 2250, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 22:49:00', 'EST-5', '24-JUN-18 22:50:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 5, 'NE', 'SMOAKS', 5, 'NE', 'SMOAKS', 33.13, -80.74, 33.13, -80.74, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The South Carolina Highway Patrol reported a tree down in the 5200 block of Augusta Highway.');
INSERT INTO public.stormevents_east VALUES (770874, 201806, 24, 2250, 201806, 24, 2251, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 22:50:00', 'EST-5', '24-JUN-18 22:51:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'HAMPTON', 1, 'E', 'HAMPTON', 32.87, -81.11, 32.87, -81.11, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The Hampton County 911 Call Center reported multiple trees down.');
INSERT INTO public.stormevents_east VALUES (770876, 201806, 24, 2251, 201806, 24, 2252, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 22:51:00', 'EST-5', '24-JUN-18 22:52:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ENE', 'VARNVILLE', 1, 'ENE', 'VARNVILLE', 32.86, -81.05, 32.86, -81.05, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'Law enforcement reported a tree down across Mill Pond Road.');
INSERT INTO public.stormevents_east VALUES (770878, 201806, 24, 2309, 201806, 24, 2310, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 23:09:00', 'EST-5', '24-JUN-18 23:10:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NNW', 'JONESVILLE', 2, 'NNW', 'JONESVILLE', 32.75, -80.83, 32.75, -80.83, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'Law enforcement reported a tree down on I-95 southbound near mile marker 42.');
INSERT INTO public.stormevents_east VALUES (770879, 201806, 24, 2311, 201806, 24, 2312, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 23:11:00', 'EST-5', '24-JUN-18 23:12:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 5, 'NNW', 'HENDERSONVILLE', 5, 'NNW', 'HENDERSONVILLE', 32.85, -80.76, 32.85, -80.76, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The South Carolina Highway Patrol reported a tree down at the intersection of Magellan Road and Stanley Avenue.');
INSERT INTO public.stormevents_east VALUES (767752, 201806, 18, 1615, 201806, 18, 1620, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 16:15:00', 'EST-5', '18-JUN-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SW', '(EEN)DILLANT FLD ARP', 1, 'SW', '(EEN)DILLANT FLD ARP', 42.89, -72.28, 42.89, -72.28, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed multiple trees on Mathews Road near Swanzey.');
INSERT INTO public.stormevents_east VALUES (767755, 201806, 18, 1640, 201806, 18, 1644, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 16:40:00', 'EST-5', '18-JUN-18 16:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SSW', 'GREENFIELD', 1, 'SSW', 'GREENFIELD', 42.93, -71.86, 42.93, -71.86, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed power lines on Gould Hill Road in Greenfield.');
INSERT INTO public.stormevents_east VALUES (767768, 201806, 18, 1708, 201806, 18, 1713, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:08:00', 'EST-5', '18-JUN-18 17:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NNW', 'DERRY', 1, 'NNW', 'DERRY', 42.8811, -71.3245, 42.8811, -71.3245, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees in Derry.');
INSERT INTO public.stormevents_east VALUES (767780, 201806, 18, 1726, 201806, 18, 1730, 128007, 'NEW HAMPSHIRE', 33, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 17:26:00', 'EST-5', '18-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NE', 'EPPING', 1, 'NE', 'EPPING', 43.04, -71.06, 43.04, -71.06, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some storms. Although two tornadoes were confirmed and other funnel clouds were reported, the majority of the storms produced straight line wind damage.', 'A severe thunderstorm downed trees on Route 125 in Epping.');
INSERT INTO public.stormevents_east VALUES (798765, 201811, 15, 500, 201811, 15, 900, 133506, 'GEORGIA', 13, 2018, 'November', 'Flash Flood', 'FFC', '15-NOV-18 05:00:00', 'EST-5', '15-NOV-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'TOOMSBORO', 1, 'W', 'TOOMSBORO', 32.8397, -83.0933, 32.8305, -83.0931, 'An upper level low pressure system, combined with a series of weak disturbances, provided several waves of precipitation the week of November 11th, producing periods of heavy rain over north and central Georgia. Overnight November 14th into November 15th was particularly wet over east central Georgia as a band of heavy rainfall set up over the area, dumping 4 to 5 inches of rain along a line from Rochelle, northeast to Irwinton, to Washington. These rainfall amounts combined with the already saturated soils to produce isolated flash flooding.', 'Emergency Manager reported water over C.T. Lord Highway, between Day Road and Highway 112. Radar estimates indicate that 4 to 5 inches of rainfall occurred over the area.');
INSERT INTO public.stormevents_east VALUES (761356, 201805, 19, 1600, 201805, 25, 400, 127031, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'AKQ', '19-MAY-18 16:00:00', 'EST-5', '25-MAY-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'MATTAPONI', 1, 'N', 'CENTERVILLE', 37.53, -76.77, 37.5592, -76.73, 'Flooding occurred along the Mattaponi River in East Central Virginia.', 'Flooding occurred along the Mattaponi River over several days, with roads and low lying areas near the river impacted the most.');
INSERT INTO public.stormevents_east VALUES (769055, 201807, 17, 1200, 201807, 17, 1200, 128219, 'NEW YORK', 36, 2018, 'July', 'Lightning', 'ALY', '17-JUL-18 12:00:00', 'EST-5', '17-JUL-18 12:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'N', 'KINGSTON', 1, 'N', 'KINGSTON', 41.94, -74.02, 41.94, -74.02, 'A line of thunderstorms developed in the Mid-Hudson Valley in the early afternoon hours of July 17th ahead of a cold front. Lightning from the storms caused a fire at a substation and resulted in power outages.', 'Lightning caused a fire in a substation, resulting in power outages.');
INSERT INTO public.stormevents_east VALUES (772037, 201807, 28, 1347, 201807, 28, 1347, 128670, 'VERMONT', 50, 2018, 'July', 'Thunderstorm Wind', 'ALY', '28-JUL-18 13:47:00', 'EST-5', '28-JUL-18 13:47:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'NEWFANE', 1, 'S', 'NEWFANE', 42.97, -72.65, 42.97, -72.65, 'Scattered thunderstorms developed during the afternoon of July 28th ahead of a weak frontal boundary. One of these storms produced fairly extensive damage across the town of Westminster, downing numerous trees, some onto houses and cars. The storm cleanup was estimated to cost $80,000, and portions of the town lost power which was not restored until the next day.', 'A tree was downed onto wires.');
INSERT INTO public.stormevents_east VALUES (750570, 201804, 27, 1400, 201804, 27, 1400, 125155, 'FLORIDA', 12, 2018, 'April', 'Hail', 'MFL', '27-APR-18 14:00:00', 'EST-5', '27-APR-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 3, 'SW', 'CORAL SPGS', 3, 'SW', 'CORAL SPGS', 26.24, -80.25, 26.24, -80.25, 'A weak boundary lifting northward across the state and a cold front moving south down the peninsula brought numerous showers and thunderstorms across the region during the afternoon hours. As this activity interacted with the east coast seabreeze, several storms became severe, leading to a brief tornado and small hail in Broward County.', 'A trained weather spotter reported dime sized hail near Atlantic Boulevard and University Drive in Coral Springs. Wind gusts of around 50 mph were recorded in the vicinity around the same time.');
INSERT INTO public.stormevents_east VALUES (754398, 201804, 15, 1912, 201804, 15, 1920, 125794, 'FLORIDA', 12, 2018, 'April', 'Tornado', 'KEY', '15-APR-18 19:12:00', 'EST-5', '15-APR-18 19:20:00', 0, 0, 0, 0, '4.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'SW', 'TAVERNIER', 2, 'SSW', 'TAVERNIER', 24.9879, -80.5511, 24.9907, -80.5374, 'A fast-moving pre-frontal squall line passing through the upper Florida Keys developed an embedded supercell thunderstorm with attendant mesocyclone along the Florida Bay side of Upper Matecumbe Key.  The supercell thunderstorm moved east-northeast, producing a waterspout which made landfall on the bayside of Plantation Key, Islamorada.  The tornado crossed the Overseas Highway, exiting oceanside just southwest of Tavernier Creek.  The waterspout then made a second landfall oceanside in Tavernier southeast of Tavernier Creek before dissipating.', 'Summary:  A waterspout or funnel cloud was observed backlit by |lightning over Florida Bay shortly before making landfall as a |tornado at Indian Mound Trail of the Indian Waterways subdivision of |Plantation Key, Islamorada. Large gumbo limbo tree limbs were downed |as well as the top of a palm tree, landing 20 yards from streetside |the front steps of a residence. And adjacent residence had a rolling |driveway gate completely dislodged from its mounts, pushed into a |trailered boat and car. The tornado continue to produce mostly |damage to large limbs of hardwood trees, including gumbo limbo and |mahogany, in a path rarely exceeded two residential properties in |width toward the east-northeast. An entire gutter and downspout |system was removed from a residence. Numerous loose items, including |filled trash cans and lawn/patio furniture was moved from the |backyards and understory of homes onto front lawns and streets. Most |of the observed damage in the Indian Waterways community were |consistent with 60 to 70 mph, with possible spot values near 75 mph.||The tornado crossed a patch of mangroves and undeveloped forest, and |reached greatest intensity at San Pedro Catholic Church. There, a |large tree split at the trunk, and an old-growth mahogany was |uprooted, falling toward the east onto a portion of the structure |connecting the rectory with the main church. Fortunately, the upper |portion of the tree did not substantially damage the roof, with no |leaks observed in the downpour that followed. However, several |barrel tiles were removed from the peak ridges forming the hip roof |pattern over the rectory, as well as from the southeast edge of the |church, onto the top of the church''s main entrance. Numerous large |limbs were downed toward the east, with lightweight free-standing |signs deposited northward cross the tornado path from right to left.|Estimated wind speeds were maximized in the range of 90 to 100 mph |with maximum width near 60 yards. Good impact reference made to the |observed wind impacts at this location from recent Hurricane Irma, |all having previously been removed or repaired.  ||The tornado continued toward the east-northeast, crossing U.S. |Highway 1 and the Old Highway, but weakened such that only large |tree limbs were downed. From this point, the tornado likely moved |out over the oceanside as a waterspout into Hawk Channel, southwest |of the oceanside entrance to Tavernier Creek.');
INSERT INTO public.stormevents_east VALUES (750574, 201804, 27, 1337, 201804, 27, 1343, 125155, 'FLORIDA', 12, 2018, 'April', 'Tornado', 'MFL', '27-APR-18 13:37:00', 'EST-5', '27-APR-18 13:43:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 4, 'WNW', 'CORAL SPGS', 2, 'NW', 'CORAL SPGS', 26.298, -80.267, 26.286, -80.238, 'A weak boundary lifting northward across the state and a cold front moving south down the peninsula brought numerous showers and thunderstorms across the region during the afternoon hours. As this activity interacted with the east coast seabreeze, several storms became severe, leading to a brief tornado and small hail in Broward County.', 'The tornado touched down south of the Sawgrass Expressway near Country Hills Elementary School just east of Coral Springs Drive. The tornado then continued east-southeast along a discontinuous path, damaging the tops of trees and snapping and breaking off branches and other vegetation, as well as toppling power lines. The tornado damaged a street sign near the intersection of University Drive and Wiles Road, before lifting just south of Wiles Road near NW 85th Avenue.');
INSERT INTO public.stormevents_east VALUES (754402, 201804, 15, 1912, 201804, 15, 1920, 125794, 'FLORIDA', 12, 2018, 'April', 'Tornado', 'KEY', '15-APR-18 19:12:00', 'EST-5', '15-APR-18 19:20:00', 0, 0, 0, 0, '0.20K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'S', 'TAVERNIER', 1, 'S', 'TAVERNIER', 25.0021, -80.5197, 25.0053, -80.5194, 'A fast-moving pre-frontal squall line passing through the upper Florida Keys developed an embedded supercell thunderstorm with attendant mesocyclone along the Florida Bay side of Upper Matecumbe Key.  The supercell thunderstorm moved east-northeast, producing a waterspout which made landfall on the bayside of Plantation Key, Islamorada.  The tornado crossed the Overseas Highway, exiting oceanside just southwest of Tavernier Creek.  The waterspout then made a second landfall oceanside in Tavernier southeast of Tavernier Creek before dissipating.', 'A second path, likely a continuation as the waterspout made landfall |near Lincoln Avenue on the far southwest portion of Tavernier''s |oceanside. Progressive narrowing of the damage path down to nearly |30 yards as well as a turn toward the northwest or north-northwest |was observed.  Impacts lessened from near the waterfront, including |damaged fences and large limbs,gradually down to smaller limbs and |twigs was noted. No further impacts were observed northeast of Lowe |Street.  It is likely the wind speeds 55 to 65 mph were observed, |weakening to below 50 mph roughly 3 blocks from the waterfront.');
INSERT INTO public.stormevents_east VALUES (744117, 201804, 23, 1945, 201804, 23, 1945, 123974, 'GEORGIA', 13, 2018, 'April', 'Flash Flood', 'FFC', '23-APR-18 19:45:00', 'EST-5', '23-APR-18 19:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'GRESHAMVILLE', 2, 'SW', 'GRESHAMVILLE', 33.6288, -83.3526, 33.6127, -83.3464, 'A strong cold front associated with a deep upper-level low swept across the region. Moderate instability and strong mid-level winds combined to produce scattered severe thunderstorms across portions of central and east Georgia.', 'Greene County Emergency Managers reported water over C M Copeland Road and Reid Duvall Road near Greshamville.');
INSERT INTO public.stormevents_east VALUES (770206, 201806, 24, 1850, 201806, 24, 1850, 128378, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '24-JUN-18 18:50:00', 'EST-5', '24-JUN-18 18:50:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 56, 'MG', NULL, NULL, 1, 'N', 'CROTON ON HUDSON', 1, 'N', 'CROTON ON HUDSON', 41.21, -73.9, 41.21, -73.9, 'A cold front from the northwest approached the region bringing strong to severe thunderstorms across Southeast New York.', 'A large tree branch down.');
INSERT INTO public.stormevents_east VALUES (770211, 201806, 24, 1858, 201806, 24, 1858, 128378, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '24-JUN-18 18:58:00', 'EST-5', '24-JUN-18 18:58:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 54, 'MG', NULL, NULL, 1, 'NW', 'SCARBOROUGH', 1, 'NW', 'SCARBOROUGH', 41.14, -73.88, 41.14, -73.88, 'A cold front from the northwest approached the region bringing strong to severe thunderstorms across Southeast New York.', 'Tappan Zee Light 14 Station measured a 62 mph gust.');
INSERT INTO public.stormevents_east VALUES (766172, 201806, 13, 2050, 201806, 13, 2050, 127770, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'ALY', '13-JUN-18 20:50:00', 'EST-5', '13-JUN-18 20:50:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'HAGUE', 1, 'E', 'HAGUE', 43.75, -73.5, 43.75, -73.5, 'A line of strong thunderstorms with gusty winds moved through the region ahead of a cold frontal boundary. A few of these storms produced damaging wind gusts in Warren county, knocking down trees and wires.', 'A tree was knocked down on Route 9N.');
INSERT INTO public.stormevents_east VALUES (787857, 201809, 16, 1745, 201809, 16, 2300, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 17:45:00', 'EST-5', '16-SEP-18 23:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GEORGEVILLE', 1, 'W', 'ROCKY RIVER', 35.304, -80.473, 35.324, -80.625, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'A stream gauge on the Rocky River exceeded its established flood stage after 3 to 4 inches of rain fell across the area throughout the 16th. Multiple tributaries of the river overflowed and flooded adjacent roads, including portions of Pharr Mill Rd, Hopewell Church Rd, Bowman Barrier Rd, Mount Pleasant Rd, Highway 200, and Coxe Mill Rd. Additionally, Little Cold Water Creek overflowed and flooded Old Airport Rd.');
INSERT INTO public.stormevents_east VALUES (766475, 201806, 18, 1600, 201806, 18, 1600, 127813, 'VERMONT', 50, 2018, 'June', 'Thunderstorm Wind', 'ALY', '18-JUN-18 16:00:00', 'EST-5', '18-JUN-18 16:00:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'N', 'BRATTLEBORO', 1, 'N', 'BRATTLEBORO', 42.86, -72.57, 42.86, -72.57, 'A hot and humid air mass was in place across the region with temperatures in the 90s and dew points in the 60s and 70s. This resulted in heat index values reaching 100 to 110 degrees during the afternoon hours in valley areas. ||This air mass also resulted in an unstable environment for strong to severe thunderstorms to form ahead of a cold front passage during the afternoon and evening hours of June 18th. The storms caused numerous trees and power lines to be knocked down, resulting in over 80,000 customers without power throughout the state of Vermont.', 'Large tree branches were downed along Interstate 91 just north of Exit 3.');
INSERT INTO public.stormevents_east VALUES (770155, 201806, 24, 1849, 201806, 24, 1849, 128378, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '24-JUN-18 18:49:00', 'EST-5', '24-JUN-18 18:49:00', 0, 0, 0, 0, NULL, '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SE', 'WEST NYACK', 1, 'SE', 'WEST NYACK', 41.09, -73.97, 41.09, -73.97, 'A cold front from the northwest approached the region bringing strong to severe thunderstorms across Southeast New York.', 'A tree branch with base about the size of hand down in Palisades Mall parking lot.');
INSERT INTO public.stormevents_east VALUES (787918, 201809, 17, 135, 201809, 17, 900, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '17-SEP-18 01:35:00', 'EST-5', '17-SEP-18 09:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'JOY', 3, 'ESE', 'JOY', 35.885, -81.723, 35.86, -81.738, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'A stream gauge on the Johns River north of Morganton exceeded its established flood stage after 4 to 6 inches of rain fell in the headwaters and in the Wilson Creek basin in about 24 hours. Multiple roads were flooded, including Old Johns River Rd, Johns River Rd, and Corpening Bridge Rd.');
INSERT INTO public.stormevents_east VALUES (787919, 201809, 9, 1540, 201809, 9, 1540, 131700, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '09-SEP-18 15:40:00', 'EST-5', '09-SEP-18 15:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'CHERRYVILLE', 1, 'ESE', 'CHERRYVILLE', 35.37, -81.36, 35.37, -81.36, 'Isolated thunderstorms developed over the North Carolina Piedmont during the afternoon. One of the storms produced brief severe weather in Gaston County.', 'County comms reported multiple trees blown down in the Cherryville area.');
INSERT INTO public.stormevents_east VALUES (783250, 201809, 6, 1603, 201809, 6, 1633, 130893, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'OKX', '06-SEP-18 16:03:00', 'EST-5', '06-SEP-18 16:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'SLATE HILL', 3, 'S', 'SLATE HILL', 41.34, -74.48, 41.3404, -74.4796, 'A cold front moving through a hot and humid environment triggered a line of showers and thunderstorms across the Lower Hudson Valley. In Orange County, this resulted in spotter reports of almost 2 inches of rain in 45 minutes, which resulted in isolated flash flooding.', 'Emergency Services reported flooding in Gardnerville due to 6-12 inches of running water over County Route 12 at Gardnerville Road. The road was briefly impassable.');
INSERT INTO public.stormevents_east VALUES (784172, 201809, 12, 1345, 201809, 12, 1430, 131087, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '12-SEP-18 13:45:00', 'EST-5', '12-SEP-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'NEW LONDON', 1, 'S', 'NEW LONDON', 41.3497, -72.1017, 41.3379, -72.0998, 'Showers and thunderstorms developed along a stationary front draped across southern Connecticut during the afternoon of September 12th. The 8am sounding from Upton, NY recorded a precipitable water value of 2.16 inches, a record for the date based on the Storm Prediction Center''s sounding climatology. This resulted in very heavy downpours and flash flooding over southeast Connecticut. A cooperative observer in Norwich reported 4.62 inches of rain with these storms, the bulk of which fell over a period of 2-3 hours.', 'Several roads were closed due to flooding in New London including Broad Street at Ledyard Street, Bank Street between Howard Street and Tilley Street, Bank Street at Truman Street, Pequot Avenu at Green Harbor Beach, and Garfield Avenue at Elm Street.');
INSERT INTO public.stormevents_east VALUES (770118, 201806, 18, 1829, 201806, 18, 1829, 128365, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '18-JUN-18 18:29:00', 'EST-5', '18-JUN-18 18:29:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'S', 'SODOM', 1, 'S', 'SODOM', 41.39, -73.6, 41.39, -73.6, 'A prefrontal trough ahead of a cold front approaching from the west brought severe weather to Southeastern New York.', 'Wires reported down across Star Ridge road near route 202.');
INSERT INTO public.stormevents_east VALUES (776752, 201807, 28, 2000, 201807, 28, 2200, 129676, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'ILM', '28-JUL-18 20:00:00', 'EST-5', '28-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'SSW', 'PENDERLEA', 2, 'N', 'PINEY WOOD', 34.5965, -78.0769, 34.5935, -78.0998, 'A stationary front produced slow moving storms and flash flooding.', 'High water was over the road on Shiloh Road at the Bee Branch near Penderlea.');
INSERT INTO public.stormevents_east VALUES (767641, 201807, 3, 1836, 201807, 3, 1836, 127755, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '03-JUL-18 18:36:00', 'EST-5', '03-JUL-18 18:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 5, 'SSE', 'HAMPTON SPRINGS', 5, 'SSE', 'HAMPTON SPRINGS', 30.02, -83.62, 30.02, -83.62, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down along Puckett Road.');
INSERT INTO public.stormevents_east VALUES (767642, 201807, 3, 1845, 201807, 3, 1845, 127755, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '03-JUL-18 18:45:00', 'EST-5', '03-JUL-18 18:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 2, 'NW', 'NASH', 2, 'NW', 'NASH', 30.47, -83.92, 30.47, -83.92, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'Fallen trees or limbs resulted in a power outage along Pineview Road.');
INSERT INTO public.stormevents_east VALUES (767678, 201807, 21, 1430, 201807, 21, 1430, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 14:30:00', 'EST-5', '21-JUL-18 14:30:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'SHIRED ISLAND', 0, 'N', 'SHIRED ISLAND', 29.39, -83.2, 29.39, -83.2, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees and power lines were blown down.');
INSERT INTO public.stormevents_east VALUES (767680, 201807, 21, 1440, 201807, 21, 1440, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '21-JUL-18 14:40:00', 'EST-5', '21-JUL-18 14:40:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'YELLOW JACKET', 0, 'N', 'YELLOW JACKET', 29.46, -83, 29.46, -83, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Trees and power lines were blown down.');
INSERT INTO public.stormevents_east VALUES (767760, 201807, 22, 1530, 201807, 22, 1530, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 15:30:00', 'EST-5', '22-JUL-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NNW', 'COOKS HAMMOCK', 1, 'NNW', 'COOKS HAMMOCK', 29.9328, -83.274, 29.9328, -83.274, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Fallen trees were reported along Highway 51.');
INSERT INTO public.stormevents_east VALUES (754317, 201807, 1, 1703, 201807, 1, 1705, 125774, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'ILN', '01-JUL-18 17:03:00', 'EST-5', '01-JUL-18 17:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 1, 'NE', 'GLEN JEAN', 1, 'NE', 'GLEN JEAN', 39.11, -82.97, 39.11, -82.97, 'Scattered thunderstorms developed during the afternoon hours in a hot and humid air mass that was in place across the Ohio Valley.', 'A tree was downed.');
INSERT INTO public.stormevents_east VALUES (767763, 201807, 22, 1630, 201807, 22, 1630, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 16:30:00', 'EST-5', '22-JUL-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'COOKS HAMMOCK', 0, 'N', 'COOKS HAMMOCK', 29.92, -83.27, 29.92, -83.27, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Fallen trees blocked the road near Cooks Hammock.');
INSERT INTO public.stormevents_east VALUES (754657, 201806, 20, 1727, 201806, 20, 1727, 125849, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '20-JUN-18 17:27:00', 'EST-5', '20-JUN-18 17:27:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNW', 'STOVALL', 3, 'NNW', 'STOVALL', 37.0419, -79.059, 37.0419, -79.059, 'Strong surface heating overcame westerly flow off the Blue Ridge to support a few brief severe thunderstorms across the Piedmont of south-central Virginia.', 'A tree was blown down by thunderstorm winds near the intersection of Rock Barn Road and McKeever Trail.');
INSERT INTO public.stormevents_east VALUES (768573, 201807, 22, 1945, 201807, 22, 1945, 127753, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 19:45:00', 'EST-5', '22-JUL-18 19:45:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 65, 'EG', NULL, NULL, 3, 'SW', 'WRAY', 3, 'SW', 'WRAY', 31.59, -83.09, 31.59, -83.09, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Numerous trees and power lines were blown down.');
INSERT INTO public.stormevents_east VALUES (767290, 201806, 3, 700, 201806, 3, 800, 127919, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '03-JUN-18 07:00:00', 'EST-5', '03-JUN-18 08:00:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'OLD COLD HARBOR', 2, 'NE', 'OLD COLD HARBOR', 37.6, -77.25, 37.6024, -77.2506, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flooding across portions of central and eastern Virginia.', 'Sinkhole was reported at Crown Hill Road.');
INSERT INTO public.stormevents_east VALUES (761531, 201806, 29, 1135, 201806, 29, 1135, 125964, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'CAR', '29-JUN-18 11:35:00', 'EST-5', '29-JUN-18 11:35:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 1, 'NW', 'GUERETTE', 1, 'NW', 'GUERETTE', 47.14, -68.33, 47.14, -68.33, 'An upper level disturbance crossing the region supported the development of thunderstorms across northern Maine during the early afternoon of the 29th. Isolated severe thunderstorms across northeast Aroostook county produced damaging winds. Small hail also accompanied some storms.', 'Several trees were toppled along Klein Road by wind gusts estimated at around 60 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (761532, 201806, 29, 1240, 201806, 29, 1240, 125964, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'CAR', '29-JUN-18 12:40:00', 'EST-5', '29-JUN-18 12:40:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 52, 'EG', NULL, NULL, 4, 'S', 'HAMLIN', 4, 'S', 'HAMLIN', 47.01, -67.81, 47.01, -67.81, 'An upper level disturbance crossing the region supported the development of thunderstorms across northern Maine during the early afternoon of the 29th. Isolated severe thunderstorms across northeast Aroostook county produced damaging winds. Small hail also accompanied some storms.', 'Three trees were toppled by wind gusts estimated at around 60 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (761533, 201806, 29, 1300, 201806, 29, 1300, 125964, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'CAR', '29-JUN-18 13:00:00', 'EST-5', '29-JUN-18 13:00:00', 0, 0, 0, 0, NULL, NULL, 'Post Office', 52, 'EG', NULL, NULL, 0, 'N', 'LIMESTONE', 0, 'N', 'LIMESTONE', 46.92, -67.82, 46.92, -67.82, 'An upper level disturbance crossing the region supported the development of thunderstorms across northern Maine during the early afternoon of the 29th. Isolated severe thunderstorms across northeast Aroostook county produced damaging winds. Small hail also accompanied some storms.', 'Trees were toppled on to power lines by wind gusts estimated at around 60 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (754316, 201807, 1, 1651, 201807, 1, 1653, 125774, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'ILN', '01-JUL-18 16:51:00', 'EST-5', '01-JUL-18 16:53:00', 0, 0, 0, 0, '3.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'SE', 'MILLERSTOWN', 2, 'SE', 'MILLERSTOWN', 40.13, -83.89, 40.13, -83.89, 'Scattered thunderstorms developed during the afternoon hours in a hot and humid air mass that was in place across the Ohio Valley.', 'A few trees were downed onto a road.');
INSERT INTO public.stormevents_east VALUES (768276, 201806, 11, 1907, 201806, 11, 1907, 128111, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '11-JUN-18 19:07:00', 'EST-5', '11-JUN-18 19:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'NE', 'OAK HILL', 1, 'NE', 'OAK HILL', 35.79, -81.76, 35.79, -81.76, 'Isolated thunderstorms developed during the afternoon across the North Carolina foothills. One of these storms produced occasional severe weather as it moved south across the far western Piedmont. Then, as a cold front moved southwest across the area throughout the evening, scattered to numerous showers and storms developed along it, producing additional brief severe weather.', 'Media reported multiple trees and power lines blown down in the Oak Hill area.');
INSERT INTO public.stormevents_east VALUES (768278, 201806, 11, 1920, 201806, 11, 1920, 128111, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'GSP', '11-JUN-18 19:20:00', 'EST-5', '11-JUN-18 19:20:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 2, 'NNE', 'MORGANTON', 2, 'NNE', 'MORGANTON', 35.78, -81.69, 35.78, -81.69, 'Isolated thunderstorms developed during the afternoon across the North Carolina foothills. One of these storms produced occasional severe weather as it moved south across the far western Piedmont. Then, as a cold front moved southwest across the area throughout the evening, scattered to numerous showers and storms developed along it, producing additional brief severe weather.', 'Trained spotter reported 3/4 inch hail on Valley View St at Highway 18.');
INSERT INTO public.stormevents_east VALUES (754659, 201806, 20, 1846, 201806, 20, 1846, 125849, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '20-JUN-18 18:46:00', 'EST-5', '20-JUN-18 18:46:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'ESE', 'BARNESVILLE', 1, 'ESE', 'BARNESVILLE', 36.8119, -78.5784, 36.8119, -78.5784, 'Strong surface heating overcame westerly flow off the Blue Ridge to support a few brief severe thunderstorms across the Piedmont of south-central Virginia.', 'Four trees were blown down by thunderstorm winds along Highway 92 between Highway 15 and Godseys Lane.');
INSERT INTO public.stormevents_east VALUES (753476, 201804, 16, 124, 201804, 16, 124, 125629, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 01:24:00', 'EST-5', '16-APR-18 01:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 6, 'S', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 6, 'S', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 36.89, -76.34, 36.89, -76.34, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the James River.', 'Wind gust of 41 knots was measured at South Craney Island.');
