INSERT INTO public.stormevents_east VALUES (753743, 201804, 16, 336, 201804, 16, 336, 125632, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 03:36:00', 'EST-5', '16-APR-18 03:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 0, 'N', 'RUDEE INLET', 0, 'N', 'RUDEE INLET', 36.83, -75.97, 36.83, -75.97, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 42 knots was measured at Rudee Inlet.');
INSERT INTO public.stormevents_east VALUES (753750, 201804, 16, 337, 201804, 16, 337, 125632, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 03:37:00', 'EST-5', '16-APR-18 03:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 48, 'MG', NULL, NULL, 0, 'N', 'CAPE HENRY', 0, 'N', 'CAPE HENRY', 36.92, -76, 36.92, -76, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 48 knots was measured at Cape Henry.');
INSERT INTO public.stormevents_east VALUES (753754, 201804, 16, 356, 201804, 16, 356, 125632, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 03:56:00', 'EST-5', '16-APR-18 03:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 51, 'MG', NULL, NULL, 0, 'N', 'CHESAPEAKE LIGHT C-MAN STATION (CHLV2)', 0, 'N', 'CHESAPEAKE LIGHT C-MAN STATION (CHLV2)', 36.9, -75.71, 36.9, -75.71, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 51 knots was measured at Chesapeake Light.');
INSERT INTO public.stormevents_east VALUES (753755, 201804, 16, 410, 201804, 16, 410, 125632, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 04:10:00', 'EST-5', '16-APR-18 04:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'SANDBRIDGE', 0, 'N', 'SANDBRIDGE', 36.7, -75.92, 36.7, -75.92, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 36 knots was measured at Sandbridge.');
INSERT INTO public.stormevents_east VALUES (768918, 201806, 18, 1627, 201806, 18, 1627, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:27:00', 'EST-5', '18-JUN-18 16:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'SCRANTON', 1, 'E', 'SCRANTON', 41.42, -75.66, 41.42, -75.66, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees which blocked some roadways.');
INSERT INTO public.stormevents_east VALUES (768919, 201806, 18, 1650, 201806, 18, 1650, 128202, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'BGM', '18-JUN-18 16:50:00', 'EST-5', '18-JUN-18 16:50:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'ESE', 'LAKEVILLE', 1, 'ESE', 'LAKEVILLE', 41.42, -75.26, 41.42, -75.26, 'A cold front dropped south into New York State the afternoon and evening of the 18th. This front eventually moved into northern Pennsylvania during the overnight hours from the 18th to the 19th. This front triggered a round of strong to severe thunderstorms which  moved through central New York and northeast Pennsylvania. The thunderstorms produced damaging winds which knocked down many trees and power lines.', 'Thunderstorm winds knocked down trees and power lines.');
INSERT INTO public.stormevents_east VALUES (754656, 201806, 20, 1720, 201806, 20, 1720, 125849, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '20-JUN-18 17:20:00', 'EST-5', '20-JUN-18 17:20:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'N', 'BROOKNEAL HOLT ARPT', 1, 'N', 'BROOKNEAL HOLT ARPT', 37.0894, -79.0706, 37.0894, -79.0706, 'Strong surface heating overcame westerly flow off the Blue Ridge to support a few brief severe thunderstorms across the Piedmont of south-central Virginia.', 'One tree and a piece of fencing was blown down by thunderstorm winds along Whitehall Road.');
INSERT INTO public.stormevents_east VALUES (754661, 201806, 20, 2136, 201806, 20, 2138, 125849, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'RNK', '20-JUN-18 21:36:00', 'EST-5', '20-JUN-18 21:38:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'SE', 'LOCH LAIRD', 1, 'SE', 'LOCH LAIRD', 37.7181, -79.3675, 37.7153, -79.3623, 'Strong surface heating overcame westerly flow off the Blue Ridge to support a few brief severe thunderstorms across the Piedmont of south-central Virginia.', 'A tree was blown down by thunderstorm winds onto a car on 2nd Street, while another tree was blown down onto a home on Linden Avenue.');
INSERT INTO public.stormevents_east VALUES (768921, 201806, 24, 1645, 201806, 24, 1645, 128203, 'PENNSYLVANIA', 42, 2018, 'June', 'Hail', 'BGM', '24-JUN-18 16:45:00', 'EST-5', '24-JUN-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'N', 'FOREST CITY', 0, 'N', 'FOREST CITY', 41.65, -75.47, 41.65, -75.47, 'An area of low pressure moved across Pennsylvania on the 24th triggered a couple severe thunderstorms in northeast Pennsylvania.', NULL);
INSERT INTO public.stormevents_east VALUES (770850, 201806, 20, 1751, 201806, 20, 1752, 126057, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '20-JUN-18 17:51:00', 'EST-5', '20-JUN-18 17:52:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'LURAY', 2, 'SSW', 'LURAY', 32.8, -81.24, 32.8, -81.24, 'A trough of low pressure encountered an unstable airmass over Southeast South Carolina, which led to severe thunderstorms during late afternoon hours.', 'The South Carolina Highway Patrol reported a tree down at Columbia Highway and Industry Drive.');
INSERT INTO public.stormevents_east VALUES (770863, 201806, 23, 1854, 201806, 23, 1855, 126059, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '23-JUN-18 18:54:00', 'EST-5', '23-JUN-18 18:55:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'GRAYS REEF BUOY (41008)', 0, 'N', 'GRAYS REEF BUOY (41008)', 31.4, -80.87, 31.4, -80.87, 'Strong heating and moist conditions over land helped produce a cluster of thunderstorms late afternoon and evening inland, which eventually shifted off the Southeast Georgia coast.', 'Buoy 41008 recorded a 41 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (770864, 201806, 23, 1900, 201806, 23, 1901, 126059, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '23-JUN-18 19:00:00', 'EST-5', '23-JUN-18 19:01:00', 0, 0, 0, 0, NULL, NULL, 'Official NWS Observations', 36, 'MG', NULL, NULL, 6, 'N', 'ALTAMAHA SOUND', 6, 'N', 'ALTAMAHA SOUND', 31.41, -81.31, 31.41, -81.31, 'Strong heating and moist conditions over land helped produce a cluster of thunderstorms late afternoon and evening inland, which eventually shifted off the Southeast Georgia coast.', 'The NERRS site on Sapelo Island recorded a 36 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (770919, 201806, 25, 42, 201806, 25, 43, 126062, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '25-JUN-18 00:42:00', 'EST-5', '25-JUN-18 00:43:00', 0, 0, 0, 0, NULL, NULL, 'Official NWS Observations', 34, 'MG', NULL, NULL, 3, 'WNW', 'TYBEE ISLAND', 3, 'WNW', 'TYBEE ISLAND', 32.0281, -80.8834, 32.0281, -80.8834, 'A warm and moist atmosphere in combination with a sea breeze circulation and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'The NOS tide gauge at Fort Pulaski recorded at 34 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (770920, 201806, 25, 49, 201806, 25, 50, 126062, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '25-JUN-18 00:49:00', 'EST-5', '25-JUN-18 00:50:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 1, 'N', 'TYBEE ISLAND', 1, 'N', 'TYBEE ISLAND', 32.0189, -80.841, 32.0189, -80.841, 'A warm and moist atmosphere in combination with a sea breeze circulation and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'The Weatherflow site on the north end of Tybee Island recorded a 36 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (770930, 201806, 25, 108, 201806, 25, 109, 126062, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'CHS', '25-JUN-18 01:08:00', 'EST-5', '25-JUN-18 01:09:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 9, 'E', 'ISLE OF PALMS', 9, 'E', 'ISLE OF PALMS', 32.81, -79.63, 32.81, -79.63, 'A warm and moist atmosphere in combination with a sea breeze circulation and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'The Capers nearshore Buoy recorded a wind gust of 37 knots.');
INSERT INTO public.stormevents_east VALUES (770881, 201806, 24, 2311, 201806, 24, 2312, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 23:11:00', 'EST-5', '24-JUN-18 23:12:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 5, 'ESE', 'SNIDERS XRDS', 5, 'ESE', 'SNIDERS XRDS', 32.86, -80.76, 32.86, -80.76, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The South Carolina Highway Patrol reported a tree down on Cane Branch Road near the intersection with Pellum Road.');
INSERT INTO public.stormevents_east VALUES (770882, 201806, 24, 2311, 201806, 24, 2312, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 23:11:00', 'EST-5', '24-JUN-18 23:12:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'E', 'GRAYS', 2, 'E', 'GRAYS', 32.67, -80.98, 32.67, -80.98, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'Law enforcement reported a tree down on Highway 3 east of Grays.');
INSERT INTO public.stormevents_east VALUES (770885, 201806, 24, 2316, 201806, 24, 2317, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 23:16:00', 'EST-5', '24-JUN-18 23:17:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'SW', 'WALTERBORO', 4, 'SW', 'WALTERBORO', 32.86, -80.71, 32.86, -80.71, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'Law enforcement reported two trees down across Peniel Road, including one at the intersection with Hendersonville Highway.');
INSERT INTO public.stormevents_east VALUES (770886, 201806, 24, 2318, 201806, 24, 2319, 126060, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '24-JUN-18 23:18:00', 'EST-5', '24-JUN-18 23:19:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'PINELAND', 1, 'E', 'PINELAND', 32.6, -81.16, 32.6, -81.16, 'Numerous thunderstorms associated with a Mesoscale Convective Vortex (MCV) west of the area shifted into Southeast South Carolina, eventually encountering an environment with dry mid-level air and resulting in damaging wind gusts over the region.', 'The South Carolina Highway Patrol reported a tree down on Highway 601 near Pineland.');
INSERT INTO public.stormevents_east VALUES (770931, 201806, 25, 1507, 201806, 25, 1508, 126063, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '25-JUN-18 15:07:00', 'EST-5', '25-JUN-18 15:08:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'PRITCHARDVILLE', 2, 'E', 'PRITCHARDVILLE', 32.23, -80.93, 32.23, -80.93, 'A warm and moist atmosphere in combination with a sea breeze circulation shifting inland  and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'The Beaufort 911 Call Center reported a tree down on Rose Dhu Creek Plantation.');
INSERT INTO public.stormevents_east VALUES (770957, 201806, 25, 1525, 201806, 25, 1526, 126063, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '25-JUN-18 15:25:00', 'EST-5', '25-JUN-18 15:26:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'GIVHANS', 1, 'SW', 'GIVHANS', 33.01, -80.34, 33.01, -80.34, 'A warm and moist atmosphere in combination with a sea breeze circulation shifting inland  and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'The Dorchester County 911 Call Center reported trees down near the intersection of Highway 61 and Highway 27.');
INSERT INTO public.stormevents_east VALUES (770960, 201806, 25, 1526, 201806, 25, 1527, 126063, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CHS', '25-JUN-18 15:26:00', 'EST-5', '25-JUN-18 15:27:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NNE', 'GIVHANS', 2, 'NNE', 'GIVHANS', 33.05, -80.32, 33.05, -80.32, 'A warm and moist atmosphere in combination with a sea breeze circulation shifting inland  and cold front approaching from the north, supported an environment capable of producing numerous strong to severe thunderstorms across the region.', 'Law enforcement reported a tree down near the intersection of Highway 27 and Bridlewood Farms Parkway.');
INSERT INTO public.stormevents_east VALUES (767784, 201806, 18, 1531, 201806, 18, 1536, 128012, 'MAINE', 23, 2018, 'June', 'Thunderstorm Wind', 'GYX', '18-JUN-18 15:31:00', 'EST-5', '18-JUN-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NE', 'PORTERFIELD', 1, 'NE', 'PORTERFIELD', 43.8759, -70.913, 43.8759, -70.913, 'Strong convection developed on a pre-frontal trough ahead of an approaching cold front on the afternoon of June 18th. A deep layer of moderate to strong shear accompanied this boundary as it pushed in from the west. Moderate helicity values resulted in good rotation with some of these storms and at least one tornado was confirmed along with several reports of funnel clouds. The majority of these storms produced straight line wind damage.', 'A severe thunderstorm snapped trees and power poles in Porterfield.');
INSERT INTO public.stormevents_east VALUES (798767, 201811, 15, 500, 201811, 15, 900, 133506, 'GEORGIA', 13, 2018, 'November', 'Flash Flood', 'FFC', '15-NOV-18 05:00:00', 'EST-5', '15-NOV-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'HILLMAN', 2, 'N', 'HILLMAN', 33.6261, -82.8255, 33.6279, -82.8033, 'An upper level low pressure system, combined with a series of weak disturbances, provided several waves of precipitation the week of November 11th, producing periods of heavy rain over north and central Georgia. Overnight November 14th into November 15th was particularly wet over east central Georgia as a band of heavy rainfall set up over the area, dumping 4 to 5 inches of rain along a line from Rochelle, northeast to Irwinton, to Washington. These rainfall amounts combined with the already saturated soils to produce isolated flash flooding.', 'Emergency Manager reported Silas Mercer Road was damaged due to flowing water from flash flooding. Radar estimates indicate that 3 to 4 inches, and possibly locally higher amounts, were observed in this area.');
INSERT INTO public.stormevents_east VALUES (770111, 201806, 18, 1735, 201806, 18, 1735, 128365, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'OKX', '18-JUN-18 17:35:00', 'EST-5', '18-JUN-18 17:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'ESE', 'PINE BUSH', 2, 'ESE', 'PINE BUSH', 41.59, -74.27, 41.59, -74.27, 'A prefrontal trough ahead of a cold front approaching from the west brought severe weather to Southeastern New York.', 'A tree down across state route 52 near Drexel Drive.');
INSERT INTO public.stormevents_east VALUES (774392, 201807, 28, 1725, 201807, 28, 1725, 129228, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '28-JUL-18 17:25:00', 'EST-5', '28-JUL-18 17:25:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 2, 'WSW', '(LIZ)LORING AFB LIME', 2, 'WSW', '(LIZ)LORING AFB LIME', 46.94, -67.92, 46.94, -67.92, 'A cold front crossed the region through the afternoon and evening of the 28th. Thunderstorms developed in advance of the front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Several trees were toppled by wind gusts estimated at 60 mph. One of the trees fell on a house damaging the roof.');
INSERT INTO public.stormevents_east VALUES (774412, 201807, 10, 1525, 201807, 10, 1525, 129227, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '10-JUL-18 15:25:00', 'EST-5', '10-JUL-18 15:25:00', 0, 0, 0, 0, NULL, NULL, 'Park/Forest Service', 56, 'EG', NULL, NULL, 13, 'SW', 'GRAND LAKE STREAM', 13, 'SW', 'GRAND LAKE STREAM', 45.0625, -67.983, 45.0625, -67.983, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Trees were toppled along 42-00-0 Road near Fifth Machias Lake by wind gusts estimated at 65 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (774413, 201807, 10, 1530, 201807, 10, 1530, 129227, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'CAR', '10-JUL-18 15:30:00', 'EST-5', '10-JUL-18 15:30:00', 0, 0, 0, 0, NULL, NULL, 'Park/Forest Service', 56, 'EG', NULL, NULL, 11, 'WNW', 'WESLEY', 11, 'WNW', 'WESLEY', 45.0109, -67.8579, 45.0109, -67.8579, 'A cold front and upper level disturbance crossed the region during the afternoon of the 10th. Thunderstorms developed in advance of the cold front. Some of the thunderstorms became severe producing damaging winds and large hail.', 'Numerous trees were toppled near the Machias River by wind gusts estimated at 65 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (744118, 201804, 23, 1950, 201804, 23, 1950, 123974, 'GEORGIA', 13, 2018, 'April', 'Flash Flood', 'FFC', '23-APR-18 19:50:00', 'EST-5', '23-APR-18 19:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'ESE', 'GRESHAMVILLE', 4, 'ESE', 'GRESHAMVILLE', 33.6145, -83.277, 33.6021, -83.2681, 'A strong cold front associated with a deep upper-level low swept across the region. Moderate instability and strong mid-level winds combined to produce scattered severe thunderstorms across portions of central and east Georgia.', 'Greene County Emergency Manager reported water covering Quail Trail Road near  Arrowhead Road, along the east bank of upper portion of Lake Oconee.');
INSERT INTO public.stormevents_east VALUES (757524, 201807, 5, 1340, 201807, 5, 1342, 126347, 'OHIO', 39, 2018, 'July', 'Hail', 'ILN', '05-JUL-18 13:40:00', 'EST-5', '05-JUL-18 13:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 0.75, NULL, NULL, NULL, 1, 'W', 'OUTVILLE', 1, 'W', 'OUTVILLE', 40, -82.61, 40, -82.61, 'Scattered thunderstorms developed along a cold front that was moving through the Ohio Valley. A few of the storms produced large hail and damaging winds.', NULL);
INSERT INTO public.stormevents_east VALUES (767764, 201807, 22, 1630, 201807, 22, 1630, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 16:30:00', 'EST-5', '22-JUL-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'ESE', 'PERRY', 2, 'ESE', 'PERRY', 30.0992, -83.5513, 30.0992, -83.5513, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'A tree was blown down near the intersection of Highway 27 and Walter Schmidt Lane.');
INSERT INTO public.stormevents_east VALUES (767772, 201807, 22, 1705, 201807, 22, 1705, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 17:05:00', 'EST-5', '22-JUL-18 17:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'E', 'SHAMROCK', 1, 'E', 'SHAMROCK', 29.64, -83.13, 29.64, -83.13, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'Strong winds resulted in a power outage.');
INSERT INTO public.stormevents_east VALUES (767774, 201807, 22, 1730, 201807, 22, 1730, 127752, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 17:30:00', 'EST-5', '22-JUL-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 3, 'E', 'ALMA', 3, 'E', 'ALMA', 30.6105, -83.8418, 30.6105, -83.8418, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'A tree was blown down across the road along Boston Highway.');
INSERT INTO public.stormevents_east VALUES (768562, 201807, 22, 1715, 201807, 22, 1715, 127753, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'TAE', '22-JUL-18 17:15:00', 'EST-5', '22-JUL-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'METCALF', 1, 'W', 'METCALF', 30.7, -83.99, 30.7, -83.99, 'Scattered to numerous showers and thunderstorms occurred across the area.  This was an unusual, well organized severe weather event given the time of year.  The threat for some type of severe weather during the July 21-22 period was well advertised by the models a few days in advance, although the exact times of day that would be affected varied from run to run.  A special 18z KTAE sounding from July 22 revealed SBCAPE around 4500 j/kg with 0-6 km shear of 34 knots, which is unusually high for summer.  Some mid-level dry air also contributed to a favorable environment for damaging wind.  The end result was numerous reports of severe weather across the region.', 'There were a few reports of trees and power lines down in Thomas county.');
INSERT INTO public.stormevents_east VALUES (767291, 201806, 3, 700, 201806, 3, 800, 127919, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '03-JUN-18 07:00:00', 'EST-5', '03-JUN-18 08:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'GUM TREE', 2, 'SSW', 'GUM TREE', 37.8, -77.49, 37.7984, -77.4889, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flooding across portions of central and eastern Virginia.', 'Cross Corner Road was washed out.');
INSERT INTO public.stormevents_east VALUES (767293, 201806, 3, 1830, 201806, 5, 630, 127919, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '03-JUN-18 18:30:00', 'EST-5', '05-JUN-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'SUPPLY', 1, 'ENE', 'IRAVILLE', 38.12, -77.11, 38.0867, -77.0549, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flooding across portions of central and eastern Virginia.', 'Six to eight inches of water was reported across portions of Route 17 between Port Royal and Loretto.');
INSERT INTO public.stormevents_east VALUES (767297, 201806, 3, 415, 201806, 5, 630, 127919, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '03-JUN-18 04:15:00', 'EST-5', '05-JUN-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'HOLDCROFT', 2, 'NNW', 'HOLDCROFT', 37.3921, -76.9444, 37.4042, -76.9411, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flooding across portions of central and eastern Virginia.', 'Several roads were flooded.');
