INSERT INTO public.stormevents_east VALUES (776750, 201807, 28, 2000, 201807, 28, 2200, 129676, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'ILM', '28-JUL-18 20:00:00', 'EST-5', '28-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'WNW', 'BURGAW', 2, 'W', 'BURGAW', 34.5666, -77.9787, 34.5546, -77.9696, 'A stationary front produced slow moving storms and flash flooding.', 'Water was flowing over the road on Penderlea Highway at Long Creek.');
INSERT INTO public.stormevents_east VALUES (776751, 201807, 28, 2000, 201807, 28, 2200, 129676, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'ILM', '28-JUL-18 20:00:00', 'EST-5', '28-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNW', 'WILLARD', 3, 'NNW', 'WILLARD', 34.7201, -77.9902, 34.7185, -77.9965, 'A stationary front produced slow moving storms and flash flooding.', 'Water was flowing over the road on Willard Railroad Rd at Rockfish Creek near Wallace.');
INSERT INTO public.stormevents_east VALUES (776755, 201807, 30, 920, 201807, 30, 1200, 129679, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'ILM', '30-JUL-18 09:20:00', 'EST-5', '30-JUL-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'MYRTLE GROVE', 1, 'WSW', 'MYRTLE GROVE', 34.1258, -77.8997, 34.1202, -77.9022, 'Heavy rain on already saturated soil produced flash flooding.', 'A house on Carolina Beach Drive had two feet of water in it. Flooding was reported on Canal Drive and South Lake Park Drive.');
