INSERT INTO public.stormevents_east VALUES (776757, 201807, 1, 1254, 201807, 1, 1307, 129680, 'GULF OF MEXICO', 85, 2018, 'July', 'Waterspout', 'KEY', '01-JUL-18 12:54:00', 'EST-5', '01-JUL-18 13:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 3, 'WNW', 'BIG PINE KEY', 3, 'WNW', 'BIG PINE KEY', 24.7134, -81.4169, 24.7134, -81.4169, 'A couple waterspouts were observed in association with a cumulus cloud line extending along the north side of the Lower Florida Keys.', 'Two thin rope-like waterspouts were observed in the nearshore Gulf waters east of Big Torch Key.');
INSERT INTO public.stormevents_east VALUES (776758, 201807, 1, 1334, 201807, 1, 1334, 129680, 'GULF OF MEXICO', 85, 2018, 'July', 'Waterspout', 'KEY', '01-JUL-18 13:34:00', 'EST-5', '01-JUL-18 13:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 5, 'WNW', 'SUMMERLAND KEY', 5, 'WNW', 'SUMMERLAND KEY', 24.6811, -81.5306, 24.6811, -81.5306, 'A couple waterspouts were observed in association with a cumulus cloud line extending along the north side of the Lower Florida Keys.', 'A very thin waterspout was observed between Cudjoe and Upper Sugarloaf Keys on the Gulf of Mexico side of the Overseas Highway.  The condensation funnel cloud extended from the cloud base to the horizon.');
INSERT INTO public.stormevents_east VALUES (776759, 201807, 3, 724, 201807, 3, 729, 129681, 'GULF OF MEXICO', 85, 2018, 'July', 'Waterspout', 'KEY', '03-JUL-18 07:24:00', 'EST-5', '03-JUL-18 07:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 5, 'ENE', 'KEY LARGO', 5, 'ENE', 'KEY LARGO', 25.11, -80.37, 25.11, -80.37, 'A deep trough of low pressure was located between the southeast United States and the Bahamas.  Tropical moisture combined with a deep northeast wind flow promoted cloud line development along most of the Florida Keys, were a few waterspouts were observed.', 'A mature waterspout with an attendant spray ring was observed over Hawk Channel adjacent to a heavy rain shower, about 5 miles south-southeast of the Jewfish Creek Bridge.');
INSERT INTO public.stormevents_east VALUES (779088, 201809, 21, 1749, 201809, 21, 1749, 129338, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'CTP', '21-SEP-18 17:49:00', 'EST-5', '21-SEP-18 17:49:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 5, 'S', 'PITTSFIELD ARPT', 5, 'S', 'PITTSFIELD ARPT', 41.7523, -79.3632, 41.7523, -79.3632, 'A cold front pushed into an unseasonably warm and humid airmass over northwestern Pennsylvania during the evening of September 21, 2018. Moderate shear and CAPE were observed, and the area was under an Enhanced risk from SPC. Farther to the east, a moist southeasterly flow maintained low clouds through the day and conditions were much more stable.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree and wires along Davey Hill Road.');
INSERT INTO public.stormevents_east VALUES (779089, 201809, 21, 1821, 201809, 21, 1821, 129338, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'CTP', '21-SEP-18 18:21:00', 'EST-5', '21-SEP-18 18:21:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'SE', 'SOUTH BRADFORD', 0, 'SE', 'SOUTH BRADFORD', 41.9256, -78.6655, 41.9256, -78.6655, 'A cold front pushed into an unseasonably warm and humid airmass over northwestern Pennsylvania during the evening of September 21, 2018. Moderate shear and CAPE were observed, and the area was under an Enhanced risk from SPC. Farther to the east, a moist southeasterly flow maintained low clouds through the day and conditions were much more stable.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in Bradford Township.');
INSERT INTO public.stormevents_east VALUES (779090, 201809, 21, 1828, 201809, 21, 1828, 129338, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'CTP', '21-SEP-18 18:28:00', 'EST-5', '21-SEP-18 18:28:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 1, 'E', 'LEWIS RUN', 1, 'E', 'LEWIS RUN', 41.8686, -78.6589, 41.8686, -78.6589, 'A cold front pushed into an unseasonably warm and humid airmass over northwestern Pennsylvania during the evening of September 21, 2018. Moderate shear and CAPE were observed, and the area was under an Enhanced risk from SPC. Farther to the east, a moist southeasterly flow maintained low clouds through the day and conditions were much more stable.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires near Lewis Run.');
