INSERT INTO public.stormevents_east VALUES (749826, 201803, 30, 1500, 201803, 30, 1500, 125023, 'ATLANTIC NORTH', 88, 2018, 'March', 'Marine Thunderstorm Wind', 'LWX', '30-MAR-18 15:00:00', 'EST-5', '30-MAR-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'LEWISETTA (LWS)', 0, 'N', 'LEWISETTA (LWS)', 38, -76.47, 38, -76.47, 'A strong cold front passed through. Gusty showers developed along and ahead of the boundary.', 'A wind gust of 34 knots was reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (751017, 201804, 15, 1110, 201804, 15, 1110, 125220, 'SOUTH CAROLINA', 45, 2018, 'April', 'Hail', 'GSP', '15-APR-18 11:10:00', 'EST-5', '15-APR-18 11:10:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.88, NULL, NULL, NULL, 3, 'SE', '(GRD)GREENWOOD CO AR', 3, 'SE', '(GRD)GREENWOOD CO AR', 34.22, -82.12, 34.22, -82.12, 'Scattered to numerous afternoon thunderstorms developed ahead of a cold front from late morning through the afternoon across Upstate South Carolina. Several of the storms produced severe weather in the form of large hail and locally damaging winds.', 'Public reported nickel size hail.');
INSERT INTO public.stormevents_east VALUES (760018, 201807, 22, 2310, 201807, 23, 355, 126773, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PHI', '22-JUL-18 23:10:00', 'EST-5', '23-JUL-18 03:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'HARMONY HILL', 1, 'WNW', 'HARMONY HILL', 39.9721, -75.682, 39.9876, -75.7015, 'Showers with heavy downpours occurred in southeastern Pennsylvania during the afternoon and evening hours of July 22, 2018.  Rainfall totals of 2 to 4 inches were reported.', 'Moderate flooding occurred along the east branch of the Brandywine Creek below Downingtown.');
INSERT INTO public.stormevents_east VALUES (760021, 201807, 22, 2020, 201807, 22, 2220, 126773, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PHI', '22-JUL-18 20:20:00', 'EST-5', '22-JUL-18 22:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BLANDON', 1, 'WNW', 'BASKET', 40.4113, -75.8801, 40.3839, -75.8288, 'Showers with heavy downpours occurred in southeastern Pennsylvania during the afternoon and evening hours of July 22, 2018.  Rainfall totals of 2 to 4 inches were reported.', 'Flood waters caused significant damage to the foundation of a house in Alsace Township.');
INSERT INTO public.stormevents_east VALUES (760024, 201807, 22, 2120, 201807, 22, 2320, 126773, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PHI', '22-JUL-18 21:20:00', 'EST-5', '22-JUL-18 23:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'CETRONIA', 1, 'WNW', 'CETRONIA', 40.5799, -75.5414, 40.5862, -75.5547, 'Showers with heavy downpours occurred in southeastern Pennsylvania during the afternoon and evening hours of July 22, 2018.  Rainfall totals of 2 to 4 inches were reported.', 'Several roads were flooded in South Whitehall Township.');
INSERT INTO public.stormevents_east VALUES (760673, 201807, 27, 1324, 201807, 27, 1324, 126913, 'DELAWARE', 10, 2018, 'July', 'Thunderstorm Wind', 'PHI', '27-JUL-18 13:24:00', 'EST-5', '27-JUL-18 13:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'DEWEY BEACH', 1, 'WSW', 'DEWEY BEACH', 38.6954, -75.0796, 38.6954, -75.0796, 'Severe thunderstorms impacted the area and caused wind damage.', 'Utility poles and trees down near intersections of Dodd Ave and Salisbury Street. Roof damage to a house was also reported. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (760674, 201807, 27, 1710, 201807, 27, 1710, 126915, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'PHI', '27-JUL-18 17:10:00', 'EST-5', '27-JUL-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'KILBY CORNER', 1, 'W', 'KILBY CORNER', 39.68, -76.16, 39.68, -76.16, 'Severe thunderstorms impacted the area and caused wind damage.', 'Trees and wires down in a few locations. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (767037, 201807, 23, 1138, 201807, 23, 1140, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Thunderstorm Wind', 'CAE', '23-JUL-18 11:38:00', 'EST-5', '23-JUL-18 11:40:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 55, 'EG', NULL, NULL, 1, 'SE', 'LYKESLAND', 1, 'SE', 'LYKESLAND', 33.92, -80.89, 33.92, -80.89, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Several trees down near Hopkins.');
INSERT INTO public.stormevents_east VALUES (760872, 201807, 22, 1726, 201807, 22, 1730, 126936, 'PENNSYLVANIA', 42, 2018, 'July', 'Tornado', 'PHI', '22-JUL-18 17:26:00', 'EST-5', '22-JUL-18 17:30:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NE', 'SAEGERSVILLE', 1, 'N', 'SAEGERSVILLE', 40.7074, -75.6665, 40.7151, -75.6781, 'A weak EF-0 tornado occurred on this day near Heidelberg Township in northern Lehigh County, Pennsylvania. A closed upper low centered over the Ohio Valley and a filling surface low rotating around the upper low near Lake Ontario helped initiate weak thunderstorms and heavy rainfall across east-central Pennsylvania. Enough instability allowed for several strong to severe thunderstorms to form across the Lehigh Valley on this afternoon in the wake of a strong and progressive coastal low that pivoted northward around the closed upper-low.', 'A weak tornado occurred on the evening of July 22, 2018 in |Heidelberg Township, PA. The well defined path through the corn|field and twisted nature of the tree damage and eye witness |accounts helped to determine this was tornadic damage. The tornado was brief and moved northwest for around 0.8 miles. Damage started with several small trees and limbs being downed along Church Road near the Heidelberg Church. Further west, areas of corn were blown over, with areas each being blown over in several different directions, near some solar panels at the Heidel Hollow Farm. There was also damage to sheet metal on the sides and roof of a barn at the farm. These areas of damage fell in a relatively straight line.');
INSERT INTO public.stormevents_east VALUES (775617, 201807, 6, 1325, 201807, 6, 1325, 129461, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'AKQ', '06-JUL-18 13:25:00', 'EST-5', '06-JUL-18 13:25:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'S', 'PEARY', 1, 'S', 'PEARY', 37.34, -76.28, 37.34, -76.28, 'Isolated severe thunderstorm in advance of a cold front produced damaging winds across portions of eastern Virginia.', 'Trees were downed at New Point RV Resort.');
INSERT INTO public.stormevents_east VALUES (760080, 201807, 26, 904, 201807, 26, 904, 126799, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'TBW', '26-JUL-18 09:04:00', 'EST-5', '26-JUL-18 09:04:00', 0, 0, 0, 0, '25.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'NE', 'CRYSTAL BEACH', 1, 'NE', 'CRYSTAL BEACH', 28.091, -82.762, 28.091, -82.762, 'Scattered thunderstorms developed over the eastern Gulf and moved onshore throughout the day. Lightning strikes from some of these storms damaged at least three buildings in Pinellas County.', 'A fire reported at a house in Palm Harbor that was suspected to be caused by a lightning strike.');
INSERT INTO public.stormevents_east VALUES (767038, 201807, 23, 1140, 201807, 23, 1143, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Thunderstorm Wind', 'CAE', '23-JUL-18 11:40:00', 'EST-5', '23-JUL-18 11:43:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'SW', 'LEESBURG', 3, 'SW', 'LEESBURG', 34, -80.74, 34, -80.74, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Trees down near the intersection of Old Leesburg Rd and Congress Rd.');
INSERT INTO public.stormevents_east VALUES (758901, 201807, 20, 1557, 201807, 20, 1557, 126603, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'JKL', '20-JUL-18 15:57:00', 'EST-5', '20-JUL-18 15:57:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 53, 'EG', NULL, NULL, 2, 'SSW', 'BOWEN', 2, 'SSW', 'BOWEN', 37.82, -83.78, 37.82, -83.78, 'Multiple rounds of severe storms produced wind damage across portions of eastern Kentucky during the afternoon and evening hours of July 20, 2018, extending into the early morning hours of July 21. The hardest hit areas were in Montgomery County, where Emergency Management reported that 47 roads were closed at one point due to downed trees and power lines resulting in nearly 4,600 power outages. Additionally, a disaster declaration was made for the county as multiple buildings sustained damage. These included a tobacco warehouse that had its roof blown off as well as��a hotel in Mount Sterling whose sign and building both sustained damage from severe straight-line winds.', 'A Skywarn storm spotter reported a tree and large limb were blown down near Stanton.');
INSERT INTO public.stormevents_east VALUES (758902, 201807, 20, 1610, 201807, 20, 1610, 126603, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'JKL', '20-JUL-18 16:10:00', 'EST-5', '20-JUL-18 16:10:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 54, 'EG', NULL, NULL, 1, 'SE', 'MOREHEAD ROWAN ARPT', 1, 'SE', 'MOREHEAD ROWAN ARPT', 38.12, -83.52, 38.12, -83.52, 'Multiple rounds of severe storms produced wind damage across portions of eastern Kentucky during the afternoon and evening hours of July 20, 2018, extending into the early morning hours of July 21. The hardest hit areas were in Montgomery County, where Emergency Management reported that 47 roads were closed at one point due to downed trees and power lines resulting in nearly 4,600 power outages. Additionally, a disaster declaration was made for the county as multiple buildings sustained damage. These included a tobacco warehouse that had its roof blown off as well as��a hotel in Mount Sterling whose sign and building both sustained damage from severe straight-line winds.', 'Dispatch reported trees were blown down along Kentucky Highway 801 south of Farmers along Cave Run Lake.');
INSERT INTO public.stormevents_east VALUES (758905, 201807, 20, 1620, 201807, 20, 1620, 126603, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'JKL', '20-JUL-18 16:20:00', 'EST-5', '20-JUL-18 16:20:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'WRIGLEY', 1, 'WNW', 'WRIGLEY', 38.03, -83.29, 38.03, -83.29, 'Multiple rounds of severe storms produced wind damage across portions of eastern Kentucky during the afternoon and evening hours of July 20, 2018, extending into the early morning hours of July 21. The hardest hit areas were in Montgomery County, where Emergency Management reported that 47 roads were closed at one point due to downed trees and power lines resulting in nearly 4,600 power outages. Additionally, a disaster declaration was made for the county as multiple buildings sustained damage. These included a tobacco warehouse that had its roof blown off as well as��a hotel in Mount Sterling whose sign and building both sustained damage from severe straight-line winds.', 'Dispatch relayed a report of a tree blown down on Kentucky Highway 711 northwest of Wrigley.');
INSERT INTO public.stormevents_east VALUES (760079, 201807, 26, 845, 201807, 26, 845, 126799, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'TBW', '26-JUL-18 08:45:00', 'EST-5', '26-JUL-18 08:45:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'S', 'OZONA', 1, 'S', 'OZONA', 28.049, -82.777, 28.049, -82.777, 'Scattered thunderstorms developed over the eastern Gulf and moved onshore throughout the day. Lightning strikes from some of these storms damaged at least three buildings in Pinellas County.', 'A fire reported at a bank in Dunedin was suspected to be caused by a lightning strike.');
INSERT INTO public.stormevents_east VALUES (745934, 201805, 15, 1720, 201805, 15, 1720, 124341, 'TENNESSEE', 47, 2018, 'May', 'Thunderstorm Wind', 'MRX', '15-MAY-18 17:20:00', 'EST-5', '15-MAY-18 17:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'RAMSEY', 1, 'E', 'RAMSEY', 35.97, -83.82, 35.97, -83.82, 'A couple severe thunderstorms formed producing strong wind gusts that downed a few trees in Central East Tennessee.', 'Eight trees were reported down across the eastern half of the county.');
INSERT INTO public.stormevents_east VALUES (760420, 201807, 26, 730, 201807, 26, 730, 126799, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'TBW', '26-JUL-18 07:30:00', 'EST-5', '26-JUL-18 07:30:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'ENE', 'CRYSTAL BEACH', 1, 'ENE', 'CRYSTAL BEACH', 28.09, -82.76, 28.09, -82.76, 'Scattered thunderstorms developed over the eastern Gulf and moved onshore throughout the day. Lightning strikes from some of these storms damaged at least three buildings in Pinellas County.', 'A lightning strike hit a home in Palm Harbor, leaving a burn mark in a bathroom ceiling. Sparks from the strike also caused minor burns to a resident laying in a bed in the home. No fire was caused by the lightning strike.');
INSERT INTO public.stormevents_east VALUES (760445, 201807, 21, 1035, 201807, 21, 1037, 126775, 'GULF OF MEXICO', 85, 2018, 'July', 'Waterspout', 'TBW', '21-JUL-18 10:35:00', 'EST-5', '21-JUL-18 10:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 8, 'S', 'VENICE', 8, 'S', 'VENICE', 26.982, -82.464, 26.986, -82.457, 'Westerly flow to the south of a weak surface trough set up scattered showers and storms over the eastern Gulf moving onshore into the Florida Peninsula throughout the day. One of these showers produced a waterspout, and at least one other storm caused gusty winds along the coast.', 'Private citizens reported seeing a waterspout off of Venice Beach and Englewood Beach. The time and exact location of the waterspout was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (760607, 201807, 28, 1736, 201807, 28, 1736, 126902, 'FLORIDA', 12, 2018, 'July', 'Hail', 'TBW', '28-JUL-18 17:36:00', 'EST-5', '28-JUL-18 17:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 0.75, NULL, NULL, NULL, 2, 'SW', 'WHISKEY CREEK', 2, 'SW', 'WHISKEY CREEK', 26.56, -81.92, 26.56, -81.92, 'Afternoon sea breeze thunderstorms across southwest Florida produced sub-severe hail.', 'Local broadcast media relayed a report from the public of penny size hail near McGregor.');
INSERT INTO public.stormevents_east VALUES (763024, 201807, 27, 1440, 201807, 27, 1541, 127291, 'VERMONT', 50, 2018, 'July', 'Flash Flood', 'BTV', '27-JUL-18 14:40:00', 'EST-5', '27-JUL-18 15:41:00', 0, 0, 0, 0, '400.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'SPRINGFIELD', 1, 'SSE', 'SPRINGFIELD', 43.2888, -72.4816, 43.2892, -72.4747, 'A cold front moved across New York into Vermont during the afternoon hours of July 27th. Scattered thunderstorms in moderated instability caused isolated wind damage in the form of downed trees and localized flash flooding in Springfield.', 'Heavy rainfall caused a culvert to backup at the intersection of Mineral and Grove Street. Additional heavy rainfall caused flash flooding on Union Street and Clinton Street. The flash flooding caused 78 residents of the  Louis Whitcomb Building  to be evacuated due to an electrical basement being flooded with water.');
INSERT INTO public.stormevents_east VALUES (760527, 201807, 5, 1417, 201807, 5, 1417, 126879, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'MLB', '05-JUL-18 14:17:00', 'EST-5', '05-JUL-18 14:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 6, 'N', 'ST. LUCIE INLET', 6, 'N', 'ST. LUCIE INLET', 27.57, -80.31, 27.57, -80.31, 'An upper-level low and attendant broad surface trough were located along the Florida panhandle. As these features moved slowly westward, an area of mid-level energy was moving across the central Florida peninsula. This combined with daytime heating, sufficient moisture, and veered southerly flow helped spark scattered to numerous showers and thunderstorms across east central Florida. One of these storms became strong and produced a waterspout off the extreme southeast Indian River County coast.', 'Several reports of a waterspout offshore from Avalon State Park were received. Reports came from the Ft. Pierce and Vero Beach Air Traffic Control Towers, as well as from storm spotters.');
INSERT INTO public.stormevents_east VALUES (761012, 201807, 30, 1545, 201807, 30, 1545, 126962, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '30-JUL-18 15:45:00', 'EST-5', '30-JUL-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 3, 'SSW', 'ORMOND BEACH', 3, 'SSW', 'ORMOND BEACH', 29.3138, -81.0892, 29.3138, -81.0892, 'The far southern extent of a longwave trough across the eastern United States was building towards the northeast Gulf of Mexico and Florida. At the same time, the Atlantic Bermuda Ridge located to the southeast of central Florida was strengthening. This resulted in south to southwest low-to-mid level flow across the area, and also ushered in deep moisture from the Gulf of Mexico. Daytime heating allowed scattered to numerous showers and thunderstorms to develop along the east and west coast sea breezes. Storms fired up first along the Treasure Coast where one thunderstorm produced a strong wind gust in Vero Beach. As the storms moved north, additional storms developed across Brevard County resulting in strong wind gusts at Cape Canaveral. The collision of an outflow boundary and the east coast sea breeze resulted in a strong thunderstorm that produced gusty conditions along the coast in Ormond Beach.', 'A mesonet in Ormond Beach measured a peak wind gust of 35 knots from the west-southwest.');
INSERT INTO public.stormevents_east VALUES (767032, 201807, 23, 1212, 201807, 23, 1215, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Hail', 'CAE', '23-JUL-18 12:12:00', 'EST-5', '23-JUL-18 12:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'N', 'BARR', 1, 'N', 'BARR', 33.95, -81.28, 33.95, -81.28, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Public report, via social media, of nickel to quarter size hail off of Barr Rd near Lexington.');
INSERT INTO public.stormevents_east VALUES (767036, 201807, 23, 1137, 201807, 23, 1140, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Thunderstorm Wind', 'CAE', '23-JUL-18 11:37:00', 'EST-5', '23-JUL-18 11:40:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'N', 'LYKESLAND', 1, 'N', 'LYKESLAND', 33.94, -80.9, 33.94, -80.9, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Multiple trees were downed in the vicinity of Air Base Rd, Old Hopkins Rd, and Montgomery Lane.');
INSERT INTO public.stormevents_east VALUES (761010, 201807, 30, 1505, 201807, 30, 1505, 126962, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '30-JUL-18 15:05:00', 'EST-5', '30-JUL-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 36, 'MG', NULL, NULL, 16, 'N', 'PLAYALINDA BEACH', 16, 'N', 'PLAYALINDA BEACH', 28.78, -80.8, 28.78, -80.8, 'The far southern extent of a longwave trough across the eastern United States was building towards the northeast Gulf of Mexico and Florida. At the same time, the Atlantic Bermuda Ridge located to the southeast of central Florida was strengthening. This resulted in south to southwest low-to-mid level flow across the area, and also ushered in deep moisture from the Gulf of Mexico. Daytime heating allowed scattered to numerous showers and thunderstorms to develop along the east and west coast sea breezes. Storms fired up first along the Treasure Coast where one thunderstorm produced a strong wind gust in Vero Beach. As the storms moved north, additional storms developed across Brevard County resulting in strong wind gusts at Cape Canaveral. The collision of an outflow boundary and the east coast sea breeze resulted in a strong thunderstorm that produced gusty conditions along the coast in Ormond Beach.', 'U.S. Air Force wind tower 0421 measured a peak wind gust of 36 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (761009, 201807, 30, 1505, 201807, 30, 1505, 126962, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '30-JUL-18 15:05:00', 'EST-5', '30-JUL-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 4, 'NNE', 'CAPE CANAVERAL', 4, 'NNE', 'CAPE CANAVERAL', 28.43, -80.57, 28.43, -80.57, 'The far southern extent of a longwave trough across the eastern United States was building towards the northeast Gulf of Mexico and Florida. At the same time, the Atlantic Bermuda Ridge located to the southeast of central Florida was strengthening. This resulted in south to southwest low-to-mid level flow across the area, and also ushered in deep moisture from the Gulf of Mexico. Daytime heating allowed scattered to numerous showers and thunderstorms to develop along the east and west coast sea breezes. Storms fired up first along the Treasure Coast where one thunderstorm produced a strong wind gust in Vero Beach. As the storms moved north, additional storms developed across Brevard County resulting in strong wind gusts at Cape Canaveral. The collision of an outflow boundary and the east coast sea breeze resulted in a strong thunderstorm that produced gusty conditions along the coast in Ormond Beach.', 'U.S. Air Force wind tower 0001 measured a peak wind gust of 34 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (765976, 201807, 23, 20, 201807, 23, 20, 127194, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '23-JUL-18 00:20:00', 'EST-5', '23-JUL-18 00:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 1, 'S', 'CAPE CANAVERAL', 1, 'S', 'CAPE CANAVERAL', 28.37, -80.6, 28.37, -80.6, 'A large mid-to-upper-level low pressure system centered over Ohio was expanding southward across the southeastern United States. As this occurred, a series of strong disturbances aloft traveled across the Florida peninsula. Environmental conditions supported numerous strong thunderstorms due to favorable vertical lift, wind shear and a very moist atmosphere. Scattered to numerous showers and thunderstorms developed during the afternoon and evening across northeast Florida. Over time these storms merged into a strong to severe Mesoscale Convective System (MCS) that moved south across east central Florida. Other storms also developed along the local sea breezes, and residual outflow boundaries. As the MCS moved across the intracoastal and nearshore waters of east central Florida, numerous strong wind events occurred from Volusia County south to St. Lucie County. This episode continued into the early morning hours of Monday (July 23) as a second, weaker MCS moved across the area from north to south, bringing strong winds to the Brevard County coast.', 'Weatherflow site at the Cocoa Beach Pier (XCCO) measured a peak wind gust of 37 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (763475, 201807, 23, 1321, 201807, 23, 1321, 127367, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '23-JUL-18 13:21:00', 'EST-5', '23-JUL-18 13:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 2, 'NW', 'ST. LUCIE INLET', 2, 'NW', 'ST. LUCIE INLET', 27.5, -80.338, 27.5, -80.338, 'A deep surface to upper atmosphere low pressure system, stretching from the Great Lakes region to Georgia, moved even further south into the northeast Gulf of Mexico. The trough and associated disturbance aloft moved slowly towards central Florida during the day as a swath of high moisture reached the area. Strong to severe thunderstorms developed as daytime heating intensified. As these storms moved across the intracoastal and nearshore waters along the Treasure Coast, they produced strong wind gusts. Across northeast Florida, storms merged into a Mesoscale Convective System (MCS) that then pushed south across east central Florida. This MCS brought strong winds to the Brevard County coast.', 'The ASOS at the Treasure Coast / Fort Pierce Airport (KFPR) measured a peak wind gust of 38 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (763477, 201807, 23, 1416, 201807, 23, 1416, 127367, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '23-JUL-18 14:16:00', 'EST-5', '23-JUL-18 14:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 43, 'MG', NULL, NULL, 4, 'N', 'SATELLITE BEACH', 4, 'N', 'SATELLITE BEACH', 28.23, -80.598, 28.23, -80.598, 'A deep surface to upper atmosphere low pressure system, stretching from the Great Lakes region to Georgia, moved even further south into the northeast Gulf of Mexico. The trough and associated disturbance aloft moved slowly towards central Florida during the day as a swath of high moisture reached the area. Strong to severe thunderstorms developed as daytime heating intensified. As these storms moved across the intracoastal and nearshore waters along the Treasure Coast, they produced strong wind gusts. Across northeast Florida, storms merged into a Mesoscale Convective System (MCS) that then pushed south across east central Florida. This MCS brought strong winds to the Brevard County coast.', 'The AWOS at Patrick Air Force Base (KCOF) measured a peak wind gust of 43 knots from the west-southwest.');
INSERT INTO public.stormevents_east VALUES (767039, 201807, 23, 1206, 201807, 23, 1210, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Thunderstorm Wind', 'CAE', '23-JUL-18 12:06:00', 'EST-5', '23-JUL-18 12:10:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'E', 'PROVIDENCE', 1, 'E', 'PROVIDENCE', 34.02, -81.26, 34.02, -81.26, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Tree down near the intersection of Yachting Rd and Secret Cove Rd.');
INSERT INTO public.stormevents_east VALUES (767040, 201807, 23, 1230, 201807, 23, 1235, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Thunderstorm Wind', 'CAE', '23-JUL-18 12:30:00', 'EST-5', '23-JUL-18 12:35:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 4, 'SW', 'CHAPIN', 4, 'SW', 'CHAPIN', 34.13, -81.39, 34.13, -81.39, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Tree down on a home near the intersection of Long Pine Rd and John Kinards Ct.');
INSERT INTO public.stormevents_east VALUES (767043, 201807, 23, 1302, 201807, 23, 1305, 127826, 'SOUTH CAROLINA', 45, 2018, 'July', 'Thunderstorm Wind', 'CAE', '23-JUL-18 13:02:00', 'EST-5', '23-JUL-18 13:05:00', 0, 0, 0, 0, NULL, NULL, 'Public', 55, 'EG', NULL, NULL, 2, 'SSW', 'LEESBURG', 2, 'SSW', 'LEESBURG', 34.01, -80.71, 34.01, -80.71, 'A moist atmosphere, daytime heating, and convergence along a stationary front produced scattered slow moving thunderstorms, some of which were severe.', 'Several trees and limbs downed near Leesburg Rd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (773997, 201809, 3, 1100, 201809, 3, 1100, 129142, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Marine Thunderstorm Wind', 'MLB', '03-SEP-18 11:00:00', 'EST-5', '03-SEP-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 47, 'MG', NULL, NULL, 1, 'ENE', 'ST. LUCIE INLET', 1, 'ENE', 'ST. LUCIE INLET', 27.49, -80.3, 27.49, -80.3, 'Numerous rainbands containing strong wind gusts rotated onshore the coast, well to the north of the center of Tropical Storm Gordon which moved west across the extreme southern tip of Florida during the day.', 'A Weatherflow site near Ft. Pierce recorded a peak wind of 47 knots from the south as a tropical rainband spread onshore.');
INSERT INTO public.stormevents_east VALUES (771772, 201807, 27, 1326, 201807, 27, 1326, 128650, 'NEW YORK', 36, 2018, 'July', 'Hail', 'ALY', '27-JUL-18 13:26:00', 'EST-5', '27-JUL-18 13:26:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'NW', 'ALBANY', 1, 'NW', 'ALBANY', 42.66, -73.78, 42.66, -73.78, 'Scattered thunderstorms developed ahead of a slow-moving cold front during the afternoon and evening of July 27th. The first cluster of storms that developed in the early afternoon produced fairly extensive wind damage over portions of the Capital District in addition to hail up to golf ball size. The wind brought down several large trees onto houses in and around Albany and Troy and damaged an outdoor stage set up on a golf course. Several gravestones were shattered in Albany Rural Cemetery when trees fell on them. More than 5,000 households lost power in Albany County and some were without power for up to 36 hours.||Additional strong to severe storms affected portions of the Catskills, Schoharie and Mohawk Valleys, and Mid Hudson Valley during the afternoon and evening with isolated wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (771773, 201807, 27, 1341, 201807, 27, 1341, 128650, 'NEW YORK', 36, 2018, 'July', 'Hail', 'ALY', '27-JUL-18 13:41:00', 'EST-5', '27-JUL-18 13:41:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'NNE', 'DEFREESTVILLE', 1, 'NNE', 'DEFREESTVILLE', 42.67, -73.69, 42.67, -73.69, 'Scattered thunderstorms developed ahead of a slow-moving cold front during the afternoon and evening of July 27th. The first cluster of storms that developed in the early afternoon produced fairly extensive wind damage over portions of the Capital District in addition to hail up to golf ball size. The wind brought down several large trees onto houses in and around Albany and Troy and damaged an outdoor stage set up on a golf course. Several gravestones were shattered in Albany Rural Cemetery when trees fell on them. More than 5,000 households lost power in Albany County and some were without power for up to 36 hours.||Additional strong to severe storms affected portions of the Catskills, Schoharie and Mohawk Valleys, and Mid Hudson Valley during the afternoon and evening with isolated wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (771774, 201807, 27, 1341, 201807, 27, 1341, 128650, 'NEW YORK', 36, 2018, 'July', 'Hail', 'ALY', '27-JUL-18 13:41:00', 'EST-5', '27-JUL-18 13:41:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 2, 'SW', 'ALBIA', 2, 'SW', 'ALBIA', 42.7, -73.69, 42.7, -73.69, 'Scattered thunderstorms developed ahead of a slow-moving cold front during the afternoon and evening of July 27th. The first cluster of storms that developed in the early afternoon produced fairly extensive wind damage over portions of the Capital District in addition to hail up to golf ball size. The wind brought down several large trees onto houses in and around Albany and Troy and damaged an outdoor stage set up on a golf course. Several gravestones were shattered in Albany Rural Cemetery when trees fell on them. More than 5,000 households lost power in Albany County and some were without power for up to 36 hours.||Additional strong to severe storms affected portions of the Catskills, Schoharie and Mohawk Valleys, and Mid Hudson Valley during the afternoon and evening with isolated wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (782060, 201809, 19, 1620, 201809, 19, 1620, 130670, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Marine Thunderstorm Wind', 'JAX', '19-SEP-18 16:20:00', 'EST-5', '19-SEP-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 46, 'MG', NULL, NULL, 13, 'WSW', 'MAYPORT NAS', 13, 'WSW', 'MAYPORT NAS', 30.34, -81.63, 30.34, -81.63, 'The combined forcing of a backdoor cold front sliding from NE to SW across the area and the more dominant east coast sea breeze over a moist and unstable airmass triggered strong storms as localized heavy rainfall.', NULL);
INSERT INTO public.stormevents_east VALUES (773130, 201807, 26, 1550, 201807, 26, 1550, 128935, 'OHIO', 39, 2018, 'July', 'Hail', 'CLE', '26-JUL-18 15:50:00', 'EST-5', '26-JUL-18 15:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 0, 'N', 'ELMORE', 0, 'N', 'ELMORE', 41.48, -83.3, 41.48, -83.3, 'A cold front swept east across the Upper Ohio Valley on July 26th causing a lines of thunderstorms to develop.  A lot of storm damage was reported along the central lakeshore counties of Lake Erie.  Sandusky in Erie County sustained the worst of the damage.', 'Quarter sized hail was observed.');
INSERT INTO public.stormevents_east VALUES (783294, 201809, 26, 1910, 201809, 26, 1910, 130903, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '26-SEP-18 19:10:00', 'EST-5', '26-SEP-18 19:10:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'W', 'ASHLEY FALLS', 0, 'W', 'ASHLEY FALLS', 42.0497, -73.335, 42.0497, -73.335, 'A cold front interacting with an unseasonably warm and humid airmass sparked an area of showers and thunderstorms during the evening of the 26th. One of these storms resulted in minor tree damage due to strong winds. The storms also produced heavy rain, with one report of a road closure due to flash flooding.', 'Large limbs were downed along Valley View Road.');
INSERT INTO public.stormevents_east VALUES (783295, 201809, 26, 1915, 201809, 26, 1915, 130903, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '26-SEP-18 19:15:00', 'EST-5', '26-SEP-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NE', 'SHEFFIELD', 1, 'NE', 'SHEFFIELD', 42.1086, -73.3364, 42.1086, -73.3364, 'A cold front interacting with an unseasonably warm and humid airmass sparked an area of showers and thunderstorms during the evening of the 26th. One of these storms resulted in minor tree damage due to strong winds. The storms also produced heavy rain, with one report of a road closure due to flash flooding.', 'A tree was downed on Boardman Street.');
INSERT INTO public.stormevents_east VALUES (783305, 201809, 26, 2000, 201809, 26, 2300, 130909, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'ALY', '26-SEP-18 20:00:00', 'EST-5', '26-SEP-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'SALISBURY', 0, 'NE', 'LAKEVILLE', 41.996, -73.4051, 41.9716, -73.4271, 'A cold front interacting with an unseasonably warm and humid airmass sparked an area of showers and thunderstorms during the evening of the 26th. These storms produced heavy rain, resulting in a few reports of flash flooding.', 'Multiple washouts were reported along Route 44 near Salisbury with debris and rocks in the road.');
INSERT INTO public.stormevents_east VALUES (783308, 201809, 26, 2100, 201809, 26, 2300, 130909, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'ALY', '26-SEP-18 21:00:00', 'EST-5', '26-SEP-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'PINE GROVE', 1, 'WNW', 'PINE GROVE', 42.0082, -73.3621, 42.0053, -73.3617, 'A cold front interacting with an unseasonably warm and humid airmass sparked an area of showers and thunderstorms during the evening of the 26th. These storms produced heavy rain, resulting in a few reports of flash flooding.', 'Flooding was reported at Dutcher''s Bridge.');
INSERT INTO public.stormevents_east VALUES (783561, 201809, 18, 200, 201809, 18, 400, 130978, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'ALY', '18-SEP-18 02:00:00', 'EST-5', '18-SEP-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'RICHMONDVILLE', 1, 'NE', 'RICHMONDVILLE', 42.6366, -74.5682, 42.6365, -74.5616, 'The remnants of Tropical Cyclone Florence moved into eastern New York on the 18th, resulting in a swath of two to three and a half inches of rainfall from the Schoharie Valley into the Capital District and the northern Taconics. The rainfall resulted in a couple of flooding reports.', 'Water was reported in the basement of residences in Richmondville.');
INSERT INTO public.stormevents_east VALUES (783611, 201809, 12, 721, 201809, 12, 930, 130983, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'ALY', '12-SEP-18 07:21:00', 'EST-5', '12-SEP-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'WHITEPORT', 0, 'ENE', 'WHITEPORT', 41.8809, -74.0471, 41.8821, -74.0442, 'Showers and thunderstorms developed along a stationary boundary during the morning of the 12th. The rainfall was locally heavy with isolated spots in Ulster and Dutchess Counties receiving two to three inches of rain. The rain resulted in isolated flash flooding.', 'A portion of Main Street in Bloomington was flooded.');
INSERT INTO public.stormevents_east VALUES (783612, 201809, 12, 835, 201809, 12, 1035, 130983, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'ALY', '12-SEP-18 08:35:00', 'EST-5', '12-SEP-18 10:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WURTEMBURG', 1, 'S', 'WURTEMBURG', 41.89, -73.87, 41.89, -73.8675, 'Showers and thunderstorms developed along a stationary boundary during the morning of the 12th. The rainfall was locally heavy with isolated spots in Ulster and Dutchess Counties receiving two to three inches of rain. The rain resulted in isolated flash flooding.', 'New York Route 9G was closed in the vicinity of Primrose Hill Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (783620, 201809, 6, 1322, 201809, 6, 1322, 130986, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 13:22:00', 'EST-5', '06-SEP-18 13:22:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'W', 'LENOX DALE', 2, 'W', 'LENOX DALE', 42.3268, -73.2881, 42.3268, -73.2881, 'A cold front crossed western Massachusetts on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage. Around 1400 customers lost power in due to the storms, and a few schools delayed closing until the storms passed.', 'A large tree was downed with wires blocking a road.');
INSERT INTO public.stormevents_east VALUES (783622, 201809, 6, 1343, 201809, 6, 1343, 130986, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 13:43:00', 'EST-5', '06-SEP-18 13:43:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'N', 'SHEFFIELD', 1, 'N', 'SHEFFIELD', 42.11, -73.35, 42.11, -73.35, 'A cold front crossed western Massachusetts on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage. Around 1400 customers lost power in due to the storms, and a few schools delayed closing until the storms passed.', 'A tree and wires were downed onto a house.');
INSERT INTO public.stormevents_east VALUES (783621, 201809, 6, 1322, 201809, 6, 1322, 130986, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 13:22:00', 'EST-5', '06-SEP-18 13:22:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'E', 'WEST STOCKBRIDGE', 2, 'E', 'WEST STOCKBRIDGE', 42.33, -73.3, 42.33, -73.3, 'A cold front crossed western Massachusetts on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage. Around 1400 customers lost power in due to the storms, and a few schools delayed closing until the storms passed.', 'A tree was downed onto wires.');
INSERT INTO public.stormevents_east VALUES (783623, 201809, 6, 1358, 201809, 6, 1358, 130986, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 13:58:00', 'EST-5', '06-SEP-18 13:58:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'WNW', 'ALGERIE FOUR CORNERS', 1, 'WNW', 'ALGERIE FOUR CORNERS', 42.2215, -73.0396, 42.2215, -73.0396, 'A cold front crossed western Massachusetts on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage. Around 1400 customers lost power in due to the storms, and a few schools delayed closing until the storms passed.', 'A road was blocked by a downed tree and wires.');
INSERT INTO public.stormevents_east VALUES (783625, 201809, 6, 1332, 201809, 6, 1332, 130986, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 13:32:00', 'EST-5', '06-SEP-18 13:32:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 50, 'EG', NULL, NULL, 1, 'S', 'LEE', 1, 'S', 'LEE', 42.3065, -73.2478, 42.3065, -73.2478, 'A cold front crossed western Massachusetts on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage. Around 1400 customers lost power in due to the storms, and a few schools delayed closing until the storms passed.', 'A large tree was downed onto the front yard of a residence.');
INSERT INTO public.stormevents_east VALUES (783627, 201809, 6, 1414, 201809, 6, 1414, 130987, 'CONNECTICUT', 9, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 14:14:00', 'EST-5', '06-SEP-18 14:14:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'AMENIA UNION', 2, 'NE', 'AMENIA UNION', 41.84, -73.4788, 41.84, -73.4788, 'A cold front crossed northwest Connecticut on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage.', 'A tree was downed onto wires.');
INSERT INTO public.stormevents_east VALUES (786566, 201809, 21, 1812, 201809, 21, 1812, 131456, 'NEW YORK', 36, 2018, 'September', 'Thunderstorm Wind', 'BUF', '21-SEP-18 18:12:00', 'EST-5', '21-SEP-18 18:12:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'BOLIVAR', 0, 'N', 'BOLIVAR', 42.07, -78.17, 42.07, -78.17, 'An unusually strong wind field was in place ahead of a well defined cold front. This supported very high effective bulk shear values along with very high levels of helicity. All of this supported cells that quickly formed into a textbook line echo wave pattern (LEWP) which quickly moved across the area. There were a handful of spin ups within the LEWP that developed very deep mesocyclones with persistent wind threats.', 'A tree was reported down.');
INSERT INTO public.stormevents_east VALUES (786567, 201809, 21, 1814, 201809, 21, 1814, 131456, 'NEW YORK', 36, 2018, 'September', 'Thunderstorm Wind', 'BUF', '21-SEP-18 18:14:00', 'EST-5', '21-SEP-18 18:14:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'BELMONT', 1, 'S', 'BELMONT', 42.22, -78.03, 42.22, -78.03, 'An unusually strong wind field was in place ahead of a well defined cold front. This supported very high effective bulk shear values along with very high levels of helicity. All of this supported cells that quickly formed into a textbook line echo wave pattern (LEWP) which quickly moved across the area. There were a handful of spin ups within the LEWP that developed very deep mesocyclones with persistent wind threats.', 'A tree was reported down.');
INSERT INTO public.stormevents_east VALUES (786568, 201809, 28, 1703, 201809, 28, 1703, 131458, 'LAKE ONTARIO', 94, 2018, 'September', 'Waterspout', 'BUF', '28-SEP-18 17:03:00', 'EST-5', '28-SEP-18 17:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Airplane Pilot', NULL, NULL, NULL, NULL, 6, 'NW', 'WILSON', 6, 'NW', 'WILSON', 43.3717, -78.9198, 43.3717, -78.9198, 'The first intrusion of cold air aloft brought showers over Lake Ontario. With warm early Autumn water temperatures, the first waterspout of the season was reported.', NULL);
INSERT INTO public.stormevents_east VALUES (786571, 201809, 28, 1841, 201809, 28, 1841, 131458, 'LAKE ONTARIO', 94, 2018, 'September', 'Waterspout', 'BUF', '28-SEP-18 18:41:00', 'EST-5', '28-SEP-18 18:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mariner', NULL, NULL, NULL, NULL, 9, 'NNE', 'FORT NIAGARA', 9, 'NNE', 'FORT NIAGARA', 43.3991, -79.0046, 43.3991, -79.0046, 'The first intrusion of cold air aloft brought showers over Lake Ontario. With warm early Autumn water temperatures, the first waterspout of the season was reported.', NULL);
INSERT INTO public.stormevents_east VALUES (786579, 201809, 26, 312, 201809, 26, 312, 131459, 'NEW YORK', 36, 2018, 'September', 'Lightning', 'BUF', '26-SEP-18 03:12:00', 'EST-5', '26-SEP-18 03:12:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 37, 'NNW', 'CENTERVILLE', 37, 'NNW', 'CENTERVILLE', 42.9215, -78.649, 42.9215, -78.649, 'A warm air mass and warm water temperatures combined to allow convection to extend well past the diurnally normal time frame. This brought convection from Lake Erie into western New York during the nighttime hours on September 25 that moved inland through the morning on September 26.', 'A trained spotter reported a lightning strike on a house that resulted in electrical damage to the home.');
INSERT INTO public.stormevents_east VALUES (795255, 201812, 21, 1647, 201812, 21, 1647, 132914, 'MARYLAND', 24, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 16:47:00', 'EST-5', '21-DEC-18 16:47:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SW', 'URBANA', 1, 'SW', 'URBANA', 39.32, -77.36, 39.32, -77.36, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the|atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down on I-270 near Exit 26 for MD-80 Fingerboard Road.');
INSERT INTO public.stormevents_east VALUES (795256, 201812, 21, 1656, 201812, 21, 1656, 132914, 'MARYLAND', 24, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 16:56:00', 'EST-5', '21-DEC-18 16:56:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'PLANE NUMBER FOUR', 1, 'S', 'PLANE NUMBER FOUR', 39.37, -77.2, 39.37, -77.2, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the|atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down near the intersection of Bill Moxley Road and Autumn Crest Drive.');
INSERT INTO public.stormevents_east VALUES (795258, 201812, 21, 1708, 201812, 21, 1708, 132914, 'MARYLAND', 24, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 17:08:00', 'EST-5', '21-DEC-18 17:08:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'N', 'WATERSVILLE', 2, 'N', 'WATERSVILLE', 39.4, -77.1, 39.4, -77.1, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the|atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down near the intersection of Gillis Falls Road and Davis Road.');
INSERT INTO public.stormevents_east VALUES (795259, 201812, 21, 1708, 201812, 21, 1708, 132914, 'MARYLAND', 24, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 17:08:00', 'EST-5', '21-DEC-18 17:08:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WNW', 'SAMS CREEK', 1, 'WNW', 'SAMS CREEK', 39.51, -77.12, 39.51, -77.12, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the|atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down in the 3500 block of Sams Creek Road.');
INSERT INTO public.stormevents_east VALUES (795261, 201812, 21, 1715, 201812, 21, 1715, 132914, 'MARYLAND', 24, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 17:15:00', 'EST-5', '21-DEC-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'FRIZZELLBURG', 1, 'NW', 'FRIZZELLBURG', 39.61, -77.08, 39.61, -77.08, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the|atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down blocking MD-832 Old Taneytown Road near Richardson Road.');
INSERT INTO public.stormevents_east VALUES (795263, 201812, 21, 1623, 201812, 21, 1623, 132915, 'VIRGINIA', 51, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 16:23:00', 'EST-5', '21-DEC-18 16:23:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'W', 'STERLING', 1, 'W', 'STERLING', 39, -77.45, 39, -77.45, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the |atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down near the intersection of Prentice Drive and Broderick Drive.');
INSERT INTO public.stormevents_east VALUES (795264, 201812, 21, 1627, 201812, 21, 1627, 132915, 'VIRGINIA', 51, 2018, 'December', 'Thunderstorm Wind', 'LWX', '21-DEC-18 16:27:00', 'EST-5', '21-DEC-18 16:27:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'LEGATO', 2, 'SE', 'LEGATO', 38.83, -77.34, 38.83, -77.34, 'A surface low tracked northeastward through the Appalachians as a potent jetstreak in the upper levels shifted northward. Unseasonably warm and moist air was transported northward and this, in combination with colder air moving in at the mid-levels, caused the |atmosphere to destabilize, resulting in showers and thunderstorms. A few of these storms became locally severe.', 'A tree was blown down on VA-655 Shirley Gate Road near VA-620 Braddock Road.');
INSERT INTO public.stormevents_east VALUES (737764, 201801, 23, 1500, 201801, 23, 1500, 123053, 'MASSACHUSETTS', 25, 2018, 'January', 'Thunderstorm Wind', 'BOX', '23-JAN-18 15:00:00', 'EST-5', '23-JAN-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 1, 'WSW', 'HORTONVILLE', 1, 'W', 'HORTONVILLE', 41.7757, -71.2199, 41.7767, -71.2231, 'Low pressure from the Great Lakes redeveloped over Southern New England on January 22, then moved off through the Canadian Maritimes on January 23.  Warm air moving northeast with this system moved over Cape Cod and the Islands.  Thunderstorms that developed in this warm air then brought strong wind gusts to the surface.  Gusts of 50 to 55 mph were reported along the South Coast, with one report of 58 mph.', 'At 3 PM EST, a large tree was reported down on State Route 118 at Locust Street in Swansea.');
INSERT INTO public.stormevents_east VALUES (737776, 201801, 23, 1530, 201801, 23, 1530, 123053, 'MASSACHUSETTS', 25, 2018, 'January', 'Thunderstorm Wind', 'BOX', '23-JAN-18 15:30:00', 'EST-5', '23-JAN-18 15:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 0, 'NNE', 'HYANNIS', 1, 'NE', 'HYANNIS', 41.6552, -70.2771, 41.6567, -70.272, 'Low pressure from the Great Lakes redeveloped over Southern New England on January 22, then moved off through the Canadian Maritimes on January 23.  Warm air moving northeast with this system moved over Cape Cod and the Islands.  Thunderstorms that developed in this warm air then brought strong wind gusts to the surface.  Gusts of 50 to 55 mph were reported along the South Coast, with one report of 58 mph.', 'At 330 PM EST, a tree was reported down on a house on Main Street in Barnstable.');
INSERT INTO public.stormevents_east VALUES (746459, 201804, 16, 2215, 201804, 17, 45, 123555, 'NEW JERSEY', 34, 2018, 'April', 'Flood', 'PHI', '16-APR-18 22:15:00', 'EST-5', '17-APR-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'BOUND BROOK JCT', 0, 'NE', 'BOUND BROOK JCT', 40.5511, -74.5483, 40.5507, -74.5494, 'A strong backdoor cold front moved from northeast to southwest across the area late Saturday afternoon April 15th into Sunday morning April 16th. Not only was there a significant drop in temperature coinciding with the passage of the front, but also a stark difference between high temperatures on Saturday and Sunday. On Saturday, high temperatures ranged from the mid-70s to mid-80s, but only made it to the mid-30s to mid-40s on Sunday. In general, there was a 40 degree temperature drop from Saturday to Sunday! ||The backdoor front became stationary south of the region then moved northward as a warm front Sunday night into Monday morning. Meanwhile, a strong cold front approached from the west and swept across the area Monday afternoon and evening, along with an attendant area of low pressure. This robust storm system tapped large amounts of moisture, which was lifted along the warm front as overrunning precipitation, and along the cold front as a line of showers and thunderstorms. ||As a result, heavy rainfall occurred across the region. A widespread 1 to 3 inches of rainfall occurred, with localized amounts over 4 inches, especially across the northern half of New Jersey. As a result, flooding occurred across portions of the area. Meanwhile, it was cold enough in the higher elevations of Sussex County New Jersey for freezing rain on Sunday.||Along the coast, an extended period of onshore flow occurred, beginning with east-northeast winds Saturday Night, which then shifted to the southeast on Sunday Night into Monday Morning April 16th. Widespread winds gusts of 40 to 50 mph occurred in the east-northeast flow Saturday Night and Sunday, with a lull Sunday Night, then occasionally again in the south-southeast flow along and just in advance of a heavy line of showers and thunderstorms on Monday Morning. The onshore flow, and to a lesser extent the heavy rainfall, lead to multiple rounds of coastal flooding along the oceanfront and back bays with the high tide cycles on Sunday evening and again on Monday Morning.', 'The Raritan River at Bound Brook rose above flood stage of 28.0 feet and reached a maximum of 28.10 feet.');
INSERT INTO public.stormevents_east VALUES (744638, 201805, 5, 1715, 201805, 5, 1715, 124077, 'TENNESSEE', 47, 2018, 'May', 'Hail', 'MRX', '05-MAY-18 17:15:00', 'EST-5', '05-MAY-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'NE', 'SNEEDVILLE', 1, 'NE', 'SNEEDVILLE', 36.54, -83.21, 36.54, -83.21, 'Isolated occurrences of marginal hail were reported across the Southern Appalachian region.', 'Quarter sized hail was reported near Sneedville.');
INSERT INTO public.stormevents_east VALUES (745935, 201805, 15, 1730, 201805, 15, 1730, 124341, 'TENNESSEE', 47, 2018, 'May', 'Thunderstorm Wind', 'MRX', '15-MAY-18 17:30:00', 'EST-5', '15-MAY-18 17:30:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'WSW', 'RUTLEDGE', 1, 'WSW', 'RUTLEDGE', 36.27, -83.52, 36.27, -83.52, 'A couple severe thunderstorms formed producing strong wind gusts that downed a few trees in Central East Tennessee.', 'Several trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (745940, 201805, 14, 1715, 201805, 14, 1715, 124342, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'MRX', '14-MAY-18 17:15:00', 'EST-5', '14-MAY-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WSW', 'PEACHTREE', 1, 'WSW', 'PEACHTREE', 35.09, -83.97, 35.09, -83.97, 'A lone thunderstorm developed generating a wind gust that knocked down a few trees across a small part of Southwest North Carolina.', 'Several trees were reported down three miles east of Murphy.');
INSERT INTO public.stormevents_east VALUES (745943, 201805, 18, 1648, 201805, 18, 1648, 124343, 'TENNESSEE', 47, 2018, 'May', 'Thunderstorm Wind', 'MRX', '18-MAY-18 16:48:00', 'EST-5', '18-MAY-18 16:48:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'S', 'ALCOA', 1, 'S', 'ALCOA', 35.79, -83.98, 35.79, -83.98, 'A lone severe thunderstorm formed across Central East Tennessee producing a wind gust that knocked down a few trees.', 'Several trees were reported down near Alcoa.');
INSERT INTO public.stormevents_east VALUES (761580, 201805, 25, 1906, 201805, 25, 1906, 127092, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '25-MAY-18 19:06:00', 'EST-5', '25-MAY-18 19:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'E', 'KEY WEST', 2, 'E', 'KEY WEST', 24.5571, -81.7554, 24.5571, -81.7554, 'Numerous showers and thunderstorms along the outer periphery of newly-formed Subtropical Storm Alberto produced isolated gale-force wind gusts.  These showers and thunderstorms were associated with the deep tropical moisture moving north from the western Caribbean, and not directly associated with the circulation of Subtropical Storm Alberto.', 'A wind gust of 34 knots was measured at Key West International Airport.');
INSERT INTO public.stormevents_east VALUES (761584, 201805, 26, 714, 201805, 26, 714, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 07:14:00', 'EST-5', '26-MAY-18 07:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 0, 'N', 'MOLASSES REEF LIGHT', 0, 'N', 'MOLASSES REEF LIGHT', 25.01, -80.38, 25.01, -80.38, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 35 knots was measured at Molasses Reef Light.');
INSERT INTO public.stormevents_east VALUES (761586, 201805, 26, 1459, 201805, 26, 1459, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 14:59:00', 'EST-5', '26-MAY-18 14:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'SE', 'BIG COPPITT KEY', 2, 'SE', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at the Naval Air Station Key West Boca Chica Field.');
INSERT INTO public.stormevents_east VALUES (761588, 201805, 26, 1700, 201805, 26, 1700, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 17:00:00', 'EST-5', '26-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at an automated Citizen Weather Observing Program station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (744803, 201805, 4, 1910, 201805, 4, 1912, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 19:10:00', 'EST-5', '04-MAY-18 19:12:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'SHEFFIELD', 0, 'N', 'SHEFFIELD', 44.6, -72.12, 44.6, -72.12, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Several trees and utility lines down.');
INSERT INTO public.stormevents_east VALUES (744809, 201805, 4, 1939, 201805, 4, 1940, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 19:39:00', 'EST-5', '04-MAY-18 19:40:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Utility Company', 60, 'EG', NULL, NULL, 0, 'N', 'BROOKFIELD', 0, 'N', 'BROOKFIELD', 44.05, -72.6, 44.05, -72.6, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Multiple trees and utility lines down along Route 14.');
INSERT INTO public.stormevents_east VALUES (744810, 201805, 4, 1939, 201805, 4, 1940, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 19:39:00', 'EST-5', '04-MAY-18 19:40:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'PITTSFORD', 0, 'N', 'PITTSFORD', 43.7, -73.03, 43.7, -73.03, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Several trees downed by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (745282, 201805, 16, 1535, 201805, 16, 1835, 124189, 'KENTUCKY', 21, 2018, 'May', 'Flash Flood', 'JKL', '16-MAY-18 15:35:00', 'EST-5', '16-MAY-18 18:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 4, 'SW', 'REYNOLDSVILLE', 5, 'SW', 'REYNOLDSVILLE', 38.14, -83.87, 38.122, -83.8874, 'A slow moving line of thunderstorms developed from mid to late this afternoon across central Kentucky. As this line progressed east into the Bluegrass region of eastern Kentucky, these storms increased in coverage as rainfall rates increased. This led to instances of flash flooding across portions of Bath and Montgomery Counties. These storms continued to move east into the evening hours, creating additional flash flooding from Morehead to west of Sandy Hook.', 'County Emergency Management reported several roadways containing at least half a foot of flowing water near Flat Creek and west of Owingsville, leading to a vehicle becoming stranded on U.S. Highway 60 near the Montgomery County line.');
INSERT INTO public.stormevents_east VALUES (745106, 201805, 15, 1642, 201805, 15, 2003, 124159, 'KENTUCKY', 21, 2018, 'May', 'Flash Flood', 'JKL', '15-MAY-18 16:42:00', 'EST-5', '15-MAY-18 20:03:00', 0, 0, 0, 0, '80.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'MILLSTONE', 1, 'E', 'KONA', 37.1679, -82.7292, 37.1473, -82.7054, 'Slow moving thunderstorms developed this afternoon ahead of an upper level disturbance, bringing moisture from the Gulf of Mexico into eastern Kentucky. Isolated wind damage occurred in Laurel County as one storm initially grew very strong. Additional storms produced penny to nickel sized hail, while portions of northeast Letcher County experienced flash flooding due to persistent storms producing between 2-3 inches of rain.', 'Dispatch and local media reported several instances of flash flooding from near Fish Pond Lake to Fleming-Neon and Whitaker. This included portions of Kentucky Highway 3406 being closed, along with several other local roads. Just southeast of Tolliver Town and near Payne Gap, a couple of culverts were displaced due to swiftly flowing flood waters. Three people had to be rescued from their vehicles after they became inundated by water, while four homes were flooded.');
INSERT INTO public.stormevents_east VALUES (745435, 201805, 13, 1655, 201805, 13, 1656, 124158, 'PENNSYLVANIA', 42, 2018, 'May', 'Tornado', 'CTP', '13-MAY-18 16:55:00', 'EST-5', '13-MAY-18 16:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NNE', 'KANTNER', 1, 'NE', 'KANTNER', 40.1164, -78.9219, 40.1151, -78.9167, 'An EF1 tornado was confirmed near Kantner in Somerset County by a NWS storm survey. Maximum wind speeds were estimated at 100-110 mph, with a path length of one-quarter of a mile and a maximum path width of 100 yards.', 'A tornado started just east of Whistler Rd along Koontztown Rd in|Juniata township. Along Koontztown Rd, dozens of trees were uprooted|or snapped 20-30 feet off the ground, indicating winds of 100-110|MPH. The trees fell in a convergent pattern indicating a tornado|occurred. The majority of concentrated damage occurred in a rural area west of|Center St.');
INSERT INTO public.stormevents_east VALUES (748722, 201805, 15, 1723, 201805, 15, 1930, 124787, 'MASSACHUSETTS', 25, 2018, 'May', 'Flood', 'BOX', '15-MAY-18 17:23:00', 'EST-5', '15-MAY-18 19:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'EAST BLACKSTONE', 1, 'SW', 'EAST BLACKSTONE', 42.018, -71.5448, 42.0202, -71.5326, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Massachusetts was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 5:23 PM EST, Main Street in Blackstone was flooded and impassable.  A car was trapped in the floodwaters and towed out.');
INSERT INTO public.stormevents_east VALUES (748753, 201805, 15, 1545, 201805, 15, 1545, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 48, 'EG', NULL, NULL, 1, 'WSW', 'NORTH BLOOMFIELD', 0, 'NNW', 'NORTH BLOOMFIELD', 41.8766, -72.7667, 41.8862, -72.7536, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 3:45 PM EST trees were reported down on both Duncaster Road and Hopkins Road in Bloomfield.');
INSERT INTO public.stormevents_east VALUES (748815, 201805, 15, 1655, 201805, 15, 1655, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 16:55:00', 'EST-5', '15-MAY-18 16:55:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 40, 'EG', NULL, NULL, 1, 'NE', 'PLAINFIELD', 1, 'NE', 'PLAINFIELD', 41.6765, -71.9171, 41.6765, -71.9171, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 4:55 PM EST trees were reported blocking Greene Avenue at the intersection with Butterworth Avenue in Plainfield.');
INSERT INTO public.stormevents_east VALUES (749194, 201805, 17, 2127, 201805, 18, 27, 124870, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '17-MAY-18 21:27:00', 'EST-5', '18-MAY-18 00:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WINFALL', 1, 'SE', 'WINFALL', 37.22, -79.09, 37.2243, -79.0933, 'A weak frontal boundary located near the I-64 corridor provided the focus for repeated thunderstorm activity through the evening across several counties. A broad area of low pressure over the southeastern U.S. pulled very high moisture into the region allowing the slow-moving storms to be efficient rainfall producers. Rainfall amount were generally 2 to 4 inches, with isolated higher totals indicated by radar in the heavier cores occurring over a several hour period.', 'Water was reported covering portions of Route 501 between Rustburg and Gladys.');
INSERT INTO public.stormevents_east VALUES (749202, 201805, 17, 2100, 201805, 18, 0, 124870, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '17-MAY-18 21:00:00', 'EST-5', '18-MAY-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'HARDYS FORD', 2, 'WSW', 'HARDYS FORD', 37.2107, -79.8618, 37.2102, -79.8621, 'A weak frontal boundary located near the I-64 corridor provided the focus for repeated thunderstorm activity through the evening across several counties. A broad area of low pressure over the southeastern U.S. pulled very high moisture into the region allowing the slow-moving storms to be efficient rainfall producers. Rainfall amount were generally 2 to 4 inches, with isolated higher totals indicated by radar in the heavier cores occurring over a several hour period.', 'Flooding closed the intersection of Copper Cove and Valleyview Roads.');
INSERT INTO public.stormevents_east VALUES (744138, 201805, 5, 1552, 201805, 5, 1552, 123919, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'RLX', '05-MAY-18 15:52:00', 'EST-5', '05-MAY-18 15:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1.75, NULL, NULL, NULL, 1, 'SE', 'RUSSELL MART', 1, 'SE', 'RUSSELL MART', 37.21, -82.29, 37.21, -82.29, 'Following a period of sunshine earlier in the day, thunderstorms formed across southwest Virginia and southeast Kentucky during the late afternoon of the 5th as a low pressure system approached. Large hail fell out of these storms during the late afternoon and evening.', NULL);
INSERT INTO public.stormevents_east VALUES (745268, 201805, 14, 1318, 201805, 14, 1320, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 13:18:00', 'EST-5', '14-MAY-18 13:20:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'MURRAY CITY', 1, 'S', 'MURRAY CITY', 39.51, -82.17, 39.51, -82.17, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'A few trees were downed in Murray City.');
INSERT INTO public.stormevents_east VALUES (745272, 201805, 15, 1610, 201805, 15, 1612, 124184, 'OHIO', 39, 2018, 'May', 'Hail', 'ILN', '15-MAY-18 16:10:00', 'EST-5', '15-MAY-18 16:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 1, 'E', 'URBANA WELLER ARPT', 1, 'E', 'URBANA WELLER ARPT', 40.08, -83.67, 40.08, -83.67, 'Scattered thunderstorms developed along a slow moving frontal boundary.', NULL);
