INSERT INTO public.stormevents_east VALUES (745274, 201805, 15, 1717, 201805, 15, 1719, 124184, 'OHIO', 39, 2018, 'May', 'Hail', 'ILN', '15-MAY-18 17:17:00', 'EST-5', '15-MAY-18 17:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 1, 'W', 'PRICE ARPT', 1, 'W', 'PRICE ARPT', 39.92, -82.92, 39.92, -82.92, 'Scattered thunderstorms developed along a slow moving frontal boundary.', NULL);
INSERT INTO public.stormevents_east VALUES (745275, 201805, 15, 1428, 201805, 15, 1430, 124184, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '15-MAY-18 14:28:00', 'EST-5', '15-MAY-18 14:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'W', 'AMITY', 2, 'W', 'AMITY', 40.07, -83.29, 40.07, -83.29, 'Scattered thunderstorms developed along a slow moving frontal boundary.', 'Two trees were downed.');
INSERT INTO public.stormevents_east VALUES (745276, 201805, 15, 1700, 201805, 15, 1702, 124184, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '15-MAY-18 17:00:00', 'EST-5', '15-MAY-18 17:02:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'N', 'BLOOMINGBURG', 1, 'N', 'BLOOMINGBURG', 39.61, -83.4, 39.61, -83.4, 'Scattered thunderstorms developed along a slow moving frontal boundary.', 'A home sustained some roof damage.');
INSERT INTO public.stormevents_east VALUES (745277, 201805, 15, 1715, 201805, 15, 1717, 124184, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '15-MAY-18 17:15:00', 'EST-5', '15-MAY-18 17:17:00', 0, 0, 0, 0, '0.25K', '0.00K', 'Trained Spotter', 45, 'EG', NULL, NULL, 1, 'W', 'PRICE ARPT', 1, 'W', 'PRICE ARPT', 39.92, -82.92, 39.92, -82.92, 'Scattered thunderstorms developed along a slow moving frontal boundary.', 'A few tree branches were downed.');
INSERT INTO public.stormevents_east VALUES (749306, 201805, 10, 2015, 201805, 10, 2015, 124923, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'MHX', '10-MAY-18 20:15:00', 'EST-5', '10-MAY-18 20:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 4, 'S', 'PLYMOUTH', 4, 'S', 'PLYMOUTH', 35.8121, -76.75, 35.8121, -76.75, 'Ahead of a weak cold front, a line of thunderstorms developed over the western sections of Virginia and north central North Carolina on the evening of May 10th. As this weak front moved into Eastern North Carolina, an area of thunderstorms impacted especially the northern part of our forecast area.  Some of the storms became severe and produced wind damage and large hail.', 'Quarter size hail fell.');
INSERT INTO public.stormevents_east VALUES (749307, 201805, 10, 2022, 201805, 10, 2022, 124923, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'MHX', '10-MAY-18 20:22:00', 'EST-5', '10-MAY-18 20:22:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'SSW', 'PLYMOUTH', 2, 'SSW', 'PLYMOUTH', 35.8433, -76.7637, 35.8433, -76.7637, 'Ahead of a weak cold front, a line of thunderstorms developed over the western sections of Virginia and north central North Carolina on the evening of May 10th. As this weak front moved into Eastern North Carolina, an area of thunderstorms impacted especially the northern part of our forecast area.  Some of the storms became severe and produced wind damage and large hail.', 'Trees were downed on Long Ridge Rd and Highway 64. The time was estimated by radar.');
INSERT INTO public.stormevents_east VALUES (771564, 201807, 2, 1950, 201807, 2, 2050, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '02-JUL-18 19:50:00', 'EST-5', '02-JUL-18 20:50:00', 0, 0, 0, 0, '1.00K', '1.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'SMICKSBURG', 1, 'SE', 'SMICKSBURG', 40.87, -79.17, 40.8613, -79.172, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported 5 feet of water across Route 954.');
INSERT INTO public.stormevents_east VALUES (771565, 201807, 2, 1705, 201807, 2, 1706, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Hail', 'PBZ', '02-JUL-18 17:05:00', 'EST-5', '02-JUL-18 17:06:00', 0, 0, 0, 0, '0.50K', '0.50K', 'Public', 1, NULL, NULL, NULL, 1, 'SSE', 'HARMONY', 1, 'SSE', 'HARMONY', 40.76, -80.12, 40.76, -80.12, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'Citizens of Zelienople reported strong winds along with 1 inch hail along Perry Highway.');
INSERT INTO public.stormevents_east VALUES (771566, 201807, 2, 1818, 201807, 2, 2030, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '02-JUL-18 18:18:00', 'EST-5', '02-JUL-18 20:30:00', 0, 0, 0, 0, '1.00K', '0.50K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'NEW KENSINGTON', 0, 'SSW', 'ARNOLA', 40.5678, -79.7577, 40.5736, -79.753, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'A 911 Call Center reported flooding in New Kensington along Freeport Road.');
INSERT INTO public.stormevents_east VALUES (771567, 201807, 2, 1900, 201807, 2, 2100, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '02-JUL-18 19:00:00', 'EST-5', '02-JUL-18 21:00:00', 0, 0, 0, 0, '0.50K', '0.50K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SEWICKLEY', 1, 'NE', 'STOOPS FERRY', 40.54, -80.19, 40.5364, -80.1889, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The local Emergency Manager reported flooding at Chadwick and Ferry Street.');
INSERT INTO public.stormevents_east VALUES (772440, 201807, 2, 1852, 201807, 2, 1852, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '02-JUL-18 18:52:00', 'EST-5', '02-JUL-18 18:52:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'SW', 'MC DONALD', 1, 'SW', 'MC DONALD', 40.36, -80.24, 40.36, -80.24, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported multiple trees down in McDonald Boro/Robinson Towsnhip area.');
INSERT INTO public.stormevents_east VALUES (772438, 201807, 2, 1829, 201807, 2, 1945, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '02-JUL-18 18:29:00', 'EST-5', '02-JUL-18 19:45:00', 0, 0, 0, 0, '5.00K', '1.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'SHARPSBURG', 2, 'E', 'ETNA', 40.5, -79.91, 40.5018, -79.9411, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported flooding on Route 28 near Highland Park Bridge, the intersection of Delafield Road and Eton Drive, and the bottom of Washington Blvd. The county emergency manager also reported flooding near 6th street and Penn Street in Sharpsburg.');
INSERT INTO public.stormevents_east VALUES (772442, 201807, 2, 1740, 201807, 2, 1740, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '02-JUL-18 17:40:00', 'EST-5', '02-JUL-18 17:40:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'S', 'COLLINSBURG', 1, 'S', 'COLLINSBURG', 40.22, -79.8, 40.22, -79.8, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported 2 trees down near Salem Church Rd.');
INSERT INTO public.stormevents_east VALUES (772441, 201807, 2, 1631, 201807, 2, 1631, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '02-JUL-18 16:31:00', 'EST-5', '02-JUL-18 16:31:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 3, 'S', 'WEST FAIRFIELD', 3, 'S', 'WEST FAIRFIELD', 40.3, -79.12, 40.3, -79.12, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported tree and lines down near Twin Echo Drive.');
INSERT INTO public.stormevents_east VALUES (772444, 201807, 2, 1452, 201807, 2, 1453, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Hail', 'PBZ', '02-JUL-18 14:52:00', 'EST-5', '02-JUL-18 14:53:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'W', 'WEHRUM', 2, 'W', 'WEHRUM', 40.48, -78.96, 40.48, -78.96, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'Citizens reported hail along Bracken Road.');
INSERT INTO public.stormevents_east VALUES (756835, 201805, 22, 1518, 201805, 22, 1518, 126226, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '22-MAY-18 15:18:00', 'EST-5', '22-MAY-18 15:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 6, 'N', 'MANSFIELD', 6, 'N', 'MANSFIELD', 40.8568, -82.52, 40.8568, -82.52, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Penny sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (756837, 201805, 22, 1610, 201805, 22, 1610, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 16:10:00', 'EST-5', '22-MAY-18 16:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'ALLIANCE', 0, 'N', 'ALLIANCE', 40.92, -81.1, 40.92, -81.1, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds downed two trees.');
INSERT INTO public.stormevents_east VALUES (756883, 201805, 22, 1313, 201805, 22, 1317, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 13:13:00', 'EST-5', '22-MAY-18 13:17:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SW', 'NORTH ROYALTON', 1, 'NE', 'NORTH ROYALTON', 41.2995, -81.7535, 41.3279, -81.7226, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds knocked several trees down near the intersection of Bennett Road and York Road blocking the road.  Other limbs were reported down across North Royalton and some fencing was blown down at an athletic field on Wallings Road.');
INSERT INTO public.stormevents_east VALUES (756885, 201805, 22, 1505, 201805, 22, 1505, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 15:05:00', 'EST-5', '22-MAY-18 15:05:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'WSW', 'SHELBY', 0, 'WSW', 'SHELBY', 40.8785, -82.656, 40.8785, -82.656, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm wind gusts snapped several poles along State Routes 39 and 96 in Shelby.  Widespread power outages were reported.');
INSERT INTO public.stormevents_east VALUES (756886, 201805, 22, 1355, 201805, 22, 1355, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 13:55:00', 'EST-5', '22-MAY-18 13:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'WNW', 'JOHNSTON', 1, 'WNW', 'JOHNSTON', 41.3852, -80.7067, 41.3852, -80.7067, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds downed a tree along State Route 11 just west of Johnston.');
INSERT INTO public.stormevents_east VALUES (756889, 201805, 22, 1355, 201805, 22, 1355, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 13:55:00', 'EST-5', '22-MAY-18 13:55:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 5, 'W', 'NEW WASHINGTON', 5, 'W', 'NEW WASHINGTON', 40.97, -82.9458, 40.97, -82.9458, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds downed a tree.');
INSERT INTO public.stormevents_east VALUES (756891, 201805, 22, 1444, 201805, 22, 1444, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 14:44:00', 'EST-5', '22-MAY-18 14:44:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'S', 'CHATFIELD', 4, 'S', 'CHATFIELD', 40.8921, -82.93, 40.8921, -82.93, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds downed a tree on Lemert Road.');
INSERT INTO public.stormevents_east VALUES (757149, 201805, 31, 1952, 201805, 31, 1952, 126312, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'GSP', '31-MAY-18 19:52:00', 'EST-5', '31-MAY-18 19:52:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 0, 'NW', 'CANDLER', 0, 'E', 'SAND HILL', 35.535, -82.705, 35.55, -82.649, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon. A few of the storms produced brief severe weather in the form of damaging winds, mainly across the foothills. Later in the evening, a decaying line of thunderstorms entered western North Carolina from Tennessee. Despite the weakening of the storms, a remnant area of strong winds left behind by the storms produced damage in portions of the mountains.', 'County comms reported numerous trees and some power lines blown down between Candler and Enka.');
INSERT INTO public.stormevents_east VALUES (757152, 201805, 31, 1915, 201805, 31, 1935, 126312, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'GSP', '31-MAY-18 19:15:00', 'EST-5', '31-MAY-18 19:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'ENE', 'ANTIOCH', 1, 'SE', 'ROLLINS', 35.909, -82.858, 35.772, -82.66, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon. A few of the storms produced brief severe weather in the form of damaging winds, mainly across the foothills. Later in the evening, a decaying line of thunderstorms entered western North Carolina from Tennessee. Despite the weakening of the storms, a remnant area of strong winds left behind by the storms produced damage in portions of the mountains.', 'County comms reported numerous trees blown down, with the damage roughly paralleling the French Broad River.');
INSERT INTO public.stormevents_east VALUES (757163, 201805, 31, 1650, 201805, 31, 1650, 126312, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '31-MAY-18 16:50:00', 'EST-5', '31-MAY-18 16:50:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'S', 'POLKVILLE', 1, 'S', 'POLKVILLE', 35.416, -81.629, 35.416, -81.629, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon. A few of the storms produced brief severe weather in the form of damaging winds, mainly across the foothills. Later in the evening, a decaying line of thunderstorms entered western North Carolina from Tennessee. Despite the weakening of the storms, a remnant area of strong winds left behind by the storms produced damage in portions of the mountains.', 'Spotter reported quarter size hail on West Stage Coach Trail.');
INSERT INTO public.stormevents_east VALUES (757134, 201805, 31, 2038, 201805, 31, 2038, 126312, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'GSP', '31-MAY-18 20:38:00', 'EST-5', '31-MAY-18 20:38:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'ROCK SPGS', 1, 'N', 'ROCK SPGS', 35.41, -82.13, 35.41, -82.13, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon. A few of the storms produced brief severe weather in the form of damaging winds, mainly across the foothills. Later in the evening, a decaying line of thunderstorms entered western North Carolina from Tennessee. Despite the weakening of the storms, a remnant area of strong winds left behind by the storms produced damage in portions of the mountains.', 'County comms reported multiple trees blown down on Rock Springs Church Rd.');
INSERT INTO public.stormevents_east VALUES (777213, 201807, 27, 1449, 201807, 27, 1457, 129746, 'GEORGIA', 13, 2018, 'July', 'Tornado', 'CHS', '27-JUL-18 14:49:00', 'EST-5', '27-JUL-18 14:57:00', 0, 0, 0, 0, NULL, '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'ENE', 'SAVANNAH', 4, 'E', 'THUNDERBOLT', 32.0644, -81.0287, 32.0379, -81.0053, 'A cluster of thunderstorms developed near the southeast Georgia coast in advance of a stationary front inland. As these thunderstorms moved to the south and southeast closer to the coast, they interacted with the sea breeze and moved into an environment conducive to the development rotating updrafts. A tornado developed quickly and impacted portions of Chatham County.', 'A National Weather Service storm survey team confirmed that an EF-1 tornado impacted portions of Chatham County. The tornado began near Bartow Point Drive, just north of Island Expressway. The tornado then crossed over the Frank W. Spencer Boat Ramp and Fishing Pier area before crossing Island Expressway. The tornado continued southeast across Oatland Island where it was estimated to have snapped or uprooted over 100 large hardwood and softwood trees. It also removed the roof from a log cabin and partially damaged the roof to another structure in the Delk-Dawson Heritage Homestead on Oatland Island. The tornado continued southeast over Richardson Creek, entering the Grays subdivision on Whitemarsh Island. In this neighborhood, the tornado snapped and uprooted many large trees. The most significant damage surveyed in the Grays subdivision were large snapped and uprooted trees that had fallen onto approximately 50 homes. Several homes also had significant shingle damage. The tornado then crossed Highway 80, moving over Islands Christian Church before taking a narrow path along Dolphin Lane, Passing near Marsh Point Elementary School. The school sustained moderate damage to the roof near the main entry of the facility. Finally, the tornado moved southeast across Whitemarsh Island Drive before dissipating near Islands High School, where it toppled the metal bleachers and damaged some fencing near athletic fields. The tornado was on the ground for approximately 8 minutes.');
INSERT INTO public.stormevents_east VALUES (777214, 201807, 27, 1620, 201807, 27, 1621, 129746, 'GEORGIA', 13, 2018, 'July', 'Lightning', 'CHS', '27-JUL-18 16:20:00', 'EST-5', '27-JUL-18 16:21:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 4, 'NE', 'BELLEVIEW PT', 4, 'NE', 'BELLEVIEW PT', 31.57, -81.32, 31.57, -81.32, 'A cluster of thunderstorms developed near the southeast Georgia coast in advance of a stationary front inland. As these thunderstorms moved to the south and southeast closer to the coast, they interacted with the sea breeze and moved into an environment conducive to the development rotating updrafts. A tornado developed quickly and impacted portions of Chatham County.', 'McIntosh County dispatch reported that a lightning strike started a house fire in Shellman Bluff.');
INSERT INTO public.stormevents_east VALUES (836002, 201807, 19, 755, 201807, 19, 756, 138987, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '19-JUL-18 07:55:00', 'EST-5', '19-JUL-18 07:56:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 7, 'SW', 'HILTON HEAD SOUND', 7, 'SW', 'HILTON HEAD SOUND', 32.12, -80.83, 32.12, -80.83, 'Deep moisture along a stationary front led to numerous showers and thunderstorms capable of producing waterspouts.', 'A picture via social media indicated a waterspout near the mouth of Calibogue Sound.');
INSERT INTO public.stormevents_east VALUES (836006, 201807, 24, 701, 201807, 24, 702, 138989, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '24-JUL-18 07:01:00', 'EST-5', '24-JUL-18 07:02:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 4, 'NE', 'HUNTING ISLAND', 4, 'NE', 'HUNTING ISLAND', 32.41, -80.38, 32.41, -80.38, 'A wave of energy associated with a mid-level low pressure system led to a few showers and thunderstorms capable of producing waterspouts.', 'The public reported a waterspout with a shower off Hunting Island.');
INSERT INTO public.stormevents_east VALUES (775187, 201809, 22, 1210, 201809, 22, 1210, 129376, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Waterspout', 'MLB', '22-SEP-18 12:10:00', 'EST-5', '22-SEP-18 12:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 8, 'ENE', 'STUART', 8, 'ENE', 'STUART', 27.24, -80.13, 27.24, -80.13, 'Deep moisture was set up across much of the Florida peninsula. An upper-level low located in the western Gulf of Mexico was causing scattered showers and isolated thunderstorms to develop in the Atlantic waters off the east Florida coast. Modest east winds at the surface pushed these showers and storms towards the coast. As one shower approached the northeast Martin County coast it produced a short-lived waterspout east of Jensen Beach.', 'Pictures relayed via social media of a waterspout offshore east of Jensen Beach. Observers noted the spout lasted from 1210 to 1220 LST.');
INSERT INTO public.stormevents_east VALUES (775188, 201809, 22, 1217, 201809, 22, 1217, 129376, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Waterspout', 'MLB', '22-SEP-18 12:17:00', 'EST-5', '22-SEP-18 12:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 8, 'ENE', 'STUART', 8, 'ENE', 'STUART', 27.24, -80.13, 27.24, -80.13, 'Deep moisture was set up across much of the Florida peninsula. An upper-level low located in the western Gulf of Mexico was causing scattered showers and isolated thunderstorms to develop in the Atlantic waters off the east Florida coast. Modest east winds at the surface pushed these showers and storms towards the coast. As one shower approached the northeast Martin County coast it produced a short-lived waterspout east of Jensen Beach.', 'Pictures relayed via social media of a waterspout offshore east of Jensen Beach. Observers noted the spout lasted from 1210 to 1220 LST.');
INSERT INTO public.stormevents_east VALUES (753183, 201805, 15, 1410, 201805, 15, 1410, 125581, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'RNK', '15-MAY-18 14:10:00', 'EST-5', '15-MAY-18 14:10:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'N', 'MEDLEY', 1, 'N', 'MEDLEY', 37.34, -80, 37.34, -80, 'A very moist and unstable environment set the stage for convection during the afternoon hours. Conditions were ripe enough that very little forcing was required and therefore the main impulse to trigger the storms was orographic lift, with additional storm development initiated through intersecting outflows.', NULL);
INSERT INTO public.stormevents_east VALUES (753184, 201805, 15, 1630, 201805, 15, 1630, 125582, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RNK', '15-MAY-18 16:30:00', 'EST-5', '15-MAY-18 16:30:00', 0, 0, 0, 0, '1.00K', NULL, 'Public', 50, 'EG', NULL, NULL, 0, 'SW', 'ALTA', 0, 'SW', 'ALTA', 37.8672, -80.555, 37.8672, -80.555, 'A very moist and unstable environment set the stage for convection during the afternoon hours. Conditions were ripe enough that very little forcing was required and therefore the main impulse to trigger the storms was orographic lift, with additional storm development initiated through intersecting outflows.', 'Thunderstorm winds brought down a couple of trees onto Route 12 near I-64.');
INSERT INTO public.stormevents_east VALUES (749855, 201805, 18, 1530, 201805, 18, 2130, 124890, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '18-MAY-18 15:30:00', 'EST-5', '18-MAY-18 21:30:00', 0, 0, 0, 0, '800.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'MARTINSVILLE', 3, 'S', 'MARTINSVILLE', 36.6914, -79.9102, 36.6304, -79.8803, 'The synoptic pattern remained little changed from the previous day with deep moisture in place.  Several bands of very heavy rainfall pushed north from the Carolinas in the late afternoon and evening as weak area of low pressure over the southeast lifted slowly northward. The slow-moving storms were highly efficient rainfall producers that affected number of areas in southside Virginia, most notably the Martinsville and Danville areas. Rainfall totals were generally 2 to 4 inches occurring over a several hour period with isolated higher amounts.', 'Numerous roads were flooded across the City of Martinsville and several homes were flooded. The roof of a department store partially collapsed due to the weight of water. A local state of emergency was declared by the City Council in the aftermath due to the massive cleanup required. Local sources stated that 4 to 5 inches of rain fell in approximately one hour.');
INSERT INTO public.stormevents_east VALUES (753487, 201805, 19, 2036, 201805, 19, 2038, 125626, 'VIRGINIA', 51, 2018, 'May', 'Tornado', 'RNK', '19-MAY-18 20:36:00', 'EST-5', '19-MAY-18 20:38:00', 0, 0, 0, 0, '25.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 4, 'SSW', 'BEDFORD CITY', 3, 'SSW', 'BEDFORD CITY', 37.2779, -79.5621, 37.2926, -79.5593, 'Warm and humid conditions had been in place for several days leading up to this event. A weak upper level system passed through the region, sparking showers and thunderstorms, mainly during the afternoon and evening hours. One storm did spin up a brief and weak tornado.', 'A tornado briefly touched down just south of Mount Olivet Road and moved North-Northeast, lifting before reaching a row of high voltage power lines about one mile Southwest of Hidden Oaks Lane. The tornado traveled over mostly open farmland. Approximately 50 trees were snapped or uprooted but no damage to any structures was noted. Most of the damage was consistent with EF-0, however an isolated damage indicator showed EF-1 damage.');
INSERT INTO public.stormevents_east VALUES (759680, 201805, 19, 2005, 201805, 19, 2005, 126687, 'VIRGINIA', 51, 2018, 'May', 'Debris Flow', 'RNK', '19-MAY-18 20:05:00', 'EST-5', '19-MAY-18 20:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'BEDFORD CITY', 1, 'SW', 'BEDFORD CITY', 37.325, -79.5363, 37.3247, -79.5364, 'A cluster of thunderstorms developed along a stationary front and produced torrential rains across parts of Patrick, Henry and Franklin counties. Rainfall was estimated at 2 to 3 inches in a few hours.', 'Heavy rain triggered a mudslide on the eastbound lane of U.S. Highway 460 near the route 122 intersection.');
INSERT INTO public.stormevents_east VALUES (745459, 201805, 12, 1740, 201805, 12, 1740, 124093, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '12-MAY-18 17:40:00', 'EST-5', '12-MAY-18 17:40:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 0, 'NNE', 'HILLSBORO', 0, 'NNE', 'HILLSBORO', 40.1828, -78.8683, 40.1828, -78.8683, 'Numerous showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across Pennsylvania.  Several of these storms produced wind damage and/or large hail, primarily along and south of the Route 22 corridor.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires west of Hillsboro.');
INSERT INTO public.stormevents_east VALUES (745460, 201805, 12, 1755, 201805, 12, 1755, 124093, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '12-MAY-18 17:55:00', 'EST-5', '12-MAY-18 17:55:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WNW', 'GRANITE HILL', 1, 'WNW', 'GRANITE HILL', 39.8552, -77.1925, 39.8552, -77.1925, 'Numerous showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across Pennsylvania.  Several of these storms produced wind damage and/or large hail, primarily along and south of the Route 22 corridor.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires east of Gettysburg.');
INSERT INTO public.stormevents_east VALUES (745461, 201805, 12, 1802, 201805, 12, 1802, 124093, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '12-MAY-18 18:02:00', 'EST-5', '12-MAY-18 18:02:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'ESE', 'WINDSOR', 0, 'ESE', 'WINDSOR', 39.918, -76.5713, 39.918, -76.5713, 'Numerous showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across Pennsylvania.  Several of these storms produced wind damage and/or large hail, primarily along and south of the Route 22 corridor.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires along Craley Road near Windsor.');
INSERT INTO public.stormevents_east VALUES (745462, 201805, 12, 1820, 201805, 12, 1820, 124093, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '12-MAY-18 18:20:00', 'EST-5', '12-MAY-18 18:20:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'S', 'RED LION', 1, 'S', 'RED LION', 39.8906, -76.6209, 39.8906, -76.6209, 'Numerous showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across Pennsylvania.  Several of these storms produced wind damage and/or large hail, primarily along and south of the Route 22 corridor.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree and wires along Dairyland Road.');
INSERT INTO public.stormevents_east VALUES (745463, 201805, 12, 1825, 201805, 12, 1825, 124093, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '12-MAY-18 18:25:00', 'EST-5', '12-MAY-18 18:25:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WNW', 'RAWLINSVILLE', 1, 'WNW', 'RAWLINSVILLE', 39.8879, -76.2918, 39.8879, -76.2918, 'Numerous showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across Pennsylvania.  Several of these storms produced wind damage and/or large hail, primarily along and south of the Route 22 corridor.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires west of Rawlinsville.');
INSERT INTO public.stormevents_east VALUES (745688, 201805, 10, 1515, 201805, 10, 1515, 124031, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'CTP', '10-MAY-18 15:15:00', 'EST-5', '10-MAY-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.88, NULL, NULL, NULL, 0, 'N', 'SHIPPENSBURG', 0, 'N', 'SHIPPENSBURG', 40.05, -77.52, 40.05, -77.52, 'A cold front crossed central Pennsylvania during the afternoon and early evening hours of May 10, 2018. This front touched off several broken lines of convection, with storms producing both large hail and wind damage.  The largest storm produced ping pong ball-sized hail in southern York County.', 'A thunderstorm produced nickel-sized hail in Shippensburg.');
INSERT INTO public.stormevents_east VALUES (754818, 201805, 31, 1520, 201805, 31, 1520, 125887, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'MRX', '31-MAY-18 15:20:00', 'EST-5', '31-MAY-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'HAYESVILLE', 1, 'E', 'HAYESVILLE', 35.05, -83.82, 35.05, -83.82, 'A few severe thunderstorms developed over or near the major terrain areas including the Cumberland Plateau and the Appalachian Mountains in the Vicinity of the Tennessee and North Carolina border.', 'Several trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (761589, 201805, 26, 1818, 201805, 26, 1818, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 18:18:00', 'EST-5', '26-MAY-18 18:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 37, 'MG', NULL, NULL, 2, 'E', 'KEY WEST', 2, 'E', 'KEY WEST', 24.5571, -81.7554, 24.5571, -81.7554, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 37 knots was measured at Key West International Airport.');
INSERT INTO public.stormevents_east VALUES (761591, 201805, 26, 1818, 201805, 26, 1818, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 18:18:00', 'EST-5', '26-MAY-18 18:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 2, 'SW', 'BIG COPPITT KEY', 2, 'SW', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 38 knots was measured at the Naval Air Station Key West Boca Chica Field.');
INSERT INTO public.stormevents_east VALUES (761593, 201805, 26, 1836, 201805, 26, 1836, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 18:36:00', 'EST-5', '26-MAY-18 18:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'WNW', 'KEY WEST', 1, 'WNW', 'KEY WEST', 24.5671, -81.7979, 24.5671, -81.7979, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at an automated WeatherFlow station at the U.S. Coast Guard Sector Key West.');
INSERT INTO public.stormevents_east VALUES (761595, 201805, 26, 1841, 201805, 26, 1841, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 18:41:00', 'EST-5', '26-MAY-18 18:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 1, 'WNW', 'KEY WEST', 1, 'WNW', 'KEY WEST', 24.5671, -81.7979, 24.5671, -81.7979, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 37 knots was measured at an automated WeatherFlow station at the U.S. Coast Guard Sector Key West.');
INSERT INTO public.stormevents_east VALUES (761601, 201805, 26, 1850, 201805, 26, 1850, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 18:50:00', 'EST-5', '26-MAY-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 0, 'SSW', 'SOMBRERO KEY LIGHT', 0, 'SSW', 'SOMBRERO KEY LIGHT', 24.628, -81.111, 24.628, -81.111, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 35 knots was measured at the new Sombrero Key Light.');
INSERT INTO public.stormevents_east VALUES (745437, 201805, 14, 1324, 201805, 14, 1324, 124154, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '14-MAY-18 13:24:00', 'EST-5', '14-MAY-18 13:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 4, 'SW', 'BAKERSVILLE', 4, 'SW', 'BAKERSVILLE', 40.0168, -79.2733, 40.0168, -79.2733, 'A frontal boundary was draped NW to SE across central Pennsylvania on May 14, 2018, with southwestern Pennsylvania located in the warm sector.  A broken line of storms developed over eh Pittsburgh area and progressed southeastward across Somerset County, producing spotty wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree just east of the Seven Springs resort.');
INSERT INTO public.stormevents_east VALUES (745444, 201805, 10, 1700, 201805, 10, 1700, 124031, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '10-MAY-18 17:00:00', 'EST-5', '10-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 55, 'MG', NULL, NULL, 1, 'E', 'SHREWSBURY', 1, 'E', 'SHREWSBURY', 39.77, -76.67, 39.77, -76.67, 'A cold front crossed central Pennsylvania during the afternoon and early evening hours of May 10, 2018. This front touched off several broken lines of convection, with storms producing both large hail and wind damage.  The largest storm produced ping pong ball-sized hail in southern York County.', 'A severe thunderstorm produced a wind gust of 63 mph near Shrewsbury.');
INSERT INTO public.stormevents_east VALUES (774868, 201809, 14, 1400, 201809, 17, 900, 129284, 'SOUTH CAROLINA', 45, 2018, 'September', 'Heavy Rain', 'CAE', '14-SEP-18 14:00:00', 'EST-5', '17-SEP-18 09:00:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 1, 'W', 'JEFFERSON', 1, 'W', 'JEFFERSON', 34.65, -80.39, 34.65, -80.39, 'Hurricane Florence began as an area of disturbed weather that moved west off the African coast around August 29-30, 2018.  It gradually developed into a tropical cyclone on August 31, 2018 while just south of the Cape Verde islands.  The cyclone continued to move to the WNW across the Atlantic Ocean in the ensuing two weeks, undergoing fluctuations in intensity.  The cyclone reorganized and strengthened into a category 4 hurricane on Monday, September 10 while centered around 1200 miles SE of the coast of the Carolinas. High pressure located north of the cyclone steered the hurricane to the NW. After undergoing some weakening due to some upper shear, Florence made landfall as a category 1 hurricane on the southern coast of NC near Wilmington Friday morning Sept. 14.  The center of the cyclone then moved slowly west across eastern and central SC while weakening into a tropical storm through Saturday night Sept 15.  Florence weakened into a tropical depression Sunday morning Sept 16 and began to turn to the north and accelerate, moving across the Upstate of SC and western NC through Sunday night.  ||The strongest wind gust in the Midlands of SC was 54 MPH at Shaw AFB near Sumter on the night of Friday September 14th.  Reports of downed trees and power lines were received across the central and eastern Midlands due to strong wind gusts. ||The greatest impact to the region from Florence was flooding due to very heavy rainfall. Rain began late day Friday Sept 14th and continued through early Monday morning Sept 17th. The heaviest rain occurred on the north and east side of Florence, across much of NC, as well as over eastern and northeastern SC. The greatest total rainfall amount in the Midlands of SC was 22.58 inches at the water plant in Cheraw, SC. Major flooding was reported in Chesterfield County SC, where numerous roads and bridges were flooded and washed out. Significant flooding was also reported in Lancaster County, SC. ||The Great Pee Dee River at Cheraw experienced major flooding, peaking at 46.6 feet (flood stage 30.0 ft) on Tuesday morning Sept. 18th.  This was the 3rd highest crest on record at that location, and the highest crest there since 1945.', 'Public observer in the town of Jefferson reported a total rainfall amount, associated with Tropical Cyclone Florence, of 16.84 inches.  The rain fell from late afternoon Friday Sept. 14th through early morning Monday Sept. 17th.');
INSERT INTO public.stormevents_east VALUES (744811, 201805, 4, 1945, 201805, 4, 1947, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 19:45:00', 'EST-5', '04-MAY-18 19:47:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Utility Company', 55, 'EG', NULL, NULL, 0, 'N', 'DANBY', 0, 'N', 'DANBY', 43.35, -73, 43.35, -73, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Numerous trees and utility lines down.');
INSERT INTO public.stormevents_east VALUES (744812, 201805, 4, 2015, 201805, 4, 2017, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 20:15:00', 'EST-5', '04-MAY-18 20:17:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SW', 'ASCUTNEY', 1, 'SW', 'ASCUTNEY', 43.41, -72.41, 43.41, -72.41, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Trees downed by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (744814, 201805, 4, 1955, 201805, 4, 1956, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 19:55:00', 'EST-5', '04-MAY-18 19:56:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 0, 'W', 'CONCORD', 0, 'W', 'CONCORD', 44.43, -71.89, 44.43, -71.89, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Several trees and utility lines down.');
INSERT INTO public.stormevents_east VALUES (745434, 201805, 13, 1634, 201805, 13, 1635, 124156, 'PENNSYLVANIA', 42, 2018, 'May', 'Tornado', 'CTP', '13-MAY-18 16:34:00', 'EST-5', '13-MAY-18 16:35:00', 0, 0, 0, 0, '50.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'WNW', 'GRAY', 1, 'WNW', 'GRAY', 40.1377, -79.1034, 40.1336, -79.0948, 'An EF1 tornado was confirmed in Gray, Somerset County, by a NWS storm survey. Maximum wind speeds were estimated at 90 mph, with a path length of one-half to three-quarters of a mile and a maximum path width of 100 yards.', 'The tornado started northwest of the intersection of Beam Church Rd|and Wigstrom Rd where several trees fell and a house sustained minor|siding damage. The tornado crossed Beam Church Rd and continued east|southeast into Gray. Several buildings sustained roof or siding|damage from downed trees. Many trees were completely uprooted|because of saturated soil with standing water underneath the root|ball. The tornado crossed W 3rd street where it flipped a car port|and moved a trailer about 6 feet. A large patch of shingles was|tossed over a house and landed on a car windshield.||Further east, several healthy trees were snapped 10-30 feet off the|ground consistent with winds of up to 90 mph. Healthy pines fell in|a convergent pattern perpendicular to storm motion. This pattern is|consistent with a tornado. The tornado appears to have lifted right|before a stream in the block bordered by W 3rd Street, E 1st Street,|Main St and Center St.');
INSERT INTO public.stormevents_east VALUES (745487, 201805, 18, 1945, 201805, 18, 2145, 124230, 'KENTUCKY', 21, 2018, 'May', 'Flash Flood', 'JKL', '18-MAY-18 19:45:00', 'EST-5', '18-MAY-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'ANNVILLE', 1, 'NW', 'WELCHBURG', 37.3271, -83.9515, 37.3255, -83.9359, 'Numerous showers and thunderstorms developed this afternoon, extending into the evening ahead of an upper level disturbance. While storms were progressive in nature, continued development and repeated rounds of moderate to heavy rainfall over certain locations led to instances of flash flooding. The heavy rainfall also caused a mudslide which damaged a mobile home in Perry County. Additionally, a cloud to ground lightning strike near Somerset set a hay barn on fire.', 'Dispatch reported water flowing over the road between Kentucky Highway 3630 and U.S. Highway 421 east of Annville.');
INSERT INTO public.stormevents_east VALUES (745510, 201805, 15, 1640, 201805, 15, 1640, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'CTP', '15-MAY-18 16:40:00', 'EST-5', '15-MAY-18 16:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1, NULL, NULL, NULL, 1, 'SSW', 'GETTYSBURG', 1, 'SSW', 'GETTYSBURG', 39.8199, -77.2341, 39.8199, -77.2341, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm produced quarter-sized hail near Gettysburg.');
INSERT INTO public.stormevents_east VALUES (748502, 201805, 12, 1435, 201805, 12, 1440, 124760, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '12-MAY-18 14:35:00', 'EST-5', '12-MAY-18 14:40:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'NW', 'ALSTON', 1, 'NW', 'ALSTON', 32.09, -82.49, 32.09, -82.49, 'A very moist and moderately unstable atmosphere combined with strong daytime heating resulted in an isolated thunderstorm producing strong wind gusts.', 'The Montgomery County Emergency Manager reported damage to the roof of a mobile home on Browning Road near the Alston community. Metal roof sheeting that had been installed over an existing shingle roof was peeled off of a mobile home.');
INSERT INTO public.stormevents_east VALUES (776116, 201807, 2, 1815, 201807, 2, 1815, 129537, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 18:15:00', 'EST-5', '02-JUL-18 18:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'ATHENS', 0, 'N', 'ATHENS', 41.95, -76.52, 41.95, -76.52, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees on Route 220, just north of a PENNDOT shed.');
INSERT INTO public.stormevents_east VALUES (776135, 201807, 4, 1417, 201807, 4, 1417, 129538, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'BGM', '04-JUL-18 14:17:00', 'EST-5', '04-JUL-18 14:17:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'BROOKDALE', 1, 'W', 'BROOKDALE', 41.98, -75.81, 41.98, -75.81, 'A stationary front wavered across northern Pennsylvania during the day on the 4th. This front sparked a severe thunderstorm in Susquehanna County, Pennsylvania.', 'Strong thunderstorm winds knocked down trees.');
INSERT INTO public.stormevents_east VALUES (746996, 201805, 21, 2104, 201805, 21, 2107, 124321, 'OHIO', 39, 2018, 'May', 'Tornado', 'ILN', '21-MAY-18 21:04:00', 'EST-5', '21-MAY-18 21:07:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'WNW', 'BARDWELL', 1, 'S', 'UNION PLAINS', 39.053, -83.9283, 39.0604, -83.8951, 'Thunderstorms developed during the late afternoon and evening hours in a warm and unstable air mass that was in place across the region.', 'The  tornado initially touched down on the west side of U.S. Highway 68 near Donley Road where a large tree was snapped and lying across the road. The tornado crossed U.S. Highway 68 causing sporadic tree damage on the east side of the highway. A grove of trees several hundred yards from the road suffered more substantial tree damage with numerous trees either uprooted or snapped. The tornado continued northeast to Hillcrest Road, where a grove of trees on the west side of the road showed sporadic snapped and uprooted trees. A residence on the east side of the road had minor roof damage, a chimney blown off, and several uprooted and snapped trees. The tornado began lifting further to the northeast in the vicinity of Crawford-Day Road, where several trees and large limbs were snapped.');
INSERT INTO public.stormevents_east VALUES (747013, 201805, 27, 100, 201805, 27, 200, 124506, 'OHIO', 39, 2018, 'May', 'Flash Flood', 'ILN', '27-MAY-18 01:00:00', 'EST-5', '27-MAY-18 02:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'LOGAN OWENS FLD ARPT', 2, 'ESE', 'LOGAN OWENS FLD ARPT', 39.59, -82.34, 39.5925, -82.3383, 'Slow moving thunderstorms produced locally heavy rainfall during the early morning hours.', 'A high water rescue was needed due to a car being trapped in high water at the intersection of State Route 93 and Route 668.');
INSERT INTO public.stormevents_east VALUES (779367, 201808, 10, 1450, 201808, 10, 1715, 130142, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PBZ', '10-AUG-18 14:50:00', 'EST-5', '10-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'COCHRANS MILL', 1, 'N', 'COCHRANS MILL', 40.2934, -79.9708, 40.2924, -79.9706, 'Showers and thunderstorms formed along a nearly stationary boundary that crept southeastward from the Great Lakes.  Precipitable water values of around 1.6 inches and weak steering flow along the boundary led to a few areas of training thunderstorms.  Rainfall amounts of 1.5 to 3.0 inches on already saturated ground led to several areas of flash flooding in Washington, Allegheny, and Westmoreland Counties.  The worst flooding was near Herminie, where up to 14 homes were impacted and a mobile home was shifted off of its foundation.', 'The county emergency manager reported that the police found a vehicle stranded with people inside at 1000 Cochran Mill Road.');
INSERT INTO public.stormevents_east VALUES (755925, 201805, 12, 1645, 201805, 12, 1646, 126107, 'SOUTH CAROLINA', 45, 2018, 'May', 'Thunderstorm Wind', 'ILM', '12-MAY-18 16:45:00', 'EST-5', '12-MAY-18 16:46:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 50, 'MG', NULL, NULL, 1, 'W', 'DARLINGTON CO ARPT', 1, 'W', 'DARLINGTON CO ARPT', 34.45, -79.89, 34.45, -79.89, 'A trough produced a strong thunderstorm in Darlington.', 'A 58 mph wind gust was recorded at an AWOS north of Darlington.');
INSERT INTO public.stormevents_east VALUES (755938, 201805, 28, 1030, 201805, 28, 1230, 126113, 'SOUTH CAROLINA', 45, 2018, 'May', 'Flash Flood', 'ILM', '28-MAY-18 10:30:00', 'EST-5', '28-MAY-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LITTLE RIVER', 2, 'NE', 'CHERRY GROVE BEACH', 33.8555, -78.62, 33.8394, -78.6139, 'A trough extending from Tropical Storm Alberto produced heavy rain and flash flooding.', 'Flooding has made the road impassable at 4600 Eastport Blvd.');
INSERT INTO public.stormevents_east VALUES (755946, 201805, 19, 1526, 201805, 19, 1800, 126115, 'NORTH CAROLINA', 37, 2018, 'May', 'Flood', 'ILM', '19-MAY-18 15:26:00', 'EST-5', '19-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'EAST WILMINGTON', 1, 'SW', 'EAST WILMINGTON', 34.21, -77.89, 34.2116, -77.8888, 'Very moist flow off the Atlantic produced flooding in southeast North Carolina.', 'There was about a foot of water along College Rd at the intersection of Oleander Drive.');
INSERT INTO public.stormevents_east VALUES (772584, 201809, 6, 1154, 201809, 6, 1157, 128822, 'OHIO', 39, 2018, 'September', 'Thunderstorm Wind', 'ILN', '06-SEP-18 11:54:00', 'EST-5', '06-SEP-18 11:57:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NE', 'HEATH', 1, 'NE', 'HEATH', 40.03, -82.44, 40.03, -82.44, 'Scattered thunderstorms developed during the afternoon in an unstable air mass that was in place across the region.', 'A tree and some large branches were downed in the Granville and Newark areas.');
INSERT INTO public.stormevents_east VALUES (756892, 201805, 22, 1435, 201805, 22, 1435, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 14:35:00', 'EST-5', '22-MAY-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'E', 'BENTON', 2, 'E', 'BENTON', 40.934, -83.0382, 40.934, -83.0382, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds downed a tree on Orr Road.');
INSERT INTO public.stormevents_east VALUES (756893, 201805, 22, 1409, 201805, 22, 1409, 126226, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '22-MAY-18 14:09:00', 'EST-5', '22-MAY-18 14:09:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SE', 'LYKENS', 2, 'SE', 'LYKENS', 40.9503, -82.9972, 40.9503, -82.9972, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Thunderstorm winds downed a tree west of Chatfield near the intersection of Kennedy Road and State Route 103.');
INSERT INTO public.stormevents_east VALUES (756827, 201805, 22, 1301, 201805, 22, 1310, 126226, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '22-MAY-18 13:01:00', 'EST-5', '22-MAY-18 13:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'PARMA HGTS', 0, 'N', 'PARMA HGTS', 41.38, -81.77, 41.38, -81.77, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Penny sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (756833, 201805, 22, 1450, 201805, 22, 1450, 126226, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '22-MAY-18 14:50:00', 'EST-5', '22-MAY-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'ASHLAND', 0, 'N', 'ASHLAND', 40.87, -82.3, 40.87, -82.3, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Penny sized hail was observed.');
INSERT INTO public.stormevents_east VALUES (756674, 201805, 4, 1228, 201805, 4, 1228, 126126, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '04-MAY-18 12:28:00', 'EST-5', '04-MAY-18 12:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 3, 'ESE', 'TOLEDO', 3, 'ESE', 'TOLEDO', 41.6334, -83.4963, 41.6334, -83.4963, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Penny sized hail was observed.');
INSERT INTO public.stormevents_east VALUES (756697, 201805, 21, 1930, 201805, 21, 1930, 125542, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '21-MAY-18 19:30:00', 'EST-5', '21-MAY-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 0, 'N', 'LEXINGTON', 0, 'N', 'LEXINGTON', 40.67, -82.58, 40.67, -82.58, 'Strong thunderstorms evolved across western Ohio during the afternoon and moved into central Ohio around 6-6:30 pm. Severe storms with winds and hail were prevalent. By the evening the storms began train along a warm front and old lake breeze boundary over the Central Highlands of Morrow and Richland counties. Storms intensified and slowed along this boundary, with the heaviest rainfall localized over Lexington. Flash flooding resulted.', 'Penny sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (756673, 201805, 4, 1228, 201805, 4, 1228, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 12:28:00', 'EST-5', '04-MAY-18 12:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 3, 'ESE', 'TOLEDO', 3, 'ESE', 'TOLEDO', 41.6334, -83.4963, 41.6334, -83.4963, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'A member of the general public estimated thunderstorm wind gusts at 60 mph.');
INSERT INTO public.stormevents_east VALUES (756683, 201805, 15, 950, 201805, 15, 954, 126223, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '15-MAY-18 09:50:00', 'EST-5', '15-MAY-18 09:54:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', 52, 'EG', NULL, NULL, 0, 'WSW', 'EAST UNION', 0, 'WSW', 'EAST UNION', 40.7983, -81.8255, 40.7983, -81.8255, 'A cold front moved east across northern Ohio during the morning hours of May 15th.  An area of showers and thunderstorms developed in advance of the front.  One of the thunderstorms became severe in Wayne County causing some damage.', 'A thunderstorm downburst with winds estimated to be more that 60 mph caused some damage in West Union Township.  Most of the damage occurred along Millborne Road where four properties sustained minor damage.  One house had a screened porch damaged and an adjacent house had a portion of a fence knocked down by a flying trampoline.  Two other homes sustained minor damage from fallen trees.   Several trees and large limbs in the area were downed resulted in power outages.');
INSERT INTO public.stormevents_east VALUES (750528, 201805, 27, 1805, 201805, 27, 2105, 125158, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RNK', '27-MAY-18 18:05:00', 'EST-5', '27-MAY-18 21:05:00', 0, 0, 0, 0, '250.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'SPEEDWAY', 1, 'WNW', 'SPEEDWAY', 37.4447, -81.0211, 37.452, -81.0108, 'Locally heavy downpours over central Mercer County produced flash flooding in several small basins near Athens, WV. Dual-pol radar estimated more than 4 inches fell in a 3-hour period ending around 600 PM EST and an automated gauge measured 4.53 inches in Athens of which 3.5 inches fell in one hour from 420 to 520 PM EST.', 'Flooding was reported on several small creeks, including Laurel Creek and Tracy Fork north and east of Athens and at the town water treatment plant. Several private bridges were destroyed in the area near Red Sulphur Turnpike near Athens. A section of Red Sulphur Turnpike was badly damaged and impassable.');
INSERT INTO public.stormevents_east VALUES (750533, 201805, 27, 1850, 201805, 27, 2150, 125158, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RNK', '27-MAY-18 18:50:00', 'EST-5', '27-MAY-18 21:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'ATHENS', 0, 'SW', 'SPEEDWAY', 37.4336, -81.0121, 37.4451, -81.0055, 'Locally heavy downpours over central Mercer County produced flash flooding in several small basins near Athens, WV. Dual-pol radar estimated more than 4 inches fell in a 3-hour period ending around 600 PM EST and an automated gauge measured 4.53 inches in Athens of which 3.5 inches fell in one hour from 420 to 520 PM EST.', 'A spotter reported several culvert underneath a road being overtopped.');
INSERT INTO public.stormevents_east VALUES (759327, 201805, 27, 1615, 201805, 27, 1915, 125158, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RNK', '27-MAY-18 16:15:00', 'EST-5', '27-MAY-18 19:15:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'JUDSON', 1, 'NNW', 'JUDSON', 37.7082, -80.7767, 37.7092, -80.7828, 'Locally heavy downpours over central Mercer County produced flash flooding in several small basins near Athens, WV. Dual-pol radar estimated more than 4 inches fell in a 3-hour period ending around 600 PM EST and an automated gauge measured 4.53 inches in Athens of which 3.5 inches fell in one hour from 420 to 520 PM EST.', 'Judson Road near Talcott was caved and flooded by flowing water.');
INSERT INTO public.stormevents_east VALUES (759377, 201805, 19, 2330, 201805, 20, 230, 126687, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '19-MAY-18 23:30:00', 'EST-5', '20-MAY-18 02:30:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'BASSETT FORKS', 2, 'NE', 'BASSETT FORKS', 36.73, -79.94, 36.7438, -79.9264, 'A cluster of thunderstorms developed along a stationary front and produced torrential rains across parts of Patrick, Henry and Franklin counties. Rainfall was estimated at 2 to 3 inches in a few hours.', 'Route 220 was flooded in at least four places just south of Bassett Forks near where Reed Creek enters the Smith River. One car was submerged in flood waters in the median and the driver rescued without injury. Several trees were brought down by mudslides along the highway. At a mobile home park near Blackberry Park Circle several rescues by boat were required. Numerous approach roads were flooded hindering rescue operations. Multiple vehicles were damaged as drivers attempted to drive through high water.');
INSERT INTO public.stormevents_east VALUES (753520, 201805, 20, 1633, 201805, 20, 1633, 125633, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RNK', '20-MAY-18 16:33:00', 'EST-5', '20-MAY-18 16:33:00', 0, 0, 0, 0, '2.50K', NULL, 'Fire Department/Rescue', 60, 'EG', NULL, NULL, 1, 'ENE', 'HARTMAN', 1, 'ENE', 'HARTMAN', 36.4231, -80.1704, 36.4231, -80.1704, 'Afternoon thunderstorms formed in a warm and unstable environment. A couple storms produced winds strong enough to down a few trees in northwest North Carolina.', 'Thunderstorm winds brought down five trees onto Sheppards Mill Road.');
INSERT INTO public.stormevents_east VALUES (753530, 201805, 20, 1522, 201805, 20, 1522, 125633, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RNK', '20-MAY-18 15:22:00', 'EST-5', '20-MAY-18 15:22:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'RONDA', 2, 'ENE', 'RONDA', 36.244, -80.8921, 36.244, -80.8921, 'Afternoon thunderstorms formed in a warm and unstable environment. A couple storms produced winds strong enough to down a few trees in northwest North Carolina.', 'Thunderstorm winds knocked down a tree on J J A Russell Drive.');
INSERT INTO public.stormevents_east VALUES (753532, 201805, 20, 1541, 201805, 20, 1541, 125633, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RNK', '20-MAY-18 15:41:00', 'EST-5', '20-MAY-18 15:41:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'CLINGMAN', 3, 'SE', 'CLINGMAN', 36.146, -80.8932, 36.146, -80.8932, 'Afternoon thunderstorms formed in a warm and unstable environment. A couple storms produced winds strong enough to down a few trees in northwest North Carolina.', 'Thunderstorm winds knocked down a tree on Dennyville Road.');
INSERT INTO public.stormevents_east VALUES (753533, 201805, 20, 1548, 201805, 20, 1548, 125633, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RNK', '20-MAY-18 15:48:00', 'EST-5', '20-MAY-18 15:48:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 60, 'EG', NULL, NULL, 1, 'E', 'BOONVILLE', 1, 'E', 'BOONVILLE', 36.23, -80.71, 36.23, -80.71, 'Afternoon thunderstorms formed in a warm and unstable environment. A couple storms produced winds strong enough to down a few trees in northwest North Carolina.', 'Thunderstorm winds knocked down trees and power lines in Booneville.');
INSERT INTO public.stormevents_east VALUES (753536, 201805, 20, 1554, 201805, 20, 1554, 125633, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RNK', '20-MAY-18 15:54:00', 'EST-5', '20-MAY-18 15:54:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'S', 'WINDY GAP', 3, 'S', 'WINDY GAP', 36.0808, -80.9775, 36.0808, -80.9775, 'Afternoon thunderstorms formed in a warm and unstable environment. A couple storms produced winds strong enough to down a few trees in northwest North Carolina.', 'Thunderstorm winds knocked down a tree near the intersection of Highway 115 and Hunting Creek Road.');
INSERT INTO public.stormevents_east VALUES (753513, 201805, 20, 1501, 201805, 20, 1501, 125633, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RNK', '20-MAY-18 15:01:00', 'EST-5', '20-MAY-18 15:01:00', 0, 0, 0, 0, '2.00K', NULL, 'Trained Spotter', 55, 'EG', NULL, NULL, 1, 'SE', 'THURMOND', 3, 'SE', 'THURMOND', 36.3597, -80.9212, 36.34, -80.9, 'Afternoon thunderstorms formed in a warm and unstable environment. A couple storms produced winds strong enough to down a few trees in northwest North Carolina.', 'Thunderstorm winds caused roof damage to a home and brought down a couple of trees.');
INSERT INTO public.stormevents_east VALUES (744713, 201805, 10, 1500, 201805, 10, 1600, 124099, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RLX', '10-MAY-18 15:00:00', 'EST-5', '10-MAY-18 16:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'WESTON', 1, 'NW', 'BEN DALE', 39.03, -80.45, 39.0339, -80.4925, 'Showers and thunderstorms popped up on the afternoon of the 10th as a surface front drifted through. A set of storms trained over the same area, causing some localized flash flooding.', 'Heavy rain caused water to flow down several streets after overwhelming ditches and culverts.');
INSERT INTO public.stormevents_east VALUES (744714, 201805, 10, 1310, 201805, 10, 1310, 124100, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'RLX', '10-MAY-18 13:10:00', 'EST-5', '10-MAY-18 13:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'W', 'ASHLAND', 1, 'W', 'ASHLAND', 38.47, -82.64, 38.47, -82.64, 'Showers and thunderstorms developed on the afternoon of the 10th as a front moved through. One of these storms became rather strong, producing some isolated wind damage.', 'One tree and several limbs were blown down in Central Park in Ashland. Another tree was blown down along Sucks Creek Road.');
INSERT INTO public.stormevents_east VALUES (744715, 201805, 10, 1355, 201805, 10, 1355, 124099, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'RLX', '10-MAY-18 13:55:00', 'EST-5', '10-MAY-18 13:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.88, NULL, NULL, NULL, 2, 'W', 'IRONTOWN', 2, 'W', 'IRONTOWN', 39.38, -79.96, 39.38, -79.96, 'Showers and thunderstorms popped up on the afternoon of the 10th as a surface front drifted through. A set of storms trained over the same area, causing some localized flash flooding.', 'Over an inch of hail covered the ground, with the largest stones the size of nickels.');
INSERT INTO public.stormevents_east VALUES (745890, 201805, 21, 1745, 201805, 21, 1745, 124329, 'KENTUCKY', 21, 2018, 'May', 'Hail', 'RLX', '21-MAY-18 17:45:00', 'EST-5', '21-MAY-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.88, NULL, NULL, NULL, 1, 'NNE', 'OLDTOWN', 1, 'NNE', 'OLDTOWN', 38.45, -82.89, 38.45, -82.89, 'Showers and thunderstorms formed on the afternoon of the 21st as a warm front lifted across the middle Ohio River Valley. One of the storms produced wind damage and hail.', NULL);
INSERT INTO public.stormevents_east VALUES (745891, 201805, 21, 1745, 201805, 21, 1745, 124329, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'RLX', '21-MAY-18 17:45:00', 'EST-5', '21-MAY-18 17:45:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'OLDTOWN', 1, 'N', 'OLDTOWN', 38.44, -82.9, 38.44, -82.9, 'Showers and thunderstorms formed on the afternoon of the 21st as a warm front lifted across the middle Ohio River Valley. One of the storms produced wind damage and hail.', 'Two trees were blown down along Route 1 near Oldtown.');
INSERT INTO public.stormevents_east VALUES (775714, 201807, 17, 1532, 201807, 17, 1602, 129017, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'OKX', '17-JUL-18 15:32:00', 'EST-5', '17-JUL-18 16:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'CENTRAL PARK', 1, 'SSW', 'CENTRAL PARK', 40.7602, -73.9579, 40.761, -73.9565, 'Showers and thunderstorms developed in a moist and unstable airmass ahead of an approaching cold front, leading to isolated flash flooding across parts of the New York City Metro area. Precipitable water values during the afternoon were around 2 inches, and the ASOS in Central Park recorded 2.22 inches of rain, the majority of which fell within a 2-3 hour period.', 'All lanes blocked on the northbound ramp to the FDR Drive and East 62nd Street in Manhattan due to flooding.');
INSERT INTO public.stormevents_east VALUES (775710, 201807, 28, 1630, 201807, 28, 1715, 129478, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'OKX', '28-JUL-18 16:30:00', 'EST-5', '28-JUL-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TOWNERS', 1, 'ENE', 'LAKE CARMEL', 41.4738, -73.6441, 41.4739, -73.6462, 'A cold front stalled across the region during the afternoon, resulting in widely scattered showers and thunderstorms, primarily across the Lower Hudson Valley. With plenty of moisture available in the atmosphere, these storms resulted in isolated flash flooding across parts of northeastern Putnam County. A cooperative observer in Carmel, NY measured 1.39 inches of rain from this event.', 'Ludingtonville Road was closed along I-84 in Lake Carmel due to flooding.');
INSERT INTO public.stormevents_east VALUES (775712, 201807, 28, 1645, 201807, 28, 1715, 129478, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'OKX', '28-JUL-18 16:45:00', 'EST-5', '28-JUL-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'PATTERSON', 1, 'SSE', 'PATTERSON', 41.5145, -73.6124, 41.5118, -73.6175, 'A cold front stalled across the region during the afternoon, resulting in widely scattered showers and thunderstorms, primarily across the Lower Hudson Valley. With plenty of moisture available in the atmosphere, these storms resulted in isolated flash flooding across parts of northeastern Putnam County. A cooperative observer in Carmel, NY measured 1.39 inches of rain from this event.', 'Route 311 was closed in Patterson due to flooding.');
INSERT INTO public.stormevents_east VALUES (761602, 201805, 26, 1859, 201805, 26, 1859, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 18:59:00', 'EST-5', '26-MAY-18 18:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 36 knots was measured at an automated Citizen Weather Observing Program station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (761603, 201805, 26, 1917, 201805, 26, 1917, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 19:17:00', 'EST-5', '26-MAY-18 19:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 7, 'SW', 'PLANTATION KEY', 7, 'SW', 'PLANTATION KEY', 24.9189, -80.6351, 24.9189, -80.6351, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 39 knots was measured at an automated WeatherFlow station on Upper Matecumbe Key.');
INSERT INTO public.stormevents_east VALUES (761604, 201805, 26, 2003, 201805, 26, 2003, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 20:03:00', 'EST-5', '26-MAY-18 20:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 35 knots was measured at an automated Citizen Weather Observing Station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (761607, 201805, 26, 2006, 201805, 26, 2006, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 20:06:00', 'EST-5', '26-MAY-18 20:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'E', 'KEY WEST', 2, 'E', 'KEY WEST', 24.5571, -81.7554, 24.5571, -81.7554, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at Key West International Airport.');
INSERT INTO public.stormevents_east VALUES (761610, 201805, 26, 2018, 201805, 26, 2018, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 20:18:00', 'EST-5', '26-MAY-18 20:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 39 knots was measured at an automated Citizen Weather Observing Program station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (744815, 201805, 4, 2010, 201805, 4, 2012, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 20:10:00', 'EST-5', '04-MAY-18 20:12:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Utility Company', 55, 'EG', NULL, NULL, 2, 'NNW', 'FAIRLEE', 2, 'NNW', 'FAIRLEE', 43.93, -72.17, 43.93, -72.17, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Trees and utility lines down along Rte 244.');
INSERT INTO public.stormevents_east VALUES (744816, 201805, 4, 1944, 201805, 4, 1944, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 19:44:00', 'EST-5', '04-MAY-18 19:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 2, 'SE', 'DANBY FOUR CORNERS', 2, 'SE', 'DANBY FOUR CORNERS', 43.33, -73.03, 43.33, -73.03, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', NULL);
INSERT INTO public.stormevents_east VALUES (744817, 201805, 4, 2013, 201805, 4, 2015, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 20:13:00', 'EST-5', '04-MAY-18 20:15:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Utility Company', 55, 'EG', NULL, NULL, 0, 'N', 'THETFORD', 0, 'N', 'THETFORD', 43.82, -72.23, 43.82, -72.23, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Multiple trees and utility lines down.');
INSERT INTO public.stormevents_east VALUES (745492, 201805, 13, 1632, 201805, 13, 1632, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:32:00', 'EST-5', '13-MAY-18 16:32:00', 0, 0, 0, 0, '5.00K', '0.00K', 'NWS Storm Survey', 70, 'EG', NULL, NULL, 2, 'WNW', 'GRAY', 2, 'WNW', 'GRAY', 40.1405, -79.1096, 40.1405, -79.1096, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 80 mph knocked down trees onto a home in the 200 block of Tipton Road west of Gray.');
INSERT INTO public.stormevents_east VALUES (745493, 201805, 13, 1632, 201805, 13, 1632, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:32:00', 'EST-5', '13-MAY-18 16:32:00', 0, 0, 0, 0, '15.00K', '0.00K', 'NWS Storm Survey', 70, 'EG', NULL, NULL, 2, 'WNW', 'GRAY', 2, 'WNW', 'GRAY', 40.139, -79.1132, 40.139, -79.1132, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 80 mph destroyed a large machine shed on Saint Clair Drive west of Gray.');
INSERT INTO public.stormevents_east VALUES (745507, 201805, 15, 1526, 201805, 15, 1526, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'CTP', '15-MAY-18 15:26:00', 'EST-5', '15-MAY-18 15:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'SW', 'MECHANICSBURG', 1, 'SW', 'MECHANICSBURG', 40.21, -77.01, 40.21, -77.01, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm produced quarter-sized hail near Mechanicsburg.');
INSERT INTO public.stormevents_east VALUES (745518, 201805, 15, 1156, 201805, 15, 1156, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 11:56:00', 'EST-5', '15-MAY-18 11:56:00', 0, 0, 0, 0, '8.00K', '0.00K', 'NWS Storm Survey', 78, 'EG', NULL, NULL, 2, 'NNE', 'DENTS RUN', 2, 'NNE', 'DENTS RUN', 41.3979, -78.2597, 41.3979, -78.2597, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 90 mph knocked down numerous trees and wires along Huston Hill Road.');
INSERT INTO public.stormevents_east VALUES (745540, 201805, 15, 1345, 201805, 15, 1345, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:45:00', 'EST-5', '15-MAY-18 13:45:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 0, 'E', 'TURBOTVILLE', 0, 'E', 'TURBOTVILLE', 41.1004, -76.7709, 41.1004, -76.7709, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in Turbotville.');
INSERT INTO public.stormevents_east VALUES (745544, 201805, 15, 1355, 201805, 15, 1355, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:55:00', 'EST-5', '15-MAY-18 13:55:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', 70, 'EG', NULL, NULL, 1, 'SW', 'DANVILLE', 1, 'SW', 'DANVILLE', 40.9623, -76.6103, 40.9623, -76.6103, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 80 mph knocked down numerous trees in Danville.');
INSERT INTO public.stormevents_east VALUES (744969, 201805, 4, 1918, 201805, 4, 2115, 124117, 'VERMONT', 50, 2018, 'May', 'Flash Flood', 'BTV', '04-MAY-18 19:18:00', 'EST-5', '04-MAY-18 21:15:00', 0, 0, 0, 0, '400.00K', '0.00K', 'NWS Employee', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'NASHVILLE', 0, 'NE', 'NASHVILLE', 44.447, -72.927, 44.452, -72.927, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Brief training thunderstorms dumped nearly an inch of rain within 10 minutes and up to 2 inches of rain in less than an hour. Several roads were flooded, including the corner of Bentley Lane and Nashville road in Nashville with partial road washouts in Richmond and greater washouts in Bolton.');
INSERT INTO public.stormevents_east VALUES (748516, 201805, 20, 1620, 201805, 20, 1620, 124764, 'GEORGIA', 13, 2018, 'May', 'Lightning', 'FFC', '20-MAY-18 16:20:00', 'EST-5', '20-MAY-18 16:20:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', NULL, NULL, NULL, NULL, 5, 'ESE', 'DACULA', 5, 'ESE', 'DACULA', 33.9418, -83.8224, 33.9418, -83.8224, 'A persistent moist and moderately unstable air mass over the region, combined with afternoon heating and a weak mid/upper-level low over south Georgia resulted in a cluster of severe thunderstorms producing damaging wind gusts across portions of north Georgia.', 'The Gwinnett County Emergency Manager reported a house struck by lightning near the intersection of Berry Hall Road and Marlborough Drive.');
INSERT INTO public.stormevents_east VALUES (776118, 201807, 2, 1455, 201807, 2, 1455, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 14:55:00', 'EST-5', '02-JUL-18 14:55:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'AUBURN', 0, 'N', 'AUBURN', 42.93, -76.57, 42.93, -76.57, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776119, 201807, 2, 1530, 201807, 2, 1530, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 15:30:00', 'EST-5', '02-JUL-18 15:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'WATERLOO', 1, 'E', 'WATERLOO', 42.9, -76.86, 42.9, -76.86, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees and wires on Inslee Street.');
INSERT INTO public.stormevents_east VALUES (776121, 201807, 2, 1550, 201807, 2, 1550, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 15:50:00', 'EST-5', '02-JUL-18 15:50:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'CAMILLUS', 1, 'NW', 'CAMILLUS', 43.04, -76.31, 43.04, -76.31, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees and wires on Genessee Road.');
INSERT INTO public.stormevents_east VALUES (749197, 201805, 17, 700, 201805, 17, 700, 124870, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'RNK', '17-MAY-18 07:00:00', 'EST-5', '17-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'SSW', 'CAVE SPG', 2, 'SSW', 'CAVE SPG', 37.1979, -80.0367, 37.1979, -80.0367, 'A weak frontal boundary located near the I-64 corridor provided the focus for repeated thunderstorm activity through the evening across several counties. A broad area of low pressure over the southeastern U.S. pulled very high moisture into the region allowing the slow-moving storms to be efficient rainfall producers. Rainfall amount were generally 2 to 4 inches, with isolated higher totals indicated by radar in the heavier cores occurring over a several hour period.', 'The CoCoRaHS observer at Cave Spring 2.4 SSW had a 24-hour total of 4.53 inches. This is just below the 0.1 annual chance rainfall or nearly a 10-year recurrence interval.');
INSERT INTO public.stormevents_east VALUES (749844, 201805, 17, 700, 201805, 18, 700, 124870, 'VIRGINIA', 51, 2018, 'May', 'Heavy Rain', 'RNK', '17-MAY-18 07:00:00', 'EST-5', '18-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'W', 'STEWARTSVILLE', 2, 'W', 'STEWARTSVILLE', 37.27, -79.8364, 37.27, -79.8364, 'A weak frontal boundary located near the I-64 corridor provided the focus for repeated thunderstorm activity through the evening across several counties. A broad area of low pressure over the southeastern U.S. pulled very high moisture into the region allowing the slow-moving storms to be efficient rainfall producers. Rainfall amount were generally 2 to 4 inches, with isolated higher totals indicated by radar in the heavier cores occurring over a several hour period.', 'The CoCoRaHS observer at Vinton 2.6 E had 6.86 inches of rain for the 24-hours ending at 700 AM EST. This amount exceeds the 50-year recurrence interval (0.02 annual exceedance probability) for this location and duration.');
INSERT INTO public.stormevents_east VALUES (750011, 201805, 27, 1725, 201805, 27, 1925, 124482, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RLX', '27-MAY-18 17:25:00', 'EST-5', '27-MAY-18 19:25:00', 0, 0, 0, 0, '25.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ROCKY FORK', 2, 'ESE', 'ROCKY FORK', 38.4653, -81.7229, 38.4368, -81.6917, 'The combination of daytime heating and an approaching upper level trough led to scattered thunderstorm development on the afternoon and evenings of the 26th, 27th and 28th. While these storms were slow moving, most moved enough to limit flooding. However, several storms stalled out or kept regenerating over one spot, leading to flash flooding.', 'Several roads were flooded in the Cross Lanes area. This included Doc Bailey Road near Kelly Road. Along Armour Creek, sections of Cross Lanes Drive, 40th Street and Timber Creek Lane flooded. Three homes also had minor water damage, two had a few inches of water on the main flow, and the third had a flooded basement.');
INSERT INTO public.stormevents_east VALUES (750021, 201805, 30, 1525, 201805, 30, 1525, 125053, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'RLX', '30-MAY-18 15:25:00', 'EST-5', '30-MAY-18 15:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 43, 'EG', NULL, NULL, 1, 'ESE', 'FLATWOODS', 1, 'ESE', 'FLATWOODS', 38.51, -82.7, 38.51, -82.7, 'As subtropical storm Alberto moved into the Mississippi Valley, strong thunderstorms formed in the outer bands of the storm over the middle Ohio River Valley on the 30th. As the remnants moved towards the Great Lakes, additional showers and storms moved through on the 31st.', 'A Kroger sign was blown down. Winds with this storm were estimated to be around 50 mph.');
INSERT INTO public.stormevents_east VALUES (750022, 201805, 31, 1700, 201805, 31, 1700, 125053, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'RLX', '31-MAY-18 17:00:00', 'EST-5', '31-MAY-18 17:00:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Social Media', 43, 'EG', NULL, NULL, 1, 'SW', 'ASHLAND', 1, 'SW', 'ASHLAND', 38.46, -82.64, 38.46, -82.64, 'As subtropical storm Alberto moved into the Mississippi Valley, strong thunderstorms formed in the outer bands of the storm over the middle Ohio River Valley on the 30th. As the remnants moved towards the Great Lakes, additional showers and storms moved through on the 31st.', 'A tree was blown over and fell onto a house.');
INSERT INTO public.stormevents_east VALUES (750023, 201805, 30, 1640, 201805, 30, 1640, 125054, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'RLX', '30-MAY-18 16:40:00', 'EST-5', '30-MAY-18 16:40:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'NELSONVILLE', 1, 'S', 'NELSONVILLE', 39.46, -82.23, 39.46, -82.23, 'As subtropical storm Alberto moved into the Mississippi Valley, strong thunderstorms formed in the outer bands of the storm over the middle Ohio River Valley on the 30th. As the remnants moved towards the Great Lakes, additional showers and storms moved through on the 31st.', 'A few trees were blown down near Nelsonville.');
INSERT INTO public.stormevents_east VALUES (750024, 201805, 30, 1640, 201805, 30, 1640, 125054, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'RLX', '30-MAY-18 16:40:00', 'EST-5', '30-MAY-18 16:40:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'POMEROY', 1, 'NW', 'POMEROY', 39.04, -82.04, 39.04, -82.04, 'As subtropical storm Alberto moved into the Mississippi Valley, strong thunderstorms formed in the outer bands of the storm over the middle Ohio River Valley on the 30th. As the remnants moved towards the Great Lakes, additional showers and storms moved through on the 31st.', 'Multiple trees were blown down between Chester and Sumner. One fell on a power line.');
INSERT INTO public.stormevents_east VALUES (750027, 201805, 30, 1550, 201805, 30, 1550, 125055, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '30-MAY-18 15:50:00', 'EST-5', '30-MAY-18 15:50:00', 0, 0, 0, 0, '0.50K', '0.00K', 'NWS Employee', 43, 'EG', NULL, NULL, 0, 'N', 'SATTES', 0, 'N', 'SATTES', 38.38, -81.82, 38.38, -81.82, 'As subtropical storm Alberto moved into the Mississippi Valley, strong thunderstorms formed in the outer bands of the storm over the middle Ohio River Valley on the 30th. As the remnants moved towards the Great Lakes, additional showers and storms moved through on the 31st.', 'A large tree branch was blown down. Wind gusts estimated around 50 mph.');
INSERT INTO public.stormevents_east VALUES (747700, 201805, 30, 1513, 201805, 30, 1515, 124616, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '30-MAY-18 15:13:00', 'EST-5', '30-MAY-18 15:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'PITCHIN', 2, 'NE', 'PITCHIN', 39.85, -83.75, 39.85, -83.75, 'Scattered thunderstorms developed across the region as the remnants of Sub Tropical Storm Alberto lifted north through the Ohio Valley.', 'A tree was downed.');
INSERT INTO public.stormevents_east VALUES (752001, 201805, 31, 1730, 201805, 31, 1730, 125054, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'RLX', '31-MAY-18 17:30:00', 'EST-5', '31-MAY-18 17:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'NNW', 'CORNERVILLE', 2, 'NNW', 'CORNERVILLE', 39.425, -81.3911, 39.425, -81.3911, 'As subtropical storm Alberto moved into the Mississippi Valley, strong thunderstorms formed in the outer bands of the storm over the middle Ohio River Valley on the 30th. As the remnants moved towards the Great Lakes, additional showers and storms moved through on the 31st.', 'Multiple trees were blown down and some shingles were blown off a house along Route 26.');
INSERT INTO public.stormevents_east VALUES (748750, 201805, 15, 1500, 201805, 15, 1600, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Hail', 'BOX', '15-MAY-18 15:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '70.00K', '0.00K', 'Broadcast Media', 2.5, NULL, NULL, NULL, 0, 'N', 'GRANBY', 0, 'N', 'GRANBY', 41.95, -72.78, 41.95, -72.78, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 3:15 PM EST, car windshields and house windows in Granby were smashed by tennis ball size hail.  Tennis ball size hail was also reported in East Hartland.');
INSERT INTO public.stormevents_east VALUES (759299, 201805, 12, 1443, 201805, 12, 1443, 126655, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '12-MAY-18 14:43:00', 'EST-5', '12-MAY-18 14:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 0, 'N', 'MURRYSVILLE', 0, 'N', 'MURRYSVILLE', 40.43, -79.7, 40.43, -79.7, 'Showers and thunderstorms developed along a stalled frontal boundary that was situated over the upper Ohio Valley. Strong to severe storms resulted in several reports of downed trees and hail in southwestern Pennsylvania and eastern Ohio.', NULL);
INSERT INTO public.stormevents_east VALUES (759300, 201805, 12, 1450, 201805, 12, 1450, 126655, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '12-MAY-18 14:50:00', 'EST-5', '12-MAY-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'S', 'DELMONT', 1, 'S', 'DELMONT', 40.41, -79.57, 40.41, -79.57, 'Showers and thunderstorms developed along a stalled frontal boundary that was situated over the upper Ohio Valley. Strong to severe storms resulted in several reports of downed trees and hail in southwestern Pennsylvania and eastern Ohio.', NULL);
INSERT INTO public.stormevents_east VALUES (771413, 201809, 1, 1645, 201809, 1, 1745, 128608, 'OHIO', 39, 2018, 'September', 'Flash Flood', 'ILN', '01-SEP-18 16:45:00', 'EST-5', '01-SEP-18 17:45:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'WESTERVILLE', 1, 'E', 'WESTERVILLE', 40.1279, -82.9081, 40.1214, -82.8986, 'Scattered thunderstorms developed during the afternoon hours as an upper level disturbance moved through the Ohio Valley. A few of the storms produced locally heavy rainfall.', 'High water was reported on numerous roads through the city of Westerville. Several cars became stranded in the high water.');
INSERT INTO public.stormevents_east VALUES (771607, 201809, 1, 1614, 201809, 1, 1616, 128608, 'OHIO', 39, 2018, 'September', 'Thunderstorm Wind', 'ILN', '01-SEP-18 16:14:00', 'EST-5', '01-SEP-18 16:16:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'ENE', 'GRANDVIEW HGTS', 2, 'ENE', 'GRANDVIEW HGTS', 39.9909, -83, 39.9909, -83, 'Scattered thunderstorms developed during the afternoon hours as an upper level disturbance moved through the Ohio Valley. A few of the storms produced locally heavy rainfall.', 'A few trees and a power pole were downed, damaging three different cars.');
INSERT INTO public.stormevents_east VALUES (756828, 201805, 22, 1318, 201805, 22, 1320, 126226, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '22-MAY-18 13:18:00', 'EST-5', '22-MAY-18 13:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'N', 'NORTH ROYALTON', 0, 'N', 'NORTH ROYALTON', 41.32, -81.73, 41.32, -81.73, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (756836, 201805, 22, 1610, 201805, 22, 1614, 126226, 'OHIO', 39, 2018, 'May', 'Hail', 'CLE', '22-MAY-18 16:10:00', 'EST-5', '22-MAY-18 16:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'ALLIANCE', 0, 'N', 'ALLIANCE', 40.92, -81.1, 40.92, -81.1, 'A cold front moved across northern Ohio causing showers and thunderstorms to develop.  A severe thunderstorm watch was issued for much of the area during the early afternoon. Several severe thunderstorms were reported during the middle and late afternoon hours.', 'Penny sized hail was observed.');
INSERT INTO public.stormevents_east VALUES (748831, 201805, 17, 1800, 201805, 18, 0, 124815, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RNK', '17-MAY-18 18:00:00', 'EST-5', '18-MAY-18 00:00:00', 0, 0, 0, 0, '150.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'RAINES CORNER', 1, 'NW', 'LAUREL BRANCH', 37.5178, -80.6086, 37.5365, -80.527, 'The combination of weak low pressure interacting with a stalled frontal boundary along with the soggy air mass produced very heavy rainfall across parts of Monroe County. Union IFLOWS (UNNW2) had 3.07 most of which fell in several hours. Residents described the flooding as ''the worst they had ever seen''.', 'Indian Creek was reported to be out of its banks and flowing across Route 219 at a depth of at least two feet in the Salt Sulphur Springs area. At least four homes in the same area received flood damage, including a bed and breakfast. The Union Rescue Squad office was also flooded. Several other creeks were reported to be flooded closing more roads.  Route 122 was reported with water over the road in the Raines Corner area. The Indian Creek gauge near Red Sulphur Springs (INCW2) located downstream of the heaviest rain area, crested at 11.62 feet, above the Minor flood stage of 8 feet.');
INSERT INTO public.stormevents_east VALUES (750035, 201805, 17, 2241, 201805, 18, 141, 124815, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'RNK', '17-MAY-18 22:41:00', 'EST-5', '18-MAY-18 01:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'SECOND CREEK', 1, 'N', 'SECOND CREEK', 37.6826, -80.4574, 37.6843, -80.4528, 'The combination of weak low pressure interacting with a stalled frontal boundary along with the soggy air mass produced very heavy rainfall across parts of Monroe County. Union IFLOWS (UNNW2) had 3.07 most of which fell in several hours. Residents described the flooding as ''the worst they had ever seen''.', 'Second Creek was reported in flood closing Second Creek Road.');
INSERT INTO public.stormevents_east VALUES (773423, 201809, 9, 1030, 201809, 9, 1121, 128981, 'KENTUCKY', 21, 2018, 'September', 'Flash Flood', 'JKL', '09-SEP-18 10:30:00', 'EST-5', '09-SEP-18 11:21:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'OLYMPIA', 1, 'NW', 'OLYMPIA', 38.1172, -83.733, 38.1166, -83.7143, 'A slow moving low pressure system, in combination with the remnants of Tropical Cyclone Gordon, and abundant moisture brought a long duration heavy rainfall event to much of the Bluegrass region of eastern Kentucky. Southwesterly low level winds ahead of a very slow moving cold front ushered rich moisture into eastern Kentucky, which when combined with the available lift, resulted in copious amounts of rainfall. This, in combination with several inches of rain the past couple of days, led to widespread flooding and flash flooding as multi-day rainfall amounts of 3-6 inches occurred with isolated totals near 7-8 inches.||Bath, Montgomery, and Menifee Counties all saw significant impacts. This includes 50-70 homes and 20-25 businesses, one of which was a school in Menifee County, being inundated with water. Numerous roads were damaged as culverts were washed out, forcing schools to close the following day. Disaster declarations were made for Montgomery and Menifee Counties while nearly a dozen water rescues were performed. Additionally, a nine year old boy was swept into a culvert in Morehead.', 'Water was observed flowing over Kentucky Highway 36 near Interstate 64 south of Owingsville, resulting in the closure of the road. Additionally, a woman was rescued from rapidly flowing flood waters as her vehicle became submerged northwest of Olympia.');
INSERT INTO public.stormevents_east VALUES (774124, 201809, 9, 1630, 201809, 10, 836, 128981, 'KENTUCKY', 21, 2018, 'September', 'Flood', 'JKL', '09-SEP-18 16:30:00', 'EST-5', '10-SEP-18 08:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'FRENCHBURG', 2, 'E', 'FRENCHBURG', 37.9593, -83.6342, 37.9553, -83.5925, 'A slow moving low pressure system, in combination with the remnants of Tropical Cyclone Gordon, and abundant moisture brought a long duration heavy rainfall event to much of the Bluegrass region of eastern Kentucky. Southwesterly low level winds ahead of a very slow moving cold front ushered rich moisture into eastern Kentucky, which when combined with the available lift, resulted in copious amounts of rainfall. This, in combination with several inches of rain the past couple of days, led to widespread flooding and flash flooding as multi-day rainfall amounts of 3-6 inches occurred with isolated totals near 7-8 inches.||Bath, Montgomery, and Menifee Counties all saw significant impacts. This includes 50-70 homes and 20-25 businesses, one of which was a school in Menifee County, being inundated with water. Numerous roads were damaged as culverts were washed out, forcing schools to close the following day. Disaster declarations were made for Montgomery and Menifee Counties while nearly a dozen water rescues were performed. Additionally, a nine year old boy was swept into a culvert in Morehead.', 'Emergency Management reported lingering flooding late Sunday evening into early Monday, forcing several roads to remain closed for a period of time.');
INSERT INTO public.stormevents_east VALUES (759301, 201805, 12, 1457, 201805, 12, 1457, 126655, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '12-MAY-18 14:57:00', 'EST-5', '12-MAY-18 14:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'S', 'NEW ALEXANDRIA', 1, 'S', 'NEW ALEXANDRIA', 40.39, -79.42, 40.39, -79.42, 'Showers and thunderstorms developed along a stalled frontal boundary that was situated over the upper Ohio Valley. Strong to severe storms resulted in several reports of downed trees and hail in southwestern Pennsylvania and eastern Ohio.', NULL);
