INSERT INTO public.stormevents_east VALUES (745068, 201805, 15, 1650, 201805, 15, 1650, 124103, 'OHIO', 39, 2018, 'May', 'Hail', 'RLX', '15-MAY-18 16:50:00', 'EST-5', '15-MAY-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 0.88, NULL, NULL, NULL, 1, 'E', 'MALTA', 1, 'E', 'MALTA', 39.65, -81.86, 39.65, -81.86, 'As a surface front oscillated north and south across the middle and upper Ohio River Valley, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 12th through 15th. Some of these storms became strong to severe.', NULL);
