INSERT INTO public.stormevents_east VALUES (745413, 201805, 4, 1600, 201805, 4, 1600, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:00:00', 'EST-5', '04-MAY-18 16:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'E', 'GIBBS HILL', 2, 'E', 'GIBBS HILL', 41.755, -78.8729, 41.755, -78.8729, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree across Bliss Hill Road, blocking traffic.');
INSERT INTO public.stormevents_east VALUES (745415, 201805, 4, 1617, 201805, 4, 1617, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:17:00', 'EST-5', '04-MAY-18 16:17:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'SSE', 'EAST SMETHPORT', 2, 'SSE', 'EAST SMETHPORT', 41.7808, -78.4161, 41.7808, -78.4161, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down numerous trees and wires on Irish Hollow Road near Smethport.');
INSERT INTO public.stormevents_east VALUES (745416, 201805, 4, 1624, 201805, 4, 1624, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:24:00', 'EST-5', '04-MAY-18 16:24:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'NW', 'RIDGWAY', 2, 'NW', 'RIDGWAY', 41.4488, -78.7708, 41.4488, -78.7708, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires across the intersection of Grant and Bingham Road near Ridgway.');
INSERT INTO public.stormevents_east VALUES (745417, 201805, 4, 1635, 201805, 4, 1635, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:35:00', 'EST-5', '04-MAY-18 16:35:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'TOBY MINES', 1, 'E', 'TOBY MINES', 41.3499, -78.598, 41.3499, -78.598, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires on South Kersey Road.');
INSERT INTO public.stormevents_east VALUES (745071, 201805, 15, 1630, 201805, 15, 1630, 124103, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'RLX', '15-MAY-18 16:30:00', 'EST-5', '15-MAY-18 16:30:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'CROOKSVILLE', 1, 'E', 'CROOKSVILLE', 39.77, -82.09, 39.77, -82.09, 'As a surface front oscillated north and south across the middle and upper Ohio River Valley, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 12th through 15th. Some of these storms became strong to severe.', 'Trees were downed by thunderstorm winds in the Crooksville area.');
INSERT INTO public.stormevents_east VALUES (745072, 201805, 15, 1650, 201805, 15, 1650, 124103, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'RLX', '15-MAY-18 16:50:00', 'EST-5', '15-MAY-18 16:50:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'NE', 'JOETOWN', 2, 'NE', 'JOETOWN', 39.6851, -81.8919, 39.6851, -81.8919, 'As a surface front oscillated north and south across the middle and upper Ohio River Valley, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 12th through 15th. Some of these storms became strong to severe.', 'State route 669 was blocked by downed trees north of Malta.');
