INSERT INTO public.stormevents_east VALUES (744934, 201805, 14, 1429, 201805, 14, 1429, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'RLX', '14-MAY-18 14:29:00', 'EST-5', '14-MAY-18 14:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'PENNSBORO', 0, 'N', 'PENNSBORO', 39.28, -80.97, 39.28, -80.97, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', NULL);
INSERT INTO public.stormevents_east VALUES (744935, 201805, 14, 1442, 201805, 14, 1442, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'RLX', '14-MAY-18 14:42:00', 'EST-5', '14-MAY-18 14:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1.75, NULL, NULL, NULL, 1, 'E', 'HAZELGREEN', 1, 'E', 'HAZELGREEN', 39.08, -80.98, 39.08, -80.98, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', NULL);
INSERT INTO public.stormevents_east VALUES (744936, 201805, 14, 1523, 201805, 14, 1523, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '14-MAY-18 15:23:00', 'EST-5', '14-MAY-18 15:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 55, 'MG', NULL, NULL, 1, 'NNW', '(EKN)RANDOLPH FLD EL', 1, 'NNW', '(EKN)RANDOLPH FLD EL', 38.8896, -79.8576, 38.8896, -79.8576, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', NULL);
INSERT INTO public.stormevents_east VALUES (744937, 201805, 14, 1543, 201805, 14, 1543, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '14-MAY-18 15:43:00', 'EST-5', '14-MAY-18 15:43:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'HARMAN', 1, 'E', 'HARMAN', 38.92, -79.52, 38.92, -79.52, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'Numerous trees and power lines were knocked down around Harman.');
INSERT INTO public.stormevents_east VALUES (744938, 201805, 14, 1545, 201805, 14, 1545, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '14-MAY-18 15:45:00', 'EST-5', '14-MAY-18 15:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'DRYFORK', 0, 'N', 'DRYFORK', 38.97, -79.5, 38.97, -79.5, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'Multiple trees were blown down.');
INSERT INTO public.stormevents_east VALUES (745908, 201805, 21, 1512, 201805, 21, 1512, 124331, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '21-MAY-18 15:12:00', 'EST-5', '21-MAY-18 15:12:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'S', 'WALTON', 3, 'S', 'WALTON', 38.5913, -81.4052, 38.5913, -81.4052, 'Showers and thunderstorms formed on the afternoon of the 21st as a warm front lifted across the middle Ohio River Valley and central Appalachians.  One of these produced wind damage, and other very heavy rainfall.', 'Multiple trees were blown down near the intersection of Ambler Ridge Road and US 119.');
INSERT INTO public.stormevents_east VALUES (750448, 201805, 25, 1730, 201805, 25, 1740, 124766, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '25-MAY-18 17:30:00', 'EST-5', '25-MAY-18 17:40:00', 0, 0, 0, 0, '5.00K', NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'WNW', 'WRIGHTSVILLE', 2, 'WNW', 'WRIGHTSVILLE', 32.74, -82.75, 32.74, -82.75, 'Deep tropical moisture remained in place across the region. Afternoon heating produced widespread thunderstorms across north and central Georgia with an isolated severe thunderstorm producing damaging wind gusts in central Georgia.', 'The Wrightsville Fire Department reported trees and power lines blown down on Highway 57 west of Wrightsville.');
INSERT INTO public.stormevents_east VALUES (750456, 201805, 28, 1530, 201805, 28, 1545, 124768, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '28-MAY-18 15:30:00', 'EST-5', '28-MAY-18 15:45:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'NW', 'SPRING HILL', 1, 'NW', 'SPRING HILL', 32.0225, -82.7402, 32.0225, -82.7402, 'Strong thunderstorms associated with Tropical Storm Alberto resulted in isolated reports of damaging wind gusts across parts of north and central Georgia.', 'The Wheeler County Emergency Manager reported a tree blown down along Farmers Road.');
INSERT INTO public.stormevents_east VALUES (750459, 201805, 28, 2036, 201805, 28, 2046, 124768, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '28-MAY-18 20:36:00', 'EST-5', '28-MAY-18 20:46:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'HEBRON', 1, 'WSW', 'HEBRON', 34.27, -83.39, 34.27, -83.39, 'Strong thunderstorms associated with Tropical Storm Alberto resulted in isolated reports of damaging wind gusts across parts of north and central Georgia.', 'The Banks County 911 center reported a tree blown down on Sims Bridge Road.');
INSERT INTO public.stormevents_east VALUES (748723, 201805, 6, 200, 201805, 7, 2300, 124799, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'RNK', '06-MAY-18 02:00:00', 'EST-5', '07-MAY-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'N', 'BOZOO', 6, 'NW', 'RED SULPHUR SPGS', 37.5084, -80.8366, 37.5547, -80.8523, 'An upper trough and frontal passage on May 5-6 brought pockets of moderate to heavy rainfall with amounts of 2 to 3 inches across portions of southeast West Virginia.', 'Flooding was reported in several locations in Monroe County. The gauge on Indian Creek near Red Sulphur Springs (INCW2) crested at 12.65 feet, above the Minor flood stage of 8 feet and County Road 23 was flooded. Emergency Management also reported flooding from Indian Creek along parts of Route 122 closing the road.');
INSERT INTO public.stormevents_east VALUES (748740, 201805, 6, 1000, 201805, 6, 1800, 124799, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'RNK', '06-MAY-18 10:00:00', 'EST-5', '06-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'ROCKLAND', 0, 'S', 'ROCKLAND', 37.7227, -80.5263, 37.7261, -80.5198, 'An upper trough and frontal passage on May 5-6 brought pockets of moderate to heavy rainfall with amounts of 2 to 3 inches across portions of southeast West Virginia.', 'Flooding was reported along portions of Second Creek.');
INSERT INTO public.stormevents_east VALUES (749097, 201805, 5, 1900, 201805, 6, 100, 124799, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'RNK', '05-MAY-18 19:00:00', 'EST-5', '06-MAY-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'BROOKLYN', 1, 'SSW', 'BROOKLYN', 37.66, -80.91, 37.6532, -80.9085, 'An upper trough and frontal passage on May 5-6 brought pockets of moderate to heavy rainfall with amounts of 2 to 3 inches across portions of southeast West Virginia.', 'Route 3 was closed due to flooding from Beech Run near Hinton.');
INSERT INTO public.stormevents_east VALUES (749229, 201805, 18, 1421, 201805, 18, 1721, 124894, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'RNK', '18-MAY-18 14:21:00', 'EST-5', '18-MAY-18 17:21:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'KING', 0, 'W', 'DALTON', 36.27, -80.38, 36.3201, -80.4072, 'The synoptic pattern remained little changed from the previous day with deep moisture in place. An axis of very heavy rainfall pushed north across the Carolinas in the late afternoon and evening as the weak area of low pressure over the southeast lifted slowly northward. Slow-moving storms with highly efficient rainfall affected number of areas in the mountains and foothills of northern North Carolina. Rainfall amount were generally 2 to 4 inches over a several hour period with isolated higher amounts.', 'Numerous roads across southwest Stokes County, mainly in the King area were closed or washed out due to flooding. This included Route 52, Brown Road, Briarcreek Road, Chestnut Grove Road, Goff Road and Priddy Road. Damage to a pipe under Briarcreek Road required a replacement. At least two bridges were overtopped but bridge damage was minimal.');
INSERT INTO public.stormevents_east VALUES (749230, 201805, 18, 700, 201805, 19, 700, 124894, 'NORTH CAROLINA', 37, 2018, 'May', 'Heavy Rain', 'RNK', '18-MAY-18 07:00:00', 'EST-5', '19-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'SE', 'BOONE', 1, 'SE', 'BOONE', 36.2098, -81.6673, 36.2098, -81.6673, 'The synoptic pattern remained little changed from the previous day with deep moisture in place. An axis of very heavy rainfall pushed north across the Carolinas in the late afternoon and evening as the weak area of low pressure over the southeast lifted slowly northward. Slow-moving storms with highly efficient rainfall affected number of areas in the mountains and foothills of northern North Carolina. Rainfall amount were generally 2 to 4 inches over a several hour period with isolated higher amounts.', 'The Boone 1 SE COOP (BOON7) observer recorded 3.40 inches for the 24-hours ending at 700 AM EST on the 19th. This is the 2nd highest daily May rainfall since records began at this station in 1980 and the 4th highest May rainfall all-time at Boone (since 1929) if the previous COOP station is considered.');
INSERT INTO public.stormevents_east VALUES (771562, 201807, 2, 1830, 201807, 2, 2030, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '02-JUL-18 18:30:00', 'EST-5', '02-JUL-18 20:30:00', 0, 0, 0, 0, '1.00K', '0.50K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ZELIENOPLE', 1, 'SW', 'ZELIENOPLE', 40.8, -80.14, 40.7937, -80.1416, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The fire department reported that numerous roads were closed in the town of Zelienople due to flooding.');
INSERT INTO public.stormevents_east VALUES (771563, 201807, 2, 1806, 201807, 2, 1806, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '02-JUL-18 18:06:00', 'EST-5', '02-JUL-18 18:06:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'S', 'MARGARET', 1, 'S', 'MARGARET', 40.77, -79.37, 40.77, -79.37, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported multiple trees down along Margaret Road.');
INSERT INTO public.stormevents_east VALUES (756033, 201805, 4, 1427, 201805, 4, 1427, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 14:27:00', 'EST-5', '04-MAY-18 14:27:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'RAVENNA', 0, 'N', 'RAVENNA', 41.17, -81.23, 41.17, -81.23, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Thunderstorm winds downed a few trees across Ravenna Township.');
INSERT INTO public.stormevents_east VALUES (756038, 201805, 4, 1437, 201805, 4, 1437, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 14:37:00', 'EST-5', '04-MAY-18 14:37:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'WSW', 'HOWLAND CORNERS', 2, 'WSW', 'HOWLAND CORNERS', 41.2165, -80.7816, 41.2165, -80.7816, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Thunderstorm winds downed a few trees along Ridge Road south of U.S. Highway 422 on the southeast side of Warren.');
INSERT INTO public.stormevents_east VALUES (756042, 201805, 4, 1442, 201805, 4, 1448, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 14:42:00', 'EST-5', '04-MAY-18 14:48:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'ESE', 'CHURCHILL', 0, 'ESE', 'CHURCHILL', 41.1682, -80.6617, 41.1682, -80.6617, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Thunderstorm winds downed a few trees in Liberty Township.  Scattered power outages occurred in the area.');
INSERT INTO public.stormevents_east VALUES (756204, 201805, 4, 1450, 201805, 4, 1450, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 14:50:00', 'EST-5', '04-MAY-18 14:50:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'NNE', 'HUBBARD', 0, 'NNE', 'HUBBARD', 41.1546, -80.567, 41.1546, -80.567, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Thunderstorm winds snapped a power pole on Oak Knoll Drive in Hubbard.');
INSERT INTO public.stormevents_east VALUES (756205, 201805, 4, 1437, 201805, 4, 1437, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 14:37:00', 'EST-5', '04-MAY-18 14:37:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'LAKE MILTON', 1, 'W', 'LAKE MILTON', 41.0982, -80.9897, 41.0982, -80.9897, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Thunderstorm winds toppled a tree along Interstate 76 near the Portage County line.');
INSERT INTO public.stormevents_east VALUES (756207, 201805, 4, 1330, 201805, 4, 1330, 126126, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '04-MAY-18 13:30:00', 'EST-5', '04-MAY-18 13:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'SE', 'PERRYSBURG', 2, 'SE', 'PERRYSBURG', 41.5505, -83.6104, 41.5505, -83.6104, 'A cold front marched across northern Ohio during the afternoon of May 4th.  A line of thunderstorms developed in advance of the front and caused some damage.  Most of the damage was from downed trees and power lines but there were a few reports of lost siding and roofing material.  A severe thunderstorm watch box was in effect for most of northern Ohio.', 'Thunderstorm winds downed a tree on Willow Lane in Perrysburg.');
INSERT INTO public.stormevents_east VALUES (751148, 201805, 4, 1844, 201805, 4, 1844, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:44:00', 'EST-5', '04-MAY-18 18:44:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 1, 'NW', 'FT JOHNSON', 1, 'NW', 'FT JOHNSON', 42.96, -74.24, 42.96, -74.24, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A tree was reported down.');
INSERT INTO public.stormevents_east VALUES (751437, 201805, 4, 1803, 201805, 4, 1803, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:03:00', 'EST-5', '04-MAY-18 18:03:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'ENE', 'CEDAR LAKE', 2, 'ENE', 'CEDAR LAKE', 42.9656, -75.1275, 42.9656, -75.1275, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Wires down on Jerusalem Hill Road.');
INSERT INTO public.stormevents_east VALUES (773837, 201809, 2, 1154, 201809, 2, 1154, 129111, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Marine Thunderstorm Wind', 'MLB', '02-SEP-18 11:54:00', 'EST-5', '02-SEP-18 11:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 40, 'SSE', 'MICCO', 40, 'SSE', 'MICCO', 27.35, -80.24, 27.35, -80.24, 'The combination of stout east wind flow and influence from an upper-level area of low pressure brought in sufficient moisture and instability that allowed for showers and some thunderstorms to develop over the open Atlantic waters. These showers and storms then quickly pushed west towards the Florida peninsula. As these showers and storms came onshore, one cluster produced strong wind gusts along the St. Lucie County coast during the early afternoon. A secondary set of fast moving showers and thunderstorms moved across the Cape in Brevard County and produced strong winds along the intracoastal.', 'Weatherflow site XSTL at the St. Lucie Nuclear Power Plant measured a peak wind gust of 35 knots from the west.');
INSERT INTO public.stormevents_east VALUES (773329, 201809, 7, 1825, 201809, 7, 1825, 128974, 'NEW JERSEY', 34, 2018, 'September', 'Thunderstorm Wind', 'PHI', '07-SEP-18 18:25:00', 'EST-5', '07-SEP-18 18:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'E', 'BLACKWOOD', 1, 'E', 'BLACKWOOD', 39.8, -75.06, 39.8, -75.06, 'Locally heavy rain fell in the northwestern parts of Gloucester County and Camden County during the late afternoon and evening of September 7.  Rainfall totals ranged from 3 to 5 inches.  A supercell developed along a boundary and produced isolated wind damage.', 'Several tree limbs down near Blackwood. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (773410, 201809, 9, 830, 201809, 10, 730, 128981, 'KENTUCKY', 21, 2018, 'September', 'Flood', 'JKL', '09-SEP-18 08:30:00', 'EST-5', '10-SEP-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'KENDALL SPGS', 2, 'SSW', 'PEASTICKS', 38.1, -83.81, 38.123, -83.741, 'A slow moving low pressure system, in combination with the remnants of Tropical Cyclone Gordon, and abundant moisture brought a long duration heavy rainfall event to much of the Bluegrass region of eastern Kentucky. Southwesterly low level winds ahead of a very slow moving cold front ushered rich moisture into eastern Kentucky, which when combined with the available lift, resulted in copious amounts of rainfall. This, in combination with several inches of rain the past couple of days, led to widespread flooding and flash flooding as multi-day rainfall amounts of 3-6 inches occurred with isolated totals near 7-8 inches.||Bath, Montgomery, and Menifee Counties all saw significant impacts. This includes 50-70 homes and 20-25 businesses, one of which was a school in Menifee County, being inundated with water. Numerous roads were damaged as culverts were washed out, forcing schools to close the following day. Disaster declarations were made for Montgomery and Menifee Counties while nearly a dozen water rescues were performed. Additionally, a nine year old boy was swept into a culvert in Morehead.', 'Water was observed across Stepstone Road southwest of Owingsville, as well as along Kentucky Highway 36 near Interstate 64.');
INSERT INTO public.stormevents_east VALUES (773411, 201809, 9, 830, 201809, 10, 730, 128981, 'KENTUCKY', 21, 2018, 'September', 'Flood', 'JKL', '09-SEP-18 08:30:00', 'EST-5', '10-SEP-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 4, 'WSW', 'REYNOLDSVILLE', 3, 'WSW', 'REYNOLDSVILLE', 38.16, -83.88, 38.165, -83.8713, 'A slow moving low pressure system, in combination with the remnants of Tropical Cyclone Gordon, and abundant moisture brought a long duration heavy rainfall event to much of the Bluegrass region of eastern Kentucky. Southwesterly low level winds ahead of a very slow moving cold front ushered rich moisture into eastern Kentucky, which when combined with the available lift, resulted in copious amounts of rainfall. This, in combination with several inches of rain the past couple of days, led to widespread flooding and flash flooding as multi-day rainfall amounts of 3-6 inches occurred with isolated totals near 7-8 inches.||Bath, Montgomery, and Menifee Counties all saw significant impacts. This includes 50-70 homes and 20-25 businesses, one of which was a school in Menifee County, being inundated with water. Numerous roads were damaged as culverts were washed out, forcing schools to close the following day. Disaster declarations were made for Montgomery and Menifee Counties while nearly a dozen water rescues were performed. Additionally, a nine year old boy was swept into a culvert in Morehead.', 'Water of an unknown depth was observed flowing across Flat Creek Road southeast of Sharpsburg.');
INSERT INTO public.stormevents_east VALUES (758337, 201805, 17, 2000, 201805, 17, 2230, 126513, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '17-MAY-18 20:00:00', 'EST-5', '17-MAY-18 22:30:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'MARION', 2, 'SSW', 'EAST MARION', 35.679, -82.003, 35.673, -81.987, 'Slow moving, training heavy rain showers and thunderstorms developed near the Blue Ridge escarpment during the evening and produced localized rainfall amounts as high as 3 to 4 inches in just a couple of hours. This resulted in some minor flash flooding.', 'EM reported multiple roads in central McDowell County were impacted by stream flooding after 3 to 4 inches of rain fell in just a couple of hours. These included Mud Cut Road, Old Fort Sugar Hill Road, Zion Hill Road, and Bond Street in West Marion. Youngs Fork Creek overflowed its banks on the south side of Marion and briefly flooded Currier Court at Currier Avenue. Nix Creek also overflowed its banks and isolated some homes south of Marion.');
INSERT INTO public.stormevents_east VALUES (758338, 201805, 17, 2100, 201805, 17, 2230, 126513, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '17-MAY-18 21:00:00', 'EST-5', '17-MAY-18 22:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 4, 'SSE', 'BLUE RIDGE', 3, 'SSE', 'BLUE RIDGE', 35.533, -82.305, 35.531, -82.315, 'Slow moving, training heavy rain showers and thunderstorms developed near the Blue Ridge escarpment during the evening and produced localized rainfall amounts as high as 3 to 4 inches in just a couple of hours. This resulted in some minor flash flooding.', 'Public reported (via Social Media) more than a foot of water from an overflowing Garren Creek flooding the intersection of Garren Creek Rd and Morgan Hill Rd after more than three inches of rain fell in only a couple of hours.');
INSERT INTO public.stormevents_east VALUES (760137, 201805, 17, 2245, 201805, 18, 1900, 126513, 'NORTH CAROLINA', 37, 2018, 'May', 'Flood', 'GSP', '17-MAY-18 22:45:00', 'EST-5', '18-MAY-18 19:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'CALHOUN', 1, 'W', 'GRANGE', 35.243, -82.636, 35.232, -82.643, 'Slow moving, training heavy rain showers and thunderstorms developed near the Blue Ridge escarpment during the evening and produced localized rainfall amounts as high as 3 to 4 inches in just a couple of hours. This resulted in some minor flash flooding.', 'Less than 18 hours after an earlier flood event ended along the Little River, a stream gauge exceeded its established flood stage once again after another round of heavy rain and remained in minor flood conditions for almost 24 hours. The main impact was to lowlands along the stream and to Cascade Lake Rd, which was covered by more than a foot of water in spots. Total rainfall in the basin was 2 to 3 inches from the 17th through early on the 18th. The long duration of the flooding was partly due to backwater affects from the French Broad River, which remained in moderate flood stage near Blantyre for much of this time frame.');
INSERT INTO public.stormevents_east VALUES (759212, 201805, 20, 1810, 201805, 20, 1810, 126639, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'GSP', '20-MAY-18 18:10:00', 'EST-5', '20-MAY-18 18:10:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'E', 'MORLAN PARK', 2, 'E', 'MORLAN PARK', 35.63, -80.439, 35.629, -80.423, 'Scattered to numerous thunderstorms developed over the North Carolina foothills and western Piedmont during the afternoon. One storm produced brief damaging winds in Rowan County.', 'Public reported (via Social Media), a tree down on Dunns Mountain Church Rd and a tree on a house on Stokes Ferry Rd.');
INSERT INTO public.stormevents_east VALUES (759213, 201805, 20, 1530, 201805, 20, 1530, 126639, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '20-MAY-18 15:30:00', 'EST-5', '20-MAY-18 15:30:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 0.88, NULL, NULL, NULL, 1, 'W', 'GRANITE FALLS', 1, 'W', 'GRANITE FALLS', 35.8, -81.44, 35.8, -81.44, 'Scattered to numerous thunderstorms developed over the North Carolina foothills and western Piedmont during the afternoon. One storm produced brief damaging winds in Rowan County.', 'Ham Radio operator reported pea to nickel size hail in the Granite Falls area.');
INSERT INTO public.stormevents_east VALUES (759370, 201805, 21, 1706, 201805, 21, 2006, 126685, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '21-MAY-18 17:06:00', 'EST-5', '21-MAY-18 20:06:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'CALLISON', 1, 'SE', 'BACOVA JCT', 37.9778, -79.8986, 38.0114, -79.8584, 'Storms developed in the late afternoon dropping very heavy rain across southern Bath County and produced localized flash flooding near Bacova Junction. Rainfall was estimated by radar at approximately 4 to 5 inches in about 2 hours.', 'Route 687 near Bacova Junction was closed in several spots with water and debris running across the road. The valley bottom was flooded up to near the houses and several culverts and parts of the road were damaged.');
INSERT INTO public.stormevents_east VALUES (759755, 201805, 4, 1855, 201805, 4, 1855, 126731, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '04-MAY-18 18:55:00', 'EST-5', '04-MAY-18 18:55:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'DELHI', 1, 'E', 'DELHI', 42.28, -74.91, 42.28, -74.91, 'A strong area of low pressure tracked from the Great Lakes to the Saint Lawrence Valley from the morning of the the 4th to the evening hours. This low pulled a warm front north of central New York in the morning and then a strong cold front across central New York and northeast Pennsylvania during the evening hours. This front triggered a line of severe thunderstorms that moved across central New York and northeast Pennsylvania the evening of the 4th.', 'Thunderstorm winds blew down numerous trees and wires.');
INSERT INTO public.stormevents_east VALUES (759756, 201805, 4, 1900, 201805, 4, 1900, 126731, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '04-MAY-18 19:00:00', 'EST-5', '04-MAY-18 19:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'HANCOCK', 0, 'N', 'HANCOCK', 41.95, -75.28, 41.95, -75.28, 'A strong area of low pressure tracked from the Great Lakes to the Saint Lawrence Valley from the morning of the the 4th to the evening hours. This low pulled a warm front north of central New York in the morning and then a strong cold front across central New York and northeast Pennsylvania during the evening hours. This front triggered a line of severe thunderstorms that moved across central New York and northeast Pennsylvania the evening of the 4th.', 'Thunderstorm winds blew down trees and wires.');
INSERT INTO public.stormevents_east VALUES (759757, 201805, 4, 1925, 201805, 4, 1925, 126731, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '04-MAY-18 19:25:00', 'EST-5', '04-MAY-18 19:25:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'NORTH BRANCH', 0, 'N', 'NORTH BRANCH', 41.8, -75, 41.8, -75, 'A strong area of low pressure tracked from the Great Lakes to the Saint Lawrence Valley from the morning of the the 4th to the evening hours. This low pulled a warm front north of central New York in the morning and then a strong cold front across central New York and northeast Pennsylvania during the evening hours. This front triggered a line of severe thunderstorms that moved across central New York and northeast Pennsylvania the evening of the 4th.', 'Thunderstorm winds blew down wires.');
INSERT INTO public.stormevents_east VALUES (759758, 201805, 4, 1925, 201805, 4, 1925, 126731, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '04-MAY-18 19:25:00', 'EST-5', '04-MAY-18 19:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'HORTONVILLE', 0, 'N', 'HORTONVILLE', 41.77, -75.03, 41.77, -75.03, 'A strong area of low pressure tracked from the Great Lakes to the Saint Lawrence Valley from the morning of the the 4th to the evening hours. This low pulled a warm front north of central New York in the morning and then a strong cold front across central New York and northeast Pennsylvania during the evening hours. This front triggered a line of severe thunderstorms that moved across central New York and northeast Pennsylvania the evening of the 4th.', 'Thunderstorm winds blew down trees and wires.');
INSERT INTO public.stormevents_east VALUES (759759, 201805, 4, 1927, 201805, 4, 1927, 126731, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '04-MAY-18 19:27:00', 'EST-5', '04-MAY-18 19:27:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'COCHECTON', 0, 'N', 'COCHECTON', 41.7, -75.05, 41.7, -75.05, 'A strong area of low pressure tracked from the Great Lakes to the Saint Lawrence Valley from the morning of the the 4th to the evening hours. This low pulled a warm front north of central New York in the morning and then a strong cold front across central New York and northeast Pennsylvania during the evening hours. This front triggered a line of severe thunderstorms that moved across central New York and northeast Pennsylvania the evening of the 4th.', 'Thunderstorm winds blew down trees and wires.');
INSERT INTO public.stormevents_east VALUES (760677, 201805, 14, 1252, 201805, 14, 1252, 126677, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 12:52:00', 'EST-5', '14-MAY-18 12:52:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'E', 'BEHAM', 1, 'E', 'BEHAM', 40.03, -80.5, 40.03, -80.5, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', NULL);
INSERT INTO public.stormevents_east VALUES (759018, 201805, 4, 1540, 201805, 4, 1540, 126608, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BUF', '04-MAY-18 15:40:00', 'EST-5', '04-MAY-18 15:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'COOP Observer', 52, 'EG', NULL, NULL, 1, 'SE', 'CASTORLAND', 1, 'SE', 'CASTORLAND', 43.8686, -75.4992, 43.8686, -75.4992, 'Storms formed along a pre-frontal trough east of Lake Erie as it crossed the afternoon lake breeze boundary. The environment was not terribly unstable, however, strong winds aloft were brought to the surface easily with modest convection. These crossed the area rapidly through the afternoon hours.', 'Trees, wires, and telephone poles down north of Lowville.');
INSERT INTO public.stormevents_east VALUES (759023, 201805, 4, 1540, 201805, 4, 1540, 126608, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BUF', '04-MAY-18 15:40:00', 'EST-5', '04-MAY-18 15:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 56, 'MG', NULL, NULL, 2, 'ESE', 'RIGNEY BLUFF', 2, 'ESE', 'RIGNEY BLUFF', 43.2584, -77.6025, 43.2584, -77.6025, 'Storms formed along a pre-frontal trough east of Lake Erie as it crossed the afternoon lake breeze boundary. The environment was not terribly unstable, however, strong winds aloft were brought to the surface easily with modest convection. These crossed the area rapidly through the afternoon hours.', NULL);
INSERT INTO public.stormevents_east VALUES (759404, 201805, 12, 1535, 201805, 12, 1540, 126693, 'GEORGIA', 13, 2018, 'May', 'Hail', 'CAE', '12-MAY-18 15:35:00', 'EST-5', '12-MAY-18 15:40:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 0.75, NULL, NULL, NULL, 5, 'W', 'AUGUSTA DANIEL ARPT', 5, 'W', 'AUGUSTA DANIEL ARPT', 33.47, -82.11, 33.47, -82.11, 'Daytime heating and a weak upper impulse resulted in a few strong thunderstorms.', 'Trained SKYWARN spotter reported penny size hail on Wrightsboro Rd at Flowing Wells Rd.  Time estimated.');
INSERT INTO public.stormevents_east VALUES (759405, 201805, 12, 1539, 201805, 12, 1542, 126693, 'GEORGIA', 13, 2018, 'May', 'Hail', 'CAE', '12-MAY-18 15:39:00', 'EST-5', '12-MAY-18 15:42:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Public', 0.5, NULL, NULL, NULL, 3, 'W', 'AUGUSTA DANIEL ARPT', 3, 'W', 'AUGUSTA DANIEL ARPT', 33.47, -82.08, 33.47, -82.08, 'Daytime heating and a weak upper impulse resulted in a few strong thunderstorms.', 'An mPING report of one half inch hail.');
INSERT INTO public.stormevents_east VALUES (759406, 201805, 12, 1544, 201805, 12, 1547, 126693, 'GEORGIA', 13, 2018, 'May', 'Hail', 'CAE', '12-MAY-18 15:44:00', 'EST-5', '12-MAY-18 15:47:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Public', 0.25, NULL, NULL, NULL, 3, 'WSW', 'AUGUSTA DANIEL ARPT', 3, 'WSW', 'AUGUSTA DANIEL ARPT', 33.46, -82.08, 33.46, -82.08, 'Daytime heating and a weak upper impulse resulted in a few strong thunderstorms.', 'An mPING report of pea size hail.');
INSERT INTO public.stormevents_east VALUES (759410, 201805, 18, 1005, 201805, 18, 1130, 126698, 'SOUTH CAROLINA', 45, 2018, 'May', 'Flash Flood', 'CAE', '18-MAY-18 10:05:00', 'EST-5', '18-MAY-18 11:30:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'ORANGEBURG', 1, 'S', 'ORANGEBURG', 33.48, -80.87, 33.4792, -80.8682, 'An upper disturbance and a moist atmosphere led to showers and thunderstorms that produced locally heavy rain and flooding.', 'Road closure at Glover St and Stonewall Jackson Blvd in Orangeburg.');
INSERT INTO public.stormevents_east VALUES (759411, 201805, 18, 1036, 201805, 18, 1130, 126698, 'SOUTH CAROLINA', 45, 2018, 'May', 'Flash Flood', 'CAE', '18-MAY-18 10:36:00', 'EST-5', '18-MAY-18 11:30:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'ORANGEBURG', 2, 'E', 'ORANGEBURG', 33.4973, -80.8446, 33.4962, -80.8437, 'An upper disturbance and a moist atmosphere led to showers and thunderstorms that produced locally heavy rain and flooding.', 'Flooding observed at a day care center on Russell St in Orangeburg.  Children were rescued.');
INSERT INTO public.stormevents_east VALUES (759412, 201805, 18, 900, 201805, 18, 1030, 126698, 'SOUTH CAROLINA', 45, 2018, 'May', 'Heavy Rain', 'CAE', '18-MAY-18 09:00:00', 'EST-5', '18-MAY-18 10:30:00', 0, 0, 0, 0, NULL, NULL, 'Other Federal Agency', NULL, NULL, NULL, NULL, 1, 'S', 'ORANGEBURG', 1, 'S', 'ORANGEBURG', 33.4829, -80.8739, 33.4829, -80.8739, 'An upper disturbance and a moist atmosphere led to showers and thunderstorms that produced locally heavy rain and flooding.', 'The USGS rain gage on the US Hwy 301 bridge over the N. Fork of the Edisto R. recorded 3.24 inches of rain.  Most of this rain fell between 1000 am EDT (0900 EST) and 1130 am EDT (1030 EST).');
INSERT INTO public.stormevents_east VALUES (759415, 201805, 18, 900, 201805, 18, 1030, 126698, 'SOUTH CAROLINA', 45, 2018, 'May', 'Heavy Rain', 'CAE', '18-MAY-18 09:00:00', 'EST-5', '18-MAY-18 10:30:00', 0, 0, 0, 0, NULL, NULL, 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'S', 'ORANGEBURG', 1, 'S', 'ORANGEBURG', 33.49, -80.87, 33.49, -80.87, 'An upper disturbance and a moist atmosphere led to showers and thunderstorms that produced locally heavy rain and flooding.', 'The NWS COOP observer at the Orangeburg Water Plant recorded 2.88 inches of rain.  Most of this rain fell between 1000 am EDT (0900 EST) and 1130 am EDT (1030 EST).  Runoff from the heavy rainfall resulted in a nearly 2 foot rise of the N. Fork of the Edisto R. at a gage at the US Hwy 301 bridge.');
INSERT INTO public.stormevents_east VALUES (759416, 201805, 18, 815, 201805, 18, 1115, 126698, 'SOUTH CAROLINA', 45, 2018, 'May', 'Heavy Rain', 'CAE', '18-MAY-18 08:15:00', 'EST-5', '18-MAY-18 11:15:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', NULL, NULL, NULL, NULL, 1, 'NW', 'ORANGEBURG ARPT', 1, 'NW', 'ORANGEBURG ARPT', 33.46, -80.86, 33.46, -80.86, 'An upper disturbance and a moist atmosphere led to showers and thunderstorms that produced locally heavy rain and flooding.', 'ASOS Unit at Orangeburg Municipal Airport measured a total rainfall amount of 2.87 inches in about a three hour period.  Most of this total, 2.54 inches, fell in roughly an hour and a half from about 1000 am EDT (0900 EST) to 1130 am EDT (1030 EST).');
INSERT INTO public.stormevents_east VALUES (759434, 201805, 29, 1645, 201805, 29, 1650, 126700, 'SOUTH CAROLINA', 45, 2018, 'May', 'Thunderstorm Wind', 'CAE', '29-MAY-18 16:45:00', 'EST-5', '29-MAY-18 16:50:00', 0, 0, 0, 0, NULL, NULL, 'Public', 55, 'EG', NULL, NULL, 1, 'ENE', 'WHITMIRE', 1, 'ENE', 'WHITMIRE', 34.51, -81.6, 34.51, -81.6, 'A severe thunderstorm produced wind damage in Newberry Co SC.', 'Report received via social media of trees down on US Hwy 176 near Whitmire.');
INSERT INTO public.stormevents_east VALUES (756978, 201805, 10, 1844, 201805, 10, 1855, 126278, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'RAH', '10-MAY-18 18:44:00', 'EST-5', '10-MAY-18 18:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 1, NULL, NULL, NULL, 1, 'NNW', 'ROCKY MT', 3, 'WNW', 'KINGSBORO', 35.95, -77.79, 35.93, -77.72, 'Central North Carolina was on the southern periphery of an increasingly sheared shortwave as it progressed eastward into New England and the Northeast United States. The attendant weak front crossed the area late in the afternoon and evening, with just enough CAPE/Shear to allow for loosely organized multi-cellular thunderstorms. Several of the storms produced severe wind gusts and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (756975, 201805, 20, 1800, 201805, 20, 1810, 126277, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RAH', '20-MAY-18 18:00:00', 'EST-5', '20-MAY-18 18:10:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NNE', 'GUTHRIE', 3, 'SE', 'WALKERTOWN', 36.1388, -80.1652, 36.1506, -80.1275, 'Scattered multi-cell thunderstorms developed over the Blue Ridge and moved southeast into a moist, unstable airmass over the Northwest Piedmont. Although the shear was weak, one storm intensified as it intersected a neighboring storm''s outflow, producing a microburst near Winston-Salem.', 'Several trees were blown down along a swath from the intersection of Highway 158 and Serene St to Old Hollow Road near Old Valley School Road. Trees fell onto residences on Sir Issac Drive, Beulah Lane, and on Reidsville Road, causing damage to the roof of the respective homes.');
INSERT INTO public.stormevents_east VALUES (756977, 201805, 10, 1718, 201805, 10, 1718, 126278, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'RAH', '10-MAY-18 17:18:00', 'EST-5', '10-MAY-18 17:18:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', 1.5, NULL, NULL, NULL, 1, 'NNE', 'HUCKLEBERRY SPG', 1, 'NNE', 'HUCKLEBERRY SPG', 36.07, -78.94, 36.07, -78.94, 'Central North Carolina was on the southern periphery of an increasingly sheared shortwave as it progressed eastward into New England and the Northeast United States. The attendant weak front crossed the area late in the afternoon and evening, with just enough CAPE/Shear to allow for loosely organized multi-cellular thunderstorms. Several of the storms produced severe wind gusts and large hail.', 'Ping pong ball size hail fell near the intersection of Rose Of Sharon Road and Golden Heather Drive and resulted in damage to vehicles and trees.');
INSERT INTO public.stormevents_east VALUES (756979, 201805, 10, 1623, 201805, 10, 1623, 126278, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RAH', '10-MAY-18 16:23:00', 'EST-5', '10-MAY-18 16:23:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NW', 'STOVALL', 3, 'NW', 'STOVALL', 36.48, -78.6, 36.48, -78.6, 'Central North Carolina was on the southern periphery of an increasingly sheared shortwave as it progressed eastward into New England and the Northeast United States. The attendant weak front crossed the area late in the afternoon and evening, with just enough CAPE/Shear to allow for loosely organized multi-cellular thunderstorms. Several of the storms produced severe wind gusts and large hail.', 'Two trees were blown down along Grassy Creek Road near the Bullock Community.');
INSERT INTO public.stormevents_east VALUES (756982, 201805, 10, 1749, 201805, 10, 1749, 126278, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RAH', '10-MAY-18 17:49:00', 'EST-5', '10-MAY-18 17:49:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'LOUISBURG', 0, 'N', 'LOUISBURG', 36.1, -78.3, 36.1, -78.3, 'Central North Carolina was on the southern periphery of an increasingly sheared shortwave as it progressed eastward into New England and the Northeast United States. The attendant weak front crossed the area late in the afternoon and evening, with just enough CAPE/Shear to allow for loosely organized multi-cellular thunderstorms. Several of the storms produced severe wind gusts and large hail.', 'Numerous trees were blown down within the community of Louisburg.');
INSERT INTO public.stormevents_east VALUES (778702, 201809, 20, 1337, 201809, 20, 1341, 130020, 'OHIO', 39, 2018, 'September', 'Tornado', 'CLE', '20-SEP-18 13:37:00', 'EST-5', '20-SEP-18 13:41:00', 0, 0, 0, 0, '20.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'W', 'MESOPOTAMIA', 1, 'NE', 'BUNDYSBURG', 41.4479, -81.0033, 41.4259, -80.9919, 'A warm front lifted north across Ohio on September 20th ushering in unseasonably warm and humid weather.  Scattered thunderstorms developed along the front during the middle part of the afternoon.  A couple of thunderstorms became severe and one produced two tornadoes in Northeast Ohio.', 'An EF1 tornado crossed into Trumbull County from Geauga County.  This occurred in Mesopotamia Township along Bundysburg about three quarters of a mile south of State Route 87.  The tornado quickly weakened to EF0 intensity and continued south southeast for just over a mile and a half before dissipating as it approached Clark Road about a half mile east of Parkman Mesopotamia Road.  The damage path in Trumbull County was intermittent and consisted of mainly downed trees and limbs.  The damage path was no more than 25 yards in width.');
INSERT INTO public.stormevents_east VALUES (778721, 201809, 21, 1515, 201809, 21, 1517, 130023, 'OHIO', 39, 2018, 'September', 'Thunderstorm Wind', 'CLE', '21-SEP-18 15:15:00', 'EST-5', '21-SEP-18 15:17:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'WSW', 'LAKEWOOD', 1, 'E', 'LAKEWOOD', 41.4785, -81.8051, 41.4807, -81.7896, 'A strong cold front crossed the Upper Ohio Valley during the afternoon and early evening hours of September 21st.  A line of thunderstorms developed ahead of the front.  Some segments of the storm became severe and produced damage.', 'Thunderstorm winds downed trees on Arthur Avenue and Bunts Road.  A third fallen tree damaged a house on Mars Avenue.');
INSERT INTO public.stormevents_east VALUES (778813, 201809, 21, 1525, 201809, 21, 1525, 130023, 'OHIO', 39, 2018, 'September', 'Thunderstorm Wind', 'CLE', '21-SEP-18 15:25:00', 'EST-5', '21-SEP-18 15:25:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'EAST CLEVELAND', 0, 'N', 'EAST CLEVELAND', 41.53, -81.53, 41.53, -81.53, 'A strong cold front crossed the Upper Ohio Valley during the afternoon and early evening hours of September 21st.  A line of thunderstorms developed ahead of the front.  Some segments of the storm became severe and produced damage.', 'Thunderstorm winds snapped a pine tree along Wyatt Road near Forest Hill Park.  A couple trees nearby were also downed.');
INSERT INTO public.stormevents_east VALUES (778818, 201809, 21, 1540, 201809, 21, 1542, 130023, 'OHIO', 39, 2018, 'September', 'Thunderstorm Wind', 'CLE', '21-SEP-18 15:40:00', 'EST-5', '21-SEP-18 15:42:00', 0, 0, 0, 0, '45.00K', '0.00K', 'Emergency Manager', 61, 'EG', NULL, NULL, 2, 'WSW', 'NANKIN', 1, 'SW', 'NANKIN', 40.9107, -82.3137, 40.9086, -82.2904, 'A strong cold front crossed the Upper Ohio Valley during the afternoon and early evening hours of September 21st.  A line of thunderstorms developed ahead of the front.  Some segments of the storm became severe and produced damage.', 'Thunderstorm wind gusts estimated to be at least 70 mph downed several trees north of Ashland between State Route 511 and County Road 1175.  A home in that area lost a section of roofing and corn in nearby fields was blown over.');
INSERT INTO public.stormevents_east VALUES (761636, 201805, 27, 852, 201805, 27, 852, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '27-MAY-18 08:52:00', 'EST-5', '27-MAY-18 08:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'NE', 'KEY LARGO', 1, 'NE', 'KEY LARGO', 25.1001, -80.4318, 25.1001, -80.4318, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at an automated WeatherFlow station in South Key Largo.');
INSERT INTO public.stormevents_east VALUES (761638, 201805, 27, 1038, 201805, 27, 1038, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '27-MAY-18 10:38:00', 'EST-5', '27-MAY-18 10:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 36 knots was measured at an automated Citizen Weather Observing Station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (761640, 201805, 27, 1105, 201805, 27, 1105, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '27-MAY-18 11:05:00', 'EST-5', '27-MAY-18 11:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 35 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
INSERT INTO public.stormevents_east VALUES (761641, 201805, 27, 1303, 201805, 27, 1303, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '27-MAY-18 13:03:00', 'EST-5', '27-MAY-18 13:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at an automated Citizen Weather Observing Station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (761643, 201805, 27, 1743, 201805, 27, 1743, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '27-MAY-18 17:43:00', 'EST-5', '27-MAY-18 17:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 34 knots was measured at an automated Citizen Weather Observing Program station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (745418, 201805, 4, 1635, 201805, 4, 1635, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:35:00', 'EST-5', '04-MAY-18 16:35:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 61, 'EG', NULL, NULL, 1, 'SE', 'KAULMONT', 1, 'SE', 'KAULMONT', 41.4147, -78.535, 41.4147, -78.535, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 70 mph knocked a roof off of a structure, blocking south Michael Road at Averyville Road near Saint Marys.');
INSERT INTO public.stormevents_east VALUES (745419, 201805, 4, 1640, 201805, 4, 1640, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:40:00', 'EST-5', '04-MAY-18 16:40:00', 0, 0, 0, 0, '6.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'ESE', 'ROULETTE', 2, 'ESE', 'ROULETTE', 41.7662, -78.1205, 41.7662, -78.1205, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down numerous trees and wires between Roulette and Coudersport.');
INSERT INTO public.stormevents_east VALUES (745420, 201805, 4, 1646, 201805, 4, 1646, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:46:00', 'EST-5', '04-MAY-18 16:46:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 61, 'EG', NULL, NULL, 5, 'S', 'KEATING SUMMIT', 5, 'S', 'KEATING SUMMIT', 41.6126, -78.1892, 41.6126, -78.1892, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 70 mph knocked down numerous large trees north of Sizerville State Park.');
INSERT INTO public.stormevents_east VALUES (745421, 201805, 4, 1648, 201805, 4, 1648, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:48:00', 'EST-5', '04-MAY-18 16:48:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'NE', 'EMPORIUM', 1, 'NE', 'EMPORIUM', 41.51, -78.24, 41.51, -78.24, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down numerous trees and wires near Emporium.');
INSERT INTO public.stormevents_east VALUES (745423, 201805, 4, 1652, 201805, 4, 1652, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:52:00', 'EST-5', '04-MAY-18 16:52:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'CALEDONIA', 1, 'E', 'CALEDONIA', 41.2823, -78.4512, 41.2823, -78.4512, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires along Route 555.');
INSERT INTO public.stormevents_east VALUES (745424, 201805, 4, 1708, 201805, 4, 1708, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 17:08:00', 'EST-5', '04-MAY-18 17:08:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WNW', 'OSCEOLA', 1, 'WNW', 'OSCEOLA', 41.9826, -77.3417, 41.9826, -77.3417, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires near Osceola.');
INSERT INTO public.stormevents_east VALUES (745426, 201805, 4, 1725, 201805, 4, 1725, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 17:25:00', 'EST-5', '04-MAY-18 17:25:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'NNE', 'SOUTH RENOVO', 1, 'NNE', 'SOUTH RENOVO', 41.3284, -77.7456, 41.3284, -77.7456, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down numerous trees in Renovo.');
INSERT INTO public.stormevents_east VALUES (744939, 201805, 14, 1548, 201805, 14, 1548, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '14-MAY-18 15:48:00', 'EST-5', '14-MAY-18 15:48:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'WHITMER', 1, 'S', 'WHITMER', 38.81, -79.55, 38.81, -79.55, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'Several trees were downed by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (744940, 201805, 14, 1557, 201805, 14, 1557, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '14-MAY-18 15:57:00', 'EST-5', '14-MAY-18 15:57:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'SW', 'FRANK', 0, 'SW', 'FRANK', 38.5461, -79.8059, 38.5461, -79.8059, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'Trees and power lines were blown down near Durbin and Bartow.');
INSERT INTO public.stormevents_east VALUES (745081, 201805, 15, 1757, 201805, 15, 1757, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '15-MAY-18 17:57:00', 'EST-5', '15-MAY-18 17:57:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NNE', 'MATAMORAS', 1, 'NNE', 'MATAMORAS', 39.5334, -81.0428, 39.5334, -81.0428, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'Trees and power lines were blown down across Route 2, closing the road for a time.');
INSERT INTO public.stormevents_east VALUES (745082, 201805, 15, 1803, 201805, 15, 1803, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '15-MAY-18 18:03:00', 'EST-5', '15-MAY-18 18:03:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'SSE', 'SISTERSVILLE', 1, 'SSE', 'SISTERSVILLE', 39.5609, -80.9973, 39.5609, -80.9973, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'Several trees were blown down by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (745083, 201805, 15, 1810, 201805, 15, 1810, 124101, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RLX', '15-MAY-18 18:10:00', 'EST-5', '15-MAY-18 18:10:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'ALMA', 1, 'W', 'ALMA', 39.43, -80.8394, 39.43, -80.8394, 'As a surface front oscillated north and south across central and northern West Virginia, showers and thunderstorms developed in a high instability atmosphere on the afternoons of the 14th and 15th. Some of these storms became strong to severe.', 'State Route 18 was closed due to trees and power lines down across the road.');
