INSERT INTO public.stormevents_east VALUES (746638, 201805, 15, 1657, 201805, 15, 1657, 124435, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'PHI', '15-MAY-18 16:57:00', 'EST-5', '15-MAY-18 16:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'WSW', 'WEST TRENTON', 1, 'WSW', 'WEST TRENTON', 40.26, -74.84, 40.26, -74.84, 'Severe thunderstorms moved across portions of northern New Jersey with hail and wind damage reported.', 'Downed tree on State Highway 29 near Upper Ferry Road. Lane closures in place.');
INSERT INTO public.stormevents_east VALUES (746639, 201805, 15, 1613, 201805, 15, 1613, 124435, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'PHI', '15-MAY-18 16:13:00', 'EST-5', '15-MAY-18 16:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 56, 'MG', NULL, NULL, 1, 'ENE', 'AVENEL', 1, 'ENE', 'AVENEL', 40.56, -74.25, 40.56, -74.25, 'Severe thunderstorms moved across portions of northern New Jersey with hail and wind damage reported.', 'A trained spotter reported a measured wind gust of 64 mph.');
INSERT INTO public.stormevents_east VALUES (746647, 201805, 19, 2100, 201805, 20, 700, 124443, 'MARYLAND', 24, 2018, 'May', 'Flood', 'PHI', '19-MAY-18 21:00:00', 'EST-5', '20-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'GREENSBORO', 0, 'W', 'GREENSBORO', 38.9703, -75.8057, 38.9702, -75.8062, 'Heavy rain lead to flooding along the Choptank River.', 'The Greensboro gage along the Choptank River exceeded flood stage, due to 3 to 5 inches of rainfall over three days, resulting in minor flooding on the Greensboro Carnival Ground and a few backyards along the river.');
INSERT INTO public.stormevents_east VALUES (746649, 201805, 19, 2100, 201805, 20, 700, 124442, 'DELAWARE', 10, 2018, 'May', 'Flood', 'PHI', '19-MAY-18 21:00:00', 'EST-5', '20-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'SANDTOWN', 1, 'NW', 'SANDTOWN', 39.044, -75.7365, 39.0441, -75.736, 'Heavy rain lead to flooding along the Choptank River.', 'The Greensboro gage along the Choptank River exceeded flood stage, due to 3 to 5 inches of rainfall over three days.');
INSERT INTO public.stormevents_east VALUES (776132, 201807, 2, 1748, 201807, 2, 1748, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 17:48:00', 'EST-5', '02-JUL-18 17:48:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 3, 'E', 'FLEMINGVILLE', 3, 'E', 'FLEMINGVILLE', 42.17, -76.2, 42.17, -76.2, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776133, 201807, 2, 1818, 201807, 2, 1818, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 18:18:00', 'EST-5', '02-JUL-18 18:18:00', 0, 0, 0, 0, '20.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'SMITHBORO', 1, 'NW', 'SMITHBORO', 42.04, -76.41, 42.04, -76.41, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees and wires. A tree was knocked down on a house.');
INSERT INTO public.stormevents_east VALUES (776134, 201807, 2, 1847, 201807, 2, 1847, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 18:47:00', 'EST-5', '02-JUL-18 18:47:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'CHENANGO FALLS', 1, 'N', 'CHENANGO FALLS', 42.24, -75.85, 42.24, -75.85, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (745531, 201805, 15, 1300, 201805, 15, 1300, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:00:00', 'EST-5', '15-MAY-18 13:00:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'S', 'BUFFALO RUN', 1, 'S', 'BUFFALO RUN', 40.82, -77.95, 40.82, -77.95, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto Sellers Lane.');
INSERT INTO public.stormevents_east VALUES (745532, 201805, 15, 1308, 201805, 15, 1308, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:08:00', 'EST-5', '15-MAY-18 13:08:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WSW', 'COLEVILLE', 1, 'WSW', 'COLEVILLE', 40.8947, -77.799, 40.8947, -77.799, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires along Seibert Road near Bellefonte.');
INSERT INTO public.stormevents_east VALUES (745533, 201805, 15, 1310, 201805, 15, 1310, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:10:00', 'EST-5', '15-MAY-18 13:10:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'S', 'AXEMANN', 1, 'S', 'AXEMANN', 40.8707, -77.7518, 40.8707, -77.7518, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto Melanie Lane in Pleasant Gap.');
INSERT INTO public.stormevents_east VALUES (745534, 201805, 15, 1325, 201805, 15, 1325, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:25:00', 'EST-5', '15-MAY-18 13:25:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'WSW', 'MILLVIEW', 1, 'WSW', 'MILLVIEW', 41.4925, -76.5992, 41.4925, -76.5992, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires onto Route 87 near Forksville.');
INSERT INTO public.stormevents_east VALUES (745535, 201805, 15, 1335, 201805, 15, 1335, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:35:00', 'EST-5', '15-MAY-18 13:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'ENE', 'DUSHORE', 1, 'ENE', 'DUSHORE', 41.5283, -76.4016, 41.5283, -76.4016, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in Dushore.');
INSERT INTO public.stormevents_east VALUES (745536, 201805, 15, 1340, 201805, 15, 1340, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:40:00', 'EST-5', '15-MAY-18 13:40:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 2, 'N', 'OPP', 2, 'N', 'OPP', 41.2055, -76.6861, 41.2055, -76.6861, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down multiple trees, including one onto a house east of Muncy.');
INSERT INTO public.stormevents_east VALUES (745537, 201805, 15, 1340, 201805, 15, 1340, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:40:00', 'EST-5', '15-MAY-18 13:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'N', 'HUGHESVILLE', 1, 'N', 'HUGHESVILLE', 41.24, -76.73, 41.24, -76.73, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree onto a home in Hughsville.');
INSERT INTO public.stormevents_east VALUES (746920, 201805, 21, 1650, 201805, 21, 1750, 124490, 'KENTUCKY', 21, 2018, 'May', 'Flood', 'JKL', '21-MAY-18 16:50:00', 'EST-5', '21-MAY-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'PIKEVILLE', 0, 'SSE', 'PIKEVILLE', 37.4759, -82.5181, 37.4757, -82.5178, 'Numerous showers and thunderstorms developed this afternoon and evening across eastern Kentucky. Repeated rounds of moderate to heavy rainfall led to an isolated instance of flooding in Pikeville.', 'A local media outlet reported several inches of water covering South Bypass Road between the expo center and hospital in Pikeville.');
INSERT INTO public.stormevents_east VALUES (748046, 201805, 31, 1229, 201805, 31, 1235, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 12:29:00', 'EST-5', '31-MAY-18 12:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'W', 'MARIBA', 0, 'SW', 'MARIBA', 37.9205, -83.5862, 37.9167, -83.584, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch relayed reports of trees down on U.S. Highway 460 and Kentucky Highway 77 near Mariba, southeast of Frenchburg.');
INSERT INTO public.stormevents_east VALUES (748048, 201805, 31, 1251, 201805, 31, 1251, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 12:51:00', 'EST-5', '31-MAY-18 12:51:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 51, 'EG', NULL, NULL, 1, 'NW', 'BETHANY', 1, 'NW', 'BETHANY', 37.66, -83.49, 37.66, -83.49, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch reported a tree blown down northwest of Bethany.');
INSERT INTO public.stormevents_east VALUES (748051, 201805, 31, 1340, 201805, 31, 1340, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 13:40:00', 'EST-5', '31-MAY-18 13:40:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 51, 'EG', NULL, NULL, 0, 'W', 'DICE', 0, 'W', 'DICE', 37.3698, -83.2373, 37.3698, -83.2373, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'A local media outlet reported a tree blown down on power lines on Lost Creek Road northwest of Dice, resulting in a temporary closure of the road.');
INSERT INTO public.stormevents_east VALUES (751954, 201805, 31, 1525, 201805, 31, 1527, 124671, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '31-MAY-18 15:25:00', 'EST-5', '31-MAY-18 15:27:00', 0, 0, 0, 0, '3.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'GEORGETOWN', 0, 'N', 'GEORGETOWN', 38.87, -83.9, 38.87, -83.9, 'A complex of thunderstorms pushed east across the Ohio Valley during the afternoon hours. Several of the thunderstorms produced damaging wind gusts.', 'A few trees were downed.');
INSERT INTO public.stormevents_east VALUES (745281, 201805, 16, 1730, 201805, 16, 1830, 124187, 'KENTUCKY', 21, 2018, 'May', 'Flash Flood', 'ILN', '16-MAY-18 17:30:00', 'EST-5', '16-MAY-18 18:30:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'COTTAGEVILLE', 2, 'NNE', 'CAMP DIX', 38.5762, -83.5982, 38.502, -83.2641, 'Slow moving thunderstorms produced localized flash flooding during the early morning hours and then again during the afternoon hours.', 'Flash flooding was reported in the Tollesboro and Camp Dix areas.  Ribolt-Epworth Road, Teager Hollow Road, Straight Fork Road, Mosby Road, Cooper Fork Road and Lower Kinney Road all sustained some road damage. Water approached some homes and caused damage to a grocery store in Tollesboro and a funeral chapel in Camp Dix.');
INSERT INTO public.stormevents_east VALUES (747019, 201805, 27, 1725, 201805, 27, 1728, 124507, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '27-MAY-18 17:25:00', 'EST-5', '27-MAY-18 17:28:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SSW', 'BOSTON', 1, 'SSW', 'BOSTON', 39.2106, -83.5257, 39.2106, -83.5257, 'Isolated thunderstorms developed during the afternoon hours in an unstable air mass in place across the region.', 'A tree was downed onto Carper Lane. Power poles and power lines were downed onto Petersburg Road.');
INSERT INTO public.stormevents_east VALUES (756687, 201805, 21, 1830, 201805, 21, 1830, 125542, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '21-MAY-18 18:30:00', 'EST-5', '21-MAY-18 18:30:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'N', 'GIST ELEVATOR ARPT', 3, 'N', 'GIST ELEVATOR ARPT', 40.6369, -82.9348, 40.6369, -82.9348, 'Strong thunderstorms evolved across western Ohio during the afternoon and moved into central Ohio around 6-6:30 pm. Severe storms with winds and hail were prevalent. By the evening the storms began train along a warm front and old lake breeze boundary over the Central Highlands of Morrow and Richland counties. Storms intensified and slowed along this boundary, with the heaviest rainfall localized over Lexington. Flash flooding resulted.', 'Thunderstorm wind gusts downed trees across State Route 309 east of Caledonia in extreme northwest Morrow County.');
INSERT INTO public.stormevents_east VALUES (791274, 201811, 24, 1740, 201811, 24, 1850, 132245, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '24-NOV-18 17:40:00', 'EST-5', '24-NOV-18 18:50:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'CRISFIELD CG (CRS)', 0, 'N', 'CRISFIELD CG (CRS)', 37.97, -75.88, 37.97, -75.88, 'A low pressure system moved up the east coast of the United States on November 24th with the warm sector of the system moving across the waters during the late day hours. This generated a limited amount of instability which combined with high levels of wind shear to produce gusty showers.', 'A wind gust of 34 knots was measured at Crisfield.');
INSERT INTO public.stormevents_east VALUES (751154, 201805, 4, 1848, 201805, 4, 1848, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:48:00', 'EST-5', '04-MAY-18 18:48:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'NW', 'AMSTERDAM', 1, 'NW', 'AMSTERDAM', 42.94, -74.19, 42.94, -74.19, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A power pole was snapped.');
INSERT INTO public.stormevents_east VALUES (751151, 201805, 4, 1843, 201805, 4, 1843, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:43:00', 'EST-5', '04-MAY-18 18:43:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 1, 'NNW', 'GLEN', 1, 'NNW', 'GLEN', 42.8944, -74.343, 42.8944, -74.343, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A tree was down blocking a road.');
INSERT INTO public.stormevents_east VALUES (751156, 201805, 4, 1854, 201805, 4, 1854, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:54:00', 'EST-5', '04-MAY-18 18:54:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'N', 'CONKLINGVILLE', 3, 'N', 'CONKLINGVILLE', 43.36, -73.95, 43.36, -73.95, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (791275, 201811, 24, 1830, 201811, 24, 1912, 132245, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '24-NOV-18 18:30:00', 'EST-5', '24-NOV-18 19:12:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'MID BAY BUOY', 0, 'N', 'MID BAY BUOY', 38.47, -76.38, 38.47, -76.38, 'A low pressure system moved up the east coast of the United States on November 24th with the warm sector of the system moving across the waters during the late day hours. This generated a limited amount of instability which combined with high levels of wind shear to produce gusty showers.', 'A wind gust of 34 knots was measured at Cove Point.');
INSERT INTO public.stormevents_east VALUES (791276, 201811, 24, 1854, 201811, 24, 1854, 132245, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '24-NOV-18 18:54:00', 'EST-5', '24-NOV-18 18:54:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'RACCOON POINT (RAC)', 0, 'N', 'RACCOON POINT (RAC)', 38.14, -75.79, 38.14, -75.79, 'A low pressure system moved up the east coast of the United States on November 24th with the warm sector of the system moving across the waters during the late day hours. This generated a limited amount of instability which combined with high levels of wind shear to produce gusty showers.', 'A wind gust of up to 34 knots was observed at Raccoon Point.');
INSERT INTO public.stormevents_east VALUES (758842, 201805, 6, 1449, 201805, 6, 1449, 126399, 'NORTH CAROLINA', 37, 2018, 'May', 'Thunderstorm Wind', 'RAH', '06-MAY-18 14:49:00', 'EST-5', '06-MAY-18 14:49:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 3, 'S', 'ELBERON', 3, 'S', 'ELBERON', 36.28, -78.2195, 36.28, -78.2195, 'Isolated to scattered storms developed in a moderately unstable air mass ahead of an approaching cold front during the afternoon into the evening. A few of the storms became strong to severe, resulting in a few reports of wind damage.', 'Two trees were reported down on Sulphur Springs Road.');
INSERT INTO public.stormevents_east VALUES (759276, 201805, 27, 2210, 201805, 28, 110, 126648, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '27-MAY-18 22:10:00', 'EST-5', '28-MAY-18 01:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'GALTS MILL', 1, 'WNW', 'GALTS MILL', 37.4559, -79.0477, 37.4576, -79.0454, 'Evening thunderstorms dropped 2 to 3 inches of rain over several hours in some spots causing isolated flash flooding.', 'Beck Creek Road and Tent Mountain Farm Road were flooded and closed. A man was rescued from his home along Beck Creek Road as water was rising around the structure.');
INSERT INTO public.stormevents_east VALUES (759268, 201805, 29, 1830, 201805, 29, 2130, 126647, 'NORTH CAROLINA', 37, 2018, 'May', 'Flood', 'RNK', '29-MAY-18 18:30:00', 'EST-5', '29-MAY-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BOONE BLWNG RCK ARPT', 1, 'N', 'BOONE BLWNG RCK ARPT', 36.2125, -81.6373, 36.2153, -81.6334, 'Rainfall of 1 to 1.5 inches in several hours over parts of southwest Watauga County produced a debris flow and some road flooding.', 'Bamboo Road near the Boone Airport and an assisted living center was flooded.');
INSERT INTO public.stormevents_east VALUES (759226, 201805, 4, 2015, 201805, 4, 2020, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:15:00', 'EST-5', '04-MAY-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'N', 'COLEBROOK', 2, 'N', 'COLEBROOK', 44.91, -71.48, 44.91, -71.48, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed a tree on Cunnington Lane in Colebrook.');
INSERT INTO public.stormevents_east VALUES (759227, 201805, 4, 2015, 201805, 4, 2019, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:15:00', 'EST-5', '04-MAY-18 20:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'E', 'HAVERHILL', 1, 'E', 'HAVERHILL', 44.03, -72.06, 44.03, -72.06, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires in Haverhill.');
INSERT INTO public.stormevents_east VALUES (759228, 201805, 4, 2020, 201805, 4, 2025, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:20:00', 'EST-5', '04-MAY-18 20:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SE', 'ORFORD', 1, 'SE', 'ORFORD', 43.91, -72.14, 43.91, -72.14, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires on Route 10 at Grimes Hill Road in Orford.');
INSERT INTO public.stormevents_east VALUES (750176, 201805, 26, 930, 201805, 26, 1230, 125074, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'RNK', '26-MAY-18 09:30:00', 'EST-5', '26-MAY-18 12:30:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'FROG LEVEL', 1, 'SW', 'PISGAH', 37.0897, -81.5681, 37.1134, -81.5875, 'Morning thunderstorms rolled across Tazewell County dropping radar estimated 2 to 4 inches of rain near the Town of Tazewell and lesser amounts toward Richlands over a several hour period causing numerous flood problems.', 'Several roads were flooded in the town of Tazewell with water running across them. A number of homes had flooded basements and at least six evacuations or water rescues were conducted at or near Maplewood Lane, Walnut Street, Texas Street, Mitchell Street, and Third Street. Most of the flood reports were from 930 to 1030 AM EST. In addition, the North Fork of the Clinch River was reported out of its banks and flooding Professional Drive.');
INSERT INTO public.stormevents_east VALUES (760016, 201805, 29, 1730, 201805, 29, 1930, 126710, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '29-MAY-18 17:30:00', 'EST-5', '29-MAY-18 19:30:00', 0, 0, 0, 0, '20.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'CHIMNEY ROCK', 1, 'NE', 'CHIMNEY ROCK', 35.449, -82.276, 35.439, -82.242, 'A very moist southeast flow developed northeast of subtropical cyclone Alberto, which made landfall across the western Florida Peninsula on the 28th and moved north across Alabama throughout the 29th. Resultant upslope flow into the southern Appalachians resulted in development of widespread heavy rain showers across western North Carolina throughout the 29th, with activity being most concentrated along the eastern escarpment of the Blue Ridge. By the time the showers tapered off during the 30th, total rainfall of 7-10 inches occurred along the Blue Ridge. This resulted in fairly widespread flash flooding followed by an extended period of high stream flow, with McDowell County being the hardest hit area.', 'In the midst of a more general flood event after which the level briefly began receding, a stream gauge on the Rocky Broad River at Bat Cave indicated a rapid increase in the river level as a series of heavy rain showers moved over the area during the late afternoon and evening. The river continued rising through the evening, cresting shortly after midnight.');
INSERT INTO public.stormevents_east VALUES (760019, 201805, 29, 1800, 201805, 30, 0, 126710, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '29-MAY-18 18:00:00', 'EST-5', '30-MAY-18 00:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BAT CAVE', 0, 'N', 'BAT CAVE', 35.455, -82.29, 35.45, -82.28, 'A very moist southeast flow developed northeast of subtropical cyclone Alberto, which made landfall across the western Florida Peninsula on the 28th and moved north across Alabama throughout the 29th. Resultant upslope flow into the southern Appalachians resulted in development of widespread heavy rain showers across western North Carolina throughout the 29th, with activity being most concentrated along the eastern escarpment of the Blue Ridge. By the time the showers tapered off during the 30th, total rainfall of 7-10 inches occurred along the Blue Ridge. This resulted in fairly widespread flash flooding followed by an extended period of high stream flow, with McDowell County being the hardest hit area.', 'County comms and stream gauges indicated flash flooding developed across central and northeast Henderson County after a series of heavy rain showers moved over areas with already-saturated ground. Mud Creek and Bat Fork Creek flooded several roads in downtown and on the east side of Hendersonville. Howard Gap Rd was closed northeast of Hendersonville due to flooding along Clear Creek. Multiple small streams also flooded in the Dana area, including Reedypatch Creek, which flooded Highway 64 at Hog Rock Rd. Several other roads were flooded in this area. Meanwhile, in the midst of a more general flood event along the Rocky Broad River near Bat Cave, just when the level briefly began receding, a stream gauge indicated a rapid increase in the river level. The river continued rising through the evening, cresting shortly after midnight. Multiple small to medium size landslides and downed trees were also reported throughout this area, some of which blocked roads.');
INSERT INTO public.stormevents_east VALUES (757096, 201805, 30, 1600, 201805, 30, 1600, 126305, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MFL', '30-MAY-18 16:00:00', 'EST-5', '30-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 7, 'WNW', 'KREAMER ISLAND', 7, 'WNW', 'KREAMER ISLAND', 26.82, -80.83, 26.82, -80.83, 'Afternoon showers and thunderstorms developed along sea breeze and outflow boundary collisions. A few of these storms became strong enough and moved over Lake Okeechobee producing gusty winds.', 'A marine thunderstorm wind gust of 48 mph...42 knots...was recorded at 500 PM EDT by SFWMD site L006 on Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (760404, 201805, 30, 400, 201805, 30, 400, 126306, 'FLORIDA', 12, 2018, 'May', 'Thunderstorm Wind', 'MFL', '30-MAY-18 04:00:00', 'EST-5', '30-MAY-18 04:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 43, 'EG', NULL, NULL, 2, 'E', 'EAST NAPLES', 2, 'ENE', 'EAST NAPLES', 26.1215, -81.7518, 26.1302, -81.7517, 'Showers and thunderstorms over the Gulf waters moved ashore overnight along the Gulf coast. One of these thunderstorms produced gusty winds causing damage to a local golf course along with tree and sign damage.', 'Minor tree branch damage was reported by Naples Daily News at Eagle Key Circle in East Naples. The Lakewood Country Club also received minor tree damage, street signs were down and a plastic garden shed was blown across the street. Radar estimated wind was around 50 mph.');
INSERT INTO public.stormevents_east VALUES (756876, 201805, 5, 1435, 201805, 5, 1435, 126260, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '05-MAY-18 14:35:00', 'EST-5', '05-MAY-18 14:35:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 1, 'W', 'GROVEMONT', 1, 'W', 'GROVEMONT', 35.62, -82.42, 35.62, -82.42, 'Isolated thunderstorms developed over the high terrain during the afternoon. Some of the storms produced hail up to the size of pennies.', 'Public reported 3/4 inch hail.');
INSERT INTO public.stormevents_east VALUES (746742, 201805, 17, 410, 201805, 17, 925, 124441, 'PENNSYLVANIA', 42, 2018, 'May', 'Flash Flood', 'PHI', '17-MAY-18 04:10:00', 'EST-5', '17-MAY-18 09:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'THORNDALE', 2, 'NNE', 'HARMONY HILL', 39.9868, -75.7108, 40.0026, -75.6662, 'Heavy rain lead to urban and small stream flooding across portions of southeast Pennsylvania.', 'Flash flooding occurred along the East Branch of the Brandywine Creek in West Bradford Township and East Bradford Township.  There was moderate flooding around the river gauge below Downingtown.  The creek level at that location reached 9.07 feet at 7:15 a.m. EST.');
INSERT INTO public.stormevents_east VALUES (747101, 201805, 27, 345, 201805, 27, 645, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 03:45:00', 'EST-5', '27-MAY-18 06:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'LAKE COMO', 1, 'W', 'LAKE COMO', 40.1726, -74.0461, 40.1689, -74.0478, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Route 35 was closed in both directions just south of Route 138 in Wall Township.');
INSERT INTO public.stormevents_east VALUES (747103, 201805, 27, 515, 201805, 27, 715, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 05:15:00', 'EST-5', '27-MAY-18 07:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'COLLINGWOOD PARK', 1, 'ESE', 'COLLINGWOOD PARK', 40.2215, -74.1309, 40.2198, -74.1269, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Route 33 was closed in Wall Township around the Collingwood Park Circle.');
INSERT INTO public.stormevents_east VALUES (747106, 201805, 27, 530, 201805, 27, 730, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 05:30:00', 'EST-5', '27-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'NORTH BRUNSWICK', 0, 'NE', 'NORTH BRUNSWICK', 40.4739, -74.4322, 40.4711, -74.4286, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Flooding occurred on Route 1 in New Brunswick and in North Brunswick Township between Route 18 and Ryders Lane.');
INSERT INTO public.stormevents_east VALUES (747108, 201805, 27, 640, 201805, 27, 740, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 06:40:00', 'EST-5', '27-MAY-18 07:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'EAST MILLSTONE', 2, 'ENE', 'MIDDLE BUSH', 40.48, -74.5611, 40.5078, -74.4855, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'There were numerous road closures in Franklin Township including Blackwells Mills Road, South Middlebush Road, Canal Road and Foxwood Drive.');
INSERT INTO public.stormevents_east VALUES (747110, 201805, 27, 600, 201805, 27, 800, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 06:00:00', 'EST-5', '27-MAY-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'FREEHOLD', 1, 'SE', 'FREEHOLD', 40.2618, -74.2731, 40.2608, -74.2717, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Broadway was closed due to flooding near East Main Street in Freehold.');
INSERT INTO public.stormevents_east VALUES (747112, 201805, 27, 600, 201805, 27, 900, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 06:00:00', 'EST-5', '27-MAY-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'EAST WINDSOR', 0, 'WNW', 'EAST WINDSOR', 40.2675, -74.5419, 40.273, -74.5365, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Water rescues in East Windsor Township. The One Mile Road extension was flooded, and Route 130 was closed from around Dutch Neck Road to near Route 571.');
INSERT INTO public.stormevents_east VALUES (745542, 201805, 15, 1351, 201805, 15, 1351, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:51:00', 'EST-5', '15-MAY-18 13:51:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'NW', 'NEWTON HAMILTON', 1, 'NW', 'NEWTON HAMILTON', 40.4093, -77.8424, 40.4093, -77.8424, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees north of Newton-Hamilton.');
INSERT INTO public.stormevents_east VALUES (745494, 201805, 13, 1634, 201805, 13, 1634, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:34:00', 'EST-5', '13-MAY-18 16:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'NW', 'GRAY', 1, 'NW', 'GRAY', 40.1363, -79.0888, 40.1363, -79.0888, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down numerous trees near Gray.');
INSERT INTO public.stormevents_east VALUES (745495, 201805, 13, 1638, 201805, 13, 1638, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:38:00', 'EST-5', '13-MAY-18 16:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 0, 'NNW', 'ACOSTA', 0, 'NNW', 'ACOSTA', 40.1236, -79.072, 40.1236, -79.072, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees along Watson Avenue north of Acosta.');
INSERT INTO public.stormevents_east VALUES (745496, 201805, 13, 1652, 201805, 13, 1652, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:52:00', 'EST-5', '13-MAY-18 16:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 1, 'SSW', 'HOOVERSVILLE', 1, 'SSW', 'HOOVERSVILLE', 40.1418, -78.9259, 40.1418, -78.9259, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees along Route 403 south of Hooversville.');
INSERT INTO public.stormevents_east VALUES (745538, 201805, 15, 1341, 201805, 15, 1341, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 13:41:00', 'EST-5', '15-MAY-18 13:41:00', 0, 0, 0, 0, '15.00K', '0.00K', '911 Call Center', 61, 'EG', NULL, NULL, 1, 'W', 'MIFFLINBURG', 1, 'W', 'MIFFLINBURG', 40.92, -77.05, 40.92, -77.05, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph blew a roof off of a building in Mifflinburg.');
