INSERT INTO public.stormevents_east VALUES (751956, 201805, 31, 1530, 201805, 31, 1532, 124671, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '31-MAY-18 15:30:00', 'EST-5', '31-MAY-18 15:32:00', 0, 0, 0, 0, '3.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'MT OREB', 0, 'N', 'MT OREB', 39.03, -83.92, 39.03, -83.92, 'A complex of thunderstorms pushed east across the Ohio Valley during the afternoon hours. Several of the thunderstorms produced damaging wind gusts.', 'A few trees were downed.');
