INSERT INTO public.stormevents_east VALUES (751964, 201805, 31, 1547, 201805, 31, 1549, 124671, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '31-MAY-18 15:47:00', 'EST-5', '31-MAY-18 15:49:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'BENTONVILLE', 1, 'W', 'BENTONVILLE', 38.75, -83.61, 38.75, -83.61, 'A complex of thunderstorms pushed east across the Ohio Valley during the afternoon hours. Several of the thunderstorms produced damaging wind gusts.', 'A tree was downed.');
INSERT INTO public.stormevents_east VALUES (748054, 201805, 31, 1341, 201805, 31, 1341, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 13:41:00', 'EST-5', '31-MAY-18 13:41:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'BURNING SPGS', 1, 'WNW', 'BURNING SPGS', 37.2554, -83.817, 37.2554, -83.817, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch reported a tree blown down on U.S. Highway 421 near Burning Springs.');
INSERT INTO public.stormevents_east VALUES (748056, 201805, 31, 1527, 201805, 31, 1527, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 15:27:00', 'EST-5', '31-MAY-18 15:27:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 53, 'EG', NULL, NULL, 2, 'NW', 'HILL TOP', 2, 'NW', 'HILL TOP', 38.3894, -83.8592, 38.3894, -83.8592, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch relayed a report of a large tree blown down across the road in the vicinity of Cedar Lake.');
INSERT INTO public.stormevents_east VALUES (748058, 201805, 31, 1532, 201805, 31, 1532, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 15:32:00', 'EST-5', '31-MAY-18 15:32:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'STANTON', 1, 'E', 'STANTON', 37.85, -83.86, 37.85, -83.86, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch reported a large tree limb blown down in Stanton.');
INSERT INTO public.stormevents_east VALUES (743686, 201805, 5, 1525, 201805, 5, 1525, 123919, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'RLX', '05-MAY-18 15:25:00', 'EST-5', '05-MAY-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1.25, NULL, NULL, NULL, 1, 'E', 'CLINTWOOD', 1, 'E', 'CLINTWOOD', 37.15, -82.46, 37.15, -82.46, 'Following a period of sunshine earlier in the day, thunderstorms formed across southwest Virginia and southeast Kentucky during the late afternoon of the 5th as a low pressure system approached. Large hail fell out of these storms during the late afternoon and evening.', NULL);
