INSERT INTO public.stormevents_east VALUES (745572, 201805, 16, 2000, 201805, 16, 2200, 124187, 'KENTUCKY', 21, 2018, 'May', 'Flood', 'ILN', '16-MAY-18 20:00:00', 'EST-5', '16-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'TOLLESBORO', 1, 'N', 'TOLLESBORO', 38.5624, -83.5807, 38.5615, -83.5713, 'Slow moving thunderstorms produced localized flash flooding during the early morning hours and then again during the afternoon hours.', 'Flooding issues lingered in the Tollesboro area from the heavy rain that fell earlier in the afternoon and evening.');
INSERT INTO public.stormevents_east VALUES (743999, 201805, 4, 1725, 201805, 4, 1727, 123967, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '04-MAY-18 17:25:00', 'EST-5', '04-MAY-18 17:27:00', 0, 0, 0, 0, '0.25K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'S', 'KINGSTON', 1, 'S', 'KINGSTON', 39.4555, -82.92, 39.4555, -82.92, 'Scattered thunderstorms developed along a cold front that pushed slowly south into the upper Ohio Valley.', 'A few large limbs were downed.');
INSERT INTO public.stormevents_east VALUES (744820, 201805, 14, 1257, 201805, 14, 1259, 124120, 'OHIO', 39, 2018, 'May', 'Hail', 'ILN', '14-MAY-18 12:57:00', 'EST-5', '14-MAY-18 12:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 6, 'NNE', 'ROCKBRIDGE', 6, 'NNE', 'ROCKBRIDGE', 39.66, -82.48, 39.66, -82.48, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', NULL);
INSERT INTO public.stormevents_east VALUES (744821, 201805, 14, 1143, 201805, 14, 1145, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 11:43:00', 'EST-5', '14-MAY-18 11:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'ENE', 'GALENA', 0, 'ENE', 'GALENA', 40.2228, -82.8743, 40.2228, -82.8743, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'A couple of trees were downed onto State Route 3.');
INSERT INTO public.stormevents_east VALUES (752923, 201805, 21, 2058, 201805, 22, 0, 125542, 'OHIO', 39, 2018, 'May', 'Flash Flood', 'CLE', '21-MAY-18 20:58:00', 'EST-5', '22-MAY-18 00:00:00', 0, 0, 0, 0, '80.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'HANLEY VLG', 2, 'NW', 'LEXINGTON', 40.6983, -82.5653, 40.689, -82.6013, 'Strong thunderstorms evolved across western Ohio during the afternoon and moved into central Ohio around 6-6:30 pm. Severe storms with winds and hail were prevalent. By the evening the storms began train along a warm front and old lake breeze boundary over the Central Highlands of Morrow and Richland counties. Storms intensified and slowed along this boundary, with the heaviest rainfall localized over Lexington. Flash flooding resulted.', 'Thunderstorms with heavy rainfall caused washouts and flood damage in Lexington Ohio on the evening of May 21st. Heavy rain moved into the area between 830 and 930 pm with rainfall amounts measured at 3.58���. The heaviest rain fell within a 15 minute period between 840 and 855 pm. Significant flooding to recreational parks up to 6 feet of water from the Clear Fork. Overland flooding in west end of town. Otterbein Drive washout in parts off of State Route 97. Norfolk Drive had minor road damage. Lexington-Ontario Road washout not seen before by residents. 15-16 homes had flood damage, mainly to basements and garages with at least 1 first floor residence.  Storage facility on Orchard Park Road flooded all units. . A rain gauge at Northmor High School in Morrow County went over 2 inches in approximately 1 hour between 830 and 930 pm. During this same time the heaviest rainfall was over Lexington Ohio.');
INSERT INTO public.stormevents_east VALUES (756688, 201805, 21, 1836, 201805, 21, 1836, 125542, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '21-MAY-18 18:36:00', 'EST-5', '21-MAY-18 18:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NW', 'CLIMAX', 2, 'NW', 'CLIMAX', 40.6471, -82.9137, 40.6471, -82.9137, 'Strong thunderstorms evolved across western Ohio during the afternoon and moved into central Ohio around 6-6:30 pm. Severe storms with winds and hail were prevalent. By the evening the storms began train along a warm front and old lake breeze boundary over the Central Highlands of Morrow and Richland counties. Storms intensified and slowed along this boundary, with the heaviest rainfall localized over Lexington. Flash flooding resulted.', 'Thunderstorm winds downed a tree along Martel Road (County Highway 171) just north of State Route 39.');
INSERT INTO public.stormevents_east VALUES (756689, 201805, 21, 1915, 201805, 21, 1915, 125542, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'CLE', '21-MAY-18 19:15:00', 'EST-5', '21-MAY-18 19:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'WSW', 'ALTA', 2, 'WSW', 'ALTA', 40.7228, -82.5993, 40.7228, -82.5993, 'Strong thunderstorms evolved across western Ohio during the afternoon and moved into central Ohio around 6-6:30 pm. Severe storms with winds and hail were prevalent. By the evening the storms began train along a warm front and old lake breeze boundary over the Central Highlands of Morrow and Richland counties. Storms intensified and slowed along this boundary, with the heaviest rainfall localized over Lexington. Flash flooding resulted.', 'Thunderstorm winds downed trees near the intersection of Graham Road and Marion Avenue.');
INSERT INTO public.stormevents_east VALUES (751434, 201805, 4, 1914, 201805, 4, 1914, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:14:00', 'EST-5', '04-MAY-18 19:14:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 50, 'MG', NULL, NULL, 0, 'N', 'SCHENECTADY ARPT', 0, 'N', 'SCHENECTADY ARPT', 42.85, -73.93, 42.85, -73.93, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A gust of 58 mph was recorded at the Schenectady County Airport (KSCH).');
INSERT INTO public.stormevents_east VALUES (751435, 201805, 4, 1915, 201805, 4, 1915, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:15:00', 'EST-5', '04-MAY-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 54, 'MG', NULL, NULL, 1, 'SE', '(GFL)GLENS FALLS ARP', 1, 'SE', '(GFL)GLENS FALLS ARP', 43.3409, -73.602, 43.3409, -73.602, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A gust of 62 mph was recorded at the New York State Mesonet site near Glens Falls.');
INSERT INTO public.stormevents_east VALUES (751436, 201805, 4, 1915, 201805, 4, 1915, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:15:00', 'EST-5', '04-MAY-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 50, 'EG', NULL, NULL, 1, 'E', 'CLIFTON PARK CENTER', 1, 'E', 'CLIFTON PARK CENTER', 42.8482, -73.8036, 42.8482, -73.8036, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Reports of trees and wires down near Barney Road in Clifton Park.');
INSERT INTO public.stormevents_east VALUES (745262, 201805, 14, 1208, 201805, 14, 1210, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:08:00', 'EST-5', '14-MAY-18 12:10:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'GRANVILLE', 1, 'E', 'GRANVILLE', 40.07, -82.5, 40.07, -82.5, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'Several trees were downed in the Granville area.');
INSERT INTO public.stormevents_east VALUES (757093, 201805, 25, 1330, 201805, 25, 1330, 126303, 'FLORIDA', 12, 2018, 'May', 'Funnel Cloud', 'MFL', '25-MAY-18 13:30:00', 'EST-5', '25-MAY-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 1, 'N', 'NAPLES', 1, 'N', 'NAPLES', 26.14, -81.8, 26.14, -81.8, 'Afternoon showers and storms developed along the sea breezes along each coast. The Gulf coast sea breeze produced a shower that developed a funnel cloud over Naples.', 'A funnel cloud photo and video were reported via social media associated with a shower moving through the Naples area. The funnel did not touchdown.');
INSERT INTO public.stormevents_east VALUES (756904, 201805, 10, 1300, 201805, 10, 1300, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 13:00:00', 'EST-5', '10-MAY-18 13:00:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 3, 'WNW', 'ENOLA', 3, 'WNW', 'ENOLA', 35.695, -81.701, 35.695, -81.701, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Media reported nickel to quarter size hail off Salem Rd.');
INSERT INTO public.stormevents_east VALUES (757104, 201805, 10, 1355, 201805, 10, 1355, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 13:55:00', 'EST-5', '10-MAY-18 13:55:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 1, 'NE', 'COLUMBUS', 1, 'NE', 'COLUMBUS', 35.263, -82.182, 35.263, -82.182, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Public reported penny sized hail along Highway 108 just east of Columbus.');
INSERT INTO public.stormevents_east VALUES (757106, 201805, 10, 1435, 201805, 10, 1455, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 14:35:00', 'EST-5', '10-MAY-18 14:55:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 2, 'NNE', 'SANDY PLAINS', 2, 'NNE', 'SANDY PLAINS', 35.281, -82.068, 35.281, -82.068, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Public reported an extended period of up to 3/4 inch hail as multiple strong to severe storms trained over Polk County.');
INSERT INTO public.stormevents_east VALUES (757107, 201805, 10, 1432, 201805, 10, 1432, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 14:32:00', 'EST-5', '10-MAY-18 14:32:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 1, NULL, NULL, NULL, 1, 'E', 'MILL SPG', 1, 'E', 'MILL SPG', 35.3, -82.16, 35.3, -82.16, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'EM reported quarter size hail in the Mill Spring area as multiple strong to severe storms trained over Polk County.');
INSERT INTO public.stormevents_east VALUES (779370, 201808, 10, 1510, 201808, 10, 1715, 130142, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PBZ', '10-AUG-18 15:10:00', 'EST-5', '10-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'ELIZABETH', 1, 'E', 'ELIZABETH', 40.2724, -79.8691, 40.2701, -79.8684, 'Showers and thunderstorms formed along a nearly stationary boundary that crept southeastward from the Great Lakes.  Precipitable water values of around 1.6 inches and weak steering flow along the boundary led to a few areas of training thunderstorms.  Rainfall amounts of 1.5 to 3.0 inches on already saturated ground led to several areas of flash flooding in Washington, Allegheny, and Westmoreland Counties.  The worst flooding was near Herminie, where up to 14 homes were impacted and a mobile home was shifted off of its foundation.', 'The county emergency manager reported that Happy Hollow Road was closed from Long Acre Drive to Scenery Drive due to flooding.');
INSERT INTO public.stormevents_east VALUES (758859, 201805, 19, 0, 201805, 19, 1800, 126514, 'NORTH CAROLINA', 37, 2018, 'May', 'Flood', 'GSP', '19-MAY-18 00:00:00', 'EST-5', '19-MAY-18 18:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'SALUDA', 0, 'ESE', 'MELROSE', 35.253, -82.335, 35.219, -82.326, 'Wait for it.', 'Although heavy rain ended across western Polk County late in the evening on the 18th, high water conditions persisted across the Saluda and Green River area through the overnight and much of the daylight hours on the 19th before the water finally receded.');
INSERT INTO public.stormevents_east VALUES (752114, 201805, 4, 1826, 201805, 4, 1826, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:26:00', 'EST-5', '04-MAY-18 18:26:00', 0, 0, 0, 0, NULL, NULL, 'Public', 70, 'EG', NULL, NULL, 1, 'SE', 'BREDTVILLE', 1, 'SE', 'BREDTVILLE', 43.0587, -74.5076, 43.0587, -74.5076, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Around 30 trees snapped about 20 feet above the ground or uprooted in a quarter-mile swath.');
INSERT INTO public.stormevents_east VALUES (752115, 201805, 4, 1908, 201805, 4, 1909, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:08:00', 'EST-5', '04-MAY-18 19:09:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 70, 'EG', NULL, NULL, 1, 'NE', 'EAST LINE', 1, 'NNW', 'MALTA', 42.9847, -73.8025, 42.9855, -73.7851, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A concentrated area of wind damage impacted the Travers Meadows subdivision in Malta. Several houses sustained shingle and siding damage. A basketball hoop and metal sign were bent. In the vicinity of Cramer Road, extensive tree damage occurred and a newly framed home collapsed.');
INSERT INTO public.stormevents_east VALUES (745255, 201805, 14, 1330, 201805, 14, 1430, 124120, 'OHIO', 39, 2018, 'May', 'Flood', 'ILN', '14-MAY-18 13:30:00', 'EST-5', '14-MAY-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'LOGAN', 1, 'ENE', 'LOGAN', 39.54, -82.4, 39.5365, -82.4016, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'High water was reported on some roads in Logan.');
INSERT INTO public.stormevents_east VALUES (758498, 201805, 18, 1900, 201805, 19, 1000, 126514, 'NORTH CAROLINA', 37, 2018, 'May', 'Flood', 'GSP', '18-MAY-18 19:00:00', 'EST-5', '19-MAY-18 10:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'E', 'JOY', 3, 'ESE', 'JOY', 35.872, -81.707, 35.862, -81.722, 'Wait for it.', 'A stream gauge on Johns River indicated moderate flooding developed along the river in northern Burke County after major flash flooding developed near the headwaters of the Johns River and the major tributary of Wilson Creek when up to 7 inches of rain fell across extreme western Caldwell County in just a few hours. Roads impacted by the flooded river included Johns River Rd, Old Johns River Rd, and Johns River Loop Rd.');
INSERT INTO public.stormevents_east VALUES (758858, 201805, 18, 1930, 201805, 19, 0, 126514, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '18-MAY-18 19:30:00', 'EST-5', '19-MAY-18 00:00:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'SALUDA', 0, 'ESE', 'MELROSE', 35.253, -82.335, 35.219, -82.326, 'Wait for it.', 'Multiple sources reported significant flash flooding developed across western Polk County, particularly in the Saluda area after 4 to 7 inches of rain fell across the area in just a few hours. Some of the main impacts were along Cove Creek and its tributaries, where water rescues were required in the area around I-26 and Ozone Dr. Multiple roads in this area, including I-26 itself were flooded due to drainage problems and small streams. A tributary of Cove Creek flooded Howard Gap Rd at Rhododendron Dr. Across the northern part of the county, Lake Adger Parkway was covered with water from Silver Creek. Flooding was also reported along the North Pacolet River along the Highway 176 corridor between Columbus and Saluda. While the flooding was significant, the worst impact of the heavy rain was from numerous landslides and slope failures.');
INSERT INTO public.stormevents_east VALUES (745258, 201805, 14, 1230, 201805, 14, 1232, 124120, 'OHIO', 39, 2018, 'May', 'Hail', 'ILN', '14-MAY-18 12:30:00', 'EST-5', '14-MAY-18 12:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 0, 'N', 'SUGAR GROVE', 0, 'N', 'SUGAR GROVE', 39.63, -82.55, 39.63, -82.55, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', NULL);
INSERT INTO public.stormevents_east VALUES (759232, 201805, 4, 2025, 201805, 4, 2029, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:25:00', 'EST-5', '04-MAY-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SW', 'WARREN', 1, 'SW', 'WARREN', 43.92, -71.89, 43.92, -71.89, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires closing Route 25C in Warren.');
INSERT INTO public.stormevents_east VALUES (759236, 201805, 4, 2030, 201805, 4, 2034, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:30:00', 'EST-5', '04-MAY-18 20:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'S', 'SPOFFORD', 1, 'S', 'SPOFFORD', 42.91, -72.42, 42.91, -72.42, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees, wires and transformers at multiple locations in Spofford.');
INSERT INTO public.stormevents_east VALUES (759237, 201805, 4, 2030, 201805, 4, 2035, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:30:00', 'EST-5', '04-MAY-18 20:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NW', 'KEENE', 2, 'NW', 'KEENE', 42.95, -72.3, 42.95, -72.3, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires in Keene.');
INSERT INTO public.stormevents_east VALUES (759238, 201805, 4, 2030, 201805, 4, 2035, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:30:00', 'EST-5', '04-MAY-18 20:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'WALPOLE', 0, 'N', 'WALPOLE', 43.08, -72.43, 43.08, -72.43, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees in Walpole.');
INSERT INTO public.stormevents_east VALUES (759243, 201805, 4, 2033, 201805, 4, 2037, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:33:00', 'EST-5', '04-MAY-18 20:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NE', 'EASTON', 2, 'NE', 'EASTON', 44.17, -71.75, 44.17, -71.75, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees in Easton.');
INSERT INTO public.stormevents_east VALUES (759247, 201805, 4, 2045, 201805, 4, 2050, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:45:00', 'EST-5', '04-MAY-18 20:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'GORHAM', 1, 'N', 'GORHAM', 44.39, -71.17, 44.39, -71.17, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees closing Route 16 at the Shelbourne line in Gorham.');
INSERT INTO public.stormevents_east VALUES (749694, 201805, 18, 1708, 201805, 18, 2308, 124894, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'RNK', '18-MAY-18 17:08:00', 'EST-5', '18-MAY-18 23:08:00', 0, 0, 0, 0, '1.25M', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'BOWERS GAP', 2, 'SE', 'KELLERSVILLE', 36.1502, -81.8429, 36.2306, -81.8835, 'The synoptic pattern remained little changed from the previous day with deep moisture in place. An axis of very heavy rainfall pushed north across the Carolinas in the late afternoon and evening as the weak area of low pressure over the southeast lifted slowly northward. Slow-moving storms with highly efficient rainfall affected number of areas in the mountains and foothills of northern North Carolina. Rainfall amount were generally 2 to 4 inches over a several hour period with isolated higher amounts.', 'Widespread flooding was reported across southern Watauga County. The Boone Fire Department said a woman driving on a flooded section of Bamboo Road got her SUV swept up by the flood waters. Rescue crews quickly got her to safety with no serious injuries. One foot of water was estimated to be flowing down Seven Devils Road onto Route 105 near Foscoe.  Linville Creek was reported to have flooded over the bridge at Linville Creek Road. The Watauga River at Sugar Grove (SGWN7) crested at 16.15 feet, the highest stage since September, 2004. Several debris flows were reported across the area, blocking roads. Overall damage to road infrastructure was around $1 million.');
INSERT INTO public.stormevents_east VALUES (750034, 201805, 18, 1510, 201805, 18, 1810, 124894, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'RNK', '18-MAY-18 15:10:00', 'EST-5', '18-MAY-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'KING', 1, 'NNE', 'KING', 36.2967, -80.3641, 36.2979, -80.363, 'The synoptic pattern remained little changed from the previous day with deep moisture in place. An axis of very heavy rainfall pushed north across the Carolinas in the late afternoon and evening as the weak area of low pressure over the southeast lifted slowly northward. Slow-moving storms with highly efficient rainfall affected number of areas in the mountains and foothills of northern North Carolina. Rainfall amount were generally 2 to 4 inches over a several hour period with isolated higher amounts.', 'Danbury Creek flooded over Brown Road, closing the road.');
INSERT INTO public.stormevents_east VALUES (760020, 201805, 29, 1330, 201805, 30, 0, 126710, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '29-MAY-18 13:30:00', 'EST-5', '30-MAY-18 00:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'BLACK MTN', 0, 'NE', 'GROVESTONE', 35.61, -82.334, 35.604, -82.363, 'A very moist southeast flow developed northeast of subtropical cyclone Alberto, which made landfall across the western Florida Peninsula on the 28th and moved north across Alabama throughout the 29th. Resultant upslope flow into the southern Appalachians resulted in development of widespread heavy rain showers across western North Carolina throughout the 29th, with activity being most concentrated along the eastern escarpment of the Blue Ridge. By the time the showers tapered off during the 30th, total rainfall of 7-10 inches occurred along the Blue Ridge. This resulted in fairly widespread flash flooding followed by an extended period of high stream flow, with McDowell County being the hardest hit area.', 'A stream gauge indicated and county comms confirmed flash flooding developed along the Swannanoa River in the Black Mountain area after 2 to 3 inches or rain fell across the area in just a few hours. This was after stream levels were already elevated due to heavy rain that fell on the 28th. The main impact was to areas around Veterans Park, including Veterans park Dr. The stream briefly fell below flood stage during late afternoon, but another round of heavy rain during the evening quickly sent it back above flood stage, where it crested at moderate flood stage before beginning to recede during late evening. Total rainfall of 4 to 6 inches was reported in the area on the 29th.');
INSERT INTO public.stormevents_east VALUES (760042, 201805, 29, 1745, 201805, 30, 0, 126710, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '29-MAY-18 17:45:00', 'EST-5', '30-MAY-18 00:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'VALHALLA', 1, 'NNW', 'MT VLY', 35.217, -82.295, 35.292, -82.308, 'A very moist southeast flow developed northeast of subtropical cyclone Alberto, which made landfall across the western Florida Peninsula on the 28th and moved north across Alabama throughout the 29th. Resultant upslope flow into the southern Appalachians resulted in development of widespread heavy rain showers across western North Carolina throughout the 29th, with activity being most concentrated along the eastern escarpment of the Blue Ridge. By the time the showers tapered off during the 30th, total rainfall of 7-10 inches occurred along the Blue Ridge. This resulted in fairly widespread flash flooding followed by an extended period of high stream flow, with McDowell County being the hardest hit area.', 'County comms and the media reported that flash flooding developed across western Polk County for the 2nd time in less than two weeks, after 4 to 6 inches of rain fell throughout the 29th into the 30th, with much of that occurring over a couple of hours during the evening. The most significant flooding was along Brights Creek west of Lake Adger, which overflowed its banks and flooded multiple bridges, effectively cutting off the Brights Creek community for a brief time. Highway 64 was closed due to flooding along the North Pacolet, where a mobile home park was also evacuated. Additional closed roads included Green River Cove Rd, Holbert Cove Rd, and Warrior Drive (due to a tributary of the North Pacolet).');
INSERT INTO public.stormevents_east VALUES (758093, 201805, 4, 1501, 201805, 4, 1501, 126470, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '04-MAY-18 15:01:00', 'EST-5', '04-MAY-18 15:01:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'SHEAKLEYVILLE', 1, 'SE', 'SHEAKLEYVILLE', 41.44, -80.21, 41.44, -80.21, 'Showers and thunderstorms, some of which became severe developed ahead of and along a passing cold front on the 4th. While instability was rather modest, shear supported some storms to severe levels, with damaging wind as a result.', 'State official reported two trees down in Sheakleyville.');
INSERT INTO public.stormevents_east VALUES (759318, 201805, 12, 1640, 201805, 12, 1640, 126655, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '12-MAY-18 16:40:00', 'EST-5', '12-MAY-18 16:40:00', 0, 0, 0, 0, '8.00K', '0.00K', 'State Official', 56, 'EG', NULL, NULL, 1, 'WSW', 'VENETIA', 1, 'WSW', 'VENETIA', 40.24, -80.07, 40.24, -80.07, 'Showers and thunderstorms developed along a stalled frontal boundary that was situated over the upper Ohio Valley. Strong to severe storms resulted in several reports of downed trees and hail in southwestern Pennsylvania and eastern Ohio.', 'State official reported dozens of trees snapped or uprooted. Roof barn and carport removed, along with other structural damage noted.');
INSERT INTO public.stormevents_east VALUES (759317, 201805, 12, 1640, 201805, 12, 1640, 126655, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '12-MAY-18 16:40:00', 'EST-5', '12-MAY-18 16:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 56, 'EG', NULL, NULL, 2, 'E', 'THOMAS', 2, 'E', 'THOMAS', 40.23, -80.07, 40.23, -80.07, 'Showers and thunderstorms developed along a stalled frontal boundary that was situated over the upper Ohio Valley. Strong to severe storms resulted in several reports of downed trees and hail in southwestern Pennsylvania and eastern Ohio.', 'State official reported that high tension lines were down along Valley View Road. There is widespread tree damage in this vicinity and along Munntown Road associated with earlier reported downburst.');
INSERT INTO public.stormevents_east VALUES (760672, 201805, 14, 1239, 201805, 14, 1244, 126677, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 12:39:00', 'EST-5', '14-MAY-18 12:44:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 2, NULL, NULL, NULL, 1, 'NNE', 'CLAYSVILLE', 1, 'NNE', 'CLAYSVILLE', 40.14, -80.41, 40.14, -80.41, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', 'A public citizen provided photos and a video of hail up to two inches in diameter.');
INSERT INTO public.stormevents_east VALUES (760720, 201805, 14, 1245, 201805, 14, 1245, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 12:45:00', 'EST-5', '14-MAY-18 12:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1, NULL, NULL, NULL, 1, 'N', 'VALLEY GROVE', 1, 'N', 'VALLEY GROVE', 40.09, -80.57, 40.09, -80.57, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', NULL);
INSERT INTO public.stormevents_east VALUES (747114, 201805, 27, 700, 201805, 27, 900, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 07:00:00', 'EST-5', '27-MAY-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'PRINCETON', 2, 'WSW', 'PENNS NECK', 40.3309, -74.6797, 40.3212, -74.6602, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Road closures in Princeton, including Quaker Road and Mercer Road.');
INSERT INTO public.stormevents_east VALUES (747116, 201805, 27, 700, 201805, 27, 900, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 07:00:00', 'EST-5', '27-MAY-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'TITUSVILLE', 2, 'WNW', 'TITUSVILLE', 40.3239, -74.9189, 40.326, -74.9173, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Route 29 was closed due to flooding around Pleasant Valley Road in Hopewell Township.');
INSERT INTO public.stormevents_east VALUES (747118, 201805, 27, 700, 201805, 27, 900, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 07:00:00', 'EST-5', '27-MAY-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'CLARKSVILLE', 1, 'WNW', 'EAST TRENTON', 40.3067, -74.6995, 40.2549, -74.7405, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Portions of the Princeton Pike were closed in Lawrence Township, including the areas around Shipetaukin Creek and Shabakunk Creek.');
INSERT INTO public.stormevents_east VALUES (747119, 201805, 27, 600, 201805, 27, 800, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 06:00:00', 'EST-5', '27-MAY-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'CRANBURY', 1, 'WNW', 'CRANBURY', 40.3302, -74.5477, 40.3277, -74.5442, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'The Petty Road bridge across Cedar Brook in Cranbury Township was washed out.');
INSERT INTO public.stormevents_east VALUES (747120, 201805, 27, 930, 201805, 27, 1025, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 09:30:00', 'EST-5', '27-MAY-18 10:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'TRENTON', 1, 'N', 'TRENTON', 40.2194, -74.7562, 40.2284, -74.7485, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'The Assunpink Creek exceeded its flood stage at Trenton.');
INSERT INTO public.stormevents_east VALUES (747121, 201805, 27, 830, 201805, 27, 1025, 124519, 'NEW JERSEY', 34, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 08:30:00', 'EST-5', '27-MAY-18 10:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'EAST TRENTON', 0, 'ENE', 'EAST TRENTON', 40.2459, -74.7316, 40.2535, -74.7222, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'The Assunpink Creek exceeded its flood stage at Mercerville.');
INSERT INTO public.stormevents_east VALUES (747122, 201805, 27, 930, 201805, 27, 1025, 124520, 'PENNSYLVANIA', 42, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 09:30:00', 'EST-5', '27-MAY-18 10:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'LANGHORNE', 2, 'ESE', 'TREVOSE', 40.1848, -74.964, 40.1452, -74.9706, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'The Neshaminy Creek exceeded its flood stage at Langhorne.');
INSERT INTO public.stormevents_east VALUES (747123, 201805, 27, 600, 201805, 27, 900, 124520, 'PENNSYLVANIA', 42, 2018, 'May', 'Flash Flood', 'PHI', '27-MAY-18 06:00:00', 'EST-5', '27-MAY-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'FOUNTAINVILLE', 1, 'NNE', 'TRADESVILLE', 40.3402, -75.1613, 40.284, -75.1592, 'Heavy rain fell on the morning of May 27 from Bucks County in southeastern Pennsylvania eastward into central New Jersey.  Rainfall amounts of 2 to 4 inches were common with some locations receiving up to 5 or 6 inches of rain.', 'Numerous roads in Doylestown were flooded and impassable. The Doylestown airport received 3.75 inches of rain in 80 minutes.');
INSERT INTO public.stormevents_east VALUES (776122, 201807, 2, 1552, 201807, 2, 1552, 129536, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '02-JUL-18 15:52:00', 'EST-5', '02-JUL-18 15:52:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'CORTLAND ARPT', 1, 'N', 'CORTLAND ARPT', 42.61, -76.2, 42.61, -76.2, 'A cold front moved into the eastern Great Lakes region the afternoon of the 2nd. This front sparked a round of severe thunderstorms in central New York and far northern Pennsylvania from the mid afternoon to early evening of the 2nd before becoming a stationary front in the eastern Great Lakes.', 'Strong thunderstorm winds knocked down trees in several locations. Trees were down across a few roadways.');
