INSERT INTO public.stormevents_east VALUES (745497, 201805, 13, 1655, 201805, 13, 1655, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:55:00', 'EST-5', '13-MAY-18 16:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 1, 'S', 'WILBERTOWN', 1, 'S', 'WILBERTOWN', 40.11, -78.8953, 40.11, -78.8953, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in the vicinity of Slick Road, Wilbur Road and Old Forbes Road east of Stoystown.');
INSERT INTO public.stormevents_east VALUES (745499, 201805, 13, 1701, 201805, 13, 1701, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 17:01:00', 'EST-5', '13-MAY-18 17:01:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 4, 'WSW', 'BAKERSVILLE', 4, 'WSW', 'BAKERSVILLE', 40.0241, -79.2828, 40.0241, -79.2828, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a large tree onto wires near the Seven Springs Golf Course, partially blocking the roadway.');
INSERT INTO public.stormevents_east VALUES (745498, 201805, 13, 1657, 201805, 13, 1657, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 16:57:00', 'EST-5', '13-MAY-18 16:57:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Fire Department/Rescue', 61, 'EG', NULL, NULL, 1, 'SSE', 'CENTRAL CITY ARPT', 1, 'SSE', 'CENTRAL CITY ARPT', 40.0331, -78.8454, 40.0331, -78.8454, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 70 mph knocked down several power lines in a field near the entrance to Indian Lake on Huckleberry Highway.');
