INSERT INTO public.stormevents_east VALUES (751971, 201805, 31, 1626, 201805, 31, 1628, 124671, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '31-MAY-18 16:26:00', 'EST-5', '31-MAY-18 16:28:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'NW', 'MC DERMOTT', 0, 'NW', 'MC DERMOTT', 38.831, -83.0709, 38.831, -83.0709, 'A complex of thunderstorms pushed east across the Ohio Valley during the afternoon hours. Several of the thunderstorms produced damaging wind gusts.', 'A tree was downed on the 4600 block of McDermott Pond Creek Road.');
