INSERT INTO public.stormevents_east VALUES (748064, 201805, 31, 1555, 201805, 31, 1555, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 15:55:00', 'EST-5', '31-MAY-18 15:55:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 51, 'EG', NULL, NULL, 3, 'S', 'HILDA', 3, 'S', 'HILDA', 38.19, -83.49, 38.19, -83.49, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch relayed a report of a tree blown down on Bluestone Road west of Morehead.');
INSERT INTO public.stormevents_east VALUES (748066, 201805, 31, 1604, 201805, 31, 1604, 124674, 'KENTUCKY', 21, 2018, 'May', 'Thunderstorm Wind', 'JKL', '31-MAY-18 16:04:00', 'EST-5', '31-MAY-18 16:04:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'KELLACEY', 1, 'S', 'KELLACEY', 37.95, -83.4, 37.95, -83.4, 'Two mesoscale convective systems moved through eastern Kentucky during the day. The first tracked through during the early to mid afternoon hours, while the second followed in its wake from mid afternoon through the evening. Strong to severe winds along the leading edge of each complex led to scattered damage throughout eastern Kentucky, mainly consisting of downed trees. Additionally, isolated flash flooding occurred in Jackson and Whitley Counties due to the multiple rounds of heavy rainfall. Clover Bottom in particular saw very heavy rainfall as over 3 inches of rain in a short period of time damaged a portion of U.S. Highway 421.', 'Dispatch reported a tree blown down onto a power line near Arnett, northwest of West Liberty.');
INSERT INTO public.stormevents_east VALUES (744828, 201805, 14, 1208, 201805, 14, 1210, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:08:00', 'EST-5', '14-MAY-18 12:10:00', 0, 0, 0, 0, '0.25K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'W', 'NEWARK', 3, 'W', 'NEWARK', 40.07, -82.46, 40.07, -82.46, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'Numerous large limbs were downed.');
INSERT INTO public.stormevents_east VALUES (744829, 201805, 14, 1213, 201805, 14, 1215, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:13:00', 'EST-5', '14-MAY-18 12:15:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NE', 'HEATH', 1, 'NE', 'HEATH', 40.03, -82.44, 40.03, -82.44, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'A few shingles were blown off of a structure.');
INSERT INTO public.stormevents_east VALUES (744831, 201805, 14, 1215, 201805, 14, 1217, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:15:00', 'EST-5', '14-MAY-18 12:17:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'W', 'NEWARK', 1, 'W', 'NEWARK', 40.07, -82.41, 40.07, -82.41, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'Numerous trees were downed along with a utility pole in the Newark area.');
INSERT INTO public.stormevents_east VALUES (744832, 201805, 14, 1222, 201805, 14, 1224, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:22:00', 'EST-5', '14-MAY-18 12:24:00', 0, 0, 0, 0, '3.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'BALTIMORE', 1, 'S', 'BALTIMORE', 39.84, -82.6, 39.84, -82.6, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'Numerous trees were downed in the Baltimore area.');
INSERT INTO public.stormevents_east VALUES (744834, 201805, 14, 1143, 201805, 14, 1144, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 11:43:00', 'EST-5', '14-MAY-18 11:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 51, 'MG', NULL, NULL, 0, 'N', '(OSU)OH ST UNIV ARPT', 0, 'N', '(OSU)OH ST UNIV ARPT', 40.08, -83.07, 40.08, -83.07, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', NULL);
INSERT INTO public.stormevents_east VALUES (745264, 201805, 14, 1226, 201805, 14, 1228, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:26:00', 'EST-5', '14-MAY-18 12:28:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'WSW', 'MILLERSPORT', 0, 'WSW', 'MILLERSPORT', 39.8976, -82.5351, 39.8976, -82.5351, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'A tree was downed near Millersport.');
INSERT INTO public.stormevents_east VALUES (745267, 201805, 14, 1234, 201805, 14, 1236, 124120, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'ILN', '14-MAY-18 12:34:00', 'EST-5', '14-MAY-18 12:36:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'CLAY LICK', 1, 'N', 'CLAY LICK', 40.08, -82.27, 40.08, -82.27, 'Thunderstorms developed during the early afternoon hours along an outflow boundary situated across central Ohio.', 'A few trees were downed.');
INSERT INTO public.stormevents_east VALUES (751143, 201805, 4, 1842, 201805, 4, 1842, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:42:00', 'EST-5', '04-MAY-18 18:42:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'SHARON SPGS', 1, 'N', 'SHARON SPGS', 42.79, -74.62, 42.79, -74.62, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Three trees were downed.');
INSERT INTO public.stormevents_east VALUES (836013, 201807, 24, 917, 201807, 24, 918, 138989, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '24-JUL-18 09:17:00', 'EST-5', '24-JUL-18 09:18:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 7, 'W', 'EDISTO BEACH', 7, 'W', 'EDISTO BEACH', 32.5, -80.44, 32.5, -80.44, 'A wave of energy associated with a mid-level low pressure system led to a few showers and thunderstorms capable of producing waterspouts.', 'Reports via social media indicated a brief waterspout.');
INSERT INTO public.stormevents_east VALUES (836015, 201807, 29, 853, 201807, 29, 854, 138990, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '29-JUL-18 08:53:00', 'EST-5', '29-JUL-18 08:54:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 12, 'SE', 'KIAWAH ISLAND', 12, 'SE', 'KIAWAH ISLAND', 32.48, -79.93, 32.48, -79.93, 'Deep moisture and light winds between high pressure offshore and low pressure inland led to an environment favorable for waterspouts.', 'The public reported a waterspout south of Folly Beach.');
INSERT INTO public.stormevents_east VALUES (836021, 201807, 20, 745, 201807, 20, 746, 138988, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '20-JUL-18 07:45:00', 'EST-5', '20-JUL-18 07:46:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 11, 'ESE', 'TYBEE ISLAND', 11, 'ESE', 'TYBEE ISLAND', 31.95, -80.67, 31.95, -80.67, 'A weak wave of low pressure shifting over deep moisture along a stationary front led to numerous showers and thunderstorms capable of producing waterspouts.', 'The public reported two ongoing waterspouts east of Tybee Island from the Tybee Island Pier.');
INSERT INTO public.stormevents_east VALUES (757108, 201805, 10, 1432, 201805, 10, 1442, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 14:32:00', 'EST-5', '10-MAY-18 14:42:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 1.75, NULL, NULL, NULL, 1, 'E', 'MILL SPG', 0, 'W', 'BEULAH', 35.3, -82.16, 35.28, -82.127, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'EM reported quarter size hail in the Mill Spring area as multiple strong to severe storms trained over Polk County. Public reported quarter to golf ball size hail on Highway 74.');
INSERT INTO public.stormevents_east VALUES (757109, 201805, 10, 1500, 201805, 10, 1500, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 15:00:00', 'EST-5', '10-MAY-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 1, NULL, NULL, NULL, 2, 'WNW', 'RODDY STORE', 2, 'WNW', 'RODDY STORE', 35.28, -82.06, 35.28, -82.06, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Public reported quarter size hail as multiple strong to severe storms trained over Polk County.');
INSERT INTO public.stormevents_east VALUES (757110, 201805, 10, 1445, 201805, 10, 1445, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 14:45:00', 'EST-5', '10-MAY-18 14:45:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 0.75, NULL, NULL, NULL, 2, 'SSW', 'BEULAH', 2, 'SSW', 'BEULAH', 35.25, -82.13, 35.25, -82.13, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Former NWS employee reported penny size hail.');
INSERT INTO public.stormevents_east VALUES (757111, 201805, 10, 1505, 201805, 10, 1505, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 15:05:00', 'EST-5', '10-MAY-18 15:05:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 4, 'SW', 'BURKE CHAPEL', 4, 'SW', 'BURKE CHAPEL', 35.63, -81.52, 35.63, -81.52, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Public reported hail of at least quarter size.');
INSERT INTO public.stormevents_east VALUES (757112, 201805, 10, 1510, 201805, 10, 1510, 126265, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 15:10:00', 'EST-5', '10-MAY-18 15:10:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 6, 'WSW', 'PROPST XRDS', 6, 'WSW', 'PROPST XRDS', 35.61, -81.48, 35.61, -81.48, 'Isolated to scattered thunderstorms developed across the Blue Ridge during the afternoon and moved into the Piedmont during the evening. Some of the storms produced severe weather in the form of large hail and locally damaging winds. Strong to severe supercell thunderstorms developed repeatedly and trained across portions of the foothills, particularly in Polk County, such that some locations received multiple periods of up to golf ball size hail.', 'Spotter reported up to quarter size hail north of Cooksville.');
INSERT INTO public.stormevents_east VALUES (751451, 201805, 5, 1430, 201805, 5, 1430, 125277, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'RNK', '05-MAY-18 14:30:00', 'EST-5', '05-MAY-18 14:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 0, 'N', 'MONTCALM', 0, 'N', 'MONTCALM', 37.35, -81.25, 37.35, -81.25, 'A frontal boundary stalled across the area became the focus for isolated severe thunderstorms during the afternoon across southeast West Virginia.', NULL);
INSERT INTO public.stormevents_east VALUES (755120, 201805, 1, 0, 201805, 8, 1300, 125958, 'MAINE', 23, 2018, 'May', 'Flood', 'CAR', '01-MAY-18 00:00:00', 'EST-5', '08-MAY-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Snow Melt', NULL, 11, 'WNW', 'SKERRY', 1, 'NNE', 'FRENCHVILLE LOWER', 46.7209, -68.7085, 46.7005, -68.3401, 'An above average seasonal snowpack and cold start to April which delayed snow melt contributed to an above average late April snowpack. Rainfall from the last week of  April through the first week of May generally ranged from 2.00 to 3.00 inches. This rain...along with melting of the remaining snowpack which released significant amounts of water...contributed to flooding of lakes and rivers across northeastern Aroostook county. The Fish River at Fort Kent rose above flood stage during the evening of April 29th. The river then crested around a foot above flood stage...at moderate flood stage...from the 3rd into the 4th. The river crested at the second highest level ever on record. The river then slowly fell...dropping below flood stage during the evening of the 7th. Flooding along the Fish River led to the closure of roads and bridges. The flooding also impacted homes and camps (seasonal homes) along the river in the Soldier Pond area along with the Fish River chain of lakes. The Saint John River at Fort Kent crested slightly above flood stage early on the 1st. However...the river remained near flood stage fort several days thereafter. Flood impacts from the Saint John River at Fort Kent were mostly confined to areas along the immediate river including the temporary closure of River Road and the flooding of parks.|Rising lake levels began to cause problems late on April 29th into the 30th with waters starting to encroach on homes and camps located along the lakeshores. Lake levels continued to rise into early May eventually flooding basements and reaching the first floor of some homes. The lakes were still largely ice covered when water levels began to rise. The rising lakes and gusty winds eventually drove ice into some homes and camps. The pressure of the ice collapsed decks...damaged structures and forced some buildings off their foundation. Lake flood damage was reported on Portage Lake...Saint Froid Lake...Eagle Lake...Square Lake...Cross Lake and Long Lake. Some of the most significant impacts occurred  around Portage Lake where numerous homes and camps were damaged due to the flooding and ice. On Long Lake...the causeway leading to Pelletier Island was flooded and closed. An estimated 65 buildings...many of them seasonal homes...were impacted to varying degrees by the lake flooding and ice. Saturated ground along with runoff from rain and melting snow also contributed to a creep landslide on the River Road in Caribou which significantly damaged a portion of the road. This river and lake flooding was an event which began in late April and persisted into early May. Monetary damages with this event were included with the April summary. The included monetary damages represented damage to public infrastructure. A significant portion of that money was related to road damage due to the landslide. Monetary damage to private property with this event is unknown.', 'River and lake flooding occurred from late April into early May due to run-off from rain and melting of the remaining snowpack. The most significant impacts occurred along the Fish River and lakes across extreme northeast Aroostook county. Homes and structures were flooded and damaged to varying degrees. Lake ice also contributed to the damage...destroying decks and forcing some buildings off their foundation. Roads were flooded and closed with damage to some roads...culverts and bridges.');
INSERT INTO public.stormevents_east VALUES (759250, 201805, 4, 2050, 201805, 4, 2054, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:50:00', 'EST-5', '04-MAY-18 20:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NW', 'LYFORDS SIDING', 1, 'NW', 'LYFORDS SIDING', 43.89, -71.68, 43.89, -71.68, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires in Lyfords Siding.');
INSERT INTO public.stormevents_east VALUES (759251, 201805, 4, 2050, 201805, 4, 2055, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:50:00', 'EST-5', '04-MAY-18 20:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 0, 'N', 'BENNINGTON', 0, 'N', 'BENNINGTON', 43, -71.93, 43, -71.93, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees blocking South Bennington Road in Bennington.');
INSERT INTO public.stormevents_east VALUES (759254, 201805, 4, 2054, 201805, 4, 2058, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:54:00', 'EST-5', '04-MAY-18 20:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'NW', 'NEW BOSTON', 1, 'NW', 'NEW BOSTON', 42.98, -71.69, 42.98, -71.69, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees closing Route 77 in New Boston.');
INSERT INTO public.stormevents_east VALUES (759257, 201805, 4, 2100, 201805, 4, 2104, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 21:00:00', 'EST-5', '04-MAY-18 21:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'E', 'WEBSTER', 1, 'E', 'WEBSTER', 43.33, -71.72, 43.33, -71.72, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and utility poles closing Route 127 in Webster.');
INSERT INTO public.stormevents_east VALUES (759259, 201805, 4, 2104, 201805, 4, 2109, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 21:04:00', 'EST-5', '04-MAY-18 21:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'N', 'HOPKINTON', 1, 'N', 'HOPKINTON', 43.19, -71.68, 43.19, -71.68, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees on Cedar Street in Hopkinton.');
INSERT INTO public.stormevents_east VALUES (759260, 201805, 4, 2105, 201805, 4, 2109, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 21:05:00', 'EST-5', '04-MAY-18 21:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'S', 'CHOCORUA', 1, 'S', 'CHOCORUA', 43.86, -71.22, 43.86, -71.22, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees on wires closing Route 113 in Chocorua.');
INSERT INTO public.stormevents_east VALUES (751452, 201805, 5, 1628, 201805, 5, 1633, 125277, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'RNK', '05-MAY-18 16:28:00', 'EST-5', '05-MAY-18 16:33:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1.25, NULL, NULL, NULL, 1, 'SW', 'HILLDALE', 0, 'N', 'TALCOTT', 37.64, -80.79, 37.65, -80.75, 'A frontal boundary stalled across the area became the focus for isolated severe thunderstorms during the afternoon across southeast West Virginia.', 'Hail reports ranged as little as dime sized with majority of reports being in the quarter to half dollar size. Reports were relayed via a trained spotter, broadcast media, and the local fire department.');
INSERT INTO public.stormevents_east VALUES (751454, 201805, 5, 1938, 201805, 5, 1938, 125277, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'RNK', '05-MAY-18 19:38:00', 'EST-5', '05-MAY-18 19:38:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 4, 'NNE', 'WHITE SULPHUR SPGS', 4, 'NNE', 'WHITE SULPHUR SPGS', 37.8294, -80.2623, 37.8294, -80.2623, 'A frontal boundary stalled across the area became the focus for isolated severe thunderstorms during the afternoon across southeast West Virginia.', 'Thunderstorm winds knocked down some trees near Highway 92.');
INSERT INTO public.stormevents_east VALUES (752746, 201805, 10, 1220, 201805, 10, 1220, 125287, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'RNK', '10-MAY-18 12:20:00', 'EST-5', '10-MAY-18 12:20:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 4, 'NNW', 'WOODLAWN', 4, 'NNW', 'WOODLAWN', 36.77, -80.85, 36.77, -80.85, 'A cold front approaching from the west would prompt isolated convection in the mountains. As the front moved east of the Blue Ridge, storms intensified where higher instabilities existed, producing damaging winds and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (760056, 201805, 29, 2145, 201805, 30, 100, 126710, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '29-MAY-18 21:45:00', 'EST-5', '30-MAY-18 01:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'BUSICK', 2, 'SSW', 'HAMRICK', 35.794, -82.197, 35.797, -82.215, 'A very moist southeast flow developed northeast of subtropical cyclone Alberto, which made landfall across the western Florida Peninsula on the 28th and moved north across Alabama throughout the 29th. Resultant upslope flow into the southern Appalachians resulted in development of widespread heavy rain showers across western North Carolina throughout the 29th, with activity being most concentrated along the eastern escarpment of the Blue Ridge. By the time the showers tapered off during the 30th, total rainfall of 7-10 inches occurred along the Blue Ridge. This resulted in fairly widespread flash flooding followed by an extended period of high stream flow, with McDowell County being the hardest hit area.', 'Media and a stream gauge indicated the South Toe River and some of its tributaries overflowed and their banks and flooded roads in eastern Yancey County after 4 to 6 inches of rain fell in the headwaters throughout the 29th, with much of that falling during the evening hours. Multiple roads along the river flooded, including Hannah Branch Rd, Halls Chapel Rd, and Wyatt Town Rd. Backwater effects from the river also caused Colbert Creek to flood Colberts Creek Rd and Middle Creek to flood Rock Creek Rd.');
INSERT INTO public.stormevents_east VALUES (760067, 201805, 29, 1700, 201805, 29, 2130, 126710, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'GSP', '29-MAY-18 17:00:00', 'EST-5', '29-MAY-18 21:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'YADKIN VLY', 1, 'SSW', 'YADKIN VLY', 36.015, -81.502, 35.991, -81.525, 'A very moist southeast flow developed northeast of subtropical cyclone Alberto, which made landfall across the western Florida Peninsula on the 28th and moved north across Alabama throughout the 29th. Resultant upslope flow into the southern Appalachians resulted in development of widespread heavy rain showers across western North Carolina throughout the 29th, with activity being most concentrated along the eastern escarpment of the Blue Ridge. By the time the showers tapered off during the 30th, total rainfall of 7-10 inches occurred along the Blue Ridge. This resulted in fairly widespread flash flooding followed by an extended period of high stream flow, with McDowell County being the hardest hit area.', 'County comms and other sources reported flash flooding developed across central Caldwell County after 2 to 3 inches of rain fell in just a few hours. Zachs Fork Creek overflowed its banks in the city of Lenoir and flooded several yards. Highway 268 was flooded where Buffalo Creek flows into the Yadkin River. Blairs Fork Rd was flooded and closed due to Long Branch overflowing its banks in the Lenoir area. Indian Grave Rd was also flooded by a stream at Tuttle Rd.');
INSERT INTO public.stormevents_east VALUES (760721, 201805, 14, 1248, 201805, 14, 1248, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 12:48:00', 'EST-5', '14-MAY-18 12:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1.25, NULL, NULL, NULL, 1, 'W', 'TRIADELPHIA', 1, 'W', 'TRIADELPHIA', 40.05, -80.63, 40.05, -80.63, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', NULL);
INSERT INTO public.stormevents_east VALUES (760722, 201805, 14, 1334, 201805, 14, 1334, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 13:34:00', 'EST-5', '14-MAY-18 13:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'W', 'MILLSBORO', 1, 'W', 'MILLSBORO', 39.73, -80.69, 39.73, -80.69, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', NULL);
INSERT INTO public.stormevents_east VALUES (760725, 201805, 14, 1518, 201805, 14, 1518, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '14-MAY-18 15:18:00', 'EST-5', '14-MAY-18 15:18:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SW', 'HANNAHSVILLE', 1, 'SW', 'HANNAHSVILLE', 39.24, -79.71, 39.24, -79.71, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', 'The county Division of Highways office reported downed trees at Hannahsville.');
INSERT INTO public.stormevents_east VALUES (760726, 201805, 14, 1521, 201805, 14, 1521, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '14-MAY-18 15:21:00', 'EST-5', '14-MAY-18 15:21:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'ST GEORGE', 2, 'SW', 'ST GEORGE', 39.15, -79.72, 39.15, -79.72, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', 'County 911 officials reported multiple trees down on Route 38 south of Auvil.');
INSERT INTO public.stormevents_east VALUES (760724, 201805, 14, 1526, 201805, 14, 1526, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 15:26:00', 'EST-5', '14-MAY-18 15:26:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 1, NULL, NULL, NULL, 1, 'N', 'PORTERWOOD', 1, 'N', 'PORTERWOOD', 39.09, -79.68, 39.09, -79.68, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', NULL);
INSERT INTO public.stormevents_east VALUES (777999, 201809, 2, 1445, 201809, 2, 1445, 129852, 'FLORIDA', 12, 2018, 'September', 'Thunderstorm Wind', 'TAE', '02-SEP-18 14:45:00', 'EST-5', '02-SEP-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'N', 'SUWANNEE', 1, 'N', 'SUWANNEE', 29.33, -83.14, 29.33, -83.14, 'Scattered to numerous showers and thunderstorms occurred across the area. Some of the storms were marginally severe with impacts to trees and power lines.', 'Several trees were blown down near Suwannee.');
INSERT INTO public.stormevents_east VALUES (754545, 201805, 17, 610, 201805, 17, 612, 125827, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'CHS', '17-MAY-18 06:10:00', 'EST-5', '17-MAY-18 06:12:00', 0, 0, 0, 0, NULL, '0.00K', 'Buoy', 37, 'MG', NULL, NULL, 0, 'NE', 'EDISTO BUOY (41004)', 0, 'NE', 'EDISTO BUOY (41004)', 32.501, -79.099, 32.501, -79.099, 'A large cluster of thunderstorms moved across the South Carolina coastal waters in the early morning hours producing strong wind gusts.', 'Buoy 41004 measured a 37 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (754546, 201805, 17, 910, 201805, 17, 912, 125827, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'CHS', '17-MAY-18 09:10:00', 'EST-5', '17-MAY-18 09:12:00', 0, 0, 0, 0, NULL, '0.00K', 'Buoy', 37, 'MG', NULL, NULL, 0, 'NE', 'EDISTO BUOY (41004)', 0, 'NE', 'EDISTO BUOY (41004)', 32.501, -79.099, 32.501, -79.099, 'A large cluster of thunderstorms moved across the South Carolina coastal waters in the early morning hours producing strong wind gusts.', 'Buoy 41004 measured a 37 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (754548, 201805, 27, 2250, 201805, 27, 2252, 125828, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'CHS', '27-MAY-18 22:50:00', 'EST-5', '27-MAY-18 22:52:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'NE', 'SULLIVANS ISLAND', 1, 'NE', 'SULLIVANS ISLAND', 32.7666, -79.8194, 32.7666, -79.8194, 'Rounds of showers and thunderstorms pushed onshore along the South Carolina coast within the circulation associated with Subtropical Storm Alberto. A few of these thunderstorms produced strong wind gusts along the coast.', 'The Weatherflow site at Station 28.5 on Sullivan''s Island measured a 35 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (745407, 201805, 3, 1558, 201805, 3, 1558, 124218, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '03-MAY-18 15:58:00', 'EST-5', '03-MAY-18 15:58:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'N', 'MARSHALLTON', 1, 'N', 'MARSHALLTON', 40.79, -76.55, 40.79, -76.55, 'A cluster of convection developed during the afternoon of May 3, 2018, as a mid-level disturbance crossed the area. A storm within this cluster of convection produced wind damage in Northumberland County near Shamokin.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in Shamokin.');
INSERT INTO public.stormevents_east VALUES (756899, 201805, 7, 1840, 201805, 7, 1840, 126264, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '07-MAY-18 18:40:00', 'EST-5', '07-MAY-18 18:40:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.75, NULL, NULL, NULL, 2, 'NNW', 'ASHFORD', 2, 'NNW', 'ASHFORD', 35.91, -81.94, 35.91, -81.94, 'Isolated thunderstorms developed across the North Carolina Blue Ridge during the evening. A few of the storms produced brief hail.', 'Public reported (via Social Media) 3/4 inch hail along Highway 221.');
INSERT INTO public.stormevents_east VALUES (756901, 201805, 7, 2000, 201805, 7, 2000, 126264, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '07-MAY-18 20:00:00', 'EST-5', '07-MAY-18 20:00:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 0.88, NULL, NULL, NULL, 1, 'NW', 'HICKORY', 1, 'NW', 'HICKORY', 35.74, -81.33, 35.74, -81.33, 'Isolated thunderstorms developed across the North Carolina Blue Ridge during the evening. A few of the storms produced brief hail.', 'Ham radio operator reported nickel size hail.');
INSERT INTO public.stormevents_east VALUES (757124, 201805, 10, 1700, 201805, 10, 1700, 126309, 'SOUTH CAROLINA', 45, 2018, 'May', 'Hail', 'GSP', '10-MAY-18 17:00:00', 'EST-5', '10-MAY-18 17:00:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.75, NULL, NULL, NULL, 1, 'NW', 'POWDERSVILLE', 1, 'NW', 'POWDERSVILLE', 34.79, -82.49, 34.79, -82.49, 'Scattered to numerous storms developed across Upstate South Carolina during the late afternoon and evening, as multiple outflow boundaries from storms originating over the North Carolina Blue Ridge passed over the area. A couple of the storms produced brief hail and damaging winds.', 'Public reported (via Social Media) 3/4 inch hail in the Powdersville area.');
INSERT INTO public.stormevents_east VALUES (757126, 201805, 11, 1629, 201805, 11, 1629, 126310, 'NORTH CAROLINA', 37, 2018, 'May', 'Hail', 'GSP', '11-MAY-18 16:29:00', 'EST-5', '11-MAY-18 16:29:00', 0, 0, 0, 0, NULL, NULL, 'CoCoRaHS', 0.75, NULL, NULL, NULL, 2, 'ENE', 'CHARLES', 2, 'ENE', 'CHARLES', 35.93, -80.82, 35.93, -80.82, 'Isolated convection developed during the afternoon and evening across the North Carolina foothills and moved southeast. One storm produced hail across Iredell County.', 'Cocorahs observer reported 3/4 inch hail.');
INSERT INTO public.stormevents_east VALUES (757127, 201805, 31, 1404, 201805, 31, 1404, 126311, 'SOUTH CAROLINA', 45, 2018, 'May', 'Hail', 'GSP', '31-MAY-18 14:04:00', 'EST-5', '31-MAY-18 14:04:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'NW', 'SALEM', 1, 'NW', 'SALEM', 34.89, -82.98, 34.89, -82.98, 'Scattered thunderstorms developed across the mountains of South Carolina and Georgia during the early afternoon and moved east. A few of the storms produced hail and minor wind damage.', 'Spotter reported 3/4 inch hail in the Salem area.');
INSERT INTO public.stormevents_east VALUES (757128, 201805, 31, 1629, 201805, 31, 1640, 126311, 'SOUTH CAROLINA', 45, 2018, 'May', 'Thunderstorm Wind', 'GSP', '31-MAY-18 16:29:00', 'EST-5', '31-MAY-18 16:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'OAKWAY', 5, 'W', 'FAIR PLAY', 34.589, -83.07, 34.52, -83.07, 'Scattered thunderstorms developed across the mountains of South Carolina and Georgia during the early afternoon and moved east. A few of the storms produced hail and minor wind damage.', 'County comms reported trees blown down on Blackjack Rd, South Union Rd, and at Shelor Ferry Rd and North Port Bass Rd.');
INSERT INTO public.stormevents_east VALUES (757129, 201805, 31, 1541, 201805, 31, 1548, 126311, 'SOUTH CAROLINA', 45, 2018, 'May', 'Thunderstorm Wind', 'GSP', '31-MAY-18 15:41:00', 'EST-5', '31-MAY-18 15:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ENE', 'TRAVELERS REST', 1, 'ENE', 'TRAVELERS REST', 34.974, -82.417, 34.974, -82.417, 'Scattered thunderstorms developed across the mountains of South Carolina and Georgia during the early afternoon and moved east. A few of the storms produced hail and minor wind damage.', 'Law enforcement and the public reported multiple trees blown down from east of Travelers Rest to the Blue Ridge community.');
INSERT INTO public.stormevents_east VALUES (757130, 201805, 31, 1620, 201805, 31, 1631, 126311, 'SOUTH CAROLINA', 45, 2018, 'May', 'Thunderstorm Wind', 'GSP', '31-MAY-18 16:20:00', 'EST-5', '31-MAY-18 16:31:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'SAXON', 1, 'N', 'WOODBURN HILLS', 34.945, -81.98, 34.944, -81.881, 'Scattered thunderstorms developed across the mountains of South Carolina and Georgia during the early afternoon and moved east. A few of the storms produced hail and minor wind damage.', 'County comms reported a few trees blown down around Spartanburg.');
INSERT INTO public.stormevents_east VALUES (749308, 201805, 31, 1311, 201805, 31, 1311, 124924, 'NORTH CAROLINA', 37, 2018, 'May', 'Flood', 'MHX', '31-MAY-18 13:11:00', 'EST-5', '31-MAY-18 13:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'HALF MOON', 1, 'S', 'HALF MOON', 34.83, -77.45, 34.8202, -77.4496, 'Heavy rain indirectly associated with Subtropical Storm Alberto fell across parts of Eastern NC during the afternoon.', 'Road flooding was reported with water 4 to 5 inches deep. An estimated 3 to 4 inches of rain fell.');
INSERT INTO public.stormevents_east VALUES (761540, 201805, 5, 1542, 201805, 5, 1542, 127082, 'GULF OF MEXICO', 85, 2018, 'May', 'Waterspout', 'KEY', '05-MAY-18 15:42:00', 'EST-5', '05-MAY-18 15:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'N', 'KEY WEST', 1, 'N', 'KEY WEST', 24.5672, -81.7799, 24.5672, -81.7799, 'Two waterspouts formed in succession and in association with a cloud line along the north side of Key West.  The second waterspout formed within a bight and damaged vessels at dock, without ever reaching shore.', 'A waterspout was reported offshore Garrison Bight Key West and relayed via social media.');
INSERT INTO public.stormevents_east VALUES (761541, 201805, 5, 1620, 201805, 5, 1620, 127082, 'GULF OF MEXICO', 85, 2018, 'May', 'Waterspout', 'KEY', '05-MAY-18 16:20:00', 'EST-5', '05-MAY-18 16:20:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 0, 'WNW', 'KEY WEST', 1, 'WNW', 'KEY WEST', 24.5625, -81.7857, 24.5629, -81.7889, 'Two waterspouts formed in succession and in association with a cloud line along the north side of Key West.  The second waterspout formed within a bight and damaged vessels at dock, without ever reaching shore.', 'A waterspout was observed to develop within Garrison Bight outside of the Palm Drive Bridge, and drifted slowly west, reaching a dock at a sailing center.  3 catamarans were considerably damaged due to overturning while tied to the dock, causing the dock planking to twist and detach from the pilings.  3 other vessels at the same dock had minor damage with ripped covers and canopy tops.  A video relayed by social media showed the width of the spray ring was only a few yards across, with the spray ring dissipating before the waterspout reached shore.  No damage was observed onshore at the sailing center nor an adjacent marina.');
INSERT INTO public.stormevents_east VALUES (761544, 201805, 8, 730, 201805, 8, 730, 127084, 'GULF OF MEXICO', 85, 2018, 'May', 'Waterspout', 'KEY', '08-MAY-18 07:30:00', 'EST-5', '08-MAY-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Coast Guard', NULL, NULL, NULL, NULL, 4, 'NNE', 'MARATHON', 4, 'NNE', 'MARATHON', 24.77, -81.07, 24.77, -81.07, 'In spite of lacking deep moisture, ideal wind conditions allowed for the development of mature cloud lines throughout the Lower, Middle and Upper Florida Keys.  Numerous waterspouts developed primarily in the nearshore Florida Bay and Gulf of Mexico waters.', 'A waterspout was reported by a member of the USCG Auxiliary about 4 miles north of Marathon.  The waterspout was extremely tilted from the vertical.');
INSERT INTO public.stormevents_east VALUES (776147, 201807, 27, 1510, 201807, 27, 1510, 129542, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '27-JUL-18 15:10:00', 'EST-5', '27-JUL-18 15:10:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SSW', 'FREMONT', 1, 'SSW', 'FREMONT', 41.81, -75.06, 41.81, -75.06, 'A cold front moved across New York State on the 27th. This front triggered a round of severe thunderstorms.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776148, 201807, 27, 1521, 201807, 27, 1521, 129542, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '27-JUL-18 15:21:00', 'EST-5', '27-JUL-18 15:21:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SSW', 'FREMONT', 1, 'SSW', 'FREMONT', 41.81, -75.06, 41.81, -75.06, 'A cold front moved across New York State on the 27th. This front triggered a round of severe thunderstorms.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776149, 201807, 27, 1622, 201807, 27, 1622, 129542, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '27-JUL-18 16:22:00', 'EST-5', '27-JUL-18 16:22:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 3, 'ESE', 'BARRYVILLE', 3, 'ESE', 'BARRYVILLE', 41.46, -74.88, 41.46, -74.88, 'A cold front moved across New York State on the 27th. This front triggered a round of severe thunderstorms.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776150, 201807, 27, 1908, 201807, 27, 1908, 129542, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '27-JUL-18 19:08:00', 'EST-5', '27-JUL-18 19:08:00', 0, 0, 0, 0, '25.00K', '0.00K', 'NWS Storm Survey', 70, 'EG', NULL, NULL, 1, 'NW', 'BOUCKVILLE', 1, 'NW', 'BOUCKVILLE', 42.89, -75.55, 42.89, -75.55, 'A cold front moved across New York State on the 27th. This front triggered a round of severe thunderstorms.', 'A microburst resulted in downed trees and wires on  Falin and Canal roads near Route 26. Winds also led to roof damage at a residence on Canal road.');
INSERT INTO public.stormevents_east VALUES (776151, 201807, 27, 1930, 201807, 27, 1930, 129542, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '27-JUL-18 19:30:00', 'EST-5', '27-JUL-18 19:30:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'WATERVILLE', 0, 'N', 'WATERVILLE', 42.93, -75.38, 42.93, -75.38, 'A cold front moved across New York State on the 27th. This front triggered a round of severe thunderstorms.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776152, 201807, 27, 1934, 201807, 27, 1934, 129542, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '27-JUL-18 19:34:00', 'EST-5', '27-JUL-18 19:34:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'CASSVILLE', 2, 'NE', 'CASSVILLE', 42.95, -75.25, 42.95, -75.25, 'A cold front moved across New York State on the 27th. This front triggered a round of severe thunderstorms.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (776145, 201807, 26, 2221, 201807, 26, 2221, 129543, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BGM', '26-JUL-18 22:21:00', 'EST-5', '26-JUL-18 22:21:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'TABERG', 0, 'N', 'TABERG', 43.3, -75.62, 43.3, -75.62, 'A few severe thunderstorms moved into north central New York during the late evening of the 26th.', 'Strong thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (745502, 201805, 13, 1721, 201805, 13, 1721, 124094, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '13-MAY-18 17:21:00', 'EST-5', '13-MAY-18 17:21:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 1, 'SSW', 'BURNING BUSH', 1, 'SSW', 'BURNING BUSH', 39.913, -78.5859, 39.913, -78.5859, 'Scattered showers and thunderstorms developed south of a stalled frontal boundary that was draped from NW to SE across southwestern Pennsylvania. A small line of storms formed over the Pittsburgh area and pushed SE across Somerset and Bedford County.  These storms produced considerable wind damage along the Route 30 corridor in Somerset County, but the wind damage quickly diminished as the storm continued eastward into slightly more stable air east of the Allegheny Front in Bedford County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree and blocked Teaberry Road near the intersection with Buck Falls Road.');
INSERT INTO public.stormevents_east VALUES (744780, 201805, 4, 1810, 201805, 4, 1810, 124117, 'VERMONT', 50, 2018, 'May', 'Hail', 'BTV', '04-MAY-18 18:10:00', 'EST-5', '04-MAY-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 0, 'N', 'SHELBURNE', 0, 'N', 'SHELBURNE', 44.38, -73.23, 44.38, -73.23, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Estimated dollar size hail or larger reported.');
INSERT INTO public.stormevents_east VALUES (744794, 201805, 4, 1806, 201805, 4, 1806, 124117, 'VERMONT', 50, 2018, 'May', 'Thunderstorm Wind', 'BTV', '04-MAY-18 18:06:00', 'EST-5', '04-MAY-18 18:06:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Utility Company', 55, 'EG', NULL, NULL, 0, 'N', 'WESTFORD', 0, 'N', 'WESTFORD', 44.62, -73.02, 44.62, -73.02, 'An energetic storm system moved from the Great Lakes across the St. Lawrence Valley into Ontario/Quebec during the afternoon and evening hours of May 4th. Instability was marginal for thunderstorm development during the evening hours with thunderstorms ahead of a cold front. However, winds were unseasonably strong in the atmosphere, accounting for some thunderstorms to produce damaging winds and there was some localized damage in non-thunderstorm winds accompanying the arrival of colder air.||Very brief heavy rainfall of up to 2 inches in less than an hour accounted for localized flash flooding and a mudslide. Strong winds and a lake level at/above flood stage caused for 4 to 6 foot waves to batter a causeway between Colchester and Grand Isle on Lake Champlain, resulting in numerous washouts and a closure of the causeway.', 'Trees and utility lines down.');
INSERT INTO public.stormevents_east VALUES (745606, 201805, 15, 1520, 201805, 15, 1520, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 15:20:00', 'EST-5', '15-MAY-18 15:20:00', 0, 0, 0, 0, '20.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'SE', 'LUCKNOW', 0, 'SE', 'LUCKNOW', 40.3173, -76.8965, 40.3173, -76.8965, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto homes on Green Street.');
INSERT INTO public.stormevents_east VALUES (745608, 201805, 15, 1538, 201805, 15, 1538, 124155, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '15-MAY-18 15:38:00', 'EST-5', '15-MAY-18 15:38:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 2, 'ENE', 'PINE GLEN', 2, 'ENE', 'PINE GLEN', 40.0424, -77.2632, 40.0424, -77.2632, 'A line of severe thunderstorms developed ahead of an approaching cold front during the afternoon of May 15, 2018.  This line progresses southeastward across central Pennsylvania, producing widespread wind damage and isolated large hail.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires along Pine Grove Road.');
