INSERT INTO public.stormevents_east VALUES (752757, 201805, 10, 1248, 201805, 10, 1248, 125287, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'RNK', '10-MAY-18 12:48:00', 'EST-5', '10-MAY-18 12:48:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 0.75, NULL, NULL, NULL, 0, 'N', 'BUCHANAN', 0, 'N', 'BUCHANAN', 37.52, -79.68, 37.52, -79.68, 'A cold front approaching from the west would prompt isolated convection in the mountains. As the front moved east of the Blue Ridge, storms intensified where higher instabilities existed, producing damaging winds and large hail.', NULL);
