INSERT INTO public.stormevents_east VALUES (775098, 201808, 12, 1410, 201808, 12, 1410, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 14:10:00', 'EST-5', '12-AUG-18 14:10:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'WSW', 'SANGERVILLE', 1, 'WSW', 'SANGERVILLE', 38.37, -79.1, 38.37, -79.1, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'A tree was blown down in the 500 block of Emmanuel Church Road.');
INSERT INTO public.stormevents_east VALUES (775100, 201808, 13, 1703, 201808, 13, 1703, 129356, 'MARYLAND', 24, 2018, 'August', 'Hail', 'LWX', '13-AUG-18 17:03:00', 'EST-5', '13-AUG-18 17:03:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'N', 'PERRY HALL', 0, 'N', 'PERRY HALL', 39.42, -76.47, 39.42, -76.47, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Quarter sized hail fell at this location.');
