INSERT INTO public.stormevents_east VALUES (775102, 201808, 13, 1607, 201808, 13, 1607, 129356, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '13-AUG-18 16:07:00', 'EST-5', '13-AUG-18 16:07:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'BRANCHVILLE', 0, 'N', 'BRANCHVILLE', 39, -76.93, 39, -76.93, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Numerous trees were blown down in the College Park area. The worst of the damage was concentrated near the intersection of Rhode Island Avenue and MD Route 193.');
INSERT INTO public.stormevents_east VALUES (778145, 201808, 11, 2118, 201808, 11, 2118, 129892, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '11-AUG-18 21:18:00', 'EST-5', '11-AUG-18 21:18:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 6, 'S', 'MID BAY BUOY', 6, 'S', 'MID BAY BUOY', 38.385, -76.372, 38.385, -76.372, 'A weak boundary was positioned overhead while an upper-level trough moved into the area. Showers and thunderstorms developed and some produced strong winds over the waters.', 'A wind gust of up to 34 knots was measured.');
