INSERT INTO public.stormevents_east VALUES (778152, 201808, 12, 1900, 201808, 12, 1901, 129893, 'ATLANTIC NORTH', 88, 2018, 'August', 'Waterspout', 'LWX', '12-AUG-18 19:00:00', 'EST-5', '12-AUG-18 19:01:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', NULL, NULL, NULL, NULL, 15, 'ESE', 'POINT LOOKOUT (PTL)', 15, 'ESE', 'POINT LOOKOUT (PTL)', 37.9738, -76.0505, 37.9742, -76.0493, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms produced strong winds over the waters.', 'A waterspout was observed over the waters near Rhodes Point on Smith Island, MD. No damage was reported.');
INSERT INTO public.stormevents_east VALUES (778153, 201808, 13, 1543, 201808, 13, 1543, 129894, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '13-AUG-18 15:43:00', 'EST-5', '13-AUG-18 15:43:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 44, 'MG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms produced strong winds over the waters.', 'A wind gust of 44 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778154, 201808, 13, 1700, 201808, 13, 1703, 129894, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '13-AUG-18 17:00:00', 'EST-5', '13-AUG-18 17:03:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 43, 'MG', NULL, NULL, 0, 'N', 'HAMPSTEAD HILL ACADEMY (BLMHH)', 0, 'N', 'HAMPSTEAD HILL ACADEMY (BLMHH)', 39.29, -76.58, 39.29, -76.58, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms produced strong winds over the waters.', 'A wind gust of 43 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778155, 201808, 13, 1703, 201808, 13, 1703, 129894, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '13-AUG-18 17:03:00', 'EST-5', '13-AUG-18 17:03:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'ORIOLE PARK AT CAMDEN YARDS (BLTPC)', 0, 'N', 'ORIOLE PARK AT CAMDEN YARDS (BLTPC)', 39.28, -76.62, 39.28, -76.62, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms produced strong winds over the waters.', 'A wind gust of 35 knots was measured.');
INSERT INTO public.stormevents_east VALUES (782320, 201808, 29, 1857, 201808, 29, 1857, 130608, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BGM', '29-AUG-18 18:57:00', 'EST-5', '29-AUG-18 18:57:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'PAINTED POST', 1, 'SE', 'PAINTED POST', 42.16, -77.09, 42.16, -77.09, 'A line of strong to severe thunderstorms moved across central New York during the evening hours ahead of a strong cold front.', 'Thunderstorm winds blew down trees and wires.');
INSERT INTO public.stormevents_east VALUES (782322, 201808, 13, 1256, 201808, 13, 1600, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 12:56:00', 'EST-5', '13-AUG-18 16:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'TROY', 1, 'E', 'TROY', 41.7742, -76.7862, 41.7825, -76.7811, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Significant flash flooding was occurring around Troy Borough.');
INSERT INTO public.stormevents_east VALUES (782819, 201808, 28, 1958, 201808, 28, 2000, 130821, 'MICHIGAN', 26, 2018, 'August', 'Tornado', 'APX', '28-AUG-18 19:58:00', 'EST-5', '28-AUG-18 20:00:00', 0, 0, 0, 0, '45.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 4, 'NNE', 'STERLING', 4, 'SW', 'MAPLE RIDGE', 44.0793, -83.9773, 44.0801, -83.9691, 'Another line of thunderstorms crossed northern Michigan in the evening of the 28th. This line produced considerable wind damage, along with a handful of tornadoes.', 'A tornado with estimated maximum winds of 85 mph briefly touched down along the Rifle River, about 4 miles northeast of Sterling. A number of hardwood and softwood trees were knocked over or snapped, damaging a few structures in the process.');
INSERT INTO public.stormevents_east VALUES (781072, 201809, 9, 2008, 201809, 9, 2330, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '09-SEP-18 20:08:00', 'EST-5', '09-SEP-18 23:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CENTERPOINT', 4, 'WSW', 'ALICE', 38.839, -82.439, 39.0009, -82.4306, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'Multiple roads were closed due to flooding, including State Routes 325, 554, and 850.');
INSERT INTO public.stormevents_east VALUES (787887, 201809, 16, 730, 201809, 16, 2000, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 07:30:00', 'EST-5', '16-SEP-18 20:00:00', 0, 0, 1, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'OLIVE BRANCH', 1, 'SSW', 'BRIEF', 35.146, -80.324, 35.169, -80.555, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'EM reported severe flash flooding developed across Union County after 7 to 13 inches of rain fell across the county in about 24 hours. Dozens of roads were closed at the height of the event during the afternoon of the 16th, some due to poor drainage flooding in urban areas, and others due to small stream flooding, including Goose Creek in the Indian Trail area, where a stream gauge exceeded its established flood stage. Multiple water rescues were necessary, and some homes were isolated by flood waters. A one-year-old boy drowned when his parent drove a vehicle around a barricade and into a swollen creek on Highway 218.');
INSERT INTO public.stormevents_east VALUES (787855, 201809, 16, 1730, 201809, 17, 30, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'GSP', '16-SEP-18 17:30:00', 'EST-5', '17-SEP-18 00:30:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'ROCKWELL', 1, 'WSW', 'LIBERTY', 35.56, -80.43, 35.576, -80.362, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'After 4 to 6 inches of rain fell throughout the 16th, county comms reported numerous roads flooded and multiple roads closed due to flooding, especially across western sections of Rowan County, including Salisbury and vicinity.');
INSERT INTO public.stormevents_east VALUES (787939, 201809, 11, 1432, 201809, 11, 1437, 131714, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'KEY', '11-SEP-18 14:32:00', 'EST-5', '11-SEP-18 14:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 5, 'W', 'KEY WEST', 5, 'W', 'KEY WEST', 24.5674, -81.8526, 24.5674, -81.8526, 'An isolated waterspout was observed southwest of Key West in association with widely separated showers moving west-southwest along the Florida Straits.', 'A waterspout was observed about 5 miles west of Wisteria Island.  A clear spray ring was visible.');
INSERT INTO public.stormevents_east VALUES (776634, 201809, 26, 453, 201809, 26, 457, 129617, 'OHIO', 39, 2018, 'September', 'Tornado', 'ILN', '26-SEP-18 04:53:00', 'EST-5', '26-SEP-18 04:57:00', 0, 0, 0, 0, '750.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WNW', 'HANFORD', 1, 'E', 'BEXLEY', 39.9564, -82.9702, 39.9712, -82.9025, 'Showers and thunderstorms moved east across the region ahead of a fast moving cold front.', 'Damage evident of a weak tornado began in the Olde Towne neighborhood of Columbus. There were numerous large tree branches down or tree trunks snapped, along with a pickup truck that was briefly partially lifted off the ground. The pickup truck suffered damage to both passenger side tires as it was forced back down to the pavement. In the same area of Olde Towne, there was damage to power poles. Damage in this area was consistent with an EF0 strength tornado. Further down the damage path, several areas of tree damage occurred in the Bexley area. ||The most significant tornado damage occurred in the Mayfair neighborhood near East Broad Street and South James Road, and where the wind speeds are estimated to be the highest. Several homes in this neighborhood sustained roof, siding and shingle damage. There were numerous large trees uprooted or snapped, causing significant damage to homes, garages and vehicles. Additionally, 2 cinder block garages had their roofs completely lifted off, with 1 or 2 block walls completely collapsed. It was this damage that was consistent with wind speeds of about 90 mph. Damage in this neighborhood was consistent with low end EF1 tornado winds.||There was no evidence nor reports of damage further to the northeast of this area, so from here it appears the tornado lifted and dissipated.');
INSERT INTO public.stormevents_east VALUES (784711, 201809, 25, 1740, 201809, 25, 2008, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:40:00', 'EST-5', '25-SEP-18 20:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'MIDDLETOWN', 1, 'W', 'PORTLAND', 41.5553, -72.6428, 41.5675, -72.6522, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'All lanes were closed on Route 9 southbound between Exit 16 and Exit 1 in Middletown due to flooding.');
INSERT INTO public.stormevents_east VALUES (784713, 201809, 25, 1740, 201809, 25, 1930, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:40:00', 'EST-5', '25-SEP-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'AUGERVILLE', 2, 'WSW', 'AUGERVILLE', 41.362, -72.9425, 41.3626, -72.9425, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'The intersection of Clover Circle and Lane Street was impassable due to flooding in Hamden.');
INSERT INTO public.stormevents_east VALUES (784714, 201809, 25, 1800, 201809, 25, 1930, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 18:00:00', 'EST-5', '25-SEP-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'AUGERVILLE', 1, 'WSW', 'AUGERVILLE', 41.3636, -72.9224, 41.364, -72.9239, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Dixwell Avenue near the Wilbur Cross Parkway was closed due to flooding in Spring Glen. Several cars were stranded with flood waters up to the rooftops.');
INSERT INTO public.stormevents_east VALUES (782321, 201808, 29, 1906, 201808, 29, 1906, 130608, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BGM', '29-AUG-18 19:06:00', 'EST-5', '29-AUG-18 19:06:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'BIG FLATS', 1, 'N', 'BIG FLATS', 42.14, -76.93, 42.14, -76.93, 'A line of strong to severe thunderstorms moved across central New York during the evening hours ahead of a strong cold front.', 'Thunderstorm winds blew down utility poles and wires.');
INSERT INTO public.stormevents_east VALUES (778018, 201809, 8, 100, 201809, 8, 200, 129880, 'WEST VIRGINIA', 54, 2018, 'September', 'Flash Flood', 'RNK', '08-SEP-18 01:00:00', 'EST-5', '08-SEP-18 02:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'MAXWELTON', 2, 'S', 'MAXWELTON', 37.84, -80.42, 37.8459, -80.4183, 'A slowly approaching frontal boundary late on the 7th triggered more widespread shower and thunderstorms in the late afternoon into the nighttime hours. Storms over Greenbrier County during the early morning hours of the 8th produced radar estimated rainfall of 1.5 to 3 inches in a few hours with some flash flooding reported near Lewisburg as water entered a home. For the 24 hours ending at 12z, Keeney Knob IFLOWS (KEEW2) measured 2.68��� (of which 1.85��� fell in 1 hour ending 05z) and Lewisburg COOP (LWBW2) 2.00���.', 'Runoff from heavy rainfall caused water to enter at least one home and wash away the all the gravel at a construction site.');
INSERT INTO public.stormevents_east VALUES (785974, 201809, 14, 903, 201809, 14, 904, 131357, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'AKQ', '14-SEP-18 09:03:00', 'EST-5', '14-SEP-18 09:04:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 3, 'NE', 'SAN SOUCI', 4, 'NE', 'SAN SOUCI', 35.96, -76.75, 35.967, -76.7555, 'Isolated severe thunderstorm near a stationary boundary produced a weak tornado across portions of northeast North Carolina.', 'Public sited a tornado and tree damage was reported off Winston Farm Road off of Route 45.');
INSERT INTO public.stormevents_east VALUES (751172, 201805, 4, 1921, 201805, 4, 1921, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:21:00', 'EST-5', '04-MAY-18 19:21:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 1, 'W', 'NORTH EASTON', 1, 'W', 'NORTH EASTON', 43.02, -73.56, 43.02, -73.56, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Several large pine trees uprooted and snapped.');
INSERT INTO public.stormevents_east VALUES (751174, 201805, 4, 1923, 201805, 4, 1923, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:23:00', 'EST-5', '04-MAY-18 19:23:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'SCHAGHTICOKE', 1, 'W', 'SCHAGHTICOKE', 42.9, -73.59, 42.9, -73.59, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (775387, 201807, 3, 1240, 201807, 3, 1240, 129369, 'NEW JERSEY', 34, 2018, 'July', 'Thunderstorm Wind', 'OKX', '03-JUL-18 12:40:00', 'EST-5', '03-JUL-18 12:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'W', 'NORTH ARLINGTON', 0, 'W', 'NORTH ARLINGTON', 40.7798, -74.1318, 40.7798, -74.1318, 'A pre-frontal trough ahead of an approaching cold front triggered strong to severe thunderstorms across the region.', 'A tree down on car on Exton Avenue between Devon Street and Elm Street.');
INSERT INTO public.stormevents_east VALUES (786852, 201809, 25, 2033, 201809, 26, 100, 131526, 'CONNECTICUT', 9, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 20:33:00', 'EST-5', '26-SEP-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WINDHAM', 2, 'ESE', 'WINDHAM', 41.6838, -72.1549, 41.6869, -72.1364, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Connecticut with 3 to 6 inches observed over Northeast Connecticut and 1 to 3 inches in Hartford County.', 'At 8:33 PM EST, Indian Hollow Road in Windham was reported flooded and impassable with debris in the road.');
INSERT INTO public.stormevents_east VALUES (786872, 201809, 25, 2225, 201809, 26, 200, 131527, 'RHODE ISLAND', 44, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 22:25:00', 'EST-5', '26-SEP-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'OAK LAWN', 0, 'S', 'OAK LAWN', 41.7462, -71.4804, 41.7466, -71.48, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Rhode Island with 3 to 5 inches observed in Providence County and Kent County. Amounts of 1 to 3 inches fell on Southern Rhode Island.', 'At 10:30 PM EST, the intersection of Wilbur Avenue at Oaklawn Avenue in Cranston was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (786854, 201809, 25, 2302, 201809, 26, 300, 131527, 'RHODE ISLAND', 44, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 23:02:00', 'EST-5', '26-SEP-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'OLNEYVILLE', 1, 'WNW', 'OLNEYVILLE', 41.8217, -71.4406, 41.8216, -71.4399, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Rhode Island with 3 to 5 inches observed in Providence County and Kent County. Amounts of 1 to 3 inches fell on Southern Rhode Island.', 'At 11:02 PM EST, Valley Street at Helme Street in Providence was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (786855, 201809, 26, 54, 201809, 26, 400, 131527, 'RHODE ISLAND', 44, 2018, 'September', 'Flood', 'BOX', '26-SEP-18 00:54:00', 'EST-5', '26-SEP-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'CENTRAL FALLS', 1, 'NW', 'CENTRAL FALLS', 41.8845, -71.4092, 41.8852, -71.4097, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Rhode Island with 3 to 5 inches observed in Providence County and Kent County. Amounts of 1 to 3 inches fell on Southern Rhode Island.', 'At 12:54 AM EST, Higginson Avenue in Lincoln near the Wood and Wire Fence Company was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (786857, 201809, 26, 120, 201809, 26, 500, 131527, 'RHODE ISLAND', 44, 2018, 'September', 'Flood', 'BOX', '26-SEP-18 01:20:00', 'EST-5', '26-SEP-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'OLNEYVILLE', 1, 'SSW', 'OLNEYVILLE', 41.8171, -71.4297, 41.8094, -71.4359, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Rhode Island with 3 to 5 inches observed in Providence County and Kent County. Amounts of 1 to 3 inches fell on Southern Rhode Island.', 'At 1:20 AM EST, Westminster Street, Union Avenue, and part of State Route 10 in Providence were all flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (786858, 201809, 26, 2330, 201809, 26, 2330, 131527, 'RHODE ISLAND', 44, 2018, 'September', 'Lightning', 'BOX', '26-SEP-18 23:30:00', 'EST-5', '26-SEP-18 23:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 2, 'WNW', 'MILLVILLE', 2, 'WNW', 'MILLVILLE', 41.5764, -71.7092, 41.5764, -71.7092, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Rhode Island with 3 to 5 inches observed in Providence County and Kent County. Amounts of 1 to 3 inches fell on Southern Rhode Island.', 'At 11:30 PM EST on Sept 26, wires were reported down due to a lightning strike on Ten Rod Road (State Route 165) and Summit Road in Exeter.');
INSERT INTO public.stormevents_east VALUES (753457, 201804, 16, 325, 201804, 16, 325, 125033, 'ATLANTIC NORTH', 88, 2018, 'April', 'Marine Thunderstorm Wind', 'AKQ', '16-APR-18 03:25:00', 'EST-5', '16-APR-18 03:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 2, 'SSW', 'CAPE HENRY STATION (CHYV2)', 2, 'SSW', 'CAPE HENRY STATION (CHYV2)', 36.91, -76.08, 36.91, -76.08, 'Scattered thunderstorms in advance of low pressure and its associated cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 36 knots was measured at Lynnhaven Pier.');
INSERT INTO public.stormevents_east VALUES (759446, 201805, 14, 354, 201805, 14, 354, 126702, 'MARYLAND', 24, 2018, 'May', 'Heavy Rain', 'AKQ', '14-MAY-18 03:54:00', 'EST-5', '14-MAY-18 03:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 1, 'NE', '(SBY)WICOMICO CO ARP', 1, 'NE', '(SBY)WICOMICO CO ARP', 38.34, -75.51, 38.34, -75.51, 'Scattered thunderstorms along a frontal boundary produced heavy rain across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 1.76 inches was measured at SBY.');
INSERT INTO public.stormevents_east VALUES (785611, 201809, 7, 800, 201809, 10, 800, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'SE', 'DAVIS', 0, 'SE', 'DAVIS', 39.13, -79.47, 39.13, -79.47, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A COOP observer recorded a 72 hour storm total of 2.67 inches of rain.');
INSERT INTO public.stormevents_east VALUES (785612, 201809, 7, 730, 201809, 10, 730, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:30:00', 'EST-5', '10-SEP-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 38, 'S', 'BETHANY', 38, 'S', 'BETHANY', 39.6633, -80.4293, 39.6633, -80.4293, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A COOP Observer recorded 5.66 inches of rain in 72 hours.');
INSERT INTO public.stormevents_east VALUES (782907, 201808, 18, 1630, 201808, 18, 1645, 130832, 'ATLANTIC NORTH', 88, 2018, 'August', 'Waterspout', 'BOX', '18-AUG-18 16:30:00', 'EST-5', '18-AUG-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 12, 'N', 'WOODS HOLE', 13, 'N', 'WOODS HOLE', 41.7009, -70.6461, 41.7203, -70.6244, 'A cold front moved across the coastal waters during the afternoon and evening of August 18th. One thunderstorm generated a waterspout near Cape Cod.', 'Waterspout moved through Hog Island Channel, passing west of Monument Beach and east of Mashnee Road.');
INSERT INTO public.stormevents_east VALUES (785487, 201809, 10, 500, 201809, 10, 500, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '10-SEP-18 05:00:00', 'EST-5', '10-SEP-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'E', 'MINGO JCT', 1, 'E', 'MINGO JCT', 40.32, -80.61, 40.32, -80.61, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A trained spotter reported 6.10 inches of rain in a 48 hour period ( Sunday 9/9 TO Monday 9/10).');
INSERT INTO public.stormevents_east VALUES (785489, 201809, 9, 1257, 201809, 9, 1257, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '09-SEP-18 12:57:00', 'EST-5', '09-SEP-18 12:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'E', 'PLEASANT CITY', 1, 'E', 'PLEASANT CITY', 39.9, -81.54, 39.9, -81.54, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A storm total of 3.64 inches was recorded by a local citizen.');
INSERT INTO public.stormevents_east VALUES (785583, 201809, 10, 233, 201809, 10, 400, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '10-SEP-18 02:33:00', 'EST-5', '10-SEP-18 04:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'NEW BRIGHTON', 1, 'SSW', 'BEAVER FALLS', 40.74, -80.32, 40.7432, -80.3355, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported that 100 Block of Ross Hill Rd in Beaver Falls is closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (785584, 201809, 10, 239, 201809, 10, 400, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '10-SEP-18 02:39:00', 'EST-5', '10-SEP-18 04:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'NEW GALILEE', 2, 'NW', 'DARLINGTON', 40.84, -80.42, 40.8397, -80.4392, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported that a portion of Madden Run Rd is closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (776462, 201807, 4, 845, 201807, 4, 1045, 129623, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'BUF', '04-JUL-18 08:45:00', 'EST-5', '04-JUL-18 10:45:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'HINSDALE', 2, 'NNE', 'WESTONS MILLS', 42.1422, -78.4218, 42.102, -78.3576, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Flooding along Union Valley Road and Windfall Road in Olean. A bridge also washed out on Union Valley Road.');
INSERT INTO public.stormevents_east VALUES (776550, 201807, 4, 700, 201807, 4, 700, 129623, 'NEW YORK', 36, 2018, 'July', 'Lightning', 'BUF', '04-JUL-18 07:00:00', 'EST-5', '04-JUL-18 07:00:00', 1, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'S', 'BELMONT', 1, 'S', 'BELMONT', 42.22, -78.03, 42.22, -78.03, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'A male was struck by lightning along Route 244 near Amity.');
INSERT INTO public.stormevents_east VALUES (776464, 201807, 4, 1615, 201807, 4, 1615, 129623, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'BUF', '04-JUL-18 16:15:00', 'EST-5', '04-JUL-18 16:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'N', 'KABOB', 1, 'N', 'KABOB', 42.3, -79.32, 42.3, -79.32, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Several trees down around Stockton, including on Rocky Glen Road.');
INSERT INTO public.stormevents_east VALUES (776553, 201807, 4, 930, 201807, 4, 930, 129623, 'NEW YORK', 36, 2018, 'July', 'Heavy Rain', 'BUF', '04-JUL-18 09:30:00', 'EST-5', '04-JUL-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NW', 'PORTVILLE', 1, 'NW', 'PORTVILLE', 42.04, -78.34, 42.04, -78.34, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Very heavy rain fell between 7 and 10 AM.');
INSERT INTO public.stormevents_east VALUES (785629, 201809, 7, 600, 201809, 10, 600, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 06:00:00', 'EST-5', '10-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'CONNELLSVILLE', 0, 'N', 'CONNELLSVILLE', 40.02, -79.58, 40.02, -79.58, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A COOP Observer recorded 5.53 inches of rain in 72 hours.');
INSERT INTO public.stormevents_east VALUES (785630, 201809, 7, 430, 201809, 10, 430, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 04:30:00', 'EST-5', '10-SEP-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 5, 'W', 'MARIENVILLE', 5, 'W', 'MARIENVILLE', 41.45, -79.1766, 41.45, -79.1766, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A CoCoRaHS observer recorded 2.79 inches of rain in a 72 hour period.');
INSERT INTO public.stormevents_east VALUES (772465, 201807, 4, 2010, 201807, 4, 2230, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '04-JUL-18 20:10:00', 'EST-5', '04-JUL-18 22:30:00', 0, 0, 0, 0, '10.00K', '1.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'SANDY CREEK', 0, 'NNE', 'SANDY CREEK', 40.48, -79.86, 40.4816, -79.8486, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'The 911 Call Center reported that vehicles were stuck in flooded roadway at Allegheny River Blvd and Sandy Creek Road.');
INSERT INTO public.stormevents_east VALUES (772467, 201807, 4, 1909, 201807, 4, 1909, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '04-JUL-18 19:09:00', 'EST-5', '04-JUL-18 19:09:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'SE', 'MILLTOWN', 1, 'SE', 'MILLTOWN', 40.49, -79.79, 40.49, -79.79, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'The 911 Call Center reported a large tree fell on a vehicle along Hulton Rd in Unity. There was also a tree blocking a roadway at Repp Rd and Milltown Road.');
INSERT INTO public.stormevents_east VALUES (772470, 201807, 4, 1939, 201807, 4, 2010, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '04-JUL-18 19:39:00', 'EST-5', '04-JUL-18 20:10:00', 0, 0, 0, 0, '1.00K', '0.50K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ARNOLA', 1, 'WSW', 'BAGDAD', 40.59, -79.75, 40.6452, -79.6494, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'The 911 Call Center reported that 2300 Block of Freeport Road was flooded. Also the intersection of Route 356 and Leechburg Road.');
INSERT INTO public.stormevents_east VALUES (773784, 201807, 5, 1340, 201807, 5, 1540, 129093, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'PBZ', '05-JUL-18 13:40:00', 'EST-5', '05-JUL-18 15:40:00', 0, 0, 0, 0, '0.50K', '0.50K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'AVILTON', 3, 'SE', 'AVILTON', 39.63, -79.03, 39.6239, -79.0153, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'The 911 Call Center reported Avilton Lonaconing Road at Lancaster Hill Road is flooded.');
INSERT INTO public.stormevents_east VALUES (772504, 201807, 5, 815, 201807, 5, 1000, 128797, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '05-JUL-18 08:15:00', 'EST-5', '05-JUL-18 10:00:00', 0, 0, 0, 0, '500.00K', '5.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'BERKLEY HILLS', 0, 'ESE', 'CHERRY CITY', 40.51, -79.99, 40.4785, -79.9652, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'The 911 Call Center reported that a Port Authority bus with passengers was taking on water and disable at Thompson Run Road. Swift water team dispatched at Thompson and Evergeen Road. Spring Garden Ave flooded at Wilson Road in Northview Heights; vehicle stranded. Residence were flooded at 11 Sedgwick Street. Six people were stranded on the 2nd floor.');
INSERT INTO public.stormevents_east VALUES (800747, 201812, 16, 1033, 201812, 18, 245, 133708, 'WEST VIRGINIA', 54, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 10:33:00', 'EST-5', '18-DEC-18 02:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'ESE', 'BEDINGTON', 3, 'SSE', 'MARLOWE', 39.5002, -77.8543, 39.5392, -77.8399, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Potomac River at Shepherdstown exceeded the 15 foot flood stage during the indicated period. River Road was completely flooded in low spots between Shepherdstown and Harpers Ferry. Water covered the pedestrian bridge to the Shepherdstown boat ramp and significant portions of the C&O canal were flooded. Water approached homes on the West Virginia side of the river near Shepherdstown and impacts to roads and structures were also observed on the Maryland side of the river. The peak level of 22.11 feet occurred at 3:00 AM on December 17th.');
INSERT INTO public.stormevents_east VALUES (800750, 201812, 16, 430, 201812, 16, 2010, 133708, 'WEST VIRGINIA', 54, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 04:30:00', 'EST-5', '16-DEC-18 20:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'MILLESON', 2, 'NNW', 'POINTS', 39.4657, -78.6443, 39.4589, -78.6344, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The stream gage on the South Branch Potomac River at Springfield exceeded the 15 foot flood stage during the indicated period. Flooding was observed along Mileson Mill Road (County Route 28/5) and Clarence Taylor Road (Route 3/7). A significant portion of the meadowlands near the river, as well as the boat launch ramp were also flooded. The peak level of 16.25 feet occurred at 10:30 AM on December 16th.');
INSERT INTO public.stormevents_east VALUES (807237, 201812, 15, 1030, 201812, 15, 1515, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 10:30:00', 'EST-5', '15-DEC-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'VIENNA', 2, 'N', 'VIENNA', 38.9246, -77.2636, 38.9249, -77.2651, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Old Courthouse Road closed near intersection with Besley Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (775389, 201807, 3, 1259, 201807, 3, 1259, 129369, 'NEW JERSEY', 34, 2018, 'July', 'Thunderstorm Wind', 'OKX', '03-JUL-18 12:59:00', 'EST-5', '03-JUL-18 12:59:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 1, 'SE', 'GARWOOD', 1, 'SE', 'GARWOOD', 40.6414, -74.3093, 40.6414, -74.3093, 'A pre-frontal trough ahead of an approaching cold front triggered strong to severe thunderstorms across the region.', 'A downed tree on Carolina Street.');
INSERT INTO public.stormevents_east VALUES (787290, 201809, 27, 2215, 201809, 28, 415, 131621, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '27-SEP-18 22:15:00', 'EST-5', '28-SEP-18 04:15:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MILLBORO', 1, 'NNW', 'MILLBORO', 37.989, -79.6, 37.9786, -79.607, 'A slow-moving frontal boundary crossed the mountains and produced 1 to 2.5 inches of rain with the heaviest falling in the 24-hours ending at 12z (700 AM local) on the 28th. 24-hour rain totals were highest across the upper James and Greenbrier river basins. The James River rose above flood stage in the upper reaches and pockets of flooding were reported on smaller streams in these basins.', 'A resident reported a driveway washed out in Millboro with creek nearby running very high.');
INSERT INTO public.stormevents_east VALUES (787292, 201809, 27, 2228, 201809, 28, 428, 131621, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '27-SEP-18 22:28:00', 'EST-5', '28-SEP-18 04:28:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'CLIFTON FORGE CITY', 2, 'WSW', 'CLIFTON FORGE CITY', 37.82, -79.83, 37.8152, -79.8289, 'A slow-moving frontal boundary crossed the mountains and produced 1 to 2.5 inches of rain with the heaviest falling in the 24-hours ending at 12z (700 AM local) on the 28th. 24-hour rain totals were highest across the upper James and Greenbrier river basins. The James River rose above flood stage in the upper reaches and pockets of flooding were reported on smaller streams in these basins.', 'Minor street flooding was reported in Clifton Forge.');
INSERT INTO public.stormevents_east VALUES (787291, 201809, 27, 2122, 201809, 28, 322, 131621, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '27-SEP-18 21:22:00', 'EST-5', '28-SEP-18 03:22:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BACOVA JCT', 0, 'ESE', 'BACOVA JCT', 38.02, -79.87, 38.019, -79.865, 'A slow-moving frontal boundary crossed the mountains and produced 1 to 2.5 inches of rain with the heaviest falling in the 24-hours ending at 12z (700 AM local) on the 28th. 24-hour rain totals were highest across the upper James and Greenbrier river basins. The James River rose above flood stage in the upper reaches and pockets of flooding were reported on smaller streams in these basins.', 'The Jackson River Turnpike was flooded and the road closed by VDOT.');
INSERT INTO public.stormevents_east VALUES (751167, 201805, 4, 1910, 201805, 4, 1910, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:10:00', 'EST-5', '04-MAY-18 19:10:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 50, 'EG', NULL, NULL, 1, 'S', 'SNAKE HILL', 1, 'S', 'SNAKE HILL', 42.9849, -73.7529, 42.9849, -73.7529, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Route 9P was closed between Plains Road and Lake Road due to downed poles and wires.');
INSERT INTO public.stormevents_east VALUES (787584, 201809, 17, 800, 201809, 17, 1400, 130244, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'RNK', '17-SEP-18 08:00:00', 'EST-5', '17-SEP-18 14:00:00', 0, 0, 0, 0, '131.82K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'PULASKI', 2, 'ENE', 'MC ADAM', 37.05, -80.8, 37.0445, -80.6935, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'Pulaski County was included in the Presidential Major Disaster declaration with significant damage to roads and other structures. The time and spatial occurrence was based on the highest runoff from the CREST hydrologic model.');
INSERT INTO public.stormevents_east VALUES (787604, 201809, 17, 745, 201809, 18, 445, 130244, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '17-SEP-18 07:45:00', 'EST-5', '18-SEP-18 04:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'W', 'ALLISONIA', 1, 'S', 'HIWASSEE', 36.935, -80.7932, 36.9553, -80.7169, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'The New River at Allisonia (ALSV2) rose very rapidly and crested in the Moderate flood category at 11.52 feet (60900 cfs) mid-afternoon of the 17th. It was the highest stage since the January 31, 2013 flood (12.91 ft.) and was approximately a 5-year flood event (.20 annual chance event) per USGS studies. Several roads close to the river were flooded and closed including Clarks Ferry Road and Julia Simpkins Road.');
INSERT INTO public.stormevents_east VALUES (763449, 201807, 22, 1245, 201807, 22, 1245, 127194, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '22-JUL-18 12:45:00', 'EST-5', '22-JUL-18 12:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 37, 'MG', NULL, NULL, 2, 'SSE', 'PONCE INLET', 2, 'SSE', 'PONCE INLET', 29.076, -80.913, 29.076, -80.913, 'A large mid-to-upper-level low pressure system centered over Ohio was expanding southward across the southeastern United States. As this occurred, a series of strong disturbances aloft traveled across the Florida peninsula. Environmental conditions supported numerous strong thunderstorms due to favorable vertical lift, wind shear and a very moist atmosphere. Scattered to numerous showers and thunderstorms developed during the afternoon and evening across northeast Florida. Over time these storms merged into a strong to severe Mesoscale Convective System (MCS) that moved south across east central Florida. Other storms also developed along the local sea breezes, and residual outflow boundaries. As the MCS moved across the intracoastal and nearshore waters of east central Florida, numerous strong wind events occurred from Volusia County south to St. Lucie County. This episode continued into the early morning hours of Monday (July 23) as a second, weaker MCS moved across the area from north to south, bringing strong winds to the Brevard County coast.', 'The AWOS at the New Smyrna Beach Airport (KEVB) measured a peak wind gust of 37 knots from the north.');
INSERT INTO public.stormevents_east VALUES (782262, 201808, 21, 1806, 201808, 21, 1806, 130730, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '21-AUG-18 18:06:00', 'EST-5', '21-AUG-18 18:06:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Park/Forest Service', 52, 'EG', NULL, NULL, 1, 'SSE', 'QUAKER BRIDGE', 1, 'SSE', 'QUAKER BRIDGE', 42.05, -78.87, 42.05, -78.87, 'A pre-frontal trough moved through with ample wind shear while in a marginal risk during the afternoon. This touched off several lines of convection. One storm of interest with notable rotation moved through Allegany State Park. A few more storms developed during the afternoon and evening hours that didn''t last as long nor look as impressive on radar.', 'Trees were reported down at the Quaker entrance of Allegany State Park.');
INSERT INTO public.stormevents_east VALUES (781508, 201808, 6, 1436, 201808, 6, 1436, 130550, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '06-AUG-18 14:36:00', 'EST-5', '06-AUG-18 14:36:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'SW', 'PALMYRA', 1, 'SW', 'PALMYRA', 43.06, -77.25, 43.06, -77.25, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', 'Multiple reports of trees down were received from Palmyra and Macedon.');
INSERT INTO public.stormevents_east VALUES (781513, 201808, 6, 1441, 201808, 6, 1441, 130550, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '06-AUG-18 14:41:00', 'EST-5', '06-AUG-18 14:41:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 1, 'NE', 'ONTARIO', 1, 'NE', 'ONTARIO', 43.23, -77.27, 43.23, -77.27, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', 'A tree was reported down on a trailer home at 2275 Route 104.');
INSERT INTO public.stormevents_east VALUES (781514, 201808, 6, 1544, 201808, 6, 1544, 130550, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '06-AUG-18 15:44:00', 'EST-5', '06-AUG-18 15:44:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'ESE', 'MEXICO', 2, 'ESE', 'MEXICO', 43.46, -76.2, 43.46, -76.2, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', 'Tree and wires were reported down on Smithers Rd.');
INSERT INTO public.stormevents_east VALUES (772787, 201808, 1, 0, 201808, 1, 700, 128861, 'NORTH CAROLINA', 37, 2018, 'August', 'Heavy Rain', 'RNK', '01-AUG-18 00:00:00', 'EST-5', '01-AUG-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 6, 'E', 'YADKINVILLE', 6, 'E', 'YADKINVILLE', 36.13, -80.5625, 36.13, -80.5625, 'Heavy rain fell across parts of Yadkin and Wilkes counties during the late afternoon and evening of July 31st.', 'The Yadkinville 6 E COOP station (YKNN7) measured 2.93 for the 24-hours ending at 700 AM EDT on August 1st, the highest recorded on this date at this site since records began there in 1940 (with a break in data from 1952-1957).');
INSERT INTO public.stormevents_east VALUES (775243, 201808, 2, 1652, 201808, 2, 1852, 129383, 'DISTRICT OF COLUMBIA', 11, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 16:52:00', 'EST-5', '02-AUG-18 18:52:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'BENNING', 1, 'NE', 'BENNING', 38.8904, -76.9378, 38.8904, -76.938, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding.', 'The 4500 Block of Benning road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (775265, 201808, 18, 135, 201808, 18, 135, 129359, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '18-AUG-18 01:35:00', 'EST-5', '18-AUG-18 01:35:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 2, 'NE', 'CARDEROCK SPGS', 2, 'NE', 'CARDEROCK SPGS', 39.02, -77.15, 39.02, -77.15, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'Trees were blown down along the I-270 spur south of Democracy Boulevard.');
INSERT INTO public.stormevents_east VALUES (775266, 201808, 21, 1406, 201808, 21, 1406, 129384, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '21-AUG-18 14:06:00', 'EST-5', '21-AUG-18 14:06:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'MT SAVAGE', 1, 'S', 'MT SAVAGE', 39.69, -78.88, 39.69, -78.88, 'A warm front lifted northward through the day across the area, while a cold front approached from the west. These boundaries interacted with a moist and unstable air mass and moderate wind shear to generate strong to locally severe thunderstorms.', 'A tree was blown down in the 15000 block of Mount Savage Road.');
INSERT INTO public.stormevents_east VALUES (775267, 201808, 21, 1425, 201808, 21, 1425, 129384, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '21-AUG-18 14:25:00', 'EST-5', '21-AUG-18 14:25:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NNW', 'NORTH BRANCH', 1, 'NNW', 'NORTH BRANCH', 39.6, -78.74, 39.6, -78.74, 'A warm front lifted northward through the day across the area, while a cold front approached from the west. These boundaries interacted with a moist and unstable air mass and moderate wind shear to generate strong to locally severe thunderstorms.', 'A five inch in diameter branch was broken off a tree by the wind.');
INSERT INTO public.stormevents_east VALUES (775268, 201808, 21, 1512, 201808, 21, 1512, 129384, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '21-AUG-18 15:12:00', 'EST-5', '21-AUG-18 15:12:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'ESE', 'LAUREL GROVE', 2, 'ESE', 'LAUREL GROVE', 38.4087, -76.6509, 38.4087, -76.6509, 'A warm front lifted northward through the day across the area, while a cold front approached from the west. These boundaries interacted with a moist and unstable air mass and moderate wind shear to generate strong to locally severe thunderstorms.', 'A tree was blown down on Queentree Road near Jesse Drive.');
INSERT INTO public.stormevents_east VALUES (775103, 201808, 13, 1626, 201808, 13, 1626, 129356, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '13-AUG-18 16:26:00', 'EST-5', '13-AUG-18 16:26:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'OAKLAND MILLS', 1, 'S', 'OAKLAND MILLS', 39.2, -76.85, 39.2, -76.85, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'A tree was blown down on Setting Star Road near Sandchain Road.');
INSERT INTO public.stormevents_east VALUES (775422, 201808, 3, 2107, 201808, 3, 2307, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 21:07:00', 'EST-5', '03-AUG-18 23:07:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'STANDARDSVILLE', 2, 'NNW', 'STANDARDSVILLE', 38.333, -78.4472, 38.3326, -78.4465, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Octonia Road was closed near South River Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (775423, 201808, 3, 2139, 201808, 3, 2339, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 21:39:00', 'EST-5', '03-AUG-18 23:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'OAKPARK', 1, 'NNE', 'ACHSAH', 38.35, -78.16, 38.3477, -78.158, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-635 Mount Zion Church Road was closed due to flooding at Beaverdam Run.');
INSERT INTO public.stormevents_east VALUES (775424, 201808, 3, 2139, 201808, 3, 2339, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 21:39:00', 'EST-5', '03-AUG-18 23:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'OAKPARK', 1, 'ENE', 'OAKPARK', 38.38, -78.15, 38.379, -78.1465, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-618 Fords Shop Road closed due to flooding near VA-632 Beahm Town Road.');
INSERT INTO public.stormevents_east VALUES (775425, 201808, 3, 2139, 201808, 3, 2339, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 21:39:00', 'EST-5', '03-AUG-18 23:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'OAKPARK', 1, 'NNW', 'OAKPARK', 38.38, -78.18, 38.385, -78.1814, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-607 Lillards Ford Road was closed due to flooding between VA-634 Oak Park Road and VA-629 Spring Branch Road.');
INSERT INTO public.stormevents_east VALUES (775554, 201808, 3, 2147, 201808, 3, 2347, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 21:47:00', 'EST-5', '03-AUG-18 23:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'LINCOLN', 1, 'SW', 'LINCOLN', 39.11, -77.69, 39.1092, -77.6915, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-723 Foundry Road was closed due to flooding near VA-726 Taylor Road.');
INSERT INTO public.stormevents_east VALUES (782486, 201809, 11, 1407, 201809, 12, 135, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '11-SEP-18 14:07:00', 'EST-5', '12-SEP-18 01:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'YANKEEBURG', 2, 'E', 'YANKEEBURG', 39.3822, -81.3364, 39.3659, -81.3097, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'The river gage on the Ohio River at Willow Island Lock indicated the river rose above its 37 foot flood stage mid afternoon on the 11th. The river crested in minor flood, around 37.2 feet that evening and returned below flood stage shortly after midnight. This flooded sections of Ohio State Route 7, along with Township Roads 19 and 443.');
INSERT INTO public.stormevents_east VALUES (776232, 201809, 9, 1435, 201809, 9, 1630, 129568, 'WEST VIRGINIA', 54, 2018, 'September', 'Flash Flood', 'RLX', '09-SEP-18 14:35:00', 'EST-5', '09-SEP-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'YATES CROSSING', 3, 'ENE', 'MALCOM SPGS HGTS', 38.4484, -82.177, 38.4723, -82.101, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in western West Virginia.', 'Two roads were closed due to flooding near Milton. This included the 1600 block of John''s Creek Road along Johns Branch, and 1700 block of Newman''s Branch Road, along Mill Creek and Lower Creek.');
INSERT INTO public.stormevents_east VALUES (782482, 201809, 11, 300, 201809, 12, 1724, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '11-SEP-18 03:00:00', 'EST-5', '12-SEP-18 17:24:00', 0, 0, 0, 0, '3.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'PORTLAND', 2, 'SSW', 'TUPPERS PLAINS', 38.9851, -81.7974, 39.1442, -81.8594, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'The river gage on the Ohio River at Belleville Lock showed the river rose above its 35 foot flood stage early on the 11th. The river crested in minor flood at around 36.5 feet just after midnight on the 12th before returning to its banks late that afternoon. This caused closures along Ohio State Route 124 in multiple places.');
INSERT INTO public.stormevents_east VALUES (782485, 201809, 11, 1222, 201809, 12, 339, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '11-SEP-18 12:22:00', 'EST-5', '12-SEP-18 03:39:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'PINE HURST', 0, 'SSW', 'WEST MARRIETTA', 39.3915, -81.4805, 39.4195, -81.4803, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'The river gage on the Ohio River at Marietta showed the river rose above is 35 foot flood stage around noon on the 11th. The river crested in minor flood around 35.3 feet late that evening before returning below flood stage shortly after midnight on the 12th. This flooded several roads in Marietta, including Stark Street at 7th Street, Pike Street at Wayne, and Elmwood Avenue and Greene Street near Don Drumm Field.');
INSERT INTO public.stormevents_east VALUES (781087, 201809, 10, 700, 201809, 10, 2300, 129568, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'RLX', '10-SEP-18 07:00:00', 'EST-5', '10-SEP-18 23:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'EVERETT', 1, 'ENE', 'ADONIS', 39.4718, -81.0254, 39.5053, -80.9696, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in western West Virginia.', 'Middle Island Creek at Little rose above its 14 foot flood stage on the morning of the 10th. The creek crested in moderate flooding that afternoon at almost 17 feet before returning to its banks late that night. This flooded low areas on both sides of the creek.');
INSERT INTO public.stormevents_east VALUES (781079, 201809, 10, 500, 201809, 10, 2200, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '10-SEP-18 05:00:00', 'EST-5', '10-SEP-18 22:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BLOOMFIELD', 1, 'NW', 'SITKA', 39.5731, -81.219, 39.458, -81.358, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'The Little Muskingum River at Bloomfield rose above its 16 foot flood stage early on the 10th. It crested at 18.5 feet, or minor flooding, that evening and returned to its banks by midnight. This flooded Route 26 near its intersection with Route 260.');
INSERT INTO public.stormevents_east VALUES (783303, 201809, 7, 600, 201809, 8, 600, 129880, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'RNK', '07-SEP-18 06:00:00', 'EST-5', '08-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 3, 'N', 'LEWISBURG', 3, 'N', 'LEWISBURG', 37.8434, -80.45, 37.8434, -80.45, 'A slowly approaching frontal boundary late on the 7th triggered more widespread shower and thunderstorms in the late afternoon into the nighttime hours. Storms over Greenbrier County during the early morning hours of the 8th produced radar estimated rainfall of 1.5 to 3 inches in a few hours with some flash flooding reported near Lewisburg as water entered a home. For the 24 hours ending at 12z, Keeney Knob IFLOWS (KEEW2) measured 2.68��� (of which 1.85��� fell in 1 hour ending 05z) and Lewisburg COOP (LWBW2) 2.00���.', 'The COOP station at Lewisburg 3 N (LWBW2) had 2.00 inches in the 24-hour period ending at 700 AM local time on September 8th which is the highest ever on this date. The old record was 1.90 inches in 1969. Nearly continuous climate records at this station date back to 1900.');
INSERT INTO public.stormevents_east VALUES (783624, 201809, 6, 1332, 201809, 6, 1332, 130986, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'ALY', '06-SEP-18 13:32:00', 'EST-5', '06-SEP-18 13:32:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 50, 'EG', NULL, NULL, 1, 'S', 'LEE', 1, 'S', 'LEE', 42.3079, -73.2508, 42.3079, -73.2508, 'A cold front crossed western Massachusetts on the 6th, bringing and end to a four-day heat wave. This front sparked a broken line of thunderstorms during the afternoon as it interacted with the hot and humid airmass. Some of these storms became severe, resulting in scattered reports of wind damage. Around 1400 customers lost power in due to the storms, and a few schools delayed closing until the storms passed.', 'A large tree was snapped onto power lines in the driveway of a residence.');
INSERT INTO public.stormevents_east VALUES (783630, 201809, 6, 1420, 201809, 6, 1420, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 14:20:00', 'EST-5', '06-SEP-18 14:20:00', 0, 0, 0, 0, '7.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'WSW', 'GILBERTVILLE', 0, 'WSW', 'GILBERTVILLE', 42.3181, -72.2048, 42.3181, -72.2048, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 2:20 PM EST, a tree and wires came down on a truck on Hardwick Road at Mechanic Street.');
INSERT INTO public.stormevents_east VALUES (784716, 201809, 25, 1815, 201809, 25, 1845, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 18:15:00', 'EST-5', '25-SEP-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'SPORT HILL', 1, 'N', 'BRIDGEPORT', 41.2257, -73.2441, 41.1887, -73.2195, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Fifteen water rescues for people trapped in their vehicles were performed by the fire department in Bridgeport.');
INSERT INTO public.stormevents_east VALUES (784718, 201809, 25, 1815, 201809, 25, 1815, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 18:15:00', 'EST-5', '25-SEP-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'HIGHWOOD', 1, 'NW', 'HIGHWOOD', 41.3387, -72.9415, 41.3375, -72.9417, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Morse Street in Hamden was closed due to flooding with one car stranded in flood waters.');
INSERT INTO public.stormevents_east VALUES (784719, 201809, 25, 1830, 201809, 25, 1930, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 18:30:00', 'EST-5', '25-SEP-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNW', 'MERIDEN MARKHAM ARPT', 4, 'NE', 'MERIDEN', 41.565, -72.8465, 41.5782, -72.748, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Road closures were reported around the town of Meriden due to flooding.');
INSERT INTO public.stormevents_east VALUES (785443, 201809, 6, 1430, 201809, 6, 1630, 131283, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '06-SEP-18 14:30:00', 'EST-5', '06-SEP-18 16:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'GABBY HGTS', 1, 'NNW', 'GABBY HGTS', 40.16, -80.27, 40.1581, -80.2759, 'Showers and thunderstorms developed with the passage of a cold front. There was sufficient moisture, modest instability, and weak wind shear. Forecasted soundings predicted 0-3km lapse rates at an excess of 8.5 C/km. Mid-level dry air helped create an environment for strong downdrafts/damaging winds.', 'Local media reported street and lot flooding along Chartiers Creek near Route 40/Interstate 70 intersection. Stagnant Water in photos appears to be around 1 foot deep.');
INSERT INTO public.stormevents_east VALUES (785445, 201809, 6, 1535, 201809, 6, 1535, 131283, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'PBZ', '06-SEP-18 15:35:00', 'EST-5', '06-SEP-18 15:35:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'DEER LICK', 1, 'W', 'DEER LICK', 39.98, -80.32, 39.98, -80.32, 'Showers and thunderstorms developed with the passage of a cold front. There was sufficient moisture, modest instability, and weak wind shear. Forecasted soundings predicted 0-3km lapse rates at an excess of 8.5 C/km. Mid-level dry air helped create an environment for strong downdrafts/damaging winds.', 'The local public reported widespread tree branches and power-lines from a down-burst.');
INSERT INTO public.stormevents_east VALUES (751173, 201805, 4, 1920, 201805, 4, 1920, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:20:00', 'EST-5', '04-MAY-18 19:20:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 1, 'NE', 'ARGYLE', 1, 'NE', 'ARGYLE', 43.24, -73.49, 43.24, -73.49, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'In the town of Argyle, multiple trees were downed, a roof was partially torn off, and a barn was damaged.');
INSERT INTO public.stormevents_east VALUES (756333, 201805, 15, 1534, 201805, 15, 1534, 125464, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '15-MAY-18 15:34:00', 'EST-5', '15-MAY-18 15:34:00', 0, 0, 0, 0, NULL, NULL, 'Public', 75, 'EG', NULL, NULL, 0, 'N', 'HOLMES', 0, 'N', 'HOLMES', 41.52, -73.65, 41.52, -73.65, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', 'Several large pine trees were snapped two feet above the ground.');
INSERT INTO public.stormevents_east VALUES (756420, 201805, 15, 1441, 201805, 15, 1441, 126186, 'CONNECTICUT', 9, 2018, 'May', 'Hail', 'ALY', '15-MAY-18 14:41:00', 'EST-5', '15-MAY-18 14:41:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 2, NULL, NULL, NULL, 1, 'E', 'FALLS VLG', 1, 'E', 'FALLS VLG', 41.95, -73.36, 41.95, -73.36, 'Severe thunderstorms impacted portions of Litchfield County during the afternoon of May 15th. A supercell thunderstorm crossed northern portions of the county, resulting in hail up to two inches in diameter, two confirmed tornadoes, and straight-line wind damage. Later in the afternoon, a severe thunderstorm resulted in wind damage across far southern portions of the county. Numerous power outages and several road closures occurred as a result of the storms.', NULL);
INSERT INTO public.stormevents_east VALUES (785490, 201809, 9, 1347, 201809, 9, 1347, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '09-SEP-18 13:47:00', 'EST-5', '09-SEP-18 13:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NW', 'CARROLLTON', 1, 'NW', 'CARROLLTON', 40.58, -81.09, 40.58, -81.09, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A storm total of 2.35 inches was reported by a trained spotter.');
INSERT INTO public.stormevents_east VALUES (785492, 201809, 9, 939, 201809, 9, 939, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '09-SEP-18 09:39:00', 'EST-5', '09-SEP-18 09:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'E', 'GAYSPORT', 1, 'E', 'GAYSPORT', 39.8, -81.89, 39.8, -81.89, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A trained spotter reported a storm total of 2.24 inches.');
INSERT INTO public.stormevents_east VALUES (785500, 201809, 9, 924, 201809, 9, 924, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '09-SEP-18 09:24:00', 'EST-5', '09-SEP-18 09:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 0, 'N', 'ST CLAIRSVILLE', 0, 'N', 'ST CLAIRSVILLE', 40.08, -80.9, 40.08, -80.9, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A trained spotter reported a storm total of 2.24 inches.');
INSERT INTO public.stormevents_east VALUES (785613, 201809, 7, 800, 201809, 10, 800, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'ESE', 'CHILI', 2, 'ESE', 'CHILI', 40.3589, -81.7349, 40.3589, -81.7349, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A CoCoRaHS observer recorded a 72 hour storm total of 3.68 inches.');
INSERT INTO public.stormevents_east VALUES (763927, 201807, 5, 1744, 201807, 5, 1744, 127437, 'KENTUCKY', 21, 2018, 'July', 'Thunderstorm Wind', 'LMK', '05-JUL-18 17:44:00', 'EST-5', '05-JUL-18 17:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 53, 'EG', NULL, NULL, 1, 'E', 'GOFFS CORNER', 1, 'E', 'GOFFS CORNER', 37.93, -83.98, 37.93, -83.98, 'A cold front dropped southward into Illinois and Indiana. It triggered convection during the mid afternoon. Storms dropped into southern Indiana and north central Kentucky by the late afternoon and evening. High percipitable water values of 2 were waiting ahead of the front near the Ohio River. DCAPE values of around 1,000 J/kg also sat over the area providing conditions for heavy rain and severe thunderstorm winds.', 'Trees were down along Mountain Parkway on the Clark County side.');
INSERT INTO public.stormevents_east VALUES (785585, 201809, 10, 304, 201809, 10, 404, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '10-SEP-18 03:04:00', 'EST-5', '10-SEP-18 04:04:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'FOMBELL', 1, 'S', 'FOMBELL', 40.81, -80.2, 40.7925, -80.1998, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported several roads are closed due to flooding in Franklin Township.');
INSERT INTO public.stormevents_east VALUES (800392, 201812, 16, 1941, 201812, 17, 1126, 133708, 'WEST VIRGINIA', 54, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 19:41:00', 'EST-5', '17-DEC-18 11:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'BOLIVAR', 1, 'E', 'BOLIVAR', 39.3218, -77.7411, 39.3202, -77.7376, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Potomac River at Harpers Ferry exceeded the 18 foot flood stage during the indicated period. The C&O Canal towpath on the Maryland side of the river experienced flooding. Floodwaters also covered much of the Hamilton Street area, as well as the employee parking lot in historic Harpers Ferry. The peak level of 18.81 feet occurred at 2:30 AM on December 17th.');
INSERT INTO public.stormevents_east VALUES (776395, 201807, 22, 2348, 201807, 22, 2350, 129608, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'ILM', '22-JUL-18 23:48:00', 'EST-5', '22-JUL-18 23:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 45, 'MG', NULL, NULL, 2, 'W', 'HARRIS REEF', 2, 'W', 'HARRIS REEF', 34.2143, -77.7886, 34.2143, -77.7886, 'A stationary frontal boundary produce strong storms that moved offshore.', 'A 52 mph gust was recorded at the Johnny Mercer Pier.');
INSERT INTO public.stormevents_east VALUES (785631, 201809, 7, 800, 201809, 10, 800, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 1, 'ESE', 'GRAYSVILLE', 1, 'ESE', 'GRAYSVILLE', 39.9245, -80.3826, 39.9245, -80.3826, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'The US Army Corps recorded 5.53 inches of rain in a 72 hr period.');
INSERT INTO public.stormevents_east VALUES (785632, 201809, 7, 700, 201809, 10, 700, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:00:00', 'EST-5', '10-SEP-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 4, 'NNE', 'WORTHVILLE', 4, 'NNE', 'WORTHVILLE', 41.0835, -79.1206, 41.0835, -79.1206, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A CoCoRaHS observer recorded 3.77 inches of rain in a 72 hr period.');
INSERT INTO public.stormevents_east VALUES (783644, 201809, 6, 1533, 201809, 6, 1533, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 15:33:00', 'EST-5', '06-SEP-18 15:33:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'S', 'WETHERSFIELD', 0, 'S', 'WETHERSFIELD', 42.0955, -71.4693, 42.0955, -71.4693, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 3:33 PM EST, wind brought a tree down on High Street in Bellingham, blocking the road.');
INSERT INTO public.stormevents_east VALUES (772505, 201807, 5, 600, 201807, 5, 748, 128797, 'PENNSYLVANIA', 42, 2018, 'July', 'Heavy Rain', 'PBZ', '05-JUL-18 06:00:00', 'EST-5', '05-JUL-18 07:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NE', 'HIGHCLIFF', 1, 'NE', 'HIGHCLIFF', 40.53, -80.02, 40.53, -80.02, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'Trained spotter received 1.80 inches of rain in 2 hours.');
INSERT INTO public.stormevents_east VALUES (772513, 201807, 5, 620, 201807, 5, 1052, 128797, 'PENNSYLVANIA', 42, 2018, 'July', 'Heavy Rain', 'PBZ', '05-JUL-18 06:20:00', 'EST-5', '05-JUL-18 10:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'E', 'SHALECREST', 1, 'E', 'SHALECREST', 40.52, -79.96, 40.52, -79.96, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'A citizen reported 2.19 inches has fallen since 6am.');
INSERT INTO public.stormevents_east VALUES (773782, 201807, 5, 1353, 201807, 5, 1353, 128797, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 13:53:00', 'EST-5', '05-JUL-18 13:53:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'DAWSON RIDGE', 2, 'ENE', 'DAWSON RIDGE', 40.71, -80.37, 40.71, -80.37, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'The 911 Call Center reported multiple trees down in Patterson and Brighton Township.');
INSERT INTO public.stormevents_east VALUES (773783, 201807, 5, 1321, 201807, 5, 1321, 128797, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 13:21:00', 'EST-5', '05-JUL-18 13:21:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNE', 'FOMBELL', 3, 'NNE', 'FOMBELL', 40.84, -80.18, 40.84, -80.18, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'A 911 Call Center reported trees down at American School Road and Camp Run in Franklin Township.');
INSERT INTO public.stormevents_east VALUES (772510, 201807, 5, 600, 201807, 5, 1005, 128797, 'PENNSYLVANIA', 42, 2018, 'July', 'Heavy Rain', 'PBZ', '05-JUL-18 06:00:00', 'EST-5', '05-JUL-18 10:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NE', 'HIGHCLIFF', 1, 'NE', 'HIGHCLIFF', 40.53, -80.02, 40.53, -80.02, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'Trained spotter measured 2.27 inches since 6am.');
INSERT INTO public.stormevents_east VALUES (773785, 201807, 5, 1723, 201807, 5, 1723, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 17:23:00', 'EST-5', '05-JUL-18 17:23:00', 0, 0, 0, 0, NULL, NULL, 'COOP Observer', 50, 'EG', NULL, NULL, 1, 'SW', 'SHERRODSVILLE', 1, 'SW', 'SHERRODSVILLE', 40.49, -81.24, 40.49, -81.24, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'A COOP Observer and an Emergency Manager reported numerous trees down near SR-212.');
INSERT INTO public.stormevents_east VALUES (807238, 201812, 15, 1215, 201812, 15, 1515, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 12:15:00', 'EST-5', '15-DEC-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'WSW', 'TREMONT', 38.8469, -77.2379, 38.8459, -77.2386, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Woodburn Road closed due to flooding between Spicewood Drive and Robey Avenue.');
INSERT INTO public.stormevents_east VALUES (807253, 201812, 15, 1225, 201812, 15, 1425, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 12:25:00', 'EST-5', '15-DEC-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'BRIGHTWOOD', 3, 'SSW', 'BRIGHTWOOD', 38.3864, -78.2197, 38.3885, -78.2229, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'VA-680 (Gate Road) closed due to high water east of US-29 (Seminole Trail).');
INSERT INTO public.stormevents_east VALUES (807260, 201812, 15, 1242, 201812, 15, 1442, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 12:42:00', 'EST-5', '15-DEC-18 14:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'LEESBURG', 2, 'ESE', 'LEESBURG', 39.1135, -77.5201, 39.1136, -77.5214, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Edwards Ferry Road NE closed between Battlefield Parkway and Red Rock Way.');
INSERT INTO public.stormevents_east VALUES (807261, 201812, 15, 1245, 201812, 15, 1515, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 12:45:00', 'EST-5', '15-DEC-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'DONOVANS CORNER', 1, 'E', 'DONOVANS CORNER', 38.77, -77.31, 38.7707, -77.3087, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Burke Lake Road closed near intersection with Kilkenny Lane due to flooding.');
INSERT INTO public.stormevents_east VALUES (787851, 201809, 3, 1200, 201809, 3, 2300, 131618, 'FLORIDA', 12, 2018, 'September', 'Flood', 'MFL', '03-SEP-18 12:00:00', 'EST-5', '03-SEP-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'SSW', 'HOMESTEAD', 1, 'E', 'LEISURE CITY', 25.4627, -80.4753, 25.4813, -80.4151, 'A low pressure system moving across the tropical Atlantic into the Bahamas formed into Tropical Storm Gordon near the South Florida peninsula. Although the effects from Tropical Storm Gordon were fairly minor for South Florida, sustained Tropical Storm force winds were felt across portions of Miami-Dade and Broward County. Miami-Dade and Broward reported slightly higher amount of power outages than a typical day across the region. Due to some heavy rainbands Miami-Dade county experienced some street flooding that led to partial lane closures. However, no structural flooding was reported with all flood impacts relatively minor.', 'Heavy rainfall associated with Tropical Storm Gordon fell across much of southern Miami-Dade County, including the Homestead area. Multiple reports of 5 to 7 inches of rain fell across the region, which led to some minor street flooding and a few partial lane closures.');
INSERT INTO public.stormevents_east VALUES (801133, 201812, 15, 2211, 201812, 16, 1224, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 22:11:00', 'EST-5', '16-DEC-18 12:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'DARNESTOWN', 2, 'NNE', 'DARNESTOWN', 39.1229, -77.2917, 39.1299, -77.2917, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The stream gage on the Seneca Creek at Dawsonville exceeded the 7.5 foot flood stage during the indicated period, leading to flooding of the Seneca Creek Greenway, as well as a small portion of Berryville Road west of Darnestown. The peak level of 8.98 feet occurred at 1:35 AM on the 16th.');
INSERT INTO public.stormevents_east VALUES (801773, 201812, 16, 310, 201812, 16, 828, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 03:10:00', 'EST-5', '16-DEC-18 08:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'GLENCOE', 1, 'WSW', 'GLENCOE', 39.5432, -76.6405, 39.5442, -76.6416, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The stream gage on Gunpowder Falls at Glencoe exceeded the 7 foot flood stage during the indicated period. Flooding occurred along portions of Upper Glencoe Road and Lower Glencoe Road. The peak level of 7.76 feet occurred at 5:45 AM on December 16th.');
INSERT INTO public.stormevents_east VALUES (783576, 201809, 16, 600, 201809, 16, 600, 130244, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 06:00:00', 'EST-5', '16-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 3, 'SE', 'WILLIS', 3, 'SE', 'WILLIS', 36.8224, -80.4455, 36.8224, -80.4455, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'Willis 2.7 SE CoCoRaHS (VA-FL-6) measured 7.78 inches for the 24 hours ending 0700 local time on the 17th. This value falls into the 90 percent confidence interval (7.63-9.31 inches) for a 25-year average recurrence interval (.04 annual exceedance probability) per NOAA Atlas 2.');
INSERT INTO public.stormevents_east VALUES (787610, 201809, 17, 810, 201809, 17, 1910, 130244, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '17-SEP-18 08:10:00', 'EST-5', '17-SEP-18 19:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'IVANHOE', 1, 'WNW', 'AUSTINVILLE', 36.8272, -80.9506, 36.8554, -80.9146, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'The New River at Ivanhoe (IVNV2) rose very rapidly and crested at 18.02 feet (44400 cfs) late morning of the 17th. It was the highest stage since the January 31, 2013 flood (19.66 ft.) and the 8th highest since gage records began in 1931.  It was approximately a 10-year flood event (.10 annual chance event) per USGS studies. Shady River Drive in Ivanhoe near the gage was flooded.');
INSERT INTO public.stormevents_east VALUES (787709, 201809, 17, 830, 201809, 17, 2130, 130244, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '17-SEP-18 08:30:00', 'EST-5', '17-SEP-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'SALEM (C)', 3, 'WSW', 'SALEM (C)', 37.2794, -80.1068, 37.2768, -80.1033, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'The Roanoke River IFLOWS gage at Salem Pump Station (SPSV2) rose above the minor flood stage of 7 feet on the morning of the 17th and crested at 10.1 feet. The Mill Lane bridge was closed and flooding occurred along portions of Riverside Drive.');
INSERT INTO public.stormevents_east VALUES (781515, 201808, 6, 1552, 201808, 6, 1552, 130550, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '06-AUG-18 15:52:00', 'EST-5', '06-AUG-18 15:52:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'S', 'ALBION CENTER', 1, 'S', 'ALBION CENTER', 43.47, -76.05, 43.47, -76.05, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', 'Trees and wires were reported down along County Route 22 and State Route 104.');
INSERT INTO public.stormevents_east VALUES (781516, 201808, 6, 1615, 201808, 6, 1615, 130550, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '06-AUG-18 16:15:00', 'EST-5', '06-AUG-18 16:15:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'WILLIAMSTOWN', 1, 'E', 'WILLIAMSTOWN', 43.42, -75.89, 43.42, -75.89, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', 'A tree was reported down near the intersection of Route 17 and 13.');
INSERT INTO public.stormevents_east VALUES (781518, 201808, 7, 358, 201808, 7, 358, 130551, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '07-AUG-18 03:58:00', 'EST-5', '07-AUG-18 03:58:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'NNW', 'SMITHVILLE', 2, 'NNW', 'SMITHVILLE', 43.9, -76.11, 43.9, -76.11, 'A pre-frontal trough moved across southern Ontario during the overnight and pre-dawn hours with weak forcing brushing areas close to the Canadian border. A cluster of storms developed over the western end of Lake Ontario and maintained intensity as they crossed the lake, likely due to better nocturnal instability over the very warm lake waters. Outflow from these storms came onshore near Stony Point and Sackets Harbor with greater than 40 knots velocity and a still elevated core. This core came down as the storms approached Jefferson County. The storms quickly weakened as they moved onshore and away from the warm waters of Lake Ontario.', 'A large tree was reported down across Ridge Road between Route 3 and 75.');
INSERT INTO public.stormevents_east VALUES (781519, 201808, 8, 815, 201808, 8, 815, 130552, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '08-AUG-18 08:15:00', 'EST-5', '08-AUG-18 08:15:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'W', 'FOREST GLEN', 1, 'W', 'FOREST GLEN', 42.72, -78.83, 42.72, -78.83, 'The region was in a moist southwest flow with a weak ridge across the southeastern states and an shortwave digging into eastern Michigan. The 12z BUF sounding had a precipitable water value of 1.78 inches but very limited wind shear with 15 kts at 850mb and 20 kts at 700 mb. Despite this limited shear, an impressive storm developed across lake Erie around 7 AM and slowly tracked across the Buffalo metro area around 9 AM. The same storm moved eastward toward Victor, producing mainly heavy rainfall with radar estimates near 2 inches.', 'Several large tree limbs were reported down with minor property damage.');
INSERT INTO public.stormevents_east VALUES (781799, 201808, 14, 850, 201808, 14, 1050, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 08:50:00', 'EST-5', '14-AUG-18 10:50:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'RAILROAD MILLS', 1, 'SSW', 'BUSHNELL BASIN', 43.0429, -77.4883, 43.052, -77.487, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Park and Woolston Roads were closed in Powder Mill Park due to flooding.');
INSERT INTO public.stormevents_east VALUES (767827, 201808, 1, 1845, 201808, 1, 1845, 128020, 'VIRGINIA', 51, 2018, 'August', 'Lightning', 'RNK', '01-AUG-18 18:45:00', 'EST-5', '01-AUG-18 18:45:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', NULL, NULL, NULL, NULL, 1, 'ENE', 'ALTAVISTA', 1, 'ENE', 'ALTAVISTA', 37.1247, -79.2742, 37.1247, -79.2742, 'Scattered severe thunderstorms developed in parts of the Virginia Piedmont during the afternoon.  The storms blew down several trees and power lines, and lightning from one of these storms struck a residence.', 'Lightning struck a residence on Riverview Drive in Altavista. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (767831, 201808, 1, 1712, 201808, 1, 1712, 128020, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '01-AUG-18 17:12:00', 'EST-5', '01-AUG-18 17:12:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 0, 'ESE', 'RIDGEWAY', 0, 'ESE', 'RIDGEWAY', 36.5789, -79.8631, 36.5789, -79.8631, 'Scattered severe thunderstorms developed in parts of the Virginia Piedmont during the afternoon.  The storms blew down several trees and power lines, and lightning from one of these storms struck a residence.', 'Thunderstorm winds blew down multiple trees in Ridgeway.');
INSERT INTO public.stormevents_east VALUES (767821, 201808, 1, 1624, 201808, 1, 1624, 128019, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '01-AUG-18 16:24:00', 'EST-5', '01-AUG-18 16:24:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 3, 'NE', 'VADE MECUM', 3, 'NE', 'VADE MECUM', 36.4474, -80.2902, 36.4474, -80.2902, 'One severe thunderstorm developed during the afternoon and became severe over the North Carolina Piedmont.  This storm blew a few trees down in Stokes County.', 'Thunderstorm winds blew down multiple trees on Lynchburg Road.');
INSERT INTO public.stormevents_east VALUES (767823, 201808, 1, 1636, 201808, 1, 1636, 128019, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '01-AUG-18 16:36:00', 'EST-5', '01-AUG-18 16:36:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'E', 'LAWSONVILLE', 2, 'E', 'LAWSONVILLE', 36.4824, -80.2106, 36.4824, -80.2106, 'One severe thunderstorm developed during the afternoon and became severe over the North Carolina Piedmont.  This storm blew a few trees down in Stokes County.', 'Thunderstorm winds blew down multiple trees on Snow Hill Church Road.');
INSERT INTO public.stormevents_east VALUES (767882, 201808, 2, 1806, 201808, 2, 1806, 128028, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '02-AUG-18 18:06:00', 'EST-5', '02-AUG-18 18:06:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'WNW', 'ELKIN', 2, 'WNW', 'ELKIN', 36.257, -80.8841, 36.257, -80.8841, 'A slow-moving front with a deep upper trough pulling moisture into the region fueled pockets of heavy rainfall in the early to mid-morning. A few storms became severe by afternoon blowing down trees in several counties. Heavy rainfall redeveloped by mid- to late afternoon as a complex, broken line of convection pushed north under deep, moist southerly flow. Rainfall ranged from 2 to 3 inches in a wide swath across Rockingham and parts of Surry counties.', 'Thunderstorm winds blew down multiple trees in Pleasant Hill.');
INSERT INTO public.stormevents_east VALUES (768202, 201808, 8, 1409, 201808, 8, 1431, 128103, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 14:09:00', 'EST-5', '08-AUG-18 14:31:00', 0, 0, 0, 0, '50.00K', NULL, 'Fire Department/Rescue', 60, 'EG', NULL, NULL, 5, 'W', 'DANVILLE', 2, 'E', 'DANVILLE', 36.6008, -79.4862, 36.5892, -79.3612, 'A hot and humid air mass sparked scattered severe thunderstorms during the afternoon.  These storms blew down multiple trees and power lines in southwest Virginia.  Two homes suffered damage in the city of Danville due to a tree falling on each of them.', 'Thunderstorm winds blew down several trees in a swath of damage through the city of Danville from 2:09 PM EST to 2:31 PM EST.  One of the trees landed on Parkway Drive.  Another tree fell over power lines on Lynch Street, and a power pole was split as a result.  In addition, two houses suffered damage due to a tree falling on each of them.');
INSERT INTO public.stormevents_east VALUES (768439, 201808, 12, 1255, 201808, 12, 1255, 128143, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:55:00', 'EST-5', '12-AUG-18 12:55:00', 0, 0, 0, 0, '0.50K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'ENE', 'FAIRPLAINS', 1, 'ENE', 'FAIRPLAINS', 36.2237, -81.1599, 36.2237, -81.1599, 'A closed upper level low combined with a passing cold front sparked a severe thunderstorm during the afternoon.  This storm blew down several trees in Wilkes County.', 'Thunderstorm winds blew down one tree along John McGrady Road.');
INSERT INTO public.stormevents_east VALUES (768543, 201808, 12, 1315, 201808, 12, 1315, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:15:00', 'EST-5', '12-AUG-18 13:15:00', 0, 0, 0, 0, '2.50K', NULL, 'Trained Spotter', 55, 'EG', NULL, NULL, 0, 'E', 'NATURAL WELL', 0, 'E', 'NATURAL WELL', 37.9198, -79.9651, 37.9198, -79.9651, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down several trees along Route 687 from Falling Spring to Lake Moomaw.');
INSERT INTO public.stormevents_east VALUES (775556, 201808, 3, 2213, 201808, 4, 13, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:13:00', 'EST-5', '04-AUG-18 00:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'WILLOW GROVE', 1, 'N', 'WILLOW GROVE', 38.84, -78.53, 38.845, -78.5332, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-672 Chapman Landing Road was closed due to flooding at the North Fork Shenandoah River near US-11 Old Valley Pike.');
INSERT INTO public.stormevents_east VALUES (775557, 201808, 3, 2213, 201808, 4, 13, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:13:00', 'EST-5', '04-AUG-18 00:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'WOODSTOCK', 3, 'ESE', 'WOODSTOCK', 38.87, -78.49, 38.864, -78.4713, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-667 Lupton Road was closed at the North Fork Shenandoah River due to flooding near French Roods Road.');
INSERT INTO public.stormevents_east VALUES (775558, 201808, 3, 2216, 201808, 4, 16, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:16:00', 'EST-5', '04-AUG-18 00:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'STANDARDSVILLE', 1, 'N', 'STANDARDSVILLE', 38.32, -78.43, 38.3146, -78.428, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-621 South River Road was closed due to flooding near VA-230 Madison Road.');
INSERT INTO public.stormevents_east VALUES (775559, 201808, 3, 2216, 201808, 4, 16, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:16:00', 'EST-5', '04-AUG-18 00:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'LYDIA', 1, 'SSW', 'LYDIA', 38.3306, -78.4982, 38.317, -78.5078, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-634 Mutton Holow Road was closed due to flooding between VA-635 Matties Run Road and US-33 Spotswood Trail.');
INSERT INTO public.stormevents_east VALUES (775562, 201808, 3, 2231, 201808, 4, 31, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:31:00', 'EST-5', '04-AUG-18 00:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 4, 'NNW', 'BOYCE', 4, 'NNW', 'BOYCE', 39.15, -78.09, 39.1496, -78.0864, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-655 Opequon Road was closed at Opequon Creek due to flooding.');
INSERT INTO public.stormevents_east VALUES (778165, 201808, 21, 1853, 201808, 21, 1853, 129896, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '21-AUG-18 18:53:00', 'EST-5', '21-AUG-18 18:53:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 35, 'MG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'A warm front lifted northward through the day across the area, while a cold front approached from the west. These boundaries interacted with a moist and unstable air mass and moderate wind shear to generate thunderstorms which produced strong winds over the waters.', 'A wind gust of 35 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778168, 201808, 30, 2349, 201808, 31, 4, 129898, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '30-AUG-18 23:49:00', 'EST-5', '31-AUG-18 00:04:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 0, 'N', 'RACCOON POINT (RAC)', 0, 'N', 'RACCOON POINT (RAC)', 38.14, -75.79, 38.14, -75.79, 'An approaching cold front interacted with a warm and moist unstable air mass across the region to produce showers and thunderstorms, one of which produced strong winds over the waters.', 'A wind gust of 38 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778169, 201808, 31, 1827, 201808, 31, 1847, 129899, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '31-AUG-18 18:27:00', 'EST-5', '31-AUG-18 18:47:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 50, 'MG', NULL, NULL, 0, 'N', 'HART MILLER ISLAND (HRT)', 0, 'N', 'HART MILLER ISLAND (HRT)', 39.25, -76.37, 39.25, -76.37, 'A stationary front draped across the region combined with high instability and moisture to generate slow moving showers and thunderstorms, one of which produced strong winds over the waters.', 'A wind gust of 50 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778170, 201808, 1, 38, 201808, 1, 38, 129900, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '01-AUG-18 00:38:00', 'EST-5', '01-AUG-18 00:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 35, 'EG', NULL, NULL, 0, 'N', 'ANNAPOLIS (KNAK)', 0, 'N', 'ANNAPOLIS (KNAK)', 38.98, -76.48, 38.98, -76.48, 'A cold front crossing the region combined with high instability and moderate shear values to produce thunderstorms, one of which produced strong winds over the waters.', 'A wind gust of 35 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778171, 201808, 7, 1548, 201808, 7, 1548, 129890, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '07-AUG-18 15:48:00', 'EST-5', '07-AUG-18 15:48:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of 35 knots was measured.');
INSERT INTO public.stormevents_east VALUES (775629, 201808, 12, 1431, 201808, 12, 1631, 129470, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '12-AUG-18 14:31:00', 'EST-5', '12-AUG-18 16:31:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'STANDARDSVILLE', 2, 'NNW', 'STANDARDSVILLE', 38.33, -78.45, 38.3296, -78.4476, 'A weak boundary remained overhead while an upper-level trough moved into the area. Warm and humid conditions led to an unstable atmosphere during this time. The unstable atmosphere combined with lift associated with the trough and the boundary to produce showers and thunderstorms. Locally heavy rain led to some flooding.', 'The road was closed at the intersection of South River Road and Madison Road due to high water.');
INSERT INTO public.stormevents_east VALUES (775630, 201808, 12, 1538, 201808, 12, 1738, 129470, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '12-AUG-18 15:38:00', 'EST-5', '12-AUG-18 17:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'STANDARDSVILLE', 1, 'N', 'STANDARDSVILLE', 38.31, -78.43, 38.3108, -78.432, 'A weak boundary remained overhead while an upper-level trough moved into the area. Warm and humid conditions led to an unstable atmosphere during this time. The unstable atmosphere combined with lift associated with the trough and the boundary to produce showers and thunderstorms. Locally heavy rain led to some flooding.', 'High water caused the road to be closed at the intersection of Octonia Road and Madison Road.');
INSERT INTO public.stormevents_east VALUES (785077, 201809, 17, 400, 201809, 18, 1130, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RNK', '17-SEP-18 04:00:00', 'EST-5', '18-SEP-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'MADISON', 2, 'NE', 'INTELLIGENCE', 36.3781, -79.974, 36.395, -79.8692, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'The river gage on the Dan River near Wentworth, NC (WENN7) rose above the flood stage of 19 feet and crested just below the Moderate flood category (25 feet) at 24.88 feet (28,900 cfs) mid-morning of the 17th. This was the 8th highest stage on record at this gage since records began in 1940 and the highest since 2003. According to USGS analysis, the frequency for the event was approximately a 10-year flood (0.1 annual chance of occurrence). Several roads were flooded and closed near the confluence of the Mayo and Dan rivers in the Madison area per local news reports.');
INSERT INTO public.stormevents_east VALUES (785091, 201809, 16, 2320, 201809, 17, 520, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RNK', '16-SEP-18 23:20:00', 'EST-5', '17-SEP-18 05:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'WALNUT COVE', 2, 'E', 'VADE MECUM', 36.2741, -80.1386, 36.4201, -80.2913, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'Town Fork Creek was reported out of its banks and flooding portions of Walnut Cove. Flat Shoals Creek was also flooding parts of Sunset Park. The Dan River was out its banks and flooded Dan River Shores Road.');
INSERT INTO public.stormevents_east VALUES (786775, 201809, 16, 2300, 201809, 17, 1645, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RNK', '16-SEP-18 23:00:00', 'EST-5', '17-SEP-18 16:45:00', 0, 0, 0, 0, '50.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'WAGONER', 1, 'S', 'WAGONER', 36.376, -81.3988, 36.3788, -81.3994, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'The South Fork of the New River near Jefferson (JFRN7) crested at 9.43 feet (Minor flood stage is 8 ft.) in the early morning of the 17th. Several roads are affected at this stage. This was the highest stage since January 31, 2013 at this gage. The discharge of 9460 cfs was approximately a 5 to 10-year event (0.2 to 0.1 annual chance) per USGS. Several roads close to the New River were flooded and damaged according to NC DOT officials.');
INSERT INTO public.stormevents_east VALUES (787498, 201809, 17, 524, 201809, 17, 1124, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RNK', '17-SEP-18 05:24:00', 'EST-5', '17-SEP-18 11:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'PINEY CREEK', 3, 'SW', 'PINEY CREEK', 36.5271, -81.3388, 36.5283, -81.3371, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'A spotter reported water of 2 to 3 foot depth over Garvey Bridge Road near Rivercamp USA campground in Piney Creek. Flooding may have been from the South Fork of the New River which was above flood stage at the Jefferson gage upstream.');
INSERT INTO public.stormevents_east VALUES (781077, 201809, 10, 800, 201809, 10, 2145, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '10-SEP-18 08:00:00', 'EST-5', '10-SEP-18 21:45:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'MACKSBURG', 0, 'SE', 'MACKSBURG', 39.6334, -81.4601, 39.6276, -81.4662, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'Duck Creek at Macksburg rose above its 13 foot flood stage mid-morning on the 10th. It crested in minor flood stage at 13.3 feet that evening and returned to its banks later that night. This caused minor flooding along Broad Street in the town of Macksburg.');
INSERT INTO public.stormevents_east VALUES (781082, 201809, 9, 2234, 201809, 11, 752, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '09-SEP-18 22:34:00', 'EST-5', '11-SEP-18 07:52:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'CHESTER', 2, 'SSW', 'KENO', 39.0761, -81.9192, 39.0773, -81.8808, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'The Shade River near Chester rose above its 17 foot bank full level shortly after midnight on the 10th. It crested just above 21 feet that afternoon, reaching moderate flood stage. It slowly returned to its banks by the next morning. This flooded the Sugar Run Creek Bridge and Oak Hill Road.');
INSERT INTO public.stormevents_east VALUES (781069, 201809, 9, 2003, 201809, 10, 1720, 129569, 'OHIO', 39, 2018, 'September', 'Flood', 'RLX', '09-SEP-18 20:03:00', 'EST-5', '10-SEP-18 17:20:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'HANGING ROCK', 2, 'SSW', 'RAPPSBURG', 38.5692, -82.7029, 38.5978, -82.4158, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in southeast Ohio.', 'Route 140 was closed due to flooding along Hales Creek and Route 93 was closed due to flooding along Olive Creek.||The river gage on Symmes Creek at Aid also rose into minor flood stage. The creek crested at 19.1 feet, just above its 19 foot bank full level, on the evening of the 10th. This closed a section of Route 141 near Aid.');
INSERT INTO public.stormevents_east VALUES (781062, 201809, 9, 2322, 201809, 10, 1014, 129567, 'KENTUCKY', 21, 2018, 'September', 'Flood', 'RLX', '09-SEP-18 23:22:00', 'EST-5', '10-SEP-18 10:14:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'PACTOLUS', 2, 'ENE', 'PACTOLUS', 38.3688, -82.9606, 38.3757, -82.9027, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in extreme northeast Kentucky.', 'The Little Sandy River at Grayson surpassed its 21 foot flood stage just after midnight on the 10th. The river crested in minor flood stage at 22.6 feet just before sunrise and returned to its banks shortly after noon. This flooded sections of Route 773 in the Dixie Park area and SR 1910 was also flooded along with some farmland.');
INSERT INTO public.stormevents_east VALUES (781065, 201809, 10, 1110, 201809, 11, 45, 129567, 'KENTUCKY', 21, 2018, 'September', 'Flood', 'RLX', '10-SEP-18 11:10:00', 'EST-5', '11-SEP-18 00:45:00', 0, 0, 0, 0, '10.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BEECHY', 1, 'SSE', 'BENNETT', 38.6011, -82.9563, 38.5323, -83.0065, 'Moisture from the remnants of Tropical Storm Gordon led to a prolonged period of moderate to heavy rain. This caused some flooding in extreme northeast Kentucky.', 'Tygarts Creek near Grayson flooded on the 10th. The creek rose above its 20 foot flood stage just after noon. It crested at 20.7 feet in minor flood stage that evening and returned within its banks shortly after midnight on the 11th. This flooded low areas along SR 7 and CR 2070. The country story and some homes near the creek in the town of Load also had minor flooding.');
INSERT INTO public.stormevents_east VALUES (780645, 201808, 30, 2042, 201808, 30, 2242, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 20:42:00', 'EST-5', '30-AUG-18 22:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'STOKESVILLE', 1, 'ENE', 'STOKESVILLE', 38.35, -79.13, 38.3559, -79.1287, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'Bear Trap Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (780646, 201808, 30, 1700, 201808, 30, 1900, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 17:00:00', 'EST-5', '30-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'PARNASSUS', 1, 'SW', 'PARNASSUS', 38.2935, -79.1252, 38.2933, -79.1261, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'Multiple vehicles were trapped in swift water along Scenic Highway.');
INSERT INTO public.stormevents_east VALUES (781570, 201808, 31, 2150, 201808, 31, 2350, 130420, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 21:50:00', 'EST-5', '31-AUG-18 23:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BERKELEY', 1, 'NNW', 'BERKELEY', 39.5091, -77.9341, 39.5107, -77.9335, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The 2700 Block of Williamsport Pike was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (783631, 201809, 6, 1425, 201809, 6, 1425, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 14:25:00', 'EST-5', '06-SEP-18 14:25:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'NE', 'WEST GRANVILLE', 2, 'NE', 'WEST GRANVILLE', 42.0948, -72.9277, 42.0948, -72.9277, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 2:25 PM EST, wind brought three trees down blocking North Lane in Granville.');
