INSERT INTO public.stormevents_east VALUES (785454, 201809, 6, 1558, 201809, 6, 1658, 131288, 'WEST VIRGINIA', 54, 2018, 'September', 'Flash Flood', 'PBZ', '06-SEP-18 15:58:00', 'EST-5', '06-SEP-18 16:58:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'MANNINGTON', 1, 'WSW', 'MANNINGTON', 39.53, -80.34, 39.5273, -80.3434, 'Showers and thunderstorms developed with the passage of a cold front. There was sufficient moisture, modest instability, and weak wind shear. Forecasted soundings predicted 0-3km lapse rates at an excess of 8.5 C/km. Mid-level dry air helped create an environment for strong downdrafts/damaging winds.', 'The 911 Call Center reported street flooding.');
INSERT INTO public.stormevents_east VALUES (785455, 201809, 6, 1534, 201809, 6, 1534, 131288, 'WEST VIRGINIA', 54, 2018, 'September', 'Thunderstorm Wind', 'PBZ', '06-SEP-18 15:34:00', 'EST-5', '06-SEP-18 15:34:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'WSW', 'BETHANY', 2, 'WSW', 'BETHANY', 40.19, -80.58, 40.19, -80.58, 'Showers and thunderstorms developed with the passage of a cold front. There was sufficient moisture, modest instability, and weak wind shear. Forecasted soundings predicted 0-3km lapse rates at an excess of 8.5 C/km. Mid-level dry air helped create an environment for strong downdrafts/damaging winds.', 'The Dept of Transportation reported tree branches down been Bethany and West Liberty.');
INSERT INTO public.stormevents_east VALUES (785456, 201809, 6, 1541, 201809, 6, 1541, 131288, 'WEST VIRGINIA', 54, 2018, 'September', 'Thunderstorm Wind', 'PBZ', '06-SEP-18 15:41:00', 'EST-5', '06-SEP-18 15:41:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'WEST LIBERTY', 1, 'W', 'WEST LIBERTY', 40.17, -80.59, 40.17, -80.59, 'Showers and thunderstorms developed with the passage of a cold front. There was sufficient moisture, modest instability, and weak wind shear. Forecasted soundings predicted 0-3km lapse rates at an excess of 8.5 C/km. Mid-level dry air helped create an environment for strong downdrafts/damaging winds.', 'Local 911 Call Center reported trees down around this area.');
INSERT INTO public.stormevents_east VALUES (756421, 201805, 15, 1457, 201805, 15, 1457, 126186, 'CONNECTICUT', 9, 2018, 'May', 'Hail', 'ALY', '15-MAY-18 14:57:00', 'EST-5', '15-MAY-18 14:57:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1.75, NULL, NULL, NULL, 2, 'NNW', 'BARKHAMSTED', 2, 'NNW', 'BARKHAMSTED', 41.96, -72.93, 41.96, -72.93, 'Severe thunderstorms impacted portions of Litchfield County during the afternoon of May 15th. A supercell thunderstorm crossed northern portions of the county, resulting in hail up to two inches in diameter, two confirmed tornadoes, and straight-line wind damage. Later in the afternoon, a severe thunderstorm resulted in wind damage across far southern portions of the county. Numerous power outages and several road closures occurred as a result of the storms.', 'Golf ball-sized hail was covering the ground near Barkhamsted.');
INSERT INTO public.stormevents_east VALUES (756422, 201805, 15, 1444, 201805, 15, 1446, 126186, 'CONNECTICUT', 9, 2018, 'May', 'Tornado', 'ALY', '15-MAY-18 14:44:00', 'EST-5', '15-MAY-18 14:46:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NNE', 'WINSTED', 1, 'ENE', 'WINSTED', 41.9298, -73.065, 41.9289, -73.0519, 'Severe thunderstorms impacted portions of Litchfield County during the afternoon of May 15th. A supercell thunderstorm crossed northern portions of the county, resulting in hail up to two inches in diameter, two confirmed tornadoes, and straight-line wind damage. Later in the afternoon, a severe thunderstorm resulted in wind damage across far southern portions of the county. Numerous power outages and several road closures occurred as a result of the storms.', 'An EF1 tornado struck the northeast side of Winsted, CT. The tornado moved west to east across eight city blocks, shearing and uprooting trees, and producing some minor structural damage to homes. Many homes and power lines were damaged by fallen trees. A member of the local community witnessed the tornado.');
INSERT INTO public.stormevents_east VALUES (785614, 201809, 7, 530, 201809, 10, 530, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 05:30:00', 'EST-5', '10-SEP-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 0, 'N', 'SALEM', 0, 'N', 'SALEM', 40.9, -80.85, 40.9, -80.85, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A CoCoRaHS observer recorded a storm total of 4.28 inches.');
INSERT INTO public.stormevents_east VALUES (785616, 201809, 7, 800, 201809, 10, 800, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 3, 'NE', 'ANTRIM', 3, 'NE', 'ANTRIM', 40.1507, -81.3098, 40.1507, -81.3098, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A storm total of 4.90 inches was recorded.');
INSERT INTO public.stormevents_east VALUES (785615, 201809, 7, 800, 201809, 10, 800, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 0, 'N', 'AMSTERDAM', 0, 'N', 'AMSTERDAM', 40.47, -80.92, 40.47, -80.92, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'The Army Corps of Engineers recorded a storm total of 3.52 inches.');
INSERT INTO public.stormevents_east VALUES (785617, 201809, 7, 715, 201809, 10, 715, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:15:00', 'EST-5', '10-SEP-18 07:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 0, 'N', 'CADIZ', 0, 'N', 'CADIZ', 40.27, -81, 40.27, -81, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'The Army Corps of Engineers recorded at storm total of 5.43 inches.');
INSERT INTO public.stormevents_east VALUES (782259, 201808, 16, 204, 201808, 16, 204, 130726, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'CAR', '16-AUG-18 02:04:00', 'EST-5', '16-AUG-18 02:04:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'EASTERN MAINE SHELF BUOY 44034', 0, 'N', 'EASTERN MAINE SHELF BUOY 44034', 44.11, -68.11, 44.11, -68.11, 'A cold front crossing the coastal waters produced strong thunderstorms during the early morning hours of the 16th.', NULL);
INSERT INTO public.stormevents_east VALUES (776402, 201807, 23, 8, 201807, 23, 10, 129608, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'ILM', '23-JUL-18 00:08:00', 'EST-5', '23-JUL-18 00:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 35, 'MG', NULL, NULL, 25, 'SSE', 'SHEEPSHEAD ROCK', 25, 'SSE', 'SHEEPSHEAD ROCK', 33.6016, -77.7755, 33.6016, -77.7755, 'A stationary frontal boundary produce strong storms that moved offshore.', 'A 40 mph gust was recorded at the Frying Pan Shoals Buoy.');
INSERT INTO public.stormevents_east VALUES (776405, 201807, 22, 2347, 201807, 22, 2349, 129608, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'ILM', '22-JUL-18 23:47:00', 'EST-5', '22-JUL-18 23:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 39, 'MG', NULL, NULL, 2, 'NW', 'SHEEPSHEAD ROCK', 2, 'NW', 'SHEEPSHEAD ROCK', 33.96, -77.94, 33.96, -77.94, 'A stationary frontal boundary produce strong storms that moved offshore.', 'A 45 mph gust was recorded at Federal Point.');
INSERT INTO public.stormevents_east VALUES (776410, 201807, 23, 424, 201807, 23, 426, 129608, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'ILM', '23-JUL-18 04:24:00', 'EST-5', '23-JUL-18 04:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 1, 'WNW', 'MURRELLS INLET SEA NAVIGATIONAL BUOY', 1, 'WNW', 'MURRELLS INLET SEA NAVIGATIONAL BUOY', 33.52, -79.03, 33.52, -79.03, 'A stationary frontal boundary produce strong storms that moved offshore.', 'A 40 mph gust was recorded at Murrells Inlet.');
INSERT INTO public.stormevents_east VALUES (782288, 201808, 11, 650, 201808, 11, 900, 130476, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '11-AUG-18 06:50:00', 'EST-5', '11-AUG-18 09:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'LAWTON', 1, 'NW', 'LAWTON', 41.7655, -76.0645, 41.7884, -76.0779, 'Deep tropical-like moisture lingered over the region as an upper level disturbance and slow moving surface front drifted into northern Pennsylvania. Thunderstorms continually developed over the area, producing significant amounts of rainfall in a short amount of time. This triggered areas of flash flooding in previously saturated, and flood damage areas.', 'Flood waters were washing out portions of Route 267 near Lawton.');
INSERT INTO public.stormevents_east VALUES (785586, 201809, 10, 4, 201809, 10, 404, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '10-SEP-18 00:04:00', 'EST-5', '10-SEP-18 04:04:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'EIDENAU', 2, 'ESE', 'EIDENAU', 40.79, -80.09, 40.7937, -80.0919, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported 3 people trapped in their residence on Eidenau Rd. due to flooding.');
INSERT INTO public.stormevents_east VALUES (776427, 201807, 23, 8, 201807, 23, 10, 129612, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'ILM', '23-JUL-18 00:08:00', 'EST-5', '23-JUL-18 00:10:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'N', 'WILMINGTON', 0, 'N', 'WILMINGTON', 34.23, -77.93, 34.23, -77.93, 'A stationary front produced strong nocturnal storms.', 'Power lines were reported down on Castle St, and 18th St.');
INSERT INTO public.stormevents_east VALUES (785633, 201809, 7, 610, 201809, 10, 610, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 06:10:00', 'EST-5', '10-SEP-18 06:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'E', 'SANDY LAKE', 1, 'E', 'SANDY LAKE', 41.35, -80.0607, 41.35, -80.0607, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A CoCoRaHS observer 4.13 inches of rain in a 72 hour time period.');
INSERT INTO public.stormevents_east VALUES (785634, 201809, 7, 700, 201809, 10, 700, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:00:00', 'EST-5', '10-SEP-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 0, 'N', 'SENECA', 0, 'N', 'SENECA', 41.38, -79.72, 41.38, -79.72, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A CoCoRaHS observer recorded 4.06 inches of rainfall in 72 hours.');
INSERT INTO public.stormevents_east VALUES (782323, 201808, 29, 2052, 201808, 29, 2052, 130608, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BGM', '29-AUG-18 20:52:00', 'EST-5', '29-AUG-18 20:52:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'LISLE', 0, 'N', 'LISLE', 42.35, -76, 42.35, -76, 'A line of strong to severe thunderstorms moved across central New York during the evening hours ahead of a strong cold front.', 'Thunderstorm winds blew down trees.');
INSERT INTO public.stormevents_east VALUES (773786, 201807, 5, 1737, 201807, 5, 1737, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 17:37:00', 'EST-5', '05-JUL-18 17:37:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'SE', 'LAMARTINE', 2, 'SE', 'LAMARTINE', 40.45, -81.08, 40.45, -81.08, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'Trees are reported along SR-332 by the Department of Highways.');
INSERT INTO public.stormevents_east VALUES (773787, 201807, 5, 1437, 201807, 5, 1437, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 14:37:00', 'EST-5', '05-JUL-18 14:37:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'CARROLLTON', 0, 'N', 'CARROLLTON', 40.57, -81.08, 40.57, -81.08, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'An emergency manager reported a tree fell on a home along Park Avenue in Carrollton.');
INSERT INTO public.stormevents_east VALUES (773788, 201807, 5, 1724, 201807, 5, 1724, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 17:24:00', 'EST-5', '05-JUL-18 17:24:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'JEWETT', 0, 'N', 'JEWETT', 40.37, -81.03, 40.37, -81.03, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'An Emergency Manager reported trees down along State Route 9. The Dept of Highways also reported trees down along State Route 151.');
INSERT INTO public.stormevents_east VALUES (773789, 201807, 5, 1704, 201807, 5, 1704, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 17:04:00', 'EST-5', '05-JUL-18 17:04:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 4, 'W', 'CADIZ HARRISON CO AR', 4, 'W', 'CADIZ HARRISON CO AR', 40.22, -81.09, 40.22, -81.09, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'The Department of Highways reported trees down along State Route 519.');
INSERT INTO public.stormevents_east VALUES (773790, 201807, 5, 1706, 201807, 5, 1706, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 17:06:00', 'EST-5', '05-JUL-18 17:06:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'CADIZ', 1, 'E', 'CADIZ', 40.27, -80.99, 40.27, -80.99, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'A 911 call center reported numerous trees down in Cadiz.');
INSERT INTO public.stormevents_east VALUES (773791, 201807, 5, 1615, 201807, 5, 1615, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 16:15:00', 'EST-5', '05-JUL-18 16:15:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SHORT CREEK', 1, 'E', 'SHORT CREEK', 40.22, -80.9, 40.22, -80.9, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'The 911 Call Center reported several trees down near Adena along Jefferson County line.');
INSERT INTO public.stormevents_east VALUES (800838, 201812, 16, 930, 201812, 16, 1840, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 09:30:00', 'EST-5', '16-DEC-18 18:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'KEIFER', 0, 'ENE', 'KEIFER', 39.5312, -78.4613, 39.5313, -78.4652, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Potomac River at Paw Paw exceeded the 25 foot flood stage during the indicated period. The roadway to the C&O Canal parking area flooded, as did the lowest end of the Purslane Run hiker/biker area, and a parking area adjacent to the highway bridge. The peak level of 25.33 feet occurred at 1:00 PM.');
INSERT INTO public.stormevents_east VALUES (801106, 201812, 17, 9, 201812, 18, 624, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '17-DEC-18 00:09:00', 'EST-5', '18-DEC-18 06:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'GLEN ECHO', 1, 'S', 'BROOKMONT', 38.9739, -77.1433, 38.9289, -77.1165, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Potomac River at Little Falls exceeded the 10 foot flood stage during the indicated period. Water covered many locations along the C&O Canal towpath, and many hiking trails along the Potomac between Pennyfield Lock and Little Falls were closed as a result of the flooding. The peak level of 11.56 feet occurred at 1:00 PM on December 17th.');
INSERT INTO public.stormevents_east VALUES (801121, 201812, 16, 1507, 201812, 18, 1700, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 15:07:00', 'EST-5', '18-DEC-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'SENECA', 2, 'SSW', 'SENECA', 39.0701, -77.3312, 39.0556, -77.3366, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Potomac River at Edwards Ferry exceeded the 15 foot flood stage during the indicated period. The basements at Edwards Ferry Lockhouse and Rileys Lockhouse were flooded. Backwater flooding affected homes on the Loudoun County side of the river near Broad Run in Sterling. Additionally, the parking lots at Edwards Ferry and Seneca were flooded, along with the store at Whites Ferry.  The peak level of 20.98 feet occurred at 9:00 AM on December 17th.');
INSERT INTO public.stormevents_east VALUES (787515, 201809, 3, 1315, 201809, 3, 1315, 131638, 'NEW YORK', 36, 2018, 'September', 'Thunderstorm Wind', 'BGM', '03-SEP-18 13:15:00', 'EST-5', '03-SEP-18 13:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'WOODGATE', 0, 'N', 'WOODGATE', 43.52, -75.15, 43.52, -75.15, 'A cold front moved into the eastern Great Lakes region during the afternoon of the 3rd. This front sparked off a few thunderstorms one of which become severe in Oneida County in the early afternoon.', 'Thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (787513, 201809, 3, 1742, 201809, 3, 1742, 131639, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'BGM', '03-SEP-18 17:42:00', 'EST-5', '03-SEP-18 17:42:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'MILWAUKEE KEYSE', 1, 'E', 'MILWAUKEE KEYSE', 41.42, -75.77, 41.42, -75.77, 'A cold front moved into the eastern Great Lakes region during the afternoon of the 3rd. This front sparked off a few thunderstorms one of which become severe in Lackawanna County in the late afternoon.', 'Thunderstorm winds knocked down trees and wires.');
INSERT INTO public.stormevents_east VALUES (801796, 201812, 16, 200, 201812, 16, 1131, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 02:00:00', 'EST-5', '16-DEC-18 11:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ELKRIDGE', 0, 'NNW', 'ELKRIDGE', 39.2273, -76.7211, 39.2262, -76.7227, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Patspsco River at Elkridge exceeded the 15 foot flood stage during the indicated period. Water covered a portion of River Road in Patapsco Valley State Park, and large portions of the park were flooded near the playground off Gunn Road. The peak level of 16.80 feet occurred at 5:50 AM on December 16th.');
INSERT INTO public.stormevents_east VALUES (801799, 201812, 15, 2041, 201812, 16, 936, 133709, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 20:41:00', 'EST-5', '16-DEC-18 09:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'MARYLAND CITY', 0, 'NNW', 'TIPTON AAF ARPT', 39.1254, -76.8133, 39.0858, -76.7715, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper-level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Little Patuxent River at Savage exceeded the 10 foot flood stage during the indicated period. Riverside trails were flooded. Additionally, water approached Brock Bridge Road, as well as fields off of Bald Eagle Drive. The peak level of 12.27 feet occurred at 4:45 AM on December 16th.');
INSERT INTO public.stormevents_east VALUES (778305, 201808, 2, 1200, 201808, 2, 1300, 128028, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RNK', '02-AUG-18 12:00:00', 'EST-5', '02-AUG-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'HARRISONS XRDS', 2, 'S', 'HARRISONS XRDS', 36.4, -79.69, 36.4021, -79.6869, 'A slow-moving front with a deep upper trough pulling moisture into the region fueled pockets of heavy rainfall in the early to mid-morning. A few storms became severe by afternoon blowing down trees in several counties. Heavy rainfall redeveloped by mid- to late afternoon as a complex, broken line of convection pushed north under deep, moist southerly flow. Rainfall ranged from 2 to 3 inches in a wide swath across Rockingham and parts of Surry counties.', 'Up to two feet of water was reported flowing over Lake Lemar Road due to overflow from Lake Lemar.');
INSERT INTO public.stormevents_east VALUES (782890, 201808, 18, 1259, 201808, 18, 1600, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '18-AUG-18 12:59:00', 'EST-5', '18-AUG-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'ARMORY', 1, 'NE', 'ARMORY', 42.1254, -72.5667, 42.1266, -72.562, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 12:59 PM EST, Tapley Street near Oak Hill Cemetary was closed due to floodwaters three feet deep.  At 1:21 PM EST Fire Rescue was called to rescue people in trapped car on Tapley Street.');
INSERT INTO public.stormevents_east VALUES (783577, 201809, 16, 500, 201809, 17, 500, 130244, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 05:00:00', 'EST-5', '17-SEP-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 6, 'S', 'COPPER HILL', 6, 'S', 'COPPER HILL', 36.9903, -80.13, 36.9903, -80.13, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'Copper Hill 6.2 S CoCoRaHS (VA-FL-2) measured 7.10 inches for the 24 hours ending 0600 local time on the 17th. This value falls into the 90 percent confidence interval (6.66-8.07 inches) for a 50-year average recurrence interval (.02 annual exceedance probability) per NOAA Atlas 2.');
INSERT INTO public.stormevents_east VALUES (783583, 201809, 16, 800, 201809, 17, 800, 130244, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 08:00:00', 'EST-5', '17-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'E', 'MEADOWS OF DAN', 2, 'E', 'MEADOWS OF DAN', 36.73, -80.3785, 36.73, -80.3785, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'Meadows of Dan 2.3 E CoCoRaHS (VA-PR-5) measured 7.60 inches for the 24 hours ending 0800 local time on the 17th. This value falls into the 90 percent confidence interval (7.01-8.37 inches) for a 25-year average recurrence interval (.04 annual exceedance probability) per NOAA Atlas 2.');
INSERT INTO public.stormevents_east VALUES (781800, 201808, 14, 941, 201808, 14, 1141, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 09:41:00', 'EST-5', '14-AUG-18 11:41:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'RAILROAD MILLS', 2, 'ENE', 'RAILROAD MILLS', 43.0391, -77.4598, 43.0409, -77.4591, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Route 96 was closed at Woodcliff Drive due to flooding.');
INSERT INTO public.stormevents_east VALUES (782235, 201808, 14, 1535, 201808, 14, 1635, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 15:35:00', 'EST-5', '14-AUG-18 16:35:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'PULASKI', 1, 'N', 'PULASKI', 43.58, -76.13, 43.5805, -76.1277, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'North Street was reported flooded and closed.');
INSERT INTO public.stormevents_east VALUES (768544, 201808, 12, 1315, 201808, 12, 1315, 128145, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '12-AUG-18 13:15:00', 'EST-5', '12-AUG-18 13:15:00', 0, 0, 0, 0, '0.00K', NULL, 'Broadcast Media', 1.25, NULL, NULL, NULL, 0, 'N', 'MADISON HGTS', 0, 'N', 'MADISON HGTS', 37.42, -79.13, 37.42, -79.13, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Hail up to the size of half dollar coins fell in Madison Heights.');
INSERT INTO public.stormevents_east VALUES (768589, 201808, 13, 1447, 201808, 13, 1447, 128152, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '13-AUG-18 14:47:00', 'EST-5', '13-AUG-18 14:47:00', 0, 0, 0, 0, '0.60K', NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'SE', 'FALLING SPG', 1, 'SE', 'FALLING SPG', 37.8721, -79.973, 37.8721, -79.973, 'A closed upper level low helped to trigger scattered severe thunderstorms during the afternoon.  These storms blew down a number of trees and produced hail up to the size of quarters.', 'Thunderstorm winds blew down several large tree limbs at the Cliff View Golf Club and Inn.');
INSERT INTO public.stormevents_east VALUES (807275, 201812, 15, 2120, 201812, 15, 2320, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 21:20:00', 'EST-5', '15-DEC-18 23:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'ADEN', 3, 'SW', 'ADEN', 38.6145, -77.5553, 38.6201, -77.557, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Fleetwood Drive near Sowego Road impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (775563, 201808, 3, 2231, 201808, 4, 31, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:31:00', 'EST-5', '04-AUG-18 00:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'WADESVILLE', 2, 'SSW', 'WADESVILLE', 39.23, -78.05, 39.224, -78.0516, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-761 Old Charles Town Road was closed due to flooding at Opequon Creek.');
INSERT INTO public.stormevents_east VALUES (775565, 201808, 3, 2232, 201808, 4, 32, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:32:00', 'EST-5', '04-AUG-18 00:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'STONY PT', 1, 'NW', 'STONY PT', 38.13, -78.39, 38.129, -78.3956, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-600 Watts Passage Road was closed at Preddy Creek due to flooding.');
INSERT INTO public.stormevents_east VALUES (775566, 201808, 3, 2244, 201808, 4, 44, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:44:00', 'EST-5', '04-AUG-18 00:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'MEADOW MILLS', 1, 'SW', 'MIDDLETOWN', 39.02, -78.3, 39.0253, -78.2877, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-624 Meadow Mills Road was closed at Meadow Brook near VA-625 Veterans Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (775568, 201808, 3, 2244, 201808, 4, 44, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:44:00', 'EST-5', '04-AUG-18 00:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'MIDDLETOWN', 0, 'N', 'MIDDLETOWN', 39.0326, -78.2798, 39.033, -78.28, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Route 627 Chapel Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (775570, 201808, 3, 2244, 201808, 4, 44, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:44:00', 'EST-5', '04-AUG-18 00:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'MIDDLETOWN', 1, 'NE', 'MIDDLETOWN', 39.04, -78.27, 39.0383, -78.2695, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Route 634 at Route 635 Mineral Street was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (775572, 201808, 3, 2244, 201808, 4, 44, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:44:00', 'EST-5', '04-AUG-18 00:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CAUNTERBURG', 0, 'SE', 'CAUNTERBURG', 39.05, -78.18, 39.0478, -78.1781, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Route 636 was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (782324, 201808, 29, 2057, 201808, 29, 2057, 130608, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BGM', '29-AUG-18 20:57:00', 'EST-5', '29-AUG-18 20:57:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'UNION CENTER', 0, 'N', 'UNION CENTER', 42.15, -76.07, 42.15, -76.07, 'A line of strong to severe thunderstorms moved across central New York during the evening hours ahead of a strong cold front.', 'Thunderstorm winds blew down trees.');
INSERT INTO public.stormevents_east VALUES (775992, 201808, 13, 1729, 201808, 13, 1929, 129512, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '13-AUG-18 17:29:00', 'EST-5', '13-AUG-18 19:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ROGERS FORGE', 1, 'SSW', 'ROGERS FORGE', 39.4, -76.62, 39.3932, -76.6058, 'Upper-level low pressure remained over the region while a warm and humid air mass was in place. This resulted in showers and thunderstorms, some of which produced locally heavy rainfall.', 'Two water rescues occurred due to motorists trapped in high water in the Towson area.');
INSERT INTO public.stormevents_east VALUES (775993, 201808, 13, 1730, 201808, 13, 1930, 129512, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '13-AUG-18 17:30:00', 'EST-5', '13-AUG-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'PARKVILLE', 2, 'WSW', 'PARKVILLE', 39.3699, -76.5829, 39.3705, -76.5826, 'Upper-level low pressure remained over the region while a warm and humid air mass was in place. This resulted in showers and thunderstorms, some of which produced locally heavy rainfall.', 'About a dozen cars were flooded and lifted off Loch Raven Boulevard near Walker Avenue.');
INSERT INTO public.stormevents_east VALUES (781409, 201808, 7, 2312, 201808, 7, 2312, 130525, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '07-AUG-18 23:12:00', 'EST-5', '07-AUG-18 23:12:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 39, 'MG', NULL, NULL, 1, 'N', 'WIGGINS PASS', 1, 'N', 'WIGGINS PASS', 26.2999, -81.8243, 26.2999, -81.8243, 'The presence of a nearby tropical upper level low in the Gulf of Mexico brought colder than normal temperatures aloft, leading to a few stronger storms along the Gulf coast late in the day. These storms produced a strong wind gust as they moved offshore the Collier County coast late in the evening.', 'A thunderstorm wind gust of 45 mph/39 kts was recorded at 1212 am EDT at Kalea Bay, Vanderbilt Beach, mesonet site KBNPS.');
INSERT INTO public.stormevents_east VALUES (781414, 201808, 9, 2003, 201808, 9, 2003, 130527, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'MFL', '09-AUG-18 20:03:00', 'EST-5', '09-AUG-18 20:03:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 7, 'NNE', 'CANAL PT', 7, 'NNE', 'CANAL PT', 26.95, -80.6, 26.95, -80.6, 'While storm coverage was limited, dry air from the Saharan Air Layer helped enhance the strength of afternoon showers and storms. Activity that developed along the east coast seabreeze in Miami-Dade County early in the afternoon produced numerous reports of hail over the western suburbs of Miami metro area from Doral to West Kendall. Winds were recorded in the 40-50 mph range. Additional storms across Palm Beach County later in the afternoon and evening produced wind damage around Lake Okeechobee.', 'Member of public, an employee of local business, reports numerous large tree branches down, 6-inches in diameter and greater. Also, the top of a palm tree was snapped off. Time estimated based on Doppler radar.');
INSERT INTO public.stormevents_east VALUES (783645, 201809, 6, 1534, 201809, 6, 1534, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 15:34:00', 'EST-5', '06-SEP-18 15:34:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'ENE', 'METCALF', 1, 'ENE', 'METCALF', 42.1833, -71.4312, 42.1833, -71.4312, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 3:34 PM EST, wind brought a tree down on Highland Street in the Rolling Meadow area.');
INSERT INTO public.stormevents_east VALUES (783646, 201809, 6, 1540, 201809, 6, 1540, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 15:40:00', 'EST-5', '06-SEP-18 15:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'ENE', 'MEDWAY', 1, 'ENE', 'MEDWAY', 42.1339, -71.3893, 42.1339, -71.3893, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 3:40 PM EST, wind brought a tree and wires down on Fuller Place in the northern end of Franklin.');
INSERT INTO public.stormevents_east VALUES (783647, 201809, 6, 1541, 201809, 6, 1541, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 15:41:00', 'EST-5', '06-SEP-18 15:41:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NE', 'WEST MEDWAY', 1, 'NE', 'WEST MEDWAY', 42.1581, -71.4203, 42.1581, -71.4203, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 3:41 PM EST, wind brought a large tree down on Lovering Street in Medway.');
INSERT INTO public.stormevents_east VALUES (783648, 201809, 6, 1559, 201809, 6, 1559, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 15:59:00', 'EST-5', '06-SEP-18 15:59:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'ENDICOTT', 1, 'SW', 'ENDICOTT', 42.2186, -71.1907, 42.2186, -71.1907, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 3:59 PM EST, wind brought a tree down on School Street in Westwood.');
INSERT INTO public.stormevents_east VALUES (783649, 201809, 6, 1600, 201809, 6, 1600, 130988, 'MASSACHUSETTS', 25, 2018, 'September', 'Thunderstorm Wind', 'BOX', '06-SEP-18 16:00:00', 'EST-5', '06-SEP-18 16:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NNW', 'FOXBOROUGH', 1, 'NNW', 'FOXBOROUGH', 42.0832, -71.2592, 42.0832, -71.2592, 'A cold front moved into very warm humid air over Massachusetts on September 6th. This brought showers and strong thunderstorms to the region during the afternoon and evening.', 'At 4 PM EST, wind brought a tree down on wires on North Street in Foxborough.');
INSERT INTO public.stormevents_east VALUES (783661, 201809, 12, 1237, 201809, 12, 1600, 130995, 'MASSACHUSETTS', 25, 2018, 'September', 'Flood', 'BOX', '12-SEP-18 12:37:00', 'EST-5', '12-SEP-18 16:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ATTLEBORO', 1, 'NNW', 'ATTLEBORO', 41.9474, -71.2883, 41.9469, -71.2878, 'An upper level disturbance moved over Massachusetts, tapping warm and very humid air to generate a few thunderstorms, some with heavy downpours.  Rainfall of up to four inches fell on Massachusetts.', 'At 12:37 PM, heavy rain caused street flooding at the intersection of Peck Street and North Main Street in Attleboro.  A car was trapped in the floodwaters.');
INSERT INTO public.stormevents_east VALUES (783670, 201809, 12, 1200, 201809, 12, 1600, 130996, 'CONNECTICUT', 9, 2018, 'September', 'Flood', 'BOX', '12-SEP-18 12:00:00', 'EST-5', '12-SEP-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'WEST HARTFORD', 1, 'WNW', 'WEST HARTFORD', 41.7594, -72.7513, 41.7595, -72.7508, 'An upper level disturbance moved over Connecticut, tapping warm and very humid air to generate a few thunderstorms, some with heavy downpours. Rainfall of up to five inches fell on northern Connecticut.', 'At 12 PM EST, the intersection of Arlington Road and Farmington Avenue in West Hartford was under two feet of water.');
INSERT INTO public.stormevents_east VALUES (784233, 201809, 25, 1930, 201809, 25, 2000, 131100, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 19:30:00', 'EST-5', '25-SEP-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'BELLE TERRE', 0, 'SSE', 'BELLE TERRE', 40.9447, -73.0688, 40.945, -73.0675, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City by late morning. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Rainfall amounts generally ranged from 1-4 inches across New York City and Westchester County, and 2-5 inches across portions of northern Suffolk County. The ASOS at Central Park recorded 2.08 inches of rain while the ASOS at the White Plains Airport recorded 4.43 inches of rain during the event. Farther east, 4.27 inches of rain was reported by a CoCoRaHS observer in Port Jefferson Station, while a member of the public reported 4.53 inches of rain in Setauket.', 'Widespread flash flooding was reported across the village of Port Jefferson, with some of the most significant flooding occurring on Main Street near Maple Place. Water was 3-4 feed deep in several locations with multiple cars stuck in flood waters. The flooding resulted in people being rescued from both the Old Fields Restaurant on Wynn Lane and Theatre Three on Main Street, as well as damage to a combined retail/residential building located at 464 Main Street.');
INSERT INTO public.stormevents_east VALUES (784726, 201809, 25, 1932, 201809, 25, 2120, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 19:32:00', 'EST-5', '25-SEP-18 21:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'COLCHESTER', 0, 'W', 'COLCHESTER', 41.5677, -72.3454, 41.5703, -72.3395, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Route 16 near Linwood Cemetery was closed due to flooding in Colchester.');
INSERT INTO public.stormevents_east VALUES (784728, 201809, 25, 1932, 201809, 25, 2120, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 19:32:00', 'EST-5', '25-SEP-18 21:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'LEBANON', 2, 'SE', 'LEBANON', 41.6038, -72.2537, 41.6118, -72.2006, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Several roads were closed due to flooding in Lebanon, with basements reported flooded on Goshen Heights Road and Watermand Road.');
INSERT INTO public.stormevents_east VALUES (784730, 201809, 25, 1938, 201809, 25, 2008, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 19:38:00', 'EST-5', '25-SEP-18 20:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CHESTER', 1, 'NW', 'CHESTER', 41.4082, -72.459, 41.4078, -72.4591, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'The Liberty Street bridge in Chester was washed out due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (786041, 201809, 17, 1230, 201809, 17, 1230, 131365, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'AKQ', '17-SEP-18 12:30:00', 'EST-5', '17-SEP-18 12:30:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'KENBRIDGE', 2, 'E', 'KENBRIDGE', 36.97, -78.12, 36.97, -78.12, 'Scattered severe thunderstorms associated with tropical cyclone Florence produced damaging winds and ten tornadoes across portions of central and south central Virginia.', 'Trees were downed on Center Street in Kenbridge.');
INSERT INTO public.stormevents_east VALUES (786042, 201809, 17, 1513, 201809, 17, 1513, 131365, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'AKQ', '17-SEP-18 15:13:00', 'EST-5', '17-SEP-18 15:13:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 42, 'WSW', 'WELLFORD', 42, 'WSW', 'WELLFORD', 37.59, -77.45, 37.59, -77.45, 'Scattered severe thunderstorms associated with tropical cyclone Florence produced damaging winds and ten tornadoes across portions of central and south central Virginia.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (786043, 201809, 17, 1535, 201809, 17, 1535, 131365, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'AKQ', '17-SEP-18 15:35:00', 'EST-5', '17-SEP-18 15:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'NE', 'CHESTERFIELD', 1, 'NE', 'CHESTERFIELD', 37.38, -77.51, 37.38, -77.51, 'Scattered severe thunderstorms associated with tropical cyclone Florence produced damaging winds and ten tornadoes across portions of central and south central Virginia.', 'Large tree was downed.');
INSERT INTO public.stormevents_east VALUES (786216, 201809, 21, 1854, 201809, 21, 1854, 131308, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'PBZ', '21-SEP-18 18:54:00', 'EST-5', '21-SEP-18 18:54:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'BULLY HILL', 1, 'SSW', 'BULLY HILL', 41.35, -79.84, 41.35, -79.84, 'A line of thunderstorms developed along an approaching cold front. Mostly clear skies and scattered cumulus clouds helped support surface heating and instability. Temperatures got up to the mid-80s; dewpoints were in the upper 60s. MLCAPE values neared 2000 J/kg; deep layer vertical wind shear increased in the afternoon hours.The Storm Prediction Center issued Severe Thunderstorm Watches for portions of Eastern Ohio and Western PA.', 'A 911 call center reported multiple trees down in Sandy Creek Twp.');
INSERT INTO public.stormevents_east VALUES (786217, 201809, 21, 1819, 201809, 21, 1819, 131308, 'PENNSYLVANIA', 42, 2018, 'September', 'Thunderstorm Wind', 'PBZ', '21-SEP-18 18:19:00', 'EST-5', '21-SEP-18 18:19:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'FARRELL', 1, 'WNW', 'FARRELL', 41.23, -80.5, 41.23, -80.5, 'A line of thunderstorms developed along an approaching cold front. Mostly clear skies and scattered cumulus clouds helped support surface heating and instability. Temperatures got up to the mid-80s; dewpoints were in the upper 60s. MLCAPE values neared 2000 J/kg; deep layer vertical wind shear increased in the afternoon hours.The Storm Prediction Center issued Severe Thunderstorm Watches for portions of Eastern Ohio and Western PA.', 'A 911 Call Center reported multiple trees down in Sharon.');
