INSERT INTO public.stormevents_east VALUES (775390, 201807, 3, 1314, 201807, 3, 1314, 129369, 'NEW JERSEY', 34, 2018, 'July', 'Thunderstorm Wind', 'OKX', '03-JUL-18 13:14:00', 'EST-5', '03-JUL-18 13:14:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'E', 'BERGENFIELD', 1, 'E', 'BERGENFIELD', 40.9188, -74.0647, 40.9188, -74.0647, 'A pre-frontal trough ahead of an approaching cold front triggered strong to severe thunderstorms across the region.', 'Wires down closing the middle and right lanes of Route 4 eastbound from Forest Avenue to the River Edge border.');
INSERT INTO public.stormevents_east VALUES (756445, 201805, 6, 2115, 201805, 6, 2115, 126190, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'AKQ', '06-MAY-18 21:15:00', 'EST-5', '06-MAY-18 21:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'NNE', 'FIVE FORKS', 1, 'NNE', 'FIVE FORKS', 37.27, -76.76, 37.27, -76.76, 'Scattered severe thunderstorms well in advance of a frontal boundary produced damaging winds across portions of south central and southeast Virginia.', 'Trees were downed on Monticello Avenue.');
INSERT INTO public.stormevents_east VALUES (758158, 201805, 10, 1729, 201805, 10, 1729, 126404, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '10-MAY-18 17:29:00', 'EST-5', '10-MAY-18 17:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 0, 'N', 'TANGIER ISLAND', 0, 'N', 'TANGIER ISLAND', 37.83, -75.99, 37.83, -75.99, 'Scattered thunderstorms well in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 43 knots was measured at Tangier Island.');
INSERT INTO public.stormevents_east VALUES (760422, 201805, 14, 1944, 201805, 14, 1944, 126825, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '14-MAY-18 19:44:00', 'EST-5', '14-MAY-18 19:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 0, 'N', 'DELTAVILLE', 0, 'N', 'DELTAVILLE', 37.56, -76.29, 37.56, -76.29, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 40 knots was measured at Deltaville.');
INSERT INTO public.stormevents_east VALUES (761342, 201805, 22, 1906, 201805, 22, 1906, 127037, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'AKQ', '22-MAY-18 19:06:00', 'EST-5', '22-MAY-18 19:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 50, 'MG', NULL, NULL, 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 37.54, -76.02, 37.54, -76.02, 'Scattered thunderstorms in advance of a cold front produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 50 knots was measured at Rappahannock Light.');
INSERT INTO public.stormevents_east VALUES (785618, 201809, 7, 700, 201809, 10, 700, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:00:00', 'EST-5', '10-SEP-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'STEUBENVILLE', 0, 'N', 'STEUBENVILLE', 40.37, -80.62, 40.37, -80.62, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A COOP observer recorded 5.77 inches of rain for a 72 hour storm total.');
INSERT INTO public.stormevents_east VALUES (785620, 201809, 7, 630, 201809, 10, 630, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 06:30:00', 'EST-5', '10-SEP-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'ENE', 'SARAHSVILLE', 1, 'ENE', 'SARAHSVILLE', 39.8055, -81.4526, 39.8055, -81.4526, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A Mesonet recorded 4.53 inches over a 72 hour period.');
INSERT INTO public.stormevents_east VALUES (785619, 201809, 7, 700, 201809, 10, 700, 131294, 'OHIO', 39, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:00:00', 'EST-5', '10-SEP-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'WOODSFIELD', 0, 'N', 'WOODSFIELD', 39.77, -81.12, 39.77, -81.12, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across portions of southeast Ohio ranged from 3 inches to 5.5 inches.  Drier antecedent conditions and the long period over which the rain occurred prevented problems with small stream flooding for the most part.', 'A COOP Observer recorded 4.06 inches for 72 hour storm total.');
INSERT INTO public.stormevents_east VALUES (785587, 201809, 9, 2035, 201809, 10, 435, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '09-SEP-18 20:35:00', 'EST-5', '10-SEP-18 04:35:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'STRANGFORD', 2, 'W', 'BLAIRSVILLE', 40.43, -79.26, 40.4027, -79.2342, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported several roads are flooded.');
INSERT INTO public.stormevents_east VALUES (785588, 201809, 10, 30, 201809, 10, 330, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '10-SEP-18 00:30:00', 'EST-5', '10-SEP-18 03:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'CRAMER', 0, 'W', 'CRAMER', 41, -78.84, 41.0199, -78.8519, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported that the intersection of Pike Rd and Beaver Rd in Henderson Twp is flooded.');
