INSERT INTO public.stormevents_east VALUES (773792, 201807, 5, 1608, 201807, 5, 1608, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 16:08:00', 'EST-5', '05-JUL-18 16:08:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'CHANDLER', 1, 'S', 'CHANDLER', 40.31, -80.8, 40.31, -80.8, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'A 911 Call Center reported multiple trees down along County Road 23 and in Smithfield.');
