INSERT INTO public.stormevents_east VALUES (773796, 201807, 5, 1722, 201807, 5, 1722, 129094, 'OHIO', 39, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '05-JUL-18 17:22:00', 'EST-5', '05-JUL-18 17:22:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'BRIDGEPORT', 1, 'N', 'BRIDGEPORT', 40.09, -80.75, 40.09, -80.75, 'A very moist and unstable airmass lead to thunderstorms in the northeast ahead of a cold front. PWAT values continued to be high; the PBZ 12Z sounding measured 2.04 inches (this was noted to be the top 5 reading for PWAT of all time). Localized flooding continued to be the concern as the region has already had a number of rainy days prior. A Flash Flood Watch was issued by the office.', 'The Department of Highways reported trees down on U.S. 250.');
