INSERT INTO public.stormevents_east VALUES (776559, 201807, 24, 1853, 201807, 24, 1853, 129627, 'NEW YORK', 36, 2018, 'July', 'Heavy Rain', 'BUF', '24-JUL-18 18:53:00', 'EST-5', '24-JUL-18 18:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 1, 'NW', 'DUNKIRK MUNI ARPT', 1, 'NW', 'DUNKIRK MUNI ARPT', 42.49, -79.28, 42.49, -79.28, 'A moist environment was over the area with a deep and slow-moving closed low to the west. A cluster of thunderstorms developed over PA and tracked northeastward and over Allegany County. This resulted in 1 to 1.5 inches of rainfall and isolated flooding. The pattern failed to evolved through the following day, resulting in a similar setup causing flooding over Chautauqua County.', 'Rainfall of 2.17 inches total in 3 hours with 1.66 inches of that in one hour.');
INSERT INTO public.stormevents_east VALUES (776560, 201807, 25, 400, 201807, 25, 400, 129627, 'NEW YORK', 36, 2018, 'July', 'Heavy Rain', 'BUF', '25-JUL-18 04:00:00', 'EST-5', '25-JUL-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'NW', 'FREDONIA', 1, 'NW', 'FREDONIA', 42.44, -79.35, 42.44, -79.35, 'A moist environment was over the area with a deep and slow-moving closed low to the west. A cluster of thunderstorms developed over PA and tracked northeastward and over Allegany County. This resulted in 1 to 1.5 inches of rainfall and isolated flooding. The pattern failed to evolved through the following day, resulting in a similar setup causing flooding over Chautauqua County.', 'Rainfall of 3.40 inches total.');
INSERT INTO public.stormevents_east VALUES (776656, 201807, 27, 1613, 201807, 27, 1614, 129649, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'OKX', '27-JUL-18 16:13:00', 'EST-5', '27-JUL-18 16:14:00', 0, 0, 0, 0, '5.00K', NULL, 'Broadcast Media', 52, 'EG', NULL, NULL, 0, 'SSE', 'OAKWOOD HGTS', 1, 'NW', 'MIDLAND BEACH', 40.5652, -74.1261, 40.5788, -74.1099, 'A passing cold front triggered an isolated severe thunderstorm over Orange County and Staten Island.', 'Trees were reported down across the Staten Island Railroad between Oakwaood Heights and Grant City.');
INSERT INTO public.stormevents_east VALUES (773802, 201807, 15, 1445, 201807, 15, 1445, 129098, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '15-JUL-18 14:45:00', 'EST-5', '15-JUL-18 14:45:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'NNE', 'FAIRVIEW', 1, 'NNE', 'FAIRVIEW', 39.75, -80.77, 39.75, -80.77, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds were generated with mixing of dry air. Static air flow continued to create flooding potential as tropical moisture lingered.', 'The Department of Highways reported trees down near Fairview and Saint Joseph vicinity.');
INSERT INTO public.stormevents_east VALUES (773803, 201807, 15, 1730, 201807, 15, 1745, 129098, 'WEST VIRGINIA', 54, 2018, 'July', 'Flash Flood', 'PBZ', '15-JUL-18 17:30:00', 'EST-5', '15-JUL-18 17:45:00', 0, 0, 0, 0, '1.00K', '1.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 6, 'WSW', 'ST GEORGE', 5, 'W', 'MOORE', 39.14, -79.8, 39.0923, -79.8083, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds were generated with mixing of dry air. Static air flow continued to create flooding potential as tropical moisture lingered.', 'The 911 Call Center reported that Clover Run Road  and Valley Fork Roads were closed due to high water running swiftly across the roadway.');
INSERT INTO public.stormevents_east VALUES (773806, 201807, 15, 1520, 201807, 15, 1520, 129100, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '15-JUL-18 15:20:00', 'EST-5', '15-JUL-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'VENETIA', 0, 'N', 'VENETIA', 40.25, -80.05, 40.25, -80.05, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds could be generated with mixing of dry air. Static air flow continues to create flooding potential as tropical moisture lingered.', 'A trained spotter reported that several trees were snapped.');
INSERT INTO public.stormevents_east VALUES (773807, 201807, 15, 1713, 201807, 15, 1713, 129100, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '15-JUL-18 17:13:00', 'EST-5', '15-JUL-18 17:13:00', 0, 0, 0, 0, NULL, NULL, 'River/Stream Gage', 50, 'EG', NULL, NULL, 1, 'E', 'BOWER HILL', 1, 'E', 'BOWER HILL', 40.27, -80.06, 40.27, -80.06, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds could be generated with mixing of dry air. Static air flow continues to create flooding potential as tropical moisture lingered.', 'On social media, there was a report of trees down on Froebe Road and Oak Ridge Road.');
INSERT INTO public.stormevents_east VALUES (773808, 201807, 15, 1625, 201807, 15, 1625, 129100, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '15-JUL-18 16:25:00', 'EST-5', '15-JUL-18 16:25:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NE', 'LONGVIEW', 1, 'NE', 'LONGVIEW', 40.36, -80.01, 40.36, -80.01, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds could be generated with mixing of dry air. Static air flow continues to create flooding potential as tropical moisture lingered.', 'An emergency manager reported a tree down with live power lines near Linden Grove and southwest of Salida. A trained spotter also reported an uprooted tree near Longview as well as trees down along Robert Drive.');
INSERT INTO public.stormevents_east VALUES (773809, 201807, 15, 1623, 201807, 15, 1623, 129100, 'PENNSYLVANIA', 42, 2018, 'July', 'Hail', 'PBZ', '15-JUL-18 16:23:00', 'EST-5', '15-JUL-18 16:23:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 1, 'SE', 'DORMONT', 1, 'SE', 'DORMONT', 40.39, -80.02, 40.39, -80.02, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds could be generated with mixing of dry air. Static air flow continues to create flooding potential as tropical moisture lingered.', 'Social media report of nickel and quarter size hail.');
INSERT INTO public.stormevents_east VALUES (773810, 201807, 15, 1642, 201807, 15, 1642, 129100, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '15-JUL-18 16:42:00', 'EST-5', '15-JUL-18 16:42:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'E', 'MT LEBANON', 1, 'E', 'MT LEBANON', 40.38, -80.02, 40.38, -80.02, 'Thunderstorms generated as a shortwave trough sagged into our region. Despite little wind shear, damaging winds could be generated with mixing of dry air. Static air flow continues to create flooding potential as tropical moisture lingered.', 'An emergency manager reported that McNeilly Road and Pearce Road were closed due to trees and power lines being down.');
INSERT INTO public.stormevents_east VALUES (775516, 201807, 17, 1520, 201807, 17, 1520, 129439, 'NEW YORK', 36, 2018, 'July', 'Lightning', 'OKX', '17-JUL-18 15:20:00', 'EST-5', '17-JUL-18 15:20:00', 0, 0, 0, 0, '0.75K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'W', 'TERRYVILLE', 1, 'W', 'TERRYVILLE', 40.92, -73.07, 40.92, -73.07, 'A cold front approached from the west and brought a line with isolated severe thunderstorms across Westchester County.', 'Lightning struck a fence and shattered it.');
