INSERT INTO public.stormevents_east VALUES (775128, 201808, 17, 1512, 201808, 17, 1512, 129357, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 15:12:00', 'EST-5', '17-AUG-18 15:12:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NNW', 'SPRING CREEK', 1, 'NNW', 'SPRING CREEK', 38.42, -79.04, 38.42, -79.04, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'A large tree was blown down near the intersection of Spring Creek Road and George Wine Road. Another tree was also blown down in the 2100 block of West Dry River Road.');
INSERT INTO public.stormevents_east VALUES (775129, 201808, 17, 1500, 201808, 17, 1500, 129357, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 15:00:00', 'EST-5', '17-AUG-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'SW', 'BERRYVILLE', 2, 'SW', 'BERRYVILLE', 39.13, -77.99, 39.13, -77.99, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'A tree was blown down on wires near the 200 block of Smallwood Lane.');
INSERT INTO public.stormevents_east VALUES (775070, 201808, 12, 1345, 201808, 12, 1345, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 13:45:00', 'EST-5', '12-AUG-18 13:45:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'UNO', 2, 'NE', 'UNO', 38.29, -78.21, 38.29, -78.21, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'A tree was blown down in the 220 block of Locust Grove Church Road.');
