INSERT INTO public.stormevents_east VALUES (775081, 201808, 12, 1357, 201808, 12, 1357, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 13:57:00', 'EST-5', '12-AUG-18 13:57:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'ESE', 'UNO', 2, 'ESE', 'UNO', 38.26, -78.2, 38.26, -78.2, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'A tree was blown down in the 300 block of Caves Ford Lane.');
INSERT INTO public.stormevents_east VALUES (775082, 201808, 12, 1520, 201808, 12, 1520, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 15:20:00', 'EST-5', '12-AUG-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 70, 'EG', NULL, NULL, 2, 'W', 'BROOKE', 2, 'W', 'BROOKE', 38.38, -77.45, 38.38, -77.45, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'Over 50 trees were blown down between Stafford and Falmouth, including trees onto houses in the Grafton Village subdivision off Deacon Road.');
INSERT INTO public.stormevents_east VALUES (775083, 201808, 12, 1536, 201808, 12, 1536, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 15:36:00', 'EST-5', '12-AUG-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'WNW', 'GOBY', 2, 'WNW', 'GOBY', 38.33, -77.3, 38.33, -77.3, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'Multiple trees were blown down in vicinity of Belvedere Drive and Mill Pond Road.');
INSERT INTO public.stormevents_east VALUES (783568, 201809, 16, 600, 201809, 17, 600, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 06:00:00', 'EST-5', '17-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 4, 'SSW', 'SPARTA', 4, 'SSW', 'SPARTA', 36.4532, -81.1541, 36.4532, -81.1541, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'The COOP observer at Sparta (SPRN7) measured 7.64 inches for the 24-hours ending 700 AM local time on September 17th. This was the highest daily rainfall for any date on record at this station. The old record was 7.10 inches August 31, 1964. This value falls into the 90 percent confidence interval (7.02-8.57 inches) for a 50-year average recurrence interval (.02 annual exceedance probability) per NOAA Atlas 2. Continuous precipitation data began in 1942 and ended in mid-2010 but resumed in mid-2018 at this station.');
INSERT INTO public.stormevents_east VALUES (783570, 201809, 16, 600, 201809, 17, 600, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 06:00:00', 'EST-5', '17-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 5, 'ESE', 'BOONE', 5, 'ESE', 'BOONE', 36.1951, -81.6054, 36.1951, -81.6054, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'Boone 4.5 SE CoCoRaHS (NC-WT-24) station measured 6.70 inches for the 24 hours ending 0700 local time on the 17th. This value falls into the confidence interval (5.82-6.97 inches) for a 10-year average recurrence interval (.10 annual exceedance probability) per NOAA Atlas 2.');
INSERT INTO public.stormevents_east VALUES (785065, 201809, 16, 1930, 201809, 17, 130, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RNK', '16-SEP-18 19:30:00', 'EST-5', '17-SEP-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 4, 'S', 'ELLISBORO', 4, 'W', 'PRICE', 36.2738, -79.9853, 36.5414, -79.9958, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'Numerous roads were closed across the county with the first reports received around 830 PM local time. Many roads were still closed the next morning according to newspaper accounts. Jacobs Creek near Madison and Troublesome Creek near Reidsville were both reported out of their banks and flooding nearby areas.');
INSERT INTO public.stormevents_east VALUES (785069, 201809, 17, 100, 201809, 17, 1545, 130243, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RNK', '17-SEP-18 01:00:00', 'EST-5', '17-SEP-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'W', 'PRICE', 4, 'W', 'PRICE', 36.5413, -79.9945, 36.54, -79.9865, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as a Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The first rainfall of any significance was during the late afternoon and evening of the 14th as several outer bands of Florence affected mainly Rockingham and Caswell counties with 24-hour totals ending 12z (700 AM) on the 15th of 1 to 2 inches, with much lower amounts to the northwest.  The next 24 hours (ending 12z on the 16th) saw heavier rains still mainly over the NC Piedmont counties with about 1 to 3 inches falling. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in North Carolina within the HSA were over parts of Alleghany County with up to 8 inches in 24 hours (ending at 700 AM on the 17th) and over 10 inches storm total. The highest gage report was from Glade Creek VFD DCP (GLCN7) with 10.99 inches in the 72-hour period ending 700 AM on the 18th.', 'The river gage on the Mayo River near Price, NC (PRIN7) in northwest Rockingham County rose above the flood stage of 8 feet and crested in the Moderate flood category at 11.20 feet (13,600 cfs) mid-morning of the 17th. This was the 6th highest stage on record at this gage with over 65 years of data. According to USGS analysis, the flood frequency for the event was between a 5- and 10-year (0.2 to 0.1 annual chance of occurrence). Parts of Mayo Beach Road near the river were flooded.');
INSERT INTO public.stormevents_east VALUES (778173, 201808, 22, 1336, 201808, 22, 1336, 129901, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '22-AUG-18 13:36:00', 'EST-5', '22-AUG-18 13:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 6, 'S', 'MID BAY BUOY', 6, 'S', 'MID BAY BUOY', 38.38, -76.376, 38.38, -76.376, 'A strong upper level trough produced scattered showers and isolated thunderstorms, one of which brought strong winds over the waters.', 'A wind gust of 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (781046, 201809, 28, 345, 201809, 28, 800, 130484, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'RLX', '28-SEP-18 03:45:00', 'EST-5', '28-SEP-18 08:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'ELKVIEW', 1, 'NNE', 'CLENDENIN', 38.4598, -81.4664, 38.4979, -81.337, 'On the 23rd a surface boundary was stalled across southern West Virginia. It slowly moved north as a warm front on the 24th and 25th as a surface low crossed the region. This low then pushed a cold front through on the 26th and 27th. Atmospheric moisture was anomalously high throughout the period, leading to multiple rounds of moderate to heavy rain which caused flooding issues across parts of the state.', 'The Elk River at Queen Shoals rose above its 19 foot flood stage early on the 28th. It crested in minor flood around 19.3 feet around sunrise that morning and returned within its banks by mid-morning. This also caused flooding on Spencer Road in Clendenin.');
INSERT INTO public.stormevents_east VALUES (782492, 201809, 27, 1900, 201809, 28, 234, 130484, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'RLX', '27-SEP-18 19:00:00', 'EST-5', '28-SEP-18 02:34:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'HYERS', 1, 'NNE', 'BURNSVILLE', 38.8726, -80.6807, 38.8648, -80.6457, 'On the 23rd a surface boundary was stalled across southern West Virginia. It slowly moved north as a warm front on the 24th and 25th as a surface low crossed the region. This low then pushed a cold front through on the 26th and 27th. Atmospheric moisture was anomalously high throughout the period, leading to multiple rounds of moderate to heavy rain which caused flooding issues across parts of the state.', 'The Little Kanawha River at Burnsville crested in minor flood stage during the late evening of the 27th, flooding low areas along Buffalo Creek Road. The river gage indicated the river rose above its 13 foot flood stage just before sunset on the 27th, and crested around 14.4 feet that night. The river had returned to its banks a couple hours after midnight on the 28th.');
INSERT INTO public.stormevents_east VALUES (782491, 201809, 28, 300, 201809, 28, 400, 130484, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'RLX', '28-SEP-18 03:00:00', 'EST-5', '28-SEP-18 04:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'MILL CREEK', 1, 'WNW', 'HUTTONSVILLE', 38.7508, -79.9912, 38.7252, -80.0033, 'On the 23rd a surface boundary was stalled across southern West Virginia. It slowly moved north as a warm front on the 24th and 25th as a surface low crossed the region. This low then pushed a cold front through on the 26th and 27th. Atmospheric moisture was anomalously high throughout the period, leading to multiple rounds of moderate to heavy rain which caused flooding issues across parts of the state.', 'County Route 39 flooded just outside of Mill Creek as the Tygart Valley River just touched its 11 foot flood stage. The stream gage on the river showed a crest of right at 11 feet during the middle of the night.');
INSERT INTO public.stormevents_east VALUES (782493, 201809, 27, 2251, 201809, 28, 1634, 130484, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'RLX', '27-SEP-18 22:51:00', 'EST-5', '28-SEP-18 16:34:00', 0, 0, 0, 0, '5.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'REVEL', 1, 'NNE', 'SAND FORK', 38.9587, -80.8586, 38.9349, -80.7411, 'On the 23rd a surface boundary was stalled across southern West Virginia. It slowly moved north as a warm front on the 24th and 25th as a surface low crossed the region. This low then pushed a cold front through on the 26th and 27th. Atmospheric moisture was anomalously high throughout the period, leading to multiple rounds of moderate to heavy rain which caused flooding issues across parts of the state.', 'Flooding along the Little Kanawha River in Glenville closed several roads in town, including River Street, South Lewis Street and Main Street. Water also reached the foundation of the motel on South Court Street. The river gage at Glenville showed the river rose above its 23 foot flood stage just before midnight on the 27th. The river crested in moderate flooding, around 27.4 feet around sunrise on the 28th and then returned to its banks late that afternoon.');
INSERT INTO public.stormevents_east VALUES (783262, 201809, 1, 600, 201809, 2, 600, 129856, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '01-SEP-18 06:00:00', 'EST-5', '02-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'APPOMATTOX', 0, 'N', 'APPOMATTOX', 37.35, -78.83, 37.35, -78.83, 'A stationary boundary through the Mid-Atlantic into the Mid-Mississippi Valley spawned thunderstorms in the afternoon and evening of August 31st that carried over into the early morning hours of September 1st . Storms were mainly across the foothills and southside Virginia with radar estimated rainfall of 1 to 2.5 inches in a few hours.  Top rain gage reports ending at 0700 EDT on the 1st included 2.28��� at Woolwine 3.7 NNE CCR (VA-PR-6), 1.98��� at Woolwine COOP (WLWV2), 1.74��� at Smith R. Fieldale IFLOWS (SRVV2), 1.50��� at Martinsville COOP (MARV2), and 1.11��� at Meadows Church IFLOWS (MEAV2). Dissipation of the storms prior to daybreak allowed for enough heating during the day to destabilize the region again for another round of thunderstorms during the afternoon in the same areas near the stationary boundary. The late afternoon storms on the 1st dropped 2-3 inches in a few hours across parts of eastern Campbell, western Charlotte and southern Appomattox counties.', 'The COOP station at Appomattox, VA (APXV2) measured 2.92 inches for the 24-hour period ending 700 AM local time on September 2nd. This was the highest ever for the date (the old record was 1.30 inches in 1957) and the 11th highest ever in the month of September. Nearly continuous data back to 1938 exists at this location.');
INSERT INTO public.stormevents_east VALUES (787613, 201809, 1, 600, 201809, 2, 600, 129856, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '01-SEP-18 06:00:00', 'EST-5', '02-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 60, 'SE', 'LONGDALE FURNACE', 60, 'SE', 'LONGDALE FURNACE', 37.3261, -78.8274, 37.3261, -78.8274, 'A stationary boundary through the Mid-Atlantic into the Mid-Mississippi Valley spawned thunderstorms in the afternoon and evening of August 31st that carried over into the early morning hours of September 1st . Storms were mainly across the foothills and southside Virginia with radar estimated rainfall of 1 to 2.5 inches in a few hours.  Top rain gage reports ending at 0700 EDT on the 1st included 2.28��� at Woolwine 3.7 NNE CCR (VA-PR-6), 1.98��� at Woolwine COOP (WLWV2), 1.74��� at Smith R. Fieldale IFLOWS (SRVV2), 1.50��� at Martinsville COOP (MARV2), and 1.11��� at Meadows Church IFLOWS (MEAV2). Dissipation of the storms prior to daybreak allowed for enough heating during the day to destabilize the region again for another round of thunderstorms during the afternoon in the same areas near the stationary boundary. The late afternoon storms on the 1st dropped 2-3 inches in a few hours across parts of eastern Campbell, western Charlotte and southern Appomattox counties.', 'The COOP station at Appomattox (APXV2) measured 2.92 inches for the 24-hour period ending 700 AM local time on September 2nd. It was the highest rainfall for this date with records dating back to 1937.');
INSERT INTO public.stormevents_east VALUES (784705, 201809, 25, 1530, 201809, 25, 1845, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 15:30:00', 'EST-5', '25-SEP-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'EAST NORWALK', 1, 'N', 'EAST NORWALK', 41.1106, -73.4024, 41.1088, -73.4019, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'I-95 was closed southbound at Exit 16 (East Avenue) in East Norwalk due to flooding. A car was stuck in the water with police on the scene.');
INSERT INTO public.stormevents_east VALUES (784706, 201809, 25, 1615, 201809, 25, 1845, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 16:15:00', 'EST-5', '25-SEP-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'SPORT HILL', 2, 'SE', 'SPORT HILL', 41.2075, -73.2279, 41.2078, -73.2273, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'The Horse Haven Brook was over its banks and flooding the area of Park Avenue and Brion Drive in Toilsome Hill. Multiple cars were submerged in several feet of flowing flood waters.');
INSERT INTO public.stormevents_east VALUES (784707, 201809, 25, 1649, 201809, 25, 1845, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 16:49:00', 'EST-5', '25-SEP-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'SPORT HILL', 2, 'SSE', 'SPORT HILL', 41.2055, -73.2427, 41.2057, -73.2422, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Numerous people were trapped in vehicles on Bennett Street in Fairfield due to flood waters.');
INSERT INTO public.stormevents_east VALUES (785371, 201809, 9, 2045, 201809, 10, 115, 131268, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'AKQ', '09-SEP-18 20:45:00', 'EST-5', '10-SEP-18 01:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'EXMORE', 1, 'E', 'NASSAWADOX', 37.53, -75.82, 37.473, -75.8433, 'Scattered showers and thunderstorms along a stationary boundary produced heavy rain which caused flash flooding across portions of the Virginia Eastern Shore.', 'High water was covering numerous roads in Exmore. Debris was floating down Virginia Avenue. Radar estimates indicated that up to three to four inches of rain had fallen in the area.');
INSERT INTO public.stormevents_east VALUES (751123, 201805, 4, 1747, 201805, 4, 1747, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 17:47:00', 'EST-5', '04-MAY-18 17:47:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'GRAVESVILLE', 1, 'NE', 'GRAVESVILLE', 43.26, -75.11, 43.26, -75.11, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Several trees were reported down.');
INSERT INTO public.stormevents_east VALUES (751124, 201805, 4, 1758, 201805, 4, 1758, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 17:58:00', 'EST-5', '04-MAY-18 17:58:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'LONG LAKE', 0, 'N', 'LONG LAKE', 43.97, -74.42, 43.97, -74.42, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees were reported down.');
INSERT INTO public.stormevents_east VALUES (751423, 201805, 4, 1942, 201805, 4, 1942, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:42:00', 'EST-5', '04-MAY-18 19:42:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'E', 'CLINTON HGTS', 1, 'E', 'CLINTON HGTS', 42.62, -73.73, 42.62, -73.73, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Route 20 was closed at Madison Avenue due to a downed power pole.');
INSERT INTO public.stormevents_east VALUES (783754, 201809, 18, 1008, 201809, 18, 1408, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 10:08:00', 'EST-5', '18-SEP-18 14:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'WATERTOWN', 0, 'WSW', 'WATERTOWN', 42.3691, -71.1857, 42.3685, -71.1848, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 10:08 AM EST, Summer Street in Watertown was flooded near the intersection with Winter Street.');
INSERT INTO public.stormevents_east VALUES (786784, 201809, 18, 1050, 201809, 18, 1400, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 10:50:00', 'EST-5', '18-SEP-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WOLLASTON', 1, 'SE', 'WOLLASTON', 42.2585, -71.0024, 42.2587, -71.0018, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 10:50 AM EST, the Southern Artery at Greenleaf Street in Quincy was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786791, 201809, 18, 1156, 201809, 18, 1500, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 11:56:00', 'EST-5', '18-SEP-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'BOSTON NAVAL SHIPYAR', 1, 'SSW', 'BOSTON NAVAL SHIPYAR', 42.3645, -71.0785, 42.361, -71.0829, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 11:56 AM EST, Longfellow Bridge and Memorial Drive in Cambridge were closed in both directions due to flooding.');
INSERT INTO public.stormevents_east VALUES (786833, 201809, 26, 2125, 201809, 26, 2355, 131524, 'MASSACHUSETTS', 25, 2018, 'September', 'Flood', 'BOX', '26-SEP-18 21:25:00', 'EST-5', '26-SEP-18 23:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'BRIGHTWOOD', 2, 'WNW', 'BRIGHTWOOD', 42.1299, -72.6359, 42.1291, -72.637, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Massachusetts with 3 to 6 inches observed in Northern Bristol County and Northern Plymouth County in Southeast Massachusetts.  Amounts of 1 to 3 inches fell on Northeast, Central and Western Massachusetts.', 'At 9:25 PM EST, Piper Cross Road in West Springfield was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (785605, 201809, 7, 800, 201809, 10, 800, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'E', 'WEIRTON', 1, 'E', 'WEIRTON', 40.4, -80.561, 40.4, -80.561, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A 72 hr storm total of 4.33 inches of rain.');
INSERT INTO public.stormevents_east VALUES (785606, 201809, 7, 800, 201809, 10, 435, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 04:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'MANNINGTON', 0, 'N', 'MANNINGTON', 39.53, -80.33, 39.53, -80.33, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A 72 storm total of 3.92 inches of rain was recorded.');
INSERT INTO public.stormevents_east VALUES (785607, 201809, 7, 600, 201809, 10, 600, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 06:00:00', 'EST-5', '10-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'NW', 'LAUREL IRON WORKS', 2, 'NW', 'LAUREL IRON WORKS', 39.7179, -79.8582, 39.7179, -79.8582, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A 72 hour storm total of 4.40 inches was recorded.');
INSERT INTO public.stormevents_east VALUES (778175, 201808, 8, 2112, 201808, 8, 2112, 129891, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '08-AUG-18 21:12:00', 'EST-5', '08-AUG-18 21:12:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 4, 'SSW', '(KMTN)MARTIN STATE AIRPORT', 4, 'SSW', '(KMTN)MARTIN STATE AIRPORT', 39.272, -76.445, 39.272, -76.445, 'An upper level trough and surface cold front combined with high instability to produce thunderstorms, some of which strong winds over the waters.', 'A wind gust of 36 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778176, 201808, 8, 2203, 201808, 8, 2203, 129891, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '08-AUG-18 22:03:00', 'EST-5', '08-AUG-18 22:03:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'LOWER HOOPERS ISLAND (HPR)', 0, 'N', 'LOWER HOOPERS ISLAND (HPR)', 38.26, -76.18, 38.26, -76.18, 'An upper level trough and surface cold front combined with high instability to produce thunderstorms, some of which strong winds over the waters.', 'A wind gust to 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778177, 201808, 13, 1536, 201808, 13, 1536, 129894, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '13-AUG-18 15:36:00', 'EST-5', '13-AUG-18 15:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 1, 'WNW', 'GREENBERRY POINT (GBY)', 1, 'WNW', 'GREENBERRY POINT (GBY)', 38.973, -76.47, 38.973, -76.47, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms produced strong winds over the waters.', 'A wind gust of 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778471, 201808, 21, 1410, 201808, 21, 1610, 129519, 'DISTRICT OF COLUMBIA', 11, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 14:10:00', 'EST-5', '21-AUG-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'ANACOSTIA', 1, 'WSW', 'ANACOSTIA', 38.8634, -76.9914, 38.8634, -76.9912, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'MLK Jr. Avenue was closed due to high water at the intersection with Morris Road Southeast.');
INSERT INTO public.stormevents_east VALUES (778473, 201808, 21, 1410, 201808, 21, 1610, 129519, 'DISTRICT OF COLUMBIA', 11, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 14:10:00', 'EST-5', '21-AUG-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'MOUNT PLEASANT', 1, 'NE', 'MOUNT PLEASANT', 38.9405, -77.0351, 38.9406, -77.0347, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Piney Branch Parkway was closed due to high water near the intersection with Arkansas Avenue Northwest.');
INSERT INTO public.stormevents_east VALUES (780637, 201808, 30, 1615, 201808, 30, 1815, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 16:15:00', 'EST-5', '30-AUG-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'ELKTON', 1, 'SSW', 'ELKTON', 38.4064, -78.6469, 38.4113, -78.6268, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'Route 33 flooded near Old Spotswood Trail and Rockingham Pike.');
INSERT INTO public.stormevents_east VALUES (780638, 201808, 30, 1630, 201808, 30, 1830, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 16:30:00', 'EST-5', '30-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'MOSCOW', 0, 'S', 'MOSCOW', 38.3143, -79.0779, 38.3162, -79.0794, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'A family was rescued from a vehcile stranded in high water near North River Elementary School.');
INSERT INTO public.stormevents_east VALUES (780639, 201808, 30, 1650, 201808, 30, 1850, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 16:50:00', 'EST-5', '30-AUG-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'MT SOLON', 1, 'SW', 'MT SOLON', 38.3356, -79.0933, 38.3371, -79.0919, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'Mossy Creek was out of its banks flooding Whetstone Draft Road.');
INSERT INTO public.stormevents_east VALUES (780640, 201808, 30, 1725, 201808, 30, 1925, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 17:25:00', 'EST-5', '30-AUG-18 19:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'MOSCOW', 2, 'SE', 'MOSCOW', 38.3075, -79.0385, 38.2984, -79.0485, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'Long Glade Creek was out of its banks. Nash Road was closed.');
INSERT INTO public.stormevents_east VALUES (780642, 201808, 30, 2042, 201808, 30, 2242, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 20:42:00', 'EST-5', '30-AUG-18 22:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'PARNASSUS', 1, 'NW', 'PARNASSUS', 38.3164, -79.1333, 38.3125, -79.1335, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'George Waltons Road was closed due to high water and Buck Hill Road was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (780643, 201808, 30, 2042, 201808, 30, 2242, 130414, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '30-AUG-18 20:42:00', 'EST-5', '30-AUG-18 22:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'STOKESVILLE', 1, 'ENE', 'STOKESVILLE', 38.3544, -79.1333, 38.3541, -79.1333, 'A weak cold front stalled out nearby. Showers and thunderstorms developed ahead of the boundary. A slow storm motion along with copious amounts of moisture led to heavy rainfall.', 'Kyles Mill Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (785579, 201809, 9, 2258, 201809, 10, 258, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '09-SEP-18 22:58:00', 'EST-5', '10-SEP-18 02:58:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'INDEPENDENCE', 1, 'S', 'INDEPENDENCE', 40.57, -80.31, 40.5539, -80.3222, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported several roads were closed due to flooding in Independence.');
INSERT INTO public.stormevents_east VALUES (785625, 201809, 7, 700, 201809, 10, 700, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:00:00', 'EST-5', '10-SEP-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'NE', 'SCHENLEY', 0, 'NE', 'SCHENLEY', 40.683, -79.667, 40.683, -79.667, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A COOP Observer recorded a 72 hr storm total of 5.82 inches at the Freeport Dam.');
INSERT INTO public.stormevents_east VALUES (785626, 201809, 7, 725, 201809, 10, 725, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:25:00', 'EST-5', '10-SEP-18 07:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'E', 'EASTVALE', 2, 'E', 'EASTVALE', 40.77, -80.2618, 40.77, -80.2618, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 72 hr storm total of 5.28 inches was recorded by a CoCoRaHS observer.');
INSERT INTO public.stormevents_east VALUES (772437, 201807, 2, 1825, 201807, 2, 1945, 128625, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '02-JUL-18 18:25:00', 'EST-5', '02-JUL-18 19:45:00', 0, 0, 0, 0, '1.30M', '100.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'HARMERVILLE', 1, 'NW', 'SANDY CREEK', 40.5458, -79.8683, 40.4899, -79.8629, 'A line of thunderstorms developed east of Cleveland from a breeze off of Lake Erie near 17Z. Areas south and east of the line gave way to more storms as outflow boundaries converged. With high PWAT values (near 1.90) flash flooding became an issue with training storms. |Wet microbursts were also a concern with DCAPE values near 500kjg-1. The Weather Prediction Center had our region under a slight risk for excessive rainfall.', 'The 911 Call Center reported flooded intersection near Squaw Run Road/Field Club Road and at the intersection Fairview Road and Old Mill Road. An emergency manager also reported rushing water near Woodland Farms Road. Fox Chapel Stone Supply INC worker says the store took on 2 ft of water (WPXI reported). Aspinwall declared a state of emergency. The O''Hara Township manager reported that some homes may be total losses; said total infrastructure losses in the township added up to $1.3 million.');
INSERT INTO public.stormevents_east VALUES (772450, 201807, 3, 1550, 201807, 3, 1550, 128785, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '03-JUL-18 15:50:00', 'EST-5', '03-JUL-18 15:50:00', 0, 0, 0, 0, NULL, NULL, 'County Official', 55, 'EG', NULL, NULL, 0, 'N', 'THOMAS', 0, 'N', 'THOMAS', 39.15, -79.5, 39.15, -79.5, 'Rich tropical moisture remained across the Northeast region. Precipitable water values continued to be high at 1.90 to 2.00 inches. Morning soundings showed very little upper level flow. A static atmosphere prompted a risk for flooding; storms that developed tended to move very little. Isolated wet microbursts were a potential due to CAPE values over 2000 J/kg. Storms developed from outflow boundaries and light convergence aloft.', 'A county official reported trees down on Buckston Road and 2nd Street in Thomas.');
INSERT INTO public.stormevents_east VALUES (772451, 201807, 3, 1826, 201807, 3, 1826, 128786, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '03-JUL-18 18:26:00', 'EST-5', '03-JUL-18 18:26:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'N', 'HOPWOOD', 1, 'N', 'HOPWOOD', 39.88, -79.72, 39.88, -79.72, 'Rich tropical moisture remained across the Northeast region. Precipitable water values continued to be high at 1.90 to 2.00 inches. Morning soundings showed very little upper level flow. A static atmosphere prompted a risk for flooding; storms that developed tended to move very little. Isolated wet microbursts were a potential due to CAPE values over 2000 J/kg. Storms developed from outflow boundaries and light convergence aloft.', 'The 911 Call Center reported that a tree fell on a car in Uniontown Country Club. A number of other trees were reported down across Uniontown. East Fayette Street was closed for a period of time due to trees being down.');
INSERT INTO public.stormevents_east VALUES (772455, 201807, 4, 1905, 201807, 4, 1905, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '04-JUL-18 19:05:00', 'EST-5', '04-JUL-18 19:05:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'E', 'ETNA', 2, 'E', 'ETNA', 40.5, -79.94, 40.5, -79.94, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'The 911 Call Center reported trees down near Route 28 at the Sharpsburg Exit. A old garage also collapsed into a roadway on Kittanning Street.');
INSERT INTO public.stormevents_east VALUES (806301, 201812, 15, 2025, 201812, 16, 730, 133711, 'DISTRICT OF COLUMBIA', 11, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 20:25:00', 'EST-5', '16-DEC-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'WALTER REED', 1, 'SW', 'WALTER REED', 38.966, -77.0466, 38.9667, -77.0486, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The stream gage on Rock Creek at Sherrill Drive/DC exceeded the 7 foot flood stage during the indicated period. Water reached several portions of the Valley Trail between Picnic Areas 7 and 10 in Rock Creek Park, and completely covered the Rolling Meadows Trailbridge. The peak level of 8.02 feet occurred at 3:45 AM on the 16th.');
INSERT INTO public.stormevents_east VALUES (806295, 201812, 16, 121, 201812, 16, 623, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 01:21:00', 'EST-5', '16-DEC-18 06:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'RAPIDAN', 1, 'NW', 'RAPIDAN', 38.3266, -78.0824, 38.3283, -78.0797, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Robinson River at Locust Dale exceeded the 11 foot flood stage during the indicated period. Water covered a portion of Route 721 (Robinson River Road). Agricultural flooding was also observed. The peak level of 11.91 feet occurred at 3:45 AM on the 16th.');
INSERT INTO public.stormevents_east VALUES (806306, 201812, 22, 2003, 201812, 23, 2337, 133753, 'MARYLAND', 24, 2018, 'December', 'Flood', 'LWX', '22-DEC-18 20:03:00', 'EST-5', '23-DEC-18 23:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'SENECA', 2, 'S', 'SENECA', 39.0706, -77.334, 39.0554, -77.3351, 'Following immediately on the heels of the system that produced flooding on the 20th in VA, another wave of low pressure tracked up along the spine of the Appalachians on the 21st. Showers and thunderstorms moved across the area during the afternoon hours of the 21st, locally producing an additional 1-2 inches of rain on top of previously saturated soils. This rainfall eventually led to some larger-stem river flooding on the 22nd and 23rd as the runoff drained downstream.', 'The river gage on the Potomac River at Edwards Ferry exceeded the 15 foot flood stage during the indicated period. Water reached the boat ramp and lower parking area at Edwards Ferry, and began to inundate areas near Whites Ferry.  The peak level of 16.08 feet occurred at 9:00 AM on the 23rd.');
INSERT INTO public.stormevents_east VALUES (807276, 201812, 15, 2128, 201812, 15, 2328, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 21:28:00', 'EST-5', '15-DEC-18 23:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'SILER', 2, 'NE', 'SILER', 39.34, -78.27, 39.3747, -78.216, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Numerous roads closed due to flooding in Frederick County VA, particularly north of US Route 522 and west of Interstate 81, including Adams Road, Green Spring Road, Hunting Ridge Road, and Cattail Road.');
INSERT INTO public.stormevents_east VALUES (807277, 201812, 15, 2130, 201812, 15, 2330, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 21:30:00', 'EST-5', '15-DEC-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'CATHARPIN', 2, 'S', 'CATHARPIN', 38.8236, -77.5781, 38.8234, -77.5737, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Artemus Road at Pageland Lane is closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (807278, 201812, 15, 2208, 201812, 16, 8, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 22:08:00', 'EST-5', '16-DEC-18 00:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'MOUNTAIN FALLS', 2, 'NNE', 'MOUNTAIN FALLS', 39.14, -78.38, 39.1415, -78.3831, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'High water reported in the 4000 block of Back Mountain Road in vicinity of Pifer Run.');
INSERT INTO public.stormevents_east VALUES (807280, 201812, 15, 2249, 201812, 16, 49, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 22:49:00', 'EST-5', '16-DEC-18 00:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BRISTOW', 1, 'N', 'BRISTOW', 38.7346, -77.5331, 38.7356, -77.5314, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Piper Lane closed as a result of flooding.');
INSERT INTO public.stormevents_east VALUES (807703, 201812, 16, 126, 201812, 16, 326, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 01:26:00', 'EST-5', '16-DEC-18 03:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'INDEPENDENT HILL', 0, 'NW', 'INDEPENDENT HILL', 38.6343, -77.4387, 38.6339, -77.4348, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Joplin Road from Bristow Road to Liming Lane closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (779372, 201809, 2, 1431, 201809, 2, 1431, 130143, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RNK', '02-SEP-18 14:31:00', 'EST-5', '02-SEP-18 14:31:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'BUCK', 1, 'SSE', 'BUCK', 36.1504, -81.22, 36.1504, -81.22, 'High pressure in place over the region continued a pattern that had been in place for several days. Early morning fog would break early in the day and give way to isolated, terrain enhanced convection during the afternoon hours.', 'Thunderstorm winds brought down trees along Congo Road and Buck Road. One of the trees came down on a power line causing a fire.');
INSERT INTO public.stormevents_east VALUES (779374, 201809, 2, 1426, 201809, 2, 1426, 130143, 'NORTH CAROLINA', 37, 2018, 'September', 'Hail', 'RNK', '02-SEP-18 14:26:00', 'EST-5', '02-SEP-18 14:26:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 1.25, NULL, NULL, NULL, 1, 'E', 'BUCK', 1, 'E', 'BUCK', 36.17, -81.22, 36.17, -81.22, 'High pressure in place over the region continued a pattern that had been in place for several days. Early morning fog would break early in the day and give way to isolated, terrain enhanced convection during the afternoon hours.', NULL);
INSERT INTO public.stormevents_east VALUES (786832, 201809, 20, 1400, 201809, 20, 1410, 131525, 'FLORIDA', 12, 2018, 'September', 'Hail', 'MFL', '20-SEP-18 14:00:00', 'EST-5', '20-SEP-18 14:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 2, 'W', 'CORAL SPGS', 2, 'W', 'CORAL SPGS', 26.27, -80.26, 26.27, -80.26, 'A surface trough with an upper level short wave was moving across South Florida. This allowed mid level 500mb temps to cool and convective instability to increase over the region. Scattered showers and thunderstorms developed producing gusty winds and hail in Broward County.', 'A trained spotter reported dime sized hail on 99th Avenue in Coral Springs. Multiple other reports of smaller hail in the area.');
INSERT INTO public.stormevents_east VALUES (786844, 201809, 20, 1410, 201809, 20, 1410, 131525, 'FLORIDA', 12, 2018, 'September', 'Hail', 'MFL', '20-SEP-18 14:10:00', 'EST-5', '20-SEP-18 14:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 4, 'W', 'CORAL SPGS', 4, 'W', 'CORAL SPGS', 26.2589, -80.2827, 26.2589, -80.2827, 'A surface trough with an upper level short wave was moving across South Florida. This allowed mid level 500mb temps to cool and convective instability to increase over the region. Scattered showers and thunderstorms developed producing gusty winds and hail in Broward County.', 'A trained spotter reported of dime size hail near intersection of Coral Ridge Drive and Royal Palm Blvd.');
INSERT INTO public.stormevents_east VALUES (786848, 201809, 20, 1425, 201809, 20, 1425, 131525, 'FLORIDA', 12, 2018, 'September', 'Hail', 'MFL', '20-SEP-18 14:25:00', 'EST-5', '20-SEP-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1, NULL, NULL, NULL, 8, 'W', 'LAUDERDALE LAKES', 8, 'W', 'LAUDERDALE LAKES', 26.1617, -80.3227, 26.1617, -80.3227, 'A surface trough with an upper level short wave was moving across South Florida. This allowed mid level 500mb temps to cool and convective instability to increase over the region. Scattered showers and thunderstorms developed producing gusty winds and hail in Broward County.', 'Members of the public and photos on social media show quarter sized hail fell near the BB&T Center in Sunrise.');
INSERT INTO public.stormevents_east VALUES (786841, 201809, 20, 1429, 201809, 20, 1429, 131525, 'FLORIDA', 12, 2018, 'September', 'Hail', 'MFL', '20-SEP-18 14:29:00', 'EST-5', '20-SEP-18 14:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 7, 'W', 'LAUDERDALE LAKES', 7, 'W', 'LAUDERDALE LAKES', 26.15, -80.32, 26.15, -80.32, 'A surface trough with an upper level short wave was moving across South Florida. This allowed mid level 500mb temps to cool and convective instability to increase over the region. Scattered showers and thunderstorms developed producing gusty winds and hail in Broward County.', 'A trained spotter reported 3/4 inch hail at Sawgrass Mills Mall in Sunrise.');
INSERT INTO public.stormevents_east VALUES (787508, 201809, 16, 600, 201809, 17, 600, 130244, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 06:00:00', 'EST-5', '17-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'STUART', 0, 'N', 'STUART', 36.63, -80.28, 36.63, -80.28, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'The COOP site at Stuart (STUV2) measured 4.49 inches for the 24 hours ending at 700 AM local time on the 17th. This was the 4th highest daily rainfall in September with nearly complete climate date back to 1923. The record is 6.03 inches set September 28, 2004.');
INSERT INTO public.stormevents_east VALUES (787510, 201809, 16, 600, 201809, 17, 600, 130244, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '16-SEP-18 06:00:00', 'EST-5', '17-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'WNW', 'COPPER HILL', 0, 'WNW', 'COPPER HILL', 37.0817, -80.1349, 37.0817, -80.1349, 'Hurricane Florence made landfall on the far southeast North Carolina coast on September 14th and tracked very slowly across South Carolina before slowly re-curving across far western North Carolina and southwest Virginia as Tropical Depression and on into the Ohio Valley. Multiple incidents of strong winds, flash flooding and flooding occurred with Florence. The following counties were included in a subsequent Presidential Disaster Declaration: Botetourt, Franklin, Halifax, City of Martinsville, Patrick, and Pittsylvania. Several more counties were still working through the validation process: Charlotte, Craig, and City of Danville. The first rainfall of any significance reached southern Virginia on the 15th  with about 1 to 3 inches falling by 12z (700 AM) on the 16th. Much heavier rainfall began to spread further northward during the afternoon and evening of the 16th prompting numerous Flash Flood Warnings and causing significant flood impacts.  The highest observed rain amounts in Virginia within the HSA were over parts of southwest Floyd and northwest Patrick counties with over 8 inches in 24 hours (ending at 700 AM on the 17th) and 9 to 10 inches storm total. Willis 2.7 SE CoCoRaHS (VA-FL-6) had 9.59 inches in the 72-hour period ending 700 AM on the 18th.', 'The COOP station at Copper Hill (COHV2) measured 4.61 inches for the 24 hours ending at 700 AM local time on the 17th. This was the 6th highest recorded in the month of September with nearly complete rainfall records extending back to 1940.');
INSERT INTO public.stormevents_east VALUES (767914, 201808, 7, 1605, 201808, 7, 1605, 128036, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '07-AUG-18 16:05:00', 'EST-5', '07-AUG-18 16:05:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'NNE', 'FLINT HILL', 2, 'NNE', 'FLINT HILL', 36.2138, -80.4693, 36.2138, -80.4693, 'Scattered severe thunderstorms developed in the afternoon from a hot and humid air mass.  These storms blew several trees down in the North Carolina Piedmont.', 'Thunderstorm winds blew down several trees near the intersection of Route 67 and Butner Mill Road.');
INSERT INTO public.stormevents_east VALUES (775130, 201808, 17, 1548, 201808, 17, 1548, 129357, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 15:48:00', 'EST-5', '17-AUG-18 15:48:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 4, 'S', 'HARRISONBURG', 4, 'S', 'HARRISONBURG', 38.4, -78.88, 38.4, -78.88, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'Several trees were blown down near and just south of Harrisonburg.');
INSERT INTO public.stormevents_east VALUES (775131, 201808, 17, 1610, 201808, 17, 1610, 129357, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 16:10:00', 'EST-5', '17-AUG-18 16:10:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NNE', 'FLINT HILL', 1, 'NNE', 'FLINT HILL', 38.79, -78.11, 38.79, -78.11, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'A tree was blown down on Hittles Mill Road.');
INSERT INTO public.stormevents_east VALUES (775132, 201808, 17, 1615, 201808, 17, 1615, 129357, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 16:15:00', 'EST-5', '17-AUG-18 16:15:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'LURAY', 1, 'SE', 'LURAY', 38.66, -78.46, 38.66, -78.46, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'A tree was blown down on Airport Road.');
