INSERT INTO public.stormevents_east VALUES (775137, 201808, 17, 1424, 201808, 17, 1424, 129358, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 14:24:00', 'EST-5', '17-AUG-18 14:24:00', 0, 0, 0, 0, NULL, NULL, 'Public', 54, 'EG', NULL, NULL, 1, 'N', '(MRB)SHEPHERD FLD MR', 1, 'N', '(MRB)SHEPHERD FLD MR', 39.41, -77.98, 39.41, -77.98, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'Trees were  blown down in the Summer Hill subdivision.');
INSERT INTO public.stormevents_east VALUES (775138, 201808, 17, 1435, 201808, 17, 1435, 129358, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 14:35:00', 'EST-5', '17-AUG-18 14:35:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'SHEPHERDSTOWN', 0, 'N', 'SHEPHERDSTOWN', 39.43, -77.8, 39.43, -77.8, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'Two trees were blown down, one into a house.');
INSERT INTO public.stormevents_east VALUES (775084, 201808, 12, 1600, 201808, 12, 1600, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 16:00:00', 'EST-5', '12-AUG-18 16:00:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 3, 'NE', 'HOOES', 3, 'NE', 'HOOES', 38.38, -77.04, 38.38, -77.04, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'Multiple trees were blown down in vicinity of Mathias Point Road and Osprey Landing Road.');
INSERT INTO public.stormevents_east VALUES (775087, 201808, 12, 1605, 201808, 12, 1605, 129354, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 16:05:00', 'EST-5', '12-AUG-18 16:05:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'SW', 'INDIAN HD MRYLND ARP', 1, 'SW', 'INDIAN HD MRYLND ARP', 38.59, -77.08, 38.59, -77.08, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'A tree was blown down on Bumpy Oak Road near Ashland Road.');
INSERT INTO public.stormevents_east VALUES (775088, 201808, 13, 1435, 201808, 13, 1435, 129355, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'LWX', '13-AUG-18 14:35:00', 'EST-5', '13-AUG-18 14:35:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 0.75, NULL, NULL, NULL, 2, 'NNW', 'LOFTON', 2, 'NNW', 'LOFTON', 37.98, -79.19, 37.98, -79.19, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Penny sized hail fell at this location.');
INSERT INTO public.stormevents_east VALUES (775089, 201808, 13, 1459, 201808, 13, 1459, 129355, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'LWX', '13-AUG-18 14:59:00', 'EST-5', '13-AUG-18 14:59:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NE', 'CANOVA', 1, 'NE', 'CANOVA', 38.69, -77.42, 38.69, -77.42, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Quarter sized hail fell at this location.');
INSERT INTO public.stormevents_east VALUES (775090, 201808, 13, 1520, 201808, 13, 1520, 129355, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'LWX', '13-AUG-18 15:20:00', 'EST-5', '13-AUG-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1.5, NULL, NULL, NULL, 1, 'WNW', 'FAIRFAX PARK', 1, 'WNW', 'FAIRFAX PARK', 38.78, -77.27, 38.78, -77.27, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Hail up to the size of ping pong balls fell at this location.');
INSERT INTO public.stormevents_east VALUES (775091, 201808, 13, 1536, 201808, 13, 1536, 129355, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'LWX', '13-AUG-18 15:36:00', 'EST-5', '13-AUG-18 15:36:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 0.75, NULL, NULL, NULL, 2, 'E', 'FAIRFAX PARK', 2, 'E', 'FAIRFAX PARK', 38.77, -77.22, 38.77, -77.22, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Penny sized hail fell at this location.');
INSERT INTO public.stormevents_east VALUES (775093, 201808, 13, 1458, 201808, 13, 1458, 129355, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '13-AUG-18 14:58:00', 'EST-5', '13-AUG-18 14:58:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'CANOVA', 1, 'E', 'CANOVA', 38.68, -77.42, 38.68, -77.42, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Trees were blown down onto wires near the intersection of Kahns Road and Harvey Road, and in the 6500 block of Shamrock Road. A tree was also blown onto a house in the 13000 block of Celtic Lane.');
INSERT INTO public.stormevents_east VALUES (775094, 201808, 13, 1455, 201808, 13, 1455, 129355, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '13-AUG-18 14:55:00', 'EST-5', '13-AUG-18 14:55:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'MINNIEVILLE', 1, 'W', 'MINNIEVILLE', 38.63, -77.36, 38.63, -77.36, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'A tree was blown down in the 5100 block of Bobcat Court.');
INSERT INTO public.stormevents_east VALUES (782494, 201809, 28, 522, 201809, 28, 1503, 130484, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'RLX', '28-SEP-18 05:22:00', 'EST-5', '28-SEP-18 15:03:00', 0, 0, 0, 0, '5.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'REYNOLDSVILLE', 1, 'WSW', 'GORE', 39.2512, -80.4033, 39.3115, -80.3703, 'On the 23rd a surface boundary was stalled across southern West Virginia. It slowly moved north as a warm front on the 24th and 25th as a surface low crossed the region. This low then pushed a cold front through on the 26th and 27th. Atmospheric moisture was anomalously high throughout the period, leading to multiple rounds of moderate to heavy rain which caused flooding issues across parts of the state.', 'Flooding along the West Fork River in Clarksburg impacted some homes along the river and flooded a section of Liberty Avenue. The river gage on the West Fork showed the river rose above its 14 foot flood stage before sunrise on the 28th, cresting at 14.6 feet mid morning. It then returned to its banks by mid afternoon.');
INSERT INTO public.stormevents_east VALUES (783301, 201809, 5, 1533, 201809, 5, 1533, 130907, 'NEW YORK', 36, 2018, 'September', 'Thunderstorm Wind', 'ALY', '05-SEP-18 15:33:00', 'EST-5', '05-SEP-18 15:33:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 60, 'EG', NULL, NULL, 1, 'NNE', 'BROADALBIN', 1, 'NNE', 'BROADALBIN', 43.0589, -74.1924, 43.0589, -74.1924, 'Isolated thunderstorms developed in the Mohawk Valley during the afternoon of the 5th in a hot and humid airmass. Though these storms were mainly below severe limits, one storm produced several reports of wind damage in Broadalbin. It was reported that 380 residences lost power due to the storm.', 'A tree was downed across Saratoga Avenue.');
INSERT INTO public.stormevents_east VALUES (783300, 201809, 5, 1533, 201809, 5, 1533, 130907, 'NEW YORK', 36, 2018, 'September', 'Thunderstorm Wind', 'ALY', '05-SEP-18 15:33:00', 'EST-5', '05-SEP-18 15:33:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 60, 'EG', NULL, NULL, 1, 'N', 'BROADALBIN', 1, 'N', 'BROADALBIN', 43.0606, -74.2006, 43.0606, -74.2006, 'Isolated thunderstorms developed in the Mohawk Valley during the afternoon of the 5th in a hot and humid airmass. Though these storms were mainly below severe limits, one storm produced several reports of wind damage in Broadalbin. It was reported that 380 residences lost power due to the storm.', 'Multiple trees and wires were downed in the village of Broadalbin. One tree was downed onto a car with people trapped inside. Other trees were downed onto houses.');
INSERT INTO public.stormevents_east VALUES (783302, 201809, 5, 1535, 201809, 5, 1535, 130907, 'NEW YORK', 36, 2018, 'September', 'Thunderstorm Wind', 'ALY', '05-SEP-18 15:35:00', 'EST-5', '05-SEP-18 15:35:00', 0, 0, 0, 0, NULL, NULL, 'Newspaper', 60, 'EG', NULL, NULL, 1, 'WSW', 'NORTH BROADALBIN', 1, 'WSW', 'NORTH BROADALBIN', 43.0884, -74.1941, 43.0884, -74.1941, 'Isolated thunderstorms developed in the Mohawk Valley during the afternoon of the 5th in a hot and humid airmass. Though these storms were mainly below severe limits, one storm produced several reports of wind damage in Broadalbin. It was reported that 380 residences lost power due to the storm.', 'A large pine tree was snapped near the base resulting in downed wires.');
INSERT INTO public.stormevents_east VALUES (781571, 201808, 31, 2152, 201808, 31, 2352, 130420, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 21:52:00', 'EST-5', '31-AUG-18 23:52:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'MARTINSBURG', 0, 'NW', 'MARTINSBURG', 39.4632, -77.9777, 39.4545, -77.9751, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'North Tennessee Avenue was closed near est Race street due to flooding. Baltimore Street was closed due to flooding near Randolph Street. The 200 Block of Stephen Street was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (784708, 201809, 25, 1700, 201809, 25, 1845, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:00:00', 'EST-5', '25-SEP-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'UPPER STEPNEY', 1, 'SSE', 'REDDING', 41.3296, -73.2847, 41.2887, -73.3746, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Fifty water rescues were performed by the local fire department and emergency management in Easton.');
INSERT INTO public.stormevents_east VALUES (784709, 201809, 25, 1715, 201809, 25, 1815, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:15:00', 'EST-5', '25-SEP-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'ANSONIA ARPT', 1, 'SE', 'DERBY JCT', 41.3041, -73.0299, 41.3106, -73.0628, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Numerous roads were closed due to flooding around the town of Orange including Route 34 (Derby Avenue) at Route 114, Glenbrook Road, Mapledale Road, Chestnut Ridge Road, Edison Road, Grassy Hill Road, Opekun Road, and Arrowhead Road.');
INSERT INTO public.stormevents_east VALUES (784710, 201809, 25, 1730, 201809, 25, 1845, 131165, 'CONNECTICUT', 9, 2018, 'September', 'Flash Flood', 'OKX', '25-SEP-18 17:30:00', 'EST-5', '25-SEP-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'GREENFIELD HILL', 2, 'W', 'BRIDGEPORT', 41.1808, -73.2623, 41.1828, -73.2602, 'Rain developed across the area ahead of an approaching warm front, consolidating into a slow-moving band of heavy rain west of New York City that advanced eastward across southern Connecticut during the afternoon and evening. Precipitable water values increased from 1.84 on the morning sounding from Upton, NY to 2.13 by evening. Both of these values are above the 90th percentile based on a sounding climatology, with the 2.13 precipitable water value on the evening of the 25th a record for the date. Widespread rainfall amounts of 4 inches or more were reported across southern Connecticut with flash flooding resulting in numerous water rescues. A trained spotter in Trubmull received 7.32 inches of rain during the event, while a HAM radio operator in Lebanon received 6.79 inches. Automated stations near Durham and Hamden reported 7.24 and 8.59 inches of rain, respectively.', 'Firefighters rescued a mother and child from a flooded car at the intersection of Brookside Drive and Samp Mortar Drive in Fairfield.');
INSERT INTO public.stormevents_east VALUES (786883, 201809, 3, 1715, 201809, 3, 1945, 131540, 'OHIO', 39, 2018, 'September', 'Flash Flood', 'CLE', '03-SEP-18 17:15:00', 'EST-5', '03-SEP-18 19:45:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'OTTAWA HILLS', 1, 'E', 'VULCAN', 41.69, -83.62, 41.6521, -83.6032, 'Hot and humid conditions with temperatures in the 90s and dew points in the 70s on the afternoon of the 3rd produced torrential rainfall with radar estimated rainfall rates up to 5 inches and hour. Though these storms were moving at a forward motion around 25 mph, the intensity of the rainfall resulted in flash flooding over portions of Lucas and Trumbull Counties. The Toledo area (Lucas County) experienced similar torrential rainfall concurrently as the Liberty Township (Trumbull County) storms.', 'Flash flood resulted almost immediately due to the urban nature of the city. Dozens of roads received several feet of water. A car was submerged in up to 3 feet of water near the University on Central Avenue. Storm drainage systems were overwhelmed resulting in 18 homes with basement flooding.');
INSERT INTO public.stormevents_east VALUES (785372, 201809, 9, 2226, 201809, 10, 115, 131268, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'AKQ', '09-SEP-18 22:26:00', 'EST-5', '10-SEP-18 01:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'EXMORE', 0, 'N', 'WILLIS WHARF', 37.53, -75.82, 37.5256, -75.8207, 'Scattered showers and thunderstorms along a stationary boundary produced heavy rain which caused flash flooding across portions of the Virginia Eastern Shore.', 'Numerous homes were flooded and water rescues were reported in Exmore. Radar estimates indicated that up to three to four inches of rain had fallen in the area.');
INSERT INTO public.stormevents_east VALUES (785377, 201809, 1, 1807, 201809, 1, 1817, 131269, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '01-SEP-18 18:07:00', 'EST-5', '01-SEP-18 18:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 4, 'ENE', 'LORAY', 1, 'WNW', 'STATESVILLE', 35.839, -80.904, 35.788, -80.92, 'Isolated thunderstorms developed over the North Carolina Piedmont and foothills during the evening. A couple of the storms produced brief severe weather.', 'Fd reported trees blown down on power lines at S. Chipley Ford Rd and Viewmont Ct. County comms reported other trees nad power lines down on Front St.');
INSERT INTO public.stormevents_east VALUES (785380, 201809, 1, 1812, 201809, 1, 1812, 131269, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'GSP', '01-SEP-18 18:12:00', 'EST-5', '01-SEP-18 18:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'SW', 'SHEFFIELD', 1, 'WSW', 'SHEFFIELD', 35.952, -80.694, 35.962, -80.688, 'Isolated thunderstorms developed over the North Carolina Piedmont and foothills during the evening. A couple of the storms produced brief severe weather.', 'Spotter reported multiple trees and power lines blown down along Edwards Rd and Sheffield Road. A large limb fell on a house on Edwards Rd.');
INSERT INTO public.stormevents_east VALUES (785846, 201809, 22, 2047, 201809, 23, 47, 131344, 'WEST VIRGINIA', 54, 2018, 'September', 'Flash Flood', 'RNK', '22-SEP-18 20:47:00', 'EST-5', '23-SEP-18 00:47:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'CALDWELL', 2, 'WSW', 'HARTS RUN', 37.7775, -80.4001, 37.7585, -80.3664, 'A slow-moving frontal boundary triggered thunderstorms producing heavy rainfall in pockets across southwest Monroe and northeast Greenbrier counties. Rainfall estimates were 2 to 3 inches in several hours.', 'There were several reports of flash flooding across Greenbrier County. The tunnel on Route 63 at Howards Creek was flooded as the creek was out of its banks. A car was reported stuck in flood waters in the tunnel. Route 92 was flooded in various locations and there were several mud and rockslides along the road.');
INSERT INTO public.stormevents_east VALUES (786849, 201809, 25, 2015, 201809, 26, 0, 131526, 'CONNECTICUT', 9, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 20:15:00', 'EST-5', '26-SEP-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WILLIMANTIC', 1, 'W', 'WINDHAM', 41.7056, -72.1994, 41.6982, -72.187, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Connecticut with 3 to 6 inches observed over Northeast Connecticut and 1 to 3 inches in Hartford County.', 'At 8:15 PM EST, Windham Road (State Route 32) just south of Willimantic was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (751422, 201805, 4, 1923, 201805, 4, 1923, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:23:00', 'EST-5', '04-MAY-18 19:23:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'GUILDERLAND CENTER', 0, 'N', 'GUILDERLAND CENTER', 42.7, -73.97, 42.7, -73.97, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees were reported down.');
INSERT INTO public.stormevents_east VALUES (751424, 201805, 4, 1954, 201805, 4, 1954, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:54:00', 'EST-5', '04-MAY-18 19:54:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'PHOENICIA', 1, 'E', 'PHOENICIA', 42.08, -74.31, 42.08, -74.31, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A tree and wires were reported down.');
INSERT INTO public.stormevents_east VALUES (752516, 201805, 15, 1334, 201805, 15, 1335, 125464, 'NEW YORK', 36, 2018, 'May', 'Tornado', 'ALY', '15-MAY-18 13:34:00', 'EST-5', '15-MAY-18 13:35:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 4, 'WSW', 'VIEWMONTE', 3, 'SW', 'VIEWMONTE', 42.071, -73.9286, 42.0715, -73.9211, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', 'A tornado that touched down between Woodstock and Saugerties in Ulster County crossed the Hudson River into Dutchess County and ended in Tivoli, just south of the Clermont State Historic Site. The damage in Dutchess County was rated EF-0, with several trees damaged or downed.');
INSERT INTO public.stormevents_east VALUES (752885, 201805, 15, 1518, 201805, 15, 1526, 125464, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '15-MAY-18 15:18:00', 'EST-5', '15-MAY-18 15:26:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', 91, 'EG', NULL, NULL, 0, 'NNW', 'CASTLE PT', 1, 'WSW', 'EAST FISHKILL', 41.525, -73.9732, 41.5403, -73.8206, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', 'A National Weather Service team determined that a macroburst occurred along the I-84 corridor roughly between Beacon/Wappingers Falls and East Fishkill/Hopewell Junction. The macroburst toppled and uprooted hundreds of trees. Some trees fell on structures, and a tree was downed onto I-84 blocking a lane. There was limited direct damage from wind to structures. A fallen chimney was noted and some siding was ripped off a few homes. The damage swath was around seven miles long and three miles wide.');
INSERT INTO public.stormevents_east VALUES (800365, 201812, 15, 2354, 201812, 17, 612, 133708, 'WEST VIRGINIA', 54, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 23:54:00', 'EST-5', '17-DEC-18 06:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'LARGENT', 1, 'W', 'LARGENT', 39.4753, -78.3839, 39.4828, -78.4075, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The stream gage on the Cacapon River at Great Cacapon exceeded the 9 foot flood stage during the indicated period. Rock Ford Road flooded in multiple locations, including flowing completely over the low water bridge.  Flooding was also observed along Constant Run Road, Kilgore Road and Running Waters Way. The peak level of 13.05 feet occurred at 10:15 AM.');
INSERT INTO public.stormevents_east VALUES (786837, 201809, 25, 1908, 201809, 25, 2200, 131526, 'CONNECTICUT', 9, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 19:08:00', 'EST-5', '25-SEP-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'WILLIMANTIC', 0, 'SSW', 'WILLIMANTIC', 41.715, -72.2206, 41.7154, -72.2224, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Connecticut with 3 to 6 inches observed over Northeast Connecticut and 1 to 3 inches in Hartford County.', 'At 7:08 PM EST,  Valley Street at Watson Street in Willimantic was closed due to flooding.  A car was trapped in floodwaters on Valley Street, with water above the sidewalks. At 7:14 PM EST, Valley Street at Birch Street was also closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786843, 201809, 25, 1946, 201809, 26, 50, 131526, 'CONNECTICUT', 9, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 19:46:00', 'EST-5', '26-SEP-18 00:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WILLIMANTIC', 1, 'S', 'WILLIMANTIC', 41.7128, -72.2195, 41.7105, -72.222, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Connecticut with 3 to 6 inches observed over Northeast Connecticut and 1 to 3 inches in Hartford County.', 'At 7:46 PM EST, Bridge Street in Willimantic was flooded and impassable.  The Willimantic River, below the bridge, was coming out of its banks.');
INSERT INTO public.stormevents_east VALUES (785608, 201809, 7, 800, 201809, 10, 800, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'W', 'VALLEY GROVE', 1, 'W', 'VALLEY GROVE', 40.08, -80.5889, 40.08, -80.5889, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A 72 storm total of 4.98 inches was recorded.');
INSERT INTO public.stormevents_east VALUES (785609, 201809, 7, 800, 201809, 10, 800, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 08:00:00', 'EST-5', '10-SEP-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 6, 'N', 'TERRA ALTA', 6, 'N', 'TERRA ALTA', 39.5368, -79.55, 39.5368, -79.55, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A 72 hour storm total of 5.49 inches was recorded.');
INSERT INTO public.stormevents_east VALUES (772457, 201807, 4, 1906, 201807, 4, 1906, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '04-JUL-18 19:06:00', 'EST-5', '04-JUL-18 19:06:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'E', 'CHERRY CITY', 2, 'E', 'CHERRY CITY', 40.48, -79.94, 40.48, -79.94, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'The 911 Call Center reported tree blocking 57th Street at Duncan Street.');
INSERT INTO public.stormevents_east VALUES (785610, 201809, 7, 745, 201809, 10, 745, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:45:00', 'EST-5', '10-SEP-18 07:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 0, 'N', 'ALBRIGHT', 0, 'N', 'ALBRIGHT', 39.5, -79.63, 39.5, -79.63, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A 72 hour storm total of 4.71 inches was recorded by the Army Corps.');
INSERT INTO public.stormevents_east VALUES (781680, 201808, 1, 27, 201808, 1, 240, 129380, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 00:27:00', 'EST-5', '01-AUG-18 02:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'NE', 'LITTLE ORLEANS', 2, 'ENE', 'LITTLE ORLEANS', 39.6528, -78.3405, 39.6498, -78.3408, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. An isolated incident of flooding occurred due to locally  heavy rainfall.', 'The USGS stream gage on Sideling Hill Creek near Bellegrove exceeded the 7.5 foot flood stage during the indicated period. The peak level of 7.88 feet occurred at 1:45am EST. Agricultural flooding occurred, along with water approaching Allegany Line Road.');
INSERT INTO public.stormevents_east VALUES (781733, 201808, 4, 100, 201808, 4, 704, 129454, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 01:00:00', 'EST-5', '04-AUG-18 07:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'WADESVILLE', 2, 'SW', 'WADESVILLE', 39.2241, -78.061, 39.2242, -78.0599, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'The USGS stream gage on Opequon Creek near Berryville exceeded the 10 foot flood stage during the indicated period. The peak level of 11.01 feet occurred at 4:45am EST. Old Charles Town Road was flooded.');
INSERT INTO public.stormevents_east VALUES (782784, 201808, 4, 513, 201808, 4, 2323, 130818, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 05:13:00', 'EST-5', '04-AUG-18 23:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'BLAIRTON', 2, 'WSW', 'VANCLEVESVILLE', 39.4225, -77.9394, 39.4208, -77.9333, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding along the Opequon Creek.', 'The stream gauge on the Opequon Creek at Martinsburg crested at 11.77 feet, above the flood stage of 10 feet. Water covered backyards of homes along Bowers Road. Douglas Grove Road was flooded and impassible. Water also approached Golf Course Road and Grapevine Road.');
INSERT INTO public.stormevents_east VALUES (782868, 201808, 13, 1724, 201808, 13, 1740, 129512, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '13-AUG-18 17:24:00', 'EST-5', '13-AUG-18 17:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'OAKLEIGH', 1, 'NNW', 'OAKLEIGH', 39.4119, -76.5541, 39.4105, -76.5558, 'Upper-level low pressure remained over the region while a warm and humid air mass was in place. This resulted in showers and thunderstorms, some of which produced locally heavy rainfall.', 'The stream gage on Minebank Run near Glen Arm briefly, but rapidly, exceeded the 10 foot flood stage during the indicated period, flooding lands and an access road near Talmar for a brief period of time. The peak level of 10.41 feet occurred at 5:30pm EST.');
INSERT INTO public.stormevents_east VALUES (782879, 201808, 3, 2025, 201808, 3, 2125, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'LWX', '03-AUG-18 20:25:00', 'EST-5', '03-AUG-18 21:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'MONUMENT MILLS', 1, 'NNE', 'RIXEYVILLE', 38.597, -78.0059, 38.5966, -77.9605, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Flash flooding was reported on multiple roadways near Rixeyville.');
INSERT INTO public.stormevents_east VALUES (785581, 201809, 9, 2345, 201809, 10, 345, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '09-SEP-18 23:45:00', 'EST-5', '10-SEP-18 03:45:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BARRISVILLE', 1, 'NNW', 'FOMBELL', 40.78, -80.24, 40.8131, -80.2037, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported that Route 588 near Brush Creek Park has a foot of water on the road.');
INSERT INTO public.stormevents_east VALUES (785582, 201809, 10, 116, 201809, 10, 316, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Flood', 'PBZ', '10-SEP-18 01:16:00', 'EST-5', '10-SEP-18 03:16:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NORTH SEWICKLEY', 1, 'ESE', 'NORTH SEWICKLEY', 40.83, -80.28, 40.826, -80.2527, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A 911 Call Center reported that several roads are closed due to flooding in North Sewickley Twp.');
INSERT INTO public.stormevents_east VALUES (776452, 201807, 4, 730, 201807, 4, 900, 129623, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'BUF', '04-JUL-18 07:30:00', 'EST-5', '04-JUL-18 09:00:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'RICHBURG', 1, 'W', 'LITTLE GENESEE', 42.0994, -78.1696, 42.0276, -78.2229, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Water and associated debris over roads in Richburg, Little Genesee, and Clarksville. This included Rout 40, Route 5A, and Sunny Hill Road.');
INSERT INTO public.stormevents_east VALUES (776454, 201807, 4, 800, 201807, 4, 930, 129623, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'BUF', '04-JUL-18 08:00:00', 'EST-5', '04-JUL-18 09:30:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'SHONGO', 0, 'W', 'SHONGO', 42.0037, -77.8902, 42.0207, -77.907, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Route 19 in Shongo closed due to water and debris over road.');
INSERT INTO public.stormevents_east VALUES (776457, 201807, 4, 800, 201807, 4, 930, 129623, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'BUF', '04-JUL-18 08:00:00', 'EST-5', '04-JUL-18 09:30:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'BELVIDERE', 3, 'SE', 'ROCKVILLE', 42.28, -78.11, 42.2719, -78.1354, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Several roads closed with water and debris in the Town of Belfast, and Route 41 closed south of the Town of Belfast with debris over the road.');
INSERT INTO public.stormevents_east VALUES (776458, 201807, 4, 809, 201807, 4, 900, 129623, 'NEW YORK', 36, 2018, 'July', 'Flash Flood', 'BUF', '04-JUL-18 08:09:00', 'EST-5', '04-JUL-18 09:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'RICHBURG', 1, 'NNE', 'BOLIVAR', 42.0838, -78.1654, 42.0783, -78.1634, 'The region was underneath a large upper level ridge with a subtle frontal boundary near the NY/PA state line. The region was in a warm and very moist air mass with precipitable water values around 1.75 inches. Thunderstorms developed across Allegany County early in the morning. With 700 mb winds less than 10 kts, these storms hardly moved at all. They maintained intensity, eventually dropping a radar estimated 2.5 inches in about an hour. These storms eventually meandered into Northern PA, producing up to 6 inches of rain there.', 'Video on social media of water over Reed Street in Bolivar.');
INSERT INTO public.stormevents_east VALUES (785627, 201809, 7, 700, 201809, 10, 725, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 07:00:00', 'EST-5', '10-SEP-18 07:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'SE', 'SAXONBURG', 2, 'SE', 'SAXONBURG', 40.7295, -79.773, 40.7295, -79.773, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A CoCoRaHS observer recorded 5.80 inches of rain in a 72 hour period.');
INSERT INTO public.stormevents_east VALUES (785628, 201809, 7, 600, 201809, 10, 600, 131295, 'PENNSYLVANIA', 42, 2018, 'September', 'Heavy Rain', 'PBZ', '07-SEP-18 06:00:00', 'EST-5', '10-SEP-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 4, 'NNE', 'ST PETERSBURG', 4, 'NNE', 'ST PETERSBURG', 41.2235, -79.6406, 41.2235, -79.6406, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period and creating widespread flooding. 72 hour totals across southwest Pennsylvania from 2 inches to a little over 7 inches. Storm rainfall total for Pittsburgh ranks #2 for tropical remnants at 5.64 inches (Hurricane Ivan in 2004 still remains #1 at 5.94 inches).  Disaster declarations were made in Allegheny County (where five municipalities had already done so) and in Westmoreland County.||The U.S Small Business Administration awarded low-interest loans to qualifying victims of flooding. The money follows Governor Tom Wolf''s request to SBA to declare a disaster in Westmoreland County. The disaster declaration also makes homeowners, renters, and businesses eligible for the loans in Washington, Fayette, Allegheny, and Indiana County. Low-interest loans of up to $200,000 are available to homeowners to repair or replace damaged or destroyed real estate, Wolf���s office said. Regulations permit loans of up to $40,000 to repair or replace personal property. Businesses and nonprofits can borrow up to $2 million to restore damaged or destroyed buildings, inventory, equipment and assets.', 'A CoCoRaHS observer recorded 4.33 inches of rain in a 72 hr period.');
INSERT INTO public.stormevents_east VALUES (781616, 201808, 2, 1530, 201808, 2, 1530, 130587, 'LAKE HURON', 90, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '02-AUG-18 15:30:00', 'EST-5', '02-AUG-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 8, 'NNE', 'BAY PORT', 8, 'NNE', 'BAY PORT', 43.95, -83.29, 43.95, -83.29, 'Thunderstorms moving through Saginaw Bay produced wind gusts around 50 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (772452, 201807, 3, 1940, 201807, 3, 2040, 128786, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '03-JUL-18 19:40:00', 'EST-5', '03-JUL-18 20:40:00', 0, 0, 0, 0, '1.00K', '0.50K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LAUGHLINTOWN', 1, 'W', 'LAUGHLINTOWN', 40.21, -79.2, 40.2222, -79.2184, 'Rich tropical moisture remained across the Northeast region. Precipitable water values continued to be high at 1.90 to 2.00 inches. Morning soundings showed very little upper level flow. A static atmosphere prompted a risk for flooding; storms that developed tended to move very little. Isolated wet microbursts were a potential due to CAPE values over 2000 J/kg. Storms developed from outflow boundaries and light convergence aloft.', 'The 911 Call Center reported Nature Run Road and Route 381 was also flooded in Laghlintown.');
INSERT INTO public.stormevents_east VALUES (772459, 201807, 4, 1925, 201807, 4, 1925, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '04-JUL-18 19:25:00', 'EST-5', '04-JUL-18 19:25:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 55, 'EG', NULL, NULL, 2, 'WSW', 'ASPINWALL', 2, 'WSW', 'ASPINWALL', 40.47, -79.92, 40.47, -79.92, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'A large tree was reported down in Highland Park on Wellesley on social media.');
INSERT INTO public.stormevents_east VALUES (772460, 201807, 4, 1908, 201807, 4, 1908, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '04-JUL-18 19:08:00', 'EST-5', '04-JUL-18 19:08:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'S', 'OPTION', 2, 'S', 'OPTION', 40.4, -79.98, 40.4, -79.98, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'A 911 Call Center reported that a tree was blocking the road at Wagner and Becks Run Road.');
INSERT INTO public.stormevents_east VALUES (772461, 201807, 4, 1908, 201807, 4, 1908, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'PBZ', '04-JUL-18 19:08:00', 'EST-5', '04-JUL-18 19:08:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'N', 'ASPINWALL', 1, 'N', 'ASPINWALL', 40.49, -79.88, 40.49, -79.88, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'The 911 Call Center reported that a tree was blocking the ramp near Chapel Road at North Margery Drive.');
INSERT INTO public.stormevents_east VALUES (772462, 201807, 4, 2000, 201807, 4, 2100, 128788, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'PBZ', '04-JUL-18 20:00:00', 'EST-5', '04-JUL-18 21:00:00', 0, 0, 0, 0, '5.00K', '1.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'SHARPSBURG', 1, 'SSE', 'SHARPSBURG', 40.49, -79.9, 40.4879, -79.895, 'The Pittsburgh region continued to sit under an upper level ridge while tropical moisture lingered in the Northeast U.S. Sufficient instability allowed for a few strong storms to develop, causing tree damage. Localized flooding was the main concern due to a static atmosphere with light flow.', 'A local emergency manager reported that Washington Blvd was closed in both directions due to flooding at Allegheny River Blvd and Negley Run. The north side of the river, in Aspinwall, there was flooding at Delafield Ave (report via social media).');
INSERT INTO public.stormevents_east VALUES (765402, 201807, 3, 1552, 201807, 3, 1552, 127641, 'MASSACHUSETTS', 25, 2018, 'July', 'Lightning', 'BOX', '03-JUL-18 15:52:00', 'EST-5', '03-JUL-18 15:52:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Airplane Pilot', NULL, NULL, NULL, NULL, 2, 'ENE', 'METROPOLITAN ARPT', 2, 'ENE', 'METROPOLITAN ARPT', 42.2297, -72.2926, 42.2297, -72.2926, 'A cold front moved from New York through Southern New England and produced showers and thunderstorms.', 'At 3:52 PM EST, power lines were reported down due to a lightning strike on State Route 32 near the Ware Town Line.');
INSERT INTO public.stormevents_east VALUES (807262, 201812, 15, 1253, 201812, 15, 1453, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 12:53:00', 'EST-5', '15-DEC-18 14:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LEESBURG MUNI', 1, 'S', 'LEESBURG MUNI', 39.0597, -77.5536, 39.062, -77.5541, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Shreve Mill Road closed west of Sycolin Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (807704, 201812, 16, 126, 201812, 16, 326, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 01:26:00', 'EST-5', '16-DEC-18 03:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'NOKESVILLE', 2, 'W', 'NOKESVILLE', 38.6928, -77.619, 38.6963, -77.622, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Reid Lane closed from Fauqier Drive to Vint Hill Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (787289, 201809, 27, 2018, 201809, 28, 318, 131621, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'RNK', '27-SEP-18 20:18:00', 'EST-5', '28-SEP-18 03:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 4, 'SSE', '(HSP)INGALLS FLD HOT', 6, 'SSE', '(HSP)INGALLS FLD HOT', 37.9, -79.8, 37.8636, -79.8074, 'A slow-moving frontal boundary crossed the mountains and produced 1 to 2.5 inches of rain with the heaviest falling in the 24-hours ending at 12z (700 AM local) on the 28th. 24-hour rain totals were highest across the upper James and Greenbrier river basins. The James River rose above flood stage in the upper reaches and pockets of flooding were reported on smaller streams in these basins.', 'Several low water bridges were flooded in Douthat State Park along Douthat Park Road.');
INSERT INTO public.stormevents_east VALUES (807705, 201812, 16, 147, 201812, 16, 347, 134551, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '16-DEC-18 01:47:00', 'EST-5', '16-DEC-18 03:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 4, 'NNW', 'BOYCE', 4, 'NNW', 'BOYCE', 39.1487, -78.0908, 39.148, -78.0887, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Opequon Road closed near Clarke and Frederick County line due to flooding.');
INSERT INTO public.stormevents_east VALUES (807707, 201812, 15, 1600, 201812, 15, 1800, 133708, 'WEST VIRGINIA', 54, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 16:00:00', 'EST-5', '15-DEC-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'INWOOD', 1, 'NNW', 'BUNKER HILL', 39.3411, -78.0631, 39.3388, -78.0543, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'Henshaw Road (500 block) closed due to flooding along Mill Creek.');
INSERT INTO public.stormevents_east VALUES (781694, 201808, 3, 1511, 201808, 3, 1611, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 15:11:00', 'EST-5', '03-AUG-18 16:11:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'E', 'CLAVERACK', 1, 'E', 'CLAVERACK', 42.22, -73.72, 42.22, -73.72, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 1.5 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (781695, 201808, 3, 1555, 201808, 3, 1625, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 15:55:00', 'EST-5', '03-AUG-18 16:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NW', 'COKERTOWN', 1, 'NW', 'COKERTOWN', 42.03, -73.83, 42.03, -73.83, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 2.12 inches of rainfall in a 30 minute period.');
INSERT INTO public.stormevents_east VALUES (779587, 201808, 3, 1345, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:45:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'ALBANY', 1, 'SW', 'ALBANY', 42.6437, -73.7827, 42.6435, -73.7825, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Medical Transport vehicle is stuck in water on Hackett Blvd. The road is closed.');
INSERT INTO public.stormevents_east VALUES (781658, 201808, 3, 1353, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:53:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'ALBANY', 2, 'E', 'NORTH BETHLEHEM', 42.6664, -73.8069, 42.6665, -73.807, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Flooding occurred at the intersection of Cortland St and Colonial Ave with water entering vehicles.');
INSERT INTO public.stormevents_east VALUES (781657, 201808, 3, 1330, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:30:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WATERVLIET', 1, 'SE', 'WATERVLIET', 42.72, -73.71, 42.7199, -73.7095, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'A basement wall collapsed due to flooding.');
INSERT INTO public.stormevents_east VALUES (781683, 201808, 3, 1244, 201808, 3, 1344, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 12:44:00', 'EST-5', '03-AUG-18 13:44:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 1, 'NW', 'ALBANY', 1, 'NW', 'ALBANY', 42.66, -73.78, 42.66, -73.78, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Heavy rain of 2.13 inches fell in a short period of time.');
INSERT INTO public.stormevents_east VALUES (774917, 201807, 22, 1412, 201807, 22, 1510, 128275, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 14:12:00', 'EST-5', '22-JUL-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LINCOLN MEMORIAL', 1, 'NNW', 'LINCOLN MEMORIAL', 38.8932, -77.056, 38.895, -77.0569, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the District of Columbia. Rainfall totals of 3 to 5 inches were observed, causing flooding, especially along Rock Creek.', 'Flooding on Rock Creek Parkway between I-66 and the Kennedy Center forced the closure of the northbound lanes.');
INSERT INTO public.stormevents_east VALUES (775492, 201807, 21, 1529, 201807, 21, 1730, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 15:29:00', 'EST-5', '21-JUL-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'FERRY FARMS', 2, 'SW', 'FERRY FARMS', 38.3023, -77.4471, 38.3019, -77.4466, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Kings Highway flooded and closed near Fredericksburg.');
INSERT INTO public.stormevents_east VALUES (775494, 201807, 21, 1545, 201807, 21, 1730, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 15:45:00', 'EST-5', '21-JUL-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'WOODBRIDGE', 0, 'NW', 'WOODBRIDGE', 38.6545, -77.2546, 38.6547, -77.2544, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Easy Street closed over Marumsco Creek due to water flowing over the road.');
INSERT INTO public.stormevents_east VALUES (780108, 201808, 19, 0, 201808, 19, 9, 130303, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '19-AUG-18 00:00:00', 'EST-5', '19-AUG-18 00:09:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'LEMON SPGS', 1, 'NE', 'LEMON SPGS', 35.39, -79.19, 35.389, -79.1881, 'Prefrontal convection developed over central North Carolina during the late evening in a warm and unstable atmosphere. Several of the storms produced wind damage, with one report of flash flooding.', 'Greenwood Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (780145, 201808, 6, 1518, 201808, 6, 1518, 130310, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '06-AUG-18 15:18:00', 'EST-5', '06-AUG-18 15:18:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ESE', 'COATS XRDS', 1, 'ESE', 'COATS XRDS', 35.5112, -78.5269, 35.5112, -78.5269, 'Showers and thunderstorms developed along a lee side surface trough across central North Carolina. The storms intensified as a weak mid level shortwave disturbance approached the area from the west in the late afternoon and early evening hours. Some of these storms became severe and produced wind damage.', 'Two trees were reported down at the intersection of Highway 210 and Berea Chruch Road.');
INSERT INTO public.stormevents_east VALUES (780146, 201808, 6, 1536, 201808, 6, 1536, 130310, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '06-AUG-18 15:36:00', 'EST-5', '06-AUG-18 15:36:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'ENE', 'EMIT', 2, 'ENE', 'EMIT', 35.74, -78.23, 35.74, -78.23, 'Showers and thunderstorms developed along a lee side surface trough across central North Carolina. The storms intensified as a weak mid level shortwave disturbance approached the area from the west in the late afternoon and early evening hours. Some of these storms became severe and produced wind damage.', 'Power lines were reported down.');
INSERT INTO public.stormevents_east VALUES (780147, 201808, 6, 1605, 201808, 6, 1605, 130310, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '06-AUG-18 16:05:00', 'EST-5', '06-AUG-18 16:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'SSE', 'HARPERS XRDS', 4, 'SSE', 'HARPERS XRDS', 35.5224, -79.4333, 35.5224, -79.4333, 'Showers and thunderstorms developed along a lee side surface trough across central North Carolina. The storms intensified as a weak mid level shortwave disturbance approached the area from the west in the late afternoon and early evening hours. Some of these storms became severe and produced wind damage.', 'One tree was reported down between Highway 42 and Siler city Glendon Road and Walter Oldham Road.');
INSERT INTO public.stormevents_east VALUES (780148, 201808, 6, 1615, 201808, 6, 1615, 130310, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '06-AUG-18 16:15:00', 'EST-5', '06-AUG-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SE', 'HARPERS XRDS', 1, 'SE', 'HARPERS XRDS', 35.555, -79.4559, 35.555, -79.4559, 'Showers and thunderstorms developed along a lee side surface trough across central North Carolina. The storms intensified as a weak mid level shortwave disturbance approached the area from the west in the late afternoon and early evening hours. Some of these storms became severe and produced wind damage.', 'One tree was reported down on Siler City Glendon Road, south of Tyson Creek Church Road.');
INSERT INTO public.stormevents_east VALUES (780149, 201808, 7, 1840, 201808, 7, 1840, 130311, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '07-AUG-18 18:40:00', 'EST-5', '07-AUG-18 18:40:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'ALAMANCE', 1, 'SW', 'ALAMANCE', 36.02, -79.49, 36.02, -79.49, 'Thunderstorms developed along a lee trough axis and were further enhanced by a sea breeze moving inland. Some of these storms became strong to severe producing wind damage.', 'Multiple trees were reported down in Alamance County, south of Interstate 40 and 85.');
INSERT INTO public.stormevents_east VALUES (780150, 201808, 7, 1900, 201808, 7, 1900, 130311, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '07-AUG-18 19:00:00', 'EST-5', '07-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'OCCONEECHEE', 1, 'NNW', 'OCCONEECHEE', 36.0825, -79.0832, 36.0825, -79.0832, 'Thunderstorms developed along a lee trough axis and were further enhanced by a sea breeze moving inland. Some of these storms became strong to severe producing wind damage.', 'One tree was reported down at Saint Marys Road and Miller Road.');
INSERT INTO public.stormevents_east VALUES (781946, 201808, 16, 1512, 201808, 16, 1512, 130638, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '16-AUG-18 15:12:00', 'EST-5', '16-AUG-18 15:12:00', 0, 0, 0, 0, '0.05K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'WNW', 'ARREDONDA', 1, 'WNW', 'ARREDONDA', 29.61, -82.44, 29.61, -82.44, 'A lingering mid level trough across SE GA combined with sea breeze forcing under southerly steering flow triggered strong to pulse severe storms over an unstable airmass.', 'Tree branches were blown down along SW 45th Blvd. The time of damage was based on radar and the cost of damage was unknown but estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781947, 201808, 16, 1555, 201808, 16, 1555, 130638, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '16-AUG-18 15:55:00', 'EST-5', '16-AUG-18 15:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Park/Forest Service', 50, 'EG', NULL, NULL, 7, 'S', 'DOWLING PARK', 7, 'S', 'DOWLING PARK', 30.15, -83.23, 30.15, -83.23, 'A lingering mid level trough across SE GA combined with sea breeze forcing under southerly steering flow triggered strong to pulse severe storms over an unstable airmass.', 'Wes Skiles Peacock Springs State Park reported a tree was blown down across an access road. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (781948, 201808, 16, 1610, 201808, 16, 1610, 130638, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '16-AUG-18 16:10:00', 'EST-5', '16-AUG-18 16:10:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 4, 'ESE', 'MERCER', 4, 'ESE', 'MERCER', 30.25, -83.06, 30.25, -83.06, 'A lingering mid level trough across SE GA combined with sea breeze forcing under southerly steering flow triggered strong to pulse severe storms over an unstable airmass.', 'A tree was blown down near County Road 250 and 153rd Road south of Live Oak. The time of damage was based on radar. The cost of damage was unknown but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781949, 201808, 16, 1619, 201808, 16, 1619, 130638, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '16-AUG-18 16:19:00', 'EST-5', '16-AUG-18 16:19:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'SE', 'DAYVILLE', 1, 'SE', 'DAYVILLE', 29.62, -82.37, 29.62, -82.37, 'A lingering mid level trough across SE GA combined with sea breeze forcing under southerly steering flow triggered strong to pulse severe storms over an unstable airmass.', 'A tree was blown down across SW 29th Terrace. The cost of damage was unknown but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781950, 201808, 17, 1630, 201808, 17, 1630, 130639, 'FLORIDA', 12, 2018, 'August', 'Lightning', 'JAX', '17-AUG-18 16:30:00', 'EST-5', '17-AUG-18 16:30:00', 0, 0, 0, 0, '0.10K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'N', 'HILLIARD', 1, 'N', 'HILLIARD', 30.69, -81.92, 30.69, -81.92, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'Lightning struck a tree and caused a small fire near US Highway 1 and Wade Drive. The cost of damage was unknown but estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781951, 201808, 17, 1456, 201808, 17, 1456, 130639, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '17-AUG-18 14:56:00', 'EST-5', '17-AUG-18 14:56:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Fire Department/Rescue', 45, 'EG', NULL, NULL, 0, 'N', 'SIMPSON YARD', 0, 'N', 'SIMPSON YARD', 30.35, -81.73, 30.35, -81.73, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'A wire was blown down near Edgewood Avenue and W 12th Street. The time of damage was based on radar imagery and the cost of damage was estimated.');
INSERT INTO public.stormevents_east VALUES (781952, 201808, 17, 1458, 201808, 17, 1458, 130639, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '17-AUG-18 14:58:00', 'EST-5', '17-AUG-18 14:58:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 2, 'NNW', 'DAYVILLE', 2, 'NNW', 'DAYVILLE', 29.65, -82.39, 29.65, -82.39, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'A tree was blown down on NW 46th Street. The time of damage was based on radar and the cost was estimated.');
INSERT INTO public.stormevents_east VALUES (780533, 201808, 9, 951, 201808, 9, 1251, 130386, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '09-AUG-18 09:51:00', 'EST-5', '09-AUG-18 12:51:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ROCK HARBOR', 1, 'NE', 'ORLEANS', 41.7984, -69.9904, 41.7863, -69.9904, 'A cold front moved across Massachusetts, bringing thunderstorms and downpours to Southeast Massachusetts and especially over Cape Cod.  Up to 4.5 inches of rain fell on Cape Cod during the morning and early afternoon.', 'At 9:51 AM EST, heavy rain brought up to a foot of water to Main Street in Orleans, in front of Friends Marketplace. Water was up to the wheel wells and floorboards of SUVs.  At 9:52 AM, heavy rain flooded the basement of the Orleans District Court on Rock Harbor Road.');
INSERT INTO public.stormevents_east VALUES (780537, 201808, 9, 1158, 201808, 9, 1500, 130386, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '09-AUG-18 11:58:00', 'EST-5', '09-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SOUTH BREWSTER', 1, 'SW', 'SOUTH BREWSTER', 41.7412, -70.0622, 41.7413, -70.0614, 'A cold front moved across Massachusetts, bringing thunderstorms and downpours to Southeast Massachusetts and especially over Cape Cod.  Up to 4.5 inches of rain fell on Cape Cod during the morning and early afternoon.', 'At 11:58 AM EST, Sheep Pond Drive and Clark Road were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (780573, 201808, 12, 916, 201808, 12, 1300, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flash Flood', 'BOX', '12-AUG-18 09:16:00', 'EST-5', '12-AUG-18 13:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'LYNN', 1, 'N', 'EAST SAUGUS', 42.4626, -70.9457, 42.4627, -70.982, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 9:16 AM EST, cars on Monroe Street in Lynn were floating in the street. At 9:18 AM EST, water was rising in a building on Monroe Street, causing people to stand on chairs.  At 9:31 AM cars were trapped in flood waters on Chatham Street under a bridge; the road was impassable.  At 10:03 AM the basement door to a building on Union Street had collapsed due to the flooding, and water was pouring in.  At 10:18 AM, large sections of Boston Street in Lynn were flooded and impassable, and several cars were trapped in the floodwaters. At 10:32 AM state route 107 on the Lynn/Salem border was closed due to flooding. At 10:59 AM EST, manhole covers were reported coming off the road on Seymour Avenue.  A car was trapped in three feet of water on Wilfred Street; the road was impassable. At 11:42 AM EST, street flooding on Erie Street reached several feet.');
INSERT INTO public.stormevents_east VALUES (780576, 201808, 12, 918, 201808, 12, 1300, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flash Flood', 'BOX', '12-AUG-18 09:18:00', 'EST-5', '12-AUG-18 13:00:00', 0, 0, 0, 0, '40.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'SALEM MARITIME NHS', 0, 'NE', 'SALEM MARITIME NHS', 42.5215, -70.9331, 42.5225, -70.9166, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 9:18 AM EST, Walnut Street in Peabody was closed due to flooding. At 9:36 AM EST, Spring Street was closed due to flooding. At 9:41 AM EST Oak Street was closed due to flooding; a car was trapped in the parking lot of the Elks Lodge on Oak Street.  At 9:42 AM train tracks were flooded near Howley Street and Proctor Brook; the water level was six inches below the bridge.  Also, Tremont Street and Foster Street were closed due to flooding with several cars trapped in the waters. By 9:48 AM nearly two feet of water was reported on Walnut Street with two cars trapped on the road. At 10:02 AM EST, Margin Street near Sheldon Road was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (781617, 201808, 2, 1530, 201808, 2, 1530, 130588, 'MICHIGAN', 26, 2018, 'August', 'Thunderstorm Wind', 'DTX', '02-AUG-18 15:30:00', 'EST-5', '02-AUG-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'E', 'KAWKAWLIN', 1, 'E', 'KAWKAWLIN', 43.65, -83.93, 43.65, -83.93, 'A thunderstorm brought down a tree just north of Bay city.', 'A large tree was reported blown down onto the road.');
INSERT INTO public.stormevents_east VALUES (779866, 201808, 2, 1204, 201808, 2, 1206, 130245, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'ILM', '02-AUG-18 12:04:00', 'EST-5', '02-AUG-18 12:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 52, 'MG', NULL, NULL, 1, 'NE', 'LUMBERTON MUNI ARPT', 1, 'NE', 'LUMBERTON MUNI ARPT', 34.61, -79.06, 34.61, -79.06, 'A near stationary frontal boundary produced a strong thunderstorm.', 'A 60 mph wind gust was recorded at the Lumberton ASOS.');
INSERT INTO public.stormevents_east VALUES (779868, 201808, 8, 2200, 201808, 8, 2202, 130246, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'ILM', '08-AUG-18 22:00:00', 'EST-5', '08-AUG-18 22:02:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'NNW', 'CONWAY', 1, 'NNW', 'CONWAY', 33.8434, -79.0567, 33.8434, -79.0567, 'A Piedmont trough kicked off some strong storms.', 'A tree was blown down on a house on Lockwood Lane near Monti Drive.');
INSERT INTO public.stormevents_east VALUES (779871, 201808, 12, 836, 201808, 12, 838, 130247, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'ILM', '12-AUG-18 08:36:00', 'EST-5', '12-AUG-18 08:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 34, 'MG', NULL, NULL, 6, 'ENE', 'LOCKWOOD FOLLY INLET SEA NAVIGATIONAL BUOY', 6, 'ENE', 'LOCKWOOD FOLLY INLET SEA NAVIGATIONAL BUOY', 33.91, -78.12, 33.91, -78.12, 'A cold front produced strong winds along the coast.', 'A 39 mph gust was recorded at Oak Island.');
INSERT INTO public.stormevents_east VALUES (748594, 201804, 15, 1658, 201804, 15, 1710, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 16:58:00', 'EST-5', '15-APR-18 17:10:00', 0, 0, 0, 0, '1.00M', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NW', 'WESTOVER HILLS', 1, 'S', 'DRY FORK', 36.6138, -79.4658, 36.731, -79.422, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'This is the third and final segment in Virginia of a tornado that originated west of Pelham near Dusty Lane in Caswell County of North Carolina at 4:51 PM EST.  After crossing Pittsylvania County and the independent city of Danville, the tornado continued northward and entered Pittsylvania County again at 4:58 PM EST.   Numerous trees were damaged or destroyed, several outbuildings were destroyed, and minor roof damage occurred on numerous houses.  The greatest damage was found on a farm at R and L Smith Road.  Estimated maximum winds were 110 MPH.  By 5:10 PM EST, the tornado finally lifted about two miles southwest of Dry Fork.');
INSERT INTO public.stormevents_east VALUES (748618, 201804, 15, 1742, 201804, 15, 1742, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 17:42:00', 'EST-5', '15-APR-18 17:42:00', 0, 0, 0, 0, '5.00K', NULL, 'Department of Highways', 55, 'EG', NULL, NULL, 1, 'WSW', 'HALIFAX', 1, 'WSW', 'HALIFAX', 36.7668, -78.9288, 36.7668, -78.9288, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'Several trees were blown down by thunderstorm winds in the town of Halifax.');
INSERT INTO public.stormevents_east VALUES (748621, 201804, 15, 1830, 201804, 15, 1830, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 18:30:00', 'EST-5', '15-APR-18 18:30:00', 0, 0, 0, 0, '50.00K', NULL, 'Trained Spotter', 56, 'EG', NULL, NULL, 9, 'SW', 'WINGINA', 0, 'N', 'WINGINA', 37.5448, -78.8478, 37.6336, -78.7194, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'Thunderstorm wind gusts estimated up to 65 MPH snapped and uprooted trees from Gladstone at 6:25 PM EST to Wingina at 6:35 PM EST.');
INSERT INTO public.stormevents_east VALUES (775744, 201808, 4, 1030, 201808, 4, 1215, 129487, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '04-AUG-18 10:30:00', 'EST-5', '04-AUG-18 12:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 21, 'NNW', 'SPUYTEN DUYVIL', 21, 'NNW', 'SPUYTEN DUYVIL', 41.1414, -74.1178, 41.1402, -74.1178, 'A developing area of low pressure along a surface trough helped produce heavy rainfall across parts of the Lower Hudson Valley on the morning of August 4th that resulted in flash flooding. Rainfall amounts ranged from 1-2.5 inches across Rockland County, with a CooCoRaHS observer in West Nyack reporting 2.47 inches of rain between the afternoon of August 3rd and the afternoon of August 4th.', 'The Mahwah River near Suffern rose above its flood stage of 4.0 feet at 11:30am EDT, crested at a height of 4.06 feet at 12:15pm EDT, and fell back below flood stage at 1:15pm EDT.');
INSERT INTO public.stormevents_east VALUES (779531, 201808, 7, 1845, 201808, 7, 1915, 130179, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '07-AUG-18 18:45:00', 'EST-5', '07-AUG-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'CORONA', 1, 'SSE', 'CORONA', 40.7296, -73.8622, 40.7303, -73.8615, 'A surface trough developing in a hot and humid airmass ahead of an approaching cold front resulted in the development of widely scattered showers and thunderstorms on the afternoon of August 7th. By evening, these showers and storms merged over New York City and Long Island, resulting in isolated reports of flash flooding. Rainfall totals ranged from around one inch in parts of New York City to 1-3 inches across much of Nassau and western Suffolk County.', 'Flowing water up to the height of car tires was observed on 63rd Drive near Queens Boulevard in Rego Park.');
INSERT INTO public.stormevents_east VALUES (779534, 201808, 7, 1935, 201808, 7, 2005, 130179, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '07-AUG-18 19:35:00', 'EST-5', '07-AUG-18 20:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BABYLON', 1, 'SSW', 'BABYLON', 40.6909, -73.3269, 40.691, -73.3263, 'A surface trough developing in a hot and humid airmass ahead of an approaching cold front resulted in the development of widely scattered showers and thunderstorms on the afternoon of August 7th. By evening, these showers and storms merged over New York City and Long Island, resulting in isolated reports of flash flooding. Rainfall totals ranged from around one inch in parts of New York City to 1-3 inches across much of Nassau and western Suffolk County.', 'A vehicle was stuck in flood waters at the intersection of Cedar Lane and Coppertree Lane in Babylon.');
INSERT INTO public.stormevents_east VALUES (779540, 201808, 11, 640, 201808, 11, 801, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 06:40:00', 'EST-5', '11-AUG-18 08:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'FANWOOD', 1, 'WNW', 'SCOTCH PLAINS', 40.64, -74.4021, 40.654, -74.3865, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Widespread flooding reported across the town of Fanwood, including two water rescues from vehicles.');
INSERT INTO public.stormevents_east VALUES (767591, 201808, 10, 1828, 201808, 10, 1838, 127532, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '10-AUG-18 18:28:00', 'EST-5', '10-AUG-18 18:38:00', 0, 0, 0, 0, '0.00K', '25.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'ESE', 'NEWPORT', 4, 'ESE', 'NEWPORT', 39.8132, -83.4368, 39.8066, -83.3947, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'An area of corn a couple of miles long was flattened.');
INSERT INTO public.stormevents_east VALUES (769246, 201808, 22, 1432, 201808, 22, 1432, 128249, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '22-AUG-18 14:32:00', 'EST-5', '22-AUG-18 14:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 12, 'E', 'VERO BEACH', 12, 'E', 'VERO BEACH', 27.656, -80.376, 27.656, -80.376, 'Scattered thunderstorms move slowly east across east-central Florida during the afternoon. A few of the storms produced strong winds along the coast as they moved offshore Brevard and Indian River Counties.', 'The ASOS at Vero Beach Airport (KVRB) reported a wind gust of 34 knots as a thunderstorm moved east to the Indian River, barrier island and nearshore Atlantic waters.');
INSERT INTO public.stormevents_east VALUES (769247, 201808, 22, 1425, 201808, 22, 1425, 128249, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '22-AUG-18 14:25:00', 'EST-5', '22-AUG-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 48, 'MG', NULL, NULL, 14, 'NNE', 'PLAYALINDA BEACH', 14, 'NNE', 'PLAYALINDA BEACH', 28.74, -80.7, 28.74, -80.7, 'Scattered thunderstorms move slowly east across east-central Florida during the afternoon. A few of the storms produced strong winds along the coast as they moved offshore Brevard and Indian River Counties.', 'USAF wind tower 0019 near Haulover Canal along the Canaveral National Seashore recorded a peak wind gust of 48 knots as a strong thunderstorm crossed the barrier island and continued into the nearshore Atlantic waters.');
INSERT INTO public.stormevents_east VALUES (773842, 201808, 10, 1135, 201808, 10, 1135, 129113, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '10-AUG-18 11:35:00', 'EST-5', '10-AUG-18 11:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 36, 'MG', NULL, NULL, 3, 'WNW', 'CAPE CANAVERAL', 3, 'WNW', 'CAPE CANAVERAL', 28.4, -80.65, 28.4, -80.65, 'A broad area of low pressure was located from the mid-Atlantic to New England, while a high pressure system was located over the southeast Gulf of Mexico. These two systems combined to produce west-northwest winds across the Florida peninsula. Moisture was plentiful across the area, and combined with daytime heating provided the necessary instability to generate showers and thunderstorms. The west winds favored the west coast sea breeze, thus many of the showers and storms that developed moved quickly towards the eastern side of central Florida. As these storms pushed across the coast of Brevard County, one storm produced strong winds along the intracoastal waters before moving offshore.', 'US Air Force wind tower measured a peak wind gust of 36 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (778028, 201808, 2, 1525, 201808, 2, 1525, 129884, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'BOX', '02-AUG-18 15:25:00', 'EST-5', '02-AUG-18 15:25:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NNE', 'ENFIELD', 1, 'ENE', 'HAZARDVILLE', 41.9781, -72.5648, 41.9832, -72.5161, 'Bermuda high pressure brought heat and humidity to Northern Connecticut. Heat indices climbed into the 90s. This tropical weather caused a few thunderstorms to develop.', 'At 3:40 PM EDT, thunderstorm winds in Enfield brought a tree down on wires at Raffia Road and South Road, and a tree down on Broad Brook Road at Water Street.');
INSERT INTO public.stormevents_east VALUES (780155, 201808, 7, 2008, 201808, 7, 2008, 130311, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '07-AUG-18 20:08:00', 'EST-5', '07-AUG-18 20:08:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'HENDERSON', 1, 'SE', 'HENDERSON', 36.3228, -78.3897, 36.3228, -78.3897, 'Thunderstorms developed along a lee trough axis and were further enhanced by a sea breeze moving inland. Some of these storms became strong to severe producing wind damage.', 'One tree was reported down on East Andrews Avenue.');
INSERT INTO public.stormevents_east VALUES (778024, 201808, 2, 1605, 201808, 2, 1605, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '02-AUG-18 16:05:00', 'EST-5', '02-AUG-18 16:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'WNW', 'BONDSVILLE', 1, 'WNW', 'BONDSVILLE', 42.2257, -72.378, 42.2257, -72.378, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:05 PM EDT, thunderstorm winds brought power lines down on North Liberty Street in Belchertown.');
INSERT INTO public.stormevents_east VALUES (778026, 201808, 2, 1515, 201808, 2, 1515, 129884, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'BOX', '02-AUG-18 15:15:00', 'EST-5', '02-AUG-18 15:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SE', 'WEST GRANBY', 1, 'SE', 'WEST GRANBY', 41.9379, -72.835, 41.9379, -72.835, 'Bermuda high pressure brought heat and humidity to Northern Connecticut. Heat indices climbed into the 90s. This tropical weather caused a few thunderstorms to develop.', 'At 3:!5 PM EDT, thunderstorm winds brought trees and power lines down on Simsbury Road at Firetown Road.  Numerous power outages.');
INSERT INTO public.stormevents_east VALUES (778027, 201808, 2, 1515, 201808, 2, 1515, 129884, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'BOX', '02-AUG-18 15:15:00', 'EST-5', '02-AUG-18 15:15:00', 0, 0, 0, 0, '5500.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'SUFFIELD', 2, 'NW', 'THOMPSONVILLE', 41.9602, -72.6494, 42.0252, -72.6273, 'Bermuda high pressure brought heat and humidity to Northern Connecticut. Heat indices climbed into the 90s. This tropical weather caused a few thunderstorms to develop.', 'At 3:25 PM EST thunderstorm winds in Suffield brought a tree down on wires on Suffield Street, and a tree down on a house on Hickory Street.');
INSERT INTO public.stormevents_east VALUES (740209, 201804, 15, 700, 201804, 16, 700, 123444, 'VIRGINIA', 51, 2018, 'April', 'Heavy Rain', 'RNK', '15-APR-18 07:00:00', 'EST-5', '16-APR-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'BUENA VISTA', 0, 'N', 'BUENA VISTA', 37.73, -79.37, 37.73, -79.37, 'A strong cold front propelled by a deep upper trough that took on a negative tilt, pushed through the region on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding but longer duration flooding occurred on several rivers and streams, mainly in the minor category. Rainfall ranged from 2 to 4 inches with locally higher amounts up to nearly 4.5 inches in 24-hours ending at 7 AM on the 16th. The highest amounts were roughly a 5-year recurrence interval (0.2 Annual exceedance probability).', 'The COOP station at Buena Vista (BUVV2) measured 2.55 inches for the 24-hour period ending 7AM on the 16th. This was the 3rd highest 1-day April rainfall total in the period of record at this location, with data starting in 1938.');
INSERT INTO public.stormevents_east VALUES (779846, 201808, 1, 2130, 201808, 1, 2143, 130233, 'SOUTH CAROLINA', 45, 2018, 'August', 'Tornado', 'GSP', '01-AUG-18 21:30:00', 'EST-5', '01-AUG-18 21:43:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SE', 'FAIRS XRDS', 1, 'SW', 'DUE WEST', 34.269, -82.419, 34.32, -82.393, 'Scattered thunderstorms and thunderstorm clusters developed across Upstate South Carolina during the afternoon and evening. One storm produced a brief, weak tornado near Due West in Abbeville County.', 'NWS storm survey confirmed a weak tornado touched down near the intersection of Highway 201 and Milford Dairy Rd and moved north-northeast for less than two miles before dissipating. Numerous trees were blown down along the path while a couple of outbuildings were heavily damaged.');
INSERT INTO public.stormevents_east VALUES (752785, 201805, 10, 1452, 201805, 10, 1453, 125287, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'RNK', '10-MAY-18 14:52:00', 'EST-5', '10-MAY-18 14:53:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'SHEPPARDS', 2, 'N', 'SHEPPARDS', 37.3898, -78.4999, 37.402, -78.4852, 'A cold front approaching from the west would prompt isolated convection in the mountains. As the front moved east of the Blue Ridge, storms intensified where higher instabilities existed, producing damaging winds and large hail.', 'Thunderstorm winds brought down at least two trees along a path from Francisco Road to Fork Road.');
INSERT INTO public.stormevents_east VALUES (782229, 201808, 3, 755, 201808, 3, 815, 130469, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '03-AUG-18 07:55:00', 'EST-5', '03-AUG-18 08:15:00', 0, 0, 0, 0, '50.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'NEW ALBANY', 0, 'WSW', 'NEW ALBANY', 41.6076, -76.4438, 41.5985, -76.4351, 'Deep tropical-like air surging into Pennsylvania interacted with areas of weak low pressure which caused several rounds of heavy rain producing thunderstorms throughout the day. These storms moved across the same locations in the northeastern part of the State.', 'Severe flooding was reported in the New Albany Public Library. Approximately 1.5 feet of water was flowing through the structure.');
INSERT INTO public.stormevents_east VALUES (782231, 201808, 3, 1115, 201808, 3, 1500, 130469, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '03-AUG-18 11:15:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NEW ALBANY', 2, 'W', 'EVERGREEN', 41.6034, -76.4547, 41.6203, -76.4591, 'Deep tropical-like air surging into Pennsylvania interacted with areas of weak low pressure which caused several rounds of heavy rain producing thunderstorms throughout the day. These storms moved across the same locations in the northeastern part of the State.', 'Two bridges were damaged and closed by raging flood waters and debris striking the bridge decks.');
INSERT INTO public.stormevents_east VALUES (782234, 201808, 3, 1430, 201808, 3, 1715, 130469, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '03-AUG-18 14:30:00', 'EST-5', '03-AUG-18 17:15:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'LACEYVILLE', 0, 'N', 'LACEYVILLE', 41.6406, -76.1955, 41.6544, -76.1694, 'Deep tropical-like air surging into Pennsylvania interacted with areas of weak low pressure which caused several rounds of heavy rain producing thunderstorms throughout the day. These storms moved across the same locations in the northeastern part of the State.', 'Serious flooding of low lying areas was occurring between Wyalusing-New Albany Road and the Susquehanna River. Flooding caused by overflow of an unnamed stream, and the Sugar Run creek.');
INSERT INTO public.stormevents_east VALUES (780979, 201808, 2, 1505, 201808, 2, 1505, 130480, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'JAX', '02-AUG-18 15:05:00', 'EST-5', '02-AUG-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'WSW', 'HICKOX', 3, 'WSW', 'HICKOX', 31.14, -82.05, 31.14, -82.05, 'A passing mid level short wave trough combined with moist SW steering flow enhanced diurnally driven sea breeze convection, which triggered a few strong to severe storms.', 'Trees and power lines were blown down along Caney Bay Road between Hoboken and Nahunta. The time of damage was based on radar data.');
INSERT INTO public.stormevents_east VALUES (782300, 201808, 11, 915, 201808, 11, 1145, 130476, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '11-AUG-18 09:15:00', 'EST-5', '11-AUG-18 11:45:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'DIMOCK', 2, 'SSE', 'DIMOCK', 41.73, -75.88, 41.7267, -75.8913, 'Deep tropical-like moisture lingered over the region as an upper level disturbance and slow moving surface front drifted into northern Pennsylvania. Thunderstorms continually developed over the area, producing significant amounts of rainfall in a short amount of time. This triggered areas of flash flooding in previously saturated, and flood damage areas.', 'Water was washing out portions of CR 3023 near Dimock.');
INSERT INTO public.stormevents_east VALUES (782301, 201808, 11, 1000, 201808, 11, 1145, 130476, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '11-AUG-18 10:00:00', 'EST-5', '11-AUG-18 11:45:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'RUSHVILLE', 2, 'NW', 'WEST AUBURN', 41.7551, -76.1208, 41.7437, -76.1232, 'Deep tropical-like moisture lingered over the region as an upper level disturbance and slow moving surface front drifted into northern Pennsylvania. Thunderstorms continually developed over the area, producing significant amounts of rainfall in a short amount of time. This triggered areas of flash flooding in previously saturated, and flood damage areas.', 'A culvert and section of pavement were washed out on Whitney Road near Rushville.');
INSERT INTO public.stormevents_east VALUES (782350, 201808, 13, 1308, 201808, 13, 1730, 130509, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 13:08:00', 'EST-5', '13-AUG-18 17:30:00', 0, 0, 0, 0, '20.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'WELLSBURG', 1, 'NW', 'WELLSBURG', 42.0034, -76.749, 42.0277, -76.7447, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Numerous roads were experiencing flash flooding and wash overs near the NY/PA border.');
INSERT INTO public.stormevents_east VALUES (781726, 201808, 17, 1748, 201808, 17, 1748, 130601, 'NEW JERSEY', 34, 2018, 'August', 'Hail', 'OKX', '17-AUG-18 17:48:00', 'EST-5', '17-AUG-18 17:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'SSE', 'RIDGEWOOD', 1, 'SSE', 'RIDGEWOOD', 40.98, -74.11, 40.98, -74.11, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', NULL);
INSERT INTO public.stormevents_east VALUES (781727, 201808, 17, 1750, 201808, 17, 1750, 130601, 'NEW JERSEY', 34, 2018, 'August', 'Hail', 'OKX', '17-AUG-18 17:50:00', 'EST-5', '17-AUG-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', 1, NULL, NULL, NULL, 1, 'N', 'GLEN ROCK', 1, 'N', 'GLEN ROCK', 40.96, -74.13, 40.96, -74.13, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', NULL);
INSERT INTO public.stormevents_east VALUES (781747, 201808, 17, 2125, 201808, 17, 2125, 130609, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'OKX', '17-AUG-18 21:25:00', 'EST-5', '17-AUG-18 21:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 0, 'SW', 'NORWALK LIGHT WXFLOW', 0, 'SW', 'NORWALK LIGHT WXFLOW', 41.0767, -73.3837, 41.0767, -73.3837, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Marine Thunderstorm wind gust of 42 knots.');
INSERT INTO public.stormevents_east VALUES (781757, 201808, 17, 2051, 201808, 17, 2051, 130609, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'OKX', '17-AUG-18 20:51:00', 'EST-5', '17-AUG-18 20:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 0, 'N', 'LAGUARDIA AIRPORT', 0, 'N', 'LAGUARDIA AIRPORT', 40.78, -73.88, 40.78, -73.88, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Marine thunderstorm wind gust of 34 knots.');
INSERT INTO public.stormevents_east VALUES (781728, 201808, 3, 1330, 201808, 3, 1430, 130606, 'VERMONT', 50, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:30:00', 'EST-5', '03-AUG-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'WEST WARDSBORO', 0, 'NE', 'WEST WARDSBORO', 43.0314, -72.8485, 43.0313, -72.8484, 'A slow-moving cold front brought several rounds of heavy rainfall and thunderstorms to eastern  New York and western New England. After passing through eastern New York, a severe thunderstorm knocked down trees and caused localized flash flooding in the towns of Putney and West Wardsboro, Vermont.', 'Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (751126, 201805, 4, 1812, 201805, 4, 1812, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:12:00', 'EST-5', '04-MAY-18 18:12:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'DOLGEVILLE', 1, 'NE', 'DOLGEVILLE', 43.11, -74.77, 43.11, -74.77, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees and wires were reported down.');
INSERT INTO public.stormevents_east VALUES (781696, 201808, 3, 1602, 201808, 3, 1702, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 16:02:00', 'EST-5', '03-AUG-18 17:02:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 0, 'N', 'RED HOOK', 0, 'N', 'RED HOOK', 42, -73.88, 42, -73.88, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 1.07 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (781697, 201808, 3, 1710, 201808, 3, 1810, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 17:10:00', 'EST-5', '03-AUG-18 18:10:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'E', 'NORTH BLENHEIM', 1, 'E', 'NORTH BLENHEIM', 42.47, -74.44, 42.47, -74.44, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 2.25 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (781659, 201808, 3, 1355, 201808, 3, 1630, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:55:00', 'EST-5', '03-AUG-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CLUMS CORNER', 1, 'NW', 'CLUMS CORNER', 42.7592, -73.5906, 42.7594, -73.5905, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Water flowing over Route 278 resulting in a road closure.');
INSERT INTO public.stormevents_east VALUES (781661, 201808, 3, 1530, 201808, 3, 1815, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 15:30:00', 'EST-5', '03-AUG-18 18:15:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'CATSKILL', 1, 'S', 'CATSKILL', 42.2097, -73.8689, 42.2098, -73.8693, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Reports of street flooding, and flooding with damage to an assisted living facility.');
INSERT INTO public.stormevents_east VALUES (781663, 201808, 3, 1530, 201808, 3, 1815, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 15:30:00', 'EST-5', '03-AUG-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WEST COXSACKIE', 1, 'SSE', 'WEST COXSACKIE', 42.36, -73.81, 42.3594, -73.8134, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Street flooding was reported.');
INSERT INTO public.stormevents_east VALUES (768601, 201808, 19, 1545, 201808, 19, 1550, 128155, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '19-AUG-18 15:45:00', 'EST-5', '19-AUG-18 15:50:00', 0, 0, 0, 0, '0.00K', NULL, 'Trained Spotter', 0.88, NULL, NULL, NULL, 2, 'NW', 'CHALK LEVEL', 2, 'NW', 'CHALK LEVEL', 36.94, -79.3122, 36.94, -79.3122, 'A cold front triggered strong to severe severe thunderstorms during the afternoon that produced hail up to the size of quarters and isolated flash flooding in Pittsylvania County. Radar estimated that heaviest rain, 3 to 5 inches in several hours, fell in the southeast along the Halifax County line, although hail may have affected these estimates. Runoff from the CREST model also showed a maximum in that same area, but no flood reports were received from there.', 'Hail up to the size of nickels fell for about five minutes along Ray Mill Road.');
INSERT INTO public.stormevents_east VALUES (768602, 201808, 19, 1605, 201808, 19, 1605, 128155, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '19-AUG-18 16:05:00', 'EST-5', '19-AUG-18 16:05:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 1, NULL, NULL, NULL, 1, 'NNE', 'CHALK LEVEL', 1, 'NNE', 'CHALK LEVEL', 36.9368, -79.2718, 36.9368, -79.2718, 'A cold front triggered strong to severe severe thunderstorms during the afternoon that produced hail up to the size of quarters and isolated flash flooding in Pittsylvania County. Radar estimated that heaviest rain, 3 to 5 inches in several hours, fell in the southeast along the Halifax County line, although hail may have affected these estimates. Runoff from the CREST model also showed a maximum in that same area, but no flood reports were received from there.', 'Hail up to the size of quarters fell at the intersection of Route 40 and Route 685 just north of Chalk Level.');
INSERT INTO public.stormevents_east VALUES (780464, 201808, 19, 2150, 201808, 19, 2250, 128155, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'RNK', '19-AUG-18 21:50:00', 'EST-5', '19-AUG-18 22:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'DRY FORK', 3, 'WSW', 'DRY FORK', 36.7777, -79.4604, 36.7284, -79.4639, 'A cold front triggered strong to severe severe thunderstorms during the afternoon that produced hail up to the size of quarters and isolated flash flooding in Pittsylvania County. Radar estimated that heaviest rain, 3 to 5 inches in several hours, fell in the southeast along the Halifax County line, although hail may have affected these estimates. Runoff from the CREST model also showed a maximum in that same area, but no flood reports were received from there.', 'Road closed due to flash flooding from Bearskin Creek near the intersection of Irish and Bearskin Roads.');
INSERT INTO public.stormevents_east VALUES (780468, 201808, 19, 700, 201808, 20, 700, 128155, 'VIRGINIA', 51, 2018, 'August', 'Heavy Rain', 'RNK', '19-AUG-18 07:00:00', 'EST-5', '20-AUG-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'CHATHAM', 0, 'N', 'CHATHAM', 36.82, -79.4, 36.82, -79.4, 'A cold front triggered strong to severe severe thunderstorms during the afternoon that produced hail up to the size of quarters and isolated flash flooding in Pittsylvania County. Radar estimated that heaviest rain, 3 to 5 inches in several hours, fell in the southeast along the Halifax County line, although hail may have affected these estimates. Runoff from the CREST model also showed a maximum in that same area, but no flood reports were received from there.', 'The COOP observer at Chatham measured 2.50 inches for 24-hours ending at 7 AM EST on the 20th. This was the highest ever for this date. Continuous records at this site date back to 1922.');
INSERT INTO public.stormevents_east VALUES (748628, 201804, 15, 1800, 201804, 15, 1803, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 18:00:00', 'EST-5', '15-APR-18 18:03:00', 3, 0, 0, 0, '6.10M', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ESE', 'TIMBERLAKE', 1, 'NE', 'TIMBERLAKE', 37.3264, -79.241, 37.3416, -79.2367, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'This is the first segment of a tornado that touched down just south of Waterlink Road near Timberlake in Campbell County at 6:00 PM EST.  The tornado uprooted trees, damaged multiple roofs from homes, damaged several businesses, and flipped several cars.  A total of 28 buildings suffered damage, and five of those buildings were completely destroyed.  The tornado crossed Timberlake Road and exited Campbell County at 6:03 PM EST.  It would continue into the western portion of the independent city of Lynchburg and further northward into Amherst County.');
INSERT INTO public.stormevents_east VALUES (748598, 201804, 15, 1406, 201804, 15, 1406, 123442, 'VIRGINIA', 51, 2018, 'April', 'Hail', 'RNK', '15-APR-18 14:06:00', 'EST-5', '15-APR-18 14:06:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 2.5, NULL, NULL, NULL, 0, 'N', 'HILLSVILLE', 0, 'N', 'HILLSVILLE', 36.77, -80.73, 36.77, -80.73, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', NULL);
INSERT INTO public.stormevents_east VALUES (766107, 201808, 6, 1745, 201808, 6, 1745, 127737, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '06-AUG-18 17:45:00', 'EST-5', '06-AUG-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'WSW', 'SYLVESTER-WORTH ARPT', 1, 'WSW', 'SYLVESTER-WORTH ARPT', 31.5474, -83.9003, 31.5474, -83.9003, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down onto Old State Route 50.');
INSERT INTO public.stormevents_east VALUES (766108, 201808, 6, 1815, 201808, 6, 1815, 127737, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '06-AUG-18 18:15:00', 'EST-5', '06-AUG-18 18:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 5, 'SW', 'RED ROCK', 5, 'SW', 'RED ROCK', 31.5282, -83.9769, 31.5282, -83.9769, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A power line was blown down near Dogwood Lane and Wynn Drive.');
