INSERT INTO public.stormevents_east VALUES (781953, 201808, 17, 1550, 201808, 17, 1550, 130639, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '17-AUG-18 15:50:00', 'EST-5', '17-AUG-18 15:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'FT WHITE', 1, 'E', 'FT WHITE', 29.92, -82.71, 29.92, -82.71, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'Thunderstorm wind gusts damaged some property in the Holling Woods Estate Neighborhood.');
INSERT INTO public.stormevents_east VALUES (781954, 201808, 17, 1553, 201808, 17, 1553, 130639, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '17-AUG-18 15:53:00', 'EST-5', '17-AUG-18 15:53:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'ELLISVILLE', 1, 'N', 'ELLISVILLE', 30.02, -82.6, 30.02, -82.6, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'Numeorus trees were blown down across the county. The time of damage was based on radar.');
