INSERT INTO public.stormevents_east VALUES (781956, 201808, 17, 1601, 201808, 17, 1601, 130639, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '17-AUG-18 16:01:00', 'EST-5', '17-AUG-18 16:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Park/Forest Service', 50, 'EG', NULL, NULL, 6, 'S', 'ELLISVILLE', 6, 'S', 'ELLISVILLE', 29.92, -82.59, 29.92, -82.59, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'A couple trees and several limbs were blown down near the Oleno State Park ranger office. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (781957, 201808, 17, 1526, 201808, 17, 1526, 130639, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '17-AUG-18 15:26:00', 'EST-5', '17-AUG-18 15:26:00', 0, 0, 0, 0, '0.01K', '0.00K', 'Trained Spotter', 49, 'EG', NULL, NULL, 2, 'SSW', 'ARREDONDA', 2, 'SSW', 'ARREDONDA', 29.57, -82.44, 29.57, -82.44, 'SW steering flow and cooler 500 mb temperatures of -7C to -9C combined moisture and instability over the area which triggered strong to pulse severe storms along sea breeze and outflow mergers.', 'A spotter estimated wind gusts near 60 mph which blew down some branches. Pea size hail was also observed. The cost of tree damage was estimated.');
INSERT INTO public.stormevents_east VALUES (781958, 201808, 18, 1850, 201808, 18, 1850, 130640, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '18-AUG-18 18:50:00', 'EST-5', '18-AUG-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'WSW', 'BEEGHLY HGTS', 2, 'WSW', 'BEEGHLY HGTS', 30.47, -81.71, 30.47, -81.71, 'Sea breeze storms developed with a drier airmass limiting convective coverage compared to recent days.', 'A tree was blown down at the intersection of Terrell Road and Lem Turner Road. Multiple tree limbs were blown down across the road. Pea size hail was also reported.');
INSERT INTO public.stormevents_east VALUES (781961, 201808, 21, 1730, 201808, 21, 1730, 130643, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'JAX', '21-AUG-18 17:30:00', 'EST-5', '21-AUG-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 35, 'EG', NULL, NULL, 8, 'WSW', 'FLAGLER BEACH', 8, 'WSW', 'FLAGLER BEACH', 29.47, -81.13, 29.47, -81.13, 'Sea breezes merged across the eastern side SE GA and NE FL which produced some strong wind gusts.', 'A spotter estimated wind gusts of 40 mph in Flagler Beach.');
INSERT INTO public.stormevents_east VALUES (781964, 201808, 25, 1700, 201808, 25, 1700, 130644, 'FLORIDA', 12, 2018, 'August', 'Flood', 'JAX', '25-AUG-18 17:00:00', 'EST-5', '25-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'COTTON PLANT', 1, 'WSW', 'COTTON PLANT', 29.17, -82.34, 29.173, -82.3337, 'NE flow focused stronger east coast sea breeze inland with strong storms impacting Marion county into the early evening.', 'Moving flood water was reported across westbound lanes of State Road 40 near Rainbow Lakes Estates.');
INSERT INTO public.stormevents_east VALUES (763192, 201808, 1, 2145, 201808, 1, 2145, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '01-AUG-18 21:45:00', 'EST-5', '01-AUG-18 21:45:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'LANARK', 1, 'SE', 'LANARK', 40.54, -75.42, 40.54, -75.42, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'There were numerous reports of trees and wires being down.');
INSERT INTO public.stormevents_east VALUES (763191, 201808, 1, 2142, 201808, 1, 2142, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '01-AUG-18 21:42:00', 'EST-5', '01-AUG-18 21:42:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'EAST PENN JCT', 1, 'ESE', 'EAST PENN JCT', 40.59, -75.43, 40.59, -75.43, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'Numerous trees and wires were reported to be down.');
INSERT INTO public.stormevents_east VALUES (763193, 201808, 1, 2150, 201808, 1, 2150, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '01-AUG-18 21:50:00', 'EST-5', '01-AUG-18 21:50:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'STEEL CITY', 1, 'SSW', 'STEEL CITY', 40.61, -75.34, 40.61, -75.34, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'A large tree was reported to be down.');
INSERT INTO public.stormevents_east VALUES (763194, 201808, 1, 2154, 201808, 1, 2154, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '01-AUG-18 21:54:00', 'EST-5', '01-AUG-18 21:54:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'FARMERSVILLE', 2, 'SSE', 'FARMERSVILLE', 40.64, -75.28, 40.64, -75.28, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'A tree was reported down in the area.');
INSERT INTO public.stormevents_east VALUES (780584, 201808, 12, 1033, 201808, 12, 1300, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flash Flood', 'BOX', '12-AUG-18 10:33:00', 'EST-5', '12-AUG-18 13:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'WEST PEABODY', 1, 'N', 'SOUTH PEABODY', 42.53, -70.97, 42.5151, -70.9504, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 10:33 AM EST, Quail Road in South Peabody was closed due to flooding. At 10:52 AM EST, Lynnfield Street was closed due to flooding. At 11:07 AM EST, a car was reported trapped in floodwaters on Lynnfield Street.  At 11:14 AM a car was trapped in floodwaters on Lake Street near U.S. Route 1; Lake Street was reported closed soon after. At 11:33 AM EST, a house on Batchelder Avenue was reported to have 4 feet of water in the basement.');
INSERT INTO public.stormevents_east VALUES (780587, 201808, 12, 630, 201808, 12, 930, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 06:30:00', 'EST-5', '12-AUG-18 09:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'CHARLESTOWN', 2, 'S', 'CHARLESTOWN', 42.3679, -71.0665, 42.3554, -71.0704, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 6:30 AM EST, Storrow Drive near U.S. Route 1 was flooded and impassable, with a car trapped in the floodwaters. At 6:33 AM EST, Storrow Drive was also flooded and impassable in the Lagoon area along the Back Bay; cars were driving across the median to avoid the flooding.  At 6:40 AM a car was trapped in floodwaters under the Massachusetts Avenue bridge.  At 6:49 AM Heath Street was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (780592, 201808, 12, 638, 201808, 12, 900, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 06:38:00', 'EST-5', '12-AUG-18 09:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'EAST EVERETT', 0, 'ENE', 'EAST EVERETT', 42.4018, -71.0457, 42.4018, -71.0445, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 6:38 AM EST a car was trapped in floodwaters on Vale Street at Boston Street in Everett.');
INSERT INTO public.stormevents_east VALUES (780595, 201808, 12, 646, 201808, 12, 1000, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 06:46:00', 'EST-5', '12-AUG-18 10:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'CAMBRIDGE', 1, 'SSE', 'CAMBRIDGE', 42.3574, -71.0933, 42.3567, -71.0928, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 6:46 AM, Memorial Drive in Cambridge was flooded and impassable at Massachusetts Avenue.  Multiple cars were trapped in floodwaters.');
INSERT INTO public.stormevents_east VALUES (779872, 201808, 12, 1017, 201808, 12, 1019, 130247, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'ILM', '12-AUG-18 10:17:00', 'EST-5', '12-AUG-18 10:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 38, 'MG', NULL, NULL, 2, 'NW', 'SHEEPSHEAD ROCK', 2, 'NW', 'SHEEPSHEAD ROCK', 33.96, -77.94, 33.96, -77.94, 'A cold front produced strong winds along the coast.', 'A 44 mph gust was recorded at Federal Point.');
INSERT INTO public.stormevents_east VALUES (779876, 201808, 15, 1530, 201808, 15, 1830, 130249, 'NORTH CAROLINA', 37, 2018, 'August', 'Flood', 'ILM', '15-AUG-18 15:30:00', 'EST-5', '15-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'BAYMEADE', 0, 'NNE', 'BAYMEADE', 34.2724, -77.8186, 34.2752, -77.8173, 'An isolated stationary storm dumped four inches of rain.', 'A slow moving storm produced four inches of rain in Ogden.  Police closed Bright Leaf Road at Wendover Lane. Flooding was also reported in the 7400 block of Market Street and on Amsterdam Way.');
INSERT INTO public.stormevents_east VALUES (781407, 201808, 5, 1130, 201808, 5, 1130, 130524, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '05-AUG-18 11:30:00', 'EST-5', '05-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 22, 'N', 'KEY BISCAYNE', 22, 'N', 'KEY BISCAYNE', 26.09, -80.12, 26.09, -80.12, 'High pressure across the western Atlantic Ocean brought deep easterly flow across South Florida, leading to morning showers and storms across the local Atlantic waters. This activity produced several strong wind gusts as it moved into the coasts of Broward and Miami-Dade counties.', 'A wind gust from the E of 43 mph/39 knots was measured at WxFlow site XPEG in Port Everglades at a height of 135 feet.');
INSERT INTO public.stormevents_east VALUES (781408, 201808, 5, 1139, 201808, 5, 1139, 130524, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '05-AUG-18 11:39:00', 'EST-5', '05-AUG-18 11:39:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 9, 'SSW', 'KEY BISCAYNE', 9, 'SSW', 'KEY BISCAYNE', 25.66, -80.19, 25.66, -80.19, 'High pressure across the western Atlantic Ocean brought deep easterly flow across South Florida, leading to morning showers and storms across the local Atlantic waters. This activity produced several strong wind gusts as it moved into the coasts of Broward and Miami-Dade counties.', 'A wind gust from the ENE at 39 mph/34 knots was measured at WxFlow site XKBS on Biscayne Bay at a height of 20 feet.');
INSERT INTO public.stormevents_east VALUES (781411, 201808, 9, 1956, 201808, 9, 1956, 130526, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '09-AUG-18 19:56:00', 'EST-5', '09-AUG-18 19:56:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 42, 'MG', NULL, NULL, 13, 'NE', 'KREAMER ISLAND', 13, 'NE', 'KREAMER ISLAND', 26.92, -80.61, 26.92, -80.61, 'While storm coverage was limited, dry air from the Saharan Air Layer helped enhance the strength of afternoon showers and storms. Late day activity due to the collision of the lake breeze and east coast seabreeze led to a strong storm along the east side of Lake Okeechobee that produced a strong wind gust.', 'SFWMD mesonet site C10a S-271  recorded a gust to 42 knots/48 mph with a thunderstorm on the east side of Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (781417, 201808, 10, 1445, 201808, 10, 1445, 130528, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '10-AUG-18 14:45:00', 'EST-5', '10-AUG-18 14:45:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 7, 'S', 'PORT MAYACA', 7, 'S', 'PORT MAYACA', 26.9, -80.79, 26.9, -80.79, 'Showers and storms developed along both seabreezes during the early afternoon hours, with several strong storms affecting Lake Okeechobee and producing strong wind gusts. An additional strong outflow boundary that moved from Central Florida into South Florida during the evening hours produced additional strong storms that affected the nearshore Atlantic waters.', 'The SFWMD LZ-40 tower in Lake Okeechobee reported a wind gust of 42 mph/36 kts at 345 pm EDT.');
INSERT INTO public.stormevents_east VALUES (781418, 201808, 10, 1445, 201808, 10, 1445, 130528, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '10-AUG-18 14:45:00', 'EST-5', '10-AUG-18 14:45:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 5, 'NW', 'KREAMER ISLAND', 5, 'NW', 'KREAMER ISLAND', 26.82, -80.78, 26.82, -80.78, 'Showers and storms developed along both seabreezes during the early afternoon hours, with several strong storms affecting Lake Okeechobee and producing strong wind gusts. An additional strong outflow boundary that moved from Central Florida into South Florida during the evening hours produced additional strong storms that affected the nearshore Atlantic waters.', 'The SFWMD L-6 tower in Lake Okeechobee reported a wind gust of 44 mph/38 kts at 345 pm EDT.');
INSERT INTO public.stormevents_east VALUES (779541, 201808, 11, 640, 201808, 11, 801, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 06:40:00', 'EST-5', '11-AUG-18 08:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'SCOTCH PLAINS', 0, 'SE', 'SCOTCH PLAINS', 40.645, -74.3707, 40.6457, -74.364, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Widespread flooding was reported across the town of Scotch Plains, including two water rescues from vehicles.');
INSERT INTO public.stormevents_east VALUES (779542, 201808, 11, 731, 201808, 11, 801, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 07:31:00', 'EST-5', '11-AUG-18 08:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'EAST NEWARK', 1, 'SSW', 'EAST NEWARK', 40.7383, -74.1562, 40.7401, -74.1561, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Frank E. Rogers Boulevard was under water near the PATH station in Harrison.');
INSERT INTO public.stormevents_east VALUES (779555, 201808, 11, 750, 201808, 11, 900, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 07:50:00', 'EST-5', '11-AUG-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'FAIRVIEW', 1, 'E', 'PALISADES PARK', 40.8054, -73.9904, 40.829, -73.9705, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Cars were stranded on River Road in Edgewater due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (779558, 201808, 11, 751, 201808, 11, 900, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 07:51:00', 'EST-5', '11-AUG-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'JERSEY CITY ARPT', 1, 'S', 'JERSEY CITY ARPT', 40.7057, -74.0995, 40.706, -74.0988, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Manhole covers were being pushed up resulting in flash flooding on Danforth Avenue in Jersey City.');
INSERT INTO public.stormevents_east VALUES (769248, 201808, 22, 1435, 201808, 22, 1435, 128249, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '22-AUG-18 14:35:00', 'EST-5', '22-AUG-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 38, 'MG', NULL, NULL, 9, 'ENE', 'PLAYALINDA BEACH', 9, 'ENE', 'PLAYALINDA BEACH', 28.6, -80.64, 28.6, -80.64, 'Scattered thunderstorms move slowly east across east-central Florida during the afternoon. A few of the storms produced strong winds along the coast as they moved offshore Brevard and Indian River Counties.', 'USAF wind tower 0311 recorded a peak wind gust of 38 knots as a strong thunderstorm crossed the northern portion of Cape Canaveral and continued offshore.');
INSERT INTO public.stormevents_east VALUES (767184, 201808, 17, 1645, 201808, 17, 1645, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 16:45:00', 'EST-5', '17-AUG-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'N', 'GERMANSVILLE', 1, 'N', 'GERMANSVILLE', 40.71, -75.7, 40.71, -75.7, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Tree Down - Snyder Drive and Quarry Road.');
INSERT INTO public.stormevents_east VALUES (767186, 201808, 17, 1657, 201808, 17, 1657, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 16:57:00', 'EST-5', '17-AUG-18 16:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SSW', 'WINDSOR CASTLE', 1, 'SSW', 'WINDSOR CASTLE', 40.51, -75.94, 40.51, -75.94, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Tree down - Bellevue Avenue.');
INSERT INTO public.stormevents_east VALUES (767187, 201808, 17, 1700, 201808, 17, 1700, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:00:00', 'EST-5', '17-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'E', 'BATH', 1, 'E', 'BATH', 40.73, -75.39, 40.73, -75.39, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Two trees down.');
INSERT INTO public.stormevents_east VALUES (767191, 201808, 17, 1700, 201808, 17, 1700, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:00:00', 'EST-5', '17-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'KLECKNERSVILLE', 1, 'W', 'KLECKNERSVILLE', 40.78, -75.43, 40.78, -75.43, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Several reports of downed trees and power lines in Moore Twp...Allen Twp...and Chapman. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (767193, 201808, 17, 1702, 201808, 17, 1702, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:02:00', 'EST-5', '17-AUG-18 17:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SW', 'ALSACE MANOR', 1, 'SW', 'ALSACE MANOR', 40.39, -75.86, 40.39, -75.86, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Tree Down on Oley Road.');
INSERT INTO public.stormevents_east VALUES (767194, 201808, 17, 1703, 201808, 17, 1703, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:03:00', 'EST-5', '17-AUG-18 17:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'SSE', 'SAYLORSBURG', 2, 'SSE', 'SAYLORSBURG', 40.87, -75.3, 40.87, -75.3, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Trees down in wires. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (767195, 201808, 17, 1703, 201808, 17, 1703, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:03:00', 'EST-5', '17-AUG-18 17:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SE', 'CLEARFIELD', 1, 'SE', 'CLEARFIELD', 40.79, -75.34, 40.79, -75.34, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Multiple reports of trees and wires down in Bushkill Township.');
INSERT INTO public.stormevents_east VALUES (773996, 201808, 19, 1800, 201808, 19, 2000, 129140, 'FLORIDA', 12, 2018, 'August', 'Flood', 'MLB', '19-AUG-18 18:00:00', 'EST-5', '19-AUG-18 20:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'WESTWOOD', 1, 'WNW', 'WESTWOOD', 28.5783, -81.4715, 28.576, -81.4714, 'Slow moving thunderstorms produced heavy rain in a short period of time leading to localized flooding in the Pine Hills area of Orlando. A few roads were briefly closed to traffic after several cars become stranded due to high water.', 'Slow moving thunderstorms produced three to five inches of rain in less than two hours over the Pine Hills area of Orlando. A few major roadways were temporarily closed to traffic after three or four cars become stuck in water two to three feet deep within a very localized area. Poor or blocked drainage may have also contributed to the localized problem. The nearest rain gauge, located eight miles southeast at Orlando Executive Airport measured 3.83 inches in less than 3-hours and radar estimated rain at the flood location indicated four to five inches fell.');
INSERT INTO public.stormevents_east VALUES (774010, 201808, 9, 1700, 201808, 9, 1700, 129144, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '09-AUG-18 17:00:00', 'EST-5', '09-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 50, 'MG', NULL, NULL, 5, 'NNE', 'PLAYALINDA BEACH', 5, 'NNE', 'PLAYALINDA BEACH', 28.61, -80.75, 28.61, -80.75, 'A broken line of strong thunderstorm moved quickly east from the mainland to across Cape Canaveral and the adjacent intracoastal, coastal and offshore waters. Many of the storms produced wind gusts between 35 and 50 knots.', 'USAF wind tower 0714 within the Merritt Island National Wildlife Refuge, east of Titusville, recorded a peak wind of 50 knots from the southwest as a severe thunderstorm moved across northern Merritt Island toward the Atlantic.');
INSERT INTO public.stormevents_east VALUES (778025, 201808, 2, 1615, 201808, 2, 1615, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '02-AUG-18 16:15:00', 'EST-5', '02-AUG-18 16:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'MONSON', 1, 'SW', 'MONSON', 42.0935, -72.3274, 42.0935, -72.3274, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:15 PM EDT, a tree was brought down on power lines on Ely Road in Monson.');
INSERT INTO public.stormevents_east VALUES (778048, 201808, 3, 1612, 201808, 3, 1815, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '03-AUG-18 16:12:00', 'EST-5', '03-AUG-18 18:15:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GREENFIELD', 1, 'NNW', 'TURNERS FALLS', 42.5878, -72.5973, 42.6075, -72.5566, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:12 PM EST heavy rain in Greenfield caused flooding of several basements on Franklin Street. At 4:33 PM EST Scout Road was flooded and impassable with some basement flooding.  At 4:36 EST PM Sanderson Road near Kennemetal and the Medical Center was completely flooded. At 4:46 PM EST Adams Road was flooded and impassable. At 5:06 PM EST Green Street in Greenfield had significant basement flooding.');
INSERT INTO public.stormevents_east VALUES (778049, 201808, 3, 1725, 201808, 3, 2000, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '03-AUG-18 17:25:00', 'EST-5', '03-AUG-18 20:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'WENDELL DEPOT', 1, 'SE', 'WENDELL DEPOT', 42.5978, -72.3623, 42.5929, -72.3413, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 5:25 PM EST, downpours near Orange caused significant street flooding, with Rocks washed onto state routes 2 and 2A west of Lyman Contractors.');
INSERT INTO public.stormevents_east VALUES (778050, 201808, 3, 1725, 201808, 3, 2000, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '03-AUG-18 17:25:00', 'EST-5', '03-AUG-18 20:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'TURNERS FALLS', 0, 'SW', 'TURNERS FALLS', 42.6049, -72.5621, 42.5955, -72.5556, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:12 PM EST flooding from heavy rain forced manhole covers off their settings on Avenue A near Food City Plaza in Turners Falls, and made the road impassable.  At 5:25 PM EST Griswold Street and Avenue C in Turners Falls were flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (781737, 201808, 8, 1954, 201808, 8, 1954, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 19:54:00', 'EST-5', '08-AUG-18 19:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SW', 'OWENS', 1, 'SW', 'OWENS', 35.0397, -78.9666, 35.0397, -78.9666, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was reported down near the intersection of Sequoia Road and Elder Lane.');
INSERT INTO public.stormevents_east VALUES (781741, 201808, 8, 1951, 201808, 8, 1951, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 19:51:00', 'EST-5', '08-AUG-18 19:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'WSW', 'FENIX', 2, 'WSW', 'FENIX', 35.014, -79.0615, 35.014, -79.0615, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was reported down near the intersction of Stoney Point Road and Galatia Church Road.');
INSERT INTO public.stormevents_east VALUES (782351, 201808, 13, 1315, 201808, 13, 1730, 130509, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 13:15:00', 'EST-5', '13-AUG-18 17:30:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'SOUTHPORT', 2, 'S', 'SOUTHPORT', 42.0286, -76.8375, 42.0202, -76.8266, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flash flooding swept a car down Christian Hollow Road.');
INSERT INTO public.stormevents_east VALUES (774391, 201807, 30, 825, 201807, 30, 1000, 128281, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '30-JUL-18 08:25:00', 'EST-5', '30-JUL-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ST INIGOES', 1, 'N', 'ST INIGOES', 38.16, -76.4, 38.1608, -76.399, 'Isolated heavy rain during the morning hours of July 30th totalled over four inches in southern Saint Mary''s County, causing several localized instances of flooding.', 'Villa Road flooded and closed near Point Lookout Road, with high water reported over the entire roadway.');
INSERT INTO public.stormevents_east VALUES (781743, 201808, 8, 1930, 201808, 8, 1930, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 19:30:00', 'EST-5', '08-AUG-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'PIKEVILLE', 0, 'N', 'PIKEVILLE', 35.5, -77.98, 35.5, -77.98, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Two trees reported down in Pikeville.');
INSERT INTO public.stormevents_east VALUES (781745, 201808, 8, 1916, 201808, 8, 1916, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 19:16:00', 'EST-5', '08-AUG-18 19:16:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'NE', 'ROCKINGHAM', 1, 'NE', 'ROCKINGHAM', 34.94, -79.77, 34.94, -79.77, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Trees were reported down on power-line in downtown Rockingham.');
INSERT INTO public.stormevents_east VALUES (781751, 201808, 8, 1912, 201808, 8, 1940, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 19:12:00', 'EST-5', '08-AUG-18 19:40:00', 0, 0, 0, 0, '15.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'HARRIS', 3, 'W', 'CAMERON', 35.2815, -79.571, 35.325, -79.3018, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Numerous trees and power-lines down throughout the county.');
INSERT INTO public.stormevents_east VALUES (779526, 201808, 1, 700, 201808, 2, 700, 130178, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '01-AUG-18 07:00:00', 'EST-5', '02-AUG-18 07:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'W', 'COXSACKIE', 1, 'W', 'COXSACKIE', 42.35, -73.81, 42.35, -73.81, 'An area of rainfall with embedded thunderstorms brought a swath of 1 to 3 inches from the eastern Catskills through the Capital District and into southern Vermont.', 'Total 24 hour rainfall reports ranged from 1.7 inches to 1.91 inches in Greene county.');
INSERT INTO public.stormevents_east VALUES (779527, 201808, 1, 700, 201808, 2, 700, 130178, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '01-AUG-18 07:00:00', 'EST-5', '02-AUG-18 07:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'N', 'DENNING', 1, 'N', 'DENNING', 41.97, -74.5, 41.97, -74.5, 'An area of rainfall with embedded thunderstorms brought a swath of 1 to 3 inches from the eastern Catskills through the Capital District and into southern Vermont.', 'Total 24 hour rainfall reports ranged from 0.6 inches to 3.14 inches in Ulster county.');
INSERT INTO public.stormevents_east VALUES (779528, 201808, 1, 700, 201808, 2, 700, 130178, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '01-AUG-18 07:00:00', 'EST-5', '02-AUG-18 07:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NE', 'COPAKE FALLS', 1, 'NE', 'COPAKE FALLS', 42.13, -73.51, 42.13, -73.51, 'An area of rainfall with embedded thunderstorms brought a swath of 1 to 3 inches from the eastern Catskills through the Capital District and into southern Vermont.', 'Total 24 hour rainfall reports ranged from 0.90 inches to 1.62 inches across Columbia county.');
INSERT INTO public.stormevents_east VALUES (779529, 201808, 1, 700, 201808, 2, 700, 130178, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '01-AUG-18 07:00:00', 'EST-5', '02-AUG-18 07:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NW', 'KINDERHOOK', 1, 'NW', 'KINDERHOOK', 42.41, -73.72, 42.41, -73.72, 'An area of rainfall with embedded thunderstorms brought a swath of 1 to 3 inches from the eastern Catskills through the Capital District and into southern Vermont.', 'Total 24 hour rainfall reports ranged from 0.90 inches to 1.62 inches across Columbia county.');
INSERT INTO public.stormevents_east VALUES (779532, 201808, 1, 700, 201808, 2, 700, 130178, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '01-AUG-18 07:00:00', 'EST-5', '02-AUG-18 07:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'ESE', 'SOUTH SCHODACK', 2, 'ESE', 'SOUTH SCHODACK', 42.51, -73.68, 42.51, -73.68, 'An area of rainfall with embedded thunderstorms brought a swath of 1 to 3 inches from the eastern Catskills through the Capital District and into southern Vermont.', 'Total 24 hour rainfall reports ranged from less than half an inch of rain to 1.91 inches across Rensselaer county.');
INSERT INTO public.stormevents_east VALUES (779533, 201808, 1, 700, 201808, 2, 700, 130178, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '01-AUG-18 07:00:00', 'EST-5', '02-AUG-18 07:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'E', 'ELKA PARK', 2, 'E', 'ELKA PARK', 42.17, -74.12, 42.17, -74.12, 'An area of rainfall with embedded thunderstorms brought a swath of 1 to 3 inches from the eastern Catskills through the Capital District and into southern Vermont.', 'Total 24 hour rainfall reports ranged from 0.74 inches to 1.92 inches across Greene county.');
INSERT INTO public.stormevents_east VALUES (774394, 201807, 30, 845, 201807, 30, 1045, 128281, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '30-JUL-18 08:45:00', 'EST-5', '30-JUL-18 10:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'BEACHVILLE', 0, 'WSW', 'ST INIGOES', 38.1472, -76.4136, 38.1477, -76.4077, 'Isolated heavy rain during the morning hours of July 30th totalled over four inches in southern Saint Mary''s County, causing several localized instances of flooding.', 'Beachville Road was reported flooded and closed between Grayson Road and Jutland Road.');
INSERT INTO public.stormevents_east VALUES (774498, 201807, 25, 1809, 201807, 25, 1915, 128279, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 18:09:00', 'EST-5', '25-JUL-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'TENLEYTOWN', 1, 'ENE', 'TENLEYTOWN', 38.9563, -77.0589, 38.9538, -77.057, 'Locally heavy rain fell in Washington DC on the afternoon of July 25th. This caused flash flooding at rush hour in the metro area.', 'High rushing water reported over Broad Branch Road in Northwest DC with Broad Branch out of its banks.');
INSERT INTO public.stormevents_east VALUES (781698, 201808, 3, 1719, 201808, 3, 1819, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 17:19:00', 'EST-5', '03-AUG-18 18:19:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'WNW', 'CARMAN', 2, 'WNW', 'CARMAN', 42.78, -73.95, 42.78, -73.95, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 1.5 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (781699, 201808, 3, 1721, 201808, 3, 1821, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 17:21:00', 'EST-5', '03-AUG-18 18:21:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'S', 'KINDERHOOK', 1, 'S', 'KINDERHOOK', 42.39, -73.7, 42.39, -73.7, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 1.76 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (782195, 201808, 7, 540, 201808, 7, 540, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 05:40:00', 'EST-5', '07-AUG-18 05:40:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 52, 'EG', NULL, NULL, 0, 'N', 'ALLAGASH', 0, 'N', 'ALLAGASH', 47.08, -69.05, 47.08, -69.05, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Two trees were toppled on the Farm Road by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (780473, 201808, 19, 2215, 201808, 19, 2315, 130374, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RNK', '19-AUG-18 22:15:00', 'EST-5', '19-AUG-18 23:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'YARBRO', 1, 'NNE', 'YARBRO', 36.4906, -79.209, 36.509, -79.1963, 'A slow-moving frontal boundary triggered more widespread showers and thunderstorms during the afternoon and evening of the 19th with some flash flooding reported in northeast Caswell County. Rainfall of 2 to 5 inches in several hours occurred across parts of the area with significant runoff per hydrologic models.', 'Jack Pointer Road was closed due to flash flooding along Kilgore Creek, with water reported over the bridge.');
INSERT INTO public.stormevents_east VALUES (782198, 201808, 19, 630, 201808, 19, 630, 130374, 'NORTH CAROLINA', 37, 2018, 'August', 'Heavy Rain', 'RNK', '19-AUG-18 06:30:00', 'EST-5', '19-AUG-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'SSW', 'SEMORA', 1, 'SSW', 'SEMORA', 36.4866, -79.1569, 36.4866, -79.1569, 'A slow-moving frontal boundary triggered more widespread showers and thunderstorms during the afternoon and evening of the 19th with some flash flooding reported in northeast Caswell County. Rainfall of 2 to 5 inches in several hours occurred across parts of the area with significant runoff per hydrologic models.', 'The CoCoRaHS observer at Hyco (NC-CS-1) measured 3.00 inches in 24-hours ending at 730 AM local time.');
INSERT INTO public.stormevents_east VALUES (781742, 201808, 7, 1315, 201808, 7, 1315, 130611, 'NEW YORK', 36, 2018, 'August', 'Hail', 'ALY', '07-AUG-18 13:15:00', 'EST-5', '07-AUG-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 1, 'SW', 'CLIFTON PARK', 1, 'SW', 'CLIFTON PARK', 42.87, -73.79, 42.87, -73.79, 'Scattered showers and thunderstorms developed within a humid, warm airmass across eastern New York. Some of these storms became severe, resulting in numerous trees and wires down along with hail.', NULL);
INSERT INTO public.stormevents_east VALUES (781759, 201808, 7, 1420, 201808, 7, 1420, 130611, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '07-AUG-18 14:20:00', 'EST-5', '07-AUG-18 14:20:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'W', 'COUSE', 1, 'W', 'COUSE', 42.62, -73.72, 42.62, -73.72, 'Scattered showers and thunderstorms developed within a humid, warm airmass across eastern New York. Some of these storms became severe, resulting in numerous trees and wires down along with hail.', 'Trees and wires downed.');
INSERT INTO public.stormevents_east VALUES (781768, 201808, 8, 1819, 201808, 8, 1819, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:19:00', 'EST-5', '08-AUG-18 18:19:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'E', 'PINSON', 3, 'E', 'PINSON', 35.5176, -79.9724, 35.5176, -79.9724, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was reported down near the intersection of Burney Mill Road and Lassister Mill Road.');
INSERT INTO public.stormevents_east VALUES (773381, 201808, 7, 1400, 201808, 7, 1400, 128985, 'VERMONT', 50, 2018, 'August', 'Thunderstorm Wind', 'BTV', '07-AUG-18 14:00:00', 'EST-5', '07-AUG-18 14:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'CASTLETON', 0, 'N', 'CASTLETON', 43.62, -73.18, 43.62, -73.18, 'A cold front moved across the region in the morning  hours of August 7th, with scattered showers and thunderstorms accompanied the front. One thunderstorm briefly pulsed up in intensity to deliver a brief wind gust that knocked down some trees.', 'Vermont DMV reported trees and power lines down on Route  30.');
INSERT INTO public.stormevents_east VALUES (740205, 201804, 15, 700, 201804, 16, 700, 123443, 'NORTH CAROLINA', 37, 2018, 'April', 'Heavy Rain', 'RNK', '15-APR-18 07:00:00', 'EST-5', '16-APR-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'E', 'JEFFERSON', 2, 'E', 'JEFFERSON', 36.42, -81.444, 36.42, -81.444, 'A strong cold front propelled by an deep upper trough that took on a negative tilt pushed through on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding by longer duration flooding occurred on several rivers and streams.', 'The COOP station at Jefferson 2E (JEFN7) measured 3.20 inches of rain for the 24-hour period ending 7AM on the 16th. This was the 3rd highest 1-day April rainfall total in the period of record at this location, with data starting in 1896.');
INSERT INTO public.stormevents_east VALUES (746056, 201804, 15, 2235, 201804, 16, 1212, 123443, 'NORTH CAROLINA', 37, 2018, 'April', 'Flood', 'RNK', '15-APR-18 22:35:00', 'EST-5', '16-APR-18 12:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'VALLE CRUCIS', 1, 'NW', 'VALLE CRUCIS', 36.2145, -81.784, 36.2265, -81.788, 'A strong cold front propelled by an deep upper trough that took on a negative tilt pushed through on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding by longer duration flooding occurred on several rivers and streams.', 'The Watauga River at Sugar Grove (SGWN7) rose very rapidly,  cresting at 10.39 feet, well above the Minor Flood Stage of 6 feet. Several low water bridges were flooded roads near the river were also flooded and closed.');
INSERT INTO public.stormevents_east VALUES (766113, 201808, 8, 1526, 201808, 8, 1526, 127738, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '08-AUG-18 15:26:00', 'EST-5', '08-AUG-18 15:26:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'MERRILLVILLE', 1, 'WSW', 'MERRILLVILLE', 30.9324, -83.8872, 30.9324, -83.8872, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A couple of trees were blown down near the intersection of Dillon Road and Clyde Griffin Road just north of Thomasville airport.');
INSERT INTO public.stormevents_east VALUES (766114, 201808, 8, 1604, 201808, 8, 1604, 127738, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '08-AUG-18 16:04:00', 'EST-5', '08-AUG-18 16:04:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'TWIN LAKES', 1, 'SW', 'TWIN LAKES', 30.6827, -83.2074, 30.6827, -83.2074, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A power line was blown down at 401 Francis Drive in Lake Park.');
INSERT INTO public.stormevents_east VALUES (766115, 201808, 8, 1607, 201808, 8, 1607, 127738, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '08-AUG-18 16:07:00', 'EST-5', '08-AUG-18 16:07:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'E', 'I-75 AT EXIT 11', 0, 'E', 'I-75 AT EXIT 11', 30.7498, -83.2679, 30.7498, -83.2679, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down on Touchton Road.');
INSERT INTO public.stormevents_east VALUES (766116, 201808, 8, 1607, 201808, 8, 1607, 127738, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '08-AUG-18 16:07:00', 'EST-5', '08-AUG-18 16:07:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'I-75 AT EXIT 11', 1, 'SW', 'I-75 AT EXIT 11', 30.7403, -83.279, 30.7403, -83.279, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down on Madison Highway.');
INSERT INTO public.stormevents_east VALUES (766117, 201808, 8, 1637, 201808, 8, 1637, 127738, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '08-AUG-18 16:37:00', 'EST-5', '08-AUG-18 16:37:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SW', '(VAD)MOODY AFB', 3, 'SW', '(VAD)MOODY AFB', 30.937, -83.2231, 30.937, -83.2231, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down on Lori Street.');
INSERT INTO public.stormevents_east VALUES (766119, 201808, 10, 1850, 201808, 10, 1850, 127741, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '10-AUG-18 18:50:00', 'EST-5', '10-AUG-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'E', 'AMBOY', 2, 'E', 'AMBOY', 31.7931, -83.5513, 31.7931, -83.5513, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'Multiple trees were blown down along Amboy-Rebecca Road.');
INSERT INTO public.stormevents_east VALUES (780160, 201808, 7, 2125, 201808, 7, 2125, 130311, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '07-AUG-18 21:25:00', 'EST-5', '07-AUG-18 21:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'COLERIDGE', 1, 'S', 'COLERIDGE', 35.6353, -79.6268, 35.6353, -79.6268, 'Thunderstorms developed along a lee trough axis and were further enhanced by a sea breeze moving inland. Some of these storms became strong to severe producing wind damage.', 'One tree was reported down near the intersection of Highway 42 and Doc Hayworth Road.');
INSERT INTO public.stormevents_east VALUES (781160, 201808, 19, 1922, 201808, 19, 2129, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '19-AUG-18 19:22:00', 'EST-5', '19-AUG-18 21:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'GENTRYS STORE', 3, 'E', 'HYCO JCT', 36.49, -78.9, 36.5193, -78.8965, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'There were multiple reports of flooded roadways in Bethel Hill, including Bethel Hill School Road, Gentry-Massey Road, Bowmantown Road, and John Obie Road.');
INSERT INTO public.stormevents_east VALUES (781161, 201808, 19, 2346, 201808, 20, 159, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '19-AUG-18 23:46:00', 'EST-5', '20-AUG-18 01:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'COLLEGE VIEW', 1, 'ESE', 'CAMP POLK', 35.77, -78.69, 35.816, -78.6925, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'Multiple water rescues reported in Raleigh, including at 3415 Aventy Ferry Road and 3600 Lake Boone Trail.');
INSERT INTO public.stormevents_east VALUES (781163, 201808, 19, 2346, 201808, 20, 159, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '19-AUG-18 23:46:00', 'EST-5', '20-AUG-18 01:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'MILLBROOK', 1, 'W', 'STARMOUNT', 35.86, -78.64, 35.8501, -78.5918, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'Multiple water rescues reported across the city, including at E. Millbrook Road, Six Forks Road, Atlantic Avenue, Hodges Street, and I-440 W at Glenwood Avenue.');
INSERT INTO public.stormevents_east VALUES (781965, 201808, 25, 1800, 201808, 25, 1800, 130644, 'FLORIDA', 12, 2018, 'August', 'Lightning', 'JAX', '25-AUG-18 18:00:00', 'EST-5', '25-AUG-18 18:00:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 5, 'SSE', 'YORK', 5, 'SSE', 'YORK', 29.08, -82.27, 29.08, -82.27, 'NE flow focused stronger east coast sea breeze inland with strong storms impacting Marion county into the early evening.', 'Lightning struck a home along SE 90th Court. The cost of damage was unknown but estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781968, 201808, 25, 1620, 201808, 25, 1620, 130644, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '25-AUG-18 16:20:00', 'EST-5', '25-AUG-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'EARLY BIRD', 2, 'SSE', 'EARLY BIRD', 29.15, -82.35, 29.15, -82.35, 'NE flow focused stronger east coast sea breeze inland with strong storms impacting Marion county into the early evening.', 'Trees were blown down across the northbound lane of SW 140th Avenue near the intersection with State Road 40. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781969, 201808, 25, 1620, 201808, 25, 1620, 130644, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '25-AUG-18 16:20:00', 'EST-5', '25-AUG-18 16:20:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 2, 'NNE', 'EARLY BIRD', 2, 'NNE', 'EARLY BIRD', 29.21, -82.36, 29.21, -82.36, 'NE flow focused stronger east coast sea breeze inland with strong storms impacting Marion county into the early evening.', 'A tree was blown down across Tropical Park Road near the intersection of Woodridge Drive. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781970, 201808, 25, 1825, 201808, 25, 1825, 130644, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '25-AUG-18 18:25:00', 'EST-5', '25-AUG-18 18:25:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 2, 'SSE', 'SANTOS', 2, 'SSE', 'SANTOS', 29.08, -82.09, 29.08, -82.09, 'NE flow focused stronger east coast sea breeze inland with strong storms impacting Marion county into the early evening.', 'A tree was blown down across the southbound lane of SW 36th Avenue. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781971, 201808, 25, 1855, 201808, 25, 1855, 130644, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '25-AUG-18 18:55:00', 'EST-5', '25-AUG-18 18:55:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 3, 'SSE', 'SILVER SPGS', 3, 'SSE', 'SILVER SPGS', 29.18, -82.04, 29.18, -82.04, 'NE flow focused stronger east coast sea breeze inland with strong storms impacting Marion county into the early evening.', 'A power line pole was blown down across SE 69th Avenue. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781972, 201808, 27, 1730, 201808, 27, 1730, 130645, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '27-AUG-18 17:30:00', 'EST-5', '27-AUG-18 17:30:00', 0, 0, 0, 0, '0.80K', '0.00K', 'Emergency Manager', 40, 'EG', NULL, NULL, 1, 'SE', 'BEVERLY BEACH', 1, 'SE', 'BEVERLY BEACH', 29.49, -81.14, 29.49, -81.14, 'Weak onshore flow enabled sea breezes to form and drift inland. Drier mid level air helped produced stronger downdrafts in resultant storms due to evaporative cooling.', 'A palm frond broke off of the tree and was partially blown through a window of a residence. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781973, 201808, 28, 1600, 201808, 28, 1600, 130646, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '28-AUG-18 16:00:00', 'EST-5', '28-AUG-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 8, 'WSW', 'MC ALPIN', 8, 'WSW', 'MC ALPIN', 30.07, -83.06, 30.07, -83.06, 'A coastal trough moved inland with the east coast sea breeze with very high PWAT content over 2 which produced strong wind gusts in diurnally enhanced thunderstorms.', 'Trees were blown down near the intersection of County Road 349 north and 208th Street. The time of damage was based on radar data.');
INSERT INTO public.stormevents_east VALUES (740208, 201804, 15, 700, 201804, 16, 700, 123444, 'VIRGINIA', 51, 2018, 'April', 'Heavy Rain', 'RNK', '15-APR-18 07:00:00', 'EST-5', '16-APR-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'SSW', 'HOT SPGS', 0, 'SSW', 'HOT SPGS', 37.997, -79.832, 37.997, -79.832, 'A strong cold front propelled by a deep upper trough that took on a negative tilt, pushed through the region on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding but longer duration flooding occurred on several rivers and streams, mainly in the minor category. Rainfall ranged from 2 to 4 inches with locally higher amounts up to nearly 4.5 inches in 24-hours ending at 7 AM on the 16th. The highest amounts were roughly a 5-year recurrence interval (0.2 Annual exceedance probability).', 'The COOP station at Hot Springs (HSPV2) measured 3.50 inches for the 24-hour period ending 7AM on the 16th. This was the 2nd highest 1-day April rainfall total in the period of record at this location, with data starting in 1893.');
INSERT INTO public.stormevents_east VALUES (763230, 201808, 3, 1330, 201808, 3, 1330, 127312, 'NEW JERSEY', 34, 2018, 'August', 'Thunderstorm Wind', 'PHI', '03-AUG-18 13:30:00', 'EST-5', '03-AUG-18 13:30:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 1, 'SW', 'MORRISTOWN', 1, 'SW', 'MORRISTOWN', 40.79, -74.48, 40.79, -74.48, 'Severe thunderstorms formed across extreme eastern Pennsylvania and New Jersey as a surface low and weak cold front moved eastward across the region. The strongest storms moved northeastward across the Delaware Valley, prompting several warnings. Instability was present with CAPE values exceeding 1000 J/kg and soundings indicated strong wind was the primary hazard with generally linear hodographs.', 'There were several reports of trees and wires being down. There was also a report of a tree falling on a car, but no injuries were reported.');
INSERT INTO public.stormevents_east VALUES (763266, 201808, 3, 2020, 201808, 3, 2230, 127331, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '03-AUG-18 20:20:00', 'EST-5', '03-AUG-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'WOMELSDORF STATION', 1, 'WNW', 'WOMELSDORF STATION', 40.3526, -76.1928, 40.3532, -76.1907, 'Rainfall totals of 3 to 5 inches fell across Berks County and the Lehigh Valley from the evening of August 3 into the early morning hours of August 4.', 'A water rescue took place on Brickplant Road in Heidelberg Township.');
INSERT INTO public.stormevents_east VALUES (763267, 201808, 3, 2100, 201808, 3, 2300, 127331, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '03-AUG-18 21:00:00', 'EST-5', '03-AUG-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'PRICETOWN', 2, 'SSW', 'NEW JERUSALEM', 40.4213, -75.7779, 40.4234, -75.7731, 'Rainfall totals of 3 to 5 inches fell across Berks County and the Lehigh Valley from the evening of August 3 into the early morning hours of August 4.', 'Flood waters caused significant damage to the foundation of a house in Rockland Township.');
INSERT INTO public.stormevents_east VALUES (763268, 201808, 4, 25, 201808, 4, 230, 127331, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '04-AUG-18 00:25:00', 'EST-5', '04-AUG-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'FRITZTOWN', 1, 'NNW', 'FRITZTOWN', 40.3115, -76.0832, 40.3119, -76.076, 'Rainfall totals of 3 to 5 inches fell across Berks County and the Lehigh Valley from the evening of August 3 into the early morning hours of August 4.', 'Flood waters caused significant damage to the foundation of a house in South Heidelberg Township.');
INSERT INTO public.stormevents_east VALUES (763269, 201808, 4, 645, 201808, 4, 845, 127332, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '04-AUG-18 06:45:00', 'EST-5', '04-AUG-18 08:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'PINE BROOK', 2, 'NNW', 'PARSIPPANY', 40.8714, -74.3704, 40.8766, -74.43, 'Heavy rain fell in northern New Jersey during the morning hours of August 4. Rainfall totals of 3 to 5 inches were common in the northwestern part of the state.', 'Significant flooding occurred along US Route 46 in Parsippany-Troy Hills.  At least one water rescue took place.  Also, Edwards Road was closed between US Route 46 and New Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (763270, 201808, 4, 815, 201808, 4, 915, 127332, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '04-AUG-18 08:15:00', 'EST-5', '04-AUG-18 09:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'GREEN BROOK', 3, 'ENE', 'GREEN BROOK', 40.6323, -74.4313, 40.6281, -74.4227, 'Heavy rain fell in northern New Jersey during the morning hours of August 4. Rainfall totals of 3 to 5 inches were common in the northwestern part of the state.', 'Multiple vehicles were trapped in high water in North Plainfield.');
INSERT INTO public.stormevents_east VALUES (763271, 201808, 4, 1015, 201808, 4, 1100, 127332, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '04-AUG-18 10:15:00', 'EST-5', '04-AUG-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'GREEN BROOK', 1, 'SSE', 'GREEN BROOK', 40.6027, -74.4573, 40.6057, -74.4592, 'Heavy rain fell in northern New Jersey during the morning hours of August 4. Rainfall totals of 3 to 5 inches were common in the northwestern part of the state.', 'Flash flooding occurred along Green Brook in North Plainfield.');
INSERT INTO public.stormevents_east VALUES (763272, 201808, 4, 900, 201808, 4, 1115, 127332, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '04-AUG-18 09:00:00', 'EST-5', '04-AUG-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'REAVILLE', 1, 'ENE', 'COPPER HILL', 40.4751, -74.827, 40.4867, -74.8366, 'Heavy rain fell in northern New Jersey during the morning hours of August 4. Rainfall totals of 3 to 5 inches were common in the northwestern part of the state.', 'Flash flooding occurred along the Neshanic River in Raritan Township.');
INSERT INTO public.stormevents_east VALUES (780598, 201808, 12, 752, 201808, 12, 1000, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 07:52:00', 'EST-5', '12-AUG-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'DEVEREUX', 0, 'SW', 'DEVEREUX', 42.4961, -70.8756, 42.4961, -70.8744, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 752 AM EST, West Shore Drive in Marblehead was flooded and impassable near the Tower School.');
INSERT INTO public.stormevents_east VALUES (780597, 201808, 12, 720, 201808, 12, 1015, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 07:20:00', 'EST-5', '12-AUG-18 10:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'WELLINGTON', 1, 'SSW', 'WELLINGTON', 42.395, -71.0863, 42.393, -71.0835, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 7:20 AM EST, a car was trapped in floodwaters in the Mystic Avenue underpass of the McGrath Highway.');
INSERT INTO public.stormevents_east VALUES (780600, 201808, 12, 800, 201808, 12, 1000, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 08:00:00', 'EST-5', '12-AUG-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'OAK GROVE', 1, 'W', 'OAK GROVE', 42.4577, -71.0897, 42.4491, -71.0899, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 8 AM EST, Woodland Road in Stoneham was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (780604, 201808, 12, 822, 201808, 12, 1000, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '12-AUG-18 08:22:00', 'EST-5', '12-AUG-18 10:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'FARM HILL', 1, 'NNW', 'FARM HILL', 42.4888, -71.1039, 42.4889, -71.1028, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 8:22 AM EST, a car was trapped in floodwaters on Oak Street in Stoneham.');
INSERT INTO public.stormevents_east VALUES (780606, 201808, 11, 1355, 201808, 11, 1600, 130389, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '11-AUG-18 13:55:00', 'EST-5', '11-AUG-18 16:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'LAWRENCE', 1, 'SSW', 'LAWRENCE', 42.7003, -71.1606, 42.7004, -71.1595, 'A cold front stalled over Southern New England on the 11th.  Low pressure from the Midwest then moved slowly east along the front. The weather system drew upon warm and very humid air to create showers with local downpours, resulting in rainfall amounts of two to five inches in Northern Massachusetts on August 11th and 12th.  An exceptionally powerful downpour left 8.15 inches in the city of Lynn.', 'At 1:55 PM EST, two cars were trapped in flooding at the intersection of Market Street and Parker Street in Lawrence.');
INSERT INTO public.stormevents_east VALUES (781436, 201808, 28, 1230, 201808, 28, 1230, 130534, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MFL', '28-AUG-18 12:30:00', 'EST-5', '28-AUG-18 12:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 42, 'MG', NULL, NULL, 5, 'NW', 'KREAMER ISLAND', 5, 'NW', 'KREAMER ISLAND', 26.82, -80.78, 26.82, -80.78, 'High pressure across the western Atlantic lead to deep easterly flow that quickly pushed the east coast seabreeze inland during the late morning and early afternoon hours. A storm that moved across the lake with the seabreeze produced a strong wind gusts over the lake.', 'A marine thunderstorm wind gust of 48 mph / 42 knots was recorded by the SFWMD site L006 located over the southern end of Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (779565, 201808, 11, 1555, 201808, 11, 1700, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 15:55:00', 'EST-5', '11-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'PACKANACK LAKE', 1, 'N', 'PACKANACK LAKE', 40.9465, -74.2538, 40.9467, -74.2538, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'The intersection of Gina Marie Court and Lake Drive East was flooded and impassable in Packanack Lake.');
INSERT INTO public.stormevents_east VALUES (779562, 201808, 11, 800, 201808, 11, 900, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 08:00:00', 'EST-5', '11-AUG-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'HOBOKEN', 2, 'S', 'WEEHAWKEN', 40.7329, -74.0318, 40.7452, -74.0232, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Several roads around the city of Hoboken were flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (779579, 201808, 11, 1600, 201808, 11, 1700, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 16:00:00', 'EST-5', '11-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'CALDWELL', 1, 'S', 'CALDWELL', 40.8351, -74.2668, 40.8358, -74.2666, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'The intersection of Bloomfield Avenue and Ryerson Avenue in Caldwell was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (779580, 201808, 11, 1640, 201808, 11, 1700, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 16:40:00', 'EST-5', '11-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'SOUTH PATERSON', 2, 'E', 'SOUTH PATERSON', 40.9009, -74.136, 40.9006, -74.1391, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'I-80 flooded in both directions at Exit 59 (Market Street) in Paterson.');
INSERT INTO public.stormevents_east VALUES (767207, 201808, 17, 1730, 201808, 17, 1730, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:30:00', 'EST-5', '17-AUG-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'NNE', 'EAST BANGOR', 1, 'NNE', 'EAST BANGOR', 40.9, -75.17, 40.9, -75.17, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Several trees down in Upper Mount Bethel Twp and East Bangor. Time estimated from radar.');
