INSERT INTO public.stormevents_east VALUES (767223, 201808, 17, 1750, 201808, 17, 1750, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:50:00', 'EST-5', '17-AUG-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'SHILLINGTON', 0, 'N', 'SHILLINGTON', 40.3, -75.97, 40.3, -75.97, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Report of a tree down blocking traffic. Time estimated from radar.');
