INSERT INTO public.stormevents_east VALUES (767226, 201808, 17, 1759, 201808, 17, 1759, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:59:00', 'EST-5', '17-AUG-18 17:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'N', '(RDG)SPAATZ FLD READ', 1, 'N', '(RDG)SPAATZ FLD READ', 40.39, -75.97, 40.39, -75.97, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Tree down at the intersection of Arnold Road and Leisczs Bridge Road.');
INSERT INTO public.stormevents_east VALUES (767227, 201808, 17, 1812, 201808, 17, 1812, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 18:12:00', 'EST-5', '17-AUG-18 18:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'E', 'SLATEDALE', 1, 'E', 'SLATEDALE', 40.75, -75.65, 40.75, -75.65, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Tree down on East Grant Street in Washington Twp, forcing the temporary closure of the road. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (767229, 201808, 17, 1822, 201808, 17, 1822, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 18:22:00', 'EST-5', '17-AUG-18 18:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'HEREFORD', 1, 'W', 'HEREFORD', 40.45, -75.57, 40.45, -75.57, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Report of a tree down at Seisholtzville Road and Chickadee Lane.');
INSERT INTO public.stormevents_east VALUES (767230, 201808, 17, 1837, 201808, 17, 1837, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 18:37:00', 'EST-5', '17-AUG-18 18:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'E', 'HELLERTOWN', 1, 'E', 'HELLERTOWN', 40.58, -75.31, 40.58, -75.31, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Report of trees down in Lower Saucon Twp. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (771115, 201808, 28, 1552, 201808, 28, 1552, 128529, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '28-AUG-18 15:52:00', 'EST-5', '28-AUG-18 15:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'EG', NULL, NULL, 1, 'S', 'LOWER TAMPA BAY', 1, 'S', 'LOWER TAMPA BAY', 27.6, -82.65, 27.6, -82.65, 'Numerous thunderstorms developed across Florida during the afternoon and shifted west into the eastern Gulf of Mexico during the late afternoon and early evening. Some of these storms produced gusty winds along the coast.', 'The WeatherFlow station on the Skyway Fishing Pier (XSKY) recorded a 36 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (768574, 201808, 13, 1355, 201808, 13, 1355, 128152, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '13-AUG-18 13:55:00', 'EST-5', '13-AUG-18 13:55:00', 0, 0, 0, 0, '0.50K', NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 2, 'W', 'BATH ALUM', 2, 'W', 'BATH ALUM', 38.0465, -79.7482, 38.0465, -79.7482, 'A closed upper level low helped to trigger scattered severe thunderstorms during the afternoon.  These storms blew down a number of trees and produced hail up to the size of quarters.', 'Hail up to the size of quarters fell on Route 39 on the east side of Warm Springs Mountain and created hazardous driving conditions.  In addition, thunderstorm winds blew down one tree along Route 39.');
INSERT INTO public.stormevents_east VALUES (772770, 201808, 31, 1300, 201808, 31, 1500, 128858, 'DELAWARE', 10, 2018, 'August', 'Flash Flood', 'PHI', '31-AUG-18 13:00:00', 'EST-5', '31-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'ELLENDALE', 2, 'WNW', 'REDDEN', 38.8088, -75.4503, 38.7405, -75.458, 'Locally heavy rain produced a swath of 4 to 7 inch rainfall totals from southern New Castle County down to northern Sussex County on the afternoon and evening of August 31. Thunderstorms caused isolated wind damage as well.', 'Locally heavy rain resulted in flash flooding in areas along Route 113 from around Ellendale southward.');
INSERT INTO public.stormevents_east VALUES (772783, 201808, 31, 1200, 201808, 31, 1400, 128858, 'DELAWARE', 10, 2018, 'August', 'Flash Flood', 'PHI', '31-AUG-18 12:00:00', 'EST-5', '31-AUG-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CHESTNUT KNOLL', 1, 'W', 'LINCOLN', 38.9055, -75.4497, 38.8726, -75.4446, 'Locally heavy rain produced a swath of 4 to 7 inch rainfall totals from southern New Castle County down to northern Sussex County on the afternoon and evening of August 31. Thunderstorms caused isolated wind damage as well.', 'Several roads in Milford were closed due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (772784, 201808, 31, 1540, 201808, 31, 1840, 128858, 'DELAWARE', 10, 2018, 'August', 'Flash Flood', 'PHI', '31-AUG-18 15:40:00', 'EST-5', '31-AUG-18 18:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'CHESNUT GROVE', 1, 'N', 'CAMDEN', 39.1849, -75.576, 39.133, -75.5468, 'Locally heavy rain produced a swath of 4 to 7 inch rainfall totals from southern New Castle County down to northern Sussex County on the afternoon and evening of August 31. Thunderstorms caused isolated wind damage as well.', 'Widespread roadway flooding in and around Dover, including along US Route 13.');
INSERT INTO public.stormevents_east VALUES (774006, 201808, 9, 1551, 201808, 9, 1554, 129143, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'MLB', '09-AUG-18 15:51:00', 'EST-5', '09-AUG-18 15:54:00', 0, 0, 0, 0, NULL, '0.00K', 'ASOS', 60, 'MG', NULL, NULL, 0, 'N', '(MCO)ORLANDO INTL AR', 0, 'N', '(MCO)ORLANDO INTL AR', 28.43, -81.32, 28.43, -81.32, 'Plentiful low level moisture, the presence of dry air aloft and a westerly steering component caused scattered thunderstorms to develop over the western peninsula and move into the interior during the late afternoon. Several of the storms became severe, producing winds of 60 mph winds at Orlando International Airport, over the Merritt Island National Wildlife Refuge and near Port Mayaca. A funnel cloud was also spotted near Tradition in St. Lucie County.', 'A thunderstorm become severe just west of Orlando International Airport then moved over the airfield. Downed powerlines were reported by a trained spotter, approximately 3 miles west of the airfield. The airport ASOS (KMCO) measured peak gusts of 60 mph at 1551LST and then 69 mph at 1554LST.');
INSERT INTO public.stormevents_east VALUES (787143, 201810, 23, 850, 201810, 23, 855, 131592, 'ATLANTIC NORTH', 88, 2018, 'October', 'Waterspout', 'BOX', '23-OCT-18 08:50:00', 'EST-5', '23-OCT-18 08:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mariner', NULL, NULL, NULL, NULL, 3, 'SSW', 'WOODS HOLE', 1, 'SSW', 'WOODS HOLE', 41.4904, -70.6713, 41.5151, -70.6705, 'A strong upper level short-wave trough with a very cold pool of air aloft and strong jet dynamics triggered localized flooding and a few waterspouts off the southern Massachusetts coast in the morning.', 'The Massachusetts Steamship Authority ship named Island Home''s captain reported observing a waterspout (photo attached).  The ship had departed Oak Bluffs and spotted the waterspout facing southwest toward Naushon Island.');
INSERT INTO public.stormevents_east VALUES (778067, 201808, 3, 1723, 201808, 3, 1723, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Lightning', 'BOX', '03-AUG-18 17:23:00', 'EST-5', '03-AUG-18 17:23:00', 0, 0, 0, 0, '7.50K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 2, 'NE', 'BACONVILLE', 2, 'NE', 'BACONVILLE', 42.4339, -72.4269, 42.4339, -72.4269, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 5:23 PM EST lightning struck a telephone pole on Baker Road in Shutesbury and set it on fire.');
INSERT INTO public.stormevents_east VALUES (778069, 201808, 3, 1627, 201808, 3, 1627, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '03-AUG-18 16:27:00', 'EST-5', '03-AUG-18 16:27:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'GOSHEN', 1, 'S', 'GOSHEN', 42.409, -72.7965, 42.409, -72.7965, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:27 PM EST wind from a thunderstorm brought a tree down on a house on Pine Road in Goshen.');
INSERT INTO public.stormevents_east VALUES (778071, 201808, 3, 1641, 201808, 3, 1641, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '03-AUG-18 16:41:00', 'EST-5', '03-AUG-18 16:41:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'ENE', 'HOLYOKE', 0, 'ENE', 'HOLYOKE', 42.2012, -72.6153, 42.2012, -72.6153, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 4:41 PM EST thunderstorm winds brought a tree down on a car and a house on Sergeant Street in Holyoke.');
INSERT INTO public.stormevents_east VALUES (778072, 201808, 3, 1703, 201808, 3, 1703, 129883, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '03-AUG-18 17:03:00', 'EST-5', '03-AUG-18 17:03:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'E', 'COOKS CORNER', 0, 'E', 'COOKS CORNER', 42.2802, -72.4637, 42.2802, -72.4637, 'Bermuda High Pressure offshore delivered heat and humidity to Massachusetts.  Heat indices in Eastern Massachusetts climbed into the lower 100s on the 2nd, but not high enough for an Excessive Heat Warning. Heat Index values climbed into the 90s on the 3rd. This tropical weather allowed a few strong thunderstorms over Western Massachusetts both days, with reports of flooding from downpours on the 3rd.', 'At 5:03 PM EST winds from a thunderstorm brought a large tree down across Batchelor Street in Granby, blocking the street.');
INSERT INTO public.stormevents_east VALUES (768567, 201808, 13, 1530, 201808, 13, 1530, 128151, 'WEST VIRGINIA', 54, 2018, 'August', 'Hail', 'RNK', '13-AUG-18 15:30:00', 'EST-5', '13-AUG-18 15:30:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 1, NULL, NULL, NULL, 1, 'SW', 'PICKAWAY', 1, 'SW', 'PICKAWAY', 37.6205, -80.5286, 37.6205, -80.5286, 'A closed upper level low helped to trigger one severe thunderstorm during the afternoon.  This storm produced hail up to the size of quarters in Monroe County.', 'Hail up to the size of quarters fell at the UTC Aerospace Systems north of Union.');
INSERT INTO public.stormevents_east VALUES (777939, 201808, 1, 2027, 201808, 1, 2127, 129866, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RNK', '01-AUG-18 20:27:00', 'EST-5', '01-AUG-18 21:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'INTELLIGENCE', 3, 'NNE', 'INTELLIGENCE', 36.41, -79.88, 36.4132, -79.8794, 'Heavy rain moved into an area where earlier afternoon thunderstorms had occurred making conditions favorable for flash flooding as an additional 1 to 2 inches fell in a few hours.', 'County dispatch reported high water covering River Road around Country Club Drive.');
INSERT INTO public.stormevents_east VALUES (777940, 201808, 1, 2050, 201808, 1, 2150, 129866, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RNK', '01-AUG-18 20:50:00', 'EST-5', '01-AUG-18 21:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'PENNRINGTON', 1, 'W', 'PENNRINGTON', 36.4, -79.66, 36.3997, -79.6557, 'Heavy rain moved into an area where earlier afternoon thunderstorms had occurred making conditions favorable for flash flooding as an additional 1 to 2 inches fell in a few hours.', 'Wolf Island Creek overtopped a bridge on Wolf Island Road.');
INSERT INTO public.stormevents_east VALUES (780454, 201808, 4, 929, 201808, 4, 1200, 130371, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '04-AUG-18 09:29:00', 'EST-5', '04-AUG-18 12:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'OXFORD', 1, 'ESE', 'OXFORD', 42.1163, -71.8493, 42.1132, -71.8489, 'An atmospheric trough moved over Massachusetts on the 4th, tapping high amounts of moisture in the air to cause heavy showers that resulted in flooding.  Up to 6.5 inches of rain fell on Cape Cod, and 1 to 3 inches across the rest of Massachusetts. A few thunderstorms also moved across the state, causing wind damage.', 'At 9:29 AM EST, several cars were reported trapped in flood waters on Sutton Avenue in Oxford.');
INSERT INTO public.stormevents_east VALUES (780455, 201808, 4, 1153, 201808, 4, 1400, 130371, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '04-AUG-18 11:53:00', 'EST-5', '04-AUG-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'FALL RIVER', 1, 'WSW', 'WATUPPA', 41.6958, -71.1401, 41.6954, -71.1395, 'An atmospheric trough moved over Massachusetts on the 4th, tapping high amounts of moisture in the air to cause heavy showers that resulted in flooding.  Up to 6.5 inches of rain fell on Cape Cod, and 1 to 3 inches across the rest of Massachusetts. A few thunderstorms also moved across the state, causing wind damage.', 'At 11:53 AM EST, the intersection of Quarry Street and Pleasant Street in Fall River was reported flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (780457, 201808, 4, 1237, 201808, 4, 1500, 130371, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '04-AUG-18 12:37:00', 'EST-5', '04-AUG-18 15:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'FALL RIVER', 0, 'NNW', 'FALL RIVER', 41.705, -71.1537, 41.7051, -71.1531, 'An atmospheric trough moved over Massachusetts on the 4th, tapping high amounts of moisture in the air to cause heavy showers that resulted in flooding.  Up to 6.5 inches of rain fell on Cape Cod, and 1 to 3 inches across the rest of Massachusetts. A few thunderstorms also moved across the state, causing wind damage.', 'At 12:37 PM EST, a basement at a house on Purchase Street in Fall River was reported flooded.');
INSERT INTO public.stormevents_east VALUES (782354, 201808, 13, 1328, 201808, 13, 1730, 130509, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 13:28:00', 'EST-5', '13-AUG-18 17:30:00', 0, 0, 0, 0, '25.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WEST ELMIRA', 2, 'WSW', 'EAST ELMIRA', 42.0642, -76.8473, 42.0627, -76.7723, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flash flooding led to evacuations and swift water rescues near Southport.');
INSERT INTO public.stormevents_east VALUES (781758, 201808, 8, 1847, 201808, 8, 1847, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:47:00', 'EST-5', '08-AUG-18 18:47:00', 0, 0, 0, 0, '300.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NE', 'FOUR OAKS', 2, 'NE', 'FOUR OAKS', 35.47, -78.4, 35.47, -78.4, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Numerous trees down in the Four Oaks, especially in the Johnston County Country Club community. Down trees fell onto at least 13 homes, 3 of which were significantly damaged.');
INSERT INTO public.stormevents_east VALUES (781762, 201808, 8, 1845, 201808, 8, 1915, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:45:00', 'EST-5', '08-AUG-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'BENNETT', 1, 'E', 'SILK HOPE', 35.57, -79.55, 35.7802, -79.3557, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Multiple trees down along a swath extending from Silk Hope, Siler City, to Bennett.');
INSERT INTO public.stormevents_east VALUES (781765, 201808, 8, 1842, 201808, 8, 1842, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:42:00', 'EST-5', '08-AUG-18 18:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NE', 'ERECT', 1, 'NE', 'ERECT', 35.56, -79.66, 35.56, -79.66, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One down tree was blocking track on Erect Road near Fork Creek Mill Road.');
INSERT INTO public.stormevents_east VALUES (781767, 201808, 8, 1832, 201808, 8, 1832, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:32:00', 'EST-5', '08-AUG-18 18:32:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SE', 'AUMAN CORNER', 2, 'SE', 'AUMAN CORNER', 35.5314, -79.8316, 35.5314, -79.8316, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was blown down at New Hope Church Road and Bethel Lucas Road.');
INSERT INTO public.stormevents_east VALUES (781769, 201808, 8, 1814, 201808, 8, 1814, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:14:00', 'EST-5', '08-AUG-18 18:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'S', 'JACKSON HILL', 2, 'S', 'JACKSON HILL', 35.5474, -80.1504, 35.5474, -80.1504, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was blown down near the intersection of Allegany Church Raod and NC Highway 8.');
INSERT INTO public.stormevents_east VALUES (781770, 201808, 8, 1809, 201808, 8, 1809, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 18:09:00', 'EST-5', '08-AUG-18 18:09:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ENE', 'HIGH ROCK', 3, 'ENE', 'HIGH ROCK', 35.616, -80.1771, 35.616, -80.1771, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was blown down near the intersection of Bringle Ferry Road and NC Highway 8.');
INSERT INTO public.stormevents_east VALUES (753688, 201805, 14, 434, 201805, 14, 438, 125671, 'FLORIDA', 12, 2018, 'May', 'Tornado', 'MFL', '14-MAY-18 04:34:00', 'EST-5', '14-MAY-18 04:38:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 8, 'NNE', 'LOXAHATCHEE', 9, 'NNE', 'LOXAHATCHEE', 26.7823, -80.2867, 26.801, -80.2997, 'An upper level low over the eastern Gulf of Mexico allowed brought abundant tropical moisture to the region. With all of this moisture scattered showers and thunderstorms developed along sea breeze and outflow boundaries. A few of these storms became severe producing  hail and a tornado.', 'A EF-0 tornado affected the community of The Acreage during the pre-dawn hours on May 14th. Damage consisted primary of snapped tree branches, uprooted trees and downed fences and power lines along the tornado''s path. Several homes suffered minor roof damage in the form of shingles being blown off. Two homes sustained damage to side doors, and one home had a set of window panes blown out. Several sheds were damaged, a few horse stables lost their covering, and a chicken coop was destroyed. Estimated peak wind was in the 75-80 mph range.');
INSERT INTO public.stormevents_east VALUES (772215, 201807, 27, 1520, 201807, 27, 1520, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 15:20:00', 'EST-5', '27-JUL-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 38.03, -76.34, 38.03, -76.34, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts in excess of 30 knots were reported at Potomac Point Lookout.');
INSERT INTO public.stormevents_east VALUES (772216, 201807, 27, 1436, 201807, 27, 1436, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 14:36:00', 'EST-5', '27-JUL-18 14:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 21, 'N', 'ST INIGOES (KNUI)', 21, 'N', 'ST INIGOES (KNUI)', 38.432, -76.387, 38.432, -76.387, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'A wind gust of 38 knots was reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (778375, 201808, 2, 1623, 201808, 2, 1723, 128029, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'RNK', '02-AUG-18 16:23:00', 'EST-5', '02-AUG-18 17:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'MARTINSVILLE', 0, 'WNW', 'MARTINSVILLE', 36.6841, -79.8779, 36.6831, -79.8779, 'A complex, broken line of thunderstorms developed during the afternoon ahead of an approaching cold front producing very heavy rainfall and some embedded severe storms. Trees were blown trees onto power lines, which caused a number of power outages.  Henry County and the city of Martinsville suffered the most tree damage and power outages. Rainfall was extremely intense within the very moist environment with precipitable water over 2 inches and several boundary collisions enhancing the rainfall. The highest amounts occurred in the City of Lynchburg and adjacent parts of Campbell County where radar estimated 4 to 6 inches of rain in several hours which was confirmed by several rain gages.', 'A TV viewer reported flooding at Bridge Street and Memorial Boulevard.');
INSERT INTO public.stormevents_east VALUES (774502, 201807, 25, 1849, 201807, 25, 2000, 128279, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 18:49:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'TENLEYTOWN', 1, 'ENE', 'TENLEYTOWN', 38.9537, -77.0565, 38.9536, -77.0562, 'Locally heavy rain fell in Washington DC on the afternoon of July 25th. This caused flash flooding at rush hour in the metro area.', 'A mail truck overturned in swift water on Broad Branch Road in Northwest DC near the Davenport Street/Grant Road intersection. The occupant was rescued.');
INSERT INTO public.stormevents_east VALUES (774503, 201807, 25, 1831, 201807, 25, 2000, 128279, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 18:31:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'DALECARLIA RESERVOIR', 2, 'SSE', 'DALECARLIA RESERVOIR', 38.9197, -77.1011, 38.9195, -77.101, 'Locally heavy rain fell in Washington DC on the afternoon of July 25th. This caused flash flooding at rush hour in the metro area.', 'Canal Road NW flooded and closed between Arizona Avenue and MacArthur Boulevard.');
INSERT INTO public.stormevents_east VALUES (781701, 201808, 3, 1721, 201808, 3, 1821, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 17:21:00', 'EST-5', '03-AUG-18 18:21:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 0, 'N', 'RED HOOK', 0, 'N', 'RED HOOK', 42, -73.88, 42, -73.88, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 2.12 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (781703, 201808, 3, 2107, 201808, 3, 2207, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 21:07:00', 'EST-5', '03-AUG-18 22:07:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 1, 'NE', 'ALBANY', 1, 'NE', 'ALBANY', 42.66, -73.76, 42.66, -73.76, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Strong storm resulted in 2.37 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (773384, 201808, 29, 1614, 201808, 29, 1615, 128988, 'VERMONT', 50, 2018, 'August', 'Thunderstorm Wind', 'BTV', '29-AUG-18 16:14:00', 'EST-5', '29-AUG-18 16:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SW', 'CANAAN', 2, 'SW', 'CANAAN', 44.98, -71.56, 44.98, -71.56, 'A weak trough ahead of a cold front moved across a unstable air mass across NY and VT during the afternoon and evening hours of August 29th. A few storms produced strong to damaging winds, including one storm near Canaan.', 'Trees down on road near Fund and Canaan Hill roads.');
INSERT INTO public.stormevents_east VALUES (767324, 201808, 1, 1712, 201808, 1, 1712, 127922, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'MLB', '01-AUG-18 17:12:00', 'EST-5', '01-AUG-18 17:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'SSW', 'ORLOVISTA', 2, 'SSW', 'ORLOVISTA', 28.5066, -81.4849, 28.5066, -81.4849, 'Sea breeze collisions produced thunderstorms with strong wind gusts across Orange and Seminole Counties during the early evening. One of the storms become briefly severe, resulting in wind damage to trees in the Metrowest portion of Orlando.', 'A thunderstorm briefly became severe and downed trees near the 3400 block of South Hiawassee Road in the Metrowest portion of southwest Orlando. Additional minor tree damage occurred nearby within Metrowest.');
INSERT INTO public.stormevents_east VALUES (767333, 201808, 8, 1555, 201808, 8, 1555, 127923, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '08-AUG-18 15:55:00', 'EST-5', '08-AUG-18 15:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 14, 'NNE', 'PLAYALINDA BEACH', 14, 'NNE', 'PLAYALINDA BEACH', 28.74, -80.7, 28.74, -80.7, 'A thunderstorm with strong winds moved off the coast of northern Brevard County near Haulover Canal.', 'USAF wind tower 0019 recorded a peak wind of 34 knots from the southwest as a strong thunderstorm cross Canaveral National Seashore near Haulover Canal and exited into the nearshore Atlantic.');
INSERT INTO public.stormevents_east VALUES (769249, 201808, 22, 1525, 201808, 22, 1525, 128250, 'FLORIDA', 12, 2018, 'August', 'Funnel Cloud', 'MLB', '22-AUG-18 15:25:00', 'EST-5', '22-AUG-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 3, 'NNW', 'INDIANTOWN CRL T ARP', 3, 'NNW', 'INDIANTOWN CRL T ARP', 27.07, -80.46, 27.07, -80.46, 'A funnel cloud was observed in association with an isolated thunderstorm which quickly formed just north of Indiantown.', 'A public report was received of a funnel cloud to the north of Indiantown, in association with an isolated thunderstorm.');
INSERT INTO public.stormevents_east VALUES (773995, 201808, 28, 1646, 201808, 28, 1646, 129139, 'FLORIDA', 12, 2018, 'August', 'Lightning', 'MLB', '28-AUG-18 16:46:00', 'EST-5', '28-AUG-18 16:46:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'NNW', 'DE LAND', 1, 'NNW', 'DE LAND', 29.049, -81.305, 29.049, -81.305, 'A woman standing in a parking lot in Deland was struck and seriously injured by a lightning strike.', 'A woman was standing in a Denny''s parking lot talking with a coworker when she was struck by lightning. The lightning knocked her unconscious and she was in serious condition when taken to a local hospital. An eyewitness reported that it was hardly raining and that the strike came out of nowhere.');
INSERT INTO public.stormevents_east VALUES (774007, 201808, 9, 1645, 201808, 9, 1645, 129144, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '09-AUG-18 16:45:00', 'EST-5', '09-AUG-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 6, 'NNW', 'PLAYALINDA BEACH', 6, 'NNW', 'PLAYALINDA BEACH', 28.63, -80.81, 28.63, -80.81, 'A broken line of strong thunderstorm moved quickly east from the mainland to across Cape Canaveral and the adjacent intracoastal, coastal and offshore waters. Many of the storms produced wind gusts between 35 and 50 knots.', 'Weatherflow site XPAR near Titusville recorded a peak wind of 36 knots from the west-northwest as a strong thunderstorm moved offshore the peninsula.');
INSERT INTO public.stormevents_east VALUES (774008, 201808, 9, 1650, 201808, 9, 1650, 129144, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '09-AUG-18 16:50:00', 'EST-5', '09-AUG-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 38, 'MG', NULL, NULL, 2, 'SSE', 'PLAYALINDA BEACH', 2, 'SSE', 'PLAYALINDA BEACH', 28.53, -80.77, 28.53, -80.77, 'A broken line of strong thunderstorm moved quickly east from the mainland to across Cape Canaveral and the adjacent intracoastal, coastal and offshore waters. Many of the storms produced wind gusts between 35 and 50 knots.', 'USAF wind tower 1007 onthe NASA Parkway at the Indian River recorded a peak wind of 38 knots from the west-northwest as a strong thunderstorm moved offshore the peninsula.');
INSERT INTO public.stormevents_east VALUES (766120, 201808, 10, 1910, 201808, 10, 1910, 127741, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '10-AUG-18 19:10:00', 'EST-5', '10-AUG-18 19:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'WNW', 'TEMPY', 1, 'WNW', 'TEMPY', 31.4454, -83.8325, 31.4454, -83.8325, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'Multiple trees and a power line were blown down along Highway 33 South.');
INSERT INTO public.stormevents_east VALUES (771395, 201808, 31, 1350, 201808, 31, 1350, 128594, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '31-AUG-18 13:50:00', 'EST-5', '31-AUG-18 13:50:00', 0, 0, 0, 0, '0.20K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'W', 'FALLVILLE', 2, 'W', 'FALLVILLE', 36.7501, -81.1581, 36.7501, -81.1581, 'A hot and humid air mass sparked isolated severe thunderstorms during the evening.  These storms blew down several trees across southwest Virginia.', 'Thunderstorm winds blew down large tree limbs on Highway 21.');
INSERT INTO public.stormevents_east VALUES (766121, 201808, 10, 1912, 201808, 10, 1912, 127741, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'TAE', '10-AUG-18 19:12:00', 'EST-5', '10-AUG-18 19:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'CHULA', 1, 'E', 'CHULA', 31.551, -83.5301, 31.551, -83.5301, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down on Chula Brookfield Road about one mile east of I-75.');
INSERT INTO public.stormevents_east VALUES (766122, 201808, 13, 800, 201808, 13, 1500, 127743, 'FLORIDA', 12, 2018, 'August', 'Flood', 'TAE', '13-AUG-18 08:00:00', 'EST-5', '13-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 4, 'S', 'HAMPTON SPRINGS', 3, 'SW', 'HAMPTON SPRINGS', 30.03, -83.66, 30.0427, -83.6894, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'Video of standing water on Courtney Grade Road was posted to the Taylor County EM facebook page.  Radar estimates around 3.5 inches of rain in the previous 24 hours across the area.  This rain on top of saturated soils resulted in minor flooding across the area in the form of areas of standing water.');
INSERT INTO public.stormevents_east VALUES (781167, 201808, 20, 15, 201808, 20, 159, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '20-AUG-18 00:15:00', 'EST-5', '20-AUG-18 01:59:00', 0, 0, 0, 0, '80.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'RALEIGH', 2, 'E', 'RALEIGH', 35.8049, -78.623, 35.8049, -78.6263, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'Water rescues were conducted as multiple vehicles were submerged in over 4 feet of water on Wake Forest Road near Georgetown Road.');
INSERT INTO public.stormevents_east VALUES (781170, 201808, 20, 30, 201808, 20, 229, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '20-AUG-18 00:30:00', 'EST-5', '20-AUG-18 02:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'CALVANDER', 1, 'WSW', 'CHAPEL HILL', 35.8997, -79.1067, 35.9127, -79.0876, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'There were several reports of flooded roadways in the area, including at Jones Ferry Road, NC-Highway 54 at Old Fayetteville Road, and Old Greensboro Road.');
INSERT INTO public.stormevents_east VALUES (781168, 201808, 20, 23, 201808, 20, 159, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '20-AUG-18 00:23:00', 'EST-5', '20-AUG-18 01:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'FAWLERS XRDS', 1, 'ESE', 'FAWLERS XRDS', 35.87, -78.58, 35.8712, -78.5793, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'Water rescue conducted at Capital Boulevard and Old Wake Forest Road.');
INSERT INTO public.stormevents_east VALUES (781172, 201808, 19, 2253, 201808, 19, 2258, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '19-AUG-18 22:53:00', 'EST-5', '19-AUG-18 22:58:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'CAMP POLK', 1, 'WNW', 'MILLBROOK', 35.83, -78.74, 35.86, -78.64, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'Three trees were blown down along a wind swath extending from Trenton Road to Spring Forest Road.');
INSERT INTO public.stormevents_east VALUES (781974, 201808, 29, 1510, 201808, 29, 1550, 130647, 'FLORIDA', 12, 2018, 'August', 'Heavy Rain', 'JAX', '29-AUG-18 15:10:00', 'EST-5', '29-AUG-18 15:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 3, 'N', 'CHATMAR', 3, 'N', 'CHATMAR', 29.11, -82.45, 29.11, -82.45, 'Sea breeze storms with a very moist airmass with PWAT over 2 produced localized heavy rainfall.', 'A citizen measured 2.43 inches of rainfall in 40 minutes about 4 miles north of Dunnellon.');
INSERT INTO public.stormevents_east VALUES (781975, 201808, 30, 1329, 201808, 30, 1329, 130648, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '30-AUG-18 13:29:00', 'EST-5', '30-AUG-18 13:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'W', 'BRYCEVILLE', 5, 'W', 'BRYCEVILLE', 30.38, -82.02, 30.38, -82.02, 'Prevailing SE steering flow focused a stronger east coast sea breeze inland through the day which triggered scattered strong to severe storms over a moist and unstable airmass.', 'A road was blocked by a downed tree at 7578 County Road 121. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (781977, 201808, 30, 1335, 201808, 30, 1335, 130648, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '30-AUG-18 13:35:00', 'EST-5', '30-AUG-18 13:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 2, 'NNW', 'ARCHER', 2, 'NNW', 'ARCHER', 29.56, -82.54, 29.56, -82.54, 'Prevailing SE steering flow focused a stronger east coast sea breeze inland through the day which triggered scattered strong to severe storms over a moist and unstable airmass.', 'Trees were blown down and blocked U.S. Highway 27 near Archer. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (780061, 201808, 8, 1521, 201808, 8, 1521, 130298, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'ALY', '08-AUG-18 15:21:00', 'EST-5', '08-AUG-18 15:21:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'WSW', 'NORTH EGREMONT', 0, 'WSW', 'NORTH EGREMONT', 42.1984, -73.4381, 42.1984, -73.4381, 'Scattered thunderstorms developed during the afternoon and evening of August 8th. One of these storms resulted in downed power lines.', 'Power lines were downed at Egremont Plain Road and Boice Road.');
INSERT INTO public.stormevents_east VALUES (780199, 201808, 14, 1435, 201808, 14, 1435, 130319, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '14-AUG-18 14:35:00', 'EST-5', '14-AUG-18 14:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'GLENVILLE', 1, 'NE', 'GLENVILLE', 42.93, -74.05, 42.93, -74.05, 'Several bands of showers and thunderstorms developed on August 14th ahead of an upper level low pressure system. One of these storms resulted in minor wind damage.', 'Powerlines were reported down due to thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (780200, 201808, 18, 1242, 201808, 18, 1442, 130320, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '18-AUG-18 12:42:00', 'EST-5', '18-AUG-18 14:42:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'SAUGERTIES', 0, 'N', 'SAUGERTIES', 42.082, -73.9528, 42.0826, -73.9497, 'A cold front moved into a warm and humid airmass on August 18th, sparking a line of showers and thunderstorms. These storms produced heavy rainfall, resulting in a report of flash flooding. Gusty winds with a thunderstorm resulted in a report of tree and powerline damage as well.', 'High water resulted in a vehicle becoming stranded with the motorist trapped inside. The road was closed. No injuries were reported.');
INSERT INTO public.stormevents_east VALUES (780201, 201808, 18, 1302, 201808, 18, 1302, 130320, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '18-AUG-18 13:02:00', 'EST-5', '18-AUG-18 13:02:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'HAMMERTOWN', 1, 'NW', 'HAMMERTOWN', 41.98, -73.66, 41.98, -73.66, 'A cold front moved into a warm and humid airmass on August 18th, sparking a line of showers and thunderstorms. These storms produced heavy rainfall, resulting in a report of flash flooding. Gusty winds with a thunderstorm resulted in a report of tree and powerline damage as well.', 'A tree and powerlines were downed in Pine Plains.');
INSERT INTO public.stormevents_east VALUES (768600, 201808, 17, 1622, 201808, 17, 1622, 128154, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '17-AUG-18 16:22:00', 'EST-5', '17-AUG-18 16:22:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'E', 'CONGO', 0, 'E', 'CONGO', 36.1699, -81.265, 36.1699, -81.265, 'A hot and humid air mass sparked one severe thunderstorm during the afternoon.  This storm blew down several trees in Wilkes County.', 'Thunderstorm winds blew down several trees along North Minton Road.');
INSERT INTO public.stormevents_east VALUES (771207, 201808, 30, 1502, 201808, 30, 1502, 128556, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'RNK', '30-AUG-18 15:02:00', 'EST-5', '30-AUG-18 15:02:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 1, NULL, NULL, NULL, 1, 'N', 'NELLA', 1, 'N', 'NELLA', 36.58, -81.55, 36.58, -81.55, 'A hot and humid air mass combined with an approaching cold front to spark isolated severe thunderstorms during the afternoon.  These storms produced thunderstorm wind damage and hail up to the size of quarters in northwest North Carolina.', 'Hail up to the size of quarters fell about one mile north of Nella.');
INSERT INTO public.stormevents_east VALUES (771396, 201808, 31, 1354, 201808, 31, 1354, 128594, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '31-AUG-18 13:54:00', 'EST-5', '31-AUG-18 13:54:00', 0, 0, 0, 0, '0.50K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WNW', 'WYTHEVILLE', 1, 'WNW', 'WYTHEVILLE', 36.9528, -81.0902, 36.9528, -81.0902, 'A hot and humid air mass sparked isolated severe thunderstorms during the evening.  These storms blew down several trees across southwest Virginia.', 'Thunderstorm winds blew down one tree near the intersection of North Fourth Street and West Ridge Street.');
INSERT INTO public.stormevents_east VALUES (771397, 201808, 31, 2328, 201808, 31, 2328, 128594, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '31-AUG-18 23:28:00', 'EST-5', '31-AUG-18 23:28:00', 0, 0, 0, 0, '0.20K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 4, 'SSW', 'DODSON', 4, 'SSW', 'DODSON', 36.7801, -80.1331, 36.7801, -80.1331, 'A hot and humid air mass sparked isolated severe thunderstorms during the evening.  These storms blew down several trees across southwest Virginia.', 'Thunderstorm winds blew down large tree limbs along Highway 57.');
INSERT INTO public.stormevents_east VALUES (771398, 201808, 31, 1424, 201808, 31, 1430, 128594, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '31-AUG-18 14:24:00', 'EST-5', '31-AUG-18 14:30:00', 0, 0, 0, 0, '1.50K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'LONE ASH', 1, 'E', 'LONE ASH', 36.9071, -80.8026, 36.9204, -80.8022, 'A hot and humid air mass sparked isolated severe thunderstorms during the evening.  These storms blew down several trees across southwest Virginia.', 'Thunderstorm winds blew down one tree near the Barren Springs post office, a second tree near the intersection of Foster Falls Road and Wysor Highway, and a third tree along the 2700 block of Wysor Highway.');
INSERT INTO public.stormevents_east VALUES (782615, 201808, 31, 1350, 201808, 31, 1350, 128594, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '31-AUG-18 13:50:00', 'EST-5', '31-AUG-18 13:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 2, 'N', 'SIMMERMAN', 2, 'N', 'SIMMERMAN', 36.85, -81.13, 36.85, -81.13, 'A hot and humid air mass sparked isolated severe thunderstorms during the evening.  These storms blew down several trees across southwest Virginia.', NULL);
INSERT INTO public.stormevents_east VALUES (763710, 201808, 7, 2045, 201808, 7, 2315, 127416, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '07-AUG-18 20:45:00', 'EST-5', '07-AUG-18 23:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'WEST KEANSBURG', 1, 'WSW', 'ATLANTIC HIGHLANDS', 40.4355, -74.1262, 40.4157, -74.0548, 'Rainfall totals of 2 to 4 inches fell in northeastern Monmouth County in a short amount of time on the evening of August 7, 2018.', 'There were widespread road closures in Middletown Township and Sea Bright. Many  vehicles were caught in the flood waters. Route 35 southbound in Middletown Township was entirely closed due to the flooding.');
INSERT INTO public.stormevents_east VALUES (768933, 201808, 13, 815, 201808, 13, 1115, 128207, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:15:00', 'EST-5', '13-AUG-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'SEA GIRT', 1, 'WNW', 'MANASQUAN', 40.1388, -74.0404, 40.1244, -74.0398, 'Rainfall totals of 3 to 6 inches were reported in southeastern Monmouth County and northeastern Ocean County with isolated amounts near 8 inches.  The heavy rain resulted in widespread flash flooding in the area.', 'Flash flooding resulted in widespread roadway flooding in Sea Girt.  Many roads were closed due to the flooding.');
INSERT INTO public.stormevents_east VALUES (768941, 201808, 13, 815, 201808, 13, 1115, 128207, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:15:00', 'EST-5', '13-AUG-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'LAKEWOOD', 1, 'SSE', 'LAKEWOOD', 40.0878, -74.2149, 40.0935, -74.2146, 'Rainfall totals of 3 to 6 inches were reported in southeastern Monmouth County and northeastern Ocean County with isolated amounts near 8 inches.  The heavy rain resulted in widespread flash flooding in the area.', 'Route 88 in Lakewood was flooded and impassable.  Some vehicles were trapped in the flood waters.');
INSERT INTO public.stormevents_east VALUES (768942, 201808, 13, 845, 201808, 13, 1145, 128207, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:45:00', 'EST-5', '13-AUG-18 11:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'PARKWAY PINES', 1, 'E', 'GREENVILLE', 40.0888, -74.1497, 40.1013, -74.1434, 'Rainfall totals of 3 to 6 inches were reported in southeastern Monmouth County and northeastern Ocean County with isolated amounts near 8 inches.  The heavy rain resulted in widespread flash flooding in the area.', 'Widespread flooding occurred in and around the Greenbriar development in Brick Township.  Several homes on Markham Road were flooded.  Also, a nearby medical building experienced flooding on the first floor.  There were a number of water rescues in the area.  The adjacent section of the Garden State Parkway was flooded and some of the northbound lanes were closed.');
INSERT INTO public.stormevents_east VALUES (769197, 201808, 13, 945, 201808, 13, 1115, 128207, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 09:45:00', 'EST-5', '13-AUG-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'RIVERTON', 1, 'NNE', 'RIVERTON', 39.9962, -75.0341, 40.0123, -75.011, 'Rainfall totals of 3 to 6 inches were reported in southeastern Monmouth County and northeastern Ocean County with isolated amounts near 8 inches.  The heavy rain resulted in widespread flash flooding in the area.', 'Heavy rain resulted in widespread roadway flooding in Palmyra, Maple Shade and Moorestown.  Sections of Route 73 and Route 38 were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (769210, 201808, 13, 945, 201808, 13, 1115, 128207, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 09:45:00', 'EST-5', '13-AUG-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MORRISVILLE', 1, 'NE', 'DELAIR', 39.9915, -75.0277, 39.9764, -75.058, 'Rainfall totals of 3 to 6 inches were reported in southeastern Monmouth County and northeastern Ocean County with isolated amounts near 8 inches.  The heavy rain resulted in widespread flash flooding in the area.', 'There were multiple road closures in Pennsauken due to flash flooding, including Route 130 near Union Avenue and Route 73 at Hylton Road.');
INSERT INTO public.stormevents_east VALUES (769212, 201808, 13, 1000, 201808, 13, 1200, 128207, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 10:00:00', 'EST-5', '13-AUG-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'LAKE COMO', 0, 'WNW', 'LAKE COMO', 40.1681, -74.0341, 40.1707, -74.034, 'Rainfall totals of 3 to 6 inches were reported in southeastern Monmouth County and northeastern Ocean County with isolated amounts near 8 inches.  The heavy rain resulted in widespread flash flooding in the area.', 'Route 71 in West Belmar was closed around 18th Avenue due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (782828, 201808, 14, 1130, 201808, 14, 1130, 130823, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '14-AUG-18 11:30:00', 'EST-5', '14-AUG-18 11:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 30, 'EG', NULL, NULL, 1, 'E', 'WARE CENTER', 1, 'E', 'WARE CENTER', 42.27, -72.253, 42.27, -72.253, 'Low pressure centered over New York brought tropical air north into Southern New England.  This generated thunderstorms which caused isolated tree damage and isolated reports of flooding during the afternoon of the 14th.', 'At 11:30 AM EST, a tree was reported down on wires on Crescent Street in Ware.');
INSERT INTO public.stormevents_east VALUES (782834, 201808, 14, 1144, 201808, 14, 1144, 130823, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '14-AUG-18 11:44:00', 'EST-5', '14-AUG-18 11:44:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 48, 'EG', NULL, NULL, 3, 'N', 'PETERSHAM', 3, 'N', 'PETERSHAM', 42.5166, -72.1821, 42.5166, -72.1821, 'Low pressure centered over New York brought tropical air north into Southern New England.  This generated thunderstorms which caused isolated tree damage and isolated reports of flooding during the afternoon of the 14th.', 'At 11:44 AM EST, a tree was reported down across State Route 32 in Petersham.');
INSERT INTO public.stormevents_east VALUES (782837, 201808, 14, 1308, 201808, 14, 1500, 130823, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '14-AUG-18 13:08:00', 'EST-5', '14-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'WHALOM', 0, 'W', 'WHALOM', 42.5207, -71.7557, 42.5205, -71.7548, 'Low pressure centered over New York brought tropical air north into Southern New England.  This generated thunderstorms which caused isolated tree damage and isolated reports of flooding during the afternoon of the 14th.', 'At 1:08 PM EST, the intersection of Lancaster Street and Graham Street was reported closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (782856, 201808, 17, 1330, 201808, 17, 1330, 130824, 'MASSACHUSETTS', 25, 2018, 'August', 'Lightning', 'BOX', '17-AUG-18 13:30:00', 'EST-5', '17-AUG-18 13:30:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 2, 'W', 'NORTHFIELD FARMS', 2, 'W', 'NORTHFIELD FARMS', 42.6202, -72.5015, 42.6202, -72.5015, 'Low pressure moved east from the Great Lakes. This drew warm humid air north across Massachusetts, then swung a cold front across the state.  This caused afternoon thunderstorms; the most damaging thunderstorms moved across the northern half of Massachusetts.', 'At 1:30 PM EST, a house fire due to lightning was reported on Barney Hale Road in Gill.');
INSERT INTO public.stormevents_east VALUES (782857, 201808, 17, 1330, 201808, 17, 1330, 130824, 'MASSACHUSETTS', 25, 2018, 'August', 'Lightning', 'BOX', '17-AUG-18 13:30:00', 'EST-5', '17-AUG-18 13:30:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 1, 'SE', 'MONTAGUE STATION', 1, 'SE', 'MONTAGUE STATION', 42.5418, -72.5175, 42.5418, -72.5175, 'Low pressure moved east from the Great Lakes. This drew warm humid air north across Massachusetts, then swung a cold front across the state.  This caused afternoon thunderstorms; the most damaging thunderstorms moved across the northern half of Massachusetts.', 'At 1:30 PM EST, a house fire due to lightning was reported near State Route 63 in Montague.');
INSERT INTO public.stormevents_east VALUES (782860, 201808, 17, 1338, 201808, 17, 1338, 130824, 'MASSACHUSETTS', 25, 2018, 'August', 'Lightning', 'BOX', '17-AUG-18 13:38:00', 'EST-5', '17-AUG-18 13:38:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 1, 'ENE', 'COOLEYVILLE', 1, 'ENE', 'COOLEYVILLE', 42.4726, -72.3531, 42.4726, -72.3531, 'Low pressure moved east from the Great Lakes. This drew warm humid air north across Massachusetts, then swung a cold front across the state.  This caused afternoon thunderstorms; the most damaging thunderstorms moved across the northern half of Massachusetts.', 'At 1:38 PM EST, a house fire due to lightning was reported at 16 Cooleyville Road in New Salem.');
INSERT INTO public.stormevents_east VALUES (782862, 201808, 17, 2215, 201808, 17, 2215, 130824, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '17-AUG-18 22:15:00', 'EST-5', '17-AUG-18 22:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'MIDDLEFIELD', 1, 'SW', 'MIDDLEFIELD', 42.3407, -73.0325, 42.3407, -73.0325, 'Low pressure moved east from the Great Lakes. This drew warm humid air north across Massachusetts, then swung a cold front across the state.  This caused afternoon thunderstorms; the most damaging thunderstorms moved across the northern half of Massachusetts.', 'At 10:15 PM EST, a tree and wires were brought down on the lower part of Town Hill Road in Middlefield.');
INSERT INTO public.stormevents_east VALUES (782237, 201808, 3, 2013, 201808, 3, 2330, 130470, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '03-AUG-18 20:13:00', 'EST-5', '03-AUG-18 23:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'GRAHAMSVILLE', 1, 'S', 'GRAHAMSVILLE', 41.85, -74.57, 41.8296, -74.5702, 'Deep tropical-like air surging into NY interacted with areas of weak low pressure, causing  several rounds of heavy rain producing thunderstorms throughout the day. Repeating storms over certain locations led to rapid onset flooding.', 'Flash flooding was surging water across a road and into the basement of a house near Main Street and River Road.');
INSERT INTO public.stormevents_east VALUES (782265, 201808, 8, 1849, 201808, 8, 2300, 130474, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '08-AUG-18 18:49:00', 'EST-5', '08-AUG-18 23:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'KIRKWOOD', 1, 'ENE', 'KIRKWOOD ARPK ARPT', 42.03, -75.78, 42.0098, -75.7596, 'Persistent tropical-like moisture remained across the northeastern United States. An upper level disturbance moved through the region, triggering heavy rain producing thunderstorms during the late afternoon and evening hours.', 'Streams and creeks were out of their banks flooding Route 11 and surrounding areas.');
INSERT INTO public.stormevents_east VALUES (782269, 201808, 8, 1832, 201808, 8, 2300, 130474, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '08-AUG-18 18:32:00', 'EST-5', '08-AUG-18 23:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'KIRKWOOD', 1, 'N', 'KIRKWOOD', 42.03, -75.78, 42.0474, -75.7845, 'Persistent tropical-like moisture remained across the northeastern United States. An upper level disturbance moved through the region, triggering heavy rain producing thunderstorms during the late afternoon and evening hours.', 'Several streets were flooded in Kirkwood and surrounding areas.');
INSERT INTO public.stormevents_east VALUES (782273, 201808, 8, 1948, 201808, 8, 2315, 130474, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '08-AUG-18 19:48:00', 'EST-5', '08-AUG-18 23:15:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'HANCOCK', 1, 'N', 'HANCOCK', 41.95, -75.28, 41.9627, -75.2771, 'Persistent tropical-like moisture remained across the northeastern United States. An upper level disturbance moved through the region, triggering heavy rain producing thunderstorms during the late afternoon and evening hours.', 'Severe street flooding was occurring in Hancock. Water was entering downtown businesses and other properties. Flash flooding was coming directly off the hillsides as sheet and debris flow. Streams were at bankful and in danger of flooding.');
INSERT INTO public.stormevents_east VALUES (782276, 201808, 8, 2136, 201808, 8, 2316, 130474, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '08-AUG-18 21:36:00', 'EST-5', '08-AUG-18 23:16:00', 0, 0, 0, 0, '300.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'HANCOCK', 1, 'WSW', 'HANCOCK', 41.9563, -75.2824, 41.9483, -75.2897, 'Persistent tropical-like moisture remained across the northeastern United States. An upper level disturbance moved through the region, triggering heavy rain producing thunderstorms during the late afternoon and evening hours.', 'Devastating flash flooding occurred along E. Main Street with 18 inches of water over the road. Flooding entered a funeral home, clinic, many basements and at least one residence to the first floor. Nearly all roads in the village were closed, as well as major State Route 17 between Hancock and Deposit.');
INSERT INTO public.stormevents_east VALUES (782277, 201808, 8, 1831, 201808, 8, 2300, 130474, 'NEW YORK', 36, 2018, 'August', 'Flood', 'BGM', '08-AUG-18 18:31:00', 'EST-5', '08-AUG-18 23:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'VESTAL CENTER', 2, 'N', 'HAWLEYTON', 42.033, -76.0415, 42.0465, -75.9214, 'Persistent tropical-like moisture remained across the northeastern United States. An upper level disturbance moved through the region, triggering heavy rain producing thunderstorms during the late afternoon and evening hours.', 'Several creeks along State Line Road were flooding rural areas and back roads.');
INSERT INTO public.stormevents_east VALUES (782910, 201808, 14, 1832, 201808, 14, 2300, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 18:32:00', 'EST-5', '14-AUG-18 23:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'CHENANGO FORKS', 1, 'N', 'KETTELLVILLE', 42.25, -75.89, 42.2116, -75.8679, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flash flooding closed Route 11 near Knapp Hill Road.');
INSERT INTO public.stormevents_east VALUES (779584, 201808, 11, 1700, 201808, 11, 1700, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 17:00:00', 'EST-5', '11-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'CLIFTON', 1, 'ESE', 'LAKE VIEW', 40.8791, -74.1508, 40.8773, -74.1601, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Route 46 flooded in both directions west of Piaget Avenue in Clifton.');
INSERT INTO public.stormevents_east VALUES (779582, 201808, 11, 1644, 201808, 11, 1700, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 16:44:00', 'EST-5', '11-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'CLIFTON', 2, 'NNE', 'CLIFTON', 40.8931, -74.1301, 40.8927, -74.1326, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Flooding closed all lanes on US 46 westbound at NJ 20 in Clifton.');
INSERT INTO public.stormevents_east VALUES (779586, 201808, 11, 1707, 201808, 11, 1737, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 17:07:00', 'EST-5', '11-AUG-18 17:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'CARLSTADT', 0, 'S', 'CARLSTADT', 40.8433, -74.0789, 40.8443, -74.0805, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'All lanes closed due to flooding on NJ 17 southbound at Moonachie Avenue in Wood-Ridge.');
INSERT INTO public.stormevents_east VALUES (779589, 201808, 11, 1730, 201808, 11, 1830, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 17:30:00', 'EST-5', '11-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'GLEN RIDGE', 0, 'NW', 'MONTCLAIR', 40.8159, -74.2324, 40.8329, -74.2237, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Flash flooding reported throughout the town of Verona.');
INSERT INTO public.stormevents_east VALUES (779609, 201808, 11, 728, 201808, 11, 900, 130194, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 07:28:00', 'EST-5', '11-AUG-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'NEW YORK', 2, 'NE', 'NEW YORK', 40.7437, -73.9711, 40.7442, -73.9721, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in isolated flash flooding in New York City. Rainfall amounts ranged from 1-3 inches across the city, with the majority of that rain falling in just a 1-2 hour time frame. The ASOS in Central Park recorded 2.90 inches of rain.', 'Flooding reported on FDR Drive with water up to car bottoms.');
INSERT INTO public.stormevents_east VALUES (767231, 201808, 17, 1842, 201808, 17, 1842, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 18:42:00', 'EST-5', '17-AUG-18 18:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'N', 'GABELSVILLE', 1, 'N', 'GABELSVILLE', 40.35, -75.67, 40.35, -75.67, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Tree down at Sawmill Road and Hauseman Road in Colebrookdale Twp. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (767232, 201808, 17, 1850, 201808, 17, 1850, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 18:50:00', 'EST-5', '17-AUG-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'N', 'SOUTH EASTON', 1, 'N', 'SOUTH EASTON', 40.69, -75.22, 40.69, -75.22, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Trees and wires down in Easton. Time estimated from radar.');
