INSERT INTO public.stormevents_east VALUES (767234, 201808, 17, 1757, 201808, 17, 1757, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '17-AUG-18 17:57:00', 'EST-5', '17-AUG-18 17:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SSW', 'WINDSOR CASTLE', 1, 'SSW', 'WINDSOR CASTLE', 40.51, -75.94, 40.51, -75.94, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Several reports of trees down in Perry Twp...including near Schappell Road and Merkel Lane and on Grandview Road.');
INSERT INTO public.stormevents_east VALUES (769251, 201808, 17, 1815, 201808, 17, 1945, 127903, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '17-AUG-18 18:15:00', 'EST-5', '17-AUG-18 19:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'CHEROKEE RANCH', 1, 'ENE', 'WEST LEESPORT', 40.4144, -75.9383, 40.433, -75.9522, 'Severe thunderstorms and flash flooding impacted eastern PA and central/northern NJ.  Rainfall totals of 1 to 2 inches were reported in Berks County.', 'Flash flooding resulted in road closures in Ontelaunee Township.');
INSERT INTO public.stormevents_east VALUES (768962, 201808, 25, 1630, 201808, 25, 1630, 128210, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TBW', '25-AUG-18 16:30:00', 'EST-5', '25-AUG-18 16:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'NE', 'GULFPORT', 2, 'NE', 'GULFPORT', 27.77, -82.69, 27.77, -82.69, 'Easterly flow allowed scattered to numerous thunderstorms to develop over the Florida Peninsula and push west into the eastern Gulf of Mexico during the afternoon and early evening. One of these storms caused damaging wind gusts. Lightning strikes from other storms caused multiple structure fires.', 'Multiple trees and large branches were reported knocked down.');
INSERT INTO public.stormevents_east VALUES (773328, 201808, 31, 1136, 201808, 31, 1136, 128858, 'DELAWARE', 10, 2018, 'August', 'Thunderstorm Wind', 'PHI', '31-AUG-18 11:36:00', 'EST-5', '31-AUG-18 11:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 2, 'W', 'MILFORD', 2, 'W', 'MILFORD', 38.92, -75.45, 38.92, -75.45, 'Locally heavy rain produced a swath of 4 to 7 inch rainfall totals from southern New Castle County down to northern Sussex County on the afternoon and evening of August 31. Thunderstorms caused isolated wind damage as well.', 'Numerous trees and limbs reported down around the area.');
INSERT INTO public.stormevents_east VALUES (771097, 201808, 25, 1730, 201808, 25, 1730, 128210, 'FLORIDA', 12, 2018, 'August', 'Lightning', 'TBW', '25-AUG-18 17:30:00', 'EST-5', '25-AUG-18 17:30:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 2, 'SW', 'PORT RICHEY COMPS SITE', 2, 'SW', 'PORT RICHEY COMPS SITE', 28.2739, -82.7549, 28.2739, -82.7549, 'Easterly flow allowed scattered to numerous thunderstorms to develop over the Florida Peninsula and push west into the eastern Gulf of Mexico during the afternoon and early evening. One of these storms caused damaging wind gusts. Lightning strikes from other storms caused multiple structure fires.', 'A stilt house just off the beach in Port Richey completely burned down after being struck by lightning. Time was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (768575, 201808, 13, 1530, 201808, 13, 1530, 128152, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '13-AUG-18 15:30:00', 'EST-5', '13-AUG-18 15:30:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 0.75, NULL, NULL, NULL, 3, 'WNW', 'WOODSON', 3, 'WNW', 'WOODSON', 37.7703, -79.1367, 37.7703, -79.1367, 'A closed upper level low helped to trigger scattered severe thunderstorms during the afternoon.  These storms blew down a number of trees and produced hail up to the size of quarters.', 'Hail up to the size of pennies fell about five miles east of Alto.');
