INSERT INTO public.stormevents_east VALUES (769577, 201808, 21, 2240, 201808, 22, 400, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:40:00', 'EST-5', '22-AUG-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'PENNSBURG', 0, 'SE', 'FRUITVILLE', 40.3914, -75.5145, 40.3971, -75.5274, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Moderate flooding occurred along the East Branch of the Perkiomen Creek at East Greenville.');
INSERT INTO public.stormevents_east VALUES (769583, 201808, 21, 2245, 201808, 22, 45, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:45:00', 'EST-5', '22-AUG-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'GOUGLERSVILLE', 1, 'WSW', 'MOHNTON', 40.2751, -76.0053, 40.2757, -76.0001, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'A mudslide occurred at the intersection of Vermont Road and Hampshire Road in Cumru Township.');
INSERT INTO public.stormevents_east VALUES (769588, 201808, 21, 2255, 201808, 22, 100, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:55:00', 'EST-5', '22-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'WESCOSVILLE', 1, 'NW', 'CETRONIA', 40.5886, -75.5566, 40.5863, -75.5384, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Numerous road closures in South Whitehall Township.  Several vehicles were trapped in the flood waters.');
INSERT INTO public.stormevents_east VALUES (769599, 201808, 21, 2235, 201808, 22, 30, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:35:00', 'EST-5', '22-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'FRITZTOWN', 1, 'SW', 'MONTELLO', 40.2986, -76.0707, 40.3096, -76.0491, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Fritztown Road was closed due to flash flooding between Old Fritztown Road and Chapel Hill Road in South Heidelberg Township and Spring Township.');
INSERT INTO public.stormevents_east VALUES (769604, 201808, 21, 2310, 201808, 22, 110, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 23:10:00', 'EST-5', '22-AUG-18 01:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'LOCKPORT', 0, 'NE', 'LOCKPORT', 40.732, -75.5429, 40.7331, -75.5467, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Flash flooding resulted in the closure of Riverview Drive in Lehigh Township.');
INSERT INTO public.stormevents_east VALUES (769615, 201808, 21, 2310, 201808, 22, 110, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 23:10:00', 'EST-5', '22-AUG-18 01:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'SEEMSVILLE', 1, 'NNE', 'JACKSONVILLE', 40.7248, -75.4461, 40.7321, -75.4166, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Widespread roadway flooding in East Allen Township.');
INSERT INTO public.stormevents_east VALUES (769628, 201808, 21, 2250, 201808, 22, 100, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:50:00', 'EST-5', '22-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'CHEROKEE RANCH', 1, 'ESE', 'LEESPORT', 40.414, -75.9373, 40.4438, -75.9552, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Widespread roadway flooding in Ontlelaunee Township with several roads closed.');
INSERT INTO public.stormevents_east VALUES (769650, 201808, 21, 2245, 201808, 22, 45, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:45:00', 'EST-5', '22-AUG-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'SEIPSTOWN', 2, 'NNW', 'SIGMUND', 40.5528, -75.6794, 40.494, -75.5875, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Widespread roadway flooding in Upper Macungie Township, Lower Macungie Township and Macungie.');
INSERT INTO public.stormevents_east VALUES (782884, 201808, 18, 1700, 201808, 18, 1700, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Lightning', 'BOX', '18-AUG-18 17:00:00', 'EST-5', '18-AUG-18 17:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 1, 'N', 'SANDWICH', 1, 'N', 'SANDWICH', 41.7701, -70.4959, 41.7701, -70.4959, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 5 PM EST, a house was struck by lightning on Knott Avenue in Sandwich.');
INSERT INTO public.stormevents_east VALUES (782887, 201808, 18, 1420, 201808, 18, 1420, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '18-AUG-18 14:20:00', 'EST-5', '18-AUG-18 14:20:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'NNE', 'SOUTHBRIDGE ARPT', 1, 'SSW', 'DODGE', 42.1241, -72.0135, 42.1569, -71.938, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 2:20 PM EST, a tree was down near Berry Corner Road in Charlton partly blocking the road.  Another tree was down on Carroll Hill Road in Charlton.');
INSERT INTO public.stormevents_east VALUES (782892, 201808, 18, 1309, 201808, 18, 1510, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '18-AUG-18 13:09:00', 'EST-5', '18-AUG-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BRIGHTWOOD', 1, 'SSE', 'BRIGHTWOOD', 42.1103, -72.598, 42.1106, -72.5974, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 1:09 PM EST, the Dwight Street ramp for Route 91 was impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (782894, 201808, 18, 1311, 201808, 18, 1600, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '18-AUG-18 13:11:00', 'EST-5', '18-AUG-18 16:00:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'SPRINGFIELD', 1, 'SSW', 'SPRINGFIELD', 42.1029, -72.5898, 42.1017, -72.588, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 1:11 PM EST, water was reported entering basements on the 1300 block of Main Street in Springfield.');
INSERT INTO public.stormevents_east VALUES (782897, 201808, 18, 1325, 201808, 18, 1600, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '18-AUG-18 13:25:00', 'EST-5', '18-AUG-18 16:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ARMORY', 1, 'E', 'ARMORY', 42.1169, -72.5522, 42.1171, -72.5504, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 1:25 PM EST, Roosevelt Avenue and Berlin Street were flooded to about one foot. |There were at least two trapped cars, with one requiring the rescue of a woman and child.');
INSERT INTO public.stormevents_east VALUES (782899, 201808, 18, 1348, 201808, 18, 1600, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '18-AUG-18 13:48:00', 'EST-5', '18-AUG-18 16:00:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'BRIGHTWOOD', 0, 'ENE', 'BRIGHTWOOD', 42.1209, -72.5943, 42.1227, -72.5915, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 1:48 PM EST, water was flowing into basements on Melha Avenue and Parkside Street, as well as Ashley Street.');
INSERT INTO public.stormevents_east VALUES (782900, 201808, 18, 1401, 201808, 18, 1700, 130831, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '18-AUG-18 14:01:00', 'EST-5', '18-AUG-18 17:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'ARMORY', 0, 'SSE', 'ARMORY', 42.1183, -72.573, 42.1176, -72.5681, 'A cold front moved through Massachusetts during the afternoon and evening of August 18th.  Showers and thunderstorms associated with this front left from one to three inches of rain in the state, with numerous reports of flooding.', 'At 2:01 PM EST, basement flooding was reported on Harvard Street in Springfield.');
INSERT INTO public.stormevents_east VALUES (746165, 201804, 25, 1200, 201804, 26, 2200, 124367, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'RNK', '25-APR-18 12:00:00', 'EST-5', '26-APR-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'SOUTH BOSTON', 3, 'SSW', 'PACES', 36.696, -78.8913, 36.6034, -79.1117, 'A wet period developed from April 23-25 as an upper level low over the southeastern U.S. slowly tracked toward the Atlantic coast. Rainfall was persistent during this period with sustained south to southeasterly flow with the heaviest rains falling in the 24-hour period ending 12z (7AM) on the 24th. Rainfall of 2 to 3 inch amounts were common.', 'The Dan River at South Boston (SBNV2) crested at 22.2 feet (Minor Flood stage - 19 ft.), with mainly lowland flooding.');
INSERT INTO public.stormevents_east VALUES (782931, 201808, 14, 2046, 201808, 14, 2200, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 20:46:00', 'EST-5', '14-AUG-18 22:00:00', 0, 0, 0, 0, '100.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'HAMILTON', 2, 'ENE', 'HAMILTON', 42.8123, -75.549, 42.8286, -75.5025, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Streets flooded throughout the village of Hamilton. Many cars stranded.');
INSERT INTO public.stormevents_east VALUES (782933, 201808, 14, 1945, 201808, 14, 2200, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 19:45:00', 'EST-5', '14-AUG-18 22:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BOUCKVILLE', 0, 'ENE', 'PECKSPORT', 42.88, -75.54, 42.8704, -75.5485, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Route 12B washed out near Hinman Road.');
INSERT INTO public.stormevents_east VALUES (782935, 201808, 14, 520, 201808, 14, 1500, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 05:20:00', 'EST-5', '14-AUG-18 15:00:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'HECTOR', 1, 'NNE', 'HECTOR', 42.5078, -76.8872, 42.5102, -76.8611, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Many roads flooded and damaged by severe flash flooding. People trapped in homes with rescues underway.');
INSERT INTO public.stormevents_east VALUES (782937, 201808, 14, 421, 201808, 14, 1500, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 04:21:00', 'EST-5', '14-AUG-18 15:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'LODI STATION', 2, 'ENE', 'LODI', 42.6252, -76.868, 42.6272, -76.7896, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Numerous roads were flooded across southern Seneca county.');
INSERT INTO public.stormevents_east VALUES (782940, 201808, 14, 420, 201808, 14, 2000, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 04:20:00', 'EST-5', '14-AUG-18 20:00:00', 0, 0, 0, 0, '1.20M', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'LODI STATION', 2, 'SW', 'LODI STATION', 42.62, -76.88, 42.5952, -76.8758, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Severe flash flooding occurred in this area. The entire cliff side was washed away into Seneca Lake. Multiple water rescues and evacuations were in progress. A woman was trapped in the wreckage of her home, and was rescued from the lake by small boat.');
INSERT INTO public.stormevents_east VALUES (782942, 201808, 14, 448, 201808, 14, 1500, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 04:48:00', 'EST-5', '14-AUG-18 15:00:00', 0, 0, 0, 0, '125.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'LODI STATION', 2, 'NW', 'CAYWOOD', 42.62, -76.87, 42.5942, -76.8752, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Many vehicles and seasonal campers washed down Mill Creek.');
INSERT INTO public.stormevents_east VALUES (782943, 201808, 14, 452, 201808, 14, 1000, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 04:52:00', 'EST-5', '14-AUG-18 10:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'LODI', 2, 'ESE', 'LODI', 42.61, -76.83, 42.6067, -76.7873, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Swift water rescues were in progress for people trapped in houses near Lodi.');
INSERT INTO public.stormevents_east VALUES (779596, 201808, 11, 1550, 201808, 11, 1750, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 15:50:00', 'EST-5', '11-AUG-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'MONTCLAIR', 1, 'NW', 'MONTCLAIR', 40.8461, -74.2366, 40.8461, -74.2346, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'The Peckman River at Verona rose above its flood stage of 3.5 feet at 4:50pm EDT. The river continued to rise above its moderate flood stage of 4.0 feet (4:55pm EDT) and major flood stage of 5.0 feet (5:10pm EDT) before cresting at a height of 6.36 feet at 5:35pm EDT. The river fell back below flood stage at 6:50pm EDT. The crest of 6.36 feet was within about 0.2 feet of the record crest at this location of 6.6 feet.');
INSERT INTO public.stormevents_east VALUES (779597, 201808, 11, 1740, 201808, 11, 2030, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 17:40:00', 'EST-5', '11-AUG-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BELWOOD PARK', 1, 'W', 'BELWOOD PARK', 40.8004, -74.1887, 40.7995, -74.1892, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'The Third River at Bloomfield rose above its flood stage of 6.0 feet at 6:40pm EDT, crested at a height of 7.15 feet at 7:40pm EDT, then fell back below flood stage at 9:30pm EDT.');
INSERT INTO public.stormevents_east VALUES (779602, 201808, 11, 1800, 201808, 11, 1830, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 18:00:00', 'EST-5', '11-AUG-18 18:30:00', 0, 0, 0, 0, '3.20M', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'GREAT NOTCH', 1, 'SSE', 'TOTOWA', 40.8881, -74.2117, 40.8894, -74.2164, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Flooding from the Peckman River impacted the Party City and Best Buy shopping centers as well as the Planet Fitness gym in Woodland Park. Cars were underwater in the Best Buy parking lot. Overall, approximately 210 homes, 70 businesses, and 22 parked cars were impacted by flooding in Woodland Park.');
INSERT INTO public.stormevents_east VALUES (768245, 201808, 8, 1621, 201808, 8, 1621, 128098, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 16:21:00', 'EST-5', '08-AUG-18 16:21:00', 0, 0, 0, 0, '0.50K', NULL, 'Public', 50, 'EG', NULL, NULL, 2, 'WSW', 'BOONVILLE ARPT', 2, 'WSW', 'BOONVILLE ARPT', 36.212, -80.7455, 36.212, -80.7455, 'A hot and humid air mass sparked numerous severe thunderstorms during the afternoon.  These storms downed a copious amount of trees and power lines across the North Carolina Piedmont.  Surry County suffered the most notable damage.  Lightning also struck a power transformer in Yadkin County.', 'Thunderstorm winds blew down one tree at the intersection of Moxley Road and North Oak Ridge Church Road.');
INSERT INTO public.stormevents_east VALUES (765083, 201808, 11, 1242, 201808, 11, 1242, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Hail', 'PHI', '11-AUG-18 12:42:00', 'EST-5', '11-AUG-18 12:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 0.75, NULL, NULL, NULL, 1, 'WNW', 'KING OF PRUSSIA', 1, 'WNW', 'KING OF PRUSSIA', 40.09, -75.4, 40.09, -75.4, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Dime size hail in King of Prussia. TIme estimated from radar.');
INSERT INTO public.stormevents_east VALUES (767165, 201808, 11, 440, 201808, 11, 640, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 04:40:00', 'EST-5', '11-AUG-18 06:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'MT PLEASANT', 2, 'NE', 'MT PLEASANT', 40.4263, -76.0393, 40.4231, -76.0381, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'A vehicle was trapped in flood waters near the intersection of Plum Creek Road and Bloomsburg Road in Penn Township resulting in the need for a water rescue.');
INSERT INTO public.stormevents_east VALUES (767166, 201808, 11, 450, 201808, 11, 650, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 04:50:00', 'EST-5', '11-AUG-18 06:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'DAUBERVILLE', 1, 'NNE', 'DAUBERVILLE', 40.4553, -75.9757, 40.4578, -75.976, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Route 61 was closed in both directions around Bellemans Church Road and Indian Manor Drive in Ontelaunee Township due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (767169, 201808, 11, 1255, 201808, 11, 1500, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 12:55:00', 'EST-5', '11-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KING OF PRUSSIA', 1, 'N', 'KING OF PRUSSIA', 40.0977, -75.3866, 40.0984, -75.38, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'A water rescue took place on Crossfield Road in Upper Merion Township due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (767171, 201808, 11, 1325, 201808, 11, 1525, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 13:25:00', 'EST-5', '11-AUG-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'MOORE', 1, 'E', 'MOORE', 39.8846, -75.3094, 39.8806, -75.306, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Two vehicles were trapped in flood waters on Lincoln Avenue in Prospect Park resulting in the need for water rescues.');
INSERT INTO public.stormevents_east VALUES (767173, 201808, 11, 1400, 201808, 11, 1900, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 14:00:00', 'EST-5', '11-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'SPINNERSTOWN', 1, 'NNE', 'STEINSBURG', 40.4395, -75.4573, 40.4771, -75.4138, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Widespread flash flooding occurred in Milford Township.  Five water rescues took place and eight individuals were evacuated from their homes.  Many roads were closed due to the flooding.');
INSERT INTO public.stormevents_east VALUES (767175, 201808, 11, 1425, 201808, 11, 1900, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 14:25:00', 'EST-5', '11-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'DILLINGER', 2, 'ESE', 'DILLINGERSVILLE', 40.4939, -75.4669, 40.4618, -75.4407, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Heavy rain resulted in a landslide along the Northeast Extension of the Pennsylvania Turnpike in Lower Milford Township closing all southbound lanes.');
INSERT INTO public.stormevents_east VALUES (768216, 201808, 8, 1435, 201808, 8, 1435, 128098, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 14:35:00', 'EST-5', '08-AUG-18 14:35:00', 0, 0, 0, 0, '5.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NW', 'YANCEYVILLE', 0, 'NW', 'YANCEYVILLE', 36.4028, -79.3332, 36.4028, -79.3332, 'A hot and humid air mass sparked numerous severe thunderstorms during the afternoon.  These storms downed a copious amount of trees and power lines across the North Carolina Piedmont.  Surry County suffered the most notable damage.  Lightning also struck a power transformer in Yadkin County.', 'Thunderstorm winds blew down a tree and a power line on Lee Street in Yanceyville.');
INSERT INTO public.stormevents_east VALUES (768249, 201808, 8, 1635, 201808, 8, 1635, 128098, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 16:35:00', 'EST-5', '08-AUG-18 16:35:00', 0, 0, 0, 0, '20.00K', NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 1, 'SW', 'SHOAL', 1, 'SW', 'SHOAL', 36.2739, -80.5112, 36.2739, -80.5112, 'A hot and humid air mass sparked numerous severe thunderstorms during the afternoon.  These storms downed a copious amount of trees and power lines across the North Carolina Piedmont.  Surry County suffered the most notable damage.  Lightning also struck a power transformer in Yadkin County.', 'Thunderstorm winds blew down over twenty trees and two power lines near Shoals.  The damage path was about 100 yards wide and between a quarter and a third of a mile long.');
INSERT INTO public.stormevents_east VALUES (768250, 201808, 8, 1650, 201808, 8, 1650, 128098, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 16:50:00', 'EST-5', '08-AUG-18 16:50:00', 0, 0, 0, 0, '5.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'MAYODAN MAYO ARPT', 1, 'NNW', 'MAYODAN MAYO ARPT', 36.4072, -79.9857, 36.4072, -79.9857, 'A hot and humid air mass sparked numerous severe thunderstorms during the afternoon.  These storms downed a copious amount of trees and power lines across the North Carolina Piedmont.  Surry County suffered the most notable damage.  Lightning also struck a power transformer in Yadkin County.', 'Thunderstorm winds blew down one tree that also took down a power line near the intersection of Ayersville Road and Turner Road.');
INSERT INTO public.stormevents_east VALUES (782580, 201808, 8, 1306, 201808, 8, 1306, 128098, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 13:06:00', 'EST-5', '08-AUG-18 13:06:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'PILOT MTN', 1, 'WSW', 'PILOT MTN', 36.3756, -80.4907, 36.3756, -80.4907, 'A hot and humid air mass sparked numerous severe thunderstorms during the afternoon.  These storms downed a copious amount of trees and power lines across the North Carolina Piedmont.  Surry County suffered the most notable damage.  Lightning also struck a power transformer in Yadkin County.', 'Thunderstorm winds below down a power line on Barney Venable Road.');
INSERT INTO public.stormevents_east VALUES (768200, 201808, 8, 1408, 201808, 8, 1408, 128098, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 14:08:00', 'EST-5', '08-AUG-18 14:08:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'MAYFIELD', 1, 'N', 'MAYFIELD', 36.535, -79.571, 36.535, -79.571, 'A hot and humid air mass sparked numerous severe thunderstorms during the afternoon.  These storms downed a copious amount of trees and power lines across the North Carolina Piedmont.  Surry County suffered the most notable damage.  Lightning also struck a power transformer in Yadkin County.', 'Thunderstorm winds blew down one tree on Dodson Road near the intersection with Gravel Hill Road.');
INSERT INTO public.stormevents_east VALUES (767848, 201808, 1, 2018, 201808, 1, 2018, 128020, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '01-AUG-18 20:18:00', 'EST-5', '01-AUG-18 20:18:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNE', 'ENONVILLE', 3, 'NNE', 'ENONVILLE', 37.5321, -78.4989, 37.5321, -78.4989, 'Scattered severe thunderstorms developed in parts of the Virginia Piedmont during the afternoon.  The storms blew down several trees and power lines, and lightning from one of these storms struck a residence.', 'Thunderstorm winds blew down one tree on the eastbound lanes of West James Anderson Highway.');
INSERT INTO public.stormevents_east VALUES (767849, 201808, 1, 2025, 201808, 1, 2025, 128020, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '01-AUG-18 20:25:00', 'EST-5', '01-AUG-18 20:25:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SE', 'DILLWYN', 2, 'SE', 'DILLWYN', 37.5047, -78.4254, 37.5047, -78.4254, 'Scattered severe thunderstorms developed in parts of the Virginia Piedmont during the afternoon.  The storms blew down several trees and power lines, and lightning from one of these storms struck a residence.', 'Thunderstorm winds blew down one tree on Rosney Road.');
INSERT INTO public.stormevents_east VALUES (767911, 201808, 6, 1518, 201808, 6, 1518, 128034, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '06-AUG-18 15:18:00', 'EST-5', '06-AUG-18 15:18:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 1, NULL, NULL, NULL, 4, 'ESE', 'SHELORS MILL', 4, 'ESE', 'SHELORS MILL', 36.843, -80.3199, 36.843, -80.3199, 'One severe thunderstorm developed over Floyd County and produced hail up to the size of quarters.', 'Hail up to the size of quarters fell near the Tuggle Gap entrance to the Blue Ridge Parkway.');
INSERT INTO public.stormevents_east VALUES (767916, 201808, 7, 1941, 201808, 7, 1941, 128036, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '07-AUG-18 19:41:00', 'EST-5', '07-AUG-18 19:41:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'LONGTOWN', 1, 'NE', 'LONGTOWN', 36.1643, -80.7503, 36.1643, -80.7503, 'Scattered severe thunderstorms developed in the afternoon from a hot and humid air mass.  These storms blew several trees down in the North Carolina Piedmont.', 'Thunderstorm winds blew down one tree along Whitaker Road.');
INSERT INTO public.stormevents_east VALUES (767918, 201808, 7, 1946, 201808, 7, 1951, 128036, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '07-AUG-18 19:46:00', 'EST-5', '07-AUG-18 19:51:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'RICHMOND HILL', 0, 'NW', 'NEBO', 36.2523, -80.6504, 36.2233, -80.6559, 'Scattered severe thunderstorms developed in the afternoon from a hot and humid air mass.  These storms blew several trees down in the North Carolina Piedmont.', 'Thunderstorm winds blew down one tree at the intersection of Rockford Road and Gadberry Road and a second tree along Rockford Road between the intersections of Route 67 and Nebo Road.');
INSERT INTO public.stormevents_east VALUES (767919, 201808, 7, 1957, 201808, 7, 1957, 128036, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '07-AUG-18 19:57:00', 'EST-5', '07-AUG-18 19:57:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'SMITHTOWN', 1, 'WSW', 'SMITHTOWN', 36.223, -80.6034, 36.223, -80.6034, 'Scattered severe thunderstorms developed in the afternoon from a hot and humid air mass.  These storms blew several trees down in the North Carolina Piedmont.', 'Thunderstorm winds blew down one tree on Vallie Davis Drive just off Route 67.');
INSERT INTO public.stormevents_east VALUES (767922, 201808, 7, 1517, 201808, 7, 1517, 128038, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '07-AUG-18 15:17:00', 'EST-5', '07-AUG-18 15:17:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'ELLISTON', 0, 'S', 'ELLISTON', 37.2068, -80.2358, 37.2156, -80.2305, 'Scattered severe thunderstorms developed during the afternoon from a hot and humid air mass.  These storms blew down several trees and a telephone line.', 'Thunderstorm winds blew down one tree at the intersection of Roanoke Road and Crozier Road and a second tree down on Brake Road in Elliston.');
INSERT INTO public.stormevents_east VALUES (767924, 201808, 7, 1522, 201808, 7, 1522, 128038, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '07-AUG-18 15:22:00', 'EST-5', '07-AUG-18 15:22:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'LAFAYETTE', 2, 'ENE', 'LAFAYETTE', 37.233, -80.1956, 37.233, -80.1956, 'Scattered severe thunderstorms developed during the afternoon from a hot and humid air mass.  These storms blew down several trees and a telephone line.', 'Thunderstorm winds blew down one tree along Roanoke Road between the intersections of Lafayette Road and Stones Keep Lane.');
INSERT INTO public.stormevents_east VALUES (773854, 201808, 12, 1630, 201808, 12, 1630, 129116, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '12-AUG-18 16:30:00', 'EST-5', '12-AUG-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 35, 'MG', NULL, NULL, 3, 'WNW', 'CAPE CANAVERAL', 3, 'WNW', 'CAPE CANAVERAL', 28.4, -80.65, 28.4, -80.65, 'Florida was sandwiched in between two areas of high pressure, one over the Gulf of Mexico, and one over the western Atlantic Ocean. The resulting southwest winds pushed very moist air across the Florida peninsula. With cool temperatures in the mid-levels, plentiful moisture, and daytime heating the atmosphere was primed for scattered to numerous showers and thunderstorms to develop along the two sea breezes. The southwest winds favored the west coast sea breeze, thus the majority of the showers and storms developed on the east side of central Florida. Towards the late afternoon many of these showers and thunderstorms approached and moved across the coastal areas of Brevard County. Several reports of strong winds were received.', 'US Air Force wind tower 0300 measured a peak wind gust of 35 knots from the south.');
INSERT INTO public.stormevents_east VALUES (740200, 201804, 4, 204, 201804, 4, 205, 123439, 'WEST VIRGINIA', 54, 2018, 'April', 'Thunderstorm Wind', 'RNK', '04-APR-18 02:04:00', 'EST-5', '04-APR-18 02:05:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SW', 'NEMOURS', 1, 'WSW', 'LITTLESBURG', 37.2949, -81.3048, 37.31, -81.24, 'A cold front pushed a line of showers and thunderstorms into parts of southeast West Virginia.  The thunderstorms produced wind damage by knocking down two trees in Mercer County before dissipating.', 'One tree was blown down along Falls Mill Road, and one tree was blown down along Red Oak Ridge.');
INSERT INTO public.stormevents_east VALUES (773864, 201808, 13, 1655, 201808, 13, 1655, 129119, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '13-AUG-18 16:55:00', 'EST-5', '13-AUG-18 16:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 6, 'NNW', 'PLAYALINDA BEACH', 6, 'NNW', 'PLAYALINDA BEACH', 28.63, -80.81, 28.63, -80.81, 'A strong area of low pressure was located from the northeast Gulf of Mexico into the Carolinas, while an area of high pressure was located over the western Atlantic Ocean. This led to southwest winds across the Florida peninsula. Moisture was plentiful across the area and mid level temperatures were marginally cool. The combination of these factors set the stage for numerous showers and thunderstorms to develop across central Florida, with some storms becoming strong. The southwest winds favored the west coast sea breeze. By mid afternoon, scattered to numerous showers were developing across the Orlando Metro area, with some storms becoming strong. As these storms pushed towards the coast and crossed the intracoastal waters, they produced strong winds near the Cape in Brevard County.', 'Weatherflow site XPAR near Parrish Park in Titusville measured a peak wind gust of 36 knots from the south-southwest.');
INSERT INTO public.stormevents_east VALUES (773868, 201808, 13, 2142, 201808, 13, 2142, 129119, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MLB', '13-AUG-18 21:42:00', 'EST-5', '13-AUG-18 21:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 3, 'NNE', 'CAPE CANAVERAL', 3, 'NNE', 'CAPE CANAVERAL', 28.42, -80.59, 28.42, -80.59, 'A strong area of low pressure was located from the northeast Gulf of Mexico into the Carolinas, while an area of high pressure was located over the western Atlantic Ocean. This led to southwest winds across the Florida peninsula. Moisture was plentiful across the area and mid level temperatures were marginally cool. The combination of these factors set the stage for numerous showers and thunderstorms to develop across central Florida, with some storms becoming strong. The southwest winds favored the west coast sea breeze. By mid afternoon, scattered to numerous showers were developing across the Orlando Metro area, with some storms becoming strong. As these storms pushed towards the coast and crossed the intracoastal waters, they produced strong winds near the Cape in Brevard County.', 'National Ocean Service Station TRDF1, in Trident Pier, measured a peak wind gust of 34 knots from the south.');
INSERT INTO public.stormevents_east VALUES (765314, 201808, 3, 850, 201808, 3, 1000, 127619, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '03-AUG-18 08:50:00', 'EST-5', '03-AUG-18 10:00:00', 0, 0, 0, 0, '500.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'MT VERNON', 1, 'SW', 'HURRICANE', 38.4653, -81.9731, 38.4184, -82.048, 'An upper-level disturbance moved through West Virginia on the 3rd. This resulted in showers and thunderstorms with heavy rain, leading to isolated flash flooding.', 'Cow Creek flooded causing water to cover parts of Cow Creek Road. Indian Fork also flooded, forcing evacuations of the Westwood Mobile Home Community due to high water. Multiple homes were damaged.');
INSERT INTO public.stormevents_east VALUES (746024, 201804, 16, 1635, 201804, 17, 1040, 123444, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'RNK', '16-APR-18 16:35:00', 'EST-5', '17-APR-18 10:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'IRON GATE', 2, 'SSW', 'LONGDALE FURNACE', 37.7924, -79.7436, 37.8, -79.7373, 'A strong cold front propelled by a deep upper trough that took on a negative tilt, pushed through the region on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding but longer duration flooding occurred on several rivers and streams, mainly in the minor category. Rainfall ranged from 2 to 4 inches with locally higher amounts up to nearly 4.5 inches in 24-hours ending at 7 AM on the 16th. The highest amounts were roughly a 5-year recurrence interval (0.2 Annual exceedance probability).', 'The Cowpasture River near Clifton Forge (COWV2) flooded, reaching a stage of 13.80 feet (Minor flood stage - 10 ft.) early on the 17th. This was the highest level in over 20 years at this gauge--since a 14.39 ft. crest on January 8, 1998. USGS and FEMA data suggest a return interval of approximately 10 years (0.1 Annual Exceedance Probability or AEP) for the flooding on the Cowpasture.');
INSERT INTO public.stormevents_east VALUES (746039, 201804, 16, 1116, 201804, 17, 108, 123444, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'RNK', '16-APR-18 11:16:00', 'EST-5', '17-APR-18 01:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ROCKBRIDGE BATHS', 0, 'NE', 'ROCKBRIDGE BATHS', 37.9075, -79.4243, 37.9044, -79.414, 'A strong cold front propelled by a deep upper trough that took on a negative tilt, pushed through the region on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding but longer duration flooding occurred on several rivers and streams, mainly in the minor category. Rainfall ranged from 2 to 4 inches with locally higher amounts up to nearly 4.5 inches in 24-hours ending at 7 AM on the 16th. The highest amounts were roughly a 5-year recurrence interval (0.2 Annual exceedance probability).', 'The Maury River at Rockbridge Baths (ROBV2) gauge reached 10.40 feet (Minor flood stage ��� 9 ft.) which was the highest level since April, 2011 at this site. Several roads were flooded.');
INSERT INTO public.stormevents_east VALUES (746044, 201804, 16, 345, 201804, 17, 1630, 123444, 'VIRGINIA', 51, 2018, 'April', 'Flood', 'RNK', '16-APR-18 03:45:00', 'EST-5', '17-APR-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'BACOVA JCT', 1, 'ESE', 'BACOVA', 38.0471, -79.8721, 38.0681, -79.8401, 'A strong cold front propelled by a deep upper trough that took on a negative tilt, pushed through the region on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding but longer duration flooding occurred on several rivers and streams, mainly in the minor category. Rainfall ranged from 2 to 4 inches with locally higher amounts up to nearly 4.5 inches in 24-hours ending at 7 AM on the 16th. The highest amounts were roughly a 5-year recurrence interval (0.2 Annual exceedance probability).', 'The Jackson River near Bacova (BCVV2) gauge crested at 12.29 feet (Minor flood stage - 10 ft.) the highest since March 2, 2007. USGS frequency data showed this was close to a 5-year return (0.2 AEP) period.');
INSERT INTO public.stormevents_east VALUES (748571, 201804, 15, 1438, 201804, 15, 1438, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 14:38:00', 'EST-5', '15-APR-18 14:38:00', 0, 0, 0, 0, '2.50K', NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'WNW', 'FRANCISCO', 1, 'WNW', 'FRANCISCO', 36.5041, -80.3843, 36.5041, -80.3843, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Multiple large trees were blown down along the intersection of Route 89 and Horseshoe Road near Francisco.');
INSERT INTO public.stormevents_east VALUES (748573, 201804, 15, 1443, 201804, 15, 1443, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 14:43:00', 'EST-5', '15-APR-18 14:43:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'PINE RIDGE', 1, 'SE', 'PINE RIDGE', 36.489, -80.7107, 36.489, -80.7107, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Power lines were blown down by thunderstorm winds along Pine Ridge Road.');
INSERT INTO public.stormevents_east VALUES (780488, 201808, 7, 1810, 201808, 7, 1810, 130376, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '07-AUG-18 18:10:00', 'EST-5', '07-AUG-18 18:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NW', 'FOUR CORNERS', 1, 'NW', 'FOUR CORNERS', 42.6769, -71.5791, 42.6769, -71.5791, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts.  The airmass over the state was very humid and unstable. This generated strong thunderstorms, some causing damage. The front lingered north and west of the state on August 8th, forming thunderstorms and downpours in Massachusetts on that day, especially near Natick.', 'At 6:10 PM EST, thunderstorm winds brought a large tree down on Hollis Street in Pepperell.');
INSERT INTO public.stormevents_east VALUES (780491, 201808, 8, 1830, 201808, 8, 1830, 130376, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '08-AUG-18 18:30:00', 'EST-5', '08-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'MINUTE MAN ARPT', 1, 'SSW', 'MINUTE MAN ARPT', 42.4533, -71.534, 42.4527, -71.5344, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts.  The airmass over the state was very humid and unstable. This generated strong thunderstorms, some causing damage. The front lingered north and west of the state on August 8th, forming thunderstorms and downpours in Massachusetts on that day, especially near Natick.', 'At 6:30 PM EST, Dunster Drive in Stow was reported flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (780497, 201808, 8, 1859, 201808, 8, 2200, 130376, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '08-AUG-18 18:59:00', 'EST-5', '08-AUG-18 22:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'MAYNARD', 1, 'NNW', 'MAYNARD', 42.4373, -71.4538, 42.4377, -71.4527, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts.  The airmass over the state was very humid and unstable. This generated strong thunderstorms, some causing damage. The front lingered north and west of the state on August 8th, forming thunderstorms and downpours in Massachusetts on that day, especially near Natick.', 'At 6:59 PM EST, basement flooding was reported on Acton Street in Maynard.');
INSERT INTO public.stormevents_east VALUES (780501, 201808, 8, 1935, 201808, 8, 2200, 130376, 'MASSACHUSETTS', 25, 2018, 'August', 'Flood', 'BOX', '08-AUG-18 19:35:00', 'EST-5', '08-AUG-18 22:00:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'FELCHVILLE', 0, 'SSE', 'FELCHVILLE', 42.2955, -71.3763, 42.2983, -71.3495, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts.  The airmass over the state was very humid and unstable. This generated strong thunderstorms, some causing damage. The front lingered north and west of the state on August 8th, forming thunderstorms and downpours in Massachusetts on that day, especially near Natick.', 'At 7:35 PM EST, cars were trapped in two feet of water on Speen Street at Timber Lane in Natick. At 7:41 PM, cars were trapped in flood waters at the junction of State Routes 9 and 27 in Natick.  At 7:52 PM EST, a car was trapped in flood waters on Chrysler Road in Natick.  At 7:53 PM EST, Wethersfield Road was flooded with two feet on water.  At 8:04 PM, three feet of water covered the intersection of Terrance Avenue and Wethersfield Road.');
INSERT INTO public.stormevents_east VALUES (781162, 201808, 19, 2346, 201808, 20, 159, 130501, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '19-AUG-18 23:46:00', 'EST-5', '20-AUG-18 01:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'RALEIGH', 2, 'ESE', 'RALEIGH', 35.79, -78.64, 35.79, -78.6451, 'A meso-scale boundary along the North Carolina-Virginia state line sparked a complex of slow moving convection that produced 4 to 5 inches of rain and isolated flash flooding across Person County. This complex then moved southward into the Triangle region around midnight, where it produced another 3 to 4 inch swath of rain over the Raleigh-Durham Metro area. This heavy rainfall led to numerous reports of flash flooding within the Raleigh urban area, with multiple water rescues. Additionally, with saturated soils, the thunderstorms also produced scattered wind damage across the Raleigh metro.', 'Outbound Capital Blvd before Peace Street closed due to high water.');
INSERT INTO public.stormevents_east VALUES (782305, 201808, 13, 1111, 201808, 13, 1500, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 11:11:00', 'EST-5', '13-AUG-18 15:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'FASSETT', 1, 'NNW', 'FASSETT', 41.9859, -76.8014, 41.9921, -76.7741, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flash flooding closed Route 14 and Roaring Run Road. Wash over occurred and damaged these roads in several places.');
INSERT INTO public.stormevents_east VALUES (782307, 201808, 13, 1115, 201808, 13, 1400, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 11:15:00', 'EST-5', '13-AUG-18 14:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'WEST BURLINGTON', 1, 'NNE', 'BURLINGTON', 41.7835, -76.6392, 41.796, -76.5867, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flood waters closed several portions of U.S. Route 6 near Burlington.');
INSERT INTO public.stormevents_east VALUES (782309, 201808, 13, 1127, 201808, 13, 1400, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 11:27:00', 'EST-5', '13-AUG-18 14:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'TROY', 1, 'SSW', 'TROY', 41.77, -76.79, 41.7704, -76.8026, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Creeks were flowing across Route 14 and Beaverdale Roads on the south half of Troy. Road was damaged and closed.');
INSERT INTO public.stormevents_east VALUES (782312, 201808, 13, 1135, 201808, 13, 1400, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 11:35:00', 'EST-5', '13-AUG-18 14:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'MINNEQUA', 1, 'NNW', 'CEDAR LEDGE', 41.6768, -76.8637, 41.6436, -76.8779, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Several roads were flooded, and damaged in the Canton area.');
INSERT INTO public.stormevents_east VALUES (782316, 201808, 13, 1216, 201808, 13, 1530, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 12:16:00', 'EST-5', '13-AUG-18 15:30:00', 0, 0, 0, 0, '50.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'BENTLEY CREEK', 3, 'ESE', 'BENTLEY CREEK', 41.93, -76.64, 41.9312, -76.621, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Extensive flooding of Wolcott Hollow Road and a nearby residence. A bridge along the road was also washed out. Several roads in the area were impassable.');
INSERT INTO public.stormevents_east VALUES (782318, 201808, 13, 1243, 201808, 13, 1600, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 12:43:00', 'EST-5', '13-AUG-18 16:00:00', 0, 0, 0, 0, '150.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'RIDGEBURY', 1, 'S', 'BENTLEY CREEK', 41.94, -76.72, 41.9424, -76.68, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Severe flooding occurred in the area. Boats were requested for evacuations in Ridgebury Township. The Berwick Turnpike was closed near the NY/PA border due to flooding washouts.');
INSERT INTO public.stormevents_east VALUES (782327, 201808, 13, 1315, 201808, 13, 2100, 130510, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 13:15:00', 'EST-5', '13-AUG-18 21:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'NEW ALBANY', 1, 'SW', 'EVERGREEN', 41.6106, -76.4605, 41.6113, -76.4288, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Roads were damaged from flash flooding around the New Albany area.');
INSERT INTO public.stormevents_east VALUES (781794, 201808, 8, 1609, 201808, 8, 1609, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 16:09:00', 'EST-5', '08-AUG-18 16:09:00', 0, 0, 0, 0, '0.25K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'ETLAND', 1, 'WNW', 'ETLAND', 36.0836, -79.1855, 36.0836, -79.1855, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'A tree and power-line were blown down at 300 Tinnin Road.');
INSERT INTO public.stormevents_east VALUES (781795, 201808, 8, 1609, 201808, 8, 1609, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 16:09:00', 'EST-5', '08-AUG-18 16:09:00', 0, 0, 0, 0, '0.25K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WSW', 'SWEPSONVILLE', 3, 'WSW', 'SWEPSONVILLE', 36.0001, -79.4135, 36.0001, -79.4135, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Power-line was blown down on Rodgers Road.');
INSERT INTO public.stormevents_east VALUES (781796, 201808, 8, 1555, 201808, 8, 1555, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 15:55:00', 'EST-5', '08-AUG-18 15:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'BURLINGTON', 2, 'WSW', 'BURLINGTON', 36.0885, -79.4611, 36.0885, -79.4611, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was blown down on N. Oneal Street at Billingham Drive.');
INSERT INTO public.stormevents_east VALUES (781797, 201808, 8, 1541, 201808, 8, 1541, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 15:41:00', 'EST-5', '08-AUG-18 15:41:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 2, 'WSW', 'HALLS STORE', 2, 'WSW', 'HALLS STORE', 35.1127, -78.58, 35.1127, -78.58, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'Trees were reported down on power-lines on Maxwell Road.');
INSERT INTO public.stormevents_east VALUES (781798, 201808, 8, 1539, 201808, 8, 1539, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 15:39:00', 'EST-5', '08-AUG-18 15:39:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'CLEMENT', 3, 'SE', 'CLEMENT', 35.0623, -78.5978, 35.0623, -78.5978, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'One tree was blown down near the intersection of Carroll Store Road and Holland Road.');
INSERT INTO public.stormevents_east VALUES (780007, 201808, 27, 0, 201808, 27, 0, 130284, 'LAKE HURON', 90, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '27-AUG-18 00:00:00', 'EST-5', '27-AUG-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 40, 'MG', NULL, NULL, 0, 'N', 'SAGINAW BAY LIGHT', 0, 'N', 'SAGINAW BAY LIGHT', 43.81, -83.72, 43.81, -83.72, 'A thunderstorm moving through Saginaw Bay produced a 40 knot gust.', NULL);
INSERT INTO public.stormevents_east VALUES (781375, 201808, 2, 2123, 201808, 2, 2125, 130519, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '02-AUG-18 21:23:00', 'EST-5', '02-AUG-18 21:25:00', 0, 0, 0, 0, '2.00K', NULL, 'NWS Storm Survey', 61, 'EG', NULL, NULL, 1, 'N', 'COLLEGE PT', 1, 'N', 'FLUSHING ARPT', 40.7888, -73.8311, 40.7963, -73.8233, 'A passing trough of low pressure and upper level disturbance triggered an isolated severe thunderstorm in Queens, including producing a tornado in the College Point section.', 'Straight line wind damage occurred from near the southeast corner of Powell''s Cove Park, northeastward to the Francis Lewis Park near the Whitestone Bridge.');
INSERT INTO public.stormevents_east VALUES (781744, 201808, 7, 1257, 201808, 7, 1257, 130611, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '07-AUG-18 12:57:00', 'EST-5', '07-AUG-18 12:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'EAST GLENVILLE', 1, 'W', 'EAST GLENVILLE', 42.88, -73.94, 42.88, -73.94, 'Scattered showers and thunderstorms developed within a humid, warm airmass across eastern New York. Some of these storms became severe, resulting in numerous trees and wires down along with hail.', 'Trees were reported down.');
