INSERT INTO public.stormevents_east VALUES (782452, 201808, 20, 740, 201808, 20, 915, 130759, 'NORTH CAROLINA', 37, 2018, 'August', 'Flood', 'AKQ', '20-AUG-18 07:40:00', 'EST-5', '20-AUG-18 09:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'MOYOCK', 1, 'SW', 'CURRITUCK CO ARPT', 36.53, -76.18, 36.3859, -76.0454, 'Scattered thunderstorms associated with a trough of low pressure produced heavy rain which caused flooding across portions of northeast North Carolina.', 'Several roads were flooded.');
INSERT INTO public.stormevents_east VALUES (782458, 201808, 30, 2100, 201808, 30, 2100, 130761, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'AKQ', '30-AUG-18 21:00:00', 'EST-5', '30-AUG-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 49, 'MG', NULL, NULL, 4, 'SSE', 'YORK RIVER EAST REAR RANGE LIGHT WLON (YKRV2)', 4, 'SSE', 'YORK RIVER EAST REAR RANGE LIGHT WLON (YKRV2)', 37.2, -76.3, 37.2, -76.3, 'Scattered thunderstorms in advance of a frontal boundary produced gusty winds across portions of the Chesapeake Bay and Virginia Coastal Waters.', 'Wind gust of 49 knots was measured at York Spit.');
INSERT INTO public.stormevents_east VALUES (769654, 201808, 21, 2305, 201808, 22, 100, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 23:05:00', 'EST-5', '22-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'LAURYS', 2, 'ESE', 'LAURYS', 40.7088, -75.5209, 40.7081, -75.5241, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'A vehicle was trapped in flood waters at the intersection of Route 145 and Clearview Road in North Whitehall Township.');
INSERT INTO public.stormevents_east VALUES (769680, 201808, 21, 2305, 201808, 22, 100, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 23:05:00', 'EST-5', '22-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'FOGELSVILLE', 1, 'ENE', 'FOGELSVILLE', 40.5816, -75.6319, 40.5841, -75.621, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'A vehicle was trapped in two feet of water on the eastbound ramp of Interstate 78 from Route 100 in Fogelsville.');
INSERT INTO public.stormevents_east VALUES (769687, 201808, 21, 2255, 201808, 22, 100, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:55:00', 'EST-5', '22-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'BAUMSTOWN', 1, 'NNE', 'MONOCACY', 40.2737, -75.7777, 40.2671, -75.7651, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Flash flooding occurred along Monocacy Creek Road in Amity Township.');
INSERT INTO public.stormevents_east VALUES (769690, 201808, 21, 2255, 201808, 22, 100, 128312, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '21-AUG-18 22:55:00', 'EST-5', '22-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'SCHWENKSVILLE', 1, 'SE', 'SCHWENKSVILLE', 40.2599, -75.4706, 40.2639, -75.4587, 'Heavy rain caused flash flooding in parts of southeastern Pennsylvania and the Lehigh Valley on the night of August 21-22.  Some locations received up to 2.5 to 4.5 inches of rain.', 'Several roads in the Schwenksville area were closed due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (772771, 201808, 31, 530, 201808, 31, 700, 128859, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'PHI', '31-AUG-18 05:30:00', 'EST-5', '31-AUG-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'EWANSVILLE', 1, 'SSW', 'EWANSVILLE', 39.9707, -74.7289, 39.9707, -74.7346, 'Locally heavy rain produced flash flooding in parts of Burlington County on the morning of August 31.  Rainfall totals of 2.5 to 5.5 inches fell in a short amount of time.', 'Heavy rain produced flash flooding on Route 530 just east of Route 206 in Southampton Township.');
INSERT INTO public.stormevents_east VALUES (782946, 201808, 14, 1941, 201808, 14, 2300, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 19:41:00', 'EST-5', '14-AUG-18 23:00:00', 0, 0, 0, 0, '25.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'APALACHIN', 1, 'ENE', 'CAMPVILLE', 42.073, -76.163, 42.0847, -76.1331, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Water was flowing over multiple roadways in the Campville area.');
INSERT INTO public.stormevents_east VALUES (782947, 201808, 14, 1941, 201808, 14, 2300, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 19:41:00', 'EST-5', '14-AUG-18 23:00:00', 0, 0, 0, 0, '12.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'APALACHIN', 0, 'ESE', 'CAMPVILLE', 42.07, -76.17, 42.0785, -76.1418, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Portions of Route 434 were closed. Water washed out portions of the road and a culvert.');
INSERT INTO public.stormevents_east VALUES (782951, 201808, 14, 700, 201808, 14, 1300, 130513, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 07:00:00', 'EST-5', '14-AUG-18 13:00:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NEW ALBANY', 1, 'WNW', 'NEW ALBANY', 41.6015, -76.4533, 41.6039, -76.4398, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Many areas were flooded with evacuations of several homes taking place.');
INSERT INTO public.stormevents_east VALUES (782956, 201808, 14, 717, 201808, 14, 1300, 130513, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 07:17:00', 'EST-5', '14-AUG-18 13:00:00', 0, 0, 0, 0, '35.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'WILMOT', 1, 'S', 'WILMOT', 41.6, -76.32, 41.5867, -76.3217, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Many flooded roads and structures in the area. Evacuations were taking place.');
INSERT INTO public.stormevents_east VALUES (782957, 201808, 14, 720, 201808, 14, 1300, 130513, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 07:20:00', 'EST-5', '14-AUG-18 13:00:00', 0, 0, 0, 0, '35.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'TERRYTOWN', 1, 'ENE', 'WYALUSING', 41.6724, -76.282, 41.6765, -76.2434, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Many roads and structures were flooding in the area. Evacuations were taking place.');
INSERT INTO public.stormevents_east VALUES (782959, 201808, 14, 818, 201808, 14, 1400, 130513, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 08:18:00', 'EST-5', '14-AUG-18 14:00:00', 0, 0, 0, 0, '500.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LAWSVILLE CENTER', 2, 'SSW', 'FRANKLINS FORKS', 41.947, -75.8451, 41.8901, -75.8726, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Severe flash flooding occurred with numerous roads washed over, or washed out. Water surrounded three homes near Franklin Forks. Residents were trapped in the home. A garage was seen floating downstream.');
INSERT INTO public.stormevents_east VALUES (782961, 201808, 14, 2022, 201808, 14, 2345, 130513, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 20:22:00', 'EST-5', '14-AUG-18 23:45:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BROOKDALE', 1, 'NNE', 'LAWSVILLE CENTER', 41.96, -75.81, 41.9486, -75.8151, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'In Liberty Township, a family was trapped in a mobile home due to rising waters.');
INSERT INTO public.stormevents_east VALUES (779603, 201808, 11, 1800, 201808, 11, 1830, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 18:00:00', 'EST-5', '11-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'GLEN RIDGE', 1, 'ESE', 'GLEN RIDGE', 40.8152, -74.2185, 40.8148, -74.218, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Flash flooding inundated portions of the Montclair Film Festival at 505 Bloomfield Avenue in Montclair. Both the cinema and education center were damaged when the current forced open doors to the building.');
INSERT INTO public.stormevents_east VALUES (779610, 201808, 11, 830, 201808, 11, 900, 130194, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 08:30:00', 'EST-5', '11-AUG-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'BROAD CHANNEL', 2, 'NE', 'BROAD CHANNEL', 40.6406, -73.7427, 40.6401, -73.7433, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in isolated flash flooding in New York City. Rainfall amounts ranged from 1-3 inches across the city, with the majority of that rain falling in just a 1-2 hour time frame. The ASOS in Central Park recorded 2.90 inches of rain.', 'Flooding resulted in a water rescue at the intersection of Rockaway Boulevard and Brookville Boulevard in Rosedale, Queens.');
INSERT INTO public.stormevents_east VALUES (779619, 201808, 11, 941, 201808, 11, 1011, 130194, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 09:41:00', 'EST-5', '11-AUG-18 10:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'BROADWAY', 1, 'S', 'COLLEGE PT', 40.772, -73.8291, 40.7725, -73.8306, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in isolated flash flooding in New York City. Rainfall amounts ranged from 1-3 inches across the city, with the majority of that rain falling in just a 1-2 hour time frame. The ASOS in Central Park recorded 2.90 inches of rain.', 'Basements flooded due to heavy rain on 28th Road in Flushing, Queens.');
INSERT INTO public.stormevents_east VALUES (779809, 201808, 12, 558, 201808, 12, 630, 130227, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '12-AUG-18 05:58:00', 'EST-5', '12-AUG-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'MORICHES', 1, 'NW', 'CENTER MORICHES', 40.8054, -72.8107, 40.807, -72.7902, 'A weak disturbance just north of a stalled stationary boundary provided a focusing mechanism for heavy rainfall that resulted in isolated flash flooding across parts of Long Island. In an environment with precipitable water values around two inches, rainfall amounts ranged from 1-3 across much of Nassau and Suffolk counties. In Suffolk County, a CWOP station reported 2.79 of rain in Mastic Beach, while in Nassau County a 2.15 of rain was reported in North Bellmore via social media.', 'A basement on Frowein Road in Center Moriches was flooded.');
INSERT INTO public.stormevents_east VALUES (779813, 201808, 12, 600, 201808, 12, 630, 130227, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '12-AUG-18 06:00:00', 'EST-5', '12-AUG-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'QUIOGUE', 1, 'S', 'QUIOGUE', 40.8179, -72.6305, 40.8183, -72.6293, 'A weak disturbance just north of a stalled stationary boundary provided a focusing mechanism for heavy rainfall that resulted in isolated flash flooding across parts of Long Island. In an environment with precipitable water values around two inches, rainfall amounts ranged from 1-3 across much of Nassau and Suffolk counties. In Suffolk County, a CWOP station reported 2.79 of rain in Mastic Beach, while in Nassau County a 2.15 of rain was reported in North Bellmore via social media.', 'A basement was flooded on Main Street in Westhampton Beach due to heavy rain.');
INSERT INTO public.stormevents_east VALUES (748599, 201804, 15, 1407, 201804, 15, 1407, 124780, 'WEST VIRGINIA', 54, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 14:07:00', 'EST-5', '15-APR-18 14:07:00', 0, 0, 0, 0, '45.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'W', 'BELLEPOINT', 1, 'W', 'BELLEPOINT', 37.65, -80.89, 37.65, -80.89, 'A strong cold front with a negatively-tilted upper level trough approached southeast West Virginia.  Plenty of wind shear with modest instability made conditions ripe for damaging winds.  One thunderstorm would produce winds that caused damage in Summers County.', 'Thunderstorm winds blew over several trees and billboards.');
INSERT INTO public.stormevents_east VALUES (767176, 201808, 11, 1400, 201808, 11, 1900, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 14:00:00', 'EST-5', '11-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'WYDNOR', 1, 'NNE', 'FARMINGTON', 40.5808, -75.3932, 40.587, -75.3771, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Several roads were closed in Lower Saucon Township due to flash flooding and at least one water rescue took place.');
INSERT INTO public.stormevents_east VALUES (767177, 201808, 11, 1400, 201808, 11, 1900, 127601, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 14:00:00', 'EST-5', '11-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'LOCUST VLY', 1, 'NNW', 'LIMEPORT', 40.4964, -75.4064, 40.5377, -75.4574, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in southeastern Pennsylvania.  Additionally, severe thunderstorms impacted the area.', 'Widespread flash flooding was reported in Upper Saucon Township and Coopersburg due to the heavy rainfall.  Many roads were impassable.');
INSERT INTO public.stormevents_east VALUES (765100, 201808, 11, 1758, 201808, 11, 1758, 127605, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'PHI', '11-AUG-18 17:58:00', 'EST-5', '11-AUG-18 17:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SW', 'NARROWS', 1, 'SW', 'NARROWS', 38.96, -76.19, 38.96, -76.19, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 1 to 3 inches were reported in northeastern Maryland.  Additionally, severe thunderstorms impacted the area.', 'Social media photos of several large tree branches down at a residence near Grasonville. Time approximated from radar.');
INSERT INTO public.stormevents_east VALUES (765105, 201808, 11, 1920, 201808, 11, 1920, 127605, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'PHI', '11-AUG-18 19:20:00', 'EST-5', '11-AUG-18 19:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 56, 'MG', NULL, NULL, 0, 'N', 'TILGHMAN', 0, 'N', 'TILGHMAN', 38.72, -76.33, 38.72, -76.33, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 1 to 3 inches were reported in northeastern Maryland.  Additionally, severe thunderstorms impacted the area.', 'Wind gust of 65 mph reported at the Knapps Narrows Drawbridge MDDOT Gauge.');
INSERT INTO public.stormevents_east VALUES (767597, 201808, 11, 1935, 201808, 11, 2130, 127605, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 19:35:00', 'EST-5', '11-AUG-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'DENTON', 1, 'SSE', 'DENTON', 38.8703, -75.8325, 38.8732, -75.8168, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 1 to 3 inches were reported in northeastern Maryland.  Additionally, severe thunderstorms impacted the area.', 'Flash flooding occurred on Route 404 to the south of Denton.');
INSERT INTO public.stormevents_east VALUES (767599, 201808, 11, 2000, 201808, 11, 2200, 127605, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'PHI', '11-AUG-18 20:00:00', 'EST-5', '11-AUG-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'EASTON', 1, 'SW', 'EASTON ARPT', 38.784, -76.0854, 38.7886, -76.08, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 1 to 3 inches were reported in northeastern Maryland.  Additionally, severe thunderstorms impacted the area.', 'Seven people were rescued from a van that was trapped by flood waters on Commerce Drive in Easton.');
INSERT INTO public.stormevents_east VALUES (765130, 201808, 11, 1310, 201808, 11, 1310, 127607, 'NEW JERSEY', 34, 2018, 'August', 'Thunderstorm Wind', 'PHI', '11-AUG-18 13:10:00', 'EST-5', '11-AUG-18 13:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'NW', 'ALPHA', 1, 'NW', 'ALPHA', 40.68, -75.16, 40.68, -75.16, 'Several areas of flash flooding occurred due to heavy rain.  Rainfall totals of 2 to 5 inches were reported in northern New Jersey.  Additionally, severe thunderstorms impacted the area.', 'Trees and wires down on Lock Street near Logan Street. Damage likely due to a combination of strong thunderstorm winds and heavy rain. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (768182, 201808, 8, 1255, 201808, 8, 1259, 128103, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 12:55:00', 'EST-5', '08-AUG-18 12:59:00', 0, 0, 0, 0, '6.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NE', 'SUGAR GROVE', 2, 'ENE', 'SHAWSVILLE', 37.1366, -80.3099, 37.1779, -80.2369, 'A hot and humid air mass sparked scattered severe thunderstorms during the afternoon.  These storms blew down multiple trees and power lines in southwest Virginia.  Two homes suffered damage in the city of Danville due to a tree falling on each of them.', 'Thunderstorm winds blew down one tree that also took down a power line at the intersection of Georges Run Road and Mount Pleasant Road and a second tree along the 7600 block of Roanoke Road.');
INSERT INTO public.stormevents_east VALUES (768193, 201808, 8, 1335, 201808, 8, 1335, 128103, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 13:35:00', 'EST-5', '08-AUG-18 13:35:00', 0, 0, 0, 0, '6.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ESE', 'KENT', 2, 'ESE', 'KENT', 36.937, -80.9907, 36.937, -80.9907, 'A hot and humid air mass sparked scattered severe thunderstorms during the afternoon.  These storms blew down multiple trees and power lines in southwest Virginia.  Two homes suffered damage in the city of Danville due to a tree falling on each of them.', 'Thunderstorm winds blew down two trees and a power line on East Lee Highway.');
