INSERT INTO public.stormevents_east VALUES (768206, 201808, 8, 1442, 201808, 8, 1442, 128103, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '08-AUG-18 14:42:00', 'EST-5', '08-AUG-18 14:42:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'W', 'FLOYD', 3, 'W', 'FLOYD', 36.914, -80.3656, 36.914, -80.3656, 'A hot and humid air mass sparked scattered severe thunderstorms during the afternoon.  These storms blew down multiple trees and power lines in southwest Virginia.  Two homes suffered damage in the city of Danville due to a tree falling on each of them.', 'Thunderstorm winds blew down one tree at the intersection of Laurel Branch Road and Weddle Creek Road.');
