INSERT INTO public.stormevents_east VALUES (768433, 201808, 12, 1225, 201808, 12, 1225, 128143, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:25:00', 'EST-5', '12-AUG-18 12:25:00', 0, 0, 0, 0, '0.50K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SW', 'CHAMPION', 1, 'SW', 'CHAMPION', 36.1348, -81.3374, 36.1348, -81.3374, 'A closed upper level low combined with a passing cold front sparked a severe thunderstorm during the afternoon.  This storm blew down several trees in Wilkes County.', 'Thunderstorm winds blew down one tree along Champion Mount Pleasant Road.');
INSERT INTO public.stormevents_east VALUES (768441, 201808, 12, 1255, 201808, 12, 1255, 128143, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:55:00', 'EST-5', '12-AUG-18 12:55:00', 0, 0, 0, 0, '0.50K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'E', 'WILKESBORO', 2, 'E', 'WILKESBORO', 36.1517, -81.141, 36.1517, -81.141, 'A closed upper level low combined with a passing cold front sparked a severe thunderstorm during the afternoon.  This storm blew down several trees in Wilkes County.', 'Thunderstorm winds blew down one tree along Hays Street.');
