INSERT INTO public.stormevents_east VALUES (768461, 201808, 12, 1224, 201808, 12, 1224, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:24:00', 'EST-5', '12-AUG-18 12:24:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ESE', 'MOUNTAIN VIEW', 2, 'ESE', 'MOUNTAIN VIEW', 37.0915, -80.5955, 37.0915, -80.5955, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down one tree near the intersection of Claytor Dam Road and Wilderness Road.');
INSERT INTO public.stormevents_east VALUES (768471, 201808, 12, 1226, 201808, 12, 1226, 128145, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '12-AUG-18 12:26:00', 'EST-5', '12-AUG-18 12:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1, NULL, NULL, NULL, 1, 'E', 'WALTON', 1, 'E', 'WALTON', 37.1715, -80.5159, 37.1715, -80.5159, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Hail the size of quarters fell near the intersection of Prices Fork Road and Peppers Ferry Road.');
INSERT INTO public.stormevents_east VALUES (768476, 201808, 12, 1240, 201808, 12, 1240, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:40:00', 'EST-5', '12-AUG-18 12:40:00', 0, 0, 0, 0, '0.50K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NNW', 'DORA', 1, 'NNW', 'DORA', 37.0697, -80.7574, 37.0697, -80.7574, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down one tree at the entrance to the Pulaski Hospital.');
INSERT INTO public.stormevents_east VALUES (768488, 201808, 12, 1247, 201808, 12, 1247, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:47:00', 'EST-5', '12-AUG-18 12:47:00', 0, 0, 0, 0, '0.20K', NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'S', 'HOUCHINS', 1, 'S', 'HOUCHINS', 37.134, -80.3739, 37.134, -80.3739, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down large limbs near the intersection of Route 11 and Route 460 in Christiansburg.');
INSERT INTO public.stormevents_east VALUES (765396, 201808, 14, 1455, 201808, 14, 1455, 127639, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '14-AUG-18 14:55:00', 'EST-5', '14-AUG-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'EG', NULL, NULL, 3, 'N', 'PUNTA GORDA', 3, 'N', 'PUNTA GORDA', 26.94, -82.07, 26.94, -82.07, 'Scattered afternoon thunderstorms developing along the sea breeze slowly pushed towards the Gulf waters during the mid-afternoon. One storm produced multiple wind gusts across Charlotte Harbor.', 'A mesonet station on channel marker 4 along the Peace River and Charlotte Harbor measured a wind gust to 37 knots.');
INSERT INTO public.stormevents_east VALUES (771099, 201808, 27, 1553, 201808, 27, 1553, 128525, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TBW', '27-AUG-18 15:53:00', 'EST-5', '27-AUG-18 15:53:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Law Enforcement', 45, 'EG', NULL, NULL, 1, 'WNW', 'BAYSHORE ESTATES', 1, 'WNW', 'BAYSHORE ESTATES', 27.0841, -82.4392, 27.0841, -82.4392, 'Easterly flow and deep moisture allowed for scattered thunderstorms to develop across the Florida Peninsula during the afternoon, pushing west through the early evening. One of these storms produced damaging wind gusts as they neared the Gulf Coast. Another storm produced hail to the size of pennies.', 'A mobile home sustained roof damage from thunderstorm wind gusts in Venice. Another three mobile homes sustained minor damage nearby at the Lake Village Mobile Home Park in Casey Key.');
INSERT INTO public.stormevents_east VALUES (771100, 201808, 27, 1654, 201808, 27, 1657, 128525, 'FLORIDA', 12, 2018, 'August', 'Hail', 'TBW', '27-AUG-18 16:54:00', 'EST-5', '27-AUG-18 16:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 3, 'SSE', 'PALMA SOLA', 3, 'SSE', 'PALMA SOLA', 27.4615, -82.6184, 27.4615, -82.6184, 'Easterly flow and deep moisture allowed for scattered thunderstorms to develop across the Florida Peninsula during the afternoon, pushing west through the early evening. One of these storms produced damaging wind gusts as they neared the Gulf Coast. Another storm produced hail to the size of pennies.', 'A trained spotter reported penny size hail in Bradenton.');
INSERT INTO public.stormevents_east VALUES (771270, 201808, 31, 1550, 201808, 31, 1550, 128566, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '31-AUG-18 15:50:00', 'EST-5', '31-AUG-18 15:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'EG', NULL, NULL, 2, 'W', 'MIDDLE TAMPA BAY', 2, 'W', 'MIDDLE TAMPA BAY', 27.77, -82.57, 27.77, -82.57, 'Afternoon storms produce gusty winds across Tampa Bay.', 'A WeatherFlow station at Cut J in the middle of the Tampa Bay recorded a wind gust of 40 knots...46 mph.');
INSERT INTO public.stormevents_east VALUES (774294, 201808, 12, 624, 201808, 12, 624, 129205, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'RLX', '12-AUG-18 06:24:00', 'EST-5', '12-AUG-18 06:24:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'E', 'ELANA', 1, 'E', 'ELANA', 38.62, -81.11, 38.62, -81.11, 'A surface cold front and upper-level low pressure system brought showers and thunderstorms to central West Virginia on the morning of the 12th.  The strongest storms resulted in isolated wind damage and flash flooding.', 'Twenty homeowners lost power due to a tree falling on power lines near the town of Elana.');
INSERT INTO public.stormevents_east VALUES (774291, 201808, 12, 635, 201808, 12, 910, 129205, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '12-AUG-18 06:35:00', 'EST-5', '12-AUG-18 09:10:00', 0, 0, 0, 0, '30.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'OTTO', 0, 'ESE', 'SPEED', 38.7679, -81.2263, 38.7274, -81.3635, 'A surface cold front and upper-level low pressure system brought showers and thunderstorms to central West Virginia on the morning of the 12th.  The strongest storms resulted in isolated wind damage and flash flooding.', 'Heavy rain created high water issues in the area, including 242 Edgle Fork Road near Clover and in Graux where vehicles were submerged with water to the top of their wheels.');
INSERT INTO public.stormevents_east VALUES (774296, 201808, 12, 830, 201808, 12, 830, 129205, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'RLX', '12-AUG-18 08:30:00', 'EST-5', '12-AUG-18 08:30:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NW', 'CLOVER', 3, 'NW', 'CLOVER', 38.75, -81.28, 38.75, -81.28, 'A surface cold front and upper-level low pressure system brought showers and thunderstorms to central West Virginia on the morning of the 12th.  The strongest storms resulted in isolated wind damage and flash flooding.', 'A combination of flooding and strong winds associated with a passing thunderstorm caused multiple trees and a power line to fall down on Otto Road near Graux.');
INSERT INTO public.stormevents_east VALUES (781345, 201808, 1, 1345, 201808, 1, 1345, 130517, 'CONNECTICUT', 9, 2018, 'August', 'Lightning', 'OKX', '01-AUG-18 13:45:00', 'EST-5', '01-AUG-18 13:45:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Newspaper', NULL, NULL, NULL, NULL, 1, 'WSW', 'RIDGEFIELD', 1, 'WSW', 'RIDGEFIELD', 41.27, -73.52, 41.27, -73.52, 'A stationary boundary lifts northeast as a warm front triggering severe thunderstorms across Southwest Connecticut.', 'Lightning strikes a home on Old South Salem Road.');
INSERT INTO public.stormevents_east VALUES (779952, 201808, 6, 1421, 201808, 6, 1421, 130270, 'MICHIGAN', 26, 2018, 'August', 'Thunderstorm Wind', 'DTX', '06-AUG-18 14:21:00', 'EST-5', '06-AUG-18 14:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SE', 'HARPER WOODS', 1, 'SE', 'HARPER WOODS', 42.39, -82.9, 42.39, -82.9, 'A brief weak tornado developed near Croswell in Sanilac County, with trees reported down across far eastern Wayne County.', 'A tree was blown down at Grosse Pointe Public Library.');
INSERT INTO public.stormevents_east VALUES (779954, 201808, 6, 1812, 201808, 6, 1813, 130270, 'MICHIGAN', 26, 2018, 'August', 'Tornado', 'DTX', '06-AUG-18 18:12:00', 'EST-5', '06-AUG-18 18:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'NNE', 'CROSWELL PECK ARPK', 2, 'NNE', 'CROSWELL PECK ARPK', 43.276, -82.692, 43.278, -82.69, 'A brief weak tornado developed near Croswell in Sanilac County, with trees reported down across far eastern Wayne County.', 'A video indicated a brief tornado, but not damage reported.');
INSERT INTO public.stormevents_east VALUES (779959, 201808, 6, 1423, 201808, 6, 1423, 130270, 'MICHIGAN', 26, 2018, 'August', 'Thunderstorm Wind', 'DTX', '06-AUG-18 14:23:00', 'EST-5', '06-AUG-18 14:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 1, 'N', 'GROSSE PT PARK', 1, 'N', 'GROSSE PT PARK', 42.38, -82.92, 42.38, -82.92, 'A brief weak tornado developed near Croswell in Sanilac County, with trees reported down across far eastern Wayne County.', 'Trees were reported down, one on a car.');
INSERT INTO public.stormevents_east VALUES (748620, 201804, 15, 1805, 201804, 15, 1805, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 18:05:00', 'EST-5', '15-APR-18 18:05:00', 0, 0, 0, 0, '0.50K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'W', 'PHENIX', 2, 'W', 'PHENIX', 37.0756, -78.7784, 37.0756, -78.7784, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'Thunderstorm winds blew down one tree along the Patrick Henry Highway.');
INSERT INTO public.stormevents_east VALUES (781372, 201808, 1, 1354, 201808, 1, 1354, 130517, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'OKX', '01-AUG-18 13:54:00', 'EST-5', '01-AUG-18 13:54:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Newspaper', 61, 'EG', NULL, NULL, 1, 'S', 'RIDGEFIELD', 1, 'S', 'RIDGEFIELD', 41.27, -73.5, 41.27, -73.5, 'A stationary boundary lifts northeast as a warm front triggering severe thunderstorms across Southwest Connecticut.', 'Large branches and utility poles down on the western side of Ridgefield...including on North Salem Road and West Lane.');
INSERT INTO public.stormevents_east VALUES (781374, 201808, 1, 1408, 201808, 1, 1408, 130517, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'OKX', '01-AUG-18 14:08:00', 'EST-5', '01-AUG-18 14:08:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 2, 'NNW', 'WESTON', 2, 'NNW', 'WESTON', 41.23, -73.39, 41.23, -73.39, 'A stationary boundary lifts northeast as a warm front triggering severe thunderstorms across Southwest Connecticut.', 'Trees and wires down on Godfrey Road West just west of Pinefield Lane.');
INSERT INTO public.stormevents_east VALUES (781545, 201808, 3, 1347, 201808, 3, 1347, 130560, 'NEW JERSEY', 34, 2018, 'August', 'Lightning', 'OKX', '03-AUG-18 13:47:00', 'EST-5', '03-AUG-18 13:47:00', 0, 0, 0, 0, '250.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'N', 'RAMSEY', 1, 'N', 'RAMSEY', 41.06, -74.15, 41.06, -74.15, 'A weak surface trough of low pressure along with an upper level trough approaches from the west to bring severe thunderstorms to the region.', 'Two alarm fire caused by lightning strike on Davidson Avenue.');
INSERT INTO public.stormevents_east VALUES (781546, 201808, 3, 1334, 201808, 3, 1334, 130560, 'NEW JERSEY', 34, 2018, 'August', 'Thunderstorm Wind', 'OKX', '03-AUG-18 13:34:00', 'EST-5', '03-AUG-18 13:34:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'E', 'CRANFORD', 1, 'E', 'CRANFORD', 40.67, -74.31, 40.67, -74.31, 'A weak surface trough of low pressure along with an upper level trough approaches from the west to bring severe thunderstorms to the region.', 'Large tree branches reported down.');
INSERT INTO public.stormevents_east VALUES (781547, 201808, 3, 1347, 201808, 3, 1347, 130560, 'NEW JERSEY', 34, 2018, 'August', 'Thunderstorm Wind', 'OKX', '03-AUG-18 13:47:00', 'EST-5', '03-AUG-18 13:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 1, 'N', 'GLEN ROCK', 1, 'N', 'GLEN ROCK', 40.964, -74.1314, 40.964, -74.1314, 'A weak surface trough of low pressure along with an upper level trough approaches from the west to bring severe thunderstorms to the region.', 'A tree down on house on Austin Place.');
INSERT INTO public.stormevents_east VALUES (781550, 201808, 7, 1730, 201808, 7, 1730, 130561, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '07-AUG-18 17:30:00', 'EST-5', '07-AUG-18 17:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 2, 'WNW', 'RYE', 2, 'WNW', 'RYE', 40.99, -73.71, 40.99, -73.71, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'Power lines down on North Street in Harrison.');
INSERT INTO public.stormevents_east VALUES (781551, 201808, 7, 1825, 201808, 7, 1825, 130561, 'NEW YORK', 36, 2018, 'August', 'Lightning', 'OKX', '07-AUG-18 18:25:00', 'EST-5', '07-AUG-18 18:25:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'NW', 'ST ALBANS', 1, 'NW', 'ST ALBANS', 40.71, -73.79, 40.71, -73.79, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'Person struck by lightning near the corner of 155 St and Baisley Blvd.');
INSERT INTO public.stormevents_east VALUES (781732, 201808, 17, 2056, 201808, 17, 2056, 130609, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'OKX', '17-AUG-18 20:56:00', 'EST-5', '17-AUG-18 20:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 55, 'NNW', 'STATION 44025', 55, 'NNW', 'STATION 44025', 40.9181, -73.7312, 40.9181, -73.7312, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Marine thunderstorm wind gust of 36 knots.');
INSERT INTO public.stormevents_east VALUES (781561, 201808, 7, 1806, 201808, 7, 1806, 130565, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'OKX', '07-AUG-18 18:06:00', 'EST-5', '07-AUG-18 18:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'EATONS NECK WXFLOW', 0, 'N', 'EATONS NECK WXFLOW', 40.95, -73.4, 40.95, -73.4, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'A marine thunderstorm wind gust of 34 knots.');
INSERT INTO public.stormevents_east VALUES (781558, 201808, 7, 1950, 201808, 7, 1950, 130565, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'OKX', '07-AUG-18 19:50:00', 'EST-5', '07-AUG-18 19:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 4, 'WNW', 'SMITH POINT', 4, 'WNW', 'SMITH POINT', 40.751, -72.94, 40.751, -72.94, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'Marine Thunderstorm wind gust of 39 knots.');
INSERT INTO public.stormevents_east VALUES (781844, 201808, 17, 1930, 201808, 17, 2130, 130618, 'MASSACHUSETTS', 25, 2018, 'August', 'Flash Flood', 'ALY', '17-AUG-18 19:30:00', 'EST-5', '17-AUG-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'STEVENS CORNER', 1, 'WSW', 'STEVENS CORNER', 42.3959, -73.3522, 42.3962, -73.3525, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong thunderstorms to the region during the evening hours of Friday, August 17th. As a result of these disturbances, flash flooding occurred in Berkshire county, MA.  Rainfall from the event ranged from 2 to 3 inches.', 'Summit Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (781998, 201808, 2, 1434, 201808, 2, 1434, 130653, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '02-AUG-18 14:34:00', 'EST-5', '02-AUG-18 14:34:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'N', 'GOLDSTON', 4, 'N', 'GOLDSTON', 35.65, -79.32, 35.65, -79.32, 'Heavy rain showers and thunderstorms developed over central NC in association with a series of disturbances moving through the long wave trough aloft. Deep moist advection and unidirectional flow through the atmosphere resulted in training of heavy rain and thunderstorms. Saturated antecedent conditions contributed to the flash flooding that occurred as a result of the training storms. A cluster of storms became severe during the afternoon, resulting in sporadic downed trees and power lines while other marginally severe storms resulted in numerous downed trees and power lines due to saturated ground.', 'One tree was blown down near the intersection of NC-902 and Meronies Church Road.');
INSERT INTO public.stormevents_east VALUES (748589, 201804, 15, 1651, 201804, 15, 1653, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 16:51:00', 'EST-5', '15-APR-18 16:53:00', 0, 0, 0, 0, '100.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WNW', 'PELHAM', 3, 'NNW', 'PELHAM', 36.509, -79.51, 36.5408, -79.4931, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'A tornado touched down in Caswell County west of Pelham near Dusty Lane at 4:51 PM EST.  It snapped numerous trees and damaged several outbuildings.  By 4:53 PM EST, the tornado exited Caswell County and continued northward into Pittsylvania County of Virginia.  It would later cross through the independent city of Danville and back into Pittsylvania County before lifting about two miles southwest of Dry Fork by 5:10 PM EST.');
INSERT INTO public.stormevents_east VALUES (759262, 201805, 4, 2106, 201805, 4, 2110, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 21:06:00', 'EST-5', '04-MAY-18 21:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'W', 'EAST DEERING', 1, 'W', 'EAST DEERING', 43.07, -71.84, 43.07, -71.84, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed power lines on Deering Center Road in East Deering.');
INSERT INTO public.stormevents_east VALUES (759273, 201805, 4, 2144, 201805, 4, 2148, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 21:44:00', 'EST-5', '04-MAY-18 21:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 54, 'MG', NULL, NULL, 1, 'E', 'NEWINGTON STATION', 1, 'E', 'NEWINGTON STATION', 43.12, -70.82, 43.12, -70.82, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'Mesonet Station NHLBY in Newington recorded a 54 kt gust in a severe thunderstorm.');
INSERT INTO public.stormevents_east VALUES (767889, 201808, 2, 1700, 201808, 2, 1700, 128029, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '02-AUG-18 17:00:00', 'EST-5', '02-AUG-18 17:00:00', 0, 0, 0, 0, '6.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'TIMBERLAKE', 1, 'SW', 'TIMBERLAKE', 37.3181, -79.2602, 37.3181, -79.2602, 'A complex, broken line of thunderstorms developed during the afternoon ahead of an approaching cold front producing very heavy rainfall and some embedded severe storms. Trees were blown trees onto power lines, which caused a number of power outages.  Henry County and the city of Martinsville suffered the most tree damage and power outages. Rainfall was extremely intense within the very moist environment with precipitable water over 2 inches and several boundary collisions enhancing the rainfall. The highest amounts occurred in the City of Lynchburg and adjacent parts of Campbell County where radar estimated 4 to 6 inches of rain in several hours which was confirmed by several rain gages.', 'Thunderstorm winds blew down two trees on to power lines in the Windcrest Manor area along Timberlake Drive.');
INSERT INTO public.stormevents_east VALUES (774903, 201807, 22, 1455, 201807, 22, 1700, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 14:55:00', 'EST-5', '22-JUL-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BOWENS', 1, 'W', 'BOWENS', 38.5033, -76.6431, 38.5032, -76.6427, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Sixes Road was flooded and closed south of Hallowing Point Road.');
INSERT INTO public.stormevents_east VALUES (774898, 201807, 22, 1441, 201807, 22, 1600, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 14:41:00', 'EST-5', '22-JUL-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'RANDLE CLIFF BEACH', 0, 'S', 'RANDLE CLIFF BEACH', 38.6654, -76.5311, 38.6655, -76.5307, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Maryland Route 261 was flooded and closed near Randle Cliff Beach.');
INSERT INTO public.stormevents_east VALUES (781725, 201808, 3, 1124, 201808, 3, 1132, 130180, 'NEW YORK', 36, 2018, 'August', 'Tornado', 'ALY', '03-AUG-18 11:24:00', 'EST-5', '03-AUG-18 11:32:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'NNW', 'HALCOTT CENTER', 3, 'N', 'HALCOTT CENTER', 42.216, -74.503, 42.229, -74.471, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'A tornado touched down at 12:24 PM EDT on August 3,|2018 over southwest Greene County in eastern New York and |continued 1.9 miles on the ground to the northeast for 8 minutes,|ending at 12:32 PM EDT. This weak tornado was approximately 200 |feet wide and contained estimated maximum winds of 75 mph. The |tornado was rated EF-0. Many trees were snapped and uprooted |along the path of this tornado. There was no observed structural |damage associated with this tornado.');
INSERT INTO public.stormevents_east VALUES (781818, 201808, 17, 2050, 201808, 17, 2112, 130616, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '17-AUG-18 20:50:00', 'EST-5', '17-AUG-18 21:12:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'N', 'WAPPINGERS FALLS', 1, 'N', 'WAPPINGERS FALLS', 41.62, -73.92, 41.62, -73.92, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Storm resulted in 1.21 inches of rainfall in 20 minutes.');
INSERT INTO public.stormevents_east VALUES (781819, 201808, 17, 1515, 201808, 17, 1515, 130616, 'NEW YORK', 36, 2018, 'August', 'Lightning', 'ALY', '17-AUG-18 15:15:00', 'EST-5', '17-AUG-18 15:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NE', 'OHIO', 1, 'NE', 'OHIO', 43.33, -74.96, 43.33, -74.96, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'A home was struck by lightning and the fire department was dispatched.');
INSERT INTO public.stormevents_east VALUES (781820, 201808, 17, 1822, 201808, 17, 1822, 130616, 'NEW YORK', 36, 2018, 'August', 'Lightning', 'ALY', '17-AUG-18 18:22:00', 'EST-5', '17-AUG-18 18:22:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'E', 'SARATOGA SPGS', 1, 'E', 'SARATOGA SPGS', 43.08, -73.78, 43.08, -73.78, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Lightning caused a fire in the attic of City Hall. This resulted in a section of Broadway being closed. The time was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (781821, 201808, 17, 1447, 201808, 17, 1447, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 14:47:00', 'EST-5', '17-AUG-18 14:47:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'RUSSIA', 1, 'S', 'RUSSIA', 43.26, -75.08, 43.26, -75.08, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees and wires downed on Russia Road.');
INSERT INTO public.stormevents_east VALUES (769034, 201807, 16, 1518, 201807, 16, 1518, 128217, 'NEW YORK', 36, 2018, 'July', 'Thunderstorm Wind', 'ALY', '16-JUL-18 15:18:00', 'EST-5', '16-JUL-18 15:18:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 0, 'SE', 'MARBLETOWN', 0, 'SE', 'MARBLETOWN', 41.8761, -74.1147, 41.8761, -74.1147, 'It was hot and humid on July 16th as temperatures soared into the low to mid-90s with dewpoints in the upper 60s to low 70s in the Hudson and Mohawk Valleys. This resulted in heat indices reaching the mid to upper 90s. Isolated, slow-moving thunderstorms developed during the afternoon in the hot air, one of which resulted in wind damage and flash flooding in Ulster County.', 'A tree was downed on wires on Marcott Road.');
INSERT INTO public.stormevents_east VALUES (774906, 201807, 22, 1509, 201807, 22, 1600, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 15:09:00', 'EST-5', '22-JUL-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'HUNTERVILLE', 1, 'SSW', 'HUNTERVILLE', 38.4542, -76.7433, 38.4542, -76.7426, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Lockes Hill Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (767411, 201808, 2, 1610, 201808, 2, 1614, 127943, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '02-AUG-18 16:10:00', 'EST-5', '02-AUG-18 16:14:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'ENE', 'LITTLE MTN', 3, 'ENE', 'LITTLE MTN', 34.21, -81.37, 34.21, -81.37, 'A moist southerly flow provided scattered to numerous thunderstorms across the region, an isolated one reached severe limits.', 'SCHP reported tree in roadway on Interstate 26 eastbound at mile marker 88.');
INSERT INTO public.stormevents_east VALUES (767413, 201808, 2, 1611, 201808, 2, 1615, 127943, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '02-AUG-18 16:11:00', 'EST-5', '02-AUG-18 16:15:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'E', 'LITTLE MTN', 3, 'E', 'LITTLE MTN', 34.2, -81.37, 34.2, -81.37, 'A moist southerly flow provided scattered to numerous thunderstorms across the region, an isolated one reached severe limits.', 'Tree down on Beagle Run Rd.  Time estimated.');
INSERT INTO public.stormevents_east VALUES (767480, 201808, 8, 1936, 201808, 8, 1940, 127956, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '08-AUG-18 19:36:00', 'EST-5', '08-AUG-18 19:40:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'ESE', 'NEWBERRY ARPT', 1, 'ESE', 'NEWBERRY ARPT', 34.31, -81.61, 34.31, -81.61, 'An upper level disturbance and surface trough contributed to a band of scattered thunderstorms developing and moving through the region in the evening, some of which reached severe limits.', 'Trees down on Sunset Ave near Mayes Ave, blocking the roadway.');
INSERT INTO public.stormevents_east VALUES (782004, 201808, 2, 845, 201808, 2, 845, 130653, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '02-AUG-18 08:45:00', 'EST-5', '02-AUG-18 08:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'WELCOME', 0, 'SSE', 'WELCOME', 35.9231, -80.2679, 35.9155, -80.2686, 'Heavy rain showers and thunderstorms developed over central NC in association with a series of disturbances moving through the long wave trough aloft. Deep moist advection and unidirectional flow through the atmosphere resulted in training of heavy rain and thunderstorms. Saturated antecedent conditions contributed to the flash flooding that occurred as a result of the training storms. A cluster of storms became severe during the afternoon, resulting in sporadic downed trees and power lines while other marginally severe storms resulted in numerous downed trees and power lines due to saturated ground.', 'Kepley Craver Avenue near Welcome was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (773781, 201808, 1, 200, 201808, 1, 700, 127983, 'MICHIGAN', 26, 2018, 'August', 'Flood', 'DTX', '01-AUG-18 02:00:00', 'EST-5', '01-AUG-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', '(DET)DETROIT CITY AR', 1, 'NE', 'LIVONIA', 42.42, -83.02, 42.394, -83.351, 'After an abnormally dry July across lower Michigan, a low pressure system lifted up from the Ohio Valley and moved through  extreme southeastern Michigan and brought some much needed rainfall. Showers on the afternoon and evening of July 31 and became heavier into the nighttime hours. As the center of the low pressure interacted with the marine layer over western Lake Erie shortly after midnight, a brief tornado formed over Wayne County despite relatively weak winds aloft. Heavy rain bands and thunderstorm activity resulted in rainfall totals near 4 inches in several locations while many more areas around the Metro Detroit area received 1-3 inches, prompting a Flash Flood Warning for the urban areas as most of the rainfall occurred over a period of 3 hours or less. A couple feet of water were reported over roadways in Dearborn Heights and Taylor during the early morning hours.', NULL);
INSERT INTO public.stormevents_east VALUES (779955, 201808, 6, 1415, 201808, 6, 1415, 130271, 'LAKE ST CLAIR', 81, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '06-AUG-18 14:15:00', 'EST-5', '06-AUG-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 40, 'MG', NULL, NULL, 30, 'SW', 'ALGONAC', 30, 'SW', 'ALGONAC', 42.3351, -82.9851, 42.3351, -82.9851, 'Thunderstorms moving through the Lake St. Clair and the Detroit River produced wind gusts of 40 to 70 mph.', NULL);
INSERT INTO public.stormevents_east VALUES (779957, 201808, 6, 1418, 201808, 6, 1418, 130271, 'LAKE ST CLAIR', 81, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '06-AUG-18 14:18:00', 'EST-5', '06-AUG-18 14:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 49, 'MG', NULL, NULL, 8, 'NNE', 'BELLE ISLE', 8, 'NNE', 'BELLE ISLE', 42.3552, -82.9522, 42.3552, -82.9522, 'Thunderstorms moving through the Lake St. Clair and the Detroit River produced wind gusts of 40 to 70 mph.', NULL);
INSERT INTO public.stormevents_east VALUES (779962, 201808, 6, 1424, 201808, 6, 1424, 130271, 'LAKE ST CLAIR', 81, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '06-AUG-18 14:24:00', 'EST-5', '06-AUG-18 14:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 59, 'MG', NULL, NULL, 1, 'S', 'GROSSE POINTE', 1, 'S', 'GROSSE POINTE', 42.3604, -82.9069, 42.3604, -82.9069, 'Thunderstorms moving through the Lake St. Clair and the Detroit River produced wind gusts of 40 to 70 mph.', NULL);
INSERT INTO public.stormevents_east VALUES (777912, 201808, 29, 1418, 201808, 29, 1418, 129859, 'LAKE ERIE', 95, 2018, 'August', 'Marine Thunderstorm Wind', 'CLE', '29-AUG-18 14:18:00', 'EST-5', '29-AUG-18 14:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 37, 'MG', NULL, NULL, 11, 'SW', 'WILLOWICK', 11, 'SW', 'WILLOWICK', 41.5212, -81.6747, 41.5212, -81.6747, 'A cold front moved across northern Ohio during the afternoon of August 29th. A line of showers and thunderstorms developed along the front and produced strong winds on Lake Erie.', 'A 37 knots thunderstorm wind gust was measured by an automated sensor at Burke Lakefront Airport.');
INSERT INTO public.stormevents_east VALUES (777909, 201808, 6, 2340, 201808, 6, 2340, 129757, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'CLE', '06-AUG-18 23:40:00', 'EST-5', '06-AUG-18 23:40:00', 0, 0, 0, 0, '7.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 2, 'ENE', 'HENRIETTA', 2, 'ENE', 'HENRIETTA', 41.3428, -82.2745, 41.3428, -82.2745, 'A couple of strong thunderstorms developed in Northeast Ohio early in the evening of August 6th.  A couple reports of damage were received in the Cleveland area.  Late in the evening a line of thunderstorms developed in advance of an approaching cold front.  The line moved across northern Ohio causing some damage along the central lake shore.', 'Thunderstorm winds downed several trees along Baumhart Road south of State Route 113.  Power outages were reported in the area.');
INSERT INTO public.stormevents_east VALUES (779856, 201808, 2, 1830, 201808, 2, 2130, 130234, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'GSP', '02-AUG-18 18:30:00', 'EST-5', '02-AUG-18 21:30:00', 0, 0, 0, 0, '30.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'TURNERSBURG', 3, 'SSE', 'TURNERSBURG', 35.865, -80.818, 35.864, -80.8, 'Widespread heavy rain showers and embedded thunderstorms developed across the North Carolina Piedmont during the afternoon and evening. Flash flooding developed in the Statesville area after 2.5 to 4 inches of rain fell in just a couple of hours.', 'County comms and others reported flash flooding developed on the east side of Statesville and adjacent areas after 2.5 to 4 inches of rain fell across a large area, mostly within a couple of hours. There were multiple reports of creeks and small streams overflowing their banks and flooding roads, with Beaver Creek and its tributaries being the especially problematic. One to two feet of water from a tributary was flowing over Old Mocksville Rd near Davis Regional Med Center. A retaining pond on Beaver Creek near Old Mocksville Rd was spilling over the dam. Part of Old Mocksville Rd was washed away near Moore Ridge Rd due to flooding along Fifth Creek. Urban flooding was also reported, with water entering basements on Broad St. Finally, dozens of campers were trapped by flood water at a campground on Log Rd southeast of Statesville when tributaries of Third Creek washed out part of the road.');
INSERT INTO public.stormevents_east VALUES (779875, 201808, 7, 1629, 201808, 7, 1629, 130250, 'SOUTH CAROLINA', 45, 2018, 'August', 'Hail', 'GSP', '07-AUG-18 16:29:00', 'EST-5', '07-AUG-18 16:29:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.75, NULL, NULL, NULL, 1, 'E', 'WALHALLA', 1, 'E', 'WALHALLA', 34.77, -83.06, 34.77, -83.06, 'Isolated thunderstorms developed near the Blue Ridge escarpment during the afternoon and moved southeast. One storm produced brief hail and damaging winds in Oconee County.', 'Public reported (via Social Media) penny size hail in the Walhalla area.');
INSERT INTO public.stormevents_east VALUES (779878, 201808, 7, 1705, 201808, 7, 1705, 130250, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '07-AUG-18 17:05:00', 'EST-5', '07-AUG-18 17:05:00', 0, 0, 0, 0, '20.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'KEOWEE', 2, 'ENE', 'NEWRY', 34.707, -82.89, 34.725, -82.87, 'Isolated thunderstorms developed near the Blue Ridge escarpment during the afternoon and moved southeast. One storm produced brief hail and damaging winds in Oconee County.', 'County comms reported a tree blown down on a home on Chippewa Ct and multiple trees and power lines down with an additional tree on a home on North Bayshore Dr.');
INSERT INTO public.stormevents_east VALUES (779883, 201808, 7, 2053, 201808, 7, 2059, 130251, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '07-AUG-18 20:53:00', 'EST-5', '07-AUG-18 20:59:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNW', 'WILGROVE', 2, 'NE', 'MINT HILL', 35.243, -80.693, 35.195, -80.644, 'An isolated thunderstorm developed over the Charlotte area during the evening and moved southeast, producing brief wind damage in southeast Mecklenburg County.', 'County comms and the public reported multiple trees blown in the Mint Hill area, including along Robinson Church Rd and Harrisburg Rd.');
INSERT INTO public.stormevents_east VALUES (777902, 201808, 6, 1610, 201808, 6, 1610, 129757, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'CLE', '06-AUG-18 16:10:00', 'EST-5', '06-AUG-18 16:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'HUNTING VLY', 0, 'N', 'HUNTING VLY', 41.47, -81.42, 41.47, -81.42, 'A couple of strong thunderstorms developed in Northeast Ohio early in the evening of August 6th.  A couple reports of damage were received in the Cleveland area.  Late in the evening a line of thunderstorms developed in advance of an approaching cold front.  The line moved across northern Ohio causing some damage along the central lake shore.', 'Thunderstorm winds downed a tree.');
INSERT INTO public.stormevents_east VALUES (777905, 201808, 6, 2256, 201808, 6, 2256, 129757, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'CLE', '06-AUG-18 22:56:00', 'EST-5', '06-AUG-18 22:56:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'BROOK PARK', 0, 'N', 'BROOK PARK', 41.4, -81.85, 41.4, -81.85, 'A couple of strong thunderstorms developed in Northeast Ohio early in the evening of August 6th.  A couple reports of damage were received in the Cleveland area.  Late in the evening a line of thunderstorms developed in advance of an approaching cold front.  The line moved across northern Ohio causing some damage along the central lake shore.', 'Thunderstorm winds downed at least three trees and some power lines.');
INSERT INTO public.stormevents_east VALUES (777906, 201808, 6, 2250, 201808, 6, 2250, 129757, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'CLE', '06-AUG-18 22:50:00', 'EST-5', '06-AUG-18 22:50:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 2, 'W', 'LINNDALE', 2, 'W', 'LINNDALE', 41.4532, -81.7793, 41.4532, -81.7793, 'A couple of strong thunderstorms developed in Northeast Ohio early in the evening of August 6th.  A couple reports of damage were received in the Cleveland area.  Late in the evening a line of thunderstorms developed in advance of an approaching cold front.  The line moved across northern Ohio causing some damage along the central lake shore.', 'Thunderstorm winds downed a couple trees near West 130th Street.');
INSERT INTO public.stormevents_east VALUES (777907, 201808, 7, 1130, 201808, 7, 1130, 129757, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'CLE', '07-AUG-18 11:30:00', 'EST-5', '07-AUG-18 11:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'BAY VLG', 0, 'N', 'BAY VLG', 41.48, -81.9, 41.48, -81.9, 'A couple of strong thunderstorms developed in Northeast Ohio early in the evening of August 6th.  A couple reports of damage were received in the Cleveland area.  Late in the evening a line of thunderstorms developed in advance of an approaching cold front.  The line moved across northern Ohio causing some damage along the central lake shore.', 'Thunderstorm winds downed several large limbs and one tree.  Most of the damage was along Clague Road.');
INSERT INTO public.stormevents_east VALUES (781705, 201808, 17, 1815, 201808, 17, 1815, 130600, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '17-AUG-18 18:15:00', 'EST-5', '17-AUG-18 18:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'E', 'HAWTHORNE', 1, 'E', 'HAWTHORNE', 41.1, -73.79, 41.1, -73.79, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Trees and branches and wires down at Commerce Street and Elwood Avenue.');
INSERT INTO public.stormevents_east VALUES (781718, 201808, 17, 1820, 201808, 17, 1820, 130600, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '17-AUG-18 18:20:00', 'EST-5', '17-AUG-18 18:20:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Law Enforcement', 61, 'EG', NULL, NULL, 2, 'WNW', 'BANKSVILLE', 2, 'WNW', 'BANKSVILLE', 41.14, -73.68, 41.14, -73.68, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Very many reports of trees and wires down across town.');
INSERT INTO public.stormevents_east VALUES (781566, 201808, 8, 1723, 201808, 8, 1723, 130568, 'CONNECTICUT', 9, 2018, 'August', 'Thunderstorm Wind', 'OKX', '08-AUG-18 17:23:00', 'EST-5', '08-AUG-18 17:23:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'N', 'ROCKY GLEN', 1, 'N', 'ROCKY GLEN', 41.44, -73.27, 41.44, -73.27, 'A surface trough in a very warm and humid airmass triggered thunderstorms across the region.', 'A tree down on Walnut Tree Road in Newtown, CT.');
INSERT INTO public.stormevents_east VALUES (781579, 201808, 18, 1748, 201808, 18, 1748, 130573, 'NEW YORK', 36, 2018, 'August', 'Lightning', 'OKX', '18-AUG-18 17:48:00', 'EST-5', '18-AUG-18 17:48:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'E', 'LAKE RONKONKOMA', 1, 'E', 'LAKE RONKONKOMA', 40.83, -73.1, 40.83, -73.1, 'A cold front along with an upper level disturbance trigged thunderstorms across the southeastern New York.', 'Wires down at Portion Road and Patchogue-Holbrook Road.');
INSERT INTO public.stormevents_east VALUES (781689, 201808, 17, 1638, 201808, 17, 1638, 130600, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '17-AUG-18 16:38:00', 'EST-5', '17-AUG-18 16:38:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 1, 'S', 'GARDNERTOWN', 1, 'S', 'GARDNERTOWN', 41.52, -74.07, 41.52, -74.07, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Wires down at Route 300 and Holts Corners Road.');
INSERT INTO public.stormevents_east VALUES (781720, 201808, 17, 1835, 201808, 17, 1835, 130600, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '17-AUG-18 18:35:00', 'EST-5', '17-AUG-18 18:35:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'SSW', 'BEDFORD', 1, 'SSW', 'BEDFORD', 41.18, -73.66, 41.18, -73.66, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Trees and wires down at Greenwich Road and Brett Lane.');
INSERT INTO public.stormevents_east VALUES (781722, 201808, 17, 1835, 201808, 17, 1835, 130600, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '17-AUG-18 18:35:00', 'EST-5', '17-AUG-18 18:35:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'ESE', 'BEDFORD', 1, 'ESE', 'BEDFORD', 41.19, -73.63, 41.19, -73.63, 'A pre-frontal trough and mid level disturbance triggered severe thunderstorms across the region.', 'Trees and wires down at Middle Patent Road and Rustling Lane.');
INSERT INTO public.stormevents_east VALUES (781944, 201808, 13, 1532, 201808, 13, 1602, 130637, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'OKX', '13-AUG-18 15:32:00', 'EST-5', '13-AUG-18 16:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'GREENPORT', 1, 'ENE', 'GREENPORT', 41.1024, -72.3607, 41.1025, -72.3603, 'A weak area of low pressure south of the region triggered a series of showers across the area from mid morning through mid afternoon. These showers developed in a high precipitable water environment (2.08 inches on the morning sounding from Upton, NY) with slow storm motions, resulting in isolated flash flooding on the North Fork of Long Island. Rainfall totals across eastern Long Island generally ranged from 1-3 inches, with a trained spotter in Orient reporting 3.29 inches of rain.', 'Several roads were closed due to flooding in Greenport including the intersection of Front Street and First Street.');
INSERT INTO public.stormevents_east VALUES (763188, 201808, 1, 2125, 201808, 1, 2125, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '01-AUG-18 21:25:00', 'EST-5', '01-AUG-18 21:25:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 1, 'S', 'LOBACHSVILLE', 1, 'S', 'LOBACHSVILLE', 40.41, -75.73, 40.41, -75.73, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'Tree was blown down on wires such that Lobachsville Rd. was blocked near Bertolet Mill Rd.');
INSERT INTO public.stormevents_east VALUES (767257, 201808, 10, 2120, 201808, 10, 2250, 127912, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '10-AUG-18 21:20:00', 'EST-5', '10-AUG-18 22:50:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ALPHA', 2, 'SW', 'CRAIGMOOR', 39.2188, -80.3659, 39.1609, -80.3, 'Scattered showers and storms associated with a cold front passed through West Virginia the evening of the 9th and produced flooding issues in southeastern Harrison County.', 'Extensive rainfall caused Brushy Fork to rise out of its banks and flood portions of Brushy Fork Road.');
INSERT INTO public.stormevents_east VALUES (764518, 201808, 10, 2310, 201808, 11, 110, 127532, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '10-AUG-18 23:10:00', 'EST-5', '11-AUG-18 01:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'DODSONVILLE', 2, 'W', 'DODSONVILLE', 39.2, -83.87, 39.1975, -83.8633, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'High water was reported on U.S. 50 near the Highland/Brown County Line. The water was high enough to make it almost impassible for an SUV.');
INSERT INTO public.stormevents_east VALUES (768512, 201808, 12, 1308, 201808, 12, 1308, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:08:00', 'EST-5', '12-AUG-18 13:08:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SSW', 'NARUNA', 1, 'SSE', 'NARUNA', 37.1164, -79.0012, 37.1025, -78.994, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down one tree near the intersection of Three Creeks Road and Lewis Ford Road and a second tree near the intersection of Route 501 and Swinging Bridge Road.');
INSERT INTO public.stormevents_east VALUES (768519, 201808, 12, 1332, 201808, 12, 1332, 128145, 'VIRGINIA', 51, 2018, 'August', 'Lightning', 'RNK', '12-AUG-18 13:32:00', 'EST-5', '12-AUG-18 13:32:00', 0, 0, 0, 0, '50.00K', NULL, '911 Call Center', NULL, NULL, NULL, NULL, 1, 'NNW', 'RODDEN', 1, 'NNW', 'RODDEN', 36.8497, -79.0905, 36.8497, -79.0905, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Lightning struck a house and set it on fire at the 2000 block of Leda Road.');
INSERT INTO public.stormevents_east VALUES (768523, 201808, 12, 1340, 201808, 12, 1340, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:40:00', 'EST-5', '12-AUG-18 13:40:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'PHENIX', 0, 'N', 'PHENIX', 37.08, -78.75, 37.08, -78.75, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down one tree in the town of Phenix.');
INSERT INTO public.stormevents_east VALUES (768530, 201808, 12, 1410, 201808, 12, 1410, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 14:10:00', 'EST-5', '12-AUG-18 14:10:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'CHARLOTTE COURT HOUS', 1, 'NW', 'CHARLOTTE COURT HOUS', 37.0563, -78.638, 37.0563, -78.638, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down two trees in the town of Charlotte Court House.');
INSERT INTO public.stormevents_east VALUES (768534, 201808, 12, 1325, 201808, 12, 1325, 128145, 'VIRGINIA', 51, 2018, 'August', 'Lightning', 'RNK', '12-AUG-18 13:25:00', 'EST-5', '12-AUG-18 13:25:00', 0, 0, 0, 0, '0.20K', NULL, 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 3, 'ENE', 'MORRIS CHURCH', 3, 'ENE', 'MORRIS CHURCH', 37.1583, -78.8537, 37.1583, -78.8537, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Lightning struck a tree along the 6500 block of Sugar Hill Road.');
INSERT INTO public.stormevents_east VALUES (768537, 201808, 12, 1342, 201808, 12, 1342, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:42:00', 'EST-5', '12-AUG-18 13:42:00', 0, 0, 0, 0, '1.00K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'N', 'WEAL', 2, 'N', 'WEAL', 36.8497, -79.471, 36.8497, -79.471, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down two trees along Climax Road.');
INSERT INTO public.stormevents_east VALUES (768540, 201808, 12, 1344, 201808, 12, 1344, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:44:00', 'EST-5', '12-AUG-18 13:44:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'PITTSVILLE', 1, 'NW', 'PITTSVILLE', 36.9907, -79.48, 36.9907, -79.48, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down one tree near the intersection of Ridgeway Road and Pittsville Road.');
INSERT INTO public.stormevents_east VALUES (764532, 201808, 11, 1615, 201808, 11, 1815, 127534, 'KENTUCKY', 21, 2018, 'August', 'Flash Flood', 'ILN', '11-AUG-18 16:15:00', 'EST-5', '11-AUG-18 18:15:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CARRS', 1, 'NNW', 'QUEENS', 38.64, -83.41, 38.639, -83.406, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'A water line was washed out along Quicks Run Road about 2 miles from KY-8.');
INSERT INTO public.stormevents_east VALUES (764009, 201808, 7, 1624, 201808, 7, 1634, 127469, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '07-AUG-18 16:24:00', 'EST-5', '07-AUG-18 16:34:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 35, 'EG', NULL, NULL, 6, 'WNW', 'CAMP OYO', 6, 'WNW', 'CAMP OYO', 38.75, -83.26, 38.75, -83.26, 'Isolated strong thunderstorms developed in association with a weak upper level disturbance.', 'A large tree was knocked down over a road.');
INSERT INTO public.stormevents_east VALUES (764522, 201808, 10, 1505, 201808, 10, 1510, 127532, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '10-AUG-18 15:05:00', 'EST-5', '10-AUG-18 15:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 55, 'EG', NULL, NULL, 1, 'S', 'BALTIMORE', 1, 'S', 'BALTIMORE', 39.84, -82.6, 39.84, -82.6, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'A street sign was bent down on OH-158, a quarter of a mile south of OH-256 in Baltimore.');
INSERT INTO public.stormevents_east VALUES (769168, 201808, 26, 1710, 201808, 26, 1720, 128242, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '26-AUG-18 17:10:00', 'EST-5', '26-AUG-18 17:20:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SE', 'CRCLVLL PICKAWAY ARP', 1, 'SE', 'CRCLVLL PICKAWAY ARP', 39.51, -82.97, 39.51, -82.97, 'Isolated severe thunderstorms developed in an increasingly unstable air mass.', 'A small business received damage to its siding. Also three to four small trees were knocked down, Finally, pea size hail and heavy rain were also reported.');
INSERT INTO public.stormevents_east VALUES (769241, 201808, 26, 1710, 201808, 26, 1720, 128242, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '26-AUG-18 17:10:00', 'EST-5', '26-AUG-18 17:20:00', 0, 0, 0, 0, '45.00K', '0.00K', 'County Official', 52, 'EG', NULL, NULL, 0, 'N', 'CRCLVLL PICKAWAY ARP', 0, 'N', 'CRCLVLL PICKAWAY ARP', 39.52, -82.98, 39.52, -82.98, 'Isolated severe thunderstorms developed in an increasingly unstable air mass.', 'Several T-Hangers at the Pickaway County Airport received damage. One hanger had part of the roof removed. The doors on the second hanger were moved off the upper track. A third hanger had the doors blown upwards and off the lower track. An airplane inside the hanger suffered damage to the nose cowling, coolers and carburetors and possible prop damage. A taxiway light was also damaged.');
INSERT INTO public.stormevents_east VALUES (774297, 201808, 12, 930, 201808, 12, 930, 129205, 'WEST VIRGINIA', 54, 2018, 'August', 'Thunderstorm Wind', 'RLX', '12-AUG-18 09:30:00', 'EST-5', '12-AUG-18 09:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'W', 'BLUE SPG', 2, 'W', 'BLUE SPG', 38.53, -80.15, 38.53, -80.15, 'A surface cold front and upper-level low pressure system brought showers and thunderstorms to central West Virginia on the morning of the 12th.  The strongest storms resulted in isolated wind damage and flash flooding.', 'Several trees fell down along Dry Branch Road due to strong winds.');
INSERT INTO public.stormevents_east VALUES (774687, 201808, 17, 1920, 201808, 17, 2020, 129288, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '17-AUG-18 19:20:00', 'EST-5', '17-AUG-18 20:20:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BARLOW', 1, 'NW', 'ETOWAH', 38.4149, -81.592, 38.3939, -81.6126, 'An upper level disturbance and a surface frontal boundary entering the region generated showers and storms over Central Appalachia with a prolonged period of heavy rain.', 'Afternoon showers created issues near the entrance to Coonskin Park with high water at the intersection of Pennsylvania Avenue and Ruth Street.');
INSERT INTO public.stormevents_east VALUES (774696, 201808, 18, 1245, 201808, 18, 1445, 129288, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '18-AUG-18 12:45:00', 'EST-5', '18-AUG-18 14:45:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'OHLEY', 2, 'W', 'ESKDALE', 38.1005, -81.47, 38.0771, -81.4892, 'An upper level disturbance and a surface frontal boundary entering the region generated showers and storms over Central Appalachia with a prolonged period of heavy rain.', 'High water caused the intersection of Cabin Creek Road and Toms Fork Road to be closed.');
INSERT INTO public.stormevents_east VALUES (774700, 201808, 18, 1504, 201808, 18, 1704, 129288, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '18-AUG-18 15:04:00', 'EST-5', '18-AUG-18 17:04:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'MONTGOMERY', 2, 'NE', 'HUGHESTON', 38.1922, -81.3428, 38.2238, -81.342, 'An upper level disturbance and a surface frontal boundary entering the region generated showers and storms over Central Appalachia with a prolonged period of heavy rain.', 'Paint Creek rose out of its banks resulting in high water along Paint Creek Road.');
INSERT INTO public.stormevents_east VALUES (776168, 201808, 18, 1100, 201808, 18, 1300, 129288, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'RLX', '18-AUG-18 11:00:00', 'EST-5', '18-AUG-18 13:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'BENTREE', 0, 'WSW', 'DIXIE', 38.2856, -81.1817, 38.2485, -81.1861, 'An upper level disturbance and a surface frontal boundary entering the region generated showers and storms over Central Appalachia with a prolonged period of heavy rain.', 'Open Fork flooded, causing high water on Route 16 between Dixie and Bentree.');
INSERT INTO public.stormevents_east VALUES (777686, 201808, 28, 1645, 201808, 28, 1645, 129840, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TAE', '28-AUG-18 16:45:00', 'EST-5', '28-AUG-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', '(40J)PERRY-FOLEY ARPT', 2, 'SW', '(40J)PERRY-FOLEY ARPT', 30.05, -83.59, 30.05, -83.59, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down near the intersection of Puckett Road and Potts Still Road.');
INSERT INTO public.stormevents_east VALUES (777687, 201808, 31, 1335, 201808, 31, 1335, 129840, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TAE', '31-AUG-18 13:35:00', 'EST-5', '31-AUG-18 13:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'SAN PEDRO JUNCTION', 3, 'SE', 'SAN PEDRO JUNCTION', 29.98, -83.18, 29.98, -83.18, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down on GWD Road.');
INSERT INTO public.stormevents_east VALUES (778246, 201808, 14, 1455, 201808, 14, 1455, 129918, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'MHX', '14-AUG-18 14:55:00', 'EST-5', '14-AUG-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 2, 'NW', 'PAMLICO BEACH', 2, 'NW', 'PAMLICO BEACH', 35.4205, -76.6251, 35.4205, -76.6251, 'Isolated thunderstorms formed. One particular storm became severe and produced strong winds and some hail.', 'In addition to the strong winds, nickel sized hail fell.');
INSERT INTO public.stormevents_east VALUES (778248, 201808, 21, 1400, 201808, 21, 1400, 129921, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MHX', '21-AUG-18 14:00:00', 'EST-5', '21-AUG-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR RIVER BRIDGE', 0, 'N', 'ALLIGATOR RIVER BRIDGE', 35.9, -76, 35.9, -76, 'Strong thunderstorms moved through the northern Outer Banks and produced strong thunderstorm winds over the Albemarle Sound and Alligator River.', 'Weatherflow site at Alligator River Bridge.');
INSERT INTO public.stormevents_east VALUES (777911, 201808, 29, 1443, 201808, 29, 1443, 129858, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'CLE', '29-AUG-18 14:43:00', 'EST-5', '29-AUG-18 14:43:00', 0, 0, 0, 0, '12.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'WNW', 'BOSTON HGTS', 1, 'WNW', 'BOSTON HGTS', 41.2545, -81.5215, 41.2545, -81.5215, 'A cold front moved across northern Ohio during the afternoon of August 29th.  A line of showers and thunderstorms developed along the front.  A couple reports of severe weather were received.', 'Thunderstorm winds downed some trees and power lines along Boston Mills Road.');
INSERT INTO public.stormevents_east VALUES (781458, 201808, 31, 1930, 201808, 31, 2100, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 19:30:00', 'EST-5', '31-AUG-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'VAN BIBBER', 1, 'NE', 'CLAYTON', 39.4392, -76.3061, 39.4374, -76.322, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The stream gauge at Otter Point Creek in Edgewood reached flood stage of 8 feet. This means that flooding occurred on Winters Road near Singer Road.');
INSERT INTO public.stormevents_east VALUES (781553, 201808, 7, 1835, 201808, 7, 1835, 130561, 'NEW YORK', 36, 2018, 'August', 'Lightning', 'OKX', '07-AUG-18 18:35:00', 'EST-5', '07-AUG-18 18:35:00', 2, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'W', 'FLUSHING', 1, 'W', 'FLUSHING', 40.75, -73.84, 40.75, -73.84, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'Two people struck by lightning while on a soccer field at Flushing Meadows Corona Park.');
INSERT INTO public.stormevents_east VALUES (781554, 201808, 7, 1930, 201808, 7, 1930, 130561, 'NEW YORK', 36, 2018, 'August', 'Lightning', 'OKX', '07-AUG-18 19:30:00', 'EST-5', '07-AUG-18 19:30:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 0, 'N', 'HEMPSTEAD', 0, 'N', 'HEMPSTEAD', 40.7, -73.62, 40.7, -73.62, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'Lightning struck Prospect Elmementary School causing fire.');
INSERT INTO public.stormevents_east VALUES (781555, 201808, 7, 1748, 201808, 7, 1748, 130563, 'NEW JERSEY', 34, 2018, 'August', 'Thunderstorm Wind', 'OKX', '07-AUG-18 17:48:00', 'EST-5', '07-AUG-18 17:48:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'NE', 'SOUTH PATERSON', 1, 'NE', 'SOUTH PATERSON', 40.91, -74.16, 40.91, -74.16, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'A tree reported down at 58 Ellison Street with time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (781556, 201808, 7, 1758, 201808, 7, 1758, 130563, 'NEW JERSEY', 34, 2018, 'August', 'Thunderstorm Wind', 'OKX', '07-AUG-18 17:58:00', 'EST-5', '07-AUG-18 17:58:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 2, 'NW', 'ORADELL', 2, 'NW', 'ORADELL', 40.95, -74.09, 40.95, -74.09, 'A hot and humid airmass with a weak surface trough, in association with an upper level trough triggered thunderstorms across the region.', 'Multiple tree limbs and branches down up to three inches in diameter.  Also had hail ranging from one quarter to three quarters of an inch in diameter.');
INSERT INTO public.stormevents_east VALUES (767890, 201808, 2, 1945, 201808, 2, 1945, 128029, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '02-AUG-18 19:45:00', 'EST-5', '02-AUG-18 19:45:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'PEARISBURG', 1, 'SSW', 'PEARISBURG', 37.3048, -80.7386, 37.3048, -80.7386, 'A complex, broken line of thunderstorms developed during the afternoon ahead of an approaching cold front producing very heavy rainfall and some embedded severe storms. Trees were blown trees onto power lines, which caused a number of power outages.  Henry County and the city of Martinsville suffered the most tree damage and power outages. Rainfall was extremely intense within the very moist environment with precipitable water over 2 inches and several boundary collisions enhancing the rainfall. The highest amounts occurred in the City of Lynchburg and adjacent parts of Campbell County where radar estimated 4 to 6 inches of rain in several hours which was confirmed by several rain gages.', 'Thunderstorm winds blew down two trees on Forest Hill Drive just south of Pearisburg.');
INSERT INTO public.stormevents_east VALUES (772230, 201807, 27, 1600, 201807, 27, 1610, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 16:00:00', 'EST-5', '27-JUL-18 16:10:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'GOOSES REEF BUOY (44062)', 0, 'N', 'GOOSES REEF BUOY (44062)', 38.56, -76.41, 38.56, -76.41, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts of 37 to 41 knots were reported at Gooses Reef.');
INSERT INTO public.stormevents_east VALUES (772232, 201807, 27, 1627, 201807, 27, 1627, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 16:27:00', 'EST-5', '27-JUL-18 16:27:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'HART MILLER ISLAND (HRT)', 0, 'N', 'HART MILLER ISLAND (HRT)', 39.25, -76.37, 39.25, -76.37, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts in excess of 30 knots were reported at Hart Miller.');
INSERT INTO public.stormevents_east VALUES (772234, 201807, 27, 1716, 201807, 27, 1726, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 17:16:00', 'EST-5', '27-JUL-18 17:26:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'GROVE POINT (GVP)', 0, 'N', 'GROVE POINT (GVP)', 39.4, -76.04, 39.4, -76.04, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts up to 35 knots were reported at Grove Point.');
INSERT INTO public.stormevents_east VALUES (759001, 201805, 4, 1617, 201805, 4, 1617, 126608, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BUF', '04-MAY-18 16:17:00', 'EST-5', '04-MAY-18 16:17:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Storm Chaser', 52, 'EG', NULL, NULL, 1, 'N', 'STERLING', 1, 'N', 'STERLING', 43.34, -76.65, 43.34, -76.65, 'Storms formed along a pre-frontal trough east of Lake Erie as it crossed the afternoon lake breeze boundary. The environment was not terribly unstable, however, strong winds aloft were brought to the surface easily with modest convection. These crossed the area rapidly through the afternoon hours.', 'Powerlines down near Sterling Nature Center.');
INSERT INTO public.stormevents_east VALUES (759245, 201805, 4, 2045, 201805, 4, 2049, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 20:45:00', 'EST-5', '04-MAY-18 20:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'N', 'SWANZEY', 0, 'N', 'SWANZEY', 42.87, -72.28, 42.87, -72.28, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees on West Swanzey Road in Swanzey.');
INSERT INTO public.stormevents_east VALUES (759269, 201805, 4, 2120, 201805, 4, 2125, 126644, 'NEW HAMPSHIRE', 33, 2018, 'May', 'Thunderstorm Wind', 'GYX', '04-MAY-18 21:20:00', 'EST-5', '04-MAY-18 21:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'N', 'HOOKSETT', 0, 'N', 'HOOKSETT', 43.1, -71.47, 43.1, -71.47, 'A strong  cold front was approaching from the west on the afternoon of May 4th. Good shear combined with strong forcing to produce organized convection in the form of bowing line segments and some super cells. Thunderstorm wind damage was widespread with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees on the Londonderry Turnpike in Hooksett.');
INSERT INTO public.stormevents_east VALUES (781822, 201808, 17, 1641, 201808, 17, 1641, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 16:41:00', 'EST-5', '17-AUG-18 16:41:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NE', 'JEFFERSON', 2, 'NE', 'JEFFERSON', 42.5, -74.58, 42.5, -74.58, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Wires were downed. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (781823, 201808, 17, 1702, 201808, 17, 1702, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 17:02:00', 'EST-5', '17-AUG-18 17:02:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'ESPERANCE STATION', 1, 'NE', 'ESPERANCE STATION', 42.76, -74.25, 42.76, -74.25, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees were downed. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (781824, 201808, 17, 1702, 201808, 17, 1702, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 17:02:00', 'EST-5', '17-AUG-18 17:02:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'MIDDLEBURG', 1, 'S', 'MIDDLEBURG', 42.59, -74.35, 42.59, -74.35, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Wires were downed. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (781825, 201808, 17, 1715, 201808, 17, 1715, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 17:15:00', 'EST-5', '17-AUG-18 17:15:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'MIDDLEFIELD', 0, 'N', 'MIDDLEFIELD', 43.15, -74.98, 43.15, -74.98, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Tree was downed on Fishing Rock Road. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (767485, 201808, 8, 1937, 201808, 8, 1940, 127956, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '08-AUG-18 19:37:00', 'EST-5', '08-AUG-18 19:40:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'N', 'TAYLORS XRDS', 1, 'N', 'TAYLORS XRDS', 34.29, -81.5, 34.29, -81.5, 'An upper level disturbance and surface trough contributed to a band of scattered thunderstorms developing and moving through the region in the evening, some of which reached severe limits.', 'Tree down in roadway at the intersection of Halfacre Rd and St. Philips Church Rd.');
INSERT INTO public.stormevents_east VALUES (767486, 201808, 8, 2028, 201808, 8, 2030, 127956, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '08-AUG-18 20:28:00', 'EST-5', '08-AUG-18 20:30:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 5, 'S', 'ROPERS XRDS', 5, 'S', 'ROPERS XRDS', 33.61, -81.99, 33.61, -81.99, 'An upper level disturbance and surface trough contributed to a band of scattered thunderstorms developing and moving through the region in the evening, some of which reached severe limits.', 'Trees were downed in the vicinity of Mealing Rd and Martintown Rd, blocking all lanes of Mealing Rd.');
INSERT INTO public.stormevents_east VALUES (767490, 201808, 8, 1639, 201808, 8, 1642, 127956, 'SOUTH CAROLINA', 45, 2018, 'August', 'Hail', 'CAE', '08-AUG-18 16:39:00', 'EST-5', '08-AUG-18 16:42:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Trained Spotter', 0.25, NULL, NULL, NULL, 3, 'ENE', 'CHERAW MUNI ARPT', 3, 'ENE', 'CHERAW MUNI ARPT', 34.73, -79.92, 34.73, -79.92, 'An upper level disturbance and surface trough contributed to a band of scattered thunderstorms developing and moving through the region in the evening, some of which reached severe limits.', 'Spotter reported pea size hail along US Hwy 52 near Cheraw.');
INSERT INTO public.stormevents_east VALUES (767491, 201808, 8, 2109, 201808, 8, 2112, 127956, 'SOUTH CAROLINA', 45, 2018, 'August', 'Hail', 'CAE', '08-AUG-18 21:09:00', 'EST-5', '08-AUG-18 21:12:00', 0, 0, 0, 0, '0.10K', '0.10K', 'COOP Observer', 0.25, NULL, NULL, NULL, 3, 'ESE', 'SHEPARD', 3, 'ESE', 'SHEPARD', 34.31, -80.47, 34.31, -80.47, 'An upper level disturbance and surface trough contributed to a band of scattered thunderstorms developing and moving through the region in the evening, some of which reached severe limits.', 'NWS COOP observer 4 miles SW of Cassatt reported small hail along with a few small limbs down.');
