INSERT INTO public.stormevents_east VALUES (781451, 201808, 8, 1247, 201808, 8, 1247, 130539, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 12:47:00', 'EST-5', '08-AUG-18 12:47:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SSE', 'LAKEMONT', 3, 'SSE', 'LAKEMONT', 34.74, -83.39, 34.74, -83.39, 'Isolated to widely scattered thunderstorms developed across the Georgia Blue Ridge during the afternoon. One storm produced brief damaging winds near Tallulah Gorge.', 'County comms reported trees blown down along Highway 15 near Tallulah Gorge.');
INSERT INTO public.stormevents_east VALUES (781457, 201808, 8, 1442, 201808, 8, 1442, 130540, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 14:42:00', 'EST-5', '08-AUG-18 14:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 3, 'ESE', 'HIGHLAND', 2, 'NNW', 'JORDON', 35.068, -82.275, 35.056, -82.257, 'Scattered thunderstorms developed during the afternoon near the South Carolina Blue Ridge, with storms gradually spreading south and east along outflow boundaries throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Media reported trees blown down on Pink Dill Mill Road. Highway patrol reported another tree down nearby at Highway 14 and Jordan Rd.');
INSERT INTO public.stormevents_east VALUES (781464, 201808, 8, 1509, 201808, 8, 1509, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 15:09:00', 'EST-5', '08-AUG-18 15:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WNW', 'DUAN', 1, 'WNW', 'DUAN', 35.63, -81.22, 35.63, -81.22, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Spotter reported trees blown down on Rome Jones Rd.');
INSERT INTO public.stormevents_east VALUES (781465, 201808, 8, 1525, 201808, 8, 1525, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 15:25:00', 'EST-5', '08-AUG-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'W', 'STARTOWN', 1, 'W', 'STARTOWN', 35.65, -81.28, 35.65, -81.28, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Spotter reported trees blown down on Hardwood Cir.');
INSERT INTO public.stormevents_east VALUES (781467, 201808, 8, 1529, 201808, 8, 1529, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 15:29:00', 'EST-5', '08-AUG-18 15:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 4, 'NNW', 'DYSORTVILLE', 4, 'NNW', 'DYSORTVILLE', 35.648, -81.904, 35.648, -81.904, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'EM reported trees blown down along Highway 226.');
INSERT INTO public.stormevents_east VALUES (781470, 201808, 8, 1545, 201808, 8, 1545, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 15:45:00', 'EST-5', '08-AUG-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 5, 'ENE', 'BRINDLETOWN', 5, 'ENE', 'BRINDLETOWN', 35.656, -81.739, 35.656, -81.739, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Spotter reported trees blown down along Jenkins Rd.');
INSERT INTO public.stormevents_east VALUES (781472, 201808, 8, 1620, 201808, 8, 1620, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 16:20:00', 'EST-5', '08-AUG-18 16:20:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 40, 'EG', NULL, NULL, 2, 'NW', 'HICKORY', 2, 'NW', 'HICKORY', 35.749, -81.341, 35.749, -81.341, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Public reported a tree blown down on a house on 13th Ave Northwest.');
INSERT INTO public.stormevents_east VALUES (771450, 201808, 8, 1405, 201808, 8, 1405, 128612, 'TENNESSEE', 47, 2018, 'August', 'Thunderstorm Wind', 'MRX', '08-AUG-18 14:05:00', 'EST-5', '08-AUG-18 14:05:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'SW', 'MOUNTAIN CITY', 1, 'SW', 'MOUNTAIN CITY', 36.47, -81.81, 36.47, -81.81, 'Convection developed along an outflow boundary during the afternoon across Tennessee and Southwest North Carolina generating damaging winds.', 'Several trees were reported down.');
INSERT INTO public.stormevents_east VALUES (763190, 201808, 1, 2141, 201808, 1, 2141, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '01-AUG-18 21:41:00', 'EST-5', '01-AUG-18 21:41:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'EMMAUS', 1, 'WNW', 'EMMAUS', 40.54, -75.5, 40.54, -75.5, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'Multiple reports were gathered of trees being down, some on cars and a house. Time best estimated from radar.');
INSERT INTO public.stormevents_east VALUES (751133, 201805, 4, 1825, 201805, 4, 1825, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:25:00', 'EST-5', '04-MAY-18 18:25:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'LAKE PLEASANT', 1, 'NE', 'LAKE PLEASANT', 43.48, -74.4, 43.48, -74.4, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A tree was downed along Route 8 near Lake Pleasant.');
INSERT INTO public.stormevents_east VALUES (767445, 201808, 6, 1410, 201808, 6, 1415, 127945, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '06-AUG-18 14:10:00', 'EST-5', '06-AUG-18 14:15:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 4, 'SW', 'WILLISTON', 4, 'SW', 'WILLISTON', 33.36, -81.48, 33.36, -81.48, 'Daytime heating and convergence along a surface trough contributed to scattered thunderstorm development, an isolated cell reached severe limits.', 'Power lines down on US Hwy 278 near Hwy 39.');
INSERT INTO public.stormevents_east VALUES (767435, 201808, 6, 1329, 201808, 6, 1329, 127945, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '06-AUG-18 13:29:00', 'EST-5', '06-AUG-18 13:29:00', 0, 0, 0, 0, '60.00K', '0.10K', 'Law Enforcement', 45, 'EG', NULL, NULL, 1, 'WSW', 'GLOVERVILLE', 1, 'WSW', 'GLOVERVILLE', 33.5166, -81.8462, 33.5166, -81.8462, 'Daytime heating and convergence along a surface trough contributed to scattered thunderstorm development, an isolated cell reached severe limits.', 'Aiken Co Emergency Manager reported that the steeple at Langley First Baptist Church, on Augusta Rd near Warrenville, had been blown down.  Because the steeple was hollow and made of aluminum, it is thought that it was downed by sub-severe wind speeds. Local media reports that the damage may exceed $60K.');
INSERT INTO public.stormevents_east VALUES (767478, 201808, 8, 2033, 201808, 8, 2033, 127956, 'SOUTH CAROLINA', 45, 2018, 'August', 'Lightning', 'CAE', '08-AUG-18 20:33:00', 'EST-5', '08-AUG-18 20:33:00', 0, 0, 0, 0, NULL, '0.10K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'ESE', 'STEWARTS XRDS', 1, 'ESE', 'STEWARTS XRDS', 34.79, -80.58, 34.79, -80.58, 'An upper level disturbance and surface trough contributed to a band of scattered thunderstorms developing and moving through the region in the evening, some of which reached severe limits.', 'Buford Fire Dept reported that lightning struck a house near the intersection of Shiloh Unity Rd and Plyler Mill Rd.  The house sustained moderate damage. Time estimated.');
INSERT INTO public.stormevents_east VALUES (768542, 201808, 12, 1355, 201808, 12, 1355, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:55:00', 'EST-5', '12-AUG-18 13:55:00', 0, 0, 0, 0, '0.60K', NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'N', 'LOWMOOR', 1, 'N', 'LOWMOOR', 37.7997, -79.8689, 37.7997, -79.8689, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down a few large tree branches along Selma Low Moor Road.');
INSERT INTO public.stormevents_east VALUES (768545, 201808, 12, 1330, 201808, 12, 1330, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 13:30:00', 'EST-5', '12-AUG-18 13:30:00', 0, 0, 0, 0, '11.00K', NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 4, 'ESE', 'DILLARD', 4, 'ESE', 'DILLARD', 37.4599, -79.086, 37.4599, -79.086, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down multiple trees and power lines along Dixie Airport Road in Madison Heights.');
INSERT INTO public.stormevents_east VALUES (768458, 201808, 12, 1220, 201808, 12, 1220, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:20:00', 'EST-5', '12-AUG-18 12:20:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'COWAN', 1, 'SE', 'COWAN', 37.1557, -80.5619, 37.1557, -80.5619, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down one tree at the intersection of Route 114 and Viscoe Road.');
INSERT INTO public.stormevents_east VALUES (768479, 201808, 12, 1240, 201808, 12, 1245, 128145, 'VIRGINIA', 51, 2018, 'August', 'Hail', 'RNK', '12-AUG-18 12:40:00', 'EST-5', '12-AUG-18 12:45:00', 0, 0, 0, 0, '0.00K', NULL, 'NWS Employee', 1, NULL, NULL, NULL, 0, 'S', 'CAMBRIA', 1, 'WSW', 'HOUCHINS', 37.1498, -80.42, 37.1445, -80.3929, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Hail up to the size of quarters fell from Lions Drive Northwest to Gobblers Spur.');
INSERT INTO public.stormevents_east VALUES (768467, 201808, 12, 1220, 201808, 12, 1230, 128145, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'RNK', '12-AUG-18 12:20:00', 'EST-5', '12-AUG-18 12:30:00', 0, 0, 0, 0, '70.00K', NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 2, 'W', 'RADFORD', 1, 'NE', 'RADFORD', 37.1233, -80.5892, 37.1305, -80.541, 'A closed upper level low combined with a passing cold front sparked scattered severe thunderstorm during the afternoon.  These storms blew down plenty of trees and power lines, and they also produced large hail up to the size of half dollar coins.', 'Thunderstorm winds blew down numerous trees and tree limbs throughout the city of Radford.  Trees knocked down a dozen power poles in the city, including near the intersection of Auburn Avenue and Vienna Avenue.');
INSERT INTO public.stormevents_east VALUES (771394, 201808, 31, 1412, 201808, 31, 1412, 128594, 'VIRGINIA', 51, 2018, 'August', 'Lightning', 'RNK', '31-AUG-18 14:12:00', 'EST-5', '31-AUG-18 14:12:00', 0, 0, 0, 0, '0.20K', NULL, 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'NW', 'WYTHEVILLE', 1, 'NW', 'WYTHEVILLE', 36.96, -81.09, 36.96, -81.09, 'A hot and humid air mass sparked isolated severe thunderstorms during the evening.  These storms blew down several trees across southwest Virginia.', 'Lightning struck a tree about one mile north of Wytheville.');
INSERT INTO public.stormevents_east VALUES (764517, 201808, 10, 2200, 201808, 11, 0, 127532, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '10-AUG-18 22:00:00', 'EST-5', '11-AUG-18 00:00:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'EAST DANVILLE', 1, 'NNW', 'EAST DANVILLE', 39.13, -83.55, 39.1294, -83.5563, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'East Berryville Road was washed out just east of State Route 73.');
INSERT INTO public.stormevents_east VALUES (764524, 201808, 11, 1004, 201808, 11, 1204, 127533, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '11-AUG-18 10:04:00', 'EST-5', '11-AUG-18 12:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'LINCOLN VLG', 2, 'ENE', 'LINCOLN VLG', 39.975, -83.1014, 39.9745, -83.1013, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'High water was reported on the east bound lanes of I-70 at Wilson Road.');
INSERT INTO public.stormevents_east VALUES (767504, 201808, 12, 2330, 201808, 12, 2350, 127962, 'SOUTH CAROLINA', 45, 2018, 'August', 'Flash Flood', 'CAE', '12-AUG-18 23:30:00', 'EST-5', '12-AUG-18 23:50:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SUMTER', 1, 'SW', 'SUMTER', 33.9148, -80.3564, 33.913, -80.3557, 'Thunderstorms developed in a moist environment and produced locally heavy rain on the night of August 12th into the very early morning hours on August 13th.', 'Roadway was flooded with stranded vehicles at Guignard Dr and Birnie Cir. Time estimated.');
INSERT INTO public.stormevents_east VALUES (774217, 201808, 4, 836, 201808, 4, 845, 129187, 'CONNECTICUT', 9, 2018, 'August', 'Tornado', 'BOX', '04-AUG-18 08:36:00', 'EST-5', '04-AUG-18 08:45:00', 0, 0, 0, 0, '0.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WNW', 'NORTH WOODSTOCK', 1, 'W', 'FABYAN', 41.9982, -72.0377, 42.0194, -71.9397, 'A moist, tropical environment was in place across southern New England on the morning of August 4th.  A short-wave trough was approaching, along with a cold front.  The main concern was for flash flooding, but early morning sunshine destabilized the atmosphere and contributed to the development of the tornado, which also touched down again in Massachusetts.', 'An EF-0 tornado, with wind speeds estimated at 80 mph, touched down on Redhead Hill Road in northern Woodstock and traveled just over 5 miles on a discontinuous path before lifting up in the Quinebaug portion of Thompson.  It was only 8 yards wide.  It sliced a single, healthy oak tree in half and flattened small portions of two separate corn fields on Redhead Hill Road in Woodstock.  The corn was laid down in differenet directions. A woman saw swirling of trees and other debris as it occurred, despite it being enshrouded in rain.  Isolated tree damage also was spotted on Watson Road, near Green Acres Lane, in Quinebaug.  The tornado lasted from 936 AM EDT to 945 AM EDT.');
INSERT INTO public.stormevents_east VALUES (774224, 201808, 4, 859, 201808, 4, 900, 129188, 'MASSACHUSETTS', 25, 2018, 'August', 'Tornado', 'BOX', '04-AUG-18 08:59:00', 'EST-5', '04-AUG-18 09:00:00', 1, 0, 0, 0, '5.00M', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'WSW', 'WEBSTER', 0, 'WNW', 'WEBSTER', 42.0456, -71.8907, 42.0509, -71.885, 'A moist, tropical environment was in place across southern New England on the morning of August 4th. A short-wave trough was approaching, along with a cold front. The main concern was for flash flooding, but early morning sunshine destabilized the atmosphere and contributed to the development of the tornado, which had touched down in northeast Connecticut, prior to this second touchdown.', 'In just about one minute, an EF-1 tornado, with maximum winds estimated at 110 mph, wreaked havoc in the easternmost portion of Dudley, MA and in the downtown portion of Webster, MA.  It touched down along Route 12 (Schofield Avenue) to the west of Laprise Court in Dudley and traveled northeastward onto Main Street in Webster, then lifted near the French River by Oxford Avenue. ||Many trees were snapped and debarked. In Webster, a gas station overhang was twisted. An old brick rooftop was damaged, with bricks having fallen onto Main Street. The rubber roof covering of another building was peeled completely off.  Windows were blown out at a business on Main Street and the street was littered with broken glass. The side walls of an apartment complex were bent slightly outward toward the tornado. Window screens were sucked outward.  A car windshield and side mirror was damaged.  There were other reports of trees fallen onto cars.  Utility poles were snapped and numerous wires were downed.  According to MEMA, at least 3 buildings were condemned and at least 5 were uninhabitable.||Nearly everyone that our survey team spoke with had heard the warning via the Wireless Emergency Alert on their cell phones as much as 20+ minutes in advance of the touchdown! This undoubtedly played a big role in the fact that there were no fatalities.  According to media reports, there was one minor injury when part of a roof fell on top of a woman''s car.');
INSERT INTO public.stormevents_east VALUES (746148, 201804, 23, 700, 201804, 24, 700, 124365, 'NORTH CAROLINA', 37, 2018, 'April', 'Heavy Rain', 'RNK', '23-APR-18 07:00:00', 'EST-5', '24-APR-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'SE', 'BOONE', 1, 'SE', 'BOONE', 36.2098, -81.6673, 36.2098, -81.6673, 'A wet period developed from April 23-25 as an upper level low over the southeastern U.S. slowly tracked toward the Atlantic coast. Rainfall was persistent during this period with sustained south to southeasterly flow with the heaviest rains falling in the 24-hour period ending 12z (7AM) on the 24th with 3 to 4+ inch amounts common. The highest totals occurred over Watauga County, NC. Mainly minor flooding was observed in several areas.', 'The COOP station at Boone 1 SE (BOON7) measured 3.94 inches for the 24-hour period ending 7AM on the 24th. This was the highest 1-day April rainfall in the period of record at this location, with data starting in 1980. The previous April record at this site was set less than 10 days earlier on April 16, 2018. If the previous COOP site at Boone is included in the comparison (with data back to 1929) this was the 2nd wettest April day after April 5, 1957 with 4.68 inches.');
INSERT INTO public.stormevents_east VALUES (740203, 201804, 4, 145, 201804, 4, 145, 123440, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '04-APR-18 01:45:00', 'EST-5', '04-APR-18 01:45:00', 0, 0, 0, 0, '0.50K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'E', 'RAVEN', 1, 'E', 'RAVEN', 37.0816, -81.8525, 37.0816, -81.8525, 'A cold front pushed a line of showers and thunderstorms into parts of southwest Virginia. The thunderstorms produced wind damage by knocking down two trees in Tazewell County before dissipating.  Another thunderstorm blew down a few trees in Marion within Smyth County.', 'One large tree was blown down along Daw Road.');
INSERT INTO public.stormevents_east VALUES (740202, 201804, 4, 138, 201804, 4, 138, 123440, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '04-APR-18 01:38:00', 'EST-5', '04-APR-18 01:38:00', 0, 0, 0, 0, '0.50K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'NNW', 'PLEASANT HILL', 2, 'NNW', 'PLEASANT HILL', 37.2066, -81.7573, 37.2066, -81.7573, 'A cold front pushed a line of showers and thunderstorms into parts of southwest Virginia. The thunderstorms produced wind damage by knocking down two trees in Tazewell County before dissipating.  Another thunderstorm blew down a few trees in Marion within Smyth County.', 'One tree was blown down near the intersection of Bearwallow Road and Greasey Creek Road.');
INSERT INTO public.stormevents_east VALUES (748563, 201804, 4, 415, 201804, 4, 415, 123440, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '04-APR-18 04:15:00', 'EST-5', '04-APR-18 04:15:00', 0, 0, 0, 0, '2.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'MARION', 1, 'WNW', 'MARION', 36.833, -81.5113, 36.833, -81.5113, 'A cold front pushed a line of showers and thunderstorms into parts of southwest Virginia. The thunderstorms produced wind damage by knocking down two trees in Tazewell County before dissipating.  Another thunderstorm blew down a few trees in Marion within Smyth County.', 'A few trees were blown down in the town of Marion.');
INSERT INTO public.stormevents_east VALUES (778249, 201808, 21, 1438, 201808, 21, 1438, 129921, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MHX', '21-AUG-18 14:38:00', 'EST-5', '21-AUG-18 14:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'ROANOKE SOUND', 0, 'N', 'ROANOKE SOUND', 35.91, -75.63, 35.91, -75.63, 'Strong thunderstorms moved through the northern Outer Banks and produced strong thunderstorm winds over the Albemarle Sound and Alligator River.', 'Weatherflow site in the Roanoke Sound.');
INSERT INTO public.stormevents_east VALUES (778250, 201808, 21, 1439, 201808, 21, 1439, 129921, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MHX', '21-AUG-18 14:39:00', 'EST-5', '21-AUG-18 14:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 43, 'MG', NULL, NULL, 0, 'N', 'ROANOKE SOUND', 0, 'N', 'ROANOKE SOUND', 35.91, -75.63, 35.91, -75.63, 'Strong thunderstorms moved through the northern Outer Banks and produced strong thunderstorm winds over the Albemarle Sound and Alligator River.', 'A public weather station reported the strong winds.');
INSERT INTO public.stormevents_east VALUES (778247, 201808, 18, 2001, 201808, 18, 2001, 129920, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'MHX', '18-AUG-18 20:01:00', 'EST-5', '18-AUG-18 20:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 0, 'N', 'CROATAN SOUND', 0, 'N', 'CROATAN SOUND', 35.87, -75.71, 35.87, -75.71, 'Strong thunderstorms moved through the Albemarle Sound near Manteo.', 'Weatherflow site in Croatan Sound measured the wind gust.');
INSERT INTO public.stormevents_east VALUES (779583, 201808, 11, 1655, 201808, 11, 1700, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 16:55:00', 'EST-5', '11-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'ALLWOOD', 0, 'SE', 'ALLWOOD', 40.8499, -74.1697, 40.8458, -74.1745, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Route 3 was closed in both directions at the Garden State Parkway due to flooding in Clifton. In addition, the Garden State Parkway was flooded southbound at NJ 3 (Exit 153).');
INSERT INTO public.stormevents_east VALUES (780696, 201808, 8, 1515, 201808, 8, 1516, 130423, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'IWX', '08-AUG-18 15:15:00', 'EST-5', '08-AUG-18 15:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SE', 'DESHLER', 1, 'SE', 'DESHLER', 41.21, -83.89, 41.21, -83.89, 'Stalled frontal boundary remained the focus for thunderstorms into the 8th with marginal shear profiles and sufficient instability allowing for a few strong to severe storms.', 'A trained spotter reported a large, partially rotten tree limb, approximately one foot in diameter, was snapped off near the intersection of SR 18 and Oak Street.');
INSERT INTO public.stormevents_east VALUES (781573, 201808, 11, 400, 201808, 11, 400, 130571, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '11-AUG-18 04:00:00', 'EST-5', '11-AUG-18 04:00:00', 0, 0, 0, 0, '4.00K', '0.00K', 'NWS Employee', 61, 'EG', NULL, NULL, 1, 'N', 'RIDGE', 1, 'N', 'RIDGE', 40.91, -72.88, 40.91, -72.88, 'A slow moving cold front along with an upper level disturbance triggered thunderstorms across the region.', 'Numerous large tree branches reported down on farm along Route 25.');
INSERT INTO public.stormevents_east VALUES (781567, 201808, 9, 135, 201808, 9, 135, 130570, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '09-AUG-18 01:35:00', 'EST-5', '09-AUG-18 01:35:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'WSW', 'LAFFINGTOWN', 1, 'WSW', 'LAFFINGTOWN', 40.89, -73.62, 40.89, -73.62, 'A cold front and a mid level disturbance moved through the region and triggered severe thunderstorms.', 'A large tree fell on three vehicles on Lattingtown Road.');
INSERT INTO public.stormevents_east VALUES (781569, 201808, 9, 220, 201808, 9, 220, 130570, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'OKX', '09-AUG-18 02:20:00', 'EST-5', '09-AUG-18 02:20:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'NNW', 'COMMACK', 1, 'NNW', 'COMMACK', 40.8454, -73.2852, 40.8454, -73.2852, 'A cold front and a mid level disturbance moved through the region and triggered severe thunderstorms.', 'A large tree took down powerlines on Old Indian Head Road between Vance Street and Jericho Turnpike.');
INSERT INTO public.stormevents_east VALUES (748591, 201804, 15, 1653, 201804, 15, 1655, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 16:53:00', 'EST-5', '15-APR-18 16:55:00', 0, 0, 0, 0, '50.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'SSE', 'VANDOLA', 2, 'SW', 'WESTOVER HILLS', 36.5408, -79.4931, 36.5839, -79.4769, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'This is the first segment in Virginia of a tornado that originated west of Pelham near Dusty Lane in Caswell County of North Carolina at 4:51 PM EST.  It crossed into Pittsylvania County at 4:53 PM EST.  The tornado snapped numerous trees and damaged a few outbuildings.  The tornado crossed into the independent city of Danville at 4:55 PM EST.  It would later continue northward back into Pittsylvania County.');
INSERT INTO public.stormevents_east VALUES (760718, 201805, 14, 1720, 201805, 14, 1800, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'PBZ', '14-MAY-18 17:20:00', 'EST-5', '14-MAY-18 18:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'MEADOWDALE', 0, 'E', 'GATH', 39.4852, -80.0735, 39.43, -80.0716, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', 'County 911 officials reported flooding on the east side of the county, including Pricketts Creek Road and Oilwell Hollow Road.');
INSERT INTO public.stormevents_east VALUES (778376, 201808, 2, 800, 201808, 3, 800, 128029, 'VIRGINIA', 51, 2018, 'August', 'Heavy Rain', 'RNK', '02-AUG-18 08:00:00', 'EST-5', '03-AUG-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'MARTINSVILLE', 0, 'N', 'MARTINSVILLE', 36.68, -79.87, 36.68, -79.87, 'A complex, broken line of thunderstorms developed during the afternoon ahead of an approaching cold front producing very heavy rainfall and some embedded severe storms. Trees were blown trees onto power lines, which caused a number of power outages.  Henry County and the city of Martinsville suffered the most tree damage and power outages. Rainfall was extremely intense within the very moist environment with precipitable water over 2 inches and several boundary collisions enhancing the rainfall. The highest amounts occurred in the City of Lynchburg and adjacent parts of Campbell County where radar estimated 4 to 6 inches of rain in several hours which was confirmed by several rain gages.', 'Martinsville FP COOP (MARV2) measured 1.93 inches for the 24-hour period ending at 8 AM EDT on the 3rd. This was the highest ever for this date, with nearly complete data back to 1931.');
INSERT INTO public.stormevents_east VALUES (774365, 201807, 17, 1421, 201807, 17, 1615, 128271, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '17-JUL-18 14:21:00', 'EST-5', '17-JUL-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'GLEN BURNIE', 0, 'W', 'GLEN BURNIE', 39.1701, -76.6326, 39.1697, -76.6321, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding and isolated flash flooding, mainly in the Baltimore metro area.', 'Dorsey Road (Maryland 176) reported flooded in both directions and closed near Sawmill Creek at Route 648 due to rapidly rising water.');
INSERT INTO public.stormevents_east VALUES (759308, 201805, 12, 1509, 201805, 12, 1509, 126655, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '12-MAY-18 15:09:00', 'EST-5', '12-MAY-18 15:09:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'MORRISVILLE', 1, 'W', 'MORRISVILLE', 39.9, -80.19, 39.9, -80.19, 'Showers and thunderstorms developed along a stalled frontal boundary that was situated over the upper Ohio Valley. Strong to severe storms resulted in several reports of downed trees and hail in southwestern Pennsylvania and eastern Ohio.', 'Local 911 reported several trees down around the city of Waynesburg and outskirts, including railroad tracks. One large tree brought down power poles.');
INSERT INTO public.stormevents_east VALUES (782023, 201808, 2, 1805, 201808, 2, 2005, 128029, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'RNK', '02-AUG-18 18:05:00', 'EST-5', '02-AUG-18 20:05:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'TIMBERLAKE', 1, 'WNW', 'LYNCHBURG ARPT', 37.3463, -79.2461, 37.3326, -79.2162, 'A complex, broken line of thunderstorms developed during the afternoon ahead of an approaching cold front producing very heavy rainfall and some embedded severe storms. Trees were blown trees onto power lines, which caused a number of power outages.  Henry County and the city of Martinsville suffered the most tree damage and power outages. Rainfall was extremely intense within the very moist environment with precipitable water over 2 inches and several boundary collisions enhancing the rainfall. The highest amounts occurred in the City of Lynchburg and adjacent parts of Campbell County where radar estimated 4 to 6 inches of rain in several hours which was confirmed by several rain gages.', 'Several reports of flash flooding from the Timberlake area of Campbell County. Sunburst Road was flooded and impassable with more than a foot of water over it. Three feet of was over Timberlake and Woodhaven Road with a vehicle trapped. Buffalo Creek was well outof its banks and flooding Route 460. A swift was rescue was reported in this area. In addition, water was observed flowing over the spillway of Timberlake Dam. In the aftermath up to eight roads in the county were reported with some type of structural damage. Two homes were also reported to have been damaged.');
INSERT INTO public.stormevents_east VALUES (781826, 201808, 17, 1734, 201808, 17, 1734, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 17:34:00', 'EST-5', '17-AUG-18 17:34:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'EAST GLENVILLE', 1, 'N', 'EAST GLENVILLE', 42.89, -73.92, 42.89, -73.92, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees and wires were downed onto Route 50. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (774908, 201807, 22, 1510, 201807, 22, 1630, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 15:10:00', 'EST-5', '22-JUL-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'HUNTINGTOWN', 2, 'NNW', 'HUNTINGTOWN', 38.6403, -76.6349, 38.6402, -76.6342, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Stoneleigh Court and Huntingtown Road impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (781827, 201808, 17, 1744, 201808, 17, 1744, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 17:44:00', 'EST-5', '17-AUG-18 17:44:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SE', 'SARATOGA SPGS CO ARP', 2, 'SE', 'SARATOGA SPGS CO ARP', 43.03, -73.85, 43.03, -73.85, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees were downed. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (781828, 201808, 17, 1748, 201808, 17, 1748, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 17:48:00', 'EST-5', '17-AUG-18 17:48:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'MALTA', 1, 'NNW', 'MALTA', 42.99, -73.79, 42.99, -73.79, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (781829, 201808, 17, 1805, 201808, 17, 1805, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 18:05:00', 'EST-5', '17-AUG-18 18:05:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'SE', 'NORTH GREENFIELD', 1, 'SE', 'NORTH GREENFIELD', 43.16, -73.86, 43.16, -73.86, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees and wires were downed.');
INSERT INTO public.stormevents_east VALUES (763998, 201808, 6, 1630, 201808, 6, 1640, 127468, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '06-AUG-18 16:30:00', 'EST-5', '06-AUG-18 16:40:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 35, 'EG', NULL, NULL, 1, 'SSW', 'HARRISON FURNACE', 1, 'SSW', 'HARRISON FURNACE', 38.81, -82.89, 38.81, -82.89, 'Isolated strong thunderstorms developed ahead of weak upper level disturbance.', 'A tree fell down on power lines on Swauger Valley Road near Dutch Ridge Road.');
INSERT INTO public.stormevents_east VALUES (764514, 201808, 10, 1915, 201808, 10, 2100, 127532, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '10-AUG-18 19:15:00', 'EST-5', '10-AUG-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'CIRCLEVILLE', 3, 'SSW', 'FOX', 39.59, -83.0001, 39.5848, -83.0389, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'High water was reported on State Routes 138 and 104.');
INSERT INTO public.stormevents_east VALUES (764515, 201808, 10, 2015, 201808, 10, 2215, 127532, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '10-AUG-18 20:15:00', 'EST-5', '10-AUG-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'TREBEINS', 1, 'ENE', 'XENIA GREENE CO ARPT', 39.69, -83.96, 39.6887, -83.9602, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'Standing water at least ankle deep was reported.');
INSERT INTO public.stormevents_east VALUES (767500, 201808, 9, 1817, 201808, 9, 1820, 127961, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '09-AUG-18 18:17:00', 'EST-5', '09-AUG-18 18:20:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 60, 'EG', NULL, NULL, 2, 'S', 'HOPE STATION', 2, 'S', 'HOPE STATION', 34.24, -81.37, 34.24, -81.37, 'An upper disturbance and daytime heating produced scattered thunderstorms, some of which were severe.', 'Trees down between the towns of Pomaria and Peak along Hwy 213.');
INSERT INTO public.stormevents_east VALUES (767501, 201808, 9, 1838, 201808, 9, 1840, 127961, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '09-AUG-18 18:38:00', 'EST-5', '09-AUG-18 18:40:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 3, 'ENE', 'WHITE ROCK', 3, 'ENE', 'WHITE ROCK', 34.17, -81.23, 34.17, -81.23, 'An upper disturbance and daytime heating produced scattered thunderstorms, some of which were severe.', 'Public report, via social media, of large limbs down along Shady Grove Rd near the intersection with Kennerly Rd.');
INSERT INTO public.stormevents_east VALUES (767502, 201808, 9, 1857, 201808, 9, 1900, 127961, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CAE', '09-AUG-18 18:57:00', 'EST-5', '09-AUG-18 19:00:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 2, 'N', 'CHAPPELLS', 2, 'N', 'CHAPPELLS', 34.21, -81.87, 34.21, -81.87, 'An upper disturbance and daytime heating produced scattered thunderstorms, some of which were severe.', 'Trees down blocking roadway on Long Sumpit Rd near Milner Rd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (781615, 201808, 2, 1520, 201808, 2, 1520, 130587, 'LAKE HURON', 90, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '02-AUG-18 15:20:00', 'EST-5', '02-AUG-18 15:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 51, 'MG', NULL, NULL, 0, 'N', 'SAGINAW BAY LIGHT', 0, 'N', 'SAGINAW BAY LIGHT', 43.81, -83.72, 43.81, -83.72, 'Thunderstorms moving through Saginaw Bay produced wind gusts around 50 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (781506, 201808, 6, 1419, 201808, 6, 1419, 130550, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '06-AUG-18 14:19:00', 'EST-5', '06-AUG-18 14:19:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'E', 'EGYPT', 1, 'E', 'EGYPT', 43.07, -77.4, 43.07, -77.4, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', 'Tree fell on a vehicle on Mason Road.');
INSERT INTO public.stormevents_east VALUES (781802, 201808, 14, 950, 201808, 14, 1150, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 09:50:00', 'EST-5', '14-AUG-18 11:50:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BUSHNELL BASIN', 2, 'SE', 'BUSHNELL BASIN', 43.0539, -77.4688, 43.0563, -77.4543, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Garnsey Road was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (781803, 201808, 14, 813, 201808, 14, 813, 130615, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '14-AUG-18 08:13:00', 'EST-5', '14-AUG-18 08:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NE', 'PHELPS', 1, 'NE', 'PHELPS', 42.96, -77.06, 42.96, -77.06, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', NULL);
INSERT INTO public.stormevents_east VALUES (781473, 201808, 8, 1604, 201808, 8, 1610, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 16:04:00', 'EST-5', '08-AUG-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'SHELBY', 2, 'S', 'STUBBS', 35.29, -81.536, 35.302, -81.485, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'County comms center reported numerous trees and power lines blown down in the Shelby area.');
INSERT INTO public.stormevents_east VALUES (781477, 201808, 8, 1606, 201808, 8, 1606, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 16:06:00', 'EST-5', '08-AUG-18 16:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'ROCKVIEW', 0, 'N', 'ROCKVIEW', 35.78, -82.43, 35.78, -82.43, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Public reported multiple large tree limbs blown down along North Fork Road.');
INSERT INTO public.stormevents_east VALUES (781478, 201808, 8, 1625, 201808, 8, 1640, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 16:25:00', 'EST-5', '08-AUG-18 16:40:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SSE', 'CHERRYVILLE', 1, 'E', 'HIGH SHOALS', 35.346, -81.367, 35.4, -81.201, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Law enforcement reported trees and power lines blown down along Sellerstown Rd with additional trees down on Mauney Rd and a tree on a home in the High Shoals area.');
INSERT INTO public.stormevents_east VALUES (781601, 201808, 8, 1644, 201808, 8, 1648, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 16:44:00', 'EST-5', '08-AUG-18 16:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SE', 'IRON STATION', 1, 'NW', 'MARIPOSA', 35.442, -81.156, 35.428, -81.084, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Amateur radio operator reported multiple trees blown down in the Iron Station area, including some blocking Highway 27. Public reported trees blown down on Mount Zion Church Rd.');
INSERT INTO public.stormevents_east VALUES (781602, 201808, 8, 1718, 201808, 8, 1744, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 17:18:00', 'EST-5', '08-AUG-18 17:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WSW', 'ROBERTA MILLS', 6, 'ENE', 'WATTS XRDS', 35.358, -80.708, 35.49, -80.371, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'County comms reported numerous trees and power lines blown down throughout Cabarrus County.');
INSERT INTO public.stormevents_east VALUES (781603, 201808, 8, 1520, 201808, 8, 1520, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'GSP', '08-AUG-18 15:20:00', 'EST-5', '08-AUG-18 15:20:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'NE', 'DUAN', 0, 'NE', 'DUAN', 35.624, -81.196, 35.624, -81.196, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Spotter reported penny size hail on Saint James Church Rd.');
INSERT INTO public.stormevents_east VALUES (781604, 201808, 8, 1549, 201808, 8, 1549, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'GSP', '08-AUG-18 15:49:00', 'EST-5', '08-AUG-18 15:49:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 3, 'NNW', 'PROPST XRDS', 3, 'NNW', 'PROPST XRDS', 35.67, -81.4, 35.67, -81.4, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Spotter reported penny size hail on Mountain Grove Rd.');
INSERT INTO public.stormevents_east VALUES (771451, 201808, 8, 1420, 201808, 8, 1420, 128612, 'TENNESSEE', 47, 2018, 'August', 'Thunderstorm Wind', 'MRX', '08-AUG-18 14:20:00', 'EST-5', '08-AUG-18 14:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'DANDRIDGE', 0, 'N', 'DANDRIDGE', 36.02, -83.42, 36.02, -83.42, 'Convection developed along an outflow boundary during the afternoon across Tennessee and Southwest North Carolina generating damaging winds.', 'A few trees were reported down.');
INSERT INTO public.stormevents_east VALUES (771452, 201808, 8, 1425, 201808, 8, 1425, 128612, 'TENNESSEE', 47, 2018, 'August', 'Thunderstorm Wind', 'MRX', '08-AUG-18 14:25:00', 'EST-5', '08-AUG-18 14:25:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'NE', 'CLOUDS', 1, 'NE', 'CLOUDS', 36.48, -83.64, 36.48, -83.64, 'Convection developed along an outflow boundary during the afternoon across Tennessee and Southwest North Carolina generating damaging winds.', 'A few trees were reported down across Buell and Sharp Road in the Powell Valley area.');
INSERT INTO public.stormevents_east VALUES (771454, 201808, 8, 1440, 201808, 8, 1440, 128612, 'TENNESSEE', 47, 2018, 'August', 'Thunderstorm Wind', 'MRX', '08-AUG-18 14:40:00', 'EST-5', '08-AUG-18 14:40:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'TAZEWELL', 1, 'NW', 'TAZEWELL', 36.46, -83.58, 36.46, -83.58, 'Convection developed along an outflow boundary during the afternoon across Tennessee and Southwest North Carolina generating damaging winds.', 'One large tree was reported down across Bill Road.');
INSERT INTO public.stormevents_east VALUES (773475, 201808, 30, 1500, 201808, 30, 1500, 129013, 'TENNESSEE', 47, 2018, 'August', 'Thunderstorm Wind', 'MRX', '30-AUG-18 15:00:00', 'EST-5', '30-AUG-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SW', 'ELIZABETHTON', 1, 'SW', 'ELIZABETHTON', 36.34, -82.23, 36.34, -82.23, 'A storm formed over the higher terrain in Carter county ahead of a weak cool frontal boundary producing enough wind energy to down a tree. The tree damaged a home as it fell.', 'A tree fell onto a home on Bear Hollow Road.');
INSERT INTO public.stormevents_east VALUES (782855, 201808, 18, 2150, 201808, 18, 2315, 130827, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'MRX', '18-AUG-18 21:50:00', 'EST-5', '18-AUG-18 23:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'ABINGDON ARPT', 2, 'E', 'ABINGDON ARPT', 36.6511, -82.03, 36.68, -81.9939, 'A humid air mass remained in place, while a frontal boundary was slowly approaching from eastern Kentucky. Nighttime convection resulted in flash flooding in southwestern Virginia.', 'Flooding on Lee Hwy between Halls Bottom Rd and Oak Park Dr.');
INSERT INTO public.stormevents_east VALUES (783304, 201808, 2, 2300, 201808, 2, 2300, 130908, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '02-AUG-18 23:00:00', 'EST-5', '02-AUG-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'An isolated thunderstorm produced gale-force wind gusts along the reef offshore Key Largo, FL.', 'A wind gust of 35 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
INSERT INTO public.stormevents_east VALUES (783306, 201808, 7, 45, 201808, 7, 45, 130911, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '07-AUG-18 00:45:00', 'EST-5', '07-AUG-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 10, 'ENE', 'DRY TORTUGAS LIGHT', 10, 'ENE', 'DRY TORTUGAS LIGHT', 24.693, -82.773, 24.693, -82.773, 'Widely scattered thunderstorms associated with a weak westward-moving surface trough produced gale-force wind gusts near Dry Tortugas National Park.', 'A wind gust of 35 knots was measured at Pulaski Shoal Light.');
INSERT INTO public.stormevents_east VALUES (783309, 201808, 7, 1859, 201808, 7, 1859, 130912, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '07-AUG-18 18:59:00', 'EST-5', '07-AUG-18 18:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', 34, 'MG', NULL, NULL, 1, 'SW', 'KEY WEST', 1, 'SW', 'KEY WEST', 24.5532, -81.7886, 24.5532, -81.7886, 'Strong thunderstorms originating over western Cuba produced a strong outflow boundary, which moved north to northwest over the Straits of Florida.  New thunderstorm growth along the outflow boundary was enhanced by the presence of a tropical upper tropospheric trough moving slowly west through the vicinity.', 'A wind gust of 34 knots was measured at the WFO Key West RSOIS instrument.');
INSERT INTO public.stormevents_east VALUES (783310, 201808, 7, 1918, 201808, 7, 1918, 130912, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '07-AUG-18 19:18:00', 'EST-5', '07-AUG-18 19:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'SMITH SHOAL LIGHT', 0, 'N', 'SMITH SHOAL LIGHT', 24.72, -81.92, 24.72, -81.92, 'Strong thunderstorms originating over western Cuba produced a strong outflow boundary, which moved north to northwest over the Straits of Florida.  New thunderstorm growth along the outflow boundary was enhanced by the presence of a tropical upper tropospheric trough moving slowly west through the vicinity.', 'A wind gust of 37 knots was measured at an automated WeatherFlow station at Smith Shoal Light.');
INSERT INTO public.stormevents_east VALUES (763350, 201808, 5, 1707, 201808, 5, 1709, 127336, 'GULF OF MEXICO', 85, 2018, 'August', 'Waterspout', 'TBW', '05-AUG-18 17:07:00', 'EST-5', '05-AUG-18 17:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 4, 'NNE', 'OLD TAMPA BAY', 4, 'N', 'OLD TAMPA BAY', 27.91, -82.56, 27.91, -82.57, 'Easterly flow led to scattered thunderstorms developing over the Florida Peninsula and pushing into the eastern Gulf of Mexico, producing gusty winds. One storm also developed a waterspout over the Tampa Bay.', 'A waterspout over the Tampa Bay was spotted from the Howard Frankland Bridge.');
INSERT INTO public.stormevents_east VALUES (768924, 201808, 13, 630, 201808, 13, 930, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 06:30:00', 'EST-5', '13-AUG-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'ROCK RUN', 0, 'S', 'ROCK RUN', 39.9938, -75.8216, 39.9954, -75.8202, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for a water rescue at the intersection of Manor Road and Butterworth Road in Coatesville.');
INSERT INTO public.stormevents_east VALUES (763195, 201808, 3, 2015, 201808, 3, 2015, 127310, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '03-AUG-18 20:15:00', 'EST-5', '03-AUG-18 20:15:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 1, 'E', 'WYOMISSING HILLS', 1, 'E', 'WYOMISSING HILLS', 40.33, -75.96, 40.33, -75.96, 'Severe thunderstorms formed across eastern Pennsylvania ahead of a cut-off upper-level low stationed over the Ohio and Tennessee River Valleys. The strongest storms occurred across the Lehigh Valley early the morning of August 2nd.', 'There were several reports of trees and wires being down within Berks County, mainly from Earl Township through Wyomissing and Reading to Exeter and Ruscombmanor Townships. The storm damage was estimated to have occurred between 9:15 pm and 9:45 pm EDT based on radar.');
INSERT INTO public.stormevents_east VALUES (765088, 201808, 13, 1845, 201808, 13, 1845, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '13-AUG-18 18:45:00', 'EST-5', '13-AUG-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'OXFORD', 1, 'N', 'OXFORD', 39.79, -75.98, 39.79, -75.98, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'A few trees down between Oxford and Mount Vernon. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (765089, 201808, 13, 1933, 201808, 13, 1933, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Thunderstorm Wind', 'PHI', '13-AUG-18 19:33:00', 'EST-5', '13-AUG-18 19:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'SW', 'CEDAR HOLLOW STATION', 1, 'SW', 'CEDAR HOLLOW STATION', 40.04, -75.51, 40.04, -75.51, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Report of large trees and limbs down in a wooded area near Paoli Hospital as well.');
INSERT INTO public.stormevents_east VALUES (768923, 201808, 13, 605, 201808, 13, 905, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 06:05:00', 'EST-5', '13-AUG-18 09:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'LANDENBERG', 1, 'N', 'LANDENBERG', 39.7779, -75.7733, 39.7973, -75.7728, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Widespread roadway flooding in New Garden Township.  Many roads were impassable including Penn Green Road and Broad Run Road.');
INSERT INTO public.stormevents_east VALUES (768925, 201808, 13, 700, 201808, 13, 1000, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:00:00', 'EST-5', '13-AUG-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'BERNHARTS', 1, 'SW', 'BERNHARTS', 40.3679, -75.9341, 40.3714, -75.9351, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the closure of the Warren Street Bypass in Muhlenberg Township between Route 61 and Business Route 222.');
INSERT INTO public.stormevents_east VALUES (768926, 201808, 13, 730, 201808, 13, 1030, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:30:00', 'EST-5', '13-AUG-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WAYNE', 0, 'SE', 'WAYNE', 40.0438, -75.3941, 40.0467, -75.3943, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for water rescues between Banbury Way and South Bellevue Avenue in Wayne.');
INSERT INTO public.stormevents_east VALUES (768927, 201808, 13, 720, 201808, 13, 1020, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:20:00', 'EST-5', '13-AUG-18 10:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'PLANEBROOK', 1, 'E', 'PLANEBROOK', 40.0473, -75.5643, 40.0479, -75.5632, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for a water rescue on Church Road in East Whiteland Township where it intersected the Chester Valley Trail.');
INSERT INTO public.stormevents_east VALUES (740214, 201804, 15, 700, 201804, 16, 700, 123444, 'VIRGINIA', 51, 2018, 'April', 'Heavy Rain', 'RNK', '15-APR-18 07:00:00', 'EST-5', '16-APR-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 13, 'SSE', 'CLIFFDALE', 13, 'SSE', 'CLIFFDALE', 37.496, -79.954, 37.496, -79.954, 'A strong cold front propelled by a deep upper trough that took on a negative tilt, pushed through the region on April 15 producing severe weather and heavy rainfall. The speed of convective elements prevented any flash flooding but longer duration flooding occurred on several rivers and streams, mainly in the minor category. Rainfall ranged from 2 to 4 inches with locally higher amounts up to nearly 4.5 inches in 24-hours ending at 7 AM on the 16th. The highest amounts were roughly a 5-year recurrence interval (0.2 Annual exceedance probability).', 'The COOP station at Gathright Dam (GDMV2) measured 2.80 inches for the 24-hour period ending 7AM on the 16th. This was the 3rd highest 1-day April rainfall total in the period of record at this location, with data starting in 1981.');
INSERT INTO public.stormevents_east VALUES (779595, 201808, 11, 1800, 201808, 11, 1830, 130182, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '11-AUG-18 18:00:00', 'EST-5', '11-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'LITTLE FALLS', 1, 'ENE', 'LITTLE FALLS', 40.886, -74.2168, 40.885, -74.2183, 'A stalled stationary boundary within a very moist airmass provided a focusing mechanism for several rounds of heavy rain that resulted in widespread flash flooding across northeast New Jersey. The Caldwell, NJ ASOS recorded 4.92 inches of rain, and multiple other stations across northeast New Jersey received between 2.5 inches and 4 inches of precipitation. The Little Falls area of Passaic County was particularly hard hit when rising water from the Peckman River swept away numerous cars from the Route 46 Chrysler, Jeep, Dodge dealership.', 'Multiple cars parked at the Route 46 Chrysler Jeep Dodge dealer along the Peckman River in Little Falls were swept into the river when it flooded.||Media reports later indicated that a total of 42 cars were swept away from the Chrysler Jeep Dodge dealership and that an additional 200 cars were damaged due to the flooding at the McGuire Buick dealership next door. Overall, approximately 190 homes and numerous vehicles were impacted by flood waters in Little Falls, with 32 homes deemed uninhabitable. All of the uninhabitable homes were located in the Jackson Park area.');
INSERT INTO public.stormevents_east VALUES (780004, 201808, 26, 2345, 201808, 26, 2345, 130281, 'MICHIGAN', 26, 2018, 'August', 'Thunderstorm Wind', 'DTX', '26-AUG-18 23:45:00', 'EST-5', '26-AUG-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'VASSAR', 0, 'N', 'VASSAR', 43.37, -83.58, 43.37, -83.58, 'Thunderstorms brought down trees in Saginaw and Tuscola Counties.', 'Several trees reported down around Vassar.');
INSERT INTO public.stormevents_east VALUES (780005, 201808, 27, 27, 201808, 27, 27, 130281, 'MICHIGAN', 26, 2018, 'August', 'Thunderstorm Wind', 'DTX', '27-AUG-18 00:27:00', 'EST-5', '27-AUG-18 00:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'SW', 'KINGSTON', 1, 'SW', 'KINGSTON', 43.41, -83.19, 43.41, -83.19, 'Thunderstorms brought down trees in Saginaw and Tuscola Counties.', 'Several trees reported down around the Kingston Area.');
INSERT INTO public.stormevents_east VALUES (780017, 201808, 28, 2020, 201808, 28, 2020, 130289, 'LAKE HURON', 90, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '28-AUG-18 20:20:00', 'EST-5', '28-AUG-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 40, 'MG', NULL, NULL, 8, 'ESE', 'POINT AU GRES', 8, 'ESE', 'POINT AU GRES', 43.9257, -83.5014, 43.9257, -83.5014, 'Thunderstorms moving through Saginaw Bay produced with gusts to 60 mph.', NULL);
INSERT INTO public.stormevents_east VALUES (780074, 201808, 12, 2011, 201808, 12, 2030, 130301, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '12-AUG-18 20:11:00', 'EST-5', '12-AUG-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'ALBEMARLE', 1, 'W', 'ALBEMARLE', 35.36, -80.24, 35.3679, -80.2345, 'Upper low closed off over eastern Ohio, with high precipitable water values over central and eastern North Carolina with improving deep layer shear and 1500-3000 J/kg of MLCAPE fueled numerous storms and storm clusters from early afternoon through the evening. Locally heavy downpours resulted in isolated flash flooding and isolated strong to severe storms.', 'Highway 73 at City Lake Drive was closed due to flooding, along with smaller back roads.');
INSERT INTO public.stormevents_east VALUES (779811, 201808, 31, 2336, 201808, 31, 2336, 128593, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '31-AUG-18 23:36:00', 'EST-5', '31-AUG-18 23:36:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'S', 'STONEVILLE', 2, 'S', 'STONEVILLE', 36.4443, -79.9016, 36.4443, -79.9016, 'A hot and humid air mass sparked one severe thunderstorm during the evening.  This storm blew down three trees in Rockingham County.', 'Thunderstorm winds blew down a tree onto Phil Road.');
INSERT INTO public.stormevents_east VALUES (780697, 201808, 8, 1515, 201808, 8, 1516, 130423, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'IWX', '08-AUG-18 15:15:00', 'EST-5', '08-AUG-18 15:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 55, 'EG', NULL, NULL, 1, 'SW', 'DESHLER', 1, 'SW', 'DESHLER', 41.21, -83.91, 41.21, -83.91, 'Stalled frontal boundary remained the focus for thunderstorms into the 8th with marginal shear profiles and sufficient instability allowing for a few strong to severe storms.', 'A trained spotter reported tree branches ranging from six to twelve inches in diameter broken off trees near the intersection of SR 18 and Vine St.');
INSERT INTO public.stormevents_east VALUES (781613, 201808, 2, 1500, 201808, 2, 1500, 130587, 'LAKE HURON', 90, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '02-AUG-18 15:00:00', 'EST-5', '02-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 0, 'N', 'SAGINAW BAY LIGHT', 0, 'N', 'SAGINAW BAY LIGHT', 43.81, -83.72, 43.81, -83.72, 'Thunderstorms moving through Saginaw Bay produced wind gusts around 50 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (767505, 201808, 12, 2130, 201808, 13, 0, 127962, 'SOUTH CAROLINA', 45, 2018, 'August', 'Heavy Rain', 'CAE', '12-AUG-18 21:30:00', 'EST-5', '13-AUG-18 00:00:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', NULL, NULL, NULL, NULL, 1, 'E', '(SSC)SHAW AFB SUMTER', 1, 'E', '(SSC)SHAW AFB SUMTER', 33.97, -80.47, 33.97, -80.47, 'Thunderstorms developed in a moist environment and produced locally heavy rain on the night of August 12th into the very early morning hours on August 13th.', 'Automated gage at Shaw AFB near Sumter measured 2.35 inches of rain in about a two and a half hour period ending at around 0100 EDT (0000 EST).  1.13 inches of this fell in about a half hour roughly between 2230 EDT (2130 EST) and 2300 EDT (2200 EST).');
INSERT INTO public.stormevents_east VALUES (774366, 201807, 17, 1400, 201807, 17, 1600, 128271, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '17-JUL-18 14:00:00', 'EST-5', '17-JUL-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'GARLAND', 1, 'SW', 'GARLAND', 39.16, -76.66, 39.1624, -76.6567, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding and isolated flash flooding, mainly in the Baltimore metro area.', 'High water of unknown depth forced the closure of Maryland 176 between Wirth Road and WB&A Road.');
INSERT INTO public.stormevents_east VALUES (761645, 201805, 31, 1800, 201805, 31, 1810, 127106, 'GULF OF MEXICO', 85, 2018, 'May', 'Waterspout', 'KEY', '31-MAY-18 18:00:00', 'EST-5', '31-MAY-18 18:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 2, 'NNW', 'PLANTATION KEY', 2, 'NNW', 'PLANTATION KEY', 25.0065, -80.5689, 25.0065, -80.5689, 'An isolated waterspout was observed in association with a rain shower in Florida Bay.', 'A waterspout was observed about 2 miles north of Plantation Key.');
INSERT INTO public.stormevents_east VALUES (774367, 201807, 17, 1413, 201807, 17, 1600, 128271, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '17-JUL-18 14:13:00', 'EST-5', '17-JUL-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'NORTH LINTHICUM', 1, 'S', 'NORTH LINTHICUM', 39.2084, -76.6499, 39.208, -76.6494, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding and isolated flash flooding, mainly in the Baltimore metro area.', 'The ramp from the Baltimore Beltway to Camp Meade Road at Exit 6A was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (774368, 201807, 17, 1450, 201807, 17, 1700, 128271, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '17-JUL-18 14:50:00', 'EST-5', '17-JUL-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'POPLAR', 1, 'N', 'POPLAR', 39.3656, -76.4508, 39.3649, -76.4514, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding and isolated flash flooding, mainly in the Baltimore metro area.', 'Philadelphia Road flooded and closed south of Campbell Boulevard.');
INSERT INTO public.stormevents_east VALUES (774369, 201807, 17, 1510, 201807, 17, 1700, 128271, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '17-JUL-18 15:10:00', 'EST-5', '17-JUL-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'EMMORTON', 1, 'ENE', 'EMMORTON', 39.5029, -76.3069, 39.5027, -76.3068, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding and isolated flash flooding, mainly in the Baltimore metro area.', 'One foot of water over the roadway on Wheel Road near Cedar Lane.');
INSERT INTO public.stormevents_east VALUES (760723, 201805, 14, 1425, 201805, 14, 1425, 126920, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'PBZ', '14-MAY-18 14:25:00', 'EST-5', '14-MAY-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 0, 'NW', 'VALLEY PT', 0, 'NW', 'VALLEY PT', 39.5835, -79.636, 39.5835, -79.636, 'A stationary front continued to linger in the vicinity of the Mason-Dixon Line.  A marked temperature contrast existed across the front, with values in the 50s over northwestern Pennsylvania and numbers well into the 80s over northern West Virginia. This boundary helped to produce more severe weather during the afternoon and evening hours.  Storms with hail larger than quarters and downed trees were reported, along with isolated flooding.', 'The public reported hail around dime size at the Quick Stop south of Bruceton Mills.');
INSERT INTO public.stormevents_east VALUES (782127, 201808, 11, 1705, 201808, 11, 1930, 128318, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'AKQ', '11-AUG-18 17:05:00', 'EST-5', '11-AUG-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'NORFOLK', 2, 'E', 'NORFOLK', 36.87, -76.23, 36.8688, -76.23, 'Scattered thunderstorms in advance of a frontal boundary produced heavy rain which caused flash flooding across portions of southeast Virginia.', 'Neighborhood roadways were flooded. Rainfall total of 2.19 inches was measured in 45 minutes.');
INSERT INTO public.stormevents_east VALUES (782125, 201808, 17, 2328, 201808, 17, 2358, 130691, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '17-AUG-18 23:28:00', 'EST-5', '17-AUG-18 23:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'EAST NEWARK', 1, 'SSW', 'EAST NEWARK', 40.7399, -74.1561, 40.74, -74.1553, 'Showers and thunderstorms developed in a warm and humid environment ahead of an approaching cold front, resulting in isolated flash flooding across portions of urban northeast New Jersey. These storms brought 1-2 inches of rain to the region in a matter of hours, with a cooperative observer in Harrison, NJ recording 1.79 inches of rain during the event.', 'Cars were stuck in flood waters with water rescues underway on Frank E Rodgers Boulevard at the PATH train station in Harrison.');
INSERT INTO public.stormevents_east VALUES (769597, 201808, 11, 1723, 201808, 11, 1930, 128318, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'AKQ', '11-AUG-18 17:23:00', 'EST-5', '11-AUG-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NORFOLK', 1, 'W', 'NORFOLK', 36.8717, -76.2961, 36.8715, -76.2958, 'Scattered thunderstorms in advance of a frontal boundary produced heavy rain which caused flash flooding across portions of southeast Virginia.', 'Colley Avenue was closed due to flooding at the underpass. One vehicle was caught in the flood waters.');
INSERT INTO public.stormevents_east VALUES (782144, 201808, 12, 1728, 201808, 12, 1728, 130708, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'AKQ', '12-AUG-18 17:28:00', 'EST-5', '12-AUG-18 17:28:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ESE', 'BURROWSVILLE', 1, 'ESE', 'BURROWSVILLE', 37.21, -77.06, 37.21, -77.06, 'Isolated severe thunderstorm associated with a trough of low pressure produced damaging winds across portions of central Virginia.', 'Trees were downed along James River Drive (Route 10).');
INSERT INTO public.stormevents_east VALUES (781831, 201808, 17, 1810, 201808, 17, 1810, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 18:10:00', 'EST-5', '17-AUG-18 18:10:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NW', 'GANSEVOORT', 2, 'NW', 'GANSEVOORT', 43.22, -73.71, 43.22, -73.71, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (781830, 201808, 17, 1810, 201808, 17, 1810, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 18:10:00', 'EST-5', '17-AUG-18 18:10:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'GREENFIELD CENTER', 1, 'E', 'GREENFIELD CENTER', 43.13, -73.85, 43.13, -73.85, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees were downed.');
INSERT INTO public.stormevents_east VALUES (781832, 201808, 17, 1930, 201808, 17, 1930, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 19:30:00', 'EST-5', '17-AUG-18 19:30:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'CHATHAM', 1, 'W', 'CHATHAM', 42.35, -73.61, 42.35, -73.61, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Numerous wires down in Ghent.');
INSERT INTO public.stormevents_east VALUES (781833, 201808, 17, 1940, 201808, 17, 1940, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 19:40:00', 'EST-5', '17-AUG-18 19:40:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'OMI', 0, 'N', 'OMI', 42.32, -73.68, 42.32, -73.68, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Wires down across a road in the town of Ghent.');
INSERT INTO public.stormevents_east VALUES (774910, 201807, 22, 1521, 201807, 22, 1630, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 15:21:00', 'EST-5', '22-JUL-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'HUNTINGTOWN', 1, 'NNW', 'HUNTINGTOWN', 38.641, -76.6266, 38.6411, -76.6262, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Stephen Reid Road flooded and closed near Cocktown Creek.');
INSERT INTO public.stormevents_east VALUES (774911, 201807, 22, 1742, 201807, 22, 1900, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 17:42:00', 'EST-5', '22-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'DUNKIRK', 1, 'SE', 'DUNKIRK', 38.7092, -76.6522, 38.7094, -76.6519, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Southbound Maryland Route 4 flooded and closed at Hall Creek.');
INSERT INTO public.stormevents_east VALUES (774913, 201807, 22, 1822, 201807, 22, 2000, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 18:22:00', 'EST-5', '22-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'MATTAWOMAN', 1, 'ESE', 'MATTAWOMAN', 38.6461, -76.8565, 38.6457, -76.8562, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Pinefield Road flooded and closed near Alfred Drive.');
INSERT INTO public.stormevents_east VALUES (774914, 201807, 22, 1918, 201807, 22, 2030, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 19:18:00', 'EST-5', '22-JUL-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'RIVA', 2, 'SSW', 'RIVA', 38.9272, -76.5903, 38.9271, -76.5894, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'Central Avenue flooded and closed at Beards Creek.');
INSERT INTO public.stormevents_east VALUES (764516, 201808, 10, 2058, 201808, 10, 2258, 127532, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '10-AUG-18 20:58:00', 'EST-5', '10-AUG-18 22:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'XENIA', 1, 'SW', 'XENIA', 39.69, -83.94, 39.6658, -83.945, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'Some high water was reported on a few streets.');
