INSERT INTO public.stormevents_east VALUES (764523, 201808, 11, 940, 201808, 11, 1140, 127533, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '11-AUG-18 09:40:00', 'EST-5', '11-AUG-18 11:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'SOUTH COLUMBUS', 2, 'N', 'SOUTH COLUMBUS', 39.9459, -82.9947, 39.953, -82.9932, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'Underpasses were flooded on the south side of Columbus, with some cars stuck in the water.');
