INSERT INTO public.stormevents_east VALUES (764526, 201808, 11, 1159, 201808, 11, 1359, 127533, 'OHIO', 39, 2018, 'August', 'Flood', 'ILN', '11-AUG-18 11:59:00', 'EST-5', '11-AUG-18 13:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'SOUTH COLUMBUS', 2, 'SW', 'SOUTH COLUMBUS', 39.8918, -83.0245, 39.8915, -83.0289, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'State Route 104 had six to eight inches of water over the road.');
