INSERT INTO public.stormevents_east VALUES (764530, 201808, 11, 1435, 201808, 11, 1635, 127534, 'KENTUCKY', 21, 2018, 'August', 'Flash Flood', 'ILN', '11-AUG-18 14:35:00', 'EST-5', '11-AUG-18 16:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'FERRY VANCEBURG', 1, 'SSW', 'FERRY VANCEBURG', 38.58, -83.33, 38.5818, -83.327, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'Water was reported flowing over a portion of KY-59.');
INSERT INTO public.stormevents_east VALUES (777891, 201808, 3, 1315, 201808, 3, 1315, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '03-AUG-18 13:15:00', 'EST-5', '03-AUG-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'OWENS', 1, 'SSE', 'OWENS', 35.0422, -78.9439, 35.0422, -78.9439, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'One tree was reported down at Faison Avenue and John Marshall Road.');
INSERT INTO public.stormevents_east VALUES (777892, 201808, 3, 1412, 201808, 3, 1412, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '03-AUG-18 14:12:00', 'EST-5', '03-AUG-18 14:12:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'S', 'SOUTH RALEIGH ARPT', 0, 'S', 'SOUTH RALEIGH ARPT', 35.6167, -78.7002, 35.6167, -78.7002, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Power lines were reported down in the 3800 block of Air Park Road.');
