INSERT INTO public.stormevents_east VALUES (777894, 201808, 3, 1430, 201808, 3, 1430, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '03-AUG-18 14:30:00', 'EST-5', '03-AUG-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'W', '(RDU)RALEIGH-DURHAM', 3, 'W', '(RDU)RALEIGH-DURHAM', 35.867, -78.8274, 35.867, -78.8274, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'One tree was reported down at Slater Road and Carrington Mill Boulevard.');
INSERT INTO public.stormevents_east VALUES (777895, 201808, 3, 1431, 201808, 3, 1431, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '03-AUG-18 14:31:00', 'EST-5', '03-AUG-18 14:31:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'WILDERS GROVE', 2, 'SW', 'WILDERS GROVE', 35.7804, -78.5969, 35.7804, -78.5969, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'One tree was reported down at New Bern Avenue and King William Road.');
INSERT INTO public.stormevents_east VALUES (781804, 201808, 14, 920, 201808, 14, 920, 130615, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '14-AUG-18 09:20:00', 'EST-5', '14-AUG-18 09:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'W', 'BLACKWATCH HILLS', 1, 'W', 'BLACKWATCH HILLS', 43.1, -77.44, 43.1, -77.44, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', NULL);
INSERT INTO public.stormevents_east VALUES (781805, 201808, 14, 920, 201808, 14, 920, 130615, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '14-AUG-18 09:20:00', 'EST-5', '14-AUG-18 09:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'NE', 'WALWORTH', 1, 'NE', 'WALWORTH', 43.14, -77.27, 43.14, -77.27, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', NULL);
