INSERT INTO public.stormevents_east VALUES (781807, 201808, 14, 1510, 201808, 14, 1510, 130615, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '14-AUG-18 15:10:00', 'EST-5', '14-AUG-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'S', 'BLACKWATCH HILLS', 1, 'S', 'BLACKWATCH HILLS', 43.09, -77.43, 43.09, -77.43, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', NULL);
INSERT INTO public.stormevents_east VALUES (781808, 201808, 14, 1600, 201808, 14, 1600, 130615, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '14-AUG-18 16:00:00', 'EST-5', '14-AUG-18 16:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'PULASKI', 0, 'N', 'PULASKI', 43.57, -76.13, 43.57, -76.13, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Rainfall fell between 1 and 5 PM. Basement flooding was also reported.');
INSERT INTO public.stormevents_east VALUES (781809, 201808, 14, 1600, 201808, 14, 1600, 130615, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '14-AUG-18 16:00:00', 'EST-5', '14-AUG-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 0, 'N', 'MACEDON', 0, 'N', 'MACEDON', 43.07, -77.3, 43.07, -77.3, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', NULL);
INSERT INTO public.stormevents_east VALUES (782197, 201808, 7, 545, 201808, 7, 545, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 05:45:00', 'EST-5', '07-AUG-18 05:45:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 52, 'EG', NULL, NULL, 0, 'N', 'ALLAGASH', 0, 'N', 'ALLAGASH', 47.08, -69.05, 47.08, -69.05, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'A tree was toppled by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (781605, 201808, 8, 1610, 201808, 8, 1610, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'GSP', '08-AUG-18 16:10:00', 'EST-5', '08-AUG-18 16:10:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'ESE', 'HILDEBRAN', 1, 'ESE', 'HILDEBRAN', 35.712, -81.415, 35.712, -81.415, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Public reported quarter size hail On 3rd St Southeast.');
INSERT INTO public.stormevents_east VALUES (781606, 201808, 8, 1657, 201808, 8, 1657, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'GSP', '08-AUG-18 16:57:00', 'EST-5', '08-AUG-18 16:57:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1.5, NULL, NULL, NULL, 1, 'SE', 'MT MOURNE', 1, 'SE', 'MT MOURNE', 35.537, -80.831, 35.537, -80.831, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Public reported (via Social Media) ping pong ball size hail along Faith Rd.');
INSERT INTO public.stormevents_east VALUES (781607, 201808, 8, 1706, 201808, 8, 1706, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'GSP', '08-AUG-18 17:06:00', 'EST-5', '08-AUG-18 17:06:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 1, 'ESE', 'MOORESVILLE', 1, 'ESE', 'MOORESVILLE', 35.57, -80.8, 35.57, -80.8, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Public reported penny size hail in the Mooresville area.');
INSERT INTO public.stormevents_east VALUES (781900, 201808, 8, 1522, 201808, 8, 1531, 130540, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 15:22:00', 'EST-5', '08-AUG-18 15:31:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', 55, 'EG', NULL, NULL, 1, 'W', 'ROEBUCK', 1, 'SW', 'ARKWRIGHT', 34.883, -81.992, 34.909, -81.94, 'Scattered thunderstorms developed during the afternoon near the South Carolina Blue Ridge, with storms gradually spreading south and east along outflow boundaries throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'EM reported numerous trees and power lines blown down in the Roebuck area, with one tree falling on and destroying a carport along Old Airport Rd.');
INSERT INTO public.stormevents_east VALUES (782106, 201808, 8, 1722, 201808, 8, 1722, 130541, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 17:22:00', 'EST-5', '08-AUG-18 17:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SE', 'ENOCHVILLE', 1, 'SE', 'ENOCHVILLE', 35.52, -80.67, 35.52, -80.67, 'Scattered thunderstorms developed across the North Carolina Blue Ridge during the afternoon, with storms developing gradually along outflows into the Piedmont throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Spotter reported multiple trees blown down near Enochville.');
INSERT INTO public.stormevents_east VALUES (782107, 201808, 8, 1707, 201808, 8, 1707, 130540, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 17:07:00', 'EST-5', '08-AUG-18 17:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'W', 'CHESTER', 0, 'W', 'CHESTER', 34.7, -81.201, 34.7, -81.201, 'Scattered thunderstorms developed during the afternoon near the South Carolina Blue Ridge, with storms gradually spreading south and east along outflow boundaries throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Amateur radio operator reported trees blown down along Harris and Hardin streets.');
INSERT INTO public.stormevents_east VALUES (782111, 201808, 8, 1845, 201808, 8, 1904, 130540, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '08-AUG-18 18:45:00', 'EST-5', '08-AUG-18 19:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'S', 'GRAY COURT', 3, 'E', 'COLD PT', 34.596, -82.12, 34.417, -81.99, 'Scattered thunderstorms developed during the afternoon near the South Carolina Blue Ridge, with storms gradually spreading south and east along outflow boundaries throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Highway Patrol and the public reported at least a half dozen trees blown down from near Gray Court to areas just west and south of Laurens.');
INSERT INTO public.stormevents_east VALUES (783315, 201808, 10, 1527, 201808, 10, 1527, 130913, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '10-AUG-18 15:27:00', 'EST-5', '10-AUG-18 15:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 47, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR REEF LIGHT', 0, 'N', 'ALLIGATOR REEF LIGHT', 24.85, -80.62, 24.85, -80.62, 'Numerous showers and thunderstorms developing along seabreeze fronts over mainland south Florida propagated southward across Florida Bay and the upper Florida Keys.  Isolated gale-force wind gusts occurred along the reef as the cold pool from mainland thunderstorms spread southward into the Atlantic.', 'A wind gust of 47 knots was measured at an automated WeatherFlow station at Alligator Reef Light.');
INSERT INTO public.stormevents_east VALUES (783316, 201808, 11, 1722, 201808, 11, 1722, 130915, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '11-AUG-18 17:22:00', 'EST-5', '11-AUG-18 17:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 13, 'ENE', 'LAYTON', 13, 'ENE', 'LAYTON', 24.9189, -80.6351, 24.9189, -80.6351, 'An isolated thunderstorm embedded within a moist, weakly-inhibited environment produced an isolated gale-force wind gust over Islamorada, FL.', 'A wind gust of 34 knots was measured at an automated WeatherFlow station on Upper Matecumbe Key.');
INSERT INTO public.stormevents_east VALUES (783318, 201808, 14, 500, 201808, 14, 500, 130916, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '14-AUG-18 05:00:00', 'EST-5', '14-AUG-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mariner', 35, 'MG', NULL, NULL, 11, 'S', 'COSGROVE SHOAL LIGHT', 11, 'S', 'COSGROVE SHOAL LIGHT', 24.3, -82.19, 24.3, -82.19, 'An isolated gale-force wind gust was observed in association with a thunderstorm over the open Straits of Florida well southwest of Key West.', 'A wind gust of 35 knots was measured by the NOAA Research Vessel Oregon II about 32 miles southwest of Key West.');
INSERT INTO public.stormevents_east VALUES (783319, 201808, 15, 2028, 201808, 15, 2028, 130917, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '15-AUG-18 20:28:00', 'EST-5', '15-AUG-18 20:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'E', 'KEY WEST', 2, 'E', 'KEY WEST', 24.5571, -81.7554, 24.5571, -81.7554, 'Thunderstorms propagating along a northward-moving outflow boundary produced isolated gale-force wind gusts at Key West.', 'A wind gust of 34 knots was measured at Key West International Airport.');
INSERT INTO public.stormevents_east VALUES (783320, 201808, 21, 1758, 201808, 21, 1803, 130918, 'GULF OF MEXICO', 85, 2018, 'August', 'Waterspout', 'KEY', '21-AUG-18 17:58:00', 'EST-5', '21-AUG-18 18:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 7, 'WNW', 'KEY WEST', 7, 'WNW', 'KEY WEST', 24.61, -81.88, 24.61, -81.88, 'Several waterspouts were observed in association with a regenerative cumulus cloud line streaming along the north side of the lower Florida Keys.', 'Two waterspouts were observed about 7 miles west-northwest of the NWS office in Key West.  The condensation funnel clouds, one thin and one of medium width, only extended about one-fifth of the way from cloud base to the horizon.  Movement of the waterspout was toward the southwest around 5 knots.');
INSERT INTO public.stormevents_east VALUES (783322, 201808, 21, 1806, 201808, 21, 1831, 130918, 'GULF OF MEXICO', 85, 2018, 'August', 'Waterspout', 'KEY', '21-AUG-18 18:06:00', 'EST-5', '21-AUG-18 18:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 7, 'NW', 'BIG COPPITT KEY', 7, 'NW', 'BIG COPPITT KEY', 24.66, -81.78, 24.66, -81.78, 'Several waterspouts were observed in association with a regenerative cumulus cloud line streaming along the north side of the lower Florida Keys.', 'Four waterspouts were observed north of the Florida Keys NWS Office in Key West, associated with a rain shower.  One condensation funnel cloud was medium width and extended to the surface with a visible spray ring.  The other three condensation funnel clouds were thin and extended about one-firth the way from cloud base to the horizon.  Movement of the waterspouts was toward the southwest.');
INSERT INTO public.stormevents_east VALUES (783330, 201808, 23, 1105, 201808, 23, 1110, 130921, 'GULF OF MEXICO', 85, 2018, 'August', 'Waterspout', 'KEY', '23-AUG-18 11:05:00', 'EST-5', '23-AUG-18 11:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 4, 'SE', 'SAND KEY LIGHT', 4, 'SE', 'SAND KEY LIGHT', 24.42, -81.83, 24.42, -81.83, 'An isolated brief waterspout was observed in association with an isolated rain shower southwest of Key West.', 'A waterspout was reported via social media, located about four miles southeast of Sand Key Light.');
INSERT INTO public.stormevents_east VALUES (765075, 201808, 13, 900, 201808, 13, 905, 127599, 'NEW JERSEY', 34, 2018, 'August', 'Funnel Cloud', 'PHI', '13-AUG-18 09:00:00', 'EST-5', '13-AUG-18 09:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 6, 'E', 'LAVALLETTE', 6, 'E', 'CHADWICK', 39.98, -73.95, 39.9868, -73.9631, 'Two separate reports of waterspouts just offshore during the flash flooding event.', 'Skywarn spotter reported a funnel cloud ongoing at 10:04am EDT just offshore of Seaside Heights. Location estimated from radar.  No damage or injuries were reported.');
INSERT INTO public.stormevents_east VALUES (768928, 201808, 13, 725, 201808, 13, 1030, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:25:00', 'EST-5', '13-AUG-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BOOTHWYN', 1, 'N', 'BOOTHWYN', 39.8478, -75.4553, 39.8468, -75.4543, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for a water rescue at the intersection of Larkin Road and Woodstream Road in Boothwyn.');
INSERT INTO public.stormevents_east VALUES (768929, 201808, 13, 740, 201808, 13, 1040, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:40:00', 'EST-5', '13-AUG-18 10:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'BERWYN', 1, 'NNE', 'CHESTERBROOK', 40.0455, -75.4164, 40.086, -75.4385, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'At least three water rescues took place in Tredyffrin Township due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (768930, 201808, 13, 730, 201808, 13, 1030, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:30:00', 'EST-5', '13-AUG-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'RADNOR', 0, 'NNW', 'ITHAN', 40.0461, -75.3541, 40.0317, -75.3713, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding occurred along Interstate 476 in Radnor Township resulting in lane restrictions in both directions.');
INSERT INTO public.stormevents_east VALUES (768931, 201808, 13, 745, 201808, 13, 1045, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:45:00', 'EST-5', '13-AUG-18 10:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'DREXEL HILL', 0, 'WSW', 'ARLINGTON', 39.954, -75.3177, 39.9696, -75.2815, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for numerous water rescues in Upper Darby Township.');
INSERT INTO public.stormevents_east VALUES (768932, 201808, 13, 720, 201808, 13, 1030, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:20:00', 'EST-5', '13-AUG-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'GREEN TREE', 1, 'SSE', 'MALVERN', 40.0298, -75.4799, 40.0161, -75.5216, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for several water rescues in Willistown Township.');
INSERT INTO public.stormevents_east VALUES (768935, 201808, 13, 825, 201808, 13, 1030, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:25:00', 'EST-5', '13-AUG-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'KING OF PRUSSIA', 1, 'W', 'KING OF PRUSSIA', 40.0755, -75.3641, 40.0789, -75.4014, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'At least two water rescues took place in Upper Merion Township due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (768936, 201808, 13, 915, 201808, 13, 1115, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 09:15:00', 'EST-5', '13-AUG-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'NE', 'PHILADELPHIA', 3, 'SE', 'WAYNE JCT', 39.9785, -75.135, 39.9871, -75.1341, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Several homes were flooded in the Kensington section of Philadelphia.');
INSERT INTO public.stormevents_east VALUES (791241, 201811, 2, 2014, 201811, 2, 2025, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 20:14:00', 'EST-5', '02-NOV-18 20:25:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'LONG BRANCH ES (ARLNL)', 0, 'N', 'LONG BRANCH ES (ARLNL)', 38.87, -77.09, 38.87, -77.09, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed in Arlington, VA.');
INSERT INTO public.stormevents_east VALUES (791243, 201811, 2, 2019, 201811, 2, 2019, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 20:19:00', 'EST-5', '02-NOV-18 20:19:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'NATIONALS PARK (WSHNP)', 0, 'N', 'NATIONALS PARK (WSHNP)', 38.87, -77.01, 38.87, -77.01, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 37 knots was measured at Nationals Park.');
INSERT INTO public.stormevents_east VALUES (767506, 201808, 12, 2211, 201808, 12, 2211, 127962, 'SOUTH CAROLINA', 45, 2018, 'August', 'Lightning', 'CAE', '12-AUG-18 22:11:00', 'EST-5', '12-AUG-18 22:11:00', 0, 0, 0, 0, NULL, '0.10K', 'Law Enforcement', NULL, NULL, NULL, NULL, 2, 'WNW', 'SUMTER', 2, 'WNW', 'SUMTER', 33.93, -80.38, 33.93, -80.38, 'Thunderstorms developed in a moist environment and produced locally heavy rain on the night of August 12th into the very early morning hours on August 13th.', 'Sumter dispatch reported a lightning strike to an apartment complex on Alice Dr that caused a fire.  The extent of the damage was unknown, but several persons were displaced.  No injuries.');
INSERT INTO public.stormevents_east VALUES (767507, 201808, 12, 2330, 201808, 12, 2350, 127962, 'SOUTH CAROLINA', 45, 2018, 'August', 'Flash Flood', 'CAE', '12-AUG-18 23:30:00', 'EST-5', '12-AUG-18 23:50:00', 0, 0, 0, 0, '0.10K', '0.10K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'SUMTER', 1, 'ENE', 'SUMTER', 33.9249, -80.3371, 33.9238, -80.3373, 'Thunderstorms developed in a moist environment and produced locally heavy rain on the night of August 12th into the very early morning hours on August 13th.', 'Flooding with stranded vehicles at Calhoun St and Lafayette Dr in Sumter. Time estimated.');
INSERT INTO public.stormevents_east VALUES (767509, 201808, 12, 600, 201808, 13, 600, 127962, 'SOUTH CAROLINA', 45, 2018, 'August', 'Heavy Rain', 'CAE', '12-AUG-18 06:00:00', 'EST-5', '13-AUG-18 06:00:00', 0, 0, 0, 0, NULL, NULL, 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'E', 'CANE SAVANNAH', 2, 'E', 'CANE SAVANNAH', 33.8952, -80.4076, 33.8952, -80.4076, 'Thunderstorms developed in a moist environment and produced locally heavy rain on the night of August 12th into the very early morning hours on August 13th.', 'CoCoRaHS observer reported a total of 4.71 inches of rain in the 24 hour period ending around 0700 EDT (0600 EST).  Most of this rain fell in thunderstorm activity during the late night hours of 8/12.');
INSERT INTO public.stormevents_east VALUES (767510, 201808, 12, 600, 201808, 13, 600, 127962, 'SOUTH CAROLINA', 45, 2018, 'August', 'Heavy Rain', 'CAE', '12-AUG-18 06:00:00', 'EST-5', '13-AUG-18 06:00:00', 0, 0, 0, 0, NULL, NULL, 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'WNW', 'SUMTER', 2, 'WNW', 'SUMTER', 33.9322, -80.3743, 33.9322, -80.3743, 'Thunderstorms developed in a moist environment and produced locally heavy rain on the night of August 12th into the very early morning hours on August 13th.', 'CoCoRaHS observer reported a total of 4.00 inches of rain in the 24 hour period ending around 0700 EDT (0600 EST).  Most of this rain fell in thunderstorm activity during the late night hours of 8/12.');
INSERT INTO public.stormevents_east VALUES (748577, 201804, 15, 1545, 201804, 15, 1545, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 15:45:00', 'EST-5', '15-APR-18 15:45:00', 0, 0, 0, 0, '10.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'WALNUT COVE', 1, 'SE', 'WALNUT COVE', 36.2954, -80.1416, 36.2954, -80.1416, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Several trees and power lines were blown down around the community of Walnut Cove.');
INSERT INTO public.stormevents_east VALUES (748575, 201804, 15, 1535, 201804, 15, 1535, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 15:35:00', 'EST-5', '15-APR-18 15:35:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'GERMANTON', 1, 'S', 'GERMANTON', 36.2625, -80.2309, 36.2625, -80.2309, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Several trees were blown down by thunderstorm winds around the community of Germanton.');
INSERT INTO public.stormevents_east VALUES (748580, 201804, 15, 1542, 201804, 15, 1542, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 15:42:00', 'EST-5', '15-APR-18 15:42:00', 0, 0, 0, 0, '3.00K', NULL, 'Public', 50, 'EG', NULL, NULL, 3, 'WNW', 'ROSEBUD', 3, 'WNW', 'ROSEBUD', 36.33, -80.23, 36.33, -80.23, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Multiple large oak trees uprooted or snapped in half, and shingles blown off a house.');
INSERT INTO public.stormevents_east VALUES (748596, 201804, 15, 1330, 201804, 15, 1330, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 13:30:00', 'EST-5', '15-APR-18 13:30:00', 0, 0, 0, 0, '0.00K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'W', 'CLITO MILL', 1, 'W', 'CLITO MILL', 36.6987, -81.091, 36.6987, -81.091, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'One large tree was blown down by thunderstorm winds along Carsonville Road.');
INSERT INTO public.stormevents_east VALUES (748593, 201804, 15, 1655, 201804, 15, 1658, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 16:55:00', 'EST-5', '15-APR-18 16:58:00', 0, 0, 0, 0, '2.60M', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 5, 'W', 'DANVILLE', 5, 'WNW', 'DANVILLE', 36.5839, -79.4769, 36.6138, -79.4658, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'This is the second segment in Virginia of a tornado that originated west of Pelham near Dusty Lane in Caswell County of North Carolina at 4:51 PM EST.  The tornado exited Pittsylvania County and entered into the independent city of Danville at 4:55 PM EST.  The tornado damaged or destroyed numerous trees, and several outbuildings were completely destroyed.  Minor roof damage occurred to numerous homes as the tornado crossed over the Westover area within the city limits of Danville.  Private property damage was assessed at about $2.2 million, while utilities and public works cleanup added another $400,000.  By 4:58 PM EST, the tornado exited the city and continued northward back into Pittsylvania County.');
INSERT INTO public.stormevents_east VALUES (780509, 201808, 30, 1643, 201808, 30, 1743, 130385, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'RNK', '30-AUG-18 16:43:00', 'EST-5', '30-AUG-18 17:43:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RADFORD', 0, 'SSE', 'RADFORD', 37.11, -80.59, 37.1191, -80.5593, 'Strong storms with heavy rainfall developed in the late afternoon across parts of the New River Valley including Pulaski, Montgomery and the City of Radford. Water was reported over several roadways including on the Virginia Tech campus and over a dozen buildings on the Radford University campus that were flooded. Rain gage reports ending at 7 AM on the 31st included Radford 0.9 WNW CoCoRaHS (VA-RDC-1) 3.00���, Radford DCP (RDFV2) 2.55���, Blacksburg 0.4 N CoCoRaHS (VA-MN-6) and 2.44���, Blacksburg IFLOWS (BLGV2) 2.29���. Most of the rain fell in a much shorter time period however, generally in about 1 hour between 4 and 5 PM EST.', 'Flooding closed several streets in Radford with water over 2 feet deep reported on 2nd Street. In addition, up to 15 building on the Radford University campus had some water damage, with 12 of those described as significant damage. Two roads in Radford were also damaged, Wadsworth and Fairfax Streets.');
INSERT INTO public.stormevents_east VALUES (780513, 201808, 30, 1730, 201808, 30, 1830, 130385, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'RNK', '30-AUG-18 17:30:00', 'EST-5', '30-AUG-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'FAGG', 1, 'SSE', 'IRONTO', 37.19, -80.33, 37.2314, -80.3393, 'Strong storms with heavy rainfall developed in the late afternoon across parts of the New River Valley including Pulaski, Montgomery and the City of Radford. Water was reported over several roadways including on the Virginia Tech campus and over a dozen buildings on the Radford University campus that were flooded. Rain gage reports ending at 7 AM on the 31st included Radford 0.9 WNW CoCoRaHS (VA-RDC-1) 3.00���, Radford DCP (RDFV2) 2.55���, Blacksburg 0.4 N CoCoRaHS (VA-MN-6) and 2.44���, Blacksburg IFLOWS (BLGV2) 2.29���. Most of the rain fell in a much shorter time period however, generally in about 1 hour between 4 and 5 PM EST.', 'Several roads were closed including North Fork Road and several around the Virginia Tech campus.');
INSERT INTO public.stormevents_east VALUES (744640, 201805, 5, 1735, 201805, 5, 1735, 124079, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'MRX', '05-MAY-18 17:35:00', 'EST-5', '05-MAY-18 17:35:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'N', 'PENNINGTON GAP', 1, 'N', 'PENNINGTON GAP', 36.76, -83.03, 36.76, -83.03, 'A weak short wave passed across the Southern Appalachians generating a couple thunderstorms that produced marginally severe hail.', 'Quarter size hail was reported in the Pennington Bap vicinity.');
INSERT INTO public.stormevents_east VALUES (745414, 201805, 4, 1603, 201805, 4, 1603, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 16:03:00', 'EST-5', '04-MAY-18 16:03:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'SSW', 'AIKEN', 0, 'SSW', 'AIKEN', 41.8755, -78.5822, 41.8755, -78.5822, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto wires at the intersection of Northland Road and Route 646.');
INSERT INTO public.stormevents_east VALUES (745425, 201805, 4, 1722, 201805, 4, 1722, 123953, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'CTP', '04-MAY-18 17:22:00', 'EST-5', '04-MAY-18 17:22:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'SSW', 'WELLSBORO ARPT', 1, 'SSW', 'WELLSBORO ARPT', 41.72, -77.4034, 41.72, -77.4034, 'A line of severe thunderstorms produced widespread wind damage across northwestern and north-central Pennsylvania during the late afternoon and early evening hours on May 4, 2018.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees on wires along Darling Run Road.');
INSERT INTO public.stormevents_east VALUES (774372, 201807, 17, 1503, 201807, 17, 1700, 128272, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '17-JUL-18 15:03:00', 'EST-5', '17-JUL-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'POTOMAC YARD', 0, 'SSE', 'POTOMAC YARD', 38.8267, -77.0786, 38.8262, -77.0784, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding during rush hour, mainly due to standing water.', 'Valley Drive was flooded, with water flowing across and down the street near Timber Branch and the Braddock Road intersection.');
INSERT INTO public.stormevents_east VALUES (761560, 201805, 20, 855, 201805, 20, 855, 127089, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '20-MAY-18 08:55:00', 'EST-5', '20-MAY-18 08:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'Scattered showers and thunderstorms produced isolated gale-force wind gusts along the reef offshore Ocean Reef, as a trough of low pressure across southern Florida moved west into the Gulf of Mexico.', 'A wind gust of 37 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
INSERT INTO public.stormevents_east VALUES (779537, 201808, 3, 1244, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 12:44:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'ALBANY', 1, 'SSW', 'ALBANY', 42.6391, -73.7769, 42.6368, -73.7775, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'A trained spotter reported flooding in a field and building due to heavy rainfall.');
INSERT INTO public.stormevents_east VALUES (779538, 201808, 3, 1300, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:00:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'HOUCKS CORNERS', 1, 'W', 'HOUCKS CORNERS', 42.6012, -73.8404, 42.6011, -73.8404, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'A portion of Elm Ave flooded due to heavy rain.');
INSERT INTO public.stormevents_east VALUES (781835, 201808, 17, 2109, 201808, 17, 2109, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 21:09:00', 'EST-5', '17-AUG-18 21:09:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'FREEDOM PLAINS', 1, 'W', 'FREEDOM PLAINS', 41.67, -73.81, 41.67, -73.81, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Multiple trees down blocking Cramer Road.');
INSERT INTO public.stormevents_east VALUES (781834, 201808, 17, 1940, 201808, 17, 1940, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 19:40:00', 'EST-5', '17-AUG-18 19:40:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'GHENT KLINE KILL ARP', 1, 'NW', 'GHENT KLINE KILL ARP', 42.36, -73.64, 42.36, -73.64, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Wires were downed and burning in the town of Ghent.');
INSERT INTO public.stormevents_east VALUES (781836, 201808, 17, 2110, 201808, 17, 2110, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 21:10:00', 'EST-5', '17-AUG-18 21:10:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'WAPPINGERS FALLS', 1, 'SE', 'WAPPINGERS FALLS', 41.59, -73.91, 41.59, -73.91, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Trees and wires down. Time estimated by radar.');
INSERT INTO public.stormevents_east VALUES (781837, 201808, 17, 2116, 201808, 17, 2116, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 21:16:00', 'EST-5', '17-AUG-18 21:16:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'CHESTNUT RIDGE', 1, 'SW', 'CHESTNUT RIDGE', 41.72, -73.64, 41.72, -73.64, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Tree was downed.');
INSERT INTO public.stormevents_east VALUES (781051, 201808, 8, 1455, 201808, 8, 1455, 130486, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 14:55:00', 'EST-5', '08-AUG-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 6, 'N', 'WELLBORN', 6, 'N', 'WELLBORN', 30.31, -82.82, 30.31, -82.82, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'Trees and power lines were blown down along County Roads 136 and 137 in the NE portion of the county. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (775646, 201807, 6, 1421, 201807, 6, 1421, 129468, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'AKQ', '06-JUL-18 14:21:00', 'EST-5', '06-JUL-18 14:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 3, 'NW', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 3, 'NW', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 37.01, -76.35, 37.01, -76.35, 'Scattered thunderstorms in advance of a cold front produced gusty winds across portions of the James River.', 'Wind gust of 35 knots was measured at Hampton Flats.');
INSERT INTO public.stormevents_east VALUES (776390, 201807, 22, 1825, 201807, 22, 1825, 129605, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'GSP', '22-JUL-18 18:25:00', 'EST-5', '22-JUL-18 18:25:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 40, 'EG', NULL, NULL, 1, 'E', 'ROCKWELL', 1, 'E', 'ROCKWELL', 35.55, -80.41, 35.55, -80.41, 'Scattered to numerous thunderstorms developed along a cold front across the North Carolina Piedmont during the afternoon and evening.A few of the storms produced brief large hail and damaging winds. While most of the severe weather was marginal, a significant downburst did occur in the Concord area.', 'County comms reported a tree and power lines blown down on a car on Highway 52 in Rockwell.');
INSERT INTO public.stormevents_east VALUES (774915, 201807, 22, 1930, 201807, 22, 2030, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 19:30:00', 'EST-5', '22-JUL-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'LOUDON PARK', 1, 'NW', 'CANTON', 39.2824, -76.6785, 39.2861, -76.5874, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'More than two dozen roads flooded and closed throughout Baltimore City.');
INSERT INTO public.stormevents_east VALUES (774916, 201807, 21, 2115, 201807, 21, 2215, 128275, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:15:00', 'EST-5', '21-JUL-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'GEORGETOWN', 0, 'WSW', 'GEORGETOWN', 38.9181, -77.0581, 38.9186, -77.057, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the District of Columbia. Rainfall totals of 3 to 5 inches were observed, causing flooding, especially along Rock Creek.', 'Rock Creek Parkway flooded and closed at Massachusetts Avenue.');
INSERT INTO public.stormevents_east VALUES (763348, 201808, 2, 158, 201808, 2, 158, 127335, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '02-AUG-18 01:58:00', 'EST-5', '02-AUG-18 01:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'EG', NULL, NULL, 5, 'SSE', 'VENICE', 5, 'SSE', 'VENICE', 27.04, -82.42, 27.04, -82.42, 'Thunderstorms lingered over the eastern Gulf of Mexico overnight. One of these storms moved onshore, causing gusty winds.', 'A home weather station in South Venice reported a 35 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (763351, 201808, 5, 1731, 201808, 5, 1731, 127336, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '05-AUG-18 17:31:00', 'EST-5', '05-AUG-18 17:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'EG', NULL, NULL, 7, 'W', 'LOWER TAMPA BAY', 7, 'W', 'LOWER TAMPA BAY', 27.61, -82.76, 27.61, -82.76, 'Easterly flow led to scattered thunderstorms developing over the Florida Peninsula and pushing into the eastern Gulf of Mexico, producing gusty winds. One storm also developed a waterspout over the Tampa Bay.', 'The WeatherFlow station at Egmont Key recorded a 39 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (763660, 201808, 5, 1709, 201808, 5, 1709, 127399, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TBW', '05-AUG-18 17:09:00', 'EST-5', '05-AUG-18 17:09:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Emergency Manager', 43, 'EG', NULL, NULL, 4, 'S', 'TIERRA VERDE', 4, 'S', 'TIERRA VERDE', 27.6159, -82.7259, 27.6159, -82.7259, 'Easterly flow led to scattered thunderstorms developing over the Florida Peninsula and pushing into the eastern Gulf of Mexico, producing gusty winds. A lightning strike from one of these storms also caused a house fire.', 'The metal roof of a bait shop on a pier at Fort DeSoto was partially peeled back by thunderstorm wind gusts.');
INSERT INTO public.stormevents_east VALUES (763667, 201808, 5, 1906, 201808, 5, 1906, 127399, 'FLORIDA', 12, 2018, 'August', 'Lightning', 'TBW', '05-AUG-18 19:06:00', 'EST-5', '05-AUG-18 19:06:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'NNE', 'SPG-ALBERT WHITTED AIRPORT', 1, 'NNE', 'SPG-ALBERT WHITTED AIRPORT', 27.79, -82.624, 27.79, -82.624, 'Easterly flow led to scattered thunderstorms developing over the Florida Peninsula and pushing into the eastern Gulf of Mexico, producing gusty winds. A lightning strike from one of these storms also caused a house fire.', 'A lightning strike caused a fire at a house in St. Petersburg. No injuries were reported.');
INSERT INTO public.stormevents_east VALUES (765872, 201808, 11, 946, 201808, 11, 946, 127693, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '11-AUG-18 09:46:00', 'EST-5', '11-AUG-18 09:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'EG', NULL, NULL, 1, 'SSE', 'LONGBOAT KEY', 1, 'SSE', 'LONGBOAT KEY', 27.4015, -82.5586, 27.4015, -82.5586, 'Onshore flow led to morning showers and storms developing over the eastern Gulf of Mexico and moving onshore. One of these storms caused a marine wind gust as it came onshore.', 'The ASOS at Sarasota-Bradenton International Airport recorded a 38 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (767718, 201808, 7, 1630, 201808, 7, 1630, 127996, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TBW', '07-AUG-18 16:30:00', 'EST-5', '07-AUG-18 16:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 45, 'EG', NULL, NULL, 1, 'SSW', 'HARBOR VIEW', 1, 'SSW', 'HARBOR VIEW', 26.9062, -82.0749, 26.9062, -82.0749, 'Scattered afternoon thunderstorms developing along the sea breeze produced brief gusty winds near the Charlotte Harbor.', 'A pool cage was reported damaged near the corner of Via Veneto Drive and Socorro Drive in Punta Gorda.');
INSERT INTO public.stormevents_east VALUES (767731, 201808, 20, 1855, 201808, 20, 1855, 128001, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '20-AUG-18 18:55:00', 'EST-5', '20-AUG-18 18:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 41, 'MG', NULL, NULL, 5, 'N', 'HILLSBOROUGH BAY', 5, 'N', 'HILLSBOROUGH BAY', 27.9152, -82.4518, 27.9152, -82.4518, 'Scattered summer thunderstorms moved across the Tampa Bay during the early evening. One of these storms produced a downburst wind gust over Hillsborough Bay.', 'The AWOS at Peter O. Knight Airport measured a 41 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (768959, 201808, 25, 1636, 201808, 25, 1636, 128212, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '25-AUG-18 16:36:00', 'EST-5', '25-AUG-18 16:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 46, 'EG', NULL, NULL, 7, 'W', 'LOWER TAMPA BAY', 7, 'W', 'LOWER TAMPA BAY', 27.61, -82.76, 27.61, -82.76, 'Easterly flow allowed scattered to numerous thunderstorms to develop over the Florida Peninsula and push west into the eastern Gulf of Mexico. Some of these storms produced gusty winds along the coast.', 'The WeatherFlow station at Egmont Key (XEGM) recorded a 46 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (764531, 201808, 11, 1435, 201808, 11, 1635, 127534, 'KENTUCKY', 21, 2018, 'August', 'Flash Flood', 'ILN', '11-AUG-18 14:35:00', 'EST-5', '11-AUG-18 16:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CONCORD', 1, 'NW', 'CONCORD', 38.68, -83.48, 38.6855, -83.489, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'Water was flowing over a portion of KY-8 near Concord.');
INSERT INTO public.stormevents_east VALUES (764534, 201808, 11, 1800, 201808, 11, 2000, 127534, 'KENTUCKY', 21, 2018, 'August', 'Flood', 'ILN', '11-AUG-18 18:00:00', 'EST-5', '11-AUG-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'QUINCY', 2, 'SSW', 'QUINCY', 38.6, -83.14, 38.5993, -83.1401, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'Water was reported over Montgomery Road near Garrison.');
INSERT INTO public.stormevents_east VALUES (766132, 201808, 11, 1153, 201808, 11, 1203, 127533, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '11-AUG-18 11:53:00', 'EST-5', '11-AUG-18 12:03:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 40, 'EG', NULL, NULL, 1, 'NE', 'MC DERMOTT', 1, 'NE', 'MC DERMOTT', 38.84, -83.06, 38.84, -83.06, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'A tree was knocked down along Colley Road near McDermott Road.');
INSERT INTO public.stormevents_east VALUES (766133, 201808, 11, 1154, 201808, 11, 1204, 127533, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '11-AUG-18 11:54:00', 'EST-5', '11-AUG-18 12:04:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 40, 'EG', NULL, NULL, 1, 'WNW', 'OWENSVILLE', 1, 'WNW', 'OWENSVILLE', 38.86, -83.05, 38.86, -83.05, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'A tree was knocked down along Duck Run Rd.');
INSERT INTO public.stormevents_east VALUES (766134, 201808, 11, 1238, 201808, 11, 1248, 127533, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '11-AUG-18 12:38:00', 'EST-5', '11-AUG-18 12:48:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 40, 'EG', NULL, NULL, 0, 'N', 'ALLENTOWN', 0, 'N', 'ALLENTOWN', 38.7, -82.85, 38.7, -82.85, 'Scattered thunderstorms developed in the vicinity of a cold front. The thunderstorms produced heavy rain, which produced some flooding.', 'A tree was knocked down along Mill Road near Wheelersburg.');
INSERT INTO public.stormevents_east VALUES (777896, 201808, 3, 1440, 201808, 3, 1440, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '03-AUG-18 14:40:00', 'EST-5', '03-AUG-18 14:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'S', 'PET XRDS', 2, 'S', 'PET XRDS', 35.7954, -78.5207, 35.7954, -78.5207, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'One tree was reported down at Hodge Road and Knightdale Boulevard.');
INSERT INTO public.stormevents_east VALUES (777897, 201808, 3, 1600, 201808, 3, 1600, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '03-AUG-18 16:00:00', 'EST-5', '03-AUG-18 16:00:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'N', 'HOLLY GROVE', 4, 'N', 'HOLLY GROVE', 35.87, -80.17, 35.87, -80.17, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Trees were reported down between Lexington and Thomasville.');
INSERT INTO public.stormevents_east VALUES (778996, 201808, 3, 1600, 201808, 3, 1745, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 16:00:00', 'EST-5', '03-AUG-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'ELON COLLEGE', 2, 'SW', 'ELON COLLEGE', 36.09, -79.52, 36.0868, -79.5213, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Veterans Drive and Westwood Drive was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (778997, 201808, 3, 1600, 201808, 3, 1745, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 16:00:00', 'EST-5', '03-AUG-18 17:45:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'UNION RIDGE', 2, 'SSW', 'UNION RIDGE', 36.2, -79.42, 36.1949, -79.4147, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Fire Department 13 had food waters coming into the building.');
INSERT INTO public.stormevents_east VALUES (778998, 201808, 3, 1629, 201808, 3, 1745, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 16:29:00', 'EST-5', '03-AUG-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'ELON COLLEGE', 1, 'WNW', 'ELON COLLEGE', 36.1, -79.5, 36.1067, -79.5143, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Four to Five roads were reported to be underwater in Elon.');
INSERT INTO public.stormevents_east VALUES (778999, 201808, 3, 1730, 201808, 3, 1745, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 17:30:00', 'EST-5', '03-AUG-18 17:45:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'GLEN RAVEN', 2, 'NW', 'GLENCOE', 36.15, -79.46, 36.1496, -79.4519, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Iseley School Road was reported flooded. The flooded waters washed out the road, damaged a culvert and crushed a natural gas line.');
INSERT INTO public.stormevents_east VALUES (779000, 201808, 3, 1735, 201808, 3, 1745, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 17:35:00', 'EST-5', '03-AUG-18 17:45:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'GLEN RAVEN', 1, 'NW', 'GLENCOE', 36.14, -79.46, 36.1368, -79.4422, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Flood waters were reported entering a home in the 1100 black of Greenwood Drive.');
INSERT INTO public.stormevents_east VALUES (780975, 201808, 1, 1650, 201808, 1, 1650, 130477, 'FLORIDA', 12, 2018, 'August', 'Funnel Cloud', 'JAX', '01-AUG-18 16:50:00', 'EST-5', '01-AUG-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 0, 'N', 'FRUIT COVE', 0, 'N', 'FRUIT COVE', 30.1, -81.63, 30.1, -81.63, 'Fast and moist SW steering flow pushed a stronger west coast sea breeze across the area which triggered a few strong storms as activity neared the I-95 corridor where greater storm coverage occurred.', 'A funnel cloud was reported near State Road 13 and Roberts Road.');
INSERT INTO public.stormevents_east VALUES (780976, 201808, 1, 1903, 201808, 1, 1903, 130478, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'JAX', '01-AUG-18 19:03:00', 'EST-5', '01-AUG-18 19:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 11, 'SSW', 'BEVERLY BEACH', 11, 'SSW', 'BEVERLY BEACH', 29.48, -81.21, 29.48, -81.21, 'Fast and moist SW steering flow pushed a stronger west coast sea breeze across the area which triggered a few strong storms as activity neared the I-95 corridor where greater storm coverage occurred.', 'A wind gust of 46 mph was measured at the Palm Cost High School.');
INSERT INTO public.stormevents_east VALUES (780977, 201808, 1, 2005, 201808, 1, 2005, 130478, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'JAX', '01-AUG-18 20:05:00', 'EST-5', '01-AUG-18 20:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 35, 'MG', NULL, NULL, 13, 'NNW', 'SAUF1 CMAN', 13, 'NNW', 'SAUF1 CMAN', 30.03, -81.32, 30.03, -81.32, 'Fast and moist SW steering flow pushed a stronger west coast sea breeze across the area which triggered a few strong storms as activity neared the I-95 corridor where greater storm coverage occurred.', 'A private weather station at Vilano Beach measured a wind gust of 40 mph.');
INSERT INTO public.stormevents_east VALUES (780978, 201808, 2, 1304, 201808, 2, 1330, 130479, 'FLORIDA', 12, 2018, 'August', 'Flood', 'JAX', '02-AUG-18 13:04:00', 'EST-5', '02-AUG-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSE', 'JACKSONVILLE', 3, 'SSW', 'LAKE FOREST', 30.31, -81.66, 30.3158, -81.6497, 'A passing mid level short wave trough combined with moist SW steering flow enhanced diurnally driven sea breeze convection, which triggered a few strong to severe storms.', 'Around 2 pm, local media reported flooding at the intersection of Riverside Avenue and Osceola. Water was about car tire high in depth. Also around 2 pm, flooded roadways were reported at San Marco Blvd and Nira Street.');
INSERT INTO public.stormevents_east VALUES (780980, 201808, 2, 1700, 201808, 2, 1700, 130481, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'JAX', '02-AUG-18 17:00:00', 'EST-5', '02-AUG-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'A passing mid level short wave trough combined with moist SW steering flow enhanced diurnally driven sea breeze convection, which triggered a few strong to severe storms.', 'A mesonet site at Huguenot Park measured a wind gust of 43 mph.');
INSERT INTO public.stormevents_east VALUES (781007, 201808, 6, 1640, 201808, 6, 1640, 130483, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'JAX', '06-AUG-18 16:40:00', 'EST-5', '06-AUG-18 16:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'MG', NULL, NULL, 0, 'N', 'HAZELHURST', 0, 'N', 'HAZELHURST', 31.87, -82.6, 31.87, -82.6, 'High pressure north of the region brought a dominant east coast sea breeze regime to the area which triggered a few strong storms.', 'Trees were blown down in Hazelhurst. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (782239, 201808, 14, 1600, 201808, 14, 1700, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 16:00:00', 'EST-5', '14-AUG-18 17:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'LACONA', 1, 'SE', 'SANDY CREEK', 43.6414, -76.0828, 43.6427, -76.0887, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Several road closures reported around Sandy Creek.');
INSERT INTO public.stormevents_east VALUES (782240, 201808, 14, 1618, 201808, 14, 1718, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 16:18:00', 'EST-5', '14-AUG-18 17:18:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'PULASKI', 1, 'S', 'PULASKI', 43.55, -76.13, 43.5516, -76.1305, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Route 41 reported flooded and closed near the railroad crossing southwest of Pulaski.');
INSERT INTO public.stormevents_east VALUES (782241, 201808, 14, 559, 201808, 14, 559, 130615, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '14-AUG-18 05:59:00', 'EST-5', '14-AUG-18 05:59:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'SSE', 'EAST PALMYRA', 2, 'SSE', 'EAST PALMYRA', 43.05, -77.16, 43.05, -77.16, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Several trees were reported down between Palmyra and Newark.');
INSERT INTO public.stormevents_east VALUES (782242, 201808, 14, 601, 201808, 14, 601, 130615, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '14-AUG-18 06:01:00', 'EST-5', '14-AUG-18 06:01:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'PORT GIBSON', 1, 'E', 'PORT GIBSON', 43.03, -77.16, 43.03, -77.16, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Several trees were reported down.');
INSERT INTO public.stormevents_east VALUES (782256, 201808, 15, 1606, 201808, 15, 1606, 130727, 'NEW YORK', 36, 2018, 'August', 'Hail', 'BUF', '15-AUG-18 16:06:00', 'EST-5', '15-AUG-18 16:06:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 1, 'NE', 'FRONTENAC', 1, 'NE', 'FRONTENAC', 44.26, -76.03, 44.26, -76.03, 'Thunderstorms developed as expected north of Lake Ontario across southern Ontario province. Storms just on the north side of the St. Lawrence River began to strengthen during the afternoon. The storms continued to strengthen as they approached the area with impressive lightning jumps and impressive reflectivity cores aloft that included 60 dbz over 30kft and 50 dbz to around 40 kft.', 'Hail slightly smaller than a golf call reported by the public with cars dented in the area.');
INSERT INTO public.stormevents_east VALUES (782196, 201808, 7, 545, 201808, 7, 545, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 05:45:00', 'EST-5', '07-AUG-18 05:45:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 1, 'NW', 'ALLAGASH', 1, 'NW', 'ALLAGASH', 47.09, -69.06, 47.09, -69.06, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Two trees were toppled by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (782199, 201808, 7, 640, 201808, 7, 640, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 06:40:00', 'EST-5', '07-AUG-18 06:40:00', 0, 0, 0, 0, NULL, NULL, 'Public', 61, 'EG', NULL, NULL, 2, 'NNW', 'SWEDEN', 2, 'NNW', 'SWEDEN', 46.98, -68.14, 46.98, -68.14, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Between 40 and 60 trees were toppled or snapped in an area from near New Sweden to Hedman Road...along Route 161...due to straight-line winds estimated at up to 70 mph. Power poles were also toppled and snapped in the same area.The damage occurred along an approximately 1 mile wide and 50 yard long path.');
INSERT INTO public.stormevents_east VALUES (782202, 201808, 7, 1315, 201808, 7, 1315, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 13:15:00', 'EST-5', '07-AUG-18 13:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 52, 'EG', NULL, NULL, 0, 'N', 'ORIENT', 0, 'N', 'ORIENT', 45.82, -67.85, 45.82, -67.85, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Several trees were toppled on School House Road by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (782203, 201808, 7, 1213, 201808, 7, 1213, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 12:13:00', 'EST-5', '07-AUG-18 12:13:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'SANGERVILLE', 0, 'N', 'SANGERVILLE', 45.17, -69.37, 45.17, -69.37, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees were toppled on Knowlton Mills Road and Main Street by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (782204, 201808, 7, 1215, 201808, 7, 1215, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 12:15:00', 'EST-5', '07-AUG-18 12:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 2, 'NNE', 'LOWS BRIDGE', 2, 'NNE', 'LOWS BRIDGE', 45.2, -69.3, 45.2, -69.3, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees were toppled on Sebec Shores Road by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (782205, 201808, 7, 1230, 201808, 7, 1230, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 12:30:00', 'EST-5', '07-AUG-18 12:30:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'DOVER FOXCROFT', 0, 'N', 'DOVER FOXCROFT', 45.18, -69.23, 45.18, -69.23, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees were toppled on Essex Street by wind gusts estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (782210, 201808, 7, 1855, 201808, 7, 1855, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 18:55:00', 'EST-5', '07-AUG-18 18:55:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'HAMPDEN', 0, 'N', 'HAMPDEN', 44.75, -68.83, 44.75, -68.83, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees and power lines were toppled by wind gusts estimated at 60 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (782122, 201808, 9, 1745, 201808, 9, 1745, 130689, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'GSP', '09-AUG-18 17:45:00', 'EST-5', '09-AUG-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNW', 'CROMERS', 3, 'NNW', 'CROMERS', 34.32, -83.256, 34.32, -83.256, 'Isolated to widely scattered thunderstorms moved into the northeast Georgia Piedmont from the northwest and west during the evening. One storm produced brief damaging winds in Franklin County.', 'County comms reported trees blown down along Athens and Cole roads.');
INSERT INTO public.stormevents_east VALUES (782126, 201808, 12, 1746, 201808, 12, 1746, 130693, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '12-AUG-18 17:46:00', 'EST-5', '12-AUG-18 17:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'ENE', 'ROCKWELL', 2, 'ENE', 'ROCKWELL', 35.556, -80.391, 35.556, -80.391, 'Scattered thunderstorms developed across the North Carolina Piedmont in the vicinity of a stationary front during the afternoon and evening. One of the storms produced brief damaging winds in Rowan County.', 'Public reported multiple trees and large limbs blown down in and near Rockwell.');
INSERT INTO public.stormevents_east VALUES (782113, 201808, 8, 1855, 201808, 8, 1855, 130540, 'SOUTH CAROLINA', 45, 2018, 'August', 'Hail', 'GSP', '08-AUG-18 18:55:00', 'EST-5', '08-AUG-18 18:55:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.25, NULL, NULL, NULL, 1, 'W', 'BARKSDALE', 1, 'W', 'BARKSDALE', 34.57, -82.09, 34.57, -82.09, 'Scattered thunderstorms developed during the afternoon near the South Carolina Blue Ridge, with storms gradually spreading south and east along outflow boundaries throughout the afternoon and into the evening. A few of the storms produced brief damaging winds.', 'Public reported half dollar size hail in the Barksdale community.');
INSERT INTO public.stormevents_east VALUES (782118, 201808, 9, 1608, 201808, 9, 1611, 130688, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '09-AUG-18 16:08:00', 'EST-5', '09-AUG-18 16:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'E', 'MARTIN XRDS', 0, 'NW', 'ORA', 34.627, -82.008, 34.604, -82.004, 'Isolated to widely scattered thunderstorms developed along and near the South Carolina Blue Ridge during the afternoon and moved southeast into the evening. A few of the storms produced brief damaging winds.', 'Utility company reported power lines blown down with some outages along Garrett and Slippery Rock Roads. Highway patrol reported trees down along Ora and Lincoln Roads.');
INSERT INTO public.stormevents_east VALUES (782119, 201808, 9, 1644, 201808, 9, 1705, 130688, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '09-AUG-18 16:44:00', 'EST-5', '09-AUG-18 17:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'ESE', 'MAULDIN', 2, 'WSW', 'FOUNTAIN INN', 34.774, -82.269, 34.69, -82.226, 'Isolated to widely scattered thunderstorms developed along and near the South Carolina Blue Ridge during the afternoon and moved southeast into the evening. A few of the storms produced brief damaging winds.', 'Highway Patrol reported multiple trees blown down along Holland Rd. Public reported multiple trees down in the Fountain Inn area.');
INSERT INTO public.stormevents_east VALUES (782120, 201808, 9, 1708, 201808, 9, 1708, 130688, 'SOUTH CAROLINA', 45, 2018, 'August', 'Hail', 'GSP', '09-AUG-18 17:08:00', 'EST-5', '09-AUG-18 17:08:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'S', 'GAYLORD XRDS', 1, 'S', 'GAYLORD XRDS', 34.72, -82.18, 34.72, -82.18, 'Isolated to widely scattered thunderstorms developed along and near the South Carolina Blue Ridge during the afternoon and moved southeast into the evening. A few of the storms produced brief damaging winds.', 'Public reported quarter size hail.');
INSERT INTO public.stormevents_east VALUES (782121, 201808, 9, 1843, 201808, 9, 1843, 130688, 'SOUTH CAROLINA', 45, 2018, 'August', 'Hail', 'GSP', '09-AUG-18 18:43:00', 'EST-5', '09-AUG-18 18:43:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 0.88, NULL, NULL, NULL, 2, 'ESE', 'HOMELAND PARK', 2, 'ESE', 'HOMELAND PARK', 34.47, -82.635, 34.47, -82.635, 'Isolated to widely scattered thunderstorms developed along and near the South Carolina Blue Ridge during the afternoon and moved southeast into the evening. A few of the storms produced brief damaging winds.', 'Amateur radio operator reported nickel size hail along Camden Dr.');
INSERT INTO public.stormevents_east VALUES (769170, 201808, 26, 1715, 201808, 26, 1725, 128242, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '26-AUG-18 17:15:00', 'EST-5', '26-AUG-18 17:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'S', 'CIRCLEVILLE', 2, 'S', 'CIRCLEVILLE', 39.57, -82.95, 39.57, -82.95, 'Isolated severe thunderstorms developed in an increasingly unstable air mass.', 'Multiple trees were knocked down over a road. In addition, a tree fell onto a house.');
INSERT INTO public.stormevents_east VALUES (783331, 201808, 27, 2140, 201808, 27, 2140, 130922, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '27-AUG-18 21:40:00', 'EST-5', '27-AUG-18 21:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'Scattered thunderstorms associated with a westward-moving inverted surface trough of low pressure produced scattered areas of gale-force wind gusts, mainly from over and offshore the Upper Keys through Duck Key, FL.', 'A wind gust of 35 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
