INSERT INTO public.stormevents_east VALUES (783337, 201808, 27, 2248, 201808, 27, 2248, 130922, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '27-AUG-18 22:48:00', 'EST-5', '27-AUG-18 22:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Scattered thunderstorms associated with a westward-moving inverted surface trough of low pressure produced scattered areas of gale-force wind gusts, mainly from over and offshore the Upper Keys through Duck Key, FL.', 'A wind gust of 37 knots was measured at an automated Citizen Weather Observing Program station at Duck Key.');
INSERT INTO public.stormevents_east VALUES (769173, 201808, 26, 1720, 201808, 26, 1730, 128242, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '26-AUG-18 17:20:00', 'EST-5', '26-AUG-18 17:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'WHISLER', 1, 'SE', 'WHISLER', 39.47, -82.82, 39.47, -82.82, 'Isolated severe thunderstorms developed in an increasingly unstable air mass.', 'A tree was knocked down onto a road.');
INSERT INTO public.stormevents_east VALUES (765395, 201808, 7, 1600, 201808, 7, 1600, 127638, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '07-AUG-18 16:00:00', 'EST-5', '07-AUG-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 58, 'EG', NULL, NULL, 3, 'N', 'PUNTA GORDA', 3, 'N', 'PUNTA GORDA', 26.94, -82.07, 26.94, -82.07, 'Scattered afternoon thunderstorms developing along the sea breeze produced brief gusty winds across Charlotte Harbor.', 'A personal weather station mounted on a channel marker along the Peace River / Charlotte Harbor measured a brief wind gust to 58 knots...67 mph.');
INSERT INTO public.stormevents_east VALUES (765397, 201808, 14, 1459, 201808, 14, 1459, 127639, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '14-AUG-18 14:59:00', 'EST-5', '14-AUG-18 14:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'EG', NULL, NULL, 2, 'SSE', 'PORT CHARLOTTE', 2, 'SSE', 'PORT CHARLOTTE', 26.96, -82.08, 26.96, -82.08, 'Scattered afternoon thunderstorms developing along the sea breeze slowly pushed towards the Gulf waters during the mid-afternoon. One storm produced multiple wind gusts across Charlotte Harbor.', 'A Weatherflow station near Port Charlotte recorded a wind gust of 36 knots...41 mph.');
INSERT INTO public.stormevents_east VALUES (771558, 201808, 31, 2319, 201808, 31, 2319, 128593, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RNK', '31-AUG-18 23:19:00', 'EST-5', '31-AUG-18 23:19:00', 0, 0, 0, 0, '0.50K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'E', 'DILLARD', 3, 'E', 'DILLARD', 36.4057, -80.0468, 36.4057, -80.0468, 'A hot and humid air mass sparked one severe thunderstorm during the evening.  This storm blew down three trees in Rockingham County.', 'Thunderstorm winds blew down one large pine tree on K-Fork Road close to the intersection with Goad Road.');
INSERT INTO public.stormevents_east VALUES (768939, 201808, 13, 815, 201808, 13, 1015, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:15:00', 'EST-5', '13-AUG-18 10:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'HARTRANFT', 0, 'N', 'HARTRANFT', 40.1563, -75.3313, 40.1568, -75.3303, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding resulted in the need for a water rescue at the intersection of North Wales Road and Marcia Lane in East Norriton Township.');
INSERT INTO public.stormevents_east VALUES (768940, 201808, 13, 900, 201808, 13, 1100, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 09:00:00', 'EST-5', '13-AUG-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'WEST HAMBURG', 1, 'SW', 'HAMBURG', 40.561, -75.9956, 40.5438, -75.9875, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Widespread roadway flooding occurred in Hamburg.  Many roads were impassable and some residents were evacuated from their homes due to rising flood waters.');
INSERT INTO public.stormevents_east VALUES (769204, 201808, 13, 930, 201808, 13, 1130, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 09:30:00', 'EST-5', '13-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'EAST TEXAS', 1, 'N', 'ALBURTIS', 40.5422, -75.5746, 40.531, -75.5976, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Flash flooding occurred along the Little Lehigh Creek in Ancient Oaks.  Spring Creek Road was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (769214, 201808, 13, 820, 201808, 13, 1000, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:20:00', 'EST-5', '13-AUG-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'VALLEY FORGE', 0, 'NE', 'VALLEY FORGE', 40.1015, -75.4636, 40.1024, -75.4662, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Minor flooding occurred along Valley Creek at Valley Forge.');
INSERT INTO public.stormevents_east VALUES (769215, 201808, 13, 755, 201808, 13, 1130, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:55:00', 'EST-5', '13-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'PHOENIXVILLE', 1, 'SW', 'CROMBY', 40.1425, -75.5137, 40.1425, -75.5408, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Minor flooding occurred along French Creek in Phoenixville.');
INSERT INTO public.stormevents_east VALUES (769217, 201808, 13, 815, 201808, 13, 1130, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:15:00', 'EST-5', '13-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'MARSHALLTON', 1, 'SE', 'HARMONY HILL', 39.9649, -75.6745, 39.9716, -75.6676, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Major flooding occurred along the East Branch of the Brandywine Creek below Downingtown.');
INSERT INTO public.stormevents_east VALUES (769218, 201808, 13, 830, 201808, 13, 915, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 08:30:00', 'EST-5', '13-AUG-18 09:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'FIVE PTS', 1, 'ENE', 'KAOLIN', 39.8125, -75.6924, 39.803, -75.713, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Minor flooding occurred along the Red Clay Creek at Kennett Square.');
INSERT INTO public.stormevents_east VALUES (748566, 201804, 15, 1345, 201804, 15, 1350, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Hail', 'RNK', '15-APR-18 13:45:00', 'EST-5', '15-APR-18 13:50:00', 0, 0, 0, 0, '0.00K', NULL, 'Trained Spotter', 1.25, NULL, NULL, NULL, 2, 'WNW', 'BOTTOM', 2, 'WNW', 'BOTTOM', 36.49, -80.81, 36.49, -80.81, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Hail varying from the size of quarters to half dollar coins fell for several minutes and covered the ground.');
INSERT INTO public.stormevents_east VALUES (791244, 201811, 2, 2112, 201811, 2, 2112, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:12:00', 'EST-5', '02-NOV-18 21:12:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'BABAR POINT (BAB)', 0, 'N', 'BABAR POINT (BAB)', 38.31, -77.03, 38.31, -77.03, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Babar Point.');
INSERT INTO public.stormevents_east VALUES (791245, 201811, 2, 2048, 201811, 2, 2054, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 20:48:00', 'EST-5', '02-NOV-18 20:54:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 35 knots was measured at the Francis Scott Key Bridge.');
INSERT INTO public.stormevents_east VALUES (748606, 201804, 15, 1754, 201804, 15, 1754, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 17:54:00', 'EST-5', '15-APR-18 17:54:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WSW', 'BUFFALO FORGE', 3, 'WSW', 'BUFFALO FORGE', 37.6605, -79.4955, 37.6605, -79.4955, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'One tree was blown down by thunderstorm winds on Tinkerville Road.');
INSERT INTO public.stormevents_east VALUES (748595, 201804, 15, 1401, 201804, 15, 1401, 123442, 'VIRGINIA', 51, 2018, 'April', 'Hail', 'RNK', '15-APR-18 14:01:00', 'EST-5', '15-APR-18 14:01:00', 0, 0, 0, 0, '0.00K', NULL, 'Public', 2.5, NULL, NULL, NULL, 1, 'NNE', 'FANCY GAP', 1, 'NNE', 'FANCY GAP', 36.6829, -80.6963, 36.6829, -80.6963, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'Hail up to the size of tennis balls fell about one mile north of Fancy Gap along the Fancy Gap Highway.');
INSERT INTO public.stormevents_east VALUES (748608, 201804, 15, 1603, 201804, 15, 1604, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 16:03:00', 'EST-5', '15-APR-18 16:04:00', 0, 0, 0, 0, '124.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ENE', 'MARSHALLTOWN', 1, 'NE', 'MARSHALLTOWN', 37.535, -80.054, 37.541, -80.052, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'A tornado briefly touched down just south of Hawkins Lane and headed northward at 4:03 PM EST.  It crossed Hawkins Lane and Wild Cat Hollow Road before lifting at 4:04 PM EST.  The tornado caused considerable damage to trees, homes, and outbuildings.  Six homes had roof shingles and vinyl siding ripped off by the tornado.  Several outbuildings and garages were destroyed.  The tornado also flipped one truck upside down on to another damaged vehicle, and it also lofted small debris over 100 yards.  The estimated maximum winds were 105 MPH.');
INSERT INTO public.stormevents_east VALUES (748601, 201804, 15, 1509, 201804, 15, 1509, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 15:09:00', 'EST-5', '15-APR-18 15:09:00', 0, 0, 0, 0, '0.20K', NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'N', 'FLOYD', 0, 'N', 'FLOYD', 36.92, -80.32, 36.92, -80.32, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'Several large tree limbs were blown down by thunderstorm winds.');
INSERT INTO public.stormevents_east VALUES (780219, 201808, 4, 1706, 201808, 4, 1706, 130322, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '04-AUG-18 17:06:00', 'EST-5', '04-AUG-18 17:06:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NW', 'USHERS', 1, 'NW', 'USHERS', 42.9071, -73.7822, 42.9071, -73.7822, 'A cluster of thunderstorms developed in southern Quebec during the morning hours and built southward, reaching the southern Adirondacks and Lake George Saratoga region in the mid-afternoon to evening hours. These storms resulted in scattered wind damage across the area. A nationally televised horse race in Saratoga Springs was delayed due to the lightning. Toward the evening, a gust front raced ahead of the dying storms and plowed through the Capital District, resulting in additional scattered reports of wind damage.', 'Wires were downed near Wood Road and Route 9 in Clifton Park.');
INSERT INTO public.stormevents_east VALUES (780224, 201808, 4, 1717, 201808, 4, 1717, 130322, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '04-AUG-18 17:17:00', 'EST-5', '04-AUG-18 17:17:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'SPEIGLETOWN', 1, 'S', 'SPEIGLETOWN', 42.79, -73.65, 42.79, -73.65, 'A cluster of thunderstorms developed in southern Quebec during the morning hours and built southward, reaching the southern Adirondacks and Lake George Saratoga region in the mid-afternoon to evening hours. These storms resulted in scattered wind damage across the area. A nationally televised horse race in Saratoga Springs was delayed due to the lightning. Toward the evening, a gust front raced ahead of the dying storms and plowed through the Capital District, resulting in additional scattered reports of wind damage.', 'Trees and wires were downed near Speigletown.');
INSERT INTO public.stormevents_east VALUES (780854, 201808, 8, 1855, 201808, 8, 1855, 128319, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'AKQ', '08-AUG-18 18:55:00', 'EST-5', '08-AUG-18 18:55:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'FIFE', 1, 'ENE', 'FIFE', 37.74, -78.05, 37.74, -78.05, 'Scattered severe thunderstorms along a trough of low pressure produced damaging winds across portions of central and south central Virginia.', 'Several trees and branches were downed along Hadensville Road.');
INSERT INTO public.stormevents_east VALUES (769609, 201808, 8, 1710, 201808, 8, 1710, 128319, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'AKQ', '08-AUG-18 17:10:00', 'EST-5', '08-AUG-18 17:10:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'W', 'KELLS CORNER', 0, 'W', 'KELLS CORNER', 36.88, -78.4067, 36.88, -78.4067, 'Scattered severe thunderstorms along a trough of low pressure produced damaging winds across portions of central and south central Virginia.', 'Trees were downed across western Lunenburg county.');
INSERT INTO public.stormevents_east VALUES (748799, 201805, 15, 1635, 201805, 15, 1635, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 16:35:00', 'EST-5', '15-MAY-18 16:35:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'ASHFORD', 1, 'S', 'ASHFORD', 41.8555, -72.1227, 41.8555, -72.1227, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 4:35 PM EST trees and wires were reported down on Snow lane at Kennerson Reservoir Road in Ashford.');
INSERT INTO public.stormevents_east VALUES (748816, 201805, 15, 1645, 201805, 15, 1645, 124788, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'BOX', '15-MAY-18 16:45:00', 'EST-5', '15-MAY-18 16:45:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'S', 'KLONDIKE', 1, 'ESE', 'MECHANICSVILLE', 41.9261, -71.8994, 41.9273, -71.8697, 'A cold front over the Great Lakes moved through Southern New England during the late afternoon and early night of May 15th.  The air mass over Connecticut was very warm and humid, and as the cold front moved into this air it generated numerous thunderstorms. Some thunderstorms produced damaging wind gusts, large hail, and heavy downpours.', 'At 4:45 PM EST, multiple trees were down in Putnam on Mechanics Street, Groveland Avenue, and at the intersection of U.S. Route 44 and State Route 21.');
INSERT INTO public.stormevents_east VALUES (782046, 201808, 2, 1900, 201808, 2, 2100, 128029, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'RNK', '02-AUG-18 19:00:00', 'EST-5', '02-AUG-18 21:00:00', 0, 0, 0, 0, '25.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'FOREST', 2, 'NNE', 'FOREST', 37.37, -79.28, 37.3984, -79.2591, 'A complex, broken line of thunderstorms developed during the afternoon ahead of an approaching cold front producing very heavy rainfall and some embedded severe storms. Trees were blown trees onto power lines, which caused a number of power outages.  Henry County and the city of Martinsville suffered the most tree damage and power outages. Rainfall was extremely intense within the very moist environment with precipitable water over 2 inches and several boundary collisions enhancing the rainfall. The highest amounts occurred in the City of Lynchburg and adjacent parts of Campbell County where radar estimated 4 to 6 inches of rain in several hours which was confirmed by several rain gages.', 'There were several reports of roads washed out or overtopped in the Forest area  including Spring Lake Road, Bethel Church Road, Terry Place and Goose Hollow Road.');
INSERT INTO public.stormevents_east VALUES (781782, 201808, 7, 1620, 201808, 7, 1620, 130613, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'ALY', '07-AUG-18 16:20:00', 'EST-5', '07-AUG-18 16:20:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NE', 'STEVENS CORNER', 1, 'NE', 'STEVENS CORNER', 42.41, -73.32, 42.41, -73.32, 'Scattered showers and thunderstorms developed within a humid, warm airmass across western Massachusetts. Some of these storms became severe, resulting in numerous trees and wires down.', 'A tree was downed blocking Lake Road.');
INSERT INTO public.stormevents_east VALUES (781783, 201808, 7, 1640, 201808, 7, 1640, 130613, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'ALY', '07-AUG-18 16:40:00', 'EST-5', '07-AUG-18 16:40:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'LENOX', 1, 'SW', 'LENOX', 42.36, -73.29, 42.36, -73.29, 'Scattered showers and thunderstorms developed within a humid, warm airmass across western Massachusetts. Some of these storms became severe, resulting in numerous trees and wires down.', 'Trees and wires were downed near Mountain and Clifford Roads.');
INSERT INTO public.stormevents_east VALUES (781784, 201808, 7, 1640, 201808, 7, 1640, 130613, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'ALY', '07-AUG-18 16:40:00', 'EST-5', '07-AUG-18 16:40:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SSE', 'PITTSFIELD', 1, 'SSE', 'PITTSFIELD', 42.43, -73.24, 42.43, -73.24, 'Scattered showers and thunderstorms developed within a humid, warm airmass across western Massachusetts. Some of these storms became severe, resulting in numerous trees and wires down.', 'A large tree was down blocking one lane.');
INSERT INTO public.stormevents_east VALUES (779535, 201808, 3, 1206, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 12:06:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'NWS Employee', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'GLENMONT', 1, 'E', 'GLENMONT', 42.6, -73.77, 42.5986, -73.7682, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'There was over 6 inches of water on roadways, resulting in water covering half of tires on vehicles.');
INSERT INTO public.stormevents_east VALUES (779539, 201808, 3, 1311, 201808, 3, 1500, 130180, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'ALY', '03-AUG-18 13:11:00', 'EST-5', '03-AUG-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'FEURA BUSH', 1, 'NNW', 'FEURA BUSH', 42.5892, -73.8883, 42.5893, -73.8884, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'A basement wall collapsed due to flooding from heavy rainfall.');
INSERT INTO public.stormevents_east VALUES (781839, 201808, 17, 2058, 201808, 17, 2058, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 20:58:00', 'EST-5', '17-AUG-18 20:58:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 50, 'MG', NULL, NULL, 0, 'N', '(POU)POUGHKEEPSIE AR', 0, 'N', '(POU)POUGHKEEPSIE AR', 41.63, -73.88, 41.63, -73.88, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'A wind gust of 58 mph was measured at the Poughkeepsie Airport ASOS.');
INSERT INTO public.stormevents_east VALUES (781838, 201808, 17, 2119, 201808, 17, 2119, 130616, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'ALY', '17-AUG-18 21:19:00', 'EST-5', '17-AUG-18 21:19:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'HAVILAND', 1, 'W', 'HAVILAND', 41.75, -73.6, 41.75, -73.6, 'A series of disturbances ahead of a cold frontal boundary brought rounds of heavy rainfall and strong to severe thunderstorms to the region during the afternoon and evening hours of Friday, August 17th. As a result of these disturbances, numerous trees and wires were downed across the region. There were also reports of flash flooding in Columbia county, New York. Rainfall from the event ranged from 1 to 5.36 inches. A Federal Disaster Declaration was declared due to the flooding in Columbia and surrounding counties in New York state. FEMA estimated over $36,000 million in infrastructure repair and debris removal.', 'Multiple trees were downed.');
INSERT INTO public.stormevents_east VALUES (781677, 201808, 3, 1050, 201808, 3, 1150, 130180, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'ALY', '03-AUG-18 10:50:00', 'EST-5', '03-AUG-18 11:50:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'W', 'CLARKSVILLE', 1, 'W', 'CLARKSVILLE', 42.58, -73.96, 42.58, -73.96, 'A slow-moving cold front was located well to the west of the forecast area, with a deep southerly flow of moisture ahead of the front. Modest amounts of instability and low level shear developed ahead of the front. Precipitable water values were near to just above 2.00 inches. A line of convection produced a short-lived EF0 tornado in the Catskills during the early afternoon. A cluster of storms moved across the Capital District producing flash flooding within the city of Albany during the early afternoon. Another cluster of storms moved north up the Hudson Valley later in the afternoon producing wind damage and flash flooding in Dutchess and Greene counties. Finally, another round of heavy rain affected the Saratoga and upper Hudson Valley areas overnight Friday night producing minor flooding. Rainfall totals of 2 to 4 inches occurred in many areas from the mid-Hudson Valley through the Saratoga and upper Hudson Valley areas. Thousands of customers lost power as a result of these storms.', 'Heavy rainfall of 1.80 inches fell in 45 minutes.');
INSERT INTO public.stormevents_east VALUES (776774, 201807, 31, 1422, 201807, 31, 1422, 129690, 'GULF OF MEXICO', 85, 2018, 'July', 'Marine Thunderstorm Wind', 'KEY', '31-JUL-18 14:22:00', 'EST-5', '31-JUL-18 14:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR REEF LIGHT', 0, 'N', 'ALLIGATOR REEF LIGHT', 24.85, -80.62, 24.85, -80.62, 'Widely separated showers and thunderstorms over the Florida Straits moved west-northwest, accelerating due to high pressure ridging becoming established over the Florida Peninsula.  Small areas of gale-force wind gusts occurred along the waters from Islamorada through Duck Key.', 'A wind gust of 36 knots from the southeast was measured at an automated WeatherFlow station at Alligator Reef Light.');
INSERT INTO public.stormevents_east VALUES (755022, 201807, 5, 1930, 201807, 5, 1930, 125943, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'TBW', '05-JUL-18 19:30:00', 'EST-5', '05-JUL-18 19:30:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'E', 'RATTLESNAKE', 2, 'E', 'RATTLESNAKE', 27.8836, -82.4991, 27.8836, -82.4991, 'Deep moisture led to scattered thunderstorms developing across west central and southwest Florida during the afternoon and early evening. A lightning strike from one of these storms is suspected to have caused a fire in Tampa.', 'Broadcast media reported on a fire that Tampa Fire Rescue suspected was caused by lightning. Residents reported seeing lightning strike a vacant condominium building, then later seeing smoke and fire coming out of the roof. The fire damaged two of the units in the condo.');
INSERT INTO public.stormevents_east VALUES (769175, 201808, 26, 1815, 201808, 26, 1825, 128242, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '26-AUG-18 18:15:00', 'EST-5', '26-AUG-18 18:25:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'E', 'REYNOLDSBURG', 1, 'E', 'REYNOLDSBURG', 39.95, -82.8, 39.95, -82.8, 'Isolated severe thunderstorms developed in an increasingly unstable air mass.', 'Three trees were reported knocked down.');
INSERT INTO public.stormevents_east VALUES (768960, 201808, 25, 1658, 201808, 25, 1658, 128212, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '25-AUG-18 16:58:00', 'EST-5', '25-AUG-18 16:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 37, 'MG', NULL, NULL, 8, 'NW', 'OLD TAMPA BAY', 8, 'NW', 'OLD TAMPA BAY', 27.9126, -82.6856, 27.9126, -82.6856, 'Easterly flow allowed scattered to numerous thunderstorms to develop over the Florida Peninsula and push west into the eastern Gulf of Mexico. Some of these storms produced gusty winds along the coast.', 'The ASOS at St. Pete-Clearwater International Airport (KPIE) recorded a 37 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (771098, 201808, 27, 1701, 201808, 27, 1701, 128524, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '27-AUG-18 17:01:00', 'EST-5', '27-AUG-18 17:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'EG', NULL, NULL, 7, 'W', 'LOWER TAMPA BAY', 7, 'W', 'LOWER TAMPA BAY', 27.61, -82.76, 27.61, -82.76, 'Easterly flow and deep moisture allowed scattered to numerous thunderstorms to develop over Florida and push west into the eastern Gulf of Mexico during the afternoon and early evening. At least one of these storms produced gusty winds along the coast.', 'The WeatherFlow station near Egmont Key (XEGM) recorded a 36 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (771111, 201808, 28, 1529, 201808, 28, 1529, 128529, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '28-AUG-18 15:29:00', 'EST-5', '28-AUG-18 15:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 44, 'MG', NULL, NULL, 1, 'SSE', 'LONGBOAT KEY', 1, 'SSE', 'LONGBOAT KEY', 27.4015, -82.5586, 27.4015, -82.5586, 'Numerous thunderstorms developed across Florida during the afternoon and shifted west into the eastern Gulf of Mexico during the late afternoon and early evening. Some of these storms produced gusty winds along the coast.', 'The ASOS at Sarasota-Bradenton International Airport (KSRQ) recorded a 44 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (771112, 201808, 28, 1602, 201808, 28, 1602, 128529, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '28-AUG-18 16:02:00', 'EST-5', '28-AUG-18 16:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 43, 'MG', NULL, NULL, 6, 'W', 'MIDDLE TAMPA BAY', 6, 'W', 'MIDDLE TAMPA BAY', 27.7685, -82.6257, 27.7685, -82.6257, 'Numerous thunderstorms developed across Florida during the afternoon and shifted west into the eastern Gulf of Mexico during the late afternoon and early evening. Some of these storms produced gusty winds along the coast.', 'The ASOS at Albert Whitted Airport (KSPG) recorded a 43 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (771116, 201808, 28, 1611, 201808, 28, 1611, 128529, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '28-AUG-18 16:11:00', 'EST-5', '28-AUG-18 16:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 48, 'EG', NULL, NULL, 7, 'W', 'LOWER TAMPA BAY', 7, 'W', 'LOWER TAMPA BAY', 27.61, -82.76, 27.61, -82.76, 'Numerous thunderstorms developed across Florida during the afternoon and shifted west into the eastern Gulf of Mexico during the late afternoon and early evening. Some of these storms produced gusty winds along the coast.', 'The WeatherFlow station near Egmont Key (XEGM) recorded a 48 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (771117, 201808, 28, 1642, 201808, 28, 1642, 128529, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'TBW', '28-AUG-18 16:42:00', 'EST-5', '28-AUG-18 16:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'EG', NULL, NULL, 3, 'SSE', 'CLEARWATER BEACH', 3, 'SSE', 'CLEARWATER BEACH', 27.94, -82.8, 27.94, -82.8, 'Numerous thunderstorms developed across Florida during the afternoon and shifted west into the eastern Gulf of Mexico during the late afternoon and early evening. Some of these storms produced gusty winds along the coast.', 'The WeatherFlow station in Belleair (XBLA) recorded a 37 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (771118, 201808, 28, 1640, 201808, 28, 1640, 128530, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'TBW', '28-AUG-18 16:40:00', 'EST-5', '28-AUG-18 16:40:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'BAY PINES', 1, 'W', 'BAY PINES', 27.82, -82.79, 27.82, -82.79, 'Numerous thunderstorms developed across Florida during the afternoon and shifted west into the eastern Gulf of Mexico during the late afternoon and early evening. Some of these storms produced gusty winds along the coast.', 'A tree was blown over by thunderstorm wind gusts in Seminole.');
INSERT INTO public.stormevents_east VALUES (766135, 201808, 12, 1405, 201808, 12, 1415, 127745, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '12-AUG-18 14:05:00', 'EST-5', '12-AUG-18 14:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 40, 'EG', NULL, NULL, 1, 'NNE', 'SOUTH COLUMBUS', 1, 'NNE', 'SOUTH COLUMBUS', 39.94, -82.99, 39.94, -82.99, 'Isolated thunderstorms developed in the vicinity of an upper level low which was meandering through the region.', 'One tree was knocked down in Schiller Park.');
INSERT INTO public.stormevents_east VALUES (767592, 201808, 10, 1829, 201808, 10, 1839, 127532, 'OHIO', 39, 2018, 'August', 'Thunderstorm Wind', 'ILN', '10-AUG-18 18:29:00', 'EST-5', '10-AUG-18 18:39:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'W', 'KIOUSVILLE', 4, 'W', 'KIOUSVILLE', 39.807, -83.3655, 39.807, -83.3655, 'Scattered thunderstorms developed ahead of a cold front which was dropping south through the region. The thunderstorms produced heavy rain, which produced some flooding.', 'A barn was destroyed.');
INSERT INTO public.stormevents_east VALUES (751425, 201805, 4, 2004, 201805, 4, 2004, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 20:04:00', 'EST-5', '04-MAY-18 20:04:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'S', 'VALATIE', 1, 'S', 'VALATIE', 42.4105, -73.6779, 42.4105, -73.6779, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A tree was downed across a road.');
INSERT INTO public.stormevents_east VALUES (751129, 201805, 4, 1821, 201805, 4, 1821, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:21:00', 'EST-5', '04-MAY-18 18:21:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'ST JOHNSVILLE', 1, 'W', 'ST JOHNSVILLE', 43, -74.68, 43, -74.68, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A large tree and wires were reported down.');
INSERT INTO public.stormevents_east VALUES (751427, 201805, 4, 2008, 201805, 4, 2008, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 20:08:00', 'EST-5', '04-MAY-18 20:08:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'CATSKILL', 0, 'N', 'CATSKILL', 42.22, -73.87, 42.22, -73.87, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees were reported down.');
INSERT INTO public.stormevents_east VALUES (779001, 201808, 3, 1630, 201808, 3, 1715, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 16:30:00', 'EST-5', '03-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'THOMASVILLE', 1, 'E', 'CEDAR LODGE', 35.87, -80.0829, 35.8301, -80.09, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Flooding was reported on Highway 109.');
INSERT INTO public.stormevents_east VALUES (779002, 201808, 3, 1645, 201808, 3, 1715, 129855, 'NORTH CAROLINA', 37, 2018, 'August', 'Flash Flood', 'RAH', '03-AUG-18 16:45:00', 'EST-5', '03-AUG-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'GLEN ANNA', 1, 'ESE', 'GLEN ANNA', 35.84, -80.09, 35.8407, -80.0783, 'A persistent plume of tropical moisture and embedded perturbations aloft triggered clusters of convection with torrential downpours. Since the wind field was fairly unidirectional, training cells lead to locally excessive rainfall and flash flooding, along with isolated wind damage.', 'Several road were reported flooded in Thomasville and Lexington, including Fisher Ferry Road and East H.');
INSERT INTO public.stormevents_east VALUES (780028, 201808, 11, 27, 201808, 11, 27, 130221, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'RAH', '11-AUG-18 00:27:00', 'EST-5', '11-AUG-18 00:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1, NULL, NULL, NULL, 1, 'SW', 'STAR', 1, 'SW', 'STAR', 35.39, -79.81, 35.39, -79.81, 'A deamplifying mid to upper level wave glanced a west to east oriented surface to 850mb front over central North Carolina and resulted in repeated updraft intensification and eastward propagation along the front, which allowed for several strong to severe storms to develop.', NULL);
INSERT INTO public.stormevents_east VALUES (780029, 201808, 11, 133, 201808, 11, 133, 130221, 'NORTH CAROLINA', 37, 2018, 'August', 'Hail', 'RAH', '11-AUG-18 01:33:00', 'EST-5', '11-AUG-18 01:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 4, 'W', 'CAMERON', 4, 'W', 'CAMERON', 35.33, -79.32, 35.33, -79.32, 'A deamplifying mid to upper level wave glanced a west to east oriented surface to 850mb front over central North Carolina and resulted in repeated updraft intensification and eastward propagation along the front, which allowed for several strong to severe storms to develop.', NULL);
INSERT INTO public.stormevents_east VALUES (780031, 201808, 11, 120, 201808, 11, 120, 130221, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '11-AUG-18 01:20:00', 'EST-5', '11-AUG-18 01:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NE', 'HILL CREST', 1, 'NE', 'HILL CREST', 35.3306, -79.4031, 35.3306, -79.4031, 'A deamplifying mid to upper level wave glanced a west to east oriented surface to 850mb front over central North Carolina and resulted in repeated updraft intensification and eastward propagation along the front, which allowed for several strong to severe storms to develop.', 'One tree was reported down on Highway 15-501 and Vass Carthage Road.');
INSERT INTO public.stormevents_east VALUES (780032, 201808, 11, 137, 201808, 11, 137, 130221, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '11-AUG-18 01:37:00', 'EST-5', '11-AUG-18 01:37:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'VASS', 1, 'NW', 'VASS', 35.26, -79.29, 35.26, -79.29, 'A deamplifying mid to upper level wave glanced a west to east oriented surface to 850mb front over central North Carolina and resulted in repeated updraft intensification and eastward propagation along the front, which allowed for several strong to severe storms to develop.', 'Power lines were reported damaged and down due to large branches falling into them.');
INSERT INTO public.stormevents_east VALUES (780034, 201808, 11, 1525, 201808, 11, 1525, 130221, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '11-AUG-18 15:25:00', 'EST-5', '11-AUG-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'PATETOWN', 1, 'NNW', 'PATETOWN', 35.4794, -77.9366, 35.4794, -77.9366, 'A deamplifying mid to upper level wave glanced a west to east oriented surface to 850mb front over central North Carolina and resulted in repeated updraft intensification and eastward propagation along the front, which allowed for several strong to severe storms to develop.', 'One tree was reported down on the 500 block of Forehand Road.');
INSERT INTO public.stormevents_east VALUES (781049, 201808, 8, 1435, 201808, 8, 1435, 130486, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 14:35:00', 'EST-5', '08-AUG-18 14:35:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 3, 'N', 'MERCER', 3, 'N', 'MERCER', 30.31, -83.12, 30.31, -83.12, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'A tree and power line were blown down on 76th Street. The time of damage was based on radar. The cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781050, 201808, 8, 1440, 201808, 8, 1440, 130486, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 14:40:00', 'EST-5', '08-AUG-18 14:40:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 4, 'ENE', 'ELLAVILLE', 4, 'ENE', 'ELLAVILLE', 30.42, -83.11, 30.42, -83.11, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'A tree and power line were blown down on 16th Street. The time was based on radar, and the cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781052, 201808, 8, 1720, 201808, 8, 1720, 130487, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 17:20:00', 'EST-5', '08-AUG-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'N', 'WILLACOOCHEE', 3, 'N', 'WILLACOOCHEE', 31.37, -83.05, 31.37, -83.05, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'Trees were blown down near Willacoochee. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (781053, 201808, 8, 1745, 201808, 8, 1745, 130487, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 17:45:00', 'EST-5', '08-AUG-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'MORA', 1, 'N', 'MORA', 31.44, -82.97, 31.44, -82.97, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'Trees were blown down SW of Douglas. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (781054, 201808, 8, 1800, 201808, 8, 1800, 130487, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 18:00:00', 'EST-5', '08-AUG-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'HAYWOOD', 1, 'SE', 'HAYWOOD', 31.34, -82.42, 31.34, -82.42, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'A tree and power line were blown down along Dixie Union Road. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (781058, 201808, 8, 1740, 201808, 8, 1740, 130487, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 17:40:00', 'EST-5', '08-AUG-18 17:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 3, 'WSW', 'MORA', 3, 'WSW', 'MORA', 31.4082, -83.0158, 31.4082, -83.0158, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'Storm damage occurred along Ice Plant Road and Talmadge McKinnon Road. A home had some roof damage over a carport. There were numerous trees blown down, all going in the same direction. Small pea size hail was also reported.');
INSERT INTO public.stormevents_east VALUES (781060, 201808, 8, 1600, 201808, 8, 1600, 130486, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '08-AUG-18 16:00:00', 'EST-5', '08-AUG-18 16:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'SE', 'HEDGES', 1, 'SE', 'HEDGES', 30.5938, -81.5914, 30.5938, -81.5914, 'Sea breeze storms and boundary mergers produced scattered severe storms over an unstable airmass.', 'A large oak tree was blown down onto a mobile home along Patches Lane in Yulee. The time of damage was based on radar. The cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (781063, 201808, 9, 1442, 201808, 9, 1442, 130488, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '09-AUG-18 14:42:00', 'EST-5', '09-AUG-18 14:42:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'SSE', 'PALM VLY', 5, 'SSE', 'PALM VLY', 30.117, -81.3602, 30.117, -81.3602, 'Increasing SW steering flow and moisture fueled scattered sea breeze storms. Boundary collisions near the east coast sea breeze front triggered stronger storm growth in the afternoon and early evening as activity moved offshore.', 'Power lines were blown down along Ponte Vedra Blvd. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (782257, 201808, 15, 1606, 201808, 15, 1606, 130727, 'NEW YORK', 36, 2018, 'August', 'Hail', 'BUF', '15-AUG-18 16:06:00', 'EST-5', '15-AUG-18 16:06:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', 1.75, NULL, NULL, NULL, 0, 'E', 'FINEVIEW', 0, 'E', 'FINEVIEW', 44.28, -76.01, 44.28, -76.01, 'Thunderstorms developed as expected north of Lake Ontario across southern Ontario province. Storms just on the north side of the St. Lawrence River began to strengthen during the afternoon. The storms continued to strengthen as they approached the area with impressive lightning jumps and impressive reflectivity cores aloft that included 60 dbz over 30kft and 50 dbz to around 40 kft.', NULL);
INSERT INTO public.stormevents_east VALUES (782263, 201808, 21, 1945, 201808, 21, 1945, 130730, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '21-AUG-18 19:45:00', 'EST-5', '21-AUG-18 19:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'W', 'CUBA', 1, 'W', 'CUBA', 42.22, -78.28, 42.22, -78.28, 'A pre-frontal trough moved through with ample wind shear while in a marginal risk during the afternoon. This touched off several lines of convection. One storm of interest with notable rotation moved through Allegany State Park. A few more storms developed during the afternoon and evening hours that didn''t last as long nor look as impressive on radar.', 'Trees and wires reported down by law enforcement.');
INSERT INTO public.stormevents_east VALUES (782267, 201808, 8, 1050, 201808, 8, 1050, 130552, 'NEW YORK', 36, 2018, 'August', 'Thunderstorm Wind', 'BUF', '08-AUG-18 10:50:00', 'EST-5', '08-AUG-18 10:50:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'NNE', 'FARMINGTON', 1, 'NNE', 'FARMINGTON', 43, -77.32, 43, -77.32, 'The region was in a moist southwest flow with a weak ridge across the southeastern states and an shortwave digging into eastern Michigan. The 12z BUF sounding had a precipitable water value of 1.78 inches but very limited wind shear with 15 kts at 850mb and 20 kts at 700 mb. Despite this limited shear, an impressive storm developed across lake Erie around 7 AM and slowly tracked across the Buffalo metro area around 9 AM. The same storm moved eastward toward Victor, producing mainly heavy rainfall with radar estimates near 2 inches.', 'The Sheriff reported trees down in Farmington.');
INSERT INTO public.stormevents_east VALUES (782268, 201808, 6, 1436, 201808, 6, 1436, 130550, 'NEW YORK', 36, 2018, 'August', 'Hail', 'BUF', '06-AUG-18 14:36:00', 'EST-5', '06-AUG-18 14:36:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 0.75, NULL, NULL, NULL, 0, 'N', 'MACEDON', 0, 'N', 'MACEDON', 43.07, -77.3, 43.07, -77.3, 'A benign surface map featured a diffuse high pressure system across the mid-Atlantic states. Southwesterly flow ahead of a shortwave moving across southern Ontario advected moist and unstable air into the area. Despite ample instability, wind fields were weak, suggesting an environment favorable for pulse storms. While storms developed south of Lake Ontario in New York, the strongest storms were in Ontario.', NULL);
INSERT INTO public.stormevents_east VALUES (782272, 201808, 8, 1414, 201808, 8, 1414, 130552, 'NEW YORK', 36, 2018, 'August', 'Heavy Rain', 'BUF', '08-AUG-18 14:14:00', 'EST-5', '08-AUG-18 14:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'S', 'EAST CONCORD', 1, 'S', 'EAST CONCORD', 42.53, -78.63, 42.53, -78.63, 'The region was in a moist southwest flow with a weak ridge across the southeastern states and an shortwave digging into eastern Michigan. The 12z BUF sounding had a precipitable water value of 1.78 inches but very limited wind shear with 15 kts at 850mb and 20 kts at 700 mb. Despite this limited shear, an impressive storm developed across lake Erie around 7 AM and slowly tracked across the Buffalo metro area around 9 AM. The same storm moved eastward toward Victor, producing mainly heavy rainfall with radar estimates near 2 inches.', 'Spotter reported 2.30 inches of rain.');
INSERT INTO public.stormevents_east VALUES (782214, 201808, 7, 1855, 201808, 7, 1855, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 18:55:00', 'EST-5', '07-AUG-18 18:55:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'ORRINGTON', 0, 'N', 'ORRINGTON', 44.73, -68.82, 44.73, -68.82, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees and power lines were toppled by wind gusts estimated at 60 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (782217, 201808, 7, 1910, 201808, 7, 1910, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 19:10:00', 'EST-5', '07-AUG-18 19:10:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'CLIFTON', 0, 'N', 'CLIFTON', 44.82, -68.5, 44.82, -68.5, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees and power lines were toppled by wind gusts estimated at 60 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (782218, 201808, 9, 1214, 201808, 9, 1214, 130720, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '09-AUG-18 12:14:00', 'EST-5', '09-AUG-18 12:14:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 61, 'EG', NULL, NULL, 0, 'N', 'LEVANT', 0, 'N', 'LEVANT', 44.87, -68.92, 44.87, -68.92, 'Low pressure tracking across northern Maine pulled a cold front across the region through the afternoon into the evening of the 9th. Thunderstorms developed in advance of the front. Some storms became severe producing damaging winds.', 'Trees and power poles were toppled and snapped on Budget Road...Black Road and Union Street by wind gusts estimated at up to 70 mph.');
INSERT INTO public.stormevents_east VALUES (782219, 201808, 9, 1220, 201808, 9, 1220, 130720, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '09-AUG-18 12:20:00', 'EST-5', '09-AUG-18 12:20:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', 61, 'EG', NULL, NULL, 0, 'N', 'KENDUSKEAG', 0, 'N', 'KENDUSKEAG', 44.92, -68.92, 44.92, -68.92, 'Low pressure tracking across northern Maine pulled a cold front across the region through the afternoon into the evening of the 9th. Thunderstorms developed in advance of the front. Some storms became severe producing damaging winds.', 'Between 15 and 20 trees and around 10 power poles were toppled or snapped by straight-line wind gusts estimated at up to 70 mph. Portions of a metal roof were also torn from a barn. The damage occurred along an approximately 1 mile portion of Route 15 near Kenduskeag.');
INSERT INTO public.stormevents_east VALUES (782220, 201808, 9, 1226, 201808, 9, 1226, 130720, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '09-AUG-18 12:26:00', 'EST-5', '09-AUG-18 12:26:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 56, 'EG', NULL, NULL, 1, 'NNW', 'WEST GLENBURN', 1, 'NNW', 'WEST GLENBURN', 44.9, -68.88, 44.9, -68.88, 'Low pressure tracking across northern Maine pulled a cold front across the region through the afternoon into the evening of the 9th. Thunderstorms developed in advance of the front. Some storms became severe producing damaging winds.', 'A tree was toppled on to a house on Lancaster Brook Road by wind gusts estimated at 65 mph. The time is estimated.');
INSERT INTO public.stormevents_east VALUES (782221, 201808, 9, 1315, 201808, 9, 1315, 130720, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '09-AUG-18 13:15:00', 'EST-5', '09-AUG-18 13:15:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'BUCKSPORT', 0, 'N', 'BUCKSPORT', 44.57, -68.78, 44.57, -68.78, 'Low pressure tracking across northern Maine pulled a cold front across the region through the afternoon into the evening of the 9th. Thunderstorms developed in advance of the front. Some storms became severe producing damaging winds.', 'A tree was toppled on Masthill Road...with another tree toppled on Williams Pond Road...by wind gusts estimated at 60 mph. The toppled tree on Williams Pond Road also brought down power lines.');
INSERT INTO public.stormevents_east VALUES (782129, 201808, 18, 1902, 201808, 18, 1902, 130699, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'GSP', '18-AUG-18 19:02:00', 'EST-5', '18-AUG-18 19:02:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'GREENWOOD', 1, 'E', 'GREENWOOD', 34.18, -82.16, 34.18, -82.16, 'Several clusters of thunderstorms producing gusty winds developed across Upstate South Carolina during the afternoon and evening.', 'County comms reported a large tree limb fell on a vehicle on West Creswell Ave.');
INSERT INTO public.stormevents_east VALUES (782130, 201808, 19, 1926, 201808, 19, 1926, 130701, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '19-AUG-18 19:26:00', 'EST-5', '19-AUG-18 19:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 3, 'E', 'MOORESVILLE', 3, 'E', 'MOORESVILLE', 35.572, -80.767, 35.572, -80.767, 'Isolated thunderstorms developed over the North Carolina Piedmont during the evening. One of the storms produced brief damaging winds in Iredell County.', 'FD reported multiple trees blown down on Brumley Rd.');
INSERT INTO public.stormevents_east VALUES (782139, 201808, 30, 1349, 201808, 30, 1350, 130707, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '30-AUG-18 13:49:00', 'EST-5', '30-AUG-18 13:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'HAZELWOOD', 1, 'ESE', 'WAYNESVILLE', 35.482, -83.007, 35.49, -82.981, 'Isolated thunderstorms developed throughout western North Carolina during the afternoon and evening. Several of the storms produced brief damaging winds.', 'County comms reported multiple trees and power lines blown down in Waynesville, especially across the west side of town, including on Elysinia Ave, Pine Dr, and Hazelwood Ave.');
INSERT INTO public.stormevents_east VALUES (782140, 201808, 30, 1630, 201808, 30, 1630, 130707, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '30-AUG-18 16:30:00', 'EST-5', '30-AUG-18 16:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SSE', 'FAIRVIEW', 1, 'SSE', 'FAIRVIEW', 35.134, -80.546, 35.134, -80.546, 'Isolated thunderstorms developed throughout western North Carolina during the afternoon and evening. Several of the storms produced brief damaging winds.', 'EM reported multiple trees blown down with minor damage to a trailer on Brent Haigler Rd.');
INSERT INTO public.stormevents_east VALUES (782141, 201808, 30, 1359, 201808, 30, 1359, 130707, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '30-AUG-18 13:59:00', 'EST-5', '30-AUG-18 13:59:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'BANKS CREEK', 2, 'SSW', 'BANKS CREEK', 35.87, -82.38, 35.87, -82.38, 'Isolated thunderstorms developed throughout western North Carolina during the afternoon and evening. Several of the storms produced brief damaging winds.', 'County comms reported multiple trees blown down to the south of Burnsville.');
INSERT INTO public.stormevents_east VALUES (782213, 201808, 30, 2106, 201808, 30, 2106, 130707, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '30-AUG-18 21:06:00', 'EST-5', '30-AUG-18 21:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'E', 'CHINA GROVE', 1, 'WSW', 'CHINA GROVE ARPT', 35.57, -80.571, 35.544, -80.554, 'Isolated thunderstorms developed throughout western North Carolina during the afternoon and evening. Several of the storms produced brief damaging winds.', 'Spotter reported a tree blown down blocking Highway 29 and numerous trees blown down along Daugherty Rd.');
INSERT INTO public.stormevents_east VALUES (782223, 201808, 31, 1551, 201808, 31, 1551, 130721, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '31-AUG-18 15:51:00', 'EST-5', '31-AUG-18 15:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 50, 'MG', NULL, NULL, 0, 'N', '(CLT)CHARLOTTE/DOUGL', 0, 'N', '(CLT)CHARLOTTE/DOUGL', 35.22, -80.95, 35.22, -80.95, 'Isolated thunderstorms developed during the afternoon and evening over the foothills and western Piedmont of North Carolina. A few of the storms produced brief damaging winds.', 'The ASOS at the Charlotte Douglass Airport measured a wind gust of 58 mph (50 kts).');
INSERT INTO public.stormevents_east VALUES (782224, 201808, 31, 1717, 201808, 31, 1717, 130721, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'GSP', '31-AUG-18 17:17:00', 'EST-5', '31-AUG-18 17:17:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNE', 'HARDINS', 2, 'NNE', 'HARDINS', 35.4, -81.184, 35.4, -81.184, 'Isolated thunderstorms developed during the afternoon and evening over the foothills and western Piedmont of North Carolina. A few of the storms produced brief damaging winds.', 'County comms reported trees blown down near Philadelphia Church and Hardin Roads.');
INSERT INTO public.stormevents_east VALUES (780475, 201808, 4, 1036, 201808, 4, 1300, 130372, 'RHODE ISLAND', 44, 2018, 'August', 'Flood', 'BOX', '04-AUG-18 10:36:00', 'EST-5', '04-AUG-18 13:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'OAK LAWN', 0, 'SSE', 'OAK LAWN', 41.7467, -71.4796, 41.747, -71.4786, 'An atmospheric trough moved over Rhode Island on the 4th, tapping high amounts of moisture in the air to cause heavy showers that resulted in flooding.', 'At 10:36 AM EST, a car was trapped in flooding at an underpass on Wilbur Avenue near the intersection with Oaklawn Avenue in Cranston.');
INSERT INTO public.stormevents_east VALUES (780510, 201808, 7, 2050, 201808, 7, 2215, 130377, 'CONNECTICUT', 9, 2018, 'August', 'Flash Flood', 'BOX', '07-AUG-18 20:50:00', 'EST-5', '07-AUG-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'NORTH BLOOMFIELD', 1, 'S', 'NORTH BLOOMFIELD', 41.8716, -72.753, 41.8717, -72.7517, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts. The airmass over the state was very humid and unstable. This generated strong thunderstorms and downpours over Connecticut.', 'At 8:50 PM EST, three feet of water was reported on Walts Hill road in North Bloomfield.');
INSERT INTO public.stormevents_east VALUES (780511, 201808, 7, 2126, 201808, 7, 2220, 130377, 'CONNECTICUT', 9, 2018, 'August', 'Flash Flood', 'BOX', '07-AUG-18 21:26:00', 'EST-5', '07-AUG-18 22:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'WINDSOR', 1, 'NNE', 'WINDSOR', 41.8657, -72.643, 41.8657, -72.6424, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts. The airmass over the state was very humid and unstable. This generated strong thunderstorms and downpours over Connecticut.', 'At 9:26 PM EST, Sleepy Hollow Road in Windsor was closed at Pierson Lane due to flooding.');
INSERT INTO public.stormevents_east VALUES (780514, 201808, 7, 2135, 201808, 7, 2220, 130377, 'CONNECTICUT', 9, 2018, 'August', 'Flash Flood', 'BOX', '07-AUG-18 21:35:00', 'EST-5', '07-AUG-18 22:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'WINDSOR LOCKS', 0, 'WNW', 'WINDSOR LOCKS', 41.9308, -72.6339, 41.931, -72.6327, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts. The airmass over the state was very humid and unstable. This generated strong thunderstorms and downpours over Connecticut.', 'At 9:35 PM EST, Center Street in Windsor Locks was closed due to flooding between Spring Street and Elm Street.');
INSERT INTO public.stormevents_east VALUES (783338, 201808, 27, 2240, 201808, 27, 2240, 130922, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '27-AUG-18 22:40:00', 'EST-5', '27-AUG-18 22:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 34, 'MG', NULL, NULL, 3, 'WNW', 'LAYTON', 3, 'WNW', 'LAYTON', 24.843, -80.862, 24.843, -80.862, 'Scattered thunderstorms associated with a westward-moving inverted surface trough of low pressure produced scattered areas of gale-force wind gusts, mainly from over and offshore the Upper Keys through Duck Key, FL.', 'A wind gust of 34 knots was measured at Long Key Light.');
INSERT INTO public.stormevents_east VALUES (783339, 201808, 29, 1359, 201808, 29, 1359, 130925, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 13:59:00', 'EST-5', '29-AUG-18 13:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 34, 'MG', NULL, NULL, 10, 'ENE', 'DRY TORTUGAS LIGHT', 10, 'ENE', 'DRY TORTUGAS LIGHT', 24.693, -82.773, 24.693, -82.773, 'An isolated rain shower produced a gale-force wind gust near Dry Tortugas National Park.', 'A wind gust of 34 knots was measured at Pulaski Shoal Light.');
INSERT INTO public.stormevents_east VALUES (783340, 201808, 29, 2105, 201808, 29, 2105, 130926, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 21:05:00', 'EST-5', '29-AUG-18 21:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'Scattered thunderstorms moving northwest in a fast and deep 15 to 20-knot flow from near the surface through 15,000 feet produced scattered gale-force wind gusts.', 'A wind gust of 36 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
INSERT INTO public.stormevents_east VALUES (783341, 201808, 29, 2117, 201808, 29, 2117, 130926, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 21:17:00', 'EST-5', '29-AUG-18 21:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 8, 'NNW', 'CARYSFORT REEF LIGHT', 8, 'NNW', 'CARYSFORT REEF LIGHT', 25.3208, -80.2792, 25.3208, -80.2792, 'Scattered thunderstorms moving northwest in a fast and deep 15 to 20-knot flow from near the surface through 15,000 feet produced scattered gale-force wind gusts.', 'A wind gust of 35 knots was measured at an automated Citizen Weather Observing Program station at the Ocean Reef Club Airport, operated by the Monroe County Mosquito Control District.');
INSERT INTO public.stormevents_east VALUES (783342, 201808, 29, 2152, 201808, 29, 2152, 130926, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 21:52:00', 'EST-5', '29-AUG-18 21:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR REEF LIGHT', 0, 'N', 'ALLIGATOR REEF LIGHT', 24.85, -80.62, 24.85, -80.62, 'Scattered thunderstorms moving northwest in a fast and deep 15 to 20-knot flow from near the surface through 15,000 feet produced scattered gale-force wind gusts.', 'A wind gust of 34 knots was measured by an automated WeatherFlow station at Alligator Reef Light.');
INSERT INTO public.stormevents_east VALUES (783343, 201808, 29, 2042, 201808, 29, 2042, 130926, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 20:42:00', 'EST-5', '29-AUG-18 20:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 37, 'MG', NULL, NULL, 1, 'WSW', 'MARATHON', 1, 'WSW', 'MARATHON', 24.711, -81.107, 24.711, -81.107, 'Scattered thunderstorms moving northwest in a fast and deep 15 to 20-knot flow from near the surface through 15,000 feet produced scattered gale-force wind gusts.', 'A wind gust of 37 knots was measured at an automated National Ocean Service tide station on Vaca Key, near the USCG Station Marathon.');
INSERT INTO public.stormevents_east VALUES (783344, 201808, 29, 2233, 201808, 29, 2233, 130926, 'GULF OF MEXICO', 85, 2018, 'August', 'Marine Thunderstorm Wind', 'KEY', '29-AUG-18 22:33:00', 'EST-5', '29-AUG-18 22:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'Scattered thunderstorms moving northwest in a fast and deep 15 to 20-knot flow from near the surface through 15,000 feet produced scattered gale-force wind gusts.', 'A wind gust of 34 knots was measured at an automated Citizen Weather Observing Program station at Duck Key.');
INSERT INTO public.stormevents_east VALUES (748630, 201804, 15, 1808, 201804, 15, 1825, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 18:08:00', 'EST-5', '15-APR-18 18:25:00', 7, 0, 0, 0, '4.30M', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WSW', 'DILLARD', 3, 'SW', 'SARDIS', 37.4586, -79.1838, 37.606, -79.163, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'This is the third and final segment of a tornado that touched down just south of Waterlink Road near Timberlake in Campbell County at 6:00 PM EST. The tornado crossed through the independent city of Lynchburg and eventually tracked over the James River into Amherst County at 6:08 PM EST.  This was only the third EF3 tornado to occur in the NWS Blacksburg forecast since 1950, and was the longest track tornado within the state of Virginia for the NWS Blacksburg forecast area. The tornado reached its peak intensity with estimated maximum winds of 150 MPH as it crossed Route 130 and entered the town of Elon.  A total of 166 homes suffered damage, and 22 of those homes were considered a total loss.  A motor home was carried about thirty feet and tipped over.  The hardest hit locations were along Nottaway Drive and Deerfield Drive.  Seven people were injured and taken to the hospital from Elon.  As the tornado continued north-northeastward out of Elon, it snapped or uprooted hundreds of trees and caused more minor roof damage to homes.  At 6:25 PM EST, the tornado finally lifted as it began to head up Shady Mountain Ridge, which is about five and a half miles west-northwest of Amherst.');
INSERT INTO public.stormevents_east VALUES (752649, 201804, 15, 1735, 201804, 15, 1740, 123442, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RNK', '15-APR-18 17:35:00', 'EST-5', '15-APR-18 17:40:00', 0, 0, 0, 0, '50.00K', '0.00K', 'NWS Storm Survey', 78, 'EG', NULL, NULL, 3, 'NE', 'GRETNA', 3, 'ESE', 'SYCAMORE', 36.978, -79.339, 37.02, -79.299, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'Thunderstorm winds produced isolated pockets of damage form Burke Road to just northeast of Blue Ridge Drive, two miles northeast of Gretna. Three homes sustained significant roof damage and several outbuildings were destroyed.');
INSERT INTO public.stormevents_east VALUES (775723, 201808, 4, 828, 201808, 4, 917, 129483, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '04-AUG-18 08:28:00', 'EST-5', '04-AUG-18 09:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'BERKELEY HGTS', 2, 'S', 'MURRAY HILL', 40.6543, -74.404, 40.655, -74.4029, 'A developing area of low pressure along a surface trough helped produce heavy rainfall across parts of northeast New Jersey on the morning of August 4th that resulted in flash flooding. Rainfall amounts ranged from 1-3 inches in many places. Between the afternoon of August 3rd and the afternoon of August 4th, the Caldwell, NJ ASOS measured 2.75, and CoCoRaHS observers in Park Ridge and Hawthorne measured 2.90 and 2.95, respectively, with a CWOP station in Scotch Plains reporting 2.42.', 'Flooding closed all westbound lanes of US Route 22 in Scotch Plains at the intersection with Bonnie Burn Road and Park Avenue.');
INSERT INTO public.stormevents_east VALUES (775724, 201808, 4, 845, 201808, 4, 917, 129483, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '04-AUG-18 08:45:00', 'EST-5', '04-AUG-18 09:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'NEW PROVIDENCE', 1, 'NNW', 'NEW PROVIDENCE', 40.7118, -74.3878, 40.7127, -74.3861, 'A developing area of low pressure along a surface trough helped produce heavy rainfall across parts of northeast New Jersey on the morning of August 4th that resulted in flash flooding. Rainfall amounts ranged from 1-3 inches in many places. Between the afternoon of August 3rd and the afternoon of August 4th, the Caldwell, NJ ASOS measured 2.75, and CoCoRaHS observers in Park Ridge and Hawthorne measured 2.90 and 2.95, respectively, with a CWOP station in Scotch Plains reporting 2.42.', 'Both lanes of Division Avenue in Summit were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (775725, 201808, 4, 847, 201808, 4, 917, 129483, 'NEW JERSEY', 34, 2018, 'August', 'Flash Flood', 'OKX', '04-AUG-18 08:47:00', 'EST-5', '04-AUG-18 09:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'WHITEOAK RIDGE', 0, 'NW', 'WHITEOAK RIDGE', 40.7553, -74.3073, 40.7545, -74.3053, 'A developing area of low pressure along a surface trough helped produce heavy rainfall across parts of northeast New Jersey on the morning of August 4th that resulted in flash flooding. Rainfall amounts ranged from 1-3 inches in many places. Between the afternoon of August 3rd and the afternoon of August 4th, the Caldwell, NJ ASOS measured 2.75, and CoCoRaHS observers in Park Ridge and Hawthorne measured 2.90 and 2.95, respectively, with a CWOP station in Scotch Plains reporting 2.42.', 'Old Short Hills Road was closed due to flooding in Millburn.');
INSERT INTO public.stormevents_east VALUES (766131, 201808, 14, 1700, 201808, 14, 1700, 127744, 'GEORGIA', 13, 2018, 'August', 'Heavy Rain', 'TAE', '14-AUG-18 17:00:00', 'EST-5', '14-AUG-18 17:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 0, 'N', 'THOMASVILLE', 0, 'N', 'THOMASVILLE', 30.83, -83.98, 30.83, -83.98, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'There were some reports of trees leaning on power lines in Thomasville, likely due to a combination of saturated soils from recent heavy rain and winds gusts of 40-50 mph.  Rainfall of 2.01 inches of rain fell in about 1 hour at mesonet station D2427 in Thomasville.');
INSERT INTO public.stormevents_east VALUES (769219, 201808, 13, 730, 201808, 13, 845, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:30:00', 'EST-5', '13-AUG-18 08:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'STRICKERSVILLE', 1, 'E', 'STRICKERSVILLE', 39.7401, -75.7695, 39.731, -75.7735, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Minor flooding occurred along the White Clay Creek near Strickersville.');
