INSERT INTO public.stormevents_east VALUES (769223, 201808, 13, 725, 201808, 13, 1130, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 07:25:00', 'EST-5', '13-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'FLORIDA PARK', 0, 'SSW', 'EDGEMONT', 39.9773, -75.4432, 39.965, -75.4326, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Moderate flooding occurred along Crum Creek near Newtown Square.');
INSERT INTO public.stormevents_east VALUES (769236, 201808, 13, 940, 201808, 13, 1130, 127603, 'PENNSYLVANIA', 42, 2018, 'August', 'Flash Flood', 'PHI', '13-AUG-18 09:40:00', 'EST-5', '13-AUG-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'PENNSBURG', 1, 'SW', 'EAST GREENVILLE', 40.3911, -75.5143, 40.4111, -75.5161, 'Rainfall totals of 2 to 4 inches were common in southeastern Pennsylvania with some locations receiving 5 to 6 inches of rain.  The heavy rain resulted in flash flooding.  Also, severe thunderstorms impacted the area.', 'Moderate flooding occurred along the East Branch of the Perkiomen Creek near East Greenville.');
