INSERT INTO public.stormevents_east VALUES (777956, 201808, 9, 1635, 201808, 9, 1645, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '09-AUG-18 16:35:00', 'EST-5', '09-AUG-18 16:45:00', 0, 0, 0, 0, '1.00K', NULL, 'Department of Highways', 45, 'EG', NULL, NULL, 2, 'W', 'FRANKLINTON', 2, 'W', 'FRANKLINTON', 32.7951, -83.5701, 32.7951, -83.5701, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Georgia Department of Transportation reported a tree blown down across the roadway in the 4900 block of Ocmulgee East Blvd.');
INSERT INTO public.stormevents_east VALUES (777957, 201808, 9, 1645, 201808, 9, 1655, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '09-AUG-18 16:45:00', 'EST-5', '09-AUG-18 16:55:00', 0, 0, 0, 0, '1.00K', NULL, 'Department of Highways', 45, 'EG', NULL, NULL, 2, 'NE', 'EASTBURN', 2, 'NE', 'EASTBURN', 34.6237, -83.648, 34.6237, -83.648, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Georgia Department of Transportation reported a tree blown down across power lines on Highway 255 at Goat Neck Road.');
INSERT INTO public.stormevents_east VALUES (777960, 201808, 9, 1715, 201808, 9, 1725, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '09-AUG-18 17:15:00', 'EST-5', '09-AUG-18 17:25:00', 0, 0, 0, 0, '1.00K', NULL, 'Fire Department/Rescue', 45, 'EG', NULL, NULL, 0, 'SW', 'BONAIRE', 0, 'SW', 'BONAIRE', 32.5446, -83.6044, 32.5446, -83.6044, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Houston County Fire Department reported a large tree blown down on Church Street at Old Perry Road.');
INSERT INTO public.stormevents_east VALUES (768731, 201806, 24, 1310, 201806, 24, 1310, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 13:10:00', 'EST-5', '24-JUN-18 13:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'NNW', 'BENSON', 2, 'NNW', 'BENSON', 35.4026, -78.5569, 35.4026, -78.5569, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'One tree was reported down on Dogeye Road near North Lincoln Street.');
INSERT INTO public.stormevents_east VALUES (768732, 201806, 24, 1408, 201806, 24, 1408, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 14:08:00', 'EST-5', '24-JUN-18 14:08:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'MONKS XRDS', 1, 'WNW', 'MONKS XRDS', 35.2286, -78.3491, 35.2286, -78.3491, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'One tree was reported down on Hobbton Highway near Alex Benton Road.');
INSERT INTO public.stormevents_east VALUES (768733, 201806, 24, 1420, 201806, 24, 1420, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 14:20:00', 'EST-5', '24-JUN-18 14:20:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'ESE', 'SUTTONTOWN', 2, 'ESE', 'SUTTONTOWN', 35.19, -78.21, 35.19, -78.21, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'One tree was reported down on power lines.');
INSERT INTO public.stormevents_east VALUES (768734, 201806, 24, 1444, 201806, 24, 1444, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 14:44:00', 'EST-5', '24-JUN-18 14:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'SSW', 'ERWIN ARPT', 4, 'SSW', 'ERWIN ARPT', 35.2727, -78.7371, 35.2727, -78.7371, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'One tree was reported down on North Carolina Highway 217 and Horseshoe Bend Road.');
INSERT INTO public.stormevents_east VALUES (768735, 201806, 24, 1445, 201806, 24, 1445, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 14:45:00', 'EST-5', '24-JUN-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'S', 'KIPLING', 2, 'S', 'KIPLING', 35.46, -78.82, 35.4578, -78.8182, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'One tree was reported down on shoulder of Ballard Road.');
INSERT INTO public.stormevents_east VALUES (768736, 201806, 24, 1520, 201806, 24, 1520, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 15:20:00', 'EST-5', '24-JUN-18 15:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SSW', 'MIDWAY', 1, 'SSW', 'MIDWAY', 35.1499, -78.4897, 35.1499, -78.4897, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'One tree was reported down on Mount Elam Church Road.');
INSERT INTO public.stormevents_east VALUES (776453, 201807, 21, 1724, 201807, 22, 802, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 17:24:00', 'EST-5', '22-JUL-18 08:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BRISTOW', 1, 'N', 'BRISTOW', 38.7307, -77.5318, 38.735, -77.5327, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'The stream gage on Broad Run near Bristow exceeded the flood stage of 9.5 feet during the indicated period. The peak level of 14.20 feet occurred at 9:06pm EST on July 21st. Piper Lane was significantly flooded near Manassas Airport, along with streamside trails.');
INSERT INTO public.stormevents_east VALUES (776459, 201807, 21, 2110, 201807, 22, 2040, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:10:00', 'EST-5', '22-JUL-18 20:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'YORKSHIRE', 1, 'NNW', 'YORKSHIRE', 38.7947, -77.4401, 38.7945, -77.435, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'The stream gage on Bull Run near Manassas Park exceeded the 12 foot flood stage during the indicated period. The peak level of 20.20 feet was observed at 8:45am EST on July 22nd. Streamside trails were flooded. Closer to peak levels, Lake Drive flooded in multiple spots, with overland flow affecting two basements in that same area.');
INSERT INTO public.stormevents_east VALUES (776461, 201807, 21, 1919, 201807, 22, 643, 128275, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 19:19:00', 'EST-5', '22-JUL-18 06:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'WALTER REED', 1, 'SW', 'WALTER REED', 38.9675, -77.0472, 38.971, -77.0452, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the District of Columbia. Rainfall totals of 3 to 5 inches were observed, causing flooding, especially along Rock Creek.', 'The stream gage on Rock Creek in Washington DC exceeded the flood stage of 7 feet during the indicated time period. The peak level of 8.40 feet was observed at 3:45am EST on July 22nd. Valley Trail and other portions of Rock Creek Park flooded.');
INSERT INTO public.stormevents_east VALUES (775501, 201807, 21, 1725, 201807, 21, 1930, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 17:25:00', 'EST-5', '21-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'MARYE', 0, 'SW', 'MARYE', 38.0783, -77.5828, 38.0782, -77.5827, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Twilight Lane flooded and closed near Marye Road.');
INSERT INTO public.stormevents_east VALUES (775502, 201807, 21, 1728, 201807, 21, 1830, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 17:28:00', 'EST-5', '21-JUL-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'NOKESVILLE', 1, 'NE', 'NOKESVILLE', 38.712, -77.5649, 38.712, -77.5646, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Northbound Route 28 flooded and impassable near Aden Road.');
INSERT INTO public.stormevents_east VALUES (756085, 201806, 18, 1528, 201806, 18, 1528, 126027, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '18-JUN-18 15:28:00', 'EST-5', '18-JUN-18 15:28:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'ALPHA', 1, 'SSE', 'ALPHA', 39.321, -76.926, 39.321, -76.926, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to some storms becoming severe.', 'A tree was down near the intersection of Henryton Road and Old Frederick Road.');
INSERT INTO public.stormevents_east VALUES (756086, 201806, 18, 1544, 201806, 18, 1544, 126027, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '18-JUN-18 15:44:00', 'EST-5', '18-JUN-18 15:44:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SE', 'HOWARDVILLE', 0, 'SE', 'HOWARDVILLE', 39.3773, -76.7251, 39.3773, -76.7251, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to some storms becoming severe.', 'Trees and wires were down near Reisterstown Road and Old Court Road.');
