INSERT INTO public.stormevents_east VALUES (756088, 201806, 18, 1600, 201806, 18, 1600, 126027, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '18-JUN-18 16:00:00', 'EST-5', '18-JUN-18 16:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WSW', 'ROGERS FORGE', 1, 'WSW', 'ROGERS FORGE', 39.395, -76.6213, 39.395, -76.6213, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to some storms becoming severe.', 'Multiple reports of trees were down in the Towson area.');
