INSERT INTO public.stormevents_east VALUES (756910, 201806, 19, 1345, 201806, 19, 1345, 126029, 'DISTRICT OF COLUMBIA', 11, 2018, 'June', 'Thunderstorm Wind', 'LWX', '19-JUN-18 13:45:00', 'EST-5', '19-JUN-18 13:45:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'SSE', 'ANACOSTIA', 0, 'SSE', 'ANACOSTIA', 38.8638, -76.9658, 38.8638, -76.9658, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to a couple storms becoming severe.', 'A large tree was down, blocking the road.');
INSERT INTO public.stormevents_east VALUES (756911, 201806, 19, 1322, 201806, 19, 1322, 126028, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '19-JUN-18 13:22:00', 'EST-5', '19-JUN-18 13:22:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'NNE', 'BLUEMONT', 0, 'NNE', 'BLUEMONT', 39.1232, -77.8185, 39.1232, -77.8185, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to an isolated thunderstorm becoming severe.', 'A tree was down blocking the road.');
INSERT INTO public.stormevents_east VALUES (756914, 201806, 20, 1426, 201806, 20, 1426, 126030, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '20-JUN-18 14:26:00', 'EST-5', '20-JUN-18 14:26:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'ORANGE', 1, 'SE', 'ORANGE', 38.2441, -78.1093, 38.2441, -78.1093, 'A cold front passed through the area. Hot and humid conditions ahead of the front led to some severe storms.', 'A few large trees were down in Orange.');
INSERT INTO public.stormevents_east VALUES (756915, 201806, 20, 1435, 201806, 20, 1435, 126030, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '20-JUN-18 14:35:00', 'EST-5', '20-JUN-18 14:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'UNIONVILLE', 1, 'E', 'UNIONVILLE', 38.2676, -77.9537, 38.2676, -77.9537, 'A cold front passed through the area. Hot and humid conditions ahead of the front led to some severe storms.', 'A large tree was down along the 24200 block of Narrow Gauge Road.');
INSERT INTO public.stormevents_east VALUES (756916, 201806, 20, 1456, 201806, 20, 1456, 126030, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '20-JUN-18 14:56:00', 'EST-5', '20-JUN-18 14:56:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'TATUM', 1, 'S', 'TATUM', 38.2085, -77.8994, 38.2085, -77.8994, 'A cold front passed through the area. Hot and humid conditions ahead of the front led to some severe storms.', 'A large tree was down.');
INSERT INTO public.stormevents_east VALUES (756918, 201806, 20, 1829, 201806, 20, 1829, 126030, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '20-JUN-18 18:29:00', 'EST-5', '20-JUN-18 18:29:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'GEER', 1, 'ESE', 'GEER', 38.2929, -78.4851, 38.2929, -78.4851, 'A cold front passed through the area. Hot and humid conditions ahead of the front led to some severe storms.', 'A tree was down at Garth Road and Pea Ridge road.');
INSERT INTO public.stormevents_east VALUES (764850, 201806, 3, 1600, 201806, 3, 1800, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:00:00', 'EST-5', '03-JUN-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'MARKHAM', 3, 'NW', 'ADA', 38.9, -78, 38.8569, -77.952, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Numerous roads flooded and closed in the I-66 corridor of the county, including Cabin Branch Road, Grove Lane, Crest Hill Road, Carrington Road, and Ashville Road.');
INSERT INTO public.stormevents_east VALUES (764851, 201806, 3, 1642, 201806, 3, 1830, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:42:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'FALMOUTH', 1, 'WNW', 'FERRY FARMS', 38.3288, -77.4502, 38.3287, -77.449, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Harrell Road flooded and closed near Falmouth.');
INSERT INTO public.stormevents_east VALUES (764852, 201806, 3, 1643, 201806, 3, 1830, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:43:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'FALMOUTH', 1, 'SE', 'FALMOUTH', 38.3172, -77.4634, 38.3152, -77.4628, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'River Road flooded and closed near Falmouth.');
INSERT INTO public.stormevents_east VALUES (764853, 201806, 3, 1645, 201806, 3, 1830, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:45:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'SULLIVAN', 2, 'SSW', 'SULLIVAN', 38.2911, -77.4101, 38.2911, -77.4096, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Colebrook Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (764854, 201806, 3, 1645, 201806, 3, 1830, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:45:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'BLOOKE', 2, 'SSW', 'BLOOKE', 38.3572, -77.3952, 38.3566, -77.3965, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Brooke Road flooded and closed near Daffan.');
INSERT INTO public.stormevents_east VALUES (764855, 201806, 3, 1646, 201806, 3, 1830, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:46:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'GLENDIA', 2, 'ENE', 'GLENDIA', 38.4147, -77.4976, 38.415, -77.4942, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Kellogg Mill Road flooded and closed near Abel Lake.');
INSERT INTO public.stormevents_east VALUES (764856, 201806, 3, 1647, 201806, 3, 1830, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 16:47:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'MOUNTAIN VIEW', 1, 'SSW', 'MOUNTAIN VIEW', 38.4557, -77.4771, 38.4553, -77.4769, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Shelton Shop Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (754519, 201805, 14, 1800, 201805, 14, 1800, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 18:00:00', 'EST-5', '14-MAY-18 18:00:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NNW', 'LANGLEY', 1, 'NNW', 'LANGLEY', 38.963, -77.178, 38.963, -77.178, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree fell onto a car along the George Washington Parkway near the Beltway.');
