INSERT INTO public.stormevents_east VALUES (754523, 201805, 14, 1720, 201805, 14, 1720, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:20:00', 'EST-5', '14-MAY-18 17:20:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 55, 'MG', NULL, NULL, 3, 'SW', 'MANASSAS', 3, 'SW', 'MANASSAS', 38.7207, -77.5181, 38.7207, -77.5181, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A wind gust of 63 mph was measured at the Manassas Airport.');
