INSERT INTO public.stormevents_east VALUES (768707, 201806, 23, 1543, 201806, 23, 1543, 128174, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '23-JUN-18 15:43:00', 'EST-5', '23-JUN-18 15:43:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'N', 'WEST UNION', 1, 'NNW', 'SALEM', 34.791, -83.045, 34.889, -82.976, 'A cluster of thunderstorms producing damaging wind gusts moved from northeast Georgia into the South Carolina mountains and foothills during the afternoon.', 'County comms reported numerous trees and power lines blown down between Walhalla and Salem.');
INSERT INTO public.stormevents_east VALUES (768708, 201806, 23, 1603, 201806, 23, 1616, 128174, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '23-JUN-18 16:03:00', 'EST-5', '23-JUN-18 16:16:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 0, 'WNW', 'PICKENS', 4, 'NE', 'LATHAM', 34.881, -82.702, 34.86, -82.5, 'A cluster of thunderstorms producing damaging wind gusts moved from northeast Georgia into the South Carolina mountains and foothills during the afternoon.', 'County comms reported numerous trees and power lines blown down, mainly across the eastern half of Pickens County.');
INSERT INTO public.stormevents_east VALUES (768709, 201806, 23, 1620, 201806, 23, 1620, 128174, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '23-JUN-18 16:20:00', 'EST-5', '23-JUN-18 16:20:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 40, 'EG', NULL, NULL, 3, 'NNE', 'ROCK', 3, 'NNE', 'ROCK', 35.055, -82.615, 35.055, -82.615, 'A cluster of thunderstorms producing damaging wind gusts moved from northeast Georgia into the South Carolina mountains and foothills during the afternoon.', 'County comms reported a tree blown down on a vehicle.');
INSERT INTO public.stormevents_east VALUES (768934, 201806, 24, 1510, 201806, 24, 1517, 128208, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 15:10:00', 'EST-5', '24-JUN-18 15:17:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'CLAYTON', 2, 'WNW', 'SATOLAH', 34.884, -83.4, 34.994, -83.207, 'For the second day in a row, a cluster of thunderstorms produced areas of wind damage as it moved from west to east across Rabun County.', 'County comms reported multiple trees blown down from the Clayton area north toward the North Carolina border.');
INSERT INTO public.stormevents_east VALUES (768937, 201806, 24, 1525, 201806, 24, 1534, 128209, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 15:25:00', 'EST-5', '24-JUN-18 15:34:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'NNE', 'MOUNTAIN REST', 1, 'SSE', 'JOCASSEE', 34.935, -83.11, 34.954, -82.918, 'Scattered thunderstorms and clusters of storms developed over and moved in from the west over Upstate South Carolina throughout the afternoon. Some of the storms produced areas of wind damage.', 'County comms reported muliple trees blown down across the northern part of Oconee County.');
INSERT INTO public.stormevents_east VALUES (768938, 201806, 24, 1532, 201806, 24, 1532, 128209, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 15:32:00', 'EST-5', '24-JUN-18 15:32:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'MAYO', 1, 'N', 'MAYO', 35.1, -81.87, 35.1, -81.87, 'Scattered thunderstorms and clusters of storms developed over and moved in from the west over Upstate South Carolina throughout the afternoon. Some of the storms produced areas of wind damage.', 'County comms reported several trees blown down in the Mayo area.');
INSERT INTO public.stormevents_east VALUES (768945, 201806, 24, 1549, 201806, 24, 1553, 128209, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 15:49:00', 'EST-5', '24-JUN-18 15:53:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'CROW CREEK', 3, 'N', 'PICKENS', 34.901, -82.771, 34.916, -82.696, 'Scattered thunderstorms and clusters of storms developed over and moved in from the west over Upstate South Carolina throughout the afternoon. Some of the storms produced areas of wind damage.', 'Multiple sources reported multiple trees blown down in Pickens County, mainly across the central part of the county, with trees down on Rushmore Dr and Fox Squirrel Ridge Rd in Pickens. Additional sporadic tree damage was reported elsewhere in the county, including in Six Mile and Easley.');
INSERT INTO public.stormevents_east VALUES (769940, 201806, 18, 1425, 201806, 18, 1425, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 14:25:00', 'EST-5', '18-JUN-18 14:25:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'LIMESTONE', 2, 'WNW', 'LIMESTONE', 41.1423, -79.3593, 41.1423, -79.3593, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County 911 officials reported that trees were blown down on East Reidsburg Road.');
INSERT INTO public.stormevents_east VALUES (769946, 201806, 18, 1508, 201806, 18, 1508, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 15:08:00', 'EST-5', '18-JUN-18 15:08:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'WSW', 'BIG RUN', 1, 'WSW', 'BIG RUN', 40.9672, -78.8808, 40.9672, -78.8808, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County 911 officials reported single trees blown down on both Aloe Park Road and at the intersection of West Main Stree and Watts Street.');
INSERT INTO public.stormevents_east VALUES (769950, 201806, 18, 1955, 201806, 18, 1955, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 19:55:00', 'EST-5', '18-JUN-18 19:55:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SE', 'EAST HICKORY', 1, 'SE', 'EAST HICKORY', 41.57, -79.41, 41.57, -79.41, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County law enforcement reported that trees were blown down on Fleming Hill Road.');
INSERT INTO public.stormevents_east VALUES (769955, 201806, 18, 2009, 201806, 18, 2009, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 20:09:00', 'EST-5', '18-JUN-18 20:09:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'TIONESTA', 1, 'ESE', 'TIONESTA', 41.4947, -79.4589, 41.4947, -79.4589, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County 911 officials reported that trees blown onto power lines along Faulkner Drive.');
INSERT INTO public.stormevents_east VALUES (754560, 201805, 14, 1840, 201805, 14, 1840, 125704, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 18:40:00', 'EST-5', '14-MAY-18 18:40:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'S', 'HILLMEADE', 1, 'S', 'HILLMEADE', 38.956, -76.798, 38.956, -76.798, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Trees were down along Route 193 at Lisborough Road.');
