INSERT INTO public.stormevents_east VALUES (764140, 201806, 2, 1254, 201806, 2, 1500, 127371, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 12:54:00', 'EST-5', '02-JUN-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'MASSANETTA SPGS', 1, 'SSW', 'MASSANETTA SPGS', 38.3819, -78.8422, 38.3824, -78.8404, 'Some carryover flooding from an event on May 31st continued into the early morning hours of June 1st. Moderate to heavy rain on saturated soil caused isolated flooding on the evening of June 1st. Heavier and more persistent rain on the 2nd caused more widespread flooding, with isolated instances of flash flooding.', 'Flood waters flowing across the roadway along Massanetta Springs Road near Lake Shenandoah.');
INSERT INTO public.stormevents_east VALUES (764141, 201806, 2, 1301, 201806, 2, 1500, 127371, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 13:01:00', 'EST-5', '02-JUN-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'SHERANDO', 2, 'ESE', 'SHERANDO', 37.973, -78.9574, 37.9729, -78.9575, 'Some carryover flooding from an event on May 31st continued into the early morning hours of June 1st. Moderate to heavy rain on saturated soil caused isolated flooding on the evening of June 1st. Heavier and more persistent rain on the 2nd caused more widespread flooding, with isolated instances of flash flooding.', 'Up to six inches of water flowing over the road on Mount Torrey Road about a mile south of Howardsville Turnpike.');
