INSERT INTO public.stormevents_east VALUES (760248, 201806, 11, 1616, 201806, 11, 1620, 126819, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '11-JUN-18 16:16:00', 'EST-5', '11-JUN-18 16:20:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 60, 'EG', NULL, NULL, 3, 'ENE', 'PUMPKIN CENTER', 3, 'ENE', 'PUMPKIN CENTER', 33.4967, -82.2781, 33.4967, -82.2781, 'Strong daytime heating, and surface boundaries, produced scattered severe thunderstorms in the afternoon and evening.', 'Trees down on Louisville Rd at Lanatte Lane. Time estimated.');
