INSERT INTO public.stormevents_east VALUES (749662, 201806, 9, 1639, 201806, 9, 1649, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:39:00', 'EST-5', '09-JUN-18 16:49:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'E', 'BOWLUSVILLE', 2, 'E', 'BOWLUSVILLE', 40.02, -83.76, 40.02, -83.76, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'Several trees were knocked down in the 7000 block of Middle Urbana Road.');
INSERT INTO public.stormevents_east VALUES (749664, 201806, 9, 1640, 201806, 9, 1650, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:40:00', 'EST-5', '09-JUN-18 16:50:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'NW', 'MOOREFIELD', 2, 'NW', 'MOOREFIELD', 40, -83.74, 40, -83.74, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'Large sections of shingles were removed from a residence along Anson Place. Also several trees were knocked down throughout the neighborhood.');
INSERT INTO public.stormevents_east VALUES (749667, 201806, 9, 1728, 201806, 9, 1738, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 17:28:00', 'EST-5', '09-JUN-18 17:38:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 3, 'S', 'JEROME', 3, 'S', 'JEROME', 40.13, -83.18, 40.13, -83.18, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A tree limb was knocked down along Mitchell Dewitt Road near the county line.');
INSERT INTO public.stormevents_east VALUES (749668, 201806, 9, 1732, 201806, 9, 1742, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 17:32:00', 'EST-5', '09-JUN-18 17:42:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'OGDEN', 1, 'S', 'OGDEN', 39.41, -83.92, 39.41, -83.92, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A tree was knocked down along Pyle Road.');
INSERT INTO public.stormevents_east VALUES (749669, 201806, 9, 1732, 201806, 9, 1742, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 17:32:00', 'EST-5', '09-JUN-18 17:42:00', 0, 0, 0, 0, '1.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'S', 'WILMINGTON', 1, 'S', 'WILMINGTON', 39.44, -83.83, 39.44, -83.83, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A large branch was knocked down and was blocking southbound U.S. Highway 68.');
INSERT INTO public.stormevents_east VALUES (750264, 201806, 13, 2048, 201806, 13, 2248, 125084, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'ILN', '13-JUN-18 20:48:00', 'EST-5', '13-JUN-18 22:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WHEELERS MILL', 0, 'S', 'WHEELERS MILL', 38.81, -82.85, 38.8138, -82.8501, 'Showers and thunderstorms developed ahead of a cold front that was dropping southeast through the region.', 'Water rushed over Route 335, flooding the road and leaving debris.');
INSERT INTO public.stormevents_east VALUES (750265, 201806, 13, 2022, 201806, 13, 2032, 125084, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '13-JUN-18 20:22:00', 'EST-5', '13-JUN-18 20:32:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'PORTSMOUTH REGL ARPT', 1, 'E', 'PORTSMOUTH REGL ARPT', 38.83, -82.84, 38.83, -82.84, 'Showers and thunderstorms developed ahead of a cold front that was dropping southeast through the region.', 'Multiple trees were knocked down in Wheelersburg and Minford.');
INSERT INTO public.stormevents_east VALUES (782422, 201808, 9, 1730, 201808, 9, 2030, 129822, 'GEORGIA', 13, 2018, 'August', 'Flash Flood', 'FFC', '09-AUG-18 17:30:00', 'EST-5', '09-AUG-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BONAIRE', 2, 'WNW', 'BONAIRE', 32.5555, -83.5988, 32.5574, -83.629, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'Flash flooding occurred in areas near Bonaire and Kathleen, with several roads closed as a result, including the intersection of County Road and 3rd Street, Bear Branch Road, and County Road. Poor drainage also contributed to flooding in a residential neighborhood, with 18 of standing water on the street. Radar estimates indicate that widespread 1.5 to 3 inches of rainfall occurred in a very short period of time.');
INSERT INTO public.stormevents_east VALUES (768737, 201806, 24, 1525, 201806, 24, 1525, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 15:25:00', 'EST-5', '24-JUN-18 15:25:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'CROSSWAY', 1, 'E', 'CROSSWAY', 34.75, -79.48, 34.75, -79.48, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'Numerous trees and power lines were reported down across the city of Laurinburg, especially south of Highway 74.');
INSERT INTO public.stormevents_east VALUES (768738, 201806, 24, 1530, 201806, 24, 1530, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 15:30:00', 'EST-5', '24-JUN-18 15:30:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NW', 'SLOCOMB', 2, 'NW', 'SLOCOMB', 35.2087, -78.8566, 35.2087, -78.8566, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'Eight trees were blown down at the intersection of Elliot Farm Road and Elliot Bridge Road.');
INSERT INTO public.stormevents_east VALUES (768739, 201806, 24, 1554, 201806, 24, 1554, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 15:54:00', 'EST-5', '24-JUN-18 15:54:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ESE', 'SUTTONTOWN', 2, 'ESE', 'SUTTONTOWN', 35.19, -78.21, 35.19, -78.21, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'Trees and power lines were reported down.');
INSERT INTO public.stormevents_east VALUES (768740, 201806, 24, 1600, 201806, 24, 1600, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 16:00:00', 'EST-5', '24-JUN-18 16:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'S', 'MT OLIVE', 1, 'S', 'MT OLIVE', 35.19, -78.07, 35.19, -78.07, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'Multiple trees were reported down in southern Wayne County, near the Duplin County Line.');
INSERT INTO public.stormevents_east VALUES (768742, 201806, 24, 1725, 201806, 24, 1725, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 17:25:00', 'EST-5', '24-JUN-18 17:25:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'CLINTON', 0, 'N', 'CLINTON', 35, -78.33, 35, -78.33, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'Numerous trees and power lines were reported down in the Clinton area.');
INSERT INTO public.stormevents_east VALUES (768743, 201806, 24, 1725, 201806, 24, 1725, 128135, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '24-JUN-18 17:25:00', 'EST-5', '24-JUN-18 17:25:00', 0, 0, 0, 0, '15.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SALEMBURG', 1, 'E', 'SALEMBURG', 35.02, -78.5, 35.02, -78.5, 'A boundary observed on radar late that morning was the focus for initial convective development around early afternoon across Harnett and western Johnston Counties. A mid level inversion capped the atmosphere initially across the western and northern Piedmont but this cap was broken around sunset, permitting isolated severe thunderstorms to develop between the Triad and the Triangle regions.', 'Numerous trees and power lines were reported down in the Salemburg area.');
INSERT INTO public.stormevents_east VALUES (775504, 201807, 21, 1746, 201807, 21, 1930, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 17:46:00', 'EST-5', '21-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'WSW', 'TREMONT', 38.8467, -77.2375, 38.8464, -77.2369, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Woodburn Road closed at Accotink Creek due to flowing water over the road.');
INSERT INTO public.stormevents_east VALUES (775505, 201807, 21, 1759, 201807, 21, 2000, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 17:59:00', 'EST-5', '21-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'POHICK', 0, 'WNW', 'POHICK', 38.7024, -77.2085, 38.7022, -77.2083, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Armistead Road flooded and closed near US 1.');
INSERT INTO public.stormevents_east VALUES (775506, 201807, 21, 1804, 201807, 21, 2000, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 18:04:00', 'EST-5', '21-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'SOWEGO', 2, 'WNW', 'SOWEGO', 38.6055, -77.6029, 38.6051, -77.6027, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Sowego Road flooded and closed at Town Run near Elk Run Road.');
INSERT INTO public.stormevents_east VALUES (775717, 201807, 21, 1812, 201807, 21, 2000, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 18:12:00', 'EST-5', '21-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ADEN', 1, 'NNW', 'ADEN', 38.6681, -77.5392, 38.6683, -77.5375, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Fleetwood Drive reported flooded and closed.');
INSERT INTO public.stormevents_east VALUES (775718, 201807, 21, 1815, 201807, 21, 1915, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 18:15:00', 'EST-5', '21-JUL-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'HOOES', 1, 'E', 'HOOES', 38.3522, -77.0481, 38.3521, -77.0479, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Two to three feet of standing water covered the main entrance to the Dahlgren Naval Base.');
INSERT INTO public.stormevents_east VALUES (775719, 201807, 21, 1817, 201807, 21, 1930, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 18:17:00', 'EST-5', '21-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'RUBY', 3, 'WSW', 'RUBY', 38.4895, -77.5782, 38.4893, -77.5779, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Heflin Road flooded and closed near Poplar Road.');
