INSERT INTO public.stormevents_east VALUES (756924, 201806, 20, 1647, 201806, 20, 1647, 126031, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'LWX', '20-JUN-18 16:47:00', 'EST-5', '20-JUN-18 16:47:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'BERKELEY', 1, 'W', 'BERKELEY', 39.4973, -77.9516, 39.4973, -77.9516, 'A cold front passed through the area. Hot and humid conditions ahead of the front led to some severe storms.', 'Two trees were down along the Mid-Atlantic Parkway and two trees were down on Eagle School Road.');
INSERT INTO public.stormevents_east VALUES (756925, 201806, 20, 1713, 201806, 20, 1713, 126031, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'LWX', '20-JUN-18 17:13:00', 'EST-5', '20-JUN-18 17:13:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'VANCLEVESVILLE', 1, 'W', 'VANCLEVESVILLE', 39.4314, -77.9187, 39.4314, -77.9187, 'A cold front passed through the area. Hot and humid conditions ahead of the front led to some severe storms.', 'Eight large trees were down near Bakerton.');
INSERT INTO public.stormevents_east VALUES (756927, 201806, 23, 1609, 201806, 23, 1609, 126032, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '23-JUN-18 16:09:00', 'EST-5', '23-JUN-18 16:09:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NW', 'JEFFERSONTON', 2, 'NW', 'JEFFERSONTON', 38.6476, -77.9291, 38.6476, -77.9291, 'A trough triggered some showers and thunderstorms, and there was enough instability for a few storms to become severe.', 'A tree was down at the intersection of Rixeyville Road and Colvin Road.');
INSERT INTO public.stormevents_east VALUES (756929, 201806, 23, 1702, 201806, 23, 1702, 126032, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '23-JUN-18 17:02:00', 'EST-5', '23-JUN-18 17:02:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'CANOVA', 1, 'SSW', 'CANOVA', 38.6618, -77.4399, 38.6618, -77.4399, 'A trough triggered some showers and thunderstorms, and there was enough instability for a few storms to become severe.', 'A tree was down at Dumfries Road and Counselor Road.');
INSERT INTO public.stormevents_east VALUES (756930, 201806, 23, 1722, 201806, 23, 1722, 126032, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '23-JUN-18 17:22:00', 'EST-5', '23-JUN-18 17:22:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'DALE CITY', 1, 'WSW', 'DALE CITY', 38.6116, -77.3162, 38.6116, -77.3162, 'A trough triggered some showers and thunderstorms, and there was enough instability for a few storms to become severe.', 'A tree was down along the 15000 block of Beau Ridge Drive.');
INSERT INTO public.stormevents_east VALUES (756931, 201806, 23, 1845, 201806, 23, 1845, 126034, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '23-JUN-18 18:45:00', 'EST-5', '23-JUN-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'N', 'MECHANICSVILLE', 0, 'N', 'MECHANICSVILLE', 38.43, -76.73, 38.43, -76.73, 'A trough triggered some showers and thunderstorms, and there was enough instability for an isolated storm to become severe.', 'Several trees were down along Baptist Church Road.');
INSERT INTO public.stormevents_east VALUES (756933, 201806, 24, 1256, 201806, 24, 1256, 126036, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '24-JUN-18 12:56:00', 'EST-5', '24-JUN-18 12:56:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNW', 'WEST VIEW', 2, 'NNW', 'WEST VIEW', 38.1907, -79.1797, 38.1907, -79.1797, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'A tree was down along the 4500 block of Morris Mill road.');
INSERT INTO public.stormevents_east VALUES (764865, 201806, 4, 700, 201806, 4, 900, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '04-JUN-18 07:00:00', 'EST-5', '04-JUN-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'BRENTSVILLE', 1, 'WSW', 'BRENTSVILLE', 38.6767, -77.5103, 38.6777, -77.5102, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Car stalled in two feet of water on Old Church Road.');
INSERT INTO public.stormevents_east VALUES (764868, 201806, 9, 2021, 201806, 9, 2200, 127375, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '09-JUN-18 20:21:00', 'EST-5', '09-JUN-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'THORNBURG', 1, 'SSW', 'THORNBURG', 38.1169, -77.5254, 38.1168, -77.5245, 'Isolated heavy rain around two inches fell during the evening of June 9th, causing a few instances of flooding.', 'US 1 flooded and closed south of Mudd Tavern Road.');
INSERT INTO public.stormevents_east VALUES (764869, 201806, 9, 2101, 201806, 9, 2300, 127375, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '09-JUN-18 21:01:00', 'EST-5', '09-JUN-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'FOUR MILE FORK', 1, 'WNW', 'FOUR MILE FORK', 38.2558, -77.4979, 38.2549, -77.4982, 'Isolated heavy rain around two inches fell during the evening of June 9th, causing a few instances of flooding.', 'US 1 flooded and closed at Route 208.');
INSERT INTO public.stormevents_east VALUES (764870, 201806, 9, 2015, 201806, 9, 2115, 127375, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '09-JUN-18 20:15:00', 'EST-5', '09-JUN-18 21:15:00', 0, 0, 0, 0, '200.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'GAINESVILLE', 1, 'SE', 'GAINESVILLE', 38.7887, -77.5865, 38.7875, -77.5871, 'Isolated heavy rain around two inches fell during the evening of June 9th, causing a few instances of flooding.', 'The combination of a clogged drain and heavy rainfall caused a retention pond to overflow at the Jiffy Lube Live concert venue during a concert.  Overland flow flooded a portion of Wellington Road near the venue, and rising standing water flooded several dozen vehicles parked on the grounds.');
INSERT INTO public.stormevents_east VALUES (764871, 201806, 11, 1400, 201806, 11, 1600, 127376, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '11-JUN-18 14:00:00', 'EST-5', '11-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'PINEVILLE', 1, 'SW', 'PINEVILLE', 38.3411, -78.8133, 38.3409, -78.813, 'Yet another area of 1 to 2 inches of rain occurred in Rockingham County, which remained waterlogged from numerous previous heavy rain events. Several incidents of flooding were reported.', 'Goods Mill Road flooded and closed near Charlie Town Road.');
INSERT INTO public.stormevents_east VALUES (764872, 201806, 11, 1400, 201806, 11, 1600, 127376, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '11-JUN-18 14:00:00', 'EST-5', '11-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'DAYTON', 1, 'SW', 'DAYTON', 38.4133, -78.9363, 38.413, -78.9364, 'Yet another area of 1 to 2 inches of rain occurred in Rockingham County, which remained waterlogged from numerous previous heavy rain events. Several incidents of flooding were reported.', 'Flooding on West Mosby Road in the 2900 block near Cooks Creek.');
INSERT INTO public.stormevents_east VALUES (764873, 201806, 11, 1400, 201806, 11, 1600, 127376, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '11-JUN-18 14:00:00', 'EST-5', '11-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'MONTEZUMA', 1, 'WSW', 'MONTEZUMA', 38.412, -79.0046, 38.412, -79.0041, 'Yet another area of 1 to 2 inches of rain occurred in Rockingham County, which remained waterlogged from numerous previous heavy rain events. Several incidents of flooding were reported.', 'Silver Creek Road flooded near Beaver Creek Road.');
INSERT INTO public.stormevents_east VALUES (764874, 201806, 11, 1531, 201806, 11, 1700, 127376, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '11-JUN-18 15:31:00', 'EST-5', '11-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'GENOA', 1, 'NNW', 'GENOA', 38.6548, -78.9709, 38.6658, -78.9261, 'Yet another area of 1 to 2 inches of rain occurred in Rockingham County, which remained waterlogged from numerous previous heavy rain events. Several incidents of flooding were reported.', 'Genoa Road and Little Dry River Road were both flooded and closed near Fulks Run.');
INSERT INTO public.stormevents_east VALUES (754529, 201805, 14, 1615, 201805, 14, 1615, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:15:00', 'EST-5', '14-MAY-18 16:15:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 1, NULL, NULL, NULL, 0, 'NNW', 'INWOOD', 0, 'NNW', 'INWOOD', 39.3526, -78.0512, 39.3526, -78.0512, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (754530, 201805, 14, 1605, 201805, 14, 1605, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:05:00', 'EST-5', '14-MAY-18 16:05:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1.5, NULL, NULL, NULL, 1, 'NE', 'MARTINSBURG', 1, 'NE', 'MARTINSBURG', 39.4643, -77.9513, 39.4643, -77.9513, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Ping pong ball sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (754531, 201805, 14, 1615, 201805, 14, 1615, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:15:00', 'EST-5', '14-MAY-18 16:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1.75, NULL, NULL, NULL, 2, 'NE', 'MT PLEASANT', 2, 'NE', 'MT PLEASANT', 39.2693, -77.9132, 39.2693, -77.9132, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Golf ball sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (754533, 201805, 14, 1625, 201805, 14, 1625, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:25:00', 'EST-5', '14-MAY-18 16:25:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.5, NULL, NULL, NULL, 0, 'N', 'MIDDLEWAY', 0, 'N', 'MIDDLEWAY', 39.3, -77.98, 39.3, -77.98, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Ping pong ball sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (754534, 201805, 14, 1630, 201805, 14, 1630, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:30:00', 'EST-5', '14-MAY-18 16:30:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 2, 'WNW', 'CHARLES TOWN ARPT', 2, 'WNW', 'CHARLES TOWN ARPT', 39.3274, -77.8621, 39.3274, -77.8621, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (768948, 201806, 24, 1612, 201806, 24, 1612, 128209, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 16:12:00', 'EST-5', '24-JUN-18 16:12:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'FINGERVILLE', 1, 'W', 'FINGERVILLE', 35.13, -82.01, 35.13, -82.01, 'Scattered thunderstorms and clusters of storms developed over and moved in from the west over Upstate South Carolina throughout the afternoon. Some of the storms produced areas of wind damage.', 'County comms reported multiple trees and power lines blown down in the Fingerville area.');
INSERT INTO public.stormevents_east VALUES (768952, 201806, 24, 1620, 201806, 24, 1620, 128209, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 16:20:00', 'EST-5', '24-JUN-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'WOODSIDE', 2, 'E', 'WOODSIDE', 34.87, -82.372, 34.87, -82.372, 'Scattered thunderstorms and clusters of storms developed over and moved in from the west over Upstate South Carolina throughout the afternoon. Some of the storms produced areas of wind damage.', 'County comms reported multiple trees and power lines blown down along Wade Hampton Bvd.');
INSERT INTO public.stormevents_east VALUES (768953, 201806, 24, 1812, 201806, 24, 1812, 128209, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 18:12:00', 'EST-5', '24-JUN-18 18:12:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'BALDWIN MILLS', 2, 'SW', 'BALDWIN MILLS', 34.684, -81.256, 34.684, -81.256, 'Scattered thunderstorms and clusters of storms developed over and moved in from the west over Upstate South Carolina throughout the afternoon. Some of the storms produced areas of wind damage.', 'County comms reported a tree and power lines blown down on Meadowbrook Road.');
INSERT INTO public.stormevents_east VALUES (768958, 201806, 24, 1614, 201806, 24, 1619, 128208, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'GSP', '24-JUN-18 16:14:00', 'EST-5', '24-JUN-18 16:19:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ENE', 'CARNESVILLE', 1, 'NNW', 'LAVONIA MUNI ARPT', 34.394, -83.184, 34.428, -83.122, 'For the second day in a row, a cluster of thunderstorms produced areas of wind damage as it moved from west to east across Rabun County.', 'County comms reported multiple trees blown down between Carnesville and Lavonia.');
INSERT INTO public.stormevents_east VALUES (768965, 201806, 25, 1330, 201806, 25, 1330, 128213, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '25-JUN-18 13:30:00', 'EST-5', '25-JUN-18 13:30:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1.25, NULL, NULL, NULL, 1, 'SSW', 'MASCOT', 1, 'SSW', 'MASCOT', 35.05, -82.139, 35.05, -82.139, 'Scattered thunderstorms developed over the Upstate during the afternoon. Some of these storms produced severe weather in the form of damaging winds and large hail. Meanwhile, clusters of storms moved out of the North Carolina mountains and across the Upstate during the late afternoon and evening, producing areas of wind damage.', 'Public reported (via Social Media) half dollar size hail at new Cut Road and Gowan Road.');
INSERT INTO public.stormevents_east VALUES (768966, 201806, 25, 1342, 201806, 25, 1342, 128213, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '25-JUN-18 13:42:00', 'EST-5', '25-JUN-18 13:42:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 1, NULL, NULL, NULL, 1, 'E', 'INMAN MILLS', 1, 'E', 'INMAN MILLS', 35.05, -82.09, 35.05, -82.09, 'Scattered thunderstorms developed over the Upstate during the afternoon. Some of these storms produced severe weather in the form of damaging winds and large hail. Meanwhile, clusters of storms moved out of the North Carolina mountains and across the Upstate during the late afternoon and evening, producing areas of wind damage.', 'Ham radio operator reported quarter size hail in the Inman area.');
INSERT INTO public.stormevents_east VALUES (768968, 201806, 25, 1710, 201806, 25, 1716, 128213, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '25-JUN-18 17:10:00', 'EST-5', '25-JUN-18 17:16:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 1, NULL, NULL, NULL, 2, 'N', 'FAIRVIEW', 1, 'NNE', 'GREER', 34.985, -82.246, 34.942, -82.226, 'Scattered thunderstorms developed over the Upstate during the afternoon. Some of these storms produced severe weather in the form of damaging winds and large hail. Meanwhile, clusters of storms moved out of the North Carolina mountains and across the Upstate during the late afternoon and evening, producing areas of wind damage.', 'Multiple public reports of quarter size hail were received from the Greer area.');
INSERT INTO public.stormevents_east VALUES (765549, 201806, 1, 1804, 201806, 1, 1828, 127663, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 18:04:00', 'EST-5', '01-JUN-18 18:28:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 6, 'SE', 'SEDALIA', 1, 'S', 'PRIDE', 34.545, -81.65, 34.602, -81.427, 'Scattered to numerous thunderstorms and storm clusters moved into the Upstate from north Georgia during the late afternoon and evening. Multiple storm clusters produced severe weather in the form of damaging wind gusts.', 'County comms reported numerous trees blown down across the southern part of Union County.');
INSERT INTO public.stormevents_east VALUES (769959, 201806, 18, 2045, 201806, 18, 2045, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 20:45:00', 'EST-5', '18-JUN-18 20:45:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'NORTH PINE GROVE', 1, 'SE', 'NORTH PINE GROVE', 41.3874, -79.2102, 41.3874, -79.2102, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County 911 officials reported a large tree and power lines were blown down on Greenwood Road.');
INSERT INTO public.stormevents_east VALUES (769979, 201806, 18, 2135, 201806, 18, 2135, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 21:35:00', 'EST-5', '18-JUN-18 21:35:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 0, 'SSE', 'REYNOLDSVILLE', 0, 'SSE', 'REYNOLDSVILLE', 41.0959, -78.8984, 41.0959, -78.8984, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'The Reynoldsville Fire Department reported trees blown down in the Reynoldsville Area, including one on Point View Road.');
INSERT INTO public.stormevents_east VALUES (769962, 201806, 18, 2117, 201806, 18, 2117, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 21:17:00', 'EST-5', '18-JUN-18 21:17:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'SIGEL', 0, 'N', 'SIGEL', 41.28, -79.12, 41.28, -79.12, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County law enforcement reported that trees were blown down on the northwest side of Sigel.');
INSERT INTO public.stormevents_east VALUES (765547, 201806, 1, 1725, 201806, 1, 1804, 127663, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 17:25:00', 'EST-5', '01-JUN-18 18:04:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 3, 'SSW', 'WATERLOO', 1, 'ENE', 'PHILTON XRDS', 34.301, -82.083, 34.561, -81.778, 'Scattered to numerous thunderstorms and storm clusters moved into the Upstate from north Georgia during the late afternoon and evening. Multiple storm clusters produced severe weather in the form of damaging wind gusts.', 'County comms reported many trees and power lines blown down in association with a second storm cluster across the southern part of Laurens County.');
INSERT INTO public.stormevents_east VALUES (769980, 201806, 18, 2136, 201806, 18, 2136, 128346, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '18-JUN-18 21:36:00', 'EST-5', '18-JUN-18 21:36:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'PARKER CITY', 1, 'NE', 'PARKER CITY', 41.1103, -79.6808, 41.1103, -79.6808, 'Heat and humidity was in place across western Pennsylvania underneath a strong ridge, which allowed instability to build during the afternoon of June 18th.  Thunderstorms initially formed on a lake breeze boundary off of Lake Erie and dropped southeastward across areas north of Pittsburgh, resulting in a few wind damage events in Clarion and Jefferson Counties.  A second round of storms formed along a cold front and dropped in a similar fashion across western Pennsylvania, again resulting in some wind damage reports northeast of Pittsburgh.  The storms diurnally weakened thereafter, with the severe weather threat over by midnight.', 'County 911 officials reported that trees were blown down on North Riverview Drive.');
INSERT INTO public.stormevents_east VALUES (754566, 201805, 15, 1700, 201805, 15, 1700, 125830, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '15-MAY-18 17:00:00', 'EST-5', '15-MAY-18 17:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'HIGHTOWN', 1, 'N', 'HIGHTOWN', 38.5376, -78.8011, 38.5376, -78.8011, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'A tree was down.');
INSERT INTO public.stormevents_east VALUES (754567, 201805, 15, 1710, 201805, 15, 1710, 125830, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '15-MAY-18 17:10:00', 'EST-5', '15-MAY-18 17:10:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SSW', 'TENTH LEGION', 0, 'SSW', 'TENTH LEGION', 38.5774, -78.7318, 38.5774, -78.7318, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'A tree was down over 10th Legion and State Route.');
