INSERT INTO public.stormevents_east VALUES (753894, 201805, 14, 1555, 201805, 14, 1555, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 15:55:00', 'EST-5', '14-MAY-18 15:55:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'ESE', 'LURAY', 1, 'ESE', 'LURAY', 38.6647, -78.4553, 38.6647, -78.4553, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Several trees were down in Luray and siding was stripped from a home.');
INSERT INTO public.stormevents_east VALUES (753897, 201805, 14, 1605, 201805, 14, 1605, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:05:00', 'EST-5', '14-MAY-18 16:05:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'ENE', 'GORE', 0, 'ENE', 'GORE', 39.2707, -78.3464, 39.2707, -78.3464, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down near the intersection of Carpers Pike and Northwestern Pike.');
