INSERT INTO public.stormevents_east VALUES (791784, 201812, 14, 1830, 201812, 14, 1830, 132328, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '14-DEC-18 18:30:00', 'EST-5', '14-DEC-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'E', 'DANKS CORNER', 2, 'E', 'DANKS CORNER', 29.02, -82.08, 29.02, -82.08, 'Flood watch was in effect due to above normal moisture in place across the region ahead of a very strong, long wave trough storm system over the MS River Valley. The associated warm front was draped along the FL-GA stateline, which provide a focus for widespread heavy rainfall.', 'An observer measured 1.71 inches in Belleview.');
INSERT INTO public.stormevents_east VALUES (791781, 201812, 14, 2155, 201812, 14, 2155, 132328, 'FLORIDA', 12, 2018, 'December', 'Flood', 'JAX', '14-DEC-18 21:55:00', 'EST-5', '14-DEC-18 21:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'OCALA', 0, 'S', 'OCALA', 29.19, -82.13, 29.1731, -82.1315, 'Flood watch was in effect due to above normal moisture in place across the region ahead of a very strong, long wave trough storm system over the MS River Valley. The associated warm front was draped along the FL-GA stateline, which provide a focus for widespread heavy rainfall.', 'Widespread reports of flooding across roads in Ocala.');
INSERT INTO public.stormevents_east VALUES (791785, 201812, 14, 1900, 201812, 14, 1900, 132328, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '14-DEC-18 19:00:00', 'EST-5', '14-DEC-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'W', 'WHITE SPGS', 1, 'W', 'WHITE SPGS', 30.33, -82.76, 30.33, -82.76, 'Flood watch was in effect due to above normal moisture in place across the region ahead of a very strong, long wave trough storm system over the MS River Valley. The associated warm front was draped along the FL-GA stateline, which provide a focus for widespread heavy rainfall.', 'Daily rainfall of 3.07 inches was measured near White Springs.');
INSERT INTO public.stormevents_east VALUES (768871, 201806, 17, 1641, 201806, 17, 1641, 128196, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '17-JUN-18 16:41:00', 'EST-5', '17-JUN-18 16:41:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SPIVEYS CORNER', 1, 'E', 'SPIVEYS CORNER', 35.25, -78.51, 35.25, -78.51, 'Scattered convection developed in a moderately unstable air mass with a weak surface trough in place over central North Carolina.', 'A few trees were blown down along O B J Road near Timothy Road.');
INSERT INTO public.stormevents_east VALUES (762789, 201806, 24, 1812, 201806, 24, 1815, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 18:12:00', 'EST-5', '24-JUN-18 18:15:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'SE', 'SPEARMAN', 3, 'SE', 'SPEARMAN', 34.2194, -81.6437, 34.2194, -81.6437, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Tree in roadway at Dennis Dairy Rd and Whitman Rd.');
INSERT INTO public.stormevents_east VALUES (765464, 201806, 13, 1815, 201806, 13, 1815, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 18:15:00', 'EST-5', '13-JUN-18 18:15:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'HARRISVILLE', 1, 'NW', 'HARRISVILLE', 44.16, -75.33, 44.16, -75.33, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Roof blown off building on Hands Flat Road.');
INSERT INTO public.stormevents_east VALUES (765465, 201806, 13, 1846, 201806, 13, 1846, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 18:46:00', 'EST-5', '13-JUN-18 18:46:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'BEAVER FALLS', 0, 'N', 'BEAVER FALLS', 43.88, -75.43, 43.88, -75.43, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Trees and wires reported down.');
INSERT INTO public.stormevents_east VALUES (762790, 201806, 24, 1820, 201806, 24, 1825, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 18:20:00', 'EST-5', '24-JUN-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'WINNSBORO', 1, 'E', 'WINNSBORO', 34.38, -81.09, 34.38, -81.09, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Public report and photo, via social media, of huge limb downed in Winnsboro.');
INSERT INTO public.stormevents_east VALUES (765466, 201806, 13, 1918, 201806, 13, 1918, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 19:18:00', 'EST-5', '13-JUN-18 19:18:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'LYONSDALE', 1, 'W', 'LYONSDALE', 43.62, -75.31, 43.62, -75.31, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Multiple reports of trees down along River Road.');
INSERT INTO public.stormevents_east VALUES (762787, 201806, 24, 2130, 201806, 24, 2130, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Lightning', 'CAE', '24-JUN-18 21:30:00', 'EST-5', '24-JUN-18 21:30:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'SW', 'NORTH AUGUSTA', 1, 'SW', 'NORTH AUGUSTA', 33.49, -81.98, 33.49, -81.98, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Media report, via social media, of lightning striking a house and igniting a fire in Hammond''s Ferry. Time estimated.');
INSERT INTO public.stormevents_east VALUES (762788, 201806, 24, 2102, 201806, 24, 2105, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:02:00', 'EST-5', '24-JUN-18 21:05:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'ESE', 'VAUCLUSE', 3, 'ESE', 'VAUCLUSE', 33.6003, -81.7822, 33.6003, -81.7822, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down at Vaucluse Rd and Hancock Rd.');
