INSERT INTO public.stormevents_east VALUES (762792, 201806, 24, 1925, 201806, 24, 1930, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:25:00', 'EST-5', '24-JUN-18 19:30:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 1, 'SW', 'CAPITOL VIEW', 1, 'SW', 'CAPITOL VIEW', 33.9665, -80.948, 33.9665, -80.948, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down blocking the roadway on Greenlawn Dr near the Wellington Farms Apt complex.');
INSERT INTO public.stormevents_east VALUES (762793, 201806, 24, 1928, 201806, 24, 1930, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:28:00', 'EST-5', '24-JUN-18 19:30:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 0, 'N', 'SIMS', 0, 'N', 'SIMS', 33.95, -80.97, 33.95, -80.97, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Tree down blocking the right lane of I-77 at Exit 6.');
INSERT INTO public.stormevents_east VALUES (762794, 201806, 24, 1930, 201806, 24, 1935, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:30:00', 'EST-5', '24-JUN-18 19:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 60, 'EG', NULL, NULL, 1, 'W', 'CAMDEN', 1, 'W', 'CAMDEN', 34.25, -80.61, 34.25, -80.61, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Numerous trees down, and power outages, in and around Camden. Time estimated.');
INSERT INTO public.stormevents_east VALUES (768821, 201806, 20, 1627, 201806, 20, 1627, 128186, 'NORTH CAROLINA', 37, 2018, 'June', 'Lightning', 'RAH', '20-JUN-18 16:27:00', 'EST-5', '20-JUN-18 16:27:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'S', 'DRUG STORE', 1, 'S', 'DRUG STORE', 35.59, -78.58, 35.59, -78.58, 'Isolated pulse severe storms developed near the Piedmont trough at mid-afternoon. These storms formed into clusters as they moved east-southeast. The strongest and isolated severe storms affected Moore, Lee, Harnett, Johnston, Wilson, Franklin, Nash, and Edgecombe Counties. There were frequent CG strikes that affected Harnett, Johnston, and eastern Wake Counties as well, with some house fires reported.', 'Lightning struck a home on off of Old Drug Store Road, resulting in a house fire.');
INSERT INTO public.stormevents_east VALUES (768823, 201806, 20, 1714, 201806, 20, 1714, 128186, 'NORTH CAROLINA', 37, 2018, 'June', 'Lightning', 'RAH', '20-JUN-18 17:14:00', 'EST-5', '20-JUN-18 17:14:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 2, 'WSW', 'SAMARIA', 2, 'WSW', 'SAMARIA', 35.8418, -78.2211, 35.8418, -78.2211, 'Isolated pulse severe storms developed near the Piedmont trough at mid-afternoon. These storms formed into clusters as they moved east-southeast. The strongest and isolated severe storms affected Moore, Lee, Harnett, Johnston, Wilson, Franklin, Nash, and Edgecombe Counties. There were frequent CG strikes that affected Harnett, Johnston, and eastern Wake Counties as well, with some house fires reported.', 'Lightning struck a home off of North Carolina Highway 97 in Zebulon. The house caught on fire, resulting in significant structural damage.');
INSERT INTO public.stormevents_east VALUES (768870, 201806, 17, 1545, 201806, 17, 1545, 128196, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '17-JUN-18 15:45:00', 'EST-5', '17-JUN-18 15:45:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNW', 'FOUR OAKS', 3, 'NNW', 'FOUR OAKS', 35.49, -78.46, 35.49, -78.46, 'Scattered convection developed in a moderately unstable air mass with a weak surface trough in place over central North Carolina.', 'Thunderstorm winds resulted in part of the roof of a residence being peeled back at the 700 block of Sedgewood Road.');
INSERT INTO public.stormevents_east VALUES (768873, 201806, 10, 2246, 201806, 10, 2246, 128197, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '10-JUN-18 22:46:00', 'EST-5', '10-JUN-18 22:46:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'W', 'WEST DURHAM', 4, 'W', 'WEST DURHAM', 35.99, -78.99, 35.99, -78.99, 'Convection blossomed strongly near the intersection of a southward moving outflow boundary and a similar eastward moving boundary. The convection moved east along the boundary, with one cluster of storms becoming severe, producing a swath of wind damage from Orange county to Wake county.', 'Power lines were blown down approximately 4 miles west-northwest of Durham.');
INSERT INTO public.stormevents_east VALUES (768874, 201806, 10, 2305, 201806, 10, 2305, 128197, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '10-JUN-18 23:05:00', 'EST-5', '10-JUN-18 23:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'W', 'GENLEE', 1, 'W', 'GENLEE', 35.88, -78.9, 35.88, -78.9, 'Convection blossomed strongly near the intersection of a southward moving outflow boundary and a similar eastward moving boundary. The convection moved east along the boundary, with one cluster of storms becoming severe, producing a swath of wind damage from Orange county to Wake county.', 'One tree was snapped by thunderstorm winds in a homeowner''s yard along Monarch Way.');
INSERT INTO public.stormevents_east VALUES (786609, 201809, 3, 1714, 201809, 3, 1825, 131470, 'PENNSYLVANIA', 42, 2018, 'September', 'Flash Flood', 'BGM', '03-SEP-18 17:14:00', 'EST-5', '03-SEP-18 18:25:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'NEW ALBANY', 1, 'SE', 'NEW ALBANY', 41.6145, -76.43, 41.5949, -76.4231, 'Weak upper level disturbances on the southern edge of the jet stream created areas of slow moving, heavy rain producing thunderstorms during the late afternoon and evening hours.', 'Water and debris was reported flowing over Route 220.');
INSERT INTO public.stormevents_east VALUES (758105, 201806, 1, 2354, 201806, 2, 0, 126475, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '01-JUN-18 23:54:00', 'EST-5', '02-JUN-18 00:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'LEWISETTA MD (LWTV2)', 0, 'N', 'LEWISETTA MD (LWTV2)', 38, -76.47, 38, -76.47, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'Wind gusts of 35 to 36 knots were reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (758106, 201806, 1, 2354, 201806, 2, 0, 126475, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '01-JUN-18 23:54:00', 'EST-5', '02-JUN-18 00:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'LEWISETTA (LWS)', 0, 'N', 'LEWISETTA (LWS)', 38, -76.47, 38, -76.47, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'Wind gusts of 35 to 36 knots were reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (758107, 201806, 2, 4, 201806, 2, 19, 126475, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '02-JUN-18 00:04:00', 'EST-5', '02-JUN-18 00:19:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'POINT LOOKOUT (PTL)', 0, 'N', 'POINT LOOKOUT (PTL)', 38.04, -76.32, 38.04, -76.32, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'A wind gust of 37 knots was reported at Point Lookout.');
INSERT INTO public.stormevents_east VALUES (758121, 201806, 10, 1804, 201806, 10, 1804, 126477, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '10-JUN-18 18:04:00', 'EST-5', '10-JUN-18 18:04:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms produce gusty winds.', 'A wind gust in excess of 30 knots was reported at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (758122, 201806, 10, 1830, 201806, 10, 1836, 126477, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '10-JUN-18 18:30:00', 'EST-5', '10-JUN-18 18:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 40, 'MG', NULL, NULL, 0, 'N', 'SOLOMONS ISLAND (SLIM2)', 0, 'N', 'SOLOMONS ISLAND (SLIM2)', 38.32, -76.45, 38.32, -76.45, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms produce gusty winds.', 'Wind gusts of 35 to 40 knots were reported at Solomons Island.');
INSERT INTO public.stormevents_east VALUES (766877, 201806, 3, 1942, 201806, 4, 2205, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 19:42:00', 'EST-5', '04-JUN-18 22:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'UPPER MARLBORO', 0, 'ESE', 'UPPER MARLBORO', 38.815, -76.747, 38.8192, -76.7463, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'The stream gage on Western Branch at Upper Marlboro exceeded the 11 foot flood stage during the indicated period. The peak level of 15.18 feet was observed at 3:00am EST on June 4th. Water Street was flooded, along with the pedestrian bridge that runs alongside it. Race Track Road was also flooded.');
INSERT INTO public.stormevents_east VALUES (766873, 201806, 3, 1356, 201806, 3, 1447, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 13:56:00', 'EST-5', '03-JUN-18 14:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'TAKOMA PARK', 1, 'NNW', 'TAKOMA PARK', 38.9868, -77.0051, 38.9879, -77.0049, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'The stream gage on Sligo Creek near Takoma Park exceeded the 5.5 foot flood stage during the period indicated. The peak level of 5.75 feet was observed at 2:20pm EST on June 3rd. Sligo Creek Parkway was flooded.');
INSERT INTO public.stormevents_east VALUES (766879, 201806, 4, 200, 201806, 4, 1618, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '04-JUN-18 02:00:00', 'EST-5', '04-JUN-18 16:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 5, 'SW', 'WILLIAMSPORT', 4, 'W', 'DOWNSVILLE', 39.5593, -77.886, 39.5545, -77.8765, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'The stream gage on the Potomac River at Williamsport exceeded the flood stage of 23 feet during the indicated period, and possibly earlier. The Potomac Fish and Game Club reported flooding on its property. Backwater flooding caused by the high waters flooded Maryland Route 68 in Williamsport. The peak level observed was 24.49 feet at 9:47am EST on June 4th.');
INSERT INTO public.stormevents_east VALUES (767185, 201806, 3, 1739, 201806, 4, 638, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 17:39:00', 'EST-5', '04-JUN-18 06:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'BUENA', 2, 'E', 'BUENA', 38.3464, -77.9988, 38.3497, -77.9958, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Rapidan River near Culpeper exceeded the 13 foot flood stage during the indicated period. The peak level of 14.46 feet occurred at 2:00am EST on June 4th. River Road was flooded around the time of peak, along with farmland on both the Orange and Culpeper County sides of the river.');
INSERT INTO public.stormevents_east VALUES (769021, 201806, 25, 1526, 201806, 25, 1606, 128214, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:26:00', 'EST-5', '25-JUN-18 16:06:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'WSW', 'PERSIMMON', 6, 'SW', 'PINE MTN', 34.875, -83.578, 34.887, -83.252, 'For the third consecutive day, a cluster of thunderstorms moved from central Georgia into and across Rabun County, resulting in quite a bit of wind damage.', 'County comms reported numerous trees blown down across the county.');
INSERT INTO public.stormevents_east VALUES (769036, 201806, 25, 1433, 201806, 25, 1433, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 14:33:00', 'EST-5', '25-JUN-18 14:33:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'MILLTOWN', 1, 'E', 'MILLTOWN', 35.32, -83.81, 35.32, -83.81, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms reported a few trees blown down in the Robbinsville area.');
INSERT INTO public.stormevents_east VALUES (769302, 201806, 25, 1435, 201806, 25, 1435, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 14:35:00', 'EST-5', '25-JUN-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'LEICESTER', 1, 'E', 'LEICESTER', 35.65, -82.69, 35.65, -82.69, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms reported a couple trees blown down in the Leicester area.');
INSERT INTO public.stormevents_east VALUES (769303, 201806, 25, 1502, 201806, 25, 1502, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:02:00', 'EST-5', '25-JUN-18 15:02:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'BRYSON CITY', 0, 'N', 'BRYSON CITY', 35.43, -83.45, 35.43, -83.45, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms employee observed a couple of large trees blown down in Bryson City.');
INSERT INTO public.stormevents_east VALUES (769306, 201806, 25, 1519, 201806, 25, 1519, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:19:00', 'EST-5', '25-JUN-18 15:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'NE', 'NORTH COVE CROSSING', 1, 'NE', 'NORTH COVE CROSSING', 35.842, -81.986, 35.842, -81.986, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Media reported multiple trees blown down along Highway 221 in far northern McDowell County, including near Honeycutt Road.');
INSERT INTO public.stormevents_east VALUES (769310, 201806, 25, 1513, 201806, 25, 1545, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:13:00', 'EST-5', '25-JUN-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'NNW', 'WILMOT', 4, 'NE', 'RICH MTN', 35.417, -83.332, 35.362, -83.006, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms reported numerous trees blown down across the northern part of Jackson County.');
INSERT INTO public.stormevents_east VALUES (771299, 201806, 11, 1115, 201806, 11, 1115, 128576, 'GULF OF MEXICO', 85, 2018, 'June', 'Marine Thunderstorm Wind', 'KEY', '11-JUN-18 11:15:00', 'EST-5', '11-JUN-18 11:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 36, 'MG', NULL, NULL, 2, 'E', 'KEY WEST', 2, 'E', 'KEY WEST', 24.5571, -81.7554, 24.5571, -81.7554, 'Gale-force wind gusts occurred in association with thunderstorms developing over the Lower Florida Keys.', 'A wind gust of 36 knots was measured at Key West International Airport.');
INSERT INTO public.stormevents_east VALUES (771300, 201806, 11, 1122, 201806, 11, 1122, 128576, 'GULF OF MEXICO', 85, 2018, 'June', 'Marine Thunderstorm Wind', 'KEY', '11-JUN-18 11:22:00', 'EST-5', '11-JUN-18 11:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', 35, 'MG', NULL, NULL, 1, 'SW', 'KEY WEST', 1, 'SW', 'KEY WEST', 24.5532, -81.7886, 24.5532, -81.7886, 'Gale-force wind gusts occurred in association with thunderstorms developing over the Lower Florida Keys.', 'A wind gust of 35 knots was measured at the Weather Forecast Office Key West RSOIS.');
INSERT INTO public.stormevents_east VALUES (771301, 201806, 12, 1040, 201806, 12, 1040, 128577, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '12-JUN-18 10:40:00', 'EST-5', '12-JUN-18 10:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 7, 'NNE', 'KEY LARGO', 7, 'NNE', 'KEY LARGO', 25.1791, -80.3953, 25.1791, -80.3953, 'Cumulus cloud lines developed simultaneously throughout the entire Florida Keys, producing isolated waterspouts.', 'A waterspout was observed near the Jewfish Creek Bridge.');
INSERT INTO public.stormevents_east VALUES (771302, 201806, 12, 1052, 201806, 12, 1052, 128577, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '12-JUN-18 10:52:00', 'EST-5', '12-JUN-18 10:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'S', 'MARATHON', 2, 'S', 'MARATHON', 24.6862, -81.0848, 24.6862, -81.0848, 'Cumulus cloud lines developed simultaneously throughout the entire Florida Keys, producing isolated waterspouts.', 'A narrow waterspout was observed near Sombrero Beach in Marathon.  A spray ring was clearly visible.');
INSERT INTO public.stormevents_east VALUES (771303, 201806, 12, 1115, 201806, 12, 1135, 128577, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '12-JUN-18 11:15:00', 'EST-5', '12-JUN-18 11:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NNW', 'DUCK KEY', 1, 'NNW', 'DUCK KEY', 24.7949, -80.915, 24.7949, -80.915, 'Cumulus cloud lines developed simultaneously throughout the entire Florida Keys, producing isolated waterspouts.', 'A waterspout was observed on Florida Bay less than one mile north of Duck Key.  A spray ring was clearly visible.');
INSERT INTO public.stormevents_east VALUES (771304, 201806, 15, 1115, 201806, 15, 1140, 128578, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '15-JUN-18 11:15:00', 'EST-5', '15-JUN-18 11:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 9, 'SE', 'BIG PINE KEY', 9, 'SE', 'BIG PINE KEY', 24.59, -81.28, 24.59, -81.28, 'A waterspout was observed in association with an isolated rain shower oceanside of Bahia Honda Key.', 'A waterspout was observed about 5 miles south of Bahia Honda Key.  The condensation funnel reached the water surface from 1115 am through 1140 am.');
INSERT INTO public.stormevents_east VALUES (771305, 201806, 17, 1320, 201806, 17, 1320, 128579, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '17-JUN-18 13:20:00', 'EST-5', '17-JUN-18 13:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 5, 'N', 'KEY WEST', 5, 'N', 'KEY WEST', 24.63, -81.79, 24.63, -81.79, 'An isolated waterspout was observed north northwest of Key West in association with an isolated rain shower.', 'A waterspout was observed 5 miles north-northwest of Key West.');
INSERT INTO public.stormevents_east VALUES (771306, 201806, 23, 1505, 201806, 23, 1514, 128580, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '23-JUN-18 15:05:00', 'EST-5', '23-JUN-18 15:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 4, 'SSW', 'PLANTATION KEY', 4, 'SSW', 'PLANTATION KEY', 24.93, -80.57, 24.93, -80.57, 'Waterspouts were observed in association with isolated showers oceanside of Islamorada.', 'A waterspout with a visible spray ring was observed about 3 miles offshore of Mile Marker 84 of the Overseas Highway.  The waterspout moved toward the east-southeast.');
INSERT INTO public.stormevents_east VALUES (771307, 201806, 23, 1510, 201806, 23, 1517, 128580, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '23-JUN-18 15:10:00', 'EST-5', '23-JUN-18 15:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 4, 'E', 'PLANTATION KEY', 4, 'E', 'PLANTATION KEY', 24.9778, -80.4929, 24.9778, -80.4929, 'Waterspouts were observed in association with isolated showers oceanside of Islamorada.', 'A well-developed waterspout with a visible spray ring was observed about 2 miles offshore Tavernier and offshore of Mile Marker 89 of the Overseas Highway.');
INSERT INTO public.stormevents_east VALUES (780020, 201808, 28, 2130, 201808, 28, 2130, 130289, 'LAKE HURON', 90, 2018, 'August', 'Marine Thunderstorm Wind', 'DTX', '28-AUG-18 21:30:00', 'EST-5', '28-AUG-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 38, 'MG', NULL, NULL, 1, 'E', 'HARBOR BEACH', 1, 'E', 'HARBOR BEACH', 43.85, -82.6199, 43.85, -82.6199, 'Thunderstorms moving through Saginaw Bay produced with gusts to 60 mph.', NULL);
INSERT INTO public.stormevents_east VALUES (758661, 201805, 17, 2340, 201805, 20, 207, 126451, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 23:40:00', 'EST-5', '20-MAY-18 02:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'UPPER MARLBORO', 0, 'SSE', 'UPPER MARLBORO', 38.8196, -76.7455, 38.8146, -76.7456, 'Heavy rain fell in southern Maryland during the night of May 17th into the morning hours of the 18th. 1-4 inches of rain caused flooding, including of streams. More moderate to heavy rain continued in that area on the 18th and 19th, prolonging some flooding in Saint Mary''s County. Meanwhile, the cumulative effects of several days of rain throughout the region caused stream flooding, particularly on the Potomac River.', 'The stream gage on Western Branch at Upper Marlboro exceeded the 11 foot flood stage during the indicated times. The peak level observed was 12.75 feet at 3:40pm EST on May 18th. Water Street and portions of Marlboro Race Track Road were both flooded.');
INSERT INTO public.stormevents_east VALUES (758682, 201805, 18, 1900, 201805, 21, 1410, 126451, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '18-MAY-18 19:00:00', 'EST-5', '21-MAY-18 14:10:00', 0, 0, 0, 0, '0.10K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'SW', 'POOLESVILLE', 4, 'SW', 'WHITES FERRY', 39.1013, -77.4716, 39.1577, -77.5172, 'Heavy rain fell in southern Maryland during the night of May 17th into the morning hours of the 18th. 1-4 inches of rain caused flooding, including of streams. More moderate to heavy rain continued in that area on the 18th and 19th, prolonging some flooding in Saint Mary''s County. Meanwhile, the cumulative effects of several days of rain throughout the region caused stream flooding, particularly on the Potomac River.', 'The stream gage on the Potomac River at Edwards Ferry exceeded the 15 foot flood stage during the times indicated. The peak level of 17.87 feet was observed at 12:15pm EST on May 20th. Low-lying areas near Whites Ferry were covered by water, along with the boat ramp and lower parking area at Edwards Ferry. Near the time of peak flow, water entered the store at Whites Ferry.');
INSERT INTO public.stormevents_east VALUES (758735, 201805, 19, 1645, 201805, 21, 34, 126451, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 16:45:00', 'EST-5', '21-MAY-18 00:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'BRUNSWICK', 0, 'SSW', 'CATOCTIN STATION', 39.3103, -77.6408, 39.2963, -77.5711, 'Heavy rain fell in southern Maryland during the night of May 17th into the morning hours of the 18th. 1-4 inches of rain caused flooding, including of streams. More moderate to heavy rain continued in that area on the 18th and 19th, prolonging some flooding in Saint Mary''s County. Meanwhile, the cumulative effects of several days of rain throughout the region caused stream flooding, particularly on the Potomac River.', 'The stream gage on the Potomac River at Point of Rocks exceeded the 16 foot flood stage during the indicated times. The peak level of 17.39 feet occurred at 11:00am EST on May 20th. The Brunswick campground, parts of the C and O Canal, the lower parking lot of the Point of Rocks boat ramp, and the parking lot of the Brunswick and Nolands Ferry boat ramps all flooded.');
INSERT INTO public.stormevents_east VALUES (758803, 201805, 21, 1741, 201805, 21, 2000, 126453, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '21-MAY-18 17:41:00', 'EST-5', '21-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'HISER', 1, 'ESE', 'HISER', 38.9605, -79.1133, 38.9636, -79.1041, 'Another band of heavy rain fell in Grant County on May 21st, with 1-3 inches of rain causing flooding in the southeastern part of the county.', 'Multiple areas of water from South Mill Creek flowing over Durgon Road between North Mill Creek Road and the Hardy County border. Some were as much as two feet deep.');
INSERT INTO public.stormevents_east VALUES (754903, 201806, 3, 1430, 201806, 3, 1430, 125915, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'MRX', '03-JUN-18 14:30:00', 'EST-5', '03-JUN-18 14:30:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'N', 'PENNINGTON GAP', 1, 'N', 'PENNINGTON GAP', 36.76, -83.03, 36.76, -83.03, 'A few storms became severe in a strongly unstable environment ahead of a cold front during the afternoon. The storms produced a couple reports of small hail but, the main impact was from a few reports of damaging winds gusts along with some localized flooding.', 'One tree was reported down along with some trees limbs in Pennington Gap.');
INSERT INTO public.stormevents_east VALUES (758082, 201805, 15, 2300, 201805, 16, 200, 126423, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 23:00:00', 'EST-5', '16-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'SANDY HOOK', 1, 'N', 'WEVERTON', 39.33, -77.72, 39.3391, -77.6788, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Ongoing flooding throughout the overnight hours following torrential rains in South Washington County. Several roads remained covered by water and closed.');
INSERT INTO public.stormevents_east VALUES (758573, 201805, 16, 1653, 201805, 16, 2300, 126423, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 16:53:00', 'EST-5', '16-MAY-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'FT DETRICK', 1, 'N', 'FT DETRICK', 39.4394, -77.3996, 39.438, -77.4009, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'High standing water was covering North Market Street at Schifferstadt Boulevard. The road was closed as a result.');
INSERT INTO public.stormevents_east VALUES (758574, 201805, 16, 1725, 201805, 16, 2000, 126423, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 17:25:00', 'EST-5', '16-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'FT DETRICK', 0, 'SW', 'FT DETRICK', 39.425, -77.409, 39.4253, -77.4058, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'For the second day in a row, flooding occurred near North Market Street and 9th Street. Water was reported to be entering garages in the area, and covering yards.');
INSERT INTO public.stormevents_east VALUES (750817, 201806, 10, 2000, 201806, 10, 2000, 125189, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '10-JUN-18 20:00:00', 'EST-5', '10-JUN-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 46, 'MG', NULL, NULL, 15, 'N', 'PLAYALINDA BEACH', 15, 'N', 'PLAYALINDA BEACH', 28.77, -80.8, 28.77, -80.8, 'An upper-level low that had persisted just north of Florida moved away from the area, however deep south-southwesterly flow remained, keeping deep moisture across all of east central Florida. However, flow at the surface was weak as the axis of the Bermuda Ridge was south of the area across the northern Bahamas. This allowed the east coast sea breeze to develop. With enough instability due to daytime heating, showers and thunderstorms developed along the sea breeze. As the storms pushed back towards the coast in the evening, one storm produced strong winds along the Brevard County coast.', 'US Air Force wind tower 0421 measured a peak wind gust of 46 knots.');
INSERT INTO public.stormevents_east VALUES (750827, 201806, 14, 1823, 201806, 14, 1823, 125194, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'MLB', '14-JUN-18 18:23:00', 'EST-5', '14-JUN-18 18:23:00', 3, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'NE', 'ELLISON ACRES', 2, 'NE', 'ELLISON ACRES', 29.07, -80.91, 29.07, -80.91, 'Numerous showers and thunderstorms developed along the collision of the east and west coast sea breeze in eastern Orange and eastern Seminole County. One storm became strong and produced penny sized hail just east of Geneva. Then, as these storms pushed east towards the coast, one storm produced a lightning strike that injured three people that were near the edge of the boardwalk in New Smyrna Beach.', 'Broadcast Media relayed reports that three people were injured after being struck by lightning at the Smyrna Dunes Park, just south of Ponce Inlet, in New Smyrna Beach. A good samaritan called 911 after finding three people injured on the boardwalk in Smyrna Dunes Park from a lightning strike. The good samaritan helped revive one victim by performing life-saving CPR. Once firefighters arrived they provided medical assistance to the victims, and transported all of them to a local hospital where they were treated for minor injuries.');
INSERT INTO public.stormevents_east VALUES (750828, 201806, 14, 1800, 201806, 14, 1800, 125194, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MLB', '14-JUN-18 18:00:00', 'EST-5', '14-JUN-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'ESE', 'BRIDGEND', 1, 'ESE', 'BRIDGEND', 28.74, -81.1, 28.74, -81.1, 'Numerous showers and thunderstorms developed along the collision of the east and west coast sea breeze in eastern Orange and eastern Seminole County. One storm became strong and produced penny sized hail just east of Geneva. Then, as these storms pushed east towards the coast, one storm produced a lightning strike that injured three people that were near the edge of the boardwalk in New Smyrna Beach.', 'A trained spotter reported penny sized hail along State Road 46 just east of Geneva. The spotter also reported strong winds and a number of small branches on the roadway.');
INSERT INTO public.stormevents_east VALUES (753309, 201806, 20, 1554, 201806, 20, 1604, 125609, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '20-JUN-18 15:54:00', 'EST-5', '20-JUN-18 16:04:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'CLARKTOWN', 1, 'S', 'CLARKTOWN', 38.84, -82.9, 38.84, -82.9, 'Thunderstorms developed near a warm front that was across the region.', 'A large tree was knocked down into a power pole on Riddlebarger Road. Power lines were knocked down.');
INSERT INTO public.stormevents_east VALUES (752520, 201806, 25, 1235, 201806, 25, 1238, 125465, 'KENTUCKY', 21, 2018, 'June', 'Thunderstorm Wind', 'JKL', '25-JUN-18 12:35:00', 'EST-5', '25-JUN-18 12:38:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 51, 'EG', NULL, NULL, 1, 'SSW', 'WESSELL', 0, 'NNW', 'CALLAWAY', 36.7585, -83.6046, 36.782, -83.5715, 'After an overnight complex of storms pushed through eastern Kentucky, another system developed during the morning hours in western Kentucky. Clearing skies across southeast Kentucky allowed for destabilization and intensification of this second system as it pushed into eastern Kentucky. These showers and thunderstorms produced scattered wind damage across portions of southeast Kentucky during the early to mid afternoon hours.', 'Dispatch reported a tree blown down onto a home on U.S. Highway 119 at Helton Road. A tree was also blown down onto U.S. Highway 119 near Callaway.');
INSERT INTO public.stormevents_east VALUES (752518, 201806, 25, 1213, 201806, 25, 1215, 125465, 'KENTUCKY', 21, 2018, 'June', 'Thunderstorm Wind', 'JKL', '25-JUN-18 12:13:00', 'EST-5', '25-JUN-18 12:15:00', 0, 0, 0, 0, '25.00K', NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 0, 'N', 'CALVIN', 1, 'E', 'CALLAWAY', 36.72, -83.62, 36.78, -83.56, 'After an overnight complex of storms pushed through eastern Kentucky, another system developed during the morning hours in western Kentucky. Clearing skies across southeast Kentucky allowed for destabilization and intensification of this second system as it pushed into eastern Kentucky. These showers and thunderstorms produced scattered wind damage across portions of southeast Kentucky during the early to mid afternoon hours.', 'The Kentucky Department of Highways and local dispatch reported trees blown down from Calvin to Callaway along U.S. Highway 119. A home and vehicle were both damaged in Calvin as trees fell on both of them.');
INSERT INTO public.stormevents_east VALUES (752895, 201806, 26, 943, 201806, 26, 943, 125536, 'KENTUCKY', 21, 2018, 'June', 'Thunderstorm Wind', 'JKL', '26-JUN-18 09:43:00', 'EST-5', '26-JUN-18 09:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 51, 'EG', NULL, NULL, 1, 'ENE', 'SLEMP', 1, 'ENE', 'SLEMP', 37.09, -83.1, 37.09, -83.1, 'Multiple rounds of showers and thunderstorms brought periods of heavy rainfall to portions of southeast Kentucky from this morning into this evening, leading to instances of flooding and flash flooding. The worst flash flooding occurred in Harlan County, particularly near the Ages to Jones Creek area where a few locales received greater than 3 inches of rain in just over a 24 hour period. Late morning and afternoon heating allowed for a few storms to become severe, producing damaging wind gusts from early to mid afternoon.', 'The Kentucky Department of Highways relayed a report of a tree blown down across Kentucky Highway 699 between Slemp and Daisy.');
INSERT INTO public.stormevents_east VALUES (753308, 201806, 20, 1542, 201806, 20, 1552, 125609, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '20-JUN-18 15:42:00', 'EST-5', '20-JUN-18 15:52:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'LUCASVILLE', 1, 'W', 'LUCASVILLE', 38.88, -82.99, 38.88, -82.99, 'Thunderstorms developed near a warm front that was across the region.', 'Two trees were knocked down on Robert Lucas Road in Lucasville.');
INSERT INTO public.stormevents_east VALUES (753974, 201806, 27, 1258, 201806, 27, 1258, 125720, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'MLB', '27-JUN-18 12:58:00', 'EST-5', '27-JUN-18 12:58:00', 0, 0, 1, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, NULL, NULL, 3, 'NW', 'UMATILLA', 3, 'NW', 'UMATILLA', 28.9414, -81.6834, 28.9414, -81.6834, 'The main flow across central Florida was from the west-southwest due to a frontal trough moving across the mid-Atlantic states, and the axis of the Bermuda High Pressure situated across south Florida. Moisture was high across the area with Precipitable Water values around 1.80 to 2.00 inches. Temperatures aloft at 500 mb were around -6 to -7 degrees Celsius. The atmosphere was favorable for showers and thunderstorms to develop along the east and west coast sea breezes. Due to the stronger west winds, the west coast sea breeze was dominant, and the main collision between the two sea breezes occurred closer to the east central Florida coast. Still, numerous showers and thunderstorms impacted much of east central Florida. One man was killed after being struck by lightning in Umatilla, while another man was injured after being struck by lightning in Orlando.', 'Per a report received via a local newspaper, a 44-year-old man was killed after being struck by lightning in Umatilla. At 1721 LST, a man was found unconscious by his neighbors on a small pontoon boat at his home on Lake Owen, on the 40000th block of Long Island Drive in Umatilla. The neighbors called the Lake County Sheriffs Office, and first responders transported the man to a local hospital where he was pronounced deceased. The medical examiners office determined the cause of death to be electrocution, and this is further supported by burn marks found on the seat and floor of the boat. NWS Melbourne meteorologists determined the lightning strike occurred around 1258 LST, this was confirmed by reports from the neighbors who heard loud bang of the strike many hours before finding the deceased man on his boat.');
INSERT INTO public.stormevents_east VALUES (754603, 201806, 29, 1230, 201806, 29, 1530, 125737, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'MLB', '29-JUN-18 12:30:00', 'EST-5', '29-JUN-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'S', 'ROCKLEDGE', 2, 'SSW', 'COCOA WEST', 28.3022, -80.7219, 28.3245, -80.757, 'The surface high pressure ridge was located across south Florida, which resulted in south-southwesterly winds across east central Florida. Moisture was abundant with Precipitable Water values around 2 inches. An initial thunderstorm developed in central Brevard County and moved over Rockledge, producing rain for approximately 15 minutes. A short time later, a stronger, slow-moving thunderstorm developed right over Rockledge and remain over the same area for around an hour and a half. In total, 5 to 6 inches of rain fell in a 1.5 by 1.5 square mile area in southwest Rockledge. Temporary, but considerable roadway flood resulted.', 'Several reports of 5 to 6 inches of rain in the Rockledge area were received from trained spotters and the public. Most of the rain fell between 1230 and 1430 LST, with light rain lingering for several more hours. The main areas impacted were between Interstate 95, Fiske Boulevard, Eyster Boulevard, Murrell Road and Roy Wall Boulevard. Street flooding was reported on Levitt Parkway and in the nearby Silver Pines Estates neighborhood.');
INSERT INTO public.stormevents_east VALUES (751753, 201806, 18, 1616, 201806, 18, 1618, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Hail', 'BOX', '18-JUN-18 16:16:00', 'EST-5', '18-JUN-18 16:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 1, NULL, NULL, NULL, 1, 'NE', 'PLAINFIELD', 2, 'ENE', 'PLAINFIELD', 42.5299, -72.91, 42.5347, -72.8859, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:17 PM EST, hail up to 1 inch in diameter was reported on North Union Street and on Campbell Road.');
INSERT INTO public.stormevents_east VALUES (754860, 201806, 25, 40, 201806, 25, 500, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 00:40:00', 'EST-5', '25-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BELMONT', 1, 'SW', 'BELMONT', 42.3905, -71.1784, 42.3908, -71.1792, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 12:40 AM EST, Beech Street in Belmont was reported flooded and impassable from Waverly Road to Upland Road.');
INSERT INTO public.stormevents_east VALUES (754863, 201806, 25, 53, 201806, 25, 500, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 00:53:00', 'EST-5', '25-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'WEST VLG', 1, 'WNW', 'WEST VLG', 42.5715, -71.1101, 42.5719, -71.1095, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 12:53 AM EST, Main Street near Walmart in North Reading was flooded with one foot of standing water.');
INSERT INTO public.stormevents_east VALUES (790514, 201812, 9, 848, 201812, 9, 848, 132105, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '09-DEC-18 08:48:00', 'EST-5', '09-DEC-18 08:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 12, 'N', 'CLEARWATER BEACH', 12, 'N', 'CLEARWATER BEACH', 28.1533, -82.8012, 28.1533, -82.8012, 'A strong squall line moved southeast through the Florida Peninsula ahead of a cold front, producing gusty winds along the coast.', 'The COMPS site at Fred Howard Park (FHPF1) recorded a 43 knot marine wind gust.');
INSERT INTO public.stormevents_east VALUES (790515, 201812, 9, 1121, 201812, 9, 1125, 132104, 'FLORIDA', 12, 2018, 'December', 'Tornado', 'TBW', '09-DEC-18 11:21:00', 'EST-5', '09-DEC-18 11:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'SSE', 'BALM', 3, 'ESE', 'BALM', 27.703, -82.249, 27.7316, -82.2174, 'A strong squall line moved southeast through the Florida Peninsula ahead of a cold front, producing gusty winds and two weak tornadoes.', 'Tree damage and minor structural damage was found in the vicinity of Carlton Lake Road and Florida 674.');
INSERT INTO public.stormevents_east VALUES (790516, 201812, 9, 857, 201812, 9, 858, 132104, 'FLORIDA', 12, 2018, 'December', 'Tornado', 'TBW', '09-DEC-18 08:57:00', 'EST-5', '09-DEC-18 08:58:00', 0, 0, 0, 0, '50.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'E', 'NEW PORT RICHEY', 2, 'E', 'NEW PORT RICHEY', 28.2555, -82.6883, 28.2557, -82.6863, 'A strong squall line moved southeast through the Florida Peninsula ahead of a cold front, producing gusty winds and two weak tornadoes.', 'The majority of damage was EF0 in nature with large tree limbs,|branches and powerlines down in a small area off of Bolam Avenue near|Atis Street. Minor roof damage was also observed with some homes|having shingles and roofing felt blown off. One large oak tree was|found to have been snapped in two different places and this was|consistent with EF1 damage in the 90-100 mph range.');
INSERT INTO public.stormevents_east VALUES (790566, 201812, 20, 710, 201812, 20, 710, 132119, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '20-DEC-18 07:10:00', 'EST-5', '20-DEC-18 07:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'EG', NULL, NULL, 2, 'W', 'MIDDLE TAMPA BAY', 2, 'W', 'MIDDLE TAMPA BAY', 27.77, -82.57, 27.77, -82.57, 'A squall line developed ahead of a strong cold front and pushed southeast through the west coast of the Florida Peninsula, producing widespread thunderstorm wind gusts along the coast.', 'The WeatherFlow station in the Tampa Bay (XTAM) recorded a 39 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (790219, 201812, 9, 1305, 201812, 9, 1305, 132058, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'MLB', '09-DEC-18 13:05:00', 'EST-5', '09-DEC-18 13:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 35, 'MG', NULL, NULL, 7, 'E', 'PLAYALINDA BEACH', 7, 'E', 'PLAYALINDA BEACH', 28.56, -80.67, 28.56, -80.67, 'Thunderstorms moved across northern Merritt Island and produced wind gusts of 35 to 40 knots.', 'A wind gust of 35 knots from the southwest was recorded at USAF wind tower 0509 over north Merritt Island as a thunderstorm crossed the area. Five minutes later, wind gusts of 40 knots and 34 knots were recorded at USAF wind towers 0211 and 0311, respectively, several miles farther northeast.');
INSERT INTO public.stormevents_east VALUES (790340, 201812, 3, 1505, 201812, 3, 1505, 132086, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'MLB', '03-DEC-18 15:05:00', 'EST-5', '03-DEC-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 6, 'NNW', 'PLAYALINDA BEACH', 6, 'NNW', 'PLAYALINDA BEACH', 28.63, -80.81, 28.63, -80.81, 'A thunderstorm produced wind gusts over 34 knots as it exited the mainland near Titusville and continued rapidly east across the Merritt Island National Wildlife Refuge and offshore The Canaveral National Seashore.', 'A thunderstorm moved offshore the mainland near Titusville and produced wind gusts of 35 knots from the west-northwest at a mesonet site four miles south-southeast of Mims.');
INSERT INTO public.stormevents_east VALUES (791707, 201812, 2, 1250, 201812, 2, 1250, 132316, 'GEORGIA', 13, 2018, 'December', 'Flood', 'JAX', '02-DEC-18 12:50:00', 'EST-5', '02-DEC-18 12:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'WAYCROSS', 2, 'S', 'WAYCROSS', 31.21, -82.36, 31.197, -82.3457, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'Widespread flooding across the city of Waycross with road closures. Flood waters were at the door of many residences.');
INSERT INTO public.stormevents_east VALUES (791806, 201812, 20, 1118, 201812, 20, 1118, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 11:18:00', 'EST-5', '20-DEC-18 11:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 0, 'N', 'FERNANDINA NOS', 0, 'N', 'FERNANDINA NOS', 30.67, -81.47, 30.67, -81.47, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The NOS station in Fernandina Beach measured a wind gust to 40 mph in showers.');
INSERT INTO public.stormevents_east VALUES (764899, 201806, 22, 354, 201806, 22, 600, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 03:54:00', 'EST-5', '22-JUN-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'HEARDS', 0, 'SW', 'HEARDS', 37.9173, -78.756, 37.917, -78.7553, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Taylor Creek Road flooded and closed near the Nelson County border.');
INSERT INTO public.stormevents_east VALUES (764901, 201806, 22, 500, 201806, 22, 700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 05:00:00', 'EST-5', '22-JUN-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'GRASSLAND', 1, 'SSW', 'GRASSLAND', 38.2619, -77.985, 38.2622, -77.9836, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Flooding causing road closures near the intersection of Virginia Routes 20 and 671.');
INSERT INTO public.stormevents_east VALUES (765714, 201806, 22, 533, 201806, 22, 730, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 05:33:00', 'EST-5', '22-JUN-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BUENA', 1, 'S', 'BUENA', 38.3316, -78.0346, 38.3319, -78.0334, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Twin Mountains Road (Route 647) flooded and closed.');
INSERT INTO public.stormevents_east VALUES (765715, 201806, 22, 637, 201806, 22, 830, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 06:37:00', 'EST-5', '22-JUN-18 08:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'HOLLY CORNER', 2, 'E', 'HOLLY CORNER', 38.3736, -77.5404, 38.3739, -77.5397, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Holly Corner Road (Route 655) flooded and closed near Hall Lane.');
INSERT INTO public.stormevents_east VALUES (765716, 201806, 22, 725, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:25:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'HUDSON XRDS', 1, 'NW', 'HUDSON XRDS', 38.8132, -78.7426, 38.8127, -78.7423, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Crooked Run Road flooded and closed at Riles Run.');
INSERT INTO public.stormevents_east VALUES (765822, 201806, 23, 430, 201806, 23, 630, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 04:30:00', 'EST-5', '23-JUN-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'PARTLOW', 2, 'SSW', 'PARTLOW', 38.0018, -77.6523, 38.0016, -77.6514, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Four to five feet of standing water over Log Cabin Road west of Butler Road.');
INSERT INTO public.stormevents_east VALUES (765823, 201806, 23, 430, 201806, 23, 630, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 04:30:00', 'EST-5', '23-JUN-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'WSW', 'PARTLOW', 4, 'WSW', 'PARTLOW', 38.0133, -77.7016, 38.0133, -77.7009, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Water was flowing over Arritt Road at the North Anna River. The bridge to Louisa County was impassable.');
INSERT INTO public.stormevents_east VALUES (765824, 201806, 22, 315, 201806, 22, 500, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'LWX', '22-JUN-18 03:15:00', 'EST-5', '22-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'GEER', 1, 'ESE', 'GEER', 38.2944, -78.4884, 38.2945, -78.4879, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Garth Road washed out due to rapidly rising and moving waters at Swift Run.');
INSERT INTO public.stormevents_east VALUES (765825, 201806, 22, 315, 201806, 22, 500, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'LWX', '22-JUN-18 03:15:00', 'EST-5', '22-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'STANDARDSVILLE', 1, 'NNW', 'STANDARDSVILLE', 38.3127, -78.4357, 38.3121, -78.4351, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Octonia Road flooded and closed with extremely high water and a large amount of debris.');
INSERT INTO public.stormevents_east VALUES (765827, 201806, 22, 315, 201806, 22, 500, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'LWX', '22-JUN-18 03:15:00', 'EST-5', '22-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 4, 'W', 'QUINQUE', 3, 'W', 'QUINQUE', 38.2517, -78.4645, 38.2516, -78.4633, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Amicus Road flooded and closed east of Celt Road due to extreme flooding of Swift Run.');
INSERT INTO public.stormevents_east VALUES (791807, 201812, 20, 1137, 201812, 20, 1137, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 11:37:00', 'EST-5', '20-DEC-18 11:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 2, 'SE', 'CUMBERLAND STAFFORD', 2, 'SE', 'CUMBERLAND STAFFORD', 31.05, -81.41, 31.05, -81.41, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The WeatherFlow sensor at Jekyll Island measured a wind gust to 42 mph in showers.');
INSERT INTO public.stormevents_east VALUES (791808, 201812, 20, 1155, 201812, 20, 1155, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 11:55:00', 'EST-5', '20-DEC-18 11:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 37, 'MG', NULL, NULL, 5, 'NNE', 'BRUNSWICK', 5, 'NNE', 'BRUNSWICK', 31.25, -81.47, 31.25, -81.47, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The AWOS at the Brunswick Golden Isles airport measured a gust of 43 mph.');
INSERT INTO public.stormevents_east VALUES (775044, 201808, 8, 1655, 201808, 8, 1655, 129352, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '08-AUG-18 16:55:00', 'EST-5', '08-AUG-18 16:55:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'MADRID', 1, 'S', 'MADRID', 38.1393, -78.8806, 38.1393, -78.8806, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which became severe.', 'A tree was blown down on the 700 block of Hildebrand Church Road.');
INSERT INTO public.stormevents_east VALUES (775045, 201808, 8, 1715, 201808, 8, 1715, 129352, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '08-AUG-18 17:15:00', 'EST-5', '08-AUG-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 0, 'SW', 'MIDWAY', 0, 'SW', 'MIDWAY', 38.0253, -78.7059, 38.0253, -78.7059, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which became severe.', 'A tree was blown down along Miller School Road.');
INSERT INTO public.stormevents_east VALUES (775079, 201808, 12, 1500, 201808, 12, 1500, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 15:00:00', 'EST-5', '12-AUG-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'SPOTSYLVANIA', 1, 'W', 'SPOTSYLVANIA', 38.2, -77.59, 38.2, -77.59, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'A tree was blown down on the 8600 block of Brock Road. A tree was also blown down on River Road near Bragg Road.');
INSERT INTO public.stormevents_east VALUES (791809, 201812, 20, 1156, 201812, 20, 1156, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 11:56:00', 'EST-5', '20-DEC-18 11:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 39, 'MG', NULL, NULL, 2, 'NNE', 'MCKINNON ARPT', 2, 'NNE', 'MCKINNON ARPT', 31.18, -81.38, 31.18, -81.38, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Malcom McKinnon Airport ASOS measured a wind gust to 45 mph.');
INSERT INTO public.stormevents_east VALUES (791810, 201812, 20, 1152, 201812, 20, 1152, 132334, 'GEORGIA', 13, 2018, 'December', 'Thunderstorm Wind', 'JAX', '20-DEC-18 11:52:00', 'EST-5', '20-DEC-18 11:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 50, 'MG', NULL, NULL, 2, 'SE', 'JEKYLL IS', 2, 'SE', 'JEKYLL IS', 31.05, -81.41, 31.05, -81.41, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow site at Jekyll Island measured a wind gust of 58 mph.');
INSERT INTO public.stormevents_east VALUES (791805, 201812, 20, 1106, 201812, 20, 1106, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 11:06:00', 'EST-5', '20-DEC-18 11:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 48, 'MG', NULL, NULL, 1, 'NE', 'MAYPORT NAS', 1, 'NE', 'MAYPORT NAS', 30.41, -81.41, 30.41, -81.41, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow sensor at Huguenot Park measured a wind gust to 55 mph in showers.');
INSERT INTO public.stormevents_east VALUES (755236, 201806, 2, 920, 201806, 3, 500, 125982, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'RLX', '02-JUN-18 09:20:00', 'EST-5', '03-JUN-18 05:00:00', 0, 0, 0, 0, '50.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'KINGSVILLE', 2, 'SE', 'BEECH RUN JCT', 38.9158, -80.0576, 38.677, -80.1274, 'A cold front and upper level low pressure system brought showers and thunderstorms on the 2nd. An area of heavy rain across the northern mountainous counties of WV caused minor flooding.', 'High water closed multiple roads across the county. This included sections of Georgetown Road, Pritt Lane and Rack Road in Daily. Water also closed Becky Creek Road near Lee Bell and Route 29 near Whitmer. Adolph Road was washed out in several places near Adolph, and was also closed by mud slide debris near Mill Creek.||The river gage on the Tygart Valley River at Mill Creek showed the Tygart Valley River surpassed its bankfull level of 11 feet around noon on the 2nd. The river crested at 12.4 feet late that evening and returned to its banks during the predawn hours of the 3rd.');
INSERT INTO public.stormevents_east VALUES (755255, 201806, 17, 1510, 201806, 17, 1510, 125985, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 15:10:00', 'EST-5', '17-JUN-18 15:10:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'MILLFIELD', 0, 'N', 'MILLFIELD', 39.43, -82.1, 39.43, -82.1, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. A couple of these storms were strong enough to produce hail and isolated wind damage.', 'Several trees were blown down in Millfield.');
INSERT INTO public.stormevents_east VALUES (755256, 201806, 17, 1515, 201806, 17, 1515, 125985, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 15:15:00', 'EST-5', '17-JUN-18 15:15:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'CHAUNCEY', 0, 'N', 'CHAUNCEY', 39.4, -82.13, 39.4, -82.13, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. A couple of these storms were strong enough to produce hail and isolated wind damage.', 'Two trees were blown down in Chauncey, each bringing down electrical wires and blocking roads.');
INSERT INTO public.stormevents_east VALUES (755257, 201806, 17, 1550, 201806, 17, 1550, 125985, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 15:50:00', 'EST-5', '17-JUN-18 15:50:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'STOCKPORT', 0, 'N', 'STOCKPORT', 39.55, -81.8, 39.55, -81.8, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. A couple of these storms were strong enough to produce hail and isolated wind damage.', 'Several trees were downed by thunderstorm winds along Dale Road and County Route 2.');
INSERT INTO public.stormevents_east VALUES (755259, 201806, 17, 1505, 201806, 17, 1505, 125985, 'OHIO', 39, 2018, 'June', 'Hail', 'RLX', '17-JUN-18 15:05:00', 'EST-5', '17-JUN-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'MILLFIELD', 0, 'N', 'MILLFIELD', 39.43, -82.1, 39.43, -82.1, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. A couple of these storms were strong enough to produce hail and isolated wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (751741, 201806, 18, 1615, 201806, 18, 1615, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 16:15:00', 'EST-5', '18-JUN-18 16:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NE', 'COLRAIN', 1, 'NE', 'COLRAIN', 42.6759, -72.6703, 42.6759, -72.6703, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:15 PM EST, a tree was reported down on wires on West Leyden Road in Colrain.');
INSERT INTO public.stormevents_east VALUES (751743, 201806, 18, 1629, 201806, 18, 1629, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 16:29:00', 'EST-5', '18-JUN-18 16:29:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'E', 'BERNARDSTON', 1, 'E', 'BERNARDSTON', 42.6674, -72.5251, 42.6674, -72.5251, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:29 PM EST, multiple trees and wires were down on Shaw Road in Bernardston.');
INSERT INTO public.stormevents_east VALUES (751744, 201806, 18, 1631, 201806, 18, 1631, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 16:31:00', 'EST-5', '18-JUN-18 16:31:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'SW', 'SOUTH ASHFIELD', 0, 'SW', 'SOUTH ASHFIELD', 42.5152, -72.7769, 42.5152, -72.7769, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:31 PM EST, wires and a transformer were down on Conway Road, State Route 116, in Ashfield.');
INSERT INTO public.stormevents_east VALUES (765486, 201806, 18, 1352, 201806, 18, 1352, 127655, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 13:52:00', 'EST-5', '18-JUN-18 13:52:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNE', 'PORTERS CORNERS', 2, 'NNE', 'PORTERS CORNERS', 43.6, -75.2, 43.6, -75.2, 'Our region was located at the top of an upper level ridge, with a shortwave passing to the north driving a cold front across the region. Early on, this looked like a flash flood event with precipitable water values forecast to exceed 2 inches. However, wind speeds aloft got progressively faster as the event approached, leading to faster storm motion which ultimately limited the threat. The first round of storms developed along lake breezes and with a weak pre-frontal trough. By this time wind shear was moderate with the 18Z Buffalo sounding showing 40 kts at 700 mb with some directional shear. Mid-level lapse rates were marginal, which probably limited updraft strength. However radar showed rotation in some storms, one of which produced damage in Lewis county.', 'Trees down on Moose River Road.');
INSERT INTO public.stormevents_east VALUES (765487, 201806, 18, 1800, 201806, 18, 1800, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:00:00', 'EST-5', '18-JUN-18 18:00:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'PORTLAND', 0, 'N', 'PORTLAND', 42.38, -79.47, 42.38, -79.47, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Tree down in the town of Portland.');
INSERT INTO public.stormevents_east VALUES (765488, 201806, 18, 1817, 201806, 18, 1817, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:17:00', 'EST-5', '18-JUN-18 18:17:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'ELLERY CENTER', 0, 'N', 'ELLERY CENTER', 42.18, -79.35, 42.18, -79.35, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Multiple reports of the downing of trees and wires.');
INSERT INTO public.stormevents_east VALUES (765489, 201806, 18, 1824, 201806, 18, 1824, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:24:00', 'EST-5', '18-JUN-18 18:24:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'GERRY', 1, 'N', 'GERRY', 42.19, -79.25, 42.19, -79.25, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Multiple reports of the downing of trees and wires.');
INSERT INTO public.stormevents_east VALUES (765490, 201806, 18, 1826, 201806, 18, 1826, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:26:00', 'EST-5', '18-JUN-18 18:26:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'FLUVANNA', 0, 'N', 'FLUVANNA', 42.12, -79.28, 42.12, -79.28, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Multiple reports of the downing of trees and wires.');
INSERT INTO public.stormevents_east VALUES (762795, 201806, 24, 1930, 201806, 24, 1935, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:30:00', 'EST-5', '24-JUN-18 19:35:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 0, 'NNE', 'HOPKINS', 0, 'NNE', 'HOPKINS', 33.9058, -80.8767, 33.9058, -80.8767, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Power lines down near the intersection of Lower Richland Blvd and Old Hopkins Rd.');
INSERT INTO public.stormevents_east VALUES (762801, 201806, 24, 1930, 201806, 24, 1935, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:30:00', 'EST-5', '24-JUN-18 19:35:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'SE', 'GREENLAWN', 1, 'SE', 'GREENLAWN', 33.9714, -80.9548, 33.9714, -80.9548, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Tree down in roadway at I-77 at exit 9.');
INSERT INTO public.stormevents_east VALUES (762802, 201806, 24, 1942, 201806, 24, 1945, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:42:00', 'EST-5', '24-JUN-18 19:45:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 4, 'NW', 'HAMMOND XRDS', 4, 'NW', 'HAMMOND XRDS', 33.7911, -80.9212, 33.7911, -80.9212, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Tree limbs were downed and major damage occurred to an aluminum pump house on Old Swamp Rd in Sandy Run.  Time estimated.');
INSERT INTO public.stormevents_east VALUES (762803, 201806, 24, 2032, 201806, 24, 2035, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 20:32:00', 'EST-5', '24-JUN-18 20:35:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 2, 'NW', 'BEARD', 2, 'NW', 'BEARD', 33.8728, -80.0724, 33.8728, -80.0724, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down near the intersection of Farmington Rd and Salem Rd.');
INSERT INTO public.stormevents_east VALUES (762804, 201806, 24, 2035, 201806, 24, 2040, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 20:35:00', 'EST-5', '24-JUN-18 20:40:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 1, 'WSW', 'TURBEVILLE', 1, 'WSW', 'TURBEVILLE', 33.8748, -80.0345, 33.8748, -80.0345, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down near the intersection of William Gibbons Rd and US Hwy 301.');
INSERT INTO public.stormevents_east VALUES (762805, 201806, 24, 2039, 201806, 24, 2044, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 20:39:00', 'EST-5', '24-JUN-18 20:44:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'SW', 'JORDAN', 1, 'SW', 'JORDAN', 33.59, -80.23, 33.59, -80.23, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Numerous limbs down on a golf course.');
INSERT INTO public.stormevents_east VALUES (762807, 201806, 24, 2048, 201806, 24, 2050, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 20:48:00', 'EST-5', '24-JUN-18 20:50:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 4, 'ENE', 'WILSON', 4, 'ENE', 'WILSON', 33.6866, -80.0546, 33.6866, -80.0546, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down on Kingstree Hwy and S Brewington Rd.');
INSERT INTO public.stormevents_east VALUES (762808, 201806, 24, 2052, 201806, 24, 2055, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 20:52:00', 'EST-5', '24-JUN-18 20:55:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 60, 'EG', NULL, NULL, 1, 'WSW', 'BELVEDERE', 1, 'WSW', 'BELVEDERE', 33.5244, -81.9663, 33.5244, -81.9663, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Media reported trees fell on 2 cars at a home on Cadada Ct in North Augusta. No injuries.');
INSERT INTO public.stormevents_east VALUES (779302, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'EMMITSBURG', 1, 'ESE', 'EMMITSBURG', 39.7008, -77.3219, 39.6979, -77.3189, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Creamery Road was closed due to flooding of Willow Run.');
INSERT INTO public.stormevents_east VALUES (779304, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'EMMITSBURG', 1, 'WNW', 'EMMITSBURG', 39.7036, -77.3529, 39.7035, -77.3523, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Annandale Road at Hampton Valley Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (779305, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'EMMITSBURG', 1, 'N', 'EMMITSBURG', 39.7186, -77.3275, 39.7185, -77.3273, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Irishtown Road was closed due to flooding of Toms Creek.');
INSERT INTO public.stormevents_east VALUES (779306, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'ST ANTHONY', 3, 'NW', 'ST ANTHONY', 39.7176, -77.3925, 39.7174, -77.3925, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Hornets Nest Road was closed due to flooding of Owens Creek.');
INSERT INTO public.stormevents_east VALUES (779307, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'EMMITSBURG', 1, 'NE', 'EMMITSBURG', 39.7084, -77.3214, 39.7086, -77.3217, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'North Seton Avenue was closed due to flooding of Flat Run.');
INSERT INTO public.stormevents_east VALUES (768881, 201806, 3, 2005, 201806, 3, 2010, 128204, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '03-JUN-18 20:05:00', 'EST-5', '03-JUN-18 20:10:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WNW', 'WHITNEY', 2, 'ENE', 'RICHFIELD', 35.5, -80.2, 35.4811, -80.2372, 'Convection developed along a cold front moving eastward through the region during the early evening. One cell produced isolated wind damage as it moved through Stanly county.', 'Several trees were blown down along a swath from Richfield to Newsom. Dime sized hail was also reported near the intersection of Highway 49 and Ingram Road in Richfield.');
INSERT INTO public.stormevents_east VALUES (768889, 201806, 2, 1650, 201806, 2, 1650, 128205, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '02-JUN-18 16:50:00', 'EST-5', '02-JUN-18 16:50:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'NW', 'FREMONT', 4, 'NW', 'FREMONT', 35.59, -78.04, 35.59, -78.04, 'A slow-moving upper level trough drifting across the central Appalachians and southern middle Atlantic states resulted in scattered convection development and outflow mergers across central North Carolina.', 'One tree was blown down on Polly Watson Road in Fremont.');
INSERT INTO public.stormevents_east VALUES (768894, 201806, 1, 1652, 201806, 1, 1700, 128206, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '01-JUN-18 16:52:00', 'EST-5', '01-JUN-18 17:00:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'W', 'LEWISVILLE', 1, 'ESE', 'LEWISVILLE', 36.1, -80.48, 36.09, -80.4, 'A few multi-cell clusters developed ahead of a well-defined, convectively enhanced vorticity maximum that crossed the mountains and moved into the area during the late afternoon and evening. Two of the clusters produced minor wind damage in the form of scattered trees down in Forsyth and Chatham counties.', 'A couple of trees were blown down along a swath from mile marker 247 on US-421 to the intersection of Ridge Gate Drive and Arbor Run Drive in Lewisville.');
INSERT INTO public.stormevents_east VALUES (768895, 201806, 1, 1900, 201806, 1, 1900, 128206, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '01-JUN-18 19:00:00', 'EST-5', '01-JUN-18 19:00:00', 0, 0, 0, 0, '7.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'CRUTCHFIELD XRDS', 1, 'S', 'CRUTCHFIELD XRDS', 35.78, -79.42, 35.78, -79.42, 'A few multi-cell clusters developed ahead of a well-defined, convectively enhanced vorticity maximum that crossed the mountains and moved into the area during the late afternoon and evening. Two of the clusters produced minor wind damage in the form of scattered trees down in Forsyth and Chatham counties.', 'Several trees were blown down along Silk Hope Liberty Road and Siler City Snow Camp Road.');
INSERT INTO public.stormevents_east VALUES (768899, 201806, 1, 2108, 201806, 1, 2108, 128206, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '01-JUN-18 21:08:00', 'EST-5', '01-JUN-18 21:08:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'SNEADS GROVE', 1, 'ENE', 'SNEADS GROVE', 34.84, -79.46, 34.84, -79.46, 'A few multi-cell clusters developed ahead of a well-defined, convectively enhanced vorticity maximum that crossed the mountains and moved into the area during the late afternoon and evening. Two of the clusters produced minor wind damage in the form of scattered trees down in Forsyth and Chatham counties.', 'One tree was blown down on Old Wire Road near Aberdeen Road in Laurel Hill.');
INSERT INTO public.stormevents_east VALUES (769070, 201806, 11, 1549, 201806, 11, 1549, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'RAH', '11-JUN-18 15:49:00', 'EST-5', '11-JUN-18 15:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'E', 'MAMERS', 1, 'E', 'MAMERS', 35.4195, -78.9372, 35.4195, -78.9372, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Quarter-sized hail was reported at  7071 U.S. Highway 421, Mamers, NC.');
INSERT INTO public.stormevents_east VALUES (776120, 201807, 21, 2045, 201807, 21, 2130, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 20:45:00', 'EST-5', '21-JUL-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'ARCOLA', 1, 'NW', 'ARCOLA', 38.9592, -77.544, 38.9595, -77.543, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Torrential rain prompted flooding of Broad Run, forcing a water rescue on Evergreen Mills Road near Belmont Ridge Road.');
INSERT INTO public.stormevents_east VALUES (776123, 201807, 21, 2125, 201807, 21, 2225, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 21:25:00', 'EST-5', '21-JUL-18 22:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'WELLINGTON', 3, 'NNE', 'WELLINGTON', 38.8184, -77.5275, 38.8187, -77.5261, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Sudley Road (State Route 234) flooded due to Youngs Branch going out of its banks. Two vehicles were trapped in swift rushing water from Youngs Branch, prompting water rescues.');
INSERT INTO public.stormevents_east VALUES (776126, 201807, 21, 2255, 201807, 21, 2355, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 22:55:00', 'EST-5', '21-JUL-18 23:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'WELLINGTON', 2, 'N', 'WELLINGTON', 38.8151, -77.5494, 38.815, -77.5486, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Swift water rescue on Featherbed Lane near Manassas.');
INSERT INTO public.stormevents_east VALUES (776175, 201807, 21, 2010, 201807, 21, 2200, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 20:10:00', 'EST-5', '21-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BRENTSVILLE', 0, 'WNW', 'BRENTSVILLE', 38.6821, -77.5096, 38.6816, -77.5085, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Water rescue from floodwaters at the intersection of Old Church Road and Crockett Road.');
INSERT INTO public.stormevents_east VALUES (776179, 201807, 21, 2010, 201807, 21, 2200, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 20:10:00', 'EST-5', '21-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BRISTOW', 0, 'NNW', 'BRISTOW', 38.726, -77.5315, 38.7268, -77.5321, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Piper Lane flooded and closed due to overflow of Broad Run near the railroad tracks.');
INSERT INTO public.stormevents_east VALUES (776180, 201807, 21, 2125, 201807, 21, 2300, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:25:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'MINNIEVILLE', 1, 'SW', 'MINNIEVILLE', 38.6251, -77.357, 38.625, -77.3571, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Wintercress Court flooded and closed near Tallowwood Drive.');
INSERT INTO public.stormevents_east VALUES (758123, 201806, 10, 1848, 201806, 10, 1848, 126477, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '10-JUN-18 18:48:00', 'EST-5', '10-JUN-18 18:48:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 3, 'S', 'MID BAY BUOY', 3, 'S', 'MID BAY BUOY', 38.432, -76.387, 38.432, -76.387, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms produce gusty winds.', 'A wind gust in excess of 30 knots was reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (758124, 201806, 18, 1714, 201806, 18, 1719, 126478, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '18-JUN-18 17:14:00', 'EST-5', '18-JUN-18 17:19:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 52, 'MG', NULL, NULL, 0, 'N', 'GREENBERRY POINT (GBY)', 0, 'N', 'GREENBERRY POINT (GBY)', 38.97, -76.46, 38.97, -76.46, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to some storms producing gusty winds.', 'Wind gusts of 36 to 52 knots were reported at Greenberry Point.');
INSERT INTO public.stormevents_east VALUES (758126, 201806, 18, 1721, 201806, 18, 1721, 126478, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '18-JUN-18 17:21:00', 'EST-5', '18-JUN-18 17:21:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to some storms producing gusty winds.', 'A wind gust in excess of 30 knots was reported at Tolly Point.');
INSERT INTO public.stormevents_east VALUES (758127, 201806, 19, 1342, 201806, 19, 1342, 126479, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '19-JUN-18 13:42:00', 'EST-5', '19-JUN-18 13:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 3, 'S', 'MID BAY BUOY', 3, 'S', 'MID BAY BUOY', 38.432, -76.387, 38.432, -76.387, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to a couple storms producing gusty winds.', 'A wind gust in excess of 30 knots was reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (758128, 201806, 19, 1431, 201806, 19, 1431, 126479, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '19-JUN-18 14:31:00', 'EST-5', '19-JUN-18 14:31:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'EG', NULL, NULL, 0, 'N', 'QUANTICO (KNYG)', 0, 'N', 'QUANTICO (KNYG)', 38.51, -77.3, 38.51, -77.3, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to a couple storms producing gusty winds.', 'A wind gust in excess of 30 knots was reported at Quantico.');
INSERT INTO public.stormevents_east VALUES (758130, 201806, 19, 1524, 201806, 19, 1524, 126479, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '19-JUN-18 15:24:00', 'EST-5', '19-JUN-18 15:24:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'A weak trough caused thunderstorms to develop in a hot and humid air mass. The heat and humidity led to a couple storms producing gusty winds.', 'A wind gust in excess of 30 knots was reported at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (758131, 201806, 23, 1739, 201806, 23, 1739, 126480, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '23-JUN-18 17:39:00', 'EST-5', '23-JUN-18 17:39:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 43, 'MG', NULL, NULL, 0, 'N', 'QUANTICO (KNYG)', 0, 'N', 'QUANTICO (KNYG)', 38.51, -77.3, 38.51, -77.3, 'An isolated thunderstorm caused gusty winds.', 'A wind gust of 43 knots was reported at Quantico.');
INSERT INTO public.stormevents_east VALUES (758132, 201806, 24, 1444, 201806, 24, 1454, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 14:44:00', 'EST-5', '24-JUN-18 14:54:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 46, 'MG', NULL, NULL, 0, 'N', 'POINT LOOKOUT (PTL)', 0, 'N', 'POINT LOOKOUT (PTL)', 38.04, -76.32, 38.04, -76.32, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'Wind gusts of 38 to 46 knots were reported at Point Lookout.');
INSERT INTO public.stormevents_east VALUES (758133, 201806, 24, 1556, 201806, 24, 1556, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 15:56:00', 'EST-5', '24-JUN-18 15:56:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 39, 'MG', NULL, NULL, 0, 'N', 'MONROE CREEK (MON)', 0, 'N', 'MONROE CREEK (MON)', 38.23, -76.95, 38.23, -76.95, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'A wind gust of 39 knots was reported at Monroe Creek.');
INSERT INTO public.stormevents_east VALUES (766925, 201806, 3, 517, 201806, 3, 2155, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 05:17:00', 'EST-5', '03-JUN-18 21:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'NW', 'BOYCE', 5, 'NNW', 'BOYCE', 39.1477, -78.0911, 39.1637, -78.0882, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Flooding occurred along Opequon Creek in Clarke County both upstream and downstream of the stream gage near Berryville. The gage exceeded the 10 foot flood stage during the indicated period, with a peak of 13.12 feet at 12:45pm EST on June 3rd. Opequon Road and Old Charles Town Road both flooded and other flooding, especially agricultural flooding, was observed.');
INSERT INTO public.stormevents_east VALUES (767256, 201806, 3, 2200, 201806, 5, 54, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 22:00:00', 'EST-5', '05-JUN-18 00:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'FREDERICKSBURG', 1, 'NNE', 'FREDERICKSBURG', 38.3198, -77.4698, 38.3171, -77.4643, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The tide gage on the Rappahannock River at Fredericksburg City Dock exceeded the 13 foot flood stage during the indicated period. River Road and a park on the Stafford County side of the river flooded.');
INSERT INTO public.stormevents_east VALUES (767258, 201806, 3, 1107, 201806, 3, 1417, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 11:07:00', 'EST-5', '03-JUN-18 14:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'FRONT ROYAL', 2, 'WSW', 'FRONT ROYAL', 38.9138, -78.2103, 38.9107, -78.2104, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the South Fork Shenandoah River near Front Royal exceeded the 12 foot flood stage during the indicated period. The peak level of 16.52 feet occurred at 10:30pm EST on June 3rd. Luray Avenue was flooded along with a riverside parking area and boat ramp, and other overland flooding in the vicinity.');
INSERT INTO public.stormevents_east VALUES (767260, 201806, 3, 1109, 201806, 3, 1258, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 11:09:00', 'EST-5', '03-JUN-18 12:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'HAYFIELD', 1, 'SSE', 'HAYFIELD', 39.2136, -78.2898, 39.2136, -78.2877, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on Hogue Creek near Hayfield exceeded the 8 foot flood stage during the period indicated. The peak level of 8.39 feet was recorded at 11:45am EST on June 3rd. Yards and agricultural fields near the creek flooded during the brief event.');
INSERT INTO public.stormevents_east VALUES (767261, 201806, 3, 753, 201806, 4, 612, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 07:53:00', 'EST-5', '04-JUN-18 06:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'RAPIDAN', 3, 'NW', 'RAPIDAN', 38.3518, -78.1125, 38.342, -78.1076, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on Robinson River near Locust Dale exceeded the 11 foot flood stage during the indicated period. The peak level of 17.93 feet occurred at 4:30pm EST on June 3rd. Multiple spots were flooded along Robinson River Road, and a few private drives were flooded.');
INSERT INTO public.stormevents_east VALUES (762544, 201806, 2, 1545, 201806, 2, 1830, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 15:45:00', 'EST-5', '02-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'WEST END MANOR', 2, 'WSW', 'WEST END MANOR', 37.64, -77.56, 37.6367, -77.5628, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'High water was reported at Pemberton Road and Mayland Drive.');
INSERT INTO public.stormevents_east VALUES (762548, 201806, 2, 1600, 201806, 2, 1830, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 16:00:00', 'EST-5', '02-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'SHORT PUMP', 2, 'NNE', 'SHORT PUMP', 37.68, -77.6, 37.6776, -77.6007, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'High water was reported on roads, as well as 1.5 inches of rain occurring in the past 25 minutes.');
INSERT INTO public.stormevents_east VALUES (762553, 201806, 2, 1600, 201806, 2, 1830, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 16:00:00', 'EST-5', '02-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 5, 'ESE', 'SUBLETTS', 5, 'ESE', 'SUBLETTS', 37.56, -77.69, 37.5587, -77.6909, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'High water was reported near Huguenot Trail and Route 288.');
INSERT INTO public.stormevents_east VALUES (762555, 201806, 2, 1630, 201806, 2, 1830, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 16:30:00', 'EST-5', '02-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'SHORT PUMP', 1, 'ESE', 'SHORT PUMP', 37.65, -77.61, 37.645, -77.6085, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Vehicle was stuck in water on Cox Road in Innsbrook.');
INSERT INTO public.stormevents_east VALUES (762558, 201806, 2, 1650, 201806, 2, 1715, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 16:50:00', 'EST-5', '02-JUN-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'NEW KENT', 2, 'SW', 'NEW KENT', 37.49, -77.01, 37.4941, -77.0092, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Street flooding was reported on Interstate 64 at Exit 220.');
INSERT INTO public.stormevents_east VALUES (762562, 201806, 2, 1655, 201806, 2, 1830, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 16:55:00', 'EST-5', '02-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'SHORT PUMP', 2, 'SSE', 'SHORT PUMP', 37.62, -77.61, 37.6221, -77.6095, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Flooding was reported at Pump Road and Ridgefield Parkway.');
INSERT INTO public.stormevents_east VALUES (762564, 201806, 2, 1805, 201806, 2, 1830, 127220, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 18:05:00', 'EST-5', '02-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'SHORT PUMP', 2, 'NW', 'QUIOCCASIN', 37.62, -77.61, 37.6191, -77.6098, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Water was reported running across the roadway.');
INSERT INTO public.stormevents_east VALUES (762566, 201806, 2, 1724, 201806, 2, 1724, 127220, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '02-JUN-18 17:24:00', 'EST-5', '02-JUN-18 17:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'SSW', 'SHORT PUMP', 2, 'SSW', 'SHORT PUMP', 37.62, -77.64, 37.62, -77.64, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Rainfall total of 4.11 inches was reported in two hours.');
INSERT INTO public.stormevents_east VALUES (762573, 201806, 2, 1937, 201806, 2, 1937, 127220, 'VIRGINIA', 51, 2018, 'June', 'Heavy Rain', 'AKQ', '02-JUN-18 19:37:00', 'EST-5', '02-JUN-18 19:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'WNW', 'WEST END MANOR', 2, 'WNW', 'WEST END MANOR', 37.66, -77.56, 37.66, -77.56, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of central Virginia.', 'Rainfall total of 3.07 inches was reported.  Rainfall amount of 0.53 inch fell in 5 minutes during the peak of the storm.');
INSERT INTO public.stormevents_east VALUES (769311, 201806, 25, 1530, 201806, 25, 1557, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:30:00', 'EST-5', '25-JUN-18 15:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 55, 'EG', NULL, NULL, 4, 'SW', 'TABLE ROCK', 2, 'ESE', 'MORGANTON', 35.787, -81.874, 35.742, -81.667, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Spotter reported numerous trees and power lines blown down in western Burke County. Media reported numerous trees down in the Morganton area, especially along the Catawba River. At least one road was closed in Morganton due to falling trees. Additional sporadic tree damage was also reported outside of this corridor, including at Highway 18 and Antioch Rd near the Caldwell County line.');
INSERT INTO public.stormevents_east VALUES (769320, 201806, 25, 1556, 201806, 25, 1609, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:56:00', 'EST-5', '25-JUN-18 16:09:00', 0, 0, 0, 0, '200.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'N', 'GAMEWELL', 1, 'SSW', 'BATON', 35.882, -81.619, 35.812, -81.533, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Multiple sources reported numerous trees blown down in the Gamewell area. Trees fell on and destroyed one house and severely damaged two others. Roads blocked by downed trees included Miller Hill Rd, Dulatown Rd, and Connelly Springs Rd in Granite Falls.');
INSERT INTO public.stormevents_east VALUES (769322, 201806, 25, 1622, 201806, 25, 1622, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 16:22:00', 'EST-5', '25-JUN-18 16:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'WNW', 'ALL HEALING SPGS', 2, 'WNW', 'ALL HEALING SPGS', 35.94, -81.296, 35.94, -81.296, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Media reported multiple trees blown down on Mountain Ridge Church Road.');
INSERT INTO public.stormevents_east VALUES (769324, 201806, 25, 1634, 201806, 25, 1634, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 16:34:00', 'EST-5', '25-JUN-18 16:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 0, 'ENE', 'LONGVIEW', 0, 'ENE', 'LONGVIEW', 35.732, -81.366, 35.732, -81.366, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Media reported trees blown down along Highway 321.');
INSERT INTO public.stormevents_east VALUES (769332, 201806, 25, 1642, 201806, 25, 1648, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 16:42:00', 'EST-5', '25-JUN-18 16:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 6, 'N', 'CLAREMONT', 3, 'NE', 'CLAREMONT', 35.8, -81.14, 35.755, -81.118, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Broadcast media reported several trees blown down along River Bend Rd. Public also reported (via social media) reported numerous small trees blown down in the Catfish community.');
INSERT INTO public.stormevents_east VALUES (771311, 201806, 28, 1700, 201806, 28, 1700, 128582, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '28-JUN-18 17:00:00', 'EST-5', '28-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 8, 'E', 'BIG PINE KEY', 8, 'E', 'BIG PINE KEY', 24.7045, -81.2486, 24.7045, -81.2486, 'And isolated waterspout and marine thunderstorm wind gusts occurred with scattered showers and thunderstorm developing along a cloud line over the middle Florida Keys.', 'A narrow waterspout was observed about 2 miles north of Ohio Key with a spray ring visible.');
INSERT INTO public.stormevents_east VALUES (771313, 201806, 28, 1713, 201806, 28, 1713, 128582, 'GULF OF MEXICO', 85, 2018, 'June', 'Marine Thunderstorm Wind', 'KEY', '28-JUN-18 17:13:00', 'EST-5', '28-JUN-18 17:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'SSE', 'DUCK KEY', 1, 'SSE', 'DUCK KEY', 24.7706, -80.9073, 24.7706, -80.9073, 'And isolated waterspout and marine thunderstorm wind gusts occurred with scattered showers and thunderstorm developing along a cloud line over the middle Florida Keys.', 'A wind gust of 34 knots was measured at an automated Citizen Weather Observing Program station on Duck Key.');
INSERT INTO public.stormevents_east VALUES (771320, 201806, 30, 1242, 201806, 30, 1247, 128583, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'KEY', '30-JUN-18 12:42:00', 'EST-5', '30-JUN-18 12:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 21, 'WSW', 'SOMBRERO KEY LIGHT', 21, 'WSW', 'SOMBRERO KEY LIGHT', 24.47, -81.4, 24.47, -81.4, 'Waterspouts were associated with an isolated strong rain shower moving toward Looe Key Reef.', 'Three waterspouts were observed two and five miles south of Looe Key Reef.  One of the condensation funnel clouds extended all the way to the water surface.');
INSERT INTO public.stormevents_east VALUES (754535, 201805, 14, 1632, 201805, 14, 1632, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:32:00', 'EST-5', '14-MAY-18 16:32:00', 0, 0, 0, 0, NULL, NULL, 'Public', 2.5, NULL, NULL, NULL, 2, 'WSW', 'CHARLES TOWN', 2, 'WSW', 'CHARLES TOWN', 39.29, -77.888, 39.29, -77.888, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Hail 2.5 inches in diameter was measured off of Middleway Pike.');
INSERT INTO public.stormevents_east VALUES (754536, 201805, 14, 1634, 201805, 14, 1634, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:34:00', 'EST-5', '14-MAY-18 16:34:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 1.75, NULL, NULL, NULL, 2, 'WSW', 'MANNINGS', 2, 'WSW', 'MANNINGS', 39.216, -77.81, 39.216, -77.81, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Golf ball sized hail was reported. Wind blown hail damaged siding and windows.');
INSERT INTO public.stormevents_east VALUES (754537, 201805, 14, 1635, 201805, 14, 1635, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 16:35:00', 'EST-5', '14-MAY-18 16:35:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 1, 'SSW', 'CHARLES TOWN', 1, 'SSW', 'CHARLES TOWN', 39.2851, -77.8575, 39.2851, -77.8575, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (751898, 201806, 13, 1822, 201806, 13, 1822, 125080, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'CTP', '13-JUN-18 18:22:00', 'EST-5', '13-JUN-18 18:22:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WSW', 'LAWRENCEVILLE', 1, 'WSW', 'LAWRENCEVILLE', 41.9966, -77.1292, 41.9966, -77.1292, 'A cold front crossed central Pennsylvania the evening of June 13, 2018, with scattered storms developing in a high-shear, modest CAPE environment. Most of the storms that developed displayed rotation, and wind damage reports were received from a line of storms that crossed Tioga County and a single cell that crossed Cambria County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees near Lawrenceville.');
INSERT INTO public.stormevents_east VALUES (780486, 201808, 7, 1800, 201808, 7, 1800, 130376, 'MASSACHUSETTS', 25, 2018, 'August', 'Thunderstorm Wind', 'BOX', '07-AUG-18 18:00:00', 'EST-5', '07-AUG-18 18:00:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'WNW', 'HUBBARDSTON', 1, 'WNW', 'HUBBARDSTON', 42.4872, -72.0375, 42.4872, -72.0375, 'A cold front moved into New England the evening of August 7th and stalled just north of Massachusetts.  The airmass over the state was very humid and unstable. This generated strong thunderstorms, some causing damage. The front lingered north and west of the state on August 8th, forming thunderstorms and downpours in Massachusetts on that day, especially near Natick.', 'At 6 PM EST, thunderstorm winds brought several trees down in a backyard on Mt. Jefferson Road in Hubbardston.');
INSERT INTO public.stormevents_east VALUES (781729, 201808, 3, 1415, 201808, 3, 1415, 130606, 'VERMONT', 50, 2018, 'August', 'Thunderstorm Wind', 'ALY', '03-AUG-18 14:15:00', 'EST-5', '03-AUG-18 14:15:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'PUTNEY STATION', 0, 'N', 'PUTNEY STATION', 42.97, -72.52, 42.97, -72.52, 'A slow-moving cold front brought several rounds of heavy rainfall and thunderstorms to eastern  New York and western New England. After passing through eastern New York, a severe thunderstorm knocked down trees and caused localized flash flooding in the towns of Putney and West Wardsboro, Vermont.', 'Trees were reported down.');
INSERT INTO public.stormevents_east VALUES (781789, 201808, 8, 1653, 201808, 8, 1653, 130554, 'NORTH CAROLINA', 37, 2018, 'August', 'Thunderstorm Wind', 'RAH', '08-AUG-18 16:53:00', 'EST-5', '08-AUG-18 16:53:00', 0, 0, 0, 0, '0.25K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'RURAL HALL', 1, 'W', 'RURAL HALL', 36.2309, -80.3229, 36.2309, -80.3229, 'A remnant MCV helped to initiate a broken band of thunderstorms that moved east  across central North Carolina during the afternoon and late evening hours. The band of storms organized into a fairly large bowing cluster as it crossed the area, downing numerous trees across Central NC.', 'A power-line was blown down at 3151 Westinghouse Road.');
INSERT INTO public.stormevents_east VALUES (781976, 201808, 30, 1402, 201808, 30, 1402, 130648, 'FLORIDA', 12, 2018, 'August', 'Thunderstorm Wind', 'JAX', '30-AUG-18 14:02:00', 'EST-5', '30-AUG-18 14:02:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 2, 'SE', 'CRAWFORD', 2, 'SE', 'CRAWFORD', 30.48, -81.85, 30.48, -81.85, 'Prevailing SE steering flow focused a stronger east coast sea breeze inland through the day which triggered scattered strong to severe storms over a moist and unstable airmass.', 'A tree was blown down onto a power line which sparked a small fire at 43000 Thomas Creek Road. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (758804, 201805, 21, 1915, 201805, 21, 2200, 126453, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '21-MAY-18 19:15:00', 'EST-5', '21-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'ROUGH RUN', 1, 'ESE', 'ROUGH RUN', 38.9009, -79.1191, 38.8977, -79.1092, 'Another band of heavy rain fell in Grant County on May 21st, with 1-3 inches of rain causing flooding in the southeastern part of the county.', 'Rough Run was reported to be out of its banks flooding nearby roadways.');
INSERT INTO public.stormevents_east VALUES (751899, 201806, 13, 1846, 201806, 13, 1846, 125080, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'CTP', '13-JUN-18 18:46:00', 'EST-5', '13-JUN-18 18:46:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'WNW', 'MAINESBURG', 2, 'WNW', 'MAINESBURG', 41.7942, -77.0338, 41.7942, -77.0338, 'A cold front crossed central Pennsylvania the evening of June 13, 2018, with scattered storms developing in a high-shear, modest CAPE environment. Most of the storms that developed displayed rotation, and wind damage reports were received from a line of storms that crossed Tioga County and a single cell that crossed Cambria County.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto Route 6 east of Mansfield, blocking one lane of traffic.');
INSERT INTO public.stormevents_east VALUES (754904, 201806, 3, 1540, 201806, 3, 1540, 125916, 'TENNESSEE', 47, 2018, 'June', 'Thunderstorm Wind', 'MRX', '03-JUN-18 15:40:00', 'EST-5', '03-JUN-18 15:40:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'PARROTTSVILLE', 1, 'NW', 'PARROTTSVILLE', 36.01, -83.09, 36.01, -83.09, 'A few storms became severe in a strongly unstable environment ahead of a cold front during the afternoon. The storms produced a couple reports of small hail but, the main impact was from a few reports of damaging winds gusts along with some localized flooding.', 'A few trees were reported down in the Parrottsville vicinity.');
INSERT INTO public.stormevents_east VALUES (754907, 201806, 3, 1400, 201806, 3, 1400, 125915, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'MRX', '03-JUN-18 14:00:00', 'EST-5', '03-JUN-18 14:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'PENNINGTON GAP', 1, 'N', 'PENNINGTON GAP', 36.76, -83.03, 36.76, -83.03, 'A few storms became severe in a strongly unstable environment ahead of a cold front during the afternoon. The storms produced a couple reports of small hail but, the main impact was from a few reports of damaging winds gusts along with some localized flooding.', 'Four trees were reported down in the Pennington Gap vicinity.');
INSERT INTO public.stormevents_east VALUES (754908, 201806, 9, 2215, 201806, 9, 2215, 125917, 'TENNESSEE', 47, 2018, 'June', 'Thunderstorm Wind', 'MRX', '09-JUN-18 22:15:00', 'EST-5', '09-JUN-18 22:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NW', 'PARROTTSVILLE', 1, 'NW', 'PARROTTSVILLE', 36.01, -83.09, 36.01, -83.09, 'A thunderstorm became severe in the waning heat and instability in the late evening hours across East Tennessee.', 'A metal building was blown down.');
INSERT INTO public.stormevents_east VALUES (754909, 201806, 10, 1545, 201806, 10, 1545, 125918, 'TENNESSEE', 47, 2018, 'June', 'Thunderstorm Wind', 'MRX', '10-JUN-18 15:45:00', 'EST-5', '10-JUN-18 15:45:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NE', 'STRIGGERSVILLE', 1, 'NE', 'STRIGGERSVILLE', 36.44, -82.97, 36.44, -82.97, 'A thunderstorm became severe in the heat and instability of the afternoon. The storm downed two trees in Northeast Tennessee.', 'Two trees were reported down in Central Hawkins county.');
INSERT INTO public.stormevents_east VALUES (758575, 201805, 16, 2050, 201805, 17, 400, 126423, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 20:50:00', 'EST-5', '17-MAY-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'HARMONY GROVE', 1, 'SE', 'BOLIVAR', 39.4404, -77.3949, 39.462, -77.5915, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Widespread flooding occurred throughout southern Frederick County for the second day in a row.');
INSERT INTO public.stormevents_east VALUES (758579, 201805, 16, 2300, 201805, 17, 500, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 23:00:00', 'EST-5', '17-MAY-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 5, 'SE', 'BERRYVILLE', 4, 'SSE', 'BERRYVILLE', 39.1021, -77.908, 39.0976, -77.9301, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'River Road flooded and closed in multiple locations due to flooding along the Shenandoah River.');
INSERT INTO public.stormevents_east VALUES (758577, 201805, 15, 1940, 201805, 15, 2040, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 19:40:00', 'EST-5', '15-MAY-18 20:40:00', 0, 0, 0, 0, '43.20M', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'FT DETRICK', 0, 'NNW', 'GROVE', 39.4399, -77.3957, 39.4055, -77.3841, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Significant flash flooding occurred during the evening of May 15th from the city of Frederick southwestward toward Braddock Heights and Jefferson. The amount of damage shown here is total damage not already accounted for in other reports.');
INSERT INTO public.stormevents_east VALUES (752527, 201806, 25, 1330, 201806, 25, 1336, 125465, 'KENTUCKY', 21, 2018, 'June', 'Thunderstorm Wind', 'JKL', '25-JUN-18 13:30:00', 'EST-5', '25-JUN-18 13:36:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 51, 'EG', NULL, NULL, 2, 'NNE', 'FRAKES', 1, 'NW', 'DAVISBURG', 36.66, -83.9, 36.69, -83.83, 'After an overnight complex of storms pushed through eastern Kentucky, another system developed during the morning hours in western Kentucky. Clearing skies across southeast Kentucky allowed for destabilization and intensification of this second system as it pushed into eastern Kentucky. These showers and thunderstorms produced scattered wind damage across portions of southeast Kentucky during the early to mid afternoon hours.', 'The Department of Highways reported several trees and large limbs blown down onto |Kentucky Highway 190 from southwest of Chenoa to near Davisburg.');
INSERT INTO public.stormevents_east VALUES (755926, 201806, 25, 37, 201806, 25, 300, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 00:37:00', 'EST-5', '25-JUN-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'CONCORD', 1, 'WSW', 'CONCORD', 42.44, -71.3685, 42.441, -71.3698, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 12:37 AM EST, Sudbury Road near East Bridge in Concord was reported to be flooded with two feet of standing water.');
INSERT INTO public.stormevents_east VALUES (752568, 201806, 17, 1617, 201806, 17, 1617, 125466, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MLB', '17-JUN-18 16:17:00', 'EST-5', '17-JUN-18 16:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SE', 'OCOEE', 2, 'SE', 'OCOEE', 28.55, -81.5, 28.55, -81.5, 'A surface trough was moving south near the east Florida coast while a surface high pressure was situated near the Carolina coastline. The main steering flow winds were out of the north-northwest, although low-level winds were out of the east-southeast. Temperatures aloft were around -7 C to -8 C, and a deep plume of moisture with Precipitable Water values around 1.50 to 1.60 inches was situated over central Florida. The east coast sea breeze was dominant and progressed inland faster than the west coast sea breeze. As the two sea breezes collided in western Orange County, a thunderstorm quickly developed and became severe. This storm produced several reports of wind damage in Windermere and Ocoee in western Orange County.', 'Several reports were received via social media of wind related damage in western Orange County. The first report was of a large Sycamore tree downed by winds near the West Oaks Mall in Ocoee. About five minutes later, reports were received of large trees downed and a wooden fence knocked over in Windermere.');
INSERT INTO public.stormevents_east VALUES (753560, 201806, 9, 1520, 201806, 9, 1521, 125652, 'FLORIDA', 12, 2018, 'June', 'Tornado', 'MLB', '09-JUN-18 15:20:00', 'EST-5', '09-JUN-18 15:21:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'W', 'ARIEL', 0, 'WNW', 'ARIEL', 28.8989, -80.861, 28.9018, -80.8536, 'Afternoon showers and thunderstorms developed in southern Volusia County and northern Brevard County along the collision of the east coast sea breeze with an outflow boundary put out by an earlier group of thunderstorms over Orlando. After the storms developed, they pushed east towards the southeastern Volusia County coastline. One storm managed to produce a very weak, short-lived tornado (landspout) in Oak Hill.', 'NWS Melbourne confirms a very weak, short-lived tornado (landspout) occurred in Oak Hill. Reports of minor roof damage was received from local broadcast media, and a first-hand account from a member of the public who witnessed the tornado. Several reports were received of minor damage to a few homes, and there was a carport damaged on Gary Avenue.');
INSERT INTO public.stormevents_east VALUES (753653, 201806, 24, 1600, 201806, 24, 1600, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 16:00:00', 'EST-5', '24-JUN-18 16:00:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 2, 'S', 'MERRITT', 2, 'S', 'MERRITT', 35.0711, -76.72, 35.0711, -76.72, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'Trees were blown down and quarter inch hail was reported north of Oriental.');
INSERT INTO public.stormevents_east VALUES (753665, 201806, 20, 1809, 201806, 20, 1809, 125664, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '20-JUN-18 18:09:00', 'EST-5', '20-JUN-18 18:09:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 4, 'S', 'WARSAW', 4, 'S', 'WARSAW', 34.9421, -78.08, 34.9421, -78.08, 'Thunderstorms developed across Eastern North Carolina during the evening hours. Several storms became severe and produced damaging winds.', 'Multiple trees were blown down on roadways south of Warsaw, including state routes 1107, 1105, and 1305. The time was estimated based on radar.');
INSERT INTO public.stormevents_east VALUES (753669, 201806, 23, 1352, 201806, 23, 1352, 125666, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '23-JUN-18 13:52:00', 'EST-5', '23-JUN-18 13:52:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 3, 'WNW', 'PACTOLUS', 3, 'WNW', 'PACTOLUS', 35.64, -77.29, 35.64, -77.29, 'An isolated severe thunderstorm developed and produced wind damage.', 'Moderate damage to the roof of a mobile home occurred due to straight line winds. The time was estimated based on radar and was relayed via social media.');
INSERT INTO public.stormevents_east VALUES (754864, 201806, 25, 55, 201806, 25, 530, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 00:55:00', 'EST-5', '25-JUN-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'MEDFORD', 0, 'WSW', 'MEDFORD', 42.4177, -71.1073, 42.4172, -71.106, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 12:55 AM EST, Riverside Avenue at City Hall Mall in Medford was reported flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (754868, 201806, 25, 103, 201806, 25, 600, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 01:03:00', 'EST-5', '25-JUN-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'EAST EVERETT', 1, 'NNE', 'EAST EVERETT', 42.4124, -71.0443, 42.4129, -71.0447, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 1:03 AM EST, the area between the Everett Recreation Center and the Everett Police Department was reported flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (754870, 201806, 25, 130, 201806, 25, 630, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 01:30:00', 'EST-5', '25-JUN-18 06:30:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'WEST EVERETT', 0, 'NNE', 'WEST EVERETT', 42.4224, -71.0689, 42.4225, -71.0685, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 1:30 AM EST, Meridian Street in Malden was reported flooded and impassable with cars trapped in the flood waters.');
INSERT INTO public.stormevents_east VALUES (754872, 201806, 25, 52, 201806, 25, 52, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '25-JUN-18 00:52:00', 'EST-5', '25-JUN-18 00:52:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 43, 'EG', NULL, NULL, 1, 'SSE', 'WEST MEDFORD', 1, 'SW', 'MEDFORD', 42.4185, -71.1269, 42.412, -71.1113, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 12:52 AM EST, a large tree was down on a car and laying across Auburn Street in Medford.  At the same time, a tree was reported down on Summer Street and a large tree was down on George Street.');
INSERT INTO public.stormevents_east VALUES (755927, 201806, 25, 103, 201806, 25, 400, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 01:03:00', 'EST-5', '25-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'BEAVER BROOK', 0, 'WNW', 'BEAVER BROOK', 42.4021, -71.2353, 42.4024, -71.2351, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 1:03 AM EST, a car was trapped in flood waters near the intersection of Lake Street and Lexington Street in Waltham.');
INSERT INTO public.stormevents_east VALUES (755930, 201806, 25, 120, 201806, 25, 430, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 01:20:00', 'EST-5', '25-JUN-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'REVERE', 1, 'SSW', 'REVERE', 42.4086, -71.027, 42.4082, -71.0265, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 1:20 AM EST, five cars were trapped in flood waters on the on the exit ramp from U.S. Route 1 to State Route 16.');
INSERT INTO public.stormevents_east VALUES (790570, 201812, 20, 1048, 201812, 20, 1048, 132119, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '20-DEC-18 10:48:00', 'EST-5', '20-DEC-18 10:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'EG', NULL, NULL, 3, 'WNW', 'SARASOTA BEACH', 3, 'WNW', 'SARASOTA BEACH', 27.34, -82.57, 27.34, -82.57, 'A squall line developed ahead of a strong cold front and pushed southeast through the west coast of the Florida Peninsula, producing widespread thunderstorm wind gusts along the coast.', 'The WeatherFlow station at Sarasota Bay Marker 17 (XSAR) recorded a 43 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (790571, 201812, 20, 1030, 201812, 20, 1030, 132119, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '20-DEC-18 10:30:00', 'EST-5', '20-DEC-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 39, 'MG', NULL, NULL, 27, 'WSW', 'SARASOTA BEACH', 27, 'WSW', 'SARASOTA BEACH', 27.173, -82.924, 27.173, -82.924, 'A squall line developed ahead of a strong cold front and pushed southeast through the west coast of the Florida Peninsula, producing widespread thunderstorm wind gusts along the coast.', 'COMPS buoy C10 (42013) recorded a 39 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (790572, 201812, 20, 1048, 201812, 20, 1048, 132119, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '20-DEC-18 10:48:00', 'EST-5', '20-DEC-18 10:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 48, 'MG', NULL, NULL, 0, 'SW', 'CLEARWATER BEACH', 0, 'SW', 'CLEARWATER BEACH', 27.9777, -82.8321, 27.9777, -82.8321, 'A squall line developed ahead of a strong cold front and pushed southeast through the west coast of the Florida Peninsula, producing widespread thunderstorm wind gusts along the coast.', 'The NOS/CO-OPs station at Clearwater Beach (CWBF1) recorded a 48 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (790573, 201812, 20, 1215, 201812, 20, 1215, 132119, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '20-DEC-18 12:15:00', 'EST-5', '20-DEC-18 12:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'EG', NULL, NULL, 1, 'W', 'PORT CHARLOTTE', 1, 'W', 'PORT CHARLOTTE', 26.99, -82.11, 26.99, -82.11, 'A squall line developed ahead of a strong cold front and pushed southeast through the west coast of the Florida Peninsula, producing widespread thunderstorm wind gusts along the coast.', 'A home weather station in Port Charlotte recorded a 43 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (791708, 201812, 2, 1350, 201812, 2, 1350, 132316, 'GEORGIA', 13, 2018, 'December', 'Flood', 'JAX', '02-DEC-18 13:50:00', 'EST-5', '02-DEC-18 13:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 9, 'NNE', 'PRENTISS', 9, 'NE', 'PINE GROVE', 31.92, -82.36, 31.9211, -82.366, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'Two roads were flooded off of Doyle Road.');
INSERT INTO public.stormevents_east VALUES (791709, 201812, 2, 1523, 201812, 2, 1523, 132316, 'GEORGIA', 13, 2018, 'December', 'Hail', 'JAX', '02-DEC-18 15:23:00', 'EST-5', '02-DEC-18 15:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'SW', 'KINGSLAND', 1, 'SW', 'KINGSLAND', 30.79, -81.69, 30.79, -81.69, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'Quarter size hail was reported in Kingsland.');
INSERT INTO public.stormevents_east VALUES (791710, 201812, 1, 800, 201812, 2, 800, 132316, 'GEORGIA', 13, 2018, 'December', 'Heavy Rain', 'JAX', '01-DEC-18 08:00:00', 'EST-5', '02-DEC-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'S', 'WOODBINE', 1, 'S', 'WOODBINE', 30.96, -81.72, 30.96, -81.72, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'An observer measured 3.48 inches of rainfall over the past 24 hrs.');
INSERT INTO public.stormevents_east VALUES (791711, 201812, 1, 800, 201812, 2, 800, 132316, 'GEORGIA', 13, 2018, 'December', 'Heavy Rain', 'JAX', '01-DEC-18 08:00:00', 'EST-5', '02-DEC-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'E', 'PRIDGEN', 1, 'E', 'PRIDGEN', 31.7, -82.92, 31.7, -82.92, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'An observer in Pridgen measured 3.65 inches in 24 hrs.');
INSERT INTO public.stormevents_east VALUES (791712, 201812, 1, 900, 201812, 2, 900, 132316, 'GEORGIA', 13, 2018, 'December', 'Heavy Rain', 'JAX', '01-DEC-18 09:00:00', 'EST-5', '02-DEC-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 3, 'WNW', 'MANOR', 3, 'WNW', 'MANOR', 31.12, -82.62, 31.12, -82.62, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'An observer near Manor measured 5.12 inches of rainfall in 24 hrs.');
INSERT INTO public.stormevents_east VALUES (765717, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'GORDONSVILLE', 1, 'SSW', 'GORDONSVILLE', 38.1308, -78.1878, 38.1302, -78.1878, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'US 15 flooded and closed in Gordonsville.');
INSERT INTO public.stormevents_east VALUES (765718, 201806, 22, 730, 201806, 22, 900, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SPRINGFIELD', 1, 'SSW', 'SPRINGFIELD', 38.71, -78.4598, 38.7106, -78.4571, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Old Forge Road (Route 658) flooded and closed.');
INSERT INTO public.stormevents_east VALUES (765720, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'JEROME', 0, 'SE', 'JEROME', 38.8615, -78.7173, 38.8666, -78.7157, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Flooding along Stony Creek caused the closures of Dellinger Gap Road and Supinlick Ridge Road.');
INSERT INTO public.stormevents_east VALUES (765721, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'COLUMBIA FURNACE', 1, 'NW', 'COLUMBIA FURNACE', 38.8866, -78.6421, 38.879, -78.6282, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Wolf Gap Road closed near Columbia Furnace due to flooding.');
INSERT INTO public.stormevents_east VALUES (765722, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ST LUKE', 1, 'ESE', 'ST LUKE', 38.8972, -78.5676, 38.8969, -78.5666, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'St. Luke Road flooded and closed near Narrow Passage Creek.');
INSERT INTO public.stormevents_east VALUES (765830, 201806, 22, 315, 201806, 22, 500, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'LWX', '22-JUN-18 03:15:00', 'EST-5', '22-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'GEER', 1, 'SW', 'GEER', 38.2936, -78.5109, 38.2946, -78.51, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Rapid flooding in the 12300 block of Dyke Road near Parker Branch, with high water and a large amount of debris in the roadway.');
INSERT INTO public.stormevents_east VALUES (765832, 201806, 22, 515, 201806, 22, 700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flash Flood', 'LWX', '22-JUN-18 05:15:00', 'EST-5', '22-JUN-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'HAYWOOD', 2, 'ENE', 'HAYWOOD', 38.4575, -78.2355, 38.4576, -78.2316, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Rapid and extreme flooding along Muddy Run east of Haywood, causing the closure of West Hoover Road and Towles Road. 911 operators reported that the flooding was causing problems for deputies and that these areas typically do not flood.');
INSERT INTO public.stormevents_east VALUES (769091, 201806, 24, 340, 201806, 24, 602, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '24-JUN-18 03:40:00', 'EST-5', '24-JUN-18 06:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BRISTOW', 0, 'NNW', 'BRISTOW', 38.7348, -77.5328, 38.7256, -77.5327, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on Broad Run in Bristow exceeded the 9.5 foot flood stage during the indicated period. The peak level of 10.17 feet occurred at 5:02am on June 24th. Piper Lane was flooded during the overnight hours.');
INSERT INTO public.stormevents_east VALUES (769092, 201806, 23, 115, 201806, 23, 750, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 01:15:00', 'EST-5', '23-JUN-18 07:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'WADESVILLE', 2, 'SW', 'WADESVILLE', 39.2235, -78.0619, 39.2252, -78.0576, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on Opequon Creek near Berryville exceeded the 10 foot flood stage during the indicated period. The peak level of 10.23 feet occurred at 6:30am EST on June 23rd. Old Charles Town Road was flooded along the creek.');
INSERT INTO public.stormevents_east VALUES (775073, 201808, 12, 1400, 201808, 12, 1400, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 14:00:00', 'EST-5', '12-AUG-18 14:00:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 70, 'EG', NULL, NULL, 1, 'N', 'STEVENSBURG', 1, 'N', 'STEVENSBURG', 38.47, -77.88, 38.47, -77.88, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'Approximately 40 to 50 trees were blown down, some onto houses and farm buildings, just east of Culpeper. This included numerous 75 to 100 foot tall trees up to 3 feet in diameter that were uprooted and snapped in the vicinity of Carrico Mills Road.');
INSERT INTO public.stormevents_east VALUES (775126, 201808, 17, 1446, 201808, 17, 1446, 129357, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '17-AUG-18 14:46:00', 'EST-5', '17-AUG-18 14:46:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SSW', 'WHITE POST', 1, 'SSW', 'WHITE POST', 39.03, -78.11, 39.03, -78.11, 'A cold front interacted with a moist and unstable air mass to produce thunderstorms across the region. Some of these storms became severe.', 'A tree was blown down blocking Sugar Hill Road near White Post. A tree was also blown down near the intersection of Berry''s Ferry Road and White Post Road.');
INSERT INTO public.stormevents_east VALUES (791811, 201812, 20, 830, 201812, 21, 830, 132335, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '20-DEC-18 08:30:00', 'EST-5', '21-DEC-18 08:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'N', 'INDIAN TRAILS', 1, 'N', 'INDIAN TRAILS', 29.6, -81.25, 29.6, -81.25, 'A deepening area of low pressure across SE Georgia tracked NE of the region with a trailing cold front edging across the local area. Strong wind gusts in showers and outside of showers produced isolated wind damage with localized heavy rainfall.', 'The public measured 2.9 inches of rainfall over the past 24 hrs near exit 293 off fhore I-95 in Palm Coast.');
INSERT INTO public.stormevents_east VALUES (791812, 201812, 2, 1848, 201812, 2, 1849, 132316, 'GEORGIA', 13, 2018, 'December', 'Tornado', 'JAX', '02-DEC-18 18:48:00', 'EST-5', '02-DEC-18 18:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', NULL, NULL, NULL, NULL, 19, 'S', 'HOPKINS', 19, 'S', 'HOPKINS', 30.6911, -82.3895, 30.7062, -82.3739, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'NWS JAX Science and Operations officer identified weak tornado based on radar imagery including debris ball signature over the Okenfenokee Swamp.');
INSERT INTO public.stormevents_east VALUES (777950, 201808, 9, 1524, 201808, 9, 1534, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '09-AUG-18 15:24:00', 'EST-5', '09-AUG-18 15:34:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'W', 'MOORES', 1, 'W', 'MOORES', 32.5211, -82.9887, 32.5211, -82.9887, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Laurens County Emergency Manager reported a tree blown down on Moore Station Road near Old Valambrosia Road.');
INSERT INTO public.stormevents_east VALUES (755262, 201806, 17, 1835, 201806, 17, 1935, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Flash Flood', 'RLX', '17-JUN-18 18:35:00', 'EST-5', '17-JUN-18 19:35:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'INSTITUTE', 0, 'SE', 'BUNKER HILL', 38.38, -81.78, 38.3686, -81.728, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'Several roads were closed due to high water. This included Vine Street in Saint Albans, where one to two feet of water flowed across the road. Washington Avenue was also closed. High water collected along McCorkle Avenue in multiple spots, including in Jefferson and near Thomas Memorial Hospital in South Charleston.');
INSERT INTO public.stormevents_east VALUES (755265, 201806, 17, 1800, 201806, 17, 1800, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 18:00:00', 'EST-5', '17-JUN-18 18:00:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'SCOTT DEPOT', 1, 'S', 'SCOTT DEPOT', 38.44, -81.92, 38.44, -81.92, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'Trees and a power line were blown down along Scott Depot Road.');
INSERT INTO public.stormevents_east VALUES (755266, 201806, 17, 1810, 201806, 17, 1810, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 18:10:00', 'EST-5', '17-JUN-18 18:10:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'ST ALBANS', 1, 'NW', 'ST ALBANS', 38.39, -81.84, 38.39, -81.84, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'Several trees were blown down in Saint Albans.');
INSERT INTO public.stormevents_east VALUES (755268, 201806, 17, 1819, 201806, 17, 1819, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 18:19:00', 'EST-5', '17-JUN-18 18:19:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'INSTITUTE', 1, 'SE', 'INSTITUTE', 38.37, -81.76, 38.37, -81.76, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'A large tree was downed in Institute along Carver Street.');
INSERT INTO public.stormevents_east VALUES (755269, 201806, 17, 1820, 201806, 17, 1820, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 18:20:00', 'EST-5', '17-JUN-18 18:20:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'BUNKER HILL', 1, 'W', 'BUNKER HILL', 38.37, -81.74, 38.37, -81.74, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'Multiple trees were blown down around Dunbar.');
INSERT INTO public.stormevents_east VALUES (755271, 201806, 17, 1830, 201806, 17, 1830, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 18:30:00', 'EST-5', '17-JUN-18 18:30:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SPRING HILL', 1, 'E', 'SPRING HILL', 38.35, -81.72, 38.35, -81.72, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'Jones Street was closed by a fallen tree.');
INSERT INTO public.stormevents_east VALUES (755272, 201806, 17, 1840, 201806, 17, 1840, 125986, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '17-JUN-18 18:40:00', 'EST-5', '17-JUN-18 18:40:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'SOUTH RUFFNER', 0, 'N', 'SOUTH RUFFNER', 38.33, -81.62, 38.33, -81.62, 'In an unstable atmosphere, showers and thunderstorms developed during the heat of the afternoon on the 17th. One of these storms was strong enough to produce hail and wind damage, along with flooding rain.', 'A tree fell onto Loudon Heights Road, closing one lane.');
INSERT INTO public.stormevents_east VALUES (751746, 201806, 18, 1642, 201806, 18, 1642, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 16:42:00', 'EST-5', '18-JUN-18 16:42:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'SE', 'BURKVILLE', 0, 'SE', 'BURKVILLE', 42.5191, -72.6984, 42.5191, -72.6984, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:42 PM EST, a tree and wires were down on Shelburne Falls Road in Conway.');
INSERT INTO public.stormevents_east VALUES (751748, 201806, 18, 1646, 201806, 18, 1646, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 16:46:00', 'EST-5', '18-JUN-18 16:46:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'WNW', 'WHATELY STATION', 1, 'WNW', 'WHATELY STATION', 42.4519, -72.6397, 42.4519, -72.6397, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:46 PM EST, two trees and wires were down on North Street in Whately.');
INSERT INTO public.stormevents_east VALUES (751752, 201806, 18, 1615, 201806, 18, 1615, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 16:15:00', 'EST-5', '18-JUN-18 16:15:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'N', 'LEYDEN', 0, 'N', 'LEYDEN', 42.7, -72.62, 42.7, -72.62, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:15 PM EST, trees were reported down on wires on Kately Road, Mid County Road and Greenfield Road in Leyden.');
INSERT INTO public.stormevents_east VALUES (751758, 201806, 16, 1650, 201806, 18, 1655, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Funnel Cloud', 'BOX', '16-JUN-18 16:50:00', 'EST-5', '18-JUN-18 16:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 1, 'NNE', 'GRANBY', 1, 'NNE', 'GRANBY', 42.2569, -72.5167, 42.2569, -72.5167, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 4:52 PM EST, a funnel cloud was sighted at Granby.  Multiple videos later confirmed rotation in the funnel cloud.');
INSERT INTO public.stormevents_east VALUES (751762, 201806, 18, 1910, 201806, 18, 1910, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Lightning', 'BOX', '18-JUN-18 19:10:00', 'EST-5', '18-JUN-18 19:10:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Amateur Radio', NULL, NULL, NULL, NULL, 0, 'NNE', 'GILLETT CORNER', 0, 'NNE', 'GILLETT CORNER', 42.0202, -72.7799, 42.0202, -72.7799, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 7:10 PM EST, lightning caused a structure fire at 58 Congamond Road in Southwick.  The fire started in the attic and then spread.  Two residents were able to escape without injury.');
INSERT INTO public.stormevents_east VALUES (751766, 201806, 18, 1733, 201806, 18, 1733, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:33:00', 'EST-5', '18-JUN-18 17:33:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'WSW', 'WHALOM', 1, 'WSW', 'WHALOM', 42.5143, -71.7703, 42.5143, -71.7703, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:33 PM EST, a tree was down across Pleasant Street in Leominster.');
INSERT INTO public.stormevents_east VALUES (765493, 201806, 18, 1829, 201806, 18, 1829, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:29:00', 'EST-5', '18-JUN-18 18:29:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Newspaper', 50, 'EG', NULL, NULL, 1, 'W', 'JAMESTOWN', 1, 'W', 'JAMESTOWN', 42.1, -79.24, 42.1, -79.24, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'A tree fell on a house on Willard Street.');
INSERT INTO public.stormevents_east VALUES (765495, 201806, 18, 1840, 201806, 18, 1840, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:40:00', 'EST-5', '18-JUN-18 18:40:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'CONEWANGO', 1, 'N', 'CONEWANGO', 42.24, -79.03, 42.24, -79.03, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Tree down in Conewango.');
INSERT INTO public.stormevents_east VALUES (765496, 201806, 18, 1851, 201806, 18, 1851, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 18:51:00', 'EST-5', '18-JUN-18 18:51:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'STEAMBURG', 1, 'N', 'STEAMBURG', 42.11, -78.9, 42.11, -78.9, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Tree limbs and wires down in Steamburg.');
INSERT INTO public.stormevents_east VALUES (765497, 201806, 18, 1920, 201806, 18, 1920, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 19:20:00', 'EST-5', '18-JUN-18 19:20:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'PORTVILLE', 1, 'NW', 'PORTVILLE', 42.04, -78.34, 42.04, -78.34, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Tree down on wires in Portville.');
INSERT INTO public.stormevents_east VALUES (765499, 201806, 18, 1941, 201806, 18, 1941, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 19:41:00', 'EST-5', '18-JUN-18 19:41:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NE', 'SOUTH BOLIVAR', 1, 'NE', 'SOUTH BOLIVAR', 42.01, -78.1, 42.01, -78.1, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Tree fell across route 18.');
INSERT INTO public.stormevents_east VALUES (765500, 201806, 18, 1946, 201806, 18, 1946, 127656, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '18-JUN-18 19:46:00', 'EST-5', '18-JUN-18 19:46:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'WELLSVILLE', 0, 'N', 'WELLSVILLE', 42.12, -77.95, 42.12, -77.95, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', 'Tree down in Wellsville.');
INSERT INTO public.stormevents_east VALUES (762809, 201806, 24, 2105, 201806, 24, 2110, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:05:00', 'EST-5', '24-JUN-18 21:10:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 0, 'WNW', 'JACKSONVILLE', 0, 'WNW', 'JACKSONVILLE', 33.5018, -81.8555, 33.5018, -81.8555, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees in roadway at Daley Dr and Ivan St in Burnettown.');
INSERT INTO public.stormevents_east VALUES (762810, 201806, 24, 2106, 201806, 24, 2110, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:06:00', 'EST-5', '24-JUN-18 21:10:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 60, 'EG', NULL, NULL, 1, 'NW', 'JACKSONVILLE', 1, 'NW', 'JACKSONVILLE', 33.5068, -81.8566, 33.5068, -81.8566, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down on Dummy Line Rd in Burnettown.');
