INSERT INTO public.stormevents_east VALUES (762814, 201806, 24, 2122, 201806, 24, 2125, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:22:00', 'EST-5', '24-JUN-18 21:25:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'NE', 'CORDOVA', 2, 'NE', 'CORDOVA', 33.4551, -80.907, 33.4551, -80.907, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'SCHP reported trees down at the intersection of Cordova Rd and Mixon Mill Rd.');
INSERT INTO public.stormevents_east VALUES (762815, 201806, 24, 2158, 201806, 24, 2200, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:58:00', 'EST-5', '24-JUN-18 22:00:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'SE', 'KITCHINGS MILL', 1, 'SE', 'KITCHINGS MILL', 33.5728, -81.4681, 33.5728, -81.4681, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees in roadway at SC 4 (Surrey Race Rd) and SC 394 (Salley Rd).');
INSERT INTO public.stormevents_east VALUES (762816, 201806, 24, 2200, 201806, 24, 2205, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 22:00:00', 'EST-5', '24-JUN-18 22:05:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 1, 'W', 'NORWAY', 1, 'W', 'NORWAY', 33.45, -81.15, 33.45, -81.15, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Public reported pecan trees down and metal siding ripped from a home.');
INSERT INTO public.stormevents_east VALUES (779308, 201808, 22, 13, 201808, 22, 213, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '22-AUG-18 00:13:00', 'EST-5', '22-AUG-18 02:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'GLEN', 0, 'SSE', 'GLEN', 39.0459, -77.2179, 39.0462, -77.2176, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'A vehicle was trapped in high water in the 12200 Block of South Glen Road.');
INSERT INTO public.stormevents_east VALUES (781081, 201808, 31, 1222, 201808, 31, 1422, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 12:22:00', 'EST-5', '31-AUG-18 14:22:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'SAVAGE', 2, 'NNE', 'SAVAGE', 39.1494, -76.8167, 39.1499, -76.8169, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Guilford Road was closed at Mary Lane due to high water.');
INSERT INTO public.stormevents_east VALUES (781083, 201808, 31, 1639, 201808, 31, 1839, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 16:39:00', 'EST-5', '31-AUG-18 18:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'SCARBORO', 1, 'WSW', 'POOLE', 39.6272, -76.2877, 39.6253, -76.2647, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Conowingo Road was closed due to flooding near Trappe Road and Route 136 was closed due to flooding between Route 440 and Deerfield Road.');
INSERT INTO public.stormevents_east VALUES (781084, 201808, 31, 1724, 201808, 31, 1924, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 17:24:00', 'EST-5', '31-AUG-18 19:24:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'WHITEFORD', 2, 'NE', 'MILL GREEN', 39.7089, -76.3458, 39.6933, -76.3018, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Multiple roads were closed due to water rescues and flooding.');
INSERT INTO public.stormevents_east VALUES (781085, 201808, 31, 1730, 201808, 31, 1930, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 17:30:00', 'EST-5', '31-AUG-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'DUBLIN', 1, 'NNW', 'POOLE', 39.639, -76.2617, 39.6409, -76.2573, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Arena Road was closed due to flooding on the 1500 Block. People were rescued from a house.');
INSERT INTO public.stormevents_east VALUES (781086, 201808, 31, 1740, 201808, 31, 1940, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 17:40:00', 'EST-5', '31-AUG-18 19:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'BERKLEY', 2, 'W', 'BERKLEY', 39.6694, -76.2317, 39.6679, -76.2285, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Love Road bridge collapsed over Peddler Run Creek due to flooding. Love Road was closed due to flooding near Franklin Church Road. A vehicle was trapped in high water.');
INSERT INTO public.stormevents_east VALUES (781088, 201808, 31, 1804, 201808, 31, 2004, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 18:04:00', 'EST-5', '31-AUG-18 20:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BERKLEY', 1, 'WNW', 'BERKLEY', 39.6754, -76.2166, 39.6737, -76.2157, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Casgleton Road was closed due to flooding near Glen Cove Road.');
INSERT INTO public.stormevents_east VALUES (769071, 201806, 11, 1608, 201806, 11, 1608, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'RAH', '11-JUN-18 16:08:00', 'EST-5', '11-JUN-18 16:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 5, 'S', 'DUNN', 5, 'S', 'DUNN', 35.25, -78.63, 35.25, -78.63, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Quarter-sized hail was reported on Interstate 95 at Exit 70.');
INSERT INTO public.stormevents_east VALUES (769072, 201806, 11, 1608, 201806, 11, 1608, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'RAH', '11-JUN-18 16:08:00', 'EST-5', '11-JUN-18 16:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 2, 'SSE', 'DUNN', 2, 'SSE', 'DUNN', 35.29, -78.6, 35.29, -78.6, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Quarter-sized hail reported on Interstate 95 at exit 72.');
INSERT INTO public.stormevents_east VALUES (769073, 201806, 11, 1601, 201806, 11, 1601, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '11-JUN-18 16:01:00', 'EST-5', '11-JUN-18 16:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'E', 'BENSON', 0, 'E', 'BENSON', 35.3795, -78.5424, 35.3795, -78.5424, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Thunderstorm winds downed a tree along East Church Street.');
INSERT INTO public.stormevents_east VALUES (769074, 201806, 11, 1606, 201806, 11, 1606, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '11-JUN-18 16:06:00', 'EST-5', '11-JUN-18 16:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'KIPLING', 1, 'W', 'KIPLING', 35.4798, -78.8322, 35.4798, -78.8322, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Several trees were blown down along a 150 foot section of roadway on Olive Branch Road near Kipling Road.');
INSERT INTO public.stormevents_east VALUES (769075, 201806, 11, 1610, 201806, 11, 1610, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '11-JUN-18 16:10:00', 'EST-5', '11-JUN-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WNW', 'SPIVEYS CORNER', 3, 'WNW', 'SPIVEYS CORNER', 35.27, -78.57, 35.27, -78.57, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Thunderstorm winds downed one tree near the community of Dunn.');
INSERT INTO public.stormevents_east VALUES (769076, 201806, 11, 1627, 201806, 11, 1627, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '11-JUN-18 16:27:00', 'EST-5', '11-JUN-18 16:27:00', 0, 0, 0, 0, '0.00K', '1.50K', 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'W', 'LEWISVILLE', 4, 'W', 'LEWISVILLE', 36.1, -80.5, 36.1, -80.5, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Thunderstorm winds downed several trees along Route 421, just east of the Yadkin County border.');
INSERT INTO public.stormevents_east VALUES (776183, 201807, 21, 2130, 201807, 21, 2300, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:30:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'LEESBURG', 2, 'ESE', 'LEESBURG', 39.1141, -77.5211, 39.1141, -77.5204, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Edwards Ferry Road flooded and closed east of Leesburg.');
INSERT INTO public.stormevents_east VALUES (776185, 201807, 21, 2035, 201807, 21, 2200, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 20:35:00', 'EST-5', '21-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'CARDEROCK SPGS', 1, 'NNE', 'CARDEROCK SPGS', 39.0099, -77.1674, 39.0096, -77.1673, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Water rescue during torrential rainfall on Bradley Boulevard near Kentsdale Drive.');
INSERT INTO public.stormevents_east VALUES (781495, 201807, 23, 322, 201807, 23, 1414, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '23-JUL-18 03:22:00', 'EST-5', '23-JUL-18 14:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RAYNOR HGTS', 1, 'W', 'RAYNOR HGTS', 39.2118, -76.7027, 39.2207, -76.6935, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'The stream gage on the Patapsco River near Elkridge exceeded the 16 foot flood stage during the indicated period. The peak level of 17.36 feet occurred at 6:05am EST. Hammonds Ferry Road and Furnace Avenue were flooded.');
INSERT INTO public.stormevents_east VALUES (781507, 201807, 22, 355, 201807, 22, 659, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 03:55:00', 'EST-5', '22-JUL-18 06:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'UNITY', 1, 'NW', 'UNITY', 39.2379, -77.0562, 39.2375, -77.0565, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'The USGS stream gage on the Patuxent River near Unity exceeded the 8 foot flood stage during the indicated period. The peak level of 8.61 feet occurred at 6:00am EST. The parking lot for the Patuxent River State Park near Route 97 flooded.');
INSERT INTO public.stormevents_east VALUES (781509, 201807, 25, 1824, 201807, 25, 1947, 128279, 'DISTRICT OF COLUMBIA', 11, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 18:24:00', 'EST-5', '25-JUL-18 19:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'WALTER REED', 1, 'SW', 'WALTER REED', 38.9765, -77.041, 38.9675, -77.0474, 'Locally heavy rain fell in Washington DC on the afternoon of July 25th. This caused flash flooding at rush hour in the metro area.', 'The USGS stream gage on Rock Creek at Sherrill Drive rapidly exceeded the 7 foot flood stage due to torrential rain, flooding the Valley Trail and other portions of Rock Creek Park. The peak level of 7.99 feet was observed at 6:45pm EST.');
INSERT INTO public.stormevents_east VALUES (758134, 201806, 24, 1810, 201806, 24, 1810, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 18:10:00', 'EST-5', '24-JUN-18 18:10:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'ORIOLE PARK AT CAMDEN YARDS (BLTPC)', 0, 'N', 'ORIOLE PARK AT CAMDEN YARDS (BLTPC)', 39.28, -76.62, 39.28, -76.62, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'A wind gust in excess of 30 knots was reported at Oriole Park.');
INSERT INTO public.stormevents_east VALUES (758135, 201806, 24, 1812, 201806, 24, 1818, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 18:12:00', 'EST-5', '24-JUN-18 18:18:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'BALTIMORE (BLTM2)', 0, 'N', 'BALTIMORE (BLTM2)', 39.27, -76.58, 39.27, -76.58, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'Wind gusts up to 34 knots were reported.');
INSERT INTO public.stormevents_east VALUES (758136, 201806, 24, 1818, 201806, 24, 1830, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 18:18:00', 'EST-5', '24-JUN-18 18:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'Wind gusts up to 34 knots were reported at Key Bridge.');
INSERT INTO public.stormevents_east VALUES (758139, 201806, 24, 1832, 201806, 24, 1842, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 18:32:00', 'EST-5', '24-JUN-18 18:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'HART MILLER ISLAND (HRT)', 0, 'N', 'HART MILLER ISLAND (HRT)', 39.25, -76.37, 39.25, -76.37, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'Wind gusts of 35 to 37 knots were reported at Hartmiller Island.');
INSERT INTO public.stormevents_east VALUES (758140, 201806, 24, 1848, 201806, 24, 1848, 126482, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '24-JUN-18 18:48:00', 'EST-5', '24-JUN-18 18:48:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'A cold front passed through the area on the 24th and it was accompanied by a potent upper-level trough. The upper-level trough caused stronger winds aloft, and storms that developed were able to drag these stronger winds down to the surface.', 'A wind gust in excess of 30 knots was reported at Tolchester Beach.');
INSERT INTO public.stormevents_east VALUES (763482, 201806, 1, 2115, 201806, 1, 2315, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:15:00', 'EST-5', '01-JUN-18 23:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'REELS MILL', 1, 'S', 'REELS MILL', 39.3498, -77.3769, 39.3499, -77.3764, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'Water covering a portion of the 4100 block of Urbana Pike.');
INSERT INTO public.stormevents_east VALUES (763483, 201806, 1, 2215, 201806, 2, 15, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 22:15:00', 'EST-5', '02-JUN-18 00:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BAKERSVILLE', 1, 'S', 'BAKERSVILLE', 39.512, -77.7473, 39.5088, -77.748, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'A portion of Maryland Route 65 was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (767263, 201806, 3, 1209, 201806, 5, 1808, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 12:09:00', 'EST-5', '05-JUN-18 18:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'S', 'MILLWOOD', 5, 'SE', 'BERRYVILLE', 39.0172, -78.0285, 39.1034, -77.9035, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Shenandoah River at Millville, WV exceeded the 10 foot flood stage during the indicated period, and rose to a significant height of 17.52 feet, the highest observed since 1996. Several roads near the river in Clarke County were significantly flooded.');
INSERT INTO public.stormevents_east VALUES (767266, 201806, 3, 816, 201806, 3, 2018, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 08:16:00', 'EST-5', '03-JUN-18 20:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'MT JACKSON', 1, 'SE', 'MT JACKSON', 38.7433, -78.6406, 38.7431, -78.6375, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the North Fork Shenandoah River at Mount Jackson exceeded the 13 foot flood stage during the period indicated. The peak level of 14.20 feet occurred at 1:30pm EST on June 3rd. Several roads experienced flooding in the area.');
INSERT INTO public.stormevents_east VALUES (767267, 201806, 3, 319, 201806, 4, 339, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 03:19:00', 'EST-5', '04-JUN-18 03:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSE', 'SOUTH JACKSON', 3, 'ENE', 'NEW MARKET', 38.6949, -78.6309, 38.666, -78.6254, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on Smith Creek near New Market exceeded the 8 foot flood stage during the indicated period. The peak level of 11.55 feet occurred at 1:00pm EST on June 3rd. Agricultural flooding was widespread, along with several road closures, including Route 826.');
INSERT INTO public.stormevents_east VALUES (767269, 201806, 3, 1726, 201806, 4, 2108, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 17:26:00', 'EST-5', '04-JUN-18 21:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'REMINGTON', 1, 'WSW', 'REMINGTON', 38.5357, -77.8032, 38.5272, -77.814, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Rappahannock River near Remington exceeded the 15 foot flood stage during the indicated period. The peak level of 18.32 feet occurred at 8:30am EST on June 4th. Backwater flooding occurred on Tin Pot Run, along with flooding in the Kellys Ford area.');
INSERT INTO public.stormevents_east VALUES (767270, 201806, 3, 952, 201806, 4, 441, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 09:52:00', 'EST-5', '04-JUN-18 04:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'LAKOTA', 1, 'S', 'MONUMENT MILLS', 38.5767, -77.9168, 38.5888, -78, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Hazel River at Rixeyville exceeded the 16 foot flood stage during the indicated period. The peak level of 19.78 feet occurred at 6:30pm EST on June 3rd. Ryland Chapel Road and Butler Store Road were both flooded.');
INSERT INTO public.stormevents_east VALUES (767363, 201806, 9, 1225, 201806, 9, 1815, 127934, 'MARYLAND', 24, 2018, 'June', 'Flash Flood', 'AKQ', '09-JUN-18 12:25:00', 'EST-5', '09-JUN-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'MARYLAND BEACH', 3, 'ESE', 'SHOWELL', 38.4064, -75.0577, 38.389, -75.1761, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of the Lower Maryland Eastern Shore.', 'Numerous roads were flooded with one to two feet of water on them. Cars were stalled out upon driving through the water.');
INSERT INTO public.stormevents_east VALUES (767396, 201806, 9, 1350, 201806, 9, 1350, 127934, 'MARYLAND', 24, 2018, 'June', 'Heavy Rain', 'AKQ', '09-JUN-18 13:50:00', 'EST-5', '09-JUN-18 13:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'WSW', 'MARYLAND BEACH', 1, 'WSW', 'MARYLAND BEACH', 38.44, -75.07, 38.44, -75.07, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flash flooding across portions of the Lower Maryland Eastern Shore.', 'Rainfall total of 6.20 inches was measured within 3 hours.');
INSERT INTO public.stormevents_east VALUES (767403, 201806, 9, 2245, 201806, 10, 430, 127939, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '09-JUN-18 22:45:00', 'EST-5', '10-JUN-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'TAPPAHANNOCK', 1, 'WNW', 'TAPPAHANNOCK ARPT', 37.93, -76.87, 37.9239, -76.8866, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flooding across portions of the Virginia Northern Neck.', 'Several roads were flooded.');
INSERT INTO public.stormevents_east VALUES (767404, 201806, 9, 2245, 201806, 10, 430, 127939, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'AKQ', '09-JUN-18 22:45:00', 'EST-5', '10-JUN-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'FARNHAM', 1, 'NNW', 'EMMERTON', 37.8653, -76.62, 37.9103, -76.6887, 'Scattered showers and thunderstorms along a frontal boundary produced heavy rain which caused flooding across portions of the Virginia Northern Neck.', 'Several roads were flooded.');
INSERT INTO public.stormevents_east VALUES (768035, 201806, 10, 1230, 201806, 10, 1230, 128062, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '10-JUN-18 12:30:00', 'EST-5', '10-JUN-18 12:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'FORD', 1, 'E', 'FORD', 37.15, -77.73, 37.15, -77.73, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Numerous trees were snapped in a field near Ford.');
INSERT INTO public.stormevents_east VALUES (768036, 201806, 10, 1621, 201806, 10, 1621, 128062, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '10-JUN-18 16:21:00', 'EST-5', '10-JUN-18 16:21:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'S', 'STAGE JCT', 1, 'S', 'STAGE JCT', 37.76, -78.17, 37.76, -78.17, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Trees were downed near Columbia.');
INSERT INTO public.stormevents_east VALUES (768037, 201806, 10, 1700, 201806, 10, 1700, 128062, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '10-JUN-18 17:00:00', 'EST-5', '10-JUN-18 17:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'INEZ', 0, 'N', 'INEZ', 37.8, -77.82, 37.8, -77.82, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Trees were downed across eastern portions of the county.');
INSERT INTO public.stormevents_east VALUES (768038, 201806, 10, 1740, 201806, 10, 1740, 128062, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '10-JUN-18 17:40:00', 'EST-5', '10-JUN-18 17:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'E', 'FLAT ROCK', 1, 'E', 'FLAT ROCK', 37.52, -77.81, 37.52, -77.81, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Trees were downed near Flat Rock.');
INSERT INTO public.stormevents_east VALUES (768039, 201806, 10, 2030, 201806, 10, 2100, 128062, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '10-JUN-18 20:30:00', 'EST-5', '10-JUN-18 21:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'CHASE CITY', 0, 'N', 'CHASE CITY', 36.8, -78.45, 36.8, -78.45, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds across portions of central and south central Virginia.', 'Numerous trees were downed on Route 92 and Route 47.');
INSERT INTO public.stormevents_east VALUES (769333, 201806, 25, 1720, 201806, 25, 1720, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 17:20:00', 'EST-5', '25-JUN-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'MOORESVILLE', 1, 'E', 'MOORESVILLE', 35.58, -80.81, 35.58, -80.81, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms reported a couple of trees blown down on East Center Avenue.');
INSERT INTO public.stormevents_east VALUES (769335, 201806, 25, 1802, 201806, 25, 1823, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 18:02:00', 'EST-5', '25-JUN-18 18:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'SSE', 'CRAVEN', 5, 'S', 'POOLETOWN', 35.611, -80.341, 35.509, -80.225, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Spotter reported multiple trees blown down across roads in southeast Rowan County, including Poole Rd, St Matthews Church Rd, and Stokes Ferry Rd at River Rd.');
INSERT INTO public.stormevents_east VALUES (769336, 201806, 25, 1824, 201806, 25, 1824, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 18:24:00', 'EST-5', '25-JUN-18 18:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'S', 'MATTHEWS', 4, 'S', 'MATTHEWS', 35.07, -80.74, 35.07, -80.74, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'Public reported multiple large tree limbs blown down.');
INSERT INTO public.stormevents_east VALUES (769339, 201806, 25, 1553, 201806, 25, 1626, 128218, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '25-JUN-18 15:53:00', 'EST-5', '25-JUN-18 16:26:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 4, 'NNW', 'LAKE TOXAWAY', 2, 'ESE', 'CEDAR MTN', 35.181, -82.965, 35.143, -82.613, 'For the third day in a row, multiple thunderstorm clusters, some producing damaging winds moved from East Tennessee into western North Carolina during the afternoon into the evening. While severe weather was confined to the mountains on the 23rd and 24th, storms on the 25th also produced severe weather in the foothills and northwest Piedmont.', 'County comms reported numerous trees and power lines blown down throughout the county.');
INSERT INTO public.stormevents_east VALUES (769341, 201806, 26, 1420, 201806, 26, 1420, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 14:20:00', 'EST-5', '26-JUN-18 14:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'SALEM', 1, 'SW', 'SALEM', 34.87, -82.98, 34.87, -82.98, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'County comms reported numerous trees blown down in the Salem area.');
INSERT INTO public.stormevents_east VALUES (769342, 201806, 26, 1400, 201806, 26, 1437, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 14:00:00', 'EST-5', '26-JUN-18 14:37:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'S', 'PUMPKINTOWN', 1, 'SE', 'LATHAM', 34.999, -82.65, 34.808, -82.54, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'County comms reported numerous trees and power lines blown down across northern and eastern sections of Pickens County.');
INSERT INTO public.stormevents_east VALUES (754538, 201805, 14, 1530, 201805, 14, 1530, 125706, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 15:30:00', 'EST-5', '14-MAY-18 15:30:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'HAMPSHIRE CLUB', 1, 'ENE', 'HAMPSHIRE CLUB', 39.3058, -78.8016, 39.3058, -78.8016, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Trees and wires were down near S. Branch River Road and Hampshire Park Drive.');
INSERT INTO public.stormevents_east VALUES (782200, 201808, 7, 645, 201808, 7, 645, 130715, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'CAR', '07-AUG-18 06:45:00', 'EST-5', '07-AUG-18 06:45:00', 0, 0, 0, 0, NULL, NULL, 'Public', 61, 'EG', NULL, NULL, 3, 'NNE', 'NEW SWEDEN', 3, 'NNE', 'NEW SWEDEN', 46.99, -68.1, 46.99, -68.1, 'A cold front crossed the region during the afternoon and evening of the 7th producing severe thunderstorms across central and Downeast portions of the region. A disturbance in advance of the front produced a severe thunderstorm which crossed northern Aroostook county during the morning. The thunderstorms produced damaging winds.', 'Trees were toppled and snapped...with a power pole also toppled...along Rista Road by wind gusts estimated at up to 70 mph.');
INSERT INTO public.stormevents_east VALUES (782236, 201808, 14, 1600, 201808, 14, 1700, 130615, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BUF', '14-AUG-18 16:00:00', 'EST-5', '14-AUG-18 17:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'PULASKI', 1, 'S', 'PULASKI', 43.566, -76.1424, 43.5626, -76.1313, 'A mid level closed low, more typical of the cold season, passed slowly through PA and into eastern NY. Abundant moisture in the presence of this anomalous forcing produced heavy rain and flash flooding. The main corridors of heavy rain developed along fairly subtle deformation zones and subtle low level convergence zones in Oswego, Wayne, and Ontario counties, reaching eastern Monroe County by mid-morning.', 'Five village roads flooded with six to eight inches of water across them. Water was reported up to the doors of many businesses.');
INSERT INTO public.stormevents_east VALUES (782353, 201808, 13, 2054, 201808, 13, 2054, 130740, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'AKQ', '13-AUG-18 20:54:00', 'EST-5', '13-AUG-18 20:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 43, 'MG', NULL, NULL, 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 0, 'N', 'RAPPAHANNOCK LIGHT STATION (RPLV2)', 37.54, -76.02, 37.54, -76.02, 'Scattered thunderstorms associated with a trough of low pressure produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 43 knots was measured at Rappahannock Light.');
INSERT INTO public.stormevents_east VALUES (782372, 201808, 13, 1737, 201808, 13, 2030, 130509, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '13-AUG-18 17:37:00', 'EST-5', '13-AUG-18 20:30:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CONKLIN', 1, 'NNW', 'CONKLIN', 42.03, -75.8, 42.0379, -75.8042, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Numerous roads were flooded around town. Water surrounded a trailer park.');
INSERT INTO public.stormevents_east VALUES (754915, 201806, 24, 1738, 201806, 24, 1738, 125920, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MRX', '24-JUN-18 17:38:00', 'EST-5', '24-JUN-18 17:38:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'VALLEYTOWN', 0, 'N', 'VALLEYTOWN', 35.2, -83.82, 35.2, -83.82, 'A rather small thunderstorm complex which originated across Arkansas earlier in the day made steady progress across the Tennessee Valley of Alabama and into Southeast Tennessee and Southwest North Carolina producing damaging winds along its path.', 'Several trees were reported down at Valleytown.');
INSERT INTO public.stormevents_east VALUES (758578, 201805, 17, 430, 201805, 17, 530, 126423, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 04:30:00', 'EST-5', '17-MAY-18 05:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'HARMONY GROVE', 2, 'NNW', 'HARMONY GROVE', 39.4725, -77.4129, 39.471, -77.4137, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Two water rescues near the intersection of Willow Road and Willowbrook Road along Tuscarora Creek. Water was up to the hoods of the vehicles.');
INSERT INTO public.stormevents_east VALUES (758580, 201805, 17, 100, 201805, 17, 300, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 01:00:00', 'EST-5', '17-MAY-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'BURNING KNOLLS', 2, 'ENE', 'BURNING KNOLLS', 39.1796, -78.0856, 39.1793, -78.0857, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'Low water bridge over Abrams Creek flooded and closed on Valley Mill Road in the 1500 block.');
INSERT INTO public.stormevents_east VALUES (758581, 201805, 17, 515, 201805, 17, 700, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 05:15:00', 'EST-5', '17-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'WNW', 'PURCELLVILLE', 1, 'WNW', 'PURCELLVILLE', 39.17, -77.77, 39.1539, -77.7437, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'Several roads flooded and closed near South Fork Catoctin Creek north of Round Hill.');
INSERT INTO public.stormevents_east VALUES (758583, 201805, 17, 645, 201805, 17, 800, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 06:45:00', 'EST-5', '17-MAY-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'PURCELLVILLE', 2, 'WNW', 'PURCELLVILLE', 39.1582, -77.7487, 39.1583, -77.748, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'Ketoctin Church Road flooded and closed at the crossing of South Fork Catoctin Creek.');
INSERT INTO public.stormevents_east VALUES (758587, 201805, 17, 1522, 201805, 17, 1645, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 15:22:00', 'EST-5', '17-MAY-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'CASKIE', 1, 'SW', 'CASKIE', 37.5437, -78.8451, 37.5397, -78.839, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'Cars trapped in floodwaters in the Gladstone area.');
INSERT INTO public.stormevents_east VALUES (751237, 201806, 9, 1245, 201806, 9, 1445, 125267, 'DELAWARE', 10, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 12:45:00', 'EST-5', '09-JUN-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'FENWICK IS', 1, 'NE', 'OCEAN VIEW', 38.4518, -75.0646, 38.5597, -75.082, 'Heavy rain fell in southern Delaware on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'There was widespread roadway flooding and some vehicles were stranded from Bethany Beach down to Fenwick Island.  All lanes of busy Delaware Route 1 were closed at Delaware Route 54 in Fenwick Island.');
INSERT INTO public.stormevents_east VALUES (751240, 201806, 9, 1315, 201806, 9, 1615, 125267, 'DELAWARE', 10, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 13:15:00', 'EST-5', '09-JUN-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'FRANKFORD', 0, 'SW', 'DAGSBORO', 38.5231, -75.2544, 38.5463, -75.2563, 'Heavy rain fell in southern Delaware on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'A number of roads were flooded in and around Dagsboro.  Swamp Road was closed between Railroad Avenue and US Route 113.  Armory Road was closed between Delaware Route 26 and Townsend Road.');
INSERT INTO public.stormevents_east VALUES (751244, 201806, 9, 1345, 201806, 9, 1615, 125267, 'DELAWARE', 10, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 13:45:00', 'EST-5', '09-JUN-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'STOCKLEY', 1, 'WNW', 'GEORGETOWN', 38.6416, -75.3823, 38.6879, -75.403, 'Heavy rain fell in southern Delaware on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'There was roadway flooding and a number of road closures in and around Georgetown, including Kruger Road between US Route 113 and Breasure Road.');
INSERT INTO public.stormevents_east VALUES (751315, 201806, 9, 1430, 201806, 9, 1630, 125267, 'DELAWARE', 10, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 14:30:00', 'EST-5', '09-JUN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'BLADES', 1, 'W', 'BLADES', 38.6452, -75.6381, 38.6313, -75.6374, 'Heavy rain fell in southern Delaware on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'Widespread roadway flooding in and around Seaford.  Several vehicles were stranded in the flood waters.');
INSERT INTO public.stormevents_east VALUES (752569, 201806, 21, 1321, 201806, 21, 1321, 125467, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '21-JUN-18 13:21:00', 'EST-5', '21-JUN-18 13:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 50, 'MG', NULL, NULL, 2, 'SSE', 'MELBOURNE BEACH', 2, 'SSE', 'MELBOURNE BEACH', 28.05, -80.56, 28.05, -80.56, 'Central Florida was wedged between a high pressure ridge axis to the south, and a weak low pressure trough to the north. This resulted in strong west flow in the low-levels across east central Florida, and allowed deep moisture to remain in place across the area with Precipitable Water values near 2 inches. Scattered showers and thunderstorms developed during the afternoon and evening hours, mainly along the quickly progressing west coast sea breeze. The strong west winds delayed the development of the east coast sea breeze by a few hours, but by mid-afternoon the sea breeze had developed in Brevard County. Showers and thunderstorms began to develop along the slowly advancing sea breeze. Further south, in Indian River County, a thunderstorm there produced a northward moving outflow boundary that pushed into Brevard County and interacted with the sea breeze. This caused enhanced lift just along the sea breeze over Melbourne, and a severe thunderstorm quickly developed. This storm produced a severe wind gust along the intracoastal waters near Melbourne Beach.', 'APRS site DW8248 measured a peak wind gust of 50 knots from the northwest. Around 10 minutes later the same site gusted to 53 knots.');
INSERT INTO public.stormevents_east VALUES (752594, 201806, 22, 1755, 201806, 22, 1755, 125488, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MLB', '22-JUN-18 17:55:00', 'EST-5', '22-JUN-18 17:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 50, 'MG', NULL, NULL, 0, 'N', 'SHILOH', 0, 'N', 'SHILOH', 28.78, -80.8, 28.78, -80.8, 'A surface and 850 mb high pressure ridge axis was located well south of central Florida, which resulted in west low-level flow across the area. An upper-level ridge remained over the central Florida peninsula, although the axis had moved south to the Lake Okeechobee area. This setup favored the west coast sea breeze and most of the storms that developed to move towards the east coast. Scattered to numerous showers and storms did develop in the afternoon and early evening. One storm moved across the intracoastal waters of northern Brevard County where it produced severe winds. Also, one person was struck by lightning in Viera.', 'US Air Force wind tower 0421 measured a peak wind gust of 50 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (752570, 201806, 21, 1321, 201806, 21, 1321, 125468, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MLB', '21-JUN-18 13:21:00', 'EST-5', '21-JUN-18 13:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 50, 'MG', NULL, NULL, 2, 'SSE', 'MELBOURNE BEACH', 2, 'SSE', 'MELBOURNE BEACH', 28.05, -80.56, 28.05, -80.56, 'Central Florida was wedged between a high pressure ridge axis to the south, and a weak low pressure trough to the north. This resulted in strong west flow in the low-levels across east central Florida, and allowed deep moisture to remain in place across the area with Precipitable Water values near 2 inches. Scattered showers and thunderstorms developed during the afternoon and evening hours, mainly along the quickly progressing west coast sea breeze. The strong west winds delayed the development of the east coast sea breeze by a few hours, but by mid-afternoon the sea breeze had developed in Brevard County. Showers and thunderstorms began to develop along the slowly advancing sea breeze. Further south, in Indian River County, a thunderstorm there produced a northward moving outflow boundary that pushed into Brevard County and interacted with the sea breeze. This caused enhanced lift just along the sea breeze over Melbourne, and a severe thunderstorm quickly developed. This storm produced a severe wind gust in Melbourne Beach. In Port Orange, a home was destroyed after being struck by lightning and catching fire.', 'APRS site DW8248 measured a peak wind gust of 50 knots or 58 mph from the northwest. Around 10 minutes later the same site gusted to 53 knots or 61 mph..');
INSERT INTO public.stormevents_east VALUES (753814, 201806, 24, 1315, 201806, 24, 1315, 125691, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'TBW', '24-JUN-18 13:15:00', 'EST-5', '24-JUN-18 13:15:00', 1, 0, 1, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, NULL, NULL, 1, 'NW', 'PINE SHRS', 1, 'NW', 'PINE SHRS', 27.26, -82.54, 27.26, -82.54, 'Scattered thunderstorms developed across the Florida Peninsula throughout the afternoon. A lightning strike from one of the storms killed a person in Siesta Key. A building fire was suspected to have been caused by another lightning strike.', 'A man and woman at the beach began to head for shelter as it started to rain. The man was struck by lightning, knocking back the woman back. The man was transported to a hospital, but was unable to be revived.');
INSERT INTO public.stormevents_east VALUES (753861, 201806, 24, 1045, 201806, 24, 1045, 125691, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'TBW', '24-JUN-18 10:45:00', 'EST-5', '24-JUN-18 10:45:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'SW', 'ROTUNDA WEST', 1, 'SW', 'ROTUNDA WEST', 26.8597, -82.287, 26.8597, -82.287, 'Scattered thunderstorms developed across the Florida Peninsula throughout the afternoon. A lightning strike from one of the storms killed a person in Siesta Key. A building fire was suspected to have been caused by another lightning strike.', 'A fire that destroyed a golf club maintenance shed was suspected to have been caused by a lightning strike.');
INSERT INTO public.stormevents_east VALUES (753890, 201806, 25, 1713, 201806, 25, 1713, 125708, 'GULF OF MEXICO', 85, 2018, 'June', 'Marine Thunderstorm Wind', 'TBW', '25-JUN-18 17:13:00', 'EST-5', '25-JUN-18 17:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'EG', NULL, NULL, 1, 'S', 'LOWER TAMPA BAY', 1, 'S', 'LOWER TAMPA BAY', 27.6, -82.65, 27.6, -82.65, 'Thunderstorms developed over the Florida Peninsula throughout the afternoon hours and pushed west towards the Gulf Coast through the early evening. Some of these storms produced marine wind gusts along the coast.', 'The WeatherFlow site on the Sunshine Skyway Bridge Fishing Pier (XSKY) recorded a 35 knot marine thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (753966, 201806, 27, 1447, 201806, 27, 1447, 125720, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'MLB', '27-JUN-18 14:47:00', 'EST-5', '27-JUN-18 14:47:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'SSW', '(ORL)ORLANDO EXEC AR', 2, 'SSW', '(ORL)ORLANDO EXEC AR', 28.53, -81.34, 28.53, -81.34, 'The main flow across central Florida was from the west-southwest due to a frontal trough moving across the mid-Atlantic states, and the axis of the Bermuda High Pressure situated across south Florida. Moisture was high across the area with Precipitable Water values around 1.80 to 2.00 inches. Temperatures aloft at 500 mb were around -6 to -7 degrees Celsius. The atmosphere was favorable for showers and thunderstorms to develop along the east and west coast sea breezes. Due to the stronger west winds, the west coast sea breeze was dominant, and the main collision between the two sea breezes occurred closer to the east central Florida coast. Still, numerous showers and thunderstorms impacted much of east central Florida. One man was killed after being struck by lightning in Umatilla, while another man was injured after being struck by lightning in Orlando.', 'Per reports relayed via local broadcast media, an Orlando man working on the roof of his home was struck by lightning and injured. Two neighbors called 911 after finding the injured man laying on the ground behind his home, though he was conscious at the time. Orlando firefighters arrived at the man''s home, which is located on Lake Arnold Place, near Primrose Drive just south of State Road 408. Firefighters transported the man to a local hospital as a trauma alert. The injured man survived his injuries.');
INSERT INTO public.stormevents_east VALUES (754978, 201806, 18, 1907, 201806, 18, 1907, 125932, 'NEW JERSEY', 34, 2018, 'June', 'Thunderstorm Wind', 'PHI', '18-JUN-18 19:07:00', 'EST-5', '18-JUN-18 19:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'BARBERTOWN', 0, 'N', 'BARBERTOWN', 40.48, -75.03, 40.48, -75.03, 'Severe thunderstorms caused wind damage across portions of New Jersey.', 'A 12+ inch diameter oak tree snapped off approximately 10 feet above the ground. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (754975, 201806, 18, 1755, 201806, 18, 1755, 125931, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PHI', '18-JUN-18 17:55:00', 'EST-5', '18-JUN-18 17:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'ENE', 'STORMVILLE', 1, 'ENE', 'STORMVILLE', 40.96, -75.21, 40.96, -75.21, 'Severe thunderstorms caused wind damage across portions of eastern Pennsylvania.', 'Trees were down blocking roadways.');
INSERT INTO public.stormevents_east VALUES (754977, 201806, 18, 1815, 201806, 18, 1815, 125931, 'PENNSYLVANIA', 42, 2018, 'June', 'Thunderstorm Wind', 'PHI', '18-JUN-18 18:15:00', 'EST-5', '18-JUN-18 18:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'CENTERPORT', 1, 'S', 'CENTERPORT', 40.47, -76.02, 40.47, -76.02, 'Severe thunderstorms caused wind damage across portions of eastern Pennsylvania.', 'Trees were reported down.');
