INSERT INTO public.stormevents_east VALUES (754976, 201806, 18, 1840, 201806, 18, 1840, 125932, 'NEW JERSEY', 34, 2018, 'June', 'Thunderstorm Wind', 'PHI', '18-JUN-18 18:40:00', 'EST-5', '18-JUN-18 18:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NE', 'BROADWAY', 1, 'NE', 'BROADWAY', 40.74, -75.04, 40.74, -75.04, 'Severe thunderstorms caused wind damage across portions of New Jersey.', 'Tree was down across the road near 2093 route 57 in  franklin township. Time estimated from radar.');
INSERT INTO public.stormevents_east VALUES (755931, 201806, 25, 127, 201806, 25, 427, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 01:27:00', 'EST-5', '25-JUN-18 04:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'REVERE', 1, 'S', 'REVERE', 42.4051, -71.0169, 42.4046, -71.0161, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 1:27 AM EST, the junction of Broadway and State Route 16 in Revere was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (755933, 201806, 25, 130, 201806, 25, 500, 125905, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '25-JUN-18 01:30:00', 'EST-5', '25-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'REVERE', 1, 'ENE', 'REVERE', 42.4227, -71.0089, 42.4231, -71.0083, 'A cold front moved through from the Great Lakes the night of June 24th. This brought showers and thunderstorms with locally heavy downpours, with rainfall amounts up to 2 inches.', 'At 1:30 AM EST, Sqier Road was reported flooded and impassable from Patriot Parkway to the circle at State Route 107.');
INSERT INTO public.stormevents_east VALUES (753727, 201806, 21, 818, 201806, 21, 1018, 125679, 'KENTUCKY', 21, 2018, 'June', 'Flood', 'ILN', '21-JUN-18 08:18:00', 'EST-5', '21-JUN-18 10:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'RIBOLT', 2, 'N', 'RIBOLT', 38.59, -83.53, 38.5927, -83.5249, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general.', 'Water was reported over Poplar Flat Road.');
INSERT INTO public.stormevents_east VALUES (753728, 201806, 21, 1019, 201806, 21, 1219, 125679, 'KENTUCKY', 21, 2018, 'June', 'Flood', 'ILN', '21-JUN-18 10:19:00', 'EST-5', '21-JUN-18 12:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'GARRISON', 1, 'W', 'GARRISON', 38.5961, -83.1818, 38.5987, -83.181, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general.', 'Water was reported running over Kinney Road.');
INSERT INTO public.stormevents_east VALUES (753729, 201806, 21, 1100, 201806, 21, 1300, 125679, 'KENTUCKY', 21, 2018, 'June', 'Flood', 'ILN', '21-JUN-18 11:00:00', 'EST-5', '21-JUN-18 13:00:00', 0, 0, 0, 0, '4.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'GARRISON', 2, 'E', 'VANCEBURG', 38.6, -83.21, 38.6027, -83.2136, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general.', 'Tile was washed out near a house by rushing water.');
INSERT INTO public.stormevents_east VALUES (753731, 201806, 21, 1122, 201806, 21, 1322, 125679, 'KENTUCKY', 21, 2018, 'June', 'Flood', 'ILN', '21-JUN-18 11:22:00', 'EST-5', '21-JUN-18 13:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'VANCEBURG', 1, 'WNW', 'VANCEBURG', 38.6093, -83.2553, 38.6024, -83.2631, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general.', 'Water was reported flowing over a road in the Black Oak subdivision.');
INSERT INTO public.stormevents_east VALUES (749629, 201806, 8, 1201, 201806, 8, 1211, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 12:01:00', 'EST-5', '08-JUN-18 12:11:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'NW', 'COLUMBUS SO COLUMBUS', 1, 'NW', 'COLUMBUS SO COLUMBUS', 39.89, -82.98, 39.89, -82.98, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'A tree was blown down on a house along Rumsey Road.');
INSERT INTO public.stormevents_east VALUES (749625, 201806, 8, 2018, 201806, 8, 2218, 124954, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '08-JUN-18 20:18:00', 'EST-5', '08-JUN-18 22:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'FAIRVIEW', 3, 'NE', 'ROCK MILLS', 39.4559, -83.3484, 39.4513, -83.3791, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Several roads were closed due to high standing water. One bridge was closed on State Route 753 due to a creek flowing across it.');
INSERT INTO public.stormevents_east VALUES (749661, 201806, 9, 1639, 201806, 9, 1649, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:39:00', 'EST-5', '09-JUN-18 16:49:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'ESE', 'BOWLUSVILLE', 2, 'ESE', 'BOWLUSVILLE', 40.0047, -83.7655, 40.0047, -83.7655, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A very large tree was uprooted and fell on a house, causing some damage to the house along Calais Drive.');
INSERT INTO public.stormevents_east VALUES (749670, 201806, 9, 1833, 201806, 9, 1843, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 18:33:00', 'EST-5', '09-JUN-18 18:43:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 0, 'N', 'GROVE CITY', 0, 'N', 'GROVE CITY', 39.88, -83.08, 39.88, -83.08, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'One limb was knocked down along Columbus Street.');
INSERT INTO public.stormevents_east VALUES (758118, 201806, 9, 1635, 201806, 9, 1645, 126476, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '09-JUN-18 16:35:00', 'EST-5', '09-JUN-18 16:45:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 46, 'MG', NULL, NULL, 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 37.98, -75.86, 37.98, -75.86, 'A few thunderstorms produced gusty winds due to an unstable atmosphere both days.', 'A wind gust of 46 knots was reported at the Crisfield Fire Department.');
INSERT INTO public.stormevents_east VALUES (758120, 201806, 9, 1600, 201806, 9, 1600, 126476, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '09-JUN-18 16:00:00', 'EST-5', '09-JUN-18 16:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 43, 'MG', NULL, NULL, 1, 'SE', 'GREENBERRY POINT (GBY)', 1, 'SE', 'GREENBERRY POINT (GBY)', 38.96, -76.45, 38.96, -76.45, 'A few thunderstorms produced gusty winds due to an unstable atmosphere both days.', 'A wind gust of 43 knots was reported at the Annapolis Buoy.');
INSERT INTO public.stormevents_east VALUES (763792, 201806, 3, 1410, 201806, 3, 1412, 127428, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'CLE', '03-JUN-18 14:10:00', 'EST-5', '03-JUN-18 14:12:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'EAST ORWELL', 1, 'S', 'ORWELL', 41.5362, -80.8619, 41.5155, -80.88, 'A cold front moved across northern Ohio during the afternoon of June 3rd.  A line of thunderstorms developed in advance of the front.  A couple reports of damage were received as this line moved across Northeast Ohio.', 'Thunderstorm wind gusts knocked a tree down along Central Avenue.  The tree landed on a house causing some damage.  A second tree and some power lines were reported down south of Orville.');
INSERT INTO public.stormevents_east VALUES (763794, 201806, 18, 1814, 201806, 18, 1814, 127430, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'CLE', '18-JUN-18 18:14:00', 'EST-5', '18-JUN-18 18:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 54, 'ENE', 'WILLOWICK', 54, 'ENE', 'WILLOWICK', 41.98, -80.56, 41.98, -80.56, 'A cold front crossed Lake Erie on June 18th causing a line of thunderstorms to develop.  Wind gusts in excess of 35 knots were reported at a couple locations.', 'A 36 knot thunderstorm wind gust was measured at the Conneaut Lighthouse.');
INSERT INTO public.stormevents_east VALUES (763798, 201806, 5, 130, 201806, 5, 130, 127431, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'CLE', '05-JUN-18 01:30:00', 'EST-5', '05-JUN-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 35, 'MG', NULL, NULL, 9, 'ENE', 'VERMILION', 9, 'ENE', 'VERMILION', 41.48, -82.2, 41.48, -82.2, 'An area of showers moved across Lake Erie and produced some gusty winds.', 'A 35 knot gust was measured at the Lorain Lighthouse.');
INSERT INTO public.stormevents_east VALUES (763796, 201806, 18, 1806, 201806, 18, 1806, 127430, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'CLE', '18-JUN-18 18:06:00', 'EST-5', '18-JUN-18 18:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 37, 'MG', NULL, NULL, 81, 'ENE', 'WILLOWICK', 81, 'ENE', 'WILLOWICK', 42.15, -80.09, 42.15, -80.09, 'A cold front crossed Lake Erie on June 18th causing a line of thunderstorms to develop.  Wind gusts in excess of 35 knots were reported at a couple locations.', 'A 37 knot thunderstorm wind gust was measured.');
INSERT INTO public.stormevents_east VALUES (763795, 201806, 18, 1910, 201806, 18, 1910, 127430, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'CLE', '18-JUN-18 19:10:00', 'EST-5', '18-JUN-18 19:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 35, 'MG', NULL, NULL, 66, 'WNW', 'AVON POINT', 66, 'WNW', 'AVON POINT', 41.7, -83.26, 41.7, -83.26, 'A cold front crossed Lake Erie on June 18th causing a line of thunderstorms to develop.  Wind gusts in excess of 35 knots were reported at a couple locations.', 'A 35 knot wind gust was measured by a buoy north of Reno Beach.');
INSERT INTO public.stormevents_east VALUES (765724, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'SAUMSVILLE', 1, 'E', 'SAUMSVILLE', 38.93, -78.49, 38.9298, -78.4894, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Swartz Road (Route 642) flooded and closed near Saumsville Road.');
INSERT INTO public.stormevents_east VALUES (765725, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MAURERTOWN', 1, 'N', 'MAURERTOWN', 38.939, -78.4515, 38.9395, -78.4501, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Both US 11 and Toll House Road (Route 740) were flooded and closed near Jordan Run.');
INSERT INTO public.stormevents_east VALUES (765726, 201806, 22, 730, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:30:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'CAPON RD', 2, 'ESE', 'CAPON RD', 38.991, -78.3286, 38.9908, -78.3282, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Bowman Mill Road closed due to flooding at Cedar Creek.');
INSERT INTO public.stormevents_east VALUES (765727, 201806, 22, 731, 201806, 22, 930, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 07:31:00', 'EST-5', '22-JUN-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'MONUMENT MILLS', 2, 'NW', 'MONUMENT MILLS', 38.6232, -78.0319, 38.623, -78.0313, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Doc''s Road flooded and closed at the Thornton River.');
INSERT INTO public.stormevents_east VALUES (765729, 201806, 22, 822, 201806, 22, 1000, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 08:22:00', 'EST-5', '22-JUN-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'WASHINGTON', 2, 'NW', 'WASHINGTON', 38.7408, -78.2022, 38.7407, -78.2017, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Harris Hollow Road flooded and closed at the Rush River. The river was reported too be out of its banks, and more than a half foot over the road and still rising at the time of the report.');
INSERT INTO public.stormevents_east VALUES (769093, 201806, 22, 607, 201806, 23, 1139, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 06:07:00', 'EST-5', '23-JUN-18 11:39:00', 0, 0, 0, 0, '50.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'RAPIDAN', 1, 'S', 'RAPIDAN', 38.3089, -78.0932, 38.3067, -78.0696, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on the Rapidan River south of Culpeper exceeded the 13 foot flood stage during the indicated period, reaching a level not seen in over 20 years. The peak level of 23.70 feet occurred at 9:15pm on June 22nd. Significant flooding was reported in Rapidan, with water up to four feet deep inside the first floor of homes. Dozens of roads were closed in the area.');
INSERT INTO public.stormevents_east VALUES (769095, 201806, 23, 237, 201806, 24, 219, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 02:37:00', 'EST-5', '24-JUN-18 02:19:00', 0, 0, 0, 0, '10.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'FIVE MILE', 2, 'NNE', 'FIVE MILE', 38.3136, -77.5423, 38.3117, -77.5408, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on the Rappahannock River above Fredericksburg exceeded the 13 foot flood stage during the indicated period. The peak level of 17.55 feet occurred at 2:15pm EST on June 23rd. Water entered the building at a riverside wedding venue, and was about 4 feet deep. River Road was also flooded along with structures near the Motts Run boat landing.');
INSERT INTO public.stormevents_east VALUES (769094, 201806, 22, 648, 201806, 22, 915, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 06:48:00', 'EST-5', '22-JUN-18 09:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'COOTES STORE', 0, 'ENE', 'COOTES STORE', 38.6339, -78.8457, 38.6322, -78.8433, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on the North Fork Shenandoah River at Cootes Store exceeded the 15 foot flood stage during the indicated period. The peak level of 15.42 occurred at 8:15am EST on June 22nd. Brocks Gap Road and a campground were flooded.');
INSERT INTO public.stormevents_east VALUES (769099, 201806, 22, 908, 201806, 22, 1322, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 09:08:00', 'EST-5', '22-JUN-18 13:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'LAUREL MILLS', 1, 'E', 'LAUREL MILLS', 38.6488, -78.0758, 38.6489, -78.0753, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on Battle Run near Laurel Mills exceeded the 11 foot flood stage during the indicated period. The peak level of 12.43 feet occurred at 10:30am EST on June 22nd. Laurel Mills Road was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (759256, 201805, 19, 1152, 201805, 20, 344, 126452, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 11:52:00', 'EST-5', '20-MAY-18 03:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'REMINGTON', 1, 'WSW', 'REMINGTON', 38.5282, -77.8121, 38.5256, -77.8113, 'Heavy rain of 1-3 inches fell during the evening and overnight of May 18th into May 19th along and east of the Blue Ridge Mountains. This prompted flooding in the region, mainly of streams. Some of the stream flooding lasted into the 20th, especially on larger rivers.', 'The stream gage on the Rappahannock River at Remington exceeded the 15 foot flood stage during the times indicated. The peak level of 16.44 feet occurred at 8:30pm EST on May 19th. At these levels, roads are flooded along Tinpot Run due to backwater.');
INSERT INTO public.stormevents_east VALUES (759978, 201805, 26, 1603, 201805, 26, 1800, 126457, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '26-MAY-18 16:03:00', 'EST-5', '26-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'MT WILLIAMS', 2, 'WSW', 'MT WILLIAMS', 39.1378, -78.3656, 39.1367, -78.3567, 'Scattered heavy afternoon thunderstorms produced 1-2 inches of rain, causing flooding in a few different locations in northern Virginia.', 'Wardensville Grade flooded and closed near Furnace Run between Mount Williams and Mountain Falls.');
INSERT INTO public.stormevents_east VALUES (759253, 201805, 19, 421, 201805, 19, 1533, 126452, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 04:21:00', 'EST-5', '19-MAY-18 15:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'RIXEYVILLE', 3, 'W', 'LAKOTA', 38.5768, -77.9201, 38.577, -77.9169, 'Heavy rain of 1-3 inches fell during the evening and overnight of May 18th into May 19th along and east of the Blue Ridge Mountains. This prompted flooding in the region, mainly of streams. Some of the stream flooding lasted into the 20th, especially on larger rivers.', 'The stream gage on Hazel River near Rixeyville exceeded the 16 foot flood stage during the indicated times. The peak level of 17.69 feet was observed at 10:30am EST on May 19th. At these levels, agricultural flooding is occurring and water is approaching Ryland Chapel Road.');
INSERT INTO public.stormevents_east VALUES (751764, 201806, 18, 1744, 201806, 18, 2100, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '18-JUN-18 17:44:00', 'EST-5', '18-JUN-18 21:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'LEOMINSTER', 0, 'W', 'WHALOM', 42.5286, -71.7538, 42.5195, -71.7545, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:34 PM EST, a car was trapped in flood waters on Water Street in Leominster, and a second car was trapped in flood waters on Graham Street.');
INSERT INTO public.stormevents_east VALUES (751767, 201806, 18, 1735, 201806, 18, 1735, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:35:00', 'EST-5', '18-JUN-18 17:35:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'HARVARD', 1, 'SW', 'HARVARD', 42.4888, -71.5905, 42.4888, -71.5905, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:35 PM EST a large tree and wires were reported down on Warren Avenue in Harvard.');
INSERT INTO public.stormevents_east VALUES (751774, 201806, 18, 1835, 201806, 18, 1835, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 18:35:00', 'EST-5', '18-JUN-18 18:35:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SE', 'SOUTHBRIDGE ARPT', 1, 'SE', 'SOUTHBRIDGE ARPT', 42.0913, -72.0199, 42.0913, -72.0199, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 6:35 PM EST, a tree and wires were reported down on Charlton Street in Southbridge.');
INSERT INTO public.stormevents_east VALUES (751775, 201806, 18, 1700, 201806, 18, 1700, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:00:00', 'EST-5', '18-JUN-18 17:00:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'E', 'HOVEY CORNER', 1, 'E', 'HOVEY CORNER', 42.679, -71.5879, 42.679, -71.5879, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5 PM EST, a tree was down on wires on Brookline Street in Pepperell.');
INSERT INTO public.stormevents_east VALUES (751780, 201806, 18, 1730, 201806, 18, 1735, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:30:00', 'EST-5', '18-JUN-18 17:35:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'W', 'SOUTH CHELMSFORD', 2, 'W', 'SOUTH CHELMSFORD', 42.5677, -71.3992, 42.5677, -71.3992, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:30 PM EST, many trees and wires were brought down on Old Lowell Road and Chelmsford Road in Westford.');
INSERT INTO public.stormevents_east VALUES (751781, 201806, 18, 1725, 201806, 18, 1730, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:25:00', 'EST-5', '18-JUN-18 17:30:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'SE', 'WESTFORD', 2, 'SE', 'WESTFORD', 42.5585, -71.4076, 42.5585, -71.4076, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:30 PM EST at tree fell into a house on Sequoia Road in Westford.');
INSERT INTO public.stormevents_east VALUES (765502, 201806, 18, 1806, 201806, 18, 1806, 127657, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'BUF', '18-JUN-18 18:06:00', 'EST-5', '18-JUN-18 18:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 43, 'MG', NULL, NULL, 1, 'NW', 'DUNKIRK', 1, 'NW', 'DUNKIRK', 42.5059, -79.3458, 42.5059, -79.3458, 'After storms went through the North Country earlier in the day, a second, and more significant round, came through Lake Erie and the Southern Tier closer to the cold front with a bit more dynamics aloft. There was more shear, with 700 mb winds about 10 knots stronger and an MCV which likely enhanced shear. In this case, a line of storms was able to make it across Lake Erie, then strengthen into a bow echo across the Western Southern Tier.', NULL);
INSERT INTO public.stormevents_east VALUES (762817, 201806, 24, 2202, 201806, 24, 2205, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 22:02:00', 'EST-5', '24-JUN-18 22:05:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'N', 'BATH', 1, 'N', 'BATH', 33.51, -81.87, 33.51, -81.87, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees in roadway on Anthony Dr near Jefferson Davis Hwy (US Hwy 78).');
INSERT INTO public.stormevents_east VALUES (762818, 201806, 24, 2243, 201806, 24, 2245, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 22:43:00', 'EST-5', '24-JUN-18 22:45:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 5, 'SW', 'EHRHARDT', 5, 'SW', 'EHRHARDT', 33.04, -81.07, 33.04, -81.07, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'SCHP reported trees down on Hwy 641 near Ehrhardt in Bamberg Co.');
INSERT INTO public.stormevents_east VALUES (762819, 201806, 24, 2109, 201806, 24, 2114, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:09:00', 'EST-5', '24-JUN-18 21:14:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 60, 'EG', NULL, NULL, 2, 'ESE', 'HORSE CREEK', 2, 'ESE', 'HORSE CREEK', 33.4691, -81.8765, 33.4691, -81.8765, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Spotter reported large trees blocking the roadway near 1500 Storm Branch Rd near Beech Island, SC.');
INSERT INTO public.stormevents_east VALUES (762820, 201806, 24, 2050, 201806, 24, 2050, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 20:50:00', 'EST-5', '24-JUN-18 20:50:00', 0, 0, 0, 0, '0.10K', '0.10K', 'AWOS', 43, 'MG', NULL, NULL, 1, 'NE', 'MANNING CLARENDON AR', 1, 'NE', 'MANNING CLARENDON AR', 33.5872, -80.2087, 33.5872, -80.2087, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'AWOS unit at Santee Cooper Regional Airport measured a peak wind gust of 50 mph.');
INSERT INTO public.stormevents_east VALUES (762821, 201806, 24, 1922, 201806, 24, 1925, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 19:22:00', 'EST-5', '24-JUN-18 19:25:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 0, 'WSW', 'MYRON MANOR', 0, 'WSW', 'MYRON MANOR', 33.9977, -80.9759, 33.9977, -80.9759, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Downed power lines on Arbutus Dr and Datura Rd.');
INSERT INTO public.stormevents_east VALUES (762822, 201806, 24, 2110, 201806, 24, 2112, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'CAE', '24-JUN-18 21:10:00', 'EST-5', '24-JUN-18 21:12:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 0, 'N', 'HAMBURG', 0, 'N', 'HAMBURG', 33.48, -81.95, 33.48, -81.95, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Nickel to dime size hail reported by a spotter.');
INSERT INTO public.stormevents_east VALUES (762823, 201806, 24, 2106, 201806, 24, 2108, 126886, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'CAE', '24-JUN-18 21:06:00', 'EST-5', '24-JUN-18 21:08:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'NW', 'JACKSONVILLE', 1, 'NW', 'JACKSONVILLE', 33.5068, -81.8566, 33.5068, -81.8566, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Spotter reported dime to penny size hail on Dummy Line Rd in Burnettown.');
INSERT INTO public.stormevents_east VALUES (762824, 201806, 24, 2113, 201806, 24, 2115, 126887, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '24-JUN-18 21:13:00', 'EST-5', '24-JUN-18 21:15:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 1, 'NE', 'DE BRUCE', 1, 'NE', 'DE BRUCE', 33.4637, -81.9505, 33.4637, -81.9505, 'Strong atmospheric instability, enhanced by strong daytime heating, combined with an upper level disturbance to produce a band of severe thunderstorms that swept SE through the CSRA of GA and the Midlands of SC during the evening.', 'Trees down on E Boundary Rd and E Watkins St.');
INSERT INTO public.stormevents_east VALUES (762142, 201806, 30, 1924, 201806, 30, 1924, 127177, 'GULF OF MEXICO', 85, 2018, 'June', 'Waterspout', 'TAE', '30-JUN-18 19:24:00', 'EST-5', '30-JUN-18 19:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 10, 'WSW', 'ADAMS BEACH', 10, 'WSW', 'ADAMS BEACH', 29.8246, -83.7842, 29.8246, -83.7842, 'Strong to severe thunderstorms developed in Apalachee Bay with a waterspout reported off the Taylor county coast.', 'A photo of a waterspout offshore of Adams Beach was posted on the Taylor County Emergency Management facebook page.');
INSERT INTO public.stormevents_east VALUES (781448, 201808, 31, 1806, 201808, 31, 2006, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 18:06:00', 'EST-5', '31-AUG-18 20:06:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'CASTLETON', 1, 'SSW', 'CASTLETON', 39.6565, -76.1774, 39.6548, -76.1744, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Route 1 was closed due to flooding between Conowingo Dam and Deer Creek Dam.');
INSERT INTO public.stormevents_east VALUES (781453, 201808, 31, 1925, 201808, 31, 2000, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 19:25:00', 'EST-5', '31-AUG-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 3, 'N', 'BALTIMORE HIGHLANDS', 3, 'N', 'BALTIMORE HIGHLANDS', 39.2714, -76.6486, 39.2722, -76.6529, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The stream gauge reached the flood stage of 13 feet. At this level, water approaches the bike path alongside the stream.');
INSERT INTO public.stormevents_east VALUES (769077, 201806, 11, 1632, 201806, 11, 1632, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '11-JUN-18 16:32:00', 'EST-5', '11-JUN-18 16:32:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'W', 'LEWISVILLE', 5, 'W', 'LEWISVILLE', 36.0918, -80.5006, 36.0918, -80.5006, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Tree blown down onto a power-line on Shallowfrod Road at Williams Street.');
INSERT INTO public.stormevents_east VALUES (769078, 201806, 11, 1655, 201806, 11, 1655, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'RAH', '11-JUN-18 16:55:00', 'EST-5', '11-JUN-18 16:55:00', 0, 0, 0, 0, '0.00K', '3.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SW', 'MC CLAM XRDS', 2, 'W', 'HOBBTON', 35.1761, -78.4284, 35.1696, -78.3642, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Thunderstorm winds downed numerous trees across northern Samspon County, mainly near the community of Vann Crossroads.');
INSERT INTO public.stormevents_east VALUES (769364, 201806, 11, 1305, 201806, 11, 1305, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Lightning', 'RAH', '11-JUN-18 13:05:00', 'EST-5', '11-JUN-18 13:05:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 3, 'NNE', 'GIDDENSVILLE', 3, 'NNE', 'GIDDENSVILLE', 35.17, -78.2, 35.17, -78.2, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'East of Hobbton in Sampson County, a home improvement store was hit by lightning, causing extensive electrical damage. The lightning traveled through the phone line and destroyed a TV and microwave oven.');
INSERT INTO public.stormevents_east VALUES (769365, 201806, 11, 1605, 201806, 11, 1605, 128223, 'NORTH CAROLINA', 37, 2018, 'June', 'Lightning', 'RAH', '11-JUN-18 16:05:00', 'EST-5', '11-JUN-18 16:05:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', NULL, NULL, NULL, NULL, 2, 'SSE', 'BENSON', 2, 'SSE', 'BENSON', 35.35, -78.53, 35.35, -78.53, 'Outflow from previous night''s convection was stalled over the southeast third of NC, roughly from Camp Lejeune to Florence, SC. Meanwhile a surface cold front was drifting southward out of southern VA into NC. Thunderstorms erupted along this outflow by early afternoon. Outflows from these storms caused others to develop. The stronger cells produced quarter size hail along with isolated wind damage.', 'Lightning also damaged a Johnston County home about 2 miles south-southeast of Benson. Damage amounts were estimated.');
INSERT INTO public.stormevents_east VALUES (781511, 201807, 22, 109, 201807, 23, 1000, 128276, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 01:09:00', 'EST-5', '23-JUL-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'UPPER MARLBORO', 0, 'ESE', 'UPPER MARLBORO', 38.8148, -76.7464, 38.8188, -76.7454, 'Following the passage of a coastal low, bands of moisture pulled northward across the same areas that experienced heavy rain the day before. Rainfall amounts of 1 to 3 inches were common, with isolated higher amounts mainly in Anne Arundel and Calvert Counties. This produced renewed flooding, especially in those areas.', 'The USGS stream gage on Western Branch at Upper Marlboro exceeded the 11 foot flood stage during the indicated period. Water Street was flooded throughout, and Race Track Road was flooded for a time. The peak level of 13.05 feet occurred at 8:30am EST on July 22nd.');
INSERT INTO public.stormevents_east VALUES (781512, 201807, 21, 2309, 201807, 22, 130, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 23:09:00', 'EST-5', '22-JUL-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WALBROOK', 1, 'N', 'FREDERICK RD', 39.3005, -76.6741, 39.2975, -76.6727, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'The USGS stream gage on Gwynns Falls in Baltimore rapidly exceeded the 13 foot flood stage during the indicated period. The peak level of 18.29 feet was observed at 12:15am EST on July 22nd. Gwynns Falls Park was flooded during this period.');
INSERT INTO public.stormevents_east VALUES (753809, 201805, 10, 1333, 201805, 10, 1333, 125695, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '10-MAY-18 13:33:00', 'EST-5', '10-MAY-18 13:33:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NE', 'ADIAL', 1, 'NE', 'ADIAL', 37.8596, -78.8111, 37.8596, -78.8111, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (753834, 201805, 10, 1729, 201805, 10, 1729, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 17:29:00', 'EST-5', '10-MAY-18 17:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'OPAL', 1, 'SE', 'OPAL', 38.6052, -77.7806, 38.6052, -77.7806, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'A tree was down blocking the roadway in the 10400 Block of Old Marsh Road.');
INSERT INTO public.stormevents_east VALUES (753836, 201805, 10, 1745, 201805, 10, 1745, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 17:45:00', 'EST-5', '10-MAY-18 17:45:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 56, 'MG', NULL, NULL, 1, 'NE', 'MIDLAND WARRENTON AR', 1, 'NE', 'MIDLAND WARRENTON AR', 38.5868, -77.7097, 38.5868, -77.7097, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'A wind gust of 64 mph was measured at the Warrenton Airport.');
INSERT INTO public.stormevents_east VALUES (753841, 201805, 10, 1633, 201805, 10, 1633, 125694, 'MARYLAND', 24, 2018, 'May', 'Hail', 'LWX', '10-MAY-18 16:33:00', 'EST-5', '10-MAY-18 16:33:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'WNW', 'GAMBER', 1, 'WNW', 'GAMBER', 39.4743, -76.9601, 39.4743, -76.9601, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (763484, 201806, 1, 2215, 201806, 2, 15, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 22:15:00', 'EST-5', '02-JUN-18 00:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'MAPLEVILLE', 0, 'SE', 'MAPLEVILLE', 39.5278, -77.6476, 39.5277, -77.6465, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'A foot of water was flowing across Maryland Route 66 near Boonsboro.');
INSERT INTO public.stormevents_east VALUES (763485, 201806, 1, 2218, 201806, 2, 15, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 22:18:00', 'EST-5', '02-JUN-18 00:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'SHARPSBURG', 2, 'WNW', 'SHARPSBURG', 39.4637, -77.7763, 39.463, -77.7758, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'A portion of Snyders Landing Road was flooded and closed near Sharpsburg.');
INSERT INTO public.stormevents_east VALUES (763486, 201806, 2, 35, 201806, 2, 230, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 00:35:00', 'EST-5', '02-JUN-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'URBANA', 1, 'SE', 'URBANA', 39.3173, -77.3342, 39.317, -77.3335, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'Urbana Pike flooded and closed near Doctor Perry Road.');
INSERT INTO public.stormevents_east VALUES (763487, 201806, 2, 1709, 201806, 2, 1900, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 17:09:00', 'EST-5', '02-JUN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'BAKERSVILLE', 2, 'SSW', 'BAKERSVILLE', 39.4939, -77.763, 39.4939, -77.7622, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'Bowie Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (763488, 201806, 2, 1709, 201806, 2, 1900, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 17:09:00', 'EST-5', '02-JUN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'SHARPSBURG', 2, 'WNW', 'SHARPSBURG', 39.4636, -77.7762, 39.463, -77.7756, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'Snyders Landing Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (763489, 201806, 2, 1709, 201806, 2, 1900, 127369, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 17:09:00', 'EST-5', '02-JUN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'ANTIETAM', 1, 'NW', 'ANTIETAM', 39.4305, -77.7733, 39.4306, -77.77, 'A band of 1-2 inches of heavy rain on saturated ground across North Central Maryland caused flooding on the evening of June 1st that continued overnight into June 2nd. Then, more rain on the 2nd created flooding in some of the same areas during that evening.', 'Canal Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (763490, 201806, 1, 1826, 201806, 1, 1930, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 18:26:00', 'EST-5', '01-JUN-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'THE PARREN PLACE', 3, 'W', 'THE PARREN PLACE', 39.0039, -79.0044, 39.0059, -79.0026, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'A landslide triggered by heavy rain, along with associated floodwaters, caused the closure of US 220 just south of Moorefield near the Valley View Golf Club.');
INSERT INTO public.stormevents_east VALUES (767271, 201806, 3, 746, 201806, 4, 123, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 07:46:00', 'EST-5', '04-JUN-18 01:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LEAKSVILLE', 1, 'NNW', 'LEAKSVILLE', 38.6457, -78.537, 38.6471, -78.5355, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the South Fork Shenandoah River near Luray exceeded the 14 foot flood stage during the indicated period. The peak of 15.20 feet occurred at 6:45pm EST on June 3rd. Yards and agricultural fields were flooded, along with access roads to boat ramps at Route 211 and Bixlers Ferry.');
INSERT INTO public.stormevents_east VALUES (767272, 201806, 3, 2017, 201806, 4, 903, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 20:17:00', 'EST-5', '04-JUN-18 09:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'FISHERS HILL', 0, 'SSE', 'FISHERS HILL', 38.9523, -78.3762, 38.9752, -78.3785, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the North Fork Shenandoah River near Strasburg exceeded the 17 foot flood stage during the period indicated. The peak level was estimated by USGS to be 18.13 feet at 3:30am EST on June 4th. Deer Rapids Road floods along with significant agricultural flooding and flooding of the riverside park in Strasburg.');
INSERT INTO public.stormevents_east VALUES (767273, 201806, 3, 1341, 201806, 3, 1616, 127374, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 13:41:00', 'EST-5', '03-JUN-18 16:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'MARLBORO', 1, 'NNW', 'MARLBORO', 39.095, -78.3352, 39.0957, -78.3351, 'Ongoing flooding from June 2nd continued into the early morning hours of June 3rd. Then additional rainfall caused fairly widespread flooding across Northern Virginia later on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on Cedar Creek near Winchester exceeded the 16 foot flood stage during the indicated period. The peak level of 16.32 feet occurred at 3:00pm EST on June 3rd. Fromans Road was flooded and water neared an outbuilding nearby.');
INSERT INTO public.stormevents_east VALUES (767274, 201806, 3, 804, 201806, 3, 1536, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 08:04:00', 'EST-5', '03-JUN-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'BERKELEY SPGS', 0, 'SSW', 'BERKELEY SPGS', 39.6349, -78.223, 39.6247, -78.2317, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on Warm Springs Run near Berkeley Springs exceeded the 5 foot flood stage during the indicated period. The peak level of 5.83 feet occurred at 10:30am EST on June 3rd. Video and photos from the area show significant inundation at Berkeley Springs State Park. Several roads and buildings were reported flooded along with fields at area schools.');
INSERT INTO public.stormevents_east VALUES (767275, 201806, 3, 845, 201806, 4, 2142, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 08:45:00', 'EST-5', '04-JUN-18 21:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'GREAT CACAPON', 2, 'NNW', 'LARGENT', 39.6083, -78.2943, 39.5084, -78.3889, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Cacapon River near Great Cacapon exceeded the 9 foot flood stage during the indicated period. The peak level of 16.24 feet occurred at 10:15pm EST on June 3rd. Rock Ford Road was flooded and had to be closed for an extended period. Significant flooding with multiple road closures occurred throughout the floodplain.');
INSERT INTO public.stormevents_east VALUES (768045, 201806, 10, 2157, 201806, 10, 2157, 128065, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '10-JUN-18 21:57:00', 'EST-5', '10-JUN-18 21:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.95, -76.39, 36.95, -76.39, 'Scattered thunderstorms along a frontal boundary produced gusty winds across portions of the James River.', 'Wind gust of 36 knots was measured at Middle Ground Lighthouse.');
INSERT INTO public.stormevents_east VALUES (768055, 201806, 10, 2248, 201806, 10, 2248, 128066, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '10-JUN-18 22:48:00', 'EST-5', '10-JUN-18 22:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 0, 'N', 'CAPE HENRY', 0, 'N', 'CAPE HENRY', 36.92, -76, 36.92, -76, 'Scattered thunderstorms along a frontal boundary produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 36 knots was measured at Cape Henry.');
INSERT INTO public.stormevents_east VALUES (768108, 201806, 19, 1812, 201806, 19, 1812, 128071, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '19-JUN-18 18:12:00', 'EST-5', '19-JUN-18 18:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.95, -76.39, 36.95, -76.39, 'Scattered thunderstorms in advance of a cold front produced gusty winds across portions of the James River.', 'Wind gust of 41 knots was measured at Middle Ground Lighthouse.');
