INSERT INTO public.stormevents_east VALUES (768120, 201806, 19, 1855, 201806, 19, 1855, 128070, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '19-JUN-18 18:55:00', 'EST-5', '19-JUN-18 18:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'SANDBRIDGE', 0, 'N', 'SANDBRIDGE', 36.7, -75.92, 36.7, -75.92, 'Scattered thunderstorms in advance of a cold front produced gusty winds across portions of the Virginia Coastal Waters.', 'Wind gust of 35 knots was measured at Sandbridge.');
INSERT INTO public.stormevents_east VALUES (768213, 201806, 20, 2020, 201806, 20, 2020, 128105, 'NORTH CAROLINA', 37, 2018, 'June', 'Heavy Rain', 'AKQ', '20-JUN-18 20:20:00', 'EST-5', '20-JUN-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'SE', 'GRANDY', 1, 'SE', 'GRANDY', 36.24, -75.87, 36.24, -75.87, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds, heavy rain, and lightning damage across portions of northeast North Carolina.', 'Rainfall total of 1.80 inches was measured in one hour. Some minor flooding was reported.');
INSERT INTO public.stormevents_east VALUES (768215, 201806, 20, 2049, 201806, 20, 2049, 128105, 'NORTH CAROLINA', 37, 2018, 'June', 'Heavy Rain', 'AKQ', '20-JUN-18 20:49:00', 'EST-5', '20-JUN-18 20:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'W', 'WOODARD', 1, 'W', 'WOODARD', 35.92, -76.86, 35.92, -76.86, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds, heavy rain, and lightning damage across portions of northeast North Carolina.', 'Rainfall total of 4.32 inches was reported. The heaviest rain fell between 800 pm and 930 pm.');
INSERT INTO public.stormevents_east VALUES (768217, 201806, 20, 2106, 201806, 20, 2106, 128105, 'NORTH CAROLINA', 37, 2018, 'June', 'Heavy Rain', 'AKQ', '20-JUN-18 21:06:00', 'EST-5', '20-JUN-18 21:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 1, 'S', 'ECG CST GRD AIR STN', 1, 'S', 'ECG CST GRD AIR STN', 36.25, -76.17, 36.25, -76.17, 'Scattered severe thunderstorms along a frontal boundary produced damaging winds, heavy rain, and lightning damage across portions of northeast North Carolina.', 'Rainfall total of 2.37 inches was measured at ECG. Rainfall amount of 1.62 inches fell in about 30 minutes.');
INSERT INTO public.stormevents_east VALUES (769348, 201806, 26, 1450, 201806, 26, 1450, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 14:50:00', 'EST-5', '26-JUN-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'NW', 'CHICK SPGS', 3, 'NW', 'CHICK SPGS', 34.96, -82.306, 34.96, -82.306, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'Highway patrol reported power lines blown down at Locust Hill Rd and W McElhaney Rd and a tree down on St Mark Rd.');
INSERT INTO public.stormevents_east VALUES (769838, 201806, 26, 1544, 201806, 26, 1555, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 15:44:00', 'EST-5', '26-JUN-18 15:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'YORK', 2, 'ESE', 'YORK', 35.007, -81.266, 34.983, -81.196, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'County comms reported many trees blown down in the York area.');
INSERT INTO public.stormevents_east VALUES (769842, 201806, 26, 1555, 201806, 26, 1617, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 15:55:00', 'EST-5', '26-JUN-18 16:17:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'ROEBUCK', 0, 'NNE', 'EAST SPARTANBURG', 34.898, -82.007, 34.925, -81.897, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'County comms and highway patrol reported multiple trees blown down across the south side of the city of Spartanburg.');
INSERT INTO public.stormevents_east VALUES (769844, 201806, 26, 1704, 201806, 26, 1710, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '26-JUN-18 17:04:00', 'EST-5', '26-JUN-18 17:10:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'WNW', 'CALHOUN FALLS', 1, 'WNW', 'CALHOUN FALLS ARPT', 34.102, -82.609, 34.082, -82.58, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'County comms reported multiple trees and power lines blown down in the Calhoun Falls area. Media also reported roof damage to a church.');
INSERT INTO public.stormevents_east VALUES (769845, 201806, 26, 1632, 201806, 26, 1632, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '26-JUN-18 16:32:00', 'EST-5', '26-JUN-18 16:32:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'NE', 'EKOM', 2, 'NE', 'EKOM', 34.45, -82.11, 34.45, -82.11, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'Public reported quarter size hail on Ekom Beach Rd.');
INSERT INTO public.stormevents_east VALUES (769846, 201806, 26, 1326, 201806, 26, 1326, 128257, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '26-JUN-18 13:26:00', 'EST-5', '26-JUN-18 13:26:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 0.75, NULL, NULL, NULL, 4, 'N', 'TAMASSEE', 4, 'N', 'TAMASSEE', 34.931, -83.016, 34.931, -83.016, 'Scattered thunderstorms developed across the high terrain of the Upstate during the afternoon and moved southeast. Some of the storms organized into small clusters that produced locally damaging winds.', 'Ham radio operator reported penny size hail on North Little River Rd.');
INSERT INTO public.stormevents_east VALUES (770533, 201806, 14, 1514, 201806, 14, 1514, 128430, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '14-JUN-18 15:14:00', 'EST-5', '14-JUN-18 15:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ESE', 'SUNSET', 3, 'ESE', 'SUNSET', 34.96, -82.743, 34.96, -82.743, 'Isolated to widely scattered thunderstorms developed across the Carolina Blue Ridge during the afternoon and drifted south. One storm produced a brief damaging wind gust in Pickens County.', 'County comms reported a tree and a power line blown down on Highway 178 at Cove Creek Road.');
INSERT INTO public.stormevents_east VALUES (782914, 201808, 14, 1845, 201808, 14, 2300, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 18:45:00', 'EST-5', '14-AUG-18 23:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'LANGDON', 1, 'S', 'LANGDON', 42.05, -75.83, 42.0493, -75.8249, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flash flooding was reported along Carlin Creek. Water was entering homes.');
INSERT INTO public.stormevents_east VALUES (782945, 201808, 14, 1840, 201808, 14, 2300, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 18:40:00', 'EST-5', '14-AUG-18 23:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'OWEGO', 1, 'NE', 'OWEGO', 42.1098, -76.2771, 42.1152, -76.2524, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Flash flooding trapped people in homes.');
INSERT INTO public.stormevents_east VALUES (782948, 201808, 14, 1322, 201808, 14, 1400, 130512, 'NEW YORK', 36, 2018, 'August', 'Flash Flood', 'BGM', '14-AUG-18 13:22:00', 'EST-5', '14-AUG-18 14:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'NICHOLS', 2, 'SE', 'NICHOLS', 42.0011, -76.3728, 41.9993, -76.3325, 'A slow moving storm tracked north from New Jersey to northern New York. This system triggered several rounds of heavy rain producing thunderstorms which caused severe flash flooding and major damages in several locations.', 'Wappasening Creek was flooding out Route 282 near the NY/PA border.');
INSERT INTO public.stormevents_east VALUES (753903, 201805, 14, 1628, 201805, 14, 1628, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:28:00', 'EST-5', '14-MAY-18 16:28:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NE', 'STEPHENS CITY', 2, 'NE', 'STEPHENS CITY', 39.0996, -78.1919, 39.0996, -78.1919, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down near the intersection of Tasker Road and Lakeside Drive.');
INSERT INTO public.stormevents_east VALUES (754925, 201806, 24, 1528, 201806, 24, 1528, 125921, 'TENNESSEE', 47, 2018, 'June', 'Thunderstorm Wind', 'MRX', '24-JUN-18 15:28:00', 'EST-5', '24-JUN-18 15:28:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'ENE', 'NEW MARKET', 2, 'ENE', 'NEW MARKET', 36.11, -83.52, 36.11, -83.52, 'A rather small thunderstorm complex which originated across Arkansas earlier in the day made steady progress across the Tennessee Valley of Alabama and into Southeast Tennessee and Southwest North Carolina producing damaging winds along its path.', 'A few trees were reported down near the dispatch center.');
INSERT INTO public.stormevents_east VALUES (754927, 201806, 24, 1605, 201806, 24, 1605, 125921, 'TENNESSEE', 47, 2018, 'June', 'Thunderstorm Wind', 'MRX', '24-JUN-18 16:05:00', 'EST-5', '24-JUN-18 16:05:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'PARROTTSVILLE', 1, 'NW', 'PARROTTSVILLE', 36.01, -83.09, 36.01, -83.09, 'A rather small thunderstorm complex which originated across Arkansas earlier in the day made steady progress across the Tennessee Valley of Alabama and into Southeast Tennessee and Southwest North Carolina producing damaging winds along its path.', 'Several trees were reported down near Parrottsville.');
INSERT INTO public.stormevents_east VALUES (758588, 201805, 17, 1711, 201805, 17, 1900, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 17:11:00', 'EST-5', '17-MAY-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'MT CLIFTON', 1, 'NW', 'MT CLIFTON', 38.7564, -78.7122, 38.7611, -78.7151, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'Two feet of water over Garber Road alongside Mill Creek, rendering the roadway impassible.');
INSERT INTO public.stormevents_east VALUES (758590, 201805, 17, 26, 201805, 17, 1415, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 00:26:00', 'EST-5', '17-MAY-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'WADESVILLE', 1, 'NNW', 'WADESVILLE', 39.2232, -78.0647, 39.2658, -78.0393, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'The stream gauge on Opequon Creek near Berryville exceeded the 10 foot flood stage during the indicated times. The peak observed was 11.54 feet at 8:30am EST on May 17th. At the observed levels, Old Charles Town Road is flooded.');
INSERT INTO public.stormevents_east VALUES (759258, 201805, 19, 1400, 201805, 19, 1500, 126452, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 14:00:00', 'EST-5', '19-MAY-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ADEN', 1, 'ESE', 'ADEN', 38.6426, -77.514, 38.6426, -77.5102, 'Heavy rain of 1-3 inches fell during the evening and overnight of May 18th into May 19th along and east of the Blue Ridge Mountains. This prompted flooding in the region, mainly of streams. Some of the stream flooding lasted into the 20th, especially on larger rivers.', 'The stream gage on Cedar Run near Aden exceeded the 10 foot flood stage during the times indicated. The peak level of 10.06 feet occurred at 2:25pm EST on May 19th. Emergency management confirmed Aden Road was flooded with around 6 inches of water near the gage location.');
INSERT INTO public.stormevents_east VALUES (759979, 201805, 26, 1859, 201805, 26, 2100, 126457, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '26-MAY-18 18:59:00', 'EST-5', '26-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LAGRANGE', 1, 'NNW', 'LAGRANGE', 38.4681, -77.8616, 38.4666, -77.8604, 'Scattered heavy afternoon thunderstorms produced 1-2 inches of rain, causing flooding in a few different locations in northern Virginia.', 'Carrico Mills Road flooded and closed near Mountain Run.');
INSERT INTO public.stormevents_east VALUES (759980, 201805, 26, 1417, 201805, 26, 1600, 126457, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '26-MAY-18 14:17:00', 'EST-5', '26-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'HUNTLY', 2, 'SSE', 'HUNTLY', 38.809, -78.1079, 38.8049, -78.1073, 'Scattered heavy afternoon thunderstorms produced 1-2 inches of rain, causing flooding in a few different locations in northern Virginia.', 'A portion of US Highway 522 was flooded and closed due to rapidly rising water near Huntly.');
INSERT INTO public.stormevents_east VALUES (758585, 201805, 17, 1445, 201805, 17, 1645, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 14:45:00', 'EST-5', '17-MAY-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'CASKIE', 1, 'SSW', 'CASKIE', 37.5428, -78.8391, 37.5391, -78.8387, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'Gladstone Road and Caskie Drive both flooded and closed near Gladstone.');
INSERT INTO public.stormevents_east VALUES (750355, 201806, 10, 2152, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PHI', '10-JUN-18 21:52:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BIRDSBORO', 0, 'E', 'BIRDSBORO', 40.27, -75.82, 40.2696, -75.8164, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on Jackson Street and West Main Street in Birdsboro.');
INSERT INTO public.stormevents_east VALUES (751349, 201806, 9, 1445, 201806, 9, 1645, 125267, 'DELAWARE', 10, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 14:45:00', 'EST-5', '09-JUN-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'SEAFORD', 2, 'W', 'SYCAMORE', 38.642, -75.5672, 38.5958, -75.5222, 'Heavy rain fell in southern Delaware on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'Several roads were flooded from Concord to Sycamore.');
INSERT INTO public.stormevents_east VALUES (751273, 201806, 9, 1345, 201806, 9, 1545, 125268, 'NEW JERSEY', 34, 2018, 'June', 'Flash Flood', 'PHI', '09-JUN-18 13:45:00', 'EST-5', '09-JUN-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'BRIDGETON', 2, 'NW', 'BRIDGETON', 39.4163, -75.258, 39.4437, -75.2536, 'Heavy rain fell in Cumberland County on the afternoon of June 9, 2018.  Rainfall totals up to 3 to 5 inches occurred in a short period of time.', 'Widespread roadway flooding occurred from Bridgeton to Millville.  Many vehicles were stranded in the flood waters.');
INSERT INTO public.stormevents_east VALUES (750353, 201806, 10, 2130, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PHI', '10-JUN-18 21:30:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BRIDESBURG', 1, 'NW', 'BRIDESBURG', 40.0089, -75.0755, 40.0055, -75.0795, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Lane Closures on I-95 and I-76.');
INSERT INTO public.stormevents_east VALUES (750354, 201806, 10, 2145, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PHI', '10-JUN-18 21:45:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'ELAM', 1, 'W', 'ELAM', 39.8547, -75.5466, 39.85, -75.5423, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Lane closures on Route 202 between Carter Way and Smithbridge Road.');
INSERT INTO public.stormevents_east VALUES (750356, 201806, 10, 2200, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PHI', '10-JUN-18 22:00:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'ANGELICA', 1, 'ENE', 'MOHNTON', 40.28, -75.96, 40.2841, -75.9622, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding near intersection of Church Road and Oregon Road where Angelica Creek passes through.');
INSERT INTO public.stormevents_east VALUES (750357, 201806, 10, 2218, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flood', 'PHI', '10-JUN-18 22:18:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'MONTELLO', 1, 'E', 'FRITZTOWN', 40.31, -76.05, 40.303, -76.044, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on Fritztown Road and surrounding streets in Spring Township.');
INSERT INTO public.stormevents_east VALUES (752598, 201806, 21, 1200, 201806, 21, 1200, 125468, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'MLB', '21-JUN-18 12:00:00', 'EST-5', '21-JUN-18 12:00:00', 0, 0, 0, 0, '275.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'WSW', 'HARBOR PT', 1, 'WSW', 'HARBOR PT', 29.114, -81.0203, 29.114, -81.0203, 'Central Florida was wedged between a high pressure ridge axis to the south, and a weak low pressure trough to the north. This resulted in strong west flow in the low-levels across east central Florida, and allowed deep moisture to remain in place across the area with Precipitable Water values near 2 inches. Scattered showers and thunderstorms developed during the afternoon and evening hours, mainly along the quickly progressing west coast sea breeze. The strong west winds delayed the development of the east coast sea breeze by a few hours, but by mid-afternoon the sea breeze had developed in Brevard County. Showers and thunderstorms began to develop along the slowly advancing sea breeze. Further south, in Indian River County, a thunderstorm there produced a northward moving outflow boundary that pushed into Brevard County and interacted with the sea breeze. This caused enhanced lift just along the sea breeze over Melbourne, and a severe thunderstorm quickly developed. This storm produced a severe wind gust in Melbourne Beach. In Port Orange, a home was destroyed after being struck by lightning and catching fire.', 'Per a report received from a local broadcast media: a Port Orange home caught fire and was destroyed after being struck by lightning. The home located on Stewart Avenue, north of Taylor Road, was fully engulfed by flames when fire fighters arrived on scene. The blaze began in the garage area of the home and burned two vehicles before spreading to the rest of the property. The homeowner was working in his shed in the backyard when the lightning strike occurred, though he was uninjured. When Florida Power and Light inspected the home after the blaze, they found the plastic meter was melted and hanging off, another sign the home was struck by lightning. Unfortunately, the owner''s two pet cats were killed in the blaze.');
INSERT INTO public.stormevents_east VALUES (752606, 201806, 23, 1450, 201806, 23, 1450, 125491, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '23-JUN-18 14:50:00', 'EST-5', '23-JUN-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 43, 'MG', NULL, NULL, 6, 'N', 'MERRITT ISLAND', 6, 'N', 'MERRITT ISLAND', 28.44, -80.71, 28.44, -80.71, 'Light southwest flow was in place across central Florida as the surface high pressure ridge axis resided over the Florida Keys. Aloft, the upper-level ridge axis was located over north central Florida, and a mid-level ridge was located over the southern Peninsula, which resulted in very weak to little steering flow winds across the area. With weaker west winds, the east coast sea breeze was allowed to develop earlier, and showers and thunderstorms formed along the sea breeze near the Brevard County coast. In combination with many outflow boundaries, one thunderstorm produced a waterspout in Titusville. Strong thunderstorms then developed in central and south Brevard County, where strong winds were observed in Melbourne and Merritt Island.|||Offshore flow |looks to be a little weaker, meaning the ECSB will likely form an |hour or two earlier and ease its way inland a little faster/farther.|Steering winds will be weaker and a little more veered than Friday''s|westerly 8-12KT steering flow. H850-H50 winds average around 5KT,|veering from W-NW to northerly late in the day. This should limit|the eastward push of convection toward the east coast, with activity |more likely to be a bit early, along the ECSB there, and a little |later inland.', 'A trained spotter measured a 43 knot or 50 mph wind gust on Merritt Island.');
INSERT INTO public.stormevents_east VALUES (755107, 201806, 27, 2345, 201806, 27, 2347, 125735, 'PENNSYLVANIA', 42, 2018, 'June', 'Tornado', 'CTP', '27-JUN-18 23:45:00', 'EST-5', '27-JUN-18 23:47:00', 0, 0, 0, 0, '50.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NNW', 'PIKETOWN', 2, 'NNE', 'PIKETOWN', 40.3868, -76.7529, 40.402, -76.731, 'An EF1 tornado was confirmed by a NWS survey team to have touched down in east-central Dauphin County. The path length was approximately 1.6 miles, with a path width of 100 yards and a maximum wind speed of 100 mph. The tornado began at the intersection of Piketown Road and Appalachian Trail and ended 200 yards west of the Full Gospel Mission Church on Fishing Creek Valley Road. Hundreds of trees were snapped and uprooted along its path. The downed trees caused damage to the roofs of 4 homes, as well as several sheds.', 'An EF-1 tornado touched down near Piketown in Dauphin Count. The tornado had a path length of approximately 1.6 miles and a max path width of approximately 100 yards. Max winds were estimated around 100 mph.  Hundreds of trees were uprooted or snapped, and downed trees caused damage to the roofs of 4 homes and several sheds.');
INSERT INTO public.stormevents_east VALUES (754372, 201806, 9, 1638, 201806, 9, 1648, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:38:00', 'EST-5', '09-JUN-18 16:48:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'ESE', 'BOWLUSVILLE', 2, 'ESE', 'BOWLUSVILLE', 40.0089, -83.7752, 40.0089, -83.7752, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A large tree limb broke off a tree and fell on a car on Willow Chase Circle.');
INSERT INTO public.stormevents_east VALUES (749660, 201806, 9, 1638, 201806, 9, 1648, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:38:00', 'EST-5', '09-JUN-18 16:48:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'ESE', 'BOWLUSVILLE', 2, 'ESE', 'BOWLUSVILLE', 40.0077, -83.7721, 40.0077, -83.7721, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'A large tree was snapped near the base along Winfield Drive.');
INSERT INTO public.stormevents_east VALUES (749666, 201806, 9, 1642, 201806, 9, 1652, 124993, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '09-JUN-18 16:42:00', 'EST-5', '09-JUN-18 16:52:00', 0, 0, 0, 0, '15.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NNE', 'VILLA', 1, 'NNE', 'VILLA', 39.99, -83.76, 39.99, -83.76, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.', 'Several full size trees were knocked down near the intersection of Middle Urbana Road and Moorefield Road. Also some power lines and traffic signals were knocked down, and a house had some shingle damage to its roof.');
