INSERT INTO public.stormevents_east VALUES (749490, 201806, 8, 1712, 201806, 8, 1912, 124954, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '08-JUN-18 17:12:00', 'EST-5', '08-JUN-18 19:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'SEAMAN', 0, 'ENE', 'SEAMAN', 38.93, -83.56, 38.931, -83.5638, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'High water was reported over the road.');
