INSERT INTO public.stormevents_east VALUES (762529, 201806, 2, 1445, 201806, 2, 1745, 127218, 'MARYLAND', 24, 2018, 'June', 'Flash Flood', 'AKQ', '02-JUN-18 14:45:00', 'EST-5', '02-JUN-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'PRINCESS ANNE', 1, 'E', 'PRINCESS ANNE', 38.2015, -75.6943, 38.2017, -75.6887, 'Scattered showers and thunderstorms in advance of and along a frontal boundary produced heavy rain which caused flash flooding across portions of the Lower Maryland Eastern Shore.', 'Street flooding was reported at Antioch Avenue and Hampton, and at South Street and Somerset Avenue.');
INSERT INTO public.stormevents_east VALUES (765735, 201806, 22, 910, 201806, 22, 1200, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 09:10:00', 'EST-5', '22-JUN-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ADVANCE MILLS', 2, 'N', 'ADVANCE MILLS', 38.2, -78.45, 38.2021, -78.4493, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Bridge washed out in the 1500 block of Durrett Ridge Road.');
INSERT INTO public.stormevents_east VALUES (765736, 201806, 22, 934, 201806, 22, 1130, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 09:34:00', 'EST-5', '22-JUN-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'STONY PT', 1, 'NW', 'STONY PT', 38.1352, -78.3931, 38.1349, -78.3932, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Watts Passage flooded and impassable near Preddy Creek.');
INSERT INTO public.stormevents_east VALUES (765737, 201806, 22, 1100, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:00:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'LOGAN', 3, 'E', 'LOGAN', 38.2207, -77.716, 38.2203, -77.7159, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Flooding near the intersection of Catharpin Road and Pamunkey Road caused a road closure.');
INSERT INTO public.stormevents_east VALUES (765738, 201806, 22, 1100, 201806, 22, 1300, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:00:00', 'EST-5', '22-JUN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'FALMOUTH', 1, 'SE', 'FALMOUTH', 38.309, -77.4592, 38.3087, -77.4588, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'River Road flooded and closed near Falmouth.');
INSERT INTO public.stormevents_east VALUES (765739, 201806, 22, 1100, 201806, 22, 1300, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:00:00', 'EST-5', '22-JUN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'FERRY FARMS', 1, 'WNW', 'FERRY FARMS', 38.3293, -77.4499, 38.3292, -77.4489, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Harrell Road flooded and closed at Claiborne Run.');
INSERT INTO public.stormevents_east VALUES (769101, 201806, 22, 1125, 201806, 22, 1210, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:25:00', 'EST-5', '22-JUN-18 12:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'NEW MARKET', 2, 'SSE', 'NEW MARKET', 38.6276, -78.6642, 38.6273, -78.6636, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on Smith Creek near New Market exceeded the 8 foot flood stage briefly during the indicated period. Roads were flooded along the creek for a short time.');
INSERT INTO public.stormevents_east VALUES (769102, 201806, 22, 1535, 201806, 24, 602, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 15:35:00', 'EST-5', '24-JUN-18 06:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'REMINGTON', 1, 'WSW', 'REMINGTON', 38.5358, -77.8047, 38.5253, -77.8158, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on the Rappahannock River at Remington exceeded the 15 foot flood stage during the indicated period. The peak level of 23.10 feet occurred at 8:00pm EST on June 22nd. Significant flooding was reported with water in a couple homes and numerous roads closed.');
INSERT INTO public.stormevents_east VALUES (769105, 201806, 22, 814, 201806, 24, 215, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 08:14:00', 'EST-5', '24-JUN-18 02:15:00', 0, 0, 0, 0, '100.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'MONUMENT MILLS', 0, 'SW', 'MONUMENT MILLS', 38.6036, -78.0105, 38.5953, -78.0059, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on Hazel River near Rixeyville exceeded the 16 foot flood stage during the indicated period. The gage was washed away during the height of the flood, which was at least 10 feet over the flood stage. Significant flooding was reported in the Monumental Mills area, with homes and roads flooded.');
INSERT INTO public.stormevents_east VALUES (791786, 201812, 14, 1950, 201812, 14, 1950, 132328, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '14-DEC-18 19:50:00', 'EST-5', '14-DEC-18 19:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'N', 'ANTHONY', 1, 'N', 'ANTHONY', 29.31, -82.12, 29.31, -82.12, 'Flood watch was in effect due to above normal moisture in place across the region ahead of a very strong, long wave trough storm system over the MS River Valley. The associated warm front was draped along the FL-GA stateline, which provide a focus for widespread heavy rainfall.', 'Daily rainfall of 5.5-6 inches of rainfall was measured near Anthony.');
INSERT INTO public.stormevents_east VALUES (791787, 201812, 14, 1, 201812, 14, 1956, 132328, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '14-DEC-18 00:01:00', 'EST-5', '14-DEC-18 19:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 1, 'S', 'FT MC COY', 1, 'S', 'FT MC COY', 29.36, -81.97, 29.36, -81.97, 'Flood watch was in effect due to above normal moisture in place across the region ahead of a very strong, long wave trough storm system over the MS River Valley. The associated warm front was draped along the FL-GA stateline, which provide a focus for widespread heavy rainfall.', 'Daily rainfall of 4.25 inches was measured near Fort McCoy since early morning.');
INSERT INTO public.stormevents_east VALUES (765384, 201806, 8, 1820, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 18:20:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'ROSWELL', 1, 'WNW', 'ROSWELL', 40.4833, -81.3619, 40.482, -81.3622, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'The 5000 block of Echo Lake Road was reported as impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (782854, 201808, 4, 155, 201808, 4, 429, 129459, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '04-AUG-18 01:55:00', 'EST-5', '04-AUG-18 04:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'FINKSBURG', 0, 'SSW', 'FINKSBURG', 39.4897, -76.9035, 39.4957, -76.9024, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'The USGS stream gage on Beaver Run near Finksburg rapidly went from falling stages to above flood stage. The stream was above flood stage during the indicated period, with three different peaks. The highest level was 5.48 feet at 3:00am EST. Hughes Road flooded during this event.');
INSERT INTO public.stormevents_east VALUES (775237, 201808, 2, 2255, 201808, 3, 30, 129382, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '02-AUG-18 22:55:00', 'EST-5', '03-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'FRANKLIN', 0, 'E', 'LUKE', 39.49, -79.04, 39.4799, -79.0424, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'Numerous roads were blocked by high water in Westernport. Some roads were washed out.');
INSERT INTO public.stormevents_east VALUES (775238, 201808, 2, 2255, 201808, 3, 30, 129382, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '02-AUG-18 22:55:00', 'EST-5', '03-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'BARTON', 0, 'NE', 'MORRISONS', 39.5325, -79.0099, 39.5248, -79.0154, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'A mudslide was reported along MD-36 near Barton.');
INSERT INTO public.stormevents_east VALUES (751790, 201806, 18, 1743, 201806, 18, 1743, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:43:00', 'EST-5', '18-JUN-18 17:43:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'S', 'NEWBURYPORT', 1, 'S', 'NEWBURYPORT', 42.8059, -70.8689, 42.8059, -70.8689, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:43 PM EST two trees were down on High Street near Newburyport High School.');
INSERT INTO public.stormevents_east VALUES (751791, 201806, 18, 1745, 201806, 18, 1745, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:45:00', 'EST-5', '18-JUN-18 17:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'W', 'HAVERHILL ARPT', 1, 'W', 'HAVERHILL ARPT', 42.7987, -71.0855, 42.7987, -71.0855, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:45 PM EST, a tree was down on the backyard of a residence on Winona Avenue. This caused damage to the siding of the house and knocked down the fence.');
INSERT INTO public.stormevents_east VALUES (751792, 201806, 18, 1745, 201806, 18, 1745, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:45:00', 'EST-5', '18-JUN-18 17:45:00', 0, 0, 0, 0, '12.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NNW', 'NEWBURY', 1, 'NNW', 'NEWBURY', 42.8143, -71.0053, 42.8143, -71.0053, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:45 PM EST a tree was down on a car on Valley Street in Merrimac.');
INSERT INTO public.stormevents_east VALUES (751794, 201806, 18, 1748, 201806, 18, 1748, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:48:00', 'EST-5', '18-JUN-18 17:48:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'ESE', 'NEWBURY', 2, 'ESE', 'NEWBURY', 42.791, -70.9664, 42.791, -70.9664, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:48 PM EST, a tree and wires were down on Middle Street in West Newbury.');
INSERT INTO public.stormevents_east VALUES (751797, 201806, 18, 1753, 201806, 18, 1753, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:53:00', 'EST-5', '18-JUN-18 17:53:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'N', 'LINEBROOK', 1, 'N', 'LINEBROOK', 42.6921, -70.927, 42.6921, -70.927, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:53 PM EST, a tree and wires were down on Leslie Road in Ipswich, and on Lymick Road in Ipswich.');
INSERT INTO public.stormevents_east VALUES (751799, 201806, 18, 1754, 201806, 18, 1754, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:54:00', 'EST-5', '18-JUN-18 17:54:00', 0, 0, 0, 0, '16.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'ENE', 'AMESBURY', 1, 'ENE', 'AMESBURY', 42.8558, -70.9119, 42.8558, -70.9119, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:54 PM EST, a tree came down on a pickup truck on Monroe Street in Amesbury.');
INSERT INTO public.stormevents_east VALUES (763059, 201806, 25, 1415, 201806, 25, 1418, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 14:15:00', 'EST-5', '25-JUN-18 14:18:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 55, 'EG', NULL, NULL, 3, 'WSW', 'HAMMOND XRDS', 3, 'WSW', 'HAMMOND XRDS', 33.73, -80.93, 33.73, -80.93, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Tree down in the eastbound lanes of I-26 near mile marker 133.');
INSERT INTO public.stormevents_east VALUES (763076, 201806, 25, 1820, 201806, 25, 1825, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:20:00', 'EST-5', '25-JUN-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 7, 'NW', 'HAMMOND XRDS', 7, 'NW', 'HAMMOND XRDS', 33.81, -80.98, 33.81, -80.98, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Numerous trees down in the Sandy Run community.');
INSERT INTO public.stormevents_east VALUES (763077, 201806, 25, 2001, 201806, 25, 2005, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 20:01:00', 'EST-5', '25-JUN-18 20:05:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'WSW', 'HAMMOND XRDS', 3, 'WSW', 'HAMMOND XRDS', 33.74, -80.9352, 33.74, -80.9352, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'SCHP reported trees down on Wannaridge Rd at Big Beaver Creek Rd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (763078, 201806, 25, 1554, 201806, 25, 1558, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 15:54:00', 'EST-5', '25-JUN-18 15:58:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 4, 'NE', 'WOODWARD', 4, 'NE', 'WOODWARD', 34.55, -81.12, 34.55, -81.12, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Several large limbs down along Dawkinsville Rd near the Blackstock community.');
INSERT INTO public.stormevents_east VALUES (763079, 201806, 25, 1514, 201806, 25, 1517, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 15:14:00', 'EST-5', '25-JUN-18 15:17:00', 0, 0, 0, 0, NULL, NULL, 'COOP Observer', 50, 'EG', NULL, NULL, 3, 'NNE', 'LONGTOWN', 3, 'NNE', 'LONGTOWN', 34.39, -80.81, 34.39, -80.81, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'A tree was down across River Rd.');
INSERT INTO public.stormevents_east VALUES (763080, 201806, 25, 1534, 201806, 25, 1537, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 15:34:00', 'EST-5', '25-JUN-18 15:37:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'ROCKTON', 1, 'N', 'ROCKTON', 34.36, -81.08, 34.36, -81.08, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Tree down on Holly St in Winnsboro Mills.');
INSERT INTO public.stormevents_east VALUES (763082, 201806, 25, 1910, 201806, 25, 1915, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:10:00', 'EST-5', '25-JUN-18 19:15:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 3, 'NNW', 'RICHTEX', 3, 'NNW', 'RICHTEX', 34.22, -81.2, 34.22, -81.2, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Trees and power lines down throughout the Fairfield Co.');
INSERT INTO public.stormevents_east VALUES (763083, 201806, 25, 1830, 201806, 25, 1830, 126890, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:30:00', 'EST-5', '25-JUN-18 18:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 51, 'MG', NULL, NULL, 6, 'ENE', 'POLLARDS CORNER', 6, 'ENE', 'POLLARDS CORNER', 33.6594, -82.195, 33.6594, -82.195, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Clarks Hill GA Mesonet station reported a wind gust of 59 mph.');
INSERT INTO public.stormevents_east VALUES (753854, 201805, 12, 2053, 201805, 12, 2053, 125698, 'MARYLAND', 24, 2018, 'May', 'Hail', 'LWX', '12-MAY-18 20:53:00', 'EST-5', '12-MAY-18 20:53:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 1, 'ENE', 'LA PLATA', 1, 'ENE', 'LA PLATA', 38.5341, -76.9705, 38.5341, -76.9705, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (763498, 201806, 1, 2140, 201806, 1, 2330, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:40:00', 'EST-5', '01-JUN-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'SLANESVILLE', 1, 'N', 'SLANESVILLE', 39.3796, -78.5307, 39.3792, -78.5287, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Slanesville Pike flooded and closed near Slanesville.');
INSERT INTO public.stormevents_east VALUES (763499, 201806, 1, 2140, 201806, 1, 2330, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:40:00', 'EST-5', '01-JUN-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'SPRINGFIELD', 0, 'NE', 'SPRINGFIELD', 39.4535, -78.6971, 39.4532, -78.6969, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Springfield Pike flooded and closed near Springfield.');
INSERT INTO public.stormevents_east VALUES (763503, 201806, 1, 2140, 201806, 1, 2330, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:40:00', 'EST-5', '01-JUN-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 5, 'NW', 'BLOOMER', 4, 'NW', 'BLOOMER', 39.4239, -78.4426, 39.423, -78.4403, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Paw Paw Road flooded and closed near Forks of Cacapon.');
INSERT INTO public.stormevents_east VALUES (763504, 201806, 1, 2140, 201806, 1, 2330, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:40:00', 'EST-5', '01-JUN-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'LEVELS', 2, 'WSW', 'LEVELS', 39.4669, -78.58, 39.4669, -78.5786, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Jersey Mountain Road flooded and closed between Levels and Points.');
INSERT INTO public.stormevents_east VALUES (763506, 201806, 1, 2145, 201806, 1, 2345, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:45:00', 'EST-5', '01-JUN-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'PAW PAW', 1, 'E', 'PAW PAW', 39.5276, -78.4534, 39.5284, -78.4508, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Several roads flooded and closed near Paw Paw.');
INSERT INTO public.stormevents_east VALUES (763507, 201806, 1, 2145, 201806, 1, 2345, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 21:45:00', 'EST-5', '01-JUN-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'OMPS', 1, 'W', 'OMPS', 39.5007, -78.2931, 39.5002, -78.2924, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'US 522 flooded near the entrance to Cacapon State Park.');
INSERT INTO public.stormevents_east VALUES (769087, 201806, 3, 1508, 201806, 3, 1838, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 15:08:00', 'EST-5', '03-JUN-18 18:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'PAW PAW', 1, 'NE', 'PAW PAW', 39.5373, -78.4566, 39.5425, -78.4556, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Potomac River at Paw Paw exceeded the 25 foot flood stage during the indicated period. The peak level of 25.24 feet occurred at 4:15pm EST on June 3rd. At these levels, flooding occurs of a riverside parking area, and flooding occurs nearby along the C&O Canal.');
INSERT INTO public.stormevents_east VALUES (769088, 201806, 3, 2018, 201806, 5, 1048, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 20:18:00', 'EST-5', '05-JUN-18 10:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'SHEPHERDSTOWN', 2, 'NE', 'MOLER XRDS', 39.43, -77.8, 39.4188, -77.7428, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the Potomac River at Shepherdstown exceeded the 15 foot flood stage during the indicated period. The peak level of 23.15 feet was observed at 4:15pm on June 4th. River Road was flooded along the Potomac downstream of Shepherdstown, along with significant portions of the C&O Canal Towpath and some area structures.');
INSERT INTO public.stormevents_east VALUES (769089, 201806, 3, 608, 201806, 4, 812, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 06:08:00', 'EST-5', '04-JUN-18 08:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'MILLESONS MILL', 1, 'S', 'MILLESONS MILL', 39.4206, -78.6856, 39.4187, -78.6823, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'The stream gage on the South Branch Potomac River at Springfield exceeded the 15 foot flood stage during the indicated period. The peak level of 17.49 feet occurred at 2:15pm EST on June 3rd. Milleson Mill Road and Clarence Taylor Road were both flooded, along with farmland near the river. Water was nearing camphouses along the river.');
INSERT INTO public.stormevents_east VALUES (769090, 201806, 3, 1419, 201806, 3, 1928, 127380, 'DISTRICT OF COLUMBIA', 11, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 14:19:00', 'EST-5', '03-JUN-18 19:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'WALTER REED', 1, 'SW', 'WALTER REED', 38.9684, -77.0467, 38.9714, -77.0449, 'Heavy rain around 3 inches fell just north of Washington DC on June 3rd, causing flooding in the Rock Creek area of the District.', 'The stream gage on Rock Creek in Rock Creek Park exceeded the 7 foot flood stage during the indicated period. The peak level of 8.57 feet occurred at 4:45pm on June 3rd. Portions of Rock Creek Park were flooded within Washington DC.');
INSERT INTO public.stormevents_east VALUES (769111, 201806, 24, 326, 201806, 24, 1203, 127377, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '24-JUN-18 03:26:00', 'EST-5', '24-JUN-18 12:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 5, 'WSW', 'POOLESVILLE', 4, 'SW', 'WHITES FERRY', 39.1269, -77.5131, 39.1557, -77.5155, 'Heavy rain upstream caused minor flooding on a portion of the Potomac River on June 24th.', 'The stream gage on the Potomac River at Edwards Ferry exceeded the 15 foot flood stage during the indicated period. The peak level of 15.20 feet occurred at 7:15am EST on June 24th. The boat ramp and parking area at Edwards Ferry were inundated by floodwaters.');
INSERT INTO public.stormevents_east VALUES (769112, 201806, 22, 2016, 201806, 23, 950, 127378, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 20:16:00', 'EST-5', '23-JUN-18 09:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'GREAT CACAPON', 1, 'SW', 'GREAT CACAPON', 39.5828, -78.3158, 39.6099, -78.2925, 'Heavy rain over a two day period caused flooding across eastern West Virginia on June 22nd into the 23rd. Then, the combination of upstream rainfall caused river flooding on the 23rd and 24th.', 'The stream gage on the Cacapon River near Great Cacapon exceeded the 9 foot flood stage during the indicated period. The peak of 11.38 feet was observed at 1:15am EST on June 23rd. Rock Ford Road and Powerhouse Road were both flooded.');
INSERT INTO public.stormevents_east VALUES (768864, 201806, 22, 2006, 201806, 22, 2006, 128191, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 20:06:00', 'EST-5', '22-JUN-18 20:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'MG', NULL, NULL, 0, 'N', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 0, 'N', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 36.98, -76.32, 36.98, -76.32, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the James River.', 'Wind gust of 44 knots was measured at Willoughby Degaussing Station.');
INSERT INTO public.stormevents_east VALUES (768866, 201806, 22, 2312, 201806, 22, 2312, 128191, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 23:12:00', 'EST-5', '22-JUN-18 23:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'MG', NULL, NULL, 0, 'N', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 0, 'N', 'WILLOUGHBY DEGAUSSING STATION WLON (WDSV2)', 36.98, -76.32, 36.98, -76.32, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the James River.', 'Wind gust of 44 knots was measured at Willoughby Degaussing Station.');
INSERT INTO public.stormevents_east VALUES (768867, 201806, 22, 2312, 201806, 22, 2312, 128191, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '22-JUN-18 23:12:00', 'EST-5', '22-JUN-18 23:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 2, 'ESE', 'DOMINION TERMINAL ASSOCIATES WLON (DOMV2)', 36.95, -76.39, 36.95, -76.39, 'Scattered thunderstorms along a warm frontal boundary produced gusty winds across portions of the James River.', 'Wind gust of 42 knots was measured at Middle Ground Lighthouse.');
INSERT INTO public.stormevents_east VALUES (769400, 201806, 23, 1827, 201806, 23, 1827, 128286, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '23-JUN-18 18:27:00', 'EST-5', '23-JUN-18 18:27:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 4, 'WNW', 'MAYOCK', 4, 'WNW', 'MAYOCK', 36.55, -76.24, 36.55, -76.24, 'Isolated severe thunderstorm in advance of a frontal boundary produced damaging winds  across portions of northeast North Carolina.', 'Large tree was downed onto power lines near Backwoods Road.');
INSERT INTO public.stormevents_east VALUES (769401, 201806, 23, 1354, 201806, 23, 1354, 128287, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '23-JUN-18 13:54:00', 'EST-5', '23-JUN-18 13:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 0, 'N', 'DELTAVILLE', 0, 'N', 'DELTAVILLE', 37.56, -76.29, 37.56, -76.29, 'Scattered thunderstorms in advance of a frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 39 knots was measured at Deltaville.');
INSERT INTO public.stormevents_east VALUES (769404, 201806, 23, 1428, 201806, 23, 1428, 128287, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'AKQ', '23-JUN-18 14:28:00', 'EST-5', '23-JUN-18 14:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'ONANCOCK', 0, 'N', 'ONANCOCK', 37.65, -75.9, 37.65, -75.9, 'Scattered thunderstorms in advance of a frontal boundary produced gusty winds across portions of the Chesapeake Bay.', 'Wind gust of 37 knots was measured at Onancock.');
INSERT INTO public.stormevents_east VALUES (769688, 201806, 24, 2018, 201806, 24, 2018, 128290, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 20:18:00', 'EST-5', '24-JUN-18 20:18:00', 0, 0, 0, 0, '35.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'AHOSKIE', 1, 'NW', 'AHOSKIE', 36.29, -76.99, 36.29, -76.99, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of northeast North Carolina.', 'Numerous trees were downed. A couple of houses had numerous shingles blown off. A baseball field dugout was destroyed. A carport was damaged.');
INSERT INTO public.stormevents_east VALUES (769689, 201806, 24, 2020, 201806, 24, 2020, 128290, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'AKQ', '24-JUN-18 20:20:00', 'EST-5', '24-JUN-18 20:20:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'NNE', 'SUNBURY', 2, 'NNE', 'SUNBURY', 36.46, -76.61, 36.46, -76.61, 'Scattered severe thunderstorms in advance of a cold front produced damaging winds across portions of northeast North Carolina.', 'Trees were downed along Savage Road, just off Highway 32 between Corapeake and Sunbury. Numerous power outages were also reported in the area.');
INSERT INTO public.stormevents_east VALUES (768104, 201806, 1, 2150, 201806, 1, 2330, 128077, 'NEW YORK', 36, 2018, 'June', 'Flash Flood', 'BGM', '01-JUN-18 21:50:00', 'EST-5', '01-JUN-18 23:30:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'WNW', 'ATLANTA', 3, 'NNE', 'HASKINVILLE', 42.565, -77.532, 42.459, -77.541, 'Scattered, slow moving thunderstorms developed over portions of central New York during the afternoon and evening of June 1st. Thunderstorms became attached to the hillsides in Steuben county, bringing 1 to 2 inches of locally heavy rainfall in less than an hour to rural areas in the north half of the county. Local drainage become overwhelmed by the excessive rainfall. Several road closures, washouts and flooded basements were reported.', 'In excess of 2 inches of rainfall caused basement flooding and road closures at several locations in the Town of Cohocton. Water was flowing down Reynolds Creek Road, Wilcox Street, and Unionville Road.');
INSERT INTO public.stormevents_east VALUES (764388, 201806, 1, 1505, 201806, 1, 1505, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 15:05:00', 'EST-5', '01-JUN-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'E', 'GAMEWELL', 1, 'E', 'GAMEWELL', 35.87, -81.6, 35.87, -81.6, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'Ham radio operator reported several trees blown down around the Highway 18 and Rocky Road area.');
INSERT INTO public.stormevents_east VALUES (764394, 201806, 1, 1537, 201806, 1, 1537, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 15:37:00', 'EST-5', '01-JUN-18 15:37:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SSE', 'HARRIS', 0, 'SSE', 'HARRIS', 35.247, -81.878, 35.247, -81.878, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'County comms reported a few trees blown down on Jack McKinney Rd near Highway 221.');
INSERT INTO public.stormevents_east VALUES (765517, 201806, 1, 1550, 201806, 1, 1550, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'GSP', '01-JUN-18 15:50:00', 'EST-5', '01-JUN-18 15:50:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 1, 'E', 'HARRIS SPICERS ARPT', 1, 'E', 'HARRIS SPICERS ARPT', 35.22, -81.85, 35.22, -81.85, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'Public reported pea to penny size hail.');
INSERT INTO public.stormevents_east VALUES (765530, 201806, 1, 2010, 201806, 1, 2010, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 20:10:00', 'EST-5', '01-JUN-18 20:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'GRIFFITH', 1, 'N', 'GRIFFITH', 35.18, -80.88, 35.18, -80.88, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'County comms reported multiple trees and powerlines down across southwest Charlotte.');
INSERT INTO public.stormevents_east VALUES (753644, 201806, 24, 1605, 201806, 24, 1605, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 16:05:00', 'EST-5', '24-JUN-18 16:05:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 60, 'EG', NULL, NULL, 1, 'N', 'CALYPSO', 1, 'N', 'CALYPSO', 35.1645, -78.1, 35.1645, -78.1, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'Trees were blown down along Highway 117 south of Mt. Olive.');
INSERT INTO public.stormevents_east VALUES (753645, 201806, 24, 1610, 201806, 24, 1610, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 16:10:00', 'EST-5', '24-JUN-18 16:10:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SE', 'CALYPSO', 2, 'SE', 'CALYPSO', 35.1295, -78.075, 35.1295, -78.075, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'A 14 foot landscaping trailer was lifted and blown into a ditch. Dime to nickel size hail was also reported.');
INSERT INTO public.stormevents_east VALUES (753646, 201806, 24, 1620, 201806, 24, 1620, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 16:20:00', 'EST-5', '24-JUN-18 16:20:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'WNW', 'KORNEGAY', 1, 'WNW', 'KORNEGAY', 35.0755, -77.8463, 35.0755, -77.8463, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'Trees were blown down along highway 903 near the intersection of highway 11.');
INSERT INTO public.stormevents_east VALUES (753647, 201806, 24, 1640, 201806, 24, 1640, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 16:40:00', 'EST-5', '24-JUN-18 16:40:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 0, 'N', 'PINK HILL', 0, 'N', 'PINK HILL', 35.05, -77.75, 35.05, -77.75, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'The DOT reported trees down around Pink Hill. The time is estimated based on radar.');
INSERT INTO public.stormevents_east VALUES (753648, 201806, 24, 1730, 201806, 24, 1730, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 17:30:00', 'EST-5', '24-JUN-18 17:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 2, 'SSW', 'TRENT WOODS', 2, 'SSW', 'TRENT WOODS', 35.0799, -77.0902, 35.0799, -77.0902, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'Several trees were blown down in the Trent Woods neighborhood, including one on top of a house. The time was estimated based on radar.');
INSERT INTO public.stormevents_east VALUES (753649, 201806, 24, 1740, 201806, 24, 1740, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 17:40:00', 'EST-5', '24-JUN-18 17:40:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', 65, 'EG', NULL, NULL, 3, 'WSW', 'TRENT WOODS', 3, 'WSW', 'TRENT WOODS', 35.09, -77.13, 35.09, -77.13, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'A confirmed microburst occurred near New Bern. Damage was found around and along Highway 17 business, to varying degrees, but consistent with wind speeds of 75 to 90 mph. The most significant damage occurred along Highway 17 business with multiple trees snapped and uprooted.');
INSERT INTO public.stormevents_east VALUES (753919, 201805, 14, 1655, 201805, 14, 1655, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:55:00', 'EST-5', '14-MAY-18 16:55:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 52, 'EG', NULL, NULL, 1, 'NE', 'STAUNTON', 1, 'NE', 'STAUNTON', 38.1588, -79.0623, 38.1588, -79.0623, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Multiple trees were down at Sadley Road and Lee Highway.');
INSERT INTO public.stormevents_east VALUES (753916, 201805, 14, 1655, 201805, 14, 1655, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:55:00', 'EST-5', '14-MAY-18 16:55:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 0, 'NNW', 'FT DEFIANCE', 0, 'NNW', 'FT DEFIANCE', 38.2551, -78.9731, 38.2551, -78.9731, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down in Mount Sidney.');
INSERT INTO public.stormevents_east VALUES (753921, 201805, 14, 1703, 201805, 14, 1703, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:03:00', 'EST-5', '14-MAY-18 17:03:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NW', 'BAUCO', 0, 'NW', 'BAUCO', 38.451, -78.281, 38.451, -78.281, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree fell onto N. Blue Ridge Turnpike.');
INSERT INTO public.stormevents_east VALUES (753922, 201805, 14, 1655, 201805, 14, 1655, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:55:00', 'EST-5', '14-MAY-18 16:55:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 52, 'EG', NULL, NULL, 1, 'ESE', 'GROTTOES', 1, 'ESE', 'GROTTOES', 38.2617, -78.814, 38.2617, -78.814, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Multiple trees were down along Browns Gap Road.');
INSERT INTO public.stormevents_east VALUES (754500, 201805, 14, 1702, 201805, 14, 1702, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:02:00', 'EST-5', '14-MAY-18 17:02:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'CRIGLERSVILLE', 1, 'SSW', 'CRIGLERSVILLE', 38.462, -78.303, 38.462, -78.303, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree fell into a home.');
INSERT INTO public.stormevents_east VALUES (754501, 201805, 14, 1640, 201805, 14, 1640, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:40:00', 'EST-5', '14-MAY-18 16:40:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 3, 'E', 'ROUND HILL', 3, 'E', 'ROUND HILL', 39.1335, -77.7705, 39.1335, -77.7705, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Two trees were down on Route 7.');
INSERT INTO public.stormevents_east VALUES (751705, 201806, 10, 2345, 201806, 11, 200, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '10-JUN-18 23:45:00', 'EST-5', '11-JUN-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'TORRESDALE', 1, 'NW', 'BUSTLETON', 40.0483, -74.9922, 40.0884, -75.0391, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on Interstate 95 with ramp closures at Cottman Avenue.');
INSERT INTO public.stormevents_east VALUES (752062, 201806, 10, 2315, 201806, 11, 130, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '10-JUN-18 23:15:00', 'EST-5', '11-JUN-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'CHESTERBROOK', 2, 'NW', 'COLONIAL VLG', 40.0838, -75.4502, 40.0924, -75.4241, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Water rescues took place along Richards Road at Gulph Road and at Glenhardie Road in Tredyffrin Township.  A home was flooded to the first floor near Yellow Spring Road and Well Springs Lane in Tredyffrin Township.  Also, there was roadway flooding in Valley Forge.');
INSERT INTO public.stormevents_east VALUES (752063, 201806, 10, 2245, 201806, 11, 100, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '10-JUN-18 22:45:00', 'EST-5', '11-JUN-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'CHESTER SPGS', 2, 'ESE', 'CHESTER SPGS', 40.1023, -75.6115, 40.0904, -75.5882, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding occurred along Clover Mill Road and Pikeland Road in East Pikeland Township and West Pikeland Township.');
INSERT INTO public.stormevents_east VALUES (752065, 201806, 10, 2305, 201806, 11, 130, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '10-JUN-18 23:05:00', 'EST-5', '11-JUN-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'ROXBOROUGH', 1, 'E', 'MANAYUNK', 40.0699, -75.2433, 40.0198, -75.2036, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'The Wissahickon Creek exceeded its flood stage of 5 feet at the river gauge in Philadelphia.  Lincoln Drive was closed due to flooding between Wissahickon Avenue and West Johnson Street.');
INSERT INTO public.stormevents_east VALUES (752907, 201806, 11, 30, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '11-JUN-18 00:30:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'OAKS', 2, 'SSE', 'OAKS', 40.1, -75.46, 40.0975, -75.4599, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Valley Road impassible due to flood waters.');
INSERT INTO public.stormevents_east VALUES (752912, 201806, 11, 127, 201806, 11, 400, 125031, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '11-JUN-18 01:27:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'CHESTER SPGS', 1, 'ENE', 'CHESTER SPGS', 40.11, -75.6, 40.1066, -75.5971, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on Clover Mill Road and Pikeland Road between Kimberton Road and Wildlife Drive.  All Lanes Closed.');
INSERT INTO public.stormevents_east VALUES (751056, 201806, 11, 110, 201806, 11, 400, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flood', 'PHI', '11-JUN-18 01:10:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NEW ALBANY', 0, 'WSW', 'NEW ALBANY', 40, -74.99, 39.9973, -74.9884, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding along U.S. Highway 130 northbound approaching Riverton Road. Right and center lanes impassable.');
INSERT INTO public.stormevents_east VALUES (749185, 201806, 4, 1405, 201806, 4, 1405, 124887, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '04-JUN-18 14:05:00', 'EST-5', '04-JUN-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 14, 'NNE', 'PLAYALINDA BEACH', 14, 'NNE', 'PLAYALINDA BEACH', 28.7435, -80.7005, 28.7435, -80.7005, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating, conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast where a few intensified. One severe thunderstorm produced strong to severe winds along the Brevard County Coast. A second thunderstorm produced strong winds along the St. Lucie County coast.', 'US Air Force wind tower 0019 measured a peak wind gust of 34 knots from the north-northeast.');
INSERT INTO public.stormevents_east VALUES (749186, 201806, 4, 1425, 201806, 4, 1425, 124887, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '04-JUN-18 14:25:00', 'EST-5', '04-JUN-18 14:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 9, 'NE', 'PLAYALINDA BEACH', 9, 'NE', 'PLAYALINDA BEACH', 28.6256, -80.6571, 28.6256, -80.6571, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating, conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast where a few intensified. One severe thunderstorm produced strong to severe winds along the Brevard County Coast. A second thunderstorm produced strong winds along the St. Lucie County coast.', 'US Air Force wind tower 3132 measured a peak wind gust of 34 knots from the north-northwest.');
INSERT INTO public.stormevents_east VALUES (749187, 201806, 4, 1450, 201806, 4, 1450, 124887, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '04-JUN-18 14:50:00', 'EST-5', '04-JUN-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 42, 'MG', NULL, NULL, 9, 'N', 'CAPE CANAVERAL', 9, 'N', 'CAPE CANAVERAL', 28.5103, -80.6102, 28.5103, -80.6102, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating, conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast where a few intensified. One severe thunderstorm produced strong to severe winds along the Brevard County Coast. A second thunderstorm produced strong winds along the St. Lucie County coast.', 'US Air Force wind tower 0506 measured a peak wind gust of 42 knots from the north-northwest.');
INSERT INTO public.stormevents_east VALUES (755063, 201806, 28, 520, 201806, 28, 520, 125951, 'TENNESSEE', 47, 2018, 'June', 'Thunderstorm Wind', 'MRX', '28-JUN-18 05:20:00', 'EST-5', '28-JUN-18 05:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'WSW', 'GLADES', 1, 'WSW', 'GLADES', 35.72, -83.49, 35.72, -83.49, 'Repeat convection along a slow moving frontal boundary over a lengthy period generated wind damage and flash flooding across Southeast Tennessee from the evening hours into the following morning.', 'A few trees were reported down.');
INSERT INTO public.stormevents_east VALUES (749500, 201806, 8, 1829, 201806, 8, 2029, 124954, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '08-JUN-18 18:29:00', 'EST-5', '08-JUN-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'XENIA', 2, 'SSW', 'XENIA', 39.65, -83.94, 39.6539, -83.9387, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'High water was reported over Route 380 near Washington Road.');
INSERT INTO public.stormevents_east VALUES (749623, 201806, 8, 1841, 201806, 8, 2041, 124954, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '08-JUN-18 18:41:00', 'EST-5', '08-JUN-18 20:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'MAD RIVER ARPT', 1, 'SSE', 'DIALTON', 40.0176, -83.8396, 40.0104, -83.9196, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Water was crossing several roads in multiple spots. A trailer park in Lawrenceville had no in or out access.');
INSERT INTO public.stormevents_east VALUES (749626, 201806, 8, 2030, 201806, 8, 2230, 124954, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '08-JUN-18 20:30:00', 'EST-5', '08-JUN-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'AUSTIN', 2, 'W', 'AUSTIN', 39.4226, -83.2221, 39.432, -83.2507, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Roads were reported closed near Austin due to high standing water. This includes Austin-Good Hope Rd.');
INSERT INTO public.stormevents_east VALUES (749628, 201806, 8, 1152, 201806, 8, 1202, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 11:52:00', 'EST-5', '08-JUN-18 12:02:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'BRIGGSDALE', 1, 'E', 'BRIGGSDALE', 39.92, -83.05, 39.92, -83.05, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Several trees were damaged. A portion of a fence was blown over.');
INSERT INTO public.stormevents_east VALUES (749630, 201806, 8, 1206, 201806, 8, 1216, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 12:06:00', 'EST-5', '08-JUN-18 12:16:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'N', 'COLUMBUS SO COLUMBUS', 1, 'N', 'COLUMBUS SO COLUMBUS', 39.89, -82.97, 39.89, -82.97, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'A tree was knocked down on a power line on Williams Road.');
INSERT INTO public.stormevents_east VALUES (755582, 201806, 16, 1935, 201806, 16, 1945, 125339, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '16-JUN-18 19:35:00', 'EST-5', '16-JUN-18 19:45:00', 0, 0, 0, 0, '20.00K', '10.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 3, 'SW', 'WEST RUSHVILLE', 3, 'SW', 'WEST RUSHVILLE', 39.7417, -82.5019, 39.7417, -82.5019, 'Thunderstorms developed due to an upper level disturbance moving across Lake Erie.', 'Numerous trees and limbs were knocked down, with several power poles titled over. In addition, corn was bent down due to the wind.');
INSERT INTO public.stormevents_east VALUES (755650, 201806, 16, 1927, 201806, 16, 1937, 125339, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '16-JUN-18 19:27:00', 'EST-5', '16-JUN-18 19:37:00', 0, 0, 0, 0, '0.00K', '10.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SW', 'THURSTON', 2, 'SW', 'THURSTON', 39.8117, -82.5701, 39.8117, -82.5701, 'Thunderstorms developed due to an upper level disturbance moving across Lake Erie.', 'Damage was reported to corn in a field, as the stalks were bent over or flattened in a circle shape.');
INSERT INTO public.stormevents_east VALUES (774411, 201807, 6, 1636, 201807, 6, 1636, 129233, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 16:36:00', 'EST-5', '06-JUL-18 16:36:00', 0, 0, 0, 0, '1.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'ALTO', 0, 'N', 'ALTO', 37.77, -79.23, 37.77, -79.23, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew three trees down. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (765582, 201806, 22, 1136, 201806, 22, 1136, 125817, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '22-JUN-18 11:36:00', 'EST-5', '22-JUN-18 11:36:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'KINDERLOU', 2, 'W', 'KINDERLOU', 30.8, -83.39, 30.8, -83.39, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down on Old Quitman Highway south of Highway 84.');
INSERT INTO public.stormevents_east VALUES (765583, 201806, 22, 1148, 201806, 22, 1148, 125817, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '22-JUN-18 11:48:00', 'EST-5', '22-JUN-18 11:48:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'REMERTON', 2, 'ENE', 'REMERTON', 30.8504, -83.2878, 30.8504, -83.2878, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down onto a power line near the 1600 block of North Patterson Street.');
INSERT INTO public.stormevents_east VALUES (765589, 201806, 25, 1915, 201806, 25, 1915, 125818, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '25-JUN-18 19:15:00', 'EST-5', '25-JUN-18 19:15:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'FITZGERALD', 1, 'NNW', 'FITZGERALD', 31.7234, -83.256, 31.7234, -83.256, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree and a power line were blown down at the intersection of Lee Street and Sultana Drive.');
INSERT INTO public.stormevents_east VALUES (765590, 201806, 25, 1945, 201806, 25, 1945, 125818, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '25-JUN-18 19:45:00', 'EST-5', '25-JUN-18 19:45:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'W', 'OCILLA', 1, 'W', 'OCILLA', 31.59, -83.26, 31.59, -83.26, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree was blown down onto a power line resulting in a power outage on the southwest side of Ocilla.');
INSERT INTO public.stormevents_east VALUES (791713, 201812, 1, 900, 201812, 2, 900, 132316, 'GEORGIA', 13, 2018, 'December', 'Heavy Rain', 'JAX', '01-DEC-18 09:00:00', 'EST-5', '02-DEC-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 0, 'N', '(AYS)WARE CO ARPT WA', 0, 'N', '(AYS)WARE CO ARPT WA', 31.25, -82.4, 31.25, -82.4, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'A RAWs site in the Okefenokee Swamp measured 3.62 inches in 24 hrs.');
INSERT INTO public.stormevents_east VALUES (791715, 201812, 2, 1250, 201812, 2, 1250, 132316, 'GEORGIA', 13, 2018, 'December', 'Lightning', 'JAX', '02-DEC-18 12:50:00', 'EST-5', '02-DEC-18 12:50:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'N', 'EMERSON PARK', 1, 'N', 'EMERSON PARK', 31.26, -82.38, 31.26, -82.38, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'A home was damaged by lightning along Lucille Street. The cost of damage was unknown, but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (791716, 201812, 2, 1414, 201812, 2, 1415, 132316, 'GEORGIA', 13, 2018, 'December', 'Tornado', 'JAX', '02-DEC-18 14:14:00', 'EST-5', '02-DEC-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'NE', 'SAYE', 3, 'WSW', 'KIRKLAND', 31.2925, -83.0196, 31.3088, -82.9688, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'Tree tops were broken off at the tops per EM storm survey. Damage was confined to areas south of Highway 82, between County Road 38 and Lazy Nine Road. The time of damage was based on radar data.');
INSERT INTO public.stormevents_east VALUES (791717, 201812, 2, 1430, 201812, 2, 1431, 132316, 'GEORGIA', 13, 2018, 'December', 'Tornado', 'JAX', '02-DEC-18 14:30:00', 'EST-5', '02-DEC-18 14:31:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'NE', 'PEARSON', 1, 'NE', 'PEARSON', 31.31, -82.86, 31.3114, -82.8573, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'A home security camera captured video of a tornado moving across personal property. Minor damage was done to the home. Cost of damage was estimated.');
INSERT INTO public.stormevents_east VALUES (791720, 201812, 2, 1445, 201812, 2, 1445, 132316, 'GEORGIA', 13, 2018, 'December', 'Thunderstorm Wind', 'JAX', '02-DEC-18 14:45:00', 'EST-5', '02-DEC-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 70, 'EG', NULL, NULL, 4, 'W', 'PYLES MARSH', 4, 'W', 'PYLES MARSH', 31.13, -81.56, 31.13, -81.56, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'Trees were blown down in the Royal Oaks subdivision.');
INSERT INTO public.stormevents_east VALUES (774500, 201807, 16, 1343, 201807, 16, 1343, 129249, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '16-JUL-18 13:43:00', 'EST-5', '16-JUL-18 13:43:00', 0, 0, 0, 0, '1.50K', NULL, 'Public', 50, 'EG', NULL, NULL, 2, 'SE', 'MONROE', 2, 'SE', 'MONROE', 37.4786, -79.098, 37.4786, -79.098, 'An upper level disturbance crossed the region during the afternoon hours, yielding an area of relatively higher instability aloft. The result was the development of showers and storms, with two of these storms increasing to severe levels and producing damaging winds.', 'Thunderstorm winds downed a tree and other large branches in the 200 block of Abbitts Drive near Lynchburg, VA. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774504, 201807, 16, 1648, 201807, 16, 1648, 129249, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '16-JUL-18 16:48:00', 'EST-5', '16-JUL-18 16:48:00', 0, 0, 0, 0, '10.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'MONROE', 2, 'SE', 'MONROE', 37.48, -79.11, 37.48, -79.11, 'An upper level disturbance crossed the region during the afternoon hours, yielding an area of relatively higher instability aloft. The result was the development of showers and storms, with two of these storms increasing to severe levels and producing damaging winds.', 'Thunderstorm winds blew several trees down on, and around, a house in the 200 block along Dixie Airport Road. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (759240, 201805, 19, 929, 201805, 19, 1302, 126452, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 09:29:00', 'EST-5', '19-MAY-18 13:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BRISTOW', 0, 'NNW', 'BRISTOW', 38.7351, -77.5337, 38.7261, -77.5336, 'Heavy rain of 1-3 inches fell during the evening and overnight of May 18th into May 19th along and east of the Blue Ridge Mountains. This prompted flooding in the region, mainly of streams. Some of the stream flooding lasted into the 20th, especially on larger rivers.', 'The stream gage on Broad Run near Manassas Airport exceeded the 9.5 foot flood stage during the indicated times. The peak value of 10.46 feet occurred at 11:45am EST on May 19th. At the observed levels, Piper Lane floods near the Manassas Airport.');
INSERT INTO public.stormevents_east VALUES (759244, 201805, 19, 219, 201805, 19, 1250, 126452, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 02:19:00', 'EST-5', '19-MAY-18 12:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'RAPIDAN', 3, 'NW', 'RAPIDAN', 38.3484, -78.1123, 38.3509, -78.1083, 'Heavy rain of 1-3 inches fell during the evening and overnight of May 18th into May 19th along and east of the Blue Ridge Mountains. This prompted flooding in the region, mainly of streams. Some of the stream flooding lasted into the 20th, especially on larger rivers.', 'The stream gage on Robinson River at Locust Dale exceeded the 11 foot flood stage during the times indicated. The peak level of 12.64 feet was observed at 06:45am EST on May 19th. At these levels, portions of Route 721 (Robinson River Road) flood.');
INSERT INTO public.stormevents_east VALUES (765740, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'FRONT ROYAL ARPT', 1, 'SE', 'FRONT ROYAL ARPT', 38.9349, -78.1047, 38.9369, -78.1033, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Oregon Hollow Road flooded and closed near Front Royal.');
INSERT INTO public.stormevents_east VALUES (765741, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'WAKEMAN MILLS', 1, 'W', 'WAKEMAN MILLS', 38.9512, -78.2956, 38.9505, -78.2946, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Mountain Road flooded and closed near Passage Creek.');
INSERT INTO public.stormevents_east VALUES (765742, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'CEDARVILLE', 1, 'WSW', 'CEDARVILLE', 38.9769, -78.1956, 38.9772, -78.1947, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Ritenour Hollow Road flooded and closed near Molly Campbell Lane.');
INSERT INTO public.stormevents_east VALUES (765743, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'WATERLICK', 0, 'WSW', 'WATERLICK', 38.9665, -78.2854, 38.968, -78.2839, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Bucks Mill Road flooded and closed between Route 55 and Richardson Road.');
INSERT INTO public.stormevents_east VALUES (765744, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'BUCKTON', 1, 'E', 'BUCKTON', 38.9791, -78.2705, 38.9805, -78.2688, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Gafia Lodge Road flooded and closed near the North Fork Shenandoah River.');
INSERT INTO public.stormevents_east VALUES (769107, 201806, 23, 336, 201806, 23, 1142, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 03:36:00', 'EST-5', '23-JUN-18 11:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'FISHERS HILL', 0, 'WNW', 'FISHERS HILL', 38.9555, -78.3848, 38.9818, -78.3886, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'The stream gage on the North Fork Shenandoah River near Strasburg exceeded the 17 foot flood stage during the indicated period. The peak level of 17.77 was observed at 8:00am EST on June 23rd. Low lying areas and low water crossings were flooded, along with the river walk at the Strasburg Riverfront Park.');
INSERT INTO public.stormevents_east VALUES (753871, 201805, 13, 2132, 201805, 13, 2132, 125701, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '13-MAY-18 21:32:00', 'EST-5', '13-MAY-18 21:32:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'ESE', 'FRANCONIA', 2, 'ESE', 'FRANCONIA', 38.7902, -77.1049, 38.7902, -77.1049, 'A few showers and thunderstorms developed near a stationary front. Some storms became severe due to an unstable atmosphere.', 'Quarter sized hail was reported in Rose Hill.');
INSERT INTO public.stormevents_east VALUES (791789, 201812, 15, 935, 201812, 15, 935, 132330, 'FLORIDA', 12, 2018, 'December', 'Flood', 'JAX', '15-DEC-18 09:35:00', 'EST-5', '15-DEC-18 09:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'DAYTONA NORTH', 2, 'NE', 'DAYTONA NORTH', 29.4372, -81.3776, 29.4684, -81.3783, 'Strong upper level forcing unseasonably moist conditions continued across the area during the early morning hours ahead of a large surface low near the TN/AL stateline. Localized heavy rainfall continued to impact north-central Florida.', 'Forest Park Street in Daytona North was submerged by about 1 ft of flood water.');
INSERT INTO public.stormevents_east VALUES (791790, 201812, 14, 1030, 201812, 15, 1030, 132330, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '14-DEC-18 10:30:00', 'EST-5', '15-DEC-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'E', 'SUMMERFIELD', 1, 'E', 'SUMMERFIELD', 29.02, -82.01, 29.02, -82.01, 'Strong upper level forcing unseasonably moist conditions continued across the area during the early morning hours ahead of a large surface low near the TN/AL stateline. Localized heavy rainfall continued to impact north-central Florida.', 'The Del Webb Golf and Country Club measured a 24 hr rainfall of 4.79 inches.');
INSERT INTO public.stormevents_east VALUES (791792, 201812, 20, 1010, 201812, 20, 1010, 132332, 'FLORIDA', 12, 2018, 'December', 'Thunderstorm Wind', 'JAX', '20-DEC-18 10:10:00', 'EST-5', '20-DEC-18 10:10:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 40, 'EG', NULL, NULL, 1, 'W', 'CODYS CORNER', 1, 'W', 'CODYS CORNER', 29.34, -81.33, 29.34, -81.33, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'A tree was blown down across County Road 304 in the St. Johns Park area. The cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (791793, 201812, 20, 1048, 201812, 20, 1048, 132332, 'FLORIDA', 12, 2018, 'December', 'Thunderstorm Wind', 'JAX', '20-DEC-18 10:48:00', 'EST-5', '20-DEC-18 10:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 1, 'S', 'LAKE FOREST', 1, 'S', 'LAKE FOREST', 30.34, -81.63, 30.34, -81.63, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow sensor at the Terminal Channel measured a wind gust to 60 mph.');
INSERT INTO public.stormevents_east VALUES (765387, 201806, 8, 1955, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 19:55:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'ROCKFORD', 3, 'NNE', 'ROCKFORD', 40.5093, -81.2728, 40.5075, -81.2734, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'The intersection of Dawn Road and Miller Hill Road was reported as impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (753656, 201806, 11, 1320, 201806, 11, 1320, 125661, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '11-JUN-18 13:20:00', 'EST-5', '11-JUN-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 0, 'N', 'FAISON', 0, 'N', 'FAISON', 35.12, -78.13, 35.12, -78.13, 'Thunderstorms developed during the afternoon hours. A few of them became severe producing damaging wind gusts and some hail dime to nickel size.', 'Power lines were blown down and pea size hail was reported.');
INSERT INTO public.stormevents_east VALUES (765389, 201806, 8, 2000, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 20:00:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'SHERRODSVILLE', 2, 'WSW', 'SHERRODSVILLE', 40.4946, -81.2648, 40.4925, -81.264, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'Dana Road was reported to be impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (775043, 201808, 8, 1637, 201808, 8, 1637, 129352, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '08-AUG-18 16:37:00', 'EST-5', '08-AUG-18 16:37:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'WSW', 'PINEVILLE', 1, 'WSW', 'PINEVILLE', 38.3425, -78.8205, 38.3425, -78.8205, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which became severe.', 'Trees and power lines were blown down on the 7100 block of Trimble Road.');
INSERT INTO public.stormevents_east VALUES (765385, 201806, 8, 1900, 201806, 8, 2145, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 19:00:00', 'EST-5', '08-JUN-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ROSWELL', 1, 'ESE', 'ROSWELL', 40.47, -81.33, 40.4719, -81.3305, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'A State Trooper reported that Highway 30 was completely under water.');
INSERT INTO public.stormevents_east VALUES (765386, 201806, 8, 1900, 201806, 8, 2145, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 19:00:00', 'EST-5', '08-JUN-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'ROSWELL', 1, 'NE', 'ROSWELL', 40.4933, -81.3328, 40.492, -81.3327, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'A residence at 6368 Echo Lake Road reported that a wall of water hit the basement door and damaged it.  Also, an outdoor shed at the residence was moved by flood water.');
INSERT INTO public.stormevents_east VALUES (765390, 201806, 8, 2000, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 20:00:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'ROCKFORD', 1, 'S', 'ROCKFORD', 40.4666, -81.3014, 40.4585, -81.3024, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'Portions of Roxford Church Road were washed away.');
INSERT INTO public.stormevents_east VALUES (765391, 201806, 8, 2000, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 20:00:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'ROSWELL', 1, 'NNE', 'ROSWELL', 40.4907, -81.3454, 40.4879, -81.3449, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'Lawvers Road was reported as flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (751801, 201806, 18, 1755, 201806, 18, 1755, 125354, 'MASSACHUSETTS', 25, 2018, 'June', 'Thunderstorm Wind', 'BOX', '18-JUN-18 17:55:00', 'EST-5', '18-JUN-18 17:55:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 2, 'SW', 'IPSWICH', 2, 'SW', 'IPSWICH', 42.6561, -70.8611, 42.6561, -70.8611, 'A cold front moved from the Great Lakes across New England during the night of the 18th. The air mass ahead of the cold front was very warm and very humid. Showers and thunderstorms developed well ahead of the front over New York and Pennsylvania, then moved east into New England. There were numerous reports of wind damage in northern and western Massachusetts.', 'At 5:55 PM EST several trees were down on Waldingfield Road in Hamilton.');
INSERT INTO public.stormevents_east VALUES (753657, 201806, 11, 1320, 201806, 11, 1320, 125661, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '11-JUN-18 13:20:00', 'EST-5', '11-JUN-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 6, 'W', 'SANDY BOTTOM', 6, 'W', 'SANDY BOTTOM', 35.22, -77.8063, 35.22, -77.8063, 'Thunderstorms developed during the afternoon hours. A few of them became severe producing damaging wind gusts and some hail dime to nickel size.', 'Trees were blown down in the Seven Springs area.');
INSERT INTO public.stormevents_east VALUES (755934, 201806, 28, 630, 201806, 28, 1100, 126111, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '28-JUN-18 06:30:00', 'EST-5', '28-JUN-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'HOLYOKE', 0, 'E', 'HOLYOKE', 42.1996, -72.613, 42.1993, -72.6123, 'Low pressure from the Great Lakes moved northeast up the St Lawrence Valley. This moved a warm front across Southern New England in the morning, followed by a cold front in the afternoon.  These two periods of showers and thunderstorms brought heavy downpours to the region, with rain amounts as high as four and one-half inches reported in parts of Western Massachusetts.', 'At 6:30 AM EST, the Sargeant Street underpass was reported flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (755935, 201806, 28, 1455, 201806, 28, 1800, 126111, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '28-JUN-18 14:55:00', 'EST-5', '28-JUN-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BRIGHTWOOD', 1, 'SSE', 'BRIGHTWOOD', 42.1049, -72.596, 42.1051, -72.5952, 'Low pressure from the Great Lakes moved northeast up the St Lawrence Valley. This moved a warm front across Southern New England in the morning, followed by a cold front in the afternoon.  These two periods of showers and thunderstorms brought heavy downpours to the region, with rain amounts as high as four and one-half inches reported in parts of Western Massachusetts.', 'At 2:55 PM EST flooding was reported at the railroad underpass near Liberty and Main Streets.');
INSERT INTO public.stormevents_east VALUES (755936, 201806, 28, 1505, 201806, 28, 1800, 126111, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '28-JUN-18 15:05:00', 'EST-5', '28-JUN-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'WEST SPRINGFIELD', 1, 'NE', 'WEST SPRINGFIELD', 42.1119, -72.6559, 42.1121, -72.6558, 'Low pressure from the Great Lakes moved northeast up the St Lawrence Valley. This moved a warm front across Southern New England in the morning, followed by a cold front in the afternoon.  These two periods of showers and thunderstorms brought heavy downpours to the region, with rain amounts as high as four and one-half inches reported in parts of Western Massachusetts.', 'At 3:05 PM EST, street flooding was reported up to 1 foot deep at the intersection of Ely Avenue and Verdugo Street in West Springfield.');
INSERT INTO public.stormevents_east VALUES (755937, 201806, 28, 1505, 201806, 28, 1800, 126111, 'MASSACHUSETTS', 25, 2018, 'June', 'Flood', 'BOX', '28-JUN-18 15:05:00', 'EST-5', '28-JUN-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'WILLIMANSETT', 1, 'ESE', 'SMITH HIGHLANDS', 42.2014, -72.5764, 42.1961, -72.5905, 'Low pressure from the Great Lakes moved northeast up the St Lawrence Valley. This moved a warm front across Southern New England in the morning, followed by a cold front in the afternoon.  These two periods of showers and thunderstorms brought heavy downpours to the region, with rain amounts as high as four and one-half inches reported in parts of Western Massachusetts.', 'At 3:05 PM EST, a car was trapped in street flooding on Prospect Street in Chicopee.');
INSERT INTO public.stormevents_east VALUES (765413, 201806, 1, 1310, 201806, 1, 1310, 127642, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '01-JUN-18 13:10:00', 'EST-5', '01-JUN-18 13:10:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 58, 'EG', NULL, NULL, 1, 'E', 'SAVANNAH', 1, 'E', 'SAVANNAH', 43.07, -76.76, 43.07, -76.76, 'Strong to severe convection developed as a warm and sultry air mass interacted with several boundaries, including at least two ''pieces'' of a cold front, lake breeze boundaries, and several outflow boundaries. While there was very little shear for the storms to work with, MLCAPE values averaged 1500 J/kg. Given light unidirectional flow through at least 12,000 ft, slow moving downpours were the main concern.', 'Trees down.');
INSERT INTO public.stormevents_east VALUES (763084, 201806, 25, 1808, 201806, 25, 1815, 126890, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:08:00', 'EST-5', '25-JUN-18 18:15:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 52, 'EG', NULL, NULL, 1, 'N', 'LINCOLNTON', 1, 'N', 'LINCOLNTON', 33.7942, -82.4783, 33.7942, -82.4783, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Lincoln County Emergency Manager estimated wind gusts of at least 60 mph near Lincolnton.');
INSERT INTO public.stormevents_east VALUES (763085, 201806, 25, 1755, 201806, 25, 1759, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 17:55:00', 'EST-5', '25-JUN-18 17:59:00', 0, 0, 0, 0, NULL, NULL, 'Park/Forest Service', 60, 'EG', NULL, NULL, 3, 'WSW', 'GADSDEN', 3, 'WSW', 'GADSDEN', 33.83, -80.82, 33.83, -80.82, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Several trees down within Congaree National Park.  A portion of the lower boardwalk was damaged due to fallen trees.');
INSERT INTO public.stormevents_east VALUES (763087, 201806, 25, 1910, 201806, 25, 1912, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:10:00', 'EST-5', '25-JUN-18 19:12:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 3, 'SW', 'MONTGOMERY', 3, 'SW', 'MONTGOMERY', 34.0942, -81.1636, 34.0942, -81.1636, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Shady Lane was blocked by a fallen tree near Gaillard St and Kinley Rd.');
INSERT INTO public.stormevents_east VALUES (763088, 201806, 25, 1834, 201806, 25, 1852, 126890, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:34:00', 'EST-5', '25-JUN-18 18:52:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 56, 'EG', NULL, NULL, 1, 'NW', 'EVANS', 1, 'NW', 'EVANS', 33.54, -82.14, 33.54, -82.14, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Columbia County Sherriff Dispatch reported multiple trees down across the county, radar indicated strongest winds in the Evans, Martinez, and Grovetown communities.');
INSERT INTO public.stormevents_east VALUES (763089, 201806, 25, 1932, 201806, 25, 1935, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:32:00', 'EST-5', '25-JUN-18 19:35:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 0, 'WSW', 'MYRON MANOR', 0, 'WSW', 'MYRON MANOR', 33.9971, -80.9772, 33.9971, -80.9772, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Tree on roadway blocking intersection of Beltline Blvd and Cross Hill Rd.');
INSERT INTO public.stormevents_east VALUES (763090, 201806, 25, 1915, 201806, 25, 1922, 126890, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:15:00', 'EST-5', '25-JUN-18 19:22:00', 0, 0, 0, 0, '0.01K', '0.00K', 'Law Enforcement', 43, 'EG', NULL, NULL, 3, 'SE', 'KEYSVILLE', 3, 'SE', 'KEYSVILLE', 33.2039, -82.1917, 33.2039, -82.1917, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Burke County Sheriff Dispatch reported a tree down on Farmers Bridge Rd just north of Brier Creek.');
INSERT INTO public.stormevents_east VALUES (763091, 201806, 25, 1915, 201806, 25, 1918, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:15:00', 'EST-5', '25-JUN-18 19:18:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'SSW', 'PROVIDENCE', 2, 'SSW', 'PROVIDENCE', 33.99, -81.29, 33.99, -81.29, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'SCHP reported tree down at intersection of Wise Ferry Rd and US Hwy 378.');
INSERT INTO public.stormevents_east VALUES (779310, 201808, 22, 733, 201808, 22, 933, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '22-AUG-18 07:33:00', 'EST-5', '22-AUG-18 09:33:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'EMMITSBURG', 1, 'NE', 'EMMITSBURG', 39.7121, -77.3124, 39.7121, -77.3114, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'North Seton Avenue was closed near Route 15 due to flooding.');
INSERT INTO public.stormevents_east VALUES (782858, 201808, 21, 2318, 201808, 21, 2358, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:18:00', 'EST-5', '21-AUG-18 23:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'FINKSBURG', 1, 'SSW', 'FINKSBURG', 39.49, -76.9034, 39.4896, -76.9032, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The USGS stream gage on Beaver Run near Finksburg briefly exceeded the 5 foot flood stage during the indicated period, flooding Hughes Road. The peak level of 5.19 feet occurred at 11:30pm EST.');
INSERT INTO public.stormevents_east VALUES (783182, 201808, 22, 138, 201808, 22, 749, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '22-AUG-18 01:38:00', 'EST-5', '22-AUG-18 07:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'UPPER MARLBORO', 1, 'SSE', 'UPPER MARLBORO', 38.81, -76.75, 38.8095, -76.7441, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The stream gauge at  Upper Marlboro crested at 11.95 feet, above the flood stage of 11 feet. Much of Race Track Road flooded between Marlboro Pike and the community center.');
INSERT INTO public.stormevents_east VALUES (777983, 201808, 21, 724, 201808, 21, 924, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 07:24:00', 'EST-5', '21-AUG-18 09:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'DUET', 0, 'WNW', 'DUET', 38.4734, -78.2593, 38.4814, -78.2744, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Duet Road was closed due to flooding between Whippoorwill Road and Dead End.');
INSERT INTO public.stormevents_east VALUES (777984, 201808, 21, 724, 201808, 21, 924, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 07:24:00', 'EST-5', '21-AUG-18 09:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 4, 'NNW', 'SYRIA', 4, 'NNW', 'SYRIA', 38.53, -78.35, 38.533, -78.3592, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Weakley Hollow Road was closed due to flooding between Etlan Road and Route 643.');
INSERT INTO public.stormevents_east VALUES (774381, 201807, 31, 2115, 201807, 31, 2215, 128282, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '31-JUL-18 21:15:00', 'EST-5', '31-JUL-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'FARMINGTON', 1, 'ENE', 'FARMINGTON', 38.0575, -78.5319, 38.0569, -78.5315, 'Heavy rain developed during the evening of July 31st, mainly in Albemarle and Orange Counties. Rainfall totals over four inches were observed, with numerous instances of flooding. This rain continued into the morning hours of August 1st with additional flooding reports.', 'Floodwaters were covering the road near the entrance to the Farmington Heights neighborhood. This forced local residents to be told to shelter in place since they could not leave the area.');
INSERT INTO public.stormevents_east VALUES (774382, 201807, 31, 2200, 201807, 31, 2230, 128282, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '31-JUL-18 22:00:00', 'EST-5', '31-JUL-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'FARMINGTON', 2, 'E', 'FARMINGTON', 38.0448, -78.515, 38.0447, -78.5147, 'Heavy rain developed during the evening of July 31st, mainly in Albemarle and Orange Counties. Rainfall totals over four inches were observed, with numerous instances of flooding. This rain continued into the morning hours of August 1st with additional flooding reports.', 'Another vehicle was reported stuck in floodwaters near the intersection of Old Ivy Road and Ivy Road.');
INSERT INTO public.stormevents_east VALUES (774383, 201807, 31, 2212, 201807, 31, 2359, 128282, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '31-JUL-18 22:12:00', 'EST-5', '31-JUL-18 23:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'EASTHAM', 1, 'NNE', 'EASTHAM', 38.0881, -78.4131, 38.0875, -78.4119, 'Heavy rain developed during the evening of July 31st, mainly in Albemarle and Orange Counties. Rainfall totals over four inches were observed, with numerous instances of flooding. This rain continued into the morning hours of August 1st with additional flooding reports.', 'Proffit Road flooded and closed near Stony Point Road.');
INSERT INTO public.stormevents_east VALUES (774386, 201807, 31, 2224, 201807, 31, 2359, 128282, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '31-JUL-18 22:24:00', 'EST-5', '31-JUL-18 23:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'CAMPBELL', 0, 'NW', 'CAMPBELL', 38.0337, -78.3051, 38.0333, -78.3046, 'Heavy rain developed during the evening of July 31st, mainly in Albemarle and Orange Counties. Rainfall totals over four inches were observed, with numerous instances of flooding. This rain continued into the morning hours of August 1st with additional flooding reports.', 'Campbell Road closed due to flooding between Paddock Wood Road and Louisa Road.');
INSERT INTO public.stormevents_east VALUES (774389, 201807, 30, 755, 201807, 30, 930, 128281, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '30-JUL-18 07:55:00', 'EST-5', '30-JUL-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ST INIGOES', 1, 'ESE', 'ST INIGOES', 38.1481, -76.3905, 38.1476, -76.3903, 'Isolated heavy rain during the morning hours of July 30th totalled over four inches in southern Saint Mary''s County, causing several localized instances of flooding.', 'Point Lookout Road flooded and closed at Beachville Road.');
INSERT INTO public.stormevents_east VALUES (763508, 201806, 1, 2243, 201806, 1, 2345, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '01-JUN-18 22:43:00', 'EST-5', '01-JUN-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'HAINESVILLE', 0, 'S', 'HAINESVILLE', 39.5245, -77.9216, 39.5249, -77.9211, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'A vehicle stalled in high standing water on US 11 near Hoke Run in the 4000 block. The driver self-rescued but water continued to rise after the evacuation.');
INSERT INTO public.stormevents_east VALUES (753855, 201805, 12, 2115, 201805, 12, 2115, 125698, 'MARYLAND', 24, 2018, 'May', 'Hail', 'LWX', '12-MAY-18 21:15:00', 'EST-5', '12-MAY-18 21:15:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'N', 'MUTUAL', 1, 'N', 'MUTUAL', 38.4832, -76.5488, 38.4832, -76.5488, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (763509, 201806, 2, 56, 201806, 2, 300, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 00:56:00', 'EST-5', '02-JUN-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'TOMAHAWK', 2, 'SSW', 'TOMAHAWK', 39.5057, -78.0617, 39.5057, -78.0605, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Water covered Swinging Bridge Road near Sapwood Drive. Three trees were also reported down in the same area, likely due to the floodwaters.');
INSERT INTO public.stormevents_east VALUES (763510, 201806, 2, 115, 201806, 2, 315, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 01:15:00', 'EST-5', '02-JUN-18 03:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'STOTLERS XRDS', 1, 'E', 'STOTLERS XRDS', 39.5018, -78.2108, 39.5009, -78.2104, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Portions of Posey Hollow Road were flooded and closed.');
INSERT INTO public.stormevents_east VALUES (763512, 201806, 2, 115, 201806, 2, 315, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 01:15:00', 'EST-5', '02-JUN-18 03:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'LARGENT', 0, 'NNE', 'LARGENT', 39.4828, -78.3781, 39.483, -78.3775, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Flooding forced the closure of West Virginia Route 9 near Largent.');
INSERT INTO public.stormevents_east VALUES (763513, 201806, 2, 125, 201806, 2, 315, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 01:25:00', 'EST-5', '02-JUN-18 03:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'JOHNSTOWN', 1, 'WSW', 'JOHNSTOWN', 39.5718, -78.0545, 39.5715, -78.0544, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Water reported over the bridge on Tilhance Road at the Tilhance Creek crossing.');
INSERT INTO public.stormevents_east VALUES (763514, 201806, 2, 742, 201806, 2, 900, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 07:42:00', 'EST-5', '02-JUN-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'JOHNSTOWN', 2, 'ENE', 'JOHNSTOWN', 39.5878, -78.0029, 39.588, -78.0026, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Allensville Road flooded near Back Creek.');
INSERT INTO public.stormevents_east VALUES (769113, 201806, 23, 603, 201806, 24, 1019, 127378, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 06:03:00', 'EST-5', '24-JUN-18 10:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'VANCLEVESVILLE', 1, 'W', 'BLAIRTON', 39.4188, -77.9398, 39.4494, -77.9345, 'Heavy rain over a two day period caused flooding across eastern West Virginia on June 22nd into the 23rd. Then, the combination of upstream rainfall caused river flooding on the 23rd and 24th.', 'The stream gage on Opequon Creek near Martinsburg exceeded the 10 foot flood stage during the indicated period. The peak level of 12.93 feet was observed at 8:00pm EST on June 23rd. Golf Course Road and other roads in the area were flooded.');
INSERT INTO public.stormevents_east VALUES (769114, 201806, 23, 738, 201806, 24, 1955, 127378, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '23-JUN-18 07:38:00', 'EST-5', '24-JUN-18 19:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'MILLVILLE', 0, 'NNW', 'BLOOMERY', 39.2944, -77.7831, 39.2561, -77.8219, 'Heavy rain over a two day period caused flooding across eastern West Virginia on June 22nd into the 23rd. Then, the combination of upstream rainfall caused river flooding on the 23rd and 24th.', 'The stream gage on the Shenandoah River near Millville exceeded the 10 foot flood stage during the indicated period. The peak level of 12.62 feet occurred at 9:30pm EST on June 23rd. Several roads were flooded along the stream.');
INSERT INTO public.stormevents_east VALUES (753856, 201805, 12, 2036, 201805, 12, 2036, 125698, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '12-MAY-18 20:36:00', 'EST-5', '12-MAY-18 20:36:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SHILOH', 1, 'E', 'SHILOH', 38.371, -76.9206, 38.371, -76.9206, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'A tree was down at Mount Victoria and Shiloh Church Road.');
INSERT INTO public.stormevents_east VALUES (753858, 201805, 12, 1909, 201805, 12, 1909, 125698, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '12-MAY-18 19:09:00', 'EST-5', '12-MAY-18 19:09:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 53, 'MG', NULL, NULL, 0, 'SE', 'GLEN BURNIE', 0, 'SE', 'GLEN BURNIE', 39.165, -76.625, 39.165, -76.625, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'A wind gust of 61 mph was reported.');
INSERT INTO public.stormevents_east VALUES (753859, 201805, 12, 1942, 201805, 12, 1942, 125698, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '12-MAY-18 19:42:00', 'EST-5', '12-MAY-18 19:42:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 54, 'MG', NULL, NULL, 1, 'SE', 'WARDOUR', 1, 'SE', 'WARDOUR', 38.9913, -76.4891, 38.9913, -76.4891, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'A wind gust of 62 mph was reported at Annapolis (KNAK).');
INSERT INTO public.stormevents_east VALUES (753860, 201805, 12, 1917, 201805, 12, 1917, 125698, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '12-MAY-18 19:17:00', 'EST-5', '12-MAY-18 19:17:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 52, 'MG', NULL, NULL, 4, 'ENE', 'LYNCH PT', 4, 'ENE', 'LYNCH PT', 39.253, -76.371, 39.253, -76.371, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'A wind gust of 60 mph was reported at Hart Miller Island.');
INSERT INTO public.stormevents_east VALUES (765535, 201806, 1, 1935, 201806, 1, 1959, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '01-JUN-18 19:35:00', 'EST-5', '01-JUN-18 19:59:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'SW', 'MONROE', 3, 'SE', 'HAMILTONS XRDS', 34.965, -80.586, 35.018, -80.317, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'County comms reported numerous trees blown down from the Monroe area east toward the county line.');
INSERT INTO public.stormevents_east VALUES (765536, 201806, 1, 1730, 201806, 1, 1730, 127504, 'NORTH CAROLINA', 37, 2018, 'June', 'Lightning', 'GSP', '01-JUN-18 17:30:00', 'EST-5', '01-JUN-18 17:30:00', 1, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'SE', 'LAWNDALE', 1, 'SE', 'LAWNDALE', 35.41, -81.57, 35.41, -81.57, 'Scattered to numerous thunderstorms developed across western North Carolina throughout the afternoon and evening. Several of the storms produced brief severe weather in the form of damaging wind gusts.', 'County comms reported a woman on Shelby Rd was injured when lightning struck and caused a power surge to her stove.');
INSERT INTO public.stormevents_east VALUES (767984, 201806, 2, 1413, 201806, 2, 1413, 128047, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '02-JUN-18 14:13:00', 'EST-5', '02-JUN-18 14:13:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'FT MILL', 2, 'WNW', 'FT MILL', 35.035, -80.965, 35.035, -80.965, 'Isolated thunderstorms developed over the mountains and foothills of North Carolina during the afternoon and moved southeast into the South Carolina Upstate and Piedmont. Some of the storms produced brief severe weather, mainly in the form of damaging wind gusts.', 'County dispatch reported a tree blown down on Carolina Place Dr with at least one other tree down in the area. Post Office also reported large limbs down in the same general area.');
INSERT INTO public.stormevents_east VALUES (767985, 201806, 2, 1350, 201806, 2, 1350, 128047, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '02-JUN-18 13:50:00', 'EST-5', '02-JUN-18 13:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNE', 'NINE TIMES', 2, 'NNE', 'NINE TIMES', 34.946, -82.801, 34.946, -82.801, 'Isolated thunderstorms developed over the mountains and foothills of North Carolina during the afternoon and moved southeast into the South Carolina Upstate and Piedmont. Some of the storms produced brief severe weather, mainly in the form of damaging wind gusts.', 'County comms reported a couple of trees and power lines blown down near Nine Times.');
INSERT INTO public.stormevents_east VALUES (767986, 201806, 2, 1534, 201806, 2, 1534, 128047, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '02-JUN-18 15:34:00', 'EST-5', '02-JUN-18 15:34:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NW', 'WESTMINSTER', 2, 'NW', 'WESTMINSTER', 34.69, -83.12, 34.69, -83.12, 'Isolated thunderstorms developed over the mountains and foothills of North Carolina during the afternoon and moved southeast into the South Carolina Upstate and Piedmont. Some of the storms produced brief severe weather, mainly in the form of damaging wind gusts.', 'County comms reported a few trees blown down on power lines.');
INSERT INTO public.stormevents_east VALUES (767987, 201806, 2, 1413, 201806, 2, 1413, 128047, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '02-JUN-18 14:13:00', 'EST-5', '02-JUN-18 14:13:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 2, 'NW', 'FT MILL', 2, 'NW', 'FT MILL', 35.04, -80.96, 35.04, -80.96, 'Isolated thunderstorms developed over the mountains and foothills of North Carolina during the afternoon and moved southeast into the South Carolina Upstate and Piedmont. Some of the storms produced brief severe weather, mainly in the form of damaging wind gusts.', 'Public reported (via Social Media) nickel to quarter size hail along Coltharp Road.');
INSERT INTO public.stormevents_east VALUES (767989, 201806, 2, 1733, 201806, 2, 1733, 128048, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'GSP', '02-JUN-18 17:33:00', 'EST-5', '02-JUN-18 17:33:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 1, 'NNW', 'ROWAN CO ARPT', 1, 'NNW', 'ROWAN CO ARPT', 35.67, -80.54, 35.67, -80.54, 'Isolated thunderstorms developed over the foothills of North Carolina during the afternoon and moved east and southeast into the Piedmont. One of the storms produced brief damaging wind gusts and large hail.', 'Media reported quarter size hail on Sherrills Ford Road.');
INSERT INTO public.stormevents_east VALUES (753650, 201806, 24, 1750, 201806, 24, 1750, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 17:50:00', 'EST-5', '24-JUN-18 17:50:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'PUMPKIN CENTER', 0, 'N', 'PUMPKIN CENTER', 34.78, -77.37, 34.78, -77.37, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'Trees were snapped and fell on power lines near the intersection of Piney Green Rd and Country Club Rd. The time was estimated based on radar.');
INSERT INTO public.stormevents_east VALUES (753651, 201806, 24, 1843, 201806, 24, 1843, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 18:43:00', 'EST-5', '24-JUN-18 18:43:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SSE', 'OTWAY', 1, 'SSE', 'OTWAY', 34.7566, -76.5633, 34.7566, -76.5633, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'Large limbs were blown down. The time was estimated based on radar.');
INSERT INTO public.stormevents_east VALUES (753652, 201806, 24, 1525, 201806, 24, 1525, 125660, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '24-JUN-18 15:25:00', 'EST-5', '24-JUN-18 15:25:00', 0, 0, 0, 0, NULL, NULL, 'Public', 52, 'EG', NULL, NULL, 0, 'N', 'CATON', 0, 'N', 'CATON', 35.27, -77, 35.27, -77, 'Scattered to numerous thunderstorms developed over Eastern North Carolina during the afternoon and evening hours. Some of these storms became severe with large hail and damaging winds. An upper level trough of low pressure and strong shear combined with strong instability over the area to produce the severe thunderstorms.', 'A reported wind gust of 60 mph was received via social media.');
INSERT INTO public.stormevents_east VALUES (753654, 201806, 11, 1132, 201806, 11, 1132, 125661, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '11-JUN-18 11:32:00', 'EST-5', '11-JUN-18 11:32:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', 52, 'EG', NULL, NULL, 0, 'N', 'VANCEBORO', 0, 'N', 'VANCEBORO', 35.3, -77.17, 35.3, -77.17, 'Thunderstorms developed during the afternoon hours. A few of them became severe producing damaging wind gusts and some hail dime to nickel size.', 'A microburst, or straight line wind damage, occurred about 7 to 8 miles southwest of Chocowinity. Significant damage occurred to a camper and minor damage occurred to surrounding trees and outbuildings. Damage was also found on Pollard Rd.');
INSERT INTO public.stormevents_east VALUES (753655, 201806, 11, 1203, 201806, 11, 1203, 125661, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'MHX', '11-JUN-18 12:03:00', 'EST-5', '11-JUN-18 12:03:00', 0, 0, 0, 0, NULL, NULL, 'Post Office', 50, 'EG', NULL, NULL, 0, 'N', 'MINNESOTT BEACH', 0, 'N', 'MINNESOTT BEACH', 34.97, -76.8, 34.97, -76.8, 'Thunderstorms developed during the afternoon hours. A few of them became severe producing damaging wind gusts and some hail dime to nickel size.', 'Carriers reported limbs and small trees blown down near Minnesott Beach. Thumbnail size hail was also reported. The time was estimated based on a microburst signature on radar.');
INSERT INTO public.stormevents_east VALUES (754503, 201805, 14, 1707, 201805, 14, 1707, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:07:00', 'EST-5', '14-MAY-18 17:07:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'ENE', 'BUCKLAND', 0, 'ENE', 'BUCKLAND', 38.782, -77.6655, 38.782, -77.6655, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Two trees were down at US 15 and US 29.');
INSERT INTO public.stormevents_east VALUES (754505, 201805, 14, 1707, 201805, 14, 1707, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:07:00', 'EST-5', '14-MAY-18 17:07:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'SSE', 'WATERFALL', 1, 'SSE', 'WATERFALL', 38.862, -77.666, 38.862, -77.666, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Many large trees were uprooted and snapped in communities around Waterfall Road.');
INSERT INTO public.stormevents_east VALUES (754506, 201805, 14, 1710, 201805, 14, 1710, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:10:00', 'EST-5', '14-MAY-18 17:10:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'NW', 'HILLSBORO', 3, 'NW', 'HILLSBORO', 39.2245, -77.7579, 39.2245, -77.7579, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Three trees were down along with a damaged fence.');
INSERT INTO public.stormevents_east VALUES (754507, 201805, 14, 1720, 201805, 14, 1720, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:20:00', 'EST-5', '14-MAY-18 17:20:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'WSW', 'MANASSAS', 0, 'WSW', 'MANASSAS', 38.7474, -77.4854, 38.7474, -77.4854, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down along Leland and Route 28.');
INSERT INTO public.stormevents_east VALUES (754510, 201805, 14, 1722, 201805, 14, 1722, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:22:00', 'EST-5', '14-MAY-18 17:22:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'S', 'UNO', 2, 'S', 'UNO', 38.248, -78.229, 38.248, -78.229, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree fell onto the S. Blue Ridge Turnpike.');
INSERT INTO public.stormevents_east VALUES (754511, 201805, 14, 1718, 201805, 14, 1718, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:18:00', 'EST-5', '14-MAY-18 17:18:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'LIMSTRONG', 2, 'SE', 'LIMSTRONG', 38.704, -77.446, 38.704, -77.446, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree fell into a home.');
INSERT INTO public.stormevents_east VALUES (751057, 201806, 11, 126, 201806, 11, 400, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flood', 'PHI', '11-JUN-18 01:26:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'CAMDEN', 1, 'NNW', 'CAMDEN', 39.95, -75.13, 39.9502, -75.1275, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on the Ben Franklin Bridge eastbound, with the ramp for eastbound State Highway 90 to northbound U.S. Highway 130 closed at this time.');
INSERT INTO public.stormevents_east VALUES (751059, 201806, 11, 130, 201806, 11, 400, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flood', 'PHI', '11-JUN-18 01:30:00', 'EST-5', '11-JUN-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ERLTON', 1, 'N', 'ERLTON', 39.9346, -75.0582, 39.9343, -75.0504, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on Route 38 at Cuthbert Boulevard.');
