INSERT INTO public.stormevents_east VALUES (751062, 201806, 11, 338, 201806, 11, 420, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flood', 'PHI', '11-JUN-18 03:38:00', 'EST-5', '11-JUN-18 04:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'EVANSVILLE', 1, 'S', 'EWANSVILLE', 39.9665, -74.7479, 39.9658, -74.7288, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on U.S. Highway 206 southbound south of Route 38 in Southampton Twp. Lane restrictions in place.');
INSERT INTO public.stormevents_east VALUES (751065, 201806, 11, 402, 201806, 11, 430, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flood', 'PHI', '11-JUN-18 04:02:00', 'EST-5', '11-JUN-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'WHITESVILLE', 1, 'WNW', 'WHITESVILLE', 40.08, -74.31, 40.0786, -74.2902, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on County Road 528 northbound near County Road 638.');
INSERT INTO public.stormevents_east VALUES (751067, 201806, 11, 428, 201806, 11, 500, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flood', 'PHI', '11-JUN-18 04:28:00', 'EST-5', '11-JUN-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GLOUCESTER HGTS', 0, 'ESE', 'BELLMAWR', 39.87, -75.1, 39.8686, -75.0768, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Flooding on I-295 northbound approaching the I-76/I-276 interchange. Lane restrictions in place.');
INSERT INTO public.stormevents_east VALUES (752141, 201806, 11, 20, 201806, 11, 220, 125032, 'NEW JERSEY', 34, 2018, 'June', 'Flash Flood', 'PHI', '11-JUN-18 00:20:00', 'EST-5', '11-JUN-18 02:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'RIVERSIDE', 2, 'SE', 'RIVERSIDE', 40.0119, -74.9307, 40.0104, -74.9287, 'Torrential rain occurred on the night of June 10 across parts of southeastern Pennsylvania, and central and southern New Jersey. Rainfall totals up to 3 to 6 inches were reported.', 'Water rescues along and around Willow Bend Drive in Delran Township.  At least five individuals were rescued from vehicles that were stranded in flood waters.');
INSERT INTO public.stormevents_east VALUES (749188, 201806, 4, 1505, 201806, 4, 1505, 124887, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '04-JUN-18 15:05:00', 'EST-5', '04-JUN-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 47, 'MG', NULL, NULL, 8, 'NE', 'CAPE CANAVERAL', 8, 'NE', 'CAPE CANAVERAL', 28.4624, -80.5105, 28.4624, -80.5105, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating, conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast where a few intensified. One severe thunderstorm produced strong to severe winds along the Brevard County Coast. A second thunderstorm produced strong winds along the St. Lucie County coast.', 'US Air Force wind tower 0003 measured a peak wind gust of 47 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (749189, 201806, 4, 1505, 201806, 4, 1505, 124887, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '04-JUN-18 15:05:00', 'EST-5', '04-JUN-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 45, 'MG', NULL, NULL, 2, 'E', '(TIX) SPACE CENTER EXEC', 2, 'E', '(TIX) SPACE CENTER EXEC', 28.5142, -80.7642, 28.5142, -80.7642, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating, conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast where a few intensified. One severe thunderstorm produced strong to severe winds along the Brevard County Coast. A second thunderstorm produced strong winds along the St. Lucie County coast.', 'The AWOS at the Space Coast Regional Airport in Titusville, KTIX, measured a peak wind gust of 45 knots from the north.');
INSERT INTO public.stormevents_east VALUES (749634, 201806, 8, 1252, 201806, 8, 1302, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 12:52:00', 'EST-5', '08-JUN-18 13:02:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Public', 60, 'EG', NULL, NULL, 2, 'SSW', 'FOX', 2, 'SSW', 'FOX', 39.6014, -83.0429, 39.6014, -83.0429, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'A roof was blown off an attached sun room. In addition, a barn was destroyed and multiple trees were blown down.');
INSERT INTO public.stormevents_east VALUES (749190, 201806, 4, 1510, 201806, 4, 1510, 124887, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '04-JUN-18 15:10:00', 'EST-5', '04-JUN-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 50, 'MG', NULL, NULL, 2, 'NW', 'CAPE CANAVERAL', 2, 'NW', 'CAPE CANAVERAL', 28.4, -80.6229, 28.4, -80.6229, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating, conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast where a few intensified. One severe thunderstorm produced strong to severe winds along the Brevard County Coast. A second thunderstorm produced strong winds along the St. Lucie County coast.', 'US Air Force wind tower 0300 measured a peak wind gust of 50 knots from the north.');
INSERT INTO public.stormevents_east VALUES (772522, 201806, 28, 900, 201806, 28, 1015, 125951, 'TENNESSEE', 47, 2018, 'June', 'Flash Flood', 'MRX', '28-JUN-18 09:00:00', 'EST-5', '28-JUN-18 10:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Park/Forest Service', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'ELKMONT', 1, 'N', 'ELKMONT', 35.6602, -83.5674, 35.6645, -83.58, 'Repeat convection along a slow moving frontal boundary over a lengthy period generated wind damage and flash flooding across Southeast Tennessee from the evening hours into the following morning.', 'Flooding in the GSMNP near the Elkmont area.');
INSERT INTO public.stormevents_east VALUES (749631, 201806, 8, 1215, 201806, 8, 1225, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 12:15:00', 'EST-5', '08-JUN-18 12:25:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'W', 'COLUMBUS SO COLUMBUS', 1, 'W', 'COLUMBUS SO COLUMBUS', 39.88, -82.98, 39.88, -82.98, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Three large power poles were knocked down along Obetz Road between Lockbourne and Parsons Avenues.');
INSERT INTO public.stormevents_east VALUES (749632, 201806, 8, 1240, 201806, 8, 1250, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 12:40:00', 'EST-5', '08-JUN-18 12:50:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 3, 'WNW', 'CIRCLEVILLE CLRKS AR', 3, 'WNW', 'CIRCLEVILLE CLRKS AR', 39.67, -83.07, 39.67, -83.07, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Numerous trees were damaged along Darby Road.');
INSERT INTO public.stormevents_east VALUES (749633, 201806, 8, 1250, 201806, 8, 1300, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 12:50:00', 'EST-5', '08-JUN-18 13:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 3, 'SW', 'FOX', 3, 'SW', 'FOX', 39.6, -83.05, 39.6, -83.05, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Multiple trees were reported down throughout the county.');
INSERT INTO public.stormevents_east VALUES (749635, 201806, 8, 1346, 201806, 8, 1356, 124954, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'ILN', '08-JUN-18 13:46:00', 'EST-5', '08-JUN-18 13:56:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SW', 'GIBISONVILLE', 2, 'SW', 'GIBISONVILLE', 39.48, -82.6, 39.48, -82.6, 'Scattered thunderstorms developed ahead of an upper level disturbance in a moist and unstable air mass.  Some of the storms produce torrential rainfall with amounts as high as 4 to 5 inches.', 'Multiple trees were knocked down.');
INSERT INTO public.stormevents_east VALUES (751986, 201806, 21, 2125, 201806, 22, 25, 125365, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '21-JUN-18 21:25:00', 'EST-5', '22-JUN-18 00:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'POTTERSBURG', 1, 'SW', 'RAYMOND', 40.27, -83.5, 40.3202, -83.4811, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general, with locally higher amounts.', 'A few creeks remained out of their banks across the western part of Union County. High water was also reported on several roads across the county.');
INSERT INTO public.stormevents_east VALUES (754271, 201806, 21, 2130, 201806, 21, 2330, 125365, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '21-JUN-18 21:30:00', 'EST-5', '21-JUN-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'MARYSVILLE', 2, 'NNE', 'MARYSVILLE', 40.2629, -83.3591, 40.2625, -83.359, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general, with locally higher amounts.', 'A small stream overflowed it banks, causing water, eight inches deep, to flow over the road at County Home Road and Navin Road.');
INSERT INTO public.stormevents_east VALUES (751989, 201806, 22, 820, 201806, 22, 1120, 125365, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '22-JUN-18 08:20:00', 'EST-5', '22-JUN-18 11:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'OREVILLE', 2, 'ESE', 'LOGAN OWENS FLD ARPT', 39.5647, -82.2304, 39.5942, -82.3345, 'Showers developed in a very moist tropical air mass, which was located ahead of a slow moving upper low. Between 1 and 3 inches of rain fell in general, with locally higher amounts.', 'Numerous roads remained closed, mainly across the eastern and southern part of the county. This included State Route 595 between U.S. 33 and the Perry County line; State Route 328 between State Route 56 and U.S. 33; State Route 216 between Murray City and the Perry County line; State Route 93 between Logan and the Perry County line, and portions of State Route 56 between Laurelville and the Vinton County line and where it enters Hocking County again to State Route 278.');
INSERT INTO public.stormevents_east VALUES (753335, 201806, 22, 1150, 201806, 22, 1450, 125610, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '22-JUN-18 11:50:00', 'EST-5', '22-JUN-18 14:50:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'POTTERSBURG', 1, 'W', 'WEST MARYSVILLE', 40.24, -83.48, 40.227, -83.4042, 'Showers and thunderstorms developed ahead of a low pressure system. Between 1 and 3 inches of rain fell in general.', 'There were numerous reports of vehicles stalled in high water, with several roads closed.');
INSERT INTO public.stormevents_east VALUES (753337, 201806, 22, 1222, 201806, 22, 1522, 125610, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '22-JUN-18 12:22:00', 'EST-5', '22-JUN-18 15:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'DELAWARE ARPT', 2, 'NNW', 'DELAWARE ARPT', 40.3022, -83.1169, 40.3018, -83.1186, 'Showers and thunderstorms developed ahead of a low pressure system. Between 1 and 3 inches of rain fell in general.', 'U.S. 36 at Lehner Wood Road was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (753342, 201806, 22, 1223, 201806, 22, 1523, 125610, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '22-JUN-18 12:23:00', 'EST-5', '22-JUN-18 15:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'OSTRANDER', 1, 'NW', 'OSTRANDER', 40.2831, -83.2319, 40.2818, -83.2316, 'Showers and thunderstorms developed ahead of a low pressure system. Between 1 and 3 inches of rain fell in general.', 'Burnt Pond Road near Fontanelle Rd was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (753693, 201806, 22, 1223, 201806, 22, 1423, 125610, 'OHIO', 39, 2018, 'June', 'Flood', 'ILN', '22-JUN-18 12:23:00', 'EST-5', '22-JUN-18 14:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'WARRENSBURG', 2, 'NW', 'DELAWARE ARPT', 40.31, -83.13, 40.3007, -83.1277, 'Showers and thunderstorms developed ahead of a low pressure system. Between 1 and 3 inches of rain fell in general.', 'South Section Line Road north of U.S. 36 was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (765601, 201806, 8, 1654, 201806, 8, 1654, 125822, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'TAE', '08-JUN-18 16:54:00', 'EST-5', '08-JUN-18 16:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 6, 'WSW', 'GREENVILLE', 6, 'WSW', 'GREENVILLE', 30.45, -83.72, 30.45, -83.72, 'Scattered to numerous showers and thunderstorms occurred across the area. As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A few trees were blown down at Mile Marker 237 and 239 on I-10.');
INSERT INTO public.stormevents_east VALUES (791719, 201812, 2, 1510, 201812, 2, 1520, 132316, 'GEORGIA', 13, 2018, 'December', 'Tornado', 'JAX', '02-DEC-18 15:10:00', 'EST-5', '02-DEC-18 15:20:00', 4, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'N', 'ST MARYS ARPT', 8, 'NE', 'ST MARYS ARPT', 30.78, -81.55, 30.82, -81.44, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'National Weather Service Jacksonville Storm Survey|revealed  damage consistent with EF-3 tornado damage at Naval |Submarine Base Kings Bay, which was confirmed by a 125 knot / 144 |mph maximum wind gust measurement from a docked Coast Guard |vessel. This is the strongest tornado in recent memory within the |National Weather Service Jacksonville''s area of responsibility in |southeast Georgia, northeast and north central Florida. Four |injuries were reported by officials at Naval Submarine Base Kings |Bay. The tornado continued on an east-northeast path across |Cumberland Island, beginning from Old House Creek and exiting into|the Atlantic waters just south of the Stafford Beach Campground. |The tornado path across Cumberland Island was estimated by |Cumberland Island National Seashore park rangers to be |approximately one-third to one half mile wide. Significant tree |damage occurred within the tornado path across Cumberland Island, |with no structural damage reported. The main park road and several|trails on Cumberland Island were left impassable by the tree |damage.');
INSERT INTO public.stormevents_east VALUES (791721, 201812, 3, 1112, 201812, 3, 1112, 132317, 'FLORIDA', 12, 2018, 'December', 'Flood', 'JAX', '03-DEC-18 11:12:00', 'EST-5', '03-DEC-18 11:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'JACKSONVILLE', 2, 'SW', 'JACKSONVILLE', 30.3324, -81.6951, 30.3259, -81.6958, 'A very moist and unsettled weather pattern continued across the local area ahead of an approaching cold front. The front stalled across the local area, providing a focus for very heavy training rainfall.', 'McCoys creek was flooding near the intersection of McCoys Creek Blvd and Hollybrook Ave. Streets were impassable and water was approaching structures.');
INSERT INTO public.stormevents_east VALUES (781455, 201808, 31, 1930, 201808, 31, 2130, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 19:30:00', 'EST-5', '31-AUG-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BALTIMORE HIGHLANDS', 1, 'N', 'BALTIMORE HIGHLANDS', 39.2452, -76.6484, 39.2451, -76.648, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Hollins Ferry Road was closed due to flooding near Lansdowne Road.');
INSERT INTO public.stormevents_east VALUES (765745, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'NINEVEH', 2, 'W', 'NINEVEH', 39.0148, -78.2098, 39.0149, -78.2091, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Bowman Hollow Road flooded and closed at Sheep Run.');
INSERT INTO public.stormevents_east VALUES (781456, 201808, 31, 1930, 201808, 31, 2130, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 19:30:00', 'EST-5', '31-AUG-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BALTIMORE HIGHLANDS', 2, 'NNW', 'BALTIMORE HIGHLANDS', 39.2477, -76.6651, 39.2485, -76.6648, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Hammonds Ferry Road was closed due to flooding at Mine Bank Lane.');
INSERT INTO public.stormevents_east VALUES (765746, 201806, 22, 1152, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:52:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'RELIANCE', 2, 'ENE', 'RELIANCE', 39.0135, -78.2221, 39.0131, -78.2219, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Cauthorn Mill Road flooded and closed near West Run.');
INSERT INTO public.stormevents_east VALUES (765748, 201806, 22, 1155, 201806, 22, 1400, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 11:55:00', 'EST-5', '22-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 4, 'NW', 'CORDOVA', 4, 'NNW', 'CORDOVA', 38.5731, -78.0679, 38.5731, -78.0654, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Dulaney Road flooded and closed between Duckett Lane and Eggbornsville Road.');
INSERT INTO public.stormevents_east VALUES (765750, 201806, 22, 1334, 201806, 22, 1530, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 13:34:00', 'EST-5', '22-JUN-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'BEALETON', 0, 'SSW', 'BEALETON', 38.5666, -77.7721, 38.5669, -77.7717, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Remington Road flooded and closed near Meadfield Drive.');
INSERT INTO public.stormevents_east VALUES (765752, 201806, 22, 1410, 201806, 22, 1600, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:10:00', 'EST-5', '22-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LOCUST DALE', 1, 'S', 'LOCUST DALE', 38.3171, -78.1283, 38.3171, -78.1277, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'US 15 flooded and closed near Great Run.');
INSERT INTO public.stormevents_east VALUES (791795, 201812, 20, 1016, 201812, 20, 1016, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:16:00', 'EST-5', '20-DEC-18 10:16:00', 0, 0, 0, 0, NULL, NULL, 'Public', 36, 'MG', NULL, NULL, 7, 'SSE', 'CRESCENT BEACH', 7, 'SSE', 'CRESCENT BEACH', 29.67, -81.21, 29.67, -81.21, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'A citizens weather observing station at Marineland measured a peak wind gust of 41 mph in showers moving offshore.');
INSERT INTO public.stormevents_east VALUES (791797, 201812, 20, 1029, 201812, 20, 1029, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:29:00', 'EST-5', '20-DEC-18 10:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 5, 'NW', 'SAUF1 CMAN', 5, 'NW', 'SAUF1 CMAN', 29.91, -81.32, 29.91, -81.32, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatheflow sensor at Lewis measured a wind gust of 41 mph in showers.');
INSERT INTO public.stormevents_east VALUES (791798, 201812, 20, 1029, 201812, 20, 1029, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:29:00', 'EST-5', '20-DEC-18 10:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 45, 'MG', NULL, NULL, 6, 'N', 'CRESCENT BEACH', 6, 'N', 'CRESCENT BEACH', 29.86, -81.26, 29.86, -81.26, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'A wind gust of 52 mph was measured in showers that moved across the sensor.');
INSERT INTO public.stormevents_east VALUES (791799, 201812, 20, 1038, 201812, 20, 1038, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:38:00', 'EST-5', '20-DEC-18 10:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 13, 'WSW', 'MAYPORT NAS', 13, 'WSW', 'MAYPORT NAS', 30.34, -81.63, 30.34, -81.63, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow sensor at Terminal Channel measured a wind gust of 45 mph in showers that moved across the site.');
INSERT INTO public.stormevents_east VALUES (791800, 201812, 20, 1045, 201812, 20, 1045, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:45:00', 'EST-5', '20-DEC-18 10:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 1, 'NW', 'JACKSONVILLE BEACH', 1, 'NW', 'JACKSONVILLE BEACH', 30.29, -81.39, 30.29, -81.39, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow sensor at the Jacksonville Beach Pier measured a wind gust of 47 mph in showers that moved across the site.');
INSERT INTO public.stormevents_east VALUES (775270, 201808, 21, 2033, 201808, 21, 2033, 129384, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '21-AUG-18 20:33:00', 'EST-5', '21-AUG-18 20:33:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SW', 'BYNUM', 1, 'SW', 'BYNUM', 39.56, -76.38, 39.56, -76.38, 'A warm front lifted northward through the day across the area, while a cold front approached from the west. These boundaries interacted with a moist and unstable air mass and moderate wind shear to generate strong to locally severe thunderstorms.', 'Multiple trees were blown down in the Spenceola development. Trees were also blown down at the intersection of Bynum Road and Melrose Road, and along Ady Road.');
INSERT INTO public.stormevents_east VALUES (781459, 201808, 31, 2005, 201808, 31, 2205, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 20:05:00', 'EST-5', '31-AUG-18 22:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'HALETHORPE', 1, 'ENE', 'HALETHORPE', 39.2653, -76.6735, 39.2585, -76.6825, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Benson Avenue was closed due to flooding between Haverhill Road and Knecht Avenue.');
INSERT INTO public.stormevents_east VALUES (765392, 201806, 8, 2000, 201806, 8, 2245, 127636, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'PBZ', '08-JUN-18 20:00:00', 'EST-5', '08-JUN-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'NEW CUMBERLAND', 2, 'SW', 'NEW CUMBERLAND', 40.5249, -81.3366, 40.5312, -81.324, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'Henderson School Road was reported as completely submerged.');
INSERT INTO public.stormevents_east VALUES (781460, 201808, 31, 2055, 201808, 31, 2255, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 20:55:00', 'EST-5', '31-AUG-18 22:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'ABERDEEN', 1, 'NNE', 'ABERDEEN', 39.531, -76.1744, 39.5335, -76.1659, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Maxa Road was closed due to flooding and Robinhood Road was closed near Paradise Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (765393, 201806, 8, 1910, 201806, 8, 2045, 127636, 'OHIO', 39, 2018, 'June', 'Flood', 'PBZ', '08-JUN-18 19:10:00', 'EST-5', '08-JUN-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'MINGO JCT', 1, 'S', 'MINGO JCT', 40.3089, -80.6179, 40.3013, -80.6194, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'Flooding was reported along Commercial Avenue.');
INSERT INTO public.stormevents_east VALUES (765394, 201806, 8, 1700, 201806, 8, 1700, 127636, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'PBZ', '08-JUN-18 17:00:00', 'EST-5', '08-JUN-18 17:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'WSW', 'SPRING MTN', 2, 'WSW', 'SPRING MTN', 40.3885, -82.0791, 40.3885, -82.0791, 'A slow-moving frontal boundary draped across Ohio and Pennsylvania led to the development of thunderstorms during the afternoon and early evening.  Sufficient downdraft instability led to a couple storms producing modest tree damage, but flooding was the main imapact from the storms, particularly in southeast Ohio.', 'Single trees were reported down on both township roads 338 and 340.');
INSERT INTO public.stormevents_east VALUES (765423, 201806, 1, 1545, 201806, 1, 1645, 127642, 'NEW YORK', 36, 2018, 'June', 'Flash Flood', 'BUF', '01-JUN-18 15:45:00', 'EST-5', '01-JUN-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'KENNEDY', 2, 'ESE', 'WATERBORO', 42.1405, -79.0824, 42.1564, -79.0359, 'Strong to severe convection developed as a warm and sultry air mass interacted with several boundaries, including at least two ''pieces'' of a cold front, lake breeze boundaries, and several outflow boundaries. While there was very little shear for the storms to work with, MLCAPE values averaged 1500 J/kg. Given light unidirectional flow through at least 12,000 ft, slow moving downpours were the main concern.', 'I-86 eastbound was reported closed between exits 14 and 15 because of flooding.');
INSERT INTO public.stormevents_east VALUES (781461, 201808, 31, 2112, 201808, 31, 2312, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 21:12:00', 'EST-5', '31-AUG-18 23:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'ARNOLD', 1, 'S', 'ARNOLD', 39.0254, -76.5011, 39.0174, -76.4983, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'A water rescue in the 1500 Block of MD-2 Ritchie Highway.');
INSERT INTO public.stormevents_east VALUES (765415, 201806, 1, 1323, 201806, 1, 1323, 127642, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '01-JUN-18 13:23:00', 'EST-5', '01-JUN-18 13:23:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 58, 'EG', NULL, NULL, 1, 'S', 'CATO', 1, 'S', 'CATO', 43.16, -76.58, 43.16, -76.58, 'Strong to severe convection developed as a warm and sultry air mass interacted with several boundaries, including at least two ''pieces'' of a cold front, lake breeze boundaries, and several outflow boundaries. While there was very little shear for the storms to work with, MLCAPE values averaged 1500 J/kg. Given light unidirectional flow through at least 12,000 ft, slow moving downpours were the main concern.', 'Trees down in Cato.');
INSERT INTO public.stormevents_east VALUES (765416, 201806, 1, 1511, 201806, 1, 1511, 127642, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '01-JUN-18 15:11:00', 'EST-5', '01-JUN-18 15:11:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'S', 'CANASERAGA', 1, 'S', 'CANASERAGA', 42.46, -77.78, 42.46, -77.78, 'Strong to severe convection developed as a warm and sultry air mass interacted with several boundaries, including at least two ''pieces'' of a cold front, lake breeze boundaries, and several outflow boundaries. While there was very little shear for the storms to work with, MLCAPE values averaged 1500 J/kg. Given light unidirectional flow through at least 12,000 ft, slow moving downpours were the main concern.', 'Pictures of several trees down on Twitter.');
