INSERT INTO public.stormevents_east VALUES (781454, 201808, 31, 1930, 201808, 31, 2005, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 19:30:00', 'EST-5', '31-AUG-18 20:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'HALETHORPE', 1, 'SSE', 'HALETHORPE', 39.24, -76.6922, 39.24, -76.692, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The stream gauge crested at 8.11 feet. At this level, water covers yards near Tom Day Boulevard. Water approaches structures along the creek, and approaches the top of the culvert at Sulphur Spring road.');
INSERT INTO public.stormevents_east VALUES (781462, 201808, 31, 2117, 201808, 31, 2317, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 21:17:00', 'EST-5', '31-AUG-18 23:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'WEST ANNAPOLIS', 1, 'WNW', 'NAVAL ACADEMY', 38.9886, -76.4964, 38.9837, -76.4895, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'MD-450 King George Street Bridge was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (781463, 201808, 31, 2130, 201808, 31, 2330, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 21:30:00', 'EST-5', '31-AUG-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'WEST ANNAPOLIS', 0, 'NW', 'WEST ANNAPOLIS', 38.9832, -76.5055, 38.983, -76.5057, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'A water rescue occurred at the intersection of Taylor Avenue and Melrose Street.');
INSERT INTO public.stormevents_east VALUES (774364, 201807, 17, 1410, 201807, 17, 1600, 128271, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '17-JUL-18 14:10:00', 'EST-5', '17-JUL-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'NORTH LINTHICUM', 0, 'E', 'NORTH LINTHICUM', 39.2207, -76.645, 39.2209, -76.6437, 'Heavy rain developed in the DC/Baltimore corridor during the afternoon of July 17th ahead of an approaching cold front. Rainfall of 1 to 3 inches caused flooding and isolated flash flooding, mainly in the Baltimore metro area.', 'Nursery Road flooded and closed near Maryland 648 due to rapidly rising water.');
INSERT INTO public.stormevents_east VALUES (763515, 201806, 2, 1116, 201806, 2, 1300, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 11:16:00', 'EST-5', '02-JUN-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'LANDES', 3, 'SSW', 'LANDES', 38.8556, -79.2259, 38.8564, -79.2254, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'US 220 was flooded with water 2 to 3 feet deep near the Grant Pendleton County border.');
INSERT INTO public.stormevents_east VALUES (763516, 201806, 2, 1130, 201806, 2, 1330, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flash Flood', 'LWX', '02-JUN-18 11:30:00', 'EST-5', '02-JUN-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BRUSHY RUN', 1, 'WNW', 'BRUSHY RUN', 38.8364, -79.2469, 38.8372, -79.2446, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Rising water on Brushy Run forced evacuations of several structures.');
INSERT INTO public.stormevents_east VALUES (763517, 201806, 2, 1200, 201806, 2, 1400, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 12:00:00', 'EST-5', '02-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'FRANKLIN', 3, 'ENE', 'FRANKLIN', 38.67, -79.29, 38.67, -79.2888, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'US 33 flooded and closed east of Franklin.');
INSERT INTO public.stormevents_east VALUES (763518, 201806, 2, 1410, 201806, 2, 1600, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 14:10:00', 'EST-5', '02-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'KESSEL', 1, 'E', 'KESSEL', 39.0693, -79.0145, 39.0697, -79.014, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Darlington School Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (763519, 201806, 2, 1413, 201806, 2, 1600, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 14:13:00', 'EST-5', '02-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'HISER', 1, 'NNW', 'HISER', 38.9834, -79.1251, 38.9835, -79.1248, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Franklin Pike flooded and closed south of Petersburg. Voluntary evacuations in the area.');
INSERT INTO public.stormevents_east VALUES (763617, 201806, 1, 2348, 201806, 1, 2348, 126475, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '01-JUN-18 23:48:00', 'EST-5', '01-JUN-18 23:48:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'HAVRE DE GRACE (HAVDG)', 0, 'N', 'HAVRE DE GRACE (HAVDG)', 39.55, -76.11, 39.55, -76.11, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'A wind gust of 34 knots was reported 1 mile east of Havre De Grace.');
INSERT INTO public.stormevents_east VALUES (763622, 201806, 10, 1909, 201806, 10, 1909, 126477, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '10-JUN-18 19:09:00', 'EST-5', '10-JUN-18 19:09:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 44, 'MG', NULL, NULL, 3, 'NNW', 'PATUXENT RIVER ASOS (KNAK)', 3, 'NNW', 'PATUXENT RIVER ASOS (KNAK)', 38.3268, -76.4261, 38.3268, -76.4261, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms produce gusty winds.', 'A wind gust of 44 knots was reported.');
INSERT INTO public.stormevents_east VALUES (753862, 201805, 12, 1950, 201805, 12, 1950, 125698, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '12-MAY-18 19:50:00', 'EST-5', '12-MAY-18 19:50:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 53, 'MG', NULL, NULL, 1, 'SSE', 'NAVAL ACADEMY', 1, 'SSE', 'NAVAL ACADEMY', 38.9684, -76.477, 38.9684, -76.477, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'A wind gust of 61 mph was reported at Greenbury.');
INSERT INTO public.stormevents_east VALUES (753863, 201805, 12, 1846, 201805, 12, 1846, 125700, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '12-MAY-18 18:46:00', 'EST-5', '12-MAY-18 18:46:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 2, 'WSW', 'MERRIFIELD', 2, 'WSW', 'MERRIFIELD', 38.86, -77.26, 38.86, -77.26, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. An isolated thunderstorm became severe.', 'Hail up to the size of quarters was reported.');
INSERT INTO public.stormevents_east VALUES (753868, 201805, 13, 1717, 201805, 13, 1717, 125701, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '13-MAY-18 17:17:00', 'EST-5', '13-MAY-18 17:17:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'N', 'MONUMENT MILLS', 2, 'N', 'MONUMENT MILLS', 38.6241, -78.0061, 38.6241, -78.0061, 'A few showers and thunderstorms developed near a stationary front. Some storms became severe due to an unstable atmosphere.', 'Hail up to the size of quarters was reported.');
INSERT INTO public.stormevents_east VALUES (753870, 201805, 13, 2118, 201805, 13, 2118, 125701, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '13-MAY-18 21:18:00', 'EST-5', '13-MAY-18 21:18:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'W', 'MT VERNON', 1, 'W', 'MT VERNON', 38.7185, -77.1076, 38.7185, -77.1076, 'A few showers and thunderstorms developed near a stationary front. Some storms became severe due to an unstable atmosphere.', 'Quarter sized hail was reported.');
