INSERT INTO public.stormevents_east VALUES (753874, 201805, 13, 1747, 201805, 13, 1747, 125701, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '13-MAY-18 17:47:00', 'EST-5', '13-MAY-18 17:47:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'ELKWOOD', 2, 'E', 'ELKWOOD', 38.5143, -77.8118, 38.5143, -77.8118, 'A few showers and thunderstorms developed near a stationary front. Some storms became severe due to an unstable atmosphere.', 'A tree was down on power lines on Newbys Shop Road near Lewis Lane.');
INSERT INTO public.stormevents_east VALUES (753875, 201805, 13, 1830, 201805, 13, 1830, 125702, 'WEST VIRGINIA', 54, 2018, 'May', 'Hail', 'LWX', '13-MAY-18 18:30:00', 'EST-5', '13-MAY-18 18:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'NW', 'HOLTON', 2, 'NW', 'HOLTON', 39.619, -78.0897, 39.619, -78.0897, 'A few showers and thunderstorms developed near a stationary front. Some storms became severe due to an unstable atmosphere.', 'Quarter sized hail was reported.');
