INSERT INTO public.stormevents_east VALUES (763106, 201806, 25, 1736, 201806, 25, 1738, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 17:36:00', 'EST-5', '25-JUN-18 17:38:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 1, 'N', 'SOUTH LYNCHBURG', 1, 'N', 'SOUTH LYNCHBURG', 34.06, -80.07, 34.06, -80.07, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'SCHP reported trees down at SC 341 and US Hwy 76 in Lynchburg.');
