INSERT INTO public.stormevents_east VALUES (783174, 201808, 31, 1844, 201808, 31, 2030, 130416, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '31-AUG-18 18:44:00', 'EST-5', '31-AUG-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'CARSINS RUN', 1, 'NE', 'CARSINS RUN', 39.5375, -76.2122, 39.5375, -76.2118, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'Carsins Runs Road bridge was closed near MD-22 due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (776190, 201807, 21, 2138, 201807, 21, 2230, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 21:38:00', 'EST-5', '21-JUL-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'CLOPPER', 1, 'NNW', 'CLOPPER', 39.1598, -77.2338, 39.1599, -77.2334, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Vehicle stranded in high water after torrential rains on Game Preserve Road near I-270.');
INSERT INTO public.stormevents_east VALUES (776192, 201807, 21, 2030, 201807, 21, 2230, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 20:30:00', 'EST-5', '21-JUL-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LIME KILN', 1, 'NNW', 'LIME KILN', 39.3618, -77.4342, 39.3618, -77.4336, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Lime Kiln Way flooded and closed near English Muffin Way.');
INSERT INTO public.stormevents_east VALUES (776193, 201807, 21, 2133, 201807, 21, 2230, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:33:00', 'EST-5', '21-JUL-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WALKERSVILLE', 1, 'SE', 'WALKERSVILLE', 39.4745, -77.341, 39.474, -77.3408, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Water rescue reported on Crum Road at Israel Creek.');
INSERT INTO public.stormevents_east VALUES (776198, 201807, 21, 2200, 201807, 21, 2300, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 22:00:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'HUNTING HILL', 2, 'WSW', 'HUNTING HILL', 39.0936, -77.2501, 39.0932, -77.2496, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'A swift water rescue occurred on Quince Orchard Road near Muddy Branch.');
INSERT INTO public.stormevents_east VALUES (776200, 201807, 21, 2206, 201807, 21, 2300, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 22:06:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'PARKWOOD', 1, 'SSE', 'PARKWOOD', 39.0092, -77.0776, 39.0091, -77.0771, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'A swift water rescue occurred on Beach Drive near Kensington Parkway along Rock Creek.');
INSERT INTO public.stormevents_east VALUES (776203, 201807, 21, 2223, 201807, 21, 2315, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 22:23:00', 'EST-5', '21-JUL-18 23:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'CLARKSBURG', 1, 'ESE', 'CLARKSBURG', 39.2215, -77.2598, 39.2216, -77.2596, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'A swift water rescue was performed on Frederick Road (Maryland State Route 355) at Little Seneca Creek.');
INSERT INTO public.stormevents_east VALUES (763629, 201806, 21, 2008, 201806, 21, 2013, 127395, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '21-JUN-18 20:08:00', 'EST-5', '21-JUN-18 20:13:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 42, 'MG', NULL, NULL, 2, 'E', 'BABAR POINT (BAB)', 2, 'E', 'BABAR POINT (BAB)', 38.3089, -77.0019, 38.3089, -77.0019, 'An isolated thunderstorm produced gusty winds.', 'A wind gust of 42 knots was reported at Pylons DAH.');
INSERT INTO public.stormevents_east VALUES (763631, 201806, 22, 1030, 201806, 22, 1030, 127396, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '22-JUN-18 10:30:00', 'EST-5', '22-JUN-18 10:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'LEWISETTA (LWS)', 0, 'N', 'LEWISETTA (LWS)', 38, -76.47, 38, -76.47, 'An isolated thunderstorm produced gusty winds.', 'A wind gust in excess of 30 knots was reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (764133, 201806, 2, 1413, 201806, 2, 1600, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 14:13:00', 'EST-5', '02-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'HISER', 1, 'SSW', 'HISER', 38.9574, -79.1328, 38.957, -79.1308, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'North Mill Creek Road flooded and closed, with voluntary evacuations of the area.');
INSERT INTO public.stormevents_east VALUES (753878, 201805, 14, 1326, 201805, 14, 1326, 125705, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 13:26:00', 'EST-5', '14-MAY-18 13:26:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 0, 'WNW', 'VERONA', 0, 'WNW', 'VERONA', 38.2016, -79.0069, 38.2016, -79.0069, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Quarter sized hail was reported.');
