INSERT INTO public.stormevents_east VALUES (768002, 201806, 3, 1939, 201806, 3, 1939, 128054, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '03-JUN-18 19:39:00', 'EST-5', '03-JUN-18 19:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'W', 'ROCKWELL', 1, 'W', 'ROCKWELL', 35.55, -80.44, 35.55, -80.44, 'Scattered thunderstorms developed across the southern Appalachians throughout the afternoon and moved southeast. Several storms produced brief severe weather in the form of large hail and damaging winds across the North Carolina mountains and foothills.', 'Spotter reported multiple trees blown down near Rockwell, with one down on a house.');
