INSERT INTO public.stormevents_east VALUES (765767, 201806, 22, 1410, 201806, 22, 1600, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:10:00', 'EST-5', '22-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'PEOLA MILLS', 1, 'N', 'PEOLA MILLS', 38.5442, -78.2738, 38.5437, -78.2727, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Champe Plain Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (765770, 201806, 22, 1410, 201806, 22, 1600, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:10:00', 'EST-5', '22-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'PEOLA MILLS', 2, 'ENE', 'PEOLA MILLS', 38.5416, -78.2447, 38.5411, -78.244, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Roads closed due to flooding in the vicinity of F.T. Valley Road, Hughes River Road, and Nethers Road.');
