INSERT INTO public.stormevents_east VALUES (759334, 201806, 24, 2022, 201806, 24, 2024, 126673, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '24-JUN-18 20:22:00', 'EST-5', '24-JUN-18 20:24:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 55, 'EG', NULL, NULL, 2, 'WSW', 'WARD STATION', 2, 'WSW', 'WARD STATION', 34.26, -78.86, 34.26, -78.86, 'An approaching cold front produced strong storms in SE North Carolina.', 'Trees were blown down across the road.');
INSERT INTO public.stormevents_east VALUES (765439, 201806, 13, 1542, 201806, 13, 1542, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 15:42:00', 'EST-5', '13-JUN-18 15:42:00', 0, 0, 0, 0, '50.00K', '0.00K', 'NWS Employee', 52, 'EG', NULL, NULL, 0, 'N', 'HARRIS HILL', 0, 'N', 'HARRIS HILL', 42.95, -78.67, 42.95, -78.67, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Several parked tractor trailers tipped over.');
INSERT INTO public.stormevents_east VALUES (765440, 201806, 13, 1623, 201806, 13, 1623, 127651, 'LAKE ERIE', 95, 2018, 'June', 'Marine Thunderstorm Wind', 'BUF', '13-JUN-18 16:23:00', 'EST-5', '13-JUN-18 16:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 51, 'MG', NULL, NULL, 2, 'WNW', 'DUNKIRK', 2, 'WNW', 'DUNKIRK', 42.4977, -79.3594, 42.4977, -79.3594, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', NULL);
INSERT INTO public.stormevents_east VALUES (765442, 201806, 13, 1702, 201806, 13, 1702, 127654, 'NEW YORK', 36, 2018, 'June', 'Hail', 'BUF', '13-JUN-18 17:02:00', 'EST-5', '13-JUN-18 17:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1.5, NULL, NULL, NULL, 1, 'W', 'MACHIAS', 1, 'W', 'MACHIAS', 42.42, -78.5, 42.42, -78.5, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', NULL);
