INSERT INTO public.stormevents_east VALUES (763113, 201806, 25, 1848, 201806, 25, 1853, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:48:00', 'EST-5', '25-JUN-18 18:53:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 3, 'NNW', 'SUPREME', 3, 'NNW', 'SUPREME', 33.86, -81.94, 33.86, -81.94, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Multiple trees down across Edgefield Co.');
INSERT INTO public.stormevents_east VALUES (763115, 201806, 25, 1910, 201806, 25, 1915, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:10:00', 'EST-5', '25-JUN-18 19:15:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 60, 'EG', NULL, NULL, 2, 'S', 'HELENA', 2, 'S', 'HELENA', 34.25, -81.63, 34.25, -81.63, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Newberry Co dispatch reported at least 20 trees down across the county.');
INSERT INTO public.stormevents_east VALUES (763116, 201806, 25, 1915, 201806, 25, 1920, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:15:00', 'EST-5', '25-JUN-18 19:20:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 60, 'EG', NULL, NULL, 1, 'N', 'AIKEN', 1, 'N', 'AIKEN', 33.56, -81.72, 33.56, -81.72, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Multiple trees down throughout the county.');
INSERT INTO public.stormevents_east VALUES (763118, 201806, 25, 1956, 201806, 25, 1959, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 19:56:00', 'EST-5', '25-JUN-18 19:59:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 60, 'EG', NULL, NULL, 4, 'NNW', 'HEALING SPGS', 4, 'NNW', 'HEALING SPGS', 33.45, -81.3, 33.45, -81.3, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'SC DOT reported multiple trees down in Barnwell Co between Barnwell and the south fork of the Edisto River, including Magnolia Lane, SC Hwy 3, SC Hwy 39, and SC Hwy 304.');
INSERT INTO public.stormevents_east VALUES (763119, 201806, 25, 2018, 201806, 25, 2020, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 20:18:00', 'EST-5', '25-JUN-18 20:20:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 55, 'EG', NULL, NULL, 1, 'NNW', 'SATO', 1, 'NNW', 'SATO', 33.3308, -81.1338, 33.3308, -81.1338, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'SCHP reported trees down on Guess Dr in Denmark. Time estimated.');
INSERT INTO public.stormevents_east VALUES (763120, 201806, 25, 1841, 201806, 25, 1841, 126890, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:41:00', 'EST-5', '25-JUN-18 18:41:00', 0, 0, 0, 0, '0.00K', NULL, 'ASOS', 41, 'MG', NULL, NULL, 0, 'WSW', 'AUGUSTA DANIEL ARPT', 0, 'WSW', 'AUGUSTA DANIEL ARPT', 33.4671, -82.037, 33.4671, -82.037, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Augusta Daniel Field ASOS measured a wind gust of 41 kts (47 mph).');
INSERT INTO public.stormevents_east VALUES (763121, 201806, 25, 1852, 201806, 25, 1855, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:52:00', 'EST-5', '25-JUN-18 18:55:00', 0, 0, 0, 0, NULL, NULL, 'CoCoRaHS', 60, 'EG', NULL, NULL, 9, 'E', 'MERCHANT', 9, 'E', 'MERCHANT', 34.04, -81.52, 34.04, -81.52, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'CoCoRaHS observer reported strong winds that downed several trees in the area.');
INSERT INTO public.stormevents_east VALUES (763123, 201806, 25, 1800, 201806, 25, 1804, 126889, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:00:00', 'EST-5', '25-JUN-18 18:04:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 55, 'EG', NULL, NULL, 0, 'WNW', 'BEARD', 0, 'WNW', 'BEARD', 33.8527, -80.0567, 33.8527, -80.0567, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'Tree down along Salem Rd.');
INSERT INTO public.stormevents_east VALUES (751130, 201805, 4, 1823, 201805, 4, 1823, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:23:00', 'EST-5', '04-MAY-18 18:23:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 5, 'NNW', 'PAGE HILL', 5, 'NNW', 'PAGE HILL', 43.59, -74.41, 43.59, -74.41, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'Trees and wires were downed on Route 30 between Speculator and Indian Lake, resulting in a road closure.');
INSERT INTO public.stormevents_east VALUES (765596, 201806, 2, 1520, 201806, 2, 1520, 125383, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'TAE', '02-JUN-18 15:20:00', 'EST-5', '02-JUN-18 15:20:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'W', 'LEE', 4, 'W', 'LEE', 30.4, -83.36, 30.4, -83.36, 'Scattered to numerous showers and thunderstorms occurred across the area during the June 2-4 period.  As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'Trees and power lines were blown down.');
INSERT INTO public.stormevents_east VALUES (765598, 201806, 2, 1528, 201806, 2, 1528, 125383, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'TAE', '02-JUN-18 15:28:00', 'EST-5', '02-JUN-18 15:28:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'PERRY', 0, 'N', 'PERRY', 30.11, -83.58, 30.11, -83.58, 'Scattered to numerous showers and thunderstorms occurred across the area during the June 2-4 period.  As is typical with summer storms in this part of the country, some of the storms were marginally severe with impacts to trees and power lines.', 'A tree and power line were reported down near Highway 27 and San Pedro.');
INSERT INTO public.stormevents_east VALUES (759353, 201806, 25, 1630, 201806, 25, 1632, 126680, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '25-JUN-18 16:30:00', 'EST-5', '25-JUN-18 16:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 2, 'N', 'ALMA', 2, 'N', 'ALMA', 34.78, -79.33, 34.78, -79.33, 'Strong storms produced damage and small hail.', 'Robeson County Water Treatment Plant reported large limbs down and dime size hail.');
INSERT INTO public.stormevents_east VALUES (776205, 201807, 21, 2146, 201807, 21, 2300, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:46:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CLOPPER', 1, 'SE', 'CLOPPER', 39.1436, -77.2242, 39.1434, -77.2236, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Clopper Road flooded and closed near Firstfield Road. Around 18 inches of standing water reported in the area.');
INSERT INTO public.stormevents_east VALUES (776207, 201807, 21, 2147, 201807, 21, 2300, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:47:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'THURMONT', 1, 'ENE', 'THURMONT', 39.6228, -77.4091, 39.6231, -77.409, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'High water was reported on Main Street in the 100 block, causing a road closure.');
INSERT INTO public.stormevents_east VALUES (776208, 201807, 21, 2214, 201807, 21, 2345, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 22:14:00', 'EST-5', '21-JUL-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'URBANA', 1, 'SE', 'URBANA', 39.3173, -77.3342, 39.3178, -77.3336, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Urbana Pike flooded and closed near Big Woods Road at Bennett Creek.');
INSERT INTO public.stormevents_east VALUES (776210, 201807, 21, 2206, 201807, 21, 2345, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 22:06:00', 'EST-5', '21-JUL-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'MOUNTVILLE', 2, 'SSE', 'MOUNTVILLE', 39.0064, -77.6906, 39.006, -77.6902, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Snickersville Turnpike flooded and closed near Mountville.');
INSERT INTO public.stormevents_east VALUES (776212, 201807, 21, 2320, 201807, 22, 45, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 23:20:00', 'EST-5', '22-JUL-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'HALETHORPE', 2, 'W', 'WOODLAWN', 39.2476, -76.7024, 39.3245, -76.7611, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Several different swift water rescues ongoing in the corridor between Arbutus and Woodlawn.');
INSERT INTO public.stormevents_east VALUES (776213, 201807, 21, 2353, 201807, 22, 45, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 23:53:00', 'EST-5', '22-JUL-18 00:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'RIDGEVILLE', 1, 'WSW', 'RIDGEVILLE', 39.3658, -77.1786, 39.3658, -77.179, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Water rescue for vehicle stranded in rapidly rising water on Mill Bottom Road at Bush Creek.');
INSERT INTO public.stormevents_east VALUES (756019, 201806, 1, 2115, 201806, 1, 2115, 126019, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '01-JUN-18 21:15:00', 'EST-5', '01-JUN-18 21:15:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'S', 'FT DETRICK', 1, 'S', 'FT DETRICK', 39.4166, -77.4022, 39.4166, -77.4022, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'A pole and wires were down near the intersection of Third Street and East Church Street.');
INSERT INTO public.stormevents_east VALUES (756020, 201806, 1, 2125, 201806, 1, 2125, 126019, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '01-JUN-18 21:25:00', 'EST-5', '01-JUN-18 21:25:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'N', 'KEMPTOWN', 1, 'N', 'KEMPTOWN', 39.3462, -77.229, 39.3462, -77.229, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'A tree was down near the intersection of Bartholows road and Bill Moxley road.');
INSERT INTO public.stormevents_east VALUES (756021, 201806, 1, 2137, 201806, 1, 2137, 126019, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '01-JUN-18 21:37:00', 'EST-5', '01-JUN-18 21:37:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'SW', 'PLANE NUMBER FOUR', 1, 'SW', 'PLANE NUMBER FOUR', 39.3726, -77.2094, 39.3726, -77.2094, 'A weak cold front triggered a few showers and thunderstorms. Some storms became severe due to an unstable atmosphere.', 'A tree was down on Woodville road just north of MD-144 Old National Pike.');
INSERT INTO public.stormevents_east VALUES (764134, 201806, 2, 1415, 201806, 2, 1615, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 14:15:00', 'EST-5', '02-JUN-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'RUDDLE', 2, 'SSE', 'RUDDLE', 38.6863, -79.2886, 38.6863, -79.2882, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Keyser Gap Road closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (764135, 201806, 2, 1745, 201806, 2, 1945, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 17:45:00', 'EST-5', '02-JUN-18 19:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'ENGLE', 0, 'NW', 'ENGLE', 39.3546, -77.7847, 39.3547, -77.7867, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Kidwiler Road flooded and closed in the 700 block.');
INSERT INTO public.stormevents_east VALUES (764136, 201806, 2, 1749, 201806, 2, 2000, 127370, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '02-JUN-18 17:49:00', 'EST-5', '02-JUN-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'UVILLA', 0, 'N', 'UVILLA', 39.3737, -77.8005, 39.3739, -77.7992, 'Heavy rain of 1 to 4 inches fell on June 1st across the eastern West Virginia panhandle, causing flooding and a few instances of flash flooding in Hampshire County. Flooding continued into the overnight hours. Then, persistent rain on the 2nd renewed the flooding, along with isolated flash flooding in and near Pendleton County, where over three inches of rain was observed.', 'Shepherdstown Pike (Route 230) flooded and closed north of French Road.');
INSERT INTO public.stormevents_east VALUES (764831, 201806, 3, 1523, 201806, 3, 1700, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 15:23:00', 'EST-5', '03-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'WOODSTOCK', 2, 'N', 'WOODSTOCK', 39.3626, -76.9682, 39.3625, -76.9677, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'River Road flooded and closed at Route 851.');
INSERT INTO public.stormevents_east VALUES (764833, 201806, 3, 1951, 201806, 3, 2100, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 19:51:00', 'EST-5', '03-JUN-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'BROOKEVILLE', 1, 'E', 'BROOKEVILLE', 39.1817, -77.0666, 39.1807, -77.0606, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'Brookeville Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (764834, 201806, 3, 1957, 201806, 3, 2100, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 19:57:00', 'EST-5', '03-JUN-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'HENRYTON', 2, 'ENE', 'HENRYTON', 39.3633, -76.8859, 39.3639, -76.8831, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'Marriottsville Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (753886, 201805, 14, 1325, 201805, 14, 1325, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 13:25:00', 'EST-5', '14-MAY-18 13:25:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'WNW', 'VERONA', 2, 'WNW', 'VERONA', 38.2105, -79.0302, 38.2105, -79.0302, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree limb was down and siding damage was reported to a home.');
INSERT INTO public.stormevents_east VALUES (753889, 201805, 14, 1330, 201805, 14, 1330, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 13:30:00', 'EST-5', '14-MAY-18 13:30:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 19, 'SSW', 'HARRISONBURG', 19, 'SSW', 'HARRISONBURG', 38.2006, -79.0108, 38.2006, -79.0108, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A bank roof was damaged.');
INSERT INTO public.stormevents_east VALUES (753891, 201805, 14, 1405, 201805, 14, 1405, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 14:05:00', 'EST-5', '14-MAY-18 14:05:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NE', 'WOLFTOWN', 0, 'NE', 'WOLFTOWN', 38.354, -78.344, 38.354, -78.344, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down on Shelby and Wolftown Hood Road.');
INSERT INTO public.stormevents_east VALUES (753810, 201805, 10, 1515, 201805, 10, 1515, 125695, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '10-MAY-18 15:15:00', 'EST-5', '10-MAY-18 15:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1.5, NULL, NULL, NULL, 0, 'S', 'HILLSBORO', 0, 'S', 'HILLSBORO', 39.1977, -77.7204, 39.1977, -77.7204, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Quarter to ping pong sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (753811, 201805, 10, 1530, 201805, 10, 1530, 125695, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '10-MAY-18 15:30:00', 'EST-5', '10-MAY-18 15:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'NNW', 'WATERFORD', 2, 'NNW', 'WATERFORD', 39.2012, -77.6103, 39.2012, -77.6103, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (753813, 201805, 10, 1312, 201805, 10, 1312, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 13:12:00', 'EST-5', '10-MAY-18 13:12:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 50, 'EG', NULL, NULL, 3, 'SSE', 'FARMINGTON', 3, 'SSE', 'FARMINGTON', 38.011, -78.527, 38.011, -78.527, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Several trees were down along Sunset Boulevard.');
INSERT INTO public.stormevents_east VALUES (753815, 201805, 10, 1312, 201805, 10, 1312, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 13:12:00', 'EST-5', '10-MAY-18 13:12:00', 0, 0, 0, 0, '10.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 60, 'N', 'MADISONVILLE', 60, 'N', 'MADISONVILLE', 38.0374, -78.4857, 38.0374, -78.4857, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Several trees and power lines were down including one tree onto a structure.');
INSERT INTO public.stormevents_east VALUES (768295, 201806, 14, 2044, 201806, 14, 2044, 128112, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '14-JUN-18 20:44:00', 'EST-5', '14-JUN-18 20:44:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Emergency Manager', 55, 'EG', NULL, NULL, 1, 'SW', 'MOORESVILLE ARPT', 1, 'SW', 'MOORESVILLE ARPT', 35.607, -80.917, 35.607, -80.917, 'Scattered thunderstorms developed along the I-40 corridor in North Carolina during the evening and moved south across the Piedmont. A couple of storms produced brief damaging winds.', 'EM reported multiple large hardwood trees uprooted in the area centered around Hermance Ln, including trees down on Robinson Rd, Crusoe Rd, and Waddell Rd. One mobile home was destroyed by a large tree and another home sustained damage from a fallen tree.');
INSERT INTO public.stormevents_east VALUES (768360, 201806, 14, 2114, 201806, 14, 2118, 128112, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '14-JUN-18 21:14:00', 'EST-5', '14-JUN-18 21:18:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'LINCOLNTON', 0, 'SW', 'SOUTHSIDE', 35.481, -81.253, 35.445, -81.235, 'Scattered thunderstorms developed along the I-40 corridor in North Carolina during the evening and moved south across the Piedmont. A couple of storms produced brief damaging winds.', 'County comms reported around a half dozen trees blown down onto power lines and roads across the city of Lincolnton, including on E Sycamore St and N Cedar St. A tree was also on an apartment building on Tait St.');
INSERT INTO public.stormevents_east VALUES (768361, 201806, 14, 2008, 201806, 14, 2008, 128112, 'NORTH CAROLINA', 37, 2018, 'June', 'Hail', 'GSP', '14-JUN-18 20:08:00', 'EST-5', '14-JUN-18 20:08:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 0.75, NULL, NULL, NULL, 2, 'WSW', 'OSWALT', 2, 'WSW', 'OSWALT', 35.668, -80.896, 35.668, -80.896, 'Scattered thunderstorms developed along the I-40 corridor in North Carolina during the evening and moved south across the Piedmont. A couple of storms produced brief damaging winds.', 'Ham radio operator reported 3/4 inch hail along Perth Rd.');
INSERT INTO public.stormevents_east VALUES (768362, 201806, 16, 1442, 201806, 16, 1442, 128129, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '16-JUN-18 14:42:00', 'EST-5', '16-JUN-18 14:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NNW', 'ARIAL', 2, 'NW', 'ARIAL', 34.883, -82.645, 34.874, -82.655, 'Isolated to widely scattered thunderstorms developed along the Blue Ridge escarpment during the afternoon and moved southeast into the foothills, where a couple of the storms produced brief damaging wind gusts.', 'Highway patrol reported a tree blown down at Highway 183 and Cedar Rock Rd and multiple trees and power lines blown down along Ireland Rd.');
INSERT INTO public.stormevents_east VALUES (768363, 201806, 16, 1446, 201806, 16, 1457, 128129, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '16-JUN-18 14:46:00', 'EST-5', '16-JUN-18 14:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'WNW', 'ARIAL', 1, 'SE', 'EASLEY', 34.854, -82.644, 34.819, -82.583, 'Isolated to widely scattered thunderstorms developed along the Blue Ridge escarpment during the afternoon and moved southeast into the foothills, where a couple of the storms produced brief damaging wind gusts.', 'FD reported multiple trees and power lines blown down at Store Road and Cedar Rock Church Road and a tree down on Ballentine St at Brushy Creek Rd in Easley.');
INSERT INTO public.stormevents_east VALUES (768364, 201806, 16, 1535, 201806, 16, 1535, 128129, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '16-JUN-18 15:35:00', 'EST-5', '16-JUN-18 15:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 4, 'NNE', 'GREENVILLE', 4, 'NNE', 'GREENVILLE', 34.9035, -82.373, 34.9035, -82.373, 'Isolated to widely scattered thunderstorms developed along the Blue Ridge escarpment during the afternoon and moved southeast into the foothills, where a couple of the storms produced brief damaging wind gusts.', 'NWS employee reported numerous large tree limbs blown down near Half Mile Lake.');
INSERT INTO public.stormevents_east VALUES (768365, 201806, 16, 1636, 201806, 16, 1636, 128129, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '16-JUN-18 16:36:00', 'EST-5', '16-JUN-18 16:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 0, 'N', 'UNION', 0, 'N', 'UNION', 34.72, -81.62, 34.72, -81.62, 'Isolated to widely scattered thunderstorms developed along the Blue Ridge escarpment during the afternoon and moved southeast into the foothills, where a couple of the storms produced brief damaging wind gusts.', 'County comms reported multiple trees and power lines blown down in the city of Union. Two of the trees fell on residences.');
INSERT INTO public.stormevents_east VALUES (751431, 201805, 4, 2014, 201805, 4, 2014, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 20:14:00', 'EST-5', '04-MAY-18 20:14:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'ENE', 'BRICK TAVERN', 2, 'ENE', 'BRICK TAVERN', 42.28, -73.69, 42.28, -73.69, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A tree and wires were reported down.');
INSERT INTO public.stormevents_east VALUES (751433, 201805, 4, 1913, 201805, 4, 1913, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 19:13:00', 'EST-5', '04-MAY-18 19:13:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 53, 'MG', NULL, NULL, 1, 'SE', '(GFL)GLENS FALLS ARP', 1, 'SE', '(GFL)GLENS FALLS ARP', 43.34, -73.61, 43.34, -73.61, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A gust of 61 miles per hour was recorded at the Floyd Bennett Memorial Airport (KGFL).');
INSERT INTO public.stormevents_east VALUES (751432, 201805, 4, 1840, 201805, 4, 1840, 125225, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'ALY', '04-MAY-18 18:40:00', 'EST-5', '04-MAY-18 18:40:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 52, 'MG', NULL, NULL, 2, 'ESE', 'JOHNSTOWN FULCO ARPT', 2, 'ESE', 'JOHNSTOWN FULCO ARPT', 42.99, -74.3, 42.99, -74.3, 'A powerful low pressure system formed on May 4th, pushing a strong cold front across eastern New York. A line of thunderstorms developed along this front in the afternoon and evening, resulting in widespread wind damage. Nearly 60,000 customers lost power as a result of the storms. Particularly intense damage occurred in the villages of Johnstown and Cambridge, the town of Hebron, and Saratoga National Historical Park, where dozens of trees were uprooted and snapped in concentrated swaths. Some of these trees fell onto cars and houses, resulting in property damage. The National Guard was deployed to assist with storm recovery in Washington County.||In the evening hours, strong non-thunderstorm winds developed behind the cold front, impacting portions of the southern Adirondacks. Winds gusted as high as 58 mph at Chestertown, and a few trees and limbs were downed.', 'A gust of 60 miles per hour was recorded at the New York State Mesonet site near Johnstown.');
INSERT INTO public.stormevents_east VALUES (758038, 201805, 15, 1656, 201805, 15, 1900, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 16:56:00', 'EST-5', '15-MAY-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'SINGERS GLEN', 1, 'W', 'DAPHNA', 38.5528, -78.905, 38.5809, -78.8139, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'Multiple roads flooded and closed in the central portion of Rockingham County, including Mount Zion Road and Lacey Spring Road.');
INSERT INTO public.stormevents_east VALUES (758039, 201805, 15, 2020, 201805, 15, 2120, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 20:20:00', 'EST-5', '15-MAY-18 21:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BURKE', 1, 'SSE', 'BURKE', 38.7886, -77.2665, 38.7875, -77.2665, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'Flooding reported near Pohick Creek at the intersection of Burke Road and Heritage Square Drive.');
INSERT INTO public.stormevents_east VALUES (755315, 201806, 22, 1530, 201806, 22, 1730, 125995, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'RLX', '22-JUN-18 15:30:00', 'EST-5', '22-JUN-18 17:30:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'GLENFORD', 1, 'WSW', 'GLENFORD', 39.8924, -82.3363, 39.8758, -82.3363, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'County Route 204 was closed near Glenford due to high water from flooding along Jonathan''s Creek.');
INSERT INTO public.stormevents_east VALUES (758042, 201805, 15, 2200, 201805, 16, 200, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 22:00:00', 'EST-5', '16-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'LEESBURG', 1, 'ESE', 'LEESBURG', 39.1149, -77.5254, 39.1136, -77.5255, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'Edwards Ferry Road flooded and closed east of Battlefield Parkway.');
INSERT INTO public.stormevents_east VALUES (758044, 201805, 15, 2200, 201805, 16, 200, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 22:00:00', 'EST-5', '16-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'CLARKES GAP', 1, 'WNW', 'LEESBURG', 39.1289, -77.5746, 39.1278, -77.5739, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'Old Waterford Road flooded and closed near Leesburg.');
INSERT INTO public.stormevents_east VALUES (758045, 201805, 15, 2221, 201805, 16, 200, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 22:21:00', 'EST-5', '16-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'PURCELLVILLE', 1, 'E', 'NORTH FORK', 39.14, -77.71, 39.0681, -77.713, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'Several roads reported flooded and closed in Loudoun County between Purcellville and Philomont.');
INSERT INTO public.stormevents_east VALUES (749179, 201806, 4, 1457, 201806, 4, 1457, 124886, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MLB', '04-JUN-18 14:57:00', 'EST-5', '04-JUN-18 14:57:00', 0, 0, 0, 0, NULL, '0.00K', 'Other Federal Agency', 56, 'EG', NULL, NULL, 1, 'S', '(TIX)SPACE CNTR EXEC', 1, 'S', '(TIX)SPACE CNTR EXEC', 28.51, -80.8, 28.51, -80.8, 'A late season frontal boundary moved slowly south across north Florida, while south of the boundary strong westerly flow was observed across central Florida. Deep moisture was in place across the area, and with cool temperatures aloft and daytime heating conditions became favorable for the development of scattered to numerous showers and thunderstorms in the afternoon. Some showers and storms formed across the interior counties early in the afternoon and pushed east towards the coast. One storm became severe as it moved across northern Brevard County where it produced wind damage at the Titusville Airport, along with small hail.', 'Airport personnel at the Space Coast Regional Airport, KTIX, in Titusville reported three small planes were flipped during a severe thunderstorm. NWS Melbourne confirmed that a severe downburst occurred over the airport, with winds estimated around 60-65 mph.');
INSERT INTO public.stormevents_east VALUES (749196, 201806, 5, 1423, 201806, 5, 1423, 124888, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MLB', '05-JUN-18 14:23:00', 'EST-5', '05-JUN-18 14:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 2, 'SE', 'PINE GROVE', 2, 'SE', 'PINE GROVE', 28.26, -81.15, 28.26, -81.15, 'Persistent westerly flow was observed across central Florida. Deep moisture was in place across the area, with cool temperatures aloft and daytime heating conditions became favorable for the development of scattered showers and thunderstorms in the afternoon. Dry mid-level air was observed in the upper air sounding, allowing storms to produce strong to severe wind gusts. Scattered showers and storms were ongoing across the area during the afternoon. One storm became severe in northeastern Osceola County where it produced wind damage near Harmony.', 'A trained spotter reported two 30-foot tall pine trees were knocked down by a severe thunderstorm. The spotter also mentioned the trees had a diameter of 8 inches. Winds are estimated at 60 mph.');
INSERT INTO public.stormevents_east VALUES (749198, 201806, 5, 1457, 201806, 5, 1457, 124889, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '05-JUN-18 14:57:00', 'EST-5', '05-JUN-18 14:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'NNE', 'MELBOURNE', 2, 'NNE', 'MELBOURNE', 28.1011, -80.5913, 28.1011, -80.5913, 'Persistent westerly flow was observed across central Florida. Deep moisture was in place across the area, with cool temperatures aloft and daytime heating conditions became favorable for the development of scattered showers and thunderstorms in the afternoon. Dry mid-level air was observed in the upper air sounding, allowing storms to produce strong to severe wind gusts. Scattered showers and storms were ongoing across east central Florida during the afternoon. As the storms approached Brevard County they intensified, and produced several strong wind reports along the intracoastal waters.', 'The ASOS at the Melbourne International Airport, KMLB, measured a peak wind gust of 34 knots from the west.');
INSERT INTO public.stormevents_east VALUES (755306, 201806, 19, 1800, 201806, 19, 1800, 125991, 'WEST VIRGINIA', 54, 2018, 'June', 'Thunderstorm Wind', 'RLX', '19-JUN-18 18:00:00', 'EST-5', '19-JUN-18 18:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Broadcast Media', 45, 'EG', NULL, NULL, 1, 'SW', 'MIDWAY', 1, 'SW', 'MIDWAY', 37.71, -81.26, 37.71, -81.26, 'As a front drifted south across the central Appalachians on the 19th, showers and storms developed in the afternoon heat. Repetitive heavy rain caused flash flooding in some areas. Isolated tree damage was also recorded.', 'A single large tree was blown down across Tams Highway, closing the road for a time.');
INSERT INTO public.stormevents_east VALUES (755310, 201806, 19, 1730, 201806, 19, 2000, 125991, 'WEST VIRGINIA', 54, 2018, 'June', 'Flash Flood', 'RLX', '19-JUN-18 17:30:00', 'EST-5', '19-JUN-18 20:00:00', 0, 0, 0, 0, '20.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'DARTMOOR', 1, 'NE', 'CLEMENTS', 39.0027, -79.9386, 39.0615, -80.0025, 'As a front drifted south across the central Appalachians on the 19th, showers and storms developed in the afternoon heat. Repetitive heavy rain caused flash flooding in some areas. Isolated tree damage was also recorded.', 'Multiple roads were closed due to high water. This included Route 250 north of Belington where Baker Run flooded. Water from Baker Run also caused minor damage at two residences. Bills Creek also flooded near Belington, closing a section of Bills Creek Road. Near Corley, Laurel Run flooded, closing sections of Mouse Run Road and Mt. Liberty Road.');
INSERT INTO public.stormevents_east VALUES (755313, 201806, 20, 1625, 201806, 20, 1625, 125994, 'OHIO', 39, 2018, 'June', 'Thunderstorm Wind', 'RLX', '20-JUN-18 16:25:00', 'EST-5', '20-JUN-18 16:25:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'RUTLAND', 1, 'S', 'RUTLAND', 39.04, -82.13, 39.04, -82.13, 'Thunderstorms along a front led to isolated tree damage on the 20th.', 'Several trees were blown down near Rutland.');
INSERT INTO public.stormevents_east VALUES (755316, 201806, 22, 1900, 201806, 22, 2100, 125995, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'RLX', '22-JUN-18 19:00:00', 'EST-5', '22-JUN-18 21:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'RODNEY', 1, 'NE', 'GALLIPOLIS', 38.843, -82.3209, 38.828, -82.1926, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'State Route 554 was closed in both directions between State Routes 7 and 160 due to flooding along Kyger Creek and White Oak Creek.||State Route 850 was closed in both direction between State Routes 554 and 588 due to flooding on Chickamauga Creek.');
INSERT INTO public.stormevents_east VALUES (755321, 201806, 21, 1945, 201806, 22, 1200, 125995, 'OHIO', 39, 2018, 'June', 'Flood', 'RLX', '21-JUN-18 19:45:00', 'EST-5', '22-JUN-18 12:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'DUNDAS', 1, 'SSE', 'BOLINS MILLS', 39.223, -82.4911, 39.2112, -82.275, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'Several roads were closed due to high water across eastern Vinton County. This included US Route 50, between McArthur and State Route 356. State Routes 56 and 328 were also closed.');
INSERT INTO public.stormevents_east VALUES (755327, 201806, 22, 500, 201806, 22, 1000, 125995, 'OHIO', 39, 2018, 'June', 'Flood', 'RLX', '22-JUN-18 05:00:00', 'EST-5', '22-JUN-18 10:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BLOOMFIELD', 2, 'SW', 'HESLOP', 39.5753, -81.2141, 39.5037, -81.3035, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'The Little Muskingum River near Bloomfield flooded, causing high water along Route 26. The river gage showed the river rose above its bankfull level of 16 feet during the predawn hours on the 22nd. It crested half a foot above bankfull around sunrise before returning to its banks by mid morning.');
INSERT INTO public.stormevents_east VALUES (755021, 201806, 18, 1900, 201806, 18, 1900, 125932, 'NEW JERSEY', 34, 2018, 'June', 'Thunderstorm Wind', 'PHI', '18-JUN-18 19:00:00', 'EST-5', '18-JUN-18 19:00:00', 1, 0, 1, 0, '0.00K', '0.00K', 'Newspaper', 50, 'EG', NULL, NULL, 1, 'N', 'CONVENT STATION', 1, 'N', 'CONVENT STATION', 40.79, -74.47, 40.79, -74.47, 'Severe thunderstorms caused wind damage across portions of New Jersey.', 'One person died and One other person critically injured when a tree fell onto a moving car traveling on Ford Road. Person died on June 22, 2018.');
INSERT INTO public.stormevents_east VALUES (758108, 201806, 5, 1718, 201806, 5, 1718, 126476, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '05-JUN-18 17:18:00', 'EST-5', '05-JUN-18 17:18:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'A few thunderstorms produced gusty winds due to an unstable atmosphere both days.', 'A wind gust of 35 knots was measured at Tolchester Beach.');
INSERT INTO public.stormevents_east VALUES (758109, 201806, 5, 1920, 201806, 5, 1920, 126476, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '05-JUN-18 19:20:00', 'EST-5', '05-JUN-18 19:20:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'LAKELAND ES AND MS (BLTLK)', 0, 'N', 'LAKELAND ES AND MS (BLTLK)', 39.25, -76.65, 39.25, -76.65, 'A few thunderstorms produced gusty winds due to an unstable atmosphere both days.', 'A wind gust of 34 knots was reported at Lakeland Elementary School.');
INSERT INTO public.stormevents_east VALUES (759325, 201806, 20, 1337, 201806, 20, 1339, 126668, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '20-JUN-18 13:37:00', 'EST-5', '20-JUN-18 13:39:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'N', 'HAMER', 1, 'N', 'HAMER', 34.5, -79.32, 34.5, -79.32, 'Strong storms formed over Dillon county.', 'Trees were blown down on Interstate 95 near mile marker 198.');
INSERT INTO public.stormevents_east VALUES (759349, 201806, 25, 1616, 201806, 25, 1618, 126679, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '25-JUN-18 16:16:00', 'EST-5', '25-JUN-18 16:18:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'SSE', '(FLO)FLORENCE CITY-C', 2, 'SSE', '(FLO)FLORENCE CITY-C', 34.15, -79.71, 34.15, -79.71, 'A pre-frontal trough produced strong thunderstorms.', 'A tree was blown down on Trilly Lane.');
INSERT INTO public.stormevents_east VALUES (774405, 201807, 6, 1113, 201807, 6, 1113, 129233, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 11:13:00', 'EST-5', '06-JUL-18 11:13:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'ADWOLF', 1, 'NNW', 'ADWOLF', 36.7893, -81.5845, 36.7893, -81.5845, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew down a tree along Riverside Road in Adwolfe. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774406, 201807, 6, 1119, 201807, 6, 1119, 129233, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 11:19:00', 'EST-5', '06-JUL-18 11:19:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'CHILHOWIE', 1, 'W', 'CHILHOWIE', 36.8, -81.68, 36.8, -81.68, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew a tree down in Chilhowie. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774407, 201807, 6, 1137, 201807, 6, 1137, 129233, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 11:37:00', 'EST-5', '06-JUL-18 11:37:00', 0, 0, 0, 0, '2.00K', NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'SSW', 'JACKSONS FERRY', 1, 'SSW', 'JACKSONS FERRY', 36.85, -80.86, 36.85, -80.86, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew trees down along Highway 52. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774408, 201807, 6, 1535, 201807, 6, 1535, 129233, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 15:35:00', 'EST-5', '06-JUL-18 15:35:00', 0, 0, 0, 0, '1.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'PICKAWAY', 1, 'SW', 'PICKAWAY', 36.756, -79.2194, 36.756, -79.2194, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew three trees down on Blair Branch Road. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (765662, 201806, 30, 1200, 201806, 30, 2300, 125826, 'FLORIDA', 12, 2018, 'June', 'Flood', 'TAE', '30-JUN-18 12:00:00', 'EST-5', '30-JUN-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'PERRY', 1, 'NW', 'PERRY', 30.1209, -83.5912, 30.12, -83.59, 'A well organized line of severe thunderstorms moved from north to south across portions of the Florida panhandle with damaging winds.  Numerous trees and power lines were blown down.', 'Minor flooding occurred along a creek on Julia Street in Perry.  Radar estimated around 3 inches of rain during the day.');
INSERT INTO public.stormevents_east VALUES (763102, 201806, 25, 1849, 201806, 25, 1855, 126890, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'CAE', '25-JUN-18 18:49:00', 'EST-5', '25-JUN-18 18:55:00', 0, 0, 0, 0, '0.05K', NULL, 'Trained Spotter', 43, 'EG', NULL, NULL, 1, 'W', 'GROVETOWN', 1, 'W', 'GROVETOWN', 33.45, -82.21, 33.45, -82.21, 'Strong daytime heating combined with a surface trough, an approaching cold front, and colliding outflow boundaries to produce widespread severe thunderstorms across the CSRA of GA and the Midlands of SC during the afternoon and evening.', 'SKYWARN Spotter reported estimated winds of 40-50 mph in Grovetown.');
INSERT INTO public.stormevents_east VALUES (765775, 201806, 22, 1454, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:54:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'LAGRANGE', 2, 'ENE', 'LAGRANGE', 38.4608, -77.8145, 38.4571, -77.8169, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Stones Mill Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (765776, 201806, 22, 1454, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:54:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'WHITE SHOP', 2, 'N', 'WHITE SHOP', 38.454, -78.0718, 38.4537, -78.0719, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Sumter Road flooded and closed near US 29.');
INSERT INTO public.stormevents_east VALUES (765778, 201806, 22, 1454, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:54:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'REVA', 1, 'WSW', 'REVA', 38.4954, -78.1463, 38.4952, -78.1452, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Flooding resulted in a road closure of Reva Road near Oakland Road.');
INSERT INTO public.stormevents_east VALUES (765779, 201806, 22, 1454, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:54:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'CATALPA', 2, 'N', 'CATALPA', 38.5461, -77.973, 38.5463, -77.9728, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Jamesons Mill Road flooded and closed near Muddy Run.');
INSERT INTO public.stormevents_east VALUES (765780, 201806, 22, 1454, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:54:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'RIXEYVILLE', 3, 'ENE', 'RIXEYVILLE', 38.5966, -77.9258, 38.5961, -77.9259, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Oak Shade Road flooded and closed at Little Indian Run.');
INSERT INTO public.stormevents_east VALUES (765578, 201806, 3, 2250, 201806, 3, 2250, 125384, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'TAE', '03-JUN-18 22:50:00', 'EST-5', '03-JUN-18 22:50:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'TIFTON', 1, 'W', 'TIFTON', 31.45, -83.51, 31.45, -83.51, 'Scattered to numerous showers and thunderstorms occurred across the area during the June 2-4 period.  As is typical with summer storms in this part of the country, some of the storms were severe with impacts to trees and power lines.  One storm was particularly severe in southern Lanier county with overturned farm equipment reported.', 'Several trees and power lines were blown down in Tifton.');
INSERT INTO public.stormevents_east VALUES (775239, 201808, 2, 2157, 201808, 2, 2357, 129382, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 21:57:00', 'EST-5', '02-AUG-18 23:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ALLEGANY', 1, 'NNE', 'ALLEGANY', 39.68, -78.9, 39.6804, -78.8937, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'MD-36 Mount Savage Road Northwest was closed due to flooding over Jennings Run near MD-638 Parkersburg Road Northwest.');
INSERT INTO public.stormevents_east VALUES (781752, 201808, 2, 1907, 201808, 3, 35, 129382, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 19:07:00', 'EST-5', '03-AUG-18 00:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'FAIRVIEW', 1, 'ESE', 'FAIRVIEW', 39.7154, -77.8251, 39.7131, -77.8289, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'The USGS stream gage on Conococheague Creek near Fairview exceeded the 10 foot flood stage during the indicated period. The peak level of 10.37 feet occurred at 10:15pm EST. Wishard Road and Kemp Mill Road both flooded near the creek.');
INSERT INTO public.stormevents_east VALUES (759335, 201806, 24, 1845, 201806, 24, 1847, 126676, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '24-JUN-18 18:45:00', 'EST-5', '24-JUN-18 18:47:00', 0, 0, 0, 0, '5.00K', '0.00K', 'County Official', 50, 'EG', NULL, NULL, 1, 'N', 'CAROLINA MILLS', 1, 'N', 'CAROLINA MILLS', 34.41, -79.37, 34.41, -79.37, 'An approaching cold front produced strong storms in NE South Carolina.', 'A porch was partially blown down.');
