INSERT INTO public.stormevents_east VALUES (759339, 201806, 24, 2116, 201806, 24, 2118, 126676, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '24-JUN-18 21:16:00', 'EST-5', '24-JUN-18 21:18:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'S', 'MILLWOOD', 4, 'S', 'MILLWOOD', 33.55, -79.76, 33.55, -79.76, 'An approaching cold front produced strong storms in NE South Carolina.', 'Tree down on Hwy 521, at Taft Road.');
