INSERT INTO public.stormevents_east VALUES (759343, 201806, 24, 2010, 201806, 24, 2012, 126673, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '24-JUN-18 20:10:00', 'EST-5', '24-JUN-18 20:12:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Public', 60, 'EG', NULL, NULL, 5, 'E', 'KELLY', 5, 'E', 'KELLY', 34.47, -78.24, 34.47, -78.24, 'An approaching cold front produced strong storms in SE North Carolina.', 'Numerous trees were blown down east of the town of Kelly. A trampoline damaged some power lines.');
INSERT INTO public.stormevents_east VALUES (759354, 201806, 25, 1605, 201806, 25, 1607, 126679, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '25-JUN-18 16:05:00', 'EST-5', '25-JUN-18 16:07:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SSE', '(FLO)FLORENCE CITY-C', 2, 'SSE', '(FLO)FLORENCE CITY-C', 34.15, -79.71, 34.15, -79.71, 'A pre-frontal trough produced strong thunderstorms.', 'There were two large trees that were blown down on Bridle Circle.');
INSERT INTO public.stormevents_east VALUES (765443, 201806, 13, 1707, 201806, 13, 1707, 127654, 'NEW YORK', 36, 2018, 'June', 'Hail', 'BUF', '13-JUN-18 17:07:00', 'EST-5', '13-JUN-18 17:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1.25, NULL, NULL, NULL, 1, 'W', 'FARMERSVILLE STN', 1, 'W', 'FARMERSVILLE STN', 42.43, -78.36, 42.43, -78.36, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', NULL);
INSERT INTO public.stormevents_east VALUES (765444, 201806, 13, 1715, 201806, 13, 1715, 127654, 'NEW YORK', 36, 2018, 'June', 'Hail', 'BUF', '13-JUN-18 17:15:00', 'EST-5', '13-JUN-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1.75, NULL, NULL, NULL, 1, 'N', 'RUSHFORD', 1, 'N', 'RUSHFORD', 42.39, -78.25, 42.39, -78.25, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', NULL);
INSERT INTO public.stormevents_east VALUES (765446, 201806, 13, 1651, 201806, 13, 1651, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 16:51:00', 'EST-5', '13-JUN-18 16:51:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'NW', 'CATTARAUGUS', 2, 'NW', 'CATTARAUGUS', 42.35, -78.9, 42.35, -78.9, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Tree down on route 353 between 42nd Street and Broadway.');
