INSERT INTO public.stormevents_east VALUES (756035, 201806, 9, 1706, 201806, 9, 1706, 126023, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '09-JUN-18 17:06:00', 'EST-5', '09-JUN-18 17:06:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 52, 'EG', NULL, NULL, 2, 'NW', 'BURNING KNOLLS', 2, 'NW', 'BURNING KNOLLS', 39.1944, -78.1528, 39.1944, -78.1528, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms to become severe.', 'A tree was down along the 100 block of Buffalo Trail and a tree was down along the 700 block of Smithfield Road.');
INSERT INTO public.stormevents_east VALUES (756036, 201806, 9, 1746, 201806, 9, 1746, 126023, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '09-JUN-18 17:46:00', 'EST-5', '09-JUN-18 17:46:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNW', 'BUCKTON', 2, 'NNW', 'BUCKTON', 39.0011, -78.2862, 39.0011, -78.2862, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms to become severe.', 'A tree was down at the 5000 Block of Longmeadow Road.');
INSERT INTO public.stormevents_east VALUES (756041, 201806, 9, 1407, 201806, 9, 1407, 126024, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '09-JUN-18 14:07:00', 'EST-5', '09-JUN-18 14:07:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'WILSON', 1, 'SW', 'WILSON', 38.5891, -76.5452, 38.5891, -76.5452, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms to become severe.', 'A tree was down at Stinnett Road and Emmanuel Church Road. A tree was down along Plum Road and Cox Road as well.');
INSERT INTO public.stormevents_east VALUES (756043, 201806, 9, 1800, 201806, 9, 1800, 126024, 'MARYLAND', 24, 2018, 'June', 'Thunderstorm Wind', 'LWX', '09-JUN-18 18:00:00', 'EST-5', '09-JUN-18 18:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NW', 'POMONKEY', 0, 'NW', 'POMONKEY', 38.6238, -77.0751, 38.6238, -77.0751, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms to become severe.', 'A tree was down on Hungerford Road.');
INSERT INTO public.stormevents_east VALUES (756071, 201806, 10, 1355, 201806, 10, 1355, 126025, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '10-JUN-18 13:55:00', 'EST-5', '10-JUN-18 13:55:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 4, 'S', 'MT CRAWFORD', 4, 'S', 'MT CRAWFORD', 38.32, -78.94, 38.32, -78.94, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms to become severe.', 'A large tree was down on along the 100 block of Summit Church Road.');
INSERT INTO public.stormevents_east VALUES (756072, 201806, 10, 1455, 201806, 10, 1455, 126025, 'VIRGINIA', 51, 2018, 'June', 'Thunderstorm Wind', 'LWX', '10-JUN-18 14:55:00', 'EST-5', '10-JUN-18 14:55:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 52, 'EG', NULL, NULL, 2, 'E', 'CENTERVILLE', 2, 'E', 'CENTERVILLE', 38.3299, -78.9634, 38.3299, -78.9634, 'An upper-level trough triggered a few showers and thunderstorms. There was enough instability for few storms to become severe.', 'A tree was down on a house along Crattan Hill Road.');
INSERT INTO public.stormevents_east VALUES (764835, 201806, 3, 1957, 201806, 3, 2100, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 19:57:00', 'EST-5', '03-JUN-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'SYKESVILLE', 0, 'S', 'SYKESVILLE', 39.364, -76.9691, 39.3639, -76.9689, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'Flooding on Main Street in Sykesville forced the closure of the road.');
INSERT INTO public.stormevents_east VALUES (764836, 201806, 4, 246, 201806, 4, 500, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '04-JUN-18 02:46:00', 'EST-5', '04-JUN-18 05:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'TIPTON AAF ARPT', 1, 'NNE', 'TIPTON AAF ARPT', 39.0915, -76.7685, 39.0917, -76.7669, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'A portion of Fort Meade Road was washed out by flooding of the Little Patuxent River.');
INSERT INTO public.stormevents_east VALUES (764837, 201806, 4, 546, 201806, 4, 800, 127372, 'MARYLAND', 24, 2018, 'June', 'Flood', 'LWX', '04-JUN-18 05:46:00', 'EST-5', '04-JUN-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'WILLIAMSPORT', 0, 'NW', 'WILLIAMSPORT', 39.6025, -77.8235, 39.602, -77.8218, 'Heavy rain of 1-4 inches on June 3rd on saturated soils caused several instances of flooding in the western suburbs of Baltimore. Separately, the combined effects of several days of rain created somewhat widespread river flooding which continued to affect portions of the area through the early morning hours of June 6th.', 'Maryland Route 68 was flooded and closed in Williamsport due to backwater flooding on Conococheague Creek just upstream of the Potomac River.');
INSERT INTO public.stormevents_east VALUES (764838, 201806, 3, 615, 201806, 3, 900, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 06:15:00', 'EST-5', '03-JUN-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'PAW PAW', 5, 'SSW', 'PAW PAW', 39.5145, -78.4612, 39.4673, -78.5066, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Eight roads were closed, mainly in the northern part of the county, due to flooding. All of the roads were near streams which were out of their banks. Two rock and mud slides were reported, one across Cacapon Road.');
INSERT INTO public.stormevents_east VALUES (764839, 201806, 3, 725, 201806, 3, 825, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 07:25:00', 'EST-5', '03-JUN-18 08:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'PAW PAW', 1, 'ESE', 'PAW PAW', 39.5276, -78.4533, 39.5252, -78.4519, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Two feet of water covered Route 9 just south of downtown Paw Paw.');
INSERT INTO public.stormevents_east VALUES (764840, 201806, 3, 935, 201806, 3, 1200, 127373, 'WEST VIRGINIA', 54, 2018, 'June', 'Flood', 'LWX', '03-JUN-18 09:35:00', 'EST-5', '03-JUN-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'WOODMONT', 1, 'WSW', 'RIDERSVILLE', 39.6249, -78.3345, 39.6101, -78.2011, 'Heavy rain of 1-3 inches on saturated soil caused flooding in Morgan County, West Virginia on June 3rd. Separately, the combined effects of several days of rain created river flooding on streams which continued in some locations through June 5th.', 'Widespread flooding throughout the county, with approximately 30 roads closed due to flooding of creeks and streams. Route 9 was closed between Paw Paw and Great Cacapon due to being flooded in multiple locations along that 20 mile stretch.');
INSERT INTO public.stormevents_east VALUES (753816, 201805, 10, 1340, 201805, 10, 1340, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 13:40:00', 'EST-5', '10-MAY-18 13:40:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'WASHINGTON', 1, 'SE', 'WASHINGTON', 38.7127, -78.1598, 38.7127, -78.1598, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'A tree branch was down on Crest Hill near Zachary Boulevard.');
INSERT INTO public.stormevents_east VALUES (753820, 201805, 10, 1320, 201805, 10, 1320, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 13:20:00', 'EST-5', '10-MAY-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SSE', 'SPRINGFIELD', 1, 'SSE', 'SPRINGFIELD', 38.7064, -78.4421, 38.7064, -78.4421, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'Trees were down along a two mile stretch in Luray. The trees were 15 inches in diameter.');
INSERT INTO public.stormevents_east VALUES (753825, 201805, 10, 1345, 201805, 10, 1345, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 13:45:00', 'EST-5', '10-MAY-18 13:45:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'ARRINGTON', 1, 'N', 'ARRINGTON', 37.6949, -78.9201, 37.6949, -78.9201, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'A tree was down along Arrington Road about a mile east of Route 29.');
INSERT INTO public.stormevents_east VALUES (753832, 201805, 10, 1638, 201805, 10, 1638, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 16:38:00', 'EST-5', '10-MAY-18 16:38:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'FRONT ROYAL WARN ARP', 1, 'ESE', 'FRONT ROYAL WARN ARP', 38.9155, -78.2309, 38.9155, -78.2309, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'A tree was down in the 700 Block of Catlett Mountain Road.');
INSERT INTO public.stormevents_east VALUES (780899, 201807, 22, 332, 201807, 22, 1348, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 03:32:00', 'EST-5', '22-JUL-18 13:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 6, 'E', 'EMMITSBURG', 6, 'E', 'EMMITSBURG', 39.7029, -77.2188, 39.6981, -77.2155, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'The USGS stream gage on the Monocacy River near Bridgeport exceeded the 13 foot flood stage during the indicated period. The peak level of 15.28 feet occurred at 9:30am EST. At these levels, Baptist Road near Bridgeport floods.');
INSERT INTO public.stormevents_east VALUES (780941, 201807, 22, 16, 201807, 22, 612, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 00:16:00', 'EST-5', '22-JUL-18 06:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KEYMAR', 1, 'NNW', 'KEYMAR', 39.6155, -77.2424, 39.6144, -77.2395, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Big Pipe Creek near Bruceville exceeded the 8 foot flood stage during the indicated period. The peak level of 10.43 feet was observed at 3:00am EST. Keysville-Bruceville Road was flooded.');
INSERT INTO public.stormevents_east VALUES (768366, 201806, 16, 1635, 201806, 16, 1635, 128129, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'GSP', '16-JUN-18 16:35:00', 'EST-5', '16-JUN-18 16:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 0.75, NULL, NULL, NULL, 0, 'N', 'UNION', 0, 'N', 'UNION', 34.72, -81.62, 34.72, -81.62, 'Isolated to widely scattered thunderstorms developed along the Blue Ridge escarpment during the afternoon and moved southeast into the foothills, where a couple of the storms produced brief damaging wind gusts.', 'County comms reported up to 3/4 inch diameter hail.');
INSERT INTO public.stormevents_east VALUES (768645, 201806, 16, 1314, 201806, 16, 1314, 128163, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '16-JUN-18 13:14:00', 'EST-5', '16-JUN-18 13:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'E', 'CALVERT', 0, 'WSW', 'ROSMAN', 35.169, -82.81, 35.149, -82.832, 'Isolated to widely scattered thunderstorms developed over the North Carolina mountains during the afternoon. One storm produced very brief severe weather in the form of damaging winds near Rosman in Transylvania County.', 'FD reported a tree blown down on Highway 64 near Old Rosman Highway and power lines down on Highway 64 in Rosman.');
INSERT INTO public.stormevents_east VALUES (768646, 201806, 16, 1935, 201806, 16, 1935, 128129, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '16-JUN-18 19:35:00', 'EST-5', '16-JUN-18 19:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SW', 'JOANNA', 3, 'WSW', 'JOANNA', 34.383, -81.84, 34.396, -81.851, 'Isolated to widely scattered thunderstorms developed along the Blue Ridge escarpment during the afternoon and moved southeast into the foothills, where a couple of the storms produced brief damaging wind gusts.', 'County comms reported a large tree limb blocking the Road at Bush River Road and Hopewell Church Road. Highway patrol reported a tree down at Bush River Rd and Milton Rd.');
INSERT INTO public.stormevents_east VALUES (768647, 201806, 17, 1351, 201806, 17, 1351, 128164, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'GSP', '17-JUN-18 13:51:00', 'EST-5', '17-JUN-18 13:51:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNE', 'BARNARD', 1, 'NNE', 'BARNARD', 35.85, -82.74, 35.85, -82.74, 'Isolated to widely scattered thunderstorms developed across the North Carolina mountains during the afternoon. One of the storms produced brief damaging wind gusts in Madison County.', 'County comms reported a few trees blown down in the Walnut area.');
INSERT INTO public.stormevents_east VALUES (768652, 201806, 17, 1557, 201806, 17, 1557, 128165, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '17-JUN-18 15:57:00', 'EST-5', '17-JUN-18 15:57:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'NW', 'BEREA', 2, 'W', 'BEREA', 34.895, -82.455, 34.88, -82.46, 'Isolated thunderstorms developed near the Blue Ridge during early and mid afternoon and moved slowly south into the foothills, where a couple of storms produced brief damaging wind gusts.', 'County comms and FD reported a few trees down in Berea: on Alice Farr Dr, Hunts Bridge Rd, Sulphur Springs Rd, and on Eunice Dr, where a tree fell on an apartment building.');
INSERT INTO public.stormevents_east VALUES (768653, 201806, 17, 1645, 201806, 17, 1645, 128165, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '17-JUN-18 16:45:00', 'EST-5', '17-JUN-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'ENE', 'CROW CREEK', 4, 'ENE', 'CROW CREEK', 34.948, -82.697, 34.948, -82.697, 'Isolated thunderstorms developed near the Blue Ridge during early and mid afternoon and moved slowly south into the foothills, where a couple of storms produced brief damaging wind gusts.', 'Law enforcement reported a few trees blown down in the Midway Road area.');
INSERT INTO public.stormevents_east VALUES (768654, 201806, 19, 1610, 201806, 19, 1610, 128166, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'GSP', '19-JUN-18 16:10:00', 'EST-5', '19-JUN-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'ESE', 'GRNVL SPRTNBRG ARPT', 2, 'NE', 'PELHAM', 34.887, -82.175, 34.874, -82.199, 'Isolated thunderstorms developed over the South Carolina Blue Ridge during the afternoon and moved south into the foothills. A couple of storms produced brief severe weather in the form of damaging wind gusts.', 'Highway patrol reported a tree blown down at Freeman Farm Rd and Jones Rd and another tree down at Brockman-McClimon Rd and Abner Creek Rd.');
INSERT INTO public.stormevents_east VALUES (748476, 201806, 2, 2130, 201806, 2, 2330, 124755, 'PENNSYLVANIA', 42, 2018, 'June', 'Flash Flood', 'PHI', '02-JUN-18 21:30:00', 'EST-5', '02-JUN-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'PHILADELPHIA', 1, 'WSW', 'WEST PHILADELPHIA', 39.9446, -75.1396, 39.9476, -75.1928, 'A quick 1 to 2 inches of rain fell across parts of southeastern Pennsylvania and far northern Delaware on the evening of June 2.', 'Sections of Interstate 95 and the Schuylkill Expressway were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (758060, 201805, 16, 213, 201805, 16, 349, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 02:13:00', 'EST-5', '16-MAY-18 03:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'WATERFORD', 1, 'NW', 'WATERFORD', 39.1904, -77.6163, 39.1906, -77.615, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'The stream gage on South Fork Catoctin Creek exceeded the 8 foot flood stage during the indicated times. The peak was just over flood stage at 8.03 feet. Lowlands near the creek were flooded, and upstream Allder School Road was flooded.');
INSERT INTO public.stormevents_east VALUES (758067, 201805, 15, 1925, 201805, 15, 2100, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 19:25:00', 'EST-5', '15-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'FT DETRICK', 1, 'N', 'FT DETRICK', 39.4381, -77.4012, 39.4378, -77.3991, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'High water rapidly flowing across Market Street and Schifferstadt Boulevard north of downtown Frederick.');
INSERT INTO public.stormevents_east VALUES (758069, 201805, 15, 1949, 201805, 15, 2100, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 19:49:00', 'EST-5', '15-MAY-18 21:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'DARGAN', 0, 'N', 'DARGAN', 39.386, -77.733, 39.3864, -77.7287, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'A home on Mount Lock Canal Road was flooded. The occupants were rescued.');
INSERT INTO public.stormevents_east VALUES (749199, 201806, 5, 1514, 201806, 5, 1514, 124889, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '05-JUN-18 15:14:00', 'EST-5', '05-JUN-18 15:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 3, 'WSW', 'CAPE CANAVERAL', 3, 'WSW', 'CAPE CANAVERAL', 28.364, -80.6484, 28.364, -80.6484, 'Persistent westerly flow was observed across central Florida. Deep moisture was in place across the area, with cool temperatures aloft and daytime heating conditions became favorable for the development of scattered showers and thunderstorms in the afternoon. Dry mid-level air was observed in the upper air sounding, allowing storms to produce strong to severe wind gusts. Scattered showers and storms were ongoing across east central Florida during the afternoon. As the storms approached Brevard County they intensified, and produced several strong wind reports along the intracoastal waters.', 'Weatherflow site XCCB on the Banana River south of State Road 520 on Merritt Island measured a peak wind gust of 37 knots from the west-southwest.');
INSERT INTO public.stormevents_east VALUES (749200, 201806, 5, 1519, 201806, 5, 1519, 124889, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '05-JUN-18 15:19:00', 'EST-5', '05-JUN-18 15:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 41, 'MG', NULL, NULL, 4, 'N', 'SATELLITE BEACH', 4, 'N', 'SATELLITE BEACH', 28.23, -80.598, 28.23, -80.598, 'Persistent westerly flow was observed across central Florida. Deep moisture was in place across the area, with cool temperatures aloft and daytime heating conditions became favorable for the development of scattered showers and thunderstorms in the afternoon. Dry mid-level air was observed in the upper air sounding, allowing storms to produce strong to severe wind gusts. Scattered showers and storms were ongoing across east central Florida during the afternoon. As the storms approached Brevard County they intensified, and produced several strong wind reports along the intracoastal waters.', 'The AWOS at Patrick Air Force Base, KCOF, measured a peak wind gust of 41 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (749125, 201806, 6, 1045, 201806, 6, 1045, 124873, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MLB', '06-JUN-18 10:45:00', 'EST-5', '06-JUN-18 10:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 47, 'MG', NULL, NULL, 7, 'N', 'CAPE CANAVERAL', 7, 'N', 'CAPE CANAVERAL', 28.477, -80.594, 28.477, -80.594, 'Decaying showers and thunderstorms moved southeast from north Florida into central Florida throughout the day. Mid-level southwest flow across the Florida peninsula allowed deep moisture to move in from the eastern Gulf of Mexico. As these weak showers moved into east central Florida, they strengthened due to encountering a more unstable atmosphere due to less cloud cover and daytime heating. Then, widespread showers showers and thunderstorms developed along a broken line and moved towards Brevard County. A few storms produced strong winds along the intracoastal waters, with one severe storm producing severe winds at the Cape, and another producing a waterspout near Playalinda Beach.', 'The AWOS at the Cape Canaveral Air Force Station Skid Strip, KXMR, measured a peak wind gust of 47 knots.');
INSERT INTO public.stormevents_east VALUES (755322, 201806, 21, 2200, 201806, 23, 1600, 125995, 'OHIO', 39, 2018, 'June', 'Flood', 'RLX', '21-JUN-18 22:00:00', 'EST-5', '23-JUN-18 16:00:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'NELSONVILLE', 1, 'SW', 'BEAUMONT', 39.4543, -82.2194, 39.4634, -82.1587, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'Multiple roads were closed across Athens County due to high water. This included State Routes 13 and 685 near Glouster, and State Route 690 near Amesville.||Monday Creek also flooded at Doanville, where the gage showed the creek spilled from its banks just before noon on the 22nd. The creek crested around 18.6 feet, or about 2.5 feet above its 16 foot bankfull level, late that night. It then returned to its banks by 4 PM on the 23rd.');
INSERT INTO public.stormevents_east VALUES (755328, 201806, 22, 2230, 201806, 23, 1230, 125995, 'OHIO', 39, 2018, 'June', 'Flood', 'RLX', '22-JUN-18 22:30:00', 'EST-5', '23-JUN-18 12:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'BLOOMFIELD', 2, 'SW', 'HESLOP', 39.5753, -81.2141, 39.5037, -81.3035, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'As additional thunderstorms moved through, the Little Muskingum River near Bloomfield flooded again late on the 22nd, again causing high water along Route 26. The river gage showed the river rose above its bankfull level of 16 feet late on the 22nd, cresting near 19 feet around sunrise on the 23rd. The river receded back into its banks by noon on the 23rd.');
INSERT INTO public.stormevents_east VALUES (755325, 201806, 23, 550, 201806, 25, 900, 125995, 'OHIO', 39, 2018, 'June', 'Flood', 'RLX', '23-JUN-18 05:50:00', 'EST-5', '25-JUN-18 09:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNW', 'BOLINS MILLS', 2, 'NW', 'BOLINS MILLS', 39.2676, -82.3052, 39.2515, -82.3106, 'As a front oscillated north and south across the middle Ohio River Valley, areas of repetitive, heavy rainfall led to flooding.', 'As water drained through the water system, Raccoon Creek experience minor flooding near Bolins Mills. The stream gage showed the creek rose above its 14 foot bankfull level early on the 23rd. It crested at 16 feet late on the 24th and returned to its banks mid morning on the 25th. This caused minor flooding in fields and other lowland areas along the creek.');
INSERT INTO public.stormevents_east VALUES (755376, 201806, 27, 1950, 201806, 27, 1951, 126003, 'OHIO', 39, 2018, 'June', 'Tornado', 'RLX', '27-JUN-18 19:50:00', 'EST-5', '27-JUN-18 19:51:00', 0, 0, 0, 0, '150.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NNW', 'EVANS ARPT', 1, 'N', 'EVANS ARPT', 38.9889, -82.5794, 38.9841, -82.5682, 'Following on and off rain through the day on the 27th, a cold front pushed through during the evening with heavy rainfall leading to flooding. One low topped cell produced a concentrated damage path in Jackson County. This was determined to be a tornado through the combination of eyewitness videos and a NWS storm survey. There was no lightning in the cell.', 'An EF0 tornado, with a maximum estimated wind speed of 85 mph, touched down across the northern portion of James A. Rhodes Airport near Jackson. It damaged a hanger, including bending some of the metal roof and an overhead door. One single engine aircraft was pushed 30 feet and flipped onto a car, and another was pushed about 60 feet and suffered a landing gear collapse. Several large trees were also snapped. Several videos of the tornado were recorded by bystanders.');
INSERT INTO public.stormevents_east VALUES (755377, 201806, 27, 1830, 201806, 27, 2030, 126003, 'OHIO', 39, 2018, 'June', 'Flash Flood', 'RLX', '27-JUN-18 18:30:00', 'EST-5', '27-JUN-18 20:30:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'RENO', 2, 'SSW', 'MURPHY', 39.3778, -81.3927, 39.3919, -81.2084, 'Following on and off rain through the day on the 27th, a cold front pushed through during the evening with heavy rainfall leading to flooding. One low topped cell produced a concentrated damage path in Jackson County. This was determined to be a tornado through the combination of eyewitness videos and a NWS storm survey. There was no lightning in the cell.', 'State Route 7 was flooded near Newport. Long Run Road was closed near Sandhill due to flooding on Long Run. Near Morningside, County House Lane was flooded, and so was Cornerstone Drive near Cornerville.');
INSERT INTO public.stormevents_east VALUES (758110, 201806, 5, 1930, 201806, 5, 1930, 126476, 'ATLANTIC NORTH', 88, 2018, 'June', 'Marine Thunderstorm Wind', 'LWX', '05-JUN-18 19:30:00', 'EST-5', '05-JUN-18 19:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 39, 'MG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'A few thunderstorms produced gusty winds due to an unstable atmosphere both days.', 'A wind gust of 39 knots was reported at Key Bridge.');
