INSERT INTO public.stormevents_east VALUES (760203, 201806, 3, 2212, 201806, 3, 2212, 126809, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'CAE', '03-JUN-18 22:12:00', 'EST-5', '03-JUN-18 22:12:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 2, 'S', 'BARR', 2, 'S', 'BARR', 33.901, -81.278, 33.901, -81.278, 'A surface front and upper level trough led to isolated severe thunderstorms developing on the evening of June 3rd across portions of the central Midlands of SC.', 'Half-inch to penny size hail reported near the intersection of Nazareth Road and Long''s Pond Road.');
INSERT INTO public.stormevents_east VALUES (760204, 201806, 3, 2213, 201806, 3, 2213, 126809, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'CAE', '03-JUN-18 22:13:00', 'EST-5', '03-JUN-18 22:13:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 3, 'SSE', 'BARR', 3, 'SSE', 'BARR', 33.89, -81.26, 33.89, -81.26, 'A surface front and upper level trough led to isolated severe thunderstorms developing on the evening of June 3rd across portions of the central Midlands of SC.', 'Quarter-size hail reported on Willow Forks Road.');
