INSERT INTO public.stormevents_east VALUES (760230, 201806, 3, 2235, 201806, 3, 2235, 126809, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '03-JUN-18 22:35:00', 'EST-5', '03-JUN-18 22:35:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 2, 'SW', 'AIKEN AFS', 2, 'SW', 'AIKEN AFS', 33.627, -81.6995, 33.627, -81.6995, 'A surface front and upper level trough led to isolated severe thunderstorms developing on the evening of June 3rd across portions of the central Midlands of SC.', 'SC Highway Patrol reported trees down on Reynolds Pond Road and on Gregory Road.');
INSERT INTO public.stormevents_east VALUES (760234, 201806, 3, 2235, 201806, 3, 2235, 126809, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '03-JUN-18 22:35:00', 'EST-5', '03-JUN-18 22:35:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 1, 'SSE', 'AIKEN AFS', 1, 'SSE', 'AIKEN AFS', 33.6416, -81.6764, 33.6416, -81.6764, 'A surface front and upper level trough led to isolated severe thunderstorms developing on the evening of June 3rd across portions of the central Midlands of SC.', 'SC Highway Patrol reported trees down at the intersection of Reynolds Pond Road and SC Highway 1.');
INSERT INTO public.stormevents_east VALUES (760293, 201806, 14, 1914, 201806, 14, 1914, 126841, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '14-JUN-18 19:14:00', 'EST-5', '14-JUN-18 19:14:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 61, 'MG', NULL, NULL, 1, 'ENE', '(SSC)SHAW AFB SUMTER', 1, 'ENE', '(SSC)SHAW AFB SUMTER', 33.9733, -80.4684, 33.9733, -80.4684, 'Strong daytime heating and an approaching front produced scattered severe thunderstorms in the late afternoon and evening.', 'ASOS unit at Shaw AFB near Sumter measured a peak wind gust of 61 knots, or 70 MPH at 2014 EDT (1914 EST).');
INSERT INTO public.stormevents_east VALUES (759249, 201805, 19, 1015, 201805, 19, 1706, 126452, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 10:15:00', 'EST-5', '19-MAY-18 17:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'YORKSHIRE', 1, 'NNW', 'YORKSHIRE', 38.7951, -77.4391, 38.7953, -77.438, 'Heavy rain of 1-3 inches fell during the evening and overnight of May 18th into May 19th along and east of the Blue Ridge Mountains. This prompted flooding in the region, mainly of streams. Some of the stream flooding lasted into the 20th, especially on larger rivers.', 'The stream gage on Bull Run near Manassas Park exceeded the 12 foot flood stage during the indicated times. The peak level of 12.44 feet was observed at 2:18pm EST on May 19th. Emergency management confirmed flooding of backyards along Lake Drive, and flooding of nearby trails.');
INSERT INTO public.stormevents_east VALUES (759121, 201806, 15, 1450, 201806, 15, 1452, 126626, 'SOUTH CAROLINA', 45, 2018, 'June', 'Hail', 'ILM', '15-JUN-18 14:50:00', 'EST-5', '15-JUN-18 14:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1, NULL, NULL, NULL, 0, 'N', 'GARDEN CITY', 0, 'N', 'GARDEN CITY', 33.58, -79, 33.58, -79, 'A cold front produced strong thunderstorms with small to medium size hail.', 'Quarter size hail was reported in Garden City.');
INSERT INTO public.stormevents_east VALUES (759313, 201806, 18, 1548, 201806, 18, 1550, 126657, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '18-JUN-18 15:48:00', 'EST-5', '18-JUN-18 15:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 51, 'MG', NULL, NULL, 1, 'NE', 'LUMBERTON MUNI ARPT', 1, 'NE', 'LUMBERTON MUNI ARPT', 34.61, -79.06, 34.61, -79.06, 'A trough combined with high instability triggered strong storms.', 'A 59 mph gusts was recorded.');
INSERT INTO public.stormevents_east VALUES (759315, 201806, 18, 1555, 201806, 18, 1557, 126657, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '18-JUN-18 15:55:00', 'EST-5', '18-JUN-18 15:57:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Amateur Radio', 55, 'EG', NULL, NULL, 2, 'SSE', 'LUMBERTON', 2, 'SSE', 'LUMBERTON', 34.59, -78.99, 34.59, -78.99, 'A trough combined with high instability triggered strong storms.', 'Trees were blown down on Hestertown Road north of Hwy 72.');
INSERT INTO public.stormevents_east VALUES (759316, 201806, 18, 1516, 201806, 18, 1518, 126657, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '18-JUN-18 15:16:00', 'EST-5', '18-JUN-18 15:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'WNW', 'ST PAULS', 1, 'WNW', 'ST PAULS', 34.81, -78.97, 34.81, -78.97, 'A trough combined with high instability triggered strong storms.', 'A large oak tree was blown down in St. Pauls.');
INSERT INTO public.stormevents_east VALUES (759319, 201806, 18, 1606, 201806, 18, 1608, 126657, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '18-JUN-18 16:06:00', 'EST-5', '18-JUN-18 16:08:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 4, 'S', 'LUMBERTON', 4, 'S', 'LUMBERTON', 34.56, -79, 34.56, -79, 'A trough combined with high instability triggered strong storms.', 'A roof was blown off a trailer on Alamac Road.');
INSERT INTO public.stormevents_east VALUES (759314, 201806, 18, 1608, 201806, 18, 1610, 126658, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '18-JUN-18 16:08:00', 'EST-5', '18-JUN-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NNE', 'LITTLE ROCK', 1, 'NNE', 'LITTLE ROCK', 34.49, -79.39, 34.49, -79.39, 'A trough combined with high instability triggered strong storms.', 'A tree fell onto Interstate 95.');
INSERT INTO public.stormevents_east VALUES (759352, 201806, 24, 2107, 201806, 24, 2109, 126673, 'NORTH CAROLINA', 37, 2018, 'June', 'Thunderstorm Wind', 'ILM', '24-JUN-18 21:07:00', 'EST-5', '24-JUN-18 21:09:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'S', 'ELIZABETHTOWN', 1, 'S', 'ELIZABETHTOWN', 34.62, -78.62, 34.62, -78.62, 'An approaching cold front produced strong storms in SE North Carolina.', 'A large tree was blown down onto a trailer, leaving a large hole in the roof.');
INSERT INTO public.stormevents_east VALUES (759350, 201806, 25, 1659, 201806, 25, 1701, 126679, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '25-JUN-18 16:59:00', 'EST-5', '25-JUN-18 17:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 4, 'SW', 'PELERSFIELD', 4, 'SW', 'PELERSFIELD', 33.64, -79.27, 33.64, -79.27, 'A pre-frontal trough produced strong thunderstorms.', 'A tree was blown down on Pleasant Drive.');
INSERT INTO public.stormevents_east VALUES (765781, 201806, 22, 1454, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:54:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'MONUMENT MILLS', 1, 'WSW', 'MONUMENT MILLS', 38.5948, -78.0261, 38.5951, -78.0255, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Hazel River Road flooded and closed west of Monumental Mills Road.');
INSERT INTO public.stormevents_east VALUES (765782, 201806, 22, 1459, 201806, 22, 1700, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 14:59:00', 'EST-5', '22-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'VAN BUREN FURNACE', 1, 'NE', 'VAN BUREN FURNACE', 38.9759, -78.5393, 38.9762, -78.5388, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Van Buren Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (765783, 201806, 22, 1526, 201806, 22, 1730, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 15:26:00', 'EST-5', '22-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'LAHORE', 1, 'WSW', 'LAHORE', 38.1942, -77.9861, 38.194, -77.9848, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Matthews Mill Road flooded and closed near Pamunkey Creek.');
INSERT INTO public.stormevents_east VALUES (765784, 201806, 22, 1526, 201806, 22, 1730, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 15:26:00', 'EST-5', '22-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'OLD SOMERSET', 0, 'SSE', 'OLD SOMERSET', 38.2188, -78.2197, 38.2182, -78.2195, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Blue Ridge Turnpike flooded and closed south of Constitution Highway.');
INSERT INTO public.stormevents_east VALUES (765786, 201806, 22, 1526, 201806, 22, 1730, 127379, 'VIRGINIA', 51, 2018, 'June', 'Flood', 'LWX', '22-JUN-18 15:26:00', 'EST-5', '22-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'TATUM', 1, 'NNE', 'TATUM', 38.2331, -77.8993, 38.2345, -77.8963, 'Heavy rain on saturated soils during the evening of June 21st caused flooding. The heavy rains intensified overnight, causing both flooding and flash flooding early on the 22nd. Widespread flooding persisted throughout Northern Virginia throughout the day n the 22nd. Additional heavy rain during the evening of the 22nd caused more flooding which continued into the 23rd, and the combination of all the rain events created stream flooding that continued through the 24th.', 'Sunnyside Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (791722, 201812, 3, 1130, 201812, 3, 1130, 132317, 'FLORIDA', 12, 2018, 'December', 'Heavy Rain', 'JAX', '03-DEC-18 11:30:00', 'EST-5', '03-DEC-18 11:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'SSE', 'SOUTHSIDE ESTATES', 2, 'SSE', 'SOUTHSIDE ESTATES', 30.28, -81.54, 30.28, -81.54, 'A very moist and unsettled weather pattern continued across the local area ahead of an approaching cold front. The front stalled across the local area, providing a focus for very heavy training rainfall.', 'Heavy rainfall caused a roof collapse at the 11000 Block of Beach Blvd. The main impact was to an animal housing facility with numerous animals evacuated. No injuries were reported.');
INSERT INTO public.stormevents_east VALUES (791725, 201812, 3, 2306, 201812, 4, 448, 132318, 'GEORGIA', 13, 2018, 'December', 'Flash Flood', 'JAX', '03-DEC-18 23:06:00', 'EST-5', '04-DEC-18 04:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Dam / Levee Break', NULL, 2, 'SE', 'BLACKSHEAR', 2, 'SE', 'BLACKSHEAR', 31.28, -82.23, 31.2818, -82.2221, 'A very moist and unsettled weather pattern continued across the local area ahead of an approaching cold front. The front stalled across the local area, providing a focus for very heavy training rainfall.', 'At 1106 pm on 12/3, Pierce county law enforcement reported a dam failure was imminent along the Lakeview Country Club Lake. Property threatened from flooding included homes along Edgewood Circle, Lakeview Drive, Fox Trail and Azalea Street along the Baxter/Bernie Branch drainage from the lake. The Department of Transportation closed Highway 121 south of Blackshear due to flood water over the bridge just south of Azalea Street from the Baxter/Bernie branch drainage. At 448 am on 12/4, law enforcement reported that the lake fell about 5 ft (40 acre lake). The Baxter/Bernie branch drainage rose about 8-12 inches in the past 5 hours. No reports of flooding into structures. Dam erosion was still ongoing at the time of the last report.');
INSERT INTO public.stormevents_east VALUES (791801, 201812, 20, 1050, 201812, 20, 1050, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:50:00', 'EST-5', '20-DEC-18 10:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 47, 'MG', NULL, NULL, 1, 'NW', 'JACKSONVILLE BEACH', 1, 'NW', 'JACKSONVILLE BEACH', 30.29, -81.39, 30.29, -81.39, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow site at the Jacksonville Beach Pier measured a wind gust of 54 mph in showers.');
INSERT INTO public.stormevents_east VALUES (791802, 201812, 20, 1054, 201812, 20, 1054, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:54:00', 'EST-5', '20-DEC-18 10:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 40, 'MG', NULL, NULL, 7, 'SW', 'MAYPORT NAS', 7, 'SW', 'MAYPORT NAS', 30.33, -81.51, 30.33, -81.51, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Craig ASOS measured a wind gust of 46 mph in showers.');
INSERT INTO public.stormevents_east VALUES (791803, 201812, 20, 1056, 201812, 20, 1056, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 10:56:00', 'EST-5', '20-DEC-18 10:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 46, 'MG', NULL, NULL, 0, 'N', 'MAYPORT NAS', 0, 'N', 'MAYPORT NAS', 30.4, -81.42, 30.4, -81.42, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The ASOS at the Naval Air Station Jacksonville measured a wind gust to 53 mph in showers.');
INSERT INTO public.stormevents_east VALUES (791804, 201812, 20, 1100, 201812, 20, 1100, 132333, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'JAX', '20-DEC-18 11:00:00', 'EST-5', '20-DEC-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 4, 'W', 'MAYPORT NAS', 4, 'W', 'MAYPORT NAS', 30.39, -81.48, 30.39, -81.48, 'A warm front lifted across the local area as a unusually strong area of low pressure tracked across the SE region. A pre-frontal line of storms moved across the area in the afternoon. A strong low level jet caused strong wind gusts, even from showers. Saturated grounds caused localized flooding from additional heavy rainfall.', 'The Weatherflow sensor at Buck Island measured a wind gust of 49 mph in showers.');
INSERT INTO public.stormevents_east VALUES (765055, 201806, 3, 1911, 201806, 3, 1913, 127593, 'PENNSYLVANIA', 42, 2018, 'June', 'Tornado', 'PBZ', '03-JUN-18 19:11:00', 'EST-5', '03-JUN-18 19:13:00', 0, 0, 0, 0, '5.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SE', 'FINLEYVILLE', 1, 'SE', 'FINLEYVILLE', 40.244, -80.0089, 40.2425, -80.0081, 'A cold front advanced across eastern Ohio and western Pennsylvania during the afternoon of the 3rd.  The combination of dry air aloft and sufficient deep layer shear allowed for the generation of a few severe thunderstorms, which mainly caused tree damage.  One brief tornado was seen near Finleyville in Washington County.', 'A brief EF-0 tornado was confirmed along Airport Road near Finleyville.  The tornado touched down just south of a series of hangars along the southern end of the Finleyville Airport runway.  It tracked southeast across a residential property and into a local valley before dissipating.  Several large pine trees suffered limb damage, with one mature pine snapped entirely at the base.  A two-story garage received damage to both entry doors as well as the removal of siding.  A wooden vehicle trailer was also lifted and displaced approximately 30 feet.');
INSERT INTO public.stormevents_east VALUES (765061, 201806, 5, 1558, 201806, 5, 1558, 127594, 'PENNSYLVANIA', 42, 2018, 'June', 'Hail', 'PBZ', '05-JUN-18 15:58:00', 'EST-5', '05-JUN-18 15:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'E', 'BELL PT', 1, 'E', 'BELL PT', 40.55, -79.56, 40.55, -79.56, 'A crossing cold front created scattered showers and isolated thunderstorms during the afternoon of the 5th, with a few reports of dime-to-quarter sized hail. An isolated instance of tree damage was also reported in Allegheny County.', NULL);
INSERT INTO public.stormevents_east VALUES (765062, 201806, 5, 1559, 201806, 5, 1559, 127594, 'PENNSYLVANIA', 42, 2018, 'June', 'Hail', 'PBZ', '05-JUN-18 15:59:00', 'EST-5', '05-JUN-18 15:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 0, 'N', 'TRUXHALL', 0, 'N', 'TRUXHALL', 40.55, -79.55, 40.55, -79.55, 'A crossing cold front created scattered showers and isolated thunderstorms during the afternoon of the 5th, with a few reports of dime-to-quarter sized hail. An isolated instance of tree damage was also reported in Allegheny County.', NULL);
INSERT INTO public.stormevents_east VALUES (775244, 201808, 2, 2300, 201808, 3, 30, 129382, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '02-AUG-18 23:00:00', 'EST-5', '03-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'MIDLAND', 0, 'E', 'MIDLAND', 39.58, -78.95, 39.58, -78.9479, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'Buskirk Hollow Road Southwest was washed out near Elklick Road.');
INSERT INTO public.stormevents_east VALUES (775245, 201808, 2, 2300, 201808, 3, 30, 129382, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '02-AUG-18 23:00:00', 'EST-5', '03-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'BOWLING GREEN', 0, 'WSW', 'BOWLING GREEN', 39.6134, -78.8031, 39.6184, -78.8035, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'Water and debris were reported over the road in multiple spots in the Bowling Green and Potomac Park areas, with a rock slide reported in one location.');
INSERT INTO public.stormevents_east VALUES (775246, 201808, 2, 2318, 201808, 3, 30, 129382, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '02-AUG-18 23:18:00', 'EST-5', '03-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'LUKE', 1, 'ENE', 'LUKE', 39.4889, -79.035, 39.4872, -79.0359, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'Ten inches of water was into a house on McKinley Street.');
INSERT INTO public.stormevents_east VALUES (775247, 201808, 2, 2255, 201808, 3, 55, 129382, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 22:55:00', 'EST-5', '03-AUG-18 00:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'CLARYSVILLE', 1, 'W', 'CLARYSVILLE', 39.633, -78.8955, 39.6317, -78.8937, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'Hardwood Drive Southwest was closed due to flooding over Preston Run.');
INSERT INTO public.stormevents_east VALUES (781080, 201808, 31, 1151, 201808, 31, 1351, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 11:51:00', 'EST-5', '31-AUG-18 13:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'GUILFORD', 1, 'SSE', 'GUILFORD', 39.1564, -76.8206, 39.1568, -76.819, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'High water blocked Mission Road east of Guilford Road.');
INSERT INTO public.stormevents_east VALUES (777930, 201808, 8, 1810, 201808, 8, 1820, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '08-AUG-18 18:10:00', 'EST-5', '08-AUG-18 18:20:00', 0, 0, 0, 0, '8.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'ESE', 'RED STONE', 2, 'ESE', 'ARCADE', 34.1185, -83.5933, 34.0746, -83.5442, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Jackson County Emergency Manager reported multiple trees blown down in the Jefferson and Arcade areas.');
INSERT INTO public.stormevents_east VALUES (777961, 201808, 9, 1715, 201808, 9, 1725, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '09-AUG-18 17:15:00', 'EST-5', '09-AUG-18 17:25:00', 0, 0, 0, 0, '25.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'THURMACK', 1, 'S', 'RED STONE', 34.1237, -83.7045, 34.0991, -83.5991, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Jackson County Emergency Manager reported a few trees blown from east of Braselton to southwest of Jefferson. One tree was down across Winder Highway and another was blown down onto a house and a parked car on Ward Road. No injuries were reported.');
INSERT INTO public.stormevents_east VALUES (759355, 201806, 25, 1735, 201806, 25, 1737, 126679, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'ILM', '25-JUN-18 17:35:00', 'EST-5', '25-JUN-18 17:37:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'W', 'OLANTA', 1, 'W', 'OLANTA', 33.93, -79.94, 33.93, -79.94, 'A pre-frontal trough produced strong thunderstorms.', 'A tree was blown down on Park Avenue.');
INSERT INTO public.stormevents_east VALUES (765447, 201806, 13, 1655, 201806, 13, 1655, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 16:55:00', 'EST-5', '13-JUN-18 16:55:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'WEST VLY', 1, 'W', 'WEST VLY', 42.4, -78.61, 42.4, -78.61, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Trees reported down.');
INSERT INTO public.stormevents_east VALUES (765448, 201806, 13, 1658, 201806, 13, 1658, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 16:58:00', 'EST-5', '13-JUN-18 16:58:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'DELEVAN', 1, 'NW', 'DELEVAN', 42.49, -78.48, 42.49, -78.48, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Numerous trees reported down.');
INSERT INTO public.stormevents_east VALUES (765449, 201806, 13, 1702, 201806, 13, 1702, 127654, 'NEW YORK', 36, 2018, 'June', 'Thunderstorm Wind', 'BUF', '13-JUN-18 17:02:00', 'EST-5', '13-JUN-18 17:02:00', 0, 0, 0, 0, '2.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'MACHIAS', 1, 'W', 'MACHIAS', 42.42, -78.5, 42.42, -78.5, 'A strong shortwave passed to the north of the area late afternoon into early evening. Winds aloft increased considerably ahead of this shortwave, with 850 mb winds of about 40 knots. A warm and moist air mass was in place ahead of this, and even with considerable cloud cover, the air mass destabilized with up to 1000-1500 J/Kg of CAPE. Storms developed ahead of an associated cold front, then weakened as they approached the Lake Erie shadow. There was just enough momentum for strong winds ahead of a storm to push into downtown Buffalo even with rapidly diminishing reflectivity. A line of storms passed north of Lake Ontario, with a broken line south of it. The most impressive line moved across the St. Lawrence Valley, but despite its appearance, winds only mixed to the surface locally aided by mid-level meso-vortices. There were a few severe storms embedded in storms south of Lake Ontario. Some briefly developed impressive reflectivity cores with severe hail and damaging winds.', 'Trees down.');
INSERT INTO public.stormevents_east VALUES (760150, 201806, 1, 1830, 201806, 1, 1835, 126275, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '01-JUN-18 18:30:00', 'EST-5', '01-JUN-18 18:35:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 1, 'ENE', 'SHELTON', 1, 'ENE', 'SHELTON', 34.5051, -81.3994, 34.5051, -81.3994, 'An upper level shortwave, combined with instability enhanced by daytime heating, produced a band of scattered severe thunderstorms which moved east across the region during the late afternoon and evening.', 'Tree down at 99 Rd and Auburn Dr. Time estimated.');
INSERT INTO public.stormevents_east VALUES (760155, 201806, 1, 1837, 201806, 1, 1842, 126275, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '01-JUN-18 18:37:00', 'EST-5', '01-JUN-18 18:42:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 0, 'N', 'WHITE OAK', 0, 'N', 'WHITE OAK', 34.47, -81.12, 34.47, -81.12, 'An upper level shortwave, combined with instability enhanced by daytime heating, produced a band of scattered severe thunderstorms which moved east across the region during the late afternoon and evening.', 'Report of tree down on US Hwy 321 at White Oak. Time estimated.');
