INSERT INTO public.stormevents_east VALUES (760160, 201806, 1, 1917, 201806, 1, 1922, 126275, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '01-JUN-18 19:17:00', 'EST-5', '01-JUN-18 19:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'W', 'GADSDEN', 2, 'W', 'GADSDEN', 33.8536, -80.8118, 33.8536, -80.8118, 'An upper level shortwave, combined with instability enhanced by daytime heating, produced a band of scattered severe thunderstorms which moved east across the region during the late afternoon and evening.', 'SCHP reported tree in roadway at Dry Branch Rd at Bluff Rd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (760163, 201806, 1, 1917, 201806, 1, 1922, 126275, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '01-JUN-18 19:17:00', 'EST-5', '01-JUN-18 19:22:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 3, 'NE', 'VAN WYCK', 3, 'NE', 'VAN WYCK', 34.8883, -80.7974, 34.8883, -80.7974, 'An upper level shortwave, combined with instability enhanced by daytime heating, produced a band of scattered severe thunderstorms which moved east across the region during the late afternoon and evening.', 'SCHP reported tree down in roadway on US Hwy 521 S about 2 miles south of intersection with SC 75. Time estimated.');
