INSERT INTO public.stormevents_east VALUES (760195, 201806, 10, 1140, 201806, 10, 1145, 126814, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '10-JUN-18 11:40:00', 'EST-5', '10-JUN-18 11:45:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 0, 'ESE', 'WAGENER', 0, 'ESE', 'WAGENER', 33.6491, -81.3655, 33.6491, -81.3655, 'Scattered severe thunderstorms developed over portions of the Midlands of SC during the early afternoon, and again that evening.', 'SCHP reported power lines down near the intersection of Aiken Rd and Louie St in Wagener.');
INSERT INTO public.stormevents_east VALUES (760196, 201806, 10, 1245, 201806, 10, 1250, 126814, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '10-JUN-18 12:45:00', 'EST-5', '10-JUN-18 12:50:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 4, 'ENE', 'WOODFORD', 4, 'ENE', 'WOODFORD', 33.7, -81.06, 33.7, -81.06, 'Scattered severe thunderstorms developed over portions of the Midlands of SC during the early afternoon, and again that evening.', 'Several trees were downed and a greenhouse was damaged. Dime size hail also fell.  Strickland Rd. Time estimated.');
INSERT INTO public.stormevents_east VALUES (763158, 201806, 26, 1816, 201806, 26, 1818, 126891, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '26-JUN-18 18:16:00', 'EST-5', '26-JUN-18 18:18:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 55, 'EG', NULL, NULL, 3, 'ENE', 'PROVIDENCE', 3, 'ENE', 'PROVIDENCE', 34.0318, -81.2212, 34.0318, -81.2212, 'Upper energy combined with daytime heating and a front to the north to produce a band of thunderstorms that moved SE through the Midlands of SC during the late afternoon and evening.', 'A tree was downed at 200 Beekeeper Ct.');
INSERT INTO public.stormevents_east VALUES (763159, 201806, 26, 1820, 201806, 26, 1822, 126891, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '26-JUN-18 18:20:00', 'EST-5', '26-JUN-18 18:22:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 3, 'WNW', 'ST ANDREWS', 3, 'WNW', 'ST ANDREWS', 34.0404, -81.1322, 34.0404, -81.1322, 'Upper energy combined with daytime heating and a front to the north to produce a band of thunderstorms that moved SE through the Midlands of SC during the late afternoon and evening.', 'A tree was downed, also taking down power lines, on Kingsbridge Rd.');
INSERT INTO public.stormevents_east VALUES (763161, 201806, 26, 2007, 201806, 26, 2010, 126891, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '26-JUN-18 20:07:00', 'EST-5', '26-JUN-18 20:10:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 2, 'SW', 'BALLTOWN', 2, 'SW', 'BALLTOWN', 33.5653, -81.7515, 33.5653, -81.7515, 'Upper energy combined with daytime heating and a front to the north to produce a band of thunderstorms that moved SE through the Midlands of SC during the late afternoon and evening.', 'Public report and photo, received via social media, of trees and power lines downed on Forest Dr in Aiken.');
INSERT INTO public.stormevents_east VALUES (763162, 201806, 26, 2017, 201806, 26, 2020, 126891, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '26-JUN-18 20:17:00', 'EST-5', '26-JUN-18 20:20:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 55, 'EG', NULL, NULL, 2, 'NNW', 'COUCHTON', 2, 'NNW', 'COUCHTON', 33.5974, -81.6336, 33.5974, -81.6336, 'Upper energy combined with daytime heating and a front to the north to produce a band of thunderstorms that moved SE through the Midlands of SC during the late afternoon and evening.', 'SCHP reported a tree blocking the roadway at New Bridge Rd and Joyce Branch Rd.');
INSERT INTO public.stormevents_east VALUES (763163, 201806, 26, 1750, 201806, 26, 1753, 126891, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '26-JUN-18 17:50:00', 'EST-5', '26-JUN-18 17:53:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'NW', 'ROCKTON', 1, 'NW', 'ROCKTON', 34.3564, -81.0862, 34.3564, -81.0862, 'Upper energy combined with daytime heating and a front to the north to produce a band of thunderstorms that moved SE through the Midlands of SC during the late afternoon and evening.', 'A tree was downed on Columbia Rd in Winnsboro.');
INSERT INTO public.stormevents_east VALUES (763164, 201806, 26, 1811, 201806, 26, 1814, 126891, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '26-JUN-18 18:11:00', 'EST-5', '26-JUN-18 18:14:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 55, 'EG', NULL, NULL, 1, 'SSE', 'MACEDONIA', 1, 'SSE', 'MACEDONIA', 34.092, -81.444, 34.092, -81.444, 'Upper energy combined with daytime heating and a front to the north to produce a band of thunderstorms that moved SE through the Midlands of SC during the late afternoon and evening.', 'A tree was downed on Living Inn Rd.');
INSERT INTO public.stormevents_east VALUES (763165, 201806, 27, 1722, 201806, 27, 1725, 126892, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '27-JUN-18 17:22:00', 'EST-5', '27-JUN-18 17:25:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 1, 'SW', 'JENKINSVILLE', 1, 'SW', 'JENKINSVILLE', 34.2653, -81.2867, 34.2653, -81.2867, 'An upper disturbance combined with daytime heating to produce a band of thunderstorms that moved SE through the Midlands of SC, some of which were severe.', 'Trees down in the town of Jenkinsville near Hwy 215 and McKennin Rd.');
INSERT INTO public.stormevents_east VALUES (763166, 201806, 27, 1730, 201806, 27, 1732, 126892, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '27-JUN-18 17:30:00', 'EST-5', '27-JUN-18 17:32:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 60, 'EG', NULL, NULL, 3, 'SW', 'DOUGLAS', 3, 'SW', 'DOUGLAS', 34.6488, -80.8378, 34.6488, -80.8378, 'An upper disturbance combined with daytime heating to produce a band of thunderstorms that moved SE through the Midlands of SC, some of which were severe.', 'Trees down near the intersection of Hwy 200 and Bethel Rd.');
INSERT INTO public.stormevents_east VALUES (763167, 201806, 27, 1730, 201806, 27, 1732, 126892, 'SOUTH CAROLINA', 45, 2018, 'June', 'Thunderstorm Wind', 'CAE', '27-JUN-18 17:30:00', 'EST-5', '27-JUN-18 17:32:00', 0, 0, 0, 0, NULL, NULL, 'Public', 60, 'EG', NULL, NULL, 2, 'WSW', 'DOUGLAS', 2, 'WSW', 'DOUGLAS', 34.662, -80.8283, 34.662, -80.8283, 'An upper disturbance combined with daytime heating to produce a band of thunderstorms that moved SE through the Midlands of SC, some of which were severe.', 'Trees down near Great Falls Hwy (Hwy 200) and Douglas Heights Lane.');
INSERT INTO public.stormevents_east VALUES (783440, 201805, 15, 1543, 201805, 15, 1543, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:43:00', 'EST-5', '15-MAY-18 15:43:00', 1, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 70, 'EG', NULL, NULL, 2, 'NW', 'GERMANTOWN', 2, 'NW', 'GERMANTOWN', 41.4142, -73.4544, 41.4142, -73.4544, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A dugout roof collapsed on the baseball field of Henry Abbott Technical High School resulting in one serious injury.');
INSERT INTO public.stormevents_east VALUES (733114, 201802, 25, 13, 201802, 25, 18, 122345, 'OHIO', 39, 2018, 'February', 'Tornado', 'ILN', '25-FEB-18 00:13:00', 'EST-5', '25-FEB-18 00:18:00', 0, 0, 0, 0, '65.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ENE', 'HAMERSVILLE', 0, 'E', 'NEW HOPE', 38.9237, -83.9639, 38.9702, -83.8976, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'The tornado is first believed to have touched down near Lucas Road, about one mile northeast of Hamersville. More significant damage was observed near the intersection of White Oak Valley Road and Smokey Row Road, where a well-built home suffered partial roof loss and additional loss of roofing material. At another property on White Oak Valley Road, a trailer was flipped over. Tree damage was extensive along Smokey Row Road, especially near its intersection with Vinegar Hill Road.||On New Hope-McKinley Road, about a half mile east of U.S. 68, a mobile home had its roof completely removed. Debris from this roof was observed thrown about 500 yards downstream (northeast) of its origin. Additional tree damage was observed along New Hope-White Oak Station Road.||In addition to the tornadic damage described above, the National Weather Service storm survey observed non-tornadic damage across a much wider area. This area of damage extended about 13 miles in length, stretching from far southeastern Clermont County through north central Brown County. This straight-line wind damage affected areas near Feesburg and Hamersville, and was observed on both sides of the surveyed tornadic circulation. This damage consisted of additional tree and outbuilding damage, including the destruction of a few outbuildings.');
INSERT INTO public.stormevents_east VALUES (733115, 201802, 25, 24, 201802, 25, 29, 122345, 'OHIO', 39, 2018, 'February', 'Thunderstorm Wind', 'ILN', '25-FEB-18 00:24:00', 'EST-5', '25-FEB-18 00:29:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'SSE', 'JONESBORO', 4, 'SSE', 'JONESBORO', 39.24, -83.81, 39.24, -83.81, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'A twenty-five to thirty foot flag pole was reported bent over. Also a garden windmill was knocked down, while a van window was broken from flying debris.');
INSERT INTO public.stormevents_east VALUES (783449, 201805, 15, 1546, 201805, 15, 1546, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:46:00', 'EST-5', '15-MAY-18 15:46:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 3, 'ENE', 'RIVERSIDE', 3, 'ENE', 'RIVERSIDE', 41.44, -73.2, 41.44, -73.2, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Several trees down on Cobbler Lane in Southbury.');
INSERT INTO public.stormevents_east VALUES (767164, 201806, 11, 1509, 201806, 11, 1509, 127901, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '11-JUN-18 15:09:00', 'EST-5', '11-JUN-18 15:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 40, 'MG', NULL, NULL, 8, 'WSW', 'FLAGLER BEACH', 8, 'WSW', 'FLAGLER BEACH', 29.47, -81.13, 29.47, -81.13, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (767593, 201806, 12, 1315, 201806, 12, 1415, 127980, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '12-JUN-18 13:15:00', 'EST-5', '12-JUN-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'W', 'CENTER PARK', 1, 'W', 'CENTER PARK', 30.28, -81.51, 30.28, -81.51, 'Sea breezes storm produced localized heavy rainfall.', 'Local media Action News JAX reported 2.75 inches of rainfall since 2:15 pm, with 1.3 inches falling in a 15 minute period.');
INSERT INTO public.stormevents_east VALUES (767594, 201806, 13, 1745, 201806, 13, 1745, 127981, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '13-JUN-18 17:45:00', 'EST-5', '13-JUN-18 17:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'SE', 'HOGAN', 1, 'SE', 'HOGAN', 30.27, -81.57, 30.27, -81.57, 'Sea breeze storms and resultant lightning caused a structure fire.', 'A lightning strike cause an apartment fire in the 8500 block of Touchton Road. The cost of damage was unknown, but it was estimated so the event could be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (769103, 201806, 15, 1540, 201806, 15, 1540, 128226, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '15-JUN-18 15:40:00', 'EST-5', '15-JUN-18 15:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 4, 'W', 'MAYPORT NAS', 4, 'W', 'MAYPORT NAS', 30.39, -81.48, 30.39, -81.48, 'SW steering flow focused a stronger west coast sea breeze across FL through the day with a merger with the east coast sea breeze near the I-95 corridor during the late afternoon and early evening. Resultant storms produced strong outflow winds which moved offshore of the local coast through early evening.', 'A WeatherFlow site measured a wind gust to 41 mph.');
INSERT INTO public.stormevents_east VALUES (769104, 201806, 15, 1600, 201806, 15, 1600, 128226, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '15-JUN-18 16:00:00', 'EST-5', '15-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 7, 'W', 'MAYPORT NAS', 7, 'W', 'MAYPORT NAS', 30.4, -81.53, 30.4, -81.53, 'SW steering flow focused a stronger west coast sea breeze across FL through the day with a merger with the east coast sea breeze near the I-95 corridor during the late afternoon and early evening. Resultant storms produced strong outflow winds which moved offshore of the local coast through early evening.', 'A WeatherFlow site measured a wind gust to 49 mph.');
INSERT INTO public.stormevents_east VALUES (758567, 201807, 21, 1820, 201807, 21, 1820, 126560, 'TENNESSEE', 47, 2018, 'July', 'Hail', 'MRX', '21-JUL-18 18:20:00', 'EST-5', '21-JUL-18 18:20:00', 0, 0, 0, 0, NULL, NULL, 'Park/Forest Service', 1, NULL, NULL, NULL, 2, 'SE', 'CADES COVE', 2, 'SE', 'CADES COVE', 35.6, -83.81, 35.6, -83.81, 'A few storms became severe during the afternoon in a moderately unstable environment, mainly across Southeast Tennessee in the vicinity of an old outflow boundary.', 'Quarter size hail was reported.');
INSERT INTO public.stormevents_east VALUES (783448, 201805, 15, 1544, 201805, 15, 1544, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:44:00', 'EST-5', '15-MAY-18 15:44:00', 0, 0, 0, 0, NULL, '0.00K', 'NWS Storm Survey', 87, 'EG', NULL, NULL, 1, 'E', 'BROOK FIELD', 1, 'E', 'BROOK FIELD', 41.48, -73.41, 41.48, -73.41, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A macro burst with wind speeds of 100-110 mph impacted an area approximately two and a half miles wide and at least five miles long.');
INSERT INTO public.stormevents_east VALUES (777998, 201808, 21, 1829, 201808, 21, 1829, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 18:29:00', 'EST-5', '21-AUG-18 18:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'BETHEL', 2, 'WNW', 'WARRENTON', 38.7347, -77.8225, 38.7303, -77.8174, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Bear Wallow Road was closed due to flooding of Cattail Branch.');
INSERT INTO public.stormevents_east VALUES (762847, 201806, 2, 1600, 201806, 2, 1600, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:00:00', 'EST-5', '02-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 2, 'ESE', 'HOMELAND', 2, 'ESE', 'HOMELAND', 30.84, -81.98, 30.84, -81.98, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Wind gusts were estimated at 60 mph just east of Folkston off of Dora Llloyd Road.');
INSERT INTO public.stormevents_east VALUES (762848, 201806, 2, 1400, 201806, 2, 1400, 127223, 'GEORGIA', 13, 2018, 'June', 'Heavy Rain', 'JAX', '02-JUN-18 14:00:00', 'EST-5', '02-JUN-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 3, 'E', 'KVILLE', 3, 'E', 'KVILLE', 31.55, -82.08, 31.55, -82.08, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Heavy rainfall and poor drainage caused portions of Granny Crosby Road to collapse. The time of the collapse was unknown but estimated based on timing of thunderstorms in area based on radar.');
INSERT INTO public.stormevents_east VALUES (762860, 201806, 2, 1540, 201806, 2, 1540, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 15:40:00', 'EST-5', '02-JUN-18 15:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'N', 'LIVE OAK SUWANE ARPT', 4, 'N', 'LIVE OAK SUWANE ARPT', 30.35, -83.03, 30.35, -83.03, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees and power lines were blown down. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762861, 201806, 2, 1555, 201806, 2, 1555, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 15:55:00', 'EST-5', '02-JUN-18 15:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'E', 'RIXSFORD', 4, 'E', 'RIXSFORD', 30.35, -82.89, 30.35, -82.89, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees and power lines were blown down near 136A and Adams Road. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762862, 201806, 2, 1605, 201806, 2, 1605, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:05:00', 'EST-5', '02-JUN-18 16:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'N', 'WILBURN', 4, 'N', 'WILBURN', 30.24, -82.56, 30.24, -82.56, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees were blown down along Swamp Gum Road.');
INSERT INTO public.stormevents_east VALUES (776778, 201807, 27, 1822, 201807, 27, 1822, 129688, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '27-JUL-18 18:22:00', 'EST-5', '27-JUL-18 18:22:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'NW', 'MACON NOCARVA FLD AR', 0, 'NW', 'MACON NOCARVA FLD AR', 36.5314, -78.0716, 36.5314, -78.0716, 'Dominated by outflow and sea-breeze boundaries, a few multi-cellular clusters developed across the NC Sandhills, eastern Piedmont and coastal plain counties.  Two thunderstorm clusters produced some scattered wind damage. A back-ward building cluster produced heavy rainfall of 3 to 4 inches that resulted in isolated flash flooding.', 'One tree was blown down on Nocarva Road.');
INSERT INTO public.stormevents_east VALUES (783437, 201805, 15, 1606, 201805, 15, 1606, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:06:00', 'EST-5', '15-MAY-18 16:06:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'W', 'WATERBURY', 1, 'W', 'WATERBURY', 41.5509, -73.058, 41.5509, -73.058, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down on I-84 West, just west of Waterbury.');
INSERT INTO public.stormevents_east VALUES (783450, 201805, 15, 1600, 201805, 15, 1600, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 6, 'NNE', 'SHELTON', 6, 'NNE', 'SHELTON', 41.4, -73.05, 41.4, -73.05, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down on top of shed.  Numerous other trees down throughout neighborhood.');
INSERT INTO public.stormevents_east VALUES (733133, 201802, 22, 1155, 201802, 23, 1355, 122445, 'OHIO', 39, 2018, 'February', 'Flood', 'ILN', '22-FEB-18 11:55:00', 'EST-5', '23-FEB-18 13:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'PIKETON', 3, 'NNW', 'PIKETON', 39.07, -83, 39.1067, -83.0461, 'Low pressure tracked east along a stalled front, which was located just southeast of the area, pulling moisture and heavy rain into the region.', 'High water was reported across several roads throughout Pike County.');
INSERT INTO public.stormevents_east VALUES (741456, 201802, 10, 700, 201802, 11, 700, 123621, 'NORTH CAROLINA', 37, 2018, 'February', 'Heavy Rain', 'RNK', '10-FEB-18 07:00:00', 'EST-5', '11-FEB-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 3, 'S', 'BUCK', 3, 'S', 'BUCK', 36.131, -81.228, 36.131, -81.228, 'A broad upper level trough with a slow-moving frontal boundary extending from Texas to upstate New York brought an extended period of mainly light to moderate rainfall that began on the afternoon of the 10th and persisted well into the evening of the 11th. Storm total rainfall amounts ranged from 1.5 to 3 inches across parts of northwest North Carolina.', 'The COOP observer at W. Kerr Scott Dam had a 24-hour total of 3.08 inches for the 24-hour period ending at 7 AM on the 11th. This was the 4th highest daily rainfall total during the month of February at this location since records began in 1965.');
INSERT INTO public.stormevents_east VALUES (766624, 201806, 9, 1730, 201806, 9, 1730, 127842, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '09-JUN-18 17:30:00', 'EST-5', '09-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NNW', '(AMG)BACON CO ARPT A', 2, 'NNW', '(AMG)BACON CO ARPT A', 31.55, -82.53, 31.55, -82.53, 'A surface low was offshore of the SE GA Atlantic coast with an upper level low along the FL Gulf Coast. The upper level low lifted northward through the day, and combined with low level forcing, instability and high moisture produced strong to severe storms.', 'At least 20 large trees and power poles were blown down across roads in the NW and Western portions of the county.');
INSERT INTO public.stormevents_east VALUES (766625, 201806, 9, 1800, 201806, 9, 1800, 127843, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '09-JUN-18 18:00:00', 'EST-5', '09-JUN-18 18:00:00', 1, 0, 0, 0, '1.00M', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 4, 'NE', 'LAKE GENEVA', 4, 'NE', 'LAKE GENEVA', 29.8, -81.97, 29.8, -81.97, 'A surface low was offshore of the SE GA Atlantic coast with an upper level low along the FL Gulf Coast. The upper level low lifted northward through the day, and combined with low level forcing, instability and high moisture produced strong to severe storms.', 'A 67 year old male was struck by lightning on  his front porch along Acadia Street in Keystone Heights, near Lake Geneva. The time of the event was based on lightning data. Shed was burned down which caused over $1M in damage to vintage cars and  motorcycles.');
INSERT INTO public.stormevents_east VALUES (762873, 201807, 4, 1300, 201807, 4, 1300, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '04-JUL-18 13:00:00', 'EST-5', '04-JUL-18 13:00:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'ESE', 'JONESTOWN', 1, 'ESE', 'JONESTOWN', 41.1224, -76.2771, 41.1224, -76.2771, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires onto SR 1025 near the communications tower.');
INSERT INTO public.stormevents_east VALUES (762896, 201807, 16, 2130, 201807, 16, 2130, 126743, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '16-JUL-18 21:30:00', 'EST-5', '16-JUL-18 21:30:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 1, 'ESE', 'JOBS CORNERS', 1, 'ESE', 'JOBS CORNERS', 41.9252, -76.9265, 41.9252, -76.9265, 'Storm developed ahead of an approaching cold front on July 16, 2018. Neither CAPE nor shear were very impressive, but a couple of storms managed to produce wind damage across northwestern and north-central Pennsylvania.  Heavy rainfall brought flash flooding to portions of McKean and Potter Counties during the evening hours.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees amd wires along Route 549 near Jobs Corners.');
INSERT INTO public.stormevents_east VALUES (769683, 201807, 16, 1940, 201807, 16, 2030, 126743, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '16-JUL-18 19:40:00', 'EST-5', '16-JUL-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'NORTH BINGHAM', 1, 'N', 'KINNEY', 41.9908, -77.7529, 41.9951, -77.93, 'Storm developed ahead of an approaching cold front on July 16, 2018. Neither CAPE nor shear were very impressive, but a couple of storms managed to produce wind damage across northwestern and north-central Pennsylvania.  Heavy rainfall brought flash flooding to portions of McKean and Potter Counties during the evening hours.', 'Widespread flash flooding was reported across the Potter County.   In Bingham Township road closures included  Collins Hill Road in the area of Bingham Road and Windfall Road, Bingham Center Road at Bacon Road, and Bingham Center Road in the area of 218.  Pusher Siding Road was under 3 feet of water and approximately 1000 feet of the roadway was washed out.||In Genessee Township, Ellisburg Road between Main and Ridge roads was briefly  closed and water was approximately a foot deep. Ellisburg Road in the area of Dogtown Road had three homes under water, no injuries.');
INSERT INTO public.stormevents_east VALUES (774689, 201807, 24, 1130, 201807, 24, 1230, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 11:30:00', 'EST-5', '24-JUL-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'STONELEIGH', 2, 'W', 'STONELEIGH', 39.3677, -76.6487, 39.3677, -76.6485, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Smith Avenue flooded at Jones Falls.');
INSERT INTO public.stormevents_east VALUES (774690, 201807, 24, 1304, 201807, 24, 1430, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 13:04:00', 'EST-5', '24-JUL-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'CARDEROCK SPGS', 0, 'NNW', 'CARDEROCK SPGS', 39.0064, -77.1753, 39.0061, -77.1748, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Bradley Boulevard flooded and closed near Mercy Hollow Lane.');
INSERT INTO public.stormevents_east VALUES (774692, 201807, 24, 1319, 201807, 24, 1430, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 13:19:00', 'EST-5', '24-JUL-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'LEONARDTOWN', 1, 'WNW', 'LEONARDTOWN', 38.3047, -76.6566, 38.3045, -76.656, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Road closure due to high water near Point Lookout Road and Maypole Road.');
INSERT INTO public.stormevents_east VALUES (774693, 201807, 24, 1319, 201807, 24, 1430, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 13:19:00', 'EST-5', '24-JUL-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'LOVEVILLE', 2, 'SE', 'LOVEVILLE', 38.3538, -76.6551, 38.3534, -76.6542, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Road closed due to high water on Friendship School Road near Bishop Road.');
INSERT INTO public.stormevents_east VALUES (783596, 201805, 15, 1525, 201805, 15, 1525, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:25:00', 'EST-5', '15-MAY-18 15:25:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 1, 'W', 'NEW WINDSOR', 1, 'W', 'NEW WINDSOR', 41.47, -74.03, 41.47, -74.03, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous trees down in New Windsor, specifically near Jackson Avenue and NY Route 94.');
INSERT INTO public.stormevents_east VALUES (781501, 201807, 24, 339, 201807, 26, 2102, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 03:39:00', 'EST-5', '26-JUL-18 21:02:00', 0, 0, 0, 0, '30.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'GLENCOE', 1, 'SW', 'GLENCOE', 39.5571, -76.6411, 39.5436, -76.6418, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Gunpowder Falls near Glencoe exceeded the 7 foot flood stage throughout the indicated period. There were three distinct peaks during the long period above flood stage, the highest of which was 14.41 feet, which occurred at 7:30am EST on July 25th. Throughout the flood, portions of Upper Glencoe Road and Lower Glencoe Road were flooded. For most of the time, Sparks Road was also flooded. Water was in buildings off of Sparks Road for over 24 hours from the morning of the 24th until the afternoon of the 25th, ultimately reaching several feet inside those structures. The water receded during the evening of the 25th but rose again overnight, affecting those buildings a second time.');
INSERT INTO public.stormevents_east VALUES (781502, 201807, 23, 2206, 201807, 24, 30, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '23-JUL-18 22:06:00', 'EST-5', '24-JUL-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'ALESIA', 2, 'NE', 'ALESIA', 39.6968, -76.8067, 39.6964, -76.8043, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Gunpowder Falls near Hoffmanville exceeded the 6 foot flood stage during the indicated period. The peak level of 6.94 feet occurred at 11:45pm EST. River Valley Ranch reported some flooding in their area, with campers having to be moved inside due to floodwaters.');
INSERT INTO public.stormevents_east VALUES (781503, 201807, 25, 1901, 201807, 25, 2250, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 19:01:00', 'EST-5', '25-JUL-18 22:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'ALESIA', 2, 'NE', 'ALESIA', 39.6969, -76.8073, 39.6967, -76.8047, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Gunpowder Falls near Hoffmanville exceeded the 6 foot flood stage during the indicated period. River Valley Ranch reported flooding in their area during this time, with campers moved to higher ground.');
INSERT INTO public.stormevents_east VALUES (758522, 201805, 18, 48, 201805, 18, 400, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '18-MAY-18 00:48:00', 'EST-5', '18-MAY-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'WNW', 'BLOOMER', 3, 'WNW', 'BLOOMER', 39.4021, -78.426, 39.4014, -78.4246, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'Gaston Road flooded and closed either due to flooding of North River or backwater flooding of the Cacapon River.');
INSERT INTO public.stormevents_east VALUES (758527, 201805, 19, 618, 201805, 19, 2103, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 06:18:00', 'EST-5', '19-MAY-18 21:03:00', 0, 0, 0, 0, '0.00K', '1.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'CHAMPWOOD', 1, 'ENE', 'CHAMPWOOD', 39.452, -78.825, 39.4555, -78.804, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'The stream gage on Patterson Creek near Headsville exceeded the 9 foot flood stage during the indicated times. The peak level of 9.50 feet was observed at 145 PM EST on May 19th. Agricultural and basement flooding occurs at these levels, with water covering parts of nearby roads.');
INSERT INTO public.stormevents_east VALUES (760001, 201805, 27, 1344, 201805, 27, 1530, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 13:44:00', 'EST-5', '27-MAY-18 15:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'PARKVILLE', 0, 'W', 'PARKVILLE', 39.3801, -76.557, 39.3799, -76.5556, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'A swift water rescue was performed near Parkville along Herring Run.');
INSERT INTO public.stormevents_east VALUES (760025, 201805, 27, 1630, 201805, 27, 1730, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 16:30:00', 'EST-5', '27-MAY-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ELLICOTT CITY', 0, 'W', 'ELLICOTT CITY', 39.269, -76.8099, 39.2694, -76.808, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Video footage shows a second wave of floodwaters, with water 1-2 feet deep over the 8600 block of Frederick Road in Ellicott City''s West End. The floodwaters entered and damaged homes and vehicles.');
INSERT INTO public.stormevents_east VALUES (760026, 201805, 27, 1716, 201805, 27, 1745, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 17:16:00', 'EST-5', '27-MAY-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'ELLICOTT CITY', 0, 'SSW', 'ELLICOTT CITY', 39.2691, -76.8014, 39.2688, -76.8009, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The culvert underneath Ellicott Mills Drive was undermined as the road was overtopped by floodwaters, washing out the road. Just downstream, the floodwaters caused the collapse of the historic stone cottage locals call The Old Courthouse, which was built in 1840.');
INSERT INTO public.stormevents_east VALUES (760869, 201805, 27, 1905, 201805, 27, 2130, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 19:05:00', 'EST-5', '27-MAY-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'ELKRIDGE', 1, 'E', 'ELKRIDGE', 39.2187, -76.707, 39.2189, -76.7052, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'US Route 1 was flooded and closed at the Patapsco River due to rapid increases in the water level.');
INSERT INTO public.stormevents_east VALUES (783597, 201805, 15, 1535, 201805, 15, 1535, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:35:00', 'EST-5', '15-MAY-18 15:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'S', 'LAKE CARMEL', 1, 'S', 'LAKE CARMEL', 41.4561, -73.6713, 41.4561, -73.6713, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Bank sign damaged at the Putnam County National Bank on Route 52.');
INSERT INTO public.stormevents_east VALUES (760873, 201805, 27, 1901, 201805, 27, 2030, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 19:01:00', 'EST-5', '27-MAY-18 20:30:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'SYKESVILLE', 0, 'S', 'SYKESVILLE', 39.364, -76.9696, 39.3637, -76.9688, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Lower Main Street in Sykesville flooded due to overwhelmed storm drains during torrential rain. Some water entered two structures in addition to water covering parking lots.');
INSERT INTO public.stormevents_east VALUES (760926, 201805, 27, 1527, 201805, 27, 1900, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:27:00', 'EST-5', '27-MAY-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'OELLA', 1, 'SSE', 'OELLA', 39.2564, -76.7738, 39.2528, -76.7685, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on the Patapsco River near Catonsville rapidly exceeded the flood stage at the start time indicated. It rose more than seven feet above flood stage within 33 minutes of the flooding beginning, peaking at 27.03 feet. River Road was flooded, and damaged, as a result of this rapid rise.');
INSERT INTO public.stormevents_east VALUES (760924, 201805, 27, 2000, 201805, 28, 138, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 20:00:00', 'EST-5', '28-MAY-18 01:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'OAKLAND MILLS', 1, 'SSW', 'OAKLAND MILLS', 39.2099, -76.8557, 39.2093, -76.8535, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on the Little Patuxent River near Columbia Town Center exceeded the flood elevation of 298.5 feet during the times indicated, and had already rapidly exceeded the flood stage due to flash flooding before this time. The peak elevation of 303.76 feet was observed at 8:20pm EST on May 27th. At the peak levels, US 29 was flooded by several feet of water on the southbound side. For the duration of the flood, South Entrance Road was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (758036, 201805, 14, 1816, 201805, 14, 1915, 126422, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '14-MAY-18 18:16:00', 'EST-5', '14-MAY-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'POTOMAC YARD', 1, 'ENE', 'POTOMAC YARD', 38.8356, -77.0585, 38.8353, -77.0577, 'A surging warm front spread moderate to heavy rain across the region. Dry conditions prior to the event served to limit the amount of flooding, but 1.5-2 inches of rain was enough to cause some street flooding in more urbanized areas.', 'Torrential rain caused rapidly rising standing water in the unit block of West Glebe Road. The water reportedly reached three feet or more in depth, forcing closure of the road.');
INSERT INTO public.stormevents_east VALUES (758063, 201805, 15, 1832, 201805, 15, 1925, 126423, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 18:32:00', 'EST-5', '15-MAY-18 19:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'FT DETRICK', 1, 'N', 'FT DETRICK', 39.4378, -77.4016, 39.4378, -77.3997, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Heavy rain flooded and closed Market Street near Schifferstadt Boulevard.');
INSERT INTO public.stormevents_east VALUES (760014, 201805, 27, 1519, 201805, 27, 1547, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:19:00', 'EST-5', '27-MAY-18 15:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'ELLICOTT CITY', 0, 'ESE', 'ELLICOTT CITY', 39.2669, -76.7971, 39.2671, -76.7944, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The first of three waves of flash flooding affected lower Main Street in Ellicott City on the Tiber River. Video footage shows the Tiber escaping its banks near Tiber Alley at 4:19pm, and at the alley in the 8100 block at 4:22pm. Several feet of rushing water began inundating Main Street and buildings in the area. At 4:35pm, the force of the floodwaters buckled the floor within one business, and water pushed through the building, emptying its contents onto Main Street.');
INSERT INTO public.stormevents_east VALUES (760960, 201805, 30, 2030, 201805, 30, 2300, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 20:30:00', 'EST-5', '30-MAY-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'NORTH GARDEN', 2, 'NNW', 'NORTH GARDEN', 37.9561, -78.6601, 37.9555, -78.6595, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'A driver had to be rescued when the vehicle became stranded in two to three feet of standing water on US Highway 29 near Plank Road.');
INSERT INTO public.stormevents_east VALUES (783598, 201805, 15, 1536, 201805, 15, 1536, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:36:00', 'EST-5', '15-MAY-18 15:36:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'ESE', 'LAKE CARMEL', 1, 'ESE', 'LAKE CARMEL', 41.4675, -73.6535, 41.4675, -73.6535, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down on Woodstock Road.');
INSERT INTO public.stormevents_east VALUES (783599, 201805, 15, 1525, 201805, 15, 1525, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:25:00', 'EST-5', '15-MAY-18 15:25:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 1, 'NNW', 'VAILS GATE JCT', 1, 'NNW', 'VAILS GATE JCT', 41.4869, -74.0787, 41.4869, -74.0787, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree on car with people trapped on Route 300 near New Windsor.');
INSERT INTO public.stormevents_east VALUES (783600, 201805, 15, 1541, 201805, 15, 1541, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:41:00', 'EST-5', '15-MAY-18 15:41:00', 0, 0, 0, 0, '75.00K', '0.00K', 'NWS Storm Survey', 70, 'EG', NULL, NULL, 1, 'E', 'NORTH SALEM', 1, 'E', 'NORTH SALEM', 41.33, -73.57, 41.33, -73.57, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Microburst resulting in a track of downed trees of 250 yards along Route 22.');
INSERT INTO public.stormevents_east VALUES (783601, 201805, 15, 1515, 201805, 15, 1515, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:15:00', 'EST-5', '15-MAY-18 15:15:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 0, 'N', 'NEWBURGH', 0, 'N', 'NEWBURGH', 41.5, -74.02, 41.5, -74.02, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down with cars and buildings damaged on 1st Street between Lutheran Street and City Terrace.');
INSERT INTO public.stormevents_east VALUES (783603, 201805, 15, 1515, 201805, 15, 1515, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:15:00', 'EST-5', '15-MAY-18 15:15:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 0, 'N', 'NEWBURGH', 0, 'N', 'NEWBURGH', 41.5, -74.02, 41.5, -74.02, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Roof off of the Hotel Imperial at Broadway and Robinson Avenue.');
INSERT INTO public.stormevents_east VALUES (783605, 201805, 15, 1510, 201805, 15, 1510, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:10:00', 'EST-5', '15-MAY-18 15:10:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 1, 'NNW', 'GARDNERTOWN', 1, 'NNW', 'GARDNERTOWN', 41.5438, -74.0785, 41.5438, -74.0785, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Downed tree closed I-87 southbound about 2 miles before the Newburgh exit.');
INSERT INTO public.stormevents_east VALUES (754998, 201805, 22, 1649, 201805, 22, 1649, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 16:49:00', 'EST-5', '22-MAY-18 16:49:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 38, 'MG', NULL, NULL, 0, 'N', 'QUANTICO (KNYG)', 0, 'N', 'QUANTICO (KNYG)', 38.51, -77.3, 38.51, -77.3, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A wind gust of 38 knots was reported at Quantico.');
INSERT INTO public.stormevents_east VALUES (754999, 201805, 22, 1713, 201805, 22, 1713, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 17:13:00', 'EST-5', '22-MAY-18 17:13:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 2, 'E', 'BABAR POINT (BAB)', 2, 'E', 'BABAR POINT (BAB)', 38.3089, -77.0019, 38.3089, -77.0019, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A wind gust of 38 knots was reported at Pylons DAH.');
INSERT INTO public.stormevents_east VALUES (755001, 201805, 22, 1716, 201805, 22, 1721, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 17:16:00', 'EST-5', '22-MAY-18 17:21:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 38.34, -76.99, 38.34, -76.99, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'Wind gusts up to 36 knots were reported at Potomac Light.');
INSERT INTO public.stormevents_east VALUES (755002, 201805, 22, 1716, 201805, 22, 1716, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 17:16:00', 'EST-5', '22-MAY-18 17:16:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'MONROE CREEK (MON)', 0, 'N', 'MONROE CREEK (MON)', 38.23, -76.95, 38.23, -76.95, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'Wind gusts up to 36 knots were reported Monroe Creek.');
INSERT INTO public.stormevents_east VALUES (760968, 201805, 30, 2130, 201805, 30, 2230, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 21:30:00', 'EST-5', '30-MAY-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'SYRIA', 1, 'NE', 'SYRIA', 38.49, -78.33, 38.4873, -78.3231, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Multiple water rescues ongoing in the Syria area.');
INSERT INTO public.stormevents_east VALUES (755013, 201805, 27, 1640, 201805, 27, 1640, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 16:40:00', 'EST-5', '27-MAY-18 16:40:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 1, 'SE', 'GREENBERRY POINT (GBY)', 1, 'SE', 'GREENBERRY POINT (GBY)', 38.9627, -76.447, 38.9627, -76.447, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'A wind gust of 37 knots was reported at the Annapolis Buoy.');
INSERT INTO public.stormevents_east VALUES (755014, 201805, 27, 1800, 201805, 27, 1800, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 18:00:00', 'EST-5', '27-MAY-18 18:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 49, 'MG', NULL, NULL, 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 38.03, -76.34, 38.03, -76.34, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'A wind gust of 49 knots was reported at Potomac Point Lookout.');
INSERT INTO public.stormevents_east VALUES (755018, 201805, 27, 1909, 201805, 27, 1909, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 19:09:00', 'EST-5', '27-MAY-18 19:09:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 0, 'N', 'RACCOON POINT (RAC)', 0, 'N', 'RACCOON POINT (RAC)', 38.14, -75.79, 38.14, -75.79, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'A wind gust of 36 knots was reported at Raccoon Point.');
INSERT INTO public.stormevents_east VALUES (755015, 201805, 27, 1920, 201805, 27, 1940, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 19:20:00', 'EST-5', '27-MAY-18 19:40:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 39, 'MG', NULL, NULL, 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 38.03, -76.34, 38.03, -76.34, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'Wind gusts up to 39 knots were reported at Potomac Point Lookout.');
INSERT INTO public.stormevents_east VALUES (755019, 201805, 27, 2004, 201805, 27, 2004, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 20:04:00', 'EST-5', '27-MAY-18 20:04:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 37.98, -75.86, 37.98, -75.86, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'A wind gust in excess of 30 knots was reported at the Crisfield Fire Department.');
INSERT INTO public.stormevents_east VALUES (757953, 201807, 2, 1700, 201807, 2, 1700, 126434, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '02-JUL-18 17:00:00', 'EST-5', '02-JUL-18 17:00:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NW', 'SILER', 3, 'NW', 'SILER', 39.376, -78.289, 39.376, -78.289, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Trees were down near the intersection of Chapel Hill road and Wesley Chapel Road.');
INSERT INTO public.stormevents_east VALUES (757965, 201807, 4, 1238, 201807, 4, 1238, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 12:38:00', 'EST-5', '04-JUL-18 12:38:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 0, 'SSE', 'VERBENA', 0, 'SSE', 'VERBENA', 38.4642, -78.6176, 38.4642, -78.6176, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Several pine trees were down on Route 340 near Naked Creek Road.');
INSERT INTO public.stormevents_east VALUES (757966, 201807, 4, 1344, 201807, 4, 1344, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 13:44:00', 'EST-5', '04-JUL-18 13:44:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SW', 'SPRING CREEK', 0, 'SW', 'SPRING CREEK', 38.3967, -79.0356, 38.3967, -79.0356, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Trees were down on power lines near the intersection of Spring Creek Road and Sangersville Road.');
INSERT INTO public.stormevents_east VALUES (761249, 201805, 30, 2341, 201805, 31, 200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 23:41:00', 'EST-5', '31-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'DYKE', 1, 'WSW', 'DYKE', 38.2414, -78.5547, 38.2409, -78.552, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Simmons Gap Road flooded and closed.');
INSERT INTO public.stormevents_east VALUES (776998, 201807, 31, 2055, 201807, 31, 2244, 129726, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '31-JUL-18 20:55:00', 'EST-5', '31-JUL-18 22:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', '(RWI)ROCKY MT WILSON', 1, 'NW', '(RWI)ROCKY MT WILSON', 35.86, -77.91, 35.859, -77.9103, 'Deep Gulf of Mexico moisture channeling between an amplifying trough over the mid-lower MS Valley and the western Atlantic ridge led to precipitable waters increasing to to over 2.0 over the area. Upper forcing in the form of divergence aloft, within the right entrance region of an upper level jet streak that extended down the Mid-Atlantic States, combined with a south-north ribbon of elongated vorticity shear axis centered east of the southern and central Appalachians, led to the development of scattered to numerous thunderstorms through the late afternoon and evening. The heaviest rain fell over the tri-county area of Nash-Wilson-Edgecombe counties, where training thunderstorms produced a swath of 4 to 6 inches.  This area of heavy rainfall flooded numerous roads in these counties, with at least two water rescues in Nash County.', 'Intersection of South Old Carriage Road and Baywood Road closed due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (773815, 201807, 25, 35, 201807, 25, 530, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '25-JUL-18 00:35:00', 'EST-5', '25-JUL-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'DANVILLE', 3, 'ENE', 'RIDGEVILLE', 40.96, -76.61, 40.9872, -76.5025, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Numerous roads were closed across the county as a result of floodwaters.');
INSERT INTO public.stormevents_east VALUES (774431, 201807, 11, 1838, 201807, 11, 1838, 129235, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '11-JUL-18 18:38:00', 'EST-5', '11-JUL-18 18:38:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WNW', 'PELHAM', 3, 'WNW', 'PELHAM', 36.5117, -79.5204, 36.5117, -79.5204, 'A cold front moved into a moisture-rich and hot Summertime air mass and triggered showers and storms. One of these storms increased to severe levels, producing damaging winds.', 'Thunderstorm winds blew trees down near Chandler Mill Road. Damage reports are estimated.');
INSERT INTO public.stormevents_east VALUES (774482, 201807, 27, 1709, 201807, 27, 1830, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 17:09:00', 'EST-5', '27-JUL-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'SINGER', 1, 'E', 'SINGER', 39.4773, -76.3029, 39.4773, -76.3027, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Two to three feet of water over the road following torrential rains near the intersection of Kensington Parkway and Harrogate Way.');
INSERT INTO public.stormevents_east VALUES (774511, 201807, 24, 728, 201807, 24, 930, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 07:28:00', 'EST-5', '24-JUL-18 09:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'PEACOCK', 1, 'SSE', 'PEACOCK', 38.9592, -77.2464, 38.9587, -77.2467, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Bellview Road flooded and closed near Rocky Run.');
INSERT INTO public.stormevents_east VALUES (780897, 201807, 24, 526, 201807, 24, 1116, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 05:26:00', 'EST-5', '24-JUL-18 11:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'MERRIFIELD', 1, 'W', 'TREMONT', 38.855, -77.247, 38.853, -77.2414, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'The USGS stream gage on Accotink Creek near Annandale exceeded the 9.5 foot flood stage during the indicated period. The peak of 10.99 feet occurred at 10:00am EST. Woodburn Road floods at these levels.');
INSERT INTO public.stormevents_east VALUES (774708, 201807, 27, 2241, 201807, 27, 2241, 129300, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '27-JUL-18 22:41:00', 'EST-5', '27-JUL-18 22:41:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'DILLWYN', 2, 'SSE', 'DILLWYN', 37.5, -78.44, 37.5, -78.44, 'A cold front moved into and across the region. Its passage helped initiate showers and storms across the area with a couple of reports of wind damage and one report of nickle sized hail.', 'Thunderstorm winds blew two trees down. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774711, 201807, 31, 1422, 201807, 31, 1422, 129302, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '31-JUL-18 14:22:00', 'EST-5', '31-JUL-18 14:22:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 55, 'EG', NULL, NULL, 2, 'ENE', 'YADKINVILLE', 2, 'ENE', 'YADKINVILLE', 36.1356, -80.6374, 36.1356, -80.6374, 'Showers and thunderstorms developed within humid air mass as an area of low pressure approached from the west. One of these storms became severe and producing damaging winds that downed several trees in Yadkin County.', 'Thunderstorm winds blew several trees down near the intersection of Old Route 421 and Fred Hinshaw Road. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (775493, 201807, 21, 1538, 201807, 21, 1730, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 15:38:00', 'EST-5', '21-JUL-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'FERRY FARMS', 1, 'NW', 'FERRY FARMS', 38.327, -77.4432, 38.3272, -77.443, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Deacon Road flooded and closed near Harrell Road.');
INSERT INTO public.stormevents_east VALUES (776089, 201807, 21, 1852, 201807, 21, 2100, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 18:52:00', 'EST-5', '21-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'DONOVANS CORNER', 3, 'SW', 'DONOVANS CORNER', 38.7441, -77.358, 38.7443, -77.3571, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'A motorist in a truck was stranded in high water on Lakewood Lane in the Clifton area.');
INSERT INTO public.stormevents_east VALUES (772166, 201807, 17, 1534, 201807, 17, 1534, 128753, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '17-JUL-18 15:34:00', 'EST-5', '17-JUL-18 15:34:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 9, 'NNE', 'GOOSES REEF BUOY (44062)', 9, 'NNE', 'GOOSES REEF BUOY (44062)', 38.677, -76.334, 38.677, -76.334, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to gusty winds from thunderstorms.', 'A wind gust of 36 knots was reported at Black Walnut Harbor.');
INSERT INTO public.stormevents_east VALUES (777292, 201807, 23, 445, 201807, 23, 600, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '23-JUL-18 04:45:00', 'EST-5', '23-JUL-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'COATS', 1, 'NNW', 'COATS', 35.42, -78.68, 35.4287, -78.6836, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Flash flooding was reported along NC Highway 55, near the intersection of Carson Gregory Road.');
INSERT INTO public.stormevents_east VALUES (731018, 201802, 15, 2323, 201802, 15, 2325, 122117, 'OHIO', 39, 2018, 'February', 'Thunderstorm Wind', 'ILN', '15-FEB-18 23:23:00', 'EST-5', '15-FEB-18 23:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 51, 'MG', NULL, NULL, 1, 'N', 'CHLLCTH ROSS CO ARPT', 1, 'N', 'CHLLCTH ROSS CO ARPT', 39.44, -83.02, 39.44, -83.02, 'A broad southwesterly flow brought a very moist air mass into the region. A few thunderstorms developed ahead of an approaching cold front.', NULL);
INSERT INTO public.stormevents_east VALUES (759810, 201805, 15, 1435, 201805, 15, 1435, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:35:00', 'EST-5', '15-MAY-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'SHOHOLA', 0, 'N', 'SHOHOLA', 41.47, -74.92, 41.47, -74.92, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (759811, 201805, 15, 1456, 201805, 15, 1456, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:56:00', 'EST-5', '15-MAY-18 14:56:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'NANTICOKE', 0, 'N', 'NANTICOKE', 41.2, -76, 41.2, -76, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Shingles were blown off of a house.');
INSERT INTO public.stormevents_east VALUES (759812, 201805, 15, 1505, 201805, 15, 1505, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 15:05:00', 'EST-5', '15-MAY-18 15:05:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'BUSHKILL', 0, 'N', 'BUSHKILL', 41.1, -75, 41.1, -75, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (759813, 201805, 15, 1344, 201805, 15, 1344, 126736, 'NEW YORK', 36, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 13:44:00', 'EST-5', '15-MAY-18 13:44:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'N', 'LIVINGSTON MANOR', 0, 'N', 'LIVINGSTON MANOR', 41.9, -74.83, 41.9, -74.83, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (759815, 201805, 15, 1350, 201805, 15, 1350, 126736, 'NEW YORK', 36, 2018, 'May', 'Funnel Cloud', 'BGM', '15-MAY-18 13:50:00', 'EST-5', '15-MAY-18 13:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 0, 'N', 'LIBERTY', 0, 'N', 'LIBERTY', 41.8, -74.75, 41.8, -74.75, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Spotter reported a funnel cloud and pea sized hail.');
INSERT INTO public.stormevents_east VALUES (760839, 201805, 13, 1554, 201805, 13, 1554, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 15:54:00', 'EST-5', '13-MAY-18 15:54:00', 1, 0, 0, 0, '0.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'WNW', 'TENMILE', 1, 'WNW', 'TENMILE', 40.03, -80.17, 40.03, -80.17, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'State official reported that a tree fell on a car in motion on Montgomery Road injuring 1 female inside. She was transported to the hospital with minor injuries.');
INSERT INTO public.stormevents_east VALUES (760840, 201805, 13, 1610, 201805, 13, 1610, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 16:10:00', 'EST-5', '13-MAY-18 16:10:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 56, 'EG', NULL, NULL, 1, 'WNW', 'BESCO', 1, 'WNW', 'BESCO', 39.99, -80.04, 39.99, -80.04, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'State official reported structural damage and partial roof removal of a home, as well as a single wide trailer shifted 4 to 6 feet off of its foundation.');
INSERT INTO public.stormevents_east VALUES (760841, 201805, 13, 1620, 201805, 13, 1620, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 16:20:00', 'EST-5', '13-MAY-18 16:20:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 0, 'N', 'ISABELLA', 0, 'N', 'ISABELLA', 39.95, -79.93, 39.95, -79.93, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'Amateur radio operator reported trees down and a roof blown off a mobile home.');
INSERT INTO public.stormevents_east VALUES (761155, 201805, 15, 1106, 201805, 15, 1106, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '15-MAY-18 11:06:00', 'EST-5', '15-MAY-18 11:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 1, NULL, NULL, NULL, 2, 'W', 'WEST MAYFIELD', 2, 'W', 'WEST MAYFIELD', 40.78, -80.36, 40.78, -80.36, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', NULL);
