INSERT INTO public.stormevents_east VALUES (761161, 201805, 15, 1207, 201805, 15, 1207, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '15-MAY-18 12:07:00', 'EST-5', '15-MAY-18 12:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1.25, NULL, NULL, NULL, 1, 'W', 'HILLSDALE', 1, 'W', 'HILLSDALE', 40.75, -78.89, 40.75, -78.89, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', NULL);
INSERT INTO public.stormevents_east VALUES (759781, 201805, 15, 1336, 201805, 15, 1336, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 13:36:00', 'EST-5', '15-MAY-18 13:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Unknown', 1, NULL, NULL, NULL, 0, 'N', 'GIBSON', 0, 'N', 'GIBSON', 41.8, -75.65, 41.8, -75.65, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (745728, 201805, 14, 1125, 201805, 14, 1125, 124276, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Waterspout', 'MLB', '14-MAY-18 11:25:00', 'EST-5', '14-MAY-18 11:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 4, 'E', 'MERRITT ISLAND', 4, 'E', 'MERRITT ISLAND', 28.3509, -80.6599, 28.3509, -80.6599, 'The interaction between a strengthening low pressure system in the eastern Gulf of Mexico and the Atlantic Bermuda High caused south winds to develop across the Florida peninsula. These winds brought a surge of moisture from the Caribbean across the state of Florida. Widespread showers and thunderstorms were ongoing throughout the day. One storm produced strong winds along the St. Lucie County coast. Another storm produced a waterspout near Cape Canaveral along the Brevard County coast.', 'Local media relayed reports of a waterspout just offshore the River Palms Mobile Home Park in the Banana River on Merritt Island.');
INSERT INTO public.stormevents_east VALUES (745882, 201805, 14, 935, 201805, 14, 936, 124326, 'FLORIDA', 12, 2018, 'May', 'Tornado', 'MLB', '14-MAY-18 09:35:00', 'EST-5', '14-MAY-18 09:36:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 4, 'E', 'MERRITT IS', 3, 'E', 'MERRITT IS', 28.3519, -80.6613, 28.3531, -80.6628, 'The interaction between a strengthening low pressure system in the eastern Gulf of Mexico and the Atlantic Bermuda High caused south winds to develop across the Florida peninsula. These winds brought a surge of moisture from the Caribbean across the state of Florida. A weak inverted trough/low pressure system developed in the eastern Gulf of Mexico, this in turn increased the low-level shear across much of east central Florida. Widespread showers and thunderstorms were ongoing throughout the day. One thunderstorm just offshore the Brevard County Coast became strong and developed a mesocyclone. This storm produced a waterspout that moved onshore and produced minor damage on Merritt Island. A second storm over inland Martin County developed a mesocyclone and produced a weak tornado, resulting in minor damage near Indiantown.', 'Following examination of photos and video received from local broadcast media, NWS Melbourne confirmed an EF-0 tornado affected the River Palms Mobile Home Park on Merritt Island as a waterspout moved onshore from the Banana River. The tornado produced minor damage to a few mobile homes, mainly detaching awnings from trailers. Winds were estimated between 60 and 70 mph. No injuries or fatalities occurred as a result of this tornado.');
INSERT INTO public.stormevents_east VALUES (733117, 201802, 25, 30, 201802, 25, 35, 122345, 'OHIO', 39, 2018, 'February', 'Thunderstorm Wind', 'ILN', '25-FEB-18 00:30:00', 'EST-5', '25-FEB-18 00:35:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 45, 'EG', NULL, NULL, 2, 'N', 'HOAGLAND', 2, 'N', 'HOAGLAND', 39.23, -83.68, 39.23, -83.68, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'A tree was knocked down near Anderson Rd and State Route 134.');
INSERT INTO public.stormevents_east VALUES (733121, 201802, 25, 44, 201802, 25, 49, 122345, 'OHIO', 39, 2018, 'February', 'Thunderstorm Wind', 'ILN', '25-FEB-18 00:44:00', 'EST-5', '25-FEB-18 00:49:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'E', 'BOSTON', 2, 'E', 'BOSTON', 39.22, -83.48, 39.22, -83.48, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'A barn roof was damaged on Overman Rd., between U.S. 50 and Petersburg Rd.');
INSERT INTO public.stormevents_east VALUES (735021, 201802, 25, 30, 201802, 25, 35, 122345, 'OHIO', 39, 2018, 'February', 'Thunderstorm Wind', 'ILN', '25-FEB-18 00:30:00', 'EST-5', '25-FEB-18 00:35:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'ESE', 'SUGAR TREE RIDGE', 2, 'ESE', 'SUGAR TREE RIDGE', 39.0636, -83.6405, 39.0636, -83.6405, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'Two homes received roof damage.');
INSERT INTO public.stormevents_east VALUES (769106, 201806, 15, 1610, 201806, 15, 1610, 128226, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '15-JUN-18 16:10:00', 'EST-5', '15-JUN-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'SW steering flow focused a stronger west coast sea breeze across FL through the day with a merger with the east coast sea breeze near the I-95 corridor during the late afternoon and early evening. Resultant storms produced strong outflow winds which moved offshore of the local coast through early evening.', 'A WeatherFlow site measured a gust to 40 mph.');
INSERT INTO public.stormevents_east VALUES (769108, 201806, 15, 1620, 201806, 15, 1620, 128226, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '15-JUN-18 16:20:00', 'EST-5', '15-JUN-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 4, 'W', 'MAYPORT NAS', 4, 'W', 'MAYPORT NAS', 30.39, -81.48, 30.39, -81.48, 'SW steering flow focused a stronger west coast sea breeze across FL through the day with a merger with the east coast sea breeze near the I-95 corridor during the late afternoon and early evening. Resultant storms produced strong outflow winds which moved offshore of the local coast through early evening.', 'A WeatherFlow site measured a wind gust to 48 mph.');
INSERT INTO public.stormevents_east VALUES (769110, 201806, 17, 1716, 201806, 17, 1716, 128228, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '17-JUN-18 17:16:00', 'EST-5', '17-JUN-18 17:16:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SW', 'OCALA ARPT', 2, 'SW', 'OCALA ARPT', 29.15, -82.25, 29.15, -82.25, 'A surface front was draped over SE GA with a dominant east coast sea breeze drifting inland over a moist and unstable airmass. A severe storm impacted Marion county.', 'Trees were blown down onto power lines near Westport High School.');
INSERT INTO public.stormevents_east VALUES (758507, 201807, 16, 1623, 201807, 16, 1623, 126555, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '16-JUL-18 16:23:00', 'EST-5', '16-JUL-18 16:23:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'AVONDALE SPGS', 1, 'S', 'AVONDALE SPGS', 36.29, -83.5, 36.29, -83.5, 'An isolated storm developed in a weakly unstable environment with aid from orographic lifting. The storm generated some wind damage.', 'Two trees were reported down near Rutledge.');
INSERT INTO public.stormevents_east VALUES (758518, 201807, 20, 2033, 201807, 20, 2033, 126557, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 20:33:00', 'EST-5', '20-JUL-18 20:33:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 55, 'EG', NULL, NULL, 1, 'WNW', 'JONESVILLE', 1, 'WNW', 'JONESVILLE', 36.69, -83.12, 36.69, -83.12, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (758520, 201807, 20, 2038, 201807, 20, 2038, 126557, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 20:38:00', 'EST-5', '20-JUL-18 20:38:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 55, 'EG', NULL, NULL, 1, 'N', 'PENNINGTON GAP', 1, 'N', 'PENNINGTON GAP', 36.76, -83.03, 36.76, -83.03, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (762864, 201806, 2, 1630, 201806, 2, 1630, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:30:00', 'EST-5', '02-JUN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'SANDERSON', 1, 'NE', 'SANDERSON', 30.26, -82.26, 30.26, -82.26, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A tree was blown down near U.S. Highway 90 near Sanderson. The time of damage was estimated by radar.');
INSERT INTO public.stormevents_east VALUES (774996, 201807, 6, 1516, 201807, 6, 1516, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:16:00', 'EST-5', '06-JUL-18 15:16:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 2, 'NE', 'RALEIGH', 2, 'NE', 'RALEIGH', 35.82, -78.64, 35.82, -78.64, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Trees were reported down on power lines.');
INSERT INTO public.stormevents_east VALUES (774997, 201807, 6, 1517, 201807, 6, 1517, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:17:00', 'EST-5', '06-JUL-18 15:17:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 3, 'ESE', 'RALEIGH', 3, 'ESE', 'RALEIGH', 35.79, -78.62, 35.79, -78.62, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Trees were reported down on power lines.');
INSERT INTO public.stormevents_east VALUES (775001, 201807, 6, 1525, 201807, 6, 1525, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:25:00', 'EST-5', '06-JUL-18 15:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'N', 'ROUGEMONT', 1, 'N', 'ROUGEMONT', 36.2315, -78.9321, 36.2315, -78.9321, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Numerous large tree limbs and four trees were reported down on Chambers Road near Highway 501.');
INSERT INTO public.stormevents_east VALUES (775005, 201807, 6, 1525, 201807, 6, 1525, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:25:00', 'EST-5', '06-JUL-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'CANDOR', 1, 'N', 'CANDOR', 35.3125, -79.7678, 35.3125, -79.7678, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'One tree was reported down on the road.');
INSERT INTO public.stormevents_east VALUES (733135, 201802, 22, 1205, 201802, 22, 1405, 122445, 'OHIO', 39, 2018, 'February', 'Flood', 'ILN', '22-FEB-18 12:05:00', 'EST-5', '22-FEB-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'MADISON', 3, 'NE', 'MADISON', 38.884, -82.756, 38.9034, -82.7592, 'Low pressure tracked east along a stalled front, which was located just southeast of the area, pulling moisture and heavy rain into the region.', 'State Route 139 was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (733139, 201802, 22, 1500, 201802, 22, 1700, 122445, 'OHIO', 39, 2018, 'February', 'Flood', 'ILN', '22-FEB-18 15:00:00', 'EST-5', '22-FEB-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'LAURELVILLE', 2, 'NE', 'LAURELVILLE', 39.47, -82.74, 39.4772, -82.7403, 'Low pressure tracked east along a stalled front, which was located just southeast of the area, pulling moisture and heavy rain into the region.', 'State Route 56 was closed due to high water across parts of the county.');
INSERT INTO public.stormevents_east VALUES (780635, 201808, 22, 643, 201808, 22, 943, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '22-AUG-18 06:43:00', 'EST-5', '22-AUG-18 09:43:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BLAIRTON', 7, 'ESE', 'VANCLEVESVILLE', 39.439, -77.927, 39.4075, -77.7818, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The 400 Block of Queen Street was closed under the underpass due to flooding from a creek. Parts of West John Street were closed due to flooding. Williamsport Pike was closed between Berkley Station Road and Mid-Atlantic Parkway due to flooding. Parts of Baltimore Street were closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (755076, 201807, 2, 1443, 201807, 2, 1443, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 14:43:00', 'EST-5', '02-JUL-18 14:43:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 1, 'NW', 'ROOTS', 1, 'NW', 'ROOTS', 40.6296, -78.3832, 40.6296, -78.3832, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto wires northwest of Bellwood.');
INSERT INTO public.stormevents_east VALUES (755077, 201807, 2, 1515, 201807, 2, 1515, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 15:15:00', 'EST-5', '02-JUL-18 15:15:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'NNW', 'MC CONNELLSTOWN', 0, 'NNW', 'MC CONNELLSTOWN', 40.4511, -78.0808, 40.4511, -78.0808, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in McConnellstown.');
INSERT INTO public.stormevents_east VALUES (755103, 201807, 2, 1611, 201807, 2, 1611, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 16:11:00', 'EST-5', '02-JUL-18 16:11:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WNW', 'PITTSFIELD ARPT', 1, 'WNW', 'PITTSFIELD ARPT', 41.8343, -79.3835, 41.8343, -79.3835, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto wires near Pittsfield.');
INSERT INTO public.stormevents_east VALUES (755104, 201807, 2, 1612, 201807, 2, 1612, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 16:12:00', 'EST-5', '02-JUL-18 16:12:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'NE', 'SAYBROOK', 1, 'NE', 'SAYBROOK', 41.7354, -79.0616, 41.7354, -79.0616, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down numerous trees onto wires near Tiona.');
INSERT INTO public.stormevents_east VALUES (755105, 201807, 2, 1612, 201807, 2, 1612, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 16:12:00', 'EST-5', '02-JUL-18 16:12:00', 0, 0, 0, 0, '8.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 2, 'NE', 'LISTONBURG', 2, 'NE', 'LISTONBURG', 39.7633, -79.2943, 39.7633, -79.2943, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto wires and a tree onto a house on Mount Davis Road.');
INSERT INTO public.stormevents_east VALUES (762874, 201807, 4, 1300, 201807, 4, 1300, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '04-JUL-18 13:00:00', 'EST-5', '04-JUL-18 13:00:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'DENNIS MILLS', 1, 'E', 'DENNIS MILLS', 41.069, -76.2895, 41.069, -76.2895, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires onto Briar Creek Road.');
INSERT INTO public.stormevents_east VALUES (762876, 201807, 4, 1445, 201807, 4, 1445, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '04-JUL-18 14:45:00', 'EST-5', '04-JUL-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'SE', 'UPPER STRASBURG', 1, 'SE', 'UPPER STRASBURG', 40.0593, -77.6875, 40.0593, -77.6875, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees near the intersection of Orrstown Road near Sandy Mountain Road.');
INSERT INTO public.stormevents_east VALUES (764811, 201807, 4, 1130, 201807, 4, 1415, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '04-JUL-18 11:30:00', 'EST-5', '04-JUL-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'CRYSTAL', 1, 'E', 'ELMER', 41.9556, -78.0628, 41.9223, -77.6038, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'Flash flooding reported across the county with Pushersiding Road closed near Ulysses, Peet Brook Road flooded near Andrews Settlement,  Route 6 flooded west of Galeton, and Oswayo Creek flowing over Route 44 near Hebron.   West Pike reported 6.10 inches and 4.73 inches in Galeton.');
INSERT INTO public.stormevents_east VALUES (776983, 201807, 4, 1312, 201807, 5, 0, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Heavy Rain', 'CTP', '04-JUL-18 13:12:00', 'EST-5', '05-JUL-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'NW', 'SHUNK', 1, 'NW', 'SHUNK', 41.56, -76.76, 41.56, -76.76, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'Delete.');
INSERT INTO public.stormevents_east VALUES (762890, 201807, 16, 1722, 201807, 16, 1722, 126743, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '16-JUL-18 17:22:00', 'EST-5', '16-JUL-18 17:22:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'FLINTON', 1, 'E', 'FLINTON', 40.7213, -78.4916, 40.7213, -78.4916, 'Storm developed ahead of an approaching cold front on July 16, 2018. Neither CAPE nor shear were very impressive, but a couple of storms managed to produce wind damage across northwestern and north-central Pennsylvania.  Heavy rainfall brought flash flooding to portions of McKean and Potter Counties during the evening hours.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and power lines, one of which fell onto a vehicle, on the 800 block of Gill Hollow Road.');
INSERT INTO public.stormevents_east VALUES (774694, 201807, 24, 1350, 201807, 24, 1445, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 13:50:00', 'EST-5', '24-JUL-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'LEONARDTOWN', 1, 'W', 'LEONARDTOWN', 38.3034, -76.6572, 38.3041, -76.6567, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Two women were reported to be stuck in a local business with rising waters surrounding the building. One self-evacuated, and the other was safely rescued.');
INSERT INTO public.stormevents_east VALUES (774695, 201807, 24, 1915, 201807, 24, 2015, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 19:15:00', 'EST-5', '24-JUL-18 20:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'CUMBERLAND', 1, 'E', 'CUMBERLAND', 39.65, -78.76, 39.6505, -78.7558, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Over half a dozen roads reported flooded and closed in Cumberland.');
INSERT INTO public.stormevents_east VALUES (774863, 201807, 25, 1724, 201807, 25, 1900, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:24:00', 'EST-5', '25-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'WARFIELDSBURG', 1, 'SSW', 'WARFIELDSBURG', 39.5167, -77.0392, 39.5166, -77.0388, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Nicodemus Road flooded and closed near Maryland Route 27 at Morgan Run.');
INSERT INTO public.stormevents_east VALUES (774865, 201807, 25, 1750, 201807, 25, 1900, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:50:00', 'EST-5', '25-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'POOLESVILLE', 3, 'S', 'POOLESVILLE', 39.1047, -77.4202, 39.1044, -77.4197, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Six to 12 inches of water was flowing across Willard Road near Poolesville.');
INSERT INTO public.stormevents_east VALUES (774870, 201807, 25, 1803, 201807, 25, 2000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 18:03:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'MELROSE', 2, 'NE', 'MELROSE', 39.69, -76.88, 39.6933, -76.8769, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Portions of Lineboro Road flooded and impassable between Hallie Avenue and Paul Circle.');
INSERT INTO public.stormevents_east VALUES (774871, 201807, 25, 1820, 201807, 25, 1920, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 18:20:00', 'EST-5', '25-JUL-18 19:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'KEMP MILL', 1, 'S', 'KEMP MILL', 39.016, -77.0211, 39.0159, -77.0201, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Three lanes closed on the Inner Loop of the Capital Beltway near Colesville Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (774877, 201807, 25, 1930, 201807, 25, 2130, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 19:30:00', 'EST-5', '25-JUL-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CROFTON', 1, 'NNE', 'RUTLAND', 38.9908, -76.6381, 38.9875, -76.6249, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Maryland Route 450 flooded and closed between Saint Stephens Church Road and Huntwood Drive.');
INSERT INTO public.stormevents_east VALUES (780939, 201807, 25, 11, 201807, 25, 38, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 00:11:00', 'EST-5', '25-JUL-18 00:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'OREGON', 1, 'S', 'OREGON', 39.4792, -76.6779, 39.4791, -76.6779, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Baisman Run near Broadmoor exceeded the 4 foot flood stage during the brief indicated period. An access road near the gage flooded, with water approaching a porch.');
INSERT INTO public.stormevents_east VALUES (780901, 201807, 25, 157, 201807, 25, 545, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 01:57:00', 'EST-5', '25-JUL-18 05:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'WHITE HALL', 0, 'SSW', 'WHITE HALL', 39.626, -76.6348, 39.6178, -76.6312, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Little Falls near Blue Mount exceeded the 8.5 foot flood stage during the indicated period. The peak level of 10.16 feet occurred at 4:00am EST. Water approached a driveway off Wiseburg Road and exceeded the banks in that area. Water also covered Big Falls Road in the area.');
INSERT INTO public.stormevents_east VALUES (780943, 201807, 26, 531, 201807, 26, 802, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '26-JUL-18 05:31:00', 'EST-5', '26-JUL-18 08:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KEYMAR', 1, 'NNW', 'KEYMAR', 39.6154, -77.2424, 39.6146, -77.2396, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS gage on Big Pipe Creek near Bruceville exceeded the 8 foot flood stage during the indicated period. The peak level of 8.58 feet occurred at 6:45am EST. Keysville-Bruceville Road was flooded.');
INSERT INTO public.stormevents_east VALUES (780947, 201807, 25, 2034, 201807, 25, 2054, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 20:34:00', 'EST-5', '25-JUL-18 20:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'BENTLEY SPGS', 1, 'NE', 'BENTLEY SPGS', 39.6734, -76.6756, 39.6768, -76.6678, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Beetree Run at Bentley Springs briefly, but rapidly, exceeded the 5.5 foot flood stage during the indicated period. The peak level of 6.11 feet was observed at 8:37pm EST.');
INSERT INTO public.stormevents_east VALUES (781192, 201807, 24, 1138, 201807, 24, 1256, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 11:38:00', 'EST-5', '24-JUL-18 12:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'COCKEYSVILLE', 1, 'NNE', 'COCKEYSVILLE', 39.4871, -76.6449, 39.487, -76.6448, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS gage on Beaverdam Run near Cockeysville exceeded the 9 foot flood stage during the indicated period. The peak level of 9.26 feet occurred at 12:05pm EST. Beaver Run Lane was flooded.');
INSERT INTO public.stormevents_east VALUES (781510, 201807, 25, 1822, 201807, 25, 1935, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 18:22:00', 'EST-5', '25-JUL-18 19:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'TAKOMA PARK', 1, 'NNW', 'TAKOMA PARK', 38.9863, -77.0049, 38.9861, -77.0047, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Sligo Creek near Takoma Park rapidly exceeded the 5.5 foot flood stage during the indicated period. The peak level of 6.75 feet occurred at 6:55pm EST, and Sligo Creek Parkway was flooded.');
INSERT INTO public.stormevents_east VALUES (761259, 201805, 30, 2330, 201805, 31, 100, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '30-MAY-18 23:30:00', 'EST-5', '31-MAY-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'ESE', 'WAYNESBORO ARPT', 4, 'ESE', 'WAYNESBORO ARPT', 38.0591, -78.8717, 38.0587, -78.8715, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Flooding was reported on 10th Street near South Kirby Avenue.');
INSERT INTO public.stormevents_east VALUES (760017, 201805, 27, 1639, 201805, 27, 1730, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 16:39:00', 'EST-5', '27-MAY-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'ELLICOTT CITY', 0, 'SE', 'ELLICOTT CITY', 39.2669, -76.7972, 39.2672, -76.7961, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Video footage shows a third and final flood wave pushing through the 8100 block of Main Street.  The water was nearly a foot deep on Main Street and then began entering buildings. Eventually overflow from the Tiber River caused the floodwaters of the Tiber and overland flow on Main Street to join with water surrounding and going through buildings.');
INSERT INTO public.stormevents_east VALUES (759999, 201805, 27, 1519, 201805, 27, 1753, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:19:00', 'EST-5', '27-MAY-18 17:53:00', 0, 0, 1, 0, '10.50M', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ELLICOTT CITY', 0, 'WNW', 'ELLICOTT CITY', 39.2717, -76.8165, 39.2716, -76.8066, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Catastrophic flash flooding occurred in Ellicott City as a result of torrential short-term rainfall of 6-10 inches.  One person died during a lull in the flooding when he attempted to help another person evacuate and was swept away. Floodwaters on the lower portion of Main Street in the 8000 block reached the bottom of second floors of businesses. In all, dozens of water rescues were performed, most from buildings.');
INSERT INTO public.stormevents_east VALUES (755004, 201805, 22, 1734, 201805, 22, 1734, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 17:34:00', 'EST-5', '22-MAY-18 17:34:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A wind gust of 34 knots was reported at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (755007, 201805, 22, 1854, 201805, 22, 1854, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 18:54:00', 'EST-5', '22-MAY-18 18:54:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'BISHOPS HEAD (BISM2)', 0, 'N', 'BISHOPS HEAD (BISM2)', 38.22, -76.04, 38.22, -76.04, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A wind gust in excess of 30 knots was reported at Bishops Head.');
INSERT INTO public.stormevents_east VALUES (755008, 201805, 22, 1919, 201805, 22, 1919, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 19:19:00', 'EST-5', '22-MAY-18 19:19:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'RACCOON POINT (RAC)', 0, 'N', 'RACCOON POINT (RAC)', 38.14, -75.79, 38.14, -75.79, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A wind gust of 37 knots was reported Raccoon Point.');
INSERT INTO public.stormevents_east VALUES (760967, 201805, 30, 2130, 201805, 30, 2230, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 21:30:00', 'EST-5', '30-MAY-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'IVY', 1, 'NE', 'IVY', 38.0566, -78.5952, 38.0562, -78.5931, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Ongoing water rescues with rapidly deteriorating conditions were reported on Ivy Road near Little Ivy Creek.');
INSERT INTO public.stormevents_east VALUES (760969, 201805, 30, 2200, 201805, 30, 2300, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 22:00:00', 'EST-5', '30-MAY-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'RED HILL', 1, 'WSW', 'RED HILL', 37.9638, -78.6395, 37.9641, -78.639, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Water from an overflowing pond rushed across Red Hill School Road near the Red Hill Elementary School.');
INSERT INTO public.stormevents_east VALUES (760971, 201805, 30, 2232, 201805, 30, 2330, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 22:32:00', 'EST-5', '30-MAY-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'RED HILL', 3, 'E', 'RED HILL', 37.97, -78.57, 37.9705, -78.5694, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Three feet of water over Old Lynchburg Road.');
INSERT INTO public.stormevents_east VALUES (756716, 201805, 15, 1601, 201805, 15, 1608, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Tornado', 'OKX', '15-MAY-18 16:01:00', 'EST-5', '15-MAY-18 16:08:00', 0, 0, 0, 0, '100.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ENE', 'BEACON FALLS', 0, 'WNW', 'MT CARMEL', 41.4385, -73.0466, 41.4225, -72.9061, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A tornado touched down near the intersection of Bethany Road and|Bonna Street in Beacon Falls, destroyed a barn in Bethany, and|continued on to just west of Sleeping Giant State Park in Hamden,|where the damage path broadened and became more straight-line in|nature. The tornado left a path of numerous uprooted and snapped |hardwood and pine trees. Based on this information, this tornado |is classified as an EF1 with maximum winds of 110 mph.');
INSERT INTO public.stormevents_east VALUES (776070, 201807, 22, 2349, 201807, 22, 2349, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 23:49:00', 'EST-5', '22-JUL-18 23:49:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'SW', 'STEVENS MILL', 2, 'SW', 'STEVENS MILL', 35.3293, -78.1491, 35.3293, -78.1491, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Numerous trees were reported down near Falling Creek Road and Stevens Church Road.');
INSERT INTO public.stormevents_east VALUES (776092, 201807, 22, 1812, 201807, 22, 1812, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Hail', 'RAH', '22-JUL-18 18:12:00', 'EST-5', '22-JUL-18 18:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'E', 'ASHEBORO SOUTH', 1, 'E', 'ASHEBORO SOUTH', 35.72, -79.81, 35.72, -79.81, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Quarter size hail was reported on Sterling Street.');
INSERT INTO public.stormevents_east VALUES (776095, 201807, 22, 1945, 201807, 22, 1945, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Lightning', 'RAH', '22-JUL-18 19:45:00', 'EST-5', '22-JUL-18 19:45:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'NNE', 'LEXINGTON', 2, 'NNE', 'LEXINGTON', 35.8393, -80.2567, 35.8393, -80.2567, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'A man of unknown age was struck by lightning at 38 Mill Street in Lexington, North Carolina. The man was transported to the hospital, but later released.');
INSERT INTO public.stormevents_east VALUES (752428, 201804, 3, 1400, 201804, 3, 1500, 125433, 'OHIO', 39, 2018, 'April', 'Flood', 'PBZ', '03-APR-18 14:00:00', 'EST-5', '03-APR-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'CLINE', 1, 'NNE', 'CLINE', 39.5994, -81.1689, 39.6126, -81.1642, 'Moderate rain along a warm front lifting across the upper Ohio Valley resulted in flooding across portions of eastern Ohio and southwestern Pennsylvania on the 3rd, which was further exacerbated by the passing cold front later that evening. The strong cold front then produced scattered wind damage due to both strong pressure rises behind the front and with accompanying thunderstorms.', 'State official reported flooding at the two mile marker bridge known as the Dye Dip.');
INSERT INTO public.stormevents_east VALUES (752924, 201804, 4, 1526, 201804, 4, 1526, 125543, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MHX', '04-APR-18 15:26:00', 'EST-5', '04-APR-18 15:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 37, 'MG', NULL, NULL, 5, 'W', 'HARVEY POINT', 5, 'W', 'HARVEY POINT', 36.0816, -76.4021, 36.0816, -76.4021, 'An area of low pressure moved through the Great Lakes, with a trailing cold front that moved through Eastern North Carolina.  Ahead of the front a line of showers and thunderstorms developed and moved over the coastal waters producing strong wind gusts.', 'A marine wind gust of 37 knots associated with a thunderstorm was reported by public weather station.');
INSERT INTO public.stormevents_east VALUES (774338, 201807, 24, 2252, 201807, 25, 345, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flood', 'CTP', '24-JUL-18 22:52:00', 'EST-5', '25-JUL-18 03:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'LYKENS', 5, 'SSE', 'WILLIAMSTOWN', 40.56, -76.7, 40.513, -76.566, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Flooding resulted in more than forty roads being closed county wide. The flooding also led to water rescues at Trailer Park near Sunset and Sunrise Drive. In Derry Township several residents were trapped as a result of floodwaters.');
INSERT INTO public.stormevents_east VALUES (773243, 201807, 23, 500, 201807, 23, 630, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '23-JUL-18 05:00:00', 'EST-5', '23-JUL-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'GRANTVILLE', 1, 'S', 'PILLOW', 40.3956, -76.659, 40.6115, -76.7758, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'Over 4 inches of rain produced flash flooding.  PA Route 443 was closed due to flooding.  Bunker Hill Road in Halifix Township was damaged.');
INSERT INTO public.stormevents_east VALUES (774699, 201807, 22, 1910, 201807, 22, 1910, 129292, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '22-JUL-18 19:10:00', 'EST-5', '22-JUL-18 19:10:00', 0, 0, 0, 0, '2.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'GERMANTON', 1, 'S', 'GERMANTON', 36.2626, -80.2309, 36.2626, -80.2309, 'Showers and storms developed during the afternoon and evening of the 22nd in association with the approach of an area of low pressure. A few of these storms increased to severe levels and produced damaging winds.', 'Thunderstorm winds blew five trees down around the community of Germanton. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (776991, 201807, 23, 500, 201807, 27, 500, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flood', 'CTP', '23-JUL-18 05:00:00', 'EST-5', '27-JUL-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'HERSHEY ARPT', 1, 'SSW', 'HOERNERSTOWN', 40.3035, -76.6832, 40.2714, -76.7356, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'River flooding along Swatara Creek.  Main Street in Hummelstown was closed due to flooding, as was the Duke Street Bridge. Many roads near the river were closed.');
INSERT INTO public.stormevents_east VALUES (773813, 201807, 23, 2234, 201807, 24, 230, 127570, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '23-JUL-18 22:34:00', 'EST-5', '24-JUL-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'UNITYVILLE', 3, 'WNW', 'LAIRDSVILLE', 41.23, -76.52, 41.2395, -76.6748, 'I persistent upper level flow of moist southerly air brought waves of flooding and flash flooding to the region.  Significant flooding was reported across eastern portions of the area.  Two deaths were also reported, one person was washed away attempting to cross a stream, while a motorist was swept away in flood waters.', 'On Beauty Run, floodwaters were flowing through backyards.');
INSERT INTO public.stormevents_east VALUES (784170, 201810, 23, 800, 201810, 23, 805, 131088, 'LAKE ERIE', 95, 2018, 'October', 'Waterspout', 'CLE', '23-OCT-18 08:00:00', 'EST-5', '23-OCT-18 08:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 14, 'WSW', 'WILLOWICK', 14, 'WSW', 'WILLOWICK', 41.5207, -81.7415, 41.5207, -81.7415, 'Several waterspouts were reported on Lake Erie.', 'There was a report from social media of several waterspouts and funnels offshore near Cleveland.');
INSERT INTO public.stormevents_east VALUES (784171, 201810, 23, 305, 201810, 23, 310, 131088, 'LAKE ERIE', 95, 2018, 'October', 'Waterspout', 'CLE', '23-OCT-18 03:05:00', 'EST-5', '23-OCT-18 03:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 11, 'ENE', 'AVON POINT', 11, 'ENE', 'AVON POINT', 41.5218, -81.8446, 41.5218, -81.8446, 'Several waterspouts were reported on Lake Erie.', 'There was a report from the public of a brief waterspout offshore near Rocky River.');
INSERT INTO public.stormevents_east VALUES (776038, 201807, 22, 1821, 201807, 22, 1821, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:21:00', 'EST-5', '22-JUL-18 18:21:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'N', 'DOGWOOD ACRES', 2, 'N', 'DOGWOOD ACRES', 35.7784, -79.8656, 35.7784, -79.8656, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Eden Forest Drive near Plainfield Road.');
INSERT INTO public.stormevents_east VALUES (776039, 201807, 22, 1823, 201807, 22, 1823, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:23:00', 'EST-5', '22-JUL-18 18:23:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ENE', 'WHITES CHAPEL', 3, 'ENE', 'WHITES CHAPEL', 35.7909, -79.6238, 35.7909, -79.6238, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Whites Chapel road near Woodrow Juilan Road.');
INSERT INTO public.stormevents_east VALUES (776040, 201807, 22, 1823, 201807, 22, 1823, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:23:00', 'EST-5', '22-JUL-18 18:23:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'WHITES CHAPEL', 2, 'ENE', 'WHITES CHAPEL', 35.7862, -79.6433, 35.7862, -79.6433, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Whites Chapel Road near Low Bridge Road.');
INSERT INTO public.stormevents_east VALUES (771147, 201806, 4, 2042, 201806, 4, 2042, 128486, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '04-JUN-18 20:42:00', 'EST-5', '04-JUN-18 20:42:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 35, 'MG', NULL, NULL, 10, 'SSE', 'PORT OF PALM BEACH', 10, 'SSE', 'PORT OF PALM BEACH', 26.6128, -80.0355, 26.6128, -80.0355, 'Abundant moisture and a weak frontal boundary across north Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity pushed off the coast into the local Atlantic waters during the early evening hours, producing several strong wind gusts.', 'A wind gust of 40 mph/35 knots was measured at Lake Worth Pier - LKWF1.');
INSERT INTO public.stormevents_east VALUES (771148, 201806, 5, 1838, 201806, 5, 1838, 128488, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MFL', '05-JUN-18 18:38:00', 'EST-5', '05-JUN-18 18:38:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 52, 'EG', NULL, NULL, 3, 'SW', 'SEMINOLE MANOR', 3, 'SW', 'SEMINOLE MANOR', 26.57, -80.11, 26.57, -80.11, 'Abundant moisture and a weak frontal boundary across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. Strong storms that developed across Palm Beach County during the evening hours produced small hail and damaging wind gusts.', 'WPTV relayed a report and shared photos of a fence that was knocked over and a gazebo that was blown over with a thunderstorm that moved through the area near the intersection of Hypoluxo Road and Military Trail. Time is estimated via radar and concurrent observations. Radar estimated winds of 60 mph with nearby observations recording gusts of 45 to 50 mph. Pea sized hail was also reported in the vicinity.');
INSERT INTO public.stormevents_east VALUES (771149, 201806, 6, 1230, 201806, 6, 1230, 128489, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '06-JUN-18 12:30:00', 'EST-5', '06-JUN-18 12:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 9, 'WSW', 'PORT MAYACA', 9, 'WSW', 'PORT MAYACA', 26.96, -80.94, 26.96, -80.94, 'Abundant moisture and a weak stationary front across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 39 mph/34 knots at SFWMD mesonet site L005 over Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (781505, 201807, 26, 214, 201807, 26, 1136, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '26-JUL-18 02:14:00', 'EST-5', '26-JUL-18 11:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'YORKSHIRE', 2, 'NW', 'YORKSHIRE', 38.8032, -77.4503, 38.8025, -77.4496, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'The Virginia Tech stream gage on Bull Run near Manassas Park exceeded the 12 foot flood stage during the indicated period. The peak level of 14.23 feet was observed at 7:15am EST. Trails along the stream were flooded throughout this time in the vicinity of Route 28.');
INSERT INTO public.stormevents_east VALUES (774682, 201807, 21, 1900, 201807, 21, 1905, 129286, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '21-JUL-18 19:00:00', 'EST-5', '21-JUL-18 19:05:00', 0, 0, 0, 0, '13.00K', NULL, '911 Call Center', 60, 'EG', NULL, NULL, 0, 'NNE', 'ARARAT', 1, 'NW', 'FLAT ROCK', 36.4016, -80.5691, 36.5121, -80.5701, 'During the afternoon and evening of the 21st, the influence of an area of high pressure weakened, while the influence of an approaching frontal boundary strengthened. The result was the development of isolated to scattered showers and thunderstorms. A couple of these storms increased to severe levels and generated damaging winds and large hail.', 'Thunderstorm winds blew twenty-six trees down from just southwest of Ararat to Ararat to Flat Rock. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774697, 201807, 22, 2015, 201807, 22, 2015, 129292, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '22-JUL-18 20:15:00', 'EST-5', '22-JUL-18 20:15:00', 0, 0, 0, 0, '0.50K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'NW', 'LEAKSVILLE ARPT', 3, 'NW', 'LEAKSVILLE ARPT', 36.5088, -79.8414, 36.5088, -79.8414, 'Showers and storms developed during the afternoon and evening of the 22nd in association with the approach of an area of low pressure. A few of these storms increased to severe levels and produced damaging winds.', 'Thunderstorm winds blew a tree down along Price road. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774698, 201807, 22, 2017, 201807, 22, 2017, 129292, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '22-JUL-18 20:17:00', 'EST-5', '22-JUL-18 20:17:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'QUICK', 1, 'W', 'QUICK', 36.3975, -79.5201, 36.3975, -79.5201, 'Showers and storms developed during the afternoon and evening of the 22nd in association with the approach of an area of low pressure. A few of these storms increased to severe levels and produced damaging winds.', 'Thunderstorm winds blew a tree down along the Route 158 at the Rockingham, Caswell county line. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (775029, 201807, 7, 815, 201807, 7, 900, 129349, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '07-JUL-18 08:15:00', 'EST-5', '07-JUL-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 40, 'ESE', 'SUTPHIN', 40, 'ESE', 'SUTPHIN', 35.6332, -78.7092, 35.6322, -78.7057, 'The leading edge of cool air nosing down the coast caused widespread, mainly stratiform rain which was slow moving and producing rainfall rates greater than one inch per hour for several hours. The front nearly stalled across Wake County during the morning, with a heavy rain focus south of Raleigh down into northern Harnett county. Radar estimated fairly extensive 2 to 3.35 inches of rainfall. This resulted in a couple of flash flooding reports.', 'Banks Road and Ten Ten Road were reported to be flooded.');
INSERT INTO public.stormevents_east VALUES (775031, 201807, 7, 1300, 201807, 7, 1300, 129349, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '07-JUL-18 13:00:00', 'EST-5', '07-JUL-18 13:00:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'ECHO HGTS', 0, 'E', 'ECHO HGTS', 35.7294, -78.6466, 35.7295, -78.644, 'The leading edge of cool air nosing down the coast caused widespread, mainly stratiform rain which was slow moving and producing rainfall rates greater than one inch per hour for several hours. The front nearly stalled across Wake County during the morning, with a heavy rain focus south of Raleigh down into northern Harnett county. Radar estimated fairly extensive 2 to 3.35 inches of rainfall. This resulted in a couple of flash flooding reports.', 'Flash Flooding was reported along Gideon Creek Way near the intersection of Durham Drive. One vehicle became stalled in the flood waters, prompting a water rescue.');
INSERT INTO public.stormevents_east VALUES (774623, 201807, 25, 1749, 201807, 25, 2000, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:49:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ARCOLA GLASCOCK ARPT', 1, 'N', 'ARCOLA GLASCOCK ARPT', 38.9415, -77.5514, 38.9411, -77.5502, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'US 50 flooded and closed near Stone Ridge.');
INSERT INTO public.stormevents_east VALUES (768126, 201807, 15, 1620, 201807, 15, 1620, 128083, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '15-JUL-18 16:20:00', 'EST-5', '15-JUL-18 16:20:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'MILLDALE', 3, 'SE', 'MILLDALE', 38.968, -78.055, 38.968, -78.055, 'An isolated thunderstorm produced damaging wind gusts.', 'A large tree was down near the intersection of Wells Drive and Ehlers Drive.');
INSERT INTO public.stormevents_east VALUES (754961, 201805, 14, 1825, 201805, 14, 1830, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:25:00', 'EST-5', '14-MAY-18 18:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 38 knots was reported at Cuckold Creek.');
INSERT INTO public.stormevents_east VALUES (772189, 201807, 24, 946, 201807, 24, 951, 128756, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '24-JUL-18 09:46:00', 'EST-5', '24-JUL-18 09:51:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'A cutoff low from the jet stream remained just to our west on the 24th. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts up to 35 knots were reported at Tolly Point.');
INSERT INTO public.stormevents_east VALUES (772193, 201807, 24, 936, 201807, 24, 936, 128756, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '24-JUL-18 09:36:00', 'EST-5', '24-JUL-18 09:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'A cutoff low from the jet stream remained just to our west on the 24th. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'Wind gusts in excess of 30 knots were reported at Key Bridge.');
INSERT INTO public.stormevents_east VALUES (780343, 201807, 21, 1318, 201807, 21, 1318, 130344, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'JAX', '21-JUL-18 13:18:00', 'EST-5', '21-JUL-18 13:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', 42, 'MG', NULL, NULL, 6, 'W', 'MAYPORT NAS', 6, 'W', 'MAYPORT NAS', 30.39, -81.52, 30.39, -81.52, 'An outflow boundary from a squall line of storms triggered severe storm development across SE Georgia during by midday across SE GA over an unstable and unseasonably high wind shear environment. SPC had a marginal risk of severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (780613, 201807, 22, 1050, 201807, 22, 1050, 130346, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '22-JUL-18 10:50:00', 'EST-5', '22-JUL-18 10:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'ENE', 'MELROSE', 2, 'ENE', 'MELROSE', 29.6893, -82.0382, 29.6893, -82.0382, 'A low level boundary was draped across north-central FL roughly from Suwanee to Marion counties with high moisture content and an unstable airmass pumping over the boundary from the Gulf of Mexico under WSW flow.', 'Power lines were blown down along 700 N State Road 21.');
INSERT INTO public.stormevents_east VALUES (762845, 201806, 2, 1600, 201806, 2, 1600, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:00:00', 'EST-5', '02-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'FOLKSTON DAVIS ARPT', 1, 'ENE', 'FOLKSTON DAVIS ARPT', 30.81, -82.01, 30.81, -82.01, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees and power lines were blown down near Little Feebie Church Road.');
INSERT INTO public.stormevents_east VALUES (762879, 201806, 2, 1750, 201806, 2, 1750, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:50:00', 'EST-5', '02-JUN-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'NE', 'DAYTONA NORTH', 2, 'NE', 'DAYTONA NORTH', 29.47, -81.38, 29.47, -81.38, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'The Johnson Brothers Sod Farm lost part of its roof from downburst winds. The winds also blew down large tree limbs along Highway 100 between County Road 305 and County Road 2005.');
INSERT INTO public.stormevents_east VALUES (758614, 201805, 18, 610, 201805, 18, 800, 126451, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '18-MAY-18 06:10:00', 'EST-5', '18-MAY-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 0, 'NW', 'WAYSIDE', 1, 'NW', 'WAYSIDE', 38.3538, -76.9367, 38.3559, -76.9358, 'Heavy rain fell in southern Maryland during the night of May 17th into the morning hours of the 18th. 1-4 inches of rain caused flooding, including of streams. More moderate to heavy rain continued in that area on the 18th and 19th, prolonging some flooding in Saint Mary''s County. Meanwhile, the cumulative effects of several days of rain throughout the region caused stream flooding, particularly on the Potomac River.', 'Shiloh Church Road reported flooded and closed near Ditchley Prong in the Newburg area.');
INSERT INTO public.stormevents_east VALUES (753849, 201805, 12, 1900, 201805, 12, 1900, 125698, 'MARYLAND', 24, 2018, 'May', 'Hail', 'LWX', '12-MAY-18 19:00:00', 'EST-5', '12-MAY-18 19:00:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 1, NULL, NULL, NULL, 2, 'N', 'BALTIMORE HIGHLANDS', 2, 'N', 'BALTIMORE HIGHLANDS', 39.262, -76.658, 39.262, -76.658, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'Quarter sized hail was reported.');
INSERT INTO public.stormevents_east VALUES (753893, 201805, 14, 1417, 201805, 14, 1417, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 14:17:00', 'EST-5', '14-MAY-18 14:17:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NNE', 'RUCKERSVILLE', 2, 'NNE', 'RUCKERSVILLE', 38.2625, -78.3563, 38.2625, -78.3563, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down blocking the roadway at Dairy Road and the Seminole Trail.');
INSERT INTO public.stormevents_east VALUES (754502, 201805, 14, 1640, 201805, 14, 1640, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 16:40:00', 'EST-5', '14-MAY-18 16:40:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 2, 'W', 'HILLSBORO', 2, 'W', 'HILLSBORO', 39.1986, -77.7543, 39.1986, -77.7543, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Multiple trees were down at a residency on Cider Mill Road.');
INSERT INTO public.stormevents_east VALUES (760921, 201805, 27, 1555, 201805, 27, 1730, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:55:00', 'EST-5', '27-MAY-18 17:30:00', 0, 0, 0, 0, '3.00M', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'CATONSVILLE', 1, 'S', 'WALBROOK', 39.3012, -76.71, 39.31, -76.6684, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Several roads flooded in Baltimore City. More than 20 people were rescued from vehicle rooftops during heavy rains. Six people were displaced from their homes, and Frederick Avenue was damaged in the Beechfield neighborhood.');
INSERT INTO public.stormevents_east VALUES (755610, 201805, 21, 1920, 201805, 22, 140, 126041, 'NORTH CAROLINA', 37, 2018, 'May', 'Flash Flood', 'RAH', '21-MAY-18 19:20:00', 'EST-5', '22-MAY-18 01:40:00', 0, 0, 0, 0, '600.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'LEESVILLE', 1, 'W', 'CAMP POLK', 35.89, -78.71, 35.82, -78.71, 'An outflow-augmented back-door cold front, served as the foci for a slow northeast to southwest moving cluster of storms and torrential rainfall across the northern Piedmont and northern Coastal Plain counties. The heaviest rainfall of 3 to 5 inches fell across North Raleigh, which caused Crabtree Creek to flood. Multiple road closures were reported in northwest Raleigh and several cars were stranded in a flooded road.', 'Several roads were closed in northwest Raleigh, many in the vicinity of Crabtree Valley Mall and Crabtree Creek, due to flash flooding. Newton Road near Six Forks Road washed out and collapsed. Several cars were stranded in flood water near the intersection of Leesville Road and Millbrook Road. Several cars were underwater at the Crabtree Valley Mall due to flooding along Crabtree Creek overflowing its banks into the parking garage.');
INSERT INTO public.stormevents_east VALUES (759816, 201805, 15, 1350, 201805, 15, 1350, 126736, 'NEW YORK', 36, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 13:50:00', 'EST-5', '15-MAY-18 13:50:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 2, NULL, NULL, NULL, 0, 'N', 'LIVINGSTON MANOR', 0, 'N', 'LIVINGSTON MANOR', 41.9, -74.83, 41.9, -74.83, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (759817, 201805, 15, 1400, 201805, 15, 1400, 126736, 'NEW YORK', 36, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 14:00:00', 'EST-5', '15-MAY-18 14:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 1.75, NULL, NULL, NULL, 0, 'N', 'LIVINGSTON MANOR', 0, 'N', 'LIVINGSTON MANOR', 41.9, -74.83, 41.9, -74.83, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (759818, 201805, 15, 1400, 201805, 15, 1400, 126736, 'NEW YORK', 36, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 14:00:00', 'EST-5', '15-MAY-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1.75, NULL, NULL, NULL, 0, 'N', 'ROSCOE', 0, 'N', 'ROSCOE', 41.93, -74.92, 41.93, -74.92, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (759819, 201805, 15, 1415, 201805, 15, 1415, 126736, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:15:00', 'EST-5', '15-MAY-18 14:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'PARKSVILLE', 0, 'N', 'PARKSVILLE', 41.85, -74.77, 41.85, -74.77, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Trees blown down near Main street and Route 17 blocking both  lanes of road.');
INSERT INTO public.stormevents_east VALUES (759820, 201805, 15, 1415, 201805, 15, 1415, 126736, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:15:00', 'EST-5', '15-MAY-18 14:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 0, 'N', 'LIVINGSTON MANOR', 0, 'N', 'LIVINGSTON MANOR', 41.9, -74.83, 41.9, -74.83, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down on wires .');
INSERT INTO public.stormevents_east VALUES (761167, 201805, 15, 1112, 201805, 15, 1112, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:12:00', 'EST-5', '15-MAY-18 11:12:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Newspaper', 50, 'EG', NULL, NULL, 1, 'SW', 'OGLE', 1, 'SW', 'OGLE', 40.69, -80.11, 40.69, -80.11, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'Local newspaper reported trees and a utility pole down.');
INSERT INTO public.stormevents_east VALUES (761168, 201805, 15, 1113, 201805, 15, 1113, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:13:00', 'EST-5', '15-MAY-18 11:13:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'NW', 'CLARINGTON', 2, 'NW', 'CLARINGTON', 41.35, -79.14, 41.35, -79.14, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State Department of Highways reported trees down on Greenwald Road.');
INSERT INTO public.stormevents_east VALUES (761162, 201805, 15, 1209, 201805, 15, 1209, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '15-MAY-18 12:09:00', 'EST-5', '15-MAY-18 12:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'E', 'COMMODORE', 1, 'E', 'COMMODORE', 40.72, -78.92, 40.72, -78.92, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', NULL);
INSERT INTO public.stormevents_east VALUES (761163, 201805, 15, 1220, 201805, 15, 1220, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '15-MAY-18 12:20:00', 'EST-5', '15-MAY-18 12:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 1, 'NW', 'SYKESVILLE', 1, 'NW', 'SYKESVILLE', 41.06, -78.84, 41.06, -78.84, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', NULL);
INSERT INTO public.stormevents_east VALUES (761165, 201805, 15, 1056, 201805, 15, 1056, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 10:56:00', 'EST-5', '15-MAY-18 10:56:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SSE', 'CROWN', 1, 'SSE', 'CROWN', 41.36, -79.27, 41.36, -79.27, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State official reported trees down in Farmington Township.');
INSERT INTO public.stormevents_east VALUES (761166, 201805, 15, 1111, 201805, 15, 1111, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:11:00', 'EST-5', '15-MAY-18 11:11:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'E', 'COOKSBURG', 1, 'E', 'COOKSBURG', 41.33, -79.2, 41.33, -79.2, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State Department of Highways reported trees down on Cemetery Road.');
INSERT INTO public.stormevents_east VALUES (761169, 201805, 15, 1115, 201805, 15, 1115, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:15:00', 'EST-5', '15-MAY-18 11:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'ENE', 'COOKSBURG', 1, 'ENE', 'COOKSBURG', 41.34, -79.2, 41.34, -79.2, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State Department of Highways reported trees down on River Road.');
INSERT INTO public.stormevents_east VALUES (761170, 201805, 15, 1127, 201805, 15, 1127, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:27:00', 'EST-5', '15-MAY-18 11:27:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'LEATHERWOOD', 1, 'SE', 'LEATHERWOOD', 41.02, -79.39, 41.02, -79.39, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State official reported trees down on State Route 861.');
INSERT INTO public.stormevents_east VALUES (759775, 201805, 10, 1650, 201805, 10, 1650, 126733, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '10-MAY-18 16:50:00', 'EST-5', '10-MAY-18 16:50:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 3, 'NW', 'HARDING', 3, 'NW', 'HARDING', 41.4, -75.86, 41.4, -75.86, 'A frontal system moved across northeast Pennsylvania during the late afternoon of the 10th producing a few severe thunderstorms in northeast Pennsylvania.', 'Thunderstorm winds blew down trees on Lockville Road Exeter Township.');
INSERT INTO public.stormevents_east VALUES (759793, 201805, 15, 1416, 201805, 15, 1416, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:16:00', 'EST-5', '15-MAY-18 14:16:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 60, 'EG', NULL, NULL, 1, 'W', 'BUSH PATCH', 1, 'W', 'BUSH PATCH', 41.37, -75.74, 41.37, -75.74, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew a roof off a small home.');
INSERT INTO public.stormevents_east VALUES (762155, 201805, 30, 1455, 201805, 30, 1600, 124769, 'GEORGIA', 13, 2018, 'May', 'Flash Flood', 'FFC', '30-MAY-18 14:55:00', 'EST-5', '30-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'EASTBURN', 2, 'NNW', 'EASTBURN', 34.6286, -83.6762, 34.624, -83.6765, 'The remnants of Subtropical Storm Alberto continued to impact the region May 29 and early May 30, with persistent enhanced moisture plaguing the region. As bands of showers and thunderstorms encountered the topography of northeast Georgia, the storms became anchored, training and redeveloping over the ridge line. Over the terrain, widespread 3 to 6 inches were observed. Portions of southern Towns County received 6 to 8 inches, with locally higher amounts in isolated areas.', 'The Emergency Manager reported Roy Powers Road was closed due to high water from Brasstown Creek.');
INSERT INTO public.stormevents_east VALUES (762153, 201805, 30, 200, 201805, 30, 1200, 124769, 'GEORGIA', 13, 2018, 'May', 'Flash Flood', 'FFC', '30-MAY-18 02:00:00', 'EST-5', '30-MAY-18 12:00:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 8, 'SSW', 'MACEDONIA', 8, 'S', 'MACEDONIA', 34.8078, -83.7593, 34.8026, -83.7165, 'The remnants of Subtropical Storm Alberto continued to impact the region May 29 and early May 30, with persistent enhanced moisture plaguing the region. As bands of showers and thunderstorms encountered the topography of northeast Georgia, the storms became anchored, training and redeveloping over the ridge line. Over the terrain, widespread 3 to 6 inches were observed. Portions of southern Towns County received 6 to 8 inches, with locally higher amounts in isolated areas.', 'Emergency Management reported several roads experienced flooding in Towns County. The Enchanted Valley Resort RV park and River Bend Campground were evacuated due to high water from the Hiwassee River. Two cows and a cat were killed as a result of the flash flooding near the River Bend Campground. Additionally, a small mudslide occurred at Unicoi Gap.');
INSERT INTO public.stormevents_east VALUES (762154, 201805, 30, 300, 201805, 30, 1200, 124769, 'GEORGIA', 13, 2018, 'May', 'Flash Flood', 'FFC', '30-MAY-18 03:00:00', 'EST-5', '30-MAY-18 12:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 5, 'NNW', 'CLEVELAND WHITE ARPT', 1, 'W', 'CLEVELAND WHITE ARPT', 34.7923, -83.7587, 34.7217, -83.7557, 'The remnants of Subtropical Storm Alberto continued to impact the region May 29 and early May 30, with persistent enhanced moisture plaguing the region. As bands of showers and thunderstorms encountered the topography of northeast Georgia, the storms became anchored, training and redeveloping over the ridge line. Over the terrain, widespread 3 to 6 inches were observed. Portions of southern Towns County received 6 to 8 inches, with locally higher amounts in isolated areas.', 'The Emergency Manager reported several road closures as a result of flash flooding, including: Tray Mountain Road north of Rice Cabin Falls, Chastain Road, Bean Creek Road near Highway 356, and State Route 75 between Robertstown and Unicoi Gap.');
INSERT INTO public.stormevents_east VALUES (762156, 201805, 30, 1300, 201805, 30, 1600, 124769, 'GEORGIA', 13, 2018, 'May', 'Flash Flood', 'FFC', '30-MAY-18 13:00:00', 'EST-5', '30-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNW', 'TESNATEE', 3, 'NNW', 'TESNATEE', 34.5698, -83.8591, 34.5675, -83.8557, 'The remnants of Subtropical Storm Alberto continued to impact the region May 29 and early May 30, with persistent enhanced moisture plaguing the region. As bands of showers and thunderstorms encountered the topography of northeast Georgia, the storms became anchored, training and redeveloping over the ridge line. Over the terrain, widespread 3 to 6 inches were observed. Portions of southern Towns County received 6 to 8 inches, with locally higher amounts in isolated areas.', 'The Emergency Manager reported that Sandy Flats Road was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (745883, 201805, 14, 1125, 201805, 14, 1126, 124326, 'FLORIDA', 12, 2018, 'May', 'Tornado', 'MLB', '14-MAY-18 11:25:00', 'EST-5', '14-MAY-18 11:26:00', 0, 0, 0, 0, '7.50K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 4, 'NE', 'MARCY', 4, 'NE', 'MARCY', 27.1675, -80.5853, 27.1694, -80.585, 'The interaction between a strengthening low pressure system in the eastern Gulf of Mexico and the Atlantic Bermuda High caused south winds to develop across the Florida peninsula. These winds brought a surge of moisture from the Caribbean across the state of Florida. A weak inverted trough/low pressure system developed in the eastern Gulf of Mexico, this in turn increased the low-level shear across much of east central Florida. Widespread showers and thunderstorms were ongoing throughout the day. One thunderstorm just offshore the Brevard County Coast became strong and developed a mesocyclone. This storm produced a waterspout that moved onshore and produced minor damage on Merritt Island. A second storm over inland Martin County developed a mesocyclone and produced a weak tornado, resulting in minor damage near Indiantown.', 'A NWS Storm Survey determined that a severe thunderstorm along a band of convection spawned a brief tornado over rural northwest Martin County. The EF-0 tornado, with estimated winds of 70-80 mph, caused minor damage to a screen porch and damaged roof shingles on a two-story home. The tornado also ripped a portions of a roof and south-facing wall from an adjacent barn and uprooted a large tree. Debris was carried northward from the impact area.');
INSERT INTO public.stormevents_east VALUES (777992, 201808, 21, 1309, 201808, 21, 1509, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 13:09:00', 'EST-5', '21-AUG-18 15:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'DUDIE', 1, 'ENE', 'DUDIE', 38.7407, -77.8546, 38.7408, -77.8577, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Route 690 at Cannonball Gate Road was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (750806, 201805, 27, 900, 201805, 27, 900, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 09:00:00', 'EST-5', '27-MAY-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'BUOY 41009', 0, 'N', 'BUOY 41009', 28.52, -80.17, 28.52, -80.17, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'Buoy 41009 measured a peak wind gust of 41 knots from the south-southeast.');
INSERT INTO public.stormevents_east VALUES (758525, 201807, 20, 2123, 201807, 20, 2123, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 21:23:00', 'EST-5', '20-JUL-18 21:23:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'BEAN STATION', 1, 'N', 'BEAN STATION', 36.34, -83.28, 36.34, -83.28, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (758526, 201807, 20, 2127, 201807, 20, 2127, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 21:27:00', 'EST-5', '20-JUL-18 21:27:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'MAYNARDVILLE', 1, 'W', 'MAYNARDVILLE', 36.25, -83.81, 36.25, -83.81, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down in Maynardville.');
INSERT INTO public.stormevents_east VALUES (758528, 201807, 20, 2138, 201807, 20, 2138, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 21:38:00', 'EST-5', '20-JUL-18 21:38:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 55, 'EG', NULL, NULL, 1, 'NW', 'SPRINGDALE', 1, 'NW', 'SPRINGDALE', 36.53, -82.56, 36.53, -82.56, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Traffic signals and wires were reported down in Kingsport.');
INSERT INTO public.stormevents_east VALUES (758529, 201807, 20, 2145, 201807, 20, 2145, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 21:45:00', 'EST-5', '20-JUL-18 21:45:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 55, 'EG', NULL, NULL, 0, 'N', 'HALLS XRDS', 0, 'N', 'HALLS XRDS', 36.08, -83.93, 36.08, -83.93, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down. One tree had fallen on a car.');
INSERT INTO public.stormevents_east VALUES (777994, 201808, 21, 1318, 201808, 21, 1518, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 13:18:00', 'EST-5', '21-AUG-18 15:18:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'WARRENTON', 1, 'E', 'WARRENTON', 38.72, -77.76, 38.7207, -77.7584, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The road was closed at the bridge at the 7600 block of Frytown Road.');
INSERT INTO public.stormevents_east VALUES (769465, 201806, 28, 1430, 201806, 28, 1430, 128303, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '28-JUN-18 14:30:00', 'EST-5', '28-JUN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'E', 'SAMPSON', 1, 'E', 'SAMPSON', 30.02, -81.39, 30.02, -81.39, 'A passing upper level disturbance enhanced diurnally enhanced sea breeze convection over a moist and unstable airmass.', 'A tree was snapped in Palencia.');
INSERT INTO public.stormevents_east VALUES (769467, 201806, 28, 1730, 201806, 28, 1730, 128303, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '28-JUN-18 17:30:00', 'EST-5', '28-JUN-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'MG', NULL, NULL, 2, 'WNW', 'ALACHUA', 2, 'WNW', 'ALACHUA', 29.79, -82.53, 29.79, -82.53, 'A passing upper level disturbance enhanced diurnally enhanced sea breeze convection over a moist and unstable airmass.', 'A tree was blown down and blocked the road between High Springs and Alachua.');
INSERT INTO public.stormevents_east VALUES (769469, 201806, 28, 1900, 201806, 28, 1900, 128304, 'GEORGIA', 13, 2018, 'June', 'Heavy Rain', 'JAX', '28-JUN-18 19:00:00', 'EST-5', '28-JUN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 0, 'N', 'FOLKSTON', 0, 'N', 'FOLKSTON', 30.83, -82.02, 30.83, -82.02, 'A passing upper level disturbance enhanced diurnally enhanced sea breeze convection over a moist and unstable airmass.', 'Street flooding was reported in Folkston.');
INSERT INTO public.stormevents_east VALUES (769475, 201806, 30, 1233, 201806, 30, 1233, 128305, 'FLORIDA', 12, 2018, 'June', 'Funnel Cloud', 'JAX', '30-JUN-18 12:33:00', 'EST-5', '30-JUN-18 12:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'NE', 'OCALA ARPT', 2, 'NE', 'OCALA ARPT', 29.19, -82.2, 29.19, -82.2, 'Sea breezes storms and outflow mergers over a moist and unstable airmass spawned a brief funnel cloud.', 'A funnel cloud was observed 2 miles north of the Ocala Airport.');
INSERT INTO public.stormevents_east VALUES (769478, 201806, 2, 1635, 201806, 2, 1635, 127224, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '02-JUN-18 16:35:00', 'EST-5', '02-JUN-18 16:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 2, 'SE', 'CUMBERLAND STAFFORD', 2, 'SE', 'CUMBERLAND STAFFORD', 31.05, -81.41, 31.05, -81.41, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', NULL);
INSERT INTO public.stormevents_east VALUES (784160, 201806, 3, 1724, 201806, 3, 1724, 127794, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '03-JUN-18 17:24:00', 'EST-5', '03-JUN-18 17:24:00', 1, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'NE', 'ARREDONDA', 1, 'NE', 'ARREDONDA', 29.61, -82.41, 29.61, -82.41, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'A male was struck by lightning with only minor injuries. The time of the strike was estimated.');
INSERT INTO public.stormevents_east VALUES (775007, 201807, 6, 1540, 201807, 6, 1540, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:40:00', 'EST-5', '06-JUL-18 15:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'ENE', 'ROUGEMONT', 2, 'ENE', 'ROUGEMONT', 36.23, -78.9, 36.23, -78.9, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Multiple trees were reported down near the Durham Person County Line.');
INSERT INTO public.stormevents_east VALUES (775010, 201807, 6, 1540, 201807, 6, 1540, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:40:00', 'EST-5', '06-JUL-18 15:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'S', 'MT TIRZAH', 2, 'S', 'MT TIRZAH', 36.2448, -78.9072, 36.2448, -78.9072, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Trees and power lines were reported down at the intersection of Moores Mill Road and Rassie Crabtree Road.');
INSERT INTO public.stormevents_east VALUES (757407, 201805, 15, 1611, 201805, 15, 1611, 126337, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '15-MAY-18 16:11:00', 'EST-5', '15-MAY-18 16:11:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 52, 'MG', NULL, NULL, 1, 'N', 'LARCHMONT HARBOR WXFLOW', 1, 'N', 'LARCHMONT HARBOR WXFLOW', 40.93, -73.73, 40.93, -73.73, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 60 mile per hour gust was reported at Larchmont Harbor mesonet.');
INSERT INTO public.stormevents_east VALUES (757408, 201805, 15, 1618, 201805, 15, 1618, 126337, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '15-MAY-18 16:18:00', 'EST-5', '15-MAY-18 16:18:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 59, 'MG', NULL, NULL, 0, 'N', 'BAYVILLE WXFLOW', 0, 'N', 'BAYVILLE WXFLOW', 40.9, -73.63, 40.9, -73.63, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 68 mile per hour gust was reported at Bayville mesonet.');
INSERT INTO public.stormevents_east VALUES (783356, 201805, 15, 1607, 201805, 15, 1607, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Hail', 'OKX', '15-MAY-18 16:07:00', 'EST-5', '15-MAY-18 16:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NE', 'LONG HILL', 1, 'NE', 'LONG HILL', 41.26, -73.21, 41.26, -73.21, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', NULL);
INSERT INTO public.stormevents_east VALUES (783361, 201805, 15, 1615, 201805, 15, 1615, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:15:00', 'EST-5', '15-MAY-18 16:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 1, 'SSW', 'WESTON', 1, 'SSW', 'WESTON', 41.18, -73.39, 41.18, -73.39, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree on car with people trapped on Route 300 near New Windsor.');
INSERT INTO public.stormevents_east VALUES (783371, 201805, 15, 1607, 201805, 15, 1607, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:07:00', 'EST-5', '15-MAY-18 16:07:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'NE', 'ANSONIA', 1, 'NE', 'ANSONIA', 41.34, -73.07, 41.34, -73.07, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Power lines down, 1 inch hail reported.');
INSERT INTO public.stormevents_east VALUES (766259, 201806, 2, 1440, 201806, 2, 1440, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 14:40:00', 'EST-5', '02-JUN-18 14:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WNW', 'MAYDAY', 1, 'WNW', 'MAYDAY', 30.8287, -83.0229, 30.8287, -83.0229, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Many trees were blown down near Howell and Mayday. Minor damage occurred to a few building. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (766260, 201806, 2, 1530, 201806, 2, 1530, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 15:30:00', 'EST-5', '02-JUN-18 15:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'NNE', 'HEBARDVILLE', 1, 'NNE', 'HEBARDVILLE', 31.2357, -82.4145, 31.2357, -82.4145, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Power lines were blown down and a transformer blew at 3040 Cherokee Street. Time of damage was based on radar.  Cost of damage was unknown, but it was estimated for inclusion in Storm Data.');
INSERT INTO public.stormevents_east VALUES (766261, 201806, 2, 1530, 201806, 2, 1530, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 15:30:00', 'EST-5', '02-JUN-18 15:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 2, 'E', 'WEST WAYCROSS', 2, 'E', 'WEST WAYCROSS', 31.1797, -82.367, 31.1797, -82.367, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A tree was blown down across Gibbs Street. The time of damage was based on radar data. The cost of damage was unknown, but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (755078, 201807, 2, 1520, 201807, 2, 1520, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 15:20:00', 'EST-5', '02-JUL-18 15:20:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'SMITHFIELD', 1, 'E', 'SMITHFIELD', 40.4818, -78.0125, 40.4818, -78.0125, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires at Pennsylvania Avenue and 4th Street in Smithfield Township.');
INSERT INTO public.stormevents_east VALUES (755083, 201807, 2, 1524, 201807, 2, 1524, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 15:24:00', 'EST-5', '02-JUL-18 15:24:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 0, 'WSW', 'PETERSBURG', 0, 'WSW', 'PETERSBURG', 40.5677, -78.0583, 40.5677, -78.0583, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees in Logan Township.');
INSERT INTO public.stormevents_east VALUES (755106, 201807, 2, 1625, 201807, 2, 1625, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '02-JUL-18 16:25:00', 'EST-5', '02-JUL-18 16:25:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 1, 'W', 'NIVETON SPGS', 1, 'W', 'NIVETON SPGS', 39.7317, -79.1518, 39.7317, -79.1518, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees onto wires near Springs.');
INSERT INTO public.stormevents_east VALUES (761535, 201807, 2, 1505, 201807, 2, 1730, 125803, 'PENNSYLVANIA', 42, 2018, 'July', 'Flash Flood', 'CTP', '02-JUL-18 15:05:00', 'EST-5', '02-JUL-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'NEWBURG', 3, 'N', 'PUZZLETOWN', 40.5372, -78.4911, 40.4197, -78.4993, 'Pulse storms developed over the higher elevations of central Pennsylvania in a high CAPE, low shear environment. In an abnormally hot and humid airmass, these storms produced torrential rainfall and isolated reports of wind damage.', 'Flash flooding hit Blair County and the Altoona area that afternoon.   Approximately 100 homes and businesses suffered damage and Duncansville, Allegheny and Blair Townships made disaster declarations.   Multiple requests for evacuations were made during the event from residents.  A natural gas leak was reported at 210 Cambridge Drive in Allegheny Township.  Water rescues were performed at 10th Street at 8th Avenue in Duncansville.');
INSERT INTO public.stormevents_east VALUES (762871, 201807, 4, 1250, 201807, 4, 1250, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '04-JUL-18 12:50:00', 'EST-5', '04-JUL-18 12:50:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WSW', 'MINGOVILLE', 1, 'WSW', 'MINGOVILLE', 40.9247, -77.6449, 40.9247, -77.6449, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees and wires across Hecla Road near Mingoville.');
INSERT INTO public.stormevents_east VALUES (774879, 201807, 25, 1945, 201807, 25, 2045, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 19:45:00', 'EST-5', '25-JUL-18 20:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'SCARBORO', 1, 'SE', 'SCARBORO', 39.623, -76.2666, 39.6224, -76.2665, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Eight inches of water flowing over the roadway near the intersection of Priestford Road and Trappe Road.');
INSERT INTO public.stormevents_east VALUES (769161, 201806, 21, 1300, 201806, 21, 1527, 128239, 'FLORIDA', 12, 2018, 'June', 'Flood', 'JAX', '21-JUN-18 13:00:00', 'EST-5', '21-JUN-18 15:27:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'PINE LAKES', 1, 'SE', 'INDIAN TRAILS', 29.53, -81.21, 29.57, -81.24, 'A low level trough axis lingered across north-central Florida which served as a focus for an early start to diurnally enhanced showers and thunderstorms. Locally heavy rainfall occurred along and near this trough axis.', 'By 3 pm, a CoCoRaHS observer about 5 miles SSE of Marineland measured 4.79 inches in 90 minutes. At 3:21 pm, the EM reported multiple streets were flooded in NW Palm Coast. At 3:33 pm, a spotter in Palm Coast reported about 8 inches of water covered Pritchard Drive. At 4 pm, the public about 5 miles SSW of Marineland measured 5.13 inches of rainfall between 2 pm and 4 pm. At 4:27 pm, the EM reported Barrington Drive in Palm Coast was not passable due to flooding.  Other notable weather recordings from the EM include the following rainfall totals between 1345-1645 local time: 3.70 NW Palm Coast by a Spotter, 3.37 SE Flagler Beach (2 hr total) with dune washouts, 3.21 in Flagler Beach. Multiple roads were under water and a few were not passable in Indian Trails section of Palm Coast. Some roads in Flagler Beach and near Palm Circle were flooded. The cost of damage was unknown, but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (761258, 201805, 31, 335, 201805, 31, 430, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '31-MAY-18 03:35:00', 'EST-5', '31-MAY-18 04:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'DOOMS', 3, 'S', 'DOOMS', 38.0729, -78.8598, 38.0729, -78.8594, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'A Street was blocked by rushing water with Steele Run out of its banks.');
INSERT INTO public.stormevents_east VALUES (761260, 201805, 30, 2337, 201805, 31, 100, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '30-MAY-18 23:37:00', 'EST-5', '31-MAY-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'DOOMS', 2, 'SSE', 'DOOMS', 38.0939, -78.8637, 38.0941, -78.8634, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'All lanes of US 340 were covered by water which had overflowed from a retention area. Nearby basements were flooded due to overland runoff entering from above ground.');
INSERT INTO public.stormevents_east VALUES (761262, 201805, 31, 355, 201805, 31, 600, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 03:55:00', 'EST-5', '31-MAY-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'CRIGLERSVILLE', 0, 'N', 'BANCO', 38.4645, -78.3156, 38.4555, -78.299, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Several roads were flooded and closed near Criglersville.');
INSERT INTO public.stormevents_east VALUES (756757, 201805, 15, 1618, 201805, 15, 1618, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:18:00', 'EST-5', '15-MAY-18 16:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 59, 'MG', NULL, NULL, 2, 'W', 'LAFFINGTOWN', 2, 'W', 'LAFFINGTOWN', 40.9, -73.63, 40.9, -73.63, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 68 mile per hour wind gust was reported at Bayville mesonet.  Winds recorded at 45 ft.');
INSERT INTO public.stormevents_east VALUES (761273, 201805, 31, 1943, 201805, 31, 2100, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 19:43:00', 'EST-5', '31-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'OCCOQUAN', 1, 'ENE', 'OCCOQUAN', 38.6841, -77.2606, 38.6839, -77.2603, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Mill Street flooded in Occoquan near Union Street.');
INSERT INTO public.stormevents_east VALUES (761271, 201805, 31, 1930, 201805, 31, 2030, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 19:30:00', 'EST-5', '31-MAY-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BETHEL', 1, 'SSW', 'BETHEL', 38.6388, -77.3256, 38.6379, -77.3244, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Several cars were stalled in high water on Dale Boulevard near Forestdale Avenue.');
INSERT INTO public.stormevents_east VALUES (761274, 201805, 31, 1950, 201805, 31, 2100, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 19:50:00', 'EST-5', '31-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'CANOVA', 1, 'ENE', 'CANOVA', 38.6849, -77.4087, 38.6845, -77.4081, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Purcell Road flooded and closed near Hunters Grove Road.');
INSERT INTO public.stormevents_east VALUES (759274, 201805, 21, 2340, 201805, 22, 30, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '21-MAY-18 23:40:00', 'EST-5', '22-MAY-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GENOA', 5, 'WNW', 'GENOA', 38.63, -78.92, 38.6631, -79.0024, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Significant flash flooding was reported in the Yankeetown and Fulks Run areas, with water in vehicles, numerous roads closed, and most small streams out of their banks.');
INSERT INTO public.stormevents_east VALUES (759275, 201805, 21, 2340, 201805, 22, 30, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '21-MAY-18 23:40:00', 'EST-5', '22-MAY-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GENOA', 1, 'S', 'GENOA', 38.6351, -78.9169, 38.6345, -78.9162, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'A portion of Hopkins Gap Road was scoured out near Turner Run and the Bare Ridge Road intersection.');
INSERT INTO public.stormevents_east VALUES (759277, 201805, 21, 1945, 201805, 21, 2145, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '21-MAY-18 19:45:00', 'EST-5', '21-MAY-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'BERGTON', 2, 'WNW', 'BERGTON', 38.74, -78.94, 38.7805, -78.9664, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Several roads in the Bergton and Yankeetown area were observed to have water over them but they were all still passable.');
INSERT INTO public.stormevents_east VALUES (759280, 201805, 22, 1609, 201805, 22, 1800, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 16:09:00', 'EST-5', '22-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CLARKS CROSSING', 1, 'SE', 'CLARKS CROSSING', 38.9137, -77.2935, 38.9134, -77.2926, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Lawyers Road flooded and closed at Carrhill Road.');
INSERT INTO public.stormevents_east VALUES (761289, 201805, 30, 2141, 201805, 30, 2335, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 21:41:00', 'EST-5', '30-MAY-18 23:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'FREE UNION', 2, 'SSE', 'FREE UNION', 38.1392, -78.5577, 38.1407, -78.5553, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The stream gage on Moormans River near Free Union rapidly exceeded the 14 foot flood stage during the time indicated. The fields of a campground are flooded at this level.');
INSERT INTO public.stormevents_east VALUES (756715, 201805, 15, 1553, 201805, 15, 1601, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Tornado', 'OKX', '15-MAY-18 15:53:00', 'EST-5', '15-MAY-18 16:01:00', 0, 0, 0, 0, '100.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'S', 'SOUTHFORD', 1, 'E', 'QUAKER FARMS', 41.4664, -73.1691, 41.4186, -73.1383, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A tornado touched down near the intersection of Route 67 and |Burma Road in Southbury and continued southeast into Oxford, |leaving a path of numerous uprooted and snapped pine trees and |some hardwood trees. The tornado lifted after damaging the roof of|the Great Oak School in Oxford. Based on this information, this |tornado is classified as an EF1 with maximum winds of 100 mph.');
INSERT INTO public.stormevents_east VALUES (756479, 201805, 15, 1529, 201805, 15, 1530, 124185, 'NEW YORK', 36, 2018, 'May', 'Tornado', 'OKX', '15-MAY-18 15:29:00', 'EST-5', '15-MAY-18 15:30:00', 0, 0, 0, 0, '250.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'W', 'LUDINGTONVILLE', 1, 'N', 'LAKE CARMEL', 41.4996, -73.6847, 41.485, -73.6727, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Based on a National Weather Service storm survey, done in|conjunction with the Putnam County Bureau of Emergency |Services, is been determined that an EF2 tornado with estimated |peak winds of 115 mph moved through Kent, New York. The tornado|originated near apartments at 1213 New York Route 52. It continued|down NY State Route 52, damaging some roofs in the strip mall at |the intersection of Route 52 and Farmers Mill Road, where it also|knocked down portions of the parapet above the Dunkin Donuts, and|snapped and uprooted some trees. The tornado lifted near 52 Bowen|Road in Kent. The most extensive damage was along Schuykill |Court, where dozens of large trees were uprooted and snapped, with|a convergent pattern to most of the fallen trees. Based on this |damage, the tornado was classified as an EF2, with estimated |maximum winds of around 115 mph.');
INSERT INTO public.stormevents_east VALUES (753157, 201805, 3, 1756, 201805, 3, 1756, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 17:56:00', 'EST-5', '03-MAY-18 17:56:00', 0, 0, 0, 0, '5.00K', NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'THORNWOOD', 0, 'N', 'THORNWOOD', 41.12, -73.78, 41.12, -73.78, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'Reports of numerous trees down around town.');
INSERT INTO public.stormevents_east VALUES (753158, 201805, 3, 1757, 201805, 3, 1757, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 17:57:00', 'EST-5', '03-MAY-18 17:57:00', 0, 0, 0, 0, '3.00K', NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'ARMONK', 0, 'N', 'ARMONK', 41.12, -73.73, 41.12, -73.73, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'Multiple trees were reported down across the town.');
INSERT INTO public.stormevents_east VALUES (755010, 201805, 27, 1454, 201805, 27, 1506, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 14:54:00', 'EST-5', '27-MAY-18 15:06:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'A wind gust in excess of 30 knots was reported at Key Bridge.');
INSERT INTO public.stormevents_east VALUES (755012, 201805, 27, 1606, 201805, 27, 1606, 125940, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '27-MAY-18 16:06:00', 'EST-5', '27-MAY-18 16:06:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. A few storms produced gusty winds.', 'A wind gust in excess of 30 knots was reported at Tolly Point.');
INSERT INTO public.stormevents_east VALUES (761246, 201805, 30, 2341, 201805, 31, 200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 23:41:00', 'EST-5', '31-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'DYKE', 2, 'ESE', 'DYKE', 38.2355, -78.494, 38.2345, -78.4937, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Chapman Road flooded and closed at the Roach River.');
INSERT INTO public.stormevents_east VALUES (760972, 201805, 30, 2232, 201805, 30, 2330, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 22:32:00', 'EST-5', '30-MAY-18 23:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 4, 'N', 'IVY', 4, 'N', 'IVY', 38.1032, -78.5936, 38.1034, -78.5911, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Mechums River flooded, causing washouts of portions of Whippoorwill Road and Garth Road.');
INSERT INTO public.stormevents_east VALUES (761247, 201805, 30, 2341, 201805, 31, 200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 23:41:00', 'EST-5', '31-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'W', 'QUINQUE', 4, 'E', 'DYKE', 38.252, -78.465, 38.2509, -78.4651, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Amicus Road flooded and closed in multiple spots west of Quinque.');
INSERT INTO public.stormevents_east VALUES (776055, 201807, 22, 1936, 201807, 22, 1936, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 19:36:00', 'EST-5', '22-JUL-18 19:36:00', 0, 0, 0, 0, '2.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNE', 'MONTICELLO', 1, 'NNE', 'MONTICELLO', 36.24, -79.67, 36.24, -79.67, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Several trees were reported down along United States Highway 29.');
INSERT INTO public.stormevents_east VALUES (776056, 201807, 22, 2005, 201807, 22, 2005, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 20:05:00', 'EST-5', '22-JUL-18 20:05:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SE', 'DURHAM', 1, 'SE', 'DURHAM', 36.0114, -78.9117, 36.0114, -78.9117, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Trees were reported down on Green Street.');
INSERT INTO public.stormevents_east VALUES (776057, 201807, 22, 2042, 201807, 22, 2042, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 20:42:00', 'EST-5', '22-JUL-18 20:42:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'W', 'MT TIRZAH', 0, 'W', 'MT TIRZAH', 36.2806, -78.9065, 36.2806, -78.9065, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Multiple trees and power lines were reported down near the intersection of Surl Mount Tirzah Road and Helena Moriah Road.');
INSERT INTO public.stormevents_east VALUES (776058, 201807, 22, 2056, 201807, 22, 2056, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 20:56:00', 'EST-5', '22-JUL-18 20:56:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'SSE', 'CEFFO', 2, 'SSE', 'CEFFO', 36.4278, -79.0427, 36.4278, -79.0427, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Numerous tree were reported down near the intersection of Jack Hambrick Road and Morton Pulliam Road.');
INSERT INTO public.stormevents_east VALUES (776068, 201807, 22, 2330, 201807, 22, 2330, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 23:30:00', 'EST-5', '22-JUL-18 23:30:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SE', 'MT OLIVE ARPT', 2, 'SE', 'MT OLIVE ARPT', 35.2017, -78.0097, 35.2017, -78.0097, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'A tree was reported down across Highway 55. A car then wrecked into it.');
INSERT INTO public.stormevents_east VALUES (777290, 201807, 22, 1515, 201807, 22, 1700, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '22-JUL-18 15:15:00', 'EST-5', '22-JUL-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'WAUGHTOWN', 1, 'E', 'WAUGHTOWN', 36.0601, -80.2396, 36.0677, -80.1948, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Flash flooding was reported on numerous roads around the US Highway 52 corridor, running through Winston Salem. This includes but not limited to the following roads: |US-421 N at S Main Street, Wake Forest University in the coliseum area, US-52 and along Peters Creek Parkway in multiple areas from Silas Creek Parkway to US-421.');
INSERT INTO public.stormevents_east VALUES (777291, 201807, 23, 400, 201807, 23, 553, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '23-JUL-18 04:00:00', 'EST-5', '23-JUL-18 05:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'KORNBOW', 0, 'WNW', 'KORNBOW', 35.0833, -78.9403, 35.0831, -78.9272, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Flash flooding was reported across portions of Fayetteville, including at a business located on Drayton Road.');
INSERT INTO public.stormevents_east VALUES (784161, 201810, 2, 1400, 201810, 2, 1400, 130037, 'PENNSYLVANIA', 42, 2018, 'October', 'Hail', 'CLE', '02-OCT-18 14:00:00', 'EST-5', '02-OCT-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'N', 'WOODCOCK', 1, 'N', 'WOODCOCK', 41.76, -80.08, 41.76, -80.08, 'A warm front associated with an area of developing low pressure over northern Illinois moved across northern Ohio and northwestern Pennsylvania late on October 1st through the morning hours of the 2nd.  This allowed strong southerly flow to bring abnormally warm and moist air into the area. Temperatures in the upper 70s to low 80s created moderate instability ahead of the front during the afternoon. Strong low-level wind shear was in place so the environment was primed for severe weather with tornadoes possible. The low pressure lifted northeast to southern Ontario by noon on the 2nd with the associated cold front moving eastward across Ohio. The main emphasis for the tornadic development was an outflow boundary from morning convection over the lake. This boundary (maybe the warm front) was oriented west to east across Ashtabula and Crawford counties. The first storms along this boundary initiated between 1:00 and 2:00 PM in Ashtabula and southern Erie County.  These thunderstorms eventually produced three tornadoes in Crawford County.  The strongest of the three struck a nursing home near Conneautville causing significant damage.  The other two tornadoes struck rural areas and resulted in mainly tree damage.', NULL);
INSERT INTO public.stormevents_east VALUES (784162, 201810, 2, 1402, 201810, 2, 1402, 130037, 'PENNSYLVANIA', 42, 2018, 'October', 'Hail', 'CLE', '02-OCT-18 14:02:00', 'EST-5', '02-OCT-18 14:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.75, NULL, NULL, NULL, 1, 'S', 'CAMBRIDGE SPGS', 1, 'S', 'CAMBRIDGE SPGS', 41.78, -80.07, 41.78, -80.07, 'A warm front associated with an area of developing low pressure over northern Illinois moved across northern Ohio and northwestern Pennsylvania late on October 1st through the morning hours of the 2nd.  This allowed strong southerly flow to bring abnormally warm and moist air into the area. Temperatures in the upper 70s to low 80s created moderate instability ahead of the front during the afternoon. Strong low-level wind shear was in place so the environment was primed for severe weather with tornadoes possible. The low pressure lifted northeast to southern Ontario by noon on the 2nd with the associated cold front moving eastward across Ohio. The main emphasis for the tornadic development was an outflow boundary from morning convection over the lake. This boundary (maybe the warm front) was oriented west to east across Ashtabula and Crawford counties. The first storms along this boundary initiated between 1:00 and 2:00 PM in Ashtabula and southern Erie County.  These thunderstorms eventually produced three tornadoes in Crawford County.  The strongest of the three struck a nursing home near Conneautville causing significant damage.  The other two tornadoes struck rural areas and resulted in mainly tree damage.', 'This report was from Route 86 between Cambridge Springs and Woodcock.');
INSERT INTO public.stormevents_east VALUES (753003, 201804, 24, 1150, 201804, 24, 1150, 125558, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MHX', '24-APR-18 11:50:00', 'EST-5', '24-APR-18 11:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 39, 'MG', NULL, NULL, 3, 'NE', 'HARKERS ISLAND', 3, 'NE', 'HARKERS ISLAND', 34.7304, -76.5078, 34.7304, -76.5078, 'A warm front lifted north through the Eastern NC waters during the morning hours of the 24th, placing the area in the favorable warm sector during the day. A line of storms developed and moved off the coast from Onslow Bay through Cape Lookout. A few thunderstorm wind gusts were observed.', 'Public weather station reported a 39 knot marine thunderstorm wind gust near Marshallberg.');
INSERT INTO public.stormevents_east VALUES (776041, 201807, 22, 1826, 201807, 22, 1826, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:26:00', 'EST-5', '22-JUL-18 18:26:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'ENE', 'CRUTCHFIELD XRDS', 1, 'ENE', 'CRUTCHFIELD XRDS', 35.8077, -79.3989, 35.8077, -79.3989, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Trees were reported down near the intersection of Clyde Underwood Road and Plainfield Church Road.');
INSERT INTO public.stormevents_east VALUES (776046, 201807, 22, 1826, 201807, 22, 1826, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:26:00', 'EST-5', '22-JUL-18 18:26:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ESE', 'RAMSEUR YORKS FLD AR', 2, 'ESE', 'RAMSEUR YORKS FLD AR', 35.7438, -79.6372, 35.7438, -79.6372, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Reed Creek Road near Jordan Road.');
INSERT INTO public.stormevents_east VALUES (776048, 201807, 22, 1830, 201807, 22, 1830, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:30:00', 'EST-5', '22-JUL-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'ARCHDALE', 1, 'SSE', 'ARCHDALE', 35.9063, -79.9634, 35.9063, -79.9634, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Shamrock Court.');
INSERT INTO public.stormevents_east VALUES (771151, 201806, 6, 1439, 201806, 6, 1439, 128489, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '06-JUN-18 14:39:00', 'EST-5', '06-JUN-18 14:39:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 3, 'SSE', 'JUPITER INLET', 3, 'SSE', 'JUPITER INLET', 26.8932, -80.0559, 26.8932, -80.0559, 'Abundant moisture and a weak stationary front across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 41 mph/36 knots at WxFlow mesonet site XJUP at Juno Beach Pier.');
INSERT INTO public.stormevents_east VALUES (771152, 201806, 6, 1441, 201806, 6, 1441, 128489, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '06-JUN-18 14:41:00', 'EST-5', '06-JUN-18 14:41:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 2, 'SSE', 'JUPITER INLET', 2, 'SSE', 'JUPITER INLET', 26.9105, -80.0655, 26.9105, -80.0655, 'Abundant moisture and a weak stationary front across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 42 mph/36 knots at WxFlow mesonet site XOAK.');
INSERT INTO public.stormevents_east VALUES (772603, 201807, 24, 700, 201807, 25, 700, 127490, 'NORTH CAROLINA', 37, 2018, 'July', 'Heavy Rain', 'RNK', '24-JUL-18 07:00:00', 'EST-5', '25-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'ENE', 'EDEN', 2, 'ENE', 'EDEN', 36.5127, -79.7117, 36.5127, -79.7117, 'An unusually deep upper trough for July over the eastern U.S. extending all the way south to the Gulf Coast provided the setting for widespread shower and thunderstorm activity. Radar estimated rainfall of 2 to 4 inches in about 3 hours was observed across west central Rockingham County with a small area estimated at 4 to 6 inches between Intelligence and Mayodan. The annual recurrence interval of the heaviest rain approached 200-year (.005 annual exceedance probability) in a 3-hour period per NOAA Atlas 14.', 'A CoCoRaHS station at Eden 2.3 ENE measured 3.84 inches for the 24-hours ending 7 AM on July 25th.');
INSERT INTO public.stormevents_east VALUES (764148, 201807, 29, 700, 201807, 29, 700, 127482, 'WEST VIRGINIA', 54, 2018, 'July', 'Heavy Rain', 'RNK', '29-JUL-18 07:00:00', 'EST-5', '29-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'NNW', 'LILLY GROVE', 0, 'NNW', 'LILLY GROVE', 37.3854, -81.0824, 37.3854, -81.0824, 'A nearly stationary cluster of thunderstorms centered between Princeton and Spanishburg dropped rainfall amounts of 4 to 6 inches. Most of the rain fell within about a three-hour period from 830 to 1130 PM.', 'The Princeton COOP measured 5.78 inches for the 24 hours ending at 7 AM on July 30th which was an all-time daily rainfall record at this station. The old record was 5.00 inches on January 22, 1906.  Precipitation records exist from 1900-1914 and 1940 to the present at the site. Per NOAA Atlas 14 this was approximately a 500-year (.002 annual exceedance probability) recurrence interval for a 24-hour period, although most of the rain fell over a much shorter duration, roughly 3 to 5 hours.');
INSERT INTO public.stormevents_east VALUES (770927, 201806, 12, 1113, 201806, 12, 1126, 128498, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'MFL', '12-JUN-18 11:13:00', 'EST-5', '12-JUN-18 11:26:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', NULL, NULL, NULL, NULL, 7, 'ESE', 'PORT OF PALM BEACH', 7, 'ESE', 'PORT OF PALM BEACH', 26.7, -79.97, 26.7, -79.97, 'Showers and storms across the local Atlantic moving into the east coast during the late morning and early afternoon hours, producing a waterspout offshore Palm Beach County.', 'The sheriff at Palm Beach International Airport reported 2 waterspouts in the Atlantic a short distance east of the airport at 1213 pm EDT/1113 am EST. The waterspouts dissipated around 1226 pm EDT/1113 am EST.');
INSERT INTO public.stormevents_east VALUES (770929, 201806, 12, 1319, 201806, 12, 1319, 128499, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MFL', '12-JUN-18 13:19:00', 'EST-5', '12-JUN-18 13:19:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'MG', NULL, NULL, 4, 'NE', 'LOXAHATCHEE', 4, 'NE', 'LOXAHATCHEE', 26.7331, -80.3079, 26.7331, -80.3079, 'Showers and storms developed along the Atlantic seabreeze as it moved inland during the early afternoon hours. A storm over Palm Beach County produced severe wind gusts and minor damage.', 'Trained spotter reported his home weather station recorded a 58 mph wind gust. Several small trees were downed in the area, in addition to damage to fences.');
INSERT INTO public.stormevents_east VALUES (771186, 201806, 13, 1310, 201806, 13, 1310, 128501, 'FLORIDA', 12, 2018, 'June', 'Tornado', 'MFL', '13-JUN-18 13:10:00', 'EST-5', '13-JUN-18 13:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'W', 'CANAL PT', 1, 'W', 'CANAL PT', 26.8496, -80.6396, 26.8496, -80.6396, 'Deep tropical moisture lead to the development of showers and storms across South Florida during the afternoon hours. A boundary collision near Lake Okeechobee lead to the development of a brief landspout in an open field.', 'Multiple reports and photos received, including from trained spotters, of landspout tornado in an open field about 5 miles northeast of Pahokee Airport, or near Canal Point. No damage observed.');
INSERT INTO public.stormevents_east VALUES (771961, 201807, 4, 939, 201807, 4, 939, 128712, 'FLORIDA', 12, 2018, 'July', 'Lightning', 'JAX', '04-JUL-18 09:39:00', 'EST-5', '04-JUL-18 09:39:00', 0, 0, 0, 0, '0.20K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'NE', 'GOODBYS', 1, 'NE', 'GOODBYS', 30.21, -81.61, 30.21, -81.61, 'A sea breeze thunderstorm and its lightning strike struck a tree.', 'Lightning struck a tree at the Woodlake Apartments off of San Jose Blvd. The cost of damage was unknown, but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (772157, 201807, 16, 1406, 201807, 16, 1406, 128752, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '16-JUL-18 14:06:00', 'EST-5', '16-JUL-18 14:06:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'An isolated thunderstorm produced gusty winds due to an unstable atmosphere.', 'A wind gust in excess of 30 knots was reported at Key Bridge.');
INSERT INTO public.stormevents_east VALUES (772181, 201807, 23, 1210, 201807, 23, 1210, 128755, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '23-JUL-18 12:10:00', 'EST-5', '23-JUL-18 12:10:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 1, 'SE', 'GREENBERRY POINT (GBY)', 1, 'SE', 'GREENBERRY POINT (GBY)', 38.96, -76.45, 38.96, -76.45, 'A cutoff low from the jet stream remained just to our west on the 23rd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust in excess of 30 knots was reported at Annapolis Buoy.');
INSERT INTO public.stormevents_east VALUES (774775, 201807, 17, 1655, 201807, 17, 1655, 129269, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '17-JUL-18 16:55:00', 'EST-5', '17-JUL-18 16:55:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'SSE', 'PLEASANT GROVE', 4, 'SSE', 'PLEASANT GROVE', 36.1466, -79.3158, 36.1466, -79.3158, 'A slow moving cold front lagged over West Virginia and Virginia through late afternoon, with a prefrontal trough over central NC. Scattered clusters of storms developed during the mid afternoon, with a couple becoming severe and producing wind damage, along with one producing flash flooding.', 'One tree was reported down at Dickey Mill Road and Barnett Road.');
INSERT INTO public.stormevents_east VALUES (774776, 201807, 17, 1705, 201807, 17, 1705, 129269, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '17-JUL-18 17:05:00', 'EST-5', '17-JUL-18 17:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'MEBANE', 1, 'NW', 'MEBANE', 36.111, -79.2996, 36.111, -79.2996, 'A slow moving cold front lagged over West Virginia and Virginia through late afternoon, with a prefrontal trough over central NC. Scattered clusters of storms developed during the mid afternoon, with a couple becoming severe and producing wind damage, along with one producing flash flooding.', 'One tree was reported down on Mebane Rogers Road.');
INSERT INTO public.stormevents_east VALUES (774777, 201807, 17, 1705, 201807, 17, 1705, 129269, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '17-JUL-18 17:05:00', 'EST-5', '17-JUL-18 17:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NE', 'HAW RIVER', 2, 'NE', 'HAW RIVER', 36.1176, -79.352, 36.1176, -79.352, 'A slow moving cold front lagged over West Virginia and Virginia through late afternoon, with a prefrontal trough over central NC. Scattered clusters of storms developed during the mid afternoon, with a couple becoming severe and producing wind damage, along with one producing flash flooding.', 'One tree was reported down on Highway 49 at Green Level Church Road.');
INSERT INTO public.stormevents_east VALUES (774778, 201807, 17, 1952, 201807, 17, 1952, 129269, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '17-JUL-18 19:52:00', 'EST-5', '17-JUL-18 19:52:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NE', 'DUNN', 3, 'NE', 'DUNN', 35.3477, -78.5788, 35.3477, -78.5788, 'A slow moving cold front lagged over West Virginia and Virginia through late afternoon, with a prefrontal trough over central NC. Scattered clusters of storms developed during the mid afternoon, with a couple becoming severe and producing wind damage, along with one producing flash flooding.', 'A couple of trees were reported down in the 3800 block of U.S. 301.');
INSERT INTO public.stormevents_east VALUES (774782, 201807, 17, 2043, 201807, 17, 2145, 129269, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '17-JUL-18 20:43:00', 'EST-5', '17-JUL-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'LILLINGTON', 1, 'ENE', 'LILLINGTON', 35.4, -78.81, 35.404, -78.8102, 'A slow moving cold front lagged over West Virginia and Virginia through late afternoon, with a prefrontal trough over central NC. Scattered clusters of storms developed during the mid afternoon, with a couple becoming severe and producing wind damage, along with one producing flash flooding.', 'Flooding was reported on South Main Street and East Duncan Street.');
INSERT INTO public.stormevents_east VALUES (774484, 201807, 11, 1750, 201807, 11, 1750, 129237, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '11-JUL-18 17:50:00', 'EST-5', '11-JUL-18 17:50:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'N', 'ONTARIO', 2, 'N', 'ONTARIO', 37.0102, -78.4843, 37.0102, -78.4843, 'A cold front moved into a moisture-rich and hot Summertime air mass and triggered showers and storms. A couple of these storms increased to severe levels, producing damaging winds and large hail.', 'Thunderstorm winds blew one tree down along Old Kings Highway. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774489, 201807, 11, 1808, 201807, 11, 1808, 129237, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '11-JUL-18 18:08:00', 'EST-5', '11-JUL-18 18:08:00', 0, 0, 0, 0, '1.50K', NULL, 'Public', 50, 'EG', NULL, NULL, 2, 'ESE', 'MOSSINGFORD', 2, 'ESE', 'MOSSINGFORD', 36.96, -78.6, 36.96, -78.59, 'A cold front moved into a moisture-rich and hot Summertime air mass and triggered showers and storms. A couple of these storms increased to severe levels, producing damaging winds and large hail.', 'Thunderstorm winds blew down one tree and also large limbs. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774491, 201807, 11, 1808, 201807, 11, 1808, 129237, 'VIRGINIA', 51, 2018, 'July', 'Hail', 'RNK', '11-JUL-18 18:08:00', 'EST-5', '11-JUL-18 18:08:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 1, 'SSE', 'DRAKES BRANCH', 1, 'SSE', 'DRAKES BRANCH', 36.98, -78.59, 36.98, -78.59, 'A cold front moved into a moisture-rich and hot Summertime air mass and triggered showers and storms. A couple of these storms increased to severe levels, producing damaging winds and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (774494, 201807, 11, 1825, 201807, 11, 1825, 129237, 'VIRGINIA', 51, 2018, 'July', 'Hail', 'RNK', '11-JUL-18 18:25:00', 'EST-5', '11-JUL-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 0, 'N', 'SAXE', 0, 'N', 'SAXE', 36.93, -78.67, 36.93, -78.67, 'A cold front moved into a moisture-rich and hot Summertime air mass and triggered showers and storms. A couple of these storms increased to severe levels, producing damaging winds and large hail.', NULL);
INSERT INTO public.stormevents_east VALUES (774701, 201807, 23, 1817, 201807, 23, 1817, 129293, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '23-JUL-18 18:17:00', 'EST-5', '23-JUL-18 18:17:00', 0, 0, 0, 0, '0.50K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ESE', 'REDWOOD', 1, 'ESE', 'REDWOOD', 37.0182, -79.8191, 37.0182, -79.8191, 'Showers and thunderstorms developed within an unstable air mass associated with an area of low pressure that was positioned overhead. One of these storms increased to severe levels and produced winds that downed two trees in Franklin County.', 'Thunderstorm winds blew a tree down near the intersection of Redwood Road and Old Franklin Turnpike. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (770123, 201807, 31, 4, 201807, 31, 304, 128374, 'VIRGINIA', 51, 2018, 'July', 'Flash Flood', 'RNK', '31-JUL-18 00:04:00', 'EST-5', '31-JUL-18 03:04:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'SW', 'PHILPOTT', 3, 'SSW', 'PHILPOTT', 36.7497, -80.0269, 36.7459, -80.0262, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 1 to 3 inches across parts of Patrick, Franklin and Henry counties most of which fell in about a 3-hour period.', 'Blackberry Creek flooded portions of Route 698 west of Bassett.');
INSERT INTO public.stormevents_east VALUES (783427, 201805, 15, 1618, 201805, 15, 1618, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:18:00', 'EST-5', '15-MAY-18 16:18:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 2, 'NE', 'ORANGE', 2, 'NE', 'ORANGE', 41.29, -73.01, 41.29, -73.01, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A Large tree down at the Racebrook Country Club.');
INSERT INTO public.stormevents_east VALUES (774673, 201807, 24, 252, 201807, 24, 400, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 02:52:00', 'EST-5', '24-JUL-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'ALESIA', 2, 'NE', 'ALESIA', 39.6944, -76.8061, 39.6944, -76.8058, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Roller Road washed out near Lineboro.');
INSERT INTO public.stormevents_east VALUES (774685, 201807, 24, 848, 201807, 24, 1000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 08:48:00', 'EST-5', '24-JUL-18 10:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'ST DENIS', 1, 'S', 'ST DENIS', 39.2122, -76.7026, 39.2109, -76.7023, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Furnace Avenue closed between Race Road and the county line due to flooding.');
INSERT INTO public.stormevents_east VALUES (774855, 201807, 25, 1750, 201807, 25, 2000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 17:50:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'WARFIELDSBURG', 1, 'SSW', 'WARFIELDSBURG', 39.5163, -77.0389, 39.5154, -77.039, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Swift water rescue required on Maryland Route 27 near Morgan Run and Nicodemus Road.');
INSERT INTO public.stormevents_east VALUES (774869, 201807, 25, 1759, 201807, 25, 2000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:59:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'DODGE PARK', 0, 'NW', 'PALMER PARK', 38.9251, -76.8751, 38.9245, -76.8744, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The ramp from eastbound Maryland Route 202 to Route 704 was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (754509, 201805, 14, 1715, 201805, 14, 1715, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:15:00', 'EST-5', '14-MAY-18 17:15:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WNW', 'YORKSHIRE', 1, 'WNW', 'YORKSHIRE', 38.79, -77.45, 38.79, -77.45, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A tree was down.');
INSERT INTO public.stormevents_east VALUES (758805, 201805, 22, 1620, 201805, 22, 1800, 126456, 'DISTRICT OF COLUMBIA', 11, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 16:20:00', 'EST-5', '22-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'LINCOLN MEMORIAL', 1, 'NW', 'US CAPITOL', 38.8925, -77.0363, 38.8925, -77.0345, 'Afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Street flooding on Constitution Avenue in Northwest DC near the Washington Monument.');
INSERT INTO public.stormevents_east VALUES (745937, 201805, 15, 941, 201805, 15, 941, 124217, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Waterspout', 'MLB', '15-MAY-18 09:41:00', 'EST-5', '15-MAY-18 09:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', NULL, NULL, NULL, NULL, 14, 'N', 'PLAYALINDA BEACH', 14, 'N', 'PLAYALINDA BEACH', 28.7464, -80.7439, 28.7464, -80.7439, 'The interaction of an upper level cutoff low pressure over the eastern Gulf of Mexico, and a strong Atlantic Ridge resulted in the formation of showers and thunderstorms across east central Florida. Daytime heating and plenty of low-level moisture helped to initiate numerous showers and thunderstorms across east central Florida. A strong thunderstorm produced a waterspout within Mosquito Lagoon in Brevard County. Other strong storms produced strong winds along the Indian River and St. Lucie County coastline.', 'Meteorologists from the 45th Weather Squadron at Cape Canaveral relayed a report of a waterspout over Mosquito Lagoon, just east of Haulover Canal.');
INSERT INTO public.stormevents_east VALUES (776456, 201807, 21, 2152, 201807, 22, 349, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 21:52:00', 'EST-5', '22-JUL-18 03:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'ELKINS', 1, 'S', 'ELKINS', 38.9713, -77.2704, 38.9713, -77.2695, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'The stream gage on Difficult Run near Great Falls exceeded the flood stage of 11 feet during the indicated period. The peak level of 12.80 feet occurred at midnight EST on July 22nd.');
INSERT INTO public.stormevents_east VALUES (776186, 201807, 21, 2100, 201807, 21, 2300, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 21:00:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'HILL TOP', 1, 'SW', 'DENTSVILLE', 38.5036, -77.1142, 38.4718, -76.9071, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'Dozens of roads were flooded across the county due to torrential rainfall.');
INSERT INTO public.stormevents_east VALUES (774862, 201807, 25, 1716, 201807, 25, 1900, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:16:00', 'EST-5', '25-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'WESTMINSTER ARPT', 0, 'NNE', 'WESTMINSTER ARPT', 39.6045, -76.9988, 39.6046, -76.9982, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Maryland Route 97 flooded and closed near the Carroll County Airport.');
INSERT INTO public.stormevents_east VALUES (759833, 201805, 28, 1440, 201805, 28, 1440, 126737, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '28-MAY-18 14:40:00', 'EST-5', '28-MAY-18 14:40:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'DRYDEN', 1, 'S', 'DRYDEN', 42.46, -76.3, 42.46, -76.3, 'A weak wave along a stationary front produced a few severe thunderstorms in central NY the afternoon of the 28th.', 'Thunderstorm winds blew numerous trees down.');
INSERT INTO public.stormevents_east VALUES (783529, 201805, 15, 1611, 201805, 15, 1611, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:11:00', 'EST-5', '15-MAY-18 16:11:00', 0, 0, 0, 0, '5.00K', '0.00K', 'COOP Observer', 61, 'EG', NULL, NULL, 1, 'N', 'NORTH ARLINGTON', 1, 'N', 'NORTH ARLINGTON', 40.79, -74.13, 40.79, -74.13, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Numerous trees down in North Arlington.');
INSERT INTO public.stormevents_east VALUES (783530, 201805, 15, 1605, 201805, 15, 1605, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:05:00', 'EST-5', '15-MAY-18 16:05:00', 1, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'ENE', 'WESTWOOD', 1, 'ENE', 'WESTWOOD', 40.99, -74.06, 40.99, -74.06, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree fell and injured a person on intersection of Hickory Street and Willow Street.');
INSERT INTO public.stormevents_east VALUES (783531, 201805, 15, 1615, 201805, 15, 1615, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:15:00', 'EST-5', '15-MAY-18 16:15:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 0, 'N', 'EAST NEWARK', 0, 'N', 'EAST NEWARK', 40.75, -74.15, 40.75, -74.15, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Fallen tree limb resulted in one injury in West Hudson Park.');
INSERT INTO public.stormevents_east VALUES (783532, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 1, 'NE', 'PROSPECT PARK', 1, 'NE', 'PROSPECT PARK', 40.96, -74.16, 40.96, -74.16, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Wires down on Lafayette Avenue, with partial road closure.');
INSERT INTO public.stormevents_east VALUES (783533, 201805, 15, 1620, 201805, 15, 1620, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:20:00', 'EST-5', '15-MAY-18 16:20:00', 1, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'E', 'CRANFORD', 1, 'E', 'CRANFORD', 40.67, -74.31, 40.67, -74.31, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree limbs fell and injured a 14 year old boy in Nomahegan Park.');
INSERT INTO public.stormevents_east VALUES (783534, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 1, 'N', 'GLEN ROCK', 1, 'N', 'GLEN ROCK', 40.96, -74.13, 40.96, -74.13, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Trees and wires down across Stonefield Avenue near Harristown Road.  Power outage in area.');
INSERT INTO public.stormevents_east VALUES (783535, 201805, 15, 1605, 201805, 15, 1605, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:05:00', 'EST-5', '15-MAY-18 16:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'WSW', 'PALISADE', 1, 'WSW', 'PALISADE', 40.96, -74, 40.96, -74, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Whitman Street, large tree branch, 12 inches in diameter down.');
INSERT INTO public.stormevents_east VALUES (766281, 201806, 3, 1724, 201806, 3, 1724, 127794, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '03-JUN-18 17:24:00', 'EST-5', '03-JUN-18 17:24:00', 1, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'NE', 'ARREDONDA', 1, 'NE', 'ARREDONDA', 29.61, -82.41, 29.61, -82.41, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'A male was struck by lightning with only minor injuries. The time of the strike was estimated.');
INSERT INTO public.stormevents_east VALUES (776801, 201807, 28, 1330, 201807, 28, 1330, 129696, 'NORTH CAROLINA', 37, 2018, 'July', 'Lightning', 'RAH', '28-JUL-18 13:30:00', 'EST-5', '28-JUL-18 13:30:00', 1, 0, 1, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 3, 'SW', 'KNIGHTDALE', 3, 'SW', 'KNIGHTDALE', 35.75, -78.52, 35.75, -78.52, 'A quasi-stationary front, bisecting central NC, provided a focus point for scattered to numerous showers and thunderstorms. Thanks to a moist and unstable airmass, a few of these storms breached the severe limit, resulting in isolated wind damage, and localized flash flooding.', 'A 41 year old male was struck by lightning and was taken to the hospital to be treated for his injuries.   The victim subsequently passed away from his injuries.');
INSERT INTO public.stormevents_east VALUES (783423, 201805, 15, 1615, 201805, 15, 1615, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:15:00', 'EST-5', '15-MAY-18 16:15:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'SW', 'SILVERMINE', 1, 'SW', 'SILVERMINE', 41.1427, -73.4645, 41.1427, -73.4645, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree down on power lines at the intersection of Carter Street and Buttery Road.');
INSERT INTO public.stormevents_east VALUES (783441, 201805, 15, 1545, 201805, 15, 1545, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 0, 'WSW', 'BROOK FIELD CENTER', 0, 'WSW', 'BROOK FIELD CENTER', 41.467, -73.3875, 41.467, -73.3875, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Significant tree damage on Route 7 at the Exit 12 Interchange with approximately a 1/4 mile wide swath across the highway to Brookfield Center.');
INSERT INTO public.stormevents_east VALUES (783525, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 56, 'MG', NULL, NULL, 3, 'SSW', 'NORTH ARLINGTON', 3, 'SSW', 'NORTH ARLINGTON', 40.7371, -74.1503, 40.7371, -74.1503, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Red Bull Arena (100 ft. elevation) a 65 mph gust reported.');
INSERT INTO public.stormevents_east VALUES (759821, 201805, 15, 1420, 201805, 15, 1440, 126736, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:20:00', 'EST-5', '15-MAY-18 14:40:00', 0, 0, 0, 0, '100.00K', '0.00K', 'NWS Storm Survey', 83, 'EG', NULL, NULL, 1, 'WNW', 'LAVA', 2, 'NE', 'MERRIEWOLD', 41.6263, -75.0437, 41.5849, -74.6784, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'A powerful line of thunderstorms blasted the Narrowsburg, Tusten, Yulan and Forestburgh areas blowing down numerous trees. There were several |locations with widespread blow downs of mainly pine and spruce |trees. There were also many other locations with several trees |blown down and/or snapped. Most of the structural damage was to |trees falling on homes. There was an estimated 20 homes at least |that sustained damage from falling trees. Power was out through a |widespread area with numerous wires down and power poles snapped.');
INSERT INTO public.stormevents_east VALUES (759831, 201805, 28, 1400, 201805, 28, 1400, 126737, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '28-MAY-18 14:00:00', 'EST-5', '28-MAY-18 14:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'DRYDEN', 1, 'N', 'DRYDEN', 42.49, -76.3, 42.49, -76.3, 'A weak wave along a stationary front produced a few severe thunderstorms in central NY the afternoon of the 28th.', 'Thunderstorm winds blew numerous trees down.');
INSERT INTO public.stormevents_east VALUES (759822, 201805, 15, 1420, 201805, 15, 1420, 126736, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:20:00', 'EST-5', '15-MAY-18 14:20:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NE', 'CALLICOON CENTER', 1, 'NE', 'CALLICOON CENTER', 41.84, -74.95, 41.84, -74.95, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew numerous trees down.');
INSERT INTO public.stormevents_east VALUES (759832, 201805, 28, 1416, 201805, 28, 1416, 126737, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '28-MAY-18 14:16:00', 'EST-5', '28-MAY-18 14:16:00', 0, 0, 0, 0, '5.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'HARFORD', 1, 'W', 'HARFORD', 42.43, -76.25, 42.43, -76.25, 'A weak wave along a stationary front produced a few severe thunderstorms in central NY the afternoon of the 28th.', 'Thunderstorm winds blew trees down.');
