INSERT INTO public.stormevents_east VALUES (759835, 201805, 28, 1505, 201805, 28, 1505, 126737, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'BGM', '28-MAY-18 15:05:00', 'EST-5', '28-MAY-18 15:05:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 3, 'SE', 'WEST NEWARK', 3, 'SE', 'WEST NEWARK', 42.22, -76.19, 42.22, -76.19, 'A weak wave along a stationary front produced a few severe thunderstorms in central NY the afternoon of the 28th.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (761171, 201805, 15, 1130, 201805, 15, 1130, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:30:00', 'EST-5', '15-MAY-18 11:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'N', 'MIDDLE RUN', 1, 'N', 'MIDDLE RUN', 41.05, -79.32, 41.05, -79.32, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'National Weather Service Employee reported trees down at Champion Road and Route 66.');
INSERT INTO public.stormevents_east VALUES (761172, 201805, 15, 1130, 201805, 15, 1130, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 11:30:00', 'EST-5', '15-MAY-18 11:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 3, 'WSW', 'SHANNONDALE', 3, 'WSW', 'SHANNONDALE', 41.07, -79.28, 41.07, -79.28, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State official reported trees down in Redbank Township.');
INSERT INTO public.stormevents_east VALUES (761173, 201805, 15, 1215, 201805, 15, 1215, 127000, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '15-MAY-18 12:15:00', 'EST-5', '15-MAY-18 12:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SSE', 'MARION CENTER', 1, 'SSE', 'MARION CENTER', 40.7605, -79.0457, 40.7605, -79.0457, 'Shortwave passage along a sagging boundary resulted in showers and thunderstorms across the region on the 15th. With plenty of instability and unidirectional shear, the primary threat was damaging wind although there were several hail reports as well.', 'State official reported utility lines down along Pierce Hollow Road.');
