INSERT INTO public.stormevents_east VALUES (754640, 201805, 12, 2139, 201805, 12, 2139, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 21:39:00', 'EST-5', '12-MAY-18 21:39:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'POINT LOOKOUT (PTL)', 0, 'N', 'POINT LOOKOUT (PTL)', 38.04, -76.32, 38.04, -76.32, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'A wind gust in excess of 30 knots was reported at Point Lookout.');
INSERT INTO public.stormevents_east VALUES (754647, 201805, 12, 2150, 201805, 12, 2215, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 21:50:00', 'EST-5', '12-MAY-18 22:15:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 37.98, -75.86, 37.98, -75.86, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'A wind gust in excess of 30 knots was reported at the Crisfield Fire Department.');
INSERT INTO public.stormevents_east VALUES (754972, 201805, 14, 1903, 201805, 14, 1903, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:03:00', 'EST-5', '14-MAY-18 19:03:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'MG', NULL, NULL, 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 38.29, -76.41, 38.29, -76.41, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 34 knot was reported at Patuxent River (KNHK).');
INSERT INTO public.stormevents_east VALUES (754965, 201805, 14, 1906, 201805, 14, 1912, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:06:00', 'EST-5', '14-MAY-18 19:12:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 41, 'MG', NULL, NULL, 0, 'N', 'LEWISETTA MD (LWTV2)', 0, 'N', 'LEWISETTA MD (LWTV2)', 38, -76.47, 38, -76.47, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts of 37 to 41 knots were reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (754966, 201805, 14, 1906, 201805, 14, 1912, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:06:00', 'EST-5', '14-MAY-18 19:12:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'LEWISETTA (LWS)', 0, 'N', 'LEWISETTA (LWS)', 38, -76.47, 38, -76.47, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts of 37 to 41 knots were reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (754967, 201805, 14, 1912, 201805, 14, 1912, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:12:00', 'EST-5', '14-MAY-18 19:12:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 42, 'MG', NULL, NULL, 0, 'N', 'ST INIGOES (KNUI)', 0, 'N', 'ST INIGOES (KNUI)', 38.13, -76.42, 38.13, -76.42, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 42 knots was reported at St. Inigoes.');
INSERT INTO public.stormevents_east VALUES (754971, 201805, 14, 1912, 201805, 14, 1930, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:12:00', 'EST-5', '14-MAY-18 19:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 40, 'MG', NULL, NULL, 3, 'S', 'MID BAY BUOY', 3, 'S', 'MID BAY BUOY', 38.432, -76.387, 38.432, -76.387, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts of 38 to 40 knots were reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (764206, 201807, 30, 700, 201807, 31, 700, 127486, 'NORTH CAROLINA', 37, 2018, 'July', 'Heavy Rain', 'RNK', '30-JUL-18 07:00:00', 'EST-5', '31-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 3, 'S', 'BUCK', 3, 'S', 'BUCK', 36.1308, -81.2276, 36.1308, -81.2276, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 2 to 4 inches across parts of northwest Wilkes, southeast Alleghany, western Surry, and eastern Yadkin counties, most of which fell in about a 3-hour period during the late evening hours of July 30th.', 'The W. Kerr Scott Reservoir COOP station (WLKN7) measured 2.98 inches for the 24-hours ending at 7 AM on the 31st. This was the highest amount at this station for July 31st and 2nd highest for any July day, behind the 3.33��� that fell on July 16, 1978. Station records began in July 1965.');
INSERT INTO public.stormevents_east VALUES (770068, 201807, 31, 0, 201807, 31, 300, 127486, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RNK', '31-JUL-18 00:00:00', 'EST-5', '31-JUL-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'JOYNES', 2, 'ENE', 'TRAPHILL', 36.3603, -81.0707, 36.3563, -80.9994, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 2 to 4 inches across parts of northwest Wilkes, southeast Alleghany, western Surry, and eastern Yadkin counties, most of which fell in about a 3-hour period during the late evening hours of July 30th.', 'There were several reports of flash flooding and flooding in western Wilkes County. The East Prong of the Roaring River flooded Twin Locust and Grissel Trail Roads with 5 to 6 feet of water flowing across them. Flooding was also reported along Little Sandy Creek which flooded Sandy Creek Road.');
INSERT INTO public.stormevents_east VALUES (775678, 201807, 22, 1408, 201807, 22, 1408, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 14:08:00', 'EST-5', '22-JUL-18 14:08:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'SALEM', 1, 'SE', 'SALEM', 36.1135, -77.8634, 36.1135, -77.8634, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Swift Creek School Road.');
INSERT INTO public.stormevents_east VALUES (775679, 201807, 22, 1415, 201807, 22, 1415, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 14:15:00', 'EST-5', '22-JUL-18 14:15:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 2, 'ENE', '(INT)WINSTON-SALEM A', 2, 'ENE', '(INT)WINSTON-SALEM A', 36.1408, -80.1908, 36.1408, -80.1908, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Trees were reported down on power lines near Highway 311.');
INSERT INTO public.stormevents_east VALUES (753178, 201805, 3, 1801, 201805, 3, 1801, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 18:01:00', 'EST-5', '03-MAY-18 18:01:00', 0, 0, 0, 0, '5.00K', NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'QUARRY HGTS', 0, 'N', 'QUARRY HGTS', 41.07, -73.77, 41.07, -73.77, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'Numerous trees were reported down around town.');
INSERT INTO public.stormevents_east VALUES (775680, 201807, 22, 1415, 201807, 22, 1415, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 14:15:00', 'EST-5', '22-JUL-18 14:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SSW', 'HICKORY', 2, 'SSW', 'HICKORY', 36.1085, -77.8128, 36.1085, -77.8128, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Hickory Road.');
INSERT INTO public.stormevents_east VALUES (739973, 201804, 15, 755, 201804, 15, 755, 123407, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'TAE', '15-APR-18 07:55:00', 'EST-5', '15-APR-18 07:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'WACISSA', 1, 'N', 'WACISSA', 30.36, -83.99, 30.36, -83.99, 'A line of strong to severe thunderstorms associated with a cold front moved across the area during the morning hours of April 15th.  A strong low level jet enhanced low level shear across the area, and a brief tornado occurred near Tyndall AFB in addition to numerous reports of trees down across northwest Florida.', 'A tree was blown down and blocked three-fourths of the road near Tram Road and Highway 59.');
INSERT INTO public.stormevents_east VALUES (739987, 201804, 15, 826, 201804, 15, 826, 123407, 'FLORIDA', 12, 2018, 'April', 'Thunderstorm Wind', 'TAE', '15-APR-18 08:26:00', 'EST-5', '15-APR-18 08:26:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 4, 'NE', 'GREENVILLE', 4, 'NE', 'GREENVILLE', 30.51, -83.59, 30.51, -83.59, 'A line of strong to severe thunderstorms associated with a cold front moved across the area during the morning hours of April 15th.  A strong low level jet enhanced low level shear across the area, and a brief tornado occurred near Tyndall AFB in addition to numerous reports of trees down across northwest Florida.', 'A power line was blown down on Lovett Road near Highway 140.');
INSERT INTO public.stormevents_east VALUES (774612, 201807, 25, 1415, 201807, 25, 1615, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 14:15:00', 'EST-5', '25-JUL-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'BRUCETOWN', 2, 'SSE', 'BRUCETOWN', 39.2257, -78.0623, 39.2282, -78.0554, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Old Charles Town Road (VA 761) flooded and closed at Opequon Creek.');
INSERT INTO public.stormevents_east VALUES (774613, 201807, 25, 1415, 201807, 25, 1615, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 14:15:00', 'EST-5', '25-JUL-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'HAYFIELD', 1, 'ESE', 'HAYFIELD', 39.2249, -78.2799, 39.2245, -78.2794, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'US Highway 50 was flooded and closed near Hayfield.');
INSERT INTO public.stormevents_east VALUES (774614, 201807, 25, 1415, 201807, 25, 1615, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 14:15:00', 'EST-5', '25-JUL-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'HAYFIELD', 1, 'ENE', 'HAYFIELD', 39.2284, -78.2948, 39.2324, -78.2906, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'South Hayfield Road flooded and closed south of US 50.');
INSERT INTO public.stormevents_east VALUES (774615, 201807, 25, 1415, 201807, 25, 1615, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 14:15:00', 'EST-5', '25-JUL-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'HAYFIELD', 2, 'ENE', 'HAYFIELD', 39.2402, -78.2621, 39.2395, -78.2614, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Indian Hollow Road (Route 679) impassible in several locations east of Hayfield Road.');
INSERT INTO public.stormevents_east VALUES (772224, 201807, 27, 1532, 201807, 27, 1537, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 15:32:00', 'EST-5', '27-JUL-18 15:37:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'EG', NULL, NULL, 0, 'N', 'KENT ISLAND (KNT)', 0, 'N', 'KENT ISLAND (KNT)', 38.92, -76.36, 38.92, -76.36, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts in excess of 30 knots were reported at Kent Island.');
INSERT INTO public.stormevents_east VALUES (775503, 201807, 21, 1732, 201807, 21, 1930, 128273, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 17:32:00', 'EST-5', '21-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'BRISTERSBURG', 2, 'ENE', 'BRISTERSBURG', 38.5884, -77.5951, 38.5887, -77.5943, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across the southern and western suburbs of Washington DC in the state of Virginia. Rainfall totals of 3 to 6 inches were widespread, causing fairly widespread flooding.', 'Courthouse Road flooded and closed at Town Run between Brent Town Road and Elk Run Road.');
INSERT INTO public.stormevents_east VALUES (753857, 201805, 12, 2048, 201805, 12, 2048, 125698, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '12-MAY-18 20:48:00', 'EST-5', '12-MAY-18 20:48:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'NEWPORT', 1, 'WNW', 'NEWPORT', 38.4233, -76.9207, 38.4233, -76.9207, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms became severe.', 'A tree was down on Wicomico Ridge road.');
INSERT INTO public.stormevents_east VALUES (753812, 201805, 10, 1240, 201805, 10, 1240, 125695, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '10-MAY-18 12:40:00', 'EST-5', '10-MAY-18 12:40:00', 0, 0, 0, 0, '5.00K', NULL, 'State Official', 50, 'EG', NULL, NULL, 0, 'SSW', 'LADD', 0, 'SSW', 'LADD', 38.0637, -78.9543, 38.0637, -78.9543, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to trigger a few severe thunderstorms.', 'A tree was down on Pheasant Run causing a gas line to rupture and a fire.');
INSERT INTO public.stormevents_east VALUES (781190, 201807, 21, 2136, 201807, 21, 2300, 128274, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '21-JUL-18 21:36:00', 'EST-5', '21-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BURDETTS', 1, 'N', 'BURDETTS', 39.2176, -77.3172, 39.2169, -77.3168, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'The USGS stream gage on Tenmile Creek near Boyds rapidly exceeded the 7 foot flood stage during the indicated period. The peak level of 7.77 feet occurred at 10:30pm EST. Old Baltimore Road was flooded along with nearby agricultural land.');
INSERT INTO public.stormevents_east VALUES (754526, 201805, 14, 1755, 201805, 14, 1755, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:55:00', 'EST-5', '14-MAY-18 17:55:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WNW', 'SPOTSYLVANIA', 1, 'WNW', 'SPOTSYLVANIA', 38.2042, -77.5943, 38.2042, -77.5943, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'Trees were down along Old Battlefield Road.');
INSERT INTO public.stormevents_east VALUES (732519, 201802, 24, 2355, 201802, 25, 155, 122345, 'OHIO', 39, 2018, 'February', 'Flood', 'ILN', '24-FEB-18 23:55:00', 'EST-5', '25-FEB-18 01:55:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'BOWLUSVILLE', 2, 'WNW', 'BOWLUSVILLE', 40.03, -83.83, 40.0318, -83.8358, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'A vehicle hydroplaned and went into a ditch. The water carried the vehicle downstream. The occupant was able to exit the vehicle before it was carried away.');
INSERT INTO public.stormevents_east VALUES (762863, 201806, 2, 1620, 201806, 2, 1620, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:20:00', 'EST-5', '02-JUN-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'YULEE', 1, 'W', 'YULEE', 30.63, -81.61, 30.63, -81.61, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Power lines were blown down near Harts Road in Yulee.');
INSERT INTO public.stormevents_east VALUES (762866, 201806, 2, 1630, 201806, 2, 1630, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:30:00', 'EST-5', '02-JUN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'HILLIARD', 1, 'N', 'HILLIARD', 30.69, -81.92, 30.69, -81.92, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Power lines were blown down with the city limits. County dispatch received 4 different reports of this damage. Time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (768144, 201807, 17, 1915, 201807, 17, 1915, 128089, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 19:15:00', 'EST-5', '17-JUL-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'SW', 'WOLFSVILLE', 2, 'SW', 'WOLFSVILLE', 39.5621, -77.5724, 39.5621, -77.5724, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produce severe thunderstorms.', 'A tree was down near the intersection off Pleasant Walk Road and Easterday Road.');
INSERT INTO public.stormevents_east VALUES (768152, 201807, 17, 1430, 201807, 17, 1430, 128093, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '17-JUL-18 14:30:00', 'EST-5', '17-JUL-18 14:30:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'WELLINGTON', 1, 'WNW', 'WELLINGTON', 38.7531, -77.0685, 38.7531, -77.0685, 'A cold front passed through on the 17th, and southwest winds ahead of the boundary led to an unstable atmosphere. The instability combined with the lift from the cold front to produced a severe thunderstorm.', 'A tree was down blocking the road near Whiteoaks Drive and Mason Hill Drive.');
INSERT INTO public.stormevents_east VALUES (754561, 201805, 14, 2312, 201805, 14, 2312, 125830, 'VIRGINIA', 51, 2018, 'May', 'Hail', 'LWX', '14-MAY-18 23:12:00', 'EST-5', '14-MAY-18 23:12:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 1, NULL, NULL, NULL, 2, 'SE', 'ALBIN', 2, 'SE', 'ALBIN', 39.2, -78.16, 39.2, -78.16, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Quarter sized hail was reported just south of US 11 and Route 37.');
INSERT INTO public.stormevents_east VALUES (768615, 201807, 27, 1701, 201807, 27, 1701, 128153, 'MARYLAND', 24, 2018, 'July', 'Thunderstorm Wind', 'LWX', '27-JUL-18 17:01:00', 'EST-5', '27-JUL-18 17:01:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'SSE', 'EMMORTON', 0, 'SSE', 'EMMORTON', 39.4945, -76.3171, 39.4945, -76.3171, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front became severe due to the instability and stronger winds aloft.', 'A tree was down near the intersection of Laurel Bush Road and Temple Drive.');
INSERT INTO public.stormevents_east VALUES (760256, 201807, 23, 1315, 201807, 23, 1320, 126745, 'PENNSYLVANIA', 42, 2018, 'July', 'Tornado', 'CTP', '23-JUL-18 13:15:00', 'EST-5', '23-JUL-18 13:20:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SW', 'NAUVOO', 2, 'N', 'NAUVOO', 41.5634, -77.2279, 41.5941, -77.2255, 'An EF-1 tornado was confirmed by a NWS Storm Survey to have occurred near Nauvoo in Tioga County on July 23, 2018.', 'The tornado began approximately one mile west of Nauvoo near Nauvoo Road (SR 3014) and traveled north across County Road 414 before ending near the path cut for power lines at the edge of Tioga State Forest. The tornado had a sporadic damage path mainly through wooded areas. Approximately 200 trees were felled. Minor damage was done to a barn roof of a residence on SR 3014, and large pole shed on County Road 414 (approximately 30X50 feet in size) had its roof removed. Maximum winds were estimated at 105 mph, classifying this as a strong EF1. There were no injuries or fatalities.');
INSERT INTO public.stormevents_east VALUES (786796, 201809, 18, 1236, 201809, 18, 1600, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 12:36:00', 'EST-5', '18-SEP-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'SOUTH SHREWSBURY', 2, 'ENE', 'SOUTH SHREWSBURY', 42.2829, -71.6967, 42.2857, -71.6825, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 12:36 PM EST, Floral Street in Shrewsbury was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (786830, 201809, 18, 130, 201809, 18, 330, 131482, 'PENNSYLVANIA', 42, 2018, 'September', 'Flash Flood', 'BGM', '18-SEP-18 01:30:00', 'EST-5', '18-SEP-18 03:30:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'RIDGEBURY', 0, 'W', 'RIDGEBURY', 41.9698, -76.7062, 41.9695, -76.7264, 'A warm front positioned over Northeast Pennsylvania acted as the focus for several rounds of late night and early morning thunderstorm activity in the area. A deep moist environment was prime for the production of slow moving, heavy rainfall which contributed to several areas of localized flash flooding.', 'Numerous roads and bridges were flooded. Five mobile home structures were flooded. Residents were evacuated.');
INSERT INTO public.stormevents_east VALUES (786851, 201809, 20, 1405, 201809, 20, 1405, 131525, 'FLORIDA', 12, 2018, 'September', 'Thunderstorm Wind', 'MFL', '20-SEP-18 14:05:00', 'EST-5', '20-SEP-18 14:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 43, 'EG', NULL, NULL, 5, 'SW', 'CORAL SPGS', 5, 'SW', 'CORAL SPGS', 26.229, -80.2816, 26.229, -80.2816, 'A surface trough with an upper level short wave was moving across South Florida. This allowed mid level 500mb temps to cool and convective instability to increase over the region. Scattered showers and thunderstorms developed producing gusty winds and hail in Broward County.', 'A trained spotter near the intersection of Coral Ridge Drive and Southgate Boulevard reported gusty winds enough to blow around some metal sheeting in a backyard. Radar estimates winds of 50 mph.');
INSERT INTO public.stormevents_east VALUES (786874, 201809, 26, 18, 201809, 26, 400, 131527, 'RHODE ISLAND', 44, 2018, 'September', 'Flood', 'BOX', '26-SEP-18 00:18:00', 'EST-5', '26-SEP-18 04:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'THORNTON', 1, 'SE', 'THORNTON', 41.7962, -71.4801, 41.7932, -71.4732, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Rhode Island with 3 to 5 inches observed in Providence County and Kent County. Amounts of 1 to 3 inches fell on Southern Rhode Island.', 'At 12:18 AM on Sept 26, Fletcher Road in Cranston was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786881, 201809, 26, 641, 201809, 26, 641, 131537, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Waterspout', 'MFL', '26-SEP-18 06:41:00', 'EST-5', '26-SEP-18 06:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Airplane Pilot', NULL, NULL, NULL, NULL, 7, 'SE', 'HALLANDALE BEACH', 7, 'SE', 'HALLANDALE BEACH', 25.92, -80.04, 25.92, -80.04, 'High pressure in place with a diurnal showers and convective pattern in place across South Florida. Showers developed over the Atlantic waters in the morning. A waterspout was produced offshore Miami Beach.', 'A pilot reported a waterspout off shore Miami Beach associated with a shower.');
INSERT INTO public.stormevents_east VALUES (785480, 201809, 10, 630, 201809, 10, 630, 131292, 'WEST VIRGINIA', 54, 2018, 'September', 'Heavy Rain', 'PBZ', '10-SEP-18 06:30:00', 'EST-5', '10-SEP-18 06:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'WSW', 'FIELDCREST', 1, 'WSW', 'FIELDCREST', 39.64, -79.95, 39.64, -79.95, 'Tropical Storm Gordon came ashore along the central Gulf Coast on the night of September 4th.  The tropical cyclone dissipated over Missouri by the night of September 7th. Moisture from the decaying tropical system interacted with a surface low and frontal boundary, spreading widespread heavy rainfall across the region over a 3 day period. 72 hour totals across northern West Virginia ranged from 2 inches to about 5.5 inches.Small-stream flooding was not as widespread as in areas to the north and east in Pennsylvania, with only a few issues reported in Marshall County.  However, winds of 30-35 MPH combined with the saturated ground to cause a tree to fall on a house in Cheat Lake, killing a woman who was sleeping in an upstairs bedroom.', 'A storm total report of 4.03 inches reported by the public.');
INSERT INTO public.stormevents_east VALUES (785803, 201809, 22, 1904, 201809, 22, 2204, 129881, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'RNK', '22-SEP-18 19:04:00', 'EST-5', '22-SEP-18 22:04:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'BEDFORD CITY', 4, 'NNW', 'STONE MT', 37.31, -79.54, 37.2278, -79.5968, 'A slow-moving frontal boundary along with moisture convergence along the Blue Ridge and some modest jet stream support aloft triggered numerous thunderstorms from the late afternoon through late evening hours. These slow-moving storms produced very heavy rainfall from the Blue Ridge out across several piedmont counties. Rainfall totals ranged from 3 to 5 inches with isolated higher amounts approaching 6 inches in northern Franklin and southern Bedford counties, all of it occurring generally within a few hours.', 'Water was reported flowing over Highway 122. A private bridge over the East Fork Beaverdam Creek was badly damaged from the flooded creek, shown in a video on local media.');
INSERT INTO public.stormevents_east VALUES (778463, 201808, 21, 1333, 201808, 21, 1533, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 13:33:00', 'EST-5', '21-AUG-18 15:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'ANDREWS MANOR', 0, 'E', 'ANDREWS MANOR', 38.8195, -76.8935, 38.8193, -76.894, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'High water impacted three lanes of the I-95 Outer Loop near Exit 9.');
INSERT INTO public.stormevents_east VALUES (769122, 201806, 20, 1617, 201806, 20, 1617, 128231, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '20-JUN-18 16:17:00', 'EST-5', '20-JUN-18 16:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NE', 'LAKE DISSTON', 1, 'NE', 'LAKE DISSTON', 29.3, -81.38, 29.3, -81.38, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'Quarter size hail was reported near Lake Disston.');
INSERT INTO public.stormevents_east VALUES (761232, 201805, 28, 1556, 201805, 28, 1556, 127011, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '28-MAY-18 15:56:00', 'EST-5', '28-MAY-18 15:56:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'NW', 'WORTHINGTON', 1, 'NW', 'WORTHINGTON', 40.84, -79.63, 40.84, -79.63, 'A few strong to severe storms developed across east central Ohio and northern Pennsylvania on the 28th. There were several reports of wind damage in Armstrong County, PA.', 'State official reported trees down on Worthington Slatelick Road.');
INSERT INTO public.stormevents_east VALUES (761233, 201805, 28, 1610, 201805, 28, 1610, 127011, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '28-MAY-18 16:10:00', 'EST-5', '28-MAY-18 16:10:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'WNW', 'BUFFALO CREEK', 2, 'WNW', 'BUFFALO CREEK', 40.83, -79.69, 40.83, -79.69, 'A few strong to severe storms developed across east central Ohio and northern Pennsylvania on the 28th. There were several reports of wind damage in Armstrong County, PA.', 'State official reported trees down on Ray Road.');
INSERT INTO public.stormevents_east VALUES (761234, 201805, 28, 1530, 201805, 28, 1530, 127012, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '28-MAY-18 15:30:00', 'EST-5', '28-MAY-18 15:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NW', 'STRASBURG', 2, 'NW', 'STRASBURG', 40.62, -81.55, 40.62, -81.55, 'A few strong to severe storms developed across east central Ohio and northern Pennsylvania on the 28th. There were several reports of wind damage in Armstrong County, PA.', 'Emergency manager reported trees down on Route 21 between Routes 212 and 250.');
INSERT INTO public.stormevents_east VALUES (762161, 201805, 31, 1830, 201805, 31, 2030, 124770, 'GEORGIA', 13, 2018, 'May', 'Flash Flood', 'FFC', '31-MAY-18 18:30:00', 'EST-5', '31-MAY-18 20:30:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'GRESHAMVILLE', 4, 'WNW', 'WRAYSWOOD', 33.6265, -83.3238, 33.701, -83.3905, 'With ample deep moisture persisting across the region, strong afternoon heating aided by a weak upper-level trough resulted in numerous strong thunderstorms across north Georgia with isolated reports of severe thunderstorms producing damaging wind gusts.  Heavy rainfall amounts occurred in portions of north and central Georgia, generally in the northeast Georgia mountains, and in the greater Columbus area. In these locations, rainfall amounts of 3 to 4 inches were common, with isolated higher amounts to 5 inches in the mountains, which produced isolated flash flooding and exacerbated flooding from the previous day.', 'Emergency Manager reported that five roads were washed out in the Greshamville area, northward toward Farmington.');
INSERT INTO public.stormevents_east VALUES (762158, 201805, 31, 1600, 201805, 31, 1900, 124770, 'GEORGIA', 13, 2018, 'May', 'Flash Flood', 'FFC', '31-MAY-18 16:00:00', 'EST-5', '31-MAY-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'HELEN', 1, 'W', 'HELEN', 34.6946, -83.715, 34.6983, -83.7334, 'With ample deep moisture persisting across the region, strong afternoon heating aided by a weak upper-level trough resulted in numerous strong thunderstorms across north Georgia with isolated reports of severe thunderstorms producing damaging wind gusts.  Heavy rainfall amounts occurred in portions of north and central Georgia, generally in the northeast Georgia mountains, and in the greater Columbus area. In these locations, rainfall amounts of 3 to 4 inches were common, with isolated higher amounts to 5 inches in the mountains, which produced isolated flash flooding and exacerbated flooding from the previous day.', 'Multiple reports of flooding in Helen were relayed by the Emergency Manager, including along Main Street and near Helen Tubing  and Waterpark.');
INSERT INTO public.stormevents_east VALUES (769123, 201806, 20, 1507, 201806, 20, 1507, 128231, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '20-JUN-18 15:07:00', 'EST-5', '20-JUN-18 15:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'ESE', 'WESCONNETT', 1, 'ESE', 'WESCONNETT', 30.24, -81.73, 30.24, -81.73, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'Ponding of water was reported along 103rd Street.');
INSERT INTO public.stormevents_east VALUES (745405, 201805, 15, 1554, 201805, 15, 1554, 124217, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '15-MAY-18 15:54:00', 'EST-5', '15-MAY-18 15:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 46, 'MG', NULL, NULL, 4, 'SSE', 'ST. LUCIE NUCLEAR POWER PLANT', 4, 'SSE', 'ST. LUCIE NUCLEAR POWER PLANT', 27.3, -80.22, 27.3, -80.22, 'The interaction of an upper level cutoff low pressure over the eastern Gulf of Mexico, and a strong Atlantic Ridge resulted in the formation of showers and thunderstorms across east central Florida. Daytime heating and plenty of low-level moisture helped to initiate numerous showers and thunderstorms across east central Florida. A strong thunderstorm produced a waterspout within Mosquito Lagoon in Brevard County. Other strong storms produced strong winds along the Indian River and St. Lucie County coastline.', 'A mesonet site at the St. Lucie Nuclear Power Plant - XSTL, measured a peak wind gust of 46 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (745406, 201805, 15, 1616, 201805, 15, 1616, 124217, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '15-MAY-18 16:16:00', 'EST-5', '15-MAY-18 16:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 8, 'E', 'SEBASTIAN INLET', 8, 'E', 'SEBASTIAN INLET', 27.8616, -80.4448, 27.8616, -80.4448, 'The interaction of an upper level cutoff low pressure over the eastern Gulf of Mexico, and a strong Atlantic Ridge resulted in the formation of showers and thunderstorms across east central Florida. Daytime heating and plenty of low-level moisture helped to initiate numerous showers and thunderstorms across east central Florida. A strong thunderstorm produced a waterspout within Mosquito Lagoon in Brevard County. Other strong storms produced strong winds along the Indian River and St. Lucie County coastline.', 'A mesonet site at Sebastian Inlet measured a peak wind gust of 35 knots.');
INSERT INTO public.stormevents_east VALUES (769109, 201806, 15, 1652, 201806, 15, 1652, 128227, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '15-JUN-18 16:52:00', 'EST-5', '15-JUN-18 16:52:00', 0, 0, 0, 0, '0.10K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 5, 'WSW', 'SAMPSON', 5, 'WSW', 'SAMPSON', 29.99, -81.47, 29.99, -81.47, 'SW steering flow focused a stronger west coast sea breeze across FL through the day with a merger with the east coast sea breeze near the I-95 corridor during the late afternoon and early evening. Resultant storms produced strong outflow winds which moved offshore of the local coast through early evening.', 'Lightning struck a Nursing Home Facility in World Golf Village. Significant damage was not reported. The cost of damage was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (769115, 201806, 19, 1530, 201806, 19, 1530, 128229, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '19-JUN-18 15:30:00', 'EST-5', '19-JUN-18 15:30:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 1, 'SE', 'GOODBYS', 1, 'SE', 'GOODBYS', 30.19, -81.61, 30.19, -81.61, 'Stronger SW flow and thus Gulf Coast sea breeze moved across a moist and unstable airmass. Sea breezes merged near the Highway 301 corridor with localized heavy rainfall from resultant storms.', 'A lightning strike hit a home in Mandarin. The time was based on radar. The cost of damage was unknown but it was estimated for inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (769116, 201806, 15, 1539, 201806, 15, 1539, 128229, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '15-JUN-18 15:39:00', 'EST-5', '15-JUN-18 15:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'W', 'BAYARD', 1, 'W', 'BAYARD', 30.15, -81.54, 30.15, -81.54, 'Stronger SW flow and thus Gulf Coast sea breeze moved across a moist and unstable airmass. Sea breezes merged near the Highway 301 corridor with localized heavy rainfall from resultant storms.', 'A spotter reported standing water on road side lanes near I-95, I-295 and Old St. Augustine Road.');
INSERT INTO public.stormevents_east VALUES (753447, 201805, 3, 1748, 201805, 3, 1748, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 17:48:00', 'EST-5', '03-MAY-18 17:48:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 58, 'MG', NULL, NULL, 1, 'NW', 'SCARBOROUGH', 1, 'NW', 'SCARBOROUGH', 41.14, -73.88, 41.14, -73.88, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'A sixty seven mile per hour gust was reported at the Tappan Zee Light mesonet location.');
INSERT INTO public.stormevents_east VALUES (769124, 201806, 20, 1430, 201806, 20, 1600, 128231, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '20-JUN-18 14:30:00', 'EST-5', '20-JUN-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'SSW', 'NEW RIVER', 2, 'SSW', 'NEW RIVER', 29.94, -82.29, 29.94, -82.29, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'A spotter measured 2.27 along County Road 235 in 1.5 hrs.');
INSERT INTO public.stormevents_east VALUES (769126, 201806, 20, 1450, 201806, 20, 1450, 128231, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '20-JUN-18 14:50:00', 'EST-5', '20-JUN-18 14:50:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 2, 'NW', 'CAMBON', 2, 'NW', 'CAMBON', 30.35, -81.82, 30.35, -81.82, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'A transformer was hit by lightning and damage. The cost of damage was unknown and it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (762868, 201806, 2, 1640, 201806, 2, 1640, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:40:00', 'EST-5', '02-JUN-18 16:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'CALLAHAN', 1, 'SW', 'CALLAHAN', 30.56, -81.83, 30.56, -81.83, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Power lines were blown down. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762869, 201806, 2, 1700, 201806, 2, 1700, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:00:00', 'EST-5', '02-JUN-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'NW', 'STARKE', 5, 'NW', 'STARKE', 30, -82.15, 30, -82.15, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A large tree limb was blown down across County Road 233 and over Orange Street near Strarke. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762870, 201806, 2, 1720, 201806, 2, 1720, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:20:00', 'EST-5', '02-JUN-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'SUNBEAM', 1, 'N', 'SUNBEAM', 30.21, -81.58, 30.21, -81.58, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Wires were blown down near Hood Road and Sunbeam Road. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762872, 201806, 2, 1725, 201806, 2, 1725, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:25:00', 'EST-5', '02-JUN-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NW', 'HIBERNIA', 1, 'NW', 'HIBERNIA', 30.08, -81.71, 30.08, -81.71, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A tree was blown down between Fleming Island Plantation Blvd and Village Square Parkway.');
INSERT INTO public.stormevents_east VALUES (775012, 201807, 6, 1544, 201807, 6, 1544, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:44:00', 'EST-5', '06-JUL-18 15:44:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'BISCOE', 2, 'WSW', 'BISCOE', 35.36, -79.83, 35.36, -79.83, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Multiple trees were reported down across the county.');
INSERT INTO public.stormevents_east VALUES (734213, 201802, 16, 830, 201802, 17, 1615, 122507, 'OHIO', 39, 2018, 'February', 'Flood', 'RLX', '16-FEB-18 08:30:00', 'EST-5', '17-FEB-18 16:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'POMEROY', 1, 'WNW', 'MIDDLEPORT', 39.0309, -82.0146, 39.003, -82.0602, 'A wave of low pressure and a surface front crossed West Virginia, producing heavy rainfall on the 16th. Generally 1 to 2 inches of rain fell on already saturated soil. This resulted in creek and stream flooding on the 16th and into the 17th. As the rain drained through the river system, smaller main stem rivers flooded. This eventually led to flooding along the the Ohio River.', 'Flooding closed a number of roads across the county, including State Routes 124, 143, 248, and 681.||The Shade River near Chester also flooded. The river rose above its bankfull level of 17 feet just before noon on the 16th, crested at about 19.4 feet around sunrise on the 17th, and returned to its banks late that afternoon.');
INSERT INTO public.stormevents_east VALUES (766265, 201806, 3, 1830, 201806, 3, 1830, 127794, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '03-JUN-18 18:30:00', 'EST-5', '03-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NE', 'ST AUGUSTINE', 1, 'NE', 'ST AUGUSTINE', 29.89, -81.31, 29.89, -81.31, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Quarter size hail was reported at Cathedral Parish School.');
INSERT INTO public.stormevents_east VALUES (774674, 201807, 24, 310, 201807, 24, 410, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 03:10:00', 'EST-5', '24-JUL-18 04:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'MILLERS', 0, 'WSW', 'MILLERS', 39.6686, -76.8571, 39.6684, -76.857, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'A portion of Millers Station Road, where it crosses Grave Run, was completely undermined and washed out due to flooding.');
INSERT INTO public.stormevents_east VALUES (774675, 201807, 24, 615, 201807, 24, 715, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 06:15:00', 'EST-5', '24-JUL-18 07:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'WOODLAWN', 0, 'ENE', 'WOODLAWN', 39.3231, -76.7227, 39.3232, -76.7224, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Flooding near the intersection of Gwynn Lake Drive and Gwynn Oak Avenue caused closure of both roads.');
INSERT INTO public.stormevents_east VALUES (762892, 201807, 16, 1940, 201807, 16, 1940, 126743, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '16-JUL-18 19:40:00', 'EST-5', '16-JUL-18 19:40:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 5, 'NE', 'TIDIOUTE', 5, 'NE', 'TIDIOUTE', 41.7317, -79.3409, 41.7317, -79.3409, 'Storm developed ahead of an approaching cold front on July 16, 2018. Neither CAPE nor shear were very impressive, but a couple of storms managed to produce wind damage across northwestern and north-central Pennsylvania.  Heavy rainfall brought flash flooding to portions of McKean and Potter Counties during the evening hours.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree across the 4700 block of Davey Hill Road.');
INSERT INTO public.stormevents_east VALUES (762894, 201807, 16, 1945, 201807, 16, 1945, 126743, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '16-JUL-18 19:45:00', 'EST-5', '16-JUL-18 19:45:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'W', 'CHANDLERS VLY', 1, 'W', 'CHANDLERS VLY', 41.88, -79.34, 41.88, -79.34, 'Storm developed ahead of an approaching cold front on July 16, 2018. Neither CAPE nor shear were very impressive, but a couple of storms managed to produce wind damage across northwestern and north-central Pennsylvania.  Heavy rainfall brought flash flooding to portions of McKean and Potter Counties during the evening hours.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down several large tree limbs in the 2400 block of Mathews Run Road.');
INSERT INTO public.stormevents_east VALUES (762895, 201807, 16, 2115, 201807, 16, 2115, 126743, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '16-JUL-18 21:15:00', 'EST-5', '16-JUL-18 21:15:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'S', 'ARNOT', 1, 'S', 'ARNOT', 41.6593, -77.1216, 41.6593, -77.1216, 'Storm developed ahead of an approaching cold front on July 16, 2018. Neither CAPE nor shear were very impressive, but a couple of storms managed to produce wind damage across northwestern and north-central Pennsylvania.  Heavy rainfall brought flash flooding to portions of McKean and Potter Counties during the evening hours.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down a tree across the 700 block of Arnot Road in Blossburg Township.');
INSERT INTO public.stormevents_east VALUES (774858, 201807, 25, 1909, 201807, 25, 2000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 19:09:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'KEMP MILL', 2, 'S', 'KEMP MILL', 39.0075, -77.0207, 39.0073, -77.0205, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Sligo Creek rapidly rose, flowing over US 29 (Colesville Road) in the area.');
INSERT INTO public.stormevents_east VALUES (774859, 201807, 25, 1912, 201807, 25, 2000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 19:12:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'CRANBERRY STATION', 1, 'ENE', 'CRANBERRY STATION', 39.5836, -76.9694, 39.5829, -76.9701, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Water rescue in the 700 block of Old Manchester Road due to overflow from Cranberry Branch.');
INSERT INTO public.stormevents_east VALUES (753461, 201805, 3, 1809, 201805, 3, 1809, 125625, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 18:09:00', 'EST-5', '03-MAY-18 18:09:00', 0, 0, 0, 0, '1.00K', NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NNW', 'HUNTING RIDGE', 1, 'NNW', 'HUNTING RIDGE', 41.1317, -73.5851, 41.1317, -73.5851, 'Severe thunderstorms moved across Fairfield County ahead of a cold front.', 'A tree was reported down on Sawmill Road.');
INSERT INTO public.stormevents_east VALUES (774860, 201807, 25, 1944, 201807, 25, 2000, 128277, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '25-JUL-18 19:44:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'MELROSE', 2, 'NNE', 'MELROSE', 39.7096, -76.891, 39.709, -76.8891, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Streams out of their banks near Hay Drive and Wentz Road. Rapidly rising water forced water over driveways with leftover debris blocking access.');
INSERT INTO public.stormevents_east VALUES (774861, 201807, 25, 1636, 201807, 25, 1800, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 16:36:00', 'EST-5', '25-JUL-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'BEALLSVILLE', 1, 'SE', 'BEALLSVILLE', 39.1715, -77.4032, 39.1709, -77.4026, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Maryland Route 28 flooded and impassable in several spots near Beallsville.');
INSERT INTO public.stormevents_east VALUES (774880, 201807, 25, 2000, 201807, 25, 2100, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 20:00:00', 'EST-5', '25-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CAMDEN', 1, 'S', 'HILLEN', 39.2876, -76.6404, 39.2898, -76.5974, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'More than ten roads flooded and closed throughout the city.');
INSERT INTO public.stormevents_east VALUES (774883, 201807, 25, 2042, 201807, 25, 2200, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 20:42:00', 'EST-5', '25-JUL-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'FOX CHAPEL', 1, 'E', 'FOX CHAPEL', 39.1987, -77.2128, 39.1982, -77.2127, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Blunt Road flooded and closed between Germantown Road and Brink Road.');
INSERT INTO public.stormevents_east VALUES (781193, 201807, 24, 2335, 201807, 25, 505, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 23:35:00', 'EST-5', '25-JUL-18 05:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'COCKEYSVILLE', 1, 'NNE', 'COCKEYSVILLE', 39.4871, -76.6449, 39.4872, -76.6445, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS gage on Beaverdam Run near Cockeysville exceeded the 9 foot flood stage during the indicated period. The peak level of 11.17 feet occurred at 2:00am EST. Beaver Run Lane was flooded. York Road was also flooded with water approaching nearby businesses. Local media reported one vehicle drove around a road closed sign and got stuck in the floodwaters on York Road. The occupant was rescued.');
INSERT INTO public.stormevents_east VALUES (781497, 201807, 25, 2311, 201807, 26, 1659, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 23:11:00', 'EST-5', '26-JUL-18 16:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RAYNOR HGTS', 2, 'W', 'RAYNOR HGTS', 39.2117, -76.7025, 39.216, -76.7007, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The stream gage on the Patapsco River near Elkridge exceeded the 16 foot flood stage during the indicated period. The peak level of 19.69 feet occurred at 12:50pm EST. Hammonds Ferry Road and Furnace Avenue were flooded.');
INSERT INTO public.stormevents_east VALUES (781521, 201807, 25, 0, 201807, 25, 354, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 00:00:00', 'EST-5', '25-JUL-18 03:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'OREGON', 1, 'NNE', 'OREGON', 39.5108, -76.6776, 39.5104, -76.6773, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Western Run at this location exceeded the 8 foot flood stage during the indicated period. The peak level of 9.06 feet occurred at 2:00am EST.  Western Run Road was flooded.');
INSERT INTO public.stormevents_east VALUES (774457, 201807, 27, 1650, 201807, 27, 1845, 128280, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '27-JUL-18 16:50:00', 'EST-5', '27-JUL-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'PARKVILLE', 1, 'N', 'PARKVILLE', 39.3891, -76.55, 39.3887, -76.5499, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Putty Hill Avenue flooded and closed near Towson.');
INSERT INTO public.stormevents_east VALUES (774462, 201807, 27, 1728, 201807, 27, 1930, 128280, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '27-JUL-18 17:28:00', 'EST-5', '27-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'IJAMSVILLE', 2, 'SW', 'IJAMSVILLE', 39.3544, -77.3525, 39.3542, -77.3516, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Ball Road flooded and closed between Tabler Road and Ijamsville Road.');
INSERT INTO public.stormevents_east VALUES (774467, 201807, 27, 1658, 201807, 27, 1900, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 16:58:00', 'EST-5', '27-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'OAKLEIGH', 1, 'WNW', 'OAKLEIGH', 39.4046, -76.5673, 39.403, -76.5661, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Flash flooding due to torrential rain was reported near the intersection of Cromwell Bridge Road and Cowpens Avenue, with road closures.');
INSERT INTO public.stormevents_east VALUES (761250, 201805, 30, 2341, 201805, 31, 200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 23:41:00', 'EST-5', '31-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'STANDARDSVILLE', 2, 'SW', 'STANDARDSVILLE', 38.2763, -78.4519, 38.2769, -78.4508, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Celt Road flooded and closed south of Stanardsville.');
INSERT INTO public.stormevents_east VALUES (761252, 201805, 30, 2341, 201805, 31, 200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 23:41:00', 'EST-5', '31-MAY-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'LYDIA', 2, 'ENE', 'LYDIA', 38.3428, -78.4694, 38.3429, -78.4689, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Bull Yearling Road flooded and closed along Bull Yearling Run.');
INSERT INTO public.stormevents_east VALUES (761255, 201805, 31, 0, 201805, 31, 100, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '31-MAY-18 00:00:00', 'EST-5', '31-MAY-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'IVY', 1, 'ENE', 'IVY', 38.0599, -78.5795, 38.0599, -78.5788, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Multiple cars stranded in at least two feet of rushing water near the intersection of West Leigh Drive and Leigh Way.');
INSERT INTO public.stormevents_east VALUES (760002, 201805, 27, 1309, 201805, 27, 1400, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 13:09:00', 'EST-5', '27-MAY-18 14:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'PERRY HALL', 2, 'SSW', 'PERRY HALL', 39.3993, -76.4852, 39.3994, -76.4846, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'A swift water rescue was conducted on Seven Courts Drive where a man was trapped in rising flood waters, clinging to a tree. The man was successfully rescued.');
INSERT INTO public.stormevents_east VALUES (760881, 201805, 27, 1756, 201805, 27, 2000, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 17:56:00', 'EST-5', '27-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'WATERLOO', 2, 'N', 'WATERLOO', 39.1945, -76.7812, 39.1943, -76.7802, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Deep Run overflowed its banks, covering Mayfield Avenue in Elkridge.');
INSERT INTO public.stormevents_east VALUES (760892, 201805, 27, 1700, 201805, 27, 1900, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 17:00:00', 'EST-5', '27-MAY-18 19:00:00', 0, 0, 0, 0, '8.60M', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'CHADWICK MANOR', 2, 'S', 'CHADWICK MANOR', 39.271, -76.7354, 39.2713, -76.7334, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Widespread flash flooding in downtown Catonsville along Frederick Road.  Roads flooded and water entering buildings. Flooding was reported in local schools along with 12 swift water rescues.');
INSERT INTO public.stormevents_east VALUES (760929, 201805, 27, 1516, 201805, 27, 1746, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:16:00', 'EST-5', '27-MAY-18 17:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'HALETHORPE', 1, 'SSE', 'HALETHORPE', 39.2405, -76.6923, 39.2402, -76.6917, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on East Branch Herbert Run at Arbutus rapidly exceeded the 7 foot flood stage during the indicated times. There were two distinct peaks during the times indicated but the higher was the second peak, of 9.21 feet at 5:20pm EST on May 27th. Water levels rapidly fell thereafter.');
INSERT INTO public.stormevents_east VALUES (760930, 201805, 27, 1549, 201805, 27, 2031, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:49:00', 'EST-5', '27-MAY-18 20:31:00', 0, 0, 0, 0, '5.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ILCHESTER', 1, 'NNW', 'ELKRIDGE', 39.2426, -76.7506, 39.2295, -76.7277, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on the Patapsco River at Patapsco Valley State Park rapidly exceeded the 15 foot flood stage during the indicated times. Widespread damage occurred within the park, with a peak level reached of 24.36 feet at 5:45pm EST on May 27th. This is preliminarily the highest value reached at this location since at least 2010.');
INSERT INTO public.stormevents_east VALUES (776020, 201807, 22, 1512, 201807, 22, 1512, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 15:12:00', 'EST-5', '22-JUL-18 15:12:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'LEWISVILLE', 2, 'SSW', 'LEWISVILLE', 36.0735, -80.4389, 36.0735, -80.4389, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Concord Church Road at Williams Road.');
INSERT INTO public.stormevents_east VALUES (760932, 201805, 27, 2005, 201805, 28, 406, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 20:05:00', 'EST-5', '28-MAY-18 04:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GUILFORD', 1, 'N', 'SAVAGE', 39.1505, -76.8331, 39.1498, -76.8308, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on the Little Patuxent River at Guilford exceeded the 11 foot flood stage during the times indicated. The peak level of 15.22 feet was observed at 10:15pm EST on May 27th, and was the 3rd highest ever recorded at this location. Vollmerhausen Road was flooded.');
INSERT INTO public.stormevents_east VALUES (758066, 201805, 15, 1945, 201805, 15, 2100, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 19:45:00', 'EST-5', '15-MAY-18 21:00:00', 0, 0, 0, 0, '1.00M', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'FT DETRICK', 0, 'SW', 'FT DETRICK', 39.4266, -77.4042, 39.4261, -77.405, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Floodwaters were more than two feet deep on North Market Street near the Frederick YMCA. Water entered buildings in the area and several parked cars were mostly submerged in water. The YMCA building itself had water enter the building with an estimated 40,000 sqft of the 95,000 sqft facility suffering water damage.');
INSERT INTO public.stormevents_east VALUES (758065, 201805, 15, 1913, 201805, 15, 2100, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 19:13:00', 'EST-5', '15-MAY-18 21:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'FREDERICK', 1, 'SE', 'FREDERICK', 39.4166, -77.4113, 39.4139, -77.4116, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Flowing water up over the curb in downtown Frederick on Market Street. Water entered several businesses on Patrick Street. One business reported water at least two feet deep.');
INSERT INTO public.stormevents_east VALUES (758077, 201805, 15, 2144, 201805, 15, 2215, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 21:44:00', 'EST-5', '15-MAY-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'AUGUSTA', 0, 'ESE', 'AUGUSTA', 39.3776, -77.6653, 39.3774, -77.6638, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'Two people were rescued from a home with floodwaters inundating it near Brownsville.');
INSERT INTO public.stormevents_east VALUES (753490, 201805, 3, 1812, 201805, 3, 1812, 125625, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 18:12:00', 'EST-5', '03-MAY-18 18:12:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'S', 'NOROTON', 1, 'S', 'NOROTON', 41.05, -73.4814, 41.05, -73.4814, 'Severe thunderstorms moved across Fairfield County ahead of a cold front.', 'A few trees were reported down around town.');
INSERT INTO public.stormevents_east VALUES (776995, 201807, 31, 2025, 201807, 31, 2244, 129726, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '31-JUL-18 20:25:00', 'EST-5', '31-JUL-18 22:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'WILSON', 2, 'NE', 'WILSON', 35.7453, -77.9253, 35.7454, -77.8988, 'Deep Gulf of Mexico moisture channeling between an amplifying trough over the mid-lower MS Valley and the western Atlantic ridge led to precipitable waters increasing to to over 2.0 over the area. Upper forcing in the form of divergence aloft, within the right entrance region of an upper level jet streak that extended down the Mid-Atlantic States, combined with a south-north ribbon of elongated vorticity shear axis centered east of the southern and central Appalachians, led to the development of scattered to numerous thunderstorms through the late afternoon and evening. The heaviest rain fell over the tri-county area of Nash-Wilson-Edgecombe counties, where training thunderstorms produced a swath of 4 to 6 inches.  This area of heavy rainfall flooded numerous roads in these counties, with at least two water rescues in Nash County.', 'Heavy rainfall of 4 to 6 inches resulted in widespread flash flooding across the city of Wilson and northern portions of the county.');
INSERT INTO public.stormevents_east VALUES (776996, 201807, 31, 2030, 201807, 31, 2244, 129726, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '31-JUL-18 20:30:00', 'EST-5', '31-JUL-18 22:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'ROCKY MT', 2, 'NNE', 'ROCKY MT', 35.9589, -77.8117, 35.9537, -77.7684, 'Deep Gulf of Mexico moisture channeling between an amplifying trough over the mid-lower MS Valley and the western Atlantic ridge led to precipitable waters increasing to to over 2.0 over the area. Upper forcing in the form of divergence aloft, within the right entrance region of an upper level jet streak that extended down the Mid-Atlantic States, combined with a south-north ribbon of elongated vorticity shear axis centered east of the southern and central Appalachians, led to the development of scattered to numerous thunderstorms through the late afternoon and evening. The heaviest rain fell over the tri-county area of Nash-Wilson-Edgecombe counties, where training thunderstorms produced a swath of 4 to 6 inches.  This area of heavy rainfall flooded numerous roads in these counties, with at least two water rescues in Nash County.', 'Numerous street closures due to flash flooding throughout the Rocky Mount city limits.');
INSERT INTO public.stormevents_east VALUES (776446, 201807, 22, 538, 201807, 23, 658, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '22-JUL-18 05:38:00', 'EST-5', '23-JUL-18 06:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'GROVE', 1, 'NE', 'LIME KILN', 39.3954, -77.3753, 39.3627, -77.4141, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'The stream gage on the Monocacy River at I-70 near Frederick exceeded the 15 foot flood stage during the period indicated. The peak level of 17.62 feet was observed at 11:15pm EST on July 22nd. Pinecliff and Rivermist parks were flooded, along with portions of Monocacy Battlefield and Buckeystown Community Park.');
INSERT INTO public.stormevents_east VALUES (778618, 201810, 2, 1651, 201810, 2, 1701, 130002, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'ILN', '02-OCT-18 16:51:00', 'EST-5', '02-OCT-18 17:01:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'NW', 'HANOVER', 2, 'NW', 'HANOVER', 40.1, -82.28, 40.1, -82.28, 'Scattered severe thunderstorms developed ahead of a cold front dropping south through the region.', 'A large limb was knocked down.');
INSERT INTO public.stormevents_east VALUES (778620, 201810, 2, 1732, 201810, 2, 1742, 130002, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'ILN', '02-OCT-18 17:32:00', 'EST-5', '02-OCT-18 17:42:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'W', 'ALEXANDRIA', 2, 'W', 'ALEXANDRIA', 40.08, -82.66, 40.08, -82.66, 'Scattered severe thunderstorms developed ahead of a cold front dropping south through the region.', 'A tree was knocked down onto the 8900 block of Jersey Mill Road.');
INSERT INTO public.stormevents_east VALUES (778622, 201810, 2, 1733, 201810, 2, 1743, 130002, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'ILN', '02-OCT-18 17:33:00', 'EST-5', '02-OCT-18 17:43:00', 0, 0, 0, 0, '1.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'ALEXANDRIA', 1, 'SE', 'ALEXANDRIA', 40.07, -82.61, 40.07, -82.61, 'Scattered severe thunderstorms developed ahead of a cold front dropping south through the region.', 'A tree was knocked down onto the 1100 block of York Road.');
INSERT INTO public.stormevents_east VALUES (778623, 201810, 2, 1733, 201810, 2, 1743, 130002, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'ILN', '02-OCT-18 17:33:00', 'EST-5', '02-OCT-18 17:43:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NE', 'ALEXANDRIA', 1, 'NE', 'ALEXANDRIA', 40.09, -82.61, 40.09, -82.61, 'Scattered severe thunderstorms developed ahead of a cold front dropping south through the region.', 'A two foot diameter limb was knocked down.');
INSERT INTO public.stormevents_east VALUES (774298, 201807, 2, 1630, 201807, 2, 1635, 129211, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'RNK', '02-JUL-18 16:30:00', 'EST-5', '02-JUL-18 16:35:00', 0, 0, 0, 0, '32.50K', NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'W', 'BLUEFIELD', 0, 'ESE', 'BLUEFIELD', 37.249, -81.2991, 37.2491, -81.2769, 'Isolated showers and storms developed with a hot and humid summer air mass across the region. One of these storms increased to severe levels and produced damaging winds near Bluefield, VA.  Another thunderstorm, while not severe, produced lightning that struck a shed in Troutdale, VA, setting it on fire causing total loss of the structure.', 'A tree fell on a house on the corner of Wesley Street and Lee Avenue while multiple trees were blown down along Tazewell Avenue. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774301, 201807, 6, 1322, 201807, 6, 1322, 129213, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 13:22:00', 'EST-5', '06-JUL-18 13:22:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'E', 'GOLD HILL', 2, 'E', 'GOLD HILL', 36.3256, -79.8945, 36.3256, -79.8945, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew two trees down. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774302, 201807, 6, 1323, 201807, 6, 1323, 129213, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 13:23:00', 'EST-5', '06-JUL-18 13:23:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SW', 'STONEVILLE', 0, 'SW', 'STONEVILLE', 36.4676, -79.9044, 36.4676, -79.9044, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew several trees down in Stoneville. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774398, 201807, 6, 1323, 201807, 6, 1323, 129213, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 13:23:00', 'EST-5', '06-JUL-18 13:23:00', 0, 0, 0, 0, '15.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WNW', 'ZIONVILLE', 1, 'WNW', 'ZIONVILLE', 36.3348, -81.743, 36.3348, -81.743, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds downed power lines in Zionville. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (742157, 201804, 3, 1710, 201804, 3, 1910, 123573, 'OHIO', 39, 2018, 'April', 'Flood', 'ILN', '03-APR-18 17:10:00', 'EST-5', '03-APR-18 19:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'BELLEFONTAINE ARPT', 2, 'NNE', 'BELLEFONTAINE', 40.401, -83.7411, 40.4003, -83.7477, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'Six inches of water was reported over Township Rd 219.');
INSERT INTO public.stormevents_east VALUES (742175, 201804, 3, 1725, 201804, 3, 1730, 123573, 'OHIO', 39, 2018, 'April', 'Hail', 'ILN', '03-APR-18 17:25:00', 'EST-5', '03-APR-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 0.88, NULL, NULL, NULL, 2, 'E', 'ARNHEIM', 2, 'E', 'ARNHEIM', 38.93, -83.79, 38.93, -83.79, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'Nickel sized hail was covering the ground at Lake Waynoka.');
INSERT INTO public.stormevents_east VALUES (742214, 201804, 15, 1720, 201804, 15, 1920, 123710, 'OHIO', 39, 2018, 'April', 'Flood', 'ILN', '15-APR-18 17:20:00', 'EST-5', '15-APR-18 19:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'GREENFIELD', 3, 'NW', 'EAST MONROE', 39.35, -83.39, 39.3866, -83.5319, 'Showers and thunderstorms which produced heavy rain, developed ahead of potent surface low.', 'High water was reported on several roads resulting in road closures throughout the county, including the town of Greenfield.');
INSERT INTO public.stormevents_east VALUES (754593, 201805, 22, 1653, 201805, 22, 1653, 125835, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '22-MAY-18 16:53:00', 'EST-5', '22-MAY-18 16:53:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'NANJEMOY ARPT', 1, 'S', 'NANJEMOY ARPT', 38.4586, -77.2507, 38.4586, -77.2507, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A tree was down at the intersection of Riverside Road and Liverpool Point Road.');
INSERT INTO public.stormevents_east VALUES (758073, 201805, 15, 2013, 201805, 15, 2100, 126423, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '15-MAY-18 20:13:00', 'EST-5', '15-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'JEFFERSON', 2, 'WSW', 'JEFFERSON', 39.356, -77.5726, 39.3576, -77.5702, 'A cold front slowly sagged southward through Pennsylvania during the afternoon hours of May 15th. A line of storms spread ahead of this front, causing a widespread 1-3 inches of rain across North Central and Northeast Maryland. The western end of this line stalled, producing 3-6 inches of rain in a relatively short period of time in Frederick and extreme southeastern Washington Counties, prompting numerous water rescues and causing somewhat significant damage. The front stalled, and the next evening (May 16th), a second round of extreme rainfall struck much of the same area, with 3-6 inches of rain observed again in Frederick and southeastern Washington Counties. Renewed flooding ensued which continued into the morning hours of May 17th.', 'US 340 Westbound flooded and closed west of Jefferson.');
INSERT INTO public.stormevents_east VALUES (754598, 201805, 27, 1438, 201805, 27, 1438, 125841, 'MARYLAND', 24, 2018, 'May', 'Thunderstorm Wind', 'LWX', '27-MAY-18 14:38:00', 'EST-5', '27-MAY-18 14:38:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'MAPLE GROVE', 1, 'S', 'MAPLE GROVE', 39.6418, -76.8708, 39.6418, -76.8708, 'A weak boundary combined with a warm and humid air mass to trigger some showers and thunderstorms. An isolated thunderstorm became severe.', 'A tree was down near the intersection of MD-30 Hanover Pike and Basler Road.');
INSERT INTO public.stormevents_east VALUES (758592, 201805, 17, 815, 201805, 17, 1308, 126450, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 08:15:00', 'EST-5', '17-MAY-18 13:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'WATERFORD', 1, 'NW', 'WATERFORD', 39.1905, -77.6158, 39.1907, -77.6149, 'Heavy rain fell during the evening and early overnight of May 16th in extreme northern Virginia, near Winchester. This heavy rain of 1-3 inches caused flooding in Clarke, Frederick, and Loudoun counties early on the 17th. More heavy rain developed in Central Virginia during the afternoon of the 17th, causing new flooding as a result of 1-4 inches of rainfall.', 'The stream gage on South Fork Catoctin Creek near Waterford exceeded the 8 foot flood stage during the indicated times. The peak level of 8.49 feet occurred at 11:00am EST on May 17th. At these levels, agricultural overbank flooding is occurring.');
INSERT INTO public.stormevents_east VALUES (754968, 201805, 14, 1919, 201805, 14, 1924, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:19:00', 'EST-5', '14-MAY-18 19:24:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 45, 'MG', NULL, NULL, 0, 'N', 'POINT LOOKOUT (PTL)', 0, 'N', 'POINT LOOKOUT (PTL)', 38.04, -76.32, 38.04, -76.32, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts of 35 to 45 knots were reported at Point Lookout.');
INSERT INTO public.stormevents_east VALUES (769458, 201806, 28, 1830, 201806, 28, 1830, 128294, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '28-JUN-18 18:30:00', 'EST-5', '28-JUN-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'MG', NULL, NULL, 6, 'W', 'ST MARYS', 6, 'W', 'ST MARYS', 30.75, -81.65, 30.75, -81.65, 'A passing upper level disturbance enhanced diurnally enhanced sea breeze convection over a moist and unstable airmass.', NULL);
INSERT INTO public.stormevents_east VALUES (772200, 201807, 27, 1400, 201807, 27, 1400, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 14:00:00', 'EST-5', '27-JUL-18 14:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts in excess of 30 knots were reported at Cuckold Creek.');
INSERT INTO public.stormevents_east VALUES (783536, 201805, 15, 1615, 201805, 15, 1615, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:15:00', 'EST-5', '15-MAY-18 16:15:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'W', 'COYTESVILLE', 1, 'W', 'COYTESVILLE', 40.88, -73.98, 40.88, -73.98, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree limb down across the on / off ramp to Grand Avenue from Route 4 eastbound.');
INSERT INTO public.stormevents_east VALUES (783537, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '7.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'WSW', 'WESTWOOD', 1, 'WSW', 'WESTWOOD', 40.97, -74.1, 40.97, -74.1, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Numerous trees down in Saddle River Park.  Dog park fence crushed by falling tree.');
INSERT INTO public.stormevents_east VALUES (783539, 201805, 15, 1625, 201805, 15, 1625, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:25:00', 'EST-5', '15-MAY-18 16:25:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 1, 'E', 'CRANFORD JCT', 1, 'E', 'CRANFORD JCT', 40.67, -74.29, 40.67, -74.29, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Large tree and wires down across the road at the intersection of Birchwood Avenue and Bloomingdale Avenue.');
INSERT INTO public.stormevents_east VALUES (783540, 201805, 15, 1550, 201805, 15, 1550, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:50:00', 'EST-5', '15-MAY-18 15:50:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 1, 'E', 'OAKLAND', 1, 'E', 'OAKLAND', 41.03, -74.24, 41.03, -74.24, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree and wires down and blocking Ramapo Valley Road with road closed.');
INSERT INTO public.stormevents_east VALUES (783541, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'S', 'HILLSDALE', 1, 'S', 'HILLSDALE', 40.99, -74.03, 40.99, -74.03, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Berkeley Avenue, large tree limbs and power lines down.');
INSERT INTO public.stormevents_east VALUES (783538, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 61, 'EG', NULL, NULL, 1, 'W', 'WORTENDYKE', 1, 'W', 'WORTENDYKE', 41, -74.17, 41, -74.17, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Large tree downed onto a garage on Wyckoff Avenue.');
INSERT INTO public.stormevents_east VALUES (756742, 201805, 15, 1600, 201805, 15, 1600, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'E', 'CONGERS', 1, 'E', 'CONGERS', 41.15, -73.93, 41.15, -73.93, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree down blocking both lanes of Route 303 just south of Randi Lane.');
INSERT INTO public.stormevents_east VALUES (771183, 201806, 11, 1040, 201806, 11, 1040, 128497, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'MFL', '11-JUN-18 10:40:00', 'EST-5', '11-JUN-18 10:40:00', 0, 0, 1, 0, NULL, NULL, 'Broadcast Media', NULL, NULL, NULL, NULL, 2, 'S', 'CORAL SPGS', 2, 'S', 'CORAL SPGS', 26.2364, -80.2244, 26.2364, -80.2244, 'Morning storms once again developed along the east coast with the Atlantic seabreeze, with numerous storms across the interior and Gulf coast as seabreezed moved west and collided with the Gulf breeze along the Gulf coast during the afternoon hours. Shower and storm development along these boundaries was enhanced by a lingering upper level low across the northern Florida and the eastern Gulf of Mexico, allowing several strong storms to develop. Hail and a funnel cloud were reported in Palm Beach County with the morning activity, along with a lightning-induced fatality in Broward County. Hail was reported in Collier County during the afternoon hours.', 'A 55 year-old man was struck by lightning while carrying a weed wacker in the area of 7400 NW 4th place in Margate. He was taken to a nearby hospital in critical condition, and died from his injuries on Friday, June 15th.');
INSERT INTO public.stormevents_east VALUES (785818, 201809, 22, 700, 201809, 23, 700, 129881, 'VIRGINIA', 51, 2018, 'September', 'Heavy Rain', 'RNK', '22-SEP-18 07:00:00', 'EST-5', '23-SEP-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 6, 'E', 'BOONES MILL', 6, 'E', 'BOONES MILL', 37.12, -79.8702, 37.12, -79.8702, 'A slow-moving frontal boundary along with moisture convergence along the Blue Ridge and some modest jet stream support aloft triggered numerous thunderstorms from the late afternoon through late evening hours. These slow-moving storms produced very heavy rainfall from the Blue Ridge out across several piedmont counties. Rainfall totals ranged from 3 to 5 inches with isolated higher amounts approaching 6 inches in northern Franklin and southern Bedford counties, all of it occurring generally within a few hours.', 'The CoCoRaHS observer at Boones Mill 5.5 E (VA-FR-15) measured 5.24 inches of rain in the 24-hours ending at 0700 local time on the 23rd. Most of this fell in thunderstorms over several hours during the late evening hours of the 22nd. Flash flooding was reported in various locations across the county.');
INSERT INTO public.stormevents_east VALUES (775606, 201808, 4, 116, 201808, 4, 600, 129459, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '04-AUG-18 01:16:00', 'EST-5', '04-AUG-18 06:00:00', 0, 0, 0, 0, '15.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'FINKSBURG', 2, 'W', 'FINKSBURG', 39.5, -76.93, 39.5021, -76.9287, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'A basement wall collapsed due to flooding on Fawn Way.');
INSERT INTO public.stormevents_east VALUES (775608, 201808, 4, 130, 201808, 4, 130, 129459, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '04-AUG-18 01:30:00', 'EST-5', '04-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'MELROSE', 2, 'N', 'MELROSE', 39.71, -76.9, 39.7098, -76.8992, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'A driveway was washed out. Seven inches of rain fell from 7:30 PM EST August, 3rd to 1:30 AM EST August, 4th.');
INSERT INTO public.stormevents_east VALUES (762579, 201806, 1, 1500, 201806, 1, 1500, 127222, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '01-JUN-18 15:00:00', 'EST-5', '01-JUN-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'SE', 'MOULTRIE', 1, 'SE', 'MOULTRIE', 29.81, -81.31, 29.81, -81.31, 'Southwest steering flow focused the sea breeze merger toward the Atlantic coast in the afternoon and evening, where a few strong storms developed.', 'Quarter to nickel size hail was observed in St. Augustine Shores.');
INSERT INTO public.stormevents_east VALUES (775610, 201808, 4, 0, 201808, 4, 200, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 00:00:00', 'EST-5', '04-AUG-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'NEW LONDON', 2, 'WNW', 'NEW LONDON', 39.43, -77.28, 39.4285, -77.2774, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'Gas House Pike was closed due to flooding at Linganore Creek.');
INSERT INTO public.stormevents_east VALUES (777819, 201808, 1, 1942, 201808, 1, 1950, 129819, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '01-AUG-18 19:42:00', 'EST-5', '01-AUG-18 19:50:00', 0, 0, 0, 0, '3.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 3, 'WNW', 'OCONEE HGTS', 3, 'WNW', 'OCONEE HGTS', 33.9887, -83.4696, 33.9887, -83.4696, 'A series of short waves moving across the region in ahead of a deep upper-level trough over the Mississippi Valley brought several rounds of strong to severe thunderstorms to north and central Georgia. Several reports of damaging thunderstorm winds, flash flooding and even two isolated tornadoes were reported.', 'The Clarke County Emergency Manager reported a tree blown down onto power lines on Live Oak Place.');
INSERT INTO public.stormevents_east VALUES (777820, 201808, 1, 1950, 201808, 1, 2000, 129819, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '01-AUG-18 19:50:00', 'EST-5', '01-AUG-18 20:00:00', 0, 0, 0, 0, '2.00K', NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'THYATIRA', 1, 'S', 'THYATIRA', 34.1194, -83.5317, 34.1194, -83.5317, 'A series of short waves moving across the region in ahead of a deep upper-level trough over the Mississippi Valley brought several rounds of strong to severe thunderstorms to north and central Georgia. Several reports of damaging thunderstorm winds, flash flooding and even two isolated tornadoes were reported.', 'The Public reported power lines blown down along Still Water Lane east of Jefferson.');
INSERT INTO public.stormevents_east VALUES (806296, 201812, 21, 1115, 201812, 21, 1722, 133712, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '21-DEC-18 11:15:00', 'EST-5', '21-DEC-18 17:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'MT MERIDIAN', 1, 'SE', 'MT MERIDIAN', 38.2643, -78.8687, 38.2618, -78.8595, 'A potent longwave trough approached the area from the west on the 20th. Warm advection and strong moisture transport ahead of the mid-upper level wave led to a prolonged period of rainfall through the day as surface low pressure tracked from the FL Panhandle to WV by evening. Rainfall totals on the order of 1-2 inches led to instances of flooding across portions of Augusta, Nelson and Albemarle Counties in VA.', 'The river gage on the Middle River at Grottoes exceeded the 12 foot flood stage during the indicated period. Fields along the river were flooded. The peak level of 12.24 feet occurred at 2:00 PM on the 21st.');
INSERT INTO public.stormevents_east VALUES (761238, 201805, 31, 1935, 201805, 31, 2130, 127015, 'PENNSYLVANIA', 42, 2018, 'May', 'Flash Flood', 'PBZ', '31-MAY-18 19:35:00', 'EST-5', '31-MAY-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'PRESIDENT', 3, 'NE', 'PRESIDENT', 41.47, -79.52, 41.4733, -79.5279, 'Heavy rain resulted in flash flooding near the town of President on the 31st. In addition, there were reports of mudslides.', 'State official reported flash flooding near Bailey Drive on Route 62. Route 62 was closed as water and debris was flowing over roadway. Several mudslides were also reported.');
INSERT INTO public.stormevents_east VALUES (753164, 201805, 3, 1755, 201805, 3, 1755, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 17:55:00', 'EST-5', '03-MAY-18 17:55:00', 0, 0, 0, 0, '5.00K', NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'PLEASANTVILLE', 0, 'N', 'PLEASANTVILLE', 41.15, -73.8, 41.15, -73.8, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'Multiple trees were reported down across town.');
INSERT INTO public.stormevents_east VALUES (745726, 201805, 14, 929, 201805, 14, 929, 124276, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '14-MAY-18 09:29:00', 'EST-5', '14-MAY-18 09:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 27.3452, -80.2364, 27.3452, -80.2364, 'The interaction between a strengthening low pressure system in the eastern Gulf of Mexico and the Atlantic Bermuda High caused south winds to develop across the Florida peninsula. These winds brought a surge of moisture from the Caribbean across the state of Florida. Widespread showers and thunderstorms were ongoing throughout the day. One storm produced strong winds along the St. Lucie County coast. Another storm produced a waterspout near Cape Canaveral along the Brevard County coast.', 'Mesonet site XSTL at the St. Lucie Nuclear Power Plant measured a peak wind gust of 36 knots.');
INSERT INTO public.stormevents_east VALUES (745881, 201805, 14, 1450, 201805, 14, 1450, 124276, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '14-MAY-18 14:50:00', 'EST-5', '14-MAY-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'BUOY 41009', 0, 'N', 'BUOY 41009', 28.52, -80.17, 28.52, -80.17, 'The interaction between a strengthening low pressure system in the eastern Gulf of Mexico and the Atlantic Bermuda High caused south winds to develop across the Florida peninsula. These winds brought a surge of moisture from the Caribbean across the state of Florida. Widespread showers and thunderstorms were ongoing throughout the day. One storm produced strong winds along the St. Lucie County coast. Another storm produced a waterspout near Cape Canaveral along the Brevard County coast.', 'Buoy 41009 measured a peak wind gust of 35 knots.');
INSERT INTO public.stormevents_east VALUES (748507, 201805, 18, 1405, 201805, 18, 1410, 124762, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '18-MAY-18 14:05:00', 'EST-5', '18-MAY-18 14:10:00', 0, 0, 0, 0, '10.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'HADDOCK', 1, 'NE', 'HADDOCK', 33.0288, -83.4723, 33.0386, -83.423, 'Strong afternoon heating combined with a very moist and moderately unstable atmosphere to produce a few strong to severe thunderstorms across portions of central Georgia.', 'The Jones County 911 center reported several trees blown down, mainly between Highway 22 and Highway 129/44 northeast of Gray.');
INSERT INTO public.stormevents_east VALUES (748508, 201805, 18, 1422, 201805, 18, 1427, 124762, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '18-MAY-18 14:22:00', 'EST-5', '18-MAY-18 14:27:00', 0, 0, 0, 0, '5.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 4, 'S', 'BROWNS CROSSING', 4, 'S', 'BROWNS CROSSING', 33, -83.36, 33, -83.36, 'Strong afternoon heating combined with a very moist and moderately unstable atmosphere to produce a few strong to severe thunderstorms across portions of central Georgia.', 'The Baldwin County 911 center reported several trees blown down along County Line Church Road.');
INSERT INTO public.stormevents_east VALUES (748505, 201805, 18, 1320, 201805, 18, 1325, 124762, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '18-MAY-18 13:20:00', 'EST-5', '18-MAY-18 13:25:00', 0, 0, 0, 0, '10.00K', NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 0, 'SSW', 'WRIGHTS MILL', 2, 'S', 'ELBERTA', 32.5994, -83.6503, 32.6422, -83.6217, 'Strong afternoon heating combined with a very moist and moderately unstable atmosphere to produce a few strong to severe thunderstorms across portions of central Georgia.', 'The broadcast media reported a few trees blown down across Warner Robins from Arrowhead Trail to the Pavilion Med-stop on Houston Road to around the intersection of Francis Street and Johns Road. A house was struck by a falling tree on Arrowhead Trail. No injuries were reported.');
INSERT INTO public.stormevents_east VALUES (745399, 201805, 16, 1257, 201805, 16, 1257, 124213, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '16-MAY-18 12:57:00', 'EST-5', '16-MAY-18 12:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 41, 'MG', NULL, NULL, 2, 'NNW', 'MELBOURNE', 2, 'NNW', 'MELBOURNE', 28.101, -80.612, 28.101, -80.612, 'The interaction of an upper level cutoff low pressure over the eastern Gulf of Mexico and a strong Atlantic Ridge resulted in the formation of showers and thunderstorms across east central Florida. With southerly winds, deep moisture from the Caribbean resulted in an unstable atmosphere that produced numerous showers and thunderstorms. One thunderstorm moved across the intracoastal waters of Brevard County where it produced strong winds.', 'The ASOS at Melbourne International Airport - KMLB, measured a peak wind gust of 41 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (745397, 201805, 17, 1126, 201805, 17, 1126, 124209, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '17-MAY-18 11:26:00', 'EST-5', '17-MAY-18 11:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 35, 'MG', NULL, NULL, 4, 'N', 'SATELLITE BEACH', 4, 'N', 'SATELLITE BEACH', 28.23, -80.598, 28.23, -80.598, 'Showers and thunderstorms developed along the east coast sea breeze across western Brevard County and eastern Osceola County. The prevailing south-southwesterly flow then pushed these storms back towards the Brevard County coast. Two storms produced strong winds across the intercoastal waters.', 'The AWOS at Patrick Air Force Base - KCOF, measured a peak wind gust of 35 knots from the west.');
INSERT INTO public.stormevents_east VALUES (747693, 201805, 27, 1504, 201805, 27, 1505, 124615, 'FLORIDA', 12, 2018, 'May', 'Tornado', 'MLB', '27-MAY-18 15:04:00', 'EST-5', '27-MAY-18 15:05:00', 0, 0, 0, 0, '0.20K', '0.00K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'SE', 'SALERNO', 1, 'SE', 'SALERNO', 27.1393, -80.1901, 27.1397, -80.1894, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. One storm became severe in Martin County where it produced a short-lived, weak tornado (landspout).', 'Per reports, photos and video received from Martin County Fire Rescue, various broadcast media, and social media posts, NWS Melbourne confirmed that a very weak, short-lived tornado (landspout) occurred near the intersection of SE Geraldine Street and SE Railway Avenue in Port Salerno. The tornado, which lasted only a few seconds, was rated as EF-0 (winds near 60 mph). The landspout caused a trampoline to become airborne, where it got stuck in power lines atop a power pole.');
INSERT INTO public.stormevents_east VALUES (769127, 201806, 20, 1445, 201806, 20, 1445, 128231, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '20-JUN-18 14:45:00', 'EST-5', '20-JUN-18 14:45:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'E', 'CAMBON', 1, 'E', 'CAMBON', 30.33, -81.79, 30.33, -81.79, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'A tree was blown  down onto a home trapping one person inside. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (758530, 201807, 20, 2150, 201807, 20, 2150, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 21:50:00', 'EST-5', '20-JUL-18 21:50:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 63, 'MG', NULL, NULL, 2, 'N', 'BARTON SPGS', 2, 'N', 'BARTON SPGS', 36.26, -83.25, 36.26, -83.25, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'A 73 mph gust was recorded at Whitesburg.');
INSERT INTO public.stormevents_east VALUES (758535, 201807, 20, 2231, 201807, 20, 2231, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 22:31:00', 'EST-5', '20-JUL-18 22:31:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'WHITE ROCK', 1, 'N', 'WHITE ROCK', 35.81, -83.25, 35.81, -83.25, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down across the Cosby area.');
INSERT INTO public.stormevents_east VALUES (758538, 201807, 20, 2236, 201807, 20, 2236, 126558, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '20-JUL-18 22:36:00', 'EST-5', '20-JUL-18 22:36:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'N', 'NEVA', 1, 'N', 'NEVA', 36.42, -81.87, 36.42, -81.87, 'A very moist and unstable environment existed across the Southern Appalachian region during the mid to late evening hours. Widespread wind damage occurred as a bowing convective segment moved south across the region.', 'Several trees were reported down around the community of Butler.');
INSERT INTO public.stormevents_east VALUES (762580, 201806, 1, 1525, 201806, 1, 1525, 127222, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '01-JUN-18 15:25:00', 'EST-5', '01-JUN-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 1, NULL, NULL, NULL, 1, 'SW', 'PONTE VEDRA', 1, 'SW', 'PONTE VEDRA', 30.22, -81.38, 30.22, -81.38, 'Southwest steering flow focused the sea breeze merger toward the Atlantic coast in the afternoon and evening, where a few strong storms developed.', 'Up to quarter size hail was reported near Corona Road in Ponte Vedra Beach for nearly 20 minutes.');
INSERT INTO public.stormevents_east VALUES (762581, 201806, 1, 1720, 201806, 1, 1720, 127222, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '01-JUN-18 17:20:00', 'EST-5', '01-JUN-18 17:20:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Broadcast Media', 40, 'EG', NULL, NULL, 0, 'N', 'SUNBEAM', 0, 'N', 'SUNBEAM', 30.2, -81.58, 30.2, -81.58, 'Southwest steering flow focused the sea breeze merger toward the Atlantic coast in the afternoon and evening, where a few strong storms developed.', 'A snapped tree fell on a home in Mandarin. The cost of damage was unknown but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (762582, 201806, 2, 1345, 201806, 2, 1345, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 13:45:00', 'EST-5', '02-JUN-18 13:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'REDLAND', 2, 'W', 'REDLAND', 31.62, -82.02, 31.62, -82.02, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees were blown down onto power lines along Holmesville Road. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (772566, 201807, 4, 1824, 201807, 4, 1824, 128333, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '04-JUL-18 18:24:00', 'EST-5', '04-JUL-18 18:24:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'BLACKWOOD', 1, 'SSE', 'BLACKWOOD', 35.963, -79.0657, 35.963, -79.0657, 'A weak westward moving mid level shear axis was a focus for the development of a broken band of showers and storms. A few of these storms became strong to severe and produced isolated wind damage.', 'One tree was reported down along Camille Court.');
INSERT INTO public.stormevents_east VALUES (775013, 201807, 6, 1615, 201807, 6, 1615, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 16:15:00', 'EST-5', '06-JUL-18 16:15:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'BURNSVILLE', 2, 'SSW', 'BURNSVILLE', 35.0985, -80.2603, 35.0985, -80.2603, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'A large tree was reported down blocking Olive Branch Road, between Edwards Store Road and Cappadocia Church Road.');
INSERT INTO public.stormevents_east VALUES (775014, 201807, 6, 1646, 201807, 6, 1646, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 16:46:00', 'EST-5', '06-JUL-18 16:46:00', 0, 0, 0, 0, '1.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'MICRO', 1, 'S', 'MICRO', 35.56, -78.2, 35.56, -78.2, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Two trees were reported down.');
INSERT INTO public.stormevents_east VALUES (775032, 201807, 6, 1525, 201807, 6, 1650, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '06-JUL-18 15:25:00', 'EST-5', '06-JUL-18 16:50:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'WILDERS GROVE', 2, 'W', 'WILDERS GROVE', 35.8, -78.61, 35.7997, -78.6082, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Flooding was reported along North Raleigh Boulevard near Millbank Street, along with a car stuck in the flood waters, resulting in a water rescue.');
INSERT INTO public.stormevents_east VALUES (775034, 201807, 6, 1550, 201807, 6, 1650, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '06-JUL-18 15:50:00', 'EST-5', '06-JUL-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'RALEIGH', 2, 'ESE', 'RALEIGH', 35.79, -78.64, 35.7899, -78.6437, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'High water was reported on Peace Street and Capitol Boulevard.');
INSERT INTO public.stormevents_east VALUES (775037, 201807, 6, 1550, 201807, 6, 1650, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '06-JUL-18 15:50:00', 'EST-5', '06-JUL-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'MILLBROOK', 2, 'S', 'MILLBROOK', 35.8148, -78.6198, 35.8143, -78.6162, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Atlantic Avenue at Hodges was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (766266, 201806, 3, 1832, 201806, 3, 1832, 127794, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '03-JUN-18 18:32:00', 'EST-5', '03-JUN-18 18:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 0.88, NULL, NULL, NULL, 0, 'N', 'ST AUGUSTINE', 0, 'N', 'ST AUGUSTINE', 29.88, -81.32, 29.88, -81.32, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Pea to nickel size hail was observed.');
INSERT INTO public.stormevents_east VALUES (766267, 201806, 3, 1838, 201806, 3, 1838, 127794, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '03-JUN-18 18:38:00', 'EST-5', '03-JUN-18 18:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 2, NULL, NULL, NULL, 1, 'WNW', 'ST AUGUSTINE BEACH', 1, 'WNW', 'ST AUGUSTINE BEACH', 29.84, -81.29, 29.84, -81.29, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Hen egg to quarter size hail was observed in St. Augustine Beach.');
INSERT INTO public.stormevents_east VALUES (766268, 201806, 3, 1650, 201806, 3, 1650, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 16:50:00', 'EST-5', '03-JUN-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 9, 'WSW', 'PINE MOUNT', 9, 'WSW', 'PINE MOUNT', 30.12, -83.11, 30.12, -83.11, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Trees were blown down east of Luraville near 180th Street and 177th Road.');
INSERT INTO public.stormevents_east VALUES (766269, 201806, 3, 1715, 201806, 3, 1715, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:15:00', 'EST-5', '03-JUN-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 3, 'NNW', 'FLEMINGTON', 3, 'NNW', 'FLEMINGTON', 29.46, -82.31, 29.46, -82.31, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Multiple large tree limbs were blown down over the intersection of County Roads 320 and 329 in NW Marion County.');
INSERT INTO public.stormevents_east VALUES (766270, 201806, 3, 1720, 201806, 3, 1720, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:20:00', 'EST-5', '03-JUN-18 17:20:00', 0, 0, 0, 0, '0.10K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 2, 'SSE', 'BLAND', 2, 'SSE', 'BLAND', 29.88, -82.49, 29.88, -82.49, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Wind damage of unknown extent was reported near the intersection of County Roads 236 and NW 241. The cost of damage was unknown, but it was estimated so the event could be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (766271, 201806, 3, 1725, 201806, 3, 1725, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:25:00', 'EST-5', '03-JUN-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'W', 'MICANOPY', 1, 'W', 'MICANOPY', 29.5, -82.29, 29.5, -82.29, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Power lines were blown down over Highway 329 in Micanopy.');
INSERT INTO public.stormevents_east VALUES (768125, 201807, 11, 1435, 201807, 11, 1435, 128082, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '11-JUL-18 14:35:00', 'EST-5', '11-JUL-18 14:35:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'COLLEEN', 1, 'NE', 'COLLEEN', 37.7122, -78.933, 37.7122, -78.933, 'An isolated thunderstorm produced damaging wind gusts.', 'A tree was down on Tye Brook Highway and Route 56.');
INSERT INTO public.stormevents_east VALUES (774885, 201807, 25, 2047, 201807, 25, 2117, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 20:47:00', 'EST-5', '25-JUL-18 21:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'MEDFORD', 1, 'NNE', 'MEDFORD', 39.5614, -77.0444, 39.5615, -77.0439, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Water rescue at Little Pipe Creek near the intersection of Old New Windsor Turnpike and Adams Mill Road.');
INSERT INTO public.stormevents_east VALUES (774886, 201807, 25, 2047, 201807, 25, 2117, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 20:47:00', 'EST-5', '25-JUL-18 21:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'SAMS CREEK', 1, 'W', 'SAMS CREEK', 39.4996, -77.1144, 39.4992, -77.1146, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'A water rescue was reported in the 3400 block of Sams Creek Road.');
INSERT INTO public.stormevents_east VALUES (774887, 201807, 26, 444, 201807, 26, 545, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '26-JUL-18 04:44:00', 'EST-5', '26-JUL-18 05:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'PERRY HALL', 1, 'ENE', 'PERRY HALL', 39.4281, -76.4443, 39.4277, -76.4452, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Overflow from Big Gunpowder Falls forced the closure of one southbound lane of US 1.');
INSERT INTO public.stormevents_east VALUES (774888, 201807, 26, 1003, 201807, 26, 1100, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '26-JUL-18 10:03:00', 'EST-5', '26-JUL-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'LADIESBURG', 2, 'E', 'LADIESBURG', 39.5828, -77.2289, 39.5826, -77.2238, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Little Pipe Creek was out of its banks, flooding both Claybaugh Road and Simpsons Mill Road near the Johnsonville Bridge.');
INSERT INTO public.stormevents_east VALUES (781496, 201807, 23, 2055, 201807, 25, 1031, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '23-JUL-18 20:55:00', 'EST-5', '25-JUL-18 10:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RAYNOR HGTS', 2, 'W', 'RAYNOR HGTS', 39.2117, -76.7025, 39.216, -76.7007, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The stream gage on the Patapsco River near Elkridge exceeded the 16 foot flood stage during the indicated period. The peak level of 18.45 feet occurred at 11:05am EST. Hammonds Ferry Road and Furnace Avenue were flooded.');
INSERT INTO public.stormevents_east VALUES (753173, 201805, 3, 1758, 201805, 3, 1758, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 17:58:00', 'EST-5', '03-MAY-18 17:58:00', 0, 0, 0, 0, '7.50K', NULL, 'Law Enforcement', 52, 'EG', NULL, NULL, 0, 'N', 'BEDFORD', 0, 'N', 'BEDFORD', 41.2, -73.65, 41.2, -73.65, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'Numerous trees were reported down across town.');
INSERT INTO public.stormevents_east VALUES (781498, 201807, 26, 1946, 201807, 26, 2141, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '26-JUL-18 19:46:00', 'EST-5', '26-JUL-18 21:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RAYNOR HGTS', 2, 'W', 'RAYNOR HGTS', 39.2117, -76.7025, 39.216, -76.7007, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The stream gage on the Patapsco River near Elkridge exceeded the 16 foot flood stage during the indicated period. The peak level of 16.37 feet occurred at 9:25pm EST. Hammonds Ferry Road and Furnace Avenue were flooded.');
INSERT INTO public.stormevents_east VALUES (781499, 201807, 25, 2056, 201807, 25, 2219, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 20:56:00', 'EST-5', '25-JUL-18 22:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'FINKSBURG', 0, 'SSW', 'FINKSBURG', 39.4894, -76.9032, 39.4941, -76.9021, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Beaver Run near Finksburg exceeded the 5 foot flood stage during the indicated period. The peak level of 6.03 feet occurred at 9:30pm EST. Hughes Road was flooded in the area.');
INSERT INTO public.stormevents_east VALUES (756481, 201805, 15, 1532, 201805, 15, 1534, 124185, 'NEW YORK', 36, 2018, 'May', 'Tornado', 'OKX', '15-MAY-18 15:32:00', 'EST-5', '15-MAY-18 15:34:00', 0, 0, 0, 0, '100.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NNW', 'HAVILAND HOLLOW', 1, 'S', 'PUTNAM LAKE', 41.4929, -73.5854, 41.4585, -73.5528, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Based on a National Weather Service storm survey, done in|conjunction with the Putnam County Bureau of Emergency Services,|is been determined that an EF1 tornado with estimated peak winds |of 100 mph moved along a discontinuous path through Patterson, New|York. The tornado originated along NY State Route 22, north of |the intersection with Haviland Hollow Road, near the Watchtower |Educational Center. The tornado then tracked along East Branch|Road, turned left toward Putnam Lake, then lifted near the |intersection of East Branch Road and Fairfield Drive. The storm |snapped multiple trees along its path, not all of it continuous. |The most extensive damage occurred in the general vicinity of 706|East Branch Road, where multiple trees were uprooted and snapped,|lying in a convergent pattern, and where leaves were splattered on|three sides of the house. Based on this information, the tornado|was classified as an EF1 with estimated maximum winds of 100 mph.');
INSERT INTO public.stormevents_east VALUES (761264, 201805, 31, 1755, 201805, 31, 1900, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 17:55:00', 'EST-5', '31-MAY-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'VALE', 1, 'ESE', 'VALE', 38.8743, -77.3378, 38.8751, -77.3376, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Difficult Run was out of its banks and flowing across Waples Mill Road.');
INSERT INTO public.stormevents_east VALUES (761263, 201805, 31, 1745, 201805, 31, 1845, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 17:45:00', 'EST-5', '31-MAY-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'OAKTON', 1, 'S', 'OAKTON', 38.8708, -77.3005, 38.871, -77.2991, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Several inches of water were reported to have entered the first floor of an apartment building.');
INSERT INTO public.stormevents_east VALUES (761265, 201805, 31, 1805, 201805, 31, 1905, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 18:05:00', 'EST-5', '31-MAY-18 19:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'VALE', 1, 'ENE', 'VALE', 38.8845, -77.3417, 38.8844, -77.3413, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Fox Mill Road was flooded and closed near Hunt Road.');
INSERT INTO public.stormevents_east VALUES (808499, 201812, 20, 2356, 201812, 21, 156, 133712, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '20-DEC-18 23:56:00', 'EST-5', '21-DEC-18 01:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'YANCEY MILLS', 1, 'SE', 'YANCEY MILLS', 38.0386, -78.7194, 38.0395, -78.7179, 'A potent longwave trough approached the area from the west on the 20th. Warm advection and strong moisture transport ahead of the mid-upper level wave led to a prolonged period of rainfall through the day as surface low pressure tracked from the FL Panhandle to WV by evening. Rainfall totals on the order of 1-2 inches led to instances of flooding across portions of Augusta, Nelson and Albemarle Counties in VA.', 'VA-824 (Patterson Mill Lane) closed due to flooding near Stockton Creek between US-250 (Rockfish Gap Turnpike) and VA-688 (Midway Road).');
INSERT INTO public.stormevents_east VALUES (761280, 201805, 31, 1820, 201805, 31, 2000, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '31-MAY-18 18:20:00', 'EST-5', '31-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'DALE ENTERPRISE', 1, 'SSW', 'DALE ENTERPRISE', 38.4391, -78.9356, 38.4387, -78.9353, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Vehicle trapped in high water on Silver Lake Road due to Cooks Creek being out of bank.');
INSERT INTO public.stormevents_east VALUES (760934, 201805, 27, 2032, 201805, 28, 618, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 20:32:00', 'EST-5', '28-MAY-18 06:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'SAVAGE', 1, 'SE', 'SAVAGE', 39.1206, -76.8173, 39.1189, -76.8137, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on the Little Patuxent River near Savage exceeded the 10 foot flood stage during the indicated times. The peak level of 16.52 feet occurred at 11:30pm EST on May 27th. Brock Bridge Road significantly flooded during this event.');
INSERT INTO public.stormevents_east VALUES (759282, 201805, 22, 1620, 201805, 22, 1820, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 16:20:00', 'EST-5', '22-MAY-18 18:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'SPRINGFIELD', 1, 'WSW', 'SPRINGFIELD', 38.7753, -77.2051, 38.7762, -77.2031, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Old Keene Mill Road flooded and closed near Greeley Boulevard.');
INSERT INTO public.stormevents_east VALUES (759285, 201805, 22, 1630, 201805, 22, 1830, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 16:30:00', 'EST-5', '22-MAY-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'LEWINSVILLE', 1, 'SW', 'LEWINSVILLE', 38.9223, -77.2093, 38.9227, -77.2083, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Flooding near the intersection of Colshire Meadow Drive and Colshire Drive closed the road.');
INSERT INTO public.stormevents_east VALUES (759287, 201805, 22, 1650, 201805, 22, 1750, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 16:50:00', 'EST-5', '22-MAY-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'ROSSLYN', 1, 'NNE', 'ROSSLYN', 38.9, -77.07, 38.8996, -77.0697, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Street flooding due to standing water on George Washington Memorial Parkway near Rosslyn. Water was reported to be over the hood of a vehicle.');
INSERT INTO public.stormevents_east VALUES (759294, 201805, 22, 30, 201805, 22, 300, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 00:30:00', 'EST-5', '22-MAY-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'GENOA', 7, 'W', 'GENOA', 38.6302, -78.9493, 38.6372, -79.0442, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'Flooding continued in the Fulks Run, Bergton, and Yankeetown areas. Many roads were closed with many streams out of their banks from earlier flash flooding.');
INSERT INTO public.stormevents_east VALUES (771192, 201806, 15, 1330, 201806, 15, 1330, 128504, 'FLORIDA', 12, 2018, 'June', 'Funnel Cloud', 'MFL', '15-JUN-18 13:30:00', 'EST-5', '15-JUN-18 13:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 7, 'NNW', 'MIRAMAR', 7, 'NNW', 'MIRAMAR', 26.09, -80.46, 26.09, -80.46, 'Deep tropical moisture lead to the development of showers and storms across South Florida during the late morning and afternoon hours. A boundary collision across the western Broward County metropolitan area led to a funnel cloud.', 'Report received via social media of a funnel cloud, looking west from the intersection of Interstate 75 and Griffin Road in Weston.');
INSERT INTO public.stormevents_east VALUES (776997, 201807, 31, 2031, 201807, 31, 2244, 129726, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '31-JUL-18 20:31:00', 'EST-5', '31-JUL-18 22:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'SHARPSBURG', 1, 'SSE', 'SHARPSBURG', 35.8696, -77.8214, 35.8563, -77.8266, 'Deep Gulf of Mexico moisture channeling between an amplifying trough over the mid-lower MS Valley and the western Atlantic ridge led to precipitable waters increasing to to over 2.0 over the area. Upper forcing in the form of divergence aloft, within the right entrance region of an upper level jet streak that extended down the Mid-Atlantic States, combined with a south-north ribbon of elongated vorticity shear axis centered east of the southern and central Appalachians, led to the development of scattered to numerous thunderstorms through the late afternoon and evening. The heaviest rain fell over the tri-county area of Nash-Wilson-Edgecombe counties, where training thunderstorms produced a swath of 4 to 6 inches.  This area of heavy rainfall flooded numerous roads in these counties, with at least two water rescues in Nash County.', 'Heavy rainfall of 4 to 6 inches resulted in widespread flash flooding in the Sharpsburg area. Numerous roads were closed and 2 water rescues were conducted.');
INSERT INTO public.stormevents_east VALUES (784164, 201810, 2, 1353, 201810, 2, 1353, 130037, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'CLE', '02-OCT-18 13:53:00', 'EST-5', '02-OCT-18 13:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 3, 'SE', 'SAEGERTOWN', 3, 'SE', 'SAEGERTOWN', 41.7, -80.11, 41.7, -80.11, 'A warm front associated with an area of developing low pressure over northern Illinois moved across northern Ohio and northwestern Pennsylvania late on October 1st through the morning hours of the 2nd.  This allowed strong southerly flow to bring abnormally warm and moist air into the area. Temperatures in the upper 70s to low 80s created moderate instability ahead of the front during the afternoon. Strong low-level wind shear was in place so the environment was primed for severe weather with tornadoes possible. The low pressure lifted northeast to southern Ontario by noon on the 2nd with the associated cold front moving eastward across Ohio. The main emphasis for the tornadic development was an outflow boundary from morning convection over the lake. This boundary (maybe the warm front) was oriented west to east across Ashtabula and Crawford counties. The first storms along this boundary initiated between 1:00 and 2:00 PM in Ashtabula and southern Erie County.  These thunderstorms eventually produced three tornadoes in Crawford County.  The strongest of the three struck a nursing home near Conneautville causing significant damage.  The other two tornadoes struck rural areas and resulted in mainly tree damage.', 'Video from social media showed several trees were blown down near the Fountain House Corners area at Highway 198 and Highway 86.');
INSERT INTO public.stormevents_east VALUES (776049, 201807, 22, 1836, 201807, 22, 1836, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:36:00', 'EST-5', '22-JUL-18 18:36:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'SILER CITY', 1, 'E', 'SILER CITY', 35.73, -79.46, 35.73, -79.46, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down in Siler City.');
INSERT INTO public.stormevents_east VALUES (776050, 201807, 22, 1851, 201807, 22, 1851, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:51:00', 'EST-5', '22-JUL-18 18:51:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SE', 'WALKERTOWN', 2, 'SE', 'WALKERTOWN', 36.1605, -80.1458, 36.1605, -80.1458, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Darrow Road and Martin Street.');
INSERT INTO public.stormevents_east VALUES (776051, 201807, 22, 1856, 201807, 22, 1856, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:56:00', 'EST-5', '22-JUL-18 18:56:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'WSW', 'WALKERTOWN', 1, 'WSW', 'WALKERTOWN', 36.1772, -80.1809, 36.1772, -80.1809, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Marie Court.');
INSERT INTO public.stormevents_east VALUES (776052, 201807, 22, 1900, 201807, 22, 1900, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 19:00:00', 'EST-5', '22-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'WSW', 'DENNIS', 0, 'WSW', 'DENNIS', 36.2193, -80.1827, 36.2193, -80.1827, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Lake Woussicket Road.');
INSERT INTO public.stormevents_east VALUES (772185, 201807, 23, 1324, 201807, 23, 1324, 128755, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '23-JUL-18 13:24:00', 'EST-5', '23-JUL-18 13:24:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 0, 'N', 'BALTIMORE KEY BRIDGE (FSKM2)', 39.22, -76.53, 39.22, -76.53, 'A cutoff low from the jet stream remained just to our west on the 23rd. Some thunderstorms produced gusty winds due to an unstable atmosphere and stronger winds that were able to mix down from aloft.', 'A wind gust in excess of 30 knots was reported at Key Bridge.');
INSERT INTO public.stormevents_east VALUES (772199, 201807, 27, 1358, 201807, 27, 1358, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 13:58:00', 'EST-5', '27-JUL-18 13:58:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 2, 'E', 'BABAR POINT (BAB)', 2, 'E', 'BABAR POINT (BAB)', 38.3089, -77.0019, 38.3089, -77.0019, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts in excess of 30 knots were reported at Pylons DAH.');
INSERT INTO public.stormevents_east VALUES (772203, 201807, 27, 1405, 201807, 27, 1410, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 14:05:00', 'EST-5', '27-JUL-18 14:10:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts of 34 to 38 knots were reported Cuckold Creek.');
INSERT INTO public.stormevents_east VALUES (776805, 201807, 28, 1754, 201807, 28, 1754, 129696, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '28-JUL-18 17:54:00', 'EST-5', '28-JUL-18 17:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NNE', 'WENDELL', 1, 'NNE', 'WENDELL', 35.7878, -78.3759, 35.7878, -78.3759, 'A quasi-stationary front, bisecting central NC, provided a focus point for scattered to numerous showers and thunderstorms. Thanks to a moist and unstable airmass, a few of these storms breached the severe limit, resulting in isolated wind damage, and localized flash flooding.', 'Tree down across roadway at Wendell Boulevard and Industrial Drive.');
INSERT INTO public.stormevents_east VALUES (776211, 201807, 22, 40, 201807, 22, 40, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 00:40:00', 'EST-5', '22-JUL-18 00:40:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'COATS', 1, 'S', 'COATS', 35.41, -78.68, 35.41, -78.68, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'Multiple trees reported down near Coats. Minor damage to a structure was reported on Brick Mill Road. Monetary damages unknown.');
INSERT INTO public.stormevents_east VALUES (742221, 201804, 15, 2115, 201804, 15, 2315, 123710, 'OHIO', 39, 2018, 'April', 'Flood', 'ILN', '15-APR-18 21:15:00', 'EST-5', '15-APR-18 23:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'LOGAN', 2, 'NE', 'LOGAN', 39.55, -82.4, 39.5479, -82.3897, 'Showers and thunderstorms which produced heavy rain, developed ahead of potent surface low.', 'High water resulted in a closure of a portion of State Route 93 north of Logan.');
INSERT INTO public.stormevents_east VALUES (744412, 201804, 15, 1318, 201804, 15, 1318, 123495, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CAE', '15-APR-18 13:18:00', 'EST-5', '15-APR-18 13:18:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 63, 'MG', NULL, NULL, 1, 'ESE', 'SOUTH CONGAREE', 1, 'ESE', 'SOUTH CONGAREE', 33.89, -81.1, 33.89, -81.1, 'A strong upper level disturbance combined with strong atmospheric shear, and instability enhanced by diurnal heating, produced a line of thunderstorms, some of which were severe and included embedded tornadoes.', 'Trained spotter reported a 72 mph wind gust measured by a home weather station. Small to medium tree limbs were downed.');
INSERT INTO public.stormevents_east VALUES (754992, 201805, 15, 2010, 201805, 15, 2010, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 20:10:00', 'EST-5', '15-MAY-18 20:10:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'ANNAPOLIS BUOY (44063)', 0, 'N', 'ANNAPOLIS BUOY (44063)', 39.96, -76.45, 39.96, -76.45, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts in excess of 30 knots were reported at the Annapolis Buoy.');
INSERT INTO public.stormevents_east VALUES (755006, 201805, 22, 1800, 201805, 22, 1806, 125938, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '22-MAY-18 18:00:00', 'EST-5', '22-MAY-18 18:06:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'LEWISETTA MD (LWTV2)', 0, 'N', 'LEWISETTA MD (LWTV2)', 38, -76.47, 38, -76.47, 'A weak cold front approached the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary. An upper-level trough axis also strengthened winds aloft, and some of these winds were able to mix down to the surface in stronger storms.', 'A wind gust in excess of 30 knots was reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (762875, 201807, 4, 1408, 201807, 4, 1408, 125904, 'PENNSYLVANIA', 42, 2018, 'July', 'Thunderstorm Wind', 'CTP', '04-JUL-18 14:08:00', 'EST-5', '04-JUL-18 14:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 52, 'EG', NULL, NULL, 1, 'SE', 'CONFLUENCE', 1, 'SE', 'CONFLUENCE', 39.8112, -79.3544, 39.8112, -79.3544, 'Scattered showers and pulse thunderstorms developed in a very warm and humid airmass over central Pennsylvania. Anomalously high PWATs resulted in very heavy rainfall in some storms, and a few reports of wind damage were received.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down multiple trees and produced quarter-sized hail near Confluence.');
INSERT INTO public.stormevents_east VALUES (783514, 201805, 15, 1545, 201805, 15, 1545, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Public', 61, 'EG', NULL, NULL, 1, 'SW', 'CALDWELL', 1, 'SW', 'CALDWELL', 40.84, -74.28, 40.84, -74.28, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Large trees down.');
INSERT INTO public.stormevents_east VALUES (783515, 201805, 15, 1549, 201805, 15, 1549, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:49:00', 'EST-5', '15-MAY-18 15:49:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 61, 'EG', NULL, NULL, 1, 'E', 'OAKLAND', 1, 'E', 'OAKLAND', 41.03, -74.24, 41.03, -74.24, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree on a house on Page Drive.');
INSERT INTO public.stormevents_east VALUES (783516, 201805, 15, 1544, 201805, 15, 1544, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:44:00', 'EST-5', '15-MAY-18 15:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 57, 'MG', NULL, NULL, 9, 'W', 'GARFIELD', 9, 'W', 'GARFIELD', 40.8764, -74.2828, 40.8764, -74.2828, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Thunderstorm wind gust measured by CDW ASOS.');
INSERT INTO public.stormevents_east VALUES (783517, 201805, 15, 1552, 201805, 15, 1552, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:52:00', 'EST-5', '15-MAY-18 15:52:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Public', 61, 'EG', NULL, NULL, 2, 'NE', 'WEST ORANGE', 2, 'NE', 'WEST ORANGE', 40.79, -74.26, 40.79, -74.26, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Large tree reported down on Maple Street.');
INSERT INTO public.stormevents_east VALUES (783518, 201805, 15, 1553, 201805, 15, 1553, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:53:00', 'EST-5', '15-MAY-18 15:53:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'ENE', 'WESTWOOD', 1, 'ENE', 'WESTWOOD', 40.99, -74.06, 40.99, -74.06, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Numerous trees and wires down...including one tree down on a house.');
INSERT INTO public.stormevents_east VALUES (783519, 201805, 15, 1555, 201805, 15, 1555, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:55:00', 'EST-5', '15-MAY-18 15:55:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Amateur Radio', 61, 'EG', NULL, NULL, 0, 'N', 'ALLENDALE', 0, 'N', 'ALLENDALE', 41.03, -74.13, 41.03, -74.13, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Significant windshield damage to car from flying debris along Route 17 near the Allendale exit.');
INSERT INTO public.stormevents_east VALUES (783520, 201805, 15, 1557, 201805, 15, 1557, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:57:00', 'EST-5', '15-MAY-18 15:57:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'E', 'LITTLE FALLS', 1, 'E', 'LITTLE FALLS', 40.88, -74.22, 40.88, -74.22, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Trees on tracks on New Jersey transit.');
INSERT INTO public.stormevents_east VALUES (783521, 201805, 15, 1550, 201805, 15, 1550, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:50:00', 'EST-5', '15-MAY-18 15:50:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 1, 'E', 'OAKLAND', 1, 'E', 'OAKLAND', 41.03, -74.24, 41.03, -74.24, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree on house on Walnut Street.');
INSERT INTO public.stormevents_east VALUES (783545, 201805, 15, 1512, 201805, 15, 1512, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:12:00', 'EST-5', '15-MAY-18 15:12:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 0, 'N', 'NEWBURGH', 0, 'N', 'NEWBURGH', 41.5, -74.02, 41.5, -74.02, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Roof cover blown off an abandoned building on Carpenter Avenue near Broadway with bricks on the ground.  Partial building collapse.');
INSERT INTO public.stormevents_east VALUES (783592, 201805, 15, 1512, 201805, 15, 1512, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:12:00', 'EST-5', '15-MAY-18 15:12:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 0, 'E', 'NEWBURGH', 0, 'E', 'NEWBURGH', 41.4991, -74.0107, 41.4991, -74.0107, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Partial building collapse with a roof blown off on Liberty Street between Washington Street and Ann Street.');
INSERT INTO public.stormevents_east VALUES (771184, 201806, 11, 1155, 201806, 11, 1155, 128497, 'FLORIDA', 12, 2018, 'June', 'Funnel Cloud', 'MFL', '11-JUN-18 11:55:00', 'EST-5', '11-JUN-18 11:55:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'W', '(PBI)PALM BEACH ARPT', 1, 'W', '(PBI)PALM BEACH ARPT', 26.68, -80.17, 26.68, -80.17, 'Morning storms once again developed along the east coast with the Atlantic seabreeze, with numerous storms across the interior and Gulf coast as seabreezed moved west and collided with the Gulf breeze along the Gulf coast during the afternoon hours. Shower and storm development along these boundaries was enhanced by a lingering upper level low across the northern Florida and the eastern Gulf of Mexico, allowing several strong storms to develop. Hail and a funnel cloud were reported in Palm Beach County with the morning activity, along with a lightning-induced fatality in Broward County. Hail was reported in Collier County during the afternoon hours.', 'A trained spotter reported a funnel cloud near the intersection of the Florida Turnpike and Southern Boulevard.');
INSERT INTO public.stormevents_east VALUES (771185, 201806, 11, 1330, 201806, 11, 1330, 128497, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MFL', '11-JUN-18 13:30:00', 'EST-5', '11-JUN-18 13:30:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.75, NULL, NULL, NULL, 1, 'ENE', 'NAPLES PARK', 1, 'ENE', 'NAPLES PARK', 26.28, -81.78, 26.28, -81.78, 'Morning storms once again developed along the east coast with the Atlantic seabreeze, with numerous storms across the interior and Gulf coast as seabreezed moved west and collided with the Gulf breeze along the Gulf coast during the afternoon hours. Shower and storm development along these boundaries was enhanced by a lingering upper level low across the northern Florida and the eastern Gulf of Mexico, allowing several strong storms to develop. Hail and a funnel cloud were reported in Palm Beach County with the morning activity, along with a lightning-induced fatality in Broward County. Hail was reported in Collier County during the afternoon hours.', 'Video received via social media shows approximately dime sized ail falling in the Palm River area of North Naples. Time is estimated based on video post time and radar.');
INSERT INTO public.stormevents_east VALUES (783447, 201805, 15, 1545, 201805, 15, 1545, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 1, 0, '5.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 0, 'W', 'NEW FAIRFIELD', 0, 'W', 'NEW FAIRFIELD', 41.4708, -73.4889, 41.4708, -73.4889, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree fell on a car on Brush Hill Road, killing one person inside.');
INSERT INTO public.stormevents_east VALUES (780355, 201807, 22, 1244, 201807, 22, 1244, 130346, 'FLORIDA', 12, 2018, 'July', 'Thunderstorm Wind', 'JAX', '22-JUL-18 12:44:00', 'EST-5', '22-JUL-18 12:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'GLEN ST MARY', 1, 'NE', 'GLEN ST MARY', 30.29, -82.16, 30.29, -82.16, 'A low level boundary was draped across north-central FL roughly from Suwanee to Marion counties with high moisture content and an unstable airmass pumping over the boundary from the Gulf of Mexico under WSW flow.', 'A tree was blown down onto a power line on North County Road 125 and Crews Road.');
INSERT INTO public.stormevents_east VALUES (783351, 201805, 15, 1600, 201805, 15, 1600, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Social Media', 70, 'EG', NULL, NULL, 1, 'S', 'NEWTOWN', 1, 'S', 'NEWTOWN', 41.41, -73.32, 41.41, -73.32, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous roads closed due to downed trees in the Newtown / Monroe area.');
INSERT INTO public.stormevents_east VALUES (783353, 201805, 15, 1555, 201805, 15, 1555, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:55:00', 'EST-5', '15-MAY-18 15:55:00', 0, 0, 0, 0, '5.00K', '0.00K', 'CoCoRaHS', 61, 'EG', NULL, NULL, 1, 'S', 'NEWTOWN', 1, 'S', 'NEWTOWN', 41.41, -73.32, 41.41, -73.32, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'At Gelding Hill Road, numerous trees down.  Power lines down.');
INSERT INTO public.stormevents_east VALUES (778132, 201808, 2, 1533, 201808, 2, 1533, 129889, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '02-AUG-18 15:33:00', 'EST-5', '02-AUG-18 15:33:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'SANDY POINT (SPT)', 0, 'N', 'SANDY POINT (SPT)', 39.01, -76.4, 39.01, -76.4, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of up to 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (787852, 201809, 3, 1200, 201809, 3, 2200, 131618, 'FLORIDA', 12, 2018, 'September', 'Flood', 'MFL', '03-SEP-18 12:00:00', 'EST-5', '03-SEP-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'N', 'SWEET WATER', 2, 'S', 'MEDLEY', 25.7842, -80.3687, 25.8081, -80.322, 'A low pressure system moving across the tropical Atlantic into the Bahamas formed into Tropical Storm Gordon near the South Florida peninsula. Although the effects from Tropical Storm Gordon were fairly minor for South Florida, sustained Tropical Storm force winds were felt across portions of Miami-Dade and Broward County. Miami-Dade and Broward reported slightly higher amount of power outages than a typical day across the region. Due to some heavy rainbands Miami-Dade county experienced some street flooding that led to partial lane closures. However, no structural flooding was reported with all flood impacts relatively minor.', 'Heavy rainfall led to minor flooding and partial lane closures in Doral, mainly along NW 12 Street between NW 107 Avenue and NW 92 Avenue, and between NW 79 Avenue and NW 77 Court from NW 29 Street to NW 34 Street. Rainfall totals of 3 to 4 inches fell in only a few hours.');
INSERT INTO public.stormevents_east VALUES (771920, 201809, 2, 1353, 201809, 2, 1402, 128694, 'GULF OF MEXICO', 85, 2018, 'September', 'Waterspout', 'TBW', '02-SEP-18 13:53:00', 'EST-5', '02-SEP-18 14:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 3, 'NNE', 'MIDDLE TAMPA BAY', 1, 'S', 'OLD TAMPA BAY', 27.81, -82.5, 27.83, -82.58, 'Persistent easterly flow allowed thunderstorms to develop across the Florida Peninsula during the early afternoon and shift west into the eastern Gulf of Mexico through the early evening. Some of these storms caused gusty winds along the coast. Another storm produced a waterspout that was spotted over the Tampa Bay.', 'A waterspout off of Weedon Island was photographed by a member of the public.');
INSERT INTO public.stormevents_east VALUES (772527, 201809, 3, 1220, 201809, 3, 1220, 128809, 'GULF OF MEXICO', 85, 2018, 'September', 'Marine Thunderstorm Wind', 'TBW', '03-SEP-18 12:20:00', 'EST-5', '03-SEP-18 12:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Buoy', 45, 'EG', NULL, NULL, 2, 'W', 'MIDDLE TAMPA BAY', 2, 'W', 'MIDDLE TAMPA BAY', 27.77, -82.57, 27.77, -82.57, 'As Tropical Storm Gordon moved west-northwest through the eastern Gulf of Mexico, deep moisture and easterly winds northeast of the storms led to scattered thunderstorms moving west across parts of the Florida Peninsula. Some of these storms produced gusty winds along the coast.', 'The WeatherFlow buoy in the Tampa Bay (XTAM) recorded a 45 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (778476, 201808, 21, 2151, 201808, 21, 2351, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:51:00', 'EST-5', '21-AUG-18 23:51:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'MARTINSBURG', 2, 'NNE', 'MARTINSBURG', 39.4713, -77.958, 39.4712, -77.9564, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Apartments along Eclipse Court were evacuated due to flooding.');
INSERT INTO public.stormevents_east VALUES (778464, 201808, 21, 1354, 201808, 21, 1554, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 13:54:00', 'EST-5', '21-AUG-18 15:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'FORESTVILLE', 0, 'SSE', 'FORESTVILLE', 38.8285, -76.8783, 38.8288, -76.879, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Forestville Road was closed due to high water between Suitland Parkway and Rena Road.');
INSERT INTO public.stormevents_east VALUES (778465, 201808, 21, 2030, 201808, 21, 2230, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 20:30:00', 'EST-5', '21-AUG-18 22:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CAVETOWN', 1, 'NNW', 'CAVETOWN', 39.6648, -77.5934, 39.6657, -77.5917, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Rowe Road was closed due to flooding between Itnyre Road and Lietersburg Smithburg Road near Grove Creek.');
INSERT INTO public.stormevents_east VALUES (777829, 201808, 7, 1550, 201808, 7, 1600, 129821, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '07-AUG-18 15:50:00', 'EST-5', '07-AUG-18 16:00:00', 0, 0, 0, 0, '6.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'CROSS KEYS', 0, 'NE', 'DURESVILLE', 32.8586, -83.5861, 32.852, -83.5678, 'Despite a persistent ridge of high pressure over the region, ample moisture and strong daytime heating resulted in isolated to scattered strong to severe thunderstorms each afternoon, into the early evening.', 'The Macon-Bibb 911 center reported trees blown down onto power lines on Companion Drive. The local broadcast media reported a tree blown down onto a school bus near the intersection of Lakeshore Drive and Masseyville Road. No injuries were reported.');
INSERT INTO public.stormevents_east VALUES (778135, 201808, 2, 1526, 201808, 2, 1531, 129889, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '02-AUG-18 15:26:00', 'EST-5', '02-AUG-18 15:31:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of up to 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778136, 201808, 2, 1700, 201808, 2, 1700, 129889, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '02-AUG-18 17:00:00', 'EST-5', '02-AUG-18 17:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of up to 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778137, 201808, 7, 1624, 201808, 7, 1630, 129890, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '07-AUG-18 16:24:00', 'EST-5', '07-AUG-18 16:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (806297, 201812, 21, 618, 201812, 21, 1201, 133712, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '21-DEC-18 06:18:00', 'EST-5', '21-DEC-18 12:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'RAPIDAN', 1, 'NW', 'RAPIDAN', 38.3266, -78.0824, 38.3285, -78.0806, 'A potent longwave trough approached the area from the west on the 20th. Warm advection and strong moisture transport ahead of the mid-upper level wave led to a prolonged period of rainfall through the day as surface low pressure tracked from the FL Panhandle to WV by evening. Rainfall totals on the order of 1-2 inches led to instances of flooding across portions of Augusta, Nelson and Albemarle Counties in VA.', 'The river gage on the Robinson River at Locust Dale exceeded the 11 foot flood stage during the indicated period. Water covered a portion of Route 721 (Robinson River Road). Agricultural flooding was also observed. The peak level of 11.83 feet occurred at 9:00 AM on the 21st.');
INSERT INTO public.stormevents_east VALUES (798671, 201812, 30, 1036, 201812, 30, 1230, 133489, 'SOUTH CAROLINA', 45, 2018, 'December', 'Flood', 'ILM', '30-DEC-18 10:36:00', 'EST-5', '30-DEC-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'NORTH SANTEE', 1, 'SSW', 'NORTH SANTEE', 33.2156, -79.3888, 33.215, -79.3891, 'A stationary boundary produced slow moving showers with flooding.', 'Flooding was reported on Crow Hill Drive.');
INSERT INTO public.stormevents_east VALUES (750455, 201805, 28, 1530, 201805, 28, 1540, 124768, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '28-MAY-18 15:30:00', 'EST-5', '28-MAY-18 15:40:00', 0, 0, 0, 0, '8.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'S', 'MC RAE', 0, 'NE', 'MC RAE', 32.0532, -82.9004, 32.0748, -82.8941, 'Strong thunderstorms associated with Tropical Storm Alberto resulted in isolated reports of damaging wind gusts across parts of north and central Georgia.', 'The Telfair County Emergency Manager reported numerous trees and some power lines blown down across McRae from East Willow Creek Lane northward across the town.');
INSERT INTO public.stormevents_east VALUES (749880, 201805, 29, 1720, 201805, 29, 1720, 125035, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '29-MAY-18 17:20:00', 'EST-5', '29-MAY-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 37, 'MG', NULL, NULL, 2, 'SSE', 'PLAYALINDA BEACH', 2, 'SSE', 'PLAYALINDA BEACH', 28.53, -80.77, 28.53, -80.77, 'East central Florida was sandwiched between a mid-level trough over the Gulf of Mexico and high pressure ridge extending from just east of the Bahamas extending well into the Great Lakes region. This set up brought a deep layer, moist, south-southwest flow into the region. Showers and thunderstorms developed across the area in the afternoon and pushed towards the east coast. One storm became strong and produced strong winds over Cape Canaveral and the adjacent intracoastal waters of Brevard County.', 'US Air Force wind tower 1007 measured a peak wind gust of 37 knots from the south-southwest.');
INSERT INTO public.stormevents_east VALUES (749883, 201805, 30, 1310, 201805, 30, 1310, 125036, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '30-MAY-18 13:10:00', 'EST-5', '30-MAY-18 13:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 45, 'MG', NULL, NULL, 16, 'N', 'PLAYALINDA BEACH', 16, 'N', 'PLAYALINDA BEACH', 28.7755, -80.8043, 28.7755, -80.8043, 'East central Florida remained sandwiched between a mid-level trough over the Gulf of Mexico and high pressure ridge extending from just east of the Bahamas extending well into the Great Lakes region. This set up brought a deep layer, moist, south-southwest flow into the region. Showers and thunderstorms developed across the area in the afternoon and pushed towards the east coast eventually becoming a consistent line. As these storms moved across the intracoastal and nearshore waters of Brevard County, they produced strong winds.', 'US Air Force wind tower 0421 measured a peak wind gust of 45 knots from the south-southwest.');
INSERT INTO public.stormevents_east VALUES (756730, 201805, 15, 1550, 201805, 15, 1550, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:50:00', 'EST-5', '15-MAY-18 15:50:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'SSW', 'WEST NYACK', 1, 'SSW', 'WEST NYACK', 41.08, -73.99, 41.08, -73.99, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A tree down on Kreuz Drive.');
INSERT INTO public.stormevents_east VALUES (756735, 201805, 15, 1603, 201805, 15, 1603, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:03:00', 'EST-5', '15-MAY-18 16:03:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'E', 'DOODLETOWN', 1, 'E', 'DOODLETOWN', 41.3, -73.98, 41.3, -73.98, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree fell on car on 9W just north of Iona Island in Bear Mountain State Park with no injuries.');
INSERT INTO public.stormevents_east VALUES (756739, 201805, 15, 1605, 201805, 15, 1605, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:05:00', 'EST-5', '15-MAY-18 16:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'NE', 'IRVINGTON', 1, 'NE', 'IRVINGTON', 41.04, -73.87, 41.04, -73.87, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'On Broadway Road near Route 9, large tree limbs and branches down.');
INSERT INTO public.stormevents_east VALUES (756745, 201805, 15, 1611, 201805, 15, 1611, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:11:00', 'EST-5', '15-MAY-18 16:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 1, 'E', 'LARCHMONT NORTH', 1, 'E', 'LARCHMONT NORTH', 40.93, -73.73, 40.93, -73.73, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 60 mile per hour gust was reported at Larchmont Harbor mesonet.');
INSERT INTO public.stormevents_east VALUES (756758, 201805, 15, 1618, 201805, 15, 1618, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:18:00', 'EST-5', '15-MAY-18 16:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 55, 'MG', NULL, NULL, 1, 'W', 'KINGS PT', 1, 'W', 'KINGS PT', 40.82, -73.74, 40.82, -73.74, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 63 mile per hour gust was reported at Kings Point mesonet.');
INSERT INTO public.stormevents_east VALUES (774587, 201807, 5, 1810, 201807, 5, 1930, 129265, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '05-JUL-18 18:10:00', 'EST-5', '05-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNW', 'MORRISVILLE', 3, 'N', 'MORRISVILLE', 35.86, -78.84, 35.8644, -78.8403, 'An inverted trough axis initiated early afternoon showers and storms along the NC coast which pushed inland thanks to weak onshore flow aloft. Aided and propagated by cold pool progression, a few of these storms became strong, producing heavy rainfall and flooding, along with frequent lightning strikes before dying off rapidly after sunset.', 'Chapel Hill Road was closed near the intersection of North Carolina Highway 54 due to flooding.');
INSERT INTO public.stormevents_east VALUES (774588, 201807, 5, 1730, 201807, 5, 1730, 129265, 'NORTH CAROLINA', 37, 2018, 'July', 'Lightning', 'RAH', '05-JUL-18 17:30:00', 'EST-5', '05-JUL-18 17:30:00', 1, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 3, 'W', 'GENLEE', 3, 'W', 'GENLEE', 35.8852, -78.927, 35.8852, -78.927, 'An inverted trough axis initiated early afternoon showers and storms along the NC coast which pushed inland thanks to weak onshore flow aloft. Aided and propagated by cold pool progression, a few of these storms became strong, producing heavy rainfall and flooding, along with frequent lightning strikes before dying off rapidly after sunset.', 'A 74 year old male was struck by lightning and injured at the Fairfield Swim and Tennis Club. The individual was seeking shelter from the storm under a tree and under his umbrella. The tree was also damage and the umbrella was left in tatters.');
INSERT INTO public.stormevents_east VALUES (774589, 201807, 11, 1602, 201807, 11, 1602, 129267, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '11-JUL-18 16:02:00', 'EST-5', '11-JUL-18 16:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WSW', 'CONCORD', 1, 'WSW', 'CONCORD', 36.443, -79.0838, 36.443, -79.0838, 'A pulse type thunderstorm developed in a moist and unstable atmosphere and briefly intensified, producing wind gust strong enough to down several trees across southwest Person County.', 'One tree was reported down in the 900 block of Concord Church Road.');
INSERT INTO public.stormevents_east VALUES (774590, 201807, 11, 1604, 201807, 11, 1604, 129267, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '11-JUL-18 16:04:00', 'EST-5', '11-JUL-18 16:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'S', 'LONGS STORE', 0, 'S', 'LONGS STORE', 36.4147, -79.0794, 36.4147, -79.0794, 'A pulse type thunderstorm developed in a moist and unstable atmosphere and briefly intensified, producing wind gust strong enough to down several trees across southwest Person County.', 'One tree was reported down in the 1000 block of Maurice Daniels Road.');
INSERT INTO public.stormevents_east VALUES (774591, 201807, 11, 1614, 201807, 11, 1614, 129267, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '11-JUL-18 16:14:00', 'EST-5', '11-JUL-18 16:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'LONGS STORE', 1, 'ENE', 'LONGS STORE', 36.4281, -79.0609, 36.4281, -79.0609, 'A pulse type thunderstorm developed in a moist and unstable atmosphere and briefly intensified, producing wind gust strong enough to down several trees across southwest Person County.', 'One tree was reported down on Brooks Dairy Road.');
INSERT INTO public.stormevents_east VALUES (774592, 201807, 11, 1625, 201807, 11, 1625, 129267, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '11-JUL-18 16:25:00', 'EST-5', '11-JUL-18 16:25:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NNE', 'LONGS STORE', 1, 'WSW', 'CONCORD', 36.433, -79.0699, 36.4422, -79.088, 'A pulse type thunderstorm developed in a moist and unstable atmosphere and briefly intensified, producing wind gust strong enough to down several trees across southwest Person County.', 'Several trees were reported down at the 1400 block of Brooks Dairy Road and the 2000 block of Maurice Daniels Road.');
INSERT INTO public.stormevents_east VALUES (783383, 201805, 15, 1556, 201805, 15, 1556, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:56:00', 'EST-5', '15-MAY-18 15:56:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 2, 'ENE', 'LAKESIDE', 2, 'ENE', 'LAKESIDE', 41.44, -73.2, 41.44, -73.2, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Several trees reported down on Cobbler Lane in Southbury.');
INSERT INTO public.stormevents_east VALUES (783387, 201805, 15, 1600, 201805, 15, 1600, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'SE', 'OXFORD', 1, 'SE', 'OXFORD', 41.42, -73.11, 41.42, -73.11, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree into house and numerous other trees down on Route 67.');
INSERT INTO public.stormevents_east VALUES (783389, 201805, 15, 1602, 201805, 15, 1602, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:02:00', 'EST-5', '15-MAY-18 16:02:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 2, 'SW', 'MIDDLEBURY', 2, 'SW', 'MIDDLEBURY', 41.5, -73.14, 41.5, -73.14, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees and wires down on Brookside Drive...including a tree down on a car.');
INSERT INTO public.stormevents_east VALUES (783391, 201805, 15, 1612, 201805, 15, 1612, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:12:00', 'EST-5', '15-MAY-18 16:12:00', 0, 0, 0, 0, '6.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'SW', 'WEST CHESHIRE', 1, 'SW', 'WEST CHESHIRE', 41.49, -72.93, 41.49, -72.93, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Multiple large trees down in the Deaconwood neighborhood along Sorghum Mill Drive.');
INSERT INTO public.stormevents_east VALUES (783421, 201805, 15, 1614, 201805, 15, 1614, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:14:00', 'EST-5', '15-MAY-18 16:14:00', 0, 0, 0, 0, '18.00K', '0.00K', 'Social Media', 70, 'EG', NULL, NULL, 0, 'N', 'MT CARMEL', 0, 'N', 'MT CARMEL', 41.42, -72.9, 41.42, -72.9, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous trees and branches down on the Quinnipiac University Campus.  Two cars also were damaged.');
INSERT INTO public.stormevents_east VALUES (783422, 201805, 15, 1614, 201805, 15, 1614, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:14:00', 'EST-5', '15-MAY-18 16:14:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Broadcast Media', 70, 'EG', NULL, NULL, 0, 'N', 'BETHANY', 0, 'N', 'BETHANY', 41.42, -73, 41.42, -73, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Two barns destroyed.');
INSERT INTO public.stormevents_east VALUES (783425, 201805, 15, 1615, 201805, 15, 1615, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:15:00', 'EST-5', '15-MAY-18 16:15:00', 1, 0, 0, 0, '10.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'E', 'EAST FARMS', 1, 'E', 'EAST FARMS', 41.5303, -72.9572, 41.5303, -72.9572, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Large tree fell on house, injuring one person.');
INSERT INTO public.stormevents_east VALUES (776993, 201807, 29, 1940, 201807, 29, 2229, 129725, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '29-JUL-18 19:40:00', 'EST-5', '29-JUL-18 22:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'ARCHDALE', 1, 'SSE', 'ARCHDALE', 35.91, -79.97, 35.9058, -79.9655, 'High precipitable waters of around 2.0 inches, from the combination of gulf Stream moisture from a Bermuda high and low level flow parallel to a front zone stalled across the region, resulted in heavy rainfall of 2 to 4 inches across central NC. The heaviest rain fell across Randolph County, causing flash flooding in the city of Archdale during the late evening hours.', 'Flash flooding was reported near the intersection of Archdale Road and Dale Street stranding 2 motor vehicles in the flood waters. Local Fire Department was deployed to respond.');
INSERT INTO public.stormevents_east VALUES (776994, 201807, 29, 2007, 201807, 29, 2207, 129725, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '29-JUL-18 20:07:00', 'EST-5', '29-JUL-18 22:07:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'FULLERS', 3, 'NW', 'FULLERS', 35.86, -80.04, 35.8586, -80.0384, 'High precipitable waters of around 2.0 inches, from the combination of gulf Stream moisture from a Bermuda high and low level flow parallel to a front zone stalled across the region, resulted in heavy rainfall of 2 to 4 inches across central NC. The heaviest rain fell across Randolph County, causing flash flooding in the city of Archdale during the late evening hours.', 'Heavy rainfall of 3 to 4 inches caused Little Uwharrie Creek to overflow it''s bank, flooding portions of Chapsworth Drive.');
INSERT INTO public.stormevents_east VALUES (753485, 201805, 3, 1809, 201805, 3, 1809, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:09:00', 'EST-5', '03-MAY-18 18:09:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 40, 'MG', NULL, NULL, 5, 'W', 'STAMFORD HARBOR', 5, 'W', 'STAMFORD HARBOR', 41.0302, -73.631, 41.0302, -73.631, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 40 knot gust was reported at the Greenwich mesonet location.');
INSERT INTO public.stormevents_east VALUES (757967, 201807, 4, 1405, 201807, 4, 1405, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 14:05:00', 'EST-5', '04-JUL-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'NW', 'SILER', 4, 'NW', 'SILER', 39.3897, -78.3033, 39.3897, -78.3033, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'A small tree was down in the 9500 block of Old Frederick Pike.');
INSERT INTO public.stormevents_east VALUES (757968, 201807, 4, 1420, 201807, 4, 1420, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 14:20:00', 'EST-5', '04-JUL-18 14:20:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SE', 'CAMP MAY FLATHER', 1, 'SE', 'CAMP MAY FLATHER', 38.3646, -79.1623, 38.3646, -79.1623, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Trees were down near the intersection of Tillman Road and Stokesville Road.');
INSERT INTO public.stormevents_east VALUES (757969, 201807, 4, 1517, 201807, 4, 1517, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 15:17:00', 'EST-5', '04-JUL-18 15:17:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'ALBIN', 1, 'SSW', 'ALBIN', 39.2121, -78.186, 39.2121, -78.186, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Numerous trees were down along North Frederick Pike.');
INSERT INTO public.stormevents_east VALUES (757970, 201807, 4, 1530, 201807, 4, 1530, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 15:30:00', 'EST-5', '04-JUL-18 15:30:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'COLUMBIA FURNACE', 1, 'W', 'COLUMBIA FURNACE', 38.867, -78.643, 38.867, -78.643, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Senedo Road was blocked by downed trees.');
INSERT INTO public.stormevents_east VALUES (757971, 201807, 4, 1552, 201807, 4, 1552, 126438, 'VIRGINIA', 51, 2018, 'July', 'Thunderstorm Wind', 'LWX', '04-JUL-18 15:52:00', 'EST-5', '04-JUL-18 15:52:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 52, 'EG', NULL, NULL, 1, 'NNE', 'READUS', 1, 'NNE', 'READUS', 38.865, -78.593, 38.865, -78.593, 'A hot and humid air mass led to an unstable atmosphere. A few storms became severe.', 'Part of a roof was blown off a house on Rittenour Road.');
INSERT INTO public.stormevents_east VALUES (758515, 201805, 16, 1400, 201805, 16, 1500, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 14:00:00', 'EST-5', '16-MAY-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'STEBY', 2, 'ESE', 'STEBY', 39.0725, -79.2028, 39.0732, -79.201, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'Lunice Creek was reported to be out of its banks.');
INSERT INTO public.stormevents_east VALUES (758516, 201805, 16, 1930, 201805, 16, 2100, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 19:30:00', 'EST-5', '16-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'ENGLE', 1, 'SE', 'ENGLE', 39.3403, -77.7646, 39.3402, -77.7638, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'The intersection of Bakerton Road and Engle Switch Road was flooded and closed.');
INSERT INTO public.stormevents_east VALUES (761266, 201805, 31, 1815, 201805, 31, 1915, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 18:15:00', 'EST-5', '31-MAY-18 19:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'SWINKS MILL', 1, 'NW', 'SWINKS MILL', 38.9588, -77.2058, 38.9566, -77.2059, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Georgetown Pike and Swinks Mill Road both flooded and closed.');
INSERT INTO public.stormevents_east VALUES (753471, 201805, 3, 1803, 201805, 3, 1803, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:03:00', 'EST-5', '03-MAY-18 18:03:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 48, 'MG', NULL, NULL, 1, 'W', 'STAMFORD HARBOR', 1, 'W', 'STAMFORD HARBOR', 41.0211, -73.5594, 41.0211, -73.5594, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 48 knot gust was reported at a mesonet site in Greenwich.');
INSERT INTO public.stormevents_east VALUES (761279, 201805, 31, 1822, 201805, 31, 1930, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '31-MAY-18 18:22:00', 'EST-5', '31-MAY-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'HARRISONBURG', 2, 'ESE', 'HARRISONBURG', 38.4376, -78.8445, 38.4373, -78.8437, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'About six inches of water flowing over Country Club Drive in the vicinity of a hotel.');
INSERT INTO public.stormevents_east VALUES (761282, 201805, 30, 2127, 201805, 30, 2300, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 21:27:00', 'EST-5', '30-MAY-18 23:00:00', 0, 0, 0, 0, '107.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BANCO', 0, 'SSE', 'BAUCO', 38.45, -78.3, 38.4472, -78.2779, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Major flooding occurred in the Banco, Syria, and Criglersville areas of Madison County.');
INSERT INTO public.stormevents_east VALUES (761283, 201805, 30, 2025, 201805, 30, 2200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 20:25:00', 'EST-5', '30-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'FARMINGTON', 2, 'NNE', 'FARMINGTON', 38.0745, -78.5321, 38.0744, -78.5316, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Barracks Road shut down due to a mudslide.');
INSERT INTO public.stormevents_east VALUES (754623, 201805, 12, 1941, 201805, 12, 2001, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 19:41:00', 'EST-5', '12-MAY-18 20:01:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 37 knots were reported at Tolly Point.');
INSERT INTO public.stormevents_east VALUES (754624, 201805, 12, 2000, 201805, 12, 2000, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 20:00:00', 'EST-5', '12-MAY-18 20:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 47, 'MG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'A wind gust of 47 knots was reported at Thomas Point.');
INSERT INTO public.stormevents_east VALUES (759305, 201805, 22, 1417, 201805, 22, 1854, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 14:17:00', 'EST-5', '22-MAY-18 18:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'WILLOW GROVE', 1, 'SSE', 'WILLOW GROVE', 38.8316, -78.552, 38.8156, -78.5254, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'The stream gage on the North Fork Shenandoah River at Burnshire Dam exceeded the 13 foot flood stage during the indicated times. The peak value of 14.20 feet occurred at 3:44pm EST on May 22nd. Numerous bridges and roads were flooded in the section of the river between Woodstock and Strasburg.');
INSERT INTO public.stormevents_east VALUES (761293, 201805, 30, 2213, 201805, 31, 700, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 22:13:00', 'EST-5', '31-MAY-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'ADVANCE MILLS', 1, 'ENE', 'ADVANCE MILLS', 38.183, -78.441, 38.1822, -78.4381, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The stream gage on the North Fork Rivanna River near Earlysville rapidly exceeded the 14 foot flood stage during the times indicated. The peak value was estimated at 21.89 feet. Significant flooding occurred in northern Albemarle County.');
INSERT INTO public.stormevents_east VALUES (761294, 201805, 31, 700, 201805, 31, 1038, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 07:00:00', 'EST-5', '31-MAY-18 10:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'ADVANCE MILLS', 1, 'ENE', 'ADVANCE MILLS', 38.1842, -78.4407, 38.1842, -78.4387, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The stream gage on the North Fork Rivanna River near Earlysville remained above the 14 foot flood stage during the times indicated. Flooding of a bridge in the area was reported.');
INSERT INTO public.stormevents_east VALUES (776053, 201807, 22, 1905, 201807, 22, 1905, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 19:05:00', 'EST-5', '22-JUL-18 19:05:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NNE', 'LINWOOD', 1, 'NNE', 'LINWOOD', 35.7607, -80.3135, 35.7607, -80.3135, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Trees were reported down in Linwood.');
INSERT INTO public.stormevents_east VALUES (776054, 201807, 22, 1905, 201807, 22, 1905, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 19:05:00', 'EST-5', '22-JUL-18 19:05:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'NE', 'TYRO', 1, 'NE', 'TYRO', 35.81, -80.37, 35.81, -80.37, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Trees were reported down near Tyro.');
INSERT INTO public.stormevents_east VALUES (771154, 201806, 6, 1549, 201806, 6, 1549, 128490, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MFL', '06-JUN-18 15:49:00', 'EST-5', '06-JUN-18 15:49:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Social Media', 43, 'EG', NULL, NULL, 7, 'W', 'BOCA RATON', 7, 'W', 'BOCA RATON', 26.34, -80.19, 26.34, -80.19, 'Abundant moisture and a weak frontal boundary across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. Strong storms that developed across Palm Beach County during the evening hours produced small hail and damaging wind gusts.', 'WPTV shared photos via social media of a loosely constructed roof partially blown off and fence damaged from high winds in the pool area located in the Dunes of Boca neighborhood east of US 441 and just north of the Broward and Palm Beach county line. Time is estimated via radar. Mesonet and radar indicates winds in the area were around 50 mph.');
INSERT INTO public.stormevents_east VALUES (771158, 201806, 7, 1320, 201806, 7, 1320, 128492, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MFL', '07-JUN-18 13:20:00', 'EST-5', '07-JUN-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 60, 'MG', NULL, NULL, 1, 'W', 'HOLLYWOOD N PERRY AR', 1, 'W', 'HOLLYWOOD N PERRY AR', 26.0012, -80.2398, 26.0012, -80.2398, 'Abundant moisture, an upper level trough, and a lingering weak boundary across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. Severe storms that developed across Broward County during the early afternoon hours produced small hail and damaging wind gusts.', 'North Perry Airport ASOS gusted to 69 mph/60 knots. Nearby mesonet observations reported gusts of 55 to 60 mph with a trained spotter also reporting pea sized hail in the vicinity.');
INSERT INTO public.stormevents_east VALUES (771155, 201806, 6, 1551, 201806, 6, 1551, 128490, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'MFL', '06-JUN-18 15:51:00', 'EST-5', '06-JUN-18 15:51:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Social Media', 43, 'EG', NULL, NULL, 6, 'W', 'BOCA RATON', 6, 'W', 'BOCA RATON', 26.3364, -80.1821, 26.3364, -80.1821, 'Abundant moisture and a weak frontal boundary across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. Strong storms that developed across Palm Beach County during the evening hours produced small hail and damaging wind gusts.', 'CBS12 shared photos via social media of an uprooted tree in West Boca near the intersection of 12th Street and 54th Avenue. Residents also reported hail of unknown size. Time is estimated by radar. Mesonet and radar indicate winds in the area were around 50 mph.');
INSERT INTO public.stormevents_east VALUES (771157, 201806, 7, 1342, 201806, 7, 1342, 128491, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '07-JUN-18 13:42:00', 'EST-5', '07-JUN-18 13:42:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 36, 'MG', NULL, NULL, 10, 'SSE', 'PORT OF PALM BEACH', 10, 'SSE', 'PORT OF PALM BEACH', 26.6127, -80.0351, 26.6127, -80.0351, 'Abundant moisture, an upper level trough, and a lingering weak boundary across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 40 mph/36 knots at a mesonet site on Lake Worth Pier/LKWF1.');
INSERT INTO public.stormevents_east VALUES (771189, 201806, 15, 1615, 201806, 15, 1615, 128503, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '15-JUN-18 16:15:00', 'EST-5', '15-JUN-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 5, 'NW', 'KREAMER ISLAND', 5, 'NW', 'KREAMER ISLAND', 26.82, -80.78, 26.82, -80.78, 'Deep tropical moisture lead to the development of showers and storms across South Florida during the late morning and afternoon hours. Boundary collisions between the Lake Okeechobee breeze and ongoing storms led to additional strong storms producing wind gusts across the lake.', 'SFWMD mesonet site L006 on the south end of Lake Okeechobee recorded a wind gust to 35 knots / 40 mph.');
INSERT INTO public.stormevents_east VALUES (770925, 201806, 19, 907, 201806, 19, 912, 128505, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'MFL', '19-JUN-18 09:07:00', 'EST-5', '19-JUN-18 09:12:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', NULL, NULL, NULL, NULL, 5, 'ESE', 'MIAMI BEACH', 5, 'ESE', 'MIAMI BEACH', 25.78, -80.05, 25.78, -80.05, 'A waterspout developed with late morning showers and storms off the Miami-Dade County coast.', 'Off-duty NWS employee reported a waterspout off Miami Beach starting around 1007 am EDT/907 am EST and dissipating around 1012 am EDT/912 am EST.');
INSERT INTO public.stormevents_east VALUES (771196, 201806, 23, 1610, 201806, 23, 1610, 128506, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '23-JUN-18 16:10:00', 'EST-5', '23-JUN-18 16:10:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 3, 'W', 'KEY BISCAYNE', 3, 'W', 'KEY BISCAYNE', 25.777, -80.198, 25.777, -80.198, 'Showers and storms developed along the Gulf and Atlantic seabreezes during the late morning and afternoon hours across South Florida. Boundary collisions lead to some of these storms moving off the east coast, producing strong wind gusts as they moved into the local Atlantic.', 'A marine thunderstorm wind gust of 39 mph/34 knots was measured at the City of Miami PD Station, site MDFR22 in Downtown Miami.');
INSERT INTO public.stormevents_east VALUES (771197, 201806, 23, 1621, 201806, 23, 1621, 128506, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '23-JUN-18 16:21:00', 'EST-5', '23-JUN-18 16:21:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 6, 'SW', 'KEY BISCAYNE', 6, 'SW', 'KEY BISCAYNE', 25.71, -80.21, 25.71, -80.21, 'Showers and storms developed along the Gulf and Atlantic seabreezes during the late morning and afternoon hours across South Florida. Boundary collisions lead to some of these storms moving off the east coast, producing strong wind gusts as they moved into the local Atlantic.', 'A marine thunderstorm wind gust of 42 mph/36 knots was measured at the WxFlow site XDIN in Biscayne Bay.');
INSERT INTO public.stormevents_east VALUES (771201, 201806, 28, 1736, 201806, 28, 1736, 128508, 'FLORIDA', 12, 2018, 'June', 'Flood', 'MFL', '28-JUN-18 17:36:00', 'EST-5', '28-JUN-18 17:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'SWEET WATER', 2, 'WSW', 'SWEET WATER', 25.7827, -80.3939, 25.7615, -80.3933, 'Showers and storms developed along the Gulf and Atlantic seabreezes during the late morning and afternoon hours across South Florida. Several rounds of storms affected the east coast metro, producing street flooding across portions of Miami-Dade County.', 'Photos relayed from Twitter show flooded roadways along SW 122nd Avenue from NW 12th Street to SW 8th Street in Miami. Some cars are also stalled out in the roadway.');
INSERT INTO public.stormevents_east VALUES (772205, 201807, 27, 1407, 201807, 27, 1407, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 14:07:00', 'EST-5', '27-JUL-18 14:07:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 48, 'MG', NULL, NULL, 1, 'NNW', 'BABAR POINT (BAB)', 1, 'NNW', 'BABAR POINT (BAB)', 38.32, -77.037, 38.32, -77.037, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'A wind gust of 48 knots were reported at Baber Point.');
INSERT INTO public.stormevents_east VALUES (772225, 201807, 27, 1600, 201807, 27, 1600, 128758, 'ATLANTIC NORTH', 88, 2018, 'July', 'Marine Thunderstorm Wind', 'LWX', '27-JUL-18 16:00:00', 'EST-5', '27-JUL-18 16:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A cold front passed through the area on the 27th. Ahead of the boundary, a southerly flow led to plenty of moisture an unstable atmosphere. A potent upper-level low caused stronger winds aloft as well. Some thunderstorms associated with the cold front produced gusty winds due to the instability and stronger winds aloft.', 'Wind gusts in excess of 30 knots were reported at Thomas Point Lighthouse.');
INSERT INTO public.stormevents_east VALUES (750805, 201805, 27, 656, 201805, 27, 656, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 06:56:00', 'EST-5', '27-MAY-18 06:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 37, 'MG', NULL, NULL, 7, 'N', 'CAPE CANAVERAL', 7, 'N', 'CAPE CANAVERAL', 28.477, -80.594, 28.477, -80.594, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'The AWOS at the Cape Canaveral Air Force Station Skid Strip, KXMR, measured a peak wind gust of 37 knots from the south.');
INSERT INTO public.stormevents_east VALUES (749882, 201805, 30, 1319, 201805, 30, 1319, 125036, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '30-MAY-18 13:19:00', 'EST-5', '30-MAY-18 13:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 27.3452, -80.2364, 27.3452, -80.2364, 'East central Florida remained sandwiched between a mid-level trough over the Gulf of Mexico and high pressure ridge extending from just east of the Bahamas extending well into the Great Lakes region. This set up brought a deep layer, moist, south-southwest flow into the region. Showers and thunderstorms developed across the area in the afternoon and pushed towards the east coast eventually becoming a consistent line. As these storms moved across the intracoastal and nearshore waters of Brevard County, they produced strong winds.', 'Weatherflow site XSTL at the St. Lucie Nuclear Power Plant measured a peak wind gust of 36 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (774300, 201807, 2, 1500, 201807, 2, 1500, 129211, 'VIRGINIA', 51, 2018, 'July', 'Lightning', 'RNK', '02-JUL-18 15:00:00', 'EST-5', '02-JUL-18 15:00:00', 0, 0, 0, 0, '50.00K', NULL, 'Newspaper', NULL, NULL, NULL, NULL, 1, 'ESE', 'COLING', 1, 'ESE', 'COLING', 37.3758, -79.8852, 37.3758, -79.8852, 'Isolated showers and storms developed with a hot and humid summer air mass across the region. One of these storms increased to severe levels and produced damaging winds near Bluefield, VA.  Another thunderstorm, while not severe, produced lightning that struck a shed in Troutdale, VA, setting it on fire causing total loss of the structure.', 'Lightning was the probable cause for a fire that destroyed a shed within the 100 block of Ottaway Road in Troutdale.  The shed housed a chicken coop, and all birds escaped unharmed. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (771190, 201806, 15, 1615, 201806, 15, 1615, 128503, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '15-JUN-18 16:15:00', 'EST-5', '15-JUN-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 7, 'S', 'PORT MAYACA', 7, 'S', 'PORT MAYACA', 26.9, -80.79, 26.9, -80.79, 'Deep tropical moisture lead to the development of showers and storms across South Florida during the late morning and afternoon hours. Boundary collisions between the Lake Okeechobee breeze and ongoing storms led to additional strong storms producing wind gusts across the lake.', 'SFWMD mesonet site LZ40 in the center of Lake Okeechobee recorded a wind gust to 36 knots / 41 mph.');
INSERT INTO public.stormevents_east VALUES (776215, 201807, 21, 2214, 201807, 22, 423, 128274, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '21-JUL-18 22:14:00', 'EST-5', '22-JUL-18 04:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'ARUNDEL GARDENS', 0, 'ESE', 'GLEN BURNIE', 39.1831, -76.6141, 39.1696, -76.6288, 'A coastal low pressure moved up the Atlantic seaboard. Copious moisture spread northward across much of North Central and Northeast Maryland. Rainfall totals of 3 to 6 inches were widespread, with isolated higher amounts, causing fairly widespread flooding.', 'The USGS stream gage on Sawmill Creek at Glen Burnie exceeded the 5 foot flood stage during the indicated period. The peak level of 6.80 feet occurred at 11:45pm EST. Central Avenue was flooded. For a portion of the time, near the peak, Crain Highway was reported flooded and closed at Sawmill Creek, and water covered the Northwest Baltimore and Annapolis Trail.');
INSERT INTO public.stormevents_east VALUES (774678, 201807, 24, 27, 201807, 24, 449, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 00:27:00', 'EST-5', '24-JUL-18 04:49:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'OREGON', 1, 'NNE', 'OREGON', 39.5108, -76.6776, 39.5104, -76.6773, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'Western Run Road flooded and closed at Western Run. The USGS stream gage on Western Run at this location exceeded the 8 foot flood stage during the indicated period. The peak level of 11.35 feet occurred at 2:00am EST.');
INSERT INTO public.stormevents_east VALUES (748011, 201804, 10, 1354, 201804, 10, 1354, 124664, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'MLB', '10-APR-18 13:54:00', 'EST-5', '10-APR-18 13:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 27.3452, -80.2364, 27.3452, -80.2364, 'A nearly stationary front was located just north of east central Florida. Cloud cover across the northern areas of east central Florida kept the atmosphere more stable and only scattered showers and a few storms developed. However, from Brevard County south through the Treasure Coast saw extensive daytime heating and this allowed for widespread showers and storms to develop along the many outflow boundaries present across the area. As storms moved back towards the coast, several produced strong winds along the Brevard, Indian River and St. Lucie county coasts.', 'A Weatherflow site at the St. Lucie Nuclear Power Plant, XSTL, measured a peak wind gust of 35 knots from the northwest.');
INSERT INTO public.stormevents_east VALUES (773091, 201809, 8, 1600, 201809, 8, 1700, 128927, 'OHIO', 39, 2018, 'September', 'Flood', 'ILN', '08-SEP-18 16:00:00', 'EST-5', '08-SEP-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'ROSEMOUNT', 0, 'SW', 'ROSEMOUNT', 38.7768, -82.9862, 38.778, -82.9835, 'Showers with embedded thunderstorms spread into the area through the day as remnants from Tropical Storm Gordon approached from the west.', 'U.S. route 23 was down to one lane due to high water on the roadway between Lowry Hollow Road and Scioto Train Road.');
INSERT INTO public.stormevents_east VALUES (773098, 201809, 9, 630, 201809, 9, 930, 128930, 'OHIO', 39, 2018, 'September', 'Flood', 'ILN', '09-SEP-18 06:30:00', 'EST-5', '09-SEP-18 09:30:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'SSE', 'GATH', 2, 'SSE', 'GATH', 39.04, -83.81, 39.0446, -83.8086, 'Widespread rain and a few embedded thunderstorms moved through the Ohio Valley in association with the remnants of Tropical Storm Gordon.', 'Several roads were closed in Highland County due to high water. A person had to be rescued from a stranded vehicle on Gath Road.');
INSERT INTO public.stormevents_east VALUES (774004, 201809, 3, 1449, 201809, 3, 1449, 129142, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Marine Thunderstorm Wind', 'MLB', '03-SEP-18 14:49:00', 'EST-5', '03-SEP-18 14:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 3, 'WSW', 'CAPE CANAVERAL', 3, 'WSW', 'CAPE CANAVERAL', 28.36, -80.65, 28.36, -80.65, 'Numerous rainbands containing strong wind gusts rotated onshore the coast, well to the north of the center of Tropical Storm Gordon which moved west across the extreme southern tip of Florida during the day.', 'A Weatherflow site in the Banana River just south of the State Road 520 Causeway recorded a peak wind of 36 knots from the southeast as a tropical rainband spread onshore.');
INSERT INTO public.stormevents_east VALUES (786814, 201809, 18, 1357, 201809, 18, 1700, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 13:57:00', 'EST-5', '18-SEP-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 4, 'NNW', 'LONG POND', 4, 'NNW', 'LONG POND', 41.9073, -70.6391, 41.9105, -70.6436, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 1:57 PM EST, Long Pond Road north of Gunners Exchange Road in Plymouth was flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (786845, 201809, 25, 1950, 201809, 25, 2335, 131526, 'CONNECTICUT', 9, 2018, 'September', 'Flood', 'BOX', '25-SEP-18 19:50:00', 'EST-5', '25-SEP-18 23:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'PERKINS CORNER', 1, 'SW', 'PERKINS CORNER', 41.7189, -72.2607, 41.7173, -72.2678, 'A warm front approached from the south on Sept 25 and stalled just north of Massachusetts on Sept 26. This brought periods of heavy rain to Connecticut with 3 to 6 inches observed over Northeast Connecticut and 1 to 3 inches in Hartford County.', 'At 7:50 PM EST, State Route 66 near Columbia Motorsports in Columbia was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786865, 201809, 21, 2034, 201809, 21, 2300, 131484, 'NEW YORK', 36, 2018, 'September', 'Flash Flood', 'BGM', '21-SEP-18 20:34:00', 'EST-5', '21-SEP-18 23:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'NICHOLS', 2, 'ENE', 'NICHOLS', 42, -77.24, 42.0052, -77.2397, 'A warm front lifting across Northeast Pennsylvania and Central New York was the focus for several rounds of thunderstorm activity within a very warm and humid airmass. Slow moving, heavy rain producing thunderstorms contributed to several areas of minor flooding, along with, more serious flash flooding.', 'Two elderly people were trapped in a house surrounded by rushing water.');
INSERT INTO public.stormevents_east VALUES (775230, 201808, 2, 1326, 201808, 2, 1526, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 13:26:00', 'EST-5', '02-AUG-18 15:26:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CALVERTON', 1, 'SE', 'CALVERTON', 38.62, -77.66, 38.6198, -77.6584, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Bristersburg Road was closed near Licking Run due to flooding.');
INSERT INTO public.stormevents_east VALUES (775231, 201808, 2, 1343, 201808, 2, 1543, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 13:43:00', 'EST-5', '02-AUG-18 15:43:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'W', 'ADEN', 3, 'W', 'ADEN', 38.65, -77.59, 38.649, -77.5903, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Hazelwood Drive was closed due to flooding at Carriage Ford Road.');
INSERT INTO public.stormevents_east VALUES (775232, 201808, 2, 1346, 201808, 2, 1546, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 13:46:00', 'EST-5', '02-AUG-18 15:46:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'NOKESVILLE', 2, 'W', 'NOKESVILLE', 38.69, -77.62, 38.6936, -77.6235, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Reid lane road was closed due to flooding at Fauquier Drive.');
INSERT INTO public.stormevents_east VALUES (775233, 201808, 2, 1441, 201808, 2, 1641, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 14:41:00', 'EST-5', '02-AUG-18 16:41:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BRENTSVILLE', 0, 'W', 'BRENTSVILLE', 38.68, -77.51, 38.68, -77.5075, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Old Church Road was closed at Slate Run Bridge due to high water.');
INSERT INTO public.stormevents_east VALUES (775234, 201808, 2, 1646, 201808, 2, 1846, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 16:46:00', 'EST-5', '02-AUG-18 18:46:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BURKE', 1, 'SSE', 'BURKE', 38.7887, -77.2661, 38.7887, -77.2662, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Burke Road was closed due to flooding at Heritage Square Drive.');
INSERT INTO public.stormevents_east VALUES (778477, 201808, 21, 1800, 201808, 21, 2000, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 18:00:00', 'EST-5', '21-AUG-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'BERKELEY SPGS', 1, 'ESE', 'BERKELEY SPGS', 39.6268, -78.2278, 39.6258, -78.2153, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Martinsburg Road was closed due to flooding. Parts of Washington Street was closed and Widmyer Circle was also closed at Myers Road. The 50 block of Broadway Street was closed and the 100 Block of Mercer Street was also closed due to high water. The 1600 Block of Valley Road was closed due to flooding and Keystone Lane at Biser Street was also closed. A landslide was reported near the 1200 Block of Valley road.');
INSERT INTO public.stormevents_east VALUES (781684, 201808, 21, 2154, 201808, 22, 225, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:54:00', 'EST-5', '22-AUG-18 02:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'INWOOD', 1, 'SW', 'INWOOD', 39.3406, -78.0625, 39.3404, -78.0611, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The USGS stream gage on Mill Creek near Bunker Hill exceeded the 4.25 foot flood stage during the indicated period. The peak level of 4.61 feet occurred at midnight EST. Henshaw Road was flooded overnight.');
INSERT INTO public.stormevents_east VALUES (781721, 201808, 21, 1642, 201808, 21, 1900, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'LWX', '21-AUG-18 16:42:00', 'EST-5', '21-AUG-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BERKELEY SPGS', 0, 'S', 'BERKELEY SPGS', 39.6182, -78.2316, 39.6232, -78.2315, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The USGS stream gage on Warm Springs Run near Berkeley Springs exceeded the 5 foot flood stage rapidly during the indicated period, going from low water to flood stage in an hour. Video from 5:03pm EST shows water flowing over a roadway, with flooding also reported at Berkeley Springs State Park and in the back parking lot of the high school. The peak level of 5.97 feet occurred at 6:00pm EST. Flooding continued beyond this time as the stream level remained high.');
INSERT INTO public.stormevents_east VALUES (778466, 201808, 21, 2032, 201808, 21, 2232, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 20:32:00', 'EST-5', '21-AUG-18 22:32:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'EMMITSBURG', 0, 'NNE', 'EMMITSBURG', 39.7044, -77.327, 39.7044, -77.3268, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Seton Avenue in Emmitsburg was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (778467, 201808, 21, 2117, 201808, 21, 2317, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:17:00', 'EST-5', '21-AUG-18 23:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'STREET', 2, 'SSE', 'STREET', 39.6468, -76.361, 39.646, -76.3608, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'High water covered the roadway near the intersection of Cherry Hill Road and Burkins Road.');
INSERT INTO public.stormevents_east VALUES (778468, 201808, 21, 2228, 201808, 22, 28, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 22:28:00', 'EST-5', '22-AUG-18 00:28:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'PYLESVILLE', 1, 'SSW', 'PYLESVILLE', 39.6883, -76.3737, 39.688, -76.3741, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'A vehicle was stranded in high water and there was flooding into a house near the intersection of Ridge Road and Old Pylesville Road.');
INSERT INTO public.stormevents_east VALUES (778469, 201808, 21, 2230, 201808, 22, 30, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 22:30:00', 'EST-5', '22-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'CEDARHURST', 1, 'ESE', 'CEDARHURST', 39.496, -76.8685, 39.4974, -76.8704, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Hollingsworth Road was closed near Glen Falls Road.');
INSERT INTO public.stormevents_east VALUES (774926, 201808, 1, 400, 201808, 1, 600, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 04:00:00', 'EST-5', '01-AUG-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'MERRIFIELD', 1, 'SW', 'MERRIFIELD', 38.8549, -77.2474, 38.8542, -77.2446, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Prosperity Avenue closed over Accotink Creek due to flooding.');
INSERT INTO public.stormevents_east VALUES (798432, 201812, 20, 1715, 201812, 20, 1717, 133442, 'NORTH CAROLINA', 37, 2018, 'December', 'Thunderstorm Wind', 'ILM', '20-DEC-18 17:15:00', 'EST-5', '20-DEC-18 17:17:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 2, 'SE', 'WILMINGTON', 2, 'SE', 'WILMINGTON', 34.21, -77.91, 34.21, -77.91, 'A strong tunderstorm produced damage in Wilmington NC.', 'A tree was blown down on Waltmoor Rd.  A power pole was snapped at the corner of Bethel and Amber Rd.');
INSERT INTO public.stormevents_east VALUES (798668, 201812, 28, 1508, 201812, 28, 1510, 133488, 'SOUTH CAROLINA', 45, 2018, 'December', 'Thunderstorm Wind', 'ILM', '28-DEC-18 15:08:00', 'EST-5', '28-DEC-18 15:10:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 2, 'NW', 'FULTON', 2, 'NW', 'FULTON', 34.79, -79.8, 34.79, -79.8, 'A stationary frontal boundary produced a strong storm.', 'Several trees were snapped with large limbs blown down. There was roof damage to several old sheds/buildings.');
INSERT INTO public.stormevents_east VALUES (775019, 201808, 7, 1505, 201808, 7, 1505, 129347, 'DISTRICT OF COLUMBIA', 11, 2018, 'August', 'Thunderstorm Wind', 'LWX', '07-AUG-18 15:05:00', 'EST-5', '07-AUG-18 15:05:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'WALTER REED', 0, 'N', 'WALTER REED', 38.986, -77.03, 38.986, -77.03, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which became severe.', 'A tree was blown down in the 1300 block of Leegate Road.');
INSERT INTO public.stormevents_east VALUES (775076, 201808, 12, 1405, 201808, 12, 1405, 129353, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '12-AUG-18 14:05:00', 'EST-5', '12-AUG-18 14:05:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 3, 'ESE', 'MADISON RUN', 3, 'ESE', 'MADISON RUN', 38.1799, -78.0891, 38.1799, -78.0891, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms became severe.', 'A tree was blown down into power lines and blocked the roadway.');
INSERT INTO public.stormevents_east VALUES (775092, 201808, 13, 1450, 201808, 13, 1450, 129355, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '13-AUG-18 14:50:00', 'EST-5', '13-AUG-18 14:50:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'CANOVA', 1, 'WSW', 'CANOVA', 38.67, -77.45, 38.67, -77.45, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms became severe.', 'Six trees were blown down across the 8100 block of Counselor Road.');
INSERT INTO public.stormevents_east VALUES (775419, 201808, 3, 2027, 201808, 3, 2227, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 20:27:00', 'EST-5', '03-AUG-18 22:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 53, 'W', 'BULL RUN', 55, 'W', 'BULL RUN', 38.8598, -78.4726, 38.8675, -78.4998, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Lupton Road was closed due to flooding up till French Woods Road.');
INSERT INTO public.stormevents_east VALUES (761222, 201805, 22, 1724, 201805, 22, 1724, 127009, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:24:00', 'EST-5', '22-MAY-18 17:24:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', 55, 'EG', NULL, NULL, 2, 'SSW', 'NEWELL', 2, 'SSW', 'NEWELL', 40.59, -80.58, 40.59, -80.58, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Emergency manager reported power lines and at least 30 trees down along Allison Road.');
INSERT INTO public.stormevents_east VALUES (761240, 201805, 16, 2155, 201805, 16, 2345, 127004, 'PENNSYLVANIA', 42, 2018, 'May', 'Flash Flood', 'PBZ', '16-MAY-18 21:55:00', 'EST-5', '16-MAY-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'COLLINSBURG', 1, 'WSW', 'LOWBER', 40.2371, -79.8027, 40.245, -79.7824, 'In an environment with weak winds aloft, an isolated thunderstorm developed over eastern sections of Allegheny county. This produced significant flash flooding along Route 51 and the Baldwin area. Numerous roads were closed with a video of a dumpster floating down State Route 51. Rainfall amounts ranged from 2.43 in Mount Oliver to a trace at Pittsburgh International Airport.', 'County official reported that Plummer School Road was closed due to high water. Also, three feet of water was reported in some homes in Hutchinson. A woman had to be rescued from her vehicle near Sutersville.');
INSERT INTO public.stormevents_east VALUES (761243, 201805, 16, 1920, 201805, 16, 2100, 127004, 'PENNSYLVANIA', 42, 2018, 'May', 'Flash Flood', 'PBZ', '16-MAY-18 19:20:00', 'EST-5', '16-MAY-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'WHITEHALL', 1, 'ESE', 'SYGAN', 40.3381, -79.9789, 40.3467, -80.109, 'In an environment with weak winds aloft, an isolated thunderstorm developed over eastern sections of Allegheny county. This produced significant flash flooding along Route 51 and the Baldwin area. Numerous roads were closed with a video of a dumpster floating down State Route 51. Rainfall amounts ranged from 2.43 in Mount Oliver to a trace at Pittsburgh International Airport.', 'State official reported several roads closed in and around Mount Lebanon, Bethel Park, Castle Shannon, and Bridgeville including Library Road, Becks Run Road, Route 51 and Route 88, and Brownsville Road.');
INSERT INTO public.stormevents_east VALUES (750460, 201805, 28, 2110, 201805, 28, 2120, 124768, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '28-MAY-18 21:10:00', 'EST-5', '28-MAY-18 21:20:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 40, 'EG', NULL, NULL, 3, 'ESE', 'MURRAYVILLE', 3, 'ESE', 'MURRAYVILLE', 34.4079, -83.8558, 34.4079, -83.8558, 'Strong thunderstorms associated with Tropical Storm Alberto resulted in isolated reports of damaging wind gusts across parts of north and central Georgia.', 'The Hall County Emergency Manager reported a tree blown down across Buckhorn Road.');
INSERT INTO public.stormevents_east VALUES (761223, 201805, 22, 1726, 201805, 22, 1726, 127009, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:26:00', 'EST-5', '22-MAY-18 17:26:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Department of Highways', 52, 'EG', NULL, NULL, 2, 'NNE', 'PUGHTOWN', 2, 'NNE', 'PUGHTOWN', 40.56, -80.56, 40.56, -80.56, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State Department of Highways reported numerous trees down by very high wind in the area of Locust Hill Road.');
INSERT INTO public.stormevents_east VALUES (761224, 201805, 22, 1730, 201805, 22, 1730, 127009, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:30:00', 'EST-5', '22-MAY-18 17:30:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SE', 'NEWELL', 1, 'SE', 'NEWELL', 40.61, -80.56, 40.61, -80.56, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Citizen on social media reported numerous trees down.');
INSERT INTO public.stormevents_east VALUES (750457, 201805, 28, 2032, 201805, 28, 2042, 124768, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '28-MAY-18 20:32:00', 'EST-5', '28-MAY-18 20:42:00', 0, 0, 0, 0, '10.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'ENE', 'HURRICANE SHOALS', 2, 'NNW', 'DRY POND', 34.2111, -83.4923, 34.2227, -83.6126, 'Strong thunderstorms associated with Tropical Storm Alberto resulted in isolated reports of damaging wind gusts across parts of north and central Georgia.', 'The Jackson County 911 center reported a few trees down between Commerce and Maysville, along Red Oak Road and Woods Bridge Road.');
INSERT INTO public.stormevents_east VALUES (750458, 201805, 28, 2018, 201805, 28, 2022, 124768, 'GEORGIA', 13, 2018, 'May', 'Thunderstorm Wind', 'FFC', '28-MAY-18 20:18:00', 'EST-5', '28-MAY-18 20:22:00', 0, 0, 0, 0, '3.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 4, 'NNE', 'HOG MTN', 4, 'NNE', 'HOG MTN', 34.097, -83.9045, 34.097, -83.9045, 'Strong thunderstorms associated with Tropical Storm Alberto resulted in isolated reports of damaging wind gusts across parts of north and central Georgia.', 'The Gwinnett County Emergency Manager reported trees blown down across Tuggle Road between West Rock Quarry Road and Kay Morgan Road.');
INSERT INTO public.stormevents_east VALUES (756760, 201805, 15, 1620, 201805, 15, 1620, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:20:00', 'EST-5', '15-MAY-18 16:20:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Amateur Radio', 61, 'EG', NULL, NULL, 1, 'W', 'CENTRAL PARK', 1, 'W', 'CENTRAL PARK', 40.78, -73.97, 40.78, -73.97, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down along the Hudson River Drive at 158th Street.  Boat basin area lanes blocked.');
INSERT INTO public.stormevents_east VALUES (756763, 201805, 15, 1625, 201805, 15, 1625, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:25:00', 'EST-5', '15-MAY-18 16:25:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 2, 'WNW', 'CENTRAL PARK', 2, 'WNW', 'CENTRAL PARK', 40.79, -73.98, 40.79, -73.98, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A tree down.');
INSERT INTO public.stormevents_east VALUES (756765, 201805, 15, 1625, 201805, 15, 1625, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:25:00', 'EST-5', '15-MAY-18 16:25:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 1, 'NNW', 'CENTRAL PARK', 1, 'NNW', 'CENTRAL PARK', 40.8, -73.96, 40.8, -73.96, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Large tree limb down.');
INSERT INTO public.stormevents_east VALUES (755324, 201807, 2, 1910, 201807, 2, 1910, 125998, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '02-JUL-18 19:10:00', 'EST-5', '02-JUL-18 19:10:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'NE', 'HICKORY STAR LNDG', 1, 'NE', 'HICKORY STAR LNDG', 36.29, -83.81, 36.29, -83.81, 'A few thunderstorms became severe over the higher terrain on the Northern Cumberland Plateau and a small part of Southwest Virginia during the evening hours. The storms produced wind damage and some flooding.', 'A barn with a metal roof and a three sided carport was destroyed on Hickory Valley Road. |Additionally, siding was torn off a home and several trees were downed in the area.');
INSERT INTO public.stormevents_east VALUES (760490, 201807, 4, 1737, 201807, 4, 1737, 126499, 'WEST VIRGINIA', 54, 2018, 'July', 'Thunderstorm Wind', 'RLX', '04-JUL-18 17:37:00', 'EST-5', '04-JUL-18 17:37:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 0, 'ENE', 'DANVILLE', 0, 'ENE', 'DANVILLE', 38.083, -81.8218, 38.083, -81.8218, 'Thunderstorms developed in a hot and humid airmass on the 4th, 5th and 6th. Some of these storms became severe, causing wind damage. One house was also struck by lightning. Minor flooding also resulted from slow storm movement.', 'A tree was blown down along Price Branch Road near Danville.');
INSERT INTO public.stormevents_east VALUES (760494, 201807, 15, 1630, 201807, 15, 1930, 126868, 'WEST VIRGINIA', 54, 2018, 'July', 'Flash Flood', 'RLX', '15-JUL-18 16:30:00', 'EST-5', '15-JUL-18 19:30:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'DRYFORK', 2, 'WSW', 'HARMAN', 38.9569, -79.5204, 38.9085, -79.5558, 'Showers and thunderstorms formed on the 15th as a series of upper level shortwave troughs moved over the central Appalachians. One of the storms produced wind damage, while the slow movement of another led to flash flooding.', 'Flooding along Dry Fork and Horsecamp Run closed Route 32 near Harman for several hours.');
INSERT INTO public.stormevents_east VALUES (784197, 201807, 2, 2040, 201807, 2, 2040, 125998, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '02-JUL-18 20:40:00', 'EST-5', '02-JUL-18 20:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'SHARPS CHAPEL', 1, 'SW', 'SHARPS CHAPEL', 36.3409, -83.8113, 36.3409, -83.8113, 'A few thunderstorms became severe over the higher terrain on the Northern Cumberland Plateau and a small part of Southwest Virginia during the evening hours. The storms produced wind damage and some flooding.', 'Three trees were reported down across the county. One of the trees was downed near Sharps Chapel.');
INSERT INTO public.stormevents_east VALUES (783426, 201805, 15, 1616, 201805, 15, 1616, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:16:00', 'EST-5', '15-MAY-18 16:16:00', 0, 0, 0, 0, '7.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 0, 'N', 'AUGERVILLE', 0, 'N', 'AUGERVILLE', 41.37, -72.9, 41.37, -72.9, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous trees and wires down around town.  Roads impassable.');
INSERT INTO public.stormevents_east VALUES (758517, 201805, 16, 2043, 201805, 16, 2200, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '16-MAY-18 20:43:00', 'EST-5', '16-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'ENGLE', 0, 'S', 'ENGLE', 39.3438, -77.7798, 39.3436, -77.7796, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'Engle Switch Road flooded and closed at Engle Molers Road due to flooding of Elk Branch.');
INSERT INTO public.stormevents_east VALUES (754604, 201805, 4, 2004, 201805, 4, 2004, 125843, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '04-MAY-18 20:04:00', 'EST-5', '04-MAY-18 20:04:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'GREENBERRY POINT (GBY)', 0, 'N', 'GREENBERRY POINT (GBY)', 38.97, -76.46, 38.97, -76.46, 'An isolated storm produced gusty winds over the waters.', 'A wind gust in excess of 30 knots was reported at Greenberry Point.');
INSERT INTO public.stormevents_east VALUES (754605, 201805, 10, 1642, 201805, 10, 1642, 125844, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '10-MAY-18 16:42:00', 'EST-5', '10-MAY-18 16:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'LEWISETTA (LWS)', 0, 'N', 'LEWISETTA (LWS)', 38, -76.47, 38, -76.47, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to some storms with gusty winds.', 'A wind gust in excess of 30 knots was reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (760007, 201805, 27, 1516, 201805, 27, 1523, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 15:16:00', 'EST-5', '27-MAY-18 15:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'ELLICOTT CITY', 0, 'S', 'ELLICOTT CITY', 39.2688, -76.8001, 39.2684, -76.7999, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Video footage shows Hudson Branch out of its banks near Court Avenue, flooding yards.');
INSERT INTO public.stormevents_east VALUES (760011, 201805, 27, 1637, 201805, 27, 1753, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 16:37:00', 'EST-5', '27-MAY-18 17:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'ELLICOTT CITY', 0, 'S', 'ELLICOTT CITY', 39.2686, -76.8, 39.2683, -76.7999, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Video footage shows a second, more significant flash flood wave moved down Hudson Branch during the times indicated. Cars, dumpsters, and other large debris were swept downstream. Water covered a second-floor deck and entered structures, and was at least a foot deep flowing over Court Avenue at the peak of the flooding. The stream was not fully back in its banks in this area until after 8:00pm due to debris blockage.');
INSERT INTO public.stormevents_east VALUES (754625, 201805, 12, 2005, 201805, 12, 2015, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 20:05:00', 'EST-5', '12-MAY-18 20:15:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'ROD N REEL CHESAPEAKE BEACH (CHSRL)', 0, 'N', 'ROD N REEL CHESAPEAKE BEACH (CHSRL)', 38.69, -76.53, 38.69, -76.53, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 35 knots were reported at Chesapeake Beach.');
INSERT INTO public.stormevents_east VALUES (754626, 201805, 12, 2008, 201805, 12, 2013, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 20:08:00', 'EST-5', '12-MAY-18 20:13:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'BLACKWALNUT HARBOR (BWH)', 0, 'N', 'BLACKWALNUT HARBOR (BWH)', 38.68, -76.33, 38.68, -76.33, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts of 36 to 37 knots were reported at Black Walnut Harbor.');
