INSERT INTO public.stormevents_east VALUES (754630, 201805, 12, 2048, 201805, 12, 2100, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 20:48:00', 'EST-5', '12-MAY-18 21:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 43, 'MG', NULL, NULL, 3, 'S', 'MID BAY BUOY', 3, 'S', 'MID BAY BUOY', 38.432, -76.387, 38.432, -76.387, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 43 knots were reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (781522, 201805, 30, 2020, 201805, 30, 2320, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '30-MAY-18 20:20:00', 'EST-5', '30-MAY-18 23:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'STANDARDSVILLE', 0, 'SSW', 'STANDARDSVILLE', 38.2976, -78.4315, 38.2974, -78.4312, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Spotswood Trail was flooded and closed due to standing water near Lambs Lane.');
INSERT INTO public.stormevents_east VALUES (781524, 201805, 30, 2002, 201805, 30, 2300, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '30-MAY-18 20:02:00', 'EST-5', '30-MAY-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'ADVANCE MILLS', 3, 'NNE', 'ADVANCE MILLS', 38.2267, -78.4278, 38.2268, -78.4275, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Dunnes Shop Road flooded in multiple places, forcing a road closure.');
INSERT INTO public.stormevents_east VALUES (754951, 201805, 14, 1740, 201805, 14, 1745, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 17:40:00', 'EST-5', '14-MAY-18 17:45:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 3, 'ESE', 'LEESYLVANIA STATE PARK (LSLVN)', 3, 'ESE', 'LEESYLVANIA STATE PARK (LSLVN)', 38.644, -77.199, 38.644, -77.199, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts up to 41 knots were reported at Occoquan.');
INSERT INTO public.stormevents_east VALUES (754953, 201805, 14, 1749, 201805, 14, 1749, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 17:49:00', 'EST-5', '14-MAY-18 17:49:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'LYLES-CROUCH ACADEMY (AXDRA)', 0, 'N', 'LYLES-CROUCH ACADEMY (AXDRA)', 38.8, -77.05, 38.8, -77.05, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust in excess of 30 knots was reported at Lyels-Crouch Academy.');
INSERT INTO public.stormevents_east VALUES (754954, 201805, 14, 1749, 201805, 14, 1749, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 17:49:00', 'EST-5', '14-MAY-18 17:49:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'SW', 'TC WILLIAMS HS (ALXNK)', 0, 'SW', 'TC WILLIAMS HS (ALXNK)', 38.825, -77.0847, 38.825, -77.0847, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust in excess of 30 knots was reported at T.C. Williams High School.');
INSERT INTO public.stormevents_east VALUES (754969, 201805, 14, 1930, 201805, 14, 1930, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:30:00', 'EST-5', '14-MAY-18 19:30:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 43, 'MG', NULL, NULL, 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 38.03, -76.34, 38.03, -76.34, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 43 knots was reported at Potomac Point Lookout.');
INSERT INTO public.stormevents_east VALUES (754973, 201805, 14, 1942, 201805, 14, 1942, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:42:00', 'EST-5', '14-MAY-18 19:42:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'BISHOPS HEAD (BISM2)', 0, 'N', 'BISHOPS HEAD (BISM2)', 38.22, -76.04, 38.22, -76.04, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 34 knot was reported at Bishops Head.');
INSERT INTO public.stormevents_east VALUES (754974, 201805, 14, 1948, 201805, 14, 2000, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 19:48:00', 'EST-5', '14-MAY-18 20:00:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 39, 'MG', NULL, NULL, 0, 'N', 'BISHOPS HEAD (BISM2)', 0, 'N', 'BISHOPS HEAD (BISM2)', 38.22, -76.04, 38.22, -76.04, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts up to 35 knots were reported at Bishops Head.');
INSERT INTO public.stormevents_east VALUES (754983, 201805, 15, 1821, 201805, 15, 1846, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 18:21:00', 'EST-5', '15-MAY-18 18:46:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'GROVE POINT (GVP)', 0, 'N', 'GROVE POINT (GVP)', 39.4, -76.04, 39.4, -76.04, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'A wind gust in excess of 30 knots was reported at Grove Point.');
INSERT INTO public.stormevents_east VALUES (754984, 201805, 15, 1842, 201805, 15, 1932, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 18:42:00', 'EST-5', '15-MAY-18 19:32:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 39, 'MG', NULL, NULL, 0, 'N', 'HART MILLER ISLAND (HRT)', 0, 'N', 'HART MILLER ISLAND (HRT)', 39.25, -76.37, 39.25, -76.37, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts up to 39 knots were reported at Hart Miller Island.');
INSERT INTO public.stormevents_east VALUES (754989, 201805, 15, 1941, 201805, 15, 2001, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 19:41:00', 'EST-5', '15-MAY-18 20:01:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'TOLLY POINT (TOL)', 0, 'N', 'TOLLY POINT (TOL)', 38.94, -76.44, 38.94, -76.44, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'A wind gust in excess of 30 knots was reported at Tolly Point.');
INSERT INTO public.stormevents_east VALUES (770072, 201807, 30, 700, 201807, 31, 700, 127486, 'NORTH CAROLINA', 37, 2018, 'July', 'Heavy Rain', 'RNK', '30-JUL-18 07:00:00', 'EST-5', '31-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'NNW', 'MILLERS CREEK', 2, 'NNW', 'MILLERS CREEK', 36.2054, -81.243, 36.2054, -81.243, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 2 to 4 inches across parts of northwest Wilkes, southeast Alleghany, western Surry, and eastern Yadkin counties, most of which fell in about a 3-hour period during the late evening hours of July 30th.', 'The CoCoRaHS site at Millers Creek 1.9 NNW measured 4.12 inches in 24-hours ending at 7 AM on July 31st.');
INSERT INTO public.stormevents_east VALUES (770079, 201807, 31, 0, 201807, 31, 300, 127486, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RNK', '31-JUL-18 00:00:00', 'EST-5', '31-JUL-18 03:00:00', 0, 0, 0, 0, '100.00K', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 3, 'N', 'PINE RIDGE', 2, 'E', 'PINE RIDGE', 36.5412, -80.7103, 36.5043, -80.6835, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 2 to 4 inches across parts of northwest Wilkes, southeast Alleghany, western Surry, and eastern Yadkin counties, most of which fell in about a 3-hour period during the late evening hours of July 30th.', 'Heavy rain flooded several roads causing damage and an accident when a motorist drove into rushing water covering the road. Sparger Road west of Mt. Airy had a 20-foot opening in the road where rising waters destroyed a section of the road. The automobile was trapped in the high water although the driver escaped without injury. The car was pulled out by rescue vehicles. Pipers Gap Road and Sykes Dairy roads were also flooded but not damaged and several homes had flooded basements.');
INSERT INTO public.stormevents_east VALUES (776021, 201807, 22, 1515, 201807, 22, 1515, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 15:15:00', 'EST-5', '22-JUL-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSE', 'PFAFFTOWN', 2, 'SSE', 'PFAFFTOWN', 36.1204, -80.36, 36.1204, -80.36, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down on Robbinhood Road.');
INSERT INTO public.stormevents_east VALUES (776023, 201807, 22, 1616, 201807, 22, 1616, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 16:16:00', 'EST-5', '22-JUL-18 16:16:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ESE', 'TAYLORS XRDS', 3, 'ESE', 'TAYLORS XRDS', 35.859, -77.9611, 35.859, -77.9611, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down near the intersection of Tar River Church Road and Bend of the River Road.');
INSERT INTO public.stormevents_east VALUES (771173, 201806, 9, 1500, 201806, 9, 1500, 128493, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MFL', '09-JUN-18 15:00:00', 'EST-5', '09-JUN-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 0.75, NULL, NULL, NULL, 2, 'NE', 'GOLDEN GATE', 2, 'NE', 'GOLDEN GATE', 26.19, -81.65, 26.19, -81.65, 'The Atlantic seabreeze that developed during the late morning hours of June 7th, quickly moved west and collided with the Gulf breeze across Collier, Hendry, and Glades counties during the afternoon hours. Shower and storm development along these boundaries was enhanced by an upper level low across the eastern Gulf of Mexico, allowing several storms to become severe as a result of the collision, leading to reports of hail across interior Collier and Hendry counties.', 'NBC2 Fort Myers relayed a report of penny to dime sized hail associated with a thunderstorm in Golden Gate Estate. Time estimated via radar.');
INSERT INTO public.stormevents_east VALUES (774616, 201807, 25, 1515, 201807, 25, 1715, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 15:15:00', 'EST-5', '25-JUL-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'KIMBALL', 2, 'ESE', 'KIMBALL', 38.6737, -78.3828, 38.6736, -78.3823, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Red Church Road over Rocky Branch was flooded with the stream flowing over the roadway.');
INSERT INTO public.stormevents_east VALUES (774617, 201807, 25, 1700, 201807, 25, 1900, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:00:00', 'EST-5', '25-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'PANORAMA', 2, 'SW', 'PANORAMA', 38.6515, -78.3543, 38.6514, -78.354, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Jewell Hollow Road flooded and impassable.');
INSERT INTO public.stormevents_east VALUES (758041, 201805, 15, 2039, 201805, 15, 2200, 126449, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '15-MAY-18 20:39:00', 'EST-5', '15-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'ALEXANDRIA', 2, 'ESE', 'ALEXANDRIA', 38.8055, -77.0401, 38.8053, -77.0402, 'A cold front slowly sagged southward through Maryland during the evening hours of May 15th. A line of storms spread ahead of this front, producing 1-2 inches of rain in parts of Loudoun, Fairfax, and Arlington Counties, and the City of Alexandria. This was enough to cause some flooding. Stream flooding continued into the early morning hours of the 16th.', 'Flooding was reported near the intersection of Cameron Street and North Union Street in Alexandria.');
INSERT INTO public.stormevents_east VALUES (783522, 201805, 15, 1555, 201805, 15, 1555, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:55:00', 'EST-5', '15-MAY-18 15:55:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Amateur Radio', 61, 'EG', NULL, NULL, 1, 'E', 'OAKLAND', 1, 'E', 'OAKLAND', 41.03, -74.24, 41.03, -74.24, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree on house on Andrew Avenue.');
INSERT INTO public.stormevents_east VALUES (783523, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'N', 'ORADELL', 1, 'N', 'ORADELL', 40.95, -74.07, 40.95, -74.07, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree down in front of Bergen Catholic High School on Oradelle Road.  Road completely blocked.');
INSERT INTO public.stormevents_east VALUES (783524, 201805, 15, 1600, 201805, 15, 1600, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:00:00', 'EST-5', '15-MAY-18 16:00:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'SW', 'CLIFTON', 1, 'SW', 'CLIFTON', 40.86, -74.16, 40.86, -74.16, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Numerous trees reported down around town.');
INSERT INTO public.stormevents_east VALUES (756752, 201805, 15, 1512, 201805, 15, 1512, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:12:00', 'EST-5', '15-MAY-18 15:12:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 1, 'SSW', 'VAILS GATE JCT', 1, 'SSW', 'VAILS GATE JCT', 41.45, -74.08, 41.45, -74.08, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Three 10 ft fence sections down on Mount Airy Road near Kristi Babcock Memorial Park.  A tree also down in neighbor''s yard.');
INSERT INTO public.stormevents_east VALUES (756753, 201805, 15, 1512, 201805, 15, 1512, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:12:00', 'EST-5', '15-MAY-18 15:12:00', 0, 0, 0, 0, '7.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 1, 'N', 'WALDEN', 1, 'N', 'WALDEN', 41.56, -74.18, 41.56, -74.18, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Three 60-70 ft tall trees down on Sherman Avenue between Union Street and East Avenue.');
INSERT INTO public.stormevents_east VALUES (756777, 201805, 15, 1625, 201805, 15, 1625, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:25:00', 'EST-5', '15-MAY-18 16:25:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 2, 'NNE', 'WOODSIDE', 2, 'NNE', 'WOODSIDE', 40.78, -73.91, 40.78, -73.91, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'At 24th Avenue and 23rd Street, a tree down.');
INSERT INTO public.stormevents_east VALUES (749937, 201804, 15, 1418, 201804, 15, 1418, 125000, 'ATLANTIC SOUTH', 87, 2018, 'April', 'Marine Thunderstorm Wind', 'JAX', '15-APR-18 14:18:00', 'EST-5', '15-APR-18 14:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 13, 'WSW', 'MAYPORT NAS', 13, 'WSW', 'MAYPORT NAS', 30.33, -81.6257, 30.33, -81.6257, 'A strong pre-frontal squall line moved across the area under a moist and unstable environment. Severe storms produced wind damage and locally heavy rainfall.', 'The WeatherFlow sensor at Terminal Channel measured a peak gust of 42 mph with a squall line.');
INSERT INTO public.stormevents_east VALUES (780946, 201807, 25, 112, 201807, 25, 214, 128277, 'MARYLAND', 24, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 01:12:00', 'EST-5', '25-JUL-18 02:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'BENTLEY SPGS', 0, 'NE', 'BENTLEY SPGS', 39.673, -76.6754, 39.6741, -76.6746, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, especially in Baltimore and Carroll Counties, with widespread flooding and flash flooding throughout the period.', 'The USGS stream gage on Beetree Run near Bentley Springs, MD exceeded the 5.5 foot flood stage during the indicated period. The peak level of 6.70 feet occurred at 1:30am EST. Bentley Road floods at these levels.');
INSERT INTO public.stormevents_east VALUES (775959, 201809, 24, 2015, 201809, 24, 2145, 129499, 'KENTUCKY', 21, 2018, 'September', 'Flood', 'JKL', '24-SEP-18 20:15:00', 'EST-5', '24-SEP-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'W', 'POPLAR GROVE', 4, 'W', 'POPLAR GROVE', 38.4903, -83.7348, 38.4907, -83.7357, 'Multiple rounds of rainfall over the weekend and into early week occurred along a stationary frontal boundary. Portions of northwestern Fleming County received between 2.5 to 3.5 inches of rain during this time frame, which resulted in flooding north of Flemingsburg.', 'Dispatch reported that Mill Creek Road and Pleasantville Road north of Flemingsburg were both closed due to standing water.');
INSERT INTO public.stormevents_east VALUES (775235, 201808, 2, 1648, 201808, 2, 1848, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 16:48:00', 'EST-5', '02-AUG-18 18:48:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'DONOVANS CORNER', 1, 'E', 'DONOVANS CORNER', 38.77, -77.31, 38.7694, -77.3082, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Burke Road was closed due to flooding at Jeremiah Court.');
INSERT INTO public.stormevents_east VALUES (777948, 201808, 9, 1448, 201808, 9, 1458, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '09-AUG-18 14:48:00', 'EST-5', '09-AUG-18 14:58:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 1, 'WNW', 'BENDER', 1, 'WNW', 'BENDER', 32.5541, -83.1347, 32.5541, -83.1347, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Laurens County Emergency Manager reported a tree blown down in the 100 block of Chappell Mill Road near Montrose.');
INSERT INTO public.stormevents_east VALUES (778156, 201808, 13, 1722, 201808, 13, 1722, 129894, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '13-AUG-18 17:22:00', 'EST-5', '13-AUG-18 17:22:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 43, 'MG', NULL, NULL, 0, 'N', 'HART MILLER ISLAND (HRT)', 0, 'N', 'HART MILLER ISLAND (HRT)', 39.25, -76.37, 39.25, -76.37, 'An upper level low pressure system combined with high amounts of moisture and instability to produce thunderstorms. A few storms produced strong winds over the waters.', 'A wind gust of 43 knots was measured.');
INSERT INTO public.stormevents_east VALUES (775989, 201808, 13, 1726, 201808, 13, 1926, 129512, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '13-AUG-18 17:26:00', 'EST-5', '13-AUG-18 19:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'ROGERS FORGE', 1, 'E', 'ROGERS FORGE', 39.4019, -76.5832, 39.4013, -76.5837, 'Upper-level low pressure remained over the region while a warm and humid air mass was in place. This resulted in showers and thunderstorms, some of which produced locally heavy rainfall.', 'A vehicle was trapped in high water near the intersection of Cromwell Bridge Road and Providence Road.');
INSERT INTO public.stormevents_east VALUES (784327, 201808, 13, 252, 201808, 13, 354, 129512, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '13-AUG-18 02:52:00', 'EST-5', '13-AUG-18 03:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'WHITE MARSH', 1, 'WSW', 'WHITE MARSH', 39.3762, -76.4584, 39.3755, -76.4555, 'Upper-level low pressure remained over the region while a warm and humid air mass was in place. This resulted in showers and thunderstorms, some of which produced locally heavy rainfall.', 'The stream gage on Whitemarsh Run exceeded the 11 foot flood stage during the indicated period, flooding parking lots in the vicinity. The peak level of 12.27 feet occurred at 3:15am EST.');
INSERT INTO public.stormevents_east VALUES (782785, 201808, 4, 1242, 201808, 4, 1857, 129454, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 12:42:00', 'EST-5', '04-AUG-18 18:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'REMINGTON', 1, 'W', 'REMINGTON', 38.53, -77.81, 38.5289, -77.8134, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'The stream gauge along the Rappahannock River at Remington reached 15.41 feet, passing the flood stage of 15 feet. Tin Pot Run Road and Sumerduck road near Remington were flooded.');
INSERT INTO public.stormevents_east VALUES (775612, 201808, 4, 1, 201808, 4, 201, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 00:01:00', 'EST-5', '04-AUG-18 02:01:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'WALKERSVILLE', 2, 'E', 'WALKERSVILLE', 39.48, -77.32, 39.4761, -77.3153, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'Water street road was closed due to flooding near Harp Road.');
INSERT INTO public.stormevents_east VALUES (748581, 201804, 15, 1625, 201804, 15, 1646, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 16:25:00', 'EST-5', '15-APR-18 16:46:00', 5, 2, 0, 0, '2.20M', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'E', 'BENAJA', 2, 'NNE', 'RUFFIN', 36.245, -79.643, 36.48, -79.534, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'A tornado touched down southeast of Greensboro in Guilford County shortly after 4:00 PM EST.  This tornado later entered Rockingham County about one mile southeast of Haw River near Chrismon Road at 4:25 PM EST.  The tornado damaged numerous buildings, outbuildings, and barns.  At least twenty homes and farms suffered damage, while one house and two mobile homes were  completely destroyed.  The Oak Haven Event Center in downtown Ruffin also sustained damage.  Countless trees were snapped or uprooted.  Estimated maximum wind speeds were 110 MPH.  Seven people were injured, including a father and a seven-year-old son who were critically injured in their moving car when it struck a double-wide mobile home that was lifted on to the 1300 block of Grooms Road.  The tornado finally lifted at 4:46 PM EST about four miles north-northeast of Ruffin between Dibrell Road and Bradley Road.');
INSERT INTO public.stormevents_east VALUES (788068, 201808, 31, 1925, 201808, 31, 2003, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 19:25:00', 'EST-5', '31-AUG-18 20:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'HALETHORPE', 0, 'ESE', 'HALETHORPE', 39.2472, -76.6937, 39.2472, -76.6931, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The gauge along the Eastern Branch of Herbert Run at Arbutus surpassed the flood stage of 7 feet, cresting at 8.11 feet. Water approached structures along the creek, and approaches the top of the culvert at Sulphur Spring Road. Water covered yards near Tom Day Boulevard.');
INSERT INTO public.stormevents_east VALUES (761225, 201805, 22, 1738, 201805, 22, 1738, 127009, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:38:00', 'EST-5', '22-MAY-18 17:38:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'NEW CUMBERLAND', 1, 'W', 'NEW CUMBERLAND', 40.5, -80.61, 40.5, -80.61, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Emergency manager reported multiple trees and power lines down county-wide.');
INSERT INTO public.stormevents_east VALUES (761226, 201805, 22, 1805, 201805, 22, 1805, 127009, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:05:00', 'EST-5', '22-MAY-18 18:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'W', 'KINGS CREEK', 1, 'W', 'KINGS CREEK', 40.45, -80.6, 40.45, -80.6, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State Department of Highways reported trees down.');
INSERT INTO public.stormevents_east VALUES (761227, 201805, 22, 2130, 201805, 23, 30, 127009, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'PBZ', '22-MAY-18 21:30:00', 'EST-5', '23-MAY-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'CAMERON', 0, 'E', 'CAMERON', 39.83, -80.57, 39.8297, -80.5607, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Emergency manager reported that Upper Graves Creek had overflowed its banks in Cameron.');
INSERT INTO public.stormevents_east VALUES (761191, 201805, 22, 1440, 201805, 22, 1440, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'PBZ', '22-MAY-18 14:40:00', 'EST-5', '22-MAY-18 14:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.88, NULL, NULL, NULL, 1, 'ESE', 'PULASKI', 1, 'ESE', 'PULASKI', 41.11, -80.43, 41.11, -80.43, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', NULL);
INSERT INTO public.stormevents_east VALUES (761192, 201805, 22, 1815, 201805, 22, 1815, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:15:00', 'EST-5', '22-MAY-18 18:15:00', 0, 0, 0, 0, '0.25K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 0, 'N', 'MC DONALD', 0, 'N', 'MC DONALD', 40.37, -80.23, 40.37, -80.23, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported a tree blocking roadway.');
INSERT INTO public.stormevents_east VALUES (761548, 201805, 8, 1015, 201805, 8, 1025, 127084, 'GULF OF MEXICO', 85, 2018, 'May', 'Waterspout', 'KEY', '08-MAY-18 10:15:00', 'EST-5', '08-MAY-18 10:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, NULL, NULL, 4, 'W', 'KEY WEST', 4, 'W', 'KEY WEST', 24.55, -81.84, 24.55, -81.84, 'In spite of lacking deep moisture, ideal wind conditions allowed for the development of mature cloud lines throughout the Lower, Middle and Upper Florida Keys.  Numerous waterspouts developed primarily in the nearshore Florida Bay and Gulf of Mexico waters.', 'Multipe waterspouts were observed by NWS personnel and several members of the public about 4 miles west of Key West.  One waterspout had a significant spray ring, coupled with a thick, vertical condensation funnel.');
INSERT INTO public.stormevents_east VALUES (761567, 201805, 21, 1100, 201805, 21, 1100, 127090, 'GULF OF MEXICO', 85, 2018, 'May', 'Waterspout', 'KEY', '21-MAY-18 11:00:00', 'EST-5', '21-MAY-18 11:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 7, 'S', 'SMITH SHOAL LIGHT', 7, 'S', 'SMITH SHOAL LIGHT', 24.62, -81.92, 24.62, -81.92, 'An isolated waterspout developed northwest of Key West as result of an extended lee convergence cloud line from the Lower Florida Keys.', 'A mature waterspout was observed and relayed via social media about 10 miles west northwest of Key West.  The waterspout was observed to tilt up to 45 degrees from the vertical with a spray ring clearly visible.');
INSERT INTO public.stormevents_east VALUES (761605, 201805, 26, 2000, 201805, 26, 2000, 127095, 'GULF OF MEXICO', 85, 2018, 'May', 'Marine Thunderstorm Wind', 'KEY', '26-MAY-18 20:00:00', 'EST-5', '26-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'CARYSFORT REEF LIGHT', 0, 'N', 'CARYSFORT REEF LIGHT', 25.22, -80.21, 25.22, -80.21, 'Numerous thunderstorms and squalls along the outer periphery of Subtropical Storm Alberto produced gale-force wind gusts throughout the Florida Keys coastal waters.  These squalls were not associated with the circulation of Alberto, however deep rich moisture streaming north from the western Caribbean produced multiple rounds of deep convection near the Florida Keys from May 26 through May 27.', 'A wind gust of 35 knots was measured at an automated WeatherFlow station at Carysfort Reef Light.');
INSERT INTO public.stormevents_east VALUES (800240, 201809, 1, 1730, 201809, 1, 1730, 133722, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '01-SEP-18 17:30:00', 'EST-5', '01-SEP-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BROADVIEW', 1, 'SSE', 'BROADVIEW', 36.1111, -79.7762, 36.1125, -79.772, 'A strongly unstable air mass combined with an upper level disturbance to trigger numerous thunderstorms across the northern Piedmont, with a few reports of wind damage and one report of flash flooding. Storms produced a massive outflow boundary and excessive amounts of lightning. Storm coverage was more limited to the south and east in the Coastal Plain and southern Piedmont.', 'Yanceyville Street was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (745398, 201805, 17, 1102, 201805, 17, 1102, 124209, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '17-MAY-18 11:02:00', 'EST-5', '17-MAY-18 11:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'NNW', 'MELBOURNE', 2, 'NNW', 'MELBOURNE', 28.101, -80.612, 28.101, -80.612, 'Showers and thunderstorms developed along the east coast sea breeze across western Brevard County and eastern Osceola County. The prevailing south-southwesterly flow then pushed these storms back towards the Brevard County coast. Two storms produced strong winds across the intercoastal waters.', 'The ASOS at the Melbourne International Airport - KMLB, measured a peak wind gust of 34 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (750800, 201805, 27, 344, 201805, 27, 344, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 03:44:00', 'EST-5', '27-MAY-18 03:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 1, 'ESE', 'ST. LUCIE NUCLEAR POWER PLANT', 27.3452, -80.2364, 27.3452, -80.2364, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'Mesonet site XSTL at the St. Lucie Nuclear Power Plant measured a peak wind gust of 35 knots from the south.');
INSERT INTO public.stormevents_east VALUES (755373, 201807, 6, 1730, 201807, 6, 1730, 126002, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '06-JUL-18 17:30:00', 'EST-5', '06-JUL-18 17:30:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'NEW TAZEWELL', 1, 'N', 'NEW TAZEWELL', 36.44, -83.6, 36.44, -83.6, 'Showers and thunderstorms formed along a cool front sliding south across East Tennessee during the late afternoon and evening hours. The storms produced damaging winds, flash flooding and frequent lightning. The lightning resulted in a fatality in Roane County.', 'Several trees were reported down near First Avenue in New Tazewell.');
INSERT INTO public.stormevents_east VALUES (755374, 201807, 6, 1837, 201807, 6, 1837, 126002, 'TENNESSEE', 47, 2018, 'July', 'Thunderstorm Wind', 'MRX', '06-JUL-18 18:37:00', 'EST-5', '06-JUL-18 18:37:00', 0, 0, 0, 0, NULL, NULL, 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'E', 'CLEAR SPGS', 1, 'E', 'CLEAR SPGS', 36.15, -83.87, 36.15, -83.87, 'Showers and thunderstorms formed along a cool front sliding south across East Tennessee during the late afternoon and evening hours. The storms produced damaging winds, flash flooding and frequent lightning. The lightning resulted in a fatality in Roane County.', 'Two trees were reported down.');
INSERT INTO public.stormevents_east VALUES (769128, 201806, 20, 1835, 201806, 20, 1835, 128231, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '20-JUN-18 18:35:00', 'EST-5', '20-JUN-18 18:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SW', 'LIVE OAK', 1, 'SW', 'LIVE OAK', 30.29, -82.99, 30.29, -82.99, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'Two trees were blown down within the city of Live Oak and blocked roadways.');
INSERT INTO public.stormevents_east VALUES (769130, 201806, 20, 1545, 201806, 20, 1545, 128234, 'GEORGIA', 13, 2018, 'June', 'Hail', 'JAX', '20-JUN-18 15:45:00', 'EST-5', '20-JUN-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 2, 'NNE', 'COLESBURG', 2, 'NNE', 'COLESBURG', 30.95, -81.69, 30.95, -81.69, 'A surface trough axis was over southern GA and extended into north FL into the afternoon which served as a focus for convective development over a moist and unstable airmass.', 'Penny size hail observed along I-95 near Woodbine.');
INSERT INTO public.stormevents_east VALUES (769164, 201806, 21, 1440, 201806, 21, 1440, 128241, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '21-JUN-18 14:40:00', 'EST-5', '21-JUN-18 14:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 3, 'S', 'ST AUGUSTINE ARPT', 3, 'S', 'ST AUGUSTINE ARPT', 29.92, -81.33, 29.92, -81.33, 'A low level trough axis lingered across north-central Florida which served as a focus for an early start to diurnally enhanced showers and thunderstorms. Locally heavy rainfall occurred along and near this trough axis. A few strong outflow wind gusts impacted the adjacent Atlantic waters.', 'A WeatherFlow sensor measured a wind gust to 45 mph.');
INSERT INTO public.stormevents_east VALUES (760681, 201807, 19, 1355, 201807, 19, 1355, 126917, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MLB', '19-JUL-18 13:55:00', 'EST-5', '19-JUL-18 13:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 39, 'MG', NULL, NULL, 9, 'ENE', 'PLAYALINDA BEACH', 9, 'ENE', 'PLAYALINDA BEACH', 28.6, -80.64, 28.6, -80.64, 'Deep southwest flow was present across the Florida peninsula as a frontal trough was stalled across the Deep South and Western Atlantic, suppressing the Bermuda Ridge to the Florida Straits. Abundant moisture was present across the area with high Precipitable Water values. Diurnal heating led to scattered to numerous showers and thunderstorms development across the inland peninsula, with the dominant southwest wind flow pushing the activity to the east coast. As these storms moved across the Brevard County coast they produced strong winds along the intracoastal waters near Cape Canaveral.', 'U.S. Air Force wind tower 0311 measured a peak wind gust of 39 knots from the west-southwest.');
INSERT INTO public.stormevents_east VALUES (771146, 201806, 4, 1837, 201806, 4, 1837, 128486, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '04-JUN-18 18:37:00', 'EST-5', '04-JUN-18 18:37:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 44, 'MG', NULL, NULL, 2, 'SE', 'GOVERNMENT CUT', 2, 'SE', 'GOVERNMENT CUT', 25.75, -80.1, 25.75, -80.1, 'Abundant moisture and a weak frontal boundary across north Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity pushed off the coast into the local Atlantic waters during the early evening hours, producing several strong wind gusts.', 'A wind gust of 51 mph/44 knots was recorded at WxFlow site XGVT in Government Cut at a height of 75 feet.');
INSERT INTO public.stormevents_east VALUES (771150, 201806, 6, 1430, 201806, 6, 1430, 128489, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '06-JUN-18 14:30:00', 'EST-5', '06-JUN-18 14:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 4, 'ENE', 'BUCKHEAD RIDGE', 4, 'ENE', 'BUCKHEAD RIDGE', 27.14, -80.79, 27.14, -80.79, 'Abundant moisture and a weak stationary front across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 43 mph/37 knots at SFWMD mesonet site L001 over Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (771156, 201806, 7, 1345, 201806, 7, 1345, 128491, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '07-JUN-18 13:45:00', 'EST-5', '07-JUN-18 13:45:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 9, 'WSW', 'PORT MAYACA', 9, 'WSW', 'PORT MAYACA', 26.96, -80.94, 26.96, -80.94, 'Abundant moisture, an upper level trough, and a lingering weak boundary across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 40 mph/35 knots at mesonet site L005 over Lake Okeechobee.');
INSERT INTO public.stormevents_east VALUES (762877, 201806, 2, 1725, 201806, 2, 1725, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:25:00', 'EST-5', '02-JUN-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'ESE', 'EAST MANDARIN', 2, 'ESE', 'EAST MANDARIN', 30.14, -81.6, 30.14, -81.6, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees were blown down on two properties along Julington Creek Road. One tree clipped a home. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762878, 201806, 2, 1725, 201806, 2, 1725, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:25:00', 'EST-5', '02-JUN-18 17:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'E', 'FRUIT COVE', 2, 'E', 'FRUIT COVE', 30.1, -81.6, 30.1, -81.6, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A tree was blown down in Julington Creek. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762880, 201806, 2, 1715, 201806, 2, 1715, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 17:15:00', 'EST-5', '02-JUN-18 17:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 52, 'MG', NULL, NULL, 2, 'NNW', 'FT CAROLINE SHRS', 2, 'NNW', 'FT CAROLINE SHRS', 30.39, -81.48, 30.39, -81.48, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'The WeatherFlow station at Buck Island measured a peak wind gust of 60 mph.');
INSERT INTO public.stormevents_east VALUES (762881, 201806, 2, 1630, 201806, 2, 1630, 127225, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 16:30:00', 'EST-5', '02-JUN-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'HILLIARD', 1, 'N', 'HILLIARD', 30.69, -81.92, 30.69, -81.92, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Power lines were blown down near North Kings Road in Hilliard.');
INSERT INTO public.stormevents_east VALUES (766250, 201806, 2, 1656, 201806, 2, 1656, 127224, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '02-JUN-18 16:56:00', 'EST-5', '02-JUN-18 16:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', 36, 'MG', NULL, NULL, 4, 'W', 'FERNANDINA NOS', 4, 'W', 'FERNANDINA NOS', 30.66, -81.54, 30.66, -81.54, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', NULL);
INSERT INTO public.stormevents_east VALUES (754986, 201805, 15, 1955, 201805, 15, 1955, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 19:55:00', 'EST-5', '15-MAY-18 19:55:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 1, 'ESE', 'LONG BRANCH ES (ARLNL)', 1, 'ESE', 'LONG BRANCH ES (ARLNL)', 38.8614, -77.0719, 38.8614, -77.0719, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts in excess of 30 knots were reported at Hoffman-Boston Elementary School.');
INSERT INTO public.stormevents_east VALUES (774468, 201807, 27, 1732, 201807, 27, 1930, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 17:32:00', 'EST-5', '27-JUL-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 4, 'E', 'CATONSVILLE MANOR', 4, 'E', 'CATONSVILLE MANOR', 39.2936, -76.6539, 39.2936, -76.6527, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'US 40 flooded and closed due to torrential rain near the West Baltimore MARC station.');
INSERT INTO public.stormevents_east VALUES (774469, 201807, 27, 1745, 201807, 27, 1945, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 17:45:00', 'EST-5', '27-JUL-18 19:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'CATONSVILLE MANOR', 1, 'NNE', 'CATONSVILLE MANOR', 39.311, -76.7177, 39.3108, -76.7171, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Security Boulevard flooded and closed after torrential rains near Kernan Drive.');
INSERT INTO public.stormevents_east VALUES (774471, 201807, 27, 1753, 201807, 27, 2000, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 17:53:00', 'EST-5', '27-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'GLEN ARM', 1, 'SW', 'GLEN ARM', 39.4436, -76.5104, 39.4434, -76.5101, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Notchcliff Road flooded and closed after torrential rains swelled Cowen Run near Glen Arm Road.');
INSERT INTO public.stormevents_east VALUES (774477, 201807, 27, 1800, 201807, 27, 2000, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 18:00:00', 'EST-5', '27-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'MT ROYAL', 0, 'NNW', 'MT ROYAL', 39.3255, -76.6343, 39.3245, -76.6327, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Torrential rain forced cars to be stuck in high water on Falls Road, with nearby ramps to Interstate 83 also flooded, blocking traffic.');
INSERT INTO public.stormevents_east VALUES (774486, 201807, 27, 1727, 201807, 27, 1900, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 17:27:00', 'EST-5', '27-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BEL AIR', 1, 'N', 'BEL AIR', 39.5489, -76.3502, 39.549, -76.3498, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'Flash flooding due to torrential rain occurred at the intersection of Conowingo Road and Moores Mill Road near Bynum Run.');
INSERT INTO public.stormevents_east VALUES (781490, 201807, 27, 1703, 201807, 27, 1717, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 17:03:00', 'EST-5', '27-JUL-18 17:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'HALETHORPE', 1, 'NNE', 'RELAY', 39.2404, -76.6923, 39.24, -76.6923, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'The USGS stream gage on East Branch Herbert Run near Arbutus rapidly and briefly exceeded the 7 foot flood stage during the indicated period, sending water into nearby yards. The peak level of 7.28 feet occurred at 5:10pm EST.');
INSERT INTO public.stormevents_east VALUES (760015, 201805, 27, 1547, 201805, 27, 1620, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:47:00', 'EST-5', '27-MAY-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'ELLICOTT CITY', 0, 'SE', 'ELLICOTT CITY', 39.2675, -76.7971, 39.2669, -76.7971, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'A second, more intense, flood wave pushed into the Tiber River, with water entering buildings in the 8100 block of Main Street. The water receded from this block of Main Street by 5:20pm.');
INSERT INTO public.stormevents_east VALUES (760023, 201805, 27, 1526, 201805, 27, 1540, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:26:00', 'EST-5', '27-MAY-18 15:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ELLICOTT CITY', 0, 'W', 'ELLICOTT CITY', 39.269, -76.8099, 39.2691, -76.8079, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Video footage shows 6-12 inches of water flowing over the 8600 block of Frederick Road east of Rogers Avenue in Ellicott City''s West End for a brief period before receding.');
INSERT INTO public.stormevents_east VALUES (808500, 201812, 21, 15, 201812, 21, 900, 133712, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '21-DEC-18 00:15:00', 'EST-5', '21-DEC-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 4, 'N', 'IVY', 4, 'N', 'IVY', 38.1021, -78.5938, 38.1034, -78.594, 'A potent longwave trough approached the area from the west on the 20th. Warm advection and strong moisture transport ahead of the mid-upper level wave led to a prolonged period of rainfall through the day as surface low pressure tracked from the FL Panhandle to WV by evening. Rainfall totals on the order of 1-2 inches led to instances of flooding across portions of Augusta, Nelson and Albemarle Counties in VA.', 'The stream gauge on Mechums River near White Hall was above minor flood stage of 11 feet during the indicated period. It peaked at 13.98 feet at 5:15 AM on the 21st.');
INSERT INTO public.stormevents_east VALUES (760897, 201805, 27, 1621, 201805, 27, 1800, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 16:21:00', 'EST-5', '27-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'CHADWICK MANOR', 2, 'S', 'CHADWICK MANOR', 39.271, -76.7352, 39.2719, -76.7311, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Moving water observed over the hoods of several cars in multiple locations in the Catonsville area along Frederick Road.');
INSERT INTO public.stormevents_east VALUES (760903, 201805, 27, 1637, 201805, 27, 1800, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 16:37:00', 'EST-5', '27-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'WOLFE MILL', 1, 'W', 'WOLFE MILL', 39.67, -78.75, 39.6706, -78.7497, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Flooding of unknown depth was reported on Bedford Street in Cumberland.');
INSERT INTO public.stormevents_east VALUES (760902, 201805, 27, 1649, 201805, 27, 1800, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 16:49:00', 'EST-5', '27-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'OELLA', 1, 'SE', 'OELLA', 39.2678, -76.7761, 39.2604, -76.762, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Several issues reported near Oella. There was a partial landslide on Old Frederick Road with the road also reported flooded and closed. River Road was flooded and closed. Thistle Road had a washout and was closed. A portion of Westchester Avenue was also flooded and closed.');
INSERT INTO public.stormevents_east VALUES (760905, 201805, 27, 2216, 201805, 27, 2359, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 22:16:00', 'EST-5', '27-MAY-18 23:59:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BOWENS', 1, 'W', 'BOWENS', 38.5031, -76.6434, 38.503, -76.6426, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Buzzard Island Creek was out of its banks and running across Sixes Road.');
INSERT INTO public.stormevents_east VALUES (754955, 201805, 14, 1751, 201805, 14, 1825, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 17:51:00', 'EST-5', '14-MAY-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 34, 'EG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust in excess of 30 knots was reported at Regan National.');
INSERT INTO public.stormevents_east VALUES (754956, 201805, 14, 1810, 201805, 14, 1810, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:10:00', 'EST-5', '14-MAY-18 18:10:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 1, 'ESE', 'LONG BRANCH ES (ARLNL)', 1, 'ESE', 'LONG BRANCH ES (ARLNL)', 38.8614, -77.0719, 38.8614, -77.0719, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 37 knots was reported at Hoffman-Boston Elementary School.');
INSERT INTO public.stormevents_east VALUES (754957, 201805, 14, 1820, 201805, 14, 1825, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:20:00', 'EST-5', '14-MAY-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'NATIONALS PARK (WSHNP)', 0, 'N', 'NATIONALS PARK (WSHNP)', 38.87, -77.01, 38.87, -77.01, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts up to 37 knots were reported at Nationals Park.');
INSERT INTO public.stormevents_east VALUES (760936, 201805, 27, 1547, 201805, 27, 1916, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:47:00', 'EST-5', '27-MAY-18 19:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'FREDERICK RD', 1, 'E', 'FREDERICK RD', 39.2776, -76.661, 39.2797, -76.6606, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on Gwynns Falls at Washington Boulevard in Baltimore rapidly exceeded the 13 foot flood stage, flooding portions of Gwynns Falls Park. The peak level of 17.09 feet was the 4th highest on record, and occurred at 5:31pm EST on May 27th.');
INSERT INTO public.stormevents_east VALUES (754985, 201805, 15, 1950, 201805, 15, 1953, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 19:50:00', 'EST-5', '15-MAY-18 19:53:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 36, 'MG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts up to 36 knots were reported at Reagan National.');
INSERT INTO public.stormevents_east VALUES (758549, 201805, 18, 2345, 201805, 20, 2200, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '18-MAY-18 23:45:00', 'EST-5', '20-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'MEYERSTOWN', 1, 'NNW', 'BLOOMERY', 39.1674, -77.8707, 39.258, -77.8248, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'The stream gage on the Shenandoah River near Millville exceeded the 10 foot flood stage during the times indicated. In West Virginia, the impacts included flooding of parts of Bloomery Road and John Rissler Road, along with parks and camping areas near Bloomery and Millville. The peak level observed was 10.63 feet on May 19th at 4:30pm EST.');
INSERT INTO public.stormevents_east VALUES (778625, 201810, 2, 1742, 201810, 2, 1752, 130002, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'ILN', '02-OCT-18 17:42:00', 'EST-5', '02-OCT-18 17:52:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'SW', 'VANATTA', 3, 'SW', 'VANATTA', 40.09, -82.47, 40.09, -82.47, 'Scattered severe thunderstorms developed ahead of a cold front dropping south through the region.', 'Several trees were reported knocked down.');
INSERT INTO public.stormevents_east VALUES (776571, 201807, 31, 1730, 201807, 31, 1830, 127486, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RNK', '31-JUL-18 17:30:00', 'EST-5', '31-JUL-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'ENON', 2, 'SE', 'ENON', 36.14, -80.45, 36.1359, -80.4455, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 2 to 4 inches across parts of northwest Wilkes, southeast Alleghany, western Surry, and eastern Yadkin counties, most of which fell in about a 3-hour period during the late evening hours of July 30th.', 'Heavy rain flooded portions of Taylor Road and Riverpointe Drive near Enon. Minor residential flooding was also reported through social media.');
INSERT INTO public.stormevents_east VALUES (776025, 201807, 22, 1620, 201807, 22, 1620, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 16:20:00', 'EST-5', '22-JUL-18 16:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'EASONBURG', 2, 'WSW', 'EASONBURG', 35.9046, -77.9041, 35.9046, -77.9041, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down near the intersection of West Mount Drive And South Old Carriage Road.');
INSERT INTO public.stormevents_east VALUES (776033, 201807, 22, 1623, 201807, 22, 1623, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 16:23:00', 'EST-5', '22-JUL-18 16:23:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'LITTLE EASONBURG', 1, 'NNW', 'LITTLE EASONBURG', 35.9835, -77.8782, 35.9835, -77.8782, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'One tree was reported down along the on ramp to United States Highway 64.');
INSERT INTO public.stormevents_east VALUES (776034, 201807, 22, 1808, 201807, 22, 1808, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:08:00', 'EST-5', '22-JUL-18 18:08:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'E', 'ASHEBORO', 0, 'E', 'ASHEBORO', 35.7003, -79.8227, 35.7003, -79.8227, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'A large oak tree was reported down on a residence on Lee Street, near Kivett Street.');
INSERT INTO public.stormevents_east VALUES (776036, 201807, 22, 1813, 201807, 22, 1813, 129475, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '22-JUL-18 18:13:00', 'EST-5', '22-JUL-18 18:13:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'ASHEBORO SOUTH', 1, 'SE', 'ASHEBORO SOUTH', 35.71, -79.81, 35.71, -79.81, 'A stationary surface low over western North Carolina, and a pair of outflow modulated fronts over North Carolina and Virginia, were overspread by perturbed south southwesterly flow around an anomalous mid to upper low over the Ohio Valley. Loosely organized multi clusters resulted, with accompanying marginally severe hail, wind damage, and isolated flooding.', 'Numerous trees were reported down in Asheboro.');
INSERT INTO public.stormevents_east VALUES (770138, 201807, 30, 700, 201807, 30, 700, 128374, 'VIRGINIA', 51, 2018, 'July', 'Heavy Rain', 'RNK', '30-JUL-18 07:00:00', 'EST-5', '30-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 2, 'NW', 'ROCKY MT', 2, 'NW', 'ROCKY MT', 37.0225, -79.9082, 37.0225, -79.9082, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 1 to 3 inches across parts of Patrick, Franklin and Henry counties most of which fell in about a 3-hour period.', 'The CoCoRaHS station at Rocky Mount 2.2 NW had 3.27 inches for the 24-hour period ending 7 AM on the 31st.');
INSERT INTO public.stormevents_east VALUES (774618, 201807, 25, 1701, 201807, 25, 1800, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:01:00', 'EST-5', '25-JUL-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'ARCOLA GLASCOCK ARPT', 3, 'SSW', 'ARCOLA GLASCOCK ARPT', 38.8893, -77.5707, 38.8893, -77.5701, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Six inches of water flowing over Route 705 at Bull Run due to Bull Run flooding.');
INSERT INTO public.stormevents_east VALUES (774619, 201807, 25, 1704, 201807, 25, 1800, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:04:00', 'EST-5', '25-JUL-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'MC LEAN HAMLET', 1, 'NW', 'MC LEAN HAMLET', 38.9361, -77.2351, 38.936, -77.2352, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Gordon Lane flooded near Odricks Lane.');
INSERT INTO public.stormevents_east VALUES (774620, 201807, 25, 1708, 201807, 25, 1900, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:08:00', 'EST-5', '25-JUL-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'WELLINGTON', 1, 'SE', 'WELLINGTON', 38.7665, -77.5337, 38.7668, -77.5328, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Flooding reported on Bethlehem Road and Wellington Road, near where the two intersect. Both roads closed.');
INSERT INTO public.stormevents_east VALUES (774621, 201807, 25, 1724, 201807, 25, 1845, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:24:00', 'EST-5', '25-JUL-18 18:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'ARCOLA', 1, 'NW', 'ARCOLA', 38.9599, -77.5445, 38.9593, -77.544, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Evergreen Mills Road was flooded and closed near Belmont Ridge Road at Broad Run.');
INSERT INTO public.stormevents_east VALUES (774624, 201807, 25, 1749, 201807, 25, 2000, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 17:49:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'LENAH', 2, 'WSW', 'LENAH', 38.9381, -77.6053, 38.9378, -77.6052, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Lenah Road flooded and closed near Braddock Road.');
INSERT INTO public.stormevents_east VALUES (756718, 201805, 15, 1545, 201805, 15, 1545, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 1, 0, '5.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 2, 'W', 'NANUET', 2, 'W', 'NANUET', 41.08, -74.05, 41.08, -74.05, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree fell on car on Red Schoolhouse Road killing an 80 year old woman inside.');
INSERT INTO public.stormevents_east VALUES (756778, 201805, 15, 1635, 201805, 15, 1635, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:35:00', 'EST-5', '15-MAY-18 16:35:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 52, 'EG', NULL, NULL, 3, 'WNW', 'BROOKLYN', 3, 'WNW', 'BROOKLYN', 40.67, -73.99, 40.67, -73.99, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A tree on car on Saint John''s Place in Park Slope.');
INSERT INTO public.stormevents_east VALUES (756747, 201805, 15, 1512, 201805, 15, 1512, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:12:00', 'EST-5', '15-MAY-18 15:12:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'SE', 'CAMPBELL HALL', 1, 'SE', 'CAMPBELL HALL', 41.44, -74.26, 41.44, -74.26, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A tree down blocking road at Sarah Wells Trail and Hamptonburgh Road.');
INSERT INTO public.stormevents_east VALUES (756478, 201805, 15, 1516, 201805, 15, 1517, 124185, 'NEW YORK', 36, 2018, 'May', 'Tornado', 'OKX', '15-MAY-18 15:16:00', 'EST-5', '15-MAY-18 15:17:00', 0, 0, 1, 0, '50.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'NE', 'BALMVILLE', 1, 'ENE', 'BALMVILLE', 41.5359, -74.0123, 41.5361, -73.9999, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Based on a National Weather Service damage survey done in|conjunction with the Newburgh Fire Department, it has been |determined that an EF0 tornado went through the Balmville |neighborhood of Newburgh. The tornado originated near Albany Post |Road, to the south of the intersection with Bennet Road. A tree fell on a moving car on Albany Post Rd, killing the woman inside. The |tornado lifted near the Hudson River behind the house at 56 Susan |Drive. The tornado sheared off trees around half way to the |ground, peeled the bark off of one tree, and caused localized |convergence of uprooted trees. It also caused leaves to be |plastered on three sides of houses in the Susan Drive area. Based |on this, the tornado was classified as an EF0 tornado with an |estimated maximum wind speed of around 75 mph.');
INSERT INTO public.stormevents_east VALUES (783373, 201805, 15, 1543, 201805, 15, 1543, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:43:00', 'EST-5', '15-MAY-18 15:43:00', 1, 0, 1, 0, '5.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'N', 'DANBURY', 1, 'N', 'DANBURY', 41.4, -73.47, 41.4, -73.47, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree fell on truck in Candlewood Lake area killing a man.');
INSERT INTO public.stormevents_east VALUES (760836, 201805, 13, 1523, 201805, 13, 1523, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 15:23:00', 'EST-5', '13-MAY-18 15:23:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'E', 'CLAYSVILLE', 1, 'E', 'CLAYSVILLE', 40.12, -80.41, 40.12, -80.41, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'Public citizen reported trees down on a barn.');
INSERT INTO public.stormevents_east VALUES (783446, 201805, 15, 1540, 201805, 15, 1540, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:40:00', 'EST-5', '15-MAY-18 15:40:00', 1, 0, 1, 0, '5.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'S', 'NEWBURGH', 1, 'S', 'NEWBURGH', 41.4919, -74.0221, 41.4919, -74.0221, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree down on Robinson Avenue / Route 9 W near the New Windsor town line crushing a car.  An 11 year old girl inside the car was killed.');
INSERT INTO public.stormevents_east VALUES (769896, 201807, 25, 150, 201807, 25, 350, 127490, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RNK', '25-JUL-18 01:50:00', 'EST-5', '25-JUL-18 03:50:00', 0, 0, 0, 0, '0.50M', '0.00K', 'Newspaper', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'STONEVILLE', 2, 'N', 'INTELLIGENCE', 36.425, -79.9106, 36.3978, -79.9059, 'An unusually deep upper trough for July over the eastern U.S. extending all the way south to the Gulf Coast provided the setting for widespread shower and thunderstorm activity. Radar estimated rainfall of 2 to 4 inches in about 3 hours was observed across west central Rockingham County with a small area estimated at 4 to 6 inches between Intelligence and Mayodan. The annual recurrence interval of the heaviest rain approached 200-year (.005 annual exceedance probability) in a 3-hour period per NOAA Atlas 14.', 'A sinkhole formed and the road was badly damaged along North Carolina Route 135/311 where heavy rain occurred and runoff flowed across the road. The flooding was aggravated by a water main break under the road. Damage estimate per NC DOT. A water rescue also occurred where one person was stranded in a vehicle that was halfway submerged near the intersection of MacGregor Lane and River Road.');
INSERT INTO public.stormevents_east VALUES (777979, 201809, 27, 1602, 201809, 27, 1630, 129875, 'GEORGIA', 13, 2018, 'September', 'Thunderstorm Wind', 'FFC', '27-SEP-18 16:02:00', 'EST-5', '27-SEP-18 16:30:00', 0, 0, 0, 0, '20.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'S', 'JERSEY', 2, 'ESE', 'BRADLEY', 33.7198, -83.8, 33.8564, -83.598, 'Thunderstorms ahead of a cold front produced scattered reports of damaging wind gusts from west central Georgia into northeast Georgia.', 'The Walton County 911 center reported numerous trees and power lines blown down across the county from Jersey to Monroe and Social Circle to Mt. Vernon.');
INSERT INTO public.stormevents_east VALUES (778711, 201809, 20, 1354, 201809, 20, 1354, 130020, 'OHIO', 39, 2018, 'September', 'Thunderstorm Wind', 'CLE', '20-SEP-18 13:54:00', 'EST-5', '20-SEP-18 13:54:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'FARMINGTON', 0, 'N', 'FARMINGTON', 41.38, -80.97, 41.38, -80.97, 'A warm front lifted north across Ohio on September 20th ushering in unseasonably warm and humid weather.  Scattered thunderstorms developed along the front during the middle part of the afternoon.  A couple of thunderstorms became severe and one produced two tornadoes in Northeast Ohio.', 'Thunderstorm winds downed a tree.');
INSERT INTO public.stormevents_east VALUES (786966, 201809, 25, 1949, 201809, 25, 1952, 129599, 'MICHIGAN', 26, 2018, 'September', 'Tornado', 'DTX', '25-SEP-18 19:49:00', 'EST-5', '25-SEP-18 19:52:00', 0, 0, 0, 0, '150.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SSE', 'ROCKWOOD', 1, 'NNE', 'GIBRALTAR', 42.0616, -83.2444, 42.0871, -83.225, 'A robust upper level trough approached the western Great Lakes on September 25, while low pressure developed over northern Lower Michigan along a cold front draped over the region. Ahead of this cold front, southwest winds brought warm and moist air (dew points exceeding 70 degrees in a few areas) to Southeast Michigan during the daytime and evening hours. This moist air mass paired with ample wind shear was sufficient to generate three tornadoes, impacting northern Monroe and southern Wayne counties.', 'This tornado began in Berlin Township in Monroe County about 2 miles south of South Rockwood. The tornado entered Wayne County in Rockwood and then continued for another 2 miles, before dissipating near the intersection of Meadow Lane and Ostreich Road near the border of Brownstown Charter Township and the city of Gibraltar. The tornado remained at EF0 strength throughout the entire path length. Damage included multiple limbs and large trees downed, along with missing shingles to a house near the end of the tornado path.');
INSERT INTO public.stormevents_east VALUES (772387, 201808, 21, 1510, 201808, 21, 1511, 128081, 'PENNSYLVANIA', 42, 2018, 'August', 'Tornado', 'CTP', '21-AUG-18 15:10:00', 'EST-5', '21-AUG-18 15:11:00', 0, 0, 0, 0, '5.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'W', 'BROCKPORT', 1, 'N', 'BROCKPORT', 41.2496, -78.739, 41.262, -78.727, 'An EF-1 tornado touched down in Jefferson County, PA and traveled northeastward into Elk County, PA before lifting near Brockport. The maximum estimated wind speed was estimated at around 90 mph, with a total path length of 2.5 miles (including both Jefferson and Elk County) and a maximum path width of approximately 300 yards.', 'A NWS storm survey determined that an EF1 tornado touched down in Jefferson County, PA and traveled northeastward into Elk County, PA before lifting near Brockport. Maximum winds were estimated around 90 mph, with maximum path width of approximately 300 yards. The total path length of the tornado was 2.5 miles, with a little over a mile of that occurring in Elk County.');
INSERT INTO public.stormevents_east VALUES (782402, 201808, 3, 2200, 201808, 4, 100, 129820, 'GEORGIA', 13, 2018, 'August', 'Flash Flood', 'FFC', '03-AUG-18 22:00:00', 'EST-5', '04-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'NEW BRANCH', 1, 'NE', 'NEW BRANCH', 32.0757, -82.2003, 32.0854, -82.2408, 'Summertime showers and thunderstorms produced locally heavy rainfall in the afternoon and evening of August 3. Soils were saturated from rainfall early in the week, and combined with rainfall amounts of 2 to 4 inches to cause isolated flash flooding, particularly over portions of east central Georgia.', 'Flash flooding was reported at several locations west-southwest of Reidsville in Toombs County, including the intersection of Jack Collins Road and Levy Cave Road, the intersection of Highway 56 and Ernest Webber Road, Bud Clifton Road, Jim Shuman Road, and Ben Usher Road. Radar estimates indicate that rainfall amounts of 2.5 to 4 inches occurred in a short period of time.');
INSERT INTO public.stormevents_east VALUES (775611, 201808, 4, 0, 201808, 4, 200, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 00:00:00', 'EST-5', '04-AUG-18 02:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WALKERSVILLE', 1, 'SSE', 'WALKERSVILLE', 39.47, -77.35, 39.4695, -77.3439, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'Stauffer Road was closed due to high water in Walkersville.');
INSERT INTO public.stormevents_east VALUES (775613, 201808, 4, 58, 201808, 4, 258, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 00:58:00', 'EST-5', '04-AUG-18 02:58:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'SPRINGS MILL', 1, 'SSE', 'SPRINGS MILL', 39.5401, -77.0198, 39.5427, -77.0175, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'MD-27 Ridge Road was closed due to flooding between Lone Tree Road and Kate Wagner Road.');
INSERT INTO public.stormevents_east VALUES (775614, 201808, 4, 124, 201808, 4, 324, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 01:24:00', 'EST-5', '04-AUG-18 03:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'NEW WINDSOR', 1, 'SW', 'NEW WINDSOR', 39.54, -77.11, 39.54, -77.1104, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'MD-31 New Windsor Road was closed due to flooding at Dickenson Run near Coe Drive.');
INSERT INTO public.stormevents_east VALUES (775615, 201808, 4, 305, 201808, 4, 505, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 03:05:00', 'EST-5', '04-AUG-18 05:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'NE', 'JOHNSVILLE', 3, 'NE', 'JOHNSVILLE', 39.56, -77.18, 39.5591, -77.1809, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'MD-75 South Main Street was closed at Sams Creek south of Church Street due to flooding.');
INSERT INTO public.stormevents_east VALUES (778138, 201808, 7, 1850, 201808, 7, 1850, 129890, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '07-AUG-18 18:50:00', 'EST-5', '07-AUG-18 18:50:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 26, 'S', 'SANDY POINT (SPT)', 26, 'S', 'SANDY POINT (SPT)', 38.638, -76.323, 38.638, -76.323, 'An upper level low near the region combined with high instability and increasing winds aloft to produce thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of 36 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778142, 201808, 11, 1810, 201808, 11, 1810, 129892, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '11-AUG-18 18:10:00', 'EST-5', '11-AUG-18 18:10:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 4, 'SE', 'US-50 (MD040)', 4, 'SE', 'US-50 (MD040)', 38.929, -76.204, 38.929, -76.204, 'A weak boundary was positioned overhead while an upper-level trough moved into the area. Showers and thunderstorms developed and some produced strong winds over the waters.', 'A wind gust of 38 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778144, 201808, 11, 1917, 201808, 11, 1917, 129892, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '11-AUG-18 19:17:00', 'EST-5', '11-AUG-18 19:17:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 4, 'E', 'KENT POINT MD (KPTM2)', 4, 'E', 'KENT POINT MD (KPTM2)', 38.839, -76.305, 38.839, -76.305, 'A weak boundary was positioned overhead while an upper-level trough moved into the area. Showers and thunderstorms developed and some produced strong winds over the waters.', 'A wind gust of 41 knots was measured.');
INSERT INTO public.stormevents_east VALUES (775594, 201808, 4, 500, 201808, 4, 954, 129454, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 05:00:00', 'EST-5', '04-AUG-18 09:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'WNW', 'BURR HILL', 4, 'WNW', 'BURR HILL', 38.3615, -77.9419, 38.3602, -77.9346, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'The USGS stream gage on the Rapidan River near Culpeper exceeded the 13 foot flood stage during the indicated period. The peak level of 13.32 feet occurred at 7:45am EST. |VA-611 Raccoon Ford Road was closed due to flooding along the Rapidan River.');
INSERT INTO public.stormevents_east VALUES (775609, 201808, 4, 230, 201808, 4, 730, 129459, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '04-AUG-18 02:30:00', 'EST-5', '04-AUG-18 07:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'COVER', 1, 'S', 'COVER', 39.41, -77.12, 39.4093, -77.118, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'Gillis Falls Road was washed out at Middle Run.');
INSERT INTO public.stormevents_east VALUES (781572, 201808, 31, 2219, 201808, 31, 2345, 130417, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 22:19:00', 'EST-5', '31-AUG-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'WSW', 'ALEXANDRIA', 3, 'WSW', 'ALEXANDRIA', 38.8058, -77.1303, 38.8056, -77.1305, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'A water rescue took place for multiple cars trapped in high water. A dumpster was floating down the 600 Block of South Picket Street near South Van Dorn Street.');
INSERT INTO public.stormevents_east VALUES (774892, 201808, 1, 143, 201808, 1, 343, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 01:43:00', 'EST-5', '01-AUG-18 03:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'CATHARPIN', 2, 'SSE', 'CATHARPIN', 38.82, -77.55, 38.8199, -77.5466, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Featherbed Lane was closed due to flooding near US-29 Lee Highway.');
INSERT INTO public.stormevents_east VALUES (774900, 201808, 1, 220, 201808, 1, 420, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 02:20:00', 'EST-5', '01-AUG-18 04:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'FAIRFAX STATION', 0, 'W', 'FAIRFAX STATION', 38.8, -77.33, 38.8009, -77.329, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'A car was stuck in high water in the 11000 Block of Fairfax Station Road.');
INSERT INTO public.stormevents_east VALUES (775006, 201808, 2, 1653, 201808, 2, 1653, 129346, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '02-AUG-18 16:53:00', 'EST-5', '02-AUG-18 16:53:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'MC GAHEYSVILLE', 1, 'N', 'MC GAHEYSVILLE', 38.38, -78.73, 38.38, -78.73, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'Downed trees due to thunderstorm wind gusts closed Route 33 in the area of Island Ford Road. Trees were also blown down in the 1000 block of McGaheysville Road, the 700 block of Jacob Burner Drive, and the 300 block of McGahey Lane.');
INSERT INTO public.stormevents_east VALUES (788063, 201808, 31, 2204, 201808, 31, 2308, 130417, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'LWX', '31-AUG-18 22:04:00', 'EST-5', '31-AUG-18 23:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'ALEXANDRIA', 1, 'NW', 'POTOMAC YARD', 38.8088, -77.1183, 38.8409, -77.0978, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The gauge at Cameron Run in Alexandria rapidly surpassed flood stage of 9.5 feet and crested at 12.41 feet. Most of the Lower Holmes Run Trail along Cameron Run was flooded. Backwater flooding affected the areas along Backlick Run. Water overflowed the banks on both sides of Cameron Run upstream of the railroad culverts.  ||The gauge at Fourmile run rapidly passed flood stage of 12 feet and crested at 12.26 feet. Water flooded the north bank into grassy areas and parking lots. ||The gauge at Cameron Run and Eisenhower Avenue rapidly surpassed flood stage of 8 feet, cresting at 12.25 feet.');
INSERT INTO public.stormevents_east VALUES (774876, 201808, 1, 49, 201808, 1, 249, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 00:49:00', 'EST-5', '01-AUG-18 02:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'SOWEGO', 2, 'W', 'SOWEGO', 38.6063, -77.6043, 38.6045, -77.6036, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'All of VA-609 Courthouse Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (774881, 201808, 1, 100, 201808, 1, 300, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 01:00:00', 'EST-5', '01-AUG-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'ADEN', 2, 'E', 'ADEN', 38.6526, -77.5232, 38.6451, -77.4895, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-646 Aden Road was closed due to flooding between VA-611 Fleetwood Drive and Bristow Road.');
INSERT INTO public.stormevents_east VALUES (761193, 201805, 22, 1819, 201805, 22, 1819, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:19:00', 'EST-5', '22-MAY-18 18:19:00', 0, 0, 0, 0, '0.25K', '0.00K', 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'ESE', 'NOBLESTOWN', 1, 'ESE', 'NOBLESTOWN', 40.37, -80.18, 40.37, -80.18, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Local media reported trees snapped in Sterling Ridge neighborhood.');
INSERT INTO public.stormevents_east VALUES (761194, 201805, 22, 1824, 201805, 22, 1824, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:24:00', 'EST-5', '22-MAY-18 18:24:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'BOYCE', 1, 'W', 'BOYCE', 40.32, -80.12, 40.32, -80.12, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported a tree down on power lines along Mayview Road.');
INSERT INTO public.stormevents_east VALUES (761195, 201805, 22, 1826, 201805, 22, 1826, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:26:00', 'EST-5', '22-MAY-18 18:26:00', 0, 0, 0, 0, '0.25K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'MUSE', 1, 'S', 'MUSE', 40.28, -80.2, 40.28, -80.2, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported a tree down blocking Muse Bishop Road.');
INSERT INTO public.stormevents_east VALUES (761196, 201805, 22, 1827, 201805, 22, 1827, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:27:00', 'EST-5', '22-MAY-18 18:27:00', 0, 0, 0, 0, '0.25K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'SW', 'MORGANZA', 1, 'SW', 'MORGANZA', 40.26, -80.16, 40.26, -80.16, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported a tree down on McGregor Drive.');
INSERT INTO public.stormevents_east VALUES (761197, 201805, 22, 1829, 201805, 22, 1829, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:29:00', 'EST-5', '22-MAY-18 18:29:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'MC MURRAY', 1, 'W', 'MC MURRAY', 40.28, -80.09, 40.28, -80.09, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported a tree and wires down in Mc Murray.');
INSERT INTO public.stormevents_east VALUES (800241, 201809, 1, 1551, 201809, 1, 1551, 133722, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '01-SEP-18 15:51:00', 'EST-5', '01-SEP-18 15:51:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSE', 'BROADVIEW', 1, 'SSW', 'KOONTZVILLE', 36.1217, -79.7744, 36.1418, -79.7749, 'A strongly unstable air mass combined with an upper level disturbance to trigger numerous thunderstorms across the northern Piedmont, with a few reports of wind damage and one report of flash flooding. Storms produced a massive outflow boundary and excessive amounts of lightning. Storm coverage was more limited to the south and east in the Coastal Plain and southern Piedmont.', 'Two trees were reported down near Yanceyville Street between Lee''s Chapel Road and the railroad tracks.');
INSERT INTO public.stormevents_east VALUES (760837, 201805, 13, 1526, 201805, 13, 1526, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 15:26:00', 'EST-5', '13-MAY-18 15:26:00', 0, 0, 0, 0, '2.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'CLAYSVILLE', 1, 'E', 'CLAYSVILLE', 40.12, -80.41, 40.12, -80.41, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'State official reported trees down in Claysville.');
INSERT INTO public.stormevents_east VALUES (750801, 201805, 27, 415, 201805, 27, 415, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 04:15:00', 'EST-5', '27-MAY-18 04:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 12, 'E', 'VERO BEACH', 12, 'E', 'VERO BEACH', 27.656, -80.376, 27.656, -80.376, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'The ASOS at the Vero Beach Airport, KVRB, measured a peak wind gust of 38 knots from the south.');
INSERT INTO public.stormevents_east VALUES (750802, 201805, 27, 440, 201805, 27, 440, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 04:40:00', 'EST-5', '27-MAY-18 04:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 3, 'ESE', 'MICCO', 3, 'ESE', 'MICCO', 27.86, -80.45, 27.86, -80.45, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'Mesonet site SIPF1 at Sebastian Inlet measured a peak wind gust of 36 knots.');
INSERT INTO public.stormevents_east VALUES (752587, 201805, 30, 1300, 201805, 30, 1300, 125036, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '30-MAY-18 13:00:00', 'EST-5', '30-MAY-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 36, 'MG', NULL, NULL, 7, 'NE', 'CAPE CANAVERAL', 7, 'NE', 'CAPE CANAVERAL', 28.46, -80.53, 28.46, -80.53, 'East central Florida remained sandwiched between a mid-level trough over the Gulf of Mexico and high pressure ridge extending from just east of the Bahamas extending well into the Great Lakes region. This set up brought a deep layer, moist, south-southwest flow into the region. Showers and thunderstorms developed across the area in the afternoon and pushed towards the east coast eventually becoming a consistent line. As these storms moved across the intracoastal and nearshore waters of Brevard County, they produced strong winds.', 'US Air Force wind tower 0003 measured a peak wind gust of 36 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (769166, 201806, 21, 1525, 201806, 21, 1525, 128241, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '21-JUN-18 15:25:00', 'EST-5', '21-JUN-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 13, 'WSW', 'MAYPORT NAS', 13, 'WSW', 'MAYPORT NAS', 30.34, -81.63, 30.34, -81.63, 'A low level trough axis lingered across north-central Florida which served as a focus for an early start to diurnally enhanced showers and thunderstorms. Locally heavy rainfall occurred along and near this trough axis. A few strong outflow wind gusts impacted the adjacent Atlantic waters.', 'A WeatherFlow sensor measured a wind gust to 40 mph.');
INSERT INTO public.stormevents_east VALUES (769199, 201806, 25, 2105, 201806, 25, 2105, 128244, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '25-JUN-18 21:05:00', 'EST-5', '25-JUN-18 21:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'E', 'MC ALPIN', 4, 'E', 'MC ALPIN', 30.13, -82.89, 30.13, -82.89, 'Sea breeze induced storms produced locally strong winds over Suwanee County over a moist and unstable airmass.', 'A power line was blown down near County Road 40 and 200th Street. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (769416, 201806, 26, 1420, 201806, 26, 1420, 128291, 'FLORIDA', 12, 2018, 'June', 'Hail', 'JAX', '26-JUN-18 14:20:00', 'EST-5', '26-JUN-18 14:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 1, 'NE', 'FRUIT COVE', 1, 'NE', 'FRUIT COVE', 30.11, -81.62, 30.11, -81.62, 'Very light steering flow and a moist airmass promoted locally heavy rainfall in sea breezes storms.', NULL);
INSERT INTO public.stormevents_east VALUES (769417, 201806, 26, 1545, 201806, 26, 1645, 128291, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '26-JUN-18 15:45:00', 'EST-5', '26-JUN-18 16:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 3, 'SSE', 'LA CROSSE', 3, 'SSE', 'LA CROSSE', 29.81, -82.39, 29.81, -82.39, 'Very light steering flow and a moist airmass promoted locally heavy rainfall in sea breezes storms.', 'A rainfall total of 3.80 inches was measured in 1 hour.');
INSERT INTO public.stormevents_east VALUES (769418, 201806, 26, 1615, 201806, 26, 1900, 128291, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '26-JUN-18 16:15:00', 'EST-5', '26-JUN-18 19:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Park/Forest Service', NULL, NULL, NULL, NULL, 2, 'ENE', 'GENOA', 2, 'ENE', 'GENOA', 30.41, -82.79, 30.41, -82.79, 'Very light steering flow and a moist airmass promoted locally heavy rainfall in sea breezes storms.', 'The Suwanee River Water Management District office rain gauge measured 2.91 inches of rainfall.');
INSERT INTO public.stormevents_east VALUES (769419, 201806, 26, 1348, 201806, 26, 1348, 128291, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '26-JUN-18 13:48:00', 'EST-5', '26-JUN-18 13:48:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 2, 'SE', 'MARIETTA', 2, 'SE', 'MARIETTA', 30.3, -81.75, 30.3, -81.75, 'Very light steering flow and a moist airmass promoted locally heavy rainfall in sea breezes storms.', 'A structure fire was the result of a lightning strike at 6300 Park Street. The cost of damage was unknown, but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (771178, 201806, 10, 1058, 201806, 10, 1058, 128495, 'FLORIDA', 12, 2018, 'June', 'Funnel Cloud', 'MFL', '10-JUN-18 10:58:00', 'EST-5', '10-JUN-18 10:58:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 2, 'WNW', 'MIRAMAR', 2, 'WNW', 'MIRAMAR', 26.01, -80.43, 26.01, -80.43, 'The Atlantic seabreeze developed during the late morning hours of June 10th, quickly moving west and colliding with the Gulf breeze across Collier, Hendry, and Glades counties during the afternoon hours. Shower and storm development along these boundaries was enhanced by an upper level low across the eastern Gulf of Mexico, allowing several strong storms to develop. A funnel cloud was reported in Broward County with the morning activity, along with several reports of hail across inland Collier County during the afternoon hours.', 'A photo of a funnel cloud was reported via Twitter from a member of the public.');
INSERT INTO public.stormevents_east VALUES (771180, 201806, 11, 931, 201806, 11, 931, 128496, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'MFL', '11-JUN-18 09:31:00', 'EST-5', '11-JUN-18 09:31:00', 0, 0, 0, 0, NULL, NULL, 'Airplane Pilot', NULL, NULL, NULL, NULL, 30, 'ENE', 'BOCA RATON', 30, 'ENE', 'BOCA RATON', 26.5, -79.64, 26.5, -79.64, 'Showers and storms across the local Atlantic moving into the east coast during the morning hours, producing a waterspout and strong wind gusts offshore Palm Beach County.', 'A pilot report came in of a waterspout at 128 degrees, 28 nautical miles east of Palm Beach International Airport.');
INSERT INTO public.stormevents_east VALUES (774505, 201807, 24, 555, 201807, 24, 800, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '24-JUL-18 05:55:00', 'EST-5', '24-JUL-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'WSW', 'TREMONT', 38.8459, -77.2383, 38.8456, -77.2377, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Woodburn Road flooded and closed near Spicewood Drive.');
INSERT INTO public.stormevents_east VALUES (766251, 201806, 2, 1705, 201806, 2, 1705, 127224, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '02-JUN-18 17:05:00', 'EST-5', '02-JUN-18 17:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 13, 'WSW', 'MAYPORT NAS', 13, 'WSW', 'MAYPORT NAS', 30.34, -81.63, 30.34, -81.63, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', NULL);
INSERT INTO public.stormevents_east VALUES (776173, 201807, 21, 2032, 201807, 21, 2032, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '21-JUL-18 20:32:00', 'EST-5', '21-JUL-18 20:32:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'ELLERBE', 1, 'E', 'ELLERBE', 35.0713, -79.7616, 35.0713, -79.7616, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'A power-line was reported down across Page Street.');
INSERT INTO public.stormevents_east VALUES (776177, 201807, 21, 2040, 201807, 21, 2040, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '21-JUL-18 20:40:00', 'EST-5', '21-JUL-18 20:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'GARREN HILL', 1, 'E', 'GARREN HILL', 35.18, -79.51, 35.18, -79.51, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'One tree was blown down along Foxfire Road.');
INSERT INTO public.stormevents_east VALUES (776181, 201807, 21, 2105, 201807, 21, 2105, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '21-JUL-18 21:05:00', 'EST-5', '21-JUL-18 21:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NW', 'OAK RIDGE ARPT', 3, 'NW', 'OAK RIDGE ARPT', 36.2291, -80.0346, 36.2291, -80.0346, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'One tree was reported down on Coldwater Road, near U.S. Highway 158.');
INSERT INTO public.stormevents_east VALUES (776184, 201807, 21, 2113, 201807, 21, 2113, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '21-JUL-18 21:13:00', 'EST-5', '21-JUL-18 21:13:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SSW', 'SUMMERFIELD', 3, 'SSW', 'SUMMERFIELD', 36.165, -79.9161, 36.165, -79.9161, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'One tree was reported down on Stanely Huff Road, near Deer Meadow Lane.');
INSERT INTO public.stormevents_east VALUES (766272, 201806, 3, 1742, 201806, 3, 1742, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:42:00', 'EST-5', '03-JUN-18 17:42:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'GAINESVILLE WEST', 2, 'W', 'GAINESVILLE WEST', 29.65, -82.36, 29.65, -82.36, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Power lines were blown down near SW 2nd Ave.');
INSERT INTO public.stormevents_east VALUES (766273, 201806, 3, 1742, 201806, 3, 1742, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:42:00', 'EST-5', '03-JUN-18 17:42:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'GAINESVILLE NORTH', 1, 'E', 'GAINESVILLE NORTH', 29.67, -82.31, 29.67, -82.31, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'A large oak tree was blown down on the road near NE 20th Ave and NE 8th Street.');
INSERT INTO public.stormevents_east VALUES (766274, 201806, 3, 1745, 201806, 3, 1745, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:45:00', 'EST-5', '03-JUN-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'GAINESVILLE', 1, 'N', 'GAINESVILLE', 29.66, -82.32, 29.66, -82.32, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'Power lines were blown down at 725 NE 5th Terrace.');
INSERT INTO public.stormevents_east VALUES (781491, 201807, 27, 1932, 201807, 27, 2020, 128280, 'MARYLAND', 24, 2018, 'July', 'Flash Flood', 'LWX', '27-JUL-18 19:32:00', 'EST-5', '27-JUL-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SINGER', 1, 'SW', 'SINGER', 39.474, -76.3374, 39.4728, -76.3364, 'Heavy rain fell on saturated ground during the afternoon and evening of July 27th in the Baltimore metro area. One to three inches of rain was observed, along with numerous instances of flooding.', 'The USGS stream gage on Otter Point rapidly but briefly exceeded the 8 foot flood stage during the indicated period, causing flooding on Winters Run Road. The peak of 8.39 feet occurred at 8:00pm EST.');
INSERT INTO public.stormevents_east VALUES (753504, 201805, 3, 1812, 201805, 3, 1812, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:12:00', 'EST-5', '03-MAY-18 18:12:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 50, 'MG', NULL, NULL, 0, 'ESE', 'BAYVILLE WXFLOW', 0, 'ESE', 'BAYVILLE WXFLOW', 40.8997, -73.6291, 40.8997, -73.6291, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 50 knot gust was reported at the Bayville mesonet location.');
INSERT INTO public.stormevents_east VALUES (753499, 201805, 3, 1816, 201805, 3, 1816, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:16:00', 'EST-5', '03-MAY-18 18:16:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 40, 'MG', NULL, NULL, 1, 'WNW', 'LARCHMONT HARBOR WXFLOW', 1, 'WNW', 'LARCHMONT HARBOR WXFLOW', 40.9298, -73.7496, 40.9298, -73.7496, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 40 knot gust was reported at Larchmont mesonet location.');
INSERT INTO public.stormevents_east VALUES (753506, 201805, 3, 1817, 201805, 3, 1817, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:17:00', 'EST-5', '03-MAY-18 18:17:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 51, 'MG', NULL, NULL, 2, 'SE', 'STATION 44022', 2, 'SE', 'STATION 44022', 40.8603, -73.7099, 40.8603, -73.7099, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 51 knot wind gust was reported at the Sands Point mesonet location.');
INSERT INTO public.stormevents_east VALUES (753511, 201805, 3, 1824, 201805, 3, 1824, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:24:00', 'EST-5', '03-MAY-18 18:24:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 2, 'ENE', 'STATION KPTN6', 2, 'ENE', 'STATION KPTN6', 40.8202, -73.7388, 40.8202, -73.7388, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 36 knot gust was reported at the Kings Point mesonet location.');
INSERT INTO public.stormevents_east VALUES (753992, 201805, 3, 1825, 201805, 3, 1825, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 18:25:00', 'EST-5', '03-MAY-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 1, 'SSE', 'EATONS NECK WXFLOW', 1, 'SSE', 'EATONS NECK WXFLOW', 40.9402, -73.3914, 40.9402, -73.3914, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 38 knot gust was reported at Eatons Neck mesonet location.');
INSERT INTO public.stormevents_east VALUES (761268, 201805, 31, 1835, 201805, 31, 1935, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 18:35:00', 'EST-5', '31-MAY-18 19:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'WOODBRIDGE', 0, 'WNW', 'WOODBRIDGE', 38.652, -77.2563, 38.6524, -77.2566, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The intersection of US 1 and Marys Way / Mount Pleasant Drive had to be closed due to a foot of water over the roadway.');
INSERT INTO public.stormevents_east VALUES (800386, 201812, 15, 2141, 201812, 17, 546, 133708, 'WEST VIRGINIA', 54, 2018, 'December', 'Flood', 'LWX', '15-DEC-18 21:41:00', 'EST-5', '17-DEC-18 05:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'MARTINSBURG', 0, 'SE', 'BLAIRTON', 39.454, -77.9507, 39.4497, -77.9194, 'A potent upper-level low and associated area of surface low pressure approached the region from southwest on the 15th. Strong forcing for ascent and ample moisture transport in advance of the upper level low led to a prolonged period of rain across the region. Eventually low pressure transferred to the coast before precipitation wound down on the 16th. Widespread rainfall totals of 2-4 inches were observed across the area.', 'The river gage on the Opequon Creek at Martinsburg exceeded the 12.5 foot flood stage during the indicated period. This pushed the creek well out of its banks, leading to flooding in the nearby lowlands. Fields and backyards near the creek flooded, along with many local roads. Golf Course Road (County Road 36) was flooded near the Van Metre Ford Pedestrian Bridge. Several other roads experienced flooding, including Grapevine Road, Douglas Grove Road, and Paynes Ford Road. Backwater flooding also occurred on small tributaries, including Tuscarora Creek. The peak level of 13.52 feet occurred at 3:30 PM on December 16th.');
INSERT INTO public.stormevents_east VALUES (760937, 201805, 27, 1354, 201805, 27, 1600, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 13:54:00', 'EST-5', '27-MAY-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'WHITE MARSH', 1, 'WSW', 'WHITE MARSH', 39.3755, -76.4602, 39.3743, -76.4557, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'The stream gage on Whitemarsh Run at White Marsh rapidly exceeded the 11 foot flood stage during the times indicated. Parking lots near the stream, and Town Center Court, were flooded. The peak level of 13.42 feet was observed at 2:45pm EST on May 27th.');
INSERT INTO public.stormevents_east VALUES (759988, 201805, 27, 1500, 201805, 27, 1700, 126460, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 15:00:00', 'EST-5', '27-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'HARRISONBURG', 2, 'ESE', 'HARRISONBURG', 38.4389, -78.8467, 38.4384, -78.8455, 'Scattered thunderstorms developed ahead of a cold front over Maryland during the afternoon hours of May 27th. Moderate to heavy rain on saturated soil produced flooding in portions of northern Virginia. The soils were so saturated that just moderate rain caused more flooding near Harrisonburg during the afternoon of the 28th as the cold front pushed through the region.', 'A portion of Country Club Road in Harrisonburg was flooded.');
INSERT INTO public.stormevents_east VALUES (759989, 201805, 27, 1500, 201805, 27, 1700, 126460, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 15:00:00', 'EST-5', '27-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'HUNTLY', 1, 'SSE', 'HUNTLY', 38.801, -78.1105, 38.8108, -78.1095, 'Scattered thunderstorms developed ahead of a cold front over Maryland during the afternoon hours of May 27th. Moderate to heavy rain on saturated soil produced flooding in portions of northern Virginia. The soils were so saturated that just moderate rain caused more flooding near Harrisonburg during the afternoon of the 28th as the cold front pushed through the region.', 'US Highway 522 was flooded and closed near Huntly.  The segment from Flint Hill to Chester Gap was closed.');
INSERT INTO public.stormevents_east VALUES (759994, 201805, 28, 1443, 201805, 28, 1643, 126460, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '28-MAY-18 14:43:00', 'EST-5', '28-MAY-18 16:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'HARRISONBURG', 1, 'ESE', 'HARRISONBURG', 38.4435, -78.8512, 38.4428, -78.8508, 'Scattered thunderstorms developed ahead of a cold front over Maryland during the afternoon hours of May 27th. Moderate to heavy rain on saturated soil produced flooding in portions of northern Virginia. The soils were so saturated that just moderate rain caused more flooding near Harrisonburg during the afternoon of the 28th as the cold front pushed through the region.', 'Several roads flooded in the City of Harrisonburg, including portions of Country Club Road, Blue Ridge Drive, and Star Crest Road.');
INSERT INTO public.stormevents_east VALUES (758541, 201805, 17, 227, 201805, 18, 1703, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 02:27:00', 'EST-5', '18-MAY-18 17:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'SE', 'RIDGEWAY', 2, 'SE', 'RIDGEWAY', 39.2625, -78.0243, 39.2783, -78.0454, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'The stream gage on Opequon Creek near Martinsburg exceeded the 10 foot flood stage between the times indicated. The peak river level was the highest recorded since 2014, reaching 14.36 feet at 6pm EST on May 17th. Numerous roads flooded within the designated area, along with backyards and outbuildings.');
INSERT INTO public.stormevents_east VALUES (758558, 201805, 19, 53, 201805, 20, 1035, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '19-MAY-18 00:53:00', 'EST-5', '20-MAY-18 10:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'SE', 'RIDGEWAY', 2, 'SE', 'RIDGEWAY', 39.2625, -78.0243, 39.2783, -78.0454, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'The stream gage on Opequon Creek near Martinsburg exceeded the 10 foot flood stage between the times indicated. The peak river level reached 12.49 feet at 12:30am EST on May 20th. Numerous roads flooded within the designated area.');
INSERT INTO public.stormevents_east VALUES (760004, 201805, 30, 2030, 201805, 30, 2130, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 20:30:00', 'EST-5', '30-MAY-18 21:30:00', 0, 0, 2, 0, '20.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'FARMINGTON', 1, 'NW', 'FARMINGTON', 38.0659, -78.5679, 38.0642, -78.5693, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Two cars were swept off Old Ballard Road at Ivy Creek. The occupant of one vehicle escaped and was rescued. The second vehicle was observed to repeatedly toss and overturn in the raging floodwaters. The two occupants of that vehicle could not be rescued and were found dead.');
INSERT INTO public.stormevents_east VALUES (795054, 201812, 21, 1205, 201812, 21, 1405, 132838, 'MASSACHUSETTS', 25, 2018, 'December', 'Flood', 'BOX', '21-DEC-18 12:05:00', 'EST-5', '21-DEC-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'VINING HILL', 2, 'NNW', 'VINING HILL', 42.063, -72.8173, 42.0608, -72.8191, 'A storm passing west of Massachusetts brought strong to damaging south winds to Central and Eastern Massachusetts on Friday December 21.  The same storm also brought one to four inches of rain.', 'At 12:05 PM EST, Kline Road in Southwick was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (795061, 201812, 21, 1405, 201812, 21, 1605, 132838, 'MASSACHUSETTS', 25, 2018, 'December', 'Flood', 'BOX', '21-DEC-18 14:05:00', 'EST-5', '21-DEC-18 16:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'HOLYOKE', 0, 'NW', 'HOLYOKE', 42.2098, -72.6256, 42.2054, -72.6263, 'A storm passing west of Massachusetts brought strong to damaging south winds to Central and Eastern Massachusetts on Friday December 21.  The same storm also brought one to four inches of rain.', 'At 2:05 PM EST, a car was reported trapped in flood waters on St. Jerome Avenue in Holyoke.');
INSERT INTO public.stormevents_east VALUES (795070, 201812, 21, 1410, 201812, 21, 1610, 132862, 'CONNECTICUT', 9, 2018, 'December', 'Flood', 'BOX', '21-DEC-18 14:10:00', 'EST-5', '21-DEC-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'BURNSIDE', 1, 'NE', 'BURNSIDE', 41.7856, -72.6144, 41.7859, -72.6136, 'A storm passing west of Connecticut brought strong south winds to northern Connecticut on Friday December 21. The same storm also brought one to four inches of rain.', 'At 2:05 PM EST, multiple cars were trapped in eighteen inches of flood waters at junction of School Street and Prestige Park Road in East Hartford.');
INSERT INTO public.stormevents_east VALUES (776251, 201807, 25, 120, 201807, 25, 159, 129576, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '25-JUL-18 01:20:00', 'EST-5', '25-JUL-18 01:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'DONNAHA', 2, 'SSW', 'TOBACCOVILLE', 36.21, -80.41, 36.2082, -80.3969, 'After receiving 3 to 5 inches of heavy rainfall across the northwest Piedmont earlier in the afternoon on the 24th, another round of training showers and thunderstorms|overnight dropped an additional two to three inches of rain fell across western and northern portions of Forsyth County.', 'Heavy rain caused nearby creeks and streams to overflow their banks, flooding portions of Reynolda Road.');
INSERT INTO public.stormevents_east VALUES (770130, 201807, 30, 700, 201807, 31, 700, 128374, 'VIRGINIA', 51, 2018, 'July', 'Heavy Rain', 'RNK', '30-JUL-18 07:00:00', 'EST-5', '31-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'WNW', 'HENRY FORK', 2, 'WNW', 'HENRY FORK', 36.977, -79.896, 36.977, -79.896, 'An upper ridge off the east coast and an upper low over the central U.S. combined to bring enhanced moisture into the region. Weak low pressure along a frontal boundary draped near the Virginia-North Carolina border provided additional convergence and lift to produce widespread showers and thunderstorms mainly over the piedmont and Blue Ridge foothills. Rainfall ranged from 1 to 3 inches across parts of Patrick, Franklin and Henry counties most of which fell in about a 3-hour period.', 'The Rocky Mount COOP observer had 2.45 inches for the 24-hour period ending at 7 AM on July 31st which was a record for the date and 10th highest for any July day. Data at this station extends back to 1894.');
INSERT INTO public.stormevents_east VALUES (771153, 201806, 6, 1500, 201806, 6, 1500, 128489, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '06-JUN-18 15:00:00', 'EST-5', '06-JUN-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 35, 'MG', NULL, NULL, 12, 'NNE', 'ELLIOT KEY', 12, 'NNE', 'ELLIOT KEY', 25.59, -80.1, 25.59, -80.1, 'Abundant moisture and a weak stationary front across Central Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity moved across Lake Okeechobee during the early afternoon hours, and then off the coast into the local Atlantic waters, producing several strong wind gusts.', 'A thunderstorm produced a wind gust of 40 mph/35 knots at C-Man station Fowey Rocks/FWFY1. This site is elevated at 144 feet.');
INSERT INTO public.stormevents_east VALUES (771199, 201806, 27, 1230, 201806, 27, 1230, 128507, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MFL', '27-JUN-18 12:30:00', 'EST-5', '27-JUN-18 12:30:00', 0, 0, 0, 0, NULL, NULL, 'Public', 0.75, NULL, NULL, NULL, 4, 'W', 'LAUDERDALE LAKES', 4, 'W', 'LAUDERDALE LAKES', 26.15, -80.26, 26.15, -80.26, 'Showers and storms developed along the Gulf and Atlantic seabreezes during the late morning and afternoon hours across South Florida. Several rounds of storms developed along the Atlantic seabreeze over the east coast metro, producing several reports of small hail in Broward County around midday.', 'Public report of penny sized hail near the intersection of University Drive and Sunrise Boulevard in Plantation.');
INSERT INTO public.stormevents_east VALUES (771145, 201806, 4, 1825, 201806, 4, 1825, 128486, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '04-JUN-18 18:25:00', 'EST-5', '04-JUN-18 18:25:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 1, 'NNW', 'GOVERNMENT CUT', 1, 'NNW', 'GOVERNMENT CUT', 25.7822, -80.1332, 25.7822, -80.1332, 'Abundant moisture and a weak frontal boundary across north Florida lead to numerous afternoon and evening showers and thunderstorms across South Florida. This activity pushed off the coast into the local Atlantic waters during the early evening hours, producing several strong wind gusts.', 'A wind gust of 41 mph/36 knots was measured at the WeatherBug site at Miami Beach police headquarters at a height of 60 feet.');
INSERT INTO public.stormevents_east VALUES (774403, 201807, 6, 1403, 201807, 6, 1403, 129213, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '06-JUL-18 14:03:00', 'EST-5', '06-JUL-18 14:03:00', 0, 0, 0, 0, '1.00K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'ESE', 'LAWSONVILLE', 1, 'ESE', 'LAWSONVILLE', 36.3933, -79.5549, 36.3933, -79.5549, 'A cold front started moving into the region during the morning hours, and by evening was east of the region. As it passed through the area, showers and storms accompanied it, some reaching severe levels with winds that blew down trees and power lines.', 'Thunderstorm winds blew a couple of trees down near the intersection of Highway 158 and Grooms Road near Lick Fork Creek Road. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (774415, 201807, 11, 1738, 201807, 11, 1738, 129235, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RNK', '11-JUL-18 17:38:00', 'EST-5', '11-JUL-18 17:38:00', 0, 0, 0, 0, '1.50K', NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'NNE', 'BRANCH', 1, 'NNE', 'BRANCH', 36.5075, -79.2955, 36.5075, -79.2955, 'A cold front moved into a moisture-rich and hot Summertime air mass and triggered showers and storms. One of these storms increased to severe levels, producing damaging winds.', 'Thunderstorm winds blew a tree and several wrist-size tree limbs down on Blanch Road in Blanch, NC. Damage values are estimated.');
INSERT INTO public.stormevents_east VALUES (776250, 201807, 24, 1130, 201807, 24, 1429, 129576, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '24-JUL-18 11:30:00', 'EST-5', '24-JUL-18 14:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'LEWISVILLE', 2, 'NW', 'LEWISVILLE', 36.124, -80.4471, 36.1217, -80.4426, 'After receiving 3 to 5 inches of heavy rainfall across the northwest Piedmont earlier in the afternoon on the 24th, another round of training showers and thunderstorms|overnight dropped an additional two to three inches of rain fell across western and northern portions of Forsyth County.', 'Heavy rain caused Mills Creek to overflow, flooding Conrad Sawmill Road near the intersection of Grapevine Road.');
INSERT INTO public.stormevents_east VALUES (783526, 201805, 15, 1604, 201805, 15, 1604, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:04:00', 'EST-5', '15-MAY-18 16:04:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'N', 'ORADELL', 1, 'N', 'ORADELL', 40.95, -74.07, 40.95, -74.07, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Tree down blocking road fully on Pascack Road near Oradell Avenue intersection.');
INSERT INTO public.stormevents_east VALUES (783527, 201805, 15, 1606, 201805, 15, 1606, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:06:00', 'EST-5', '15-MAY-18 16:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 70, 'EG', NULL, NULL, 2, 'ESE', 'CLIFTON', 2, 'ESE', 'CLIFTON', 40.86, -74.12, 40.86, -74.12, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Roof blown off a nursery school at the intersection of Jefferson Street and Columbia Avenue.  No injuries.');
INSERT INTO public.stormevents_east VALUES (783528, 201805, 15, 1608, 201805, 15, 1608, 130971, 'NEW JERSEY', 34, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:08:00', 'EST-5', '15-MAY-18 16:08:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 61, 'EG', NULL, NULL, 1, 'W', 'KINGSLAND', 1, 'W', 'KINGSLAND', 40.8, -74.11, 40.8, -74.11, 'An approaching cold front triggered numerous severe thunderstorms over northeastern New Jersey.', 'Several trees reported down along Orient Way.');
INSERT INTO public.stormevents_east VALUES (778147, 201808, 12, 1636, 201808, 12, 1636, 129893, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '12-AUG-18 16:36:00', 'EST-5', '12-AUG-18 16:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'MONROE CREEK (MON)', 0, 'N', 'MONROE CREEK (MON)', 38.23, -76.95, 38.23, -76.95, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms produced strong winds over the waters.', 'A wind gust of up to 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (779838, 201809, 1, 100, 201809, 1, 100, 129856, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'RNK', '01-SEP-18 01:00:00', 'EST-5', '01-SEP-18 01:00:00', 0, 0, 0, 0, '5.00K', NULL, 'Public', 55, 'EG', NULL, NULL, 4, 'N', 'PENHOOK', 4, 'N', 'PENHOOK', 37.04, -79.63, 37.04, -79.63, 'A stationary boundary through the Mid-Atlantic into the Mid-Mississippi Valley spawned thunderstorms in the afternoon and evening of August 31st that carried over into the early morning hours of September 1st . Storms were mainly across the foothills and southside Virginia with radar estimated rainfall of 1 to 2.5 inches in a few hours.  Top rain gage reports ending at 0700 EDT on the 1st included 2.28��� at Woolwine 3.7 NNE CCR (VA-PR-6), 1.98��� at Woolwine COOP (WLWV2), 1.74��� at Smith R. Fieldale IFLOWS (SRVV2), 1.50��� at Martinsville COOP (MARV2), and 1.11��� at Meadows Church IFLOWS (MEAV2). Dissipation of the storms prior to daybreak allowed for enough heating during the day to destabilize the region again for another round of thunderstorms during the afternoon in the same areas near the stationary boundary. The late afternoon storms on the 1st dropped 2-3 inches in a few hours across parts of eastern Campbell, western Charlotte and southern Appomattox counties.', 'Thunderstorm winds brought down several trees two miles north of Penhook Palmers Marina.');
INSERT INTO public.stormevents_east VALUES (780245, 201809, 16, 1111, 201809, 16, 1311, 129284, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'CAE', '16-SEP-18 11:11:00', 'EST-5', '16-SEP-18 13:11:00', 0, 0, 0, 0, '0.10K', '0.10K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'DWIGHT XRDS', 2, 'W', 'DWIGHT XRDS', 34.73, -80.65, 34.7304, -80.654, 'Hurricane Florence began as an area of disturbed weather that moved west off the African coast around August 29-30, 2018.  It gradually developed into a tropical cyclone on August 31, 2018 while just south of the Cape Verde islands.  The cyclone continued to move to the WNW across the Atlantic Ocean in the ensuing two weeks, undergoing fluctuations in intensity.  The cyclone reorganized and strengthened into a category 4 hurricane on Monday, September 10 while centered around 1200 miles SE of the coast of the Carolinas. High pressure located north of the cyclone steered the hurricane to the NW. After undergoing some weakening due to some upper shear, Florence made landfall as a category 1 hurricane on the southern coast of NC near Wilmington Friday morning Sept. 14.  The center of the cyclone then moved slowly west across eastern and central SC while weakening into a tropical storm through Saturday night Sept 15.  Florence weakened into a tropical depression Sunday morning Sept 16 and began to turn to the north and accelerate, moving across the Upstate of SC and western NC through Sunday night.  ||The strongest wind gust in the Midlands of SC was 54 MPH at Shaw AFB near Sumter on the night of Friday September 14th.  Reports of downed trees and power lines were received across the central and eastern Midlands due to strong wind gusts. ||The greatest impact to the region from Florence was flooding due to very heavy rainfall. Rain began late day Friday Sept 14th and continued through early Monday morning Sept 17th. The heaviest rain occurred on the north and east side of Florence, across much of NC, as well as over eastern and northeastern SC. The greatest total rainfall amount in the Midlands of SC was 22.58 inches at the water plant in Cheraw, SC. Major flooding was reported in Chesterfield County SC, where numerous roads and bridges were flooded and washed out. Significant flooding was also reported in Lancaster County, SC. ||The Great Pee Dee River at Cheraw experienced major flooding, peaking at 46.6 feet (flood stage 30.0 ft) on Tuesday morning Sept. 18th.  This was the 3rd highest crest on record at that location, and the highest crest there since 1945.', 'Langley Rd at Gills Creek flooded and impassable. Times approximate.');
INSERT INTO public.stormevents_east VALUES (781386, 201809, 3, 1503, 201809, 3, 1505, 130521, 'VERMONT', 50, 2018, 'September', 'Thunderstorm Wind', 'BTV', '03-SEP-18 15:03:00', 'EST-5', '03-SEP-18 15:05:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Law Enforcement', 65, 'EG', NULL, NULL, 3, 'NE', 'IRASBURG', 3, 'NE', 'IRASBURG', 44.83, -72.25, 44.83, -72.25, 'A cold front moved across a moderate unstable air mass that produced thunderstorms across VT. Some of these thunderstorms produced localized damaging winds, especially a storm near Irasburg that did some significant damage.', 'Numerous trees down across Interstate 91, Route 5 and within the Irasburg and Coventry area.');
INSERT INTO public.stormevents_east VALUES (787913, 201809, 16, 2300, 201809, 17, 530, 131692, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'GSP', '16-SEP-18 23:00:00', 'EST-5', '17-SEP-18 05:30:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'ROCKY RIVER', 3, 'NE', 'FLOWS STORE', 35.333, -80.617, 35.331, -80.534, 'Tropical Cyclone Florence made landfall on the 15th and moved slowly west while weakening through the 16th. Widespread rainfall of 4 to 10 inches, with locally higher amounts fell across western North Carolina over a 36-48 hour period, with the highest totals reported along the Blue Ridge escarpment, and in southern and eastern sections of the Charlotte Metro area. Localized flash flooding was reported in these areas, with severe flash flooding reported across Union County.', 'Although heavy rain ended across Cabarrus County during the evening flooding continued along the Rocky River and its tributaries through daybreak.');
INSERT INTO public.stormevents_east VALUES (738673, 201804, 4, 12, 201804, 4, 12, 123204, 'KENTUCKY', 21, 2018, 'April', 'Thunderstorm Wind', 'JKL', '04-APR-18 00:12:00', 'EST-5', '04-APR-18 00:12:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SW', 'PRINTER', 1, 'SW', 'PRINTER', 37.5245, -82.7571, 37.5245, -82.7571, 'A strong early spring cold front led to a line of showers and thunderstorms developing across the Midwestern U.S. this afternoon and later pushing through eastern Kentucky during the late evening and overnight hours. Initially, a few embedded supercell thunderstorms produced large hail due to their rotation and stronger updrafts. Damaging wind gusts ended up being the primary threat across eastern Kentucky as these features became organized into line segments later into the night.||Numerous reports of downed trees and power lines were received across southeastern Kentucky where the greatest amount of instability was present. Homes in Leslie, Letcher, and Pike Counties suffered extensive damage from trees falling onto them, including one at Willow Tree Hollow near Marrowbone and Regina southeast of Pikeville that led to an injury to a person inside. More scattered wind damage was also reported up toward and north of Mountain Parkway as individual storm cells embedded within the larger line intensified.', 'Department of Highway officials reported several trees blown down along Kentucky Highway 122 south of Martin.');
INSERT INTO public.stormevents_east VALUES (752271, 201804, 3, 1757, 201804, 3, 1757, 125433, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'PBZ', '03-APR-18 17:57:00', 'EST-5', '03-APR-18 17:57:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'SE', 'BUFFALO', 1, 'SE', 'BUFFALO', 39.91, -81.51, 39.91, -81.51, 'Moderate rain along a warm front lifting across the upper Ohio Valley resulted in flooding across portions of eastern Ohio and southwestern Pennsylvania on the 3rd, which was further exacerbated by the passing cold front later that evening. The strong cold front then produced scattered wind damage due to both strong pressure rises behind the front and with accompanying thunderstorms.', 'Department of highways reported trees down near Buffalo.');
INSERT INTO public.stormevents_east VALUES (752295, 201804, 3, 1137, 201804, 3, 1337, 125432, 'PENNSYLVANIA', 42, 2018, 'April', 'Flood', 'PBZ', '03-APR-18 11:37:00', 'EST-5', '03-APR-18 13:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'HADDENVILLE', 1, 'ENE', 'DEARTH', 39.94, -79.79, 39.9343, -79.8113, 'Moderate rain along a warm front lifting across the upper Ohio Valley resulted in flooding across portions of eastern Ohio and southwestern Pennsylvania on the 3rd, which was further exacerbated by the passing cold front later that evening. The strong cold front then produced scattered wind damage due to both strong pressure rises behind the front and with accompanying thunderstorms.', 'Emergency manager reported flooding along Route 40 in Menallen Township. The creek is out of its banks.');
INSERT INTO public.stormevents_east VALUES (779314, 201808, 22, 408, 201808, 22, 608, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '22-AUG-18 04:08:00', 'EST-5', '22-AUG-18 06:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'WSW', 'REMINGTON', 0, 'WSW', 'REMINGTON', 38.5283, -77.8064, 38.5287, -77.8047, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Sumerduck Road was closed due to flooding near Lucky Hill Road.');
INSERT INTO public.stormevents_east VALUES (783183, 201808, 21, 2220, 201808, 22, 211, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 22:20:00', 'EST-5', '22-AUG-18 02:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'WATERFORD', 1, 'NW', 'WATERFORD', 39.193, -77.6177, 39.1935, -77.6126, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The stream gauge at Waterford indicated that water crested at 9.64 feet, above flood stage of 8 feet. Portions of Route 662 flooded near the creek.');
INSERT INTO public.stormevents_east VALUES (781723, 201808, 21, 1900, 201808, 21, 2200, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 19:00:00', 'EST-5', '21-AUG-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSE', 'BERKELEY SPGS', 0, 'SSE', 'BERKELEY SPGS', 39.626, -78.2286, 39.6267, -78.2287, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Flooding continued on Warm Springs Run near Berkeley Springs. Floodwaters were no longer rising rapidly, but earlier flooding persisted for several hours in Berkeley Springs State Park.');
INSERT INTO public.stormevents_east VALUES (783180, 201808, 21, 1932, 201808, 21, 2132, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flash Flood', 'LWX', '21-AUG-18 19:32:00', 'EST-5', '21-AUG-18 21:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MARTINSBURG', 1, 'N', 'MARTINSBURG', 39.4696, -77.9706, 39.4685, -77.9711, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The stream gauge at Tuscarora Creek in Martinsburg rapidly rose above flood stage, cresting at 7.47 feet. Water approached the yard and driveway of a private road off Rock Cliff Drive. Water also covered much of the field behind Rock Cliff Plaza.');
INSERT INTO public.stormevents_east VALUES (781702, 201808, 4, 128, 201808, 4, 1327, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 01:28:00', 'EST-5', '04-AUG-18 13:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KEYMAR', 1, 'NNW', 'KEYMAR', 39.6163, -77.2426, 39.6155, -77.2382, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'The USGS stream gage on Big Pipe Creek near Bruceville exceeded the 8 foot flood stage during the indicated period. The peak level of 9.56 feet occurred at 10:45am EST. Keysville-Bruceville Road was flooded during this time.');
INSERT INTO public.stormevents_east VALUES (752513, 201805, 15, 1329, 201805, 15, 1334, 125464, 'NEW YORK', 36, 2018, 'May', 'Tornado', 'ALY', '15-MAY-18 13:29:00', 'EST-5', '15-MAY-18 13:34:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'E', 'CENTERVILLE', 1, 'E', 'SAUGERTIES SOUTH', 42.0814, -74.0019, 42.0713, -73.9274, 'Severe thunderstorms impacted portions of the eastern Catskills, Mid-Hudson Valley, and Taconics during the afternoon of May 15th. Several supercell thunderstorms developed, with the lead storm resulting in a EF1 tornado near Saugerties and a swath of hail of two inches diameter and greater. Later in the afternoon, an intense thunderstorm with winds up to 105 mph resulted in a widespread area of wind damage along the I-84 corridor in southern Dutchess County. ||Over 35,000 customers in Dutchess and Ulster Counties lost power as a result of the storms. Travel restrictions were issued for southern Dutchess County due to downed trees and malfunctioning traffic lights, and Amtrak and Metro North rail service was suspended in the county. The governor deployed 125 members of the National Guard to aid storm recovery efforts.', 'The tornado path started along Route 212 between Woodstock and Saugerties and moved east through the western and southern part of Saugerties before crossing the Hudson River and ending in Tivoli, just south of the Clermont State Historic Site.||The majority of the tornado damage was rated EF-0, but isolated EF-1 damage was noted. Most of the damage was indirect, from trees falling on homes, other structures, and power lines. Downed trees blocked the southbound exit ramp from the New York State Thruway at the Saugerties exit.');
INSERT INTO public.stormevents_east VALUES (787618, 201808, 2, 1457, 201808, 2, 1458, 129819, 'GEORGIA', 13, 2018, 'August', 'Tornado', 'FFC', '02-AUG-18 14:57:00', 'EST-5', '02-AUG-18 14:58:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'ENE', 'CRUTCHFIELD', 2, 'NE', 'CRUTCHFIELD', 33.1037, -83.6601, 33.1162, -83.6483, 'A series of short waves moving across the region in ahead of a deep upper-level trough over the Mississippi Valley brought several rounds of strong to severe thunderstorms to north and central Georgia. Several reports of damaging thunderstorm winds, flash flooding and even two isolated tornadoes were reported.', 'Information from the Jones County Emergency Manager and local media show that a brief, EF0, tornado with maximum wind speeds of 80 MPH and a maximum path width of 100 yards occurred in the northwest portion of the county on the Piedmont National Wildlife Refuge. The tornado began about a quarter mile south of Round Oak-Juliette Road, traveled northeast parallel to and just south of the road before crossing the road just west of the intersection with Will Russell Road, downing several trees along the path. The tornado continued northeast downing a few more trees and causing minor damage to the metal roof of a home before lifting. [08/02/18: Tornado #2, County #1/1, EF-0, Jones, 2018:011].');
INSERT INTO public.stormevents_east VALUES (778143, 201808, 11, 1931, 201808, 11, 2001, 129892, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '11-AUG-18 19:31:00', 'EST-5', '11-AUG-18 20:01:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 42, 'MG', NULL, NULL, 9, 'NNE', 'GOOSES REEF BUOY (44062)', 9, 'NNE', 'GOOSES REEF BUOY (44062)', 38.671, -76.338, 38.671, -76.338, 'A weak boundary was positioned overhead while an upper-level trough moved into the area. Showers and thunderstorms developed and some produced strong winds over the waters.', 'A wind gust of 42 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778146, 201808, 12, 1610, 201808, 12, 1625, 129893, 'ATLANTIC NORTH', 88, 2018, 'August', 'Marine Thunderstorm Wind', 'LWX', '12-AUG-18 16:10:00', 'EST-5', '12-AUG-18 16:25:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'Widespread showers and thunderstorms formed due to a combination of high instability and a stalled frontal boundary. Some storms produced strong winds over the waters.', 'A wind gust of 34 knots was measured.');
INSERT INTO public.stormevents_east VALUES (778163, 201808, 21, 1415, 201808, 21, 1416, 129896, 'ATLANTIC NORTH', 88, 2018, 'August', 'Waterspout', 'LWX', '21-AUG-18 14:15:00', 'EST-5', '21-AUG-18 14:16:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 7, 'ESE', 'POINT LOOKOUT (PTL)', 7, 'ESE', 'POINT LOOKOUT (PTL)', 38.012, -76.191, 38.012, -76.191, 'A warm front lifted northward through the day across the area, while a cold front approached from the west. These boundaries interacted with a moist and unstable air mass and moderate wind shear to generate thunderstorms which produced strong winds over the waters.', 'A waterspout was observed over the Chesapeake Bay. Video was sent from the general public.');
INSERT INTO public.stormevents_east VALUES (774998, 201808, 1, 2135, 201808, 1, 2135, 129345, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '01-AUG-18 21:35:00', 'EST-5', '01-AUG-18 21:35:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 1, 'SE', 'VALE', 1, 'SE', 'VALE', 39.52, -76.39, 39.52, -76.39, 'A cold front crossing the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'Tree fell on a house causing a roof collapse.');
INSERT INTO public.stormevents_east VALUES (774999, 201808, 1, 2135, 201808, 1, 2135, 129345, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '01-AUG-18 21:35:00', 'EST-5', '01-AUG-18 21:35:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'VALE', 1, 'E', 'VALE', 39.53, -76.38, 39.53, -76.38, 'A cold front crossing the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'Several trees blown down on Winters Run Golf Course. Wind ripped off part of golf clubhouse roof.');
INSERT INTO public.stormevents_east VALUES (777916, 201808, 8, 1910, 201808, 8, 1915, 129822, 'GEORGIA', 13, 2018, 'August', 'Hail', 'FFC', '08-AUG-18 19:10:00', 'EST-5', '08-AUG-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'Public', 1, NULL, NULL, NULL, 2, 'NNE', 'PAYNE CITY', 2, 'NNE', 'PAYNE CITY', 32.8987, -83.689, 32.8987, -83.689, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The public reported quarter size hail in the 100 block of Tom Hill Sr. Blvd. A large branch was blown from a tree in the parking lot of a grocery store at this location as well.');
INSERT INTO public.stormevents_east VALUES (775638, 201808, 12, 1641, 201808, 12, 1841, 129470, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '12-AUG-18 16:41:00', 'EST-5', '12-AUG-18 18:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 62, 'SE', 'DBL TOLLGATE', 62, 'SE', 'DBL TOLLGATE', 38.3161, -77.4788, 38.3157, -77.4784, 'A weak boundary remained overhead while an upper-level trough moved into the area. Warm and humid conditions led to an unstable atmosphere during this time. The unstable atmosphere combined with lift associated with the trough and the boundary to produce showers and thunderstorms. Locally heavy rain led to some flooding.', 'Riverside Drive was closed due to flooding near Fall Hill Avenue.');
INSERT INTO public.stormevents_east VALUES (775227, 201808, 1, 328, 201808, 1, 528, 129380, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 03:28:00', 'EST-5', '01-AUG-18 05:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'WOODHAVEN', 0, 'SSW', 'WOODHAVEN', 38.9983, -77.1317, 38.9984, -77.131, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. An isolated incident of flooding occurred due to locally  heavy rainfall.', 'A car was trapped on Bradley Boulevard due to high water.');
INSERT INTO public.stormevents_east VALUES (775279, 201808, 30, 1525, 201808, 30, 1525, 129389, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '30-AUG-18 15:25:00', 'EST-5', '30-AUG-18 15:25:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'BLEMHEIM', 1, 'E', 'BLEMHEIM', 37.9, -78.49, 37.9, -78.49, 'An approaching cold front interacted with a warm and moist unstable air mass across the region to produce showers and thunderstorms, a few of which became severe.', 'A tree was blown down near the intersection of Blenheim Road and Secretarys Road.');
INSERT INTO public.stormevents_east VALUES (775555, 201808, 3, 2156, 201808, 3, 2356, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 21:56:00', 'EST-5', '03-AUG-18 23:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BANCO', 1, 'N', 'BANCO', 38.46, -78.3, 38.4582, -78.3005, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-642 Lindsay Lane/Poor House Road was closed due to flooding near VA-670.');
INSERT INTO public.stormevents_east VALUES (774882, 201808, 1, 104, 201808, 1, 304, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 01:04:00', 'EST-5', '01-AUG-18 03:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'REMINGTON', 0, 'NNW', 'REMINGTON', 38.5352, -77.8041, 38.5353, -77.8034, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-656 North Franklin Street was closed due to flooding near East Main Street.');
INSERT INTO public.stormevents_east VALUES (774884, 201808, 1, 115, 201808, 1, 315, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 01:15:00', 'EST-5', '01-AUG-18 03:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'EVERONA', 1, 'SSW', 'EVERONA', 38.2945, -77.9856, 38.2933, -77.9749, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-666 Hawfield Road was closed due to flooding over Mountain Run/Walkers Branch between VA-627 Clarks Mountain Road and VA-617 Everona Road.');
INSERT INTO public.stormevents_east VALUES (774889, 201808, 1, 120, 201808, 1, 320, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 01:20:00', 'EST-5', '01-AUG-18 03:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'WEST GATE OF LOMOND', 1, 'E', 'WEST GATE OF LOMOND', 38.77, -77.49, 38.7697, -77.4892, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'A car was stuck in high standing water in the 8300 Block of Sudley Road.');
INSERT INTO public.stormevents_east VALUES (774891, 201808, 1, 128, 201808, 1, 328, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 01:28:00', 'EST-5', '01-AUG-18 03:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'AUBURN', 3, 'NNE', 'AUBURN', 38.74, -77.68, 38.74, -77.6788, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-602 Rogues Road was closed due to flooding near Kennedy Road.');
INSERT INTO public.stormevents_east VALUES (798727, 201812, 20, 1902, 201812, 20, 1902, 133499, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'KEY', '20-DEC-18 19:02:00', 'EST-5', '20-DEC-18 19:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR REEF LIGHT', 0, 'N', 'ALLIGATOR REEF LIGHT', 24.85, -80.62, 24.85, -80.62, 'An extratropical cyclone with gale-force winds moving quickly northeast over the northeast Gulf of Mexico and attendant cold front produce numerous showers and scattered thunderstorms near the Florida Keys and Straits of Florida. Isolated gale-force wind gusts occurred near a few thunderstorms.', 'A wind gust of 41 knots was measured at an automated WeatherFlow station at Alligator Reef Light.');
INSERT INTO public.stormevents_east VALUES (798728, 201812, 20, 2302, 201812, 20, 2302, 133499, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'KEY', '20-DEC-18 23:02:00', 'EST-5', '20-DEC-18 23:02:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 2, 'SE', 'BIG COPPITT KEY', 2, 'SE', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'An extratropical cyclone with gale-force winds moving quickly northeast over the northeast Gulf of Mexico and attendant cold front produce numerous showers and scattered thunderstorms near the Florida Keys and Straits of Florida. Isolated gale-force wind gusts occurred near a few thunderstorms.', 'A wind gust of 38 knots was measured at the Naval Air Station Key West Boca Chica Field ASOS during the passage of a rain squall.');
INSERT INTO public.stormevents_east VALUES (775191, 201808, 1, 453, 201808, 1, 653, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 04:53:00', 'EST-5', '01-AUG-18 06:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'LEGATO', 1, 'SSW', 'LEGATO', 38.8417, -77.3725, 38.8419, -77.3721, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'High water in the vicinity of Singing Pines Road caused the road to be closed.');
INSERT INTO public.stormevents_east VALUES (775193, 201808, 1, 514, 201808, 1, 714, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 05:14:00', 'EST-5', '01-AUG-18 07:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BRISTOW', 1, 'S', 'BRISTOW', 38.7033, -77.5333, 38.703, -77.5334, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'A pickup truck was trapped in high water up to its doors on ValleyView Drive.');
INSERT INTO public.stormevents_east VALUES (808498, 201812, 20, 2341, 201812, 21, 141, 133712, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'LWX', '20-DEC-18 23:41:00', 'EST-5', '21-DEC-18 01:41:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'GREENFIELD', 1, 'SSE', 'GREENFIELD', 37.921, -78.8497, 37.9212, -78.8471, 'A potent longwave trough approached the area from the west on the 20th. Warm advection and strong moisture transport ahead of the mid-upper level wave led to a prolonged period of rainfall through the day as surface low pressure tracked from the FL Panhandle to WV by evening. Rainfall totals on the order of 1-2 inches led to instances of flooding across portions of Augusta, Nelson and Albemarle Counties in VA.', 'VA-635 Rockfish School Lane closed due to flooding near VA-151 Rockfish Valley Highway.');
INSERT INTO public.stormevents_east VALUES (761198, 201805, 22, 1830, 201805, 22, 1830, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 18:30:00', 'EST-5', '22-MAY-18 18:30:00', 0, 0, 0, 0, '0.25K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'CANONSBURG', 1, 'W', 'CANONSBURG', 40.25, -80.22, 40.25, -80.22, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported a tree down at Paxton Farm Road and Western Avenue.');
INSERT INTO public.stormevents_east VALUES (761199, 201805, 22, 1913, 201805, 22, 1913, 127005, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 19:13:00', 'EST-5', '22-MAY-18 19:13:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'ESE', 'NORTH BELLE VERNON', 1, 'ESE', 'NORTH BELLE VERNON', 40.1441, -79.8158, 40.1441, -79.8158, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg.  Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State official reported trees down along Indian Hill Road and Finley Road.');
INSERT INTO public.stormevents_east VALUES (759650, 201805, 22, 1713, 201805, 22, 1713, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:13:00', 'EST-5', '22-MAY-18 17:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 55, 'EG', NULL, NULL, 0, 'N', 'UHRICHSVILLE', 0, 'N', 'UHRICHSVILLE', 40.4, -81.33, 40.4, -81.33, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'County Emergency manager reports trees down along Stillwater Circle, scattered trees down around Mill Township--just south of Dennison/Uhrichsville.');
INSERT INTO public.stormevents_east VALUES (759652, 201805, 22, 1700, 201805, 22, 1700, 126724, 'OHIO', 39, 2018, 'May', 'Hail', 'PBZ', '22-MAY-18 17:00:00', 'EST-5', '22-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'SE', 'NEW PHILADELPHIA', 1, 'SE', 'NEW PHILADELPHIA', 40.49, -81.44, 40.49, -81.44, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'One inch hail reported by two trained spotters in the New Philadelphia/Dover area.');
INSERT INTO public.stormevents_east VALUES (759653, 201805, 22, 1710, 201805, 22, 1710, 126724, 'OHIO', 39, 2018, 'May', 'Hail', 'PBZ', '22-MAY-18 17:10:00', 'EST-5', '22-MAY-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 1, 'SW', 'BARNHILL', 1, 'SW', 'BARNHILL', 40.44, -81.36, 40.44, -81.36, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'One inch hail was reported by someone from the general public around Grizzley Drive.');
INSERT INTO public.stormevents_east VALUES (752588, 201805, 30, 1250, 201805, 30, 1250, 125036, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '30-MAY-18 12:50:00', 'EST-5', '30-MAY-18 12:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 6, 'N', 'PLAYALINDA BEACH', 6, 'N', 'PLAYALINDA BEACH', 28.6309, -80.7688, 28.6309, -80.7688, 'East central Florida remained sandwiched between a mid-level trough over the Gulf of Mexico and high pressure ridge extending from just east of the Bahamas extending well into the Great Lakes region. This set up brought a deep layer, moist, south-southwest flow into the region. Showers and thunderstorms developed across the area in the afternoon and pushed towards the east coast eventually becoming a consistent line. As these storms moved across the intracoastal and nearshore waters of Brevard County, they produced strong winds.', 'Weatherflow site XPAR at Parrish Park near Titusville measured a peak wind gust of 36 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (752589, 201805, 30, 1230, 201805, 30, 1230, 125036, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '30-MAY-18 12:30:00', 'EST-5', '30-MAY-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 46, 'MG', NULL, NULL, 4, 'WNW', 'CAPE CANAVERAL', 4, 'WNW', 'CAPE CANAVERAL', 28.4, -80.6665, 28.4, -80.6665, 'East central Florida remained sandwiched between a mid-level trough over the Gulf of Mexico and high pressure ridge extending from just east of the Bahamas extending well into the Great Lakes region. This set up brought a deep layer, moist, south-southwest flow into the region. Showers and thunderstorms developed across the area in the afternoon and pushed towards the east coast eventually becoming a consistent line. As these storms moved across the intracoastal and nearshore waters of Brevard County, they produced strong winds.', 'US Air Force wind tower 0300 measured a peak wind gust of 46 knots from the south-southwest.');
INSERT INTO public.stormevents_east VALUES (753887, 201805, 14, 1330, 201805, 14, 1330, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 13:30:00', 'EST-5', '14-MAY-18 13:30:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 0, 'W', 'VERONA', 0, 'W', 'VERONA', 38.1998, -79.0062, 38.1998, -79.0062, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A camper was blown over. Several sheds were rolled.');
INSERT INTO public.stormevents_east VALUES (754528, 201805, 14, 1755, 201805, 14, 1755, 125705, 'VIRGINIA', 51, 2018, 'May', 'Thunderstorm Wind', 'LWX', '14-MAY-18 17:55:00', 'EST-5', '14-MAY-18 17:55:00', 0, 0, 0, 0, NULL, NULL, 'Public', 50, 'EG', NULL, NULL, 1, 'SSE', 'FIVE MILE', 1, 'SSE', 'FIVE MILE', 38.2701, -77.5434, 38.2701, -77.5434, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to become severe.', 'A downed tree was near the intersection of Harrison Road and Battlefield Green Drive.');
INSERT INTO public.stormevents_east VALUES (766626, 201806, 9, 1840, 201806, 9, 1840, 127844, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '09-JUN-18 18:40:00', 'EST-5', '09-JUN-18 18:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 42, 'MG', NULL, NULL, 1, 'N', 'MAYPORT NAS', 1, 'N', 'MAYPORT NAS', 30.41, -81.42, 30.41, -81.42, 'A surface low was offshore of the SE GA Atlantic coast with an upper level low along the FL Gulf Coast. The upper level low lifted northward through the day, and combined with low level forcing, instability and high moisture produced strong to severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (762583, 201806, 2, 1403, 201806, 2, 1403, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 14:03:00', 'EST-5', '02-JUN-18 14:03:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'S', 'SNIPESVILLE', 1, 'S', 'SNIPESVILLE', 31.76, -82.75, 31.76, -82.75, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees were blown down on the northside of Snipesville.');
INSERT INTO public.stormevents_east VALUES (762584, 201806, 2, 1411, 201806, 2, 1411, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 14:11:00', 'EST-5', '02-JUN-18 14:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SE', 'SNIPESVILLE', 2, 'SE', 'SNIPESVILLE', 31.75, -82.72, 31.75, -82.72, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees and power lines were blown down for up to 7 miles along Ed Ray Road near Denton.');
INSERT INTO public.stormevents_east VALUES (762585, 201806, 2, 1430, 201806, 2, 1430, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 14:30:00', 'EST-5', '02-JUN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'WITHERS', 0, 'N', 'WITHERS', 30.85, -82.9, 30.85, -82.9, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A tree was blown down on a home along Withers Road.');
INSERT INTO public.stormevents_east VALUES (776189, 201807, 21, 2120, 201807, 21, 2120, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Hail', 'RAH', '21-JUL-18 21:20:00', 'EST-5', '21-JUL-18 21:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 1, NULL, NULL, NULL, 1, 'NNE', 'SPOUT SPGS', 1, 'NNE', 'SPOUT SPGS', 35.2877, -79.0592, 35.2877, -79.0592, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'Dime to quarter size hail was reported along Buffalo Lake Road, near Carolina Lakes Road.');
INSERT INTO public.stormevents_east VALUES (776191, 201807, 21, 2206, 201807, 21, 2206, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '21-JUL-18 22:06:00', 'EST-5', '21-JUL-18 22:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'N', 'ANGIER', 3, 'N', 'ANGIER', 35.5361, -78.75, 35.5361, -78.75, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'Trees were reported down along Kennebec Church Road.');
INSERT INTO public.stormevents_east VALUES (783428, 201805, 15, 1620, 201805, 15, 1620, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:20:00', 'EST-5', '15-MAY-18 16:20:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 1, 'SSW', 'WEST SHR', 1, 'SSW', 'WEST SHR', 41.2403, -72.9879, 41.2403, -72.9879, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees fallen into two homes on Danenberg Place in West Haven.');
INSERT INTO public.stormevents_east VALUES (783429, 201805, 15, 1620, 201805, 15, 1620, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:20:00', 'EST-5', '15-MAY-18 16:20:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'NW', 'COMPO BEACH', 1, 'NW', 'COMPO BEACH', 41.13, -73.36, 41.13, -73.36, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down on wires at Compo Road South.');
INSERT INTO public.stormevents_east VALUES (783430, 201805, 15, 1620, 201805, 15, 1620, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:20:00', 'EST-5', '15-MAY-18 16:20:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'ESE', 'WESTPORT', 1, 'ESE', 'WESTPORT', 41.14, -73.35, 41.14, -73.35, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree down on cars at the Trader Joe''s on Route 1.');
INSERT INTO public.stormevents_east VALUES (783431, 201805, 15, 1620, 201805, 15, 1620, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:20:00', 'EST-5', '15-MAY-18 16:20:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Social Media', 52, 'EG', NULL, NULL, 1, 'E', 'WESTPORT', 1, 'E', 'WESTPORT', 41.1493, -73.3422, 41.1493, -73.3422, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Wires down at Roseville Road.');
INSERT INTO public.stormevents_east VALUES (783432, 201805, 15, 1625, 201805, 15, 1625, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:25:00', 'EST-5', '15-MAY-18 16:25:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 0, 'N', 'DURHAM', 0, 'N', 'DURHAM', 41.47, -72.68, 41.47, -72.68, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous trees down.');
INSERT INTO public.stormevents_east VALUES (766275, 201806, 3, 1748, 201806, 3, 1748, 127794, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '03-JUN-18 17:48:00', 'EST-5', '03-JUN-18 17:48:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'GAINESVILLE', 1, 'E', 'GAINESVILLE', 29.65, -82.31, 29.65, -82.31, 'Very hot and unstable conditions preceded an approaching short wave trough across NE FL. This trough combined with diurnal heating and west coast sea breeze forcing spawned scattered severe storms that impacted NE FL during late late afternoon into the early evening.', 'A tree was blown down onto power lines and onto the roof of a home near SE 7th Ave and SE 10th Street.');
INSERT INTO public.stormevents_east VALUES (766276, 201806, 4, 1431, 201806, 4, 1431, 127795, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '04-JUN-18 14:31:00', 'EST-5', '04-JUN-18 14:31:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 5, 'NW', 'DAYVILLE', 5, 'NW', 'DAYVILLE', 29.67, -82.44, 29.67, -82.44, 'A surface front and mid level trough triggered severe storms over a moist and unstable airmass. Dry mid level air and cool temperatures aloft promoted wet downbursts in strong to severe storms.', 'Trees were blown down near NW 23rd Ave and NW 98th Street.');
INSERT INTO public.stormevents_east VALUES (766277, 201806, 4, 1448, 201806, 4, 1448, 127795, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '04-JUN-18 14:48:00', 'EST-5', '04-JUN-18 14:48:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NNE', 'HAGUE', 2, 'NNE', 'HAGUE', 29.8, -82.41, 29.8, -82.41, 'A surface front and mid level trough triggered severe storms over a moist and unstable airmass. Dry mid level air and cool temperatures aloft promoted wet downbursts in strong to severe storms.', 'Power lines were blown down on NW 156th Ave.');
INSERT INTO public.stormevents_east VALUES (766278, 201806, 4, 1451, 201806, 4, 1451, 127795, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '04-JUN-18 14:51:00', 'EST-5', '04-JUN-18 14:51:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'ENE', 'HAINESWORTH', 1, 'ENE', 'HAINESWORTH', 29.83, -82.43, 29.83, -82.43, 'A surface front and mid level trough triggered severe storms over a moist and unstable airmass. Dry mid level air and cool temperatures aloft promoted wet downbursts in strong to severe storms.', 'A tree was blown down and blocked the road near the intersection of County Road 237 and W State Road 235.');
INSERT INTO public.stormevents_east VALUES (766279, 201806, 4, 1515, 201806, 4, 1515, 127795, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '04-JUN-18 15:15:00', 'EST-5', '04-JUN-18 15:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WNW', 'EDGAR', 2, 'WNW', 'EDGAR', 29.61, -81.98, 29.61, -81.98, 'A surface front and mid level trough triggered severe storms over a moist and unstable airmass. Dry mid level air and cool temperatures aloft promoted wet downbursts in strong to severe storms.', 'Power lines were blown down on South County Road 21 West of Interlachen.');
INSERT INTO public.stormevents_east VALUES (753993, 201805, 3, 1906, 201805, 3, 1906, 125627, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '03-MAY-18 19:06:00', 'EST-5', '03-MAY-18 19:06:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 38, 'MG', NULL, NULL, 0, 'NNE', 'GREAT GULL ISLAND WXFLOW', 0, 'NNE', 'GREAT GULL ISLAND WXFLOW', 41.2025, -72.1183, 41.2025, -72.1183, 'Strong to severe thunderstorms moved across Long Island Sound ahead of a cold front.', 'A 38 knot gust was reported at Great Gull Island mesonet location.');
INSERT INTO public.stormevents_east VALUES (756634, 201805, 15, 1510, 201805, 15, 1510, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:10:00', 'EST-5', '15-MAY-18 15:10:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 1, 'E', 'WASHINGTONVILLE', 1, 'E', 'WASHINGTONVILLE', 41.43, -74.16, 41.43, -74.16, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees were snapped or uprooted.');
INSERT INTO public.stormevents_east VALUES (756641, 201805, 15, 1516, 201805, 15, 1516, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:16:00', 'EST-5', '15-MAY-18 15:16:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Social Media', 61, 'EG', NULL, NULL, 1, 'E', 'WASHINGTONVILLE', 1, 'E', 'WASHINGTONVILLE', 41.43, -74.16, 41.43, -74.16, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees were reported down around town.');
INSERT INTO public.stormevents_east VALUES (756645, 201805, 15, 1516, 201805, 15, 1516, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:16:00', 'EST-5', '15-MAY-18 15:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 50, 'MG', NULL, NULL, 1, 'SW', 'WEST NEWBURGH', 1, 'SW', 'WEST NEWBURGH', 41.47, -74.04, 41.47, -74.04, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 58 mile per hour gust measured by New Windsor mesonet.');
INSERT INTO public.stormevents_east VALUES (758519, 201805, 17, 1900, 201805, 17, 2200, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 19:00:00', 'EST-5', '17-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'CAPON BRIDGE', 1, 'S', 'CAPON BRIDGE', 39.2785, -78.4479, 39.2802, -78.4466, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'Capon River Road flooded and closed in the 2000 block, near Capon Bridge, due to flooding of the Cacapon River.');
INSERT INTO public.stormevents_east VALUES (758521, 201805, 17, 1909, 201805, 17, 2200, 126425, 'WEST VIRGINIA', 54, 2018, 'May', 'Flood', 'LWX', '17-MAY-18 19:09:00', 'EST-5', '17-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'COLD STREAM', 1, 'ENE', 'COLD STREAM', 39.3377, -78.4294, 39.337, -78.4283, 'Moderate rain over a two day period totaled 1-3 inches, and was enough to produce some flooding during the afternoon of May 16th. Additional heavy rain affected the far eastern West Virginia panhandle during the evening hours of the 16th, producing 3-5 inches of rain and causing additional flooding. Moderate rain continued through the 18th, causing stream flooding beginning the 17th and continuing through the early morning hours of the 21st.', 'Cold Stream Road was closed in the 3000 block due to flooding of the Cacapon River.');
INSERT INTO public.stormevents_east VALUES (761267, 201805, 31, 1826, 201805, 31, 1930, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 18:26:00', 'EST-5', '31-MAY-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'BETHEL', 1, 'WSW', 'BETHEL', 38.6461, -77.3377, 38.6454, -77.3375, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'A foot of water reported at the intersection of Dale Boulevard and Minnieville Road.');
INSERT INTO public.stormevents_east VALUES (761269, 201805, 31, 1837, 201805, 31, 1930, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 18:37:00', 'EST-5', '31-MAY-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'FAIRFAX', 0, 'WNW', 'FAIRFAX', 38.8509, -77.3076, 38.8513, -77.3047, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Accotink Creek was out of its banks, flooding portions of Bells Bird Sanctuary Park in Fairfax.');
INSERT INTO public.stormevents_east VALUES (761270, 201805, 31, 1915, 201805, 31, 2015, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 19:15:00', 'EST-5', '31-MAY-18 20:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'CANOVA', 1, 'N', 'CANOVA', 38.6919, -77.4313, 38.6914, -77.4312, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Purcell Road flooded near Purcell Creek.');
INSERT INTO public.stormevents_east VALUES (754606, 201805, 10, 1642, 201805, 10, 1642, 125844, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '10-MAY-18 16:42:00', 'EST-5', '10-MAY-18 16:42:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'LEWISETTA (LWS)', 0, 'N', 'LEWISETTA (LWS)', 38, -76.47, 38, -76.47, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to some storms with gusty winds.', 'A wind gust in excess of 30 knots was reported at Lewisetta.');
INSERT INTO public.stormevents_east VALUES (761285, 201805, 31, 1950, 201805, 31, 2200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '31-MAY-18 19:50:00', 'EST-5', '31-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'STANDARDSVILLE', 2, 'NNW', 'STANDARDSVILLE', 38.3326, -78.4473, 38.3326, -78.447, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Bridge flooded and closed on Octonia Road where South River crosses it.');
INSERT INTO public.stormevents_east VALUES (761284, 201805, 30, 2025, 201805, 30, 2200, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 20:25:00', 'EST-5', '30-MAY-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSE', 'FREE UNION', 3, 'SSE', 'FREE UNION', 38.1307, -78.5505, 38.1311, -78.5505, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Slope failure on Free Union Road near Ridge Road due to heavy rain.');
INSERT INTO public.stormevents_east VALUES (761286, 201805, 31, 715, 201805, 31, 1854, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 07:15:00', 'EST-5', '31-MAY-18 18:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'RAPIDAN', 1, 'NW', 'RAPIDAN', 38.3429, -78.1041, 38.3288, -78.0862, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The stream gage on Robinson River near Locust Dale exceeded the 11 foot flood stage during the indicated times. The peak of 14.89 feet occurred at 1:30pm EST on May 31st.');
INSERT INTO public.stormevents_east VALUES (759306, 201805, 22, 11, 201805, 22, 322, 126454, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '22-MAY-18 00:11:00', 'EST-5', '22-MAY-18 03:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'COOTES STORE', 0, 'WSW', 'BROADWAY', 38.6419, -78.8675, 38.618, -78.805, 'Heavy rains on May 21st in western Rockingham County caused significant flooding. Those floodwaters moved downstream on the 22nd, causing stream flooding. Meanwhile, afternoon showers and thunderstorms produced around an inch of rain, producing some urban flooding in the DC metropolitan area.', 'The stream gage on the North Fork Shenandoah River at Cootes Store exceeded the 15 foot flood stage during the times indicated. The peak level of 17.00 feet was observed at 1:15am EST on May 22nd, and was the highest level observed since 1996. This was also the first flood of any kind at this location since 2011. At these levels, agricultural flooding is occurring, along with flooding of a campground. Low spots on Brocks Gap road also begin to flood.');
INSERT INTO public.stormevents_east VALUES (759984, 201805, 31, 1836, 201805, 31, 2030, 126463, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 18:36:00', 'EST-5', '31-MAY-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'SAVAGE', 2, 'NNE', 'SAVAGE', 39.1498, -76.8169, 39.149, -76.8163, 'During the evening as a warm front surged northward, heavy rain developed in the Laurel area, with 1-2 inches of rain falling in a relatively short period of time. This caused one isolated instance of flooding in Howard County.', 'Guilford Road flooded and closed at Vollmerhausen Road.');
INSERT INTO public.stormevents_east VALUES (759987, 201805, 27, 1850, 201805, 27, 2000, 126461, 'WEST VIRGINIA', 54, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 18:50:00', 'EST-5', '27-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'RUSSELLDALE', 2, 'S', 'RUSSELLDALE', 39.2608, -78.9252, 39.2508, -78.927, 'Scattered thunderstorms developed ahead of a cold front over Maryland during the afternoon hours of May 27th. Moderate to heavy rain on saturated soil produced flooding in portions of eastern West Virginia.', 'Multiple roads flooded and closed after very heavy rain in a short period of time near Russeldale and Purgitsville.');
INSERT INTO public.stormevents_east VALUES (759991, 201805, 27, 1530, 201805, 27, 1730, 126460, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 15:30:00', 'EST-5', '27-MAY-18 17:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'PENN LAIRD', 1, 'NNW', 'PENN LAIRD', 38.3878, -78.8055, 38.3876, -78.8046, 'Scattered thunderstorms developed ahead of a cold front over Maryland during the afternoon hours of May 27th. Moderate to heavy rain on saturated soil produced flooding in portions of northern Virginia. The soils were so saturated that just moderate rain caused more flooding near Harrisonburg during the afternoon of the 28th as the cold front pushed through the region.', 'US 33 was flooded in the Penn Laird area near a stream crossing. Pictures showed high water greater than six inches flowing over the road, mainly out of drainage ditches.');
INSERT INTO public.stormevents_east VALUES (760010, 201805, 27, 1526, 201805, 27, 1557, 126459, 'MARYLAND', 24, 2018, 'May', 'Flash Flood', 'LWX', '27-MAY-18 15:26:00', 'EST-5', '27-MAY-18 15:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'S', 'ELLICOTT CITY', 0, 'S', 'ELLICOTT CITY', 39.2685, -76.8, 39.2684, -76.7998, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Video footage shows water covering a deck and entering structures near Court Avenue. Water also flowed across Court Avenue during this time.');
INSERT INTO public.stormevents_east VALUES (760005, 201805, 30, 1930, 201805, 30, 2030, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 19:30:00', 'EST-5', '30-MAY-18 20:30:00', 0, 0, 1, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'SYRIA', 1, 'N', 'SYRIA', 38.4891, -78.3315, 38.4891, -78.3309, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Two women attempted to cross the swollen Rose River at Graves Mountain Lodge in an ATV. When one of the women got out to check on the water, she was knocked off her feet and swept away. The other woman was uninjured and rescued.');
INSERT INTO public.stormevents_east VALUES (760941, 201805, 30, 2002, 201805, 30, 2300, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 20:02:00', 'EST-5', '30-MAY-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'DYKE', 1, 'ESE', 'DYKE', 38.24, -78.51, 38.2415, -78.5099, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'Flash flooding reported at the intersection of Bingham Mountain Road and Middle Mountain Road. The road was closed.');
INSERT INTO public.stormevents_east VALUES (756779, 201805, 15, 1653, 201805, 15, 1653, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:53:00', 'EST-5', '15-MAY-18 16:53:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 1, 'ENE', 'PT LOOKOUT', 1, 'ENE', 'PT LOOKOUT', 40.59, -73.56, 40.59, -73.56, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 50 mile per hour gust was reported at Jones Beach Coast Guard mesonet.');
INSERT INTO public.stormevents_east VALUES (756781, 201805, 15, 1656, 201805, 15, 1656, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:56:00', 'EST-5', '15-MAY-18 16:56:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Mesonet', 48, 'MG', NULL, NULL, 6, 'SW', 'FISHERS IS ARPT', 6, 'SW', 'FISHERS IS ARPT', 41.2, -72.12, 41.2, -72.12, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 55 mile per hour gust was reported at Great Gull Island mesonet.');
INSERT INTO public.stormevents_east VALUES (783543, 201805, 15, 1515, 201805, 15, 1515, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:15:00', 'EST-5', '15-MAY-18 15:15:00', 0, 0, 0, 0, '3.00K', '0.00K', 'Trained Spotter', 52, 'MG', NULL, NULL, 0, 'N', 'NEWBURGH', 0, 'N', 'NEWBURGH', 41.5, -74.02, 41.5, -74.02, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Tree limbs down with 60 mph wind gust.');
INSERT INTO public.stormevents_east VALUES (764279, 201807, 24, 700, 201807, 25, 700, 127490, 'NORTH CAROLINA', 37, 2018, 'July', 'Heavy Rain', 'RNK', '24-JUL-18 07:00:00', 'EST-5', '25-JUL-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'EDEN', 0, 'N', 'EDEN', 36.5, -79.75, 36.5, -79.75, 'An unusually deep upper trough for July over the eastern U.S. extending all the way south to the Gulf Coast provided the setting for widespread shower and thunderstorm activity. Radar estimated rainfall of 2 to 4 inches in about 3 hours was observed across west central Rockingham County with a small area estimated at 4 to 6 inches between Intelligence and Mayodan. The annual recurrence interval of the heaviest rain approached 200-year (.005 annual exceedance probability) in a 3-hour period per NOAA Atlas 14.', 'Eden COOP (EDEN7) had 2.10��� for the wettest July 25th on record with rainfall data back to 1950.');
INSERT INTO public.stormevents_east VALUES (771174, 201806, 9, 1500, 201806, 9, 1500, 128493, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MFL', '09-JUN-18 15:00:00', 'EST-5', '09-JUN-18 15:00:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 1, NULL, NULL, NULL, 1, 'S', 'IMMOKALEE ARPT', 1, 'S', 'IMMOKALEE ARPT', 26.41, -81.4, 26.41, -81.4, 'The Atlantic seabreeze that developed during the late morning hours of June 7th, quickly moved west and collided with the Gulf breeze across Collier, Hendry, and Glades counties during the afternoon hours. Shower and storm development along these boundaries was enhanced by an upper level low across the eastern Gulf of Mexico, allowing several storms to become severe as a result of the collision, leading to reports of hail across interior Collier and Hendry counties.', 'Report relayed via NBC2 Fort Myers social media account of quarter sized hail in Immokalee.');
INSERT INTO public.stormevents_east VALUES (776209, 201807, 22, 529, 201807, 22, 730, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '22-JUL-18 05:29:00', 'EST-5', '22-JUL-18 07:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'NE', 'DUNN', 4, 'NE', 'DUNN', 35.3521, -78.5736, 35.3536, -78.573, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'US 301 N at Bryan McLamb Lane closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (776202, 201807, 22, 520, 201807, 22, 729, 129556, 'NORTH CAROLINA', 37, 2018, 'July', 'Flash Flood', 'RAH', '22-JUL-18 05:20:00', 'EST-5', '22-JUL-18 07:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 4, 'SSE', 'EMIT', 4, 'SSE', 'EMIT', 35.6685, -78.2507, 35.672, -78.247, 'Multiple disturbances rotating around an upper-level low across the Ohio Valley produced multiple clusters of showers and storms across central NC during the late evening and  overnight hours. Convection congealed into an MCS-like complex and pushed east during the overnight hours which produced some isolated wind damage and pockets of heavy rainfall which produced flash flooding.', 'Flash flooding was reported at the intersection of NC Highway 42 and NC Highway 39.');
INSERT INTO public.stormevents_east VALUES (770923, 201806, 29, 1408, 201806, 29, 1408, 128509, 'FLORIDA', 12, 2018, 'June', 'Funnel Cloud', 'MFL', '29-JUN-18 14:08:00', 'EST-5', '29-JUN-18 14:08:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', NULL, NULL, NULL, NULL, 4, 'WNW', 'WESTWOOD LAKES', 4, 'WNW', 'WESTWOOD LAKES', 25.76, -80.44, 25.76, -80.44, 'Showers and storms once again developed along the seabreezes during the late morning and afternoon hours across South Florida. Boundary collisions between the seabreeze and ongoing storms produced a funnel cloud over the western Miami-Dade County metro area during the afternoon hours.', 'Photograph and report relayed via WSVN channel 7 of a funnel cloud near Southwest 8th Street and Southwest 152nd Avenue.');
INSERT INTO public.stormevents_east VALUES (770921, 201806, 30, 1230, 201806, 30, 1230, 128510, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'MFL', '30-JUN-18 12:30:00', 'EST-5', '30-JUN-18 12:30:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 7, 'NNE', 'KREAMER ISLAND', 7, 'NNE', 'KREAMER ISLAND', 26.86, -80.67, 26.86, -80.67, 'Outflow boundary collisions between ongoing afternoon showers and storms interacted with activity across Lake Okeechobee, producing a midday waterspout across the lake.', 'Photo received via Twitter of a waterspout on Lake Okeechobee with a visible spray ring west of Canal Point. Original source appears to be from a member of the general public. waterspout time 130pm. Time and position estimated with the aid of Doppler Radar.');
INSERT INTO public.stormevents_east VALUES (766628, 201806, 11, 2225, 201806, 11, 2225, 127845, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '11-JUN-18 22:25:00', 'EST-5', '11-JUN-18 22:25:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'N', 'KIRKLAND', 1, 'N', 'KIRKLAND', 31.82, -82.77, 31.82, -82.77, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', 'A tree was blown down across Burkett''s Ferry Road between Hazelhurst and Snipesville.');
INSERT INTO public.stormevents_east VALUES (742704, 201804, 3, 1616, 201804, 3, 1621, 123573, 'OHIO', 39, 2018, 'April', 'Thunderstorm Wind', 'ILN', '03-APR-18 16:16:00', 'EST-5', '03-APR-18 16:21:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', 61, 'EG', NULL, NULL, 1, 'ESE', 'LONDON', 1, 'ESE', 'LONDON', 39.8735, -83.4254, 39.8735, -83.4254, 'Severe thunderstorms and tornadoes developed ahead of a strong cold front. Between one to three inches of rain fell across the region.', 'Barn damage was observed on State Route 56 southeast of London.');
INSERT INTO public.stormevents_east VALUES (752905, 201804, 15, 1728, 201804, 15, 1729, 124835, 'SOUTH CAROLINA', 45, 2018, 'April', 'Thunderstorm Wind', 'CHS', '15-APR-18 17:28:00', 'EST-5', '15-APR-18 17:29:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'W', 'KNIGHTSVILLE', 1, 'W', 'KNIGHTSVILLE', 33.02, -80.24, 33.02, -80.24, 'A strong cold front pushed into an area of high instability, helping produce gusty wind conditions early followed by a squall line of strong to severe thunderstorms over Southeast South Carolina.', 'The Dorchester County 911 Call Center reported a tree down on Orangeburg Road near the Pinewood Preparatory School.');
INSERT INTO public.stormevents_east VALUES (777931, 201808, 8, 1815, 201808, 8, 1825, 129822, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '08-AUG-18 18:15:00', 'EST-5', '08-AUG-18 18:25:00', 0, 0, 0, 0, '3.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'E', 'FT LAMAR', 1, 'E', 'FT LAMAR', 34.23, -83.26, 34.23, -83.26, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Madison County Emergency Manager reported a couple of power lines blown down east of Fort Lamar.');
INSERT INTO public.stormevents_east VALUES (777943, 201808, 9, 1918, 201808, 9, 1918, 129822, 'GEORGIA', 13, 2018, 'August', 'Lightning', 'FFC', '09-AUG-18 19:18:00', 'EST-5', '09-AUG-18 19:18:00', 0, 0, 0, 0, '30.00K', NULL, 'Emergency Manager', NULL, NULL, NULL, NULL, 2, 'NE', 'NAMELESS', 2, 'NE', 'NAMELESS', 32.397, -83.0457, 32.397, -83.0457, 'A series of weak short waves moving through a generally zonal upper-level pattern, combined with strong daytime heating each day to produce scattered strong to severe thunderstorms across north and central Georgia.', 'The Laurens County Emergency Manager reported a barn burned to the ground due to a lightning strike in the 3000 block of Highway 338 south of Dexter.');
INSERT INTO public.stormevents_east VALUES (778470, 201808, 21, 2230, 201808, 22, 30, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 22:30:00', 'EST-5', '22-AUG-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'LAWNDALE', 0, 'ESE', 'LAWNDALE', 39.5194, -76.8768, 39.5194, -76.8765, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Lawndale Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (778478, 201808, 21, 2129, 201808, 21, 2329, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:29:00', 'EST-5', '21-AUG-18 23:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'STREET', 1, 'W', 'STREET', 39.6733, -76.4075, 39.672, -76.4076, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The road was closed due to flooding near the intersection of State Route 24 and State Route 165.');
INSERT INTO public.stormevents_east VALUES (779298, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'LOYS', 1, 'ENE', 'LOYS', 39.6019, -77.3381, 39.6021, -77.3387, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Old Mill Road was closed due flooding of Owens Creek.');
INSERT INTO public.stormevents_east VALUES (779299, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'GRACEHAM', 1, 'ENE', 'GRACEHAM', 39.6235, -77.3647, 39.6234, -77.3646, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Hoovers Mill Road was closed due to flooding of Owens Creek.');
INSERT INTO public.stormevents_east VALUES (779300, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 3, 'ESE', 'MOTTERS', 2, 'E', 'MOTTERS', 39.6398, -77.2812, 39.6494, -77.2868, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Sixes Road was closed due to flooding of Toms Creek and Grimes road was closed due to flooding of Toms Creek.');
INSERT INTO public.stormevents_east VALUES (775002, 201808, 2, 1000, 201808, 2, 1005, 129346, 'VIRGINIA', 51, 2018, 'August', 'Tornado', 'LWX', '02-AUG-18 10:00:00', 'EST-5', '02-AUG-18 10:05:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', NULL, NULL, NULL, NULL, 3, 'W', 'SIMEON', 2, 'NW', 'SIMEON', 37.9815, -78.5068, 38.0028, -78.4817, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'A EF-0 tornado touched down 2 miles south of the city limits of|the City of Charlottesville in the Avon Park area of Albemarle|County. The touchdown point at 11:00 AM was near the intersection|of Avon Street Extension and Scottsville Road. The tornado |tracked northeast, roughly parallel to Scottsville Road. Many |trees were uprooted or had large portions snapped off. There was |some minor structural damage to Monticello High School involving |windows and doors. Also at the school, trees and parking lot |lights were downed. A chimney was toppled onto the roof of a home |on Galaxie Farm Lane. The tornado dissipated 5 minutes later |as it crossed near the intersection of Willow Lake Drive and |Scottsville Road.');
INSERT INTO public.stormevents_east VALUES (775003, 201808, 2, 1034, 201808, 2, 1034, 129346, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '02-AUG-18 10:34:00', 'EST-5', '02-AUG-18 10:34:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'SSE', 'RUCKERSVILLE', 1, 'SSE', 'RUCKERSVILLE', 38.2132, -78.3597, 38.2132, -78.3597, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'Tree blown down in the 1300 block of Carpenter Mill Road.');
INSERT INTO public.stormevents_east VALUES (775004, 201808, 2, 1102, 201808, 2, 1102, 129346, 'VIRGINIA', 51, 2018, 'August', 'Thunderstorm Wind', 'LWX', '02-AUG-18 11:02:00', 'EST-5', '02-AUG-18 11:02:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'BURNT TREE', 1, 'E', 'BURNT TREE', 38.3, -78.17, 38.3, -78.17, 'A stalled front near the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'Tree blown down on Slaughter Drive.');
INSERT INTO public.stormevents_east VALUES (778472, 201808, 21, 1410, 201808, 21, 1610, 129519, 'DISTRICT OF COLUMBIA', 11, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 14:10:00', 'EST-5', '21-AUG-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNW', 'US CAPITOL', 0, 'NW', 'US CAPITOL', 38.8822, -77.0215, 38.881, -77.0217, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Seventh Street was closed due to high water approaching I-695 East.');
INSERT INTO public.stormevents_east VALUES (766629, 201806, 11, 1244, 201806, 11, 1344, 127846, 'FLORIDA', 12, 2018, 'June', 'Heavy Rain', 'JAX', '11-JUN-18 12:44:00', 'EST-5', '11-JUN-18 13:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 1, 'ESE', 'WINFIELD', 1, 'ESE', 'WINFIELD', 30.26, -82.66, 30.26, -82.66, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', 'Two inches of rainfall was measured in less than 1 hour.');
INSERT INTO public.stormevents_east VALUES (748629, 201804, 15, 1803, 201804, 15, 1808, 123442, 'VIRGINIA', 51, 2018, 'April', 'Tornado', 'RNK', '15-APR-18 18:03:00', 'EST-5', '15-APR-18 18:08:00', 2, 0, 0, 0, '9.60M', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WNW', '(LYH)GLENN FLD LYNCH', 1, 'NNW', 'BUNCHER', 37.3416, -79.2367, 37.4586, -79.1838, 'A strong cold front with a negatively-tilted upper level trough approached southwest Virginia.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  The thunderstorms ahead of the cold front became strong enough to produce six tornadoes across portions of southwest Virginia.  While the first tornado originally formed in Caswell County of North Carolina and crossed into Virginia, the other five all touched down in Virginia.  These tornadoes caused significant damage within the cities of Danville and Lynchburg and within the town of Elon in Amherst County.  It is the first time ever since storm data records began in 1950 that a tornado struck inside the city limits of Lynchburg.', 'This is the second segment of a tornado that touched down just south of Waterlink Road near Timberlake in Campbell County at 6:00 PM EST.  The tornado crossed Timberlake Road and entered the independent city of Lynchburg at 6:03 PM EST.  The tornado uprooted trees and caused notable damage to 332 private buildings, and 34 of those buildings were condemned due to the damage.  It also damaged numerous power lines and transformers.  Two people were injured.  At 6:07 PM EST, the tornado left the independent city of Lynchburg, crossed the James River, and continued northward into Amherst County.');
INSERT INTO public.stormevents_east VALUES (775197, 201808, 1, 528, 201808, 1, 728, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 05:28:00', 'EST-5', '01-AUG-18 07:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'CROWELLS CORNER', 1, 'ENE', 'CROWELLS CORNER', 38.9534, -77.2913, 38.9533, -77.2915, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'A water rescue occurred at Browns Mill Road at Difficult Run.');
INSERT INTO public.stormevents_east VALUES (775219, 201808, 1, 622, 201808, 1, 822, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 06:22:00', 'EST-5', '01-AUG-18 08:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'KENMORE', 1, 'W', 'KENMORE', 38.9511, -77.2847, 38.9505, -77.2849, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-702 Beulah Road was closed due to flooding at Wolftrap Creek near VA-675 Browns Mill Road.');
INSERT INTO public.stormevents_east VALUES (775194, 201808, 1, 521, 201808, 1, 721, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 05:21:00', 'EST-5', '01-AUG-18 07:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'CLIFTON', 0, 'WNW', 'CLIFTON', 38.7822, -77.3882, 38.7816, -77.3882, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'High water near the intersection of Newman Road and Clifton Creek Drive caused the road to be closed.');
INSERT INTO public.stormevents_east VALUES (775195, 201808, 1, 524, 201808, 1, 724, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 05:24:00', 'EST-5', '01-AUG-18 07:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'ESE', 'RESTON', 1, 'ESE', 'RESTON', 38.967, -77.2924, 38.9666, -77.2908, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Eastbound VA-7 Leesburg Pike was closed due to flooding from Colvin Run near VA-743 Colvin Run Road and Carpers Farm Way.');
INSERT INTO public.stormevents_east VALUES (775205, 201808, 1, 536, 201808, 1, 736, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 05:36:00', 'EST-5', '01-AUG-18 07:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'BRENTSVILLE', 1, 'WSW', 'BRENTSVILLE', 38.677, -77.5099, 38.677, -77.5091, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Old Church Road was closed at Slate Run due to flooding.');
INSERT INTO public.stormevents_east VALUES (775207, 201808, 1, 604, 201808, 1, 804, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 06:04:00', 'EST-5', '01-AUG-18 08:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'LYDIA', 1, 'SSW', 'LYDIA', 38.3298, -78.4967, 38.3169, -78.508, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-634 Mutton Hollow road was closed due to flooding between US-33 Spotswood Trail and VA-635 Matties Run Road.');
INSERT INTO public.stormevents_east VALUES (783185, 201808, 13, 1854, 201808, 13, 1922, 129512, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '13-AUG-18 18:54:00', 'EST-5', '13-AUG-18 19:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'WHITE MARSH', 1, 'SW', 'WHITE MARSH', 39.3719, -76.4504, 39.3702, -76.4468, 'Upper-level low pressure remained over the region while a warm and humid air mass was in place. This resulted in showers and thunderstorms, some of which produced locally heavy rainfall.', 'The stream gauge at Whitemarsh Run indicated that water rapidly rose above flood stage of 11 feet, cresting at 11.34 feet. Water flooded parking lots near the stream, particularly near Town Center Court.');
INSERT INTO public.stormevents_east VALUES (759655, 201805, 22, 1654, 201805, 22, 1659, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 16:54:00', 'EST-5', '22-MAY-18 16:59:00', 0, 0, 0, 0, '8.00K', '0.00K', 'Fire Department/Rescue', 61, 'EG', NULL, NULL, 1, 'WNW', 'DOVER', 1, 'WNW', 'DOVER', 40.53, -81.49, 40.53, -81.49, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'The local fire department reported that high wind lasted for 5 minutes and brought down several trees in the area. Several trees were down on a number of homes in the area.');
INSERT INTO public.stormevents_east VALUES (759777, 201805, 15, 1317, 201805, 15, 1317, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 13:17:00', 'EST-5', '15-MAY-18 13:17:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'NORTH TOWANDA', 1, 'S', 'NORTH TOWANDA', 41.77, -76.45, 41.77, -76.45, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (759778, 201805, 15, 1325, 201805, 15, 1325, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 13:25:00', 'EST-5', '15-MAY-18 13:25:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'W', 'NEW ALBANY', 1, 'W', 'NEW ALBANY', 41.6, -76.44, 41.6, -76.44, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (759779, 201805, 15, 1330, 201805, 15, 1330, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 13:30:00', 'EST-5', '15-MAY-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'N', 'DIMOCK', 0, 'N', 'DIMOCK', 41.75, -75.9, 41.75, -75.9, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (759780, 201805, 15, 1335, 201805, 15, 1335, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 13:35:00', 'EST-5', '15-MAY-18 13:35:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'SOUTH MONTROSE', 0, 'N', 'SOUTH MONTROSE', 41.8, -75.88, 41.8, -75.88, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew a shed over.');
INSERT INTO public.stormevents_east VALUES (759656, 201805, 22, 1700, 201805, 22, 1700, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:00:00', 'EST-5', '22-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'SE', 'NEW PHILADELPHIA', 1, 'SE', 'NEW PHILADELPHIA', 40.49, -81.44, 40.49, -81.44, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'A citizen on social media reported numerous trees down.');
INSERT INTO public.stormevents_east VALUES (760089, 201805, 22, 1640, 201805, 22, 1640, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 16:40:00', 'EST-5', '22-MAY-18 16:40:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 3, 'NE', 'AUGUSTA', 3, 'NE', 'AUGUSTA', 40.72, -80.98, 40.72, -80.98, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'The Department of Transportation reported trees down along State Route 9 at mile marker 26.');
INSERT INTO public.stormevents_east VALUES (760092, 201805, 22, 1706, 201805, 22, 1706, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:06:00', 'EST-5', '22-MAY-18 17:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'ROSCOE', 1, 'N', 'ROSCOE', 40.29, -81.88, 40.29, -81.88, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Department of Transportation reported trees down on U.S. 36, about a quarter mile from Coshocton.');
INSERT INTO public.stormevents_east VALUES (760096, 201805, 22, 1751, 201805, 22, 1751, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:51:00', 'EST-5', '22-MAY-18 17:51:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'CRAIG', 1, 'S', 'CRAIG', 40.02, -81.52, 40.02, -81.52, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'A citizen reported trees down along old National Road.');
INSERT INTO public.stormevents_east VALUES (766630, 201806, 11, 1332, 201806, 11, 1332, 127846, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '11-JUN-18 13:32:00', 'EST-5', '11-JUN-18 13:32:00', 2, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'S', 'MANHATTAN BEACH', 1, 'S', 'MANHATTAN BEACH', 30.35, -81.4, 30.35, -81.4, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', 'Two men were struck by lightning at 19th Street and Beach Blvd near Atlantic Beach. Both survived the strike.');
INSERT INTO public.stormevents_east VALUES (732518, 201802, 24, 2330, 201802, 25, 130, 122345, 'OHIO', 39, 2018, 'February', 'Flood', 'ILN', '24-FEB-18 23:30:00', 'EST-5', '25-FEB-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'FAIRBORN', 2, 'ENE', 'FAIRBORN', 39.8332, -83.992, 39.8321, -83.9909, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'Hebble Creek was reported out of its banks.');
INSERT INTO public.stormevents_east VALUES (732520, 201802, 25, 1130, 201802, 25, 1330, 122345, 'OHIO', 39, 2018, 'February', 'Flood', 'ILN', '25-FEB-18 11:30:00', 'EST-5', '25-FEB-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'MEDWAY', 0, 'ESE', 'MEDWAY', 39.87, -83.99, 39.8776, -83.994, 'Strong to severe thunderstorms, with very heavy rainfall, developed ahead of a cold front.', 'High water was reported over a portion of Spangler Road by Restoration Park Church.');
INSERT INTO public.stormevents_east VALUES (767159, 201806, 11, 1507, 201806, 11, 1507, 127846, 'FLORIDA', 12, 2018, 'June', 'Lightning', 'JAX', '11-JUN-18 15:07:00', 'EST-5', '11-JUN-18 15:07:00', 0, 0, 0, 0, '25.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'S', 'MANHATTAN BEACH', 1, 'S', 'MANHATTAN BEACH', 30.36, -81.4, 30.36, -81.4, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', 'A structure fire at 334 Ocean Walk North Drive was caused by a lightning strike. The cost of damage was unknown, but it was estimated for the inclusion of the event in Storm Data.');
INSERT INTO public.stormevents_east VALUES (767160, 201806, 11, 1445, 201806, 11, 1445, 127846, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '11-JUN-18 14:45:00', 'EST-5', '11-JUN-18 14:45:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'NE', 'ST AUGUSTINE', 1, 'NE', 'ST AUGUSTINE', 29.89, -81.31, 29.89, -81.31, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', 'Multiple lightning strikes hit trees, power lines were down and some trees were down on power lines near St. Augustine. Lightning strikes caused brush fires. The cost of damage was unknown, but it was estimated for the inclusion in Storm Data.');
INSERT INTO public.stormevents_east VALUES (767161, 201806, 11, 1445, 201806, 11, 1445, 127846, 'FLORIDA', 12, 2018, 'June', 'Thunderstorm Wind', 'JAX', '11-JUN-18 14:45:00', 'EST-5', '11-JUN-18 14:45:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'NE', 'ST AUGUSTINE', 1, 'NE', 'ST AUGUSTINE', 29.89, -81.31, 29.89, -81.31, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', 'Multiple lightning strikes hit trees, power lines were down and some trees were down on power lines near St. Augustine. Lightning strikes caused brush fires. The cost of damage was unknown, but it was estimated for the inclusion in Storm Data.');
INSERT INTO public.stormevents_east VALUES (767162, 201806, 11, 1337, 201806, 11, 1337, 127901, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '11-JUN-18 13:37:00', 'EST-5', '11-JUN-18 13:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 35, 'MG', NULL, NULL, 7, 'SW', 'MAYPORT NAS', 7, 'SW', 'MAYPORT NAS', 30.34, -81.51, 30.34, -81.51, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (767163, 201806, 11, 1430, 201806, 11, 1430, 127901, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '11-JUN-18 14:30:00', 'EST-5', '11-JUN-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 3, 'S', 'ST AUGUSTINE ARPT', 3, 'S', 'ST AUGUSTINE ARPT', 29.92, -81.33, 29.92, -81.33, 'Moist and unsettled SW steering flow over a moist and unstable airmass triggered scattered strong to severe storms.', NULL);
INSERT INTO public.stormevents_east VALUES (762586, 201806, 2, 1445, 201806, 2, 1445, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 14:45:00', 'EST-5', '02-JUN-18 14:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'BAXLEY', 2, 'WSW', 'BAXLEY', 31.76, -82.38, 31.76, -82.38, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Power lines were blown down on County Farm Road near Baxley.');
INSERT INTO public.stormevents_east VALUES (762841, 201806, 2, 1455, 201806, 2, 1455, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 14:55:00', 'EST-5', '02-JUN-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'THELMA', 1, 'N', 'THELMA', 30.83, -82.82, 30.83, -82.82, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'A tree was blown down over Highway 187 about 15 miles south of Homerville. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (762843, 201806, 2, 1545, 201806, 2, 1545, 127223, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '02-JUN-18 15:45:00', 'EST-5', '02-JUN-18 15:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'UPTONVILLE', 1, 'SW', 'UPTONVILLE', 30.89, -82.08, 30.89, -82.08, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Trees and power lines were blown down near Grace Chapel Church by Spanish Creek Road.');
INSERT INTO public.stormevents_east VALUES (774984, 201807, 6, 1334, 201807, 6, 1334, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 13:34:00', 'EST-5', '06-JUL-18 13:34:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'CLEMMONS', 1, 'NNW', 'CLEMMONS', 36.0318, -80.3848, 36.0318, -80.3848, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'One tree was reported down along Westwood Village Drive.');
INSERT INTO public.stormevents_east VALUES (774985, 201807, 6, 1335, 201807, 6, 1335, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 13:35:00', 'EST-5', '06-JUL-18 13:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SW', 'BESSEMER', 1, 'SW', 'BESSEMER', 36.0878, -79.7664, 36.0878, -79.7664, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'One tree was reported down near the intersection of Wendover Avenue and Highway 29.');
INSERT INTO public.stormevents_east VALUES (783433, 201805, 15, 1639, 201805, 15, 1639, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:39:00', 'EST-5', '15-MAY-18 16:39:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 0, 'N', 'MOODUS', 0, 'N', 'MOODUS', 41.5, -72.45, 41.5, -72.45, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous trees down.');
INSERT INTO public.stormevents_east VALUES (783435, 201805, 15, 1645, 201805, 15, 1645, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:45:00', 'EST-5', '15-MAY-18 16:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Amateur Radio', 61, 'EG', NULL, NULL, 1, 'E', 'FRANKLIN', 1, 'E', 'FRANKLIN', 41.6, -72.14, 41.6, -72.14, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Multiple trees and wires down between 5:45 and 6 pm on Baltic Road, Old Route 87, and Powder Hill Lane.');
INSERT INTO public.stormevents_east VALUES (783436, 201805, 15, 1615, 201805, 15, 1615, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:15:00', 'EST-5', '15-MAY-18 16:15:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 0, 'N', 'CHESHIRE', 0, 'N', 'CHESHIRE', 41.5, -72.9, 41.5, -72.9, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down near Mountain Road and Sorghum Road.');
INSERT INTO public.stormevents_east VALUES (742584, 201802, 15, 1901, 201802, 16, 1700, 123749, 'PENNSYLVANIA', 42, 2018, 'February', 'Flood', 'PBZ', '15-FEB-18 19:01:00', 'EST-5', '16-FEB-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'MC GOVERN', 0, 'WSW', 'LINDEN', 40.2365, -80.2259, 40.2275, -80.1363, 'Waves of heavy rain produced flooding on February 15th through the 16th. A line of thunderstorms developed along a lifting warm front, providing not only for enhancement in the rainfall totals, which ranged from 1-3 inches, but also attributed to shear that supported the development of a short-lived tornado over Uniontown, in Fayette county Pennsylvania. This was the first tornado in February since 1950 for the Pittsburgh Weather Service area of responsibility.', 'Amateur Radio operator reported that Chartiers Creek was coming out of it''s banks on Pine Street near the American Legion. In addition, several roads were reported to be flooded around Houston and Strabane.');
INSERT INTO public.stormevents_east VALUES (754607, 201805, 10, 1733, 201805, 10, 1740, 125844, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '10-MAY-18 17:33:00', 'EST-5', '10-MAY-18 17:40:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 37, 'MG', NULL, NULL, 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 0, 'N', 'CRISFIELD FIRE DEPARTMENT (CRSFL)', 37.98, -75.86, 37.98, -75.86, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to some storms with gusty winds.', 'Wind gusts of 35 to 37 knots were reported at the Crisfield Fire Department.');
INSERT INTO public.stormevents_east VALUES (754608, 201805, 10, 2033, 201805, 10, 2033, 125844, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '10-MAY-18 20:33:00', 'EST-5', '10-MAY-18 20:33:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 40, 'MG', NULL, NULL, 0, 'N', 'NORTH BAY BUOY (NB)', 0, 'N', 'NORTH BAY BUOY (NB)', 39.38, -76.11, 39.38, -76.11, 'A cold front passed through the area on the 10th. Warm and humid air ahead of the boundary led to an unstable atmosphere. The instability combined with forcing from the cold front to some storms with gusty winds.', 'A wind gust of 40 knots was reported at North Bay.');
INSERT INTO public.stormevents_east VALUES (754609, 201805, 12, 1842, 201805, 12, 1918, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 18:42:00', 'EST-5', '12-MAY-18 19:18:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 42, 'MG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 42 knots were reported at Tolchester.');
INSERT INTO public.stormevents_east VALUES (754614, 201805, 12, 1854, 201805, 12, 1900, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 18:54:00', 'EST-5', '12-MAY-18 19:00:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'BALTIMORE (BLTM2)', 0, 'N', 'BALTIMORE (BLTM2)', 39.27, -76.58, 39.27, -76.58, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts in excess of 30 knots were reported.');
INSERT INTO public.stormevents_east VALUES (754612, 201805, 12, 1859, 201805, 12, 1905, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 18:59:00', 'EST-5', '12-MAY-18 19:05:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'LAKELAND ES AND MS (BLTLK)', 0, 'N', 'LAKELAND ES AND MS (BLTLK)', 39.25, -76.65, 39.25, -76.65, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 35 knots were reported at Lakeland Elementary School.');
