INSERT INTO public.stormevents_east VALUES (754615, 201805, 12, 1905, 201805, 12, 1905, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 19:05:00', 'EST-5', '12-MAY-18 19:05:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'HAMPSTEAD HILL ACADEMY (BLMHH)', 0, 'N', 'HAMPSTEAD HILL ACADEMY (BLMHH)', 39.29, -76.58, 39.29, -76.58, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts in excess of 30 knots were reported at Hampstead Hill Academy.');
INSERT INTO public.stormevents_east VALUES (761287, 201805, 31, 535, 201805, 31, 834, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '31-MAY-18 05:35:00', 'EST-5', '31-MAY-18 08:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'SHELBY', 3, 'SSW', 'SHELBY', 38.2793, -78.3435, 38.2791, -78.3407, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The stream gage on the Rapidan River near Ruckersville exceeded the 14 foot flood stage during the indicated times. The peak level of 15.24 feet occurred at 7:15am EST on May 31st. This was the highest level observed at this location since 1995.');
INSERT INTO public.stormevents_east VALUES (783593, 201805, 15, 1517, 201805, 15, 1517, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:17:00', 'EST-5', '15-MAY-18 15:17:00', 0, 0, 0, 0, '4.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 42, 'N', 'SPUYTEN DUYVIL', 42, 'N', 'SPUYTEN DUYVIL', 41.4806, -74.0227, 41.4806, -74.0227, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Large tree uprooted on Quassaick Avenue.');
INSERT INTO public.stormevents_east VALUES (754634, 201805, 12, 2052, 201805, 12, 2052, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 20:52:00', 'EST-5', '12-MAY-18 20:52:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'BABAR POINT (BAB)', 0, 'N', 'BABAR POINT (BAB)', 38.31, -77.03, 38.31, -77.03, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts of 35 knots were reported at Baber Point.');
