INSERT INTO public.stormevents_east VALUES (761257, 201805, 31, 145, 201805, 31, 215, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '31-MAY-18 01:45:00', 'EST-5', '31-MAY-18 02:15:00', 0, 0, 0, 0, '4.10M', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'LYDIA', 2, 'WNW', 'LYDIA', 38.3536, -78.542, 38.3461, -78.532, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'At least five mudslides were reported in the Swift Run Gap area in Greene County. The slopes gave way, forcing the closure of US Route 33.');
INSERT INTO public.stormevents_east VALUES (761254, 201805, 30, 2357, 201805, 31, 100, 126462, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'LWX', '30-MAY-18 23:57:00', 'EST-5', '31-MAY-18 01:00:00', 0, 0, 0, 0, '677.00K', '312.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'MARCH', 0, 'SE', 'MARCH', 38.2668, -78.5256, 38.2673, -78.5252, 'Upslope winds on the east side of the Blue Ridge just north of an approaching warm front aided in producing torrential rainfall and catastrophic flooding in parts of Central Virginia. Rainfall amounts of 4-10 inches occurred north and west of Charlottesville. Later in the evening, heavy rain developed in northern Virginia, with 1-3 inches in the southern and western suburbs of Washington DC, as well as again near Harrisonburg. This produced another round of flooding and some flash flooding that actually continued into June 1st. June Storm Data will contain those details when available.', 'The southbound lane of Dyke Road in the 10000 block was washed out with a sinkhole reported.');
INSERT INTO public.stormevents_east VALUES (759993, 201805, 27, 1600, 201805, 27, 1800, 126460, 'VIRGINIA', 51, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 16:00:00', 'EST-5', '27-MAY-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'SPARKLING SPGS', 1, 'S', 'SPARKLING SPGS', 38.5377, -78.9322, 38.5387, -78.9312, 'Scattered thunderstorms developed ahead of a cold front over Maryland during the afternoon hours of May 27th. Moderate to heavy rain on saturated soil produced flooding in portions of northern Virginia. The soils were so saturated that just moderate rain caused more flooding near Harrisonburg during the afternoon of the 28th as the cold front pushed through the region.', 'Over three inches of rain caused substantial flooding in the Sparkling Springs area. Numerous roads were closed, including Sparkling Springs Road near Muddy Creek. The stream gage on Muddy Creek in the area briefly exceeded the 8 foot flood stage as well.');
INSERT INTO public.stormevents_east VALUES (753450, 201805, 3, 1759, 201805, 3, 1759, 125576, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '03-MAY-18 17:59:00', 'EST-5', '03-MAY-18 17:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 51, 'MG', NULL, NULL, 0, 'N', '(HPN)WHITE PLAINS AR', 0, 'N', '(HPN)WHITE PLAINS AR', 41.07, -73.7, 41.07, -73.7, 'Severe thunderstorms moved across Westchester County ahead of a cold front.', 'A 59 mph wind gust was measured at Westchester County Airport.');
INSERT INTO public.stormevents_east VALUES (783546, 201805, 15, 1516, 201805, 15, 1516, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:16:00', 'EST-5', '15-MAY-18 15:16:00', 0, 0, 0, 0, NULL, '0.00K', 'NWS Storm Survey', 87, 'EG', NULL, NULL, 0, 'N', 'NEWBURGH', 0, 'N', 'NEWBURGH', 41.5, -74.02, 41.5, -74.02, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Storm Survey Team confirmed straight line wind damage in Newburgh with numerous trees and wires down.  Maximum wind speeds were 90-100 mph.');
INSERT INTO public.stormevents_east VALUES (783591, 201805, 15, 1512, 201805, 15, 1512, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:12:00', 'EST-5', '15-MAY-18 15:12:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 0, 'NW', 'NEWBURGH', 0, 'NW', 'NEWBURGH', 41.5017, -74.0216, 41.5017, -74.0216, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Partial building collapse at South Robinson Avenue and Broadway.');
INSERT INTO public.stormevents_east VALUES (783594, 201805, 15, 1517, 201805, 15, 1517, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:17:00', 'EST-5', '15-MAY-18 15:17:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'WSW', 'WEST NEWBURGH', 1, 'WSW', 'WEST NEWBURGH', 41.4778, -74.0422, 41.4778, -74.0422, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Three foot diameter tree down on van on Union Avenue in New Windsor.');
INSERT INTO public.stormevents_east VALUES (783595, 201805, 15, 1517, 201805, 15, 1517, 124185, 'NEW YORK', 36, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:17:00', 'EST-5', '15-MAY-18 15:17:00', 0, 0, 0, 0, '80.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 1, 'N', 'WEST NEWBURGH', 1, 'N', 'WEST NEWBURGH', 41.49, -74.03, 41.49, -74.03, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Shingles and tar paper blown off the roofs of numerous houses on Meriline Avenue.  In addition...numerous trees down on houses and cars.');
INSERT INTO public.stormevents_east VALUES (754987, 201805, 15, 1955, 201805, 15, 2009, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 19:55:00', 'EST-5', '15-MAY-18 20:09:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'ALEXANDRIA COUNTRY DAY (ALXNC)', 0, 'N', 'ALEXANDRIA COUNTRY DAY (ALXNC)', 38.83, -77.07, 38.83, -77.07, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts in excess of 30 knots were reported at Alexandria Country Day.');
INSERT INTO public.stormevents_east VALUES (754988, 201805, 15, 1959, 201805, 15, 1959, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 19:59:00', 'EST-5', '15-MAY-18 19:59:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'NATIONALS PARK (WSHNP)', 0, 'N', 'NATIONALS PARK (WSHNP)', 38.87, -77.01, 38.87, -77.01, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'A wind gust of 34 knots was reported at Nationals Park.');
INSERT INTO public.stormevents_east VALUES (771175, 201806, 9, 1525, 201806, 9, 1525, 128493, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MFL', '09-JUN-18 15:25:00', 'EST-5', '09-JUN-18 15:25:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 1, 'NE', 'DENAUD', 1, 'NE', 'DENAUD', 26.74, -81.49, 26.74, -81.49, 'The Atlantic seabreeze that developed during the late morning hours of June 7th, quickly moved west and collided with the Gulf breeze across Collier, Hendry, and Glades counties during the afternoon hours. Shower and storm development along these boundaries was enhanced by an upper level low across the eastern Gulf of Mexico, allowing several storms to become severe as a result of the collision, leading to reports of hail across interior Collier and Hendry counties.', 'Report received from WINK-TV of quarter sized hail in Fort Denaud.');
INSERT INTO public.stormevents_east VALUES (771177, 201806, 10, 1023, 201806, 10, 1023, 128494, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'MFL', '10-JUN-18 10:23:00', 'EST-5', '10-JUN-18 10:23:00', 0, 0, 0, 0, NULL, NULL, 'Airplane Pilot', NULL, NULL, NULL, NULL, 19, 'ENE', 'PORT OF PALM BEACH', 19, 'ENE', 'PORT OF PALM BEACH', 26.82, -79.78, 26.82, -79.78, 'Early morning showers and storms across the local Atlantic waters produced waterspouts offshore Palm Beach and Miami-Dade Counties.', 'A waterspout was reported by a pilot at 1123 AM about 23 nm northeast of Palm Beach International Airport. Position adjusted by a couple miles based on radar.');
INSERT INTO public.stormevents_east VALUES (771176, 201806, 10, 745, 201806, 10, 745, 128494, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Waterspout', 'MFL', '10-JUN-18 07:45:00', 'EST-5', '10-JUN-18 07:45:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', NULL, NULL, NULL, NULL, 5, 'ESE', 'GOVERNMENT CUT', 5, 'ESE', 'GOVERNMENT CUT', 25.73, -80.06, 25.73, -80.06, 'Early morning showers and storms across the local Atlantic waters produced waterspouts offshore Palm Beach and Miami-Dade Counties.', 'A photo of a waterspout offshore Miami Beach in the Atlantic waters was reported via twitter at 845am EDT. Location is estimated via radar.');
INSERT INTO public.stormevents_east VALUES (771179, 201806, 10, 1400, 201806, 10, 1400, 128495, 'FLORIDA', 12, 2018, 'June', 'Hail', 'MFL', '10-JUN-18 14:00:00', 'EST-5', '10-JUN-18 14:00:00', 0, 0, 0, 0, NULL, NULL, 'Social Media', 0.75, NULL, NULL, NULL, 1, 'SE', 'GOLDEN GATE', 1, 'SE', 'GOLDEN GATE', 26.16, -81.66, 26.16, -81.66, 'The Atlantic seabreeze developed during the late morning hours of June 10th, quickly moving west and colliding with the Gulf breeze across Collier, Hendry, and Glades counties during the afternoon hours. Shower and storm development along these boundaries was enhanced by an upper level low across the eastern Gulf of Mexico, allowing several strong storms to develop. A funnel cloud was reported in Broward County with the morning activity, along with several reports of hail across inland Collier County during the afternoon hours.', 'A report received via Facebook from a member of the public reported dime sized hail at the toll booth on I-75 near Golden Gate.');
INSERT INTO public.stormevents_east VALUES (771181, 201806, 11, 1138, 201806, 11, 1138, 128496, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'MFL', '11-JUN-18 11:38:00', 'EST-5', '11-JUN-18 11:38:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 14, 'S', 'PORT OF PALM BEACH', 14, 'S', 'PORT OF PALM BEACH', 26.5417, -80.0545, 26.5417, -80.0545, 'Showers and storms across the local Atlantic moving into the east coast during the morning hours, producing a waterspout and strong wind gusts offshore Palm Beach County.', 'A wind gust from the east-southeast at 40 mph/35 knots was measured at the WxFlow station XBOY in Boynton Beach.');
INSERT INTO public.stormevents_east VALUES (783376, 201805, 15, 1545, 201805, 15, 1545, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 15:45:00', 'EST-5', '15-MAY-18 15:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'River/Stream Gage', 61, 'EG', NULL, NULL, 1, 'W', 'NEW FAIRFIELD', 1, 'W', 'NEW FAIRFIELD', 41.47, -73.49, 41.47, -73.49, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Numerous trees down near the intersection of Route 37 and Route 39.  Also nickel sized hail reported.');
INSERT INTO public.stormevents_east VALUES (789477, 201812, 16, 830, 201812, 16, 1030, 131961, 'OHIO', 39, 2018, 'December', 'Flood', 'ILN', '16-DEC-18 08:30:00', 'EST-5', '16-DEC-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'MURRAY CITY', 0, 'WSW', 'MURRAY CITY', 39.51, -82.17, 39.5193, -82.1714, 'A band of heavy rain associated with a low pressure center, brought 1 to 2.5 inches of rain to the region.', 'Hocking County ODOT reported water over several roads in the Monday Creek area of eastern Hocking County. Roads remained open as flooding was minimal.');
INSERT INTO public.stormevents_east VALUES (778457, 201808, 21, 1829, 201808, 21, 2029, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 18:29:00', 'EST-5', '21-AUG-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'DUDIE', 2, 'ENE', 'DUDIE', 38.7417, -77.8557, 38.7415, -77.8556, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Bear Wallow Road was closed due to flooding of Great Run.');
INSERT INTO public.stormevents_east VALUES (778458, 201808, 21, 1829, 201808, 21, 2029, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 18:29:00', 'EST-5', '21-AUG-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'NEW BALTIMORE', 2, 'SE', 'NEW BALTIMORE', 38.7485, -77.6879, 38.7485, -77.6877, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Shepherdstown Road was closed due to flooding of South Run.');
INSERT INTO public.stormevents_east VALUES (778459, 201808, 21, 1829, 201808, 21, 2029, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 18:29:00', 'EST-5', '21-AUG-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'NEW BALTIMORE', 2, 'SW', 'NEW BALTIMORE', 38.7514, -77.7473, 38.7513, -77.7475, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Baldwin Street was closed due to flooding of Mill Run.');
INSERT INTO public.stormevents_east VALUES (778460, 201808, 21, 1829, 201808, 21, 2029, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 18:29:00', 'EST-5', '21-AUG-18 20:29:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'BETHEL', 2, 'ESE', 'BETHEL', 38.7598, -77.7926, 38.7601, -77.7929, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Airlie Road was closed due to flooding of Towser Branch.');
INSERT INTO public.stormevents_east VALUES (778461, 201808, 21, 2146, 201808, 21, 2346, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:46:00', 'EST-5', '21-AUG-18 23:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 4, 'WNW', 'GREAT FALLS', 4, 'WNW', 'GREAT FALLS', 39.0314, -77.335, 39.0307, -77.3349, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Beach Mill Road was closed due to flooding of Jefferson Branch.');
INSERT INTO public.stormevents_east VALUES (775236, 201808, 2, 1901, 201808, 2, 2101, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 19:01:00', 'EST-5', '02-AUG-18 21:01:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'LINDEN', 2, 'WNW', 'LINDEN', 38.91, -78.1, 38.9112, -78.0961, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'There was a water rescue on John Marshall Highway near Dismall Hollow Road. The road was reported to be closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (781654, 201808, 2, 2041, 201808, 3, 212, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 20:41:00', 'EST-5', '03-AUG-18 02:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'ADEN', 3, 'SSW', 'ADEN', 38.6182, -77.5563, 38.6182, -77.5546, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'The Virginia Tech stream gage on Cedar Run near Aden exceeded the 10 foot flood stage during the indicated period. The peak level of 10.21 feet occurred at 1:15am EST on August 3rd. Fleetwood Road was flooded near peak.');
INSERT INTO public.stormevents_east VALUES (777996, 201808, 21, 1329, 201808, 21, 1745, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 13:29:00', 'EST-5', '21-AUG-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'W', 'TREMONT', 38.8454, -77.2384, 38.8477, -77.237, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Woodburn Road was closed due to high water near the intersection with Spicewood Drive. The USGS stream gage on Accotink Creek exceeded the 9.5 foot flood stage during most of the indicated period. The peak of 10.31 feet occurred at 5:00pm EST.');
INSERT INTO public.stormevents_east VALUES (778474, 201808, 21, 1658, 201808, 21, 1858, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 16:58:00', 'EST-5', '21-AUG-18 18:58:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'GREENWOOD', 5, 'E', 'GREENWOOD', 39.4578, -78.2165, 39.4356, -78.1307, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Numerous roads were closed across the central and eastern portions of the county due to high water.');
INSERT INTO public.stormevents_east VALUES (782938, 201808, 22, 22, 201808, 22, 957, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '22-AUG-18 00:22:00', 'EST-5', '22-AUG-18 09:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'VANCLEVESVILLE', 2, 'SW', 'BLAIRTON', 39.4193, -77.9384, 39.4271, -77.941, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The USGS stream gage on Opequon Creek near Martinsburg exceeded the 10 foot flood stage during the indicated period. The peak level of 11.63 feet occurred at 5:31am EST. Golf Course Road and Douglas Grove Road were both flooded.');
INSERT INTO public.stormevents_east VALUES (783181, 201808, 21, 2132, 201808, 22, 247, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:32:00', 'EST-5', '22-AUG-18 02:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MARTINSBURG', 1, 'N', 'MARTINSBURG', 39.4695, -77.9707, 39.4677, -77.9657, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'The stream gauge at Tuscarora Creek in Martinsburg remained above flood stage of 5.5 feet. Water approached the yard and driveway of a private road off Rock Cliff Drive. Water also covered much of the field behind Rock Cliff Plaza.');
INSERT INTO public.stormevents_east VALUES (743110, 201804, 4, 54, 201804, 4, 54, 123842, 'VIRGINIA', 51, 2018, 'April', 'Thunderstorm Wind', 'RLX', '04-APR-18 00:54:00', 'EST-5', '04-APR-18 00:54:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'E', 'CLINTWOOD', 1, 'E', 'CLINTWOOD', 37.15, -82.46, 37.15, -82.46, 'A strong cold front pushed through shortly after midnight on the 4th, driving a line of strong to severe thunderstorms through southwestern Virginia.', 'Several trees were blown down, which also took down some power lines.');
INSERT INTO public.stormevents_east VALUES (743277, 201804, 16, 345, 201804, 16, 630, 123865, 'WEST VIRGINIA', 54, 2018, 'April', 'Flood', 'RLX', '16-APR-18 03:45:00', 'EST-5', '16-APR-18 06:30:00', 0, 0, 0, 0, '3.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'TESLA', 1, 'N', 'CANFIELD', 38.5914, -80.6968, 38.6082, -80.7516, 'A strong upper level system combined with a lot of low level moisture led to a period of heavy rainfall on the 15th into the 16th. Widespread rainfall amounts of 2 to 3 inches fell in 24 to 36 hours from north central West Virginia into the mountainous counties. This led to flooding on many rivers and streams.', 'Flooding along the Birch River caused the closure of Little Burch Road in Little Burch. There were also some driveways flooded along the river in Herold.||In Herold, the gage showed the river rose above its 12 foot bankfull level very early on the 16th. It crested during the predawn hours around 12.2 feet and was back in its banks at sunrise.');
INSERT INTO public.stormevents_east VALUES (743339, 201804, 15, 1348, 201804, 15, 1406, 123727, 'GULF OF MEXICO', 85, 2018, 'April', 'Waterspout', 'TBW', '15-APR-18 13:48:00', 'EST-5', '15-APR-18 14:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 16, 'SSW', 'ST PETERSBURG BEACH', 2, 'S', 'ST PETERSBURG BEACH', 27.5282, -82.8761, 27.6973, -82.747, 'A squall line moved southeast through the eastern Gulf of Mexico ahead of a fast moving cold front. A few of the storms in this line produced waterspouts and strong winds along the coast.', 'Broadcast media relayed a viewer report of a waterspout near the north end of the Sunshine Skyway Bridge. Location was estimated from radar.');
INSERT INTO public.stormevents_east VALUES (779301, 201808, 21, 2330, 201808, 22, 130, 129518, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 23:30:00', 'EST-5', '22-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'MOTTERS', 2, 'NE', 'MOTTERS', 39.6715, -77.2992, 39.6711, -77.2995, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Simmons road was closed at Keysville Road due to flooding of Toms Creek.');
INSERT INTO public.stormevents_east VALUES (753588, 201804, 15, 2058, 201804, 15, 2058, 125637, 'NORTH CAROLINA', 37, 2018, 'April', 'Thunderstorm Wind', 'RAH', '15-APR-18 20:58:00', 'EST-5', '15-APR-18 20:58:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 5, 'ENE', 'TURLINGTON', 5, 'ENE', 'TURLINGTON', 35.39, -78.58, 35.39, -78.58, 'A strong upper low moved from Iowa across the Lower Great Lakes region, with a deep trough taking on a negative tilt while swinging into North Carolina. An associated strong cold front approached western North Carolina that afternoon and pushed east and east-northeast across central North Carolina on the night of the 15th. A strengthening and backing flow at all levels led to a surge of moisture into NC. Moderate instability, strong deep layer shear, and high low-level storm-relative helicity were also present. The result was a quasi-linear convective system with embedded mesovortices, which produced widespread severe weather, including a tornado in Greensboro, as it moved through North Carolina.', 'One tree was blown down on a residence in Benson, causing significant damage to the home.');
INSERT INTO public.stormevents_east VALUES (753740, 201804, 15, 2045, 201804, 15, 2215, 125637, 'NORTH CAROLINA', 37, 2018, 'April', 'Flash Flood', 'RAH', '15-APR-18 20:45:00', 'EST-5', '15-APR-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BRAGGTOWN', 0, 'ESE', 'BRAGGTOWN', 36.0315, -78.9146, 36.0281, -78.8963, 'A strong upper low moved from Iowa across the Lower Great Lakes region, with a deep trough taking on a negative tilt while swinging into North Carolina. An associated strong cold front approached western North Carolina that afternoon and pushed east and east-northeast across central North Carolina on the night of the 15th. A strengthening and backing flow at all levels led to a surge of moisture into NC. Moderate instability, strong deep layer shear, and high low-level storm-relative helicity were also present. The result was a quasi-linear convective system with embedded mesovortices, which produced widespread severe weather, including a tornado in Greensboro, as it moved through North Carolina.', 'Flash flooding was reported on United State highways 15 and 501 and along Gregson Street at Interstate 85.');
INSERT INTO public.stormevents_east VALUES (777815, 201808, 1, 1832, 201808, 1, 1833, 129819, 'GEORGIA', 13, 2018, 'August', 'Tornado', 'FFC', '01-AUG-18 18:32:00', 'EST-5', '01-AUG-18 18:33:00', 0, 0, 0, 0, '200.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SSE', 'HERNDONVILLE', 2, 'SSE', 'HERNDONVILLE', 33.6791, -83.6926, 33.6783, -83.6879, 'A series of short waves moving across the region in ahead of a deep upper-level trough over the Mississippi Valley brought several rounds of strong to severe thunderstorms to north and central Georgia. Several reports of damaging thunderstorm winds, flash flooding and even two isolated tornadoes were reported.', 'A National Weather Service survey team found that an EF1 tornado with maximum wind speeds of 100 MPH and a maximum path width of 100 yards touched down northeast of Social Circle in the 1400 block of Social Circle Fairplay Road. The tornado snapped, uprooted or broke large limbs out of 20 to 30 large trees as it travelled east along the road for nearly a third of a mile. Six homes were damaged, two severely, mainly from falling trees and branches. No injuries were reported. [08/01/18: Tornado #1, County #1/1, EF-1, Walton, 2018:010].');
INSERT INTO public.stormevents_east VALUES (777818, 201808, 1, 1818, 201808, 1, 1825, 129819, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'FFC', '01-AUG-18 18:18:00', 'EST-5', '01-AUG-18 18:25:00', 0, 0, 0, 0, '3.00K', NULL, '911 Call Center', 45, 'EG', NULL, NULL, 1, 'ENE', 'ALCOVY', 1, 'ENE', 'ALCOVY', 33.6331, -83.7685, 33.6331, -83.7685, 'A series of short waves moving across the region in ahead of a deep upper-level trough over the Mississippi Valley brought several rounds of strong to severe thunderstorms to north and central Georgia. Several reports of damaging thunderstorm winds, flash flooding and even two isolated tornadoes were reported.', 'The Newton County 911 center reported a tree blown down onto power lines along Alcovy Trestle Road.');
INSERT INTO public.stormevents_east VALUES (748567, 201804, 15, 1348, 201804, 15, 1348, 123441, 'NORTH CAROLINA', 37, 2018, 'April', 'Hail', 'RNK', '15-APR-18 13:48:00', 'EST-5', '15-APR-18 13:48:00', 0, 0, 0, 0, '0.00K', NULL, 'Fire Department/Rescue', 1.75, NULL, NULL, NULL, 0, 'N', 'PINE RIDGE', 0, 'N', 'PINE RIDGE', 36.5, -80.72, 36.5, -80.72, 'A strong cold front with a negatively-tilted upper level trough approached the North Carolina Piedmont.  Plenty of wind shear with modest instability made conditions ripe for large hail, damaging winds, and tornadoes.  A supercell ahead of the cold front became strong enough to produce two tornadoes.  The first tornado initially formed in Guilford County but crossed into Rockingham County and caused noteworthy damage, while a second tornado touched down in Caswell County and continued into Virginia.', 'Hail up to the size of golf balls fell at Pine Ridge.');
INSERT INTO public.stormevents_east VALUES (775561, 201808, 3, 2219, 201808, 4, 19, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:19:00', 'EST-5', '04-AUG-18 00:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'FAWCETT GAP', 1, 'WSW', 'FAWCETT GAP', 39.13, -78.31, 39.1257, -78.3104, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-629 Laurel Grove Road was closed due to flooding between VA-631 Marlboro Road and VA-608 Wardensville Grade.');
INSERT INTO public.stormevents_east VALUES (775574, 201808, 3, 2250, 201808, 4, 50, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 22:50:00', 'EST-5', '04-AUG-18 00:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'CALVARY', 1, 'SE', 'CALVARY', 38.8776, -78.5535, 38.861, -78.5386, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'VA-605 Saint Louis Road/Sheetz Mill Road was closed due to flooding at the Narrow Passage Creek. VA-42 Senedo Road was closed at the Narrow Passage Creek near VA-680 Coffmantown Road.');
INSERT INTO public.stormevents_east VALUES (782768, 201808, 2, 2253, 201808, 3, 3, 129382, 'MARYLAND', 24, 2018, 'August', 'Flash Flood', 'LWX', '02-AUG-18 22:53:00', 'EST-5', '03-AUG-18 00:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'FRANKLIN', 1, 'SSE', 'FRANKLIN', 39.4914, -79.0433, 39.4917, -79.0438, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding. Some of the flooding lingered into August 3rd.', 'The stream gauge on Georges Creek near Westernport quickly rose above the flood stage of 8 feet, cresting at 8.65 feet. Water reached the underside of the railroad bridge at downtown Westernport.');
INSERT INTO public.stormevents_east VALUES (782767, 201808, 4, 720, 201808, 4, 1430, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 07:20:00', 'EST-5', '04-AUG-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'GLENCOE', 1, 'SSW', 'GLENCOE', 39.5406, -76.6406, 39.541, -76.6376, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'The stream gauge at Glencoe crested at 9.64 feet above the flood stage of 7 feet. Sparks Road was flood.');
INSERT INTO public.stormevents_east VALUES (782763, 201808, 4, 931, 201808, 4, 2344, 129459, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '04-AUG-18 09:31:00', 'EST-5', '04-AUG-18 23:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'PEARL', 0, 'E', 'PEARL', 39.4013, -77.3672, 39.4003, -77.3637, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold moved into the area. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.  Some of the flooding lingered into the early morning hours of the 5th.', 'The stream gauge at Frederick along the Monocacy River crested at 15.74 feet, above the flood stage of 15 feet. Both banks of the river were flooded. Water flooded low-lying fields at Monocacy National Battlefield. Water reached the access road of the Frederick City Wastewater Treatment Plant.');
INSERT INTO public.stormevents_east VALUES (774872, 201808, 1, 49, 201808, 1, 249, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 00:49:00', 'EST-5', '01-AUG-18 02:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'BEALETON', 0, 'SSE', 'BEALETON', 38.57, -77.77, 38.568, -77.7687, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'The 11400 block of VA-656 Remington Road was closed due to flooding over Craig Run.');
INSERT INTO public.stormevents_east VALUES (774923, 201808, 1, 342, 201808, 1, 542, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 03:42:00', 'EST-5', '01-AUG-18 05:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'FAIRFAX STATION', 2, 'W', 'FAIRFAX STATION', 38.8, -77.35, 38.7984, -77.3485, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Fairfax Station Road was closed due to flooding between Colchester Road and Innisvale Drive.');
INSERT INTO public.stormevents_east VALUES (774924, 201808, 1, 353, 201808, 1, 553, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 03:53:00', 'EST-5', '01-AUG-18 05:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'CENTREVILLE', 1, 'NE', 'CENTREVILLE', 38.8404, -77.4049, 38.8403, -77.4041, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Northbound US-29 Lee Highway was closed due to flooding near Clifton Road and Stringfellow Road.');
INSERT INTO public.stormevents_east VALUES (774925, 201808, 1, 355, 201808, 1, 555, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 03:55:00', 'EST-5', '01-AUG-18 05:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'CLARKS CROSSING', 1, 'NNW', 'CLARKS CROSSING', 38.93, -77.31, 38.9307, -77.3057, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Hunter Mill Road closed over Difficult Run due to flooding near Hunter Station Road.');
INSERT INTO public.stormevents_east VALUES (774927, 201808, 1, 527, 201808, 1, 720, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 05:27:00', 'EST-5', '01-AUG-18 07:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'WSW', 'TREMONT', 38.847, -77.2372, 38.8466, -77.2362, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'The USGS stream gage on Accotink Creek near Annandale exceeded the 9.5 foot flood stage during the indicated period. The peak level of 9.99 feet occurred at 6:30am EST. |Woodburn Road was closed over the Accotink Creek due to flooding.');
INSERT INTO public.stormevents_east VALUES (759782, 201805, 15, 1337, 201805, 15, 1337, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 13:37:00', 'EST-5', '15-MAY-18 13:37:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'N', 'KINGSLEY', 0, 'N', 'KINGSLEY', 41.77, -75.77, 41.77, -75.77, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew pieces of siding off of house. Windows were also broken.');
INSERT INTO public.stormevents_east VALUES (759784, 201805, 15, 1346, 201805, 15, 1346, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 13:46:00', 'EST-5', '15-MAY-18 13:46:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 2.75, NULL, NULL, NULL, 0, 'N', 'HARFORD', 0, 'N', 'HARFORD', 41.78, -75.7, 41.78, -75.7, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Hail broke a window in house.');
INSERT INTO public.stormevents_east VALUES (759785, 201805, 15, 1357, 201805, 15, 1357, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 13:57:00', 'EST-5', '15-MAY-18 13:57:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'CLIFFORD', 0, 'N', 'CLIFFORD', 41.65, -75.6, 41.65, -75.6, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (759786, 201805, 15, 1405, 201805, 15, 1406, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Tornado', 'BGM', '15-MAY-18 14:05:00', 'EST-5', '15-MAY-18 14:06:00', 0, 0, 0, 0, '50.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WNW', 'PROMPTON', 2, 'WNW', 'PROMPTON', 41.5898, -75.3719, 41.589, -75.3678, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'A weak tornado touched down on the eastern shore of Keen Lake, approximately |120 yards from the coastline.  Most of the damage observed with the tornado was |noted near the touchdown point, where several (mostly) pine trees were snapped |and uprooted.  Damage to homes in the area was also noted, as well as the loss of |gutters and mesh screening for porches.  Minor roof damage was also seen, as |trees were snapped along the path.  A weakly convergent path, and sporadic tree |damage, continued along the tornado''s path before lifting in an open field just |under one-quarter of a mile east-southeast of its touchdown point.');
INSERT INTO public.stormevents_east VALUES (761111, 201805, 26, 1553, 201805, 26, 1553, 126993, 'MICHIGAN', 26, 2018, 'May', 'Hail', 'APX', '26-MAY-18 15:53:00', 'EST-5', '26-MAY-18 15:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 0, 'E', 'SPRATT', 0, 'E', 'SPRATT', 45, -83.76, 45, -83.76, 'Numerous thunderstorms developed over north central and northeast lower Michigan on the afternoon of the 26th. Some of these storms became severe, producing marginally large hail, though one storm produced isolated wind damage.', NULL);
INSERT INTO public.stormevents_east VALUES (761128, 201805, 27, 1509, 201805, 27, 1510, 126994, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'APX', '27-MAY-18 15:09:00', 'EST-5', '27-MAY-18 15:10:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Fire Department/Rescue', 55, 'EG', NULL, NULL, 3, 'NE', 'STERLING', 3, 'NE', 'STERLING', 44.07, -83.98, 44.07, -83.98, 'Strong to severe thunderstorms developed along a cold front over northeast lower Michigan on the afternoon of the 27th. As opposed to the previous day, these storms produced mainly damaging winds, with one report of hail.', 'Numerous trees were blown down.');
INSERT INTO public.stormevents_east VALUES (761131, 201805, 27, 1520, 201805, 27, 1525, 126994, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'APX', '27-MAY-18 15:20:00', 'EST-5', '27-MAY-18 15:25:00', 0, 0, 0, 0, '16.00K', '0.00K', 'Public', 54, 'EG', NULL, NULL, 6, 'NW', 'EAST TAWAS IOSCO ARP', 2, 'N', 'TAWAS CITY', 44.37, -83.52, 44.3038, -83.5245, 'Strong to severe thunderstorms developed along a cold front over northeast lower Michigan on the afternoon of the 27th. As opposed to the previous day, these storms produced mainly damaging winds, with one report of hail.', 'Scattered patches of trees and power lines downed in central Iosco County.');
INSERT INTO public.stormevents_east VALUES (760094, 201805, 22, 1714, 201805, 22, 1714, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:14:00', 'EST-5', '22-MAY-18 17:14:00', 0, 0, 0, 0, '0.50K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 1, 'S', 'COSHOCTON', 1, 'S', 'COSHOCTON', 40.26, -81.85, 40.26, -81.85, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'A state official reported trees down along County road 55, just northeast of Coshocton and along Cambridge Road near Coshocton High School.');
INSERT INTO public.stormevents_east VALUES (761201, 201805, 22, 1655, 201805, 22, 1655, 126724, 'OHIO', 39, 2018, 'May', 'Hail', 'PBZ', '22-MAY-18 16:55:00', 'EST-5', '22-MAY-18 16:55:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Fire Department/Rescue', 0.75, NULL, NULL, NULL, 1, 'WNW', 'DOVER', 1, 'WNW', 'DOVER', 40.53, -81.49, 40.53, -81.49, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Local fire department reported that wind-blown hail damaged vehicles.');
INSERT INTO public.stormevents_east VALUES (761202, 201805, 22, 1700, 201805, 22, 1700, 126724, 'OHIO', 39, 2018, 'May', 'Hail', 'PBZ', '22-MAY-18 17:00:00', 'EST-5', '22-MAY-18 17:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 1, 'NW', 'DOVER', 1, 'NW', 'DOVER', 40.53, -81.48, 40.53, -81.48, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', NULL);
INSERT INTO public.stormevents_east VALUES (761203, 201805, 22, 1722, 201805, 22, 1722, 126724, 'OHIO', 39, 2018, 'May', 'Hail', 'PBZ', '22-MAY-18 17:22:00', 'EST-5', '22-MAY-18 17:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1, NULL, NULL, NULL, 0, 'N', 'INDIAN CAMP', 0, 'N', 'INDIAN CAMP', 40.1, -81.65, 40.1, -81.65, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', NULL);
INSERT INTO public.stormevents_east VALUES (761205, 201805, 22, 1705, 201805, 22, 1705, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:05:00', 'EST-5', '22-MAY-18 17:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'S', 'MARR', 1, 'S', 'MARR', 39.62, -81.23, 39.62, -81.23, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'State Department of Highways reported five trees down along State Route 260.');
INSERT INTO public.stormevents_east VALUES (761437, 201805, 26, 1327, 201805, 26, 1500, 127052, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'MRX', '26-MAY-18 13:27:00', 'EST-5', '26-MAY-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 4, 'E', 'LEBANON', 2, 'SE', 'LEBANON', 36.9, -82.0076, 36.8795, -82.0544, 'Deep moisture encroached upon the area from the Gulf of Mexico, where subtropical storm Alberto was developing. Scattered mainly diurnal convection produced isolated flooding.', 'Roads flooded. Flooding across a trailer park.');
INSERT INTO public.stormevents_east VALUES (761440, 201805, 26, 1300, 201805, 26, 1430, 127052, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'MRX', '26-MAY-18 13:00:00', 'EST-5', '26-MAY-18 14:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'POUND', 1, 'E', 'POUND', 37.13, -82.62, 37.13, -82.6019, 'Deep moisture encroached upon the area from the Gulf of Mexico, where subtropical storm Alberto was developing. Scattered mainly diurnal convection produced isolated flooding.', 'Intersection of Highways 23 and 83 in Pound was flooded.');
INSERT INTO public.stormevents_east VALUES (761442, 201805, 27, 1650, 201805, 27, 1820, 127052, 'VIRGINIA', 51, 2018, 'May', 'Flash Flood', 'MRX', '27-MAY-18 16:50:00', 'EST-5', '27-MAY-18 18:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 11, 'SW', 'ABINGDON', 5, 'WSW', 'ABINGDON', 36.5974, -82.1203, 36.6823, -82.0634, 'Deep moisture encroached upon the area from the Gulf of Mexico, where subtropical storm Alberto was developing. Scattered mainly diurnal convection produced isolated flooding.', 'Flooding on several roadways. Several mudslides in the southern part of the county near Holston Lake.');
INSERT INTO public.stormevents_east VALUES (800242, 201809, 1, 1605, 201809, 1, 1605, 133722, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '01-SEP-18 16:05:00', 'EST-5', '01-SEP-18 16:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNE', 'GREENSBORO', 1, 'NNE', 'GREENSBORO', 36.09, -79.79, 36.0868, -79.7887, 'A strongly unstable air mass combined with an upper level disturbance to trigger numerous thunderstorms across the northern Piedmont, with a few reports of wind damage and one report of flash flooding. Storms produced a massive outflow boundary and excessive amounts of lightning. Storm coverage was more limited to the south and east in the Coastal Plain and southern Piedmont.', 'One tree was reported down on north Elm Street and Wendover Avenue.');
INSERT INTO public.stormevents_east VALUES (800243, 201809, 1, 1615, 201809, 1, 1615, 133722, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '01-SEP-18 16:15:00', 'EST-5', '01-SEP-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'ALTAMAHAW', 1, 'NNW', 'ALTAMAHAW', 36.1962, -79.5107, 36.1962, -79.5107, 'A strongly unstable air mass combined with an upper level disturbance to trigger numerous thunderstorms across the northern Piedmont, with a few reports of wind damage and one report of flash flooding. Storms produced a massive outflow boundary and excessive amounts of lightning. Storm coverage was more limited to the south and east in the Coastal Plain and southern Piedmont.', 'One tree was reported down on Highway 87 near Ed Patterson Road.');
INSERT INTO public.stormevents_east VALUES (800244, 201809, 1, 1632, 201809, 1, 1632, 133722, 'NORTH CAROLINA', 37, 2018, 'September', 'Thunderstorm Wind', 'RAH', '01-SEP-18 16:32:00', 'EST-5', '01-SEP-18 16:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'SSE', 'ALTAMAHAW', 2, 'SSE', 'ALTAMAHAW', 36.1525, -79.4802, 36.1525, -79.4802, 'A strongly unstable air mass combined with an upper level disturbance to trigger numerous thunderstorms across the northern Piedmont, with a few reports of wind damage and one report of flash flooding. Storms produced a massive outflow boundary and excessive amounts of lightning. Storm coverage was more limited to the south and east in the Coastal Plain and southern Piedmont.', 'One tree was reported down on Gerringer Mill Road.');
INSERT INTO public.stormevents_east VALUES (774988, 201807, 6, 1345, 201807, 6, 1345, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 13:45:00', 'EST-5', '06-JUL-18 13:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'KERNERSVILLE', 1, 'S', 'KERNERSVILLE', 36.1089, -80.0779, 36.1089, -80.0779, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'One tree was reported down across the road near the intersection of Lindsey Street and Salisbury Street.');
INSERT INTO public.stormevents_east VALUES (774989, 201807, 6, 1419, 201807, 6, 1419, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 14:19:00', 'EST-5', '06-JUL-18 14:19:00', 0, 0, 0, 0, '2.50K', '0.00K', 'Utility Company', 50, 'EG', NULL, NULL, 1, 'W', 'SEDALIA', 1, 'W', 'SEDALIA', 36.07, -79.63, 36.07, -79.63, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'Trees and power lines were reported down.');
INSERT INTO public.stormevents_east VALUES (774991, 201807, 6, 1450, 201807, 6, 1450, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 14:50:00', 'EST-5', '06-JUL-18 14:50:00', 0, 0, 0, 0, '2.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'SE', 'CEDAR GROVE', 0, 'SE', 'CEDAR GROVE', 36.1676, -79.1676, 36.1676, -79.1676, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'A tree and power line were reported down at Elland Cedar Grove Road and Carr Store Road.');
INSERT INTO public.stormevents_east VALUES (774995, 201807, 6, 1500, 201807, 6, 1500, 129313, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '06-JUL-18 15:00:00', 'EST-5', '06-JUL-18 15:00:00', 0, 0, 0, 0, '1.50K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'HILLSBOROUGH', 1, 'ENE', 'HILLSBOROUGH', 36.0898, -79.1035, 36.0866, -79.1018, 'Storms initiated in split upper level flow along a prefrontal trough. Mean 850 MB to 300 MB winds were near calm at the time with storm propagation mainly cold pool driven. The primary impacts from these storms were gusty winds, resulting in trees down, and heavy rain. One storm did become anchored over Raleigh which prompted a flash flood warning.', 'A couple of trees were reported down on North Carolina Highway 86, one at Holman Drive and another on Highway 70.');
INSERT INTO public.stormevents_east VALUES (757398, 201805, 15, 1630, 201805, 15, 1630, 126337, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '15-MAY-18 16:30:00', 'EST-5', '15-MAY-18 16:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 51, 'MG', NULL, NULL, 0, 'N', 'EATONS NECK WXFLOW', 0, 'N', 'EATONS NECK WXFLOW', 40.95, -73.4, 40.95, -73.4, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 59 mile per hour gust was reported at the Eatons Neck mesonet.');
INSERT INTO public.stormevents_east VALUES (757399, 201805, 15, 1659, 201805, 15, 1659, 126337, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '15-MAY-18 16:59:00', 'EST-5', '15-MAY-18 16:59:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 37, 'MG', NULL, NULL, 50, 'NE', 'STATION 44025', 50, 'NE', 'STATION 44025', 40.84, -72.63, 40.84, -72.63, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 43 mile per hour gust was reported at the Westhampton Airport.');
INSERT INTO public.stormevents_east VALUES (766252, 201806, 2, 1711, 201806, 2, 1711, 127224, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '02-JUN-18 17:11:00', 'EST-5', '02-JUN-18 17:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 49, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', NULL);
INSERT INTO public.stormevents_east VALUES (776802, 201807, 28, 1603, 201807, 28, 1603, 129696, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '28-JUL-18 16:03:00', 'EST-5', '28-JUL-18 16:03:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'ENE', 'BESTS', 4, 'ENE', 'BESTS', 35.38, -77.81, 35.38, -77.81, 'A quasi-stationary front, bisecting central NC, provided a focus point for scattered to numerous showers and thunderstorms. Thanks to a moist and unstable airmass, a few of these storms breached the severe limit, resulting in isolated wind damage, and localized flash flooding.', 'Thunderstorm winds downed several trees onto roadways across the eastern half of the county. These trees primarily came down on Hood Swamp Road and Parkerstown Road.');
INSERT INTO public.stormevents_east VALUES (776804, 201807, 28, 1745, 201807, 28, 1745, 129696, 'NORTH CAROLINA', 37, 2018, 'July', 'Thunderstorm Wind', 'RAH', '28-JUL-18 17:45:00', 'EST-5', '28-JUL-18 17:45:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ENE', 'KNIGHTDALE WNDLL ARP', 1, 'ENE', 'KNIGHTDALE WNDLL ARP', 35.8026, -78.4173, 35.8026, -78.4173, 'A quasi-stationary front, bisecting central NC, provided a focus point for scattered to numerous showers and thunderstorms. Thanks to a moist and unstable airmass, a few of these storms breached the severe limit, resulting in isolated wind damage, and localized flash flooding.', 'Tree reported down on power-line at Wendell Boulevard and Rolesville Road.');
INSERT INTO public.stormevents_east VALUES (754643, 201805, 12, 2100, 201805, 12, 2100, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 21:00:00', 'EST-5', '12-MAY-18 21:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 45, 'MG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'A wind gust of 45 knots was reported at Thomas Point Lighthouse.');
INSERT INTO public.stormevents_east VALUES (754644, 201805, 12, 2106, 201805, 12, 2118, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 21:06:00', 'EST-5', '12-MAY-18 21:18:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 5, 'S', 'MID BAY BUOY', 5, 'S', 'MID BAY BUOY', 38.404, -76.386, 38.404, -76.386, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 34 knots were reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (754637, 201805, 12, 2106, 201805, 12, 2116, 125845, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '12-MAY-18 21:06:00', 'EST-5', '12-MAY-18 21:16:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'MONROE CREEK (MON)', 0, 'N', 'MONROE CREEK (MON)', 38.23, -76.95, 38.23, -76.95, 'Low pressure tracked along a boundary and passed through the area on the 12th. Warm and humid air on the southern side of the boundary led to an unstable atmosphere. Some storms produced gusty winds.', 'Wind gusts up to 34 knots were reported at Monroe Creek.');
INSERT INTO public.stormevents_east VALUES (760906, 201805, 27, 2216, 201805, 27, 2359, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 22:16:00', 'EST-5', '27-MAY-18 23:59:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'PRINCE FREDERICK', 2, 'WNW', 'PRINCE FREDERICK', 38.5368, -76.5842, 38.5375, -76.5833, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Duke Street flooded and closed in Prince Frederick.');
INSERT INTO public.stormevents_east VALUES (760913, 201805, 27, 1833, 201805, 27, 2000, 126459, 'MARYLAND', 24, 2018, 'May', 'Flood', 'LWX', '27-MAY-18 18:33:00', 'EST-5', '27-MAY-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'GLEN BURNIE', 0, 'SSE', 'GLEN BURNIE', 39.1702, -76.6311, 39.1695, -76.6298, 'A cold front sagged into Maryland during the afternoon of May 27th. Heavy rain trained to the northeast of Baltimore early in the afternoon, causing flash flooding. Then, later in the afternoon, the line completely stalled just west of Baltimore, producing 6-12 inches of rain in a very short period of time. Catastrophic flash flooding occurred in the Ellicott City and Catonsville areas, with significant flooding also observed in other nearby areas. Stream flooding continued through the next morning.', 'Maryland Route 648 flooded and closed at Sawmill Creek in Glen Burnie.');
INSERT INTO public.stormevents_east VALUES (754958, 201805, 14, 1821, 201805, 14, 1841, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:21:00', 'EST-5', '14-MAY-18 18:41:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 38.34, -76.99, 38.34, -76.99, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts up to 35 knots were reported at Potomac Light.');
INSERT INTO public.stormevents_east VALUES (754959, 201805, 14, 1822, 201805, 14, 1832, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:22:00', 'EST-5', '14-MAY-18 18:32:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'BABAR POINT (BAB)', 0, 'N', 'BABAR POINT (BAB)', 38.31, -77.03, 38.31, -77.03, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'A wind gust of 35 knots was reported at Baber Point.');
INSERT INTO public.stormevents_east VALUES (754960, 201805, 14, 1823, 201805, 14, 1838, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:23:00', 'EST-5', '14-MAY-18 18:38:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 2, 'E', 'BABAR POINT (BAB)', 2, 'E', 'BABAR POINT (BAB)', 38.3089, -77.0019, 38.3089, -77.0019, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts up to 41 knots were reported at Pylons DAH.');
INSERT INTO public.stormevents_east VALUES (754963, 201805, 14, 1834, 201805, 14, 1844, 125930, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '14-MAY-18 18:34:00', 'EST-5', '14-MAY-18 18:44:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'Low pressure passed through the area on the 14th. The low tracked along a boundary that separated warm and humid air to the south and west from cooler marine air to the north and east. The warm and humid air led to an unstable atmosphere, and there was enough instability for storms to produce gusty winds.', 'Wind gusts up to 36 knots were reported at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (754990, 201805, 15, 2000, 201805, 15, 2100, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 20:00:00', 'EST-5', '15-MAY-18 21:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 43, 'MG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts of 35 to 43 knots were reported at Thomas Point Lighthouse.');
INSERT INTO public.stormevents_east VALUES (754991, 201805, 15, 2009, 201805, 15, 2009, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 20:09:00', 'EST-5', '15-MAY-18 20:09:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'GREENBERRY POINT (GBY)', 0, 'N', 'GREENBERRY POINT (GBY)', 38.97, -76.46, 38.97, -76.46, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts in excess of 30 knots were reported at Greenberry Point.');
INSERT INTO public.stormevents_east VALUES (754993, 201805, 15, 2017, 201805, 15, 2017, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 20:17:00', 'EST-5', '15-MAY-18 20:17:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'EG', NULL, NULL, 0, 'N', 'KENT ISLAND (KNT)', 0, 'N', 'KENT ISLAND (KNT)', 38.92, -76.36, 38.92, -76.36, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts in excess of 30 knots were reported at the Kent Island.');
INSERT INTO public.stormevents_east VALUES (754994, 201805, 15, 2118, 201805, 15, 2136, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 21:18:00', 'EST-5', '15-MAY-18 21:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 44, 'MG', NULL, NULL, 5, 'S', 'MID BAY BUOY', 5, 'S', 'MID BAY BUOY', 38.404, -76.386, 38.404, -76.386, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts up to 44 knots were reported at Cove Point.');
INSERT INTO public.stormevents_east VALUES (754995, 201805, 15, 2130, 201805, 15, 2142, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 21:30:00', 'EST-5', '15-MAY-18 21:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 35, 'MG', NULL, NULL, 0, 'N', 'SOLOMONS ISLAND (SLIM2)', 0, 'N', 'SOLOMONS ISLAND (SLIM2)', 38.32, -76.45, 38.32, -76.45, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts up to 35 knots were reported at Solomons Island.');
INSERT INTO public.stormevents_east VALUES (754996, 201805, 15, 2146, 201805, 15, 2153, 125936, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '15-MAY-18 21:46:00', 'EST-5', '15-MAY-18 21:53:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 34, 'MG', NULL, NULL, 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 0, 'N', 'PATUXENT RIVER ASOS (KNAK)', 38.29, -76.41, 38.29, -76.41, 'A cold front passed through the area. Warm and humid conditions led to an unstable atmosphere ahead of the boundary, and that caused a few storms to become severe.', 'Wind gusts up to 34 knots were reported at Patuxent River (KNHK).');
INSERT INTO public.stormevents_east VALUES (754997, 201805, 16, 1800, 201805, 16, 1810, 125937, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'LWX', '16-MAY-18 18:00:00', 'EST-5', '16-MAY-18 18:10:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 49, 'MG', NULL, NULL, 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 0, 'N', 'POTOMAC POINT LOOKOUT BUOY (44042)', 38.03, -76.34, 38.03, -76.34, 'An isolated thunderstorm produced gusty winds.', 'Wind gusts up to 49 knots were reported at Point Lookout.');
INSERT INTO public.stormevents_east VALUES (774627, 201807, 25, 1800, 201807, 25, 2000, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 18:00:00', 'EST-5', '25-JUL-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'WOODBRIDGE ARPT', 2, 'NE', 'WOODBRIDGE ARPT', 38.6952, -77.298, 38.6953, -77.2976, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Cotton Mill Drive flooded and closed between Antietam Road and Fox Tail Court.');
INSERT INTO public.stormevents_east VALUES (774628, 201807, 25, 1853, 201807, 25, 2030, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 18:53:00', 'EST-5', '25-JUL-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'BUFFS CORNER', 1, 'NW', 'BUFFS CORNER', 38.7895, -77.343, 38.79, -77.3427, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Havenner Road flooded and closed near Youngs Branch Drive.');
INSERT INTO public.stormevents_east VALUES (774656, 201807, 25, 1930, 201807, 25, 2100, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 19:30:00', 'EST-5', '25-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'MOUNTAIN VIEW', 2, 'SSE', 'MOUNTAIN VIEW', 38.438, -77.453, 38.4383, -77.4522, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Courthouse Road flooded near Woodcutters Road.');
INSERT INTO public.stormevents_east VALUES (774658, 201807, 25, 1930, 201807, 25, 2100, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 19:30:00', 'EST-5', '25-JUL-18 21:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'MOUNTAIN VIEW', 1, 'SE', 'MOUNTAIN VIEW', 38.4568, -77.4552, 38.4565, -77.4547, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'Winding Creek Road flooded and closed near Walpole Street.');
INSERT INTO public.stormevents_east VALUES (773321, 201807, 26, 1347, 201807, 26, 1347, 128910, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '26-JUL-18 13:47:00', 'EST-5', '26-JUL-18 13:47:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 54, 'EG', NULL, NULL, 1, 'NW', 'CARLETON', 1, 'NW', 'CARLETON', 42.06, -83.39, 42.06, -83.39, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', 'Numerous trees blown down throughout Monroe County, most around Carleton.');
INSERT INTO public.stormevents_east VALUES (774661, 201807, 25, 2120, 201807, 25, 2300, 128278, 'VIRGINIA', 51, 2018, 'July', 'Flood', 'LWX', '25-JUL-18 21:20:00', 'EST-5', '25-JUL-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NNE', 'GUM SPGS', 0, 'NNE', 'GUM SPGS', 38.7362, -77.0762, 38.7359, -77.0761, 'Following the passage of a coastal low, bands of moisture continued to pull northward across the same areas that had already experienced heavy rain. Heavy rainfall fell in some areas, with widespread flooding throughout the period.', 'High water near the intersection of Apple Hill Road and Chancery Court. Road closed.');
INSERT INTO public.stormevents_east VALUES (783384, 201805, 15, 1605, 201805, 15, 1605, 126236, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'OKX', '15-MAY-18 16:05:00', 'EST-5', '15-MAY-18 16:05:00', 0, 0, 0, 0, '12.00K', '0.00K', 'Trained Spotter', 70, 'EG', NULL, NULL, 2, 'SE', 'PINE BRIDGE', 2, 'SE', 'PINE BRIDGE', 41.4, -73.05, 41.4, -73.05, 'An approaching cold front triggered numerous severe thunderstorms over southern Connecticut. These storms produced 2 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'Trees down on top of shed, numerous other trees down throughout neighborhood.');
INSERT INTO public.stormevents_east VALUES (783716, 201809, 18, 923, 201809, 18, 1300, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 09:23:00', 'EST-5', '18-SEP-18 13:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'EAST MILLBURY', 1, 'WNW', 'EAST MILLBURY', 42.2366, -71.7498, 42.2357, -71.7464, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 9:23 AM EST, U.S. Route 20 in Worcester was flooded at the Grafton Street overpass.');
INSERT INTO public.stormevents_east VALUES (783729, 201809, 18, 955, 201809, 18, 1455, 131003, 'MASSACHUSETTS', 25, 2018, 'September', 'Flash Flood', 'BOX', '18-SEP-18 09:55:00', 'EST-5', '18-SEP-18 14:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSW', 'LAWRENCE', 1, 'NNE', 'SOUTH LAWRENCE', 42.7008, -71.1601, 42.6995, -71.1599, 'Post-Tropical Cyclone Florence moved up the East Coast, bringing heavy downpours and damaging thunderstorms to Massachusetts during September 18th.  Storm total rainfall amounts reached two to five inches, and went as high as seven inches in parts of Worcester County.', 'At 9:55 AM EST, Parker Street in Lawrence was closed from Market Street to Merrimack Street due to flooding at the railroad underpass.');
INSERT INTO public.stormevents_east VALUES (796561, 201812, 28, 1302, 201812, 28, 1305, 133140, 'SOUTH CAROLINA', 45, 2018, 'December', 'Thunderstorm Wind', 'CAE', '28-DEC-18 13:02:00', 'EST-5', '28-DEC-18 13:05:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 2, 'NNE', 'DENNIS XRDS', 2, 'NNE', 'DENNIS XRDS', 34.1, -81.7, 34.1, -81.7, 'A band of showers and thunderstorms moved across the region during the afternoon, associated with a cold front. Instability and shear contributed to a segment of the line producing damaging winds in Saluda Co SC.', 'A tree was downed onto a house on Hollywood Rd, and several other trees were downed in the vicinity.');
INSERT INTO public.stormevents_east VALUES (775228, 201808, 2, 236, 201808, 2, 2347, 129381, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '02-AUG-18 02:36:00', 'EST-5', '02-AUG-18 23:47:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'BRENTSVILLE', 0, 'WSW', 'BRENTSVILLE', 38.68, -77.51, 38.6785, -77.5077, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding, some of which lingered into the early morning hours of the 3rd.', 'Four feet of water covered Old Church Road near Slate Run Road.');
INSERT INTO public.stormevents_east VALUES (778475, 201808, 21, 2149, 201808, 21, 2349, 129521, 'WEST VIRGINIA', 54, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 21:49:00', 'EST-5', '21-AUG-18 23:49:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'MARTINSBURG', 1, 'NNE', 'MARTINSBURG', 39.4672, -77.9599, 39.467, -77.9587, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Homes adjacent to Elizabeth Street and Hess Avenue in Martinsburg were evacuated due to flooding.');
INSERT INTO public.stormevents_east VALUES (782408, 201808, 3, 2200, 201808, 4, 100, 129820, 'GEORGIA', 13, 2018, 'August', 'Flash Flood', 'FFC', '03-AUG-18 22:00:00', 'EST-5', '04-AUG-18 01:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'State Official', NULL, NULL, 'Heavy Rain', NULL, 4, 'SW', 'NEW BRANCH', 5, 'SSW', 'NEW BRANCH', 32.0337, -82.3035, 32.0085, -82.29, 'Summertime showers and thunderstorms produced locally heavy rainfall in the afternoon and evening of August 3. Soils were saturated from rainfall early in the week, and combined with rainfall amounts of 2 to 4 inches to cause isolated flash flooding, particularly over portions of east central Georgia.', 'Flash flooding was reported along John Dasher Road, between Hayden Jones Road and Clifford Rogers Road, and on Marvin Church Road. Radar estimates indicate that rainfall amounts of 2.5 to 4 inches occurred in a short period of time.');
INSERT INTO public.stormevents_east VALUES (744102, 201804, 23, 1823, 201804, 23, 1828, 123974, 'GEORGIA', 13, 2018, 'April', 'Thunderstorm Wind', 'FFC', '23-APR-18 18:23:00', 'EST-5', '23-APR-18 18:28:00', 0, 0, 0, 0, '20.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'NNW', 'VIDALIA', 1, 'NNW', 'VIDALIA', 32.2279, -82.4259, 32.2279, -82.4259, 'A strong cold front associated with a deep upper-level low swept across the region. Moderate instability and strong mid-level winds combined to produce scattered severe thunderstorms across portions of central and east Georgia.', 'The Toombs County Emergency Manager reported a few trees blown down around the intersection of Highway 292 and Fowler Street and damage to the roof of Vidalia High School nearby.');
INSERT INTO public.stormevents_east VALUES (775000, 201808, 1, 2145, 201808, 1, 2145, 129345, 'MARYLAND', 24, 2018, 'August', 'Thunderstorm Wind', 'LWX', '01-AUG-18 21:45:00', 'EST-5', '01-AUG-18 21:45:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'SE', 'SCARBORO', 1, 'SE', 'SCARBORO', 39.62, -76.27, 39.62, -76.27, 'A cold front crossing the region combined with high instability and moderate shear values to produce thunderstorms, a few of which became severe.', 'Tree blew down on wires in the 1300 block of Trappe Road.');
INSERT INTO public.stormevents_east VALUES (780000, 201808, 21, 1508, 201808, 21, 1510, 130280, 'PENNSYLVANIA', 42, 2018, 'August', 'Tornado', 'PBZ', '21-AUG-18 15:08:00', 'EST-5', '21-AUG-18 15:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'SE', 'CRENSHAW', 2, 'E', 'CRENSHAW', 41.234, -78.754, 41.2496, -78.739, 'Low pressure tracked northeastward across Michigan and eastern Canada, pushing a warm front across western Pennsylvania in the morning, with some showers and thunderstorms ahead of it.  Breaks in the clouds behind this morning activity allowed instability to build once again during the afternoon.  The environment behind the warm front was favorable for severe weather with strong wind shear and deep moisture.  Several discrete storms were able to form, with rotation and bounded weak echo regions noted in a few storms.  However, the only reports of damage were received from Jefferson County.  Several reports of trees and wires being blown down were received, and a confirmed EF-1 tornado occurred near Brockway before crossing into Elk County.', 'A ground survey was conducted and found the starting point at |Fermantown Road where three hardwood trees were knocked down. |The storm headed northeast to Coder Road where several homes had |trees fall on them. One house had a large tree limb pierce |through the ceiling. A large tractor was flipped over. This area had |the worst property damage of the entire path.  The tornado then crossed|into Elk County.');
INSERT INTO public.stormevents_east VALUES (781449, 201808, 31, 1815, 201808, 31, 1855, 130416, 'MARYLAND', 24, 2018, 'August', 'Flood', 'LWX', '31-AUG-18 18:15:00', 'EST-5', '31-AUG-18 18:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'SINGER', 1, 'NW', 'SINGER', 39.4964, -76.3478, 39.4906, -76.3472, 'Showers and thunderstorms developed around a stalled boundary. A slow storm motion combined with copious amounts of moisture led to heavy rain.', 'The stream gauge at Plumtree Run near Bel Air crested at 6.63 feet which is above flood stage of 6 feet. At this level, water flows over both Plumtree Road and Tollgate Road.');
INSERT INTO public.stormevents_east VALUES (775633, 201808, 12, 1549, 201808, 12, 1749, 129470, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '12-AUG-18 15:49:00', 'EST-5', '12-AUG-18 17:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'FALMOUTH', 0, 'NE', 'FALMOUTH', 38.3245, -77.4655, 38.3243, -77.466, 'A weak boundary remained overhead while an upper-level trough moved into the area. Warm and humid conditions led to an unstable atmosphere during this time. The unstable atmosphere combined with lift associated with the trough and the boundary to produce showers and thunderstorms. Locally heavy rain led to some flooding.', 'Forbes Street was closed due to flooding near Colonial Avenue.');
INSERT INTO public.stormevents_east VALUES (777986, 201808, 21, 1020, 201808, 21, 1220, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 10:20:00', 'EST-5', '21-AUG-18 12:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'BOSTON', 2, 'W', 'BOSTON', 38.5209, -78.1726, 38.5261, -78.1732, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Reva Road was closed due to flooding near Slate Mills Road.');
INSERT INTO public.stormevents_east VALUES (774928, 201808, 1, 403, 201808, 1, 603, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 04:03:00', 'EST-5', '01-AUG-18 06:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'WNW', 'LOCUSTGROVE', 2, 'WNW', 'LOCUSTGROVE', 38.31, -77.85, 38.3094, -77.8464, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-602 Old Office Road was closed over Mine Run Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (774930, 201808, 1, 418, 201808, 1, 618, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 04:18:00', 'EST-5', '01-AUG-18 06:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'NNE', 'WELLINGTON', 3, 'NNE', 'WELLINGTON', 38.82, -77.53, 38.8203, -77.525, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'VA-234 Sudley Road was closed at US-29 Lee Highway due to flooding over Youngs Branch.');
INSERT INTO public.stormevents_east VALUES (782760, 201808, 1, 735, 201808, 1, 820, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '01-AUG-18 07:35:00', 'EST-5', '01-AUG-18 08:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'ELKINS', 1, 'SSE', 'ELKINS', 38.9703, -77.268, 38.9719, -77.2662, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'The stream gauge at Great Falls along Difficult Run crested at 11.08 feet which is above the flood stage of 11 feet. At 11 feet, Leigh Mill Road floods near Difficult Run.');
INSERT INTO public.stormevents_east VALUES (782875, 201808, 1, 30, 201808, 1, 130, 129318, 'VIRGINIA', 51, 2018, 'August', 'Flash Flood', 'LWX', '01-AUG-18 00:30:00', 'EST-5', '01-AUG-18 01:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 3, 'SE', 'FARMINGTON', 3, 'SSE', 'FARMINGTON', 38.0188, -78.5196, 38.0112, -78.5187, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to flooding.', 'Ongoing flooding intensified to flash flooding along Moores Creek. A pedestrian bridge connecting Sunset Avenue and Sunset Avenue Extension was washed away. Water was reported to be four to five feet up on the outside of a home near the creek, and floodwaters pushed into Azalea Park, washing away parts of the playground and damaging fencing.');
INSERT INTO public.stormevents_east VALUES (775414, 201808, 3, 1930, 201808, 3, 2130, 129423, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '03-AUG-18 19:30:00', 'EST-5', '03-AUG-18 21:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'INLET', 1, 'ESE', 'INLET', 38.47, -77.91, 38.4703, -77.9065, 'A southerly flow pumped in plenty of moisture from the Atlantic while a slow moving cold front approached from the west. Copious amounts of moisture ahead of the boundary led to showers and thunderstorms. Torrential downpours combined with convection training over the same areas led to some flooding and flash flooding.', 'Glen Ella road was closed between Greens Corner Road and Bel Pre Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (759788, 201805, 15, 1405, 201805, 15, 1410, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:05:00', 'EST-5', '15-MAY-18 14:10:00', 0, 0, 0, 0, '100.00K', '0.00K', 'NWS Storm Survey', 96, 'EG', NULL, NULL, 1, 'NNE', 'WAYMART', 1, 'NE', 'HONESDALE', 41.5933, -75.4131, 41.5817, -75.2572, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Damage was first noted just northwest of Waymart, where several large branches were observed to have snapped in a thicket of mixed hardwood and softwood trees.  Trees continued to be either uprooted or snapped as the line continued moving eastward, with at least sporadic tree damage noted in a one mile wide swath along the damage path. Damage to barns was noted, with at least one poorly attached structure shifted in its entirety on its foundation.  Power poles were snapped, with additional damage done to the roof and/or facade of several buildings.  After producing damage at Prompton State |Park, the Honesdale Golf Club lost 30 trees during the storm.  However, the most |significant damage was noted at a cemetery in Honesdale, where nearly 75 trees |were estimated to have been lost near the end of the microburst.');
INSERT INTO public.stormevents_east VALUES (759787, 201805, 15, 1406, 201805, 15, 1406, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:06:00', 'EST-5', '15-MAY-18 14:06:00', 0, 0, 0, 0, '10.00K', '0.00K', 'State Official', 50, 'EG', NULL, NULL, 2, 'WNW', 'WEST SCRANTON', 2, 'WNW', 'WEST SCRANTON', 41.44, -75.72, 41.44, -75.72, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Thunderstorm winds blew trees down.');
INSERT INTO public.stormevents_east VALUES (759789, 201805, 15, 1410, 201805, 15, 1410, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Hail', 'BGM', '15-MAY-18 14:10:00', 'EST-5', '15-MAY-18 14:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 0, 'N', 'LEHMAN', 0, 'N', 'LEHMAN', 41.32, -76.03, 41.32, -76.03, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', NULL);
INSERT INTO public.stormevents_east VALUES (759790, 201805, 15, 1410, 201805, 15, 1410, 126735, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'BGM', '15-MAY-18 14:10:00', 'EST-5', '15-MAY-18 14:10:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'N', 'SWEET VLY', 0, 'N', 'SWEET VLY', 41.28, -76.15, 41.28, -76.15, 'An intense cold front move through central New York and northeast Pennsylvania during the afternoon of the 15th. This front produced a major squall line which eventually evolved into a derecho with estimated wind speeds of up to 115 mph in Wayne County, Pennsylvania. The derecho moved into Sullivan County, New York with winds just shy of 100 mph. Thousands of trees were snapped and uprooted along at least a 35 mile path with many homes damaged from falling trees and high winds.', 'Numerous trees blown down at Old Tavern Road along Hunlock  Creek.');
INSERT INTO public.stormevents_east VALUES (761122, 201805, 27, 1520, 201805, 27, 1520, 126994, 'MICHIGAN', 26, 2018, 'May', 'Hail', 'APX', '27-MAY-18 15:20:00', 'EST-5', '27-MAY-18 15:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 0, 'W', 'EAST TAWAS', 0, 'W', 'EAST TAWAS', 44.28, -83.49, 44.28, -83.49, 'Strong to severe thunderstorms developed along a cold front over northeast lower Michigan on the afternoon of the 27th. As opposed to the previous day, these storms produced mainly damaging winds, with one report of hail.', NULL);
INSERT INTO public.stormevents_east VALUES (761126, 201805, 27, 1441, 201805, 27, 1441, 126994, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'APX', '27-MAY-18 14:41:00', 'EST-5', '27-MAY-18 14:41:00', 1, 0, 1, 0, '15.00K', '0.00K', 'Law Enforcement', 52, 'EG', NULL, NULL, 2, 'N', 'PRESCOTT', 2, 'N', 'PRESCOTT', 44.21, -83.92, 44.21, -83.92, 'Strong to severe thunderstorms developed along a cold front over northeast lower Michigan on the afternoon of the 27th. As opposed to the previous day, these storms produced mainly damaging winds, with one report of hail.', 'A tree was downed onto an occupied vehicle on Sage Lake Road near Craun Road. The driver was killed, while a passenger suffered minor injuries.');
INSERT INTO public.stormevents_east VALUES (761206, 201805, 22, 1705, 201805, 22, 1705, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:05:00', 'EST-5', '22-MAY-18 17:05:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'GOSHEN', 1, 'SE', 'GOSHEN', 40.44, -81.41, 40.44, -81.41, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Emergency manager reported trees down along Route 416.');
INSERT INTO public.stormevents_east VALUES (761208, 201805, 22, 1707, 201805, 22, 1707, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:07:00', 'EST-5', '22-MAY-18 17:07:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SSE', 'SHOENBRUN', 1, 'SSE', 'SHOENBRUN', 40.45, -81.39, 40.45, -81.39, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Public citizen reported trees down just outside of Midvale.');
INSERT INTO public.stormevents_east VALUES (761209, 201805, 22, 1709, 201805, 22, 1709, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:09:00', 'EST-5', '22-MAY-18 17:09:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'BARNHILL', 1, 'W', 'BARNHILL', 40.45, -81.37, 40.45, -81.37, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Emergency manager reported a tree down along Barnhill Road.');
INSERT INTO public.stormevents_east VALUES (761210, 201805, 22, 1710, 201805, 22, 1710, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:10:00', 'EST-5', '22-MAY-18 17:10:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'ROANOKE', 1, 'N', 'ROANOKE', 40.43, -81.35, 40.43, -81.35, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Emergency manager reported trees down along Simpson Road.');
INSERT INTO public.stormevents_east VALUES (761212, 201805, 22, 1721, 201805, 22, 1721, 126724, 'OHIO', 39, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '22-MAY-18 17:21:00', 'EST-5', '22-MAY-18 17:21:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'FLAT RIDGE', 1, 'S', 'FLAT RIDGE', 40.12, -81.67, 40.12, -81.67, 'Despite the cloud morning, an approaching short wave trough, crossing during the afternoon and evening hours, helped spark showers and thunderstorms on the 22nd. A slow moving surface front became the focus for convection as the trough approached, with downdraft CAPE values near 800j/kg. Storms initially formed across northern Ohio and then moved southeast through eastern Ohio and western PA. The hardest hit areas where Tuscarawas county in Ohio and Hancock county in northern West Virginia.', 'Public citizen reported trees down on Township House Road.');
INSERT INTO public.stormevents_east VALUES (761444, 201805, 26, 1200, 201805, 26, 1300, 127056, 'TENNESSEE', 47, 2018, 'May', 'Flood', 'MRX', '26-MAY-18 12:00:00', 'EST-5', '26-MAY-18 13:00:00', 0, 0, 1, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'GRAY', 2, 'SW', 'GRAY', 36.4345, -82.47, 36.3995, -82.4954, 'Deep moisture encroached upon the area from the Gulf of Mexico, where subtropical storm Alberto was developing. Scattered mainly diurnal convection produced isolated flooding.', 'Toddler wandered into a swollen creek near the home and drowned.');
INSERT INTO public.stormevents_east VALUES (750803, 201805, 27, 618, 201805, 27, 618, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 06:18:00', 'EST-5', '27-MAY-18 06:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 42, 'MG', NULL, NULL, 4, 'N', 'SATELLITE BEACH', 4, 'N', 'SATELLITE BEACH', 28.23, -80.598, 28.23, -80.598, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'The AWOS at Patrick Air Force Base, KCOF, measured a peak wind gust of 42 knots from the southeast.');
INSERT INTO public.stormevents_east VALUES (750804, 201805, 27, 650, 201805, 27, 650, 125037, 'ATLANTIC SOUTH', 87, 2018, 'May', 'Marine Thunderstorm Wind', 'MLB', '27-MAY-18 06:50:00', 'EST-5', '27-MAY-18 06:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 37, 'MG', NULL, NULL, 7, 'NE', 'CAPE CANAVERAL', 7, 'NE', 'CAPE CANAVERAL', 28.4598, -80.5267, 28.4598, -80.5267, 'The Florida peninsula experienced strong south to southeast flow with Subtropical Storm Alberto far to the west and a strong high pressure over the western Atlantic. These south winds allowed deep tropical moisture from the Caribbean to move across the Florida peninsula. Some mid-level dry air wrapped itself around the eastern side of Alberto''s circulation, which decreased cloud cover across parts of central Florida allowing for daytime heating and instability to increase. Scattered showers and thunderstorms developed during the afternoon and moved towards the coast. Several of these storms produced strong winds along the intracoastal waters of Brevard and Indian River Counties.', 'US Air Force wind tower 0003 measured a peak wind gust of 37 knots from the south.');
INSERT INTO public.stormevents_east VALUES (777991, 201808, 21, 1300, 201808, 21, 1500, 129520, 'VIRGINIA', 51, 2018, 'August', 'Flood', 'LWX', '21-AUG-18 13:00:00', 'EST-5', '21-AUG-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'BULL RUN', 1, 'SE', 'BULL RUN', 38.82, -77.46, 38.819, -77.4634, 'Low pressure passed by to the west toward the Great Lakes. The warm front associated with the low moved through the area while the cold front associated with the low approached from the west. There was enough lift associated with the warm front to combine with a warm and humid atmosphere, resulting in showers and thunderstorms. Rainfall was heavy at times which resulted in flooding.', 'Compton Road was closed due to high water under Interstate 66.');
INSERT INTO public.stormevents_east VALUES (769421, 201806, 27, 1635, 201806, 27, 1635, 128292, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '27-JUN-18 16:35:00', 'EST-5', '27-JUN-18 16:35:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 4, 'W', 'CHATTERTON', 4, 'W', 'CHATTERTON', 31.51, -82.79, 31.51, -82.79, 'An old outflow boundary lingering over inland SE GA combined with additional low level forcing from the sea breezes and outflow boundaries over a moist and unstable airmass spawned a couple of severe storms in the afternoon and early evening.', 'Trees were blown down along Shiloh Road and New Forest Highway. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (769437, 201806, 27, 1905, 201806, 27, 1905, 128292, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'JAX', '27-JUN-18 19:05:00', 'EST-5', '27-JUN-18 19:05:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'MG', NULL, NULL, 4, 'SSE', 'BLADEN', 4, 'SSE', 'BLADEN', 31.2, -81.69, 31.2, -81.69, 'An old outflow boundary lingering over inland SE GA combined with additional low level forcing from the sea breezes and outflow boundaries over a moist and unstable airmass spawned a couple of severe storms in the afternoon and early evening.', 'A tree was blown along Highway 99. The time of damage was based on radar.');
INSERT INTO public.stormevents_east VALUES (769439, 201806, 27, 1925, 201806, 27, 1925, 128293, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '27-JUN-18 19:25:00', 'EST-5', '27-JUN-18 19:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 2, 'SE', 'CUMBERLAND STAFFORD', 2, 'SE', 'CUMBERLAND STAFFORD', 31.05, -81.41, 31.05, -81.41, 'An old outflow boundary lingering over inland SE GA combined with additional low level forcing from the sea breezes and outflow boundaries over a moist and unstable airmass spawned a couple of severe storms in the afternoon and early evening.', NULL);
