INSERT INTO public.stormevents_east VALUES (769462, 201806, 28, 1744, 201806, 28, 1744, 128303, 'FLORIDA', 12, 2018, 'June', 'Funnel Cloud', 'JAX', '28-JUN-18 17:44:00', 'EST-5', '28-JUN-18 17:44:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 2, 'WSW', 'ARREDONDA', 2, 'WSW', 'ARREDONDA', 29.59, -82.45, 29.59, -82.45, 'A passing upper level disturbance enhanced diurnally enhanced sea breeze convection over a moist and unstable airmass.', 'A funnel cloud was observed between Archer and I-75.');
INSERT INTO public.stormevents_east VALUES (757400, 201805, 15, 1700, 201805, 15, 1700, 126337, 'ATLANTIC NORTH', 88, 2018, 'May', 'Marine Thunderstorm Wind', 'OKX', '15-MAY-18 17:00:00', 'EST-5', '15-MAY-18 17:00:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 55, 'NE', 'STATION 44025', 55, 'NE', 'STATION 44025', 40.84, -72.48, 40.84, -72.48, 'An approaching cold front triggered numerous severe thunderstorms over southeastern New York. These storms produced 3 tornadoes in the Lower Hudson Valley, as well as microbursts and macroburts.', 'A 41 mile per hour gust was reported at Shinnecock mesonet.');
