INSERT INTO public.stormevents_east VALUES (766253, 201806, 2, 1712, 201806, 2, 1712, 127224, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '02-JUN-18 17:12:00', 'EST-5', '02-JUN-18 17:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', 43, 'MG', NULL, NULL, 1, 'W', 'MAYPORT NAS', 1, 'W', 'MAYPORT NAS', 30.4, -81.43, 30.4, -81.43, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'The NOAA Tide Gauge at Mayport measured a sustained wind of 31 mph with a gust to 49 mph.');
INSERT INTO public.stormevents_east VALUES (766254, 201806, 2, 1720, 201806, 2, 1720, 127224, 'ATLANTIC SOUTH', 87, 2018, 'June', 'Marine Thunderstorm Wind', 'JAX', '02-JUN-18 17:20:00', 'EST-5', '02-JUN-18 17:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 7, 'W', 'MAYPORT NAS', 7, 'W', 'MAYPORT NAS', 30.4, -81.53, 30.4, -81.53, 'Strong to severe storms develop in the afternoon and evening as a surface trough settled across SE Georgia over a moist and unstable airmass. Damaging down bursts caused extensive wind damage across SE Georgia and then across NE Florida into the evening. Storms moved offshore of the Atlantic coast in the evening.', 'Mesonet measured 43 mph at Blount Island.');
