INSERT INTO public.stormevents_east VALUES (760846, 201805, 13, 1932, 201805, 13, 1932, 126935, 'WEST VIRGINIA', 54, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 19:32:00', 'EST-5', '13-MAY-18 19:32:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'WNW', 'TRIADELPHIA', 1, 'WNW', 'TRIADELPHIA', 40.06, -80.64, 40.06, -80.64, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'State Department of Highways reported trees down on Peters Run Road.');
