INSERT INTO public.stormevents_east VALUES (760834, 201805, 13, 1615, 201805, 13, 1615, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 16:15:00', 'EST-5', '13-MAY-18 16:15:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'MORRISVILLE', 1, 'W', 'MORRISVILLE', 39.9, -80.19, 39.9, -80.19, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'Trees and power lines were reported down on social media. Time adjusted by radar.');
INSERT INTO public.stormevents_east VALUES (760835, 201805, 13, 1616, 201805, 13, 1616, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 16:16:00', 'EST-5', '13-MAY-18 16:16:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'RICES LNDG', 1, 'SW', 'RICES LNDG', 39.94, -80.01, 39.94, -80.01, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'Amateur radio operator reported trees down across Route 88. Road closed.');
INSERT INTO public.stormevents_east VALUES (760838, 201805, 13, 1527, 201805, 13, 1527, 126933, 'PENNSYLVANIA', 42, 2018, 'May', 'Thunderstorm Wind', 'PBZ', '13-MAY-18 15:27:00', 'EST-5', '13-MAY-18 15:27:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', 55, 'EG', NULL, NULL, 1, 'E', 'CLAYSVILLE', 1, 'E', 'CLAYSVILLE', 40.12, -80.4, 40.12, -80.4, 'Wavering boundary continued to pose problems on the afternoon of the 13th. Storms produced mainly wind damage.', 'Local 911 call center reported, in addition to trees down, multiple utility poles and high tension lines were down along State Route 40.');
INSERT INTO public.stormevents_east VALUES (759283, 201805, 23, 1250, 201805, 23, 1254, 126651, 'MAINE', 23, 2018, 'May', 'Thunderstorm Wind', 'GYX', '23-MAY-18 12:50:00', 'EST-5', '23-MAY-18 12:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'SHAWMUT', 1, 'NW', 'SHAWMUT', 44.63, -69.6, 44.63, -69.6, 'An approaching cold front was the trigger for showers and thunderstorms on the afternoon of May 23rd. A few isolated thunderstorms produced damaging winds as they moved through western Maine.', 'A severe thunderstorm downed trees on Route 23 in Shawmut.');
INSERT INTO public.stormevents_east VALUES (759286, 201805, 23, 1347, 201805, 23, 1351, 126651, 'MAINE', 23, 2018, 'May', 'Thunderstorm Wind', 'GYX', '23-MAY-18 13:47:00', 'EST-5', '23-MAY-18 13:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NE', 'CENTER MONTVILLE', 1, 'NE', 'CENTER MONTVILLE', 44.46, -69.24, 44.46, -69.24, 'An approaching cold front was the trigger for showers and thunderstorms on the afternoon of May 23rd. A few isolated thunderstorms produced damaging winds as they moved through western Maine.', 'A severe thunderstorm downed trees on North Mountain Valley Highway in Center Montville.');
INSERT INTO public.stormevents_east VALUES (787204, 201809, 17, 1615, 201809, 21, 100, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 16:15:00', 'EST-5', '21-SEP-18 01:00:00', 0, 0, 0, 0, '5.41M', '30.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'S', 'HASTY', 5, 'E', 'EAST LAURINBURG', 34.6322, -79.4627, 34.7733, -79.3308, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 15 to 20 inches caused widespread flooding across the county and throughout the Lumber River basin. Flooding damaged approximately 168 structures throughout the county, resulting in over $5.4 million in property damage and at least $30 million in crop damage. Numerous roads were flooded all throughout the county.');
INSERT INTO public.stormevents_east VALUES (789446, 201812, 16, 345, 201812, 16, 1656, 131950, 'OHIO', 39, 2018, 'December', 'Flood', 'RLX', '16-DEC-18 03:45:00', 'EST-5', '16-DEC-18 16:56:00', 0, 0, 0, 0, '2.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MACKSBURG', 1, 'NE', 'MACKSBURG', 39.6399, -81.471, 39.6433, -81.4556, 'A low pressure system moved through the central Appalachians on the 15th and 16th. This brought several waves of moderate to heavy rainfall, with total rain amounts in the 1.5 to 2 inch range. The cooperative observer at Marietta measured 1.52 inches of rain from the 14th through the 16th. The ground was already saturated from prior precipitation, so all of this rain was runoff, resulting in minor flooding.', 'Minor flooding occurred on the West Fork of Duck Creek. The stream gage at Macksburg showed the creek going over its 13 foot bankfull level very early on the 16th. It crested at 13.4 feet early that afternoon before returning to its banks late that afternoon.  This caused some high water in low spots along the creek.||The Little Muskingum River near Bloomfield also flooded. The gage near Bloomfield showed the river rising above its 16 foot bankfull level early on the 16th, cresting around 16.9 feet late that morning, and returning to its banks by mid afternoon. This caused flooding along Route 26 near its intersection with Route 260.');
INSERT INTO public.stormevents_east VALUES (791714, 201812, 2, 1250, 201812, 2, 1250, 132316, 'GEORGIA', 13, 2018, 'December', 'Lightning', 'JAX', '02-DEC-18 12:50:00', 'EST-5', '02-DEC-18 12:50:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, NULL, NULL, 1, 'SW', 'WAYCROSS', 1, 'SW', 'WAYCROSS', 31.21, -82.36, 31.21, -82.36, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'A lightning strike damaged a home along Carswell Avenue Tebeau Street in Waycross. The cost of damage was unknown, but it was estimated for the event to be included in Storm Data.');
INSERT INTO public.stormevents_east VALUES (772974, 201807, 16, 2020, 201807, 16, 2020, 128908, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '16-JUL-18 20:20:00', 'EST-5', '16-JUL-18 20:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 2, 'ESE', 'EAST HIGHLAND', 2, 'ESE', 'EAST HIGHLAND', 42.64, -83.53, 42.64, -83.53, 'Isolated severe thunderstorms developed over Oakland and St. Clair counties.', 'A trained spotter estimated a 60 mph thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (786319, 201809, 16, 2320, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '16-SEP-18 23:20:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'NNW', 'ALTAMAHAW', 1, 'SSE', 'PLEASANT GROVE', 36.1891, -79.5047, 36.1898, -79.3274, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Heavy rainfall of 4 to 8 inches flooded several roads across the county.');
INSERT INTO public.stormevents_east VALUES (788117, 201809, 18, 1654, 201809, 20, 35, 131752, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 16:54:00', 'EST-5', '20-SEP-18 00:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'MEYERSTOWN', 1, 'NNW', 'MILLVILLE', 39.2017, -77.8591, 39.3072, -77.7823, 'Heavy rain from the remnants of Florence caused flooding along the Shenandoah River.', 'The water level along the Shenandoah River at Milleville surpassed the flood stage of 10 feet, cresting at 13.5 feet on September 19th at 5:15 AM. ||Water reached the river access at Wagon Trail Place near Harpers Ferry, and completely covered the parking lot of the lower boat ramp at Millville Dam. Portions of the Cool Spring Battlefield were also flooded. ||A small portion of Wilt Road (County Road 9/8) was flooded. Water also flowed over Millville Dam.||Parts of Bloomery Road and John Rissler Road were flooded near Bloomery, West Virginia. Once these roads flood, access to homes is impaired. Moulton Park and the Millville boat launch were also flooded.');
INSERT INTO public.stormevents_east VALUES (788319, 201809, 18, 120, 201809, 18, 533, 131792, 'DISTRICT OF COLUMBIA', 11, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 01:20:00', 'EST-5', '18-SEP-18 05:33:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'WALTER REED', 1, 'SW', 'WALTER REED', 38.9712, -77.0429, 38.9722, -77.0403, 'Locally heavy rainfall caused Rock Creek to rise out of its banks on the 18th of September.', 'The water level surpassed the flood stage of 7 feet, and crested at 7.68 feet at 4:15 AM on September 18th. Water reaches several portions of the Valley Trail between Picnic Areas 7 and 10 in Rock Creek Park.');
INSERT INTO public.stormevents_east VALUES (788331, 201809, 9, 1453, 201809, 9, 2000, 131563, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 14:53:00', 'EST-5', '09-SEP-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'MARTINSBURG', 1, 'N', 'MARTINSBURG', 39.4696, -77.9719, 39.4703, -77.972, 'Heavy rain fell to the north of a stalled front on September 9th and 10th. One to three inches of rain fell across the eastern West Virginia Panhandle late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'The level along the Tuscarora Creek surpassed flood stage of 5.5 feet, cresting at 5.68 feet on September 9th at 4:00 PM. ||Widespread overflow of the banks of the creek occurred. Water reached the north parking lot of War Memorial Park.');
INSERT INTO public.stormevents_east VALUES (788324, 201809, 9, 400, 201809, 12, 557, 131563, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 04:00:00', 'EST-5', '12-SEP-18 05:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'SHEPHERDSTOWN', 2, 'NNE', 'MOLER XRDS', 39.44, -77.8, 39.4299, -77.7565, 'Heavy rain fell to the north of a stalled front on September 9th and 10th. One to three inches of rain fell across the eastern West Virginia Panhandle late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'The water level along the Potomac at Shepherdstown surpassed the flood stage of 15 feet, cresting at 21.79 feet on September 11th at 6:15 AM. ||Water approached homes on the West Virginia side of the river near Shepherdstown, and impacts were also observed on the Maryland side, not just to the C&O Canal towpath, but also to roads and structures. Water covered the pedestrian bridge adjacent to the Shepherdstown boat ramp. Significant portions of the C&O Canal towpath were flooded. Water flowed over the banks of the Potomac near the mouth of the Opequon River. River Road was completely flooded in low spots between Shepherdstown and Harpers Ferry. Significant portions of the C&O Canal towpath are flooded between McMahons Mill and Dam Number Four.');
INSERT INTO public.stormevents_east VALUES (796367, 201812, 20, 700, 201812, 21, 700, 133115, 'VIRGINIA', 51, 2018, 'December', 'Heavy Rain', 'RNK', '20-DEC-18 07:00:00', 'EST-5', '21-DEC-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'WNW', 'BIG ISLAND', 2, 'WNW', 'BIG ISLAND', 37.5443, -79.403, 37.5443, -79.403, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'The COOP station at Big Island (BGIV2) reported 2.76 inches of rain for the 24-hours ending at 700 AM local time which was the highest on record for December 21st. The old record was 2.29 inches in 1973. It was also the highest daily precipitation recorded in the month of December. The record was 2.35 inches set December 12, 2008. Climate records at this station exist from 1960-1985 and 2000 to present.');
INSERT INTO public.stormevents_east VALUES (772975, 201807, 16, 2015, 201807, 16, 2015, 128908, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '16-JUL-18 20:15:00', 'EST-5', '16-JUL-18 20:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 1, 'E', 'CLYDE', 1, 'E', 'CLYDE', 42.68, -83.6, 42.68, -83.6, 'Isolated severe thunderstorms developed over Oakland and St. Clair counties.', 'Multiple large tree limbs down.');
INSERT INTO public.stormevents_east VALUES (791987, 201812, 2, 242, 201812, 2, 242, 131758, 'GEORGIA', 13, 2018, 'December', 'Thunderstorm Wind', 'TAE', '02-DEC-18 02:42:00', 'EST-5', '02-DEC-18 02:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 65, 'EG', NULL, NULL, 4, 'SE', 'DOLES', 4, 'SE', 'DOLES', 31.66, -83.82, 31.66, -83.82, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'Trees were snapped north of Medders Road.');
INSERT INTO public.stormevents_east VALUES (772976, 201807, 16, 1525, 201807, 16, 1525, 128909, 'LAKE HURON', 90, 2018, 'July', 'Marine Thunderstorm Wind', 'DTX', '16-JUL-18 15:25:00', 'EST-5', '16-JUL-18 15:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'W', 'FORT GRATIOT WLON STATION (FTGM4)', 1, 'W', 'FORT GRATIOT WLON STATION (FTGM4)', 43.01, -82.43, 43.01, -82.43, 'A severe thunderstorm developed over Fort Gratoit.', 'A severe thunderstorm which brought down to trees moved into Lake Huron.');
INSERT INTO public.stormevents_east VALUES (744976, 201805, 2, 1949, 201805, 2, 1949, 124140, 'LAKE ERIE', 95, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '02-MAY-18 19:49:00', 'EST-5', '02-MAY-18 19:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 43, 'MG', NULL, NULL, 0, 'N', 'DETROIT RIVER LIGHT', 0, 'N', 'DETROIT RIVER LIGHT', 42, -83.14, 42, -83.14, 'A thunderstorm moving through Lake Erie produced a 43 knot wind gust.', NULL);
INSERT INTO public.stormevents_east VALUES (772977, 201807, 16, 1536, 201807, 16, 1536, 128909, 'LAKE HURON', 90, 2018, 'July', 'Marine Thunderstorm Wind', 'DTX', '16-JUL-18 15:36:00', 'EST-5', '16-JUL-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 51, 'MG', NULL, NULL, 1, 'W', 'FORT GRATIOT WLON STATION (FTGM4)', 1, 'W', 'FORT GRATIOT WLON STATION (FTGM4)', 43.01, -82.43, 43.01, -82.43, 'A severe thunderstorm developed over Fort Gratoit.', NULL);
INSERT INTO public.stormevents_east VALUES (772970, 201807, 16, 1505, 201807, 16, 1505, 128908, 'MICHIGAN', 26, 2018, 'July', 'Hail', 'DTX', '16-JUL-18 15:05:00', 'EST-5', '16-JUL-18 15:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.75, NULL, NULL, NULL, 1, 'NNW', 'ROSE CENTER', 1, 'NNW', 'ROSE CENTER', 42.75, -83.63, 42.75, -83.63, 'Isolated severe thunderstorms developed over Oakland and St. Clair counties.', NULL);
INSERT INTO public.stormevents_east VALUES (772971, 201807, 16, 1512, 201807, 16, 1512, 128908, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '16-JUL-18 15:12:00', 'EST-5', '16-JUL-18 15:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'SSE', 'ROSE CENTER', 1, 'SSE', 'ROSE CENTER', 42.71, -83.61, 42.71, -83.61, 'Isolated severe thunderstorms developed over Oakland and St. Clair counties.', 'A 20 inch diameter tree was reported blown down.');
INSERT INTO public.stormevents_east VALUES (744989, 201805, 4, 1225, 201805, 4, 1225, 124141, 'LAKE ST CLAIR', 81, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '04-MAY-18 12:25:00', 'EST-5', '04-MAY-18 12:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 48, 'MG', NULL, NULL, 1, 'S', 'METROPOLITAN BEACH', 1, 'S', 'METROPOLITAN BEACH', 42.57, -82.8, 42.57, -82.8, 'Thunderstorms moving through Lake St. Clair produced winds in excess of 45 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (744992, 201805, 4, 1235, 201805, 4, 1235, 124141, 'LAKE ST CLAIR', 81, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '04-MAY-18 12:35:00', 'EST-5', '04-MAY-18 12:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 43, 'MG', NULL, NULL, 2, 'SSW', 'GROSSE ILE', 2, 'SSW', 'GROSSE ILE', 42.1533, -83.185, 42.1533, -83.185, 'Thunderstorms moving through Lake St. Clair produced winds in excess of 45 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (778275, 201809, 26, 1619, 201809, 26, 1619, 129927, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:19:00', 'EST-5', '26-SEP-18 16:19:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'NORMAN', 1, 'N', 'NORMAN', 38.54, -78.07, 38.54, -78.07, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down near the intersection of Scotts Mill Road and Stone Bridge Road.');
INSERT INTO public.stormevents_east VALUES (790347, 201812, 20, 1420, 201812, 20, 1420, 132089, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'MLB', '20-DEC-18 14:20:00', 'EST-5', '20-DEC-18 14:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 50, 'MG', NULL, NULL, 2, 'SSE', 'PLAYALINDA BEACH', 2, 'SSE', 'PLAYALINDA BEACH', 28.53, -80.77, 28.53, -80.77, 'The Storm Prediction Center issued an Enhanced Risk of severe weather for most of east central Florida. A strengthening low pressure system was moving across the southeastern U.S. with a strong cold front extending southwest across the Gulf of Mexico. A potent jet stream moved towards Florida with winds of 125 knots (approximately 145 mph), at the same time a low-level jet situated along the cold front moved over the Florida peninsula with winds of 50-60 knots (55-70 mph). The rapid increase and turning of winds with height in the atmosphere led to very high shear and helicity values over Florida. Also, a surge of moisture and daytime heating led to an increase in instability over east central Florida that helped strong to severe storms develop. By early morning, a squall line of thunderstorms began to move onshore in west central Florida and quickly push east across the peninsula. As this line of showers and storms approached the east central Florida coastline, it produced numerous reports of strong to severe wind gusts from Volusia County south through Martin County.', 'US Air Force wind tower 1007 measured a peak wind gust of 50 knots from the west-southwest.');
INSERT INTO public.stormevents_east VALUES (790348, 201812, 20, 1435, 201812, 20, 1435, 132089, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'MLB', '20-DEC-18 14:35:00', 'EST-5', '20-DEC-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 48, 'MG', NULL, NULL, 6, 'N', 'CAPE CANAVERAL', 6, 'N', 'CAPE CANAVERAL', 28.46, -80.59, 28.46, -80.59, 'The Storm Prediction Center issued an Enhanced Risk of severe weather for most of east central Florida. A strengthening low pressure system was moving across the southeastern U.S. with a strong cold front extending southwest across the Gulf of Mexico. A potent jet stream moved towards Florida with winds of 125 knots (approximately 145 mph), at the same time a low-level jet situated along the cold front moved over the Florida peninsula with winds of 50-60 knots (55-70 mph). The rapid increase and turning of winds with height in the atmosphere led to very high shear and helicity values over Florida. Also, a surge of moisture and daytime heating led to an increase in instability over east central Florida that helped strong to severe storms develop. By early morning, a squall line of thunderstorms began to move onshore in west central Florida and quickly push east across the peninsula. As this line of showers and storms approached the east central Florida coastline, it produced numerous reports of strong to severe wind gusts from Volusia County south through Martin County.', 'US Air Force wind tower 403 measured a peak wind gust of 48 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (764382, 201806, 25, 1630, 201806, 25, 1635, 126788, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '25-JUN-18 16:30:00', 'EST-5', '25-JUN-18 16:35:00', 0, 0, 0, 0, '6.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'SSW', 'HOMER', 1, 'SSW', 'HOMER', 34.3203, -83.5043, 34.3203, -83.5043, 'A weak upper-level wave moving across the state resulted in widespread strong to severe thunderstorms across north and central Georgia.', 'The Banks County 911 center reported a large tree down on a home near the 200 block of Woodland Street near Homer. No significant damage or injuries reported.');
INSERT INTO public.stormevents_east VALUES (764393, 201806, 25, 1643, 201806, 25, 1648, 126788, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '25-JUN-18 16:43:00', 'EST-5', '25-JUN-18 16:48:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 45, 'EG', NULL, NULL, 0, 'W', 'ARCADE', 0, 'W', 'ARCADE', 34.0803, -83.5757, 34.0803, -83.5757, 'A weak upper-level wave moving across the state resulted in widespread strong to severe thunderstorms across north and central Georgia.', 'The Jackson County 911 center reported a tree blown down at the intersection of Highway 129 and Etheridge Road.');
INSERT INTO public.stormevents_east VALUES (764286, 201806, 22, 2030, 201806, 22, 2040, 126786, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '22-JUN-18 20:30:00', 'EST-5', '22-JUN-18 20:40:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NNW', 'FT VLY', 1, 'NNW', 'FT VLY', 32.5658, -83.8896, 32.5658, -83.8896, 'A deep, closed upper-level low over the center of the country resulted in widespread thunderstorms across north and central Georgia. Numerous reports of damaging thunderstorm winds were received.', 'The Peach County 911 center reported trees and power lines blown down on Magnolia Street in Fort Valley.');
INSERT INTO public.stormevents_east VALUES (760037, 201806, 2, 1815, 201806, 2, 1820, 126779, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '02-JUN-18 18:15:00', 'EST-5', '02-JUN-18 18:20:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 45, 'EG', NULL, NULL, 1, 'W', 'LOWERY', 1, 'W', 'LOWERY', 32.1989, -83.1376, 32.1989, -83.1376, 'A moderately unstable airmass over the region resulted in widespread thunderstorms during the afternoon and evening hours. A few storms along an old outflow boundary produced damaging wind gusts across portions of central Georgia.', 'The Houston County 911 center reported a tree blown down near the intersection of Bledsoe Road and Fred Bohannon Road.');
INSERT INTO public.stormevents_east VALUES (784959, 201809, 16, 1537, 201809, 16, 2030, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 15:37:00', 'EST-5', '16-SEP-18 20:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'SSE', 'MARION', 3, 'SE', 'MARION', 34.1399, -79.3799, 34.1483, -79.3667, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'US 501 closed due to dam overflow at Reedy Creek.');
INSERT INTO public.stormevents_east VALUES (786954, 201809, 28, 201, 201809, 28, 401, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:01:00', 'EST-5', '28-SEP-18 04:01:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KEYSER', 1, 'NNW', 'KEYSER', 39.4488, -78.9917, 39.4489, -78.9916, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'Carrol Avenue was closed at Villa Street due to high water.');
INSERT INTO public.stormevents_east VALUES (784855, 201809, 15, 1045, 201809, 15, 1047, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '15-SEP-18 10:45:00', 'EST-5', '15-SEP-18 10:47:00', 0, 0, 0, 0, '200.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SE', 'HAMPSTEAD', 2, 'SE', 'HAMPSTEAD', 34.3466, -77.6978, 34.351, -77.7045, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Tornado damage was observed in a half mile path starting in the |woods southeast of Great Oak Drive in the Deerfield community in|Hampstead NC. The EF-0 tornado moved across Great Oak Drive to East |Creek View Drive before it lifted over a tidal creek located |northwest of East Creek View Drive. The tornado mainly snapped |trees as it moved quickly toward the northwest. It flipped a boat |onto a car along East Creek View Drive and damaged a detached |garage. Before the tornado lifted it flipped a boat dock on the |tidal creek.');
INSERT INTO public.stormevents_east VALUES (784973, 201809, 16, 1540, 201809, 16, 2000, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 15:40:00', 'EST-5', '16-SEP-18 20:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'SSW', 'SOCIETY HILL', 2, 'SSW', 'SOCIETY HILL', 34.49, -79.87, 34.4964, -79.8655, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'South Main Street closed due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (784841, 201809, 15, 1816, 201809, 15, 1818, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '15-SEP-18 18:16:00', 'EST-5', '15-SEP-18 18:18:00', 0, 0, 0, 0, '300.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SSW', 'MURRAYSVILLE', 1, 'WSW', 'MURRAYSVILLE', 34.2912, -77.8335, 34.2932, -77.8437, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'An EF-1 tornado impacted the Brittany Lakes area of Murrayville near |Wilmington NC. Maximum winds were estimated at 95 mph. The tornado initially formed near Dove Field Ct and Brittany Lakes Rd. It moved into a wooded area causing dozens of trees to snap or become uprooted. Several of the trees were down|onto a few homes on the north side of Brittany Lakes Rd. The tornado moved toward the west-northwest, passing just south of the west end of Quail Woods Rd. The tornado caused additional tree damage just north of Creek Ridge Rd and lifted near Brittany Rd.');
INSERT INTO public.stormevents_east VALUES (776818, 201807, 21, 624, 201807, 21, 635, 128299, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'FFC', '21-JUL-18 06:24:00', 'EST-5', '21-JUL-18 06:35:00', 0, 0, 0, 0, '4.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'NNW', 'MADISON MUNI ARPT', 3, 'E', 'DICKSON', 33.6598, -83.4971, 33.577, -83.5544, 'A series of short waves moving through an unseasonably strong northwesterly upper-level flow pattern brought several rounds of strong to severe thunderstorms across north and central Georgia. The first round swept through in the early morning hours producing large swathes of wind damage and a few reports of small to moderate size hail. Heavy rainfall also produced isolated flash flooding in portions of north Georgia.', 'The Morgan County 911 center reported trees blown down from Bostwick Road and Sandy Creek Road north of Madison to around mile maker 108 on I-20 east of Madison.');
INSERT INTO public.stormevents_east VALUES (786948, 201809, 28, 336, 201809, 28, 536, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:36:00', 'EST-5', '28-SEP-18 05:36:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'WOODSTOCK', 2, 'NE', 'WOODSTOCK', 38.8961, -78.4934, 38.8961, -78.4931, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'The 22000 Block of Route 11 was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786949, 201809, 28, 358, 201809, 28, 558, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:58:00', 'EST-5', '28-SEP-18 05:58:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'CLARKS CROSSING', 0, 'W', 'CLARKS CROSSING', 38.9201, -77.3057, 38.9197, -77.3053, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'Lawyers Road was closed at Hunters Mill Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (786950, 201809, 28, 448, 201809, 28, 648, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 04:48:00', 'EST-5', '28-SEP-18 06:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BRISTOW', 1, 'N', 'BRISTOW', 38.7286, -77.5313, 38.7283, -77.5286, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'Traffic reports were received that indicated Piper Lane was closed between Observations Drive and Nokesville Road.');
INSERT INTO public.stormevents_east VALUES (786951, 201809, 28, 503, 201809, 28, 703, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 05:03:00', 'EST-5', '28-SEP-18 07:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LEESBURG MUNI', 1, 'S', 'LEESBURG MUNI', 39.0606, -77.5528, 39.0601, -77.5528, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'Shreve Mill Road was closed near Sycolin Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (786952, 201809, 28, 652, 201809, 28, 852, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 06:52:00', 'EST-5', '28-SEP-18 08:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'PHILOMONT', 1, 'SSE', 'PHILOMONT', 39.037, -77.7224, 39.0373, -77.7232, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'Snickersville Turnpike was closed due to flooding near Hibbs Bridge Road.');
INSERT INTO public.stormevents_east VALUES (773779, 201807, 31, 2315, 201807, 31, 2359, 127984, 'MICHIGAN', 26, 2018, 'July', 'Flash Flood', 'DTX', '31-JUL-18 23:15:00', 'EST-5', '31-JUL-18 23:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', '(DET)DETROIT CITY AR', 1, 'NE', 'LIVONIA', 42.42, -83.02, 42.394, -83.351, 'After an abnormally dry July across lower Michigan, a low pressure system lifted up from the Ohio Valley and moved through extreme southeastern Michigan and brought some much needed rainfall. Showers on the afternoon and evening of July 31 and became heavier into the nighttime hours. As the center of the low pressure interacted with the marine layer over western Lake Erie shortly after midnight, a brief tornado formed over Wayne County despite relatively weak winds aloft. Heavy rain bands and thunderstorm activity resulted in rainfall totals near 4 inches in several locations while many more areas around the Metro Detroit area received 1-3 inches, prompting a Flash Flood Warning for the urban areas as most of the rainfall occurred over a period of 3 hours or less. A couple feet of water were reported over roadways in Dearborn Heights and Taylor during the early morning hours.', 'Flash Flooding started just before midnight on July 31st and continued into August 1st.');
INSERT INTO public.stormevents_east VALUES (775293, 201809, 6, 1915, 201809, 6, 1915, 129394, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '06-SEP-18 19:15:00', 'EST-5', '06-SEP-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 52, 'EG', NULL, NULL, 1, 'W', '(MTN)MARTIN ARPT BAL', 1, 'W', '(MTN)MARTIN ARPT BAL', 39.32, -76.43, 39.32, -76.43, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which became severe.', 'A tree was blown down into an apartment building on Beech Drive.');
INSERT INTO public.stormevents_east VALUES (786404, 201809, 3, 1642, 201809, 3, 1647, 131436, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '03-SEP-18 16:42:00', 'EST-5', '03-SEP-18 16:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 4, 'W', 'ANDOVER', 4, 'W', 'ANDOVER', 44.64, -70.81, 44.64, -70.81, 'A cold front dropping south from Canada on the afternoon of September 3rd produced scattered convection as it moved south. Several storms became severe producing mainly wind damage.', 'A severe thunderstorm downed a tree on East B Hill Road in Andover.');
INSERT INTO public.stormevents_east VALUES (786441, 201809, 6, 1149, 201809, 6, 1154, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 11:49:00', 'EST-5', '06-SEP-18 11:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 60, 'MG', NULL, NULL, 1, 'NNW', 'PEMAQUID PT', 1, 'NNW', 'PEMAQUID PT', 43.8369, -69.506, 43.8369, -69.506, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm produced a measured gust of 56 knots at the Pemaquid Lighthouse.');
INSERT INTO public.stormevents_east VALUES (786420, 201809, 28, 240, 201809, 28, 440, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:40:00', 'EST-5', '28-SEP-18 04:40:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'ENE', 'PECKTONVILLE', 0, 'NE', 'PECKTONVILLE', 39.6735, -78.0431, 39.6737, -78.044, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The 13200 block of Pectonville Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786421, 201809, 28, 241, 201809, 28, 441, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:41:00', 'EST-5', '28-SEP-18 04:41:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'ASHTON', 1, 'SSE', 'ASHTON', 39.621, -77.9141, 39.6214, -77.9151, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'Ashton Road was closed at Gruber Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (782579, 201809, 18, 830, 201809, 18, 1200, 130779, 'NEW HAMPSHIRE', 33, 2018, 'September', 'Flash Flood', 'GYX', '18-SEP-18 08:30:00', 'EST-5', '18-SEP-18 12:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Local Official', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'RICHARDSON', 1, 'SSW', 'WILTON', 42.8374, -71.6677, 42.815, -71.7273, 'A moisture-laden area of low pressure produced 4 to 6 inches of rain in 6 hours in southern New Hampshire.', 'A moisture-laden area of low pressure produced 4 to 6 inches of rain in 6 hours flooding several streets in Milford. Wall, Alder, and Crosby Streets flooded. Mason Rd. near the Wilton town line was severed after a culvert washed away. Ox Brook came out of its bank flooding Melendy Rd.');
INSERT INTO public.stormevents_east VALUES (791411, 201812, 8, 1315, 201812, 8, 1320, 132221, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Waterspout', 'MFL', '08-DEC-18 13:15:00', 'EST-5', '08-DEC-18 13:20:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 11, 'NNE', 'PORT EVERGLADES', 11, 'NNE', 'PORT EVERGLADES', 26.26, -80.08, 26.26, -80.08, 'Showers developed over the local Atlantic waters through the morning and early afternoon hours ahead of a slow moving cold front across Central Florida. Two waterspouts developed with this activity off the coast of Palm Beach County; one in the morning and the other in the early afternoon.', 'Lifeguard and trained spotter reported a waterspout offshore the coast southeast of the Hillsboro Lighthouse. The waterpout lasted around 5 minutes from 115 PM to 120PM.');
INSERT INTO public.stormevents_east VALUES (787198, 201809, 17, 1615, 201809, 21, 100, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 16:15:00', 'EST-5', '21-SEP-18 01:00:00', 0, 0, 0, 0, '8.34M', '20.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'SSE', 'ADDOR', 6, 'ESE', 'MT PLEASANT', 35.043, -79.4588, 35.1796, -79.0607, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 10 to 15 inches caused widespread flooding across the county. Additional rainfall upstream resulted in major flooding along the Flat Creek near Vass. Flooding damaged approximately 418 structures throughout the county, destroying 29 and resulting in approximately $8.34 million in property damage. Crop damage was at least $20 million. Numerous streets and roads were reported flooded.');
INSERT INTO public.stormevents_east VALUES (798203, 201812, 21, 1600, 201812, 21, 2100, 133401, 'NORTH CAROLINA', 37, 2018, 'December', 'Flood', 'GSP', '21-DEC-18 16:00:00', 'EST-5', '21-DEC-18 21:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'E', 'JOY', 2, 'ESE', 'JOY', 35.887, -81.725, 35.863, -81.742, 'Moderate to heavy rain developed across western North Carolina in association with a slow-moving warm front on the 20th and continued into the 21st. Localized minor flooding developed on a couple of streams in the Piedmont and foothills.', 'A stream gauge on the Johns River north of Morganton exceeded its established flood stage after 2 to 3 inches of rain fell in throughout the basin in about a 24 hour period. Flooded roads included Johns River Loop Rd, Old Johns River Rd, and Valley View Cir.');
INSERT INTO public.stormevents_east VALUES (798206, 201812, 21, 900, 201812, 21, 1300, 133402, 'SOUTH CAROLINA', 45, 2018, 'December', 'Flood', 'GSP', '21-DEC-18 09:00:00', 'EST-5', '21-DEC-18 13:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'S', 'CAMPOBELLO ARPT', 1, 'NNE', 'ARLINGTON', 35.039, -82.22, 34.979, -82.196, 'Moderate to heavy rain developed across Upstate South Carolina in association with a slow-moving warm front on the 20th and continued into the 21st. Localized minor flooding developed on a foothills stream.', 'A stream gauge on the Middle Tyger River in the Gramling community exceeded its established flood stage after around 2 to 3 inches of rain fell throughout the basin in about a 24 hour period. Portions of Mount Lebanon Church Rd were flooded as were a few roads in the Lake Lyman area.');
INSERT INTO public.stormevents_east VALUES (791410, 201812, 8, 1033, 201812, 8, 1033, 132221, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Waterspout', 'MFL', '08-DEC-18 10:33:00', 'EST-5', '08-DEC-18 10:33:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', NULL, NULL, NULL, NULL, 7, 'ESE', 'BOCA RATON', 7, 'ESE', 'BOCA RATON', 26.3, -79.97, 26.3, -79.97, 'Showers developed over the local Atlantic waters through the morning and early afternoon hours ahead of a slow moving cold front across Central Florida. Two waterspouts developed with this activity off the coast of Palm Beach County; one in the morning and the other in the early afternoon.', 'Photo received via social media from a trained spotter shows a waterspout east of Boca Raton moving towards shore. The waterspout dissipated before the associated shower reached shower.');
INSERT INTO public.stormevents_east VALUES (787196, 201809, 9, 1356, 201809, 9, 1556, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 13:56:00', 'EST-5', '09-SEP-18 15:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'JEROME', 1, 'ESE', 'JEROME', 38.8613, -78.7139, 38.8628, -78.7052, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-611 Supinlick Ridge road was closed due to flooding between VA-717 Liberty Furnace Road and VA-701 Dellinger Gap Road.');
INSERT INTO public.stormevents_east VALUES (791413, 201812, 13, 829, 201812, 13, 829, 132222, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Waterspout', 'MFL', '13-DEC-18 08:29:00', 'EST-5', '13-DEC-18 08:29:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', NULL, NULL, NULL, NULL, 3, 'ENE', 'PORT OF PALM BEACH', 3, 'ENE', 'PORT OF PALM BEACH', 26.77, -80.02, 26.77, -80.02, 'Breezy southeast flow helped light showers develop over the local Atlantic waters during the day, primarily offshore the coast of Palm Beach County. A brief waterspouts developed during the morning hours with this activity.', 'Photos relayed via WBPF in West Palm Beach show a waterspout associated with a shower offshore Palm Beach.');
INSERT INTO public.stormevents_east VALUES (791416, 201812, 20, 2053, 201812, 20, 2053, 132223, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Waterspout', 'MFL', '20-DEC-18 20:53:00', 'EST-5', '20-DEC-18 20:53:00', 0, 0, 0, 0, NULL, NULL, 'Airplane Pilot', NULL, NULL, NULL, NULL, 22, 'E', 'MIAMI BEACH', 22, 'E', 'MIAMI BEACH', 25.78, -79.76, 25.78, -79.76, 'A pre-frontal band of showers and storms moved across South Florida during the afternoon hours. Gusty winds accompanied this band as it moved through the region, with the strongest gust across Lake Okeechobee in the early afternoon. A waterspout was reported with this activity as it moved into the local Atlantic waters.', 'Pilot from Boeing 737 offshore Miami International Airport reported a waterspout over the Atlantic Ocean.');
INSERT INTO public.stormevents_east VALUES (791718, 201812, 2, 1440, 201812, 2, 1449, 132316, 'GEORGIA', 13, 2018, 'December', 'Tornado', 'JAX', '02-DEC-18 14:40:00', 'EST-5', '02-DEC-18 14:49:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 4, 'W', 'PYLES MARSH', 3, 'W', 'PYLES MARSH', 31.13, -81.56, 31.13, -81.55, 'A lifting warm front, very saturated airmass and strong upper level dynamics ahead of a cold front created a couple waves of localized heavy rainfall across the local area from Dec. 1-2nd. A pre-frontal squall line with embedded supercell storms crossed the area during the afternoon of Dec. 2nd which triggered a few weak tornadoes.', 'National Weather Service Jacksonville Storm survey|revealed damage consistent with EF-1 tornado damage in Royal Drive|Subdivision east of I-95 and south of Jekyll Island Causeway in|Glynn County. A combination of waterspout and tornado likely|formed near I-95 on a section of the Little Satilla River before |causing damage within the subdivision. A couple dozen trees were |damaged with several snapped at the trunk. A Doppler Radar debris |signature was evident between 3-5,000 feet indicating lofted |tornado debris. The tornado damage concludes on the south side of|the Jekyll Island Causeway. The survey team was unable to find|damage west of I-95 so the start point given is where damage to |trees and docks began, however, it is possible that the tornado |started on the Little Satilla River farther west.');
INSERT INTO public.stormevents_east VALUES (787194, 201809, 9, 417, 201809, 9, 617, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 04:17:00', 'EST-5', '09-SEP-18 06:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'MT SOLON', 1, 'WSW', 'MT SOLON', 38.3459, -79.1094, 38.345, -79.1066, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-758 George Waltons Road was closed due to flooding between VA-730 North River Road and VA-747 Free Mason Road.');
INSERT INTO public.stormevents_east VALUES (787195, 201809, 9, 1248, 201809, 9, 1448, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 12:48:00', 'EST-5', '09-SEP-18 14:48:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'CLARKS CROSSING', 1, 'WNW', 'CLARKS CROSSING', 38.9237, -77.3146, 38.9249, -77.3124, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'Lawyers Road was shut down near Hunter Mill Road due to high water.');
INSERT INTO public.stormevents_east VALUES (787268, 201809, 9, 1357, 201809, 9, 1557, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 13:57:00', 'EST-5', '09-SEP-18 15:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'ARMEL', 1, 'ESE', 'ARMEL', 39.0674, -78.1203, 39.0769, -78.1411, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-646 Nations Spring Road was closed due to flooding between VA-644 and US-522.');
INSERT INTO public.stormevents_east VALUES (787269, 201809, 9, 1442, 201809, 9, 1642, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 14:42:00', 'EST-5', '09-SEP-18 16:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LEESBURG MUNI', 1, 'S', 'LEESBURG MUNI', 39.0601, -77.5524, 39.06, -77.5514, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-653 Shreve Mill Road was closed due to flooding at VA-643 Sycolin Road.');
INSERT INTO public.stormevents_east VALUES (787270, 201809, 9, 1450, 201809, 9, 1650, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 14:50:00', 'EST-5', '09-SEP-18 16:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'VALE', 2, 'NNW', 'VALE', 38.91, -77.36, 38.9099, -77.3627, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'Fox Mill Road near Shady Mill Lane was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (786813, 201809, 27, 1736, 201809, 27, 1738, 131522, 'SOUTH CAROLINA', 45, 2018, 'September', 'Thunderstorm Wind', 'ILM', '27-SEP-18 17:36:00', 'EST-5', '27-SEP-18 17:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Utility Company', 52, 'EG', NULL, NULL, 4, 'N', 'WINDY HILL', 4, 'N', 'WINDY HILL', 34.25, -79.72, 34.25, -79.72, 'A stationary front produced strong storms in South Carolina.', 'Duke Energy reported a power outage due to fallen trees.  Thirteen customers were affected.');
INSERT INTO public.stormevents_east VALUES (796376, 201812, 20, 700, 201812, 21, 700, 133115, 'VIRGINIA', 51, 2018, 'December', 'Heavy Rain', 'RNK', '20-DEC-18 07:00:00', 'EST-5', '21-DEC-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'N', 'HURT', 2, 'N', 'HURT', 37.1122, -79.275, 37.1122, -79.275, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'The COOP station at Altavista (ALTV2) reported 2.16 inches of rain for the 24-hours ending at 700 AM local time which was the highest on record for December 21st. The old record was 2.10 inches in 1973. It was also the 3rd highest daily precipitation recorded in the month of December. The record is 3.40 inches set December 29, 1958. Climate records at this station date back to 1945.');
INSERT INTO public.stormevents_east VALUES (796374, 201812, 20, 700, 201812, 21, 700, 133115, 'VIRGINIA', 51, 2018, 'December', 'Heavy Rain', 'RNK', '20-DEC-18 07:00:00', 'EST-5', '21-DEC-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 2, 'N', 'MARTINSVILLE', 2, 'N', 'MARTINSVILLE', 36.7056, -79.865, 36.7056, -79.865, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'The COOP station at Martinsville (MARV2) reported 2.48 inches for the 24-hours ending at 700 AM local time which was the highest on record for December 21st. The old record was 2.00 inches set in 1973. It was also the 2nd highest daily precipitation recorded in the month of December. The record is 2.57 inches set December 28, 1958. Nearly complete climate records at this station exist since 1930.');
INSERT INTO public.stormevents_east VALUES (791989, 201812, 2, 515, 201812, 2, 515, 131758, 'GEORGIA', 13, 2018, 'December', 'Thunderstorm Wind', 'TAE', '02-DEC-18 05:15:00', 'EST-5', '02-DEC-18 05:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'DOLES', 0, 'N', 'DOLES', 31.7, -83.88, 31.7, -83.88, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'A couple of trees were blown down.');
INSERT INTO public.stormevents_east VALUES (773315, 201807, 26, 1218, 201807, 26, 1218, 128910, 'MICHIGAN', 26, 2018, 'July', 'Hail', 'DTX', '26-JUL-18 12:18:00', 'EST-5', '26-JUL-18 12:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 0.75, NULL, NULL, NULL, 1, 'W', 'PITTSFIELD', 1, 'W', 'PITTSFIELD', 42.2, -83.73, 42.2, -83.73, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', NULL);
INSERT INTO public.stormevents_east VALUES (773316, 201807, 26, 1225, 201807, 26, 1225, 128910, 'MICHIGAN', 26, 2018, 'July', 'Hail', 'DTX', '26-JUL-18 12:25:00', 'EST-5', '26-JUL-18 12:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 0.88, NULL, NULL, NULL, 1, 'NW', 'PAINT CREEK', 1, 'NW', 'PAINT CREEK', 42.16, -83.6, 42.16, -83.6, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', NULL);
INSERT INTO public.stormevents_east VALUES (773317, 201807, 26, 1232, 201807, 26, 1232, 128910, 'MICHIGAN', 26, 2018, 'July', 'Hail', 'DTX', '26-JUL-18 12:32:00', 'EST-5', '26-JUL-18 12:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 1, NULL, NULL, NULL, 1, 'W', 'BELLEVILLE', 1, 'W', 'BELLEVILLE', 42.2, -83.48, 42.2, -83.48, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', NULL);
INSERT INTO public.stormevents_east VALUES (773319, 201807, 26, 1225, 201807, 26, 1225, 128910, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '26-JUL-18 12:25:00', 'EST-5', '26-JUL-18 12:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 52, 'EG', NULL, NULL, 2, 'WNW', 'YPSILANTI MCENNAN FL', 2, 'WNW', 'YPSILANTI MCENNAN FL', 42.21, -83.66, 42.21, -83.66, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', 'A large tree was reported blown down.');
INSERT INTO public.stormevents_east VALUES (773320, 201807, 26, 1228, 201807, 26, 1228, 128910, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '26-JUL-18 12:28:00', 'EST-5', '26-JUL-18 12:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 2, 'SSW', 'RAWSONVILLE', 2, 'SSW', 'RAWSONVILLE', 42.19, -83.56, 42.19, -83.56, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', 'A large evergreen tree was reported blown down.');
INSERT INTO public.stormevents_east VALUES (790355, 201812, 20, 1605, 201812, 20, 1605, 132088, 'FLORIDA', 12, 2018, 'December', 'Thunderstorm Wind', 'MLB', '20-DEC-18 16:05:00', 'EST-5', '20-DEC-18 16:05:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', 43, 'EG', NULL, NULL, 1, 'S', 'STUART', 1, 'S', 'STUART', 27.19, -80.25, 27.19, -80.25, 'The Storm Prediction Center issued an Enhanced Risk of severe weather for most of east central Florida. A strengthening low pressure system was moving across the southeastern U.S. with a strong cold front extending southwest across the Gulf of Mexico. A potent jet stream moved towards Florida with winds of  145 mph, at the same time a low-level jet situated along the cold front moved over the Florida peninsula with winds of 55-70 mph. The rapid increase and turning of winds with height in the atmosphere led to very high wind shear over Florida. Also, a surge of moisture and daytime heating led to an increase in instability over east central Florida that aided strong to severe thunderstorm development. By early morning, a squall line of thunderstorms began to move onshore in west central Florida and quickly push east across the peninsula. A severe thunderstorm embedded within the line caused damage to a home in Leesburg. In the early afternoon, as the line approached the Brevard County coast, a couple of severe wind gusts were reported west of Cape Canaveral. Lastly, during the late afternoon strong winds caused a tree to fall over onto a shed in Stuart.', 'A member of the public reported a medium-sized tree had fallen over onto a shed in Stuart, one mile west-northwest of Stuart Witham Airport.');
INSERT INTO public.stormevents_east VALUES (790568, 201812, 20, 1051, 201812, 20, 1051, 132119, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine Thunderstorm Wind', 'TBW', '20-DEC-18 10:51:00', 'EST-5', '20-DEC-18 10:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 40, 'EG', NULL, NULL, 1, 'S', 'LOWER TAMPA BAY', 1, 'S', 'LOWER TAMPA BAY', 27.6, -82.65, 27.6, -82.65, 'A squall line developed ahead of a strong cold front and pushed southeast through the west coast of the Florida Peninsula, producing widespread thunderstorm wind gusts along the coast.', 'The WeatherFlow station on the Sunshine Skyway Fishing Pier (XSKY) recorded a 40 knot thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (786411, 201809, 3, 1818, 201809, 3, 1823, 131436, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '03-SEP-18 18:18:00', 'EST-5', '03-SEP-18 18:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 1, 'WSW', 'LEWISTON', 1, 'WSW', 'LEWISTON', 44.0986, -70.2098, 44.0986, -70.2098, 'A cold front dropping south from Canada on the afternoon of September 3rd produced scattered convection as it moved south. Several storms became severe producing mainly wind damage.', 'A severe thunderstorm downed a tree in a yard in Lewiston.');
INSERT INTO public.stormevents_east VALUES (744982, 201805, 4, 1226, 201805, 4, 1226, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:26:00', 'EST-5', '04-MAY-18 12:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Newspaper', 54, 'EG', NULL, NULL, 1, 'W', 'TEMPERANCE', 1, 'W', 'TEMPERANCE', 41.78, -83.59, 41.78, -83.59, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'A large tree was reported down.');
INSERT INTO public.stormevents_east VALUES (764401, 201806, 25, 1835, 201806, 25, 1855, 126788, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '25-JUN-18 18:35:00', 'EST-5', '25-JUN-18 18:55:00', 0, 0, 0, 0, '20.00K', NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 2, 'NNE', 'CONDOR', 4, 'SSE', 'KEENES CROSSING', 32.55, -82.82, 32.5286, -82.6967, 'A weak upper-level wave moving across the state resulted in widespread strong to severe thunderstorms across north and central Georgia.', 'The Laurens County Emergency Manager reported thunderstorm wind damage across the eastern portion of the county from East Dublin to west of Adrian. Part of a roof was removed from a parsonage along Dewey Warnock Road where an irrigation system was also overturned and several trees were blown down. Several more trees were blown down around the intersection of Highway 86 and Orianna Road.');
INSERT INTO public.stormevents_east VALUES (788336, 201809, 17, 822, 201809, 17, 1930, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 08:22:00', 'EST-5', '17-SEP-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'WAYNESBORO ARPT', 2, 'SE', 'WAYNESBORO ARPT', 38.06, -78.9, 38.061, -78.8993, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The water level at Waynesboro near Rife Road surpassed flood stage of 10.5 feet, cresting at 13.14 feet on September 17th at 12:45 PM.');
INSERT INTO public.stormevents_east VALUES (788322, 201809, 18, 23, 201809, 18, 2251, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 00:23:00', 'EST-5', '18-SEP-18 22:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'LEAKSVILLE', 1, 'NE', 'LEAKSVILLE', 38.6332, -78.5425, 38.6374, -78.5188, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Water level at the gauge along the South Fork Shenandoah River at Luray surpassed flood stage of 14 feet. The water crested at 17.63 feet at 10:15 AM ES, September 18th. ||Water covered the entire parking area at the Bixlers Ferry boat launch. Portions of Kaufmann Mill Road, Ganders Drive, and Egypt Bend Road were flooded. Water covered yards and fields near the river southwest of Luray.');
INSERT INTO public.stormevents_east VALUES (786449, 201809, 28, 609, 201809, 28, 809, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 06:09:00', 'EST-5', '28-SEP-18 08:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BRIGHTON', 0, 'SSE', 'BRIGHTON', 39.1931, -77.0246, 39.1934, -77.0267, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The EM reported Brighton Dam Road closed due to flooding near New Hampshire Avenue.');
INSERT INTO public.stormevents_east VALUES (786406, 201809, 3, 1705, 201809, 3, 1710, 131436, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '03-SEP-18 17:05:00', 'EST-5', '03-SEP-18 17:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'E', 'NEWRY', 2, 'E', 'NEWRY', 44.48, -70.74, 44.48, -70.74, 'A cold front dropping south from Canada on the afternoon of September 3rd produced scattered convection as it moved south. Several storms became severe producing mainly wind damage.', 'A severe thunderstorm downed a tree on wires on Intervale Road in Bethel.');
INSERT INTO public.stormevents_east VALUES (786508, 201809, 15, 1921, 201809, 15, 2300, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 19:21:00', 'EST-5', '15-SEP-18 23:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'NE', 'HALLSBORO', 1, 'N', 'HALLSBORO', 34.33, -78.59, 34.3342, -78.6002, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Hwy 74 was closed in both directions east of Halsboro Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (786509, 201809, 15, 1700, 201809, 15, 2100, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 17:00:00', 'EST-5', '15-SEP-18 21:00:00', 0, 0, 0, 0, '40.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Ice Jam', NULL, 0, 'N', 'WHITEVILLE', 0, 'WSW', 'WHITEVILLE', 34.33, -78.7, 34.3289, -78.704, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'There were 50 water related rescues in the city of Whiteville.');
INSERT INTO public.stormevents_east VALUES (784975, 201809, 16, 200, 201809, 16, 200, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 02:00:00', 'EST-5', '16-SEP-18 02:00:00', 0, 0, 1, 0, '20.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'N', 'PLANTERSVILLE', 0, 'N', 'PLANTERSVILLE', 33.56, -79.22, 33.5547, -79.2197, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'A person accidentally drove into a flooded area and drowned.');
INSERT INTO public.stormevents_east VALUES (784684, 201809, 17, 836, 201809, 17, 1850, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 08:36:00', 'EST-5', '17-SEP-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'WAYNESBORO ARPT', 2, 'SE', 'WAYNESBORO ARPT', 38.06, -78.91, 38.0595, -78.9104, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The water level surpassed flood stage of 9.5 feet, cresting at 11.92 feet on September 17th at noon. Portions of the Club Court neighborhood was flooded.');
INSERT INTO public.stormevents_east VALUES (788334, 201809, 18, 144, 201809, 18, 330, 131153, 'MARYLAND', 24, 2018, 'September', 'Flash Flood', 'LWX', '18-SEP-18 01:44:00', 'EST-5', '18-SEP-18 03:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'WHITE MARSH', 1, 'WSW', 'WHITE MARSH', 39.3736, -76.4535, 39.3742, -76.4523, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The water level at Whitemarsh Run rapidly surpassed flood stage of 11 feet, cresting at 12.97 feet at 2:15 AM  EST on the 18th of September. Town Center Court was flooded, and water covered the parking lots near the stream.');
INSERT INTO public.stormevents_east VALUES (788332, 201809, 17, 1015, 201809, 17, 1638, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 10:15:00', 'EST-5', '17-SEP-18 16:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'ROSELAND', 2, 'NNW', 'COLLEEN', 37.72, -78.98, 37.7216, -78.9645, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The water level on the Tye River in Lovingston surpassed flood stage of 13 feet, cresting at 15.6 feet on September 17th at 12:45 PM. Roseland Road was flooded. Agricultural fields near the river were flooded.');
INSERT INTO public.stormevents_east VALUES (786409, 201809, 3, 1742, 201809, 3, 1747, 131436, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '03-SEP-18 17:42:00', 'EST-5', '03-SEP-18 17:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'N', 'NORWAY', 1, 'N', 'NORWAY', 44.23, -70.53, 44.23, -70.53, 'A cold front dropping south from Canada on the afternoon of September 3rd produced scattered convection as it moved south. Several storms became severe producing mainly wind damage.', 'A severe thunderstorm downed trees and wires on Nichol Street in Paris.');
INSERT INTO public.stormevents_east VALUES (786491, 201809, 15, 1350, 201809, 15, 1830, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 13:50:00', 'EST-5', '15-SEP-18 18:30:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'NE', 'RAYNHAM', 1, 'NE', 'RAYNHAM', 34.58, -79.17, 34.5815, -79.1696, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Davis Road near Hwy 301 was impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (786492, 201809, 15, 1416, 201809, 15, 1900, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 14:16:00', 'EST-5', '15-SEP-18 19:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 4, 'SSE', 'RED SPGS', 1, 'NE', 'PHILDELPHUS', 34.7665, -79.153, 34.7587, -79.1577, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Hwy 72 was closed in both directions near Lewis McNeill Road. Flooding on Hwy 72 was also reported near Philadelphus Road, and Pine Log Road.');
INSERT INTO public.stormevents_east VALUES (786498, 201809, 15, 1701, 201809, 15, 2100, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 17:01:00', 'EST-5', '15-SEP-18 21:00:00', 0, 0, 1, 0, '10.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'NNE', 'LUMBERTON', 1, 'NNE', 'LUMBERTON', 34.6334, -78.9933, 34.6318, -78.9945, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'The Swiftwater Rescue Team was called to Tartan Road with waist deep water. A female drove into a road that was washed out and drowned.');
INSERT INTO public.stormevents_east VALUES (784865, 201809, 16, 1659, 201809, 16, 1701, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Tornado', 'ILM', '16-SEP-18 16:59:00', 'EST-5', '16-SEP-18 17:01:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SE', 'OAKLAND XRDS', 1, 'SE', 'OAKLAND XRDS', 34.5073, -79.3487, 34.517, -79.3529, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'A tornado broke large limbs out of the tops of trees on the east |side of Blue Moon Drive. It moved north across open field, then |broke additional limbs from trees before crossing Harlees Bridge|Road. Several small pine trees were snapped along the north side|of Harlees Bridge Road.');
INSERT INTO public.stormevents_east VALUES (787003, 201809, 28, 105, 201809, 28, 921, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 01:05:00', 'EST-5', '28-SEP-18 09:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'PEARRE', 2, 'NNW', 'PEARRE', 39.6539, -78.343, 39.6532, -78.3393, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The USGS stream gage on Sideling Hill Creek near Bellegrove exceeded the 7.5 foot flood stage during the indicated period, flooding lowlands and farmlands near the creek. The peak level of 8.76 feet occurred at 4:15am EST.');
INSERT INTO public.stormevents_east VALUES (787045, 201809, 29, 100, 201809, 30, 854, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '29-SEP-18 01:00:00', 'EST-5', '30-SEP-18 08:54:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'KENWOOD', 0, 'N', 'KENWOOD', 38.9498, -77.1265, 38.9553, -77.1299, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The USGS stream gage on the Potomac River near Little Falls Dam exceeded the 10 foot flood stage during the indicated period, flooding lowlands and trails near the C&O Canal. The peak level of 11.01 feet occurred at 4:45pm EST on the 29th.');
INSERT INTO public.stormevents_east VALUES (785924, 201809, 18, 100, 201809, 18, 300, 131153, 'MARYLAND', 24, 2018, 'September', 'Flash Flood', 'LWX', '18-SEP-18 01:00:00', 'EST-5', '18-SEP-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'BALTIMORE HIGHLANDS', 1, 'N', 'BALTIMORE HIGHLANDS', 39.2448, -76.6488, 39.2447, -76.6482, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Three feet of swift moving water was moving over Hollins Ferry Road near Landsdowne Road.');
INSERT INTO public.stormevents_east VALUES (785931, 201809, 18, 119, 201809, 18, 319, 131153, 'MARYLAND', 24, 2018, 'September', 'Flash Flood', 'LWX', '18-SEP-18 01:19:00', 'EST-5', '18-SEP-18 03:19:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'LINHIGH', 1, 'NNW', 'LINHIGH', 39.3794, -76.5037, 39.3789, -76.5024, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Hill is being washed down the roadway on MD43 at US Route 1.');
INSERT INTO public.stormevents_east VALUES (785934, 201809, 18, 125, 201809, 18, 325, 131153, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 01:25:00', 'EST-5', '18-SEP-18 03:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'WHITE OAK', 1, 'NNE', 'WHITE OAK', 39.0437, -76.9917, 39.0429, -76.9912, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'All lanes of MD-650 New Hampshire Avenue were blocked by high water at US-29 Colesville Road.');
INSERT INTO public.stormevents_east VALUES (785935, 201809, 18, 130, 201809, 18, 330, 131153, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 01:30:00', 'EST-5', '18-SEP-18 03:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'STEMMERS RUN', 1, 'NW', 'STEMMERS RUN', 39.3377, -76.4838, 39.3375, -76.4828, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'A vehicle was stranded in high water in Golden Ring Plaza.');
INSERT INTO public.stormevents_east VALUES (776862, 201807, 21, 2010, 201807, 21, 2020, 129691, 'GEORGIA', 13, 2018, 'July', 'Hail', 'FFC', '21-JUL-18 20:10:00', 'EST-5', '21-JUL-18 20:20:00', 0, 0, 0, 0, NULL, NULL, 'Local Official', 1.5, NULL, NULL, NULL, 2, 'NW', 'DUNLAP', 2, 'NW', 'DUNLAP', 33.97, -83.26, 33.97, -83.26, 'A series of short waves moving through an unseasonably strong northwesterly upper-level flow pattern brought several rounds of strong to severe thunderstorms across north and central Georgia. One of these episodes moved across the region during the afternoon and evening producing numerous reports of large hail and damaging thunderstorm winds.', 'A city hall employee reported ping pong ball size hail at their home east of Winterville.');
INSERT INTO public.stormevents_east VALUES (786401, 201809, 3, 1620, 201809, 3, 1625, 131434, 'NEW HAMPSHIRE', 33, 2018, 'September', 'Thunderstorm Wind', 'GYX', '03-SEP-18 16:20:00', 'EST-5', '03-SEP-18 16:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 0, 'W', 'LANCASTER', 0, 'W', 'LANCASTER', 44.48, -71.58, 44.48, -71.58, 'A cold front dropping south from Canada produced scattered convection as it moved into northern New Hampshire on the afternoon of September 3rd. A few cells became severe and produced wind damage in Lancaster and Jefferson.', 'A severe thunderstorm downed trees, wires and power poles on Route 135 in Lancaster.');
INSERT INTO public.stormevents_east VALUES (786402, 201809, 3, 1900, 201809, 3, 1935, 131434, 'NEW HAMPSHIRE', 33, 2018, 'September', 'Thunderstorm Wind', 'GYX', '03-SEP-18 19:00:00', 'EST-5', '03-SEP-18 19:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', 50, 'EG', NULL, NULL, 0, 'N', 'JEFFERSON', 0, 'N', 'JEFFERSON', 44.42, -71.47, 44.42, -71.47, 'A cold front dropping south from Canada produced scattered convection as it moved into northern New Hampshire on the afternoon of September 3rd. A few cells became severe and produced wind damage in Lancaster and Jefferson.', 'A severe thunderstorm downed trees in Jefferson.');
INSERT INTO public.stormevents_east VALUES (790217, 201812, 9, 1154, 201812, 9, 1155, 132056, 'FLORIDA', 12, 2018, 'December', 'Tornado', 'MLB', '09-DEC-18 11:54:00', 'EST-5', '09-DEC-18 11:55:00', 0, 0, 0, 0, '40.00K', '0.00K', 'Broadcast Media', NULL, NULL, NULL, NULL, 4, 'ESE', 'UNION PARK', 4, 'ESE', 'UNION PARK', 28.5429, -81.2304, 28.5447, -81.2296, 'A weak tornado briefly occurred near Waterford Lakes in Orlando. Minor wind damage impacted a few homes.', 'Local media forwarded a report of a screened pool enclosure destroyed at a home on Wildlife Place in Orlando. Delayed reports from Orange County Fire Rescue indicated two nearby homes on Brown Trout Circle also experienced some minor structural damage. Residents reportedly witnessed the tornado.');
INSERT INTO public.stormevents_east VALUES (791427, 201812, 21, 258, 201812, 22, 704, 132257, 'OHIO', 39, 2018, 'December', 'Flood', 'RLX', '21-DEC-18 02:58:00', 'EST-5', '22-DEC-18 07:04:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'PRATTS FORK', 12, 'S', 'VANDERHOOT', 39.1822, -82.0455, 39.0262, -81.8703, 'Several low pressure systems lifted through the Appalachians between the 20th and 24th. The strongest impacted the area on the 21st with moderate to heavy rain totaling 1.25 to 1.5 inches over 24 hours. This fell on already saturated ground, and quickly became runoff into local creeks and streams, pushing some into flooding. Additional rainfall on the 22nd, caused some waterways to surge out of their banks again. Eventually, this water worked its way into the Ohio River, with minor flooding in typical low spots along the river.', 'The Shade River near Chester rose above its 17 foot bankfull level shortly after midnight on the 21st. The gage showed the river cresting at 19.36 feet late that evening before returning to its banks around dawn the morning of the 22nd. This caused flooding on the Sugar Run Creek Bridge.');
INSERT INTO public.stormevents_east VALUES (787202, 201809, 17, 1615, 201809, 21, 100, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 16:15:00', 'EST-5', '21-SEP-18 01:00:00', 0, 0, 0, 0, '21.80M', '30.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'WNW', 'EVERETTS MILL', 5, 'SE', 'STEEN TOWN', 34.8072, -79.9259, 34.8112, -79.6142, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 10 to 15 inches caused widespread flooding across the county. Additional rainfall upstream resulted in major flooding at the Blewett Falls Dam along the Pee Dee River. Flooding damaged approximately 160 structures throughout the county, destroying 25 and resulting in over $21.8 million in property damage. Crop damage was at least $30 million. Numerous streets and roads were reported flooded.');
INSERT INTO public.stormevents_east VALUES (798865, 201812, 28, 730, 201812, 28, 1900, 133525, 'GEORGIA', 13, 2018, 'December', 'Flood', 'GSP', '28-DEC-18 07:30:00', 'EST-5', '28-DEC-18 19:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'WNW', 'CLARKESVILLE', 0, 'WNW', 'CLARKESVILLE', 34.622, -83.528, 34.621, -83.525, 'Widespread moderate to heavy rain developed across northeast Georgia on the 27th in advance of a strong cold front. The rain persisted through much of the 28th before tapering off late in the day. Storm total rainfall amounts of 4 to 5 inches occurred across the mountains, with locally higher amounts in excess of 6 inches. This resulted in flooding along a couple of small streams.', 'A stream gauge on the Soque River in Clarkesville exceeded its established flood stage after 4 to 5 inches of rain fell in the basin in about 24 hours. Pitts Park in Clarkesville was flooded, while county comms reported closure of West Water St and Habersham Mill Rd due nto flood water from the Soque or its tributaries.');
INSERT INTO public.stormevents_east VALUES (798864, 201812, 28, 1000, 201812, 28, 1500, 133525, 'GEORGIA', 13, 2018, 'December', 'Flood', 'GSP', '28-DEC-18 10:00:00', 'EST-5', '28-DEC-18 15:00:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'BURTON', 1, 'SE', 'CHECKERO', 34.846, -83.394, 34.84, -83.335, 'Widespread moderate to heavy rain developed across northeast Georgia on the 27th in advance of a strong cold front. The rain persisted through much of the 28th before tapering off late in the day. Storm total rainfall amounts of 4 to 5 inches occurred across the mountains, with locally higher amounts in excess of 6 inches. This resulted in flooding along a couple of small streams.', 'Spotter reported Stekoa Creek overflowed its banks and flooded part of Rickman Airfield Rd. Public reported a private bridge over She Creek was washed out off She Creek Ln.');
INSERT INTO public.stormevents_east VALUES (791419, 201812, 21, 1313, 201812, 21, 1313, 132224, 'GULF OF MEXICO', 85, 2018, 'December', 'Marine High Wind', 'MFL', '21-DEC-18 13:13:00', 'EST-5', '21-DEC-18 13:13:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 52, 'MG', NULL, NULL, 1, 'S', 'WIGGINS PASS', 1, 'S', 'WIGGINS PASS', 26.27, -81.82, 26.27, -81.82, 'West-southwest gales developed behind a strong cold front that moved through the region during the early morning hours of December 21st. Several sites along the Collier County coast reported non-thunderstorm gusts to around 60 mph as the sustained winds increased.', 'Mesonet site located at  Vanderbilt Beach recorded a non-convective wind gust of 60mph/52 knots.');
INSERT INTO public.stormevents_east VALUES (787272, 201809, 9, 1726, 201809, 9, 1926, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 17:26:00', 'EST-5', '09-SEP-18 19:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'WATERLOO', 2, 'NNW', 'WATERLOO', 39.109, -78.1159, 39.108, -78.1025, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'High water blocked the end of VA-644 Ginss Road/East Parkins Mill Road.');
INSERT INTO public.stormevents_east VALUES (787275, 201809, 9, 1929, 201809, 9, 2129, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '09-SEP-18 21:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'GREEN SPG', 1, 'WSW', 'GREEN SPG', 39.3, -78.2, 39.2962, -78.1826, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-731 Cattail Road was closed due to flooding near Creola Drive.');
INSERT INTO public.stormevents_east VALUES (787276, 201809, 9, 1929, 201809, 9, 2129, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '09-SEP-18 21:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'SILER', 2, 'ESE', 'SILER', 39.34, -78.23, 39.3418, -78.2238, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-681 Three Creeks Road/Hunting Ridge Road was closed due to flooding near Shadow Brook Lane.');
INSERT INTO public.stormevents_east VALUES (787278, 201809, 9, 1929, 201809, 9, 2129, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '09-SEP-18 21:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'SILER', 1, 'SSW', 'SILER', 39.3288, -78.2593, 39.3304, -78.2593, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-689 Adams Road was closed due to flooding near Easter Ridge Lane.');
INSERT INTO public.stormevents_east VALUES (787279, 201809, 9, 1929, 201809, 9, 2129, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '09-SEP-18 21:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'WHITACRE', 2, 'NE', 'WHITACRE', 39.3505, -78.3129, 39.3467, -78.3082, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-699 New Hope Road was closed due to flooding near US-522 North Frederick Pike.');
INSERT INTO public.stormevents_east VALUES (787280, 201809, 9, 1929, 201809, 9, 2129, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '09-SEP-18 21:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 4, 'NNE', 'WHITACRE', 4, 'NW', 'SILER', 39.38, -78.31, 39.3843, -78.3079, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-694 Cumberland Trail Road was closed due to flooding near  VA-696 South Timber Ridge Road.');
INSERT INTO public.stormevents_east VALUES (787283, 201809, 9, 1926, 201809, 10, 900, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:26:00', 'EST-5', '10-SEP-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'NAIN', 1, 'ENE', 'NAIN', 39.2344, -78.1898, 39.2345, -78.1869, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'Golds Hill Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (796377, 201812, 20, 0, 201812, 21, 0, 133115, 'VIRGINIA', 51, 2018, 'December', 'Heavy Rain', 'RNK', '20-DEC-18 00:00:00', 'EST-5', '21-DEC-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 0, 'N', '(KDAN)DANVILLE REGIONAL AIRPORT', 0, 'N', '(KDAN)DANVILLE REGIONAL AIRPORT', 36.57, -79.34, 36.57, -79.34, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'A record rainfall of 1.48 inches was set at Danville, VA (ROA) for December 20, breaking the old record of 1.43 inches set in 1951. Official climate records for Danville date back to 1916.');
INSERT INTO public.stormevents_east VALUES (796378, 201812, 20, 0, 201812, 21, 0, 133115, 'VIRGINIA', 51, 2018, 'December', 'Heavy Rain', 'RNK', '20-DEC-18 00:00:00', 'EST-5', '21-DEC-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', NULL, NULL, NULL, NULL, 0, 'N', 'LYNCHBURG ARPT', 0, 'N', 'LYNCHBURG ARPT', 37.33, -79.2, 37.33, -79.2, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'The record rainfall of 1.63 inches was tied at Lynchburg, VA (LYH) for December 20, tying the record first set in 1905.  Official climate records for Lynchburg date back to 1893.');
INSERT INTO public.stormevents_east VALUES (798673, 201812, 30, 1038, 201812, 30, 1245, 133489, 'SOUTH CAROLINA', 45, 2018, 'December', 'Flood', 'ILM', '30-DEC-18 10:38:00', 'EST-5', '30-DEC-18 12:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'WNW', 'NORTH SANTEE', 3, 'WNW', 'NORTH SANTEE', 33.25, -79.43, 33.2458, -79.4245, 'A stationary boundary produced slow moving showers with flooding.', 'An elevated house was completely surrounded by water from locally heavy rain that fell into the North Santee River basin.');
INSERT INTO public.stormevents_east VALUES (784682, 201809, 17, 1024, 201809, 17, 1224, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 10:24:00', 'EST-5', '17-SEP-18 12:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'PEOLA MILLS', 2, 'NE', 'PEOLA MILLS', 38.5253, -78.2628, 38.5473, -78.252, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Multiple roads were flooded and closed in the Ethan area.');
INSERT INTO public.stormevents_east VALUES (792044, 201812, 2, 639, 201812, 2, 900, 131758, 'GEORGIA', 13, 2018, 'December', 'Flood', 'TAE', '02-DEC-18 06:39:00', 'EST-5', '02-DEC-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'FITZGERALD COTTON MILL', 1, 'E', 'FITZGERALD COTTON MILL', 31.69, -83.25, 31.6906, -83.2498, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'Flooding was reported in a parking lot in the Fitzgerald area.');
INSERT INTO public.stormevents_east VALUES (750444, 201805, 27, 2150, 201805, 27, 2150, 125120, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '27-MAY-18 21:50:00', 'EST-5', '27-MAY-18 21:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 54, 'EG', NULL, NULL, 1, 'S', 'RICHMOND', 1, 'S', 'RICHMOND', 42.81, -82.75, 42.81, -82.75, 'A few severe thunderstorms developed and produced wind damage.', 'Several trees and power lines reported down, as well as damage to a roof overhang on a building.');
INSERT INTO public.stormevents_east VALUES (750445, 201805, 27, 1601, 201805, 27, 1601, 125121, 'LAKE HURON', 90, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '27-MAY-18 16:01:00', 'EST-5', '27-MAY-18 16:01:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 37, 'MG', NULL, NULL, 2, 'NW', 'CASEVILLE', 2, 'NW', 'CASEVILLE', 43.95, -83.29, 43.95, -83.29, 'Thunderstorm moving through Saginaw Bay produced wind gusts in excess of 45 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (750446, 201805, 27, 1616, 201805, 27, 1616, 125121, 'LAKE HURON', 90, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '27-MAY-18 16:16:00', 'EST-5', '27-MAY-18 16:16:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 48, 'MG', NULL, NULL, 2, 'NW', 'CASEVILLE', 2, 'NW', 'CASEVILLE', 43.95, -83.29, 43.95, -83.29, 'Thunderstorm moving through Saginaw Bay produced wind gusts in excess of 45 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (750447, 201805, 27, 1519, 201805, 27, 1519, 125121, 'LAKE HURON', 90, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '27-MAY-18 15:19:00', 'EST-5', '27-MAY-18 15:19:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 47, 'MG', NULL, NULL, 6, 'NE', 'ALABESTER', 6, 'NE', 'ALABESTER', 44.23, -83.46, 44.23, -83.46, 'Thunderstorm moving through Saginaw Bay produced wind gusts in excess of 45 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (744983, 201805, 4, 1226, 201805, 4, 1226, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:26:00', 'EST-5', '04-MAY-18 12:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 56, 'EG', NULL, NULL, 2, 'SW', 'SMITHS CREEK', 2, 'SW', 'SMITHS CREEK', 42.9, -82.62, 42.9, -82.62, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'Trees blown down blocking roadway.');
INSERT INTO public.stormevents_east VALUES (744985, 201805, 4, 1232, 201805, 4, 1232, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:32:00', 'EST-5', '04-MAY-18 12:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'E', 'MONROE', 1, 'E', 'MONROE', 41.92, -83.39, 41.92, -83.39, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'A 10 inch tree limb was reported down.');
INSERT INTO public.stormevents_east VALUES (760179, 201806, 30, 2110, 201806, 30, 2115, 126791, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '30-JUN-18 21:10:00', 'EST-5', '30-JUN-18 21:15:00', 0, 0, 0, 0, '6.00K', NULL, 'Public', 50, 'EG', NULL, NULL, 2, 'ENE', 'CENTER', 2, 'ENE', 'CENTER', 34.0676, -83.3855, 34.0676, -83.3855, 'Despite a building upper-level ridge over the region, strong afternoon heating combined with ample moisture resulted in an isolated severe thunderstorm producing damaging wind gusts in north Georgia.', 'A report was received from the public of multiple trees and power lines blown down along Highway 334 near Asgar Farms Road.');
INSERT INTO public.stormevents_east VALUES (763928, 201806, 1, 1550, 201806, 1, 1625, 126778, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '01-JUN-18 15:50:00', 'EST-5', '01-JUN-18 16:25:00', 0, 0, 0, 0, '7.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WSW', 'PRATHER', 2, 'SSE', 'PORTERS', 33.8248, -82.9147, 33.6494, -82.6644, 'A series of fast moving upper-level short waves moving southeast out of the Ohio Valley brought two distinct rounds of thunderstorms into north Georgia, spreading south into portions of central Georgia. Numerous reports of damaging thunderstorm winds were received with isolated reports of flooding.', 'The Wilkes County Emergency Manager reported several trees and power lines blown down across the county from the Rayle and Tignall areas across Washington to near Aonia.');
INSERT INTO public.stormevents_east VALUES (763938, 201806, 1, 1555, 201806, 1, 1605, 126778, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '01-JUN-18 15:55:00', 'EST-5', '01-JUN-18 16:05:00', 0, 0, 0, 0, '2.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 3, 'NNW', 'MCENHENEYS CROSSROADS', 3, 'NNW', 'MCENHENEYS CROSSROADS', 33.2653, -83.7696, 33.2653, -83.7696, 'A series of fast moving upper-level short waves moving southeast out of the Ohio Valley brought two distinct rounds of thunderstorms into north Georgia, spreading south into portions of central Georgia. Numerous reports of damaging thunderstorm winds were received with isolated reports of flooding.', 'A tree was blown down along Clay Road.');
INSERT INTO public.stormevents_east VALUES (760858, 201806, 27, 1545, 201806, 27, 1555, 126789, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '27-JUN-18 15:45:00', 'EST-5', '27-JUN-18 15:55:00', 0, 0, 0, 0, '1.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 9, 'WNW', 'FIVE POINTS', 9, 'WNW', 'FIVE POINTS', 32.117, -83.324, 32.117, -83.324, 'A series of weak upper-level short waves moving across the region combined with strong afternoon heating to produce scattered strong to severe thunderstorms each afternoon and evening across north and central Georgia.', 'The Dodge County Emergency Manager reported a tree blown down near the intersection of Highway 230 and Rock Springs Road.');
INSERT INTO public.stormevents_east VALUES (760862, 201806, 27, 1708, 201806, 27, 1718, 126789, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '27-JUN-18 17:08:00', 'EST-5', '27-JUN-18 17:18:00', 0, 0, 0, 0, '1.00K', NULL, '911 Call Center', 45, 'EG', NULL, NULL, 0, 'N', 'MT VERNON', 0, 'N', 'MT VERNON', 32.1768, -82.601, 32.1768, -82.601, 'A series of weak upper-level short waves moving across the region combined with strong afternoon heating to produce scattered strong to severe thunderstorms each afternoon and evening across north and central Georgia.', 'The Montgomery County 911 center reported a tree blown down around the intersection of Blueberry Road and Morrison Street in Mount Vernon.');
INSERT INTO public.stormevents_east VALUES (775292, 201809, 6, 1820, 201809, 6, 1820, 129394, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '06-SEP-18 18:20:00', 'EST-5', '06-SEP-18 18:20:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'ENE', 'BEL AIR', 1, 'ENE', 'BEL AIR', 39.54, -76.33, 39.54, -76.33, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which became severe.', 'A tree was blown down into power lines on MD SR 22 in Bel Air.');
INSERT INTO public.stormevents_east VALUES (788082, 201809, 28, 406, 201809, 28, 812, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 04:06:00', 'EST-5', '28-SEP-18 08:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'GLENCOE', 0, 'W', 'GLENCOE', 39.55, -76.6362, 39.5495, -76.6356, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The water levels at Gunpowder Falls at Glencoe surpassed flood stage of 7 feet. The water levels crested at 8.47 feet at 6:00 AM September 28th. ||Portions of Upper Glencoe Road and Lower Glencoe Road began to flood.');
INSERT INTO public.stormevents_east VALUES (787000, 201809, 10, 552, 201809, 10, 1907, 131563, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '10-SEP-18 05:52:00', 'EST-5', '10-SEP-18 19:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'NW', 'ROCK GAP', 3, 'S', 'WOODMONT', 39.5723, -78.3175, 39.5816, -78.3184, 'Heavy rain fell to the north of a stalled front on September 9th and 10th. One to three inches of rain fell across the eastern West Virginia Panhandle late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'The water level along the Cacapon River at Great Cacapon surpassed flood stage of 9 feet. The water crested at 9.33 feet on September 10th at 10:00 AM EST. Rock Ford Road begins to flood in multiple locations, including flowing completely over the low water bridge. Constant Run Road also begins to flood.');
INSERT INTO public.stormevents_east VALUES (786385, 201809, 23, 324, 201809, 23, 524, 131429, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '23-SEP-18 03:24:00', 'EST-5', '23-SEP-18 05:24:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'SWOOPE', 2, 'N', 'SWOOPE', 38.2021, -79.1937, 38.2017, -79.1952, 'A boundary stalled overhead, causing showers and thunderstorms to develop. The stalled boundary caused persistent convection over central Virginia, which led to flooding.', 'Morris Mill Road was closed due to flooding between Buffalo Gap Highway and Buffalo Branch Line.');
INSERT INTO public.stormevents_east VALUES (786386, 201809, 23, 327, 201809, 23, 527, 131429, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '23-SEP-18 03:27:00', 'EST-5', '23-SEP-18 05:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'NEW HOPE', 2, 'S', 'NEW HOPE', 38.1774, -78.903, 38.1769, -78.9032, 'A boundary stalled overhead, causing showers and thunderstorms to develop. The stalled boundary caused persistent convection over central Virginia, which led to flooding.', 'New Hope-Crimora Road was closed due to flooding between the 300 and 1000 Block.');
INSERT INTO public.stormevents_east VALUES (773332, 201807, 1, 1610, 201807, 1, 1610, 128975, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '01-JUL-18 16:10:00', 'EST-5', '01-JUL-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'S', 'ROCHESTER HILLS', 1, 'S', 'ROCHESTER HILLS', 42.67, -83.13, 42.67, -83.13, 'A severe thunderstorm producing wind damage impacted the Canton area, with another severe storm hitting Rochester.', 'Multiple 5 inch diameter tree limbs reported down.');
INSERT INTO public.stormevents_east VALUES (784967, 201809, 14, 2300, 201809, 15, 400, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'ILM', '14-SEP-18 23:00:00', 'EST-5', '15-SEP-18 04:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'NE', 'CONWAY', 1, 'N', 'GRISSETT', 33.8607, -79.013, 33.8584, -79.0189, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'Long Avenue extension closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (784968, 201809, 16, 1531, 201809, 16, 2000, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 15:31:00', 'EST-5', '16-SEP-18 20:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'SSW', 'CLIO', 0, 'ENE', 'DUNBAR', 34.5399, -79.5502, 34.5332, -79.5441, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'Flooding on Dunbar Hwy from Fourth Street to Culvert Street.');
INSERT INTO public.stormevents_east VALUES (786481, 201809, 15, 1628, 201809, 15, 2100, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 16:28:00', 'EST-5', '15-SEP-18 21:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'ESE', 'ABBOTTSBURG', 2, 'ESE', 'ABBOTTSBURG', 34.51, -78.71, 34.5092, -78.707, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Hwy 211 was impassable due to flooding near White McEwen Rd.');
INSERT INTO public.stormevents_east VALUES (786805, 201809, 16, 844, 201809, 16, 1330, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 08:44:00', 'EST-5', '16-SEP-18 13:30:00', 0, 0, 0, 0, '150.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 4, 'SSE', 'SCOTTS HILL', 1, 'NE', 'WARDS CORNER', 34.2809, -77.7324, 34.5439, -78.0667, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Hwy 17 closed in Hampstead. County Club Brd near Long Leaf Drive was washed out. Hwy 53 was closed near Burgaw. Hwy 421 closed north of Hwy 210. Deerfield Drive was washed out at Creekview Drive.');
INSERT INTO public.stormevents_east VALUES (784857, 201809, 16, 2016, 201809, 16, 2017, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Tornado', 'ILM', '16-SEP-18 20:16:00', 'EST-5', '16-SEP-18 20:17:00', 0, 0, 0, 0, '5.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SW', 'CAMP SWAMP', 1, 'SW', 'CAMP SWAMP', 34.01, -78.76, 34.0119, -78.761, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'A tornado touched down in northern Horry County causing spotty damage to pine trees and minor roof damage.');
INSERT INTO public.stormevents_east VALUES (784681, 201809, 17, 830, 201809, 17, 1030, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 08:30:00', 'EST-5', '17-SEP-18 10:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'NELLYSFORD', 1, 'W', 'NELLYSFORD', 37.8817, -78.897, 37.8809, -78.9009, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Glenthorn Loop Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (784683, 201809, 17, 1030, 201809, 17, 1230, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 10:30:00', 'EST-5', '17-SEP-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'N', 'IVY', 3, 'N', 'IVY', 38.1, -78.59, 38.0998, -78.5983, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The stream gauge at Mechums River indicated that minor flooding was occurring when it crested above the flood stage of 11 feet.');
INSERT INTO public.stormevents_east VALUES (784685, 201809, 17, 1051, 201809, 17, 1251, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 10:51:00', 'EST-5', '17-SEP-18 12:51:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'ENE', 'LYDIA', 2, 'SW', 'KINDERHOOK', 38.3428, -78.4626, 38.344, -78.4576, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Octonai Road was closed and flooded near south River Road. Every Run Road and Route 634 were also flooded and closed in the area.');
INSERT INTO public.stormevents_east VALUES (787058, 201809, 28, 124, 201809, 28, 322, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 01:24:00', 'EST-5', '28-SEP-18 03:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KEYMAR', 1, 'NNW', 'KEYMAR', 39.6161, -77.2432, 39.6154, -77.2425, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The USGS stream gage on Big Pipe Creek near Bruceville exceeded the 8 foot flood stage during the indicated period, flooding Keysville-Bruceville Road. The peak level of 8.40 feet was observed at 2:15 am EST.');
INSERT INTO public.stormevents_east VALUES (776866, 201807, 21, 1925, 201807, 21, 1935, 129691, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'FFC', '21-JUL-18 19:25:00', 'EST-5', '21-JUL-18 19:35:00', 0, 0, 0, 0, '12.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 3, 'ENE', 'WHISTLEVILLE', 1, 'N', 'STATHAM', 34.0181, -83.7116, 33.9852, -83.597, 'A series of short waves moving through an unseasonably strong northwesterly upper-level flow pattern brought several rounds of strong to severe thunderstorms across north and central Georgia. One of these episodes moved across the region during the afternoon and evening producing numerous reports of large hail and damaging thunderstorm winds.', 'The Barrow County Emergency Manager reported several trees blown from north of Winder to near Statham.');
INSERT INTO public.stormevents_east VALUES (786432, 201809, 6, 1119, 201809, 6, 1124, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 11:19:00', 'EST-5', '06-SEP-18 11:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 0, 'W', 'DAYS FERRY', 0, 'W', 'DAYS FERRY', 43.9488, -69.8094, 43.9488, -69.8094, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm downed trees and wires at Days Ferry.');
INSERT INTO public.stormevents_east VALUES (786433, 201809, 6, 1117, 201809, 6, 1122, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 11:17:00', 'EST-5', '06-SEP-18 11:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'NNE', 'NEW MEADOWS', 1, 'NNE', 'NEW MEADOWS', 43.917, -69.8641, 43.917, -69.8641, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm downed trees and wires on Larabees Grove Road in Bath.');
INSERT INTO public.stormevents_east VALUES (787282, 201809, 9, 1929, 201809, 10, 900, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '10-SEP-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'FAIRMONT SCHOOL', 1, 'SSW', 'FAIRMONT SCHOOL', 39.02, -78.47, 39.0198, -78.4747, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-600 Zepp Road was closed due to flooding near the Shenandoah County Line.');
INSERT INTO public.stormevents_east VALUES (787273, 201809, 9, 1726, 201809, 10, 900, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 17:26:00', 'EST-5', '10-SEP-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'WINCHESTER ARPT', 1, 'E', 'WINCHESTER ARPT', 39.1477, -78.1271, 39.1506, -78.1345, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'VA-655 Sulphur Springs Road was closed due to flooding near US-50 Millwood Pike.');
INSERT INTO public.stormevents_east VALUES (786435, 201809, 6, 1127, 201809, 6, 1132, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 11:27:00', 'EST-5', '06-SEP-18 11:32:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'NE', 'WESTPORT', 2, 'NE', 'WESTPORT', 43.9186, -69.6993, 43.9186, -69.6993, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm downed trees and wires in Westport.');
INSERT INTO public.stormevents_east VALUES (769691, 201807, 3, 1535, 201807, 3, 1555, 128295, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'FFC', '03-JUL-18 15:35:00', 'EST-5', '03-JUL-18 15:55:00', 0, 0, 0, 0, '7.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 0, 'ENE', 'GARFIELD', 3, 'NNE', 'KIRBY', 32.6502, -82.0987, 32.5407, -82.3195, 'With a warm and very moist air mass over the area, an upper-level trough moving across the region produced scattered severe thunderstorms from the afternoon into the overnight hours.', 'The Emanuel County 911 center reported trees blown down across the county from Garfield to south of Swainsboro.');
INSERT INTO public.stormevents_east VALUES (769692, 201807, 3, 1600, 201807, 3, 1610, 128295, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'FFC', '03-JUL-18 16:00:00', 'EST-5', '03-JUL-18 16:10:00', 0, 0, 0, 0, '2.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'WNW', 'LOUISVILLE', 1, 'WNW', 'LOUISVILLE', 33.0032, -82.4111, 33.0032, -82.4111, 'With a warm and very moist air mass over the area, an upper-level trough moving across the region produced scattered severe thunderstorms from the afternoon into the overnight hours.', 'The Jefferson County Emergency Manager reported a couple of trees blown down in Louisville.');
INSERT INTO public.stormevents_east VALUES (769693, 201807, 3, 1625, 201807, 3, 1645, 128295, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'FFC', '03-JUL-18 16:25:00', 'EST-5', '03-JUL-18 16:45:00', 0, 0, 0, 0, '5.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'NW', 'RIDDLEVILLE', 2, 'ENE', 'GARDNER', 32.917, -82.7, 32.8854, -82.9476, 'With a warm and very moist air mass over the area, an upper-level trough moving across the region produced scattered severe thunderstorms from the afternoon into the overnight hours.', 'The Washington County Emergency Manager reported several trees blown down from around the intersection of Old Savannah Road and Highway 242 near Riddleville to around the intersection of Highway 272 and Tennille Oconee Road near Oconee.');
INSERT INTO public.stormevents_east VALUES (786314, 201809, 16, 2320, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '16-SEP-18 23:20:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'SSE', 'CARR', 4, 'N', 'SCHLEY', 36.2077, -79.2133, 36.2045, -79.0598, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Heavy rainfall of 6 to 12 inches flooded numerous roads across the county. Many of the roads are impassable. This list includes but is not limited to Jones Ferry Road Bridge at Uuniversity Lake, Eastgate Crossing and University Place parking lots in Chapel Hill.  Whitfield road is washed out at Foxridge road.');
INSERT INTO public.stormevents_east VALUES (787721, 201809, 17, 1615, 201809, 19, 1510, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 16:15:00', 'EST-5', '19-SEP-18 15:10:00', 0, 0, 0, 0, '26.40M', '5.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 7, 'S', 'TEER', 5, 'SE', 'CHAPEL HILL', 35.8561, -79.2494, 35.8632, -79.0154, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 6 to 10 inches caused widespread flooding across the county, which caused flooding along the Eno River and other creeks and streams throughout the county. Additionally, water held in Jordan Lake from rainfall in its headwaters resulted in flooding along the lake into far southeast portions of the county. Flooding damaged approximately 276 structures throughout the county, destroying 1 and resulting in $26.4 million in property damage. Numerous roads were closed due to flooding. Numerous homes and businesses were flooded as well. While final losses on crops are not yet tallied, estimates around $5 million or more are possible.');
INSERT INTO public.stormevents_east VALUES (786258, 201809, 14, 1350, 201809, 17, 1314, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '14-SEP-18 13:50:00', 'EST-5', '17-SEP-18 13:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'NE', 'HOLLAND', 2, 'NW', 'KNIGHTDALE WNDLL ARP', 35.5768, -78.7703, 35.8251, -78.4537, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Flash flooding from heavy rainfall of 5 to 8 inches closed several roads across the county.');
INSERT INTO public.stormevents_east VALUES (786259, 201809, 15, 900, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '15-SEP-18 09:00:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'WNW', 'ROBBINS', 1, 'SSW', 'GLENDON', 35.4346, -79.6244, 35.4728, -79.424, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 10 to 15 inches caused widespread flash flooding across the county. The heavy rains caused several creeks to overspill their banks.  Numerous roads throughout the county were closed, due to flooding, including significant flooding in the Crains Creek community.  Numerous homes and businesses were flooded as well.   At least 24 persons and 31 animals were rescued from flood waters in the southeastern part of the county.');
INSERT INTO public.stormevents_east VALUES (786268, 201809, 15, 2305, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '15-SEP-18 23:05:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 1, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'ESE', 'BURNSVILLE', 7, 'NNE', 'LILESVILLE', 35.1161, -80.231, 35.0632, -79.9453, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 15 to 20 inches caused widespread flash flooding across the county. The heavy rains caused flash flooding on several creeks. Numerous roads were closed throughout the county. George Wright Road and Mayesville Road were washed out due to flooding. Water rescues were conducted in the city of Wadesboro, including a submerged car with National Guard assets. A 52 year old male was traveling on Peru Road and entered a curve where the road was washed out. The vehicle stalled in the water and was swept away. The driver was able to get himself to safety, the passenger was swept away.');
INSERT INTO public.stormevents_east VALUES (786316, 201809, 17, 800, 201809, 17, 1315, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '17-SEP-18 08:00:00', 'EST-5', '17-SEP-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'SW', 'ROUGEMONT', 1, 'NNW', 'MANGUM STORE', 36.2113, -78.9404, 36.2158, -78.835, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Heavy rainfall of 8 to 12 inches flooded numerous roads across the county. Many of the roads are impassable. This list includes but is not limited to Durham-Chapel Hill Boulevard split, Westgate Drive at Durham-Chapel Hill Boulevard, Rippling Stream at 200 Seven Oaks Road and Old Farm neighborhood in northern Durham.');
INSERT INTO public.stormevents_east VALUES (786317, 201809, 17, 900, 201809, 17, 1315, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '17-SEP-18 09:00:00', 'EST-5', '17-SEP-18 13:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'W', 'CUNNINGHAM', 3, 'N', 'TRIPLE SPGS', 36.5292, -79.0931, 36.5294, -78.855, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Heavy rainfall of 6 to 9 inches flooded numerous roads across the county. Surl-Mount Tirzah road at Antioch Church road is closed due to the pond over flowing and covering the roadways. 3300 block of Antioch Church road is impassable due to flood waters.');
INSERT INTO public.stormevents_east VALUES (775284, 201809, 1, 1430, 201809, 1, 1430, 129391, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '01-SEP-18 14:30:00', 'EST-5', '01-SEP-18 14:30:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 3, 'N', 'ROCKY BAR', 3, 'N', 'ROCKY BAR', 38.39, -78.68, 38.39, -78.68, 'A stalled frontal boundary interacted with a warm and moist air mass to generate showers and thunderstorms, a couple of which became severe.', 'Three trees and power lines were blown down in the MaGaheysville and Elkton area.');
INSERT INTO public.stormevents_east VALUES (775285, 201809, 1, 1545, 201809, 1, 1545, 129391, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '01-SEP-18 15:45:00', 'EST-5', '01-SEP-18 15:45:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'SSW', 'WADESVILLE', 2, 'SSW', 'WADESVILLE', 39.22, -78.04, 39.22, -78.04, 'A stalled frontal boundary interacted with a warm and moist air mass to generate showers and thunderstorms, a couple of which became severe.', 'A tree was blown down on Longmarsh Road.');
INSERT INTO public.stormevents_east VALUES (775286, 201809, 1, 1550, 201809, 1, 1550, 129391, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '01-SEP-18 15:50:00', 'EST-5', '01-SEP-18 15:50:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 3, 'NW', 'BOYCE', 3, 'NW', 'BOYCE', 39.13, -78.08, 39.13, -78.08, 'A stalled frontal boundary interacted with a warm and moist air mass to generate showers and thunderstorms, a couple of which became severe.', 'Tree limbs and wires were blown down on Pyletown Road.');
INSERT INTO public.stormevents_east VALUES (775287, 201809, 4, 1457, 201809, 4, 1457, 129392, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '04-SEP-18 14:57:00', 'EST-5', '04-SEP-18 14:57:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'W', 'WHITE PLAINS', 2, 'W', 'WHITE PLAINS', 38.5748, -76.9893, 38.5748, -76.9893, 'Isolated thunderstorms formed in the afternoon hours due to high amounts of instability and subtle mesoscale boundaries, including sea and river breezes. One storm become severe.', 'A tree was blown down on Turkey Hill Road. Tree damage also occurred near the intersection of Crain Highway and Theodore Green Boulevard.');
INSERT INTO public.stormevents_east VALUES (775288, 201809, 4, 1517, 201809, 4, 1517, 129392, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '04-SEP-18 15:17:00', 'EST-5', '04-SEP-18 15:17:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 0, 'N', 'NEWTOWN', 0, 'N', 'NEWTOWN', 38.5, -76.95, 38.5, -76.95, 'Isolated thunderstorms formed in the afternoon hours due to high amounts of instability and subtle mesoscale boundaries, including sea and river breezes. One storm become severe.', 'A tree was blown down near the intersection of Springhill-Newtown Road and Rosier Place.');
INSERT INTO public.stormevents_east VALUES (775289, 201809, 6, 1535, 201809, 6, 1535, 129393, 'WEST VIRGINIA', 54, 2018, 'September', 'Thunderstorm Wind', 'LWX', '06-SEP-18 15:35:00', 'EST-5', '06-SEP-18 15:35:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 4, 'SW', 'SHORT GAP', 4, 'SW', 'SHORT GAP', 39.5, -78.87, 39.5, -78.87, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which became severe.', 'Three large trees were blown down, including one into a barn, near the 4400 block of Knobley Road in Short Gap.');
INSERT INTO public.stormevents_east VALUES (787284, 201809, 9, 1929, 201809, 10, 900, 131607, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 19:29:00', 'EST-5', '10-SEP-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'ROUND HILL', 2, 'N', 'ROUND HILL', 39.232, -78.2443, 39.228, -78.2487, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding.', 'Indian Hollow Road was closed due to flooding near North Hayfield Road and Frederick Pike.');
INSERT INTO public.stormevents_east VALUES (796379, 201812, 20, 2030, 201812, 21, 230, 133115, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'RNK', '20-DEC-18 20:30:00', 'EST-5', '21-DEC-18 02:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'NATURAL BRIDGE', 1, 'SW', 'BALCONY FALLS', 37.63, -79.54, 37.6249, -79.4387, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'Lone Jacks Road near Natural Bridge was closed due to flooding from the Maury River with water across the road. Some streets in Buena Vista were also flooded. Portions of Tinkerville Road were also flooded.');
INSERT INTO public.stormevents_east VALUES (796447, 201812, 20, 2100, 201812, 21, 300, 133115, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'RNK', '20-DEC-18 21:00:00', 'EST-5', '21-DEC-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'SE', 'GLASGOW', 1, 'SE', 'GLASGOW', 37.6249, -79.4441, 37.6242, -79.4424, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'Water overflowing from the Maury River was crossing Glasgow Highway and blocking the road with debris.');
INSERT INTO public.stormevents_east VALUES (792046, 201812, 2, 912, 201812, 2, 912, 131758, 'GEORGIA', 13, 2018, 'December', 'Funnel Cloud', 'TAE', '02-DEC-18 09:12:00', 'EST-5', '02-DEC-18 09:12:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, NULL, NULL, 4, 'WNW', 'CROSLAND', 4, 'WNW', 'CROSLAND', 31.33, -83.7, 31.33, -83.7, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'An officer reported a funnel cloud in the northern part of Colquitt county.');
INSERT INTO public.stormevents_east VALUES (792049, 201812, 2, 927, 201812, 2, 927, 131758, 'GEORGIA', 13, 2018, 'December', 'Thunderstorm Wind', 'TAE', '02-DEC-18 09:27:00', 'EST-5', '02-DEC-18 09:27:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 0, 'N', 'OMEGA', 0, 'N', 'OMEGA', 31.34, -83.59, 31.34, -83.59, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'Trees were blown down near Highway 319 and Ty Ty Omega Road.');
INSERT INTO public.stormevents_east VALUES (792051, 201812, 2, 930, 201812, 2, 1230, 131758, 'GEORGIA', 13, 2018, 'December', 'Flood', 'TAE', '02-DEC-18 09:30:00', 'EST-5', '02-DEC-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'PHILLIPSBURG', 1, 'WNW', 'TIFTON', 31.4293, -83.5157, 31.4569, -83.5197, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'Flooding impacted some garages in the Tifton area.');
INSERT INTO public.stormevents_east VALUES (750465, 201805, 30, 1805, 201805, 30, 1805, 125123, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '30-MAY-18 18:05:00', 'EST-5', '30-MAY-18 18:05:00', 0, 0, 0, 0, '4.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'E', 'MONROE', 1, 'E', 'MONROE', 41.92, -83.39, 41.92, -83.39, 'The remnants of sub-tropical Alberto move through Lower Michigan. Several trees were downed sporadically across southeast Michigan.', 'Multiple power lines reported down.');
INSERT INTO public.stormevents_east VALUES (750467, 201805, 30, 1930, 201805, 30, 1930, 125123, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '30-MAY-18 19:30:00', 'EST-5', '30-MAY-18 19:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 52, 'EG', NULL, NULL, 2, 'SE', 'GAINES', 2, 'SE', 'GAINES', 42.85, -83.87, 42.85, -83.87, 'The remnants of sub-tropical Alberto move through Lower Michigan. Several trees were downed sporadically across southeast Michigan.', 'A tree was reported down.');
INSERT INTO public.stormevents_east VALUES (760114, 201806, 11, 1430, 201806, 11, 1440, 126782, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '11-JUN-18 14:30:00', 'EST-5', '11-JUN-18 14:40:00', 0, 0, 0, 0, '2.00K', NULL, 'Emergency Manager', 45, 'EG', NULL, NULL, 2, 'SSW', 'CLEVELAND', 2, 'SSW', 'CLEVELAND', 34.57, -83.7697, 34.57, -83.7697, 'A persistent moist and unstable airmass over the region combined with afternoon heating resulted in scattered to widespread thunderstorms each afternoon and evening with a few reports of damaging wind gusts each day.', 'The White County Emergency Manager reported a tree blown down onto power lines along Daybreak Road.');
INSERT INTO public.stormevents_east VALUES (786482, 201809, 15, 1641, 201809, 15, 2100, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 16:41:00', 'EST-5', '15-SEP-18 21:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'S', 'ABBOTTSBURG', 1, 'SSW', 'ABBOTTSBURG', 34.51, -78.73, 34.5114, -78.7359, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Twisted Hickory Rd near Grimsley Farm Rd impassable due to flooding.');
INSERT INTO public.stormevents_east VALUES (784846, 201809, 15, 2029, 201809, 15, 2031, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '15-SEP-18 20:29:00', 'EST-5', '15-SEP-18 20:31:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'SSW', 'KIRKLAND', 0, 'SW', 'KIRKLAND', 34.2955, -77.7814, 34.2975, -77.7843, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'A brief tornado touched down on the north side of Porters Neck Road|between Porters Neck Road and Tibbys Drive. The tornado moved NW for|less than 2 minutes and snapped a couple dozen trees up to 16 in|diameter and uprooted a few large trees.');
INSERT INTO public.stormevents_east VALUES (784847, 201809, 16, 1435, 201809, 16, 1436, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '16-SEP-18 14:35:00', 'EST-5', '16-SEP-18 14:36:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', NULL, NULL, NULL, NULL, 34, 'WSW', 'TOBEMORY', 34, 'WSW', 'TOBEMORY', 34.62, -79.43, 34.6206, -79.4276, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'A sheriff observed a tornado that touched down on a nearby field off of Gaddys Mill Road.');
INSERT INTO public.stormevents_east VALUES (786955, 201809, 28, 202, 201809, 28, 402, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:02:00', 'EST-5', '28-SEP-18 04:02:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'HEADSVILLE', 1, 'SE', 'HEADSVILLE', 39.3931, -78.8581, 39.3928, -78.8586, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'Patterson Creek Road was closed at Headsville Road due to high water.');
INSERT INTO public.stormevents_east VALUES (786956, 201809, 28, 206, 201809, 28, 406, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:06:00', 'EST-5', '28-SEP-18 04:06:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'FT ASHBY', 2, 'W', 'FT ASHBY', 39.4965, -78.809, 39.4964, -78.8094, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'Georges Run Road was closed at the 2100 block due to flooding.');
INSERT INTO public.stormevents_east VALUES (786957, 201809, 28, 331, 201809, 28, 531, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:31:00', 'EST-5', '28-SEP-18 05:31:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'BLAIRTON', 1, 'SW', 'BLAIRTON', 39.445, -77.9269, 39.4446, -77.9266, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'The 1500 block of Golf Course Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786958, 201809, 28, 332, 201809, 28, 532, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:32:00', 'EST-5', '28-SEP-18 05:32:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'BERKELEY', 1, 'WSW', 'BERKELEY', 39.4972, -77.9411, 39.4974, -77.9415, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'Berkeley Station Road was closed at Williamsport Pike due to flooding.');
INSERT INTO public.stormevents_east VALUES (787037, 201809, 28, 1252, 201809, 28, 1743, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 12:52:00', 'EST-5', '28-SEP-18 17:43:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 6, 'SSE', 'HOLTON', 6, 'SSE', 'HOLTON', 39.51, -78.04, 39.5141, -78.0381, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'The river level at Jones Springs along the Back Creek surpassed the flood stage of 11 feet, cresting at 11.28 feet at 4:00 PM September 28th. Dry Run Road was flooded and water approached Daisy Lane.');
INSERT INTO public.stormevents_east VALUES (786772, 201809, 14, 1507, 201809, 14, 2000, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '14-SEP-18 15:07:00', 'EST-5', '14-SEP-18 20:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'County Official', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'E', 'EASTBROOK', 6, 'NNW', 'CAMP BRANCH', 34.2698, -78.0378, 34.2538, -78.4048, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Ash Little River Rd was closed at Hines Drive near Calabash. Longwood Rd was closed in both directions near Shallotte.');
INSERT INTO public.stormevents_east VALUES (787305, 201809, 9, 1231, 201809, 10, 1355, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 12:31:00', 'EST-5', '10-SEP-18 13:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'LONG', 1, 'NE', 'LONG', 39.6756, -78.7916, 39.6755, -78.7907, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'The USGS stream gage on Wills Creek near Cumberland exceeded the 10 foot flood stage during the indicated period. This caused flooding of a car wash at Motor City, with water in parking lots in the same area. The peak level of 11.57 feet was observed at 4:45pm EST on the 9th.');
INSERT INTO public.stormevents_east VALUES (787300, 201809, 10, 2321, 201809, 12, 152, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '10-SEP-18 23:21:00', 'EST-5', '12-SEP-18 01:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'E', 'KENWOOD', 0, 'N', 'KENWOOD', 38.9501, -77.1268, 38.9569, -77.131, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'The USGS stream gage on the Potomac River at Little Falls Dam exceeded the 10 foot flood stage during the indicated period, flooding low lying areas and trails on the Maryland side of the river, especially near Chain Bridge. The peak level of 10.85 feet occurred at 1:30pm EST on the 11th.');
INSERT INTO public.stormevents_east VALUES (787336, 201809, 12, 1810, 201809, 12, 2010, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '12-SEP-18 18:10:00', 'EST-5', '12-SEP-18 20:10:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'LISBON', 1, 'NE', 'DAISY', 39.3152, -77.0524, 39.3148, -77.0511, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'Carrs Mill Road was flooded near Bush Park Road due to high water.');
INSERT INTO public.stormevents_east VALUES (784686, 201809, 17, 1106, 201809, 17, 1306, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 11:06:00', 'EST-5', '17-SEP-18 13:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'LOVINGSTON', 1, 'N', 'FABER', 37.799, -78.88, 37.8495, -78.749, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Numerous roads were closed due to flooding in Nelson County.');
INSERT INTO public.stormevents_east VALUES (784687, 201809, 17, 1106, 201809, 17, 1608, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 11:06:00', 'EST-5', '17-SEP-18 16:08:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ADIAL', 1, 'N', 'ADIAL', 37.8694, -78.8236, 37.8692, -78.821, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The stream gauge on Rockfish River crested at 13.2 feet, above the flood stage of 12 feet. Water covered a portion of Route 617 near the river. Also, nearby fields were flooded.');
INSERT INTO public.stormevents_east VALUES (784688, 201809, 17, 1130, 201809, 17, 1330, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 11:30:00', 'EST-5', '17-SEP-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'FREE UNION', 2, 'SSE', 'FREE UNION', 38.1369, -78.5599, 38.1377, -78.5577, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The stream gauge at Morrmans River near Free Union indicated that minor flooding occurred when it crested above the flood stage of 14 feet.');
INSERT INTO public.stormevents_east VALUES (784689, 201809, 17, 1139, 201809, 17, 1339, 131152, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '17-SEP-18 11:39:00', 'EST-5', '17-SEP-18 13:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'FARMINGTON', 2, 'N', 'RUGBY', 38.0681, -78.5247, 38.0439, -78.3285, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'Several roads were closed in Albemarle County.');
INSERT INTO public.stormevents_east VALUES (769694, 201807, 3, 1645, 201807, 3, 1700, 128295, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'FFC', '03-JUL-18 16:45:00', 'EST-5', '03-JUL-18 17:00:00', 0, 0, 0, 0, '10.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 3, 'SW', 'LOGAN', 2, 'ENE', 'BRICKHOUSE', 33.6918, -82.7288, 33.6863, -82.7434, 'With a warm and very moist air mass over the area, an upper-level trough moving across the region produced scattered severe thunderstorms from the afternoon into the overnight hours.', 'The Wilkes County Emergency Manager reported multiple trees and power lines blown down along Lundburg Road and Branham Road south of Washington. One tree fell onto and destroyed a well house at a home on Branham Road.');
INSERT INTO public.stormevents_east VALUES (796292, 201812, 14, 700, 201812, 15, 700, 133106, 'VIRGINIA', 51, 2018, 'December', 'Heavy Rain', 'RNK', '14-DEC-18 07:00:00', 'EST-5', '15-DEC-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 1, 'NW', 'ENONVILLE', 1, 'NW', 'ENONVILLE', 37.5083, -78.5333, 37.5083, -78.5333, 'A widespread rain event occurred December 15-16 as a closed upper low and associated surface system tracked from the lower Mississippi Valley across the mid-Atlantic region. This brought two-day rain amounts  ranging  from  0.75  to  1.50  inches,  with  isolated  amounts over  2  inches.  Some  river  flooding  ensued due to the rain and snowmelt runoff, primarily along the Dan and lower Roanoke (Staunton) rivers. Minor to low-end moderate  flooding occurred from  Danville  downstream  to  South  Boston  and  from  Brookneal  to  Randolph  on  the  Roanoke  (Staunton) River.', 'The COOP station at Buckingham (BUKV2) reported 1.35 inches for the 24-hours ending at 700 AM local time which was the highest on record for December 15th. The old record was 0.81 inches in 1981. Continuous climate records at this station began in 1950.');
INSERT INTO public.stormevents_east VALUES (793070, 201812, 21, 1008, 201812, 21, 1224, 132550, 'NEW JERSEY', 34, 2018, 'December', 'Flash Flood', 'OKX', '21-DEC-18 10:08:00', 'EST-5', '21-DEC-18 12:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'BOGOTA', 1, 'NNW', 'BOGOTA', 40.8769, -74.0338, 40.8774, -74.0337, 'Low pressure moving up the spine of the Appalachians resulted in widespread heavy rainfall and reports of flash flooding across portions of northeast New Jersey. A record high precipitable water value of 1.66 inches was recorded on the 12Z sounding from Upton, NY. Rainfall amounts across the region ranged from 1.5 to 3. A CoCoRaHS observer near West Milford reported 2.94 inches of rain from this event, while a trained spotter in Westwood reported 2.66 inches. The ASOS at Newark Airport recorded 1.76 inches of rain.', 'All lanes were closed in both directions on West Ford Lee Road between River Road and Elm Avenue due to flooding in Bogota.');
INSERT INTO public.stormevents_east VALUES (775291, 201809, 6, 1755, 201809, 6, 1755, 129394, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '06-SEP-18 17:55:00', 'EST-5', '06-SEP-18 17:55:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 1, 'E', 'MILL GREEN', 1, 'E', 'MILL GREEN', 39.67, -76.31, 39.67, -76.31, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which became severe.', 'A tree was blown down on Macton Road at the Broad Creek bridge. A tree was also blown down in the 1800 block of Deep Run Road.');
INSERT INTO public.stormevents_east VALUES (787205, 201809, 17, 1615, 201809, 21, 100, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 16:15:00', 'EST-5', '21-SEP-18 01:00:00', 0, 0, 0, 0, '3.63M', '20.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 7, 'SSE', 'NORWOOD', 6, 'SE', 'NORWOOD', 35.1409, -80.0755, 35.1733, -80.052, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Heavy rainfall of 6 to 8 inches caused widespread flooding across the county. Combined with additional rainfall upstream, the rainfall caused all-time record major flooding along the Rocky River near Norwood. Flooding damaged approximately 142 structures throughout the county, destroying 3 and resulting in over $3.63 million in property damage and at least $20 million in crop damage. Numerous roads were flooded all throughout the county. The Rocky River overflowed the Highway 52 bridge and reached the base of the Plank Road bridge.');
INSERT INTO public.stormevents_east VALUES (787733, 201809, 17, 1615, 201809, 19, 1510, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 16:15:00', 'EST-5', '19-SEP-18 15:10:00', 0, 0, 0, 0, '21.07M', '10.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'WSW', 'PINSON', 6, 'SSE', 'CHEEKS', 35.5056, -80.0662, 35.5148, -79.5569, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 8 to 10 inches caused widespread flooding across the county. Additional rainfall upstream caused moderate flooding along the Deep River near Ramseur. Significant flooding also ocurred all along the Deep River and Uwharrie River and their tributaries. Flooding damaged approximately 286 structures throughout the county, destroying 12 and resulting in over $21.07 million in property damage. Numerous roads were closed due to flooding. Numerous homes and businesses were flooded as well. While final losses on crops are not yet tallied, estimates around $10 million or more are possible.');
INSERT INTO public.stormevents_east VALUES (793072, 201812, 21, 1100, 201812, 21, 1224, 132550, 'NEW JERSEY', 34, 2018, 'December', 'Flood', 'OKX', '21-DEC-18 11:00:00', 'EST-5', '21-DEC-18 12:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'ROCHELLE PARK', 0, 'S', 'ROCHELLE PARK', 40.8879, -74.083, 40.8935, -74.0806, 'Low pressure moving up the spine of the Appalachians resulted in widespread heavy rainfall and reports of flash flooding across portions of northeast New Jersey. A record high precipitable water value of 1.66 inches was recorded on the 12Z sounding from Upton, NY. Rainfall amounts across the region ranged from 1.5 to 3. A CoCoRaHS observer near West Milford reported 2.94 inches of rain from this event, while a trained spotter in Westwood reported 2.66 inches. The ASOS at Newark Airport recorded 1.76 inches of rain.', 'Local emergency management reported that the Saddle River in Lodi reached its flood stage.');
INSERT INTO public.stormevents_east VALUES (793076, 201812, 21, 1154, 201812, 21, 1224, 132550, 'NEW JERSEY', 34, 2018, 'December', 'Flood', 'OKX', '21-DEC-18 11:54:00', 'EST-5', '21-DEC-18 12:24:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'LODI', 1, 'E', 'LODI', 40.8808, -74.0831, 40.8815, -74.086, 'Low pressure moving up the spine of the Appalachians resulted in widespread heavy rainfall and reports of flash flooding across portions of northeast New Jersey. A record high precipitable water value of 1.66 inches was recorded on the 12Z sounding from Upton, NY. Rainfall amounts across the region ranged from 1.5 to 3. A CoCoRaHS observer near West Milford reported 2.94 inches of rain from this event, while a trained spotter in Westwood reported 2.66 inches. The ASOS at Newark Airport recorded 1.76 inches of rain.', 'Main Street in Lodi is closed at Route 46 due to flooding from the Saddle River.');
INSERT INTO public.stormevents_east VALUES (756427, 201805, 15, 1544, 201805, 15, 1544, 126186, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'ALY', '15-MAY-18 15:44:00', 'EST-5', '15-MAY-18 15:44:00', 0, 0, 0, 0, '210.00K', NULL, 'Broadcast Media', 70, 'EG', NULL, NULL, 0, 'SW', 'LANESVILLE', 0, 'SW', 'LANESVILLE', 41.5274, -73.4238, 41.5274, -73.4238, 'Severe thunderstorms impacted portions of Litchfield County during the afternoon of May 15th. A supercell thunderstorm crossed northern portions of the county, resulting in hail up to two inches in diameter, two confirmed tornadoes, and straight-line wind damage. Later in the afternoon, a severe thunderstorm resulted in wind damage across far southern portions of the county. Numerous power outages and several road closures occurred as a result of the storms.', 'Several large trees were snapped or uprooted. Some roads were impassable. Shingles were torn off of New Milford High School.');
INSERT INTO public.stormevents_east VALUES (756428, 201805, 15, 1551, 201805, 15, 1551, 126186, 'CONNECTICUT', 9, 2018, 'May', 'Thunderstorm Wind', 'ALY', '15-MAY-18 15:51:00', 'EST-5', '15-MAY-18 15:51:00', 0, 0, 0, 0, '139.00K', NULL, 'Emergency Manager', 60, 'EG', NULL, NULL, 1, 'NNW', 'BRIDGE WATER', 1, 'NNW', 'BRIDGE WATER', 41.5427, -73.3804, 41.5427, -73.3804, 'Severe thunderstorms impacted portions of Litchfield County during the afternoon of May 15th. A supercell thunderstorm crossed northern portions of the county, resulting in hail up to two inches in diameter, two confirmed tornadoes, and straight-line wind damage. Later in the afternoon, a severe thunderstorm resulted in wind damage across far southern portions of the county. Numerous power outages and several road closures occurred as a result of the storms.', 'Twenty residences in the town of Bridgewater were damaged due to falling trees. One lane of Curtis Road was closed between Route 67 and Hat Shop Hill Road due to fallen wires.');
INSERT INTO public.stormevents_east VALUES (789113, 201812, 1, 2325, 201812, 1, 2325, 131909, 'WEST VIRGINIA', 54, 2018, 'December', 'Thunderstorm Wind', 'RLX', '01-DEC-18 23:25:00', 'EST-5', '01-DEC-18 23:25:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'SSW', 'MOUNTAIN', 2, 'SSW', 'MOUNTAIN', 39.3308, -80.933, 39.3308, -80.933, 'A cold front crossed the region late on the 1st, kicking off showers and thunderstorms. One of these storms became severe with localized wind damage.', 'Power lines were blown down at the intersection of Route 74 and Haddox Run Road northeast of Pennsboro.');
INSERT INTO public.stormevents_east VALUES (786269, 201809, 16, 1530, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '16-SEP-18 15:30:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 0, 'ESE', 'RICHFIELD', 2, 'NE', 'BADIN', 35.4676, -80.262, 35.4178, -80.0909, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 10 to 15 inches caused widespread flash flooding across the county.  Numerous roads throughout the county were closed, due to flooding. Several homes and businesses were flooded as well.');
INSERT INTO public.stormevents_east VALUES (775290, 201809, 6, 1630, 201809, 6, 1630, 129393, 'WEST VIRGINIA', 54, 2018, 'September', 'Thunderstorm Wind', 'LWX', '06-SEP-18 16:30:00', 'EST-5', '06-SEP-18 16:30:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 4, 'NNE', 'WILLIAMSPORT', 4, 'NNE', 'WILLIAMSPORT', 39.25, -79.01, 39.25, -79.01, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which became severe.', 'A few trees were blown down on Patterson Creek Road near the Mineral County line.');
INSERT INTO public.stormevents_east VALUES (775294, 201809, 6, 1915, 201809, 6, 1915, 129394, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '06-SEP-18 19:15:00', 'EST-5', '06-SEP-18 19:15:00', 0, 0, 0, 0, NULL, NULL, 'AWOS', 52, 'MG', NULL, NULL, 1, 'N', 'BALTIMORE MARTIN ST', 1, 'N', 'BALTIMORE MARTIN ST', 39.34, -76.42, 39.34, -76.42, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which became severe.', 'A 52 knot thunderstorm wind gust was measured at KMTN.');
INSERT INTO public.stormevents_east VALUES (775295, 201809, 7, 1755, 201809, 7, 1755, 129395, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '07-SEP-18 17:55:00', 'EST-5', '07-SEP-18 17:55:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'WNW', 'CLARKSVILLE', 2, 'WNW', 'CLARKSVILLE', 39.21, -76.91, 39.21, -76.91, 'A pair of surface cold fronts interacted with a moist and warm unstable air mass to generate showers and thunderstorms. One thunderstorm became severe.', 'A tree was blown down in the 6400 block of South Wind Circle.');
INSERT INTO public.stormevents_east VALUES (775296, 201809, 19, 1535, 201809, 19, 1535, 129396, 'VIRGINIA', 51, 2018, 'September', 'Hail', 'LWX', '19-SEP-18 15:35:00', 'EST-5', '19-SEP-18 15:35:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 1, 'N', 'GILBERT', 1, 'N', 'GILBERT', 38.14, -78.37, 38.14, -78.37, 'A weakening front combined with a weak disturbance to generate an isolated severe thunderstorm in the late afternoon hours.', 'Hail up to the size of quarters fell at this location.');
INSERT INTO public.stormevents_east VALUES (775297, 201809, 19, 1535, 201809, 19, 1535, 129396, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '19-SEP-18 15:35:00', 'EST-5', '19-SEP-18 15:35:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 60, 'EG', NULL, NULL, 2, 'SE', 'GILBERT', 2, 'SE', 'GILBERT', 38.1154, -78.3471, 38.1154, -78.3471, 'A weakening front combined with a weak disturbance to generate an isolated severe thunderstorm in the late afternoon hours.', 'Multiple large trees were blown down, some onto wires, concentrated near the intersection of Turkey Sag Road and Stony Point Road.');
INSERT INTO public.stormevents_east VALUES (778266, 201809, 26, 1540, 201809, 26, 1540, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 15:40:00', 'EST-5', '26-SEP-18 15:40:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'ESE', 'CAVETOWN', 2, 'ESE', 'CAVETOWN', 39.64, -77.54, 39.64, -77.54, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down on Pleasant Valley Road near the intersection of Foxville Road.');
INSERT INTO public.stormevents_east VALUES (796461, 201812, 21, 1900, 201812, 21, 2200, 133115, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'RNK', '21-DEC-18 19:00:00', 'EST-5', '21-DEC-18 22:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'RICHLANDS', 1, 'E', 'RICHLANDS', 37.0971, -81.802, 37.0975, -81.8003, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'Allegheny Street closed due to flooding from Big Creek between Third and Fourth Streets.');
INSERT INTO public.stormevents_east VALUES (796480, 201812, 20, 2120, 201812, 21, 320, 133115, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'RNK', '20-DEC-18 21:20:00', 'EST-5', '21-DEC-18 03:20:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'KERRS CREEK', 1, 'NNE', 'KERRS CREEK', 37.86, -79.51, 37.8601, -79.5174, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'Kerrs Creek was reported out of its banks and flooding Muddy Lane at West Midland Trail.');
INSERT INTO public.stormevents_east VALUES (764024, 201806, 3, 1925, 201806, 3, 1955, 126780, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '03-JUN-18 19:25:00', 'EST-5', '03-JUN-18 19:55:00', 0, 0, 0, 0, '16.00K', NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 1, 'ESE', 'LORANE', 2, 'NNW', 'SKIPPERTON', 32.917, -83.755, 32.7833, -83.7118, 'An upper-level short wave moving across the region, combined with moderate instability and ample moisture over the state resulted in widespread thunderstorms over north and central Georgia. numerous reports of damaging wind gusts were received from across central and portions of north Georgia.', 'The Bibb County Emergency Manager reported numerous trees and a few power lines blown down across the county from the far north just southeast of Bolingbroke, across the city of Macon.');
INSERT INTO public.stormevents_east VALUES (792053, 201812, 2, 940, 201812, 2, 940, 131758, 'GEORGIA', 13, 2018, 'December', 'Thunderstorm Wind', 'TAE', '02-DEC-18 09:40:00', 'EST-5', '02-DEC-18 09:40:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'N', 'POWELLTOWN', 1, 'N', 'POWELLTOWN', 31.4111, -83.78, 31.4111, -83.78, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'A light pole blew down on Meadows Road and damaged a car.');
INSERT INTO public.stormevents_east VALUES (792056, 201812, 3, 130, 201812, 3, 530, 131758, 'GEORGIA', 13, 2018, 'December', 'Flash Flood', 'TAE', '03-DEC-18 01:30:00', 'EST-5', '03-DEC-18 05:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'KINDERLOU', 6, 'SW', 'NAYLOR', 30.8, -83.37, 30.8374, -83.1376, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'Flooding was reported across several dirt roads throughout Lowndes county.');
INSERT INTO public.stormevents_east VALUES (792054, 201812, 2, 1330, 201812, 2, 1330, 131758, 'GEORGIA', 13, 2018, 'December', 'Flood', 'TAE', '02-DEC-18 13:30:00', 'EST-5', '02-DEC-18 13:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'DAKOTA', 1, 'NNW', 'WORTH', 31.76, -83.68, 31.7608, -83.6776, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'Water from a nearby creek affected a home with flooding.');
INSERT INTO public.stormevents_east VALUES (782583, 201809, 18, 800, 201809, 18, 1200, 130779, 'NEW HAMPSHIRE', 33, 2018, 'September', 'Flash Flood', 'GYX', '18-SEP-18 08:00:00', 'EST-5', '18-SEP-18 12:00:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Local Official', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'DERRY', 2, 'NNW', 'DERRY', 42.8955, -71.3296, 42.8925, -71.3325, 'A moisture-laden area of low pressure produced 4 to 6 inches of rain in 6 hours in southern New Hampshire.', 'A moisture-laden area of low pressure produced 4 to 6 inches of rain in 6 hours resulting in flooding of 4 businesses on Tinkham Avenue in Derry. Seven people were rescued by boat and 15 cars were submerged.');
INSERT INTO public.stormevents_east VALUES (773322, 201807, 26, 1217, 201807, 26, 1217, 128910, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '26-JUL-18 12:17:00', 'EST-5', '26-JUL-18 12:17:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 52, 'MG', NULL, NULL, 1, 'N', '(ARB)ANN ARBOR MUNI', 1, 'N', '(ARB)ANN ARBOR MUNI', 42.23, -83.75, 42.23, -83.75, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', NULL);
INSERT INTO public.stormevents_east VALUES (773323, 201807, 26, 1255, 201807, 26, 1255, 128910, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '26-JUL-18 12:55:00', 'EST-5', '26-JUL-18 12:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'SW', 'RIVERVIEW', 1, 'SW', 'RIVERVIEW', 42.17, -83.19, 42.17, -83.19, 'Severe thunderstorms tracked close to I-94 in Washtenaw and Wayne counties.', 'A trained spotter estimated a 60 mph thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (773325, 201807, 26, 1407, 201807, 26, 1407, 128973, 'LAKE ERIE', 95, 2018, 'July', 'Marine Thunderstorm Wind', 'DTX', '26-JUL-18 14:07:00', 'EST-5', '26-JUL-18 14:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 40, 'MG', NULL, NULL, 1, 'N', 'DETROIT RIVER LIGHT', 1, 'N', 'DETROIT RIVER LIGHT', 42.01, -83.14, 42.01, -83.14, 'A thunderstorm moving through Lake Erie produced a 40 knot gust.', NULL);
INSERT INTO public.stormevents_east VALUES (773330, 201807, 1, 1534, 201807, 1, 1534, 128975, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '01-JUL-18 15:34:00', 'EST-5', '01-JUL-18 15:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 3, 'N', 'CHERRY HILL', 3, 'N', 'CHERRY HILL', 42.34, -83.53, 42.34, -83.53, 'A severe thunderstorm producing wind damage impacted the Canton area, with another severe storm hitting Rochester.', 'Two small trees were reported blown down.');
INSERT INTO public.stormevents_east VALUES (786953, 201809, 28, 809, 201809, 28, 1009, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 08:09:00', 'EST-5', '28-SEP-18 10:09:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'CALVERTON', 2, 'NNW', 'CALVERTON', 38.6517, -77.678, 38.6521, -77.6789, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'Bastable Mill Road was closed near Brookfield Drive due to flooding.');
INSERT INTO public.stormevents_east VALUES (790349, 201812, 20, 1435, 201812, 20, 1435, 132089, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'MLB', '20-DEC-18 14:35:00', 'EST-5', '20-DEC-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 45, 'MG', NULL, NULL, 9, 'NE', 'PLAYALINDA BEACH', 9, 'NE', 'PLAYALINDA BEACH', 28.63, -80.66, 28.63, -80.66, 'The Storm Prediction Center issued an Enhanced Risk of severe weather for most of east central Florida. A strengthening low pressure system was moving across the southeastern U.S. with a strong cold front extending southwest across the Gulf of Mexico. A potent jet stream moved towards Florida with winds of 125 knots (approximately 145 mph), at the same time a low-level jet situated along the cold front moved over the Florida peninsula with winds of 50-60 knots (55-70 mph). The rapid increase and turning of winds with height in the atmosphere led to very high shear and helicity values over Florida. Also, a surge of moisture and daytime heating led to an increase in instability over east central Florida that helped strong to severe storms develop. By early morning, a squall line of thunderstorms began to move onshore in west central Florida and quickly push east across the peninsula. As this line of showers and storms approached the east central Florida coastline, it produced numerous reports of strong to severe wind gusts from Volusia County south through Martin County.', 'US Air Force wind tower 3132 measured a peak wind gust of 45 knots from the southwest.');
INSERT INTO public.stormevents_east VALUES (778273, 201809, 26, 1805, 201809, 26, 1805, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 18:05:00', 'EST-5', '26-SEP-18 18:05:00', 0, 0, 0, 0, NULL, NULL, 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'SW', 'GLEN BURNIE PARK', 1, 'SW', 'GLEN BURNIE PARK', 39.14, -76.64, 39.14, -76.64, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A large tree limb was blown down onto a house near the intersection of Burton Road and Baylor Road.');
INSERT INTO public.stormevents_east VALUES (790350, 201812, 20, 1438, 201812, 20, 1438, 132089, 'ATLANTIC SOUTH', 87, 2018, 'December', 'Marine Thunderstorm Wind', 'MLB', '20-DEC-18 14:38:00', 'EST-5', '20-DEC-18 14:38:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'NNW', 'MELBOURNE', 2, 'NNW', 'MELBOURNE', 28.101, -80.612, 28.101, -80.612, 'The Storm Prediction Center issued an Enhanced Risk of severe weather for most of east central Florida. A strengthening low pressure system was moving across the southeastern U.S. with a strong cold front extending southwest across the Gulf of Mexico. A potent jet stream moved towards Florida with winds of 125 knots (approximately 145 mph), at the same time a low-level jet situated along the cold front moved over the Florida peninsula with winds of 50-60 knots (55-70 mph). The rapid increase and turning of winds with height in the atmosphere led to very high shear and helicity values over Florida. Also, a surge of moisture and daytime heating led to an increase in instability over east central Florida that helped strong to severe storms develop. By early morning, a squall line of thunderstorms began to move onshore in west central Florida and quickly push east across the peninsula. As this line of showers and storms approached the east central Florida coastline, it produced numerous reports of strong to severe wind gusts from Volusia County south through Martin County.', 'The ASOS at the Melbourne International Airport (KMLB) measured a peak wind gust of 34 knots from the west.');
INSERT INTO public.stormevents_east VALUES (760158, 201806, 13, 1745, 201806, 13, 1800, 126783, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '13-JUN-18 17:45:00', 'EST-5', '13-JUN-18 18:00:00', 0, 0, 0, 0, '3.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'SE', 'GARRETTA', 4, 'NW', 'LOWERY', 32.4395, -82.9153, 32.3971, -82.8429, 'A moist and somewhat unstable airmass across the region resulted in scattered afternoon and evening thunderstorms. Isolated severe thunderstorms occurred along a weak stationary front over central Georgia.', 'The Laurens County Emergency Manager reported trees blown down from Scotland Road and Robertson Church Road to around the intersection of Highway 19 and South Poplar Springs Road.');
INSERT INTO public.stormevents_east VALUES (760166, 201806, 14, 1600, 201806, 14, 1615, 126783, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '14-JUN-18 16:00:00', 'EST-5', '14-JUN-18 16:15:00', 0, 0, 0, 0, '4.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 2, 'SSE', 'JORDAN', 4, 'N', 'SPRING HILL', 32.0047, -82.6631, 32.0687, -82.7288, 'A moist and somewhat unstable airmass across the region resulted in scattered afternoon and evening thunderstorms. Isolated severe thunderstorms occurred along a weak stationary front over central Georgia.', 'The Wheeler County Emergency Manager reported trees blown down from around St. Paul Church Road and Opossum Road to Hope Church Road near Springhill Road.');
INSERT INTO public.stormevents_east VALUES (778274, 201809, 26, 1543, 201809, 26, 1543, 129927, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 15:43:00', 'EST-5', '26-SEP-18 15:43:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'W', 'JOLIVUE', 1, 'W', 'JOLIVUE', 38.1, -79.1, 38.1, -79.1, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down at the intersection of Old Greenville Road and Cochrans Mill Road.');
INSERT INTO public.stormevents_east VALUES (786501, 201809, 16, 1404, 201809, 16, 1900, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 14:04:00', 'EST-5', '16-SEP-18 19:00:00', 0, 0, 0, 0, '30.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 4, 'NE', 'BUIE', 3, 'NE', 'BUIE', 34.76, -79.1, 34.7598, -79.105, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Snipes road was completely washed out near McQueen Road.');
INSERT INTO public.stormevents_east VALUES (786502, 201809, 16, 1016, 201809, 16, 1500, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 10:16:00', 'EST-5', '16-SEP-18 15:00:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'WSW', 'LUMBERTON MUNI ARPT', 3, 'WSW', 'LUMBERTON MUNI ARPT', 34.59, -79.11, 34.5915, -79.1153, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Interstate 95 North was closed at the overpass for US-74.');
INSERT INTO public.stormevents_east VALUES (788088, 201809, 28, 743, 201809, 29, 321, 131432, 'WEST VIRGINIA', 54, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 07:43:00', 'EST-5', '29-SEP-18 03:21:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'NW', 'ROCK GAP', 2, 'W', 'ROCK GAP', 39.57, -78.3169, 39.5341, -78.3192, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.', 'The water level along the Cacapon River at Great Cacapon surpassed flood stage of 9 feet. The water crested at 11.44 feet on September 28th at 3:45 PM EST. Rock Ford Road begins to flood in multiple locations, including flowing completely over the low water bridge. Constant Run Road also begins to flood.  Running Waters Way flooded along with Kilgore Road.');
INSERT INTO public.stormevents_east VALUES (784856, 201809, 15, 2348, 201809, 15, 2358, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '15-SEP-18 23:48:00', 'EST-5', '15-SEP-18 23:58:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'WSW', 'MYRTLE GROVE', 1, 'S', 'CLARENDON', 34.1161, -77.9231, 34.1574, -77.9829, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'A tornado touched down in the Elliot Place neighborhood on River Vista|Drive, snapping approximately 15-20 hardwood trees up to 18 in diameter.|The tornado moved northwest and across the Cape Fear River. It caused|minor tree damage, breaking out a few limbs as it lifted near NC 133 in |the vicinity of Pleasant Oaks Plantation Road.');
INSERT INTO public.stormevents_east VALUES (786998, 201809, 28, 830, 201809, 28, 1707, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 08:30:00', 'EST-5', '28-SEP-18 17:07:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 3, 'SSW', 'ADEN', 3, 'SSW', 'ADEN', 38.6179, -77.5568, 38.6145, -77.5541, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'The stream gage on Cedar Run near Aden exceeded the 10 foot flood stage during the indicated period, flooding Fleetwood Road. The peak level of 10.49 feet occurred at 1:57pm EST.');
INSERT INTO public.stormevents_east VALUES (778276, 201809, 26, 1635, 201809, 26, 1635, 129927, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:35:00', 'EST-5', '26-SEP-18 16:35:00', 0, 0, 0, 0, NULL, NULL, 'State Official', 50, 'EG', NULL, NULL, 2, 'NE', 'CORDOVA', 2, 'NE', 'CORDOVA', 38.55, -78.01, 38.55, -78.01, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down on Dutch Hollow Road near Alum Spring Road. A tree was also blown down on Shiloh Church Road near Ryland Chapel Road.');
INSERT INTO public.stormevents_east VALUES (786773, 201809, 15, 1354, 201809, 15, 1845, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 13:54:00', 'EST-5', '15-SEP-18 18:45:00', 0, 0, 0, 0, '200.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'E', 'SOUTHPORT', 2, 'SW', 'SEASIDE', 33.9258, -77.9802, 33.8613, -78.5109, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Hwy 17 was closed in both directions at the Town Creek Bridge between I-140 and NC-87.  Hwy 211 was closed near Stone Chimney Rd near Sunset Beach.  Hwy 211 was also closed near Dosher Cutoff. Jabbertown Rd was closed near E Leonard St.  Hwy 17 closed near Ocean Isle Beach. Bethel Rd closed near Cagney Lane.');
INSERT INTO public.stormevents_east VALUES (787199, 201809, 9, 726, 201809, 9, 926, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 07:26:00', 'EST-5', '09-SEP-18 09:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'CROFTON', 1, 'ESE', 'CROFTON', 38.9896, -76.638, 38.9931, -76.6366, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'MD-455 Defense Highway was closed due to flooding between Huntwood Drive and Rutland road.');
INSERT INTO public.stormevents_east VALUES (787250, 201809, 9, 922, 201809, 9, 1122, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 09:22:00', 'EST-5', '09-SEP-18 11:22:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'ALLEGANY', 1, 'NNE', 'ALLEGANY', 39.68, -78.9, 39.6797, -78.894, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'MD-36 Mount Savage Road northwest was closed due to flooding near MD-638.');
INSERT INTO public.stormevents_east VALUES (787361, 201809, 10, 1101, 201809, 12, 1303, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '10-SEP-18 11:01:00', 'EST-5', '12-SEP-18 13:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 4, 'SW', 'WHITES FERRY', 4, 'SW', 'WHITES FERRY', 39.1558, -77.5211, 39.1558, -77.5186, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'The USGS stream gage on the Potomac River at Edwards Ferry exceeded the 15 foot flood stage during the indicated period. The peak level of 20.31 feet occurred at 10:15am EST on the 11th. Several parking lots along the C&O Canal were flooded, along with the store at Whites Ferry and the basements of lockhouses along the C&O Canal.');
INSERT INTO public.stormevents_east VALUES (784842, 201809, 15, 2342, 201809, 15, 2347, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '15-SEP-18 23:42:00', 'EST-5', '15-SEP-18 23:47:00', 0, 0, 0, 0, '50.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'W', 'EAST WILMINGTON', 1, 'W', 'NEW BERN JCT', 34.2176, -77.9007, 34.2511, -77.9319, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'A tornado touched down near the intersection of Floral Parkway and |Park Avenue, causing minor tree damage as it moved quickly northwest.|Damage became more severe as it passed east and north of Empie Park,|where a few pine trees up to 18 inches in diameter were snapped, and|numerous large limbs broken. A nearly continuous path of tree damage |was observed as the tornado continued northwest across the Forest |Hills community and 23rd Street between Market Street and Princess|Place Drive. This area also received significant tree damage during |the landfall of Hurricane Florence, however the path of the tornado|was discernible by observing damage limited primarily to broken and |twisted limbs amongst tree tops. The heavy damage to large oak trees |in Forest Hills and on 23rd Street was apparently a result of the|hurricane, and not the tornado. The tornado moved northwest, crossing |Princess Place Drive and snapping several trees up to 10 inches in|diameter, along with numerous limbs along 21st Street and the |intersection with Klein Road. The tornado broke large limbs from a few|trees along Wynnwood Street in the Love Grove community before lifting.');
INSERT INTO public.stormevents_east VALUES (787040, 201809, 28, 125, 201809, 28, 1031, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 01:25:00', 'EST-5', '28-SEP-18 10:31:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSE', 'MT CRAWFORD', 2, 'SSE', 'MT CRAWFORD', 38.3459, -78.9213, 38.3457, -78.9173, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'The USGS stream gage on North River near Burketown exceeded the 11 foot flood stage during the indicated period. The peak level of 13.29 feet occurred at 5:30am EST.');
INSERT INTO public.stormevents_east VALUES (786422, 201809, 28, 242, 201809, 28, 442, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:42:00', 'EST-5', '28-SEP-18 04:42:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'NE', 'PECKTONVILLE', 2, 'NE', 'PECKTONVILLE', 39.6906, -78.0207, 39.69, -78.021, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The 10400 block of Catholic Church Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786423, 201809, 28, 244, 201809, 28, 444, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 02:44:00', 'EST-5', '28-SEP-18 04:44:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'CORBETT', 0, 'ENE', 'CORBETT', 39.6325, -77.7252, 39.6323, -77.7253, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'West Memorial Boulevard was closed at the railroad underpass due to flooding.');
INSERT INTO public.stormevents_east VALUES (786426, 201809, 28, 343, 201809, 28, 543, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:43:00', 'EST-5', '28-SEP-18 05:43:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'PARK MILLS', 2, 'E', 'PARK MILLS', 39.3019, -77.3854, 39.3011, -77.3856, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The 8100 block of Peters Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (786440, 201809, 28, 345, 201809, 28, 545, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:45:00', 'EST-5', '28-SEP-18 05:45:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'BOLIVAR', 1, 'SE', 'BOLIVAR', 39.4591, -77.5817, 39.4593, -77.5824, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'Shank Road was closed at Alternate Route 40 due to flooding.');
INSERT INTO public.stormevents_east VALUES (798914, 201812, 28, 623, 201812, 28, 800, 133536, 'TENNESSEE', 47, 2018, 'December', 'Flood', 'MRX', '28-DEC-18 06:23:00', 'EST-5', '28-DEC-18 08:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'SW', 'GATLINBURG', 3, 'NW', 'PIGEON FORGE', 35.6995, -83.5452, 35.8107, -83.5879, 'An unseasonably humid regime featured moisture intrusion from the Gulf of Mexico ahead of an approaching cold front, and a southwesterly flow aloft. Localized heavy rainfall mainly south of the I-40 corridor produced flooding.', 'Several flooded roadways were noted from Pigeon Forge to Gatlinburg.');
INSERT INTO public.stormevents_east VALUES (787208, 201809, 17, 1415, 201809, 25, 1545, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flood', 'RAH', '17-SEP-18 14:15:00', 'EST-5', '25-SEP-18 15:45:00', 0, 0, 0, 0, '20.93M', '30.00M', 'Emergency Manager', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 7, 'S', 'SEVEN SPGS', 5, 'ENE', 'NEW HOPE', 35.1362, -77.8646, 35.3944, -77.8036, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 15 to 20 inches upstream caused major flooding along the Neuse River Basin. Flooding damaged approximately 1,482 structures throughout the county, resulting in over $20.93 million in property damage, and over $30 million in crop damage. Numerous streets and roads were reported flooded.');
INSERT INTO public.stormevents_east VALUES (778272, 201809, 26, 1732, 201809, 26, 1732, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 17:32:00', 'EST-5', '26-SEP-18 17:32:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'N', 'BRINKLOW', 1, 'N', 'BRINKLOW', 39.18, -77.02, 39.18, -77.02, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down on MD Route 650 near Haviland Mill Road.');
INSERT INTO public.stormevents_east VALUES (787579, 201810, 10, 1432, 201810, 10, 1436, 131655, 'GEORGIA', 13, 2018, 'October', 'Tornado', 'FFC', '10-OCT-18 14:32:00', 'EST-5', '10-OCT-18 14:36:00', 0, 0, 0, 0, '5.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'S', 'VLY VIEW ORCHARD', 1, 'SW', 'STATE COLLEGE', 32.4955, -83.8795, 32.5195, -83.8916, 'Hurricane Michael made landfall along the Florida panhandle at Mexico beach (just southeast of Panama City) on the afternoon of October 10, 2018 as a high-end Category 4 hurricane (max winds of 155 MPH). Michael then moved rapidly inland, causing widespread wind damage along its path as it swept northeast across south and central Georgia. Hurricane Michael was the first major hurricane, category 3 or higher, to directly impact Georgia since the 1890s. In southwest Georgia, wind gusts as high as 115 mph were recorded. Within the NWS Atlanta/Peachtree City county warning area, wind gusts of 40-60 MPH, with some gusts over 70 mph, across portions of central Georgia on the evening of October 10th into the morning of October 11th led to widespread tree damage and power outages with damage to numerous structures. Severe crop damage was also reported, especially to cotton and pecan crops, as well as devastating impacts to commercial timberland. In addition, a few brief tornadoes in the outer bands of Michael caused isolated damage in portions of the north and central Georgia while heavy rainfall led to localized flooding. Michael quickly exited the state as a tropical storm late on the morning of October 11th.', 'A National Weather Service survey determined that an EF0 tornado with maximum wind speeds of 70-75 MPH and a maximum path width of 100 yards traveled north northwest along Carver Drive for 1.8 miles snapping a few pine trees. [10/10/18: Tornado #1, County #1/1, EF-0, Peach, 2018:012].');
INSERT INTO public.stormevents_east VALUES (786183, 201809, 16, 2319, 201809, 16, 2332, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'RAH', '16-SEP-18 23:19:00', 'EST-5', '16-SEP-18 23:32:00', 0, 0, 0, 0, '250.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'S', 'HIGHSMITHS', 2, 'SSW', 'SALEMBURG', 34.903, -78.504, 34.992, -78.527, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'A tornado associated with tropical cylcone Florence touched  |down during the early morning of September 17th, just southeast  |of Roseboro. This tornado continued on the ground for roughly 13  |minutes mostly impacting trees, farm buildings, and eventually a  |car dealership within the city of Roseboro. The storm continued to |weaken as it pushed northwest, crossing highway 24, and  |continuing to produce intermittent tree damage prior to lifting  |southwest of Salemburg. Property damages were estimated.');
INSERT INTO public.stormevents_east VALUES (793085, 201812, 21, 1255, 201812, 21, 1325, 132552, 'CONNECTICUT', 9, 2018, 'December', 'Flash Flood', 'OKX', '21-DEC-18 12:55:00', 'EST-5', '21-DEC-18 13:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'MERIDEN', 2, 'ENE', 'MERIDEN', 41.5344, -72.7685, 41.5355, -72.769, 'Low pressure moving up the spine of the Appalachians resulted in widespread heavy rainfall and reports of flash flooding across portions of southern Connecticut. A record high precipitable water value of 1.66 inches was recorded on the 12Z sounding from Upton, NY. Rainfall amounts across the region ranged from 1.5 to 4.5. A CoCoRaHS observer near Bedford reported 4.33 inches of rain from this event, while a CoCoRaHS observer near Prospect reported 4.02 inches. The ASOS at Bridgeport Airport recorded 1.97 inches of rain.', 'Route 15 was closed northbound at Exit 68W in Meriden due to flooding.');
INSERT INTO public.stormevents_east VALUES (793088, 201812, 21, 1430, 201812, 21, 1500, 132552, 'CONNECTICUT', 9, 2018, 'December', 'Flash Flood', 'OKX', '21-DEC-18 14:30:00', 'EST-5', '21-DEC-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'BETHEL', 1, 'S', 'BETHEL', 41.3566, -73.4181, 41.3571, -73.4184, 'Low pressure moving up the spine of the Appalachians resulted in widespread heavy rainfall and reports of flash flooding across portions of southern Connecticut. A record high precipitable water value of 1.66 inches was recorded on the 12Z sounding from Upton, NY. Rainfall amounts across the region ranged from 1.5 to 4.5. A CoCoRaHS observer near Bedford reported 4.33 inches of rain from this event, while a CoCoRaHS observer near Prospect reported 4.02 inches. The ASOS at Bridgeport Airport recorded 1.97 inches of rain.', 'Route 53 was closed at Sympaug Park Road in Bethel due to flooding.');
INSERT INTO public.stormevents_east VALUES (793098, 201812, 21, 1530, 201812, 22, 415, 132550, 'NEW JERSEY', 34, 2018, 'December', 'Flood', 'OKX', '21-DEC-18 15:30:00', 'EST-5', '22-DEC-18 04:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'MAHWAH', 1, 'W', 'MAHWAH', 41.0983, -74.1649, 41.0989, -74.1629, 'Low pressure moving up the spine of the Appalachians resulted in widespread heavy rainfall and reports of flash flooding across portions of northeast New Jersey. A record high precipitable water value of 1.66 inches was recorded on the 12Z sounding from Upton, NY. Rainfall amounts across the region ranged from 1.5 to 3. A CoCoRaHS observer near West Milford reported 2.94 inches of rain from this event, while a trained spotter in Westwood reported 2.66 inches. The ASOS at Newark Airport recorded 1.76 inches of rain.', 'The Ramapo River near Mahwah rose above its flood stage of 8.0 feet at 3:30pm EST, crested at a height of 8.12 feet at 11:00pm EST, and fell back below flood stage at 4:15am EST on December 22.');
INSERT INTO public.stormevents_east VALUES (786261, 201809, 15, 1330, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '15-SEP-18 13:30:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'SW', 'ELDORADO', 1, 'NE', 'STEEDS', 35.4557, -80.046, 35.4848, -79.782, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 10 to 15 inches caused widespread flash flooding across the county. The heavy rains caused several creeks to overspill their banks.  Numerous roads throughout the county were closed, due to flooding, with two culverts washed out on River Road and Mullinix Road.  Numerous homes and businesses were flooded as well.');
INSERT INTO public.stormevents_east VALUES (778267, 201809, 26, 1612, 201809, 26, 1612, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:12:00', 'EST-5', '26-SEP-18 16:12:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'LOYS', 1, 'N', 'LOYS', 39.61, -77.35, 39.61, -77.35, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'Power lines were blown down at the 14000 block of Old Frederick Road.');
INSERT INTO public.stormevents_east VALUES (778268, 201809, 26, 1619, 201809, 26, 1619, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:19:00', 'EST-5', '26-SEP-18 16:19:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'BETHEL', 1, 'N', 'BETHEL', 39.51, -77.45, 39.51, -77.45, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down at the 10300 block of Putnam Road.');
INSERT INTO public.stormevents_east VALUES (778269, 201809, 26, 1637, 201809, 26, 1637, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:37:00', 'EST-5', '26-SEP-18 16:37:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 1, 'ENE', 'MT PLEASANT', 1, 'ENE', 'MT PLEASANT', 39.46, -77.31, 39.46, -77.31, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down across Liberty Road near the intersection of Old Annapolis Road.');
INSERT INTO public.stormevents_east VALUES (778270, 201809, 26, 1650, 201809, 26, 1650, 129925, 'MARYLAND', 24, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:50:00', 'EST-5', '26-SEP-18 16:50:00', 0, 0, 0, 0, NULL, NULL, 'Department of Highways', 50, 'EG', NULL, NULL, 2, 'ENE', 'UNIONVILLE', 2, 'ENE', 'UNIONVILLE', 39.49, -77.15, 39.49, -77.15, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down across New Windsor Road between Oak Orchard Road and Hemp Avenue.');
INSERT INTO public.stormevents_east VALUES (798665, 201812, 20, 1710, 201812, 20, 1712, 133487, 'NORTH CAROLINA', 37, 2018, 'December', 'Tornado', 'ILM', '20-DEC-18 17:10:00', 'EST-5', '20-DEC-18 17:12:00', 0, 0, 0, 0, '30.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WSW', 'MASONBORO', 2, 'ENE', 'SOUTH WILMINGTON', 34.1738, -77.8812, 34.1762, -77.8862, 'A warm front and a deep upper trough west of the area produced a tornado.', 'A tornado formed just west of Sutton Dr. along Waltmoor Rd in the Oxford|place area of Wilmington. The tornado moved northwest between Waltmoor Rd |and Archer Dr. The tornado lifted just prior to reaching Pinecliff Dr. It |primarily caused damage to numerous trees and knocked down several fences. |However, the tornado uprooted trees onto at least three homes along Waltmoor |Rd and onto a minivan on Archer Dr. In addition, the tornado flipped over |a large wooden shed and knocked a small boat onto its side.');
INSERT INTO public.stormevents_east VALUES (798725, 201812, 21, 1145, 201812, 21, 1745, 133115, 'VIRGINIA', 51, 2018, 'December', 'Flood', 'RNK', '21-DEC-18 11:45:00', 'EST-5', '21-DEC-18 17:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'REAVISTOWN', 1, 'WSW', 'REAVISTOWN', 36.62, -80.99, 36.6197, -80.992, 'Another southern stream dominated system emerged from the southwestern U.S. with a complex surface low tracking from the Gulf Coast into the southern Mid-Atlantic December 20-22. This was again an all liquid event, with 2-day rainfall totals (ending 700 AM local time on 12/22) ranging from 1 to 4 inches with isolated higher amounts mainly along and near the Blue Ridge. The top five rainfall reports in southwest Virginia in this period included Jones Creek IFLOWS (JOEV2) 4.34 inches, Fancy Gap IFLOWS (FYGV2) 4.10 inches, Glasgow 1 SE COOP (GLAV2) 4.06 inches, Trappers Lodge IFLOWS (TRAV2) 3.71 inches and Pipers Gaps IFLOWS (PPGV2) 3.71 inches. Flooding very similar in magnitude and location to the mid-December event occurred with most of the Dan and lower Roanoke (Staunton) again reaching minor to low-end moderate flood levels. Minor flooding also occurred along portions of the New River with the gage at Alisonia (ALSV2) reaching minor flood stage of 8 feet in the evening of the 21st flooding a few roads near the river. In addition, a number of areal Flood Advisories and Warnings were issued for numerous counties after reports of flooded roads were received mainly on the evening of the 20th.', 'A spotter reported water flowing across Old Baywood Road.');
INSERT INTO public.stormevents_east VALUES (773331, 201807, 1, 1536, 201807, 1, 1536, 128975, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '01-JUL-18 15:36:00', 'EST-5', '01-JUL-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'SW', 'PLYMOUTH', 2, 'SW', 'PLYMOUTH', 42.35, -83.5, 42.35, -83.5, 'A severe thunderstorm producing wind damage impacted the Canton area, with another severe storm hitting Rochester.', 'Several large tree limbs were reported down.');
INSERT INTO public.stormevents_east VALUES (773778, 201807, 31, 2345, 201807, 31, 2345, 127984, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '31-JUL-18 23:45:00', 'EST-5', '31-JUL-18 23:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'SW', 'ECORSE', 1, 'SW', 'ECORSE', 42.24, -83.18, 42.24, -83.18, 'After an abnormally dry July across lower Michigan, a low pressure system lifted up from the Ohio Valley and moved through extreme southeastern Michigan and brought some much needed rainfall. Showers on the afternoon and evening of July 31 and became heavier into the nighttime hours. As the center of the low pressure interacted with the marine layer over western Lake Erie shortly after midnight, a brief tornado formed over Wayne County despite relatively weak winds aloft. Heavy rain bands and thunderstorm activity resulted in rainfall totals near 4 inches in several locations while many more areas around the Metro Detroit area received 1-3 inches, prompting a Flash Flood Warning for the urban areas as most of the rainfall occurred over a period of 3 hours or less. A couple feet of water were reported over roadways in Dearborn Heights and Taylor during the early morning hours.', 'A trained spotter estimated a 60 mph thunderstorm wind gust.');
INSERT INTO public.stormevents_east VALUES (785941, 201809, 18, 203, 201809, 18, 403, 131153, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 02:03:00', 'EST-5', '18-SEP-18 04:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'KEMP MILL', 1, 'S', 'KEMP MILL', 39.0161, -77.0166, 39.0145, -77.0174, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'US-29 Colesville Road was blocked by high water near I-495 Capital Beltway.');
INSERT INTO public.stormevents_east VALUES (764407, 201806, 25, 1434, 201806, 25, 1438, 126788, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '25-JUN-18 14:34:00', 'EST-5', '25-JUN-18 14:38:00', 1, 0, 1, 0, '20.00K', NULL, 'Emergency Manager', 55, 'EG', NULL, NULL, 3, 'SSW', 'LASSITER', 3, 'SSW', 'LASSITER', 33.4676, -83.8719, 33.4676, -83.8719, 'A weak upper-level wave moving across the state resulted in widespread strong to severe thunderstorms across north and central Georgia.', 'The Newton County Emergency Manager reported that dozens of trees were blown down at the Bert Adams Boy Scout Camp south of Covington. One of the trees fell onto a tent occupied by two scouts. A 14 year old male camper was killed by the falling tree while the other teenaged occupant escaped with only minor injuries.');
INSERT INTO public.stormevents_east VALUES (744977, 201805, 4, 1209, 201805, 4, 1209, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:09:00', 'EST-5', '04-MAY-18 12:09:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 59, 'EG', NULL, NULL, 1, 'S', 'STONY CREEK', 1, 'S', 'STONY CREEK', 42.69, -83.12, 42.69, -83.12, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'Multiple large trees blown down.');
INSERT INTO public.stormevents_east VALUES (760910, 201806, 23, 1334, 201806, 23, 1344, 126787, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '23-JUN-18 13:34:00', 'EST-5', '23-JUN-18 13:44:00', 0, 0, 0, 0, '1.00K', NULL, 'Broadcast Media', 45, 'EG', NULL, NULL, 2, 'ESE', 'PAYNE CITY', 2, 'ESE', 'PAYNE CITY', 32.8652, -83.6741, 32.8652, -83.6741, 'Persistent warm and unstable airmass over the region resulted in widespread afternoon and evening thunderstorms each day, with several reports of damaging thunderstorm wind gusts.', 'A local television station reported a large tree blown down at the intersection of Stinsonville Road and Captain Kell Drive.');
INSERT INTO public.stormevents_east VALUES (760916, 201806, 23, 1435, 201806, 23, 1450, 126787, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '23-JUN-18 14:35:00', 'EST-5', '23-JUN-18 14:50:00', 0, 0, 0, 0, '4.00K', NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'WSW', 'CHOESTOE', 2, 'WSW', 'CHOESTOE', 34.7671, -83.9181, 34.7671, -83.9181, 'Persistent warm and unstable airmass over the region resulted in widespread afternoon and evening thunderstorms each day, with several reports of damaging thunderstorm wind gusts.', 'The Union County 911 center reported multiple trees blown down along Highway 129 at Vogel State Park.');
INSERT INTO public.stormevents_east VALUES (785948, 201809, 18, 1531, 201809, 18, 1731, 131153, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '18-SEP-18 15:31:00', 'EST-5', '18-SEP-18 17:31:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RAYNOR HGTS', 2, 'WSW', 'RAYNOR HGTS', 39.2147, -76.7019, 39.2136, -76.7007, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'A vehicle was stalled in flowing water over the road on Furnace Avenue near Race road. Deep Run was out of its banks.');
INSERT INTO public.stormevents_east VALUES (784962, 201809, 16, 1230, 201809, 16, 1630, 131188, 'SOUTH CAROLINA', 45, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 12:30:00', 'EST-5', '16-SEP-18 16:30:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'NE', 'RED BLUFF', 2, 'NE', 'RED BLUFF', 33.92, -78.81, 33.919, -78.8131, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed. The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. Particulars for South Carolina: Fatalities: 9, Homes with major damage: 543.  Coastal evacuations: 455,000 evacuated. Power outages: 187,000. Population shelters: 68 with occupancy of 7500 at its peak. Cost: About 600 million dollars. In Marlboro County alone 34 state/56 county roads were damaged.', 'The Polo Farms subdivision was flooded.');
INSERT INTO public.stormevents_east VALUES (784868, 201809, 16, 1529, 201809, 16, 1530, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Tornado', 'ILM', '16-SEP-18 15:29:00', 'EST-5', '16-SEP-18 15:30:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'WSW', 'PURVIS', 0, 'WNW', 'PURVIS', 34.5789, -79.2565, 34.5822, -79.2569, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'A tornado touched down south of SR 1134 and moved north, breaking|limbs from a few tree tops before crossing an open field. A stand of |half a dozen large oak trees on the north side of SR 1134 sustained |significant damage, with numerous large limbs broken out. One large |oak broke off near ground level. The tornado continued north across |open field, then broke limbs out of the tops of trees before lifting.');
INSERT INTO public.stormevents_east VALUES (786510, 201809, 16, 1324, 201809, 16, 1800, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '16-SEP-18 13:24:00', 'EST-5', '16-SEP-18 18:00:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'NNW', 'WHITEVILLE', 1, 'NNW', 'WHITEVILLE', 34.35, -78.71, 34.3486, -78.7104, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Heavy rain caused more flash flooding on Hwy, 74, 76, and Andrew Jackson Hwy.');
INSERT INTO public.stormevents_east VALUES (787251, 201809, 9, 1030, 201809, 9, 1230, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 10:30:00', 'EST-5', '09-SEP-18 12:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'ARUNDEL GARDENS', 1, 'WSW', 'ARUNDEL GARDENS', 39.198, -76.6368, 39.1971, -76.6327, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'Furnace Branch Road was closed due to flooding near Ritchie Street.');
INSERT INTO public.stormevents_east VALUES (787253, 201809, 9, 1328, 201809, 9, 1528, 131606, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '09-SEP-18 13:28:00', 'EST-5', '09-SEP-18 15:28:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'NEW WINDSOR', 1, 'SW', 'NEW WINDSOR', 39.5434, -77.1068, 39.5436, -77.107, 'Low pressure tracked to the west while a nearly stationary boundary was to the south. Warm and moist tropical air overran the surface cooler air in place, resulting in a moderate to heavy rainfall. Excess runoff from the rainfall led to flooding. One and a half to three inches of rain fell across northern Maryland late on the 8th into the 9th, followed by another one to three inches on the 9th into the 10th. This combination produced fairly widespread flooding, including of the mainstem rivers, which continued through the 11th and into the 12th.', 'MD-31 Main Street was closed due to flooding near Union Bridge Road.');
INSERT INTO public.stormevents_east VALUES (786493, 201809, 15, 1442, 201809, 15, 1900, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 14:42:00', 'EST-5', '15-SEP-18 19:00:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 4, 'NW', 'SMITHS', 4, 'NW', 'SMITHS', 34.6909, -78.8998, 34.6863, -78.9068, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Howell Road near Regan Church Road is impassable.');
INSERT INTO public.stormevents_east VALUES (786499, 201809, 15, 2143, 201809, 15, 2345, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 21:43:00', 'EST-5', '15-SEP-18 23:45:00', 0, 0, 0, 0, '10.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 2, 'ESE', 'OAKLAND', 1, 'SE', 'OAKLAND', 34.82, -78.92, 34.8196, -78.9338, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Shaw Mill road was impassable near Dean Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (786500, 201809, 15, 2158, 201809, 16, 100, 130719, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'ILM', '15-SEP-18 21:58:00', 'EST-5', '16-SEP-18 01:00:00', 0, 0, 0, 0, '20.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 1, 'N', 'LUMBERTON', 1, 'WNW', 'LUMBERTON', 34.6345, -79, 34.6281, -79.0192, 'Hurricane Florence began its long Atlantic trek from the Cape Verde Islands in early September. It made landfall near Wrightsville Beach during the morning of September 14th. The barometric pressure at landfall was 959 millibars, or 28.32 inches.The strongest winds were recorded at 106 mph at Cape Lookout, as well as 105 mph measured at the Wilmington International Airport.  In addition to the strong storm surge, there was historic rainfall totals of 20 to 25 inches, with isolated totals of 35 inches in parts of Bladen and Robeson counties. Flash Flooding was severe and widespread, with many communities experiencing flooding for the first time. River flooding was epic, with dozens of main highways impassible. Significant flooding occurred for weeks after the storm had departed.  The hurricane spawned 19 tornadoes, one causing significant damage to 8 structures in the Sydney community in Columbus county. The community at Lake Waccamaw experienced more damage than Hurricane Floyd in 1999, the previous benchmark for the area. In Pender County, over 6000 structures had damage, with 2800 structures suffered major damage or were destroyed altogether. Damage estimates from wind and water are in the tens of billions of dollars, making it one of the costliest hurricanes ever.', 'Interstate 95 was closed between exit 19 and exit 22.');
INSERT INTO public.stormevents_east VALUES (782586, 201809, 18, 1022, 201809, 18, 1125, 130779, 'NEW HAMPSHIRE', 33, 2018, 'September', 'Flood', 'GYX', '18-SEP-18 10:22:00', 'EST-5', '18-SEP-18 11:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Official NWS Observations', NULL, NULL, 'Heavy Rain', NULL, 1, 'SE', 'PINE VLY', 1, 'SE', 'PINE VLY', 42.8424, -71.7063, 42.8427, -71.7063, 'A moisture-laden area of low pressure produced 4 to 6 inches of rain in 6 hours in southern New Hampshire.', 'A moisture-laden area of low pressure produced 4 to 6 inches of rain in 6 hours causing the Souhegan River at Milford to flood briefly.  The river crested at 9.17 feet.  Flood stage is 9 feet.');
INSERT INTO public.stormevents_east VALUES (784238, 201809, 26, 1816, 201809, 26, 1821, 131102, 'ATLANTIC NORTH', 88, 2018, 'September', 'Marine Thunderstorm Wind', 'LWX', '26-SEP-18 18:16:00', 'EST-5', '26-SEP-18 18:21:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 37, 'MG', NULL, NULL, 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 0, 'N', 'POTOMAC LIGHT 33 (LT3)', 38.34, -76.99, 38.34, -76.99, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which produced strong winds over the waters.', 'A wind gust of 37 knots was measured at Potomac Light 33 (LT3).');
INSERT INTO public.stormevents_east VALUES (784236, 201809, 6, 1936, 201809, 6, 1936, 131101, 'ATLANTIC NORTH', 88, 2018, 'September', 'Marine Thunderstorm Wind', 'LWX', '06-SEP-18 19:36:00', 'EST-5', '06-SEP-18 19:36:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'MG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'High amounts of instability and an approaching cold front combined to produce scattered showers and thunderstorms during the afternoon and evening, some of which produced strong winds over the waters.', 'A wind gust of 34 knots was measured at Tolchester (TCBM2).');
INSERT INTO public.stormevents_east VALUES (788108, 201809, 28, 459, 201809, 28, 737, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 04:59:00', 'EST-5', '28-SEP-18 07:37:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'RAPIDAN', 1, 'NW', 'RAPIDAN', 38.32, -78.1, 38.3273, -78.0772, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'The water level at Robinson River surpassed flood stage of 11 feet, cresting at 11.56 feet at 06:15 AM September 28th. ||Water covered a portion of Route 721. Agricultural flooding also took place nearby.');
INSERT INTO public.stormevents_east VALUES (788071, 201809, 28, 120, 201809, 29, 111, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 01:20:00', 'EST-5', '29-SEP-18 01:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'WSW', 'RAYNOR HGTS', 1, 'NNE', 'RAYNOR HGTS', 39.2115, -76.6957, 39.2315, -76.662, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The stream gauge on the Patapsco River at Elkridge exceeded the 16 foot flood stage during the indicated period. Hammonds Ferry Road flooded and was closed at the Patapsco River. Backwater flooding led to the closure of Furnace Avenue in Elkridge. The peak level of 20.29 feet occurred at 10:40 AM on the 28th.');
INSERT INTO public.stormevents_east VALUES (788077, 201809, 28, 637, 201809, 29, 3, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 06:37:00', 'EST-5', '29-SEP-18 00:03:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'E', 'FAIRVIEW', 2, 'ESE', 'FAIRVIEW', 39.7173, -77.8212, 39.7133, -77.823, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The stream gauge along the Conocochague Creek surpassed the flood stage of 10 feet. the gauge crested at 11.08 feet at 1:00 PM EST September 28th. Wishard Road and Kemp Mill Road were both flooded.');
INSERT INTO public.stormevents_east VALUES (788093, 201809, 28, 126, 201809, 29, 434, 131433, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 01:26:00', 'EST-5', '29-SEP-18 04:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'MT MERIDIAN', 2, 'SSW', 'MT MERIDIAN', 38.2492, -78.8681, 38.2508, -78.884, 'A warm front moved through the area during the early morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat. Some of the flooding persisted on larger streams into the 29th.', 'The water level at Grottoes on the Middle River passed flood stage of 12 feet. The water crested at 15.71 feet at 6:30 PM, September 28th. ||Fields along the river were to flooded.');
INSERT INTO public.stormevents_east VALUES (787342, 201809, 18, 114, 201809, 18, 153, 131153, 'MARYLAND', 24, 2018, 'September', 'Flash Flood', 'LWX', '18-SEP-18 01:14:00', 'EST-5', '18-SEP-18 01:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'RELAY', 0, 'ESE', 'HALETHORPE', 39.2399, -76.6923, 39.2474, -76.6935, 'The remnants of Florence slowly tracked through the area on the 17th and 18th. Plenty of tropical moisture caused showers and thunderstorms to contain locally heavy rainfall, which led to instances of flooding.', 'The USGS stream gage on East Branch Herbert Run near Arbutus rapidly exceeded the 7 foot flood stage during the short period indicated. It rose a foot over flood stage within 20 minutes, peaking at 8.02 feet at 1:35 am EST. Yards near the stream flooded, with water up to the top of the culvert at Sulphur Spring Road.');
INSERT INTO public.stormevents_east VALUES (767655, 201807, 31, 2344, 201807, 31, 2346, 127984, 'MICHIGAN', 26, 2018, 'July', 'Tornado', 'DTX', '31-JUL-18 23:44:00', 'EST-5', '31-JUL-18 23:46:00', 0, 0, 0, 0, '50.00K', '0.00K', 'Emergency Manager', NULL, NULL, NULL, NULL, 1, 'S', 'TAYLOR CENTER', 2, 'SE', 'TAYLOR CENTER', 42.199, -83.2646, 42.199, -83.2489, 'After an abnormally dry July across lower Michigan, a low pressure system lifted up from the Ohio Valley and moved through extreme southeastern Michigan and brought some much needed rainfall. Showers on the afternoon and evening of July 31 and became heavier into the nighttime hours. As the center of the low pressure interacted with the marine layer over western Lake Erie shortly after midnight, a brief tornado formed over Wayne County despite relatively weak winds aloft. Heavy rain bands and thunderstorm activity resulted in rainfall totals near 4 inches in several locations while many more areas around the Metro Detroit area received 1-3 inches, prompting a Flash Flood Warning for the urban areas as most of the rainfall occurred over a period of 3 hours or less. A couple feet of water were reported over roadways in Dearborn Heights and Taylor during the early morning hours.', 'Brief tornado caused damage to a total of 3 buildings. Details include partial roof damage, displacement of a roof AC Unit, damage to a business sign, and some small tree damage. Emergency Management officials provided the details for this survey.');
INSERT INTO public.stormevents_east VALUES (786414, 201809, 6, 1018, 201809, 6, 1023, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 10:18:00', 'EST-5', '06-SEP-18 10:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'BRIDGTON', 1, 'W', 'BRIDGTON', 44.05, -70.71, 44.05, -70.71, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm downed numerous trees and power lines in Bridgton.');
INSERT INTO public.stormevents_east VALUES (786415, 201809, 6, 1030, 201809, 6, 1035, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 10:30:00', 'EST-5', '06-SEP-18 10:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'W', 'NAPLES', 1, 'W', 'NAPLES', 43.97, -70.61, 43.97, -70.61, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm downed trees and power lines in Naples.');
INSERT INTO public.stormevents_east VALUES (786416, 201809, 6, 1035, 201809, 6, 1040, 131437, 'MAINE', 23, 2018, 'September', 'Thunderstorm Wind', 'GYX', '06-SEP-18 10:35:00', 'EST-5', '06-SEP-18 10:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 1, 'N', 'CASCO', 1, 'N', 'CASCO', 44.01, -70.52, 44.01, -70.52, 'A cold front dropping south through the region produced a line of showers and thunderstorms as it moved into a very unstable airmass over the region. A strong squall line formed during the late morning as it moved into central and southern Maine producing numerous reports of wind damage all the way down to the coast.', 'A severe thunderstorm downed trees and power lines in Casco.');
INSERT INTO public.stormevents_east VALUES (786443, 201809, 28, 348, 201809, 28, 548, 131431, 'MARYLAND', 24, 2018, 'September', 'Flood', 'LWX', '28-SEP-18 03:48:00', 'EST-5', '28-SEP-18 05:48:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'N', 'CATOCTIN', 1, 'N', 'CATOCTIN', 39.3419, -77.5484, 39.3396, -77.5503, 'A warm front moved through the area during the morning hours of the 28th. Warm and moist air associated with a tropical air mass overran the relatively cooler air in place, resulting in heavy rainfall. Also, the steering flow aloft was weak so showers and thunderstorms were slow to move. This enhanced the flooding threat.  The resulting flooding moved into larger streams and rivers and continued through the 30th.', 'The 3500 Block of Sigler Road was closed due to flooding.');
INSERT INTO public.stormevents_east VALUES (772972, 201807, 16, 1525, 201807, 16, 1525, 128908, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '16-JUL-18 15:25:00', 'EST-5', '16-JUL-18 15:25:00', 0, 0, 0, 0, '2.00K', '0.00K', 'Trained Spotter', 52, 'EG', NULL, NULL, 1, 'SE', 'PORT HURON ARPT', 1, 'SE', 'PORT HURON ARPT', 43.01, -82.44, 43.01, -82.44, 'Isolated severe thunderstorms developed over Oakland and St. Clair counties.', 'Two trees was reported down, along with power lines.');
INSERT INTO public.stormevents_east VALUES (744999, 201805, 4, 1215, 201805, 4, 1215, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:15:00', 'EST-5', '04-MAY-18 12:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 56, 'EG', NULL, NULL, 1, 'W', 'HIGHLAND PARK', 1, 'W', 'HIGHLAND PARK', 42.4, -83.19, 42.4, -83.19, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'Trees reported down.');
INSERT INTO public.stormevents_east VALUES (772973, 201807, 16, 1536, 201807, 16, 1536, 128908, 'MICHIGAN', 26, 2018, 'July', 'Thunderstorm Wind', 'DTX', '16-JUL-18 15:36:00', 'EST-5', '16-JUL-18 15:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 51, 'MG', NULL, NULL, 1, 'SE', 'PORT HURON ARPT', 1, 'SE', 'PORT HURON ARPT', 43.01, -82.44, 43.01, -82.44, 'Isolated severe thunderstorms developed over Oakland and St. Clair counties.', NULL);
INSERT INTO public.stormevents_east VALUES (788350, 201812, 2, 922, 201812, 2, 928, 131758, 'GEORGIA', 13, 2018, 'December', 'Tornado', 'TAE', '02-DEC-18 09:22:00', 'EST-5', '02-DEC-18 09:28:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'W', 'OMEGA', 1, 'NNW', 'OMEGA', 31.339, -83.6184, 31.3595, -83.5979, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'A tornado touched down near Ty Ty Sparks Rd north of US 319 and traveled northeast across Flat Ford Rd and Keith-Fletcher Rd. The tornado lifted just after crossing Ty Ty Omega Rd. Damage was primarily confined to irrigation systems and trees. A substation sustained some damage as well. The tornado is rated EF0 with estimated maximum winds of 85 mph.');
INSERT INTO public.stormevents_east VALUES (788356, 201812, 3, 234, 201812, 3, 239, 131757, 'FLORIDA', 12, 2018, 'December', 'Tornado', 'TAE', '03-DEC-18 02:34:00', 'EST-5', '03-DEC-18 02:39:00', 0, 0, 0, 0, '25.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 3, 'NNE', 'HAMBURG', 4, 'NNW', 'CHERRY LAKE', 30.6087, -83.485, 30.6304, -83.459, 'A significant flooding and severe weather event unfolded over the tri-state area during early December as showers and thunderstorms spread northward across the area for multiple days.  The most noteworthy impact over the weekend was heavy precipitation. Widespread rainfall totals reached 5-7 inches throughout the area with some localized heavier amounts near 10 inches.  This resulted in flash flooding and river flooding across numerous counties.  In addition, five tornadoes touched down, including one in southeast Alabama, two in southwest Georgia, one in the Florida panhandle, and one in the Florida big bend.', 'An EF1 tornado with 100 mph winds touched down in Madison County early Monday morning. The path length was 2.17 miles. One mobile home was shifted off its blocks.  A small outbuilding was swept off its foundation and rolled several feet. Another mobile home nearby was shifted slightly and the blocks underneath are now tilted. Considerable tree damage was present throughout the path. There were no injuries or fatalities.');
INSERT INTO public.stormevents_east VALUES (775489, 201807, 29, 1011, 201807, 29, 1011, 129432, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'MFL', '29-JUL-18 10:11:00', 'EST-5', '29-JUL-18 10:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 6, 'SW', 'KEY BISCAYNE', 6, 'SW', 'KEY BISCAYNE', 25.71, -80.21, 25.71, -80.21, 'Light wind flow with a summertime pattern in place. Showers and storms over the Atlantic waters were able to develop and drift towards the coast. A few of these showers produced waterspouts in Biscayne bay and nearshore Atlantic waters. One of the stronger storms was able to produce gusty winds over Biscayne Bay.', 'A marine thunderstorm wind gust of 40 MPH / 35 knots was recorded by the WxFlow mesonet site XDIN located in Biscayne Bay.');
INSERT INTO public.stormevents_east VALUES (786248, 201809, 14, 1000, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '14-SEP-18 10:00:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 4, 'SSW', 'PARKERSBURG', 4, 'NNE', 'NEWTONS XRDS', 34.7782, -78.4658, 34.7271, -78.1395, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Torrential rainfall of 15 to 20 inches caused widespread flash flooding across the county. The heavy rains caused flash flooding on several creeks. At least 81 roads were covered by high water in the county, with  several road wash outs. Numerous homes and businesses were flooded as well. Sampson county emergency officials report that they were conducting multiple water rescues for swift water and that resources were becoming overwhelmed.');
INSERT INTO public.stormevents_east VALUES (787085, 201809, 1, 1600, 201809, 1, 1800, 131574, 'VIRGINIA', 51, 2018, 'September', 'Flash Flood', 'LWX', '01-SEP-18 16:00:00', 'EST-5', '01-SEP-18 18:00:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'SHENANDOAH', 1, 'NE', 'SHENANDOAH', 38.4924, -78.6198, 38.4918, -78.6195, 'A boundary remain stalled over the region and tropical moisture was in place. This caused locally heavy rainfall which led to instances of flooding and flash flooding.', 'Water was getting into houses on Junior Avenue. Two water rescues occurred with people trapped in vehicles due to high water.');
INSERT INTO public.stormevents_east VALUES (786262, 201809, 15, 1445, 201809, 17, 1114, 131166, 'NORTH CAROLINA', 37, 2018, 'September', 'Flash Flood', 'RAH', '15-SEP-18 14:45:00', 'EST-5', '17-SEP-18 11:14:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain / Tropical System', NULL, 3, 'WSW', 'CRUTCHFIELD XRDS', 4, 'NE', 'FARRINGTON', 35.7788, -79.4598, 35.8421, -78.9734, 'A ridge of high pressure over eastern North America stalled Florence''s forward motion a few miles off the southeast North Carolina coast on September 13th. Hurricane Florence made landfall near Wrightsville Beach early on Saturday September 15, and weakened further as it moved slowly inland.  Despite making landfall as a weakened|Category 1 hurricane, Florence still produced 40 to 70 mph wind gusts, enough wind speed to uproot trees and cause widespread power outages throughout the Carolinas.  As the storm moved inland, from September 15 to 17,  heavy rain of 10 to 25 inches  caused widespread inland flooding, inundating cities such as Fayetteville, Smithfield, Goldsboro, Durham, and Chapel Hill, and causing major river flooding on main-stem rivers such as the Neuse, Cape Fear, and Little River. Most major roads and highways in the area experienced some flooding, with large stretches of I-40 and I-95 remaining impassable for days after the storm had passed. The storm also spawned tornadoes in several places along its path. There were 3 direct and 6 indirect deaths attributed to the storm with in the WFO RAH CWA.', 'Heavy rainfall of 8 to 12 inches flooded numerous roads across the county. Several roads in are impassable due to flash flooding. This list includes but is not limited to U.S. 15-501 south at the Deep River, Morris Road between Parker Herndon Road and U.S. 15-501, Corinth Road between old U.S. 1 and Moncure Flatwood Road, Chatham Church Road at the bridge over the Rocky River, and R. Jordan Road near Rosser Road.');
INSERT INTO public.stormevents_east VALUES (787086, 201809, 1, 1650, 201809, 1, 1850, 131574, 'VIRGINIA', 51, 2018, 'September', 'Flood', 'LWX', '01-SEP-18 16:50:00', 'EST-5', '01-SEP-18 18:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'FREYCO', 2, 'SE', 'FREYCO', 39.2118, -78.0819, 39.212, -78.0844, 'A boundary remain stalled over the region and tropical moisture was in place. This caused locally heavy rainfall which led to instances of flooding and flash flooding.', 'Part of Jordan Springs Road was blocked by high water.');
