INSERT INTO public.stormevents_east VALUES (778278, 201809, 26, 1636, 201809, 26, 1636, 129927, 'VIRGINIA', 51, 2018, 'September', 'Thunderstorm Wind', 'LWX', '26-SEP-18 16:36:00', 'EST-5', '26-SEP-18 16:36:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'N', 'ANTIOCH', 1, 'N', 'ANTIOCH', 38.86, -77.68, 38.86, -77.68, 'A cold front moving into the region combined with with an unstable hot and humid air mass to generate showers and thunderstorms, some of which became severe.', 'A tree was blown down near the intersection of Mountain Road and Waterfall Road.');
