INSERT INTO public.stormevents_east VALUES (763851, 201806, 1, 1458, 201806, 1, 1520, 126778, 'GEORGIA', 13, 2018, 'June', 'Thunderstorm Wind', 'FFC', '01-JUN-18 14:58:00', 'EST-5', '01-JUN-18 15:20:00', 0, 0, 0, 0, '7.00K', NULL, 'Emergency Manager', 50, 'EG', NULL, NULL, 1, 'ENE', 'ELDER', 1, 'S', 'BEN DOWDY', 33.7758, -83.312, 33.8884, -83.4287, 'A series of fast moving upper-level short waves moving southeast out of the Ohio Valley brought two distinct rounds of thunderstorms into north Georgia, spreading south into portions of central Georgia. Numerous reports of damaging thunderstorm winds were received with isolated reports of flooding.', 'The Oconee County Emergency Manager reported trees blown down across the county from Hog Mountain Road south of Bogart to Hardin Hill Road and Colham Ferry Road in Watkinsville and Antioch Church Road east of Elder.');
INSERT INTO public.stormevents_east VALUES (744997, 201805, 4, 1234, 201805, 4, 1234, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:34:00', 'EST-5', '04-MAY-18 12:34:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 61, 'EG', NULL, NULL, 2, 'NNW', 'VIENNA', 2, 'NNW', 'VIENNA', 41.81, -83.49, 41.81, -83.49, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'Multiple trees and power poles blown down. Railroad crossing bars snapped off.');
INSERT INTO public.stormevents_east VALUES (744998, 201805, 4, 1214, 201805, 4, 1214, 123915, 'MICHIGAN', 26, 2018, 'May', 'Thunderstorm Wind', 'DTX', '04-MAY-18 12:14:00', 'EST-5', '04-MAY-18 12:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', 61, 'EG', NULL, NULL, 2, 'E', 'CLAWSON', 2, 'E', 'CLAWSON', 42.53, -83.1, 42.53, -83.1, 'A strong low pressure system tracked through northern Lower Michigan, swinging a strong cold front through southeast Michigan early in the afternoon. Sustained winds ranging between 30 - 40 mph, with frequent gusts in the 45 to 60 mph range, with scattered thunderstorms that developed leading to enhanced winds near 70 MPH. Downed large trees, branches, telephone and power lines were reported across all counties in Southeast Michigan, with around 230,000 customers without power during the peak. In Independence Township, a large tree fell onto a car, killing the 36 year old man inside. Additionally, a postal employee in South Lyon was also seriously hurt when a tree fell on him as well. A semi was also blown over in the strong winds on US 23, blocking all southbound lanes.', 'Roofing material blown off a Michaels Craft store.');
INSERT INTO public.stormevents_east VALUES (750450, 201805, 31, 200, 201805, 31, 359, 125122, 'LAKE HURON', 90, 2018, 'May', 'Marine Thunderstorm Wind', 'DTX', '31-MAY-18 02:00:00', 'EST-5', '31-MAY-18 03:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 52, 'MG', NULL, NULL, 0, 'N', 'GRAVELLY SHOALS LIGHT', 0, 'N', 'GRAVELLY SHOALS LIGHT', 44.02, -83.54, 44.02, -83.54, 'The remnants of Alberto and scattered thunderstorms impacted Saginaw Bay for a couple of hours, producing several gusts around 50 knots.', NULL);
