INSERT INTO public.stormevents_east VALUES (778651, 201808, 7, 1620, 201808, 7, 1625, 130007, 'MAINE', 23, 2018, 'August', 'Thunderstorm Wind', 'GYX', '07-AUG-18 16:20:00', 'EST-5', '07-AUG-18 16:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'NWS Employee', 50, 'EG', NULL, NULL, 0, 'ENE', 'INTERVALE', 0, 'ENE', 'INTERVALE', 43.952, -70.2629, 43.952, -70.2629, 'A very hot and humid air mass was in place over the region on the afternoon of August 7th with temperatures in the 90s and dew points in the lower 70s producing CAPE values up to 3000 J/KG. An upper trough approaching from the west brought increasing shear into the region as storms began developing in the afternoon. Multiple reports of wind damage were associated with these storms.', 'A severe thunderstorm downed a tree onto power lines in Intervale.');
