INSERT INTO public.stormevents_east VALUES (790469, 201810, 11, 2223, 201810, 12, 23, 131827, 'MARYLAND', 24, 2018, 'October', 'Flood', 'LWX', '11-OCT-18 22:23:00', 'EST-5', '12-OCT-18 00:23:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'CHANEYVILLE', 1, 'S', 'CHANEYVILLE', 38.6594, -76.6532, 38.6594, -76.6525, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Maryland, maximum sustained winds reached 38 mph, peak wind gusts reached 62 mph, and some rainfall totals were observed in excess of 6 inches.', 'MD-262 Lower Marlboro Road was closed due to flooding near Briscoe Turn Road.');
INSERT INTO public.stormevents_east VALUES (790601, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'NNE', 'DUNNSVILLE', 2, 'NNE', 'DUNNSVILLE', 37.8767, -76.816, 37.8767, -76.816, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 7.41 inches was reported at Dunnsville (2 NNE).');
INSERT INTO public.stormevents_east VALUES (790602, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWSS', NULL, NULL, NULL, NULL, 0, 'N', 'PALMYRA', 0, 'N', 'PALMYRA', 37.87, -78.28, 37.87, -78.28, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 6.72 inches was reported at Union Mills (1 S). Rainfall total of 3.43 inches was reported at the Palmyra River Gage.');
INSERT INTO public.stormevents_east VALUES (790603, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'N', 'ARK', 1, 'N', 'ARK', 37.4445, -76.58, 37.4445, -76.58, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 5.07 inches was reported at Ark (1 N).');
INSERT INTO public.stormevents_east VALUES (782503, 201810, 2, 1637, 201810, 2, 1637, 130766, 'WEST VIRGINIA', 54, 2018, 'October', 'Thunderstorm Wind', 'RLX', '02-OCT-18 16:37:00', 'EST-5', '02-OCT-18 16:37:00', 0, 0, 0, 0, '0.50K', '0.00K', '911 Call Center', 45, 'EG', NULL, NULL, 1, 'N', 'SARDIS', 1, 'N', 'SARDIS', 39.34, -80.42, 39.34, -80.42, 'The combination of an upper level shortwave trough and a stalled surface boundary produced strong to severe thunderstorms and isolated flash flooding across north central West Virginia on the 2nd.', 'A single tree was blown down along Sardis Road.');
INSERT INTO public.stormevents_east VALUES (790604, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'W', 'OILVILLE', 1, 'W', 'OILVILLE', 37.7, -77.7983, 37.7, -77.7983, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 2.04 inches was reported at Oilville (1 W).');
INSERT INTO public.stormevents_east VALUES (790606, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 2, 'S', 'PURDY', 2, 'S', 'PURDY', 36.7911, -77.58, 36.7911, -77.58, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 2.68 inches was reported at Cowie Corner (1 N).');
INSERT INTO public.stormevents_east VALUES (790698, 201810, 6, 2230, 201810, 7, 30, 132139, 'NEW YORK', 36, 2018, 'October', 'Flash Flood', 'BUF', '06-OCT-18 22:30:00', 'EST-5', '07-OCT-18 00:30:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'NW', 'LAWTONS', 1, 'WNW', 'LAWTONS', 42.543, -78.9357, 42.5362, -78.9362, 'A weakening surface low tracked northeast across Lake Huron during the afternoon hours with its corresponding warm front extending to the east across Lake Ontario then snaking south ahead of the higher terrain east of Syracuse. This placed all of western New York within the warm sector of the aforementioned storm system. Within this environment, a weak 30 kt low level jet was moving through the region. This helped to produce ample shear while instability increased in the warm sector of the system. A line of convection crossed Chautauqua and western Cattaraugus county, gradually increasing in intensity with time as it crossed the Southern Tier.  There were several reports of flooding issues with the thunderstorms, even though they were moving eastward fairly quickly. A second line of training thunderstorms developed again in evening and trained over the Southern Tier, resulting in additional flooding.', 'Flooding and debris was reported on Gowanda Road near Marshfield Road. Multiple other road closures were reported in the area of Collins. A creek was also reported out of its banks and flooding the nearby area.');
INSERT INTO public.stormevents_east VALUES (790701, 201810, 6, 2250, 201810, 7, 50, 132139, 'NEW YORK', 36, 2018, 'October', 'Flash Flood', 'BUF', '06-OCT-18 22:50:00', 'EST-5', '07-OCT-18 00:50:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'LAONA', 1, 'ENE', 'LILY DALE', 42.41, -79.3, 42.3525, -79.3038, 'A weakening surface low tracked northeast across Lake Huron during the afternoon hours with its corresponding warm front extending to the east across Lake Ontario then snaking south ahead of the higher terrain east of Syracuse. This placed all of western New York within the warm sector of the aforementioned storm system. Within this environment, a weak 30 kt low level jet was moving through the region. This helped to produce ample shear while instability increased in the warm sector of the system. A line of convection crossed Chautauqua and western Cattaraugus county, gradually increasing in intensity with time as it crossed the Southern Tier.  There were several reports of flooding issues with the thunderstorms, even though they were moving eastward fairly quickly. A second line of training thunderstorms developed again in evening and trained over the Southern Tier, resulting in additional flooding.', 'Flooding was reported on Route 60 between Bard Road and Porter Road.');
INSERT INTO public.stormevents_east VALUES (790710, 201810, 6, 1317, 201810, 6, 1317, 132139, 'NEW YORK', 36, 2018, 'October', 'Lightning', 'BUF', '06-OCT-18 13:17:00', 'EST-5', '06-OCT-18 13:17:00', 0, 0, 0, 0, '200.00K', '0.00K', 'Newspaper', NULL, NULL, NULL, NULL, 1, 'SW', 'DUELLS CORNER', 1, 'SW', 'DUELLS CORNER', 42.7442, -78.7384, 42.7442, -78.7384, 'A weakening surface low tracked northeast across Lake Huron during the afternoon hours with its corresponding warm front extending to the east across Lake Ontario then snaking south ahead of the higher terrain east of Syracuse. This placed all of western New York within the warm sector of the aforementioned storm system. Within this environment, a weak 30 kt low level jet was moving through the region. This helped to produce ample shear while instability increased in the warm sector of the system. A line of convection crossed Chautauqua and western Cattaraugus county, gradually increasing in intensity with time as it crossed the Southern Tier.  There were several reports of flooding issues with the thunderstorms, even though they were moving eastward fairly quickly. A second line of training thunderstorms developed again in evening and trained over the Southern Tier, resulting in additional flooding.', 'A lightning strike caused a fire that resulted in approximately $200,000 in damage to a home at 35 Lakeridge Drive in Orchard Park.');
INSERT INTO public.stormevents_east VALUES (790761, 201810, 11, 2045, 201810, 12, 115, 132141, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 20:45:00', 'EST-5', '12-OCT-18 01:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'ESE', 'WARSAW', 2, 'SE', 'WARSAW', 37.96, -76.75, 37.953, -76.7473, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Several roads were flooded across the county with water rescues reported.');
INSERT INTO public.stormevents_east VALUES (790763, 201810, 11, 2106, 201810, 12, 30, 132141, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 21:06:00', 'EST-5', '12-OCT-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'ENE', 'ST STEPHENS CHURCH', 1, 'ENE', 'ST STEPHENS CHURCH', 37.81, -77.03, 37.8094, -77.03, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Route 360 was closed at Green Chambers Road due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (790764, 201810, 11, 2110, 201810, 12, 115, 132141, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 21:10:00', 'EST-5', '12-OCT-18 01:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'DUNBROOKE', 1, 'ENE', 'DUNBROOKE', 37.9, -76.95, 37.904, -76.9477, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Route 620 was closed at Sunnyside Road due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (790765, 201810, 11, 2130, 201810, 12, 115, 132141, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 21:30:00', 'EST-5', '12-OCT-18 01:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'DIASCUND', 3, 'SSW', 'DIASCUND', 37.3704, -76.8957, 37.3665, -76.898, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Route 737 was flooded at Otey Drive.');
INSERT INTO public.stormevents_east VALUES (790766, 201810, 11, 2200, 201810, 12, 30, 132141, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 22:00:00', 'EST-5', '12-OCT-18 00:30:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'NEW KENT', 1, 'S', 'NEW KENT', 37.52, -76.98, 37.5119, -76.979, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Numerous roads throughout the county were impassable due to flash flooding.');
INSERT INTO public.stormevents_east VALUES (783909, 201810, 11, 600, 201810, 12, 600, 131036, 'NORTH CAROLINA', 37, 2018, 'October', 'Heavy Rain', 'RNK', '11-OCT-18 06:00:00', 'EST-5', '12-OCT-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 6, 'E', 'YADKINVILLE', 6, 'E', 'YADKINVILLE', 36.13, -80.5625, 36.13, -80.5625, 'As the direct storm circulation from Michael approached in the early morning hours of October 11, rainfall and strong winds began first in Watauga County in northwest NC, and progressed north and east through the day.  In addition, a cold front moving in from the west and interacted with the storm and enhanced rainfall, especially over the eastern counties.  Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, from the mountains of North Carolina across the foothills and piedmont.  Much of the rain fell in a 3 to 6 hour period,  resulting in widespread, significant flash flooding and river flooding in all the NC counties of the Blacksburg WFO area of responsibility.  In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Wind speeds were observed strongest across the higher terrain from the Blue Ridge westward, where 40 to 50 mph gusts were observed.  Winds speeds further east were generally lower as the storm continued to weaken along its eastward track.  Many trees and power lines were blown down in the water logged soil across the northern portion of North Carolina, resulting in blocked roads and numerous power outages. The state of North Carolina included the following counties located within the Blacksburg WFO area in north central NC in a request (December 12, 2018) for a federal disaster declaration as a result of Tropical Storm Michael: Caswell, Rockingham, Stokes, Surry and Yadkin. The outcome of the request was not available at this writing.', 'The COOP observer at Yadkinville 6 E (YKNN7) measured 4.11 inches for the 24-hour period ending 700 AM local time, October 12. This was the 2nd highest 24-hour rainfall in the month of October at this station, behind October 11, 1990 at 4.50 inches and the 11th highest all-time daily rainfall. Nearly complete records date back to 1940 at this station. Most of the rain actually fell in a much shorter time period, between 3 and 6 hours.');
INSERT INTO public.stormevents_east VALUES (790826, 201810, 11, 1545, 201810, 12, 545, 131036, 'NORTH CAROLINA', 37, 2018, 'October', 'Flood', 'RNK', '11-OCT-18 15:45:00', 'EST-5', '12-OCT-18 05:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 2, 'NW', 'SPRAY', 2, 'NW', 'SPRAY', 36.5412, -79.7721, 36.5409, -79.7697, 'As the direct storm circulation from Michael approached in the early morning hours of October 11, rainfall and strong winds began first in Watauga County in northwest NC, and progressed north and east through the day.  In addition, a cold front moving in from the west and interacted with the storm and enhanced rainfall, especially over the eastern counties.  Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, from the mountains of North Carolina across the foothills and piedmont.  Much of the rain fell in a 3 to 6 hour period,  resulting in widespread, significant flash flooding and river flooding in all the NC counties of the Blacksburg WFO area of responsibility.  In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Wind speeds were observed strongest across the higher terrain from the Blue Ridge westward, where 40 to 50 mph gusts were observed.  Winds speeds further east were generally lower as the storm continued to weaken along its eastward track.  Many trees and power lines were blown down in the water logged soil across the northern portion of North Carolina, resulting in blocked roads and numerous power outages. The state of North Carolina included the following counties located within the Blacksburg WFO area in north central NC in a request (December 12, 2018) for a federal disaster declaration as a result of Tropical Storm Michael: Caswell, Rockingham, Stokes, Surry and Yadkin. The outcome of the request was not available at this writing.', 'The river gage on the Smith River at Eden, NC (WENN7) rose above the flood stage of 11 feet and crested just below the Moderate flood category (14 feet) at 13.70 feet (17,400 cfs) late afternoon of the 11th. This was the 10th highest stage on record at this gage since records began in 1940 and the highest since January 2010.');
INSERT INTO public.stormevents_east VALUES (782206, 201810, 11, 600, 201810, 12, 600, 130716, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'RNK', '11-OCT-18 06:00:00', 'EST-5', '12-OCT-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'COOP Observer', NULL, NULL, NULL, NULL, 0, 'N', 'KEYSVILLE', 0, 'N', 'KEYSVILLE', 37.05, -78.48, 37.05, -78.48, 'Hurricane Michael made landfall along the Florida panhandle as major hurricane (Category 4 on the Saffir-Simpson scale) on Wednesday afternoon, October 10th, 2018, then tracked northeastward with the northern portion of the storm circulation tracking across portions of Southside, Virginia Thursday afternoon, the 11th. A deep flow of tropical moisture into the Appalachians and central mid Atlantic region ahead of the storm began to generate excessive rainfall across portions of the region as early as Wednesday evening, mainly along the Interstate 77 corridor, causing some degree of flash flooding and otherwise saturating the ground even before the arrival of the rainfall directly associated with Michael.||As the storm circulation approached on Thursday, a cold front moving in from the west and interacted with the storm and enhanced rainfall especially east of Interstate 81. Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, mainly from the mountains of North Carolina up through Southside Virginia. This resulted in significant flash flooding with flash flood emergencies issued for the city of Roanoke, as well as Roanoke County, and southern Pittsylvania county including the city of Danville.  Unfortunately, there were five fatalities as vehicles were swept away by flash flood waters in Pittsylvania County, Danville, and Charlotte County, Virginia.||The massive volume of water also then generated rapid rises on rivers including the New, Roanoke, and Dan. Major flooding was reported at several river gage locations along with a couple of record crests. There were a few landslides reported as well, blocking roads and in one case destroying a shed.||In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Many trees were blown down in the water logged soil especially across Pittsylvania, Halifax and Charlotte counties of Virginia where rainfall was heaviest.  Despite some initial reports of tornado sightings, damage surveys revealed no conclusive evidence of tornadic circulations and judged damage was caused by straight line winds.', 'The COOP observer at Keysville 2 S (KYSV2) measured 9.02 inches for the 24-hours ending at 700 AM local time, October 12, 2018. This was the highest 24-hour rainfall amount at this station with partial data back to 1979. The old record was 5.50 inches in July, 2005. In addition, the 9.02 inches is the 3rd highest 24-hour amount for any COOP station in the climate record for the NWS Blacksburg. According to the observer, most of this rain fell in about a 3.5 hour period on the afternoon of the 11th. For the 24-hour duration 9.02 inches falls into the 90 percent confidence interval (8.19-10.2 inches) for a 200-year (.002 annual chance event). For a duration of even 6 hours (being very conservative) the rainfall frequency was in excess of the 1,000 year event (.001 annual chance).');
INSERT INTO public.stormevents_east VALUES (782211, 201810, 11, 600, 201810, 11, 600, 130716, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'RNK', '11-OCT-18 06:00:00', 'EST-5', '11-OCT-18 06:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 4, 'SE', 'SAXE', 4, 'SE', 'SAXE', 36.886, -78.615, 36.886, -78.615, 'Hurricane Michael made landfall along the Florida panhandle as major hurricane (Category 4 on the Saffir-Simpson scale) on Wednesday afternoon, October 10th, 2018, then tracked northeastward with the northern portion of the storm circulation tracking across portions of Southside, Virginia Thursday afternoon, the 11th. A deep flow of tropical moisture into the Appalachians and central mid Atlantic region ahead of the storm began to generate excessive rainfall across portions of the region as early as Wednesday evening, mainly along the Interstate 77 corridor, causing some degree of flash flooding and otherwise saturating the ground even before the arrival of the rainfall directly associated with Michael.||As the storm circulation approached on Thursday, a cold front moving in from the west and interacted with the storm and enhanced rainfall especially east of Interstate 81. Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, mainly from the mountains of North Carolina up through Southside Virginia. This resulted in significant flash flooding with flash flood emergencies issued for the city of Roanoke, as well as Roanoke County, and southern Pittsylvania county including the city of Danville.  Unfortunately, there were five fatalities as vehicles were swept away by flash flood waters in Pittsylvania County, Danville, and Charlotte County, Virginia.||The massive volume of water also then generated rapid rises on rivers including the New, Roanoke, and Dan. Major flooding was reported at several river gage locations along with a couple of record crests. There were a few landslides reported as well, blocking roads and in one case destroying a shed.||In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Many trees were blown down in the water logged soil especially across Pittsylvania, Halifax and Charlotte counties of Virginia where rainfall was heaviest.  Despite some initial reports of tornado sightings, damage surveys revealed no conclusive evidence of tornadic circulations and judged damage was caused by straight line winds.', 'The CoCoRaHS site at Saxe 4.3 SE (VA-CH-1) measured 6.15 inches in 24-hours ending 700 AM local time, October 12, 2018.');
INSERT INTO public.stormevents_east VALUES (788735, 201810, 2, 1655, 201810, 2, 1659, 131754, 'PENNSYLVANIA', 42, 2018, 'October', 'Tornado', 'PBZ', '02-OCT-18 16:55:00', 'EST-5', '02-OCT-18 16:59:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'ESE', 'RODNEY', 1, 'NNE', 'DONEGAL', 40.143, -79.399, 40.136, -79.371, 'A low amplitude, positively-tilted shortwave trough crossed the eastern Great Lakes/upper Ohio Valley region on October 2nd.  Showers and thunderstorms developed in a moist, unstable air mass across eastern Ohio, northwestern Pennsylvania, and northern West Virginia. Despite expansive early morning cloud cover, some clearing was observed, allowing for a substantial buildup of instability, while dewpoints in the mid to upper 60s illustrated the available moisture.  The crossing shortwave and associated mid-level jet resulted in 40 knots of deep layer shear and a wind profile which favored discrete cells. As a result, several supercells and tornadic signatures were observed.||A total of six tornadoes were observed in the Pittsburgh forecast area, with ratings ranging from EF-0 to EF-2.  The most significant damage was observed with a tornado that resulted in damage to homes and gravestones in the vicinity of Jefferson Cemetery in Jefferson County.  No deaths or injuries were reported from these tornadoes. Several reports of hail up to golf ball size were also received, as well as reports of straight-line wind damage.||In all, 14 tornadoes occurred in the state of Pennsylvania on this day.  The previous record number (since 1950) of tornadoes on an October day was four on October 5, 1979.  Overall, there are only three days with more Pennsylvania tornadoes recorded:  May 31st to early June 1st, 1998 (23 tornadoes), June 2nd, 1998 (22), and May 31st, 1985 (21).', 'Visible tree damage began on a hilltop west of Stairs Road in |Donegal Township. The tornado intensified rapidly as it descended |into the valley, with widespread blowdown of hardwood and softwood|trees cutting a sharp path through the forest. Drone footage |shows remarkable tree damage in this area with clear convergence in the debris field.||Continuous, but weaker tree damage was found through the valley to|near the intersection of Harr Road and Donegal Lake Road, where|the circulation shrank and weakened.||The blowdown adjacent to Stairs Road was consistent with wind of|110-120 mph, which suggests a peak rating of EF2 for this tornado.');
INSERT INTO public.stormevents_east VALUES (790533, 201810, 11, 1823, 201810, 11, 1825, 132103, 'VIRGINIA', 51, 2018, 'October', 'Tornado', 'AKQ', '11-OCT-18 18:23:00', 'EST-5', '11-OCT-18 18:25:00', 0, 0, 0, 0, '150.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'SSE', 'NORGE', 1, 'NNW', 'NORGE', 37.3529, -76.7703, 37.3806, -76.7854, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Scattered severe thunderstorms associated with the Tropical Cyclone produced seven tornadoes across portions of central and eastern Virginia.', 'A tornado touched down on the northern side of the Colonial Heritage Club just south of Norge. The tornado then tracked northwest toward Toano and downed several trees. One tree went through a house on Arthur Hill Road. A roof was blown off a house near Candle Station before the tornado lifted just to the east of Toano.');
INSERT INTO public.stormevents_east VALUES (790534, 201810, 11, 1847, 201810, 11, 1848, 132103, 'VIRGINIA', 51, 2018, 'October', 'Tornado', 'AKQ', '11-OCT-18 18:47:00', 'EST-5', '11-OCT-18 18:48:00', 0, 0, 0, 0, '10.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'WSW', 'CASH', 1, 'SE', 'GLENNS', 37.5235, -76.6093, 37.5639, -76.6129, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Scattered severe thunderstorms associated with the Tropical Cyclone produced seven tornadoes across portions of central and eastern Virginia.', 'A tornado touched down on Pampa Road in northern Gloucester County before moving to the north-northwest and downing numerous trees. The tornado then lifted near the intersection of Route 17 and Glenns Road.');
INSERT INTO public.stormevents_east VALUES (790535, 201810, 11, 1913, 201810, 11, 1914, 132103, 'VIRGINIA', 51, 2018, 'October', 'Tornado', 'AKQ', '11-OCT-18 19:13:00', 'EST-5', '11-OCT-18 19:14:00', 0, 0, 0, 0, '5.00K', '0.00K', 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'WNW', 'JAMAICA', 1, 'WNW', 'JAMAICA', 37.7224, -76.7115, 37.7259, -76.7134, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Scattered severe thunderstorms associated with the Tropical Cyclone produced seven tornadoes across portions of central and eastern Virginia.', 'A tornado very briefly touched down along Union Shiloh Road where it downed numerous trees before lifting.');
INSERT INTO public.stormevents_east VALUES (789476, 201810, 11, 1400, 201810, 12, 30, 130716, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'RNK', '11-OCT-18 14:00:00', 'EST-5', '12-OCT-18 00:30:00', 0, 0, 1, 0, '1.54M', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'W', 'BROSVILLE', 1, 'NW', 'SANDY LEVEL', 36.6207, -79.6078, 36.9591, -79.5405, 'Hurricane Michael made landfall along the Florida panhandle as major hurricane (Category 4 on the Saffir-Simpson scale) on Wednesday afternoon, October 10th, 2018, then tracked northeastward with the northern portion of the storm circulation tracking across portions of Southside, Virginia Thursday afternoon, the 11th. A deep flow of tropical moisture into the Appalachians and central mid Atlantic region ahead of the storm began to generate excessive rainfall across portions of the region as early as Wednesday evening, mainly along the Interstate 77 corridor, causing some degree of flash flooding and otherwise saturating the ground even before the arrival of the rainfall directly associated with Michael.||As the storm circulation approached on Thursday, a cold front moving in from the west and interacted with the storm and enhanced rainfall especially east of Interstate 81. Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, mainly from the mountains of North Carolina up through Southside Virginia. This resulted in significant flash flooding with flash flood emergencies issued for the city of Roanoke, as well as Roanoke County, and southern Pittsylvania county including the city of Danville.  Unfortunately, there were five fatalities as vehicles were swept away by flash flood waters in Pittsylvania County, Danville, and Charlotte County, Virginia.||The massive volume of water also then generated rapid rises on rivers including the New, Roanoke, and Dan. Major flooding was reported at several river gage locations along with a couple of record crests. There were a few landslides reported as well, blocking roads and in one case destroying a shed.||In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Many trees were blown down in the water logged soil especially across Pittsylvania, Halifax and Charlotte counties of Virginia where rainfall was heaviest.  Despite some initial reports of tornado sightings, damage surveys revealed no conclusive evidence of tornadic circulations and judged damage was caused by straight line winds.', 'Pittsylvania County was included in a Presidential Major Disaster declaration due mainly to the severe flooding associated with Tropical Storm Michael. Rainfall of 4 to 8 inches in several hours triggered widespread flash flooding across the county with numerous roads closed and extensive damage.  A man lost his life when his automobile was washed off Sandy Creek Road near the 600 block during intense flooding along Sandy Creek.  Media reports indicate the incident occurred around 330 PM local time, with one witness observing that water was flowing rapidly at least two feet above the road surface.');
INSERT INTO public.stormevents_east VALUES (788363, 201810, 11, 1420, 201810, 12, 500, 130716, 'VIRGINIA', 51, 2018, 'October', 'Flood', 'RNK', '11-OCT-18 14:20:00', 'EST-5', '12-OCT-18 05:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SSW', 'IVANHOE', 2, 'NNE', 'AUSTINVILLE', 36.8279, -80.951, 36.8699, -80.8893, 'Hurricane Michael made landfall along the Florida panhandle as major hurricane (Category 4 on the Saffir-Simpson scale) on Wednesday afternoon, October 10th, 2018, then tracked northeastward with the northern portion of the storm circulation tracking across portions of Southside, Virginia Thursday afternoon, the 11th. A deep flow of tropical moisture into the Appalachians and central mid Atlantic region ahead of the storm began to generate excessive rainfall across portions of the region as early as Wednesday evening, mainly along the Interstate 77 corridor, causing some degree of flash flooding and otherwise saturating the ground even before the arrival of the rainfall directly associated with Michael.||As the storm circulation approached on Thursday, a cold front moving in from the west and interacted with the storm and enhanced rainfall especially east of Interstate 81. Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, mainly from the mountains of North Carolina up through Southside Virginia. This resulted in significant flash flooding with flash flood emergencies issued for the city of Roanoke, as well as Roanoke County, and southern Pittsylvania county including the city of Danville.  Unfortunately, there were five fatalities as vehicles were swept away by flash flood waters in Pittsylvania County, Danville, and Charlotte County, Virginia.||The massive volume of water also then generated rapid rises on rivers including the New, Roanoke, and Dan. Major flooding was reported at several river gage locations along with a couple of record crests. There were a few landslides reported as well, blocking roads and in one case destroying a shed.||In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Many trees were blown down in the water logged soil especially across Pittsylvania, Halifax and Charlotte counties of Virginia where rainfall was heaviest.  Despite some initial reports of tornado sightings, damage surveys revealed no conclusive evidence of tornadic circulations and judged damage was caused by straight line winds.', 'The New River flooded with the gage at Ivanhoe (IVNV2) rising above the Moderate flood stage of 19 feet, and reaching a peak of 20.05 feet (53100 cfs) on the afternoon of the 11th. This was the highest stage in over 40 years, since November 7, 1977 when the river reached 28.88 feet. According to USGS studies flooding from Michael was between a 10- and 25-year flood event (0.10 to 0.04 annual chance flood). Several roads close to the river were flooded and closed including Ivanhoe Road in Ivanhoe.');
INSERT INTO public.stormevents_east VALUES (788666, 201810, 11, 1320, 201810, 11, 1405, 131036, 'NORTH CAROLINA', 37, 2018, 'October', 'Flood', 'RNK', '11-OCT-18 13:20:00', 'EST-5', '11-OCT-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'WILKESBORO', 2, 'SSE', 'NORTH WILKESBORO', 36.1551, -81.1708, 36.1567, -81.139, 'As the direct storm circulation from Michael approached in the early morning hours of October 11, rainfall and strong winds began first in Watauga County in northwest NC, and progressed north and east through the day.  In addition, a cold front moving in from the west and interacted with the storm and enhanced rainfall, especially over the eastern counties.  Widespread rainfall amounts of 4 to 8 inches were reported, along with local amounts over 10 inches, from the mountains of North Carolina across the foothills and piedmont.  Much of the rain fell in a 3 to 6 hour period,  resulting in widespread, significant flash flooding and river flooding in all the NC counties of the Blacksburg WFO area of responsibility.  In addition, as the northern portion of the storm circulation moved across the Piedmont, bands of heavier rains/convection developed and mixed strong winds down to the surface.  Wind speeds were observed strongest across the higher terrain from the Blue Ridge westward, where 40 to 50 mph gusts were observed.  Winds speeds further east were generally lower as the storm continued to weaken along its eastward track.  Many trees and power lines were blown down in the water logged soil across the northern portion of North Carolina, resulting in blocked roads and numerous power outages. The state of North Carolina included the following counties located within the Blacksburg WFO area in north central NC in a request (December 12, 2018) for a federal disaster declaration as a result of Tropical Storm Michael: Caswell, Rockingham, Stokes, Surry and Yadkin. The outcome of the request was not available at this writing.', 'The Yadkin River at Wilkesboro (WKSN7) crested at 14.05 feet (11400 cfs) just above minor flood stage of 14 feet for the first time since August 1994 and the 6th highest since the completion of W. Kerr Scott Reservoir just upstream in 1962. A portion of Wilkesboro Avenue in North Wilkesboro was flooded by the Yadkin River for the first time in over 15 years according to news reports.');
INSERT INTO public.stormevents_east VALUES (790861, 201810, 7, 2300, 201810, 7, 2300, 132164, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MFL', '07-OCT-18 23:00:00', 'EST-5', '07-OCT-18 23:00:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 1, 'SE', 'PORT EVERGLADES', 1, 'SE', 'PORT EVERGLADES', 26.09, -80.12, 26.09, -80.12, 'Increasingly moist and windy flow moved across South Florida during the day on October 8th as developing Hurricane Michael lifted north into the Gulf of Mexico near the western coast of Cuba. This lead to several rounds of strong and gusty showers and storms across the local Atlantic waters.', 'A thunderstorm wind gust of 41 mph/36 knots was recorded by the WxFlow site XPEG in Port Everglades.');
INSERT INTO public.stormevents_east VALUES (790862, 201810, 8, 39, 201810, 8, 39, 132164, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MFL', '08-OCT-18 00:39:00', 'EST-5', '08-OCT-18 00:39:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 40, 'MG', NULL, NULL, 9, 'SSW', 'KEY BISCAYNE', 9, 'SSW', 'KEY BISCAYNE', 25.66, -80.19, 25.66, -80.19, 'Increasingly moist and windy flow moved across South Florida during the day on October 8th as developing Hurricane Michael lifted north into the Gulf of Mexico near the western coast of Cuba. This lead to several rounds of strong and gusty showers and storms across the local Atlantic waters.', 'A thunderstorm wind gust of 46 mph/40 knots was recorded by the WxFlow site XKBS located in Biscayne Bay.');
INSERT INTO public.stormevents_east VALUES (790863, 201810, 8, 624, 201810, 8, 624, 132164, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MFL', '08-OCT-18 06:24:00', 'EST-5', '08-OCT-18 06:24:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 34, 'MG', NULL, NULL, 10, 'SSE', 'PORT OF PALM BEACH', 10, 'SSE', 'PORT OF PALM BEACH', 26.6128, -80.0353, 26.6128, -80.0353, 'Increasingly moist and windy flow moved across South Florida during the day on October 8th as developing Hurricane Michael lifted north into the Gulf of Mexico near the western coast of Cuba. This lead to several rounds of strong and gusty showers and storms across the local Atlantic waters.', 'A thunderstorm wind gust of 39 mph/34 knots was recorded by the C-MAN station LKWF1 located on Lake Worth Pier.');
INSERT INTO public.stormevents_east VALUES (790865, 201810, 8, 1112, 201810, 8, 1112, 132164, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MFL', '08-OCT-18 11:12:00', 'EST-5', '08-OCT-18 11:12:00', 0, 0, 0, 0, NULL, NULL, 'C-MAN Station', 35, 'MG', NULL, NULL, 10, 'SSE', 'PORT OF PALM BEACH', 10, 'SSE', 'PORT OF PALM BEACH', 26.6127, -80.0353, 26.6127, -80.0353, 'Increasingly moist and windy flow moved across South Florida during the day on October 8th as developing Hurricane Michael lifted north into the Gulf of Mexico near the western coast of Cuba. This lead to several rounds of strong and gusty showers and storms across the local Atlantic waters.', 'A thunderstorm wind gust of 40 mph/35 knots was recorded b the C-MAN station LKWF1 located at the Lake Worth Pier.');
INSERT INTO public.stormevents_east VALUES (791197, 201810, 7, 2046, 201810, 7, 2046, 132164, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MFL', '07-OCT-18 20:46:00', 'EST-5', '07-OCT-18 20:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 41, 'MG', NULL, NULL, 14, 'S', 'PORT OF PALM BEACH', 14, 'S', 'PORT OF PALM BEACH', 26.5448, -80.0532, 26.5448, -80.0532, 'Increasingly moist and windy flow moved across South Florida during the day on October 8th as developing Hurricane Michael lifted north into the Gulf of Mexico near the western coast of Cuba. This lead to several rounds of strong and gusty showers and storms across the local Atlantic waters.', 'A thunderstorm wind gust of 41 knots/47 mph was measured at the WeatherFlow site KBOY in Boynton Beach.');
INSERT INTO public.stormevents_east VALUES (791198, 201810, 7, 2211, 201810, 7, 2211, 132164, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MFL', '07-OCT-18 22:11:00', 'EST-5', '07-OCT-18 22:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 39, 'MG', NULL, NULL, 2, 'SE', 'GOVERNMENT CUT', 2, 'SE', 'GOVERNMENT CUT', 25.75, -80.1, 25.75, -80.1, 'Increasingly moist and windy flow moved across South Florida during the day on October 8th as developing Hurricane Michael lifted north into the Gulf of Mexico near the western coast of Cuba. This lead to several rounds of strong and gusty showers and storms across the local Atlantic waters.', 'A thunderstorm wind gust of 39 knots/45 mph was measured at the WeatherFlow site KGVT in Government Cut at a height of 63 feet.');
INSERT INTO public.stormevents_east VALUES (778190, 201808, 5, 1405, 201808, 5, 1405, 129906, 'PENNSYLVANIA', 42, 2018, 'August', 'Hail', 'PBZ', '05-AUG-18 14:05:00', 'EST-5', '05-AUG-18 14:05:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 0.75, NULL, NULL, NULL, 0, 'N', 'VENETIA', 0, 'N', 'VENETIA', 40.25, -80.05, 40.25, -80.05, 'Isolated thunderstorms managed to form in a hot and humid pattern.  Weak steering flow led to some localized flash flooding in Allegheny County, and steep lapse rates/high instability combined with dry air aloft to produce hail and wind damage in a few instances.', 'Citizens of Washington County reported hail.');
INSERT INTO public.stormevents_east VALUES (790818, 201810, 3, 2000, 201810, 3, 2000, 132173, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '03-OCT-18 20:00:00', 'EST-5', '03-OCT-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'SMITH SHOAL LIGHT', 0, 'N', 'SMITH SHOAL LIGHT', 24.72, -81.92, 24.72, -81.92, 'Isolated showers produced gale-force wind gusts northwest of Key West, as downdraft were enhanced by dry air aloft.', 'A wind gust of 34 knots was measured at an automated WeatherFlow station at Smith Shoal Light.');
INSERT INTO public.stormevents_east VALUES (790957, 201810, 11, 1500, 201810, 11, 1500, 132191, 'GULF OF MEXICO', 85, 2018, 'October', 'Waterspout', 'KEY', '11-OCT-18 15:00:00', 'EST-5', '11-OCT-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mariner', NULL, NULL, NULL, NULL, 4, 'SE', 'SAND KEY LIGHT', 4, 'SE', 'SAND KEY LIGHT', 24.42, -81.84, 24.42, -81.84, 'An isolated waterspout was observed in association with a wet cloud line developing south of the Lower Florida Keys.', 'A waterspout was observed as a funnel cloud extending halfway between the cloud base and ocean surface, as well as a spray ring, southeast of Sand Key Light.');
INSERT INTO public.stormevents_east VALUES (790958, 201810, 12, 647, 201810, 12, 647, 132192, 'GULF OF MEXICO', 85, 2018, 'October', 'Waterspout', 'KEY', '12-OCT-18 06:47:00', 'EST-5', '12-OCT-18 06:47:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', NULL, NULL, NULL, NULL, 8, 'W', 'CARYSFORT REEF LIGHT', 8, 'W', 'CARYSFORT REEF LIGHT', 25.21, -80.33, 25.21, -80.33, 'A waterspout was observed in association with a rain shower near Key Largo.', 'A waterspout was observed oceanside of Key Largo.  The funnel cloud extended halfway from cloud base to the horizon.');
INSERT INTO public.stormevents_east VALUES (790963, 201810, 16, 1452, 201810, 16, 1452, 132193, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '16-OCT-18 14:52:00', 'EST-5', '16-OCT-18 14:52:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR REEF LIGHT', 0, 'N', 'ALLIGATOR REEF LIGHT', 24.85, -80.62, 24.85, -80.62, 'Fast-moving rain showers south of a deep axis of high pressure produced isolated gale-force wind gusts offshore Islamorada.', 'A wind gust of 35 knots was measured at an automated WeatherFlow station at Alligator Reef Light.');
INSERT INTO public.stormevents_east VALUES (777914, 201810, 2, 1629, 201810, 2, 1641, 129860, 'CONNECTICUT', 9, 2018, 'October', 'Tornado', 'OKX', '02-OCT-18 16:29:00', 'EST-5', '02-OCT-18 16:41:00', 0, 0, 0, 0, '50.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'NNW', 'NEW CANAAN', 1, 'WNW', 'NORWALK', 41.1363, -73.5031, 41.1061, -73.4435, 'An approaching cold front triggered severe thunderstorms across southwestern Connecticut, including one tornado in Fairfield County.', 'A National Weather Service (NWS) Storm Survey of damage was conducted with|Connecticut Emergency Management and Homeland Security and the New Canaan|and Norwalk Offices of Emergency Management in the area from New Canaan to Norwalk. Based on the results of this survey and NWS Doppler Radar data the following information has been determined. The tornado began near the intersection of Weed Street and Marshall Ridge Road in New Canaan and lifted near the intersection of Scribner Avenue and Orlando Road in Norwalk. Extensive tree damage was observed, and some of the trees fell on parked cars. The most significant damage was in New Canaan, where multiple trees were both uprooted and snapped. This damage is consistent with maximum wind speeds of around 100 mph, making this an EF-1 tornado. The tornado had a maximum path width of around 100 yards and was on the ground for around three and three-quarter miles.');
INSERT INTO public.stormevents_east VALUES (777913, 201810, 2, 2220, 201810, 2, 2222, 129857, 'NEW YORK', 36, 2018, 'October', 'Tornado', 'OKX', '02-OCT-18 22:20:00', 'EST-5', '02-OCT-18 22:22:00', 0, 0, 0, 0, '100.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 1, 'W', 'RONKONKOMA', 1, 'WNW', 'RONKONKOMA', 40.8221, -73.1446, 40.8217, -73.1405, 'An approaching cold front triggered severe thunderstorms across southeastern New York, they produced 3 tornadoes across Rockland, Westchester and Suffolk Counties.', 'A National Weather Service Storm Survey of damage in the Hamlet of Ronkonkoma New York was conducted in conjunction with the Town of Islip. Based on the results of this survey and NWS Doppler Radar data the following information has been determined. The tornado originated just north of the western end of Seneca Street and ended about one-eighth of a mile east of the intersection of Mohican Avenue and Seneca Street. The damage was confined to between Iroquois and Ontario streets along Mohican Avenue. Numerous homes sustained damage to siding and gutters and outdoor furniture. Trees have visibly sheared tops, and at least two or three trees were downed on cars. This damage is consistent with maximum wind speeds of around 85 mph, making this an EF-0 tornado. The tornado had a maximum path width of around 200 yards and was on the ground continuously for around 400 yards.');
INSERT INTO public.stormevents_east VALUES (782457, 201810, 10, 1730, 201810, 10, 1735, 130735, 'GULF OF MEXICO', 85, 2018, 'October', 'Waterspout', 'TBW', '10-OCT-18 17:30:00', 'EST-5', '10-OCT-18 17:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', NULL, NULL, NULL, NULL, 22, 'S', 'LOWER TAMPA BAY', 22, 'SSE', 'LOWER TAMPA BAY', 27.31, -82.59, 27.31, -82.5767, 'Hurricane Michael developed as a tropical depression in the western Caribbean on October 7th and strengthened into a major hurricane as it moved north through the Gulf of Mexico before making landfall near Mexico Beach on October 10th. Across west central and southwest Florida, Hurricane Michael caused isolated spots of tropical storm force winds on the 9th and 10th, as well as some minor storm surge along the coast. The peak wind report in west central and southwest Florida was 46 knots at the NOS station in Cedar Key on the afternoon of the 10th. Storm total rainfall was less than 2 inches across the area. At least 4 waterspouts developed in the outer rain bands, one of which made landfall as a brief tornado in Sarasota County. The total damage cost across west central and southwest Florida was estimated to be around $100,000, mostly from storm surge.', 'A social media video showed a waterspout just offshore of Lido Key and Saint Armands Key between 630 and 635, then moved onshore as a tornado.');
INSERT INTO public.stormevents_east VALUES (782456, 201810, 10, 1745, 201810, 10, 1750, 130735, 'GULF OF MEXICO', 85, 2018, 'October', 'Waterspout', 'TBW', '10-OCT-18 17:45:00', 'EST-5', '10-OCT-18 17:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 1, 'N', 'LOWER TAMPA BAY', 1, 'N', 'LOWER TAMPA BAY', 27.63, -82.65, 27.64, -82.65, 'Hurricane Michael developed as a tropical depression in the western Caribbean on October 7th and strengthened into a major hurricane as it moved north through the Gulf of Mexico before making landfall near Mexico Beach on October 10th. Across west central and southwest Florida, Hurricane Michael caused isolated spots of tropical storm force winds on the 9th and 10th, as well as some minor storm surge along the coast. The peak wind report in west central and southwest Florida was 46 knots at the NOS station in Cedar Key on the afternoon of the 10th. Storm total rainfall was less than 2 inches across the area. At least 4 waterspouts developed in the outer rain bands, one of which made landfall as a brief tornado in Sarasota County. The total damage cost across west central and southwest Florida was estimated to be around $100,000, mostly from storm surge.', 'A waterspout was reported near the Skyway Bridge.');
INSERT INTO public.stormevents_east VALUES (789352, 201810, 20, 1318, 201810, 20, 1318, 131939, 'LAKE ST CLAIR', 81, 2018, 'October', 'Marine Thunderstorm Wind', 'DTX', '20-OCT-18 13:18:00', 'EST-5', '20-OCT-18 13:18:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 40, 'MG', NULL, NULL, 3, 'S', 'ST CLAIR SHORES', 3, 'S', 'ST CLAIR SHORES', 42.433, -82.871, 42.433, -82.871, 'Thunderstorms moving through Lake St. Clair and St. Clair River produced wind gusts over 60 knots.', NULL);
INSERT INTO public.stormevents_east VALUES (788254, 201810, 2, 1631, 201810, 2, 1631, 131754, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'PBZ', '02-OCT-18 16:31:00', 'EST-5', '02-OCT-18 16:31:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'SE', 'RED MILL', 3, 'SE', 'RED MILL', 41.14, -78.8, 41.14, -78.8, 'A low amplitude, positively-tilted shortwave trough crossed the eastern Great Lakes/upper Ohio Valley region on October 2nd.  Showers and thunderstorms developed in a moist, unstable air mass across eastern Ohio, northwestern Pennsylvania, and northern West Virginia. Despite expansive early morning cloud cover, some clearing was observed, allowing for a substantial buildup of instability, while dewpoints in the mid to upper 60s illustrated the available moisture.  The crossing shortwave and associated mid-level jet resulted in 40 knots of deep layer shear and a wind profile which favored discrete cells. As a result, several supercells and tornadic signatures were observed.||A total of six tornadoes were observed in the Pittsburgh forecast area, with ratings ranging from EF-0 to EF-2.  The most significant damage was observed with a tornado that resulted in damage to homes and gravestones in the vicinity of Jefferson Cemetery in Jefferson County.  No deaths or injuries were reported from these tornadoes. Several reports of hail up to golf ball size were also received, as well as reports of straight-line wind damage.||In all, 14 tornadoes occurred in the state of Pennsylvania on this day.  The previous record number (since 1950) of tornadoes on an October day was four on October 5, 1979.  Overall, there are only three days with more Pennsylvania tornadoes recorded:  May 31st to early June 1st, 1998 (23 tornadoes), June 2nd, 1998 (22), and May 31st, 1985 (21).', 'County 911 officials reported that multiple trees were blown down near Falls Creek.');
INSERT INTO public.stormevents_east VALUES (788255, 201810, 2, 1631, 201810, 2, 1631, 131754, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'PBZ', '02-OCT-18 16:31:00', 'EST-5', '02-OCT-18 16:31:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NE', 'NEW STANTON', 1, 'NE', 'NEW STANTON', 40.23, -79.59, 40.23, -79.59, 'A low amplitude, positively-tilted shortwave trough crossed the eastern Great Lakes/upper Ohio Valley region on October 2nd.  Showers and thunderstorms developed in a moist, unstable air mass across eastern Ohio, northwestern Pennsylvania, and northern West Virginia. Despite expansive early morning cloud cover, some clearing was observed, allowing for a substantial buildup of instability, while dewpoints in the mid to upper 60s illustrated the available moisture.  The crossing shortwave and associated mid-level jet resulted in 40 knots of deep layer shear and a wind profile which favored discrete cells. As a result, several supercells and tornadic signatures were observed.||A total of six tornadoes were observed in the Pittsburgh forecast area, with ratings ranging from EF-0 to EF-2.  The most significant damage was observed with a tornado that resulted in damage to homes and gravestones in the vicinity of Jefferson Cemetery in Jefferson County.  No deaths or injuries were reported from these tornadoes. Several reports of hail up to golf ball size were also received, as well as reports of straight-line wind damage.||In all, 14 tornadoes occurred in the state of Pennsylvania on this day.  The previous record number (since 1950) of tornadoes on an October day was four on October 5, 1979.  Overall, there are only three days with more Pennsylvania tornadoes recorded:  May 31st to early June 1st, 1998 (23 tornadoes), June 2nd, 1998 (22), and May 31st, 1985 (21).', 'According to county 911 officials, a tree and wires were blown down, blocking 7th Street.');
INSERT INTO public.stormevents_east VALUES (790448, 201810, 11, 1830, 201810, 11, 2030, 130125, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'LWX', '11-OCT-18 18:30:00', 'EST-5', '11-OCT-18 20:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'FERRY FARMS', 1, 'WNW', 'FERRY FARMS', 38.3289, -77.4488, 38.3292, -77.4495, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and a minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. Ahead of the tropical storm, the strong low level wind field combined with some instability ahead of the storm to generate bands of showers and thunderstorms, one of which became severe. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Virginia, maximum sustained winds reached 35 mph, peak wind gusts reached 46 mph, and some rainfall totals were observed in excess of 6 inches.', 'Harrell Road was closed due to high water.');
INSERT INTO public.stormevents_east VALUES (790449, 201810, 11, 2100, 201810, 11, 2300, 130125, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'LWX', '11-OCT-18 21:00:00', 'EST-5', '11-OCT-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'SCOTTSVILLE', 2, 'NNE', 'SCOTTSVILLE', 37.8206, -78.4828, 37.8205, -78.4831, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and a minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. Ahead of the tropical storm, the strong low level wind field combined with some instability ahead of the storm to generate bands of showers and thunderstorms, one of which became severe. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Virginia, maximum sustained winds reached 35 mph, peak wind gusts reached 46 mph, and some rainfall totals were observed in excess of 6 inches.', 'Albevanna Spring Road was closed at Pat Dennis Road due to high water.');
INSERT INTO public.stormevents_east VALUES (790451, 201810, 11, 2100, 201810, 11, 2300, 130125, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'LWX', '11-OCT-18 21:00:00', 'EST-5', '11-OCT-18 23:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNE', 'DOGUE', 1, 'NNE', 'DOGUE', 38.2385, -77.2143, 38.2383, -77.2138, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and a minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. Ahead of the tropical storm, the strong low level wind field combined with some instability ahead of the storm to generate bands of showers and thunderstorms, one of which became severe. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Virginia, maximum sustained winds reached 35 mph, peak wind gusts reached 46 mph, and some rainfall totals were observed in excess of 6 inches.', 'Port Conway Road was washed out at Powhatan Road.');
INSERT INTO public.stormevents_east VALUES (790462, 201810, 11, 2015, 201810, 11, 2215, 130125, 'VIRGINIA', 51, 2018, 'October', 'Flood', 'LWX', '11-OCT-18 20:15:00', 'EST-5', '11-OCT-18 22:15:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'KING GEORGE', 1, 'WNW', 'MONTAGUE', 38.27, -77.18, 38.2382, -77.1976, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and a minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. Ahead of the tropical storm, the strong low level wind field combined with some instability ahead of the storm to generate bands of showers and thunderstorms, one of which became severe. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Virginia, maximum sustained winds reached 35 mph, peak wind gusts reached 46 mph, and some rainfall totals were observed in excess of 6 inches.', 'There were reports of flooded roads across the entire county, including near the intersection of U.S. 301 and Sunset Lane.');
INSERT INTO public.stormevents_east VALUES (790461, 201810, 11, 1758, 201810, 11, 1958, 130125, 'VIRGINIA', 51, 2018, 'October', 'Flood', 'LWX', '11-OCT-18 17:58:00', 'EST-5', '11-OCT-18 19:58:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 2, 'W', 'ROSEVILLE', 2, 'W', 'ROSEVILLE', 38.4743, -77.5519, 38.4736, -77.5533, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and a minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. Ahead of the tropical storm, the strong low level wind field combined with some instability ahead of the storm to generate bands of showers and thunderstorms, one of which became severe. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Virginia, maximum sustained winds reached 35 mph, peak wind gusts reached 46 mph, and some rainfall totals were observed in excess of 6 inches.', 'Poplar Road was closed due to flooding near Mountain View Road.');
INSERT INTO public.stormevents_east VALUES (790470, 201810, 11, 2235, 201810, 12, 35, 131827, 'MARYLAND', 24, 2018, 'October', 'Flood', 'LWX', '11-OCT-18 22:35:00', 'EST-5', '12-OCT-18 00:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'IRONSIDES', 1, 'SW', 'IRONSIDES', 38.492, -77.1604, 38.4922, -77.1591, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Maryland, maximum sustained winds reached 38 mph, peak wind gusts reached 62 mph, and some rainfall totals were observed in excess of 6 inches.', 'MD-425 Ironsides Road was closed due to flooding near MD-6 Port Tobacco Road.');
INSERT INTO public.stormevents_east VALUES (790471, 201810, 11, 2253, 201810, 12, 53, 131827, 'MARYLAND', 24, 2018, 'October', 'Flood', 'LWX', '11-OCT-18 22:53:00', 'EST-5', '12-OCT-18 00:53:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Broadcast Media', NULL, NULL, 'Heavy Rain', NULL, 0, 'NE', 'AQUASCO', 1, 'NNE', 'AQUASCO', 38.5846, -76.7254, 38.5884, -76.7257, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Maryland, maximum sustained winds reached 38 mph, peak wind gusts reached 62 mph, and some rainfall totals were observed in excess of 6 inches.', 'MD-381 Aquasco Road was closed due to flooding near Saint Marys Church Road.');
INSERT INTO public.stormevents_east VALUES (790472, 201810, 11, 2306, 201810, 12, 106, 131827, 'MARYLAND', 24, 2018, 'October', 'Flood', 'LWX', '11-OCT-18 23:06:00', 'EST-5', '12-OCT-18 01:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'N', 'PATUXENT', 1, 'NNE', 'PATUXENT', 38.5396, -76.7487, 38.5388, -76.747, 'After Hurricane Michael made landfall near Mexico Beach, Florida with maximum sustained winds of 155 mph and minimum central pressure of 919 mb on Wednesday October 10th, it weakened to a tropical storm as it tracked northeastward through Georgia and South Carolina. The tropical storm then tracked across North Carolina and southeast Virginia Thursday and Thursday night, October 11th, emerging back into the Atlantic Ocean early Friday morning, October 12th. As the system passed south of the region, heavy rain then caused instances of flooding, and strong winds brought down trees. Across Maryland, maximum sustained winds reached 38 mph, peak wind gusts reached 62 mph, and some rainfall totals were observed in excess of 6 inches.', 'MD-381 Brandywine Road was closed due to flooding near MD-231 Prince Frederick Road.');
INSERT INTO public.stormevents_east VALUES (782505, 201810, 2, 1725, 201810, 2, 1925, 130766, 'WEST VIRGINIA', 54, 2018, 'October', 'Flash Flood', 'RLX', '02-OCT-18 17:25:00', 'EST-5', '02-OCT-18 19:25:00', 0, 0, 0, 0, '1.00K', '0.00K', 'Public', NULL, NULL, 'Heavy Rain', NULL, 1, 'NE', 'NEW MILTON', 1, 'WSW', 'AVON', 39.2453, -80.6641, 39.19, -80.6736, 'The combination of an upper level shortwave trough and a stalled surface boundary produced strong to severe thunderstorms and isolated flash flooding across north central West Virginia on the 2nd.', 'Meathouse Fork Creek flooded, closing Meathouse Fork Road.');
INSERT INTO public.stormevents_east VALUES (790607, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWSS', NULL, NULL, NULL, NULL, 0, 'N', 'ASHLAND', 0, 'N', 'ASHLAND', 37.75, -77.48, 37.75, -77.48, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 5.52 inches was reported at Highland Springs (2 N). Rainfall total of 3.58 inches was reported at Ashland. Rainfall total of 2.77 inches was reported at Beaverdam (1 E).');
