INSERT INTO public.stormevents_east VALUES (790617, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWSS', NULL, NULL, NULL, NULL, 0, 'N', 'MINERAL', 0, 'N', 'MINERAL', 38.02, -77.92, 38.02, -77.92, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 7.32 inches was reported at Mineral. Rainfall total of 4.94 inches was reported at Zion Crossroads (3 NW). Rainfall total of 2.93 inches was reported at Louisa (1 NNW).');
INSERT INTO public.stormevents_east VALUES (790618, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 1, 'N', 'VICTORIA', 1, 'N', 'VICTORIA', 36.9945, -78.23, 36.9945, -78.23, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 7.78 inches was reported at Victoria (1 N).');
INSERT INTO public.stormevents_east VALUES (790817, 201810, 12, 50, 201810, 12, 945, 132172, 'VIRGINIA', 51, 2018, 'October', 'Flood', 'AKQ', '12-OCT-18 00:50:00', 'EST-5', '12-OCT-18 09:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'E', 'CHRLS CTY BRKELY ARP', 0, 'WSW', 'RUSTIC', 37.3226, -77.1456, 37.2983, -76.9571, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Several roads remained impassable or closed across much of the county due to lingering flooding.');
INSERT INTO public.stormevents_east VALUES (790820, 201810, 11, 2230, 201810, 12, 745, 132172, 'VIRGINIA', 51, 2018, 'October', 'Flood', 'AKQ', '11-OCT-18 22:30:00', 'EST-5', '12-OCT-18 07:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'SE', 'QUAIL OAKS', 1, 'N', 'ETTRICK', 37.3588, -77.4088, 37.2404, -77.4181, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Several roads remained impassable or closed across much of the county due to lingering flooding.');
