INSERT INTO public.stormevents_east VALUES (790621, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWSS', NULL, NULL, NULL, NULL, 1, 'SSE', 'HEALYS', 1, 'SSE', 'HEALYS', 37.5566, -76.513, 37.5566, -76.513, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 9.32 inches was reported at Cooper. Rainfall total of 5.13 inches was reported at Healys (1 SSE). Rainfall total of 5.11 inches was reported at Remlik (1 N).');
INSERT INTO public.stormevents_east VALUES (790625, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 0, 'N', 'DENBIGH', 0, 'N', 'DENBIGH', 37.13, -76.55, 37.13, -76.55, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 4.61 inches was reported at Beaconsdale (2 NNE). Rainfall total of 2.15 inches was reported at Denbigh.');
INSERT INTO public.stormevents_east VALUES (790638, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', NULL, NULL, NULL, NULL, 0, 'N', 'CREWE', 0, 'N', 'CREWE', 37.17, -78.12, 37.17, -78.12, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 5.52 inches was reported at Crewe.');
INSERT INTO public.stormevents_east VALUES (790830, 201810, 11, 2210, 201810, 12, 1015, 132172, 'VIRGINIA', 51, 2018, 'October', 'Flood', 'AKQ', '11-OCT-18 22:10:00', 'EST-5', '12-OCT-18 10:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'W', 'STATE FARM', 1, 'SSW', 'BULA', 37.6536, -77.8539, 37.7544, -78.0623, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Several roads remained impassable or closed across much of the county due to lingering flooding.');
