INSERT INTO public.stormevents_east VALUES (789784, 201810, 20, 2109, 201810, 20, 2114, 131997, 'ATLANTIC NORTH', 88, 2018, 'October', 'Marine Thunderstorm Wind', 'LWX', '20-OCT-18 21:09:00', 'EST-5', '20-OCT-18 21:14:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 40, 'MG', NULL, NULL, 0, 'N', 'NATIONALS PARK (WSHNP)', 0, 'N', 'NATIONALS PARK (WSHNP)', 38.87, -77.01, 38.87, -77.01, 'A cold front passed across the waters during the evening hours of October 20th. A band of showers and isolated thunderstorms along the front produced gusty winds across portions of the waters.', 'A wind gust of 40 knots was measured at Nationals Park.');
INSERT INTO public.stormevents_east VALUES (779316, 201810, 2, 1406, 201810, 2, 1406, 130090, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'CTP', '02-OCT-18 14:06:00', 'EST-5', '02-OCT-18 14:06:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Emergency Manager', 52, 'EG', NULL, NULL, 0, 'NNW', 'CANOE CAMP', 0, 'NNW', 'CANOE CAMP', 41.786, -77.0722, 41.786, -77.0722, 'A cold front pushed into an unseasonably warm and humid airmass during the afternoon and evening hours of October 2, 2018. Many of the larger storm cells exhibited rotation. There were 16 confirmed across Pennsylvania, three of which occurred in central Pennsylvania. This turned out to be the largest October tornado outbreak, and the fourth largest outbreak overall, in Pennsylvania history.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees near Mansfield.');
INSERT INTO public.stormevents_east VALUES (779317, 201810, 2, 1450, 201810, 2, 1450, 130090, 'PENNSYLVANIA', 42, 2018, 'October', 'Thunderstorm Wind', 'CTP', '02-OCT-18 14:50:00', 'EST-5', '02-OCT-18 14:50:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 52, 'EG', NULL, NULL, 1, 'WNW', 'LOTTSVILLE', 1, 'WNW', 'LOTTSVILLE', 41.956, -79.4532, 41.956, -79.4532, 'A cold front pushed into an unseasonably warm and humid airmass during the afternoon and evening hours of October 2, 2018. Many of the larger storm cells exhibited rotation. There were 16 confirmed across Pennsylvania, three of which occurred in central Pennsylvania. This turned out to be the largest October tornado outbreak, and the fourth largest outbreak overall, in Pennsylvania history.', 'A severe thunderstorm producing winds estimated near 60 mph knocked down trees along Route 958 in Freehold Township.');
INSERT INTO public.stormevents_east VALUES (780844, 201810, 8, 1925, 201810, 8, 1925, 130435, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MLB', '08-OCT-18 19:25:00', 'EST-5', '08-OCT-18 19:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 5, 'NNW', 'PLAYALINDA BEACH', 5, 'NNW', 'PLAYALINDA BEACH', 28.61, -80.82, 28.61, -80.82, 'The large circulation around Hurricane Michael located near the western tip of Cuba combined with high pressure to the north to initiate quick-moving showers with gusty winds over the Atlantic. The squalls spread onshore the coast from Volusia to St. Lucie counties between early afternoon and late evening, producing frequent wind gusts of 35 to 40 knots.', 'USAF wind tower 1012 measured a peak gust of 34 knots from the east as a squall moved onshore from the Atlantic.');
INSERT INTO public.stormevents_east VALUES (780846, 201810, 8, 2155, 201810, 8, 2155, 130435, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MLB', '08-OCT-18 21:55:00', 'EST-5', '08-OCT-18 21:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 2, 'NNW', 'MELBOURNE', 2, 'NNW', 'MELBOURNE', 28.101, -80.612, 28.101, -80.612, 'The large circulation around Hurricane Michael located near the western tip of Cuba combined with high pressure to the north to initiate quick-moving showers with gusty winds over the Atlantic. The squalls spread onshore the coast from Volusia to St. Lucie counties between early afternoon and late evening, producing frequent wind gusts of 35 to 40 knots.', 'The ASOS at Melbourne International Airport (KMLB) measured a peak gust of 38 knots from the east as a squall moved onshore from the Atlantic.');
INSERT INTO public.stormevents_east VALUES (780847, 201810, 8, 2245, 201810, 8, 2245, 130435, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MLB', '08-OCT-18 22:45:00', 'EST-5', '08-OCT-18 22:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 34, 'MG', NULL, NULL, 9, 'ENE', 'PLAYALINDA BEACH', 9, 'ENE', 'PLAYALINDA BEACH', 28.6, -80.64, 28.6, -80.64, 'The large circulation around Hurricane Michael located near the western tip of Cuba combined with high pressure to the north to initiate quick-moving showers with gusty winds over the Atlantic. The squalls spread onshore the coast from Volusia to St. Lucie counties between early afternoon and late evening, producing frequent wind gusts of 35 to 40 knots.', 'USAF wind tower 0311 measured a peak gust of 34 knots from the east as a squall moved onshore from the Atlantic.');
INSERT INTO public.stormevents_east VALUES (780848, 201810, 8, 2350, 201810, 8, 2350, 130435, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MLB', '08-OCT-18 23:50:00', 'EST-5', '08-OCT-18 23:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 36, 'MG', NULL, NULL, 18, 'NNE', 'PLAYALINDA BEACH', 18, 'NNE', 'PLAYALINDA BEACH', 28.8, -80.7, 28.8, -80.7, 'The large circulation around Hurricane Michael located near the western tip of Cuba combined with high pressure to the north to initiate quick-moving showers with gusty winds over the Atlantic. The squalls spread onshore the coast from Volusia to St. Lucie counties between early afternoon and late evening, producing frequent wind gusts of 35 to 40 knots.', 'USAF wind tower 0019 measured a peak gust of 36 knots from the east as a squall moved onshore from the Atlantic.');
INSERT INTO public.stormevents_east VALUES (780849, 201810, 8, 2320, 201810, 8, 2320, 130435, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MLB', '08-OCT-18 23:20:00', 'EST-5', '08-OCT-18 23:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 34, 'MG', NULL, NULL, 2, 'NW', 'ST. LUCIE INLET', 2, 'NW', 'ST. LUCIE INLET', 27.5, -80.338, 27.5, -80.338, 'The large circulation around Hurricane Michael located near the western tip of Cuba combined with high pressure to the north to initiate quick-moving showers with gusty winds over the Atlantic. The squalls spread onshore the coast from Volusia to St. Lucie counties between early afternoon and late evening, producing frequent wind gusts of 35 to 40 knots.', 'The ASOS at St. Lucie Airport in Ft. Pierce measured a peak gust of 34 knots from the east-southeast as a squall moved onshore from the Atlantic.');
INSERT INTO public.stormevents_east VALUES (782518, 201810, 28, 1822, 201810, 28, 1822, 130771, 'WEST VIRGINIA', 54, 2018, 'October', 'Hail', 'RLX', '28-OCT-18 18:22:00', 'EST-5', '28-OCT-18 18:22:00', 0, 0, 0, 0, '0.00K', '0.00K', '911 Call Center', 1, NULL, NULL, NULL, 1, 'W', 'RIPLEY', 1, 'W', 'RIPLEY', 38.82, -81.71, 38.82, -81.71, 'A quick moving low pressure system moved through the Great Lakes on the 28th, driving a cold front through the middle Ohio River Valley and central Appalachians. This front helped kick off thunderstorms, which combined with strong mid level winds led to strong thunderstorms containing hail and strong winds.', NULL);
