INSERT INTO public.stormevents_east VALUES (786910, 201810, 2, 1658, 201810, 2, 2100, 131544, 'CONNECTICUT', 9, 2018, 'October', 'Flood', 'BOX', '02-OCT-18 16:58:00', 'EST-5', '02-OCT-18 21:00:00', 0, 0, 0, 0, '15.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'NEW BRITAIN', 2, 'NNE', 'NEW BRITAIN', 41.6928, -72.7723, 41.6912, -72.7718, 'Cool northeast flow was in place across the region but a warm front attempted to move north through Connecticut just as a mid-level short wave trough was approaching. Low pressure from the Midwest moved along the boundary, crossing New England at night. Instability and unseasonably high moisture generated damaging thunderstorms and downpours. A brief tornado also touched down in Mansfield, CT during the early evening.', 'At 4:58 PM EST, the intersection of Stanley Street and Eddy Glover Blvd was closed due to flooding.  Several cars were trapped in the flooding.  The intersection is adjacent to the campus of Central Connecticut University.');
INSERT INTO public.stormevents_east VALUES (784357, 201810, 9, 756, 201810, 9, 756, 130873, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'JAX', '09-OCT-18 07:56:00', 'EST-5', '09-OCT-18 07:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'AWOS', 41, 'MG', NULL, NULL, 4, 'NW', 'SAUF1 CMAN', 4, 'NW', 'SAUF1 CMAN', 29.89, -81.31, 29.89, -81.31, 'Hurricane Michael tracked toward the FL Panhandle coast October 9th and made landfall near Mexico Beach as a very strong Cat. 4, perhaps Cat. 5 upon further research. The storm center tracked NNE across southern GA, and brought tropical storm conditions in waves of showers and thunderstorms to the area through the early morning hours of Oct. 10th. Local impacts were mainly wind damage to trees, power lines and a few structures.', NULL);
INSERT INTO public.stormevents_east VALUES (784358, 201810, 9, 820, 201810, 9, 820, 130873, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'JAX', '09-OCT-18 08:20:00', 'EST-5', '09-OCT-18 08:20:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 87, 'S', 'BRUNSWICK', 87, 'S', 'BRUNSWICK', 29.94, -81.3, 29.94, -81.3, 'Hurricane Michael tracked toward the FL Panhandle coast October 9th and made landfall near Mexico Beach as a very strong Cat. 4, perhaps Cat. 5 upon further research. The storm center tracked NNE across southern GA, and brought tropical storm conditions in waves of showers and thunderstorms to the area through the early morning hours of Oct. 10th. Local impacts were mainly wind damage to trees, power lines and a few structures.', 'Mesonet site at Vilano Beach measured a wind gust of 43 mph.');
INSERT INTO public.stormevents_east VALUES (786900, 201810, 2, 1650, 201810, 2, 2000, 131544, 'CONNECTICUT', 9, 2018, 'October', 'Flood', 'BOX', '02-OCT-18 16:50:00', 'EST-5', '02-OCT-18 20:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNE', 'HARTFORD', 2, 'NNE', 'HARTFORD', 41.7922, -72.705, 41.7913, -72.7048, 'Cool northeast flow was in place across the region but a warm front attempted to move north through Connecticut just as a mid-level short wave trough was approaching. Low pressure from the Midwest moved along the boundary, crossing New England at night. Instability and unseasonably high moisture generated damaging thunderstorms and downpours. A brief tornado also touched down in Mansfield, CT during the early evening.', 'At 4:50 PM EST, a car was reported trapped in flood waters on Granby Street at Plainfield Street.');
INSERT INTO public.stormevents_east VALUES (788124, 201810, 2, 1610, 201810, 2, 1610, 131754, 'PENNSYLVANIA', 42, 2018, 'October', 'Hail', 'PBZ', '02-OCT-18 16:10:00', 'EST-5', '02-OCT-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.75, NULL, NULL, NULL, 0, 'N', 'BYROMTOWN', 0, 'N', 'BYROMTOWN', 41.53, -79.05, 41.53, -79.05, 'A low amplitude, positively-tilted shortwave trough crossed the eastern Great Lakes/upper Ohio Valley region on October 2nd.  Showers and thunderstorms developed in a moist, unstable air mass across eastern Ohio, northwestern Pennsylvania, and northern West Virginia. Despite expansive early morning cloud cover, some clearing was observed, allowing for a substantial buildup of instability, while dewpoints in the mid to upper 60s illustrated the available moisture.  The crossing shortwave and associated mid-level jet resulted in 40 knots of deep layer shear and a wind profile which favored discrete cells. As a result, several supercells and tornadic signatures were observed.||A total of six tornadoes were observed in the Pittsburgh forecast area, with ratings ranging from EF-0 to EF-2.  The most significant damage was observed with a tornado that resulted in damage to homes and gravestones in the vicinity of Jefferson Cemetery in Jefferson County.  No deaths or injuries were reported from these tornadoes. Several reports of hail up to golf ball size were also received, as well as reports of straight-line wind damage.||In all, 14 tornadoes occurred in the state of Pennsylvania on this day.  The previous record number (since 1950) of tornadoes on an October day was four on October 5, 1979.  Overall, there are only three days with more Pennsylvania tornadoes recorded:  May 31st to early June 1st, 1998 (23 tornadoes), June 2nd, 1998 (22), and May 31st, 1985 (21).', NULL);
INSERT INTO public.stormevents_east VALUES (788125, 201810, 2, 1613, 201810, 2, 1613, 131754, 'PENNSYLVANIA', 42, 2018, 'October', 'Hail', 'PBZ', '02-OCT-18 16:13:00', 'EST-5', '02-OCT-18 16:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 1.5, NULL, NULL, NULL, 1, 'E', 'BYROMTOWN', 1, 'E', 'BYROMTOWN', 41.53, -79.04, 41.53, -79.04, 'A low amplitude, positively-tilted shortwave trough crossed the eastern Great Lakes/upper Ohio Valley region on October 2nd.  Showers and thunderstorms developed in a moist, unstable air mass across eastern Ohio, northwestern Pennsylvania, and northern West Virginia. Despite expansive early morning cloud cover, some clearing was observed, allowing for a substantial buildup of instability, while dewpoints in the mid to upper 60s illustrated the available moisture.  The crossing shortwave and associated mid-level jet resulted in 40 knots of deep layer shear and a wind profile which favored discrete cells. As a result, several supercells and tornadic signatures were observed.||A total of six tornadoes were observed in the Pittsburgh forecast area, with ratings ranging from EF-0 to EF-2.  The most significant damage was observed with a tornado that resulted in damage to homes and gravestones in the vicinity of Jefferson Cemetery in Jefferson County.  No deaths or injuries were reported from these tornadoes. Several reports of hail up to golf ball size were also received, as well as reports of straight-line wind damage.||In all, 14 tornadoes occurred in the state of Pennsylvania on this day.  The previous record number (since 1950) of tornadoes on an October day was four on October 5, 1979.  Overall, there are only three days with more Pennsylvania tornadoes recorded:  May 31st to early June 1st, 1998 (23 tornadoes), June 2nd, 1998 (22), and May 31st, 1985 (21).', NULL);
