INSERT INTO public.stormevents_east VALUES (789767, 201810, 15, 2300, 201810, 15, 2300, 131996, 'ATLANTIC NORTH', 88, 2018, 'October', 'Marine Thunderstorm Wind', 'LWX', '15-OCT-18 23:00:00', 'EST-5', '15-OCT-18 23:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'MID BAY BUOY', 0, 'N', 'MID BAY BUOY', 38.47, -76.38, 38.47, -76.38, 'A cold front passed across the waters during the evening and overnight hours of October 15th-16th. A band of showers and isolated thunderstorms along the front produced gusty winds across portions of the waters.', 'A wind gust of up to 34 knots was measured at Cove Point.');
