INSERT INTO public.stormevents_east VALUES (780853, 201810, 9, 510, 201810, 9, 510, 130435, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'MLB', '09-OCT-18 05:10:00', 'EST-5', '09-OCT-18 05:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Other Federal Agency', 40, 'MG', NULL, NULL, 16, 'N', 'PLAYALINDA BEACH', 16, 'N', 'PLAYALINDA BEACH', 28.78, -80.8, 28.78, -80.8, 'The large circulation around Hurricane Michael located near the western tip of Cuba combined with high pressure to the north to initiate quick-moving showers with gusty winds over the Atlantic. The squalls spread onshore the coast from Volusia to St. Lucie counties between early afternoon and late evening, producing frequent wind gusts of 35 to 40 knots.', 'USAF wind tower 0421 measured a peak gust of 40 knots from the east-southeast as a squall moved onshore from the Atlantic.');
INSERT INTO public.stormevents_east VALUES (782529, 201810, 28, 1740, 201810, 28, 1740, 130770, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'RLX', '28-OCT-18 17:40:00', 'EST-5', '28-OCT-18 17:40:00', 0, 0, 0, 0, '10.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 3, 'S', 'CANAANVILLE', 3, 'S', 'CANAANVILLE', 39.2897, -82.0027, 39.2897, -82.0027, 'A quick moving low pressure system moved through the Great Lakes on the 28th, driving a cold front through the middle Ohio River Valley. This front helped kick off thunderstorms, which combined with strong mid level winds led to strong thunderstorms with hail, strong wind gusts and one weak tornado.', 'Part of the roof was blown off a house along Willow Creek Road.');
INSERT INTO public.stormevents_east VALUES (782531, 201810, 28, 1811, 201810, 28, 1811, 130770, 'OHIO', 39, 2018, 'October', 'Thunderstorm Wind', 'RLX', '28-OCT-18 18:11:00', 'EST-5', '28-OCT-18 18:11:00', 0, 0, 0, 0, '1.00K', '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'SSW', 'COOLVILLE STATION', 2, 'SSW', 'COOLVILLE STATION', 39.22, -81.8, 39.22, -81.8, 'A quick moving low pressure system moved through the Great Lakes on the 28th, driving a cold front through the middle Ohio River Valley. This front helped kick off thunderstorms, which combined with strong mid level winds led to strong thunderstorms with hail, strong wind gusts and one weak tornado.', 'Multiple trees were blown down near Coolville.');
INSERT INTO public.stormevents_east VALUES (784360, 201810, 9, 900, 201810, 9, 900, 130873, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'JAX', '09-OCT-18 09:00:00', 'EST-5', '09-OCT-18 09:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 44, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'Hurricane Michael tracked toward the FL Panhandle coast October 9th and made landfall near Mexico Beach as a very strong Cat. 4, perhaps Cat. 5 upon further research. The storm center tracked NNE across southern GA, and brought tropical storm conditions in waves of showers and thunderstorms to the area through the early morning hours of Oct. 10th. Local impacts were mainly wind damage to trees, power lines and a few structures.', NULL);
