INSERT INTO public.stormevents_east VALUES (790682, 201810, 11, 1200, 201810, 12, 0, 132113, 'VIRGINIA', 51, 2018, 'October', 'Heavy Rain', 'AKQ', '11-OCT-18 12:00:00', 'EST-5', '12-OCT-18 00:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 3, 'N', 'RICHMOND', 3, 'N', 'RICHMOND', 37.5934, -77.45, 37.5934, -77.45, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. The Tropical Cyclone produced heavy rain across much of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula. Rainfall totals ranged between two and nine inches.', 'Rainfall total of 4.28 inches was reported at Downtown Richmond (3 N). Rainfall total of 4.18 inches was reported at Downtown Richmond (3 WSW).');
