INSERT INTO public.stormevents_east VALUES (790800, 201810, 11, 2330, 201810, 12, 300, 132168, 'MARYLAND', 24, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 23:30:00', 'EST-5', '12-OCT-18 03:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 0, 'N', 'PRINCESS ANNE', 1, 'E', 'WENONA', 38.2, -75.7, 38.1301, -75.9282, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of the Lower Maryland Eastern Shore.', 'Several roads were impassable or closed across northern portions of the county due to flash flooding.');
