INSERT INTO public.stormevents_east VALUES (789802, 201810, 20, 2132, 201810, 20, 2142, 131997, 'ATLANTIC NORTH', 88, 2018, 'October', 'Marine Thunderstorm Wind', 'LWX', '20-OCT-18 21:32:00', 'EST-5', '20-OCT-18 21:42:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 41, 'MG', NULL, NULL, 0, 'N', 'GROVE POINT (GVP)', 0, 'N', 'GROVE POINT (GVP)', 39.4, -76.04, 39.4, -76.04, 'A cold front passed across the waters during the evening hours of October 20th. A band of showers and isolated thunderstorms along the front produced gusty winds across portions of the waters.', 'A wind gust of 41 knots was measured at Grove Point.');
INSERT INTO public.stormevents_east VALUES (790910, 201810, 7, 2226, 201810, 7, 2226, 132188, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '07-OCT-18 22:26:00', 'EST-5', '07-OCT-18 22:26:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 38, 'MG', NULL, NULL, 2, 'E', 'KEY WEST', 2, 'E', 'KEY WEST', 24.5571, -81.7554, 24.5571, -81.7554, 'A convergence zone extending east and southeast of Tropical Cyclone Michael, which strengthened from Tropical Storm to Hurricane strength while moving north in the eastern Gulf of Mexico, became the focus for numerous showers and thunderstorms throughout the Florida Keys.  Numerous gale-force wind gusts associated with these showers and thunderstorms were reported from the evening of October 7th through October 9th.', 'A wind gust of 38 knots was measured at Key West International Airport.');
INSERT INTO public.stormevents_east VALUES (790911, 201810, 7, 2225, 201810, 7, 2225, 132188, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '07-OCT-18 22:25:00', 'EST-5', '07-OCT-18 22:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'ASOS', 43, 'MG', NULL, NULL, 2, 'SE', 'BIG COPPITT KEY', 2, 'SE', 'BIG COPPITT KEY', 24.5801, -81.6829, 24.5801, -81.6829, 'A convergence zone extending east and southeast of Tropical Cyclone Michael, which strengthened from Tropical Storm to Hurricane strength while moving north in the eastern Gulf of Mexico, became the focus for numerous showers and thunderstorms throughout the Florida Keys.  Numerous gale-force wind gusts associated with these showers and thunderstorms were reported from the evening of October 7th through October 9th.', 'A wind gust of 43 knots was measured at the Naval Air Station Key West Boca Chica Field.');
INSERT INTO public.stormevents_east VALUES (790912, 201810, 7, 2235, 201810, 7, 2235, 132188, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '07-OCT-18 22:35:00', 'EST-5', '07-OCT-18 22:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'WNW', 'KEY WEST', 1, 'WNW', 'KEY WEST', 24.5671, -81.7979, 24.5671, -81.7979, 'A convergence zone extending east and southeast of Tropical Cyclone Michael, which strengthened from Tropical Storm to Hurricane strength while moving north in the eastern Gulf of Mexico, became the focus for numerous showers and thunderstorms throughout the Florida Keys.  Numerous gale-force wind gusts associated with these showers and thunderstorms were reported from the evening of October 7th through October 9th.', 'A wind gust of 35 knots was measured at an automated WeatherFlow station at the U.S. Coast Guard Sector Key West.');
INSERT INTO public.stormevents_east VALUES (790913, 201810, 7, 2250, 201810, 7, 2250, 132188, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '07-OCT-18 22:50:00', 'EST-5', '07-OCT-18 22:50:00', 0, 0, 0, 0, '0.00K', '0.00K', 'C-MAN Station', 36, 'MG', NULL, NULL, 0, 'N', 'MOLASSES REEF LIGHT', 0, 'N', 'MOLASSES REEF LIGHT', 25.01, -80.38, 25.01, -80.38, 'A convergence zone extending east and southeast of Tropical Cyclone Michael, which strengthened from Tropical Storm to Hurricane strength while moving north in the eastern Gulf of Mexico, became the focus for numerous showers and thunderstorms throughout the Florida Keys.  Numerous gale-force wind gusts associated with these showers and thunderstorms were reported from the evening of October 7th through October 9th.', 'A wind gust of 36 knots was measured at Molasses Reef Light.');
INSERT INTO public.stormevents_east VALUES (790914, 201810, 8, 42, 201810, 8, 42, 132188, 'GULF OF MEXICO', 85, 2018, 'October', 'Marine Thunderstorm Wind', 'KEY', '08-OCT-18 00:42:00', 'EST-5', '08-OCT-18 00:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 0, 'N', 'ALLIGATOR REEF LIGHT', 0, 'N', 'ALLIGATOR REEF LIGHT', 24.85, -80.62, 24.85, -80.62, 'A convergence zone extending east and southeast of Tropical Cyclone Michael, which strengthened from Tropical Storm to Hurricane strength while moving north in the eastern Gulf of Mexico, became the focus for numerous showers and thunderstorms throughout the Florida Keys.  Numerous gale-force wind gusts associated with these showers and thunderstorms were reported from the evening of October 7th through October 9th.', 'A wind gust of 38 knots was measured at an automated WeatherFlow station at Alligator Reef Light.');
INSERT INTO public.stormevents_east VALUES (788317, 201810, 10, 1600, 201810, 10, 1800, 130796, 'NORTH CAROLINA', 37, 2018, 'October', 'Flash Flood', 'RNK', '10-OCT-18 16:00:00', 'EST-5', '10-OCT-18 18:00:00', 0, 0, 0, 0, '0.50K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 1, 'S', 'WILKES CO ARPT', 2, 'NW', 'HUNTING CREEK', 36.1335, -81.1817, 36.1469, -81.1094, 'Michael was preceded by a so-called Predecessor Event (PRE) which brought moderate to heavy rainfall across several counties through early on the 11th of October. A deep moisture plume surged north on the periphery of the subtropical ridge with very precipitable water producing high rain rates. The heaviest rainfall from the PRE was concentrated in the Watauga and upper of the New River basin where the rainfall ranged from 2 to 6 inches with isolated higher amounts in the 24 hours ending at 700 AM local time on the 11th of October.', 'There were numerous reports of flash flooding in the Wilkesboro and North Wilkesboro areas as 2 to 4 inches fell in a just a few hours.  News reports called it some of the worst street flooding in ''years''. A mud slide temporarily blocked River Road near the Colonial Drive intersection and North Wilkesboro police helped a woman and a young child exit their car and get to safety when the car stalled in high waters on East Main Street. Flooded locations in Wilkesboro included College and East Main streets. Cub Creek left its banks and flooded portions of Cub Creek Park.');
INSERT INTO public.stormevents_east VALUES (788318, 201810, 10, 1515, 201810, 10, 1615, 130796, 'NORTH CAROLINA', 37, 2018, 'October', 'Heavy Rain', 'RNK', '10-OCT-18 15:15:00', 'EST-5', '10-OCT-18 16:15:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', NULL, NULL, NULL, NULL, 1, 'SSE', 'NORTH WILKESBORO', 1, 'SSE', 'NORTH WILKESBORO', 36.1641, -81.1422, 36.1641, -81.1422, 'Michael was preceded by a so-called Predecessor Event (PRE) which brought moderate to heavy rainfall across several counties through early on the 11th of October. A deep moisture plume surged north on the periphery of the subtropical ridge with very precipitable water producing high rain rates. The heaviest rainfall from the PRE was concentrated in the Watauga and upper of the New River basin where the rainfall ranged from 2 to 6 inches with isolated higher amounts in the 24 hours ending at 700 AM local time on the 11th of October.', 'A local mesonet site in downtown North Wilkesboro measured 2.00 inches of rain between about 415 and 515 PM local time. Numerous flash flood reports were received in the area.');
INSERT INTO public.stormevents_east VALUES (788369, 201810, 10, 700, 201810, 11, 700, 130796, 'NORTH CAROLINA', 37, 2018, 'October', 'Heavy Rain', 'RNK', '10-OCT-18 07:00:00', 'EST-5', '11-OCT-18 07:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'CoCoRaHS', NULL, NULL, NULL, NULL, 3, 'ENE', 'GLADE VLY', 3, 'ENE', 'GLADE VLY', 36.4966, -81.0001, 36.4966, -81.0001, 'Michael was preceded by a so-called Predecessor Event (PRE) which brought moderate to heavy rainfall across several counties through early on the 11th of October. A deep moisture plume surged north on the periphery of the subtropical ridge with very precipitable water producing high rain rates. The heaviest rainfall from the PRE was concentrated in the Watauga and upper of the New River basin where the rainfall ranged from 2 to 6 inches with isolated higher amounts in the 24 hours ending at 700 AM local time on the 11th of October.', 'The CoCoRaHS site at Glade Valley 3.0 ENE (NC-AG-3) reported 7.49 inches for the 24 hours ending at 800 AM local time. Streets and fields were flooded and water draining off the hills. According to NOAA Atlas 2, this 24-hour amount falls into the 90 percent confidence interval (6.49-7.85 inches) for a 50-year rain event (.02 annual chance).  The observer also reported 4.21 inches in 8 hours from 800 AM to 400 PM local time.');
INSERT INTO public.stormevents_east VALUES (788794, 201810, 4, 1805, 201810, 4, 1945, 131875, 'PENNSYLVANIA', 42, 2018, 'October', 'Flash Flood', 'PBZ', '04-OCT-18 18:05:00', 'EST-5', '04-OCT-18 19:45:00', 0, 0, 0, 0, '5.00K', '0.00K', '911 Call Center', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'WEBSTER', 1, 'WNW', 'REDUCTION', 40.1863, -79.8416, 40.1887, -79.7887, 'A cold front dropped across Pennsylvania during the afternoon hours of October 4th.  A line of thunderstorms accompanied the front, dropping 1.0 to 1.5 inches of rain across urban portions of Allegheny and Westmoreland Counties in a short period of time.  Given the already wet conditions and ideal setup for runoff, several reports of flash flooding were received, including several water rescues.', 'County 911 officials reported that several roads were flooded in Rostraver Township.');
INSERT INTO public.stormevents_east VALUES (789771, 201810, 20, 2054, 201810, 20, 2120, 131997, 'ATLANTIC NORTH', 88, 2018, 'October', 'Marine Thunderstorm Wind', 'LWX', '20-OCT-18 20:54:00', 'EST-5', '20-OCT-18 21:20:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'MARYLAND SCIENCE CENTER (BLMRE)', 0, 'N', 'MARYLAND SCIENCE CENTER (BLMRE)', 39.28, -76.61, 39.28, -76.61, 'A cold front passed across the waters during the evening hours of October 20th. A band of showers and isolated thunderstorms along the front produced gusty winds across portions of the waters.', 'A wind gust of up to 34 knots was measured at the Maryland Science Center.');
