INSERT INTO public.stormevents_east VALUES (784366, 201810, 9, 1025, 201810, 9, 1025, 130873, 'ATLANTIC SOUTH', 87, 2018, 'October', 'Marine Thunderstorm Wind', 'JAX', '09-OCT-18 10:25:00', 'EST-5', '09-OCT-18 10:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Mesonet', 38, 'MG', NULL, NULL, 2, 'NNE', 'MAYPORT NAS', 2, 'NNE', 'MAYPORT NAS', 30.42, -81.41, 30.42, -81.41, 'Hurricane Michael tracked toward the FL Panhandle coast October 9th and made landfall near Mexico Beach as a very strong Cat. 4, perhaps Cat. 5 upon further research. The storm center tracked NNE across southern GA, and brought tropical storm conditions in waves of showers and thunderstorms to the area through the early morning hours of Oct. 10th. Local impacts were mainly wind damage to trees, power lines and a few structures.', NULL);
