INSERT INTO public.stormevents_east VALUES (790711, 201810, 11, 1557, 201810, 11, 2145, 132141, 'VIRGINIA', 51, 2018, 'October', 'Flash Flood', 'AKQ', '11-OCT-18 15:57:00', 'EST-5', '11-OCT-18 21:45:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WNW', 'AMELIA', 1, 'W', 'AMELIA', 37.34, -78, 37.3314, -77.9957, 'Tropical Cyclone Michael tracked from South Carolina northeast and off the Mid Atlantic Coast from Thursday morning, October 11 into early Friday morning, October 12. Showers and scattered thunderstorms associated with the Tropical Cyclone produced heavy rain which caused flash flooding across portions of central and south central Virginia, the Virginia Northern Neck, and the Middle Peninsula.', 'Patrick Henry Highway (Route 360) was closed at Amelia Avenue due to flash flooding. Several roads in the area were flooded.');
