INSERT INTO public.stormevents_east VALUES (775303, 201807, 27, 1608, 201807, 27, 1613, 129402, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'GYX', '27-JUL-18 16:08:00', 'EST-5', '27-JUL-18 16:13:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'NNE', 'SMITHS MILLS', 4, 'NNE', 'SMITHS MILLS', 43.84, -70.53, 43.84, -70.53, 'A weak, slow-moving cold front was the focus for afternoon showers and thunderstorms in a very warm and humid air mass. Numerous storms reached severe limits producing reports of wind damage.', 'A severe thunderstorm downed trees on Frye Island.');
