INSERT INTO public.stormevents_east VALUES (775311, 201807, 27, 1650, 201807, 27, 1655, 129402, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'GYX', '27-JUL-18 16:50:00', 'EST-5', '27-JUL-18 16:55:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'WNW', 'LIMINGTON HARMON ARP', 2, 'WNW', 'LIMINGTON HARMON ARP', 43.7807, -70.7105, 43.7807, -70.7105, 'A weak, slow-moving cold front was the focus for afternoon showers and thunderstorms in a very warm and humid air mass. Numerous storms reached severe limits producing reports of wind damage.', 'A severe thunderstorm downed multiple trees and wires on Whaleback Road in Limington.');
INSERT INTO public.stormevents_east VALUES (775338, 201807, 28, 1625, 201807, 28, 1630, 129404, 'MAINE', 23, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 16:25:00', 'EST-5', '28-JUL-18 16:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'NW', 'CARATUNK', 1, 'NW', 'CARATUNK', 45.2358, -69.9891, 45.2358, -69.9891, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Several reports of wind damage were associated with these storms as they moved through western Maine.', 'A severe thunderstorm downed trees and wires on Pleasant Pond Road in Caratunk.');
