INSERT INTO public.stormevents_east VALUES (795324, 201811, 5, 1104, 201811, 5, 1500, 132938, 'VIRGINIA', 51, 2018, 'November', 'Flood', 'LWX', '05-NOV-18 11:04:00', 'EST-5', '05-NOV-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'SSE', 'BURKE', 1, 'SSE', 'BURKE', 38.7886, -77.265, 38.7869, -77.2657, 'A steady, soaking rain driven by isentropic ascent to the north of a warm front, occurred primarily during the morning hours of the 5th. Most locations received 1-2 inches of rainfall, which led to localized flooding.', 'Burke Road closed near Heritage Square Drive due to flooding.');
INSERT INTO public.stormevents_east VALUES (795326, 201811, 5, 1104, 201811, 5, 1500, 132938, 'VIRGINIA', 51, 2018, 'November', 'Flood', 'LWX', '05-NOV-18 11:04:00', 'EST-5', '05-NOV-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 1, 'WSW', 'TREMONT', 1, 'WSW', 'TREMONT', 38.8452, -77.2377, 38.8458, -77.2387, 'A steady, soaking rain driven by isentropic ascent to the north of a warm front, occurred primarily during the morning hours of the 5th. Most locations received 1-2 inches of rainfall, which led to localized flooding.', 'Woodburn Road closed due to flooding near intersection with Spicewood Drive.');
