INSERT INTO public.stormevents_east VALUES (774472, 201807, 17, 910, 201807, 17, 914, 129244, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '17-JUL-18 09:10:00', 'EST-5', '17-JUL-18 09:14:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', 50, 'EG', NULL, NULL, 0, 'SE', 'MARLOW', 0, 'SE', 'MARLOW', 43.1162, -72.1964, 43.1162, -72.1964, 'A strong cold front was dropping south through the region on the morning of July 17th. Ahead of the front was a very hot and humid air mass with precipitable water values approaching 2 inches. Several severe thunderstorms developed and caused numerous reports of wind damage.', 'A severe thunderstorm downed trees and wires at the junction of Route 10 and Route 123 in Marlow.');
