INSERT INTO public.stormevents_east VALUES (795370, 201811, 5, 1104, 201811, 5, 1304, 132938, 'VIRGINIA', 51, 2018, 'November', 'Flood', 'LWX', '05-NOV-18 11:04:00', 'EST-5', '05-NOV-18 13:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'SSW', 'SUNSET HILLS', 2, 'SSW', 'SUNSET HILLS', 38.9175, -77.3683, 38.9214, -77.3711, 'A steady, soaking rain driven by isentropic ascent to the north of a warm front, occurred primarily during the morning hours of the 5th. Most locations received 1-2 inches of rainfall, which led to localized flooding.', 'Fox Mill Road closed near Steeplechase Drive due to flooding.');
