INSERT INTO public.stormevents_east VALUES (775321, 201807, 28, 1430, 201807, 28, 1435, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 14:30:00', 'EST-5', '28-JUL-18 14:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 0, 'ESE', 'GILSUM', 0, 'ESE', 'GILSUM', 43.0471, -72.2613, 43.0471, -72.2613, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed a tree onto wires on Route 10 in Gilsum.');
INSERT INTO public.stormevents_east VALUES (775327, 201807, 28, 1605, 201807, 28, 1610, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 16:05:00', 'EST-5', '28-JUL-18 16:10:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'S', 'CHICHESTER', 0, 'S', 'CHICHESTER', 43.2491, -71.3999, 43.2491, -71.3999, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires in Chichester.');
INSERT INTO public.stormevents_east VALUES (775329, 201807, 28, 1625, 201807, 28, 1630, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 16:25:00', 'EST-5', '28-JUL-18 16:30:00', 8, 0, 0, 0, NULL, '0.00K', 'Fire Department/Rescue', 70, 'EG', NULL, NULL, 2, 'NW', 'BOW LAKE VLG', 2, 'NW', 'BOW LAKE VLG', 43.2478, -71.1772, 43.2478, -71.1772, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A microburst from a severe thunderstorm downed numerous large trees around the Bow Lake area.  One tree landed on a house near Bow Lake where eight people had taken cover from the storm.  Six of the 8 were treated at the scene and 2 were taken to hospital.');
INSERT INTO public.stormevents_east VALUES (775332, 201807, 28, 1635, 201807, 28, 1640, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 16:35:00', 'EST-5', '28-JUL-18 16:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Amateur Radio', 50, 'EG', NULL, NULL, 1, 'NW', 'CENTER STRAFFORD', 1, 'NW', 'CENTER STRAFFORD', 43.28, -71.1298, 43.28, -71.1298, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed multiple trees and wires on Scribner Road in Strafford.');
INSERT INTO public.stormevents_east VALUES (775333, 201807, 28, 1630, 201807, 28, 1635, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 16:30:00', 'EST-5', '28-JUL-18 16:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'SSW', 'STRAFFORD', 0, 'SSW', 'STRAFFORD', 43.3263, -71.1831, 43.3263, -71.1831, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed numerous trees throughout the town of Strafford.');
INSERT INTO public.stormevents_east VALUES (775335, 201807, 28, 1825, 201807, 28, 1830, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 18:25:00', 'EST-5', '28-JUL-18 18:30:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'WSW', 'GROVETON', 0, 'WSW', 'GROVETON', 44.5993, -71.5034, 44.5993, -71.5034, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees near Route 110 in Northumberland.');
INSERT INTO public.stormevents_east VALUES (791228, 201811, 2, 2042, 201811, 2, 2044, 132240, 'MARYLAND', 24, 2018, 'November', 'Tornado', 'LWX', '02-NOV-18 20:42:00', 'EST-5', '02-NOV-18 20:44:00', 0, 0, 2, 0, NULL, NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'W', 'PENN MARY JCT', 0, 'NE', 'HOLABIRD', 39.27, -76.5552, 39.2718, -76.5273, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. The most intense portions of the system were able to generate localized severe damaging winds and tornadoes.', 'A tornado touched down in Baltimore City at about 9:42 PM EDT on Friday evening, November 2, 2018. Initial damage was to a tractor trailer which was blown over on Interstate 95 just north of the Fort McHenry Tunnel. A few trees were topped just west of the interstate, and a fence line blew over on South Newkirk Street just to the east. This damage is consistent with winds of about 70 MPH.||The tornado tracked generally eastward roughly parallel to Holabird Avenue. It blew in large garage doors on both side of the building at Flexi-Van Leasing facility, consistent with wind speeds over 90 MPH.||As it continued eastward, it impacted the north building of the Amazon sorting facility, reaching a peak intensity of around 105 MPH. It blew the roof off a portion of the building, including iron rafters. With the loss of the roof, the eight inch concrete wall panels pushed in and collapsed into the building towards the north end of the west wall. Two fatalities occurred inside the building with the wall collapse. About a dozen truck trailers were pushed over, moved, or rolled by the wind. Two of the trailers were noted to have been blown in an opposite direction of the wind that toppled the wall. Several light stanchions and signs were blown over, and several car windows were blown out by flying debris. Radar data from the FAA''s Terminal Doppler Weather Radar near Baltimore-Washington International Thurgood Marshall Airport indicated this was around 9:43 PM EDT, and this is when the strongest velocity signature was noted.||The tornado continued east along the south side of Holabird Avenue, uprooting several large trees, and snapping dozens of large branches, consistent with winds of about 80 MPH.||Damage along the entire path was mainly convergent, and while much of the damage was from west-southwest to east-northeast, there were several notable exceptions of damage in differing directions. An eyewitness fire fighter outside the Baltimore City Fire Department Engine 50 firehouse in the area saw the swirling debris and funnel cloud as it passed. The tornado lifted as it reached the intersection with Dundalk Avenue, which according to radar would have been at about 9:44 PM EDT.');
INSERT INTO public.stormevents_east VALUES (791227, 201811, 2, 1920, 201811, 2, 1926, 132240, 'MARYLAND', 24, 2018, 'November', 'Tornado', 'LWX', '02-NOV-18 19:20:00', 'EST-5', '02-NOV-18 19:26:00', 0, 0, 0, 0, '900.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 2, 'SSW', 'MT AIRY', 2, 'SSE', 'COVER', 39.3509, -77.1674, 39.4046, -77.1086, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. The most intense portions of the system were able to generate localized severe damaging winds and tornadoes.', 'A tornado moved northeastward from Howard County and entered Carroll County around 8:20 PM EDT on the evening of November 2nd. Several trees were downed along Bennett Road. Numerous trees were downed in the Pheasant Ridge community just south of MD-144/Frederick Road, and several mobile homes were heavily damaged. Several power poles were snapped along MD-144/Frederick Road.||As the tornado crossed Interstate 70/US-40/Baltimore National Pike, numerous trees and branches were downed in the roadway and on vehicles, which appeared to have been pulled off the roadway by the winds. No injuries were reported.||The tornado proceeded to move into the retail area of Mt. Airy, where a canopy over the gas pumps at High''s Dairy Store was partially torn off, and the TJ Maxx roof was lifted up and partially removed. There were also numerous trees snapped and uprooted in a convergent manner behind the shopping center to near the Mt. Airy water tower. In the immediate path, virtually no trees were left undamaged, indicative of winds over 100 MPH.||The tornado continued northward from this point, where several outbuildings at the Knills Farm Market just east of MD-27/Ridge Road were severely damaged or completely destroyed, including a metal silo which twisted and collapsed. Nearby along Watersville Road, several more power poles were snapped purely from wind (not from trees falling on power lines). On either side of the farm, virtually all trees in the tornado''s path were downed in a convergent manner, including at a residence along Watersville Road, with some showing signs of bark being stripped by the wind. This was one area where maximum winds are estimated to have been near 120 mph.||The tornado continued northeastward, with several residences experiencing shingle and roof damage/removal along Arrowwood Circle, and downed numerous trees and power lines, consistent with winds around 90 MPH.||Numerous hardwood trees, virtually all in the tornado''s path, were snapped with signs of stripped bark along the 6000 block of Runkles Road. At Snell''s Greenhouses, water was completely removed from a pond, and several greenhouses were destroyed. A nearby home weather station in the tornado''s path just to the northeast measured a wind gust of 112 mph. Based on this, it is likely the tornado''s maximum winds again approached 120 mph in this area. This occurred at around 825 PM EDT, when the FAA''s Terminal Doppler Weather Radar near Washington Dulles International Airport showed it''s strongest rotational signature.||The last evidence of tornadic damage was observed on Gillis Falls Road where a few trees were uprooted in convergent fashion just east of Runkles Road. Radar imagery from the FAA''s Terminal Doppler Weather Radar near Washington Dulles International Airport showed the tornadic velocity couplet dissipate just north of Gillis Ford Road at about 826 PM EDT.||The damage estimate was provided by Carroll County Emergency Management.');
INSERT INTO public.stormevents_east VALUES (775336, 201807, 28, 1835, 201807, 28, 1839, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '28-JUL-18 18:35:00', 'EST-5', '28-JUL-18 18:39:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'WSW', 'STARK', 0, 'WSW', 'STARK', 44.5987, -71.409, 44.5987, -71.409, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm downed trees and wires in Stark.');
INSERT INTO public.stormevents_east VALUES (774416, 201807, 10, 1622, 201807, 10, 1626, 129236, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Hail', 'GYX', '10-JUL-18 16:22:00', 'EST-5', '10-JUL-18 16:26:00', 0, 0, 0, 0, NULL, '0.00K', 'Public', 1.75, NULL, NULL, NULL, 3, 'E', 'GERRISH', 3, 'E', 'GERRISH', 43.3721, -71.6091, 43.3721, -71.6091, 'Showers and some thunderstorms developed ahead of an approaching cold front on the afternoon of July 10th. Numerous cells became severe as they moved into higher dew point air over southern New Hampshire with large hail and damaging winds reported in several towns.', 'A severe thunderstorm produced 1.75 inch hail at the Canterbury rest stop on Interstate 93. Cars were dented and some car windows broken. Hail accumulated to a few inches in depth.');
INSERT INTO public.stormevents_east VALUES (774419, 201807, 10, 1555, 201807, 10, 1600, 129236, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '10-JUL-18 15:55:00', 'EST-5', '10-JUL-18 16:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'ENE', 'ANDOVER', 1, 'ENE', 'ANDOVER', 43.4353, -71.8044, 43.4353, -71.8044, 'Showers and some thunderstorms developed ahead of an approaching cold front on the afternoon of July 10th. Numerous cells became severe as they moved into higher dew point air over southern New Hampshire with large hail and damaging winds reported in several towns.', 'A severe thunderstorm downed numerous trees and wires at the intersection of Route 4 and Route 11 in Andover.');
INSERT INTO public.stormevents_east VALUES (774454, 201807, 15, 1325, 201807, 15, 1329, 129241, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '15-JUL-18 13:25:00', 'EST-5', '15-JUL-18 13:29:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 2, 'W', 'BROOKFIELD', 2, 'W', 'BROOKFIELD', 43.5691, -71.0834, 43.5691, -71.0834, 'A weak upper trough provided enough instability for scattered afternoon convection on the 15th of July. A few of these cells became severe and produced several reports of wind damage in southern New Hampshire.', 'A severe thunderstorm downed trees along Route 109 in Brookfield.');
INSERT INTO public.stormevents_east VALUES (791230, 201811, 2, 1918, 201811, 2, 1918, 132240, 'MARYLAND', 24, 2018, 'November', 'Thunderstorm Wind', 'LWX', '02-NOV-18 19:18:00', 'EST-5', '02-NOV-18 19:18:00', 0, 0, 0, 0, NULL, NULL, 'Emergency Manager', 61, 'EG', NULL, NULL, 2, 'W', 'LONG CORNER', 2, 'W', 'LONG CORNER', 39.33, -77.18, 39.33, -77.18, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. The most intense portions of the system were able to generate localized severe damaging winds and tornadoes.', 'A sign and gazebo were damaged at Lu and Joe''s Restaurant. Multiple trees were also down near the 19000 block of Windsor Forest Road.');
INSERT INTO public.stormevents_east VALUES (791237, 201811, 2, 2125, 201811, 2, 2125, 132240, 'MARYLAND', 24, 2018, 'November', 'Thunderstorm Wind', 'LWX', '02-NOV-18 21:25:00', 'EST-5', '02-NOV-18 21:25:00', 0, 0, 0, 0, NULL, NULL, 'NWS Storm Survey', 50, 'EG', NULL, NULL, 1, 'S', 'ALLENS FRESH', 1, 'S', 'ALLENS FRESH', 38.41, -76.95, 38.41, -76.95, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. The most intense portions of the system were able to generate localized severe damaging winds and tornadoes.', 'Straight line winds caused minor damage to the roof of the overhang of the Citgo Gas Station on US-301 Crain Highway near MD-234 Budds Creek Road. Several trees were also downed along Glasva School Road. A barn was destroyed on Edgewater Drive just north of MD-234 Budds Creek Road.');
INSERT INTO public.stormevents_east VALUES (791254, 201811, 2, 2100, 201811, 2, 2200, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:00:00', 'EST-5', '02-NOV-18 22:00:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 38, 'MG', NULL, NULL, 0, 'N', 'THOMAS POINT (TPLM2)', 0, 'N', 'THOMAS POINT (TPLM2)', 38.9, -76.44, 38.9, -76.44, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 38 knots was measured at Thomas Point.');
INSERT INTO public.stormevents_east VALUES (791253, 201811, 2, 2145, 201811, 2, 2145, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:45:00', 'EST-5', '02-NOV-18 21:45:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'CUCKOLD CREEK (CCK)', 0, 'N', 'CUCKOLD CREEK (CCK)', 38.31, -76.93, 38.31, -76.93, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Cuckold Creek.');
INSERT INTO public.stormevents_east VALUES (791247, 201811, 2, 2124, 201811, 2, 2124, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:24:00', 'EST-5', '02-NOV-18 21:24:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'EG', NULL, NULL, 0, 'N', 'GUNPOWDER (GUN)', 0, 'N', 'GUNPOWDER (GUN)', 39.36, -76.37, 39.36, -76.37, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Gunpowder.');
INSERT INTO public.stormevents_east VALUES (796654, 201811, 24, 2335, 201811, 25, 856, 132976, 'VIRGINIA', 51, 2018, 'November', 'Flood', 'LWX', '24-NOV-18 23:35:00', 'EST-5', '25-NOV-18 08:56:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'YORKSHIRE', 1, 'NNW', 'YORKSHIRE', 38.7954, -77.439, 38.7957, -77.4373, 'A negatively tilted trough approached the area on the 24th as surface low pressure tracked up toward the Great Lakes and secondary low pressure formed along the Carolina Coast. Lift ahead of the negatively tilted trough/within the left exit region of an upper-level jet streak led to a period of moderate to heavy rain through much of the day on the 24th. Rainfall totals were generally between 1-2 inches across the area, resulting in many instances of flooding.', 'The stream gage on the Bull Run at Manassas Park exceeded the 12 foot flood stage during the indicated period. Water covered backyards in the Yorkshire area and flooded portions of the Bull Run trail system. The peak level of 13.48 feet occurred at 5:40 AM on the 25th.');
INSERT INTO public.stormevents_east VALUES (774478, 201807, 17, 1006, 201807, 17, 1011, 129244, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '17-JUL-18 10:06:00', 'EST-5', '17-JUL-18 10:11:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 0, 'N', 'SALISBURY', 0, 'N', 'SALISBURY', 43.38, -71.72, 43.38, -71.72, 'A strong cold front was dropping south through the region on the morning of July 17th. Ahead of the front was a very hot and humid air mass with precipitable water values approaching 2 inches. Several severe thunderstorms developed and caused numerous reports of wind damage.', 'A severe thunderstorm downed power lines on Old Turnpike Road in Salisbury.');
