INSERT INTO public.stormevents_east VALUES (795371, 201811, 5, 1104, 201811, 5, 1304, 132938, 'VIRGINIA', 51, 2018, 'November', 'Flood', 'LWX', '05-NOV-18 11:04:00', 'EST-5', '05-NOV-18 13:04:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Department of Highways', NULL, NULL, 'Heavy Rain', NULL, 2, 'S', 'KENMORE', 2, 'S', 'KENMORE', 38.9261, -77.2664, 38.9264, -77.2654, 'A steady, soaking rain driven by isentropic ascent to the north of a warm front, occurred primarily during the morning hours of the 5th. Most locations received 1-2 inches of rainfall, which led to localized flooding.', 'Old Courthouse Road closed near Besley Road due to flooding.');
INSERT INTO public.stormevents_east VALUES (795374, 201811, 5, 1300, 201811, 5, 1500, 132938, 'VIRGINIA', 51, 2018, 'November', 'Flood', 'LWX', '05-NOV-18 13:00:00', 'EST-5', '05-NOV-18 15:00:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', NULL, NULL, 'Heavy Rain', NULL, 2, 'NNW', 'VALE', 2, 'NNW', 'VALE', 38.9138, -77.3635, 38.9065, -77.3586, 'A steady, soaking rain driven by isentropic ascent to the north of a warm front, occurred primarily during the morning hours of the 5th. Most locations received 1-2 inches of rainfall, which led to localized flooding.', 'Fox Mill Road closed near Thoroughbred Road and between Westwood Hills Drive and Shady Mill Lane due to flooding.');
INSERT INTO public.stormevents_east VALUES (774410, 201807, 6, 453, 201807, 6, 457, 129234, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '06-JUL-18 04:53:00', 'EST-5', '06-JUL-18 04:57:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Public', 50, 'EG', NULL, NULL, 1, 'SE', 'ENFIELD', 1, 'SE', 'ENFIELD', 43.64, -72.14, 43.64, -72.14, 'Showers and some thunderstorms developed during the early morning hours of July 6th ahead of an approaching cold front. One isolated cell in Grafton County produced wind damage downing multiple trees.', 'A severe thunderstorm downed or uprooted multiple trees in Enfield.');
INSERT INTO public.stormevents_east VALUES (774490, 201807, 17, 1030, 201807, 17, 1035, 129244, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '17-JUL-18 10:30:00', 'EST-5', '17-JUL-18 10:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 2, 'NNW', 'MANCHESTER', 2, 'NNW', 'MANCHESTER', 43.0097, -71.466, 43.0097, -71.466, 'A strong cold front was dropping south through the region on the morning of July 17th. Ahead of the front was a very hot and humid air mass with precipitable water values approaching 2 inches. Several severe thunderstorms developed and caused numerous reports of wind damage.', 'A severe thunderstorm downed a tree on a car at Elm and Clark Street and another tree on power lines on North Bay Street in Manchester.');
INSERT INTO public.stormevents_east VALUES (774495, 201807, 17, 1030, 201807, 17, 1035, 129244, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '17-JUL-18 10:30:00', 'EST-5', '17-JUL-18 10:35:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 2, 'NNW', 'MANCHESTER', 2, 'NNW', 'MANCHESTER', 43.0129, -71.4666, 43.0129, -71.4666, 'A strong cold front was dropping south through the region on the morning of July 17th. Ahead of the front was a very hot and humid air mass with precipitable water values approaching 2 inches. Several severe thunderstorms developed and caused numerous reports of wind damage.', 'A severe thunderstorm downed tree limbs on the corner of Elm and Carpenter Streets in Manchester.');
INSERT INTO public.stormevents_east VALUES (775300, 201807, 27, 1320, 201807, 27, 1325, 129401, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '27-JUL-18 13:20:00', 'EST-5', '27-JUL-18 13:25:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'S', 'NORTH GRANTHAM', 1, 'S', 'NORTH GRANTHAM', 43.521, -72.1505, 43.521, -72.1505, 'A weak, slow-moving cold front was the focus for afternoon showers and thunderstorms in a very warm and humid air mass. A few storms reached severe limits producing reports of wind damage.', 'A severe thunderstorm downed trees and power lines in Grantham.');
INSERT INTO public.stormevents_east VALUES (775301, 201807, 27, 1435, 201807, 27, 1440, 129401, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '27-JUL-18 14:35:00', 'EST-5', '27-JUL-18 14:40:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'SSE', 'CHARLESTOWN', 1, 'SSE', 'CHARLESTOWN', 43.2351, -72.4236, 43.2351, -72.4236, 'A weak, slow-moving cold front was the focus for afternoon showers and thunderstorms in a very warm and humid air mass. A few storms reached severe limits producing reports of wind damage.', 'A severe thunderstorm downed trees and wires in Charlestown.');
INSERT INTO public.stormevents_east VALUES (775312, 201807, 28, 1455, 201807, 28, 1459, 129403, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Hail', 'GYX', '28-JUL-18 14:55:00', 'EST-5', '28-JUL-18 14:59:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Trained Spotter', 1, NULL, NULL, NULL, 0, 'SE', 'DOVER', 0, 'SE', 'DOVER', 43.1967, -70.874, 43.1967, -70.874, 'An approaching shortwave and increasing shear combined with a slow moving cold front to produce scattered showers and thunderstorms on the afternoon of July 28th. Many reports of wind damage and a few reports of large hail were associated with these storms as they moved through New Hampshire.', 'A severe thunderstorm produced 1 inch hail in Dover.');
INSERT INTO public.stormevents_east VALUES (795587, 201811, 24, 1856, 201811, 24, 2336, 132975, 'MARYLAND', 24, 2018, 'November', 'Flood', 'LWX', '24-NOV-18 18:56:00', 'EST-5', '24-NOV-18 23:36:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'NNW', 'KEYMAR', 1, 'NNW', 'KEYMAR', 39.6163, -77.2428, 39.6154, -77.243, 'A negatively tilted trough approached the area on the 24th as surface low pressure tracked up toward the Great Lakes and secondary low pressure formed along the Carolina Coast. Lift ahead of the negatively tilted trough/within the left exit region of an upper-level jet streak led to a period of moderate to heavy rain through much of the day on the 24th. Rainfall totals were generally between 1-2 inches across the area, resulting in many instances of flooding.', 'The stream gage on the Big Pipe Creek at Bruceville exceeded the 8 foot flood stage during the indicated period, leading to flooding on Keysville-Bruceville Road. The peak level of 9.06 feet occurred at 9:00 PM on the 24th.');
INSERT INTO public.stormevents_east VALUES (795602, 201811, 24, 2036, 201811, 25, 542, 132975, 'MARYLAND', 24, 2018, 'November', 'Flood', 'LWX', '24-NOV-18 20:36:00', 'EST-5', '25-NOV-18 05:42:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 0, 'SW', 'GLENCOE', 1, 'NW', 'GLENCOE', 39.5482, -76.6335, 39.5577, -76.6384, 'A negatively tilted trough approached the area on the 24th as surface low pressure tracked up toward the Great Lakes and secondary low pressure formed along the Carolina Coast. Lift ahead of the negatively tilted trough/within the left exit region of an upper-level jet streak led to a period of moderate to heavy rain through much of the day on the 24th. Rainfall totals were generally between 1-2 inches across the area, resulting in many instances of flooding.', 'The stream gage on Gunpowder Falls at Glencoe exceeded the flood stage of 7 feet during the indicated time period, leading to flooding on portions of Upper Glencoe Road, Lower Glencoe Road, Sparks Road and Home Road. Additionally, water began to enter buildings off of Sparks Road. The peak level of 10.74 feet occurred at 12:15 AM on the 25th.');
INSERT INTO public.stormevents_east VALUES (795632, 201811, 24, 2111, 201811, 24, 2346, 132975, 'MARYLAND', 24, 2018, 'November', 'Flood', 'LWX', '24-NOV-18 21:11:00', 'EST-5', '24-NOV-18 23:46:00', 0, 0, 0, 0, '0.00K', '0.00K', 'River/Stream Gage', NULL, NULL, 'Heavy Rain', NULL, 1, 'SW', 'SINGER', 1, 'SW', 'SINGER', 39.4738, -76.3356, 39.4743, -76.3373, 'A negatively tilted trough approached the area on the 24th as surface low pressure tracked up toward the Great Lakes and secondary low pressure formed along the Carolina Coast. Lift ahead of the negatively tilted trough/within the left exit region of an upper-level jet streak led to a period of moderate to heavy rain through much of the day on the 24th. Rainfall totals were generally between 1-2 inches across the area, resulting in many instances of flooding.', 'The stream gage on Otter Point Creek at Edgewood exceeded the 8 foot flood stage during the indicated period, leading to flooding along Winters Run Road near Singer Road. The peak level of 8.38 feet occurred at 10:15 PM on the 24th.');
INSERT INTO public.stormevents_east VALUES (775298, 201807, 17, 1150, 201807, 17, 1300, 129397, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Flash Flood', 'GYX', '17-JUL-18 11:50:00', 'EST-5', '17-JUL-18 13:00:00', 0, 0, 0, 0, '75.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 3, 'ENE', 'GRASMERE', 4, 'ENE', 'GRASMERE', 43.0349, -71.464, 43.0344, -71.4625, 'A strong cold front was dropping south through the region on the morning of July 17th. Numerous severe thunderstorms developed ahead of the front over southern New Hampshire. Precipitable water values approaching 2 inches over the region contributed to heavy rainfall with these storms. Two to 4 inches of rain fell in the Manchester area in 3 hours resulting in flash flooding.', 'Thunderstorms produced 2 to 4 inches of rain in 3 hours causing flash flooding in Manchester. North and Union streets were flooded and cars were submerged on West River Road.');
INSERT INTO public.stormevents_east VALUES (781109, 201808, 14, 1732, 201808, 14, 1733, 128551, 'GEORGIA', 13, 2018, 'August', 'Hail', 'CHS', '14-AUG-18 17:32:00', 'EST-5', '14-AUG-18 17:33:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 1, NULL, NULL, NULL, 2, 'NW', 'MEINHARD', 2, 'NW', 'MEINHARD', 32.2, -81.25, 32.2, -81.25, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast Georgia.', 'The media relayed a report of quarter size hail on Hodgeville Road.');
INSERT INTO public.stormevents_east VALUES (791249, 201811, 2, 2130, 201811, 2, 2130, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:30:00', 'EST-5', '02-NOV-18 21:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 34, 'MG', NULL, NULL, 0, 'N', 'ORIOLE PARK AT CAMDEN YARDS (BLTPC)', 0, 'N', 'ORIOLE PARK AT CAMDEN YARDS (BLTPC)', 39.28, -76.62, 39.28, -76.62, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 34 knots was measured at Oriole Park.');
INSERT INTO public.stormevents_east VALUES (791260, 201811, 2, 2119, 201811, 2, 2154, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 21:19:00', 'EST-5', '02-NOV-18 21:54:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 36, 'MG', NULL, NULL, 0, 'N', 'COBB POINT (COB)', 0, 'N', 'COBB POINT (COB)', 38.24, -76.83, 38.24, -76.83, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of 36 knots was measured at Cobb Point.');
INSERT INTO public.stormevents_east VALUES (791262, 201811, 6, 959, 201811, 6, 959, 132244, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '06-NOV-18 09:59:00', 'EST-5', '06-NOV-18 09:59:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'GREENBERRY POINT (GBY)', 0, 'N', 'GREENBERRY POINT (GBY)', 38.97, -76.46, 38.97, -76.46, 'Mild and moist air with limited instability moved across the region ahead of an eastward moving cold front. This combined with high amounts of wind shear to create a squall line that moved across the waters, producing gusty winds.', 'A wind gust of up to 34 knots was observed at Greenbury Point.');
INSERT INTO public.stormevents_east VALUES (791263, 201811, 6, 1106, 201811, 6, 1106, 132244, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '06-NOV-18 11:06:00', 'EST-5', '06-NOV-18 11:06:00', 0, 0, 0, 0, NULL, NULL, 'Buoy', 34, 'EG', NULL, NULL, 0, 'N', 'TOLCHESTER MD (TCBM2)', 0, 'N', 'TOLCHESTER MD (TCBM2)', 39.32, -76.25, 39.32, -76.25, 'Mild and moist air with limited instability moved across the region ahead of an eastward moving cold front. This combined with high amounts of wind shear to create a squall line that moved across the waters, producing gusty winds.', 'A wind gust of up to 34 knots was observed at Tolchester.');
INSERT INTO public.stormevents_east VALUES (791242, 201811, 2, 2017, 201811, 2, 2017, 132242, 'ATLANTIC NORTH', 88, 2018, 'November', 'Marine Thunderstorm Wind', 'LWX', '02-NOV-18 20:17:00', 'EST-5', '02-NOV-18 20:17:00', 0, 0, 0, 0, NULL, NULL, 'ASOS', 34, 'EG', NULL, NULL, 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 0, 'N', '(DCA)REAGAN NATIONAL AIRPORT', 38.86, -77.03, 38.86, -77.03, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. This produced gusty winds across the waters.', 'A wind gust of up to 34 knots was observed at Washington National Airport (KDCA).');
INSERT INTO public.stormevents_east VALUES (791229, 201811, 2, 2044, 201811, 2, 2045, 132240, 'MARYLAND', 24, 2018, 'November', 'Tornado', 'LWX', '02-NOV-18 20:44:00', 'EST-5', '02-NOV-18 20:45:00', 1, 0, 0, 0, '15.00K', NULL, 'NWS Storm Survey', NULL, NULL, NULL, NULL, 0, 'NNW', 'ST HELENA', 1, 'ENE', 'DUNDALK', 39.2718, -76.5306, 39.274, -76.508, 'A dynamic low pressure system tracked through the Mid-Atlantic states on the evening of November 2nd. A squall line developed along the cold front, and while instability was limited, deep and low level shear were strong enough to support the development of a quasi-linear convective system. The most intense portions of the system were able to generate localized severe damaging winds and tornadoes.', 'A tornado tracked eastward from Baltimore City into southern Baltimore County near the city of Dundalk, around 9:44 PM EDT. After it initially lifted, the tornado briefly touched down one last time at the Holabird East Apartments on 4 Georges Court in Dundalk. The two adjoined northeast buildings in the complex sustained significant roofing damage, with a large portion of the roof decking removed from the windward side. The building was deemed uninhabitable displacing 42 people. The strong southwest wind hit the building broadside causing the damage. No other damage was noted in the area. A resident reported swirling winds with the event. One resident in the building was treated for cuts. This was the last area of damage, and the tornado signature on radar weakened after this point just after 9:45 PM EDT. The monetary damage is an estimate provided by the county emergency management office.');
INSERT INTO public.stormevents_east VALUES (774420, 201807, 10, 1622, 201807, 10, 1627, 129236, 'NEW HAMPSHIRE', 33, 2018, 'July', 'Thunderstorm Wind', 'GYX', '10-JUL-18 16:22:00', 'EST-5', '10-JUL-18 16:27:00', 0, 0, 0, 0, '0.00K', '0.00K', 'Social Media', 50, 'EG', NULL, NULL, 3, 'E', 'GERRISH', 3, 'E', 'GERRISH', 43.37, -71.61, 43.37, -71.61, 'Showers and some thunderstorms developed ahead of an approaching cold front on the afternoon of July 10th. Numerous cells became severe as they moved into higher dew point air over southern New Hampshire with large hail and damaging winds reported in several towns.', 'A severe thunderstorm downed trees on the southbound side of Interstate 93 near Gerrish.');
INSERT INTO public.stormevents_east VALUES (781108, 201808, 14, 1730, 201808, 14, 1731, 128551, 'GEORGIA', 13, 2018, 'August', 'Hail', 'CHS', '14-AUG-18 17:30:00', 'EST-5', '14-AUG-18 17:31:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 0.75, NULL, NULL, NULL, 1, 'W', 'PORT WENTWORTH', 1, 'W', 'PORT WENTWORTH', 32.15, -81.18, 32.15, -81.18, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast Georgia.', 'The media relayed a report of penny size hail in Port Wentworth.');
INSERT INTO public.stormevents_east VALUES (780391, 201808, 6, 1520, 201808, 6, 1521, 128545, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '06-AUG-18 15:20:00', 'EST-5', '06-AUG-18 15:21:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 1, 'NW', 'ALLENDALE', 1, 'NW', 'ALLENDALE', 33.01, -81.31, 33.01, -81.31, 'Warm and moist conditions between high pressure extending from the Atlantic and a Lee trough positioned inland led to thunderstorms developing upstream of the area before activity shifted over Southeast South Carolina during mid to late afternoon hours.', 'The Allendale 911 Call Center reported a tree down on a power line along Highway 278.');
INSERT INTO public.stormevents_east VALUES (777555, 201808, 3, 929, 201808, 3, 930, 128541, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'CHS', '03-AUG-18 09:29:00', 'EST-5', '03-AUG-18 09:30:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 43, 'MG', NULL, NULL, 1, 'WSW', 'FOLLY BEACH', 1, 'WSW', 'FOLLY BEACH', 32.6528, -79.9384, 32.6528, -79.9384, 'A deep plume of tropical moisture and convergence between low pressure inland and high pressure offshore led to an environment favorable to severe thunderstorms and heavy rainfall across the region.', 'The Weatherflow sensor at Folly Beach Pier recorded a 43 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777556, 201808, 3, 946, 201808, 3, 947, 128541, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'CHS', '03-AUG-18 09:46:00', 'EST-5', '03-AUG-18 09:47:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 35, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'A deep plume of tropical moisture and convergence between low pressure inland and high pressure offshore led to an environment favorable to severe thunderstorms and heavy rainfall across the region.', 'The Weatherflow sensor at Fort Sumter Range Front Light recorded a 35 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (781112, 201808, 18, 1833, 201808, 18, 1834, 128552, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '18-AUG-18 18:33:00', 'EST-5', '18-AUG-18 18:34:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'WSW', 'REEVESVILLE', 3, 'WSW', 'REEVESVILLE', 33.18, -80.68, 33.18, -80.68, 'Warm and moist conditions between a trough of low pressure inland and high pressure over the Atlantic led to a few strong/severe thunderstorms ahead of a sea breeze circulation across Southeast South Carolina.', 'The Dorchester County 911 Call Center reported a tree down on power lines near the intersection of Heaton Road and Independent School Road.');
INSERT INTO public.stormevents_east VALUES (781113, 201808, 18, 1850, 201808, 18, 1851, 128552, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '18-AUG-18 18:50:00', 'EST-5', '18-AUG-18 18:51:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'NNE', 'ROSINVILLE', 3, 'NNE', 'ROSINVILLE', 33.29, -80.51, 33.29, -80.51, 'Warm and moist conditions between a trough of low pressure inland and high pressure over the Atlantic led to a few strong/severe thunderstorms ahead of a sea breeze circulation across Southeast South Carolina.', 'The South Carolina Highway Patrol reported a tree down near the intersection of Interstate 26 and U.S. Highway 15.');
INSERT INTO public.stormevents_east VALUES (776891, 201807, 16, 2139, 201807, 16, 2149, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '16-JUL-18 21:39:00', 'EST-5', '16-JUL-18 21:49:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 36, 'MG', NULL, NULL, 1, 'WSW', 'FOLLY BEACH', 1, 'WSW', 'FOLLY BEACH', 32.6528, -79.9384, 32.6528, -79.9384, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The Weatherflow site on the Folly Beach pier measured a 36 knot wind gust. The peak gust of 41 knots occurred 5 minutes later.');
INSERT INTO public.stormevents_east VALUES (776892, 201807, 16, 2146, 201807, 16, 2151, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '16-JUL-18 21:46:00', 'EST-5', '16-JUL-18 21:51:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The Weatherflow site at Fort Sumter measured a 37 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (776893, 201807, 16, 2156, 201807, 16, 2201, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '16-JUL-18 21:56:00', 'EST-5', '16-JUL-18 22:01:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The Weatherflow site at Fort Sumter measured a 35 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (776895, 201807, 16, 2208, 201807, 16, 2211, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '16-JUL-18 22:08:00', 'EST-5', '16-JUL-18 22:11:00', 0, 0, 0, 0, NULL, '0.00K', 'Buoy', 37, 'MG', NULL, NULL, 10, 'E', 'ISLE OF PALMS', 10, 'E', 'ISLE OF PALMS', 32.8, -79.62, 32.8, -79.62, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The CORMP buoy (41029) near Capers Island measured a 37 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (776896, 201807, 16, 2150, 201807, 16, 2155, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '16-JUL-18 21:50:00', 'EST-5', '16-JUL-18 21:55:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 1, 'NE', 'SULLIVANS ISLAND', 1, 'NE', 'SULLIVANS ISLAND', 32.7666, -79.8194, 32.7666, -79.8194, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The Weatherflow site at station 28.5 on Sullivan''s Island measured a 34 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (776897, 201807, 16, 1949, 201807, 16, 1954, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '16-JUL-18 19:49:00', 'EST-5', '16-JUL-18 19:54:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 43, 'MG', NULL, NULL, 7, 'N', 'TYBEE ISLAND', 7, 'N', 'TYBEE ISLAND', 32.109, -80.8391, 32.109, -80.8391, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The Weatherflow site in Calibogue Sound measured a 43 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (835999, 201807, 16, 720, 201807, 16, 721, 129714, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '16-JUL-18 07:20:00', 'EST-5', '16-JUL-18 07:21:00', 0, 0, 0, 0, NULL, NULL, 'Coast Guard', NULL, NULL, NULL, NULL, 18, 'S', 'FRIPP ISLAND', 18, 'S', 'FRIPP ISLAND', 32.07, -80.43, 32.07, -80.43, 'A cluster of thunderstorms moved off the southeast Georgia coast in the early evening hours and eventually moved across the southeast South Carolina coast through the late evening producing strong wind gusts.', 'The Coast Guard relayed a report of a waterspout.');
