INSERT INTO public.stormevents_east VALUES (779192, 201808, 5, 1145, 201808, 5, 2345, 128542, 'SOUTH CAROLINA', 45, 2018, 'August', 'Flood', 'CHS', '05-AUG-18 11:45:00', 'EST-5', '05-AUG-18 23:45:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Emergency Manager', NULL, NULL, 'Heavy Rain', NULL, 2, 'ESE', 'SLANDSVILLE', 3, 'ESE', 'SLANDSVILLE', 32.9613, -80.1944, 32.9594, -80.1902, 'A deep plume of tropical moisture and convergence between low pressure inland and high pressure offshore led to an environment favorable for thunderstorms capable of heavy rain across the region.', 'A Dorchester County Emergency Manager reported flooding due to heavy rainfall approximately 1-2 days prior upstream of the Ashborough neighborhood, mainly along Lake Ashborough extending toward the Ashley River. Mayfield Street and a park had water approximately 6 to 8 inches deep in some places. A few rescues were made due to stalled cars on streets. A few homes were also surrounded by water between Mayfield Street and the Ashley River.');
