INSERT INTO public.stormevents_east VALUES (780688, 201808, 9, 1818, 201808, 9, 1819, 128547, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '09-AUG-18 18:18:00', 'EST-5', '09-AUG-18 18:19:00', 0, 0, 0, 0, NULL, NULL, 'Trained Spotter', 50, 'EG', NULL, NULL, 2, 'NNE', 'HENDERSONVILLE', 2, 'NNE', 'HENDERSONVILLE', 32.81, -80.71, 32.81, -80.71, 'An inland trough of low pressure and sea breeze circulation helped produce strong/severe multi-cell thunderstorms within a warm and moist environment.', 'A trained spotter reported a tree down on U.S. 17 North Alternate.');
INSERT INTO public.stormevents_east VALUES (780690, 201808, 9, 1828, 201808, 9, 1829, 128547, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '09-AUG-18 18:28:00', 'EST-5', '09-AUG-18 18:29:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 3, 'NW', 'WALTERBORO', 3, 'NW', 'WALTERBORO', 32.93, -80.69, 32.93, -80.69, 'An inland trough of low pressure and sea breeze circulation helped produce strong/severe multi-cell thunderstorms within a warm and moist environment.', 'The South Carolina Highway Patrol reported a tree down in the 2000 block of Bells Highway.');
INSERT INTO public.stormevents_east VALUES (781099, 201808, 13, 1304, 201808, 13, 1305, 128549, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'CHS', '13-AUG-18 13:04:00', 'EST-5', '13-AUG-18 13:05:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NW', 'RICHMOND HILL', 2, 'NW', 'RICHMOND HILL', 31.95, -81.32, 31.95, -81.32, 'A mid-level shortwave rounded the southern edge of low pressure centered over the Carolinas and encountered a highly unstable environment across Southeast Georgia, leading to strong/severe thunderstorms during afternoon hours.', 'The Bryan County 911 Call Center reported two trees down in Richmond Hill. One small tree fell on a car in the Richmond Hill Library parking lot. The second tree was uprooted in the White Oak Village subdivision.');
INSERT INTO public.stormevents_east VALUES (781102, 201808, 13, 1435, 201808, 13, 1436, 128549, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'CHS', '13-AUG-18 14:35:00', 'EST-5', '13-AUG-18 14:36:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 3, 'ESE', 'AIMAR', 3, 'ESE', 'AIMAR', 31.759, -81.6277, 31.759, -81.6277, 'A mid-level shortwave rounded the southern edge of low pressure centered over the Carolinas and encountered a highly unstable environment across Southeast Georgia, leading to strong/severe thunderstorms during afternoon hours.', 'The Long County 911 Call Center reported a tree down near the intersection of Thompson Road and Griffin Road.');
INSERT INTO public.stormevents_east VALUES (781103, 201808, 14, 1430, 201808, 14, 1431, 128550, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '14-AUG-18 14:30:00', 'EST-5', '14-AUG-18 14:31:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 5, 'SW', 'PIGEON BAY', 5, 'SW', 'PIGEON BAY', 33.22, -80.28, 33.22, -80.28, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast South Carolina.', 'The Berkeley County Warning Point reported trees down at the intersection of Poplar Hill Road and Highway 176.');
INSERT INTO public.stormevents_east VALUES (781104, 201808, 14, 1556, 201808, 14, 1557, 128550, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '14-AUG-18 15:56:00', 'EST-5', '14-AUG-18 15:57:00', 0, 0, 0, 0, NULL, NULL, 'Fire Department/Rescue', 50, 'EG', NULL, NULL, 1, 'N', 'NEWLAND', 1, 'N', 'NEWLAND', 33.22, -79.62, 33.22, -79.62, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast South Carolina.', 'A fire department reported a tree down on the 2100 block of Shulerville Road.');
INSERT INTO public.stormevents_east VALUES (781105, 201808, 14, 1636, 201808, 14, 1637, 128550, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '14-AUG-18 16:36:00', 'EST-5', '14-AUG-18 16:37:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 1, 'S', 'LIMEHOUSE', 1, 'S', 'LIMEHOUSE', 32.21, -81.07, 32.21, -81.07, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast South Carolina.', 'The South Carolina Highway Patrol reported a tree down at the intersection of Levy Road and Freedom Parkway.');
INSERT INTO public.stormevents_east VALUES (781089, 201808, 9, 1940, 201808, 9, 1941, 128548, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'CHS', '09-AUG-18 19:40:00', 'EST-5', '09-AUG-18 19:41:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 41, 'MG', NULL, NULL, 1, 'WSW', 'THE CHARLESTON BATTERY', 1, 'WSW', 'THE CHARLESTON BATTERY', 32.7632, -79.9431, 32.7632, -79.9431, 'An inland trough of low pressure and sea breeze circulation helped produce strong/severe multi-cell thunderstorms within a warm and moist environment.', 'The Weatherflow site near Charleston recorded a 41 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777545, 201808, 1, 1536, 201808, 1, 1536, 128536, 'GEORGIA', 13, 2018, 'August', 'Lightning', 'CHS', '01-AUG-18 15:36:00', 'EST-5', '01-AUG-18 15:36:00', 0, 0, 0, 0, '2.00K', NULL, '911 Call Center', NULL, NULL, NULL, NULL, 1, 'E', 'MILLEN', 1, 'E', 'MILLEN', 32.8, -81.92, 32.8, -81.92, 'Deep moisture and warming temperatures between low pressure inland and high pressure offshore led to thunderstorms across the region.', 'A lightning strike resulted in damage at the Jenkins County Sheriff''s Office.');
INSERT INTO public.stormevents_east VALUES (777547, 201808, 2, 1136, 201808, 2, 1137, 128537, 'ATLANTIC SOUTH', 87, 2018, 'August', 'Marine Thunderstorm Wind', 'CHS', '02-AUG-18 11:36:00', 'EST-5', '02-AUG-18 11:37:00', 0, 0, 0, 0, NULL, NULL, 'Mesonet', 36, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'Strong moisture convergence, moderate instability and upper-level diffluence between low pressure inland and high pressure offshore led to a favorable environment for severe thunderstorms.', 'The Fort Sumter Range Front Light Weatherflow sensor measured a 36 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777550, 201808, 2, 1440, 201808, 2, 1441, 128539, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'CHS', '02-AUG-18 14:40:00', 'EST-5', '02-AUG-18 14:41:00', 0, 0, 0, 0, NULL, NULL, '911 Call Center', 50, 'EG', NULL, NULL, 2, 'NW', 'EXCELSIOR', 2, 'NW', 'EXCELSIOR', 32.34, -82, 32.34, -82, 'Strong moisture convergence, moderate instability and upper-level diffluence between low pressure inland and high pressure offshore led to a favorable environment for severe thunderstorms.', 'The Candler County 911 Call Center reported a tree down on a power line along Dutch Ford Road near Brown Road.');
INSERT INTO public.stormevents_east VALUES (777551, 201808, 2, 1509, 201808, 2, 1510, 128539, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'CHS', '02-AUG-18 15:09:00', 'EST-5', '02-AUG-18 15:10:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 60, 'EG', NULL, NULL, 0, 'N', 'STATESBORO', 0, 'N', 'STATESBORO', 32.45, -81.78, 32.45, -81.78, 'Strong moisture convergence, moderate instability and upper-level diffluence between low pressure inland and high pressure offshore led to a favorable environment for severe thunderstorms.', 'The media reported several trees down around Statesboro.');
INSERT INTO public.stormevents_east VALUES (781106, 201808, 14, 1909, 201808, 14, 1910, 128550, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '14-AUG-18 19:09:00', 'EST-5', '14-AUG-18 19:10:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'ENE', 'GRAYS', 2, 'ENE', 'GRAYS', 32.68, -80.98, 32.68, -80.98, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast South Carolina.', 'The South Carolina Highway Patrol reported a tree down near the intersection of Cat Branch Road and Possum Corner Road.');
INSERT INTO public.stormevents_east VALUES (781107, 201808, 14, 2226, 201808, 14, 2227, 128550, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '14-AUG-18 22:26:00', 'EST-5', '14-AUG-18 22:27:00', 0, 0, 0, 0, NULL, NULL, 'Broadcast Media', 50, 'EG', NULL, NULL, 2, 'SE', 'PINECREST', 2, 'SE', 'PINECREST', 32.76, -80, 32.76, -80, 'A weak cold front moving into a region of marginal instability and dry air aloft helped produce strong/severe thunderstorms during multiple boundary interactions across Southeast South Carolina.', 'The media relayed a report of a large water oak down crushing a car and blocking Hinson Avenue near Medway Road in the Riverland Terrace neighborhood.');
INSERT INTO public.stormevents_east VALUES (776737, 201807, 3, 1452, 201807, 3, 1453, 129665, 'GEORGIA', 13, 2018, 'July', 'Thunderstorm Wind', 'CHS', '03-JUL-18 14:52:00', 'EST-5', '03-JUL-18 14:53:00', 0, 0, 0, 0, NULL, '0.00K', '911 Call Center', 50, 'EG', NULL, NULL, 2, 'W', 'STATESBORO', 2, 'W', 'STATESBORO', 32.45, -81.82, 32.45, -81.82, 'Scattered thunderstorms developed in the afternoon hours in a typical summertime airmass. A few of these thunderstorms became strong enough to produce damaging wind gusts.', 'Bulloch County dispatch reported a tree down on Westside Road near the bypass.');
INSERT INTO public.stormevents_east VALUES (777221, 201807, 30, 341, 201807, 30, 344, 129749, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '30-JUL-18 03:41:00', 'EST-5', '30-JUL-18 03:44:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 34, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'Scattered thunderstorms developed along the Charleston County coast in the early morning hours. A few of these thunderstorms became strong enough to produce strong wind gusts along the coast and the Atlantic coastal waters.', 'The Weatherflow site at Fort Sumter measured a 34 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777222, 201807, 30, 359, 201807, 30, 402, 129749, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '30-JUL-18 03:59:00', 'EST-5', '30-JUL-18 04:02:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'WSW', 'FOLLY BEACH', 1, 'WSW', 'FOLLY BEACH', 32.6528, -79.9384, 32.6528, -79.9384, 'Scattered thunderstorms developed along the Charleston County coast in the early morning hours. A few of these thunderstorms became strong enough to produce strong wind gusts along the coast and the Atlantic coastal waters.', 'The Weatherflow site at the Folly Beach pier measured a 35 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777223, 201807, 23, 2301, 201807, 23, 2305, 129750, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '23-JUL-18 23:01:00', 'EST-5', '23-JUL-18 23:05:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'Scattered thunderstorms developed along the Charleston County coast in the late evening hours. A few of these thunderstorms became strong enough to produce strong wind gusts along the coast and the Atlantic coastal waters.', 'The Weatherflow site at Fort Sumter measured a 35 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777224, 201807, 23, 2336, 201807, 23, 2340, 129750, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '23-JUL-18 23:36:00', 'EST-5', '23-JUL-18 23:40:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 37, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'Scattered thunderstorms developed along the Charleston County coast in the late evening hours. A few of these thunderstorms became strong enough to produce strong wind gusts along the coast and the Atlantic coastal waters.', 'The Weatherflow site at Fort Sumter measured a 37 knot wind gust.');
INSERT INTO public.stormevents_east VALUES (777226, 201807, 26, 1551, 201807, 26, 1600, 129751, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Marine Thunderstorm Wind', 'CHS', '26-JUL-18 15:51:00', 'EST-5', '26-JUL-18 16:00:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 0, 'NNW', 'FORT SUMTER', 0, 'NNW', 'FORT SUMTER', 32.7512, -79.8707, 32.7512, -79.8707, 'Scattered thunderstorms developed across Charleston County in the afternoon hours and moved into the Charleston Harbor. These thunderstorms became strong enough to produce strong wind gusts.', 'The Weatherflow site at Fort Sumter measured a 35 knot wind gust. The peak gust of 45 knots occurred 5 minutes later.');
INSERT INTO public.stormevents_east VALUES (780397, 201808, 6, 1603, 201808, 6, 1604, 128545, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '06-AUG-18 16:03:00', 'EST-5', '06-AUG-18 16:04:00', 0, 0, 0, 0, '1.00K', NULL, 'Law Enforcement', 40, 'EG', NULL, NULL, 1, 'E', 'PINELAND', 1, 'E', 'PINELAND', 32.6, -81.16, 32.6, -81.16, 'Warm and moist conditions between high pressure extending from the Atlantic and a Lee trough positioned inland led to thunderstorms developing upstream of the area before activity shifted over Southeast South Carolina during mid to late afternoon hours.', 'The South Carolina Highway Patrol reported a tree down on Cypress Branch Road near the intersection with Gillison Branch road.');
INSERT INTO public.stormevents_east VALUES (780398, 201808, 6, 1619, 201808, 6, 1620, 128545, 'SOUTH CAROLINA', 45, 2018, 'August', 'Thunderstorm Wind', 'CHS', '06-AUG-18 16:19:00', 'EST-5', '06-AUG-18 16:20:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 4, 'NNE', 'EARLY BRANCH', 4, 'NNE', 'EARLY BRANCH', 32.8, -80.9, 32.8, -80.9, 'Warm and moist conditions between high pressure extending from the Atlantic and a Lee trough positioned inland led to thunderstorms developing upstream of the area before activity shifted over Southeast South Carolina during mid to late afternoon hours.', 'The South Carolina Highway Patrol reported a tree down on Old Salkehatchie Highway between Ram Horn Road and Anna Laurel Road.');
INSERT INTO public.stormevents_east VALUES (776739, 201807, 7, 1355, 201807, 7, 1400, 129667, 'SOUTH CAROLINA', 45, 2018, 'July', 'Lightning', 'CHS', '07-JUL-18 13:55:00', 'EST-5', '07-JUL-18 14:00:00', 3, 0, 0, 0, NULL, '0.00K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'SW', 'ISLE OF PALMS ARPT', 1, 'SW', 'ISLE OF PALMS ARPT', 32.79, -79.78, 32.79, -79.78, 'Scattered to numerous thunderstorms developed along the afternoon sea breeze and produce frequent lightning strikes along the coast. These lightning strikes caused injuries on Isle of Palms and also struck a car on James Island.', 'The Isle of Palms Fire Department reported that lightning struck and injured 3 people on Isle of Palms beach near 21st Avenue.  A male lost consciousness for a brief period and a female had to be pulled out of the water in cardiac arrest.  CPR was administered on the female on the beach, who was then transported to an area hospital in serious condition.  The other 2 were transported in stable condition in a second ambulance.');
INSERT INTO public.stormevents_east VALUES (777216, 201807, 28, 1530, 201807, 28, 1531, 129747, 'GEORGIA', 13, 2018, 'July', 'Lightning', 'CHS', '28-JUL-18 15:30:00', 'EST-5', '28-JUL-18 15:31:00', 0, 0, 0, 0, '5.00K', '0.00K', 'Fire Department/Rescue', NULL, NULL, NULL, NULL, 1, 'W', 'THUNDERBOLT', 1, 'W', 'THUNDERBOLT', 32.03, -81.08, 32.03, -81.08, 'Isolated thunderstorms developed along the southeast Georgia coast in the afternoon. These thunderstorms produced lightning strikes with one such strike causing a fire in the attic of a home near Savannah.', 'Savannah Fire Department reported an attic fire due to a lightning strike on East 60th Street.');
INSERT INTO public.stormevents_east VALUES (780403, 201808, 9, 1625, 201808, 9, 1626, 128546, 'GEORGIA', 13, 2018, 'August', 'Thunderstorm Wind', 'CHS', '09-AUG-18 16:25:00', 'EST-5', '09-AUG-18 16:26:00', 0, 0, 0, 0, NULL, NULL, 'Law Enforcement', 50, 'EG', NULL, NULL, 2, 'SSE', 'HERNDON', 2, 'SSE', 'HERNDON', 32.8, -82.12, 32.8, -82.12, 'An inland trough of low pressure and sea breeze circulation helped produce strong/severe multi-cell thunderstorms within a warm and moist environment.', 'Law enforcement reported a tree down along the side of Drake Chapel Road.');
INSERT INTO public.stormevents_east VALUES (836000, 201807, 19, 645, 201807, 19, 646, 138987, 'ATLANTIC SOUTH', 87, 2018, 'July', 'Waterspout', 'CHS', '19-JUL-18 06:45:00', 'EST-5', '19-JUL-18 06:46:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 7, 'NE', 'ISLE OF PALMS', 7, 'NE', 'ISLE OF PALMS', 32.847, -79.6946, 32.847, -79.6946, 'Deep moisture along a stationary front led to numerous showers and thunderstorms capable of producing waterspouts.', 'The public relayed a picture of a waterspout near Capers Island and Dewees Island.');
INSERT INTO public.stormevents_east VALUES (835990, 201809, 12, 620, 201809, 12, 621, 138984, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Waterspout', 'CHS', '12-SEP-18 06:20:00', 'EST-5', '12-SEP-18 06:21:00', 0, 0, 0, 0, NULL, NULL, 'Public', NULL, NULL, NULL, NULL, 10, 'SE', 'SULLIVANS ISLAND', 10, 'SE', 'SULLIVANS ISLAND', 32.67, -79.7, 32.67, -79.7, 'Deep moisture within an area of high pressure extended across the area led to an environment favorable for waterspouts.', 'The public observed a waterspout from a ship near Buoy 7.');
INSERT INTO public.stormevents_east VALUES (786134, 201809, 18, 2014, 201809, 18, 2018, 131382, 'ATLANTIC SOUTH', 87, 2018, 'September', 'Marine Thunderstorm Wind', 'CHS', '18-SEP-18 20:14:00', 'EST-5', '18-SEP-18 20:18:00', 0, 0, 0, 0, NULL, '0.00K', 'Mesonet', 35, 'MG', NULL, NULL, 1, 'WSW', 'FOLLY BEACH', 1, 'WSW', 'FOLLY BEACH', 32.6528, -79.9384, 32.6528, -79.9384, 'Isolated thunderstorms developed on the tail end of a cold front as it approached the southeast South Carolina coast in the evening. A few of these thunderstorms became strong enough to produce strong wind gusts.', 'The Weatherflow site on the Folly Beach pier measured a 35 knot wind gust.');
